# ---------------------------------------------------------------------
# Initialisation du host et validation Active Directory.
# Aucun processus PowerShell enfant n est cree par Domenia.
# ---------------------------------------------------------------------
# DOMENIA Reliability R1 - helpers loaded before bootstrap; Windows PowerShell 5.1.
# These functions do not start network requests, background scans or services.
function Write-DomeniaAtomicText {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$LiteralPath,[Parameter(Mandatory)][AllowEmptyString()][string]$Value,[switch]$KeepBackup)
    $full = [IO.Path]::GetFullPath($LiteralPath)
    $dir = [IO.Path]::GetDirectoryName($full)
    if (-not [IO.Directory]::Exists($dir)) { [void][IO.Directory]::CreateDirectory($dir) }
    $temp = Join-Path $dir ('.domenia-' + [guid]::NewGuid().ToString('N') + '.tmp')
    $stream = $null
    try {
        $bytes = [Text.UTF8Encoding]::new($false).GetBytes($Value)
        $stream = [IO.FileStream]::new($temp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
        $stream.Write($bytes,0,$bytes.Length)
        $stream.Flush($true)
        $stream.Dispose(); $stream = $null
        if ([IO.File]::Exists($full)) {
            # Same-directory replacement. Never delete the valid destination first.
            # [NullString]::Value: under 5.1 a plain $null becomes "" for a .NET string parameter and Replace throws.
            if ($KeepBackup) { [IO.File]::Replace($temp,$full,($full + '.bak'),$true) }
            else { [IO.File]::Replace($temp,$full,[NullString]::Value,$true) }
        } else { [IO.File]::Move($temp,$full) }
    }
    finally {
        if ($null -ne $stream) { $stream.Dispose() }
        if ([IO.File]::Exists($temp)) { [IO.File]::Delete($temp) }
    }
}

function Protect-DomeniaLogText {
    param([AllowNull()][AllowEmptyString()][string]$Text)
    $value = [string]$Text
    # D059: once the closed loader has run, the rule of Access.Model (Protect-DomeniaSecretText) masks first.
    # This function is also called before the modules exist (bootstrap trace): it stays self-sufficient and
    # never fails when the rule is absent.
    if (-not [bool]$script:DomeniaSecretTextRuleReady) {
        $script:DomeniaSecretTextRuleReady = ($null -ne (Get-Command -Name 'Protect-DomeniaSecretText' -CommandType Function -ErrorAction SilentlyContinue))
    }
    if ([bool]$script:DomeniaSecretTextRuleReady) { try { $value = [string](Protect-DomeniaSecretText $value) } catch { Write-DomeniaSwallowed 'Core' 'Protect-DomeniaLogText' $_ } }
    # Defence in depth, not a promise to recognise every possible secret.
    $value = [regex]::Replace($value,'(?i)\b(Bearer|Basic)\s+[A-Za-z0-9_.~+/=-]+','$1 [MASQUE]')
    $value = [regex]::Replace($value,'(?i)\b(password|passwd|pwd|pass|motdepasse|mot\s+de\s+passe|secret|token|authorization|api[_-]?key|apikey|client[_-]?secret)\s*[:=]\s*(?:"[^"]*"|''[^'']*''|[^\s;,]+)','$1=[MASQUE]')
    $value = [regex]::Replace($value,'(?i)("(?:password|passwd|pwd|pass|p|motdepasse|secret|token|api[_-]?key|apikey|client[_-]?secret)"\s*:\s*)("(?:\\.|[^"\\])*"|[^,}\s]+)','$1"[MASQUE]"')
    $value = [regex]::Replace($value,'(?i)(^|\s)(-p|-rp|-pass|-password|-pwd|/p|/rp|/pass|/password|/pwd)(?:\s+|[:=])(?:"[^"]*"|''[^'']*''|\S+)','$1$2 [MASQUE]')
    $value = [regex]::Replace($value,'(?<!\d)(?:\d{6}-){7}\d{6}(?!\d)','[CLE BITLOCKER MASQUEE]')
    try {
        foreach ($row in @($script:SecretRows)) {
            $secret = [string]$row.Value
            if ($secret.Length -ge 4) { $value = $value.Replace($secret,'[SECRET MASQUE]') }
        }
        $clipboard = [string]$script:SecretClipboardValue
        if ($clipboard.Length -ge 4) { $value = $value.Replace($clipboard,'[SECRET MASQUE]') }
    } catch { Write-DomeniaSwallowed 'Core' 'Protect-DomeniaLogText' $_ }
    return $value
}

function Write-DomeniaSwallowed {
    # P-CD-09: trace of an error that a catch block deliberately does not rethrow, for example
    #   catch { Write-DomeniaSwallowed 'Theme' 'Set-DomeniaTheme' $_ }
    # The ring, the masking and the sampling are the pure Add-DomeniaSwallowedEntry (Domenia-Common.Model.ps1), given
    # Protect-DomeniaLogText as its masking rule. This wrapper adds the side effect: at most once a minute per category
    # and operation, the line due goes to the technical journal (Write-AppLog, level DEBUG, area Technique: Domenia.log
    # and the Expert view, never the readable journal) and its entry is marked Logged.
    # Never throws and writes nothing to the pipeline, so it is safe in any catch block. A trace emitted while the line
    # is being written (a journal failure traced from inside Write-AppLog) is kept in the ring as a reentry, without
    # masking or journal call. Defined before any script statement of this file, so every catch of the core and of the
    # UI modules can call it, at load time too (before the closed loader, Add-DomeniaSwallowedEntry is not loaded yet
    # and the call does nothing). It exists only in this script scope: worker here-strings, functions copied into a
    # runspace and .GetNewClosure() scriptblocks cannot call it (tools/sweep_swallowed.py leaves their catch blocks).
    param(
        [AllowNull()][AllowEmptyString()][string]$Category='',
        [AllowNull()][AllowEmptyString()][string]$Operation='',
        [AllowNull()]$ErrorRecord=$null,
        [AllowNull()]$Now=$null
    )
    try {
        $writing = $false
        try { $writing = [bool]$script:DomeniaSwallowedWriting } catch { $writing = $false }
        if ($writing) {
            [void](Add-DomeniaSwallowedEntry -Category $Category -Operation $Operation -ErrorRecord $ErrorRecord -Now $Now -Reentry)
            return
        }
        $mask = $null
        try { $mask = ${function:Protect-DomeniaLogText} } catch { $mask = $null }
        $script:DomeniaSwallowedWriting = $true
        try {
            $due = Add-DomeniaSwallowedEntry -Category $Category -Operation $Operation -ErrorRecord $ErrorRecord -Now $Now -Mask $mask
            if ($null -ne $due) {
                try { [void](Write-AppLog -Text ([string]$due.Line) -Level 'DEBUG' -Area 'Technique'); $due.Entry.Journal = 'Logged' }
                catch { $due.Entry.Journal = 'Unavailable' }
            }
        }
        finally { $script:DomeniaSwallowedWriting = $false }
    }
    catch {
        # Exempt from tools/audit_swallowed.py: the trace of a swallowed error cannot trace its own failure.
        [void]$_
    }
}

function ConvertTo-DomeniaSpreadsheetCell {
    param($Value)
    if ($null -eq $Value) { return $null }
    # Preserve numeric values, booleans and dates. Only untrusted text is escaped.
    if ($Value -isnot [string]) { return $Value }
    if ($Value -match '^[\s\p{Cf}]*[=+@\-\uFF1D\uFF0B\uFF0D\uFF20]' -or $Value -match '^[\t\r\n]') {
        return "'" + $Value
    }
    return $Value
}

function ConvertTo-DomeniaSpreadsheetSafeRow {
    [CmdletBinding()]
    param([Parameter(ValueFromPipeline=$true)]$InputObject)
    process {
        if ($null -ne $InputObject) {
            $safe = [ordered]@{}
            foreach ($property in $InputObject.PSObject.Properties) {
                if ($property.MemberType -notin @('NoteProperty','Property','AliasProperty','ScriptProperty')) { continue }
                $name = [string](ConvertTo-DomeniaSpreadsheetCell ([string]$property.Name))
                $safe[$name] = ConvertTo-DomeniaSpreadsheetCell $property.Value
            }
            [pscustomobject]$safe
        }
    }
}

function Get-DomeniaGridExportColumns {
    # CO-04: the columns the operator sees, in display order, with their French headers. A template column gives
    # its sort path, otherwise the binding of the first text of its cell template.
    param($Grid)
    if ($null -eq $Grid) { return }
    $ordered = @($Grid.Columns)
    # Display order once the grid has laid its columns out; declaration order before that.
    if (@($ordered | Where-Object { $_.DisplayIndex -lt 0 }).Count -eq 0) { $ordered = @($ordered | Sort-Object DisplayIndex) }
    foreach ($column in $ordered) {
        if ($column.Visibility -ne [System.Windows.Visibility]::Visible) { continue }
        $property = ''
        try { if ($column -is [System.Windows.Controls.DataGridBoundColumn] -and $null -ne $column.Binding -and $null -ne $column.Binding.Path) { $property = [string]$column.Binding.Path.Path } } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaGridExportColumns' $_ }
        # CO-03 : une colonne modele n'a pas de Binding, mais ClipboardContentBinding designe deja la
        # valeur qu'elle represente — c'est ce que WPF copie dans le presse-papiers. Sans elle,
        # SortMemberPath gagnerait et le CSV sortirait la cle de tri, un DateTime : « Jamais » y
        # deviendrait 01/01/0001 00:00:00. Tag n'est pas une issue : DataGridColumn n'en porte pas.
        if ((-not $property) -and ($column -is [System.Windows.Controls.DataGridTemplateColumn])) {
            try { if ($null -ne $column.ClipboardContentBinding -and $null -ne $column.ClipboardContentBinding.Path) { $property = [string]$column.ClipboardContentBinding.Path.Path } } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaGridExportColumns' $_ }
        }
        if (-not $property) { $property = [string]$column.SortMemberPath }
        if ((-not $property) -and ($column -is [System.Windows.Controls.DataGridTemplateColumn]) -and ($null -ne $column.CellTemplate)) {
            try {
                $queue = New-Object System.Collections.Queue
                $queue.Enqueue($column.CellTemplate.LoadContent())
                while (($queue.Count -gt 0) -and (-not $property)) {
                    $node = $queue.Dequeue()
                    if ($node -is [System.Windows.Controls.TextBlock]) {
                        $binding = [System.Windows.Data.BindingOperations]::GetBinding($node,[System.Windows.Controls.TextBlock]::TextProperty)
                        if ($null -ne $binding -and $null -ne $binding.Path) { $property = [string]$binding.Path.Path }
                    }
                    if ($node -is [System.Windows.DependencyObject]) {
                        foreach ($child in [System.Windows.LogicalTreeHelper]::GetChildren($node)) { if ($child -is [System.Windows.DependencyObject]) { $queue.Enqueue($child) } }
                    }
                }
            } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaGridExportColumns' $_ }
        }
        if (-not $property) { continue }
        $header = $column.Header
        if ($header -is [System.Windows.Controls.TextBlock]) { $header = $header.Text }
        $header = ([string]$header).Trim()
        if (-not $header) { $header = $property }
        [pscustomobject]@{ Property=$property; Header=$header }
    }
}

function ConvertTo-DomeniaExportRows {
    # Rows projected on the exported columns (French header = column title). Without columns the row is kept.
    param([object[]]$Rows,[object[]]$Columns)
    $selected = @($Columns | Where-Object { $null -ne $_ })
    foreach ($row in @($Rows)) {
        if ($null -eq $row) { continue }
        if ($selected.Count -eq 0) { $row; continue }
        $out = [ordered]@{}
        foreach ($column in $selected) {
            $header = [string]$column.Header; $suffix = 2
            while ($out.Contains($header)) { $header = [string]$column.Header + ' (' + $suffix + ')'; $suffix++ }
            $value = $null
            try { $p = $row.PSObject.Properties[[string]$column.Property]; if ($null -ne $p) { $value = $p.Value } } catch { Write-DomeniaSwallowed 'Core' 'ConvertTo-DomeniaExportRows' $_ }
            if (($value -is [System.Collections.IEnumerable]) -and ($value -isnot [string])) { $value = (@($value) | ForEach-Object { [string]$_ }) -join ', ' }
            $out[$header] = $value
        }
        [pscustomobject]$out
    }
}

function Get-DomeniaExportDirectory {
    # Default export folder: the Exports area of the local data store.
    Initialize-DomeniaDataStore | Out-Null
    $dir = ''
    foreach ($category in @($script:StorageLayout.Categories)) {
        if ([string]$category.Category -ne 'Cache') { continue }
        foreach ($area in @($category.Areas)) { if (([string]$area.Name -eq 'Exports') -and ([string]$area.Path)) { $dir = [string]$area.Path } }
    }
    if (-not $dir) { $dir = Join-Path ([string]$script:DataDir) 'Exports' }
    if (-not [IO.Directory]::Exists($dir)) { [void][IO.Directory]::CreateDirectory($dir) }
    return $dir
}

function Get-DomeniaExportFileName {
    # UX-02: Domenia-<OU ou poste>-AAAAMMJJ-HHmm.csv ; the subject keeps letters, digits, dot, dash and underscore.
    param([string]$Subject='',[datetime]$Time=(Get-Date))
    $clean = [regex]::Replace(([string]$Subject).Trim(),'[^\p{L}\p{Nd}._-]+','-').Trim('-','.')
    if ($clean.Length -gt 60) { $clean = $clean.Substring(0,60).Trim('-','.') }
    if (-not $clean) { $clean = 'export' }
    return ('Domenia-' + $clean + '-' + $Time.ToString('yyyyMMdd-HHmm') + '.csv')
}

function Export-DomeniaCsv {
    # CO-04: the single CSV export of Domenia. Semicolon for a French Excel, UTF-8 with BOM, the visible columns
    # in their order with French headers, formula-like cells neutralised. A file is never overwritten: a second
    # export in the same minute gets a numbered name. Returns the written path and the row count.
    param([AllowEmptyCollection()][object[]]$Rows=@(),[object[]]$Columns=@(),$Grid=$null,[string]$Subject='',[string]$Path='',[string]$Directory='')
    $exportColumns = @($Columns | Where-Object { $null -ne $_ })
    if (($exportColumns.Count -eq 0) -and ($null -ne $Grid)) { $exportColumns = @(Get-DomeniaGridExportColumns -Grid $Grid) }
    $projected = @(ConvertTo-DomeniaExportRows -Rows $Rows -Columns $exportColumns)
    # Point 50: no secret leaves in an export: secret columns withheld, secret-looking text masked.
    $secretColumns = @($exportColumns | Where-Object { Test-DomeniaSecretAttribute ([string]$_.Property) } | ForEach-Object { [string]$_.Header })
    $redacted = Protect-DomeniaExportRows -Rows $projected -SecretColumns $secretColumns
    $projected = @($redacted.Rows)
    if (-not $Path) {
        if (-not $Directory) { $Directory = Get-DomeniaExportDirectory }
        $name = Get-DomeniaExportFileName -Subject $Subject
        $Path = Join-Path $Directory $name
        $suffix = 2
        while ([IO.File]::Exists($Path)) { $Path = Join-Path $Directory ([IO.Path]::GetFileNameWithoutExtension($name) + '-' + $suffix + '.csv'); $suffix++ }
    }
    $projected | ConvertTo-DomeniaSpreadsheetSafeRow | Export-Csv -LiteralPath $Path -Delimiter ';' -NoTypeInformation -Encoding UTF8
    return [pscustomobject]@{ Path=$Path; RowCount=$projected.Count; Masked=[int]$redacted.Masked; Withheld=@($redacted.Withheld) }
}

function Show-DomeniaExportResult {
    # UX-02: the number of rows is always announced; the confirmation stays in the page with « Ouvrir le dossier ».
    param($Result,[string]$Scope='',[string]$Also='')
    $count = [int]$Result.RowCount
    $label = if ($count -eq 1) { '1 ligne exportée' } else { "$count lignes exportées" }
    if ($Scope) { $label += " ($Scope)" }
    $sentence = $label + ' dans ' + [IO.Path]::GetFileName([string]$Result.Path) + '.'
    # Point 50: what was kept out of the file is said, never silently dropped.
    $masked = [int](Get-DomeniaMember $Result 'Masked' 0)
    if ($masked -eq 1) { $sentence += ' 1 valeur ressemblant à un secret a été masquée.' }
    elseif ($masked -gt 1) { $sentence += ' ' + $masked + ' valeurs ressemblant à un secret ont été masquées.' }
    if ($Also) { $sentence += ' ' + $Also }
    Set-Status ($label + ' : ' + [string]$Result.Path)
    [void](Show-DomeniaPageBanner -Kind Success -Message $sentence -ActionText 'Ouvrir le dossier' -ActionPath ([string]$Result.Path))
}

function Get-DomeniaExportComputerName {
    # Name of the workstation an inventory, software or WMI export belongs to (file name only). -Computer: the
    # workstation the rows were read from, when the caller kept it.
    param([string]$Computer='')
    $name = ([string]$Computer).Trim()
    if (-not $name) { try { $name = [string]$script:SelectedObject.Name } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaExportComputerName' $_ } }
    if (-not $name) { $name = 'poste' }
    return $name
}

function Get-DomeniaSearchExportSubject {
    # The OU named in the search export file, or the domain for a global search. Display only, never an LDAP root.
    try {
        if ((Get-DomeniaSearchMode) -eq 'Global') {
            $domain = [string]$script:Conn.Domain
            if ($domain) { return $domain }
            return 'domaine'
        }
        $dn = [string](Get-DomeniaSearchScope -Mode OU).BaseDn
        $match = [regex]::Match($dn,'^(?i:OU|CN|DC)=((?:\\.|[^,])+)')
        if ($match.Success) { return ($match.Groups[1].Value -replace '\\(.)','$1') }
    } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaSearchExportSubject' $_ }
    return 'recherche'
}

function Get-DomeniaCsvDelimiter {
    # Import of a CSV written by Domenia (semicolon since CO-04) or by an older version or another tool (comma).
    param([string]$Path)
    $first = ''
    try { $reader = [IO.StreamReader]::new($Path,$true); try { $first = [string]$reader.ReadLine() } finally { $reader.Dispose() } } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaCsvDelimiter' $_ }
    if (($first.IndexOf(';') -ge 0) -and ($first.IndexOf(',') -lt 0)) { return ';' }
    if ($first.Split(';').Count -gt $first.Split(',').Count) { return ';' }
    return ','
}

function ConvertTo-DomeniaSqlLikeText {
    param([AllowEmptyString()][string]$Value)
    # SQL quoting and LIKE escaping are independent operations.
    return $Value.Replace('!','!!').Replace('%','!%').Replace('_','!_')
}

function Get-DomeniaScopeKey {
    param([Parameter(Mandatory)][string]$BaseDn)
    $sha = [Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [Text.Encoding]::UTF8.GetBytes($BaseDn.Trim().ToLowerInvariant())
        return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').Substring(0,32).ToLowerInvariant()
    } finally { $sha.Dispose() }
}

function Get-DomeniaStoreBackupDirectory {
    $path = Join-Path ([IO.Path]::GetDirectoryName((Get-DomeniaDatabasePath))) 'Backups'
    if (-not [IO.Directory]::Exists($path)) { [void][IO.Directory]::CreateDirectory($path) }
    return $path
}

function Complete-DomeniaDetachedReadJobs {
    # Never call Dispose/EndInvoke on a running native operation on the UI thread.
    if ($null -eq $script:DetachedReadJobs) { return }
    for ($i = $script:DetachedReadJobs.Count - 1; $i -ge 0; $i--) {
        $job = $script:DetachedReadJobs[$i]
        if ($null -eq $job) { $script:DetachedReadJobs.RemoveAt($i); continue }
        $invokeDone = $false; $stopDone = $true
        try { $invokeDone = [bool]$job.Handle.IsCompleted } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaDetachedReadJobs' $_ }
        try { if ($null -ne $job.StopHandle) { $stopDone = [bool]$job.StopHandle.IsCompleted } } catch { $stopDone = $false }
        if (-not $invokeDone -or -not $stopDone) { continue }
        try { if ($null -ne $job.StopHandle) { $job.PowerShell.EndStop($job.StopHandle) } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaDetachedReadJobs' $_ }
        try { $discarded = $job.PowerShell.EndInvoke($job.Handle); $discarded = $null } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaDetachedReadJobs' $_ }
        try { $job.PowerShell.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaDetachedReadJobs' $_ }
        try { $job.Runspace.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaDetachedReadJobs' $_ }
        $job.OnSuccess = $null; $job.OnError = $null; $job.CallbackState = $null
        $script:DetachedReadJobs.RemoveAt($i)
    }
}

function Get-DomeniaRuntimeHealthText {
    $lines = New-Object 'System.Collections.Generic.List[string]'
    $process = [Diagnostics.Process]::GetCurrentProcess()
    try {
        $lines.Add("DOMENIA $script:Version / $script:MasterBuild")
        $lines.Add('Genere le ' + (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'))
        $lines.Add('PowerShell : ' + [string]$PSVersionTable.PSVersion + ' ; 64 bits : ' + [Environment]::Is64BitProcess)
        $lines.Add('Memoire privee : ' + [Math]::Round($process.PrivateMemorySize64 / 1MB,1) + ' Mo')
        $lines.Add('Lecture seule : ' + [string]$script:ReadOnlyMode + ' ; etat ecriture : ' + [string]$script:WriteState)
        $lines.Add('Cache actif : ' + (Get-DomeniaDatabasePath))
        $lines.Add('Taches actives : ' + @($script:AsyncJobs.Keys).Count)
        $lines.Add('Lectures en attente de nettoyage : ' + @($script:DetachedReadJobs).Count)
        $lines.Add('')
        foreach ($job in @($script:AsyncJobs.Values) + @($script:DetachedReadJobs)) {
            if ($null -eq $job) { continue }
            $age = [int]((Get-Date) - [datetime]$job.Started).TotalSeconds
            # UX-32: one plain sentence per task; the short reference ties it to Domenia.log for the support.
            $kind = if ([bool]$job.IsWrite) { 'écriture' } else { 'lecture' }
            $stop = if ([bool]$job.CancelRequested) { ', arrêt demandé' } else { '' }
            $reference = ([string]$job.CorrelationId); if ($reference.Length -gt 8) { $reference = $reference.Substring(0,8) }
            $lines.Add(('{0} ({1}) : {2}, depuis {3} s{4}. Réf. {5}' -f [string]$job.Name,[string]$job.OperationId,$kind,$age,$stop,$reference))
        }
        $lines.Add('')
        $lines.Add('Une lecture detachee ne renvoie plus de resultat dans le GUI, mais son appel natif peut encore etre actif.')
        $lines.Add('Les taches natives encore actives comptent dans la limite physique de concurrence.')
        return Protect-DomeniaLogText ([string]::Join([Environment]::NewLine,$lines.ToArray()))
    } finally { $process.Dispose() }
}

function Register-DomeniaReliabilityUi {
    $copy = Get-DomeniaControl -Name 'BtnCopyUiLog'
    if ($null -ne $copy) { $copy.Add_Click({
        try {
            # UI-22: copies the journal as displayed (readable or raw) and masks the names when the operator asks.
            $copied = Get-DomeniaExperienceLogCopyText
            if ($null -ne $copied -and -not [string]::IsNullOrWhiteSpace([string]$copied.Text)) {
                Set-ClipboardSafe ([string]$copied.Text)
                if ([bool]$copied.Masked) { Set-Status 'Journal copié, noms masqués. Un nom de poste isolé peut rester visible : relisez avant envoi.' }
                else { Set-Status 'Journal copié. Les noms de comptes et de machines ne sont pas masqués.' }
            }
        } catch { Show-ErrorBox $_.Exception.Message }
    }) }
    $health = Get-DomeniaControl -Name 'BtnRuntimeHealth'
    if ($null -ne $health) { $health.Add_Click({
        # UX-32: the health of the engine is read in clear in the operations panel, not in a box of raw text.
        try { if (-not (Show-DomeniaOperationsPanel)) { Show-InfoBox -Message 'État du moteur Domenia' -Details (Get-DomeniaRuntimeHealthText) } }
        catch { Show-ErrorBox $_.Exception.Message }
    }) }
    if ($null -ne $script:Window) { $script:Window.Add_Deactivated({
        if ([bool]$script:SecretsVisible) { $script:SecretsVisible = $false; Update-SecretsGrid }
    }) }
}

function Restart-DomeniaSecretLifetime {
    try { if ($null -ne $script:SecretLifetimeTimer) { $script:SecretLifetimeTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Restart-DomeniaSecretLifetime' $_ }
    $seconds = [Math]::Max(30,[Math]::Min(1800,[int](Get-CfgValue 'Security' 'SecretMemorySeconds' 300)))
    # FI-05: protected heartbeat timer; one expiry clears the secrets, the next reveal restarts it.
    $script:SecretLifetimeTimer = New-DomeniaTimer -Owner 'Timer:SecretLifetime' -IntervalMs ($seconds * 1000) -Start -Tick {
        param($sender,$eventArgs)
        try { $sender.Stop() } catch { Write-DomeniaSwallowed 'Core' 'Restart-DomeniaSecretLifetime' $_ }
        try { Clear-Secrets; Set-Status 'Secrets retirés de la vue et références effacées après expiration.' }
        catch { Write-AppLog 'Expiration des secrets : echec du nettoyage.' 'WARN' }
    }
}

function Get-DomeniaSelectedSecretSource {
    $grid = Get-DomeniaControl -Name 'DgSecrets'
    if ($null -eq $grid -or $null -eq $grid.SelectedItem) { return $null }
    $row = $grid.SelectedItem
    if ($null -eq $row.PSObject.Properties['SecretIndex']) { return $null }
    $index = [int]$row.SecretIndex
    if ($index -lt 0 -or $index -ge @($script:SecretRows).Count) { return $null }
    return $script:SecretRows[$index]
}

function Assert-DomeniaWmiReadQuery {
    param([string]$ClassName,[string]$Namespace,[string]$Where,[int]$Limit)
    if ($ClassName -notmatch '^[A-Za-z_][A-Za-z0-9_]{0,127}$') { throw 'Nom de classe WMI invalide.' }
    if ($Namespace -notmatch '^root(?:\\[A-Za-z_][A-Za-z0-9_]*)*$') { throw 'Espace de noms WMI invalide.' }
    # SE-03 : le fournisseur MSI ne se reduit pas a Win32_Product. CIM_Product enumere les memes instances et
    # Win32_SoftwareFeature est instancie par le meme fournisseur ; les 88 noms vivent dans
    # Domenia-Workstation.Model.ps1, seule source, rien n'est recopie ici. Sans module Poste charge, la garde
    # refuse la lecture au lieu de laisser passer une classe qu'elle n'a pas pu juger.
    $msiRefusee = $false
    try { $msiRefusee = [bool](Test-DomeniaMsiProviderClass $ClassName) }
    catch { throw 'Garde MSI indisponible : module Poste non charge, lecture WMI refusee.' }
    if ($msiRefusee) { throw 'Classe du fournisseur MSI bloquee : sa lecture peut declencher des verifications/reparations MSI. Utilise le panneau Logiciels.' }
    if (([string]$Where).Length -gt 2048 -or ([string]$Where).IndexOf([char]0) -ge 0) { throw 'Filtre WMI trop long ou contenant un caractere nul.' }
    if ($Limit -lt 1 -or $Limit -gt 500) { throw 'La limite WMI doit etre comprise entre 1 et 500.' }
}


function Write-DomeniaBootstrapTrace {
    param([string]$Stage,[string]$Status,[string]$Detail="")
    $Detail = Protect-DomeniaLogText $Detail
    try {
        $base = if ([string]::IsNullOrWhiteSpace([string]$env:LOCALAPPDATA)) { [string]$env:TEMP } else { [string]$env:LOCALAPPDATA }
        $dir = Join-Path $base "DOMENIA\Logs"
        if (-not (Test-Path -LiteralPath $dir)) { [void](New-Item -ItemType Directory -Path $dir -Force) }
        $path = Join-Path $dir "Domenia-bootstrap.log"
        $clean = (($Detail + "") -replace "[\r\n\t]+"," ").Trim()
        $line = "{0}`tPID={1}`tHOST={2}`t{3}`t{4}`t{5}{6}" -f (Get-Date).ToString("yyyy-MM-dd HH:mm:ss.fff"),$PID,[System.Diagnostics.Process]::GetCurrentProcess().ProcessName,$Stage,$Status,$clean,[Environment]::NewLine
        [System.IO.File]::AppendAllText($path,$line,(New-Object System.Text.UTF8Encoding($false)))
    }
    catch { Write-DomeniaSwallowed 'Core' 'Write-DomeniaBootstrapTrace' $_ }
}

# DOMENIA reste dans le processus courant. Aucun relancement automatique cache
# n'est effectue depuis PowerShell ISE : cela evite un comportement de type
#  processus parent qui lance PowerShell en arriere-plan , souvent signale
# par les protections heuristiques. Le mode ISE reste reserve au diagnostic.
$isIseHost = $false
try { $isIseHost = ($null -ne $psISE) } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
try { if ([System.Diagnostics.Process]::GetCurrentProcess().ProcessName -ieq "powershell_ise") { $isIseHost = $true } } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
if ($isIseHost) {
    Write-DomeniaBootstrapTrace -Stage "ISE" -Status "WARN" -Detail "Execution directe dans PowerShell ISE ; aucun processus enfant n'est lance. Pour un test fidele, utiliser Windows PowerShell 5.1 en mode STA ou l'EXE compile."
    Write-Warning "DOMENIA s'execute directement dans PowerShell ISE. Pour un test fidele a l'EXE, utilise Windows PowerShell 5.1 avec -STA."
}

Write-DomeniaBootstrapTrace -Stage "Bootstrap" -Status "START" -Detail "Hote principal PID=$PID, processus=$([System.Diagnostics.Process]::GetCurrentProcess().ProcessName), version=$($PSVersionTable.PSVersion), 64bits=$([Environment]::Is64BitProcess)"

Set-StrictMode -Off
$ErrorActionPreference = "Stop"

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, System.Xaml
Add-Type -AssemblyName System.DirectoryServices
Add-Type -AssemblyName System.Windows.Forms

$script:Version = "1.0"
$script:AppName = "Domenia"

$script:EmbeddedDomeniaIconBase64 = @"

"@

function Ensure-DomeniaIcon {
    try {
        $iconPath = Join-Path $script:RootDir "Domenia.ico"
        if (-not (Test-Path -LiteralPath $iconPath -PathType Leaf)) {
            [System.IO.File]::WriteAllBytes(
                $iconPath,
                [Convert]::FromBase64String($script:EmbeddedDomeniaIconBase64)
            )
        }
        return $iconPath
    }
    catch {
        return $null
    }
}


