function Load-AppConfig {
    $default = New-DefaultConfig
    # P-CD-09: a configuration that cannot be read is said at startup (Main): the session runs with the defaults, which
    # may differ from the settings the administrator chose (security, remote access, limits).
    $script:ConfigLoadIssues = New-Object 'System.Collections.Generic.List[object]'
    try {
        if (($null -ne $script:CfgPath) -and (Test-Path -LiteralPath $script:CfgPath)) {
            $raw = Get-Content -LiteralPath $script:CfgPath -Raw -Encoding UTF8
            if (-not [string]::IsNullOrWhiteSpace($raw)) {
                $json = $raw | ConvertFrom-Json
                foreach ($section in $json.PSObject.Properties) {
                    if ($default.Contains($section.Name)) {
                        foreach ($kv in $section.Value.PSObject.Properties) { $default[$section.Name][$kv.Name] = $kv.Value }
                    }
                    elseif ($section.Value -is [System.Management.Automation.PSCustomObject]) {
                        # D120 (F5): an unknown section becomes an ordered table, otherwise Get-CfgValue
                        # cannot read it and silently returns its default.
                        $extra = [ordered]@{}
                        foreach ($kv in $section.Value.PSObject.Properties) { $extra[$kv.Name] = $kv.Value }
                        $default[$section.Name] = $extra
                    }
                    else { $default[$section.Name] = $section.Value }
                }
            }
        }
    }
    catch {
        $default = New-DefaultConfig
        $script:ConfigLoadIssues.Add([pscustomobject]@{Source='Fichier';Warning=$true;Text=('La configuration ' + [string]$script:CfgPath + ' est illisible : les valeurs par défaut sʼappliquent pour cette session, y compris les réglages de sécurité et dʼaccès distant. Corrigez le fichier puis redémarrez Domenia.')})
        Write-DomeniaSwallowed 'Core' 'Load-AppConfig' $_
    }

    try {
        if (Test-Path -LiteralPath $script:RegPath) {
            $reg = Get-ItemProperty -LiteralPath $script:RegPath -ErrorAction Stop
            if ($null -ne $reg.RememberLogin) { $default.Auth.RememberLogin = ([int]$reg.RememberLogin -eq 1) }
            if ($null -ne $reg.LastLogin) { $default.Auth.LastLogin = [string]$reg.LastLogin }
            foreach($name in @('VaultDomainDn','VaultUserName')){if($null -ne $reg.PSObject.Properties[$name]){$default.Auth[$name]=[string]$reg.$name}}
        }
    }
    catch {
        $script:ConfigLoadIssues.Add([pscustomobject]@{Source='Registre';Warning=$false;Text='Préférences de connexion du registre illisibles : le dernier compte et le choix « se souvenir » ne sont pas repris.'})
        Write-DomeniaSwallowed 'Core' 'Load-AppConfig' $_
    }

    if ($Server) { $default.Conf.Server = $Server }
    if ($SearchBase) { $default.Conf.SearchBase = $SearchBase }
    if ($DefaultLimit -gt 0) { $default.Browser.DefaultLimit = $DefaultLimit }
    try {
        $forceFirst = $false
        if ($default.Browser.Contains("ForceFirstLevelAtStartup")) { $forceFirst = [bool]$default.Browser.ForceFirstLevelAtStartup }
        if (-not $forceFirst) {
            $default.Browser.FastBoot = $true
            $default.Browser.LoadFirstLevelOnStartup = $false
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Load-AppConfig' $_ }
    $script:Config = $default
    return $default
}

function Save-AppConfig {
    param([switch]$ThrowOnFailure)
    try {
        if (-not (Test-Path -LiteralPath $script:RegPath)) { New-Item -Path $script:RegPath -Force -ErrorAction Stop | Out-Null }
        Set-ItemProperty -LiteralPath $script:RegPath -Name "RememberLogin" -Value ([int][bool]$script:Config.Auth.RememberLogin) -Force -ErrorAction Stop
        Set-ItemProperty -LiteralPath $script:RegPath -Name "LastLogin" -Value ([string]$script:Config.Auth.LastLogin) -Force -ErrorAction Stop
        foreach($name in @('VaultDomainDn','VaultUserName')){Set-ItemProperty -LiteralPath $script:RegPath -Name $name -Value ([string]$script:Config.Auth[$name]) -Force -ErrorAction Stop}
    }
    catch { if($ThrowOnFailure){throw 'Enregistrement des préférences de connexion HKCU impossible.'} }
}

function Get-CfgValue {
    param([string]$Section, [string]$Name, $Default = $null)
    try {
        if ($script:Config.Contains($Section) -and $script:Config[$Section].Contains($Name)) {
            $v = $script:Config[$Section][$Name]
            if ($null -ne $v -and "" -ne [string]$v) { return $v }
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Get-CfgValue' $_ }
    return $Default
}

function Convert-DomainToDn {
    param([string]$Domain)
    if ([string]::IsNullOrWhiteSpace($Domain)) { return "" }
    $parts = $Domain.Split(".") | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
    return (($parts | ForEach-Object { "DC=$($_)" }) -join ",")
}

function Get-LdapPath {
    param([string]$Dn)
    $server = $script:Conn.Server
    if ([string]::IsNullOrWhiteSpace($Dn)) { $Dn = $script:Conn.BaseDn }
    # CO-33: a '/' inside an RDN value ('OU=Compta/Paie') would split the ADsPath; it is written '\/' (Search.Model rule).
    $Dn = ConvertTo-DomeniaAdsPathDn $Dn
    if ([string]::IsNullOrWhiteSpace($server)) { return "LDAP://$Dn" }
    return "LDAP://$server/$Dn"
}

function Get-DomeniaDirectoryBindUser {
    # IMPORTANT : Result.BindUser est l'identite qui a REELLEMENT reussi le bind
    # de validation. C'est donc elle qui doit etre reutilisee partout apres le
    # login. Le PSCredential d'origine peut contenir le sAMAccountName court saisi
    # dans l'UI ; le reutiliser ici ferait retomber les workers sur une identite
    # differente de celle validee (ex. user au lieu de DOMAINE\user).
    try {
        if (-not [string]::IsNullOrWhiteSpace([string]$script:Conn.BindUser)) {
            return ([string]$script:Conn.BindUser).Trim()
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaDirectoryBindUser' $_ }
    try {
        if ($null -ne $script:Conn.Credential -and -not [string]::IsNullOrWhiteSpace([string]$script:Conn.Credential.UserName)) {
            return ([string]$script:Conn.Credential.UserName).Trim()
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaDirectoryBindUser' $_ }
    return ""
}

function Get-LdapEntry {
    param([string]$Dn)
    $path = Get-LdapPath $Dn
    if (-not [bool]$script:Conn.UseCredential) {
        return New-Object -TypeName System.DirectoryServices.DirectoryEntry -ArgumentList @($path)
    }
    if ($null -eq $script:Conn.Credential) { throw "Credential AD explicite absent du contexte." }
    $bindUser = Get-DomeniaDirectoryBindUser
    if ([string]::IsNullOrWhiteSpace($bindUser)) { $bindUser = [string]$script:Conn.Credential.UserName }
    # SE-16: the real boundary. DirectoryEntry only accepts the password as a String: the copy made here is immutable
    # and stays in memory until the garbage collector reclaims it; no assignment can erase it. It is therefore made
    # at the last moment, handed to the Windows API at once, and never stored in a variable, logged or displayed.
    return New-Object -TypeName System.DirectoryServices.DirectoryEntry -ArgumentList @(
        $path,
        $bindUser,
        $script:Conn.Credential.GetNetworkCredential().Password,
        [System.DirectoryServices.AuthenticationTypes]::Secure
    )
}

function New-LdapSearcher {
    param(
        [string]$BaseDn,
        [string]$Filter,
        [string[]]$Properties,
        [string]$Scope = "OneLevel",
        [int]$Limit = 0
    )
    $root = Get-LdapEntry $BaseDn
    $s = New-Object -TypeName System.DirectoryServices.DirectorySearcher -ArgumentList $root
    $s.Filter = $Filter
    if ($Scope -eq "Subtree") { $s.SearchScope = [System.DirectoryServices.SearchScope]::Subtree } else { $s.SearchScope = [System.DirectoryServices.SearchScope]::OneLevel }
    $s.PageSize = [int](Get-CfgValue "Browser" "MaxPageSize" 300)
    if ($Limit -gt 0) { $s.SizeLimit = $Limit }
    $s.ServerTimeLimit = [TimeSpan]::FromSeconds(20)
    $s.ClientTimeout = [TimeSpan]::FromSeconds(25)
    if ($Properties) { foreach ($p in $Properties) { [void]$s.PropertiesToLoad.Add($p) } }
    return $s
}

function ConvertTo-DomeniaSecureString {
    # Seals a value the caller already holds as a String (password reset fields, generated password). The sign-in
    # window and the account fields read PasswordBox.SecurePassword directly instead (SE-16).
    param([AllowNull()][string]$Text)
    $secure = New-Object System.Security.SecureString
    if ($null -ne $Text) {
        foreach ($character in $Text.ToCharArray()) { $secure.AppendChar($character) }
    }
    $secure.MakeReadOnly()
    return $secure
}

