function Add-DomeniaAdBinaryDirectoryCandidate {
    param([System.Collections.Generic.List[string]]$List,[string]$Value)
    if ([string]::IsNullOrWhiteSpace($Value)) { return }
    try {
        $full = [System.IO.Path]::GetFullPath($Value)
        foreach ($existing in $List) {
            if ([string]::Equals([string]$existing,$full,[System.StringComparison]::OrdinalIgnoreCase)) { return }
        }
        [void]$List.Add($full)
    }
    catch { Write-DomeniaSwallowed 'Core' 'Add-DomeniaAdBinaryDirectoryCandidate' $_ }
}

function Get-DomeniaAdModuleSources {
    $sources = New-Object System.Collections.ArrayList
    $rsatManifest = Join-Path $env:WINDIR "System32\WindowsPowerShell\v1.0\Modules\ActiveDirectory\ActiveDirectory.psd1"
    if (Test-Path -LiteralPath $rsatManifest -PathType Leaf) {
        [void]$sources.Add([pscustomobject]@{ Kind="RSAT"; Path=[System.IO.Path]::GetFullPath($rsatManifest); ResourcePath="" })
    }

    $directories = New-Object System.Collections.Generic.List[string]
    $processPath = ""
    try { $processPath = [string][System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaAdModuleSources' $_ }
    if ($script:IsCompiledExecutable -and -not [string]::IsNullOrWhiteSpace($processPath)) {
        Add-DomeniaAdBinaryDirectoryCandidate -List $directories -Value (Split-Path -Parent $processPath)
    }
    foreach ($sourcePath in @($script:BootstrapPSCommandPath,$script:BootstrapInvocationPath)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$sourcePath)) {
            try { Add-DomeniaAdBinaryDirectoryCandidate -List $directories -Value (Split-Path -Parent $sourcePath) } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaAdModuleSources' $_ }
        }
    }
    Add-DomeniaAdBinaryDirectoryCandidate -List $directories -Value $script:BootstrapScriptRoot
    try { Add-DomeniaAdBinaryDirectoryCandidate -List $directories -Value ([Environment]::CurrentDirectory) } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaAdModuleSources' $_ }
    try { Add-DomeniaAdBinaryDirectoryCandidate -List $directories -Value ((Get-Location).ProviderPath) } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaAdModuleSources' $_ }

    foreach ($directory in $directories) {
        $management = Join-Path $directory "Microsoft.ActiveDirectory.Management.dll"
        $resources = Join-Path $directory "ActiveDirectoryPowerShellResources.dll"
        if ((Test-Path -LiteralPath $management -PathType Leaf) -and (Test-Path -LiteralPath $resources -PathType Leaf)) {
            [void]$sources.Add([pscustomobject]@{
                Kind="Binary"
                Path=[System.IO.Path]::GetFullPath($management)
                ResourcePath=[System.IO.Path]::GetFullPath($resources)
            })
            break
        }
    }
    return @($sources)
}

function Assert-DomeniaAdBinarySource {
    param($Source)
    if (-not [Environment]::Is64BitProcess) { throw "Le module Active Directory autonome exige un processus 64 bits." }
    $managementHash = (Get-FileHash -LiteralPath ([string]$Source.Path) -Algorithm SHA256 -ErrorAction Stop).Hash
    if ($managementHash -ne "1A6AF7B8F8BCE5B35FF873E2528746480C980526D86E38CA5ACD04C2E9037157") {
        throw "Integrite invalide pour Microsoft.ActiveDirectory.Management.dll : $managementHash"
    }
    $resourceHash = (Get-FileHash -LiteralPath ([string]$Source.ResourcePath) -Algorithm SHA256 -ErrorAction Stop).Hash
    if ($resourceHash -ne "E233D92238AA31EA1B3C60145D8811EDB2E517E1B9B53F4BC496883EE5D9973B") {
        throw "Integrite invalide pour ActiveDirectoryPowerShellResources.dll : $resourceHash"
    }
    $assemblyName = [System.Reflection.AssemblyName]::GetAssemblyName([string]$Source.Path)
    $token = [System.BitConverter]::ToString($assemblyName.GetPublicKeyToken()).Replace("-","").ToLowerInvariant()
    if ($assemblyName.Name -ne "Microsoft.ActiveDirectory.Management") { throw "Nom d assembly Active Directory inattendu : $($assemblyName.Name)" }
    if ($assemblyName.Version -ne [version]"10.0.0.0") { throw "Version d assembly Active Directory inattendue : $($assemblyName.Version)" }
    if ($token -ne "31bf3856ad364e35") { throw "Jeton de cle publique Active Directory inattendu : $token" }
}

function Test-DomeniaAdCommandsAvailable {
    $missing = @((Get-DomeniaRequiredAdCommands) | Where-Object { $null -eq (Get-Command -Name $_ -CommandType Cmdlet -ErrorAction SilentlyContinue) })
    return ($missing.Count -eq 0)
}

function Get-SelectedComputerTarget {
    # D012: a control label never supplies a workstation target.
    $identity = Get-DomeniaCurrentSelectionIdentity -Workspace 'WsObject'
    if ($null -eq $identity -or $identity.Type -ne 'Machine') { return '' }
    if ($script:CurrentObjectRequestDn -and [string]$script:CurrentObjectRequestDn -ine [string]$identity.DN) { return '' }
    $name = [string]$identity.Login
    if ($name.EndsWith('$')) { $name = $name.Substring(0,$name.Length-1) } else { $name = [string]$identity.Name }
    try { return (Assert-DomeniaComputerTarget $name) } catch { return '' }
}

function Assert-DomeniaComputerTarget {
    param([string]$Computer)
    $value = ([string]$Computer).Trim().TrimEnd('.')
    if ([string]::IsNullOrWhiteSpace($value)) { throw "Nom de poste vide." }
    if ($value.Length -gt 253) { throw "Nom de poste trop long." }
    $dnsLabel = '[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?'
    if ($value -notmatch "^(?:$dnsLabel)(?:\.(?:$dnsLabel))*$") {
        throw "Nom de poste refuse : seuls un nom NetBIOS ou DNS valide issu d'Active Directory sont acceptes."
    }
    return $value
}

function Set-ClipboardSafe {
    param([string]$Text)
    try { [System.Windows.Clipboard]::SetText([string]$Text) }
    catch { throw "Le presse-papiers Windows est indisponible : $($_.Exception.Message)" }
}

function Copy-ObjectSummary {
    try {
        if ($null -eq $script:SelectedObject) { return }
        $txt = @(
            "Type : $($script:SelectedObject.Type)",
            "Nom  : $($script:SelectedObject.Name)",
            "DN   : $($script:SelectedObject.DN)",
            "GUID : $($script:Ctrl["TxtObjGuid"].Text)",
            "Modifie : $($script:Ctrl["TxtObjChanged"].Text)",
            "Association : $(Get-SelectedAssociationSummary)"
        ) -join [Environment]::NewLine
        Set-ClipboardSafe $txt
        Set-Status "Resume objet copie."
    }
    catch { Show-ErrorBox "Erreur copie resume : $($_.Exception.Message)" }
}

function Open-SelectedParentBranch {
    try {
        if ($null -eq $script:SelectedObject) { return }
        $dn = $script:SelectedObject.DN
        $idx = $dn.IndexOf(",")
        if ($idx -lt 0) { return }
        $parentDn = $dn.Substring($idx + 1)
        $script:SelectedBranchDn = $parentDn
        $script:Ctrl["TxtBranchDn"].Text = $parentDn
        Load-BranchObjects -Browse
        Set-Status "Branche parent chargee : $parentDn"
    }
    catch { Show-ErrorBox "Erreur branche parent : $($_.Exception.Message)" }
}





function Copy-RawAttributesToClipboard {
    try {
        if ($null -eq $script:Ctrl["DgRawAttrs"].ItemsSource) { return }
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($r in $script:Ctrl["DgRawAttrs"].ItemsSource) { [void]$lines.Add("$($r.Attribute) = $($r.Value)") }
        Set-ClipboardSafe (($lines.ToArray()) -join [Environment]::NewLine)
        Set-Status "Attributs copies dans le presse-papiers."
    }
    catch { Show-ErrorBox "Erreur copie attributs : $($_.Exception.Message)" }
}

function Escape-LdapValue {
    # CD-13: one RFC 4515 rule for the whole interface, ConvertTo-DomeniaLdapLiteral (Search.Model). With -KeepWildcard
    # consecutive asterisks are merged (CO-34). The worker copy Escape-WLdap is generated from the same source.
    param([string]$Value, [switch]$KeepWildcard)
    return (ConvertTo-DomeniaLdapLiteral -Value $Value -KeepWildcard:$KeepWildcard)
}

function Get-PropFirst {
    param($Props, [string]$Name, $Default = "")
    try {
        if ($Props -and $Props.Contains($Name) -and $Props[$Name].Count -gt 0) { return $Props[$Name][0] }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Get-PropFirst' $_ }
    return $Default
}





function Convert-ADLargeIntegerToInt64 {
    param($Value)
    if ($null -eq $Value) { return 0 }
    if ($Value -is [int64]) { return [int64]$Value }
    if ($Value -is [int]) { return [int64]$Value }
    try {
        # A genuine ADSI IADsLargeInteger exposes no member to PowerShell 5.1: read it through IDispatch first.
        $type = $Value.GetType()
        try {
            $high = $type.InvokeMember('HighPart',[Reflection.BindingFlags]::GetProperty,$null,$Value,$null)
            $low = $type.InvokeMember('LowPart',[Reflection.BindingFlags]::GetProperty,$null,$Value,$null)
        }
        catch { $high = $Value.HighPart; $low = $Value.LowPart }
        if ($null -eq $high -or $null -eq $low) { return 0 }
        $high = [int64]$high
        $low = [int64]$low
        if ($low -lt 0) { $low = $low + 4294967296 }
        return (($high -shl 32) -bor $low)
    }
    catch { return 0 }
}

function Convert-FileTimeLabel {
    param($Value)
    $i = Convert-ADLargeIntegerToInt64 $Value
    if ($i -le 0 -or $i -eq 9223372036854775807) { return "Jamais" }
    try { return ([DateTime]::FromFileTimeUtc($i).ToLocalTime().ToString("dd/MM/yyyy HH:mm:ss")) } catch { return "" }
}

function Convert-DateLabel {
    param($Value)
    if ($null -eq $Value -or "" -eq [string]$Value) { return "" }
    try { return ([DateTime]$Value).ToString("dd/MM/yyyy HH:mm:ss") } catch { return [string]$Value }
}

function Convert-GuidLabel {
    param($Value)
    try {
        if ($Value -is [byte[]]) { return ([guid]$Value).Guid }
        return [string]$Value
    }
    catch { return "" }
}

function Get-UacStatusLabel {
    param($Uac, $Lockout, $Computed = $null)
    if ($null -eq $Uac -or [string]::IsNullOrWhiteSpace([string]$Uac)) { return 'Etat non determine' }
    $u = 0L
    if (-not [long]::TryParse([string]$Uac,[ref]$u)) { return 'Etat non determine' }
    $items = [Collections.Generic.List[string]]::new()
    if (($u -band 2) -ne 0) { $items.Add('Desactive') } else { $items.Add('Actif') }
    $c=0L
    if ($null -ne $Computed -and [long]::TryParse([string]$Computed,[ref]$c)) {
        if (($c -band 16) -ne 0) { $items.Add('Verrouille') }
        if (($c -band 8388608) -ne 0) { $items.Add('Mot de passe expire') }
    } elseif ((Convert-ADLargeIntegerToInt64 $Lockout) -gt 0) {
        $items.Add('Verrouillage a verifier')
    }
    if (($u -band 65536) -ne 0) { $items.Add('MDP jamais expire') }
    if (($u -band 32) -ne 0) { $items.Add('MDP non requis') }
    return ($items -join ' / ')
}

function Get-UacFlagsLabel {
    # Traduit userAccountControl en options lisibles. Les bits absents de cette table restent
    # visibles en hexadecimal : un compte etrange ne doit jamais prendre l'air d'un compte ordinaire.
    param($Uac)
    $u = 0L
    if ($null -eq $Uac -or [string]::IsNullOrWhiteSpace([string]$Uac)) { return 'Options non déterminées' }
    if (-not [long]::TryParse([string]$Uac,[ref]$u)) { return 'Options non déterminées' }
    $marques = @(
        @(1,'Script de connexion'),
        @(2,'Compte désactivé'),
        @(8,'Répertoire personnel requis'),
        @(16,'Compte verrouillé'),
        @(32,'Mot de passe non requis'),
        @(64,'Mot de passe non modifiable'),
        @(128,'Mot de passe stocké en clair'),
        @(256,'Compte temporaire'),
        @(512,'Compte normal'),
        @(2048,'Approbation entre forêts'),
        @(4096,'Compte ordinateur'),
        @(8192,'Contrôleur de domaine'),
        @(65536,'Mot de passe jamais expiré'),
        @(131072,'Compte de messagerie'),
        @(262144,'Carte à puce obligatoire'),
        @(524288,'Authentification déléguée'),
        @(1048576,'Authentification non déléguable'),
        @(2097152,'Chiffrement DES uniquement'),
        @(4194304,'Pre-authentication Kerberos facultative'),
        @(8388608,'Mot de passe expiré'),
        @(16777216,'Authentification déléguée vers un service'),
        @(67108864,'Contrôleur de domaine en lecture seule')
    )
    $items = [Collections.Generic.List[string]]::new()
    $connu = 0L
    foreach ($marque in $marques) {
        $valeur = [long]$marque[0]
        if (($u -band $valeur) -ne 0) { [void]$items.Add([string]$marque[1]); $connu = $connu -bor $valeur }
    }
    $reste = $u -band (-bnot $connu)
    if ($reste -ne 0) { [void]$items.Add(('Bits non reconnus 0x{0:X}' -f $reste)) }
    if ($items.Count -eq 0) { return 'Aucune option marquée' }
    return ($items -join ' · ')
}

function Get-DomeniaControl {
    param([Parameter(Mandatory=$true)][string]$Name)
    try {
        if ($null -eq $script:Ctrl) { return $null }
        if ($script:Ctrl -is [System.Collections.IDictionary]) {
            if ($script:Ctrl.Contains($Name)) { return $script:Ctrl[$Name] }
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaControl' $_ }
    return $null
}

function Get-DomeniaFriendlyControlLabel {
    param($Control)
    # Static labels only. A TextBox can contain a password, including when revealed.
    return [string](Get-DomeniaUxHelpEntry -Control $Control).Title
}

function Get-DomeniaDefaultToolTip {
    param($Control)
    return [string](Get-DomeniaUxHelpEntry -Control $Control).Text
}

function Set-DomeniaContextHint {
    param([string]$Title,[string]$Text)
    # PowerShell names are case-insensitive: Title and title must not share a slot.
    $titleControl = Get-DomeniaControl -Name 'LblContextTitle'
    $hintControl = Get-DomeniaControl -Name 'LblContextHint'
    $resolvedTitle = if ([string]::IsNullOrWhiteSpace($Title)) { 'Aide contextuelle' } else { $Title }
    $resolvedText = if ([string]::IsNullOrWhiteSpace($Text)) { 'Survolez un contrôle ou utilisez Tab pour lire son rôle ici.' } else { $Text }
    if ($resolvedTitle.Length -gt 110) { $resolvedTitle=$resolvedTitle.Substring(0,110) }
    if ($resolvedText.Length -gt 900) { $resolvedText=$resolvedText.Substring(0,900) }
    if ($null -ne $titleControl) { $titleControl.Text=$resolvedTitle }
    if ($null -ne $hintControl) { $hintControl.Text=$resolvedText }
}

function Enable-DomeniaUxHints {
    Initialize-DomeniaUxShell
}

function Set-DomeniaControlText {
    param([Parameter(Mandatory=$true)][string]$Name,[AllowNull()][string]$Text)
    $control = Get-DomeniaControl -Name $Name
    if ($null -eq $control) { return $false }
    try { $control.Text = [string]$Text; return $true } catch { return $false }
}

function Get-DomeniaGridDateSortKey {
    # CO-03 : cle de tri des colonnes datees. La valeur affichee est une chaine ; triee comme
    # texte, 09/05/2026 passe avant 10/01/2026. Une date illegible ou absente (« Jamais », « »)
    # trie comme la plus ancienne : la ligne descend d un tri croissant au lieu de se glisser au
    # milieu du tableau par la chance de sa chaine.
    param($Value)
    $text = [string]$Value
    if ([string]::IsNullOrWhiteSpace($text)) { return [datetime]::MinValue }
    $parsed = [datetime]::MinValue
    foreach ($format in @('dd/MM/yyyy HH:mm:ss','dd/MM/yyyy HH:mm','dd/MM/yyyy')) {
        if ([datetime]::TryParseExact($text, $format, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::None, [ref]$parsed)) { return $parsed }
    }
    return [datetime]::MinValue
}
function Get-DomeniaGridDateShortText {
    # CO-03 : l affiche court des colonnes datees. La date complete reste dans l infobulle et dans
    # le CSV : « il y a 3 j » ne se relit pas six mois plus tard, et un export part en controle.
    # Une valeur que le poste ne donne pas (« Jamais », « », une chaine inconnue) est rendue telle
    # quelle : rien n est invente. $Now vient du banc pour que l ecart mesure reste deterministe.
    param($Value,$Now)
    $text = [string]$Value
    if ([string]::IsNullOrWhiteSpace($text)) { return $text }
    $instant = Get-DomeniaGridDateSortKey $text
    if ($instant -eq [datetime]::MinValue) { return $text }
    $reference = if ($null -ne $Now) { [datetime]$Now } else { [datetime]::Now }
    $age = $reference - $instant
    if ($age.TotalSeconds -lt 0) { return $instant.ToString('dd/MM/yyyy',[Globalization.CultureInfo]::InvariantCulture) }
    if ($age.TotalMinutes -lt 1) { return "à l'instant" }
    if ($age.TotalHours -lt 1) { return ('il y a {0} min' -f [int][Math]::Floor($age.TotalMinutes)) }
    if ($age.TotalDays -lt 1) { return ('il y a {0} h' -f [int][Math]::Floor($age.TotalHours)) }
    if ($age.TotalDays -lt 31) { return ('il y a {0} j' -f [int][Math]::Floor($age.TotalDays)) }
    return $instant.ToString('dd/MM/yyyy',[Globalization.CultureInfo]::InvariantCulture)
}
function Get-DomeniaInventoryAgeLabel {
    # FO-07 : l'age de la derniere lecture reprise de la session. Le texte court vient de la regle des
    # colonnes datees (CO-03) pour que « il y a 3 j » veuille dire la meme chose partout ; l'heure
    # complete reste dans l'infobulle, car un age relatif ne se relit pas une heure plus tard.
    # $CompletedAt est une date, pas une chaine : elle est formatee a la culture invariante pour que
    # l'heure lue sur un poste en culture francaise ne soit pas relue en mois/jour sur un autre.
    param($CompletedAt,$Now)
    if ($CompletedAt -isnot [datetime]) { return '' }
    $text = $CompletedAt.ToString('dd/MM/yyyy HH:mm:ss',[Globalization.CultureInfo]::InvariantCulture)
    $short = Get-DomeniaGridDateShortText $text $Now
    if ([string]::IsNullOrWhiteSpace($short)) { return '' }
    if ($short -eq "à l'instant") { return "Inventaire à lʼinstant" }
    if ($short -like 'il y a *') { return ('Inventaire dʼ' + $short) }
    return ('Inventaire du ' + $short)
}
function Get-DomeniaInventorySummaryText {
    # FO-07 : une seule phrase pour la liste fraiche et pour la liste reprise de la session. Ecrite deux
    # fois, elle divergerait, et l'operateur ne saurait plus laquelle des deux dit vrai.
    param([string]$Computer,$Rows,$Access,[long]$DurationMs)
    $all = @($Access)
    $ok = @($all | Where-Object { [string]$_.Status -eq "OK" }).Count
    $refused = @($all | Where-Object { [string]$_.Status -eq "REFUSE" }).Count
    $unavailable = @($all | Where-Object { [string]$_.Status -eq "INDISPONIBLE" }).Count
    $other = $all.Count - $ok - $refused - $unavailable
    return "{0} : {1} element(s) sur {2} source(s) accessibles, {3} refusee(s), {4} indisponible(s), {5} autre(s), en {6} ms." -f `
        $Computer,@($Rows).Count,$ok,$refused,$unavailable,$other,$DurationMs
}
function Add-DomeniaGridDateKeys {
    # CO-03 : les cles sont portees par la ligne, pas par la colonne. Les grilles recoivent des
    # objets varies (ResultRow, lignes restaurees du cache en pscustomobject) : une cle portee par la
    # seule classe ResultRow laisserait les secondes trier et s afficher a l aveugle, sans erreur.
    param($Row,[string[]]$Fields=@(),$Now)
    if ($null -eq $Row -or -not $Fields.Count) { return $Row }
    foreach ($field in $Fields) {
        $name = [string]$field
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        $value = $null
        try { $value = $Row.PSObject.Properties[$name].Value } catch { $value = $null }
        $text = [string]$value
        $Row | Add-Member -NotePropertyName ($name + 'Sort') -NotePropertyValue (Get-DomeniaGridDateSortKey $text) -Force
        $Row | Add-Member -NotePropertyName ($name + 'Short') -NotePropertyValue (Get-DomeniaGridDateShortText -Value $text -Now $Now) -Force
    }
    return $Row
}
function Set-DomeniaItemsSource {
    param([Parameter(Mandatory=$true)][string]$Name,$Rows)
    $control = Get-DomeniaControl -Name $Name
    if ($null -eq $control) { return $false }
    $filterCounts = $null
    try {
        if ($Name -eq 'DgObjects') {
            $loaded=@($Rows | Where-Object { $null -ne $_ })
            # CO-05: the filter of the list narrows any loaded list, global search included (no request). D031 still holds:
            # a new search never inherits it, Invoke-GlobalSearch clears it before reading the directory.
            $filter=Get-DomeniaControl 'TxtSuiteResultFilter'
            $query=if($null -eq $filter){''}else{[string]$filter.Text}
            $Rows=if([string]::IsNullOrWhiteSpace($query)){$loaded}else{@($loaded | Where-Object { Test-DomeniaExperienceRow $_ $query })}
            # CO-03 : calculee ici et non a la production de la ligne, parce que c est le seul chemin par
            # ou passent toutes les lignes affichees : recherche, cache, enrichissement de la fiche.
            foreach ($row in @($Rows | Where-Object { $null -ne $_ })) { [void](Add-DomeniaGridDateKeys -Row $row -Fields @('Changed','LastLogon')) }
            $visible=@($Rows | Where-Object { $null -ne $_ }).Count
            [void](Set-DomeniaControlText 'LblSuiteResultCount' ("$visible ligne(s) visible(s) · filtre de la liste, sans requête AD"))
            # UX-03: a repainted copy (presence, history) counts against the whole list it was taken from.
            if ($null -ne (Get-Command Update-DomeniaFilteredEmptyState -CommandType Function -ErrorAction SilentlyContinue)) {
                $filterCounts=[pscustomobject]@{Loaded=[Math]::Max($loaded.Count,@($script:BranchObjects).Count);Visible=$visible}
            }
        }
        if ($Name -eq 'DgInventory') {
            # UX-37 : la grille affiche un libelle, pas le code CIM. Calculee ici, sur le seul chemin par ou
            # passent les lignes affichees. La valeur brute reste sur la ligne : c est elle que l infobulle
            # montre, que le clic droit copie et que l export ecrit, pour relire la propriete WMI d origine.
            foreach ($row in @($Rows | Where-Object { $null -ne $_ })) {
                $row | Add-Member -MemberType NoteProperty -Name 'ValueText' -Force -Value ([string](Get-DomeniaInventoryValueText -Category $row.Category -Item $row.Item -Value $row.Value))
            }
        }
        # Ne jamais transmettre directement une List[T] PowerShell a WPF :
        # Windows PowerShell 5.1 peut lever  types des arguments incompatibles .
        $materialized = [System.Collections.ArrayList]::new()
        if ($null -ne $Rows) {
            foreach ($row in $Rows) { [void]$materialized.Add($row) }
        }
        # W13 (point 119): the counts belong to the copy about to be shown; the one empty state of the list reads them
        # when the grid takes it (« Le filtre masque N lignes » instead of an empty answer).
        if ($null -ne $filterCounts) { Update-DomeniaFilteredEmptyState -Loaded ([int]$filterCounts.Loaded) -Visible ([int]$filterCounts.Visible) -Source $materialized }
        $control.ItemsSource = $null
        $control.ItemsSource = $materialized
        return $true
    }
    catch {
        try { Write-AppLog "ItemsSource $Name impossible : $($_.Exception.ToString())" "ERROR" } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaItemsSource' $_ }
        return $false
    }
}

function Set-DomeniaGridRows {
    # Remplace le contenu d une grille en conservant la ligne selectionnee.
    # Affecter ItemsSource declenche un SelectionChanged avec une selection
    # nulle : sans garde, la fiche affichee est purgee et la lecture AD en
    # cours est ensuite rejetee comme obsolete. C est ce qui laissait la
    # fiche vide apres une recherche, jusqu a un clic manuel sur la ligne.
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        $Rows,
        [string]$KeyProperty = "DN"
    )
    $grid = Get-DomeniaControl -Name $Name
    if ($null -eq $grid) { return $false }

    $previousKey = ""
    try {
        $current = $grid.SelectedItem
        if ($null -ne $current) { $previousKey = [string]$current.$KeyProperty }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaGridRows' $_ }

    $materialized = @($Rows)
    $restored = $false
    $script:SuppressGridSelectionEvents = $true
    try {
        if (-not (Set-DomeniaItemsSource -Name $Name -Rows $materialized)) { return $false }
        if (-not [string]::IsNullOrWhiteSpace($previousKey)) {
            foreach ($row in $materialized) {
                $key = ""
                try { $key = [string]$row.$KeyProperty } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaGridRows' $_ }
                if ($key -ieq $previousKey) {
                    try {
                        $grid.SelectedItem = $row
                        $grid.ScrollIntoView($row)
                        $restored = $true
                    }
                    catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaGridRows' $_ }
                    break
                }
            }
        }
    }
    finally { $script:SuppressGridSelectionEvents = $false }

    # La ligne selectionnee a disparu du nouveau jeu : il faut alors bien
    # notifier l interface, mais une seule fois.
    if (-not [string]::IsNullOrWhiteSpace($previousKey) -and -not $restored) {
        try { Queue-DomeniaSelectedObjectOpen } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaGridRows' $_ }
    }
    return $true
}

function Set-DomeniaControlEnabled {
    param([Parameter(Mandatory=$true)][string]$Name,[bool]$Enabled)
    $control = Get-DomeniaControl -Name $Name
    if ($null -eq $control) { return $false }
    try { $control.IsEnabled = $Enabled; return $true } catch { return $false }
}

function Get-DomeniaEffectiveWorkerResult {
    param($Result,[string[]]$RequiredProperties = @())
    $candidate = $null
    foreach ($item in @($Result)) {
        if ($null -eq $item) { continue }
        $valid = $true
        foreach ($propertyName in @($RequiredProperties)) {
            try {
                if ($null -eq $item.PSObject.Properties[$propertyName]) { $valid = $false; break }
            }
            catch { $valid = $false; break }
        }
        if ($valid) { $candidate = $item }
    }
    return $candidate
}

function Set-Status {
    # -NoFileLog: the caller already wrote its technical line, with the same incident code, in Domenia.log.
    param([string]$Text, [string]$Level = "INFO", [switch]$NoFileLog)
    try {
        # Le journal detaille en bas est l'unique surface pour les messages
        # de statut. La barre haute reste volontairement silencieuse.
        # PF-09: masked once here; the session journal reuses this masked text.
        $Text = Protect-DomeniaLogText ([string]$Text)
        $script:UiLogProtectedText = $Text
        Add-DomeniaUiLog -Text $Text -Level $Level -Area "Statut"
        # FI-08: warnings and errors also reach Domenia.log through the queued writer (not lost at closing).
        if (($Level -in @('WARN','ERROR')) -and (-not $NoFileLog)) { try { Write-DomeniaAppLogFile -Text $Text -Level $Level -Source 'Status' } catch { Write-DomeniaSwallowed 'Core' 'Set-Status' $_ } }
        if($Level -in @('WARN','ERROR') -and $null -ne (Get-Command Request-DomeniaAccessRecovery -ErrorAction SilentlyContinue)){
            [void](Request-DomeniaAccessRecovery -Operation 'Operation a verifier' -ErrorValue $Text)
        }
        $label = Get-DomeniaControl -Name "LblStatus"
        if ($null -ne $label) {
            $label.Text = ""
            $label.ToolTip = $null
            $label.Visibility = [System.Windows.Visibility]::Collapsed
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Set-Status' $_ }
}



function Set-DomeniaControlForeground {
    # Affectation typee : WPF attend un Brush, jamais une chaine.
    param($Control,[string]$Color)
    if ($null -eq $Control) { return }
    try {
        $brush = [System.Windows.Media.Brush]([System.Windows.Media.BrushConverter]::new().ConvertFromInvariantString($Color))
        if ($null -ne $brush) { $Control.Foreground = $brush }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaControlForeground' $_ }
}

function Get-DomeniaDialogOwner {
    try {
        if ($null -ne $script:Window -and $script:Window.IsVisible) { return $script:Window }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaDialogOwner' $_ }
    return $null
}

function Test-DomeniaMainHostAvailable {
    # Primitive du coeur : le bootstrap ne depend d'aucun module UI.
    try {
        return ($null -ne $script:Window -and $script:Window.IsVisible -and $script:Window.Content -is [System.Windows.Controls.Grid])
    }
    catch { return $false }
}

function Invoke-DomeniaHostWindow {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]$Window,
        [switch]$ManagedCancel,
        [switch]$PreserveTheme
    )
    # Avant la fenetre principale (login/demarrage), ShowDialog est autonome.
    if (-not (Test-DomeniaMainHostAvailable)) { return $Window.ShowDialog() }

    # Une fois le shell visible, aucune fenetre metier clandestine n'est autorisee.
    # L'hote integre doit avoir ete importe et valide par Domenia-Modules.ps1.
    $embedded = Get-Command -Name 'Show-DomeniaEmbeddedWindow' -CommandType Function -ErrorAction SilentlyContinue
    if ($null -eq $embedded) {
        throw [InvalidOperationException]::new('DOMENIA_EMBEDDED_HOST_MISSING : le panneau integre n est pas disponible. Reinstallez le paquet complet.')
    }
    return Show-DomeniaEmbeddedWindow -Window $Window -ManagedCancel:$ManagedCancel -PreserveTheme:$PreserveTheme
}

function Show-DomeniaDialog {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string]$Message,
        [string]$Title = "",
        [ValidateSet("Info","Warning","Error","Question")][string]$Kind = "Info",
        [ValidateSet("OK","YesNo")][string]$Buttons = "OK",
        [string]$Details = ""
    )

    if ([string]::IsNullOrWhiteSpace($Title)) { $Title = $script:AppName }

    if ($null -ne $script:DomeniaSurfaceState -and -not $script:DomeniaSurfaceState.Done) {
        $script:DomeniaSurfaceState.Status.Text=$Title+': '+$Message
        try { Write-AppLog ($Title+': '+$Message) 'WARN' } catch { Write-DomeniaSwallowed 'Core' 'Show-DomeniaDialog' $_ }
        if ($Buttons -eq 'YesNo') { return [Windows.MessageBoxResult]::No }
        return [Windows.MessageBoxResult]::OK
    }
    $window = New-Object System.Windows.Window
    $window.Title = $Title
    $window.Width = 580
    $window.MinWidth = 440
    $window.MaxWidth = 900
    $window.SizeToContent = [System.Windows.SizeToContent]::Height
    $window.MaxHeight = 720
    $window.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterOwner
    $window.ResizeMode = [System.Windows.ResizeMode]::CanResize
    $window.ShowInTaskbar = $false
    try { Set-AppWindowIcon $window } catch { Write-DomeniaSwallowed 'Core' 'Show-DomeniaDialog' $_ }
    $palette=Get-DomeniaBootThemePalette -Theme (Get-DomeniaStoredTheme)
    $brush=[Windows.Media.BrushConverter]::new()
    $window.Background=$brush.ConvertFromInvariantString([string]$palette.Window)
    $window.Foreground=$brush.ConvertFromInvariantString([string]$palette.Text)
    $owner = Get-DomeniaDialogOwner
    if ($null -ne $owner) { try { $window.Owner = $owner } catch { Write-DomeniaSwallowed 'Core' 'Show-DomeniaDialog' $_ } }
    if ($null -ne (Get-Command Set-DomeniaWindowFrameTheme -ErrorAction SilentlyContinue)) { [void](Set-DomeniaWindowFrameTheme -Window $window) }

    $root = New-Object System.Windows.Controls.Grid
    $root.Margin = '22'
    [void]$root.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition -Property @{ Height='Auto' }))
    [void]$root.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition -Property @{ Height='Auto' }))
    [void]$root.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition -Property @{ Height='Auto' }))

    $body = New-Object System.Windows.Controls.Grid
    [System.Windows.Controls.Grid]::SetRow($body,0)
    [void]$body.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition -Property @{ Width='52' }))
    [void]$body.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition -Property @{ Width='*' }))

    $icon = New-Object System.Windows.Controls.TextBlock
    $icon.FontFamily = 'Segoe UI Symbol'
    $icon.FontSize = 30
    $icon.VerticalAlignment = 'Top'
    $icon.HorizontalAlignment = 'Center'
    switch ($Kind) {
        'Error'    { $icon.Text=''; $icon.Foreground=$brush.ConvertFromInvariantString([string]$palette.Error) }
        'Warning'  { $icon.Text=''; $icon.Foreground=$brush.ConvertFromInvariantString([string]$palette.Warning) }
        'Question' { $icon.Text='?'; $icon.Foreground=$brush.ConvertFromInvariantString([string]$palette.AccentText); $icon.FontWeight='Bold' }
        default    { $icon.Text='i'; $icon.Foreground=$brush.ConvertFromInvariantString([string]$palette.AccentText) }
    }
    [System.Windows.Controls.Grid]::SetColumn($icon,0)
    [void]$body.Children.Add($icon)

    $messageBlock = New-Object System.Windows.Controls.TextBlock
    $messageBlock.Text = $Message
    $messageBlock.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $messageBlock.FontFamily = 'Segoe UI'
    $messageBlock.FontSize = 14
    $messageBlock.Foreground = $window.Foreground
    $messageBlock.Margin = '12,2,0,0'
    [System.Windows.Controls.Grid]::SetColumn($messageBlock,1)
    [void]$body.Children.Add($messageBlock)
    [void]$root.Children.Add($body)

    if (-not [string]::IsNullOrWhiteSpace($Details)) {
        $detailsBox = New-Object System.Windows.Controls.TextBox
        $detailsBox.Text = $Details
        $detailsBox.IsReadOnly = $true
        $detailsBox.AcceptsReturn = $true
        $detailsBox.TextWrapping = [System.Windows.TextWrapping]::Wrap
        $detailsBox.VerticalScrollBarVisibility = 'Auto'
        $detailsBox.MaxHeight = 260
        $detailsBox.Margin = '0,18,0,0'
        $detailsBox.Padding = '10'
        $detailsBox.Background = $brush.ConvertFromInvariantString([string]$palette.Input)
        $detailsBox.Foreground = $window.Foreground
        $detailsBox.ToolTip='Détails du message. Sélectionnez le texte pour le copier.'
        $detailsBox.BorderBrush = $brush.ConvertFromInvariantString([string]$palette.Border)
        [System.Windows.Controls.Grid]::SetRow($detailsBox,1)
        [void]$root.Children.Add($detailsBox)
    }

    $buttonsPanel = New-Object System.Windows.Controls.StackPanel
    $buttonsPanel.Orientation = 'Horizontal'
    $buttonsPanel.HorizontalAlignment = 'Right'
    $buttonsPanel.Margin = '0,22,0,0'
    [System.Windows.Controls.Grid]::SetRow($buttonsPanel,2)

    $result = [System.Windows.MessageBoxResult]::None
    if ($Buttons -eq 'YesNo') {
        $no = New-Object System.Windows.Controls.Button
        $no.Content='Non'; $no.Width=105; $no.Height=38; $no.Margin='0,0,10,0'; $no.IsCancel=$true
        $no.Background=$brush.ConvertFromInvariantString([string]$palette.Button); $no.Foreground=$brush.ConvertFromInvariantString([string]$palette.ButtonText); $no.ToolTip="Fermer sans valider cette demande."
        $no.Add_Click({ $script:__DomeniaDialogResult=[System.Windows.MessageBoxResult]::No; $window.Close() })
        [void]$buttonsPanel.Children.Add($no)
        $yes = New-Object System.Windows.Controls.Button
        $yes.Content='Oui'; $yes.Width=105; $yes.Height=38; $yes.IsDefault=$true
        $yes.Background=$brush.ConvertFromInvariantString([string]$palette.Accent); $yes.Foreground=$brush.ConvertFromInvariantString([string]$palette.OnAccent); $yes.FontWeight='SemiBold'
        $yes.Add_Click({ $script:__DomeniaDialogResult=[System.Windows.MessageBoxResult]::Yes; $window.Close() })
        [void]$buttonsPanel.Children.Add($yes)
        $script:__DomeniaDialogResult=[System.Windows.MessageBoxResult]::No
    }
    else {
        $ok = New-Object System.Windows.Controls.Button
        $ok.Content='OK'; $ok.Width=105; $ok.Height=38; $ok.IsDefault=$true; $ok.IsCancel=$true
        $ok.Background=$brush.ConvertFromInvariantString([string]$palette.Accent); $ok.Foreground=$brush.ConvertFromInvariantString([string]$palette.OnAccent); $ok.FontWeight='SemiBold'
        $ok.Add_Click({ $script:__DomeniaDialogResult=[System.Windows.MessageBoxResult]::OK; $window.Close() })
        [void]$buttonsPanel.Children.Add($ok)
        $script:__DomeniaDialogResult=[System.Windows.MessageBoxResult]::OK
    }
    [void]$root.Children.Add($buttonsPanel)
    $window.Content=$root
    # La duree d'attente d'une boite modale ne doit pas etre comptee comme du
    # temps de callback : sinon un simple clic tardif fait apparaitre un faux
    # "Callback UI lent" de plusieurs dizaines de secondes dans le journal.
    $window.MaxHeight=[Math]::Max(240,[Windows.SystemParameters]::WorkArea.Height-40)
    $window.MaxWidth=[Math]::Max(340,[Windows.SystemParameters]::WorkArea.Width-40)
    $window.MinWidth=[Math]::Min($window.MinWidth,$window.MaxWidth)
    $embeddedTiming = Test-DomeniaMainHostAvailable
    $modalWatch = [System.Diagnostics.Stopwatch]::StartNew()
    try { [void](Invoke-DomeniaHostWindow -Window $window) }
    finally {
        $modalWatch.Stop()
        if(-not $embeddedTiming){try { $script:ModalBlockedMs = [long]$script:ModalBlockedMs + [long]$modalWatch.ElapsedMilliseconds } catch { $script:ModalBlockedMs = [long]$modalWatch.ElapsedMilliseconds }}
    }
    $result=$script:__DomeniaDialogResult
    Remove-Variable -Scope Script -Name __DomeniaDialogResult -ErrorAction SilentlyContinue
    return $result
}

function Show-DomeniaFormDialog {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string]$Title,
        [string]$Message = "",
        [Parameter(Mandatory=$true)][array]$Fields,
        [string]$AcceptText = "Valider"
    )

    $window = New-Object System.Windows.Window
    $window.Title=$Title; $window.Width=560; $window.MinWidth=460
    $window.SizeToContent='Height'; $window.MaxHeight=760
    $window.WindowStartupLocation='CenterOwner'; $window.ResizeMode='CanResize'
    $window.ShowInTaskbar=$false
    try { Set-AppWindowIcon $window } catch { Write-DomeniaSwallowed 'Core' 'Show-DomeniaFormDialog' $_ }
    $palette=Get-DomeniaBootThemePalette -Theme (Get-DomeniaStoredTheme)
    $brush=[Windows.Media.BrushConverter]::new()
    $window.Background=$brush.ConvertFromInvariantString([string]$palette.Window)
    $window.Foreground=$brush.ConvertFromInvariantString([string]$palette.Text)
    $owner=Get-DomeniaDialogOwner
    if($null-ne $owner){try{$window.Owner=$owner}catch{Write-DomeniaSwallowed 'Core' 'Show-DomeniaFormDialog' $_}}
    if($null -ne (Get-Command Set-DomeniaWindowFrameTheme -ErrorAction SilentlyContinue)){[void](Set-DomeniaWindowFrameTheme -Window $window)}

    $scroll=New-Object System.Windows.Controls.ScrollViewer
    $scroll.VerticalScrollBarVisibility='Auto'
    $panel=New-Object System.Windows.Controls.StackPanel
    $panel.Margin='24'
    if(-not [string]::IsNullOrWhiteSpace($Message)){
        $msg=New-Object System.Windows.Controls.TextBlock
        $msg.Text=$Message; $msg.TextWrapping='Wrap'; $msg.FontSize=13; $msg.Foreground=$brush.ConvertFromInvariantString([string]$palette.Muted); $msg.Margin='0,0,0,16'
        [void]$panel.Children.Add($msg)
    }
    $controls=@{}
    foreach($field in $Fields){
        $label=New-Object System.Windows.Controls.TextBlock
        $label.Text=[string]$field.Label; $label.Foreground=$brush.ConvertFromInvariantString([string]$palette.Muted); $label.Margin='0,8,0,5'
        [void]$panel.Children.Add($label)
        $tb=New-Object System.Windows.Controls.TextBox
        $tb.Text=[string]$field.Value; $tb.MinHeight=38; $tb.Padding='9'; $tb.FontSize=13; $tb.Foreground=$window.Foreground; $tb.Background=$brush.ConvertFromInvariantString([string]$palette.Input); $tb.BorderBrush=$brush.ConvertFromInvariantString([string]$palette.Border); $tb.ToolTip=[string]$field.Label
        if($field.ContainsKey('ReadOnly') -and [bool]$field.ReadOnly){$tb.IsReadOnly=$true;$tb.Background=$brush.ConvertFromInvariantString([string]$palette.Surface)}
        $controls[[string]$field.Name]=$tb
        [void]$panel.Children.Add($tb)
    }
    $error=New-Object System.Windows.Controls.TextBlock
    $error.Foreground=$brush.ConvertFromInvariantString([string]$palette.Error); $error.TextWrapping='Wrap'; $error.MinHeight=24; $error.Margin='0,10,0,0'
    [void]$panel.Children.Add($error)
    $bp=New-Object System.Windows.Controls.StackPanel
    $bp.Orientation='Horizontal'; $bp.HorizontalAlignment='Right'; $bp.Margin='0,16,0,0'
    $cancel=New-Object System.Windows.Controls.Button
    $cancel.Content='Annuler';$cancel.Width=110;$cancel.Height=38;$cancel.Margin='0,0,10,0';$cancel.IsCancel=$true
    $cancel.Background=$brush.ConvertFromInvariantString([string]$palette.Button); $cancel.Foreground=$brush.ConvertFromInvariantString([string]$palette.ButtonText); $cancel.ToolTip="Fermer sans valider cette demande."
        $cancel.Add_Click({$script:__DomeniaFormResult=$null;$window.Close()})
    [void]$bp.Children.Add($cancel)
    $accept=New-Object System.Windows.Controls.Button
    $accept.Content=$AcceptText;$accept.Width=120;$accept.Height=38;$accept.IsDefault=$true;$accept.Background=$brush.ConvertFromInvariantString([string]$palette.Accent);$accept.Foreground=$brush.ConvertFromInvariantString([string]$palette.OnAccent);$accept.FontWeight='SemiBold'
    $accept.Add_Click({
        $result=[ordered]@{}
        foreach($key in $controls.Keys){
            $value=[string]$controls[$key].Text
            if([string]::IsNullOrWhiteSpace($value)){$error.Text="Tous les champs obligatoires doivent être renseignés.";return}
            $result[$key]=$value.Trim()
        }
        $script:__DomeniaFormResult=$result
        $window.Close()
    })
    [void]$bp.Children.Add($accept)
    [void]$panel.Children.Add($bp)
    $scroll.Content=$panel;$window.Content=$scroll
    $first=$controls.Values|Select-Object -First 1
    Register-DomeniaSurfaceReady $window ({if($null-ne $first){$first.Focus();$first.SelectAll()}})
    $window.MaxHeight=[Math]::Max(240,[Windows.SystemParameters]::WorkArea.Height-40)
    $window.MaxWidth=[Math]::Max(340,[Windows.SystemParameters]::WorkArea.Width-40)
    $window.MinWidth=[Math]::Min($window.MinWidth,$window.MaxWidth)
    $script:__DomeniaFormResult=$null
    [void](Invoke-DomeniaHostWindow -Window $window)
    $result=$script:__DomeniaFormResult
    Remove-Variable -Scope Script -Name __DomeniaFormResult -ErrorAction SilentlyContinue
    return $result
}

function Show-DomeniaPageBanner {
    # UX-06 core primitive: a banner in the page only when the main window is shown and the banner host of
    # Domenia-Embedded.UI is loaded. Otherwise the caller keeps its modal box (login, startup, fatal report).
    param([string]$Kind='Info',[string]$Message='',[string]$Details='',[string]$ActionText='',[string]$ActionPath='')
    if (-not (Test-DomeniaMainHostAvailable)) { return $false }
    if ($null -eq (Get-Command -Name 'Show-DomeniaBanner' -CommandType Function -ErrorAction SilentlyContinue)) { return $false }
    try { return [bool](Show-DomeniaBanner -Kind $Kind -Message $Message -Details $Details -ActionText $ActionText -ActionPath $ActionPath) }
    catch { return $false }
}
function Add-DomeniaErrorIncidentCode {
    # FI-07: an error shown without an incident code gets one, with its line in Domenia.log (at most once a minute
    # for the same text), so that « Copier pour le support » always points to a line of the journal.
    param([AllowEmptyString()][string]$Message)
    $text = ([string]$Message).Trim()
    if ((-not $text) -or ($text -match '\bINC-[0-9A-F]{4}\b')) { return $Message }
    $occurrence = Register-DomeniaErrorOccurrence -Signature ('Message|' + $text)
    $code = [string]$occurrence.Code
    if ([bool]$occurrence.Write) {
        $repeat = if ([int]$occurrence.Count -gt 1) { ' (même erreur ×' + [int]$occurrence.Count + ')' } else { '' }
        try { Write-AppLog ("[$code] $text$repeat") 'ERROR' } catch { Write-DomeniaSwallowed 'Core' 'Add-DomeniaErrorIncidentCode' $_ }
    }
    return ($text + "`r`n`r`nCode incident : $code.")
}
function Show-ErrorBox {
    param([string]$Message,[string]$Details='')
    if($null -ne (Get-Command Request-DomeniaAccessRecovery -ErrorAction SilentlyContinue)) {
        if(Request-DomeniaAccessRecovery -Operation 'Action demandee' -ErrorValue $Message -Interactive){return}
    }
    try { $Message = Add-DomeniaErrorIncidentCode -Message $Message } catch { Write-DomeniaSwallowed 'Core' 'Show-ErrorBox' $_ }
    # UX-06: once the main window is shown an error is a non-blocking banner (copy for support, open the journal).
    if (Show-DomeniaPageBanner -Kind Error -Message $Message -Details $Details) { return }
    [void](Show-DomeniaDialog -Message $Message -Title "$script:AppName - Erreur" -Kind Error -Buttons OK -Details $Details)
}
function Show-InfoBox {
    param([string]$Message,[string]$Details='')
    # UX-06: information is a discreet banner in the page; the modal sheet stays for decisions and write confirmations.
    if (Show-DomeniaPageBanner -Kind Info -Message $Message -Details $Details) { return }
    [void](Show-DomeniaDialog -Message $Message -Title $script:AppName -Kind Info -Buttons OK -Details $Details)
}
function Show-WarningBox {
    param([string]$Message,[string]$Details='')
    if (Show-DomeniaPageBanner -Kind Warning -Message $Message -Details $Details) { return }
    [void](Show-DomeniaDialog -Message $Message -Title "$script:AppName - Attention" -Kind Warning -Buttons OK -Details $Details)
}
function Confirm-Action { param([string]$Message,[string]$Title='') if([string]::IsNullOrWhiteSpace($Title)){$Title="$script:AppName - Confirmation"}; return ((Show-DomeniaDialog -Message $Message -Title $Title -Kind Question -Buttons YesNo) -eq [System.Windows.MessageBoxResult]::Yes) }
function Confirm-WarningAction { param([string]$Message,[string]$Title='') if([string]::IsNullOrWhiteSpace($Title)){$Title="$script:AppName - Attention"}; return ((Show-DomeniaDialog -Message $Message -Title $Title -Kind Warning -Buttons YesNo) -eq [System.Windows.MessageBoxResult]::Yes) }

function ConvertTo-DomeniaErrorInfo {
    # CD-12: Structured and Category are returned too, so that a caller never analyses the same error twice.
    param($ErrorRecordOrException,[string]$Operation="Operation",[string]$Phase='',[string]$Provider='Unknown')
    $exception = $null
    if ($ErrorRecordOrException -is [System.Management.Automation.ErrorRecord]) { $exception = $ErrorRecordOrException.Exception }
    elseif ($ErrorRecordOrException -is [System.Exception]) { $exception = $ErrorRecordOrException }
    $message = if ($null -ne $exception) { [string]$exception.Message } else { [string]$ErrorRecordOrException }
    $technical = if ($null -ne $exception) { [string]$exception.ToString() } else { $message }
    $hresult = 0
    try { if ($null -ne $exception) { $hresult = [int]$exception.HResult } } catch { Write-DomeniaSwallowed 'Core' 'ConvertTo-DomeniaErrorInfo' $_ }
    $kind = "Unexpected"
    $internal = $false
    $friendly = "$Operation a echoue."
    # D052: one structured decision (native code first, French and English alike). A delay is never a
    # rejected password; an uncertain outcome is never presented as a failure or a success.
    $decision = $null; $structured = $null
    # The step of the decision is the operation identifier only when the caller gives it (a task, CD-12): an
    # operator label never changes the classification of the historical callers.
    $step = ''
    if ([string]::IsNullOrWhiteSpace($Phase)) { $Phase = $Operation } else { $step = $Phase }
    # PF-10: the closed loader guarantees the rules; an isolated caller without them keeps the text classification.
    try {
        $structuredSource = if ($null -ne $exception) { $exception } else { $message }
        $structured = Get-DomeniaStructuredError $structuredSource -Phase $Phase -Provider $Provider
        $decision = Get-DomeniaErrorDecision -Structured $structured -Text $message -Step $step
    } catch { $decision = $null }
    $decided = $false
    if ($null -ne $decision -and [string]$decision.Category -ne 'Unknown') {
        $decided = $true
        $kind = switch ([string]$decision.Category) {
            'AccessDenied'        { 'AccessDenied' }
            'DecryptionDenied'    { 'AccessDenied' }
            'CredentialsRejected' { 'LogonFailure' }
            'AccountState'        { 'AccountState' }
            'Timeout'             { 'Timeout' }
            'Network'             { 'ServerUnavailable' }
            'Prerequisite'        { 'Prerequisite' }
            'Uncertain'           { 'Uncertain' }
            'Unconfirmed'         { 'Unconfirmed' }
            default               { 'Unexpected' }
        }
        $friendly = "$Operation : " + [string]$decision.Explanation + ' ' + [string]$decision.NextAction
    }
    if (-not $decided) {
        # Legacy text classification, kept for messages the structured decision does not classify.
        if ($hresult -eq -2147024891 -or $message -match "(?i)access.*denied|acc[eè]s.*refus|unauthori[sz]ed|insufficient.*access") {
            $kind = "AccessDenied"; $friendly = "$Operation : le compte utilise ne possede pas les droits necessaires."
        }
        elseif ($hresult -eq -2147023570 -or $message -match "(?i)logon failure|unknown user|bad password|echec.*ouverture.*session|identifiant") {
            $kind = "LogonFailure"; $friendly = "$Operation : les identifiants ont ete refuses."
        }
        elseif ($message -match "(?i)server.*not operational|serveur.*indisponible|0x8007203a|LDAP server.*unavailable") {
            $kind = "ServerUnavailable"; $friendly = "$Operation : le controleur de domaine ou le poste distant est indisponible."
        }
        elseif ($message -match "(?i)no such object|objet.*introuvable|0x80072030") {
            $kind = "ObjectNotFound"; $friendly = "$Operation : l'objet n'existe plus ou a ete deplace. Recharge les donnees."
        }
        elseif ($message -match "(?i)constraint.*violation|contrainte|password.*policy|politique.*mot de passe|0x8007202f") {
            $kind = "ConstraintViolation"; $friendly = "$Operation : Active Directory a refuse la valeur ou la politique demandee."
        }
        elseif ($message -match "(?i)already exists|existe deja|0x80071392") {
            $kind = "AlreadyExists"; $friendly = "$Operation : un objet portant deja ce nom existe."
        }
        elseif ($message -match "(?i)timed?\s*out|timeout|delai.*depass") {
            $kind = "Timeout"; $friendly = "$Operation : le delai d'attente a ete depasse. L'etat distant doit etre verifie avant de recommencer."
        }
        elseif (-not [string]::IsNullOrWhiteSpace($message)) {
            # UI-02: the raw text of a fault of Domenia itself stays in the journal and in the Expert detail.
            $isInternal = $false
            try { $isInternal = [bool](Test-DomeniaInternalFault $ErrorRecordOrException) } catch { $isInternal = $false }
            if ($isInternal) {
                $internal = $true; $friendly = "$Operation : erreur interne de Domenia. Votre travail est conservé."
            }
            else { $friendly = "$Operation : $message" }
        }
    }
    $category = ''
    if ($null -ne $decision) { $category = [string]$decision.Category }
    [pscustomobject]@{ Kind=$kind; Friendly=$friendly; Technical=$technical; HResult=$hresult; Internal=$internal; Structured=$structured; Category=$category }
}

function Test-DomeniaOperatorMessage {
    # FI-22 / UI-02: a message Domenia raised itself (throw 'texte') is written for the operator; a .NET or
    # PowerShell runtime message is not: it stays in the journal and in the Expert profile.
    param($ErrorRecordOrException)
    $record = $null; $exception = $ErrorRecordOrException
    if ($ErrorRecordOrException -is [System.Management.Automation.ErrorRecord]) { $record = $ErrorRecordOrException; $exception = $record.Exception }
    while ((($exception -is [System.Management.Automation.MethodInvocationException]) -or ($exception -is [System.Reflection.TargetInvocationException])) -and ($null -ne $exception.InnerException)) { $exception = $exception.InnerException; $record = $null }
    if ($exception -isnot [System.Exception]) { return $false }
    if ($exception.GetType() -ne [System.Management.Automation.RuntimeException]) { return $false }
    try { if ([bool]$exception.WasThrownFromThrowStatement) { return $true } } catch { Write-DomeniaSwallowed 'Core' 'Test-DomeniaOperatorMessage' $_ }
    # throw 'texte' also names its error record after the text itself.
    try {
        if ($null -eq $record) { $record = $exception.ErrorRecord }
        return (($null -ne $record) -and ([string]$record.FullyQualifiedErrorId -ceq [string]$exception.Message))
    } catch { return $false }
}

function Test-DomeniaInternalFault {
    # UI-02: a fault of Domenia itself (null value, missing member, wrong type, index, binding) tells a technician
    # nothing. A message raised by Domenia, or an I/O, network or directory message, stays readable.
    param($ErrorRecordOrException)
    $exception = $ErrorRecordOrException
    if ($ErrorRecordOrException -is [System.Management.Automation.ErrorRecord]) { $exception = $ErrorRecordOrException.Exception }
    while ((($exception -is [System.Management.Automation.MethodInvocationException]) -or ($exception -is [System.Reflection.TargetInvocationException])) -and ($null -ne $exception.InnerException)) { $exception = $exception.InnerException }
    if ($exception -isnot [System.Exception]) { return $false }
    if ($exception.GetType() -eq [System.Management.Automation.RuntimeException]) { return (-not (Test-DomeniaOperatorMessage $ErrorRecordOrException)) }
    foreach ($type in @([System.NullReferenceException],[System.InvalidCastException],[System.IndexOutOfRangeException],[System.ArgumentException],
        [System.Collections.Generic.KeyNotFoundException],[System.Management.Automation.MethodException],[System.Management.Automation.PropertyNotFoundException],
        [System.Management.Automation.ParameterBindingException],[System.Management.Automation.CommandNotFoundException])) {
        if ($exception -is $type) { return $true }
    }
    return $false
}

function New-DomeniaIncidentCode {
    # FI-07: short code read on a screenshot and searched in Domenia.log and in the Support incident (INC-7F3A).
    return ('INC-' + [guid]::NewGuid().ToString('N').Substring(0,4).ToUpperInvariant())
}

function Get-DomeniaErrorSignature {
    # FI-02: the same error is the same exception type, the same message and the same source
    # (operation name when the caller knows it, otherwise script and line, otherwise the .NET method).
    param($ErrorRecordOrException,[string]$Source='')
    $exception = $null; $record = $null
    if ($ErrorRecordOrException -is [System.Management.Automation.ErrorRecord]) { $record = $ErrorRecordOrException; $exception = $record.Exception }
    elseif ($ErrorRecordOrException -is [System.Exception]) { $exception = $ErrorRecordOrException }
    $type = if ($null -ne $exception) { $exception.GetType().FullName } else { 'Text' }
    $message = if ($null -ne $exception) { [string]$exception.Message } else { [string]$ErrorRecordOrException }
    $where = [string]$Source
    if (-not $where) {
        try {
            if ($null -eq $record -and $exception -is [System.Management.Automation.IContainsErrorRecord]) { $record = $exception.ErrorRecord }
            if ($null -ne $record -and $null -ne $record.InvocationInfo -and $record.InvocationInfo.ScriptLineNumber -gt 0) {
                $where = [string]$record.InvocationInfo.ScriptName + ':' + [string]$record.InvocationInfo.ScriptLineNumber
            }
        } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaErrorSignature' $_ }
    }
    if (-not $where -and $null -ne $exception) { try { $where = [string]$exception.TargetSite } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaErrorSignature' $_ } }
    return ($type + '|' + $message + '|' + $where)
}

function Register-DomeniaErrorOccurrence {
    # FI-02: one entry per error signature, with its incident code and its counter. Write is true for the first
    # occurrence, then at most once per IntervalSeconds: an error repeated in a loop gives one line a minute.
    param([string]$Signature,[datetime]$Now=(Get-Date),[int]$IntervalSeconds=60)
    if ($null -eq $script:DomeniaErrorOccurrences) { $script:DomeniaErrorOccurrences = @{} }
    $entry = $script:DomeniaErrorOccurrences[$Signature]
    if ($null -eq $entry) {
        # Bounded memory: an unusual burst of distinct errors restarts the table, never the logging.
        if ($script:DomeniaErrorOccurrences.Count -ge 200) { $script:DomeniaErrorOccurrences.Clear() }
        # FI-07: two different errors never share a code (four hex digits: a collision is drawn again).
        $used = @{}
        foreach ($known in @($script:DomeniaErrorOccurrences.Values)) { $used[[string]$known.Code] = $true }
        $code = New-DomeniaIncidentCode
        for ($try = 0; ($try -lt 64) -and $used.ContainsKey($code); $try++) { $code = New-DomeniaIncidentCode }
        $entry = [pscustomobject]@{ Code=$code; Count=0; LastWrite=[datetime]::MinValue }
        $script:DomeniaErrorOccurrences[$Signature] = $entry
    }
    $entry.Count = [int]$entry.Count + 1
    $write = (($Now - [datetime]$entry.LastWrite).TotalSeconds -ge $IntervalSeconds)
    if ($write) { $entry.LastWrite = $Now }
    return [pscustomobject]@{ Code=[string]$entry.Code; Count=[int]$entry.Count; New=([int]$entry.Count -eq 1); Write=$write }
}

function Show-DomeniaOperationError {
    param([string]$Operation,$ErrorRecordOrException,[string]$CorrelationId="",[switch]$NoPopup,[string]$OperationId='')
    $info = ConvertTo-DomeniaErrorInfo -ErrorRecordOrException $ErrorRecordOrException -Operation $Operation
    # Point 46: the family of the failure (refused access, rejected account, unavailable resource) and what the
    # operation needed. The operation is the one given, or the task whose error callback is running.
    if ((-not $OperationId) -and ($null -ne $script:AccessCurrentJob)) { try { $OperationId = [string]$script:AccessCurrentJob.OperationId } catch { $OperationId = '' } }
    try {
        $guidance = Get-DomeniaOperationFailureGuidance -OperationId $OperationId -Category ([string]$info.Category)
        if ([string]$guidance.Text) { $info.Friendly = ([string]$info.Friendly).TrimEnd() + ' ' + [string]$guidance.Text }
        $info | Add-Member -NotePropertyName FailureFamily -NotePropertyValue ([string]$guidance.Family) -Force
    } catch { Write-DomeniaSwallowed 'Core' 'Show-DomeniaOperationError' $_ }
    # FI-07: one code per error signature, identical on screen, in Domenia.log and in the Support incident.
    # FI-02: the technical line of a repeated error is written at most once a minute, with its counter.
    $occurrence = Register-DomeniaErrorOccurrence -Signature (Get-DomeniaErrorSignature -ErrorRecordOrException $ErrorRecordOrException -Source $Operation)
    $code = [string]$occurrence.Code
    $prefix = if ([string]::IsNullOrWhiteSpace($CorrelationId)) { "" } else { "[$CorrelationId] " }
    if ([bool]$occurrence.Write) {
        $repeat = if ([int]$occurrence.Count -gt 1) { " (même erreur ×$([int]$occurrence.Count))" } else { "" }
        # Area Technique: Domenia.log, raw Expert view and Support incident; the readable journal shows the sentence.
        try { Write-AppLog "[$code] $prefix$Operation [$($info.Kind)]$repeat : $($info.Technical)" "ERROR" -Area 'Technique' } catch { Write-DomeniaSwallowed 'Core' 'Show-DomeniaOperationError' $_ }
    }
    $friendly = [string]$info.Friendly
    # One Domenia.log line per error: the sentence goes to the session journal only.
    try { Set-Status "$friendly ($code)" "ERROR" -NoFileLog } catch { Write-DomeniaSwallowed 'Core' 'Show-DomeniaOperationError' $_ }
    if (-not $NoPopup) {
        $message = "$friendly`r`n`r`nCode incident : $code. Le détail technique est enregistré dans le journal Domenia."
        try {
            if ([string]$script:CurrentUiProfile -eq 'Admin') { Show-ErrorBox -Message $message -Details (Protect-DomeniaLogText ([string]$info.Technical)) }
            else { Show-ErrorBox $message }
        } catch { Write-DomeniaSwallowed 'Core' 'Show-DomeniaOperationError' $_ }
    }
    $info | Add-Member -NotePropertyName IncidentCode -NotePropertyValue $code -Force
    return $info
}

function Invoke-DomeniaSafeUiAction {
    param([string]$Operation,[scriptblock]$Action,[switch]$NoPopup)
    try { & $Action }
    catch { [void](Show-DomeniaOperationError -Operation $Operation -ErrorRecordOrException $_ -NoPopup:$NoPopup) }
}

function Invoke-DomeniaDispatcherFault {
    # FI-01: written first, re-entrance tested after. An exception raised while an error is being shown (nested
    # frame of a modal box) is logged and counted, then announced when that display ends; never dropped.
    # FI-02: one code and one banner per signature with a counter, at most one Domenia.log line a minute for it.
    param($Exception)
    $operation = 'Erreur interne de lʼinterface'
    $occurrence = Register-DomeniaErrorOccurrence -Signature (Get-DomeniaErrorSignature -ErrorRecordOrException $Exception)
    $code = [string]$occurrence.Code
    $kind = 'Unexpected'; $technical = [string]$Exception
    try {
        $info = ConvertTo-DomeniaErrorInfo -ErrorRecordOrException $Exception -Operation $operation
        $kind = [string]$info.Kind; $technical = [string]$info.Technical
    } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaDispatcherFault' $_ }
    if ([bool]$occurrence.Write) {
        $repeat = if ([int]$occurrence.Count -gt 1) { ' (même erreur ×' + [int]$occurrence.Count + ')' } else { '' }
        try { Write-AppLog ("[$code] $operation [$kind]$repeat : $technical") 'ERROR' -Area 'Technique' } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaDispatcherFault' $_ }
    }
    if ([bool]$script:HandlingDispatcherException) {
        $script:DispatcherErrorsDuringDisplay = [int]$script:DispatcherErrorsDuringDisplay + 1
        return [pscustomobject]@{ Code=$code; Count=[int]$occurrence.Count; Logged=[bool]$occurrence.Write; Shown=$false; Queued=$true; Others=0 }
    }
    $script:HandlingDispatcherException = $true
    $script:DispatcherErrorsDuringDisplay = 0
    $shown = $false; $others = 0
    try {
        $friendly = 'Un affichage nʼa pas pu se mettre à jour. Votre travail est conservé.'
        if ([bool]$occurrence.Write) { try { Set-Status "$friendly ($code)" 'ERROR' -NoFileLog } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaDispatcherFault' $_ } }
        # Without the page banner, a repeated error never opens a new modal box: it is counted in the journal.
        if ([bool]$occurrence.New -or (Test-DomeniaMainHostAvailable)) {
            $message = "$friendly`r`n`r`nCode incident : $code. Le détail technique est enregistré dans le journal Domenia."
            if ([string]$script:CurrentUiProfile -eq 'Admin') { Show-ErrorBox -Message $message -Details (Protect-DomeniaLogText $technical) }
            else { Show-ErrorBox $message }
            $shown = $true
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaDispatcherFault' $_ }
    finally {
        $script:HandlingDispatcherException = $false
        $others = [int]$script:DispatcherErrorsDuringDisplay
        $script:DispatcherErrorsDuringDisplay = 0
        if ($others -gt 0) {
            $label = if ($others -eq 1) { '1 autre erreur' } else { "$others autres erreurs" }
            try { Set-Status ("$label pendant lʼaffichage de lʼincident $code. Détail dans le journal Domenia.") 'ERROR' -NoFileLog } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaDispatcherFault' $_ }
        }
    }
    return [pscustomobject]@{ Code=$code; Count=[int]$occurrence.Count; Logged=[bool]$occurrence.Write; Shown=$shown; Queued=$false; Others=$others }
}

function Register-DomeniaDispatcherExceptionHandler {
    if ($null -eq $script:Window -or $script:DispatcherExceptionHandlerRegistered) { return }
    $script:Window.Dispatcher.Add_UnhandledException({
        param($sender,$eventArgs)
        try { [void](Invoke-DomeniaDispatcherFault -Exception $eventArgs.Exception) }
        catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaDispatcherExceptionHandler' $_ }
        finally { try { $eventArgs.Handled = $true } catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaDispatcherExceptionHandler' $_ } }
    })
    $script:DispatcherExceptionHandlerRegistered = $true
}

function Add-DomeniaUiLog {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$Text,
        [string]$Level = "INFO",
        [string]$Area = "Application"
    )

    # PF-09: a text already masked by Write-AppLog or Set-Status is not masked a second time.
    if ($null -eq $script:UiLogProtectedText -or -not ([string]$Text -ceq [string]$script:UiLogProtectedText)) { $Text = Protect-DomeniaLogText $Text }
    $script:UiLogProtectedText = $null
    # R1.5: bounded local explanations; a support failure must not break logging.
    try { Add-DomeniaSupportIncidentFromLog -Text $Text -Level $Level -Area $Area } catch { Write-DomeniaSwallowed 'Core' 'Add-DomeniaUiLog' $_ }
    try {
        if ($null -eq $script:UiLogLines) {
            $script:UiLogLines = New-Object System.Collections.Generic.List[string]
        }
        if ($script:UiLogMaxLines -lt 100) {
            $script:UiLogMaxLines = 2500
        }

        $now = Get-Date
        $line = "{0:HH:mm:ss.fff} [{1}] [{2}] {3}" -f `
            $now, `
            ([string]$Level).ToUpperInvariant(), `
            $Area, `
            $Text

        [void]$script:UiLogLines.Add($line)
        # UI-22 / UX-01: readable entry (HH:mm, icon, phrase) for the Essentiel view and the folded journal bar.
        try { Add-DomeniaExperienceLogEntry -Time $now -Level $Level -Area $Area -Text $Text } catch { Write-DomeniaSwallowed 'Core' 'Add-DomeniaUiLog' $_ }

        # Une purge retire des lignes en tete : la zone de texte doit alors
        # etre reconstruite. Sinon on se contente d une concatenation.
        $trimmed = $false
        if ($script:UiLogLines.Count -gt $script:UiLogMaxLines) {
            $removeCount = [Math]::Max(100,$script:UiLogLines.Count - $script:UiLogMaxLines)
            $script:UiLogLines.RemoveRange(0,[Math]::Min($removeCount,$script:UiLogLines.Count))
            $trimmed = $true
        }

        $box = Get-DomeniaControl -Name "TxtUiLog"
        if ($null -eq $box -and $null -ne $script:Window) {
            try { $box = $script:Window.FindName("TxtUiLog") } catch { Write-DomeniaSwallowed 'Core' 'Add-DomeniaUiLog' $_ }
        }
        if ($null -eq $box) { return }

        # Reconstruction complete uniquement si necessaire (purge, ou zone
        # desynchronisee). Le cas courant est une simple concatenation :
        # l ancienne implementation reserialisait 2500 lignes a chaque appel,
        # ce qui rendait l interface lente des que le journal se remplissait.
        $needsFullRebuild = $trimmed
        if (-not $needsFullRebuild) {
            if ([int]$script:UiLogRenderedCount -ne ($script:UiLogLines.Count - 1)) {
                $needsFullRebuild = $true
            }
        }

        $renderAction = {
            param([string]$value,[bool]$full)
            if ($full) { $box.Text = $value }
            elseif ($box.Text.Length -eq 0) { $box.AppendText($value) }
            else { $box.AppendText([Environment]::NewLine + $value) }
            $follow = Get-DomeniaControl -Name 'ChkUiLogFollow'
            if ($null -eq $follow -or [bool]$follow.IsChecked) { $box.ScrollToEnd() }
        }

        $payload = if ($needsFullRebuild) {
            [string]::Join([Environment]::NewLine,[string[]]$script:UiLogLines.ToArray())
        } else { $line }

        if ($box.Dispatcher.CheckAccess()) {
            & $renderAction $payload $needsFullRebuild
        }
        else {
            [void]$box.Dispatcher.Invoke(
                [System.Action[string,bool]]$renderAction,
                $payload,
                $needsFullRebuild
            )
        }
        $script:UiLogRenderedCount = $script:UiLogLines.Count
    }
    catch {
        try {
            if(-not $script:DataStoreValidated -or [string]::IsNullOrWhiteSpace([string]$script:DataDir)){throw 'Stockage non valide pour le journal UI.'}
            $logs=Join-Path ([string]$script:DataDir) 'Logs'
            foreach($category in @($script:StorageLayout.Categories)){
                if([string]$category.Category -eq 'Cache'){
                    foreach($area in @($category.Areas)){if([string]$area.Name -eq 'Logs'){$logs=[string]$area.Path}}
                }
            }
            $fallbackPath=Join-Path $logs 'Domenia-ui-log-errors.log'

            $fallbackDirectory = Split-Path -Parent $fallbackPath
            if (-not (Test-Path -LiteralPath $fallbackDirectory)) {
                [void](New-Item `
                    -ItemType Directory `
                    -Path $fallbackDirectory `
                    -Force)
            }

            Add-Content `
                -LiteralPath $fallbackPath `
                -Value (
                    "{0:yyyy-MM-dd HH:mm:ss.fff}`t{1}" -f `
                    (Get-Date), `
                    $_.Exception.ToString()
                ) `
                -Encoding UTF8
        }
        catch { Write-DomeniaSwallowed 'Core' 'Add-DomeniaUiLog' $_ }
    }
}


function Clear-DomeniaUiLog {
    try {
        if ($null -ne $script:UiLogLines) { $script:UiLogLines.Clear() }
        $script:UiLogRenderedCount = 0
        $box = Get-DomeniaControl -Name "TxtUiLog"
        if ($null -eq $box -and $null -ne $script:Window) {
            try { $box = $script:Window.FindName("TxtUiLog") } catch { Write-DomeniaSwallowed 'Core' 'Clear-DomeniaUiLog' $_ }
        }
        if ($null -ne $box) { $box.Clear() }
        try { Clear-DomeniaExperienceLogEntries } catch { Write-DomeniaSwallowed 'Core' 'Clear-DomeniaUiLog' $_ }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Clear-DomeniaUiLog' $_ }
}

function Load-DomeniaUiProfile {
    $value = [string](Get-DomeniaSetting "UiProfile" "Tech")
    if ($value -in @("Tech","Admin")) { $script:CurrentUiProfile = $value }
    return $script:CurrentUiProfile
}

function Save-DomeniaUiProfile {
    param([ValidateSet("Tech","Admin")][string]$Profile)
    $script:CurrentUiProfile = $Profile
    Set-DomeniaSetting -Name "UiProfile" -Value $Profile
}

function Apply-DomeniaUiProfile {
    # Explicit choice of the operator only (segmented choice of the menu foot, UI-30). L08 (CO-06): no shortcut, menu
    # or palette calls it. SP-13: when UI.AllowExpertProfile is false, Expert is never applied.
    param([ValidateSet('Tech','Admin')][string]$Profile = $script:CurrentUiProfile)
    if ($Profile -eq 'Admin' -and -not (Test-DomeniaUxExpertAllowed)) { $Profile = 'Tech' }
    Save-DomeniaUiProfile -Profile $Profile
    Update-DomeniaUxProfileVisibility
    # UI-22: readable journal in Essentiel, raw format and engine state in Expert.
    try { Update-DomeniaExperienceLogView } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaUiProfile' $_ }
    $segment = Get-DomeniaControl -Name 'LstUiProfile'
    if ($null -ne $segment) {
        foreach ($item in @($segment.Items)) {
            if ([string]$item.Tag -eq $Profile) { $segment.SelectedItem=$item;break }
        }
    }
    Apply-DomeniaGuiElementPolicy
    Sync-DomeniaUxNavigation
    $profileLabel=if($Profile -eq 'Tech'){'Essentiel'}else{'Expert'}
    Add-DomeniaUiLog -Area 'Interface' -Text ('Profil interface : '+$profileLabel)
    Set-Status ('Profil '+$profileLabel+' affiché. Les droits ne sont pas modifiés.')
}

function Get-DomeniaPresenceColor {
    # FI-16: the colour follows the state key (Online, NoReply, Error, Pending, Unknown, None), never the wording of
    # the label. -State still accepts a label (fiche, older callers): its key is read once by the Live rule.
    # Green online, red without reply, amber while checking or after a ping error, grey otherwise or for a value of an
    # earlier session (-Cached). CD-05: the status tokens of the painted theme (4.5:1 on every surface of both themes).
    param([AllowEmptyString()][string]$State,[AllowEmptyString()][string]$PresenceState='',[switch]$Cached)
    $key = if ($PresenceState) { ConvertTo-DomeniaPresenceStateKey $PresenceState } else { ConvertTo-DomeniaPresenceStateKey $State }
    $token = 'MutedColor'
    if (-not $Cached) {
        switch ($key) {
            'Online'  { $token = 'StatusSuccess' }
            'NoReply' { $token = 'StatusError' }
            'Pending' { $token = 'StatusWarning' }
            'Error'   { $token = 'StatusWarning' }
        }
    }
    return (Get-DomeniaThemeColor -Key $token)
}

function Set-DomeniaPresenceText {
    # Ecrit un etat de presence et lui applique la couleur de sa cle d etat (FI-16). Le texte peut etre detaille
    # (poste teste, confiance) : la couleur vient de -PresenceState quand l appelant la connait.
    param([Parameter(Mandatory=$true)][string]$Name,[AllowEmptyString()][string]$State,[AllowEmptyString()][string]$PresenceState='')
    [void](Set-DomeniaControlText -Name $Name -Text ([string]$State))
    $key = if ($PresenceState) { ConvertTo-DomeniaPresenceStateKey $PresenceState } else { ConvertTo-DomeniaPresenceStateKey $State }
    if ($null -eq $script:PresenceTextStates) { $script:PresenceTextStates = @{} }
    $script:PresenceTextStates[$Name] = $key
    Set-DomeniaControlForeground (Get-DomeniaControl -Name $Name) (Get-DomeniaPresenceColor -State $State -PresenceState $key)
}

function Update-DomeniaObjectPresence {
    # Recopie l etat de presence dans l onglet Resume, quel que soit le type
    # d objet, et memorise l etat pour pouvoir le recolorer au changement
    # de theme.
    param([AllowEmptyString()][string]$State,[AllowEmptyString()][string]$Target = "",[AllowEmptyString()][string]$PresenceState='')
    $script:CurrentPresenceState = [string]$State
    $script:CurrentPresenceTarget = [string]$Target
    Set-DomeniaPresenceText -Name "TxtObjPresence" -State $State -PresenceState $PresenceState
    [void](Set-DomeniaControlText -Name "TxtObjPresenceTarget" -Text ([string]$Target))
}

function Get-DomeniaCachedPresenceState {
    param([AllowEmptyString()][string]$Dn)
    try {
        $key = ([string]$Dn).Trim().ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($key)) { return "" }
        if ($script:PresenceCache.ContainsKey($key)) {
            $entry = $script:PresenceCache[$key]
            if ($null -ne $entry) {
                $observedUtc = $null
                if ($null -ne $entry.PSObject.Properties["UpdatedUtc"]) {
                    $observedUtc = ConvertTo-DomeniaUtcDate $entry.UpdatedUtc
                }
                elseif ($null -ne $entry.PSObject.Properties["Updated"]) {
                    $observedUtc = ConvertTo-DomeniaUtcDate $entry.Updated
                }
                $table = $null
                try { $table = Get-DomeniaActiveFreshnessTable } catch { $table = $null }
                $fresh = Get-DomeniaFreshness -Nature 'Presence' -ObservedUtc $observedUtc -Table $table
                if ([string]$fresh.State -eq 'Fresh') { return [string]$entry.State }
                [void]$script:PresenceCache.Remove($key)
            }
        }
        return ""
    }
    catch { return "" }
}

function Set-DomeniaResultRowPresence {
    # Synchronise la presence calculee dans une fiche avec la ligne de recherche
    # correspondante. Aucune nouvelle recherche AD n est lancee et la selection
    # courante reste intacte.
    param(
        [AllowEmptyString()][string]$Dn,
        [AllowEmptyString()][string]$State,
        [AllowEmptyString()][string]$Target = "",
        $Observation=$null
    )
    try {
        $dnValue = ([string]$Dn).Trim()
        if ([string]::IsNullOrWhiteSpace($dnValue)) { return }
        # Rendering consumes a committed observation; it never creates a new observation or timestamp.
        if($null -eq $Observation -or [string]$Observation.Key -ine $dnValue -or -not [string]$Observation.Guid){return}
        $stateKey = ConvertTo-DomeniaPresenceStateKey ([string]$Observation.Presence)
        if ($stateKey -in @('Pending','None')) { $stateKey = 'Unknown' }
        $shortState = Get-DomeniaPresenceStateLabel $stateKey
        $key = $dnValue.ToLowerInvariant()
        $observedUtc=ConvertTo-DomeniaUtcDate (Get-DomeniaMemberValue $Observation 'PresenceCheckedUtc')
        if($null -eq $observedUtc){return}
        $script:PresenceCache[$key] = [pscustomobject]@{State=$shortState;Target=[string]$Target;UpdatedUtc=$observedUtc}

        $changed = $false
        foreach ($row in @($script:BranchObjects)) {
            try {
                if ([string]$row.DN -ieq $dnValue -and [string]$row.Guid -ieq [string]$Observation.Guid) {
                    Set-DomeniaLiveRowValue $row "Presence" $shortState
                    # FI-16 / DS-15: the pill reads the key; the age of this committed measure replaces '(cache)'.
                    Set-DomeniaLiveRowValue $row "PresenceState" $stateKey
                    Set-DomeniaLiveRowValue $row "PresenceAge" (Get-DomeniaLiveAgeText -CheckedUtc $observedUtc.ToString('o'))
                    Set-DomeniaLiveRowValue $row "PresenceCached" ""
                    $changed = $true
                }
            }
            catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaResultRowPresence' $_ }
        }
        if (-not $changed) { return }

        if ($script:CurrentPresenceFilter -eq "Tous") {
            $grid = Get-DomeniaControl -Name "DgObjects"
            if ($null -ne $grid) {
                try { $grid.Items.Refresh() } catch {
                    try { [System.Windows.Data.CollectionViewSource]::GetDefaultView($grid.ItemsSource).Refresh() } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaResultRowPresence' $_ }
                }
            }
        }
        else {
            Apply-DomeniaPresenceFilter
        }
    }
    catch {
        Write-AppLog "Synchronisation presence grille impossible : $($_.Exception.Message)" "WARN"
    }
}

function Sync-DomeniaResultRowFromEntry {
    # Quand une fiche vient d etre relue depuis AD, recopie les attributs visibles
    # dans la ligne de resultats deja affichee. Le tableau ne doit pas rester sur
    # un ancien etat alors que la fiche contient les valeurs fraiches.
    param($Entry,[ValidateSet("Utilisateur","Machine")][string]$Type)
    try {
        if ($null -eq $Entry) { return }
        $dn = [string](Get-DeProp $Entry "distinguishedName" "")
        if ([string]::IsNullOrWhiteSpace($dn)) { return }
        $row = $null
        foreach ($candidate in @($script:BranchObjects)) {
            try { if ([string]$candidate.DN -ieq $dn) { $row = $candidate; break } } catch { Write-DomeniaSwallowed 'Core' 'Sync-DomeniaResultRowFromEntry' $_ }
        }
        if ($null -eq $row) { return }

        $uac = Get-DeProp $Entry "userAccountControl" $null
        $lockout = if ($Type -eq "Utilisateur") { Get-DeProp $Entry "lockoutTime" 0 } else { 0 }
        Set-DomeniaLiveRowValue $row "Name" ([string](Get-DeProp $Entry "name" ""))
        Set-DomeniaLiveRowValue $row "Description" ([string](Get-DeProp $Entry "description" ""))
        Set-DomeniaLiveRowValue $row "Changed" (Convert-DateLabel (Get-DeProp $Entry "whenChanged" ""))
        Set-DomeniaLiveRowValue $row "LastLogon" (Convert-FileTimeLabel (Get-DeProp $Entry "lastLogonTimestamp" 0))
        Set-DomeniaLiveRowValue $row "State" (Get-UacStatusLabel $uac $lockout (Get-DeProp $entry "msDS-User-Account-Control-Computed" $null))

        if ($Type -eq "Utilisateur") {
            Set-DomeniaLiveRowValue $row "Login" ([string](Get-DeProp $Entry "sAMAccountName" ""))
            Set-DomeniaLiveRowValue $row "UPN" ([string](Get-DeProp $Entry "userPrincipalName" ""))
            Set-DomeniaLiveRowValue $row "Mail" ([string](Get-DeProp $Entry "mail" ""))
        }
        else {
            $sam = [string](Get-DeProp $Entry "sAMAccountName" "")
            Set-DomeniaLiveRowValue $row "Login" ($sam.TrimEnd([char]36))
            Set-DomeniaLiveRowValue $row "UPN" ([string](Get-DeProp $Entry "dNSHostName" ""))
            Set-DomeniaLiveRowValue $row "OS" ([string](Get-DeProp $Entry "operatingSystem" ""))
        }

        # Recalcule aussi Association / Source / Confiance a partir des liens locaux.
        [void](Set-RowAssociationMetadata -Rows @($row))
        $grid = Get-DomeniaControl -Name "DgObjects"
        if ($null -ne $grid -and -not (Test-DomeniaLiveSearchActive)) { try { $grid.Items.Refresh() } catch { Write-DomeniaSwallowed 'Core' 'Sync-DomeniaResultRowFromEntry' $_ } }
    }
    catch {
        Write-AppLog "Synchronisation fiche vers grille impossible : $($_.Exception.Message)" "WARN"
    }
}

function Get-DomeniaSelectedPresenceWorkerCode {
    # Corps worker partage entre la presence machine et la presence
    # utilisateur. Son empreinte est enregistree sous SelectedPresence :
    # il ne doit pas etre modifie sans recalculer le hash.
    return @'
$target = [string]$Payload.Target
$ping = $null
try {
    $ping = New-Object System.Net.NetworkInformation.Ping
    $reply = $ping.Send($target,900)
    if ($null -ne $reply -and $reply.Status -eq [System.Net.NetworkInformation.IPStatus]::Success) {
        return "En ligne"
    }
    return "Hors ligne"
}
catch { return "Hors ligne" }
finally { try { if ($null -ne $ping) { $ping.Dispose() } } catch { } }
'@
}

function Apply-DomeniaPresenceFilter {
    if (Test-DomeniaLiveSearchActive) { Update-DomeniaLiveFilter; return }
    try {
        $rows = @($script:BranchObjects)
        if ((Get-DomeniaSearchMode) -ne "Global" -and $script:CurrentPresenceFilter -ne "Tous") {
            $rows = @($rows | Where-Object { Test-DomeniaPresenceMatch (Get-DomeniaRowPresenceState $_) $script:CurrentPresenceFilter })
        }
        $rows=@($rows|Where-Object{Test-DomeniaSearchQueryRow $_})
        [void](Set-DomeniaGridRows -Name "DgObjects" -Rows $rows)

        # Le libelle du jeu de resultats est conserve tant qu aucun filtre
        # n est actif : le scan de presence ne doit pas ecraser "n resultat(s)
        # global" par un libelle de filtre.
        $label = if ($script:CurrentPresenceFilter -eq "Tous") {
            if ([string]::IsNullOrWhiteSpace([string]$script:BranchCountLabel)) {
                "{0} objet(s)" -f $rows.Count
            } else { [string]$script:BranchCountLabel }
        }
        else { "{0} resultat(s)  filtre {1}" -f $rows.Count,$script:CurrentPresenceFilter }
        [void](Set-DomeniaControlText -Name "LblBranchCount" -Text $label)
    }
    catch {
        Add-DomeniaUiLog -Level "ERROR" -Area "Filtre presence" -Text $_.Exception.Message
    }
}

function Start-DomeniaResultPresenceScan {
    $machineRows = @($script:BranchObjects | Where-Object {
        [string]$_.Type -eq "Machine" -and ([string]$_.Presence -in @("","Inconnu","Test en cours..."))
    })
    if ($machineRows.Count -eq 0) {
        Apply-DomeniaPresenceFilter
        return
    }

    Add-DomeniaUiLog -Area "Presence" -Level "INFO" -Text (
        "Ping rapide demande pour {0} machine(s), un seul echo ICMP par poste." -f $machineRows.Count
    )

    $script:PresenceScanGeneration++
    $generation = $script:PresenceScanGeneration

    $payload = @(
        foreach ($row in $machineRows) {
            $target = ""
            # La ligne expose UPN (DNS pour une machine), jamais UpnDns :
            # l ancienne lecture renvoyait toujours vide et repliait sur le
            # nom NetBIOS.
            try { $target = [string]$row.UPN } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaResultPresenceScan' $_ }
            if ([string]::IsNullOrWhiteSpace($target)) {
                try { $target = [string]$row.Name } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaResultPresenceScan' $_ }
            }
            [pscustomobject]@{
                DN = [string]$row.DN
                Target = $target
            }
        }
    )

    $code = @'
$rows = New-Object Collections.ArrayList
$items = @($Payload)
$timeoutMs = 450
$batchSize = 64
$index = 0
while ($index -lt $items.Count) {
    $last = [Math]::Min($index + $batchSize - 1,$items.Count - 1)
    $pending = New-Object Collections.ArrayList
    for ($i=$index; $i -le $last; $i++) {
        $item = $items[$i]
        try {
            $ping = New-Object System.Net.NetworkInformation.Ping
            $task = $ping.SendPingAsync([string]$item.Target,$timeoutMs)
            [void]$pending.Add([pscustomobject]@{ DN=[string]$item.DN; Ping=$ping; Task=$task })
        }
        catch {
            [void]$rows.Add([pscustomobject]@{ DN=[string]$item.DN; Presence="Hors ligne" })
        }
    }
    if ($pending.Count -gt 0) {
        try {
            $tasks = @($pending | ForEach-Object { $_.Task })
            [void][System.Threading.Tasks.Task]::WaitAll($tasks,($timeoutMs + 900))
        }
        catch { }
        foreach ($entry in @($pending)) {
            $state = "Hors ligne"
            try {
                if ($entry.Task.IsCompleted -and -not $entry.Task.IsFaulted -and $null -ne $entry.Task.Result -and $entry.Task.Result.Status -eq [System.Net.NetworkInformation.IPStatus]::Success) {
                    $state = "En ligne"
                }
            }
            catch { }
            finally { try { $entry.Ping.Dispose() } catch { } }
            [void]$rows.Add([pscustomobject]@{ DN=[string]$entry.DN; Presence=$state })
        }
    }
    $index = $last + 1
}
return [object[]]$rows.ToArray()
'@

    Start-UiTask `
        -Name "Presence reseau" `
        -OperationId "PresenceScan" `
        -Code $code `
        -Payload $payload `
        -ReplaceKey "presence-results" `
        -TimeoutSeconds 20 `
        -StatusText "Ping rapide des postes en arriere-plan..." `
        -CallbackState ([pscustomobject]@{ Generation=$generation }) `
        -OnSuccess {
            param($result,$state)

            if ([int]$state.Generation -ne [int]$script:PresenceScanGeneration) {
                Add-DomeniaUiLog -Area "Presence" -Level "DEBUG" -Text "Resultat de presence obsolete ignore."
                return
            }

            Add-DomeniaUiLog -Area "Presence" -Level "INFO" -Text (
                "Scan termine : {0} reponse(s) recue(s)." -f @($result).Count
            )

            $map = @{}
            foreach ($item in @($result)) {
                $itemDn = [string]$item.DN
                $itemPresence = [string]$item.Presence
                $map[$itemDn] = $itemPresence
                try {
                    $cacheKey = $itemDn.Trim().ToLowerInvariant()
                    if (-not [string]::IsNullOrWhiteSpace($cacheKey)) {
                        $script:PresenceCache[$cacheKey] = [pscustomobject]@{ State=$itemPresence; Target=""; Updated=Get-Date }
                    }
                }
                catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaResultPresenceScan' $_ }
            }

            foreach ($row in @($script:BranchObjects)) {
                if ([string]$row.Type -eq "Machine") {
                    $presence = if ($map.ContainsKey([string]$row.DN)) { $map[[string]$row.DN] } else { "Inconnu" }
                    Add-Member -InputObject $row -NotePropertyName Presence -NotePropertyValue $presence -Force
                }
                elseif ([string]$row.Type -eq "Utilisateur" -and [string]::IsNullOrWhiteSpace([string]$row.Presence)) {
                    Add-Member -InputObject $row -NotePropertyName Presence -NotePropertyValue "Inconnu" -Force
                }
            }

            Apply-DomeniaPresenceFilter
            Add-DomeniaUiLog -Area "Presence" -Text "Scan termine : $(@($result).Count) machine(s) testee(s)."
        } `
        -OnError {
            param($message,$state)
            Add-DomeniaUiLog -Area "Presence" -Level "WARN" -Text "Scan incomplet : $message"
            Apply-DomeniaPresenceFilter
        } | Out-Null
}

function Start-DomeniaSelectedMachinePresence {
    param([string]$Name,[string]$DnsName)
    if(Test-DomeniaLiveSearchActive){
        $row=Get-DomeniaSelectedGridRow
        # SP-15: a fiche rendered with its probes is an explicit opening, not a simple click on the list.
        if($null -ne $row -and $row.Type -eq 'Machine' -and $null -ne $script:SelectedObject -and [string]$row.DN -ieq [string]$script:SelectedObject.DN){Select-DomeniaLiveResult -Explicit;return}
    }
    $target=if($DnsName){$DnsName}else{$Name}
    $guid=[string](Get-DomeniaMemberValue (Get-DomeniaMemberValue $script:SelectedObject 'Safety') 'Guid')
    Start-DomeniaCommittedPresence -Computer $target -Guid $guid -DN ([string]$script:SelectedObject.DN) -DisplayDN ([string]$script:SelectedObject.DN) -DisplayKind 'Machine'
}

function Update-DomeniaSelectedUserPresence {
    # Un compte AD n a pas d adresse reseau. On teste donc le poste associe
    # le plus fiable, ce qui repond a la vraie question : cet utilisateur
    # a-t-il une machine joignable en ce moment.
    # Point 9: $Guid and $CreatedUtc of the displayed account keep the workstations of a former holder of the login
    # out of the choice (no ping is sent to them).
    param([string]$Login,[string]$Guid='',$CreatedUtc=$null)

    $target = ""
    $confidence = 0
    $linksUnreadable = $false
    try {
        $links = @(Get-LinksForUser -UserLogin $Login -Guid $Guid -CreatedUtc $CreatedUtc)
        # D042/D043: a declared assignment first, then the most recent relation (relation model); RC1.10.7 order otherwise.
        if ($null -ne (Get-Command -Name Select-DomeniaBestLink -CommandType Function -ErrorAction SilentlyContinue)) { $best = Select-DomeniaBestLink $links }
        else {
            $best = $links |
                Sort-Object `
                    @{ Expression = { try { [int]$_.Confidence } catch { 0 } }; Descending = $true },
                    @{ Expression = { [string]$_.When }; Descending = $true } |
                Select-Object -First 1
        }
        if ($null -ne $best) {
            $target = [string]$best.Computer
            try { $confidence = [int]$best.Confidence } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSelectedUserPresence' $_ }
        }
    }
    catch { $linksUnreadable = $true; Write-DomeniaSwallowed 'Core' 'Update-DomeniaSelectedUserPresence' $_ }

    # P-CD-09: associations that could not be read are not "no associated workstation": the presence stays unknown.
    if ($linksUnreadable) {
        $unknown = "Non vérifié : postes associés illisibles"
        Set-DomeniaPresenceText -Name "TxtUserPresence" -State $unknown -PresenceState 'Unknown'
        Update-DomeniaObjectPresence -State $unknown -Target "" -PresenceState 'Unknown'
        Add-DomeniaUiLog -Area "Presence" -Level "WARN" -Text "$Login : postes associés illisibles, présence non vérifiée."
        return
    }

    if ([string]::IsNullOrWhiteSpace($target)) {
        Set-DomeniaPresenceText -Name "TxtUserPresence" -State "Aucun poste associe"
        Update-DomeniaObjectPresence -State "Aucun poste associe" -Target ""
        Add-DomeniaUiLog -Area "Presence" -Text "$Login : aucun poste associe."
        return
    }


    $suffix = if ($confidence -gt 0) { "  confiance $confidence%" } else { "" }
    # D043: the badge of the link, never a percentage, with the relation model.
    if ($null -ne $best -and $null -ne (Get-Command -Name Get-DomeniaLinkQualification -CommandType Function -ErrorAction SilentlyContinue)) { $suffix = (Get-DomeniaLinkQualification $best).Suffix }
    # A user has no ICMP identity. Persist under the associated machine GUID, never under the user's DN.
    $machineGuid=[string](Get-DomeniaMemberValue $best 'ComputerGuid');$machineDn=[string](Get-DomeniaMemberValue $best 'ComputerDn')
    if(-not $machineGuid -or -not $machineDn){
        $known=@($script:BranchObjects|Where-Object{[string]$_.Type -eq 'Machine' -and (Normalize-LinkComputer ([string]$_.Name)) -ieq (Normalize-LinkComputer $target)}|Select-Object -First 1)
        if($known.Count){$machineGuid=[string]$known[0].Guid;$machineDn=[string]$known[0].DN}
    }
    Start-DomeniaCommittedPresence -Computer $target -Guid $machineGuid -DN $machineDn -DisplayDN ([string]$script:SelectedObject.DN) -DisplayKind 'Utilisateur' -Suffix $suffix
}

function Get-DomeniaPreferencePath {
    # One write destination in the selected mode. Historical locations are read-only.
    param([Parameter(Mandatory=$true)][string]$FileName)
    if([IO.Path]::GetFileName($FileName) -cne $FileName -or $FileName -in @('.','..')){throw 'Nom de preference invalide.'}
    $userPath='';$previousPath='';$legacyPath=''
    if(-not [string]::IsNullOrWhiteSpace([string]$script:DataDir)){
        $previousPath=Join-Path ([string]$script:DataDir) $FileName
        $userPath=Join-Path (Join-Path ([string]$script:DataDir) 'Preferences') $FileName
    }
    if(-not [string]::IsNullOrWhiteSpace([string]$script:RootDir)){$legacyPath=Join-Path ([string]$script:RootDir) $FileName}
    return [pscustomobject]@{User=$userPath;Previous=$previousPath;Legacy=$legacyPath}
}


function Read-DomeniaPreference {
    param([Parameter(Mandatory=$true)][string]$FileName)
    $paths=Get-DomeniaPreferencePath -FileName $FileName
    $locations=@($paths.User,$paths.Previous,$paths.Legacy)
    # Original names remain compatibility-only; no historical file is rewritten or deleted.
    if($FileName.StartsWith('Domenia.',[StringComparison]::OrdinalIgnoreCase)){
        $legacyName='ADCC.'+$FileName.Substring(8)
        foreach($dir in @([string]$script:DataDir,(Join-Path $script:RootDir 'data'),[string]$script:RootDir,[string]$env:LOCALAPPDATA)){
            if($dir){$locations+=@(Join-Path $dir $legacyName)}
        }
    }
    foreach($candidate in @($locations | Where-Object {-not [string]::IsNullOrWhiteSpace([string]$_)} | ForEach-Object {$_;([string]$_+'.bak')})){
        try {
            if(-not (Test-Path -LiteralPath $candidate -PathType Leaf)){continue}
            $info=Get-Item -LiteralPath $candidate -Force
            $limit=if($FileName -ceq 'Domenia.settings.json'){4MB}else{1MB}
            if($info.Length -gt $limit -or ($info.Attributes -band [IO.FileAttributes]::ReparsePoint)){continue}
            $parent=$info.Directory;$redirected=$false
            while($null -ne $parent){if($parent.Attributes -band [IO.FileAttributes]::ReparsePoint){$redirected=$true;break};$parent=$parent.Parent}
            if($redirected){continue}
            $text=([IO.File]::ReadAllText($candidate)).Trim()
            if($FileName.EndsWith('.json',[StringComparison]::OrdinalIgnoreCase)){[void]($text | ConvertFrom-Json -ErrorAction Stop)}
            if($candidate -ine $paths.User -and $candidate -ine ($paths.User+'.bak')){
                if($null -eq $script:PreferenceLegacyReads){$script:PreferenceLegacyReads=@{}}
                if(-not $script:PreferenceLegacyReads.ContainsKey($candidate)){$script:PreferenceLegacyReads[$candidate]=$false}
                # Before startup validation, defer the trace: logging would initialize storage recursively.
                if($script:DataStoreValidated -and -not $script:PreferenceLegacyReads[$candidate]){
                    try {
                        Write-StartupTrace -Stage 'Preferences/LectureHistorique' -Detail $candidate
                        $script:PreferenceLegacyReads[$candidate]=$true
                    } catch { Write-DomeniaSwallowed 'Core' 'Read-DomeniaPreference' $_ }
                }
            }
            return $text
        } catch { Write-DomeniaSwallowed 'Core' 'Read-DomeniaPreference' $_ }
    }
    return ''
}


function Write-DomeniaPreference {
    param([Parameter(Mandatory=$true)][string]$FileName,[Parameter(Mandatory=$true)][string]$Value)
    $target=''
    try {
        $target=[string](Get-DomeniaPreferencePath -FileName $FileName).User
        if([string]::IsNullOrWhiteSpace($target)){throw 'Aucun dossier de donnees valide. Aucun autre emplacement choisi.'}
        $parent=[IO.DirectoryInfo]::new([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($target)))
        while($null -ne $parent){
            if($parent.Exists -and ($parent.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw ('Dossier de preferences redirige refuse : '+$parent.FullName)}
            $parent=$parent.Parent
        }
        foreach($path in @($target,($target+'.bak'))){
            if(Test-Path -LiteralPath $path){
                if((Get-Item -LiteralPath $path -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw ('Lien de preference refuse : '+$path)}
            }
        }
        $limit=if($FileName -ceq 'Domenia.settings.json'){4MB}else{1MB}
        if([Text.Encoding]::UTF8.GetByteCount($Value) -gt $limit){throw 'Préférences trop volumineuses ; version précédente conservée.'}
        Write-DomeniaAtomicText -LiteralPath $target -Value $Value -KeepBackup
        return $true
    } catch {
        try {Write-AppLog ("Preference '"+$FileName+"' non persistee dans '"+$target+"' : "+$_.Exception.Message) 'WARN'} catch { Write-DomeniaSwallowed 'Core' 'Write-DomeniaPreference' $_ }
        return $false
    }
}



# =====================================================================
# Reglages de l application.
# Les preferences durables sont conservees dans un fichier unique du profil utilisateur.
# Les filtres temporaires de recherche, eux, repartent sur une valeur neutre a chaque lancement.
# Le mode lecture seule est volontairement exclu : l application doit
# toujours demarrer sans droit d ecriture, quel que soit l etat dans
# lequel la session precedente a ete fermee.
# =====================================================================
function Get-DomeniaDefaultSettings {
    return [ordered]@{
        SavedSearches = @()
        # FO-04: OU favourites pinned above the tree (JSON list of perimeters), taken over once from SavedSearches,
        # which stays stored untouched.
        OuFavouritesJson = '[]'
        OuFavouritesImported = $false
        GridLayoutsJson = '{}'
        # DS-20: columns of the result grid chosen by the operator (JSON of column keys; empty: the six SP-02 columns).
        'Search.ResultColumnsJson' = ''
        OuBookmarksJson = '{}'
        UxNavCollapsed   = $false
        # UI-11: the help panel starts closed; the dot on « ? » is shown at the first launch only.
        UxHelpVisible    = $false
        UxHelpCompactOpen = $false
        UxHelpIntroSeen  = $false
        UxLogCollapsed = $false
        UxLogExpandedHeight = 180
        UxLogWrap = $false
        UxLogFontSize = 11
        UxDensity = "Confort"
        # L08 (FO-03, UX-09): the 8 latest searches and fiches of the top bar, local memory only (JSON list, no secret).
        UxRecentJson = '[]'
        Theme            = "Light"
        UiProfile        = "Tech"
        Workspace        = "TabDashboard"
        # UX-03: no PresenceFilter preference. At start-up every workstation is « Non vérifié »: a remembered
        # « En ligne » would show an empty list. The presence filter belongs to the session only.
        SearchType       = "Tous"
        SearchLimit      = "100"
        IndexAutoBuild   = "Ask"
        ParkSweepEnabled = $false
        ParkHarvestEnabled = $true
        InventoryScope   = "Toutes"
        SoftwareScope    = "Toutes"
        SoftwarePerUser  = $true
        SoftwareStore    = $false
        SoftwareUpdates  = $false
        WmiLimit         = "25"
        'Ui.ZoomPercent' = 100
        WindowWidth      = 0
        WindowHeight     = 0
        WindowLeft       = -1
        WindowTop        = -1
        WindowMaximized  = $false
        TreeWidth        = 0
        LogHeight        = 180
        # Account names only (never a password): accounts for workstations (POSTES) and secrets (SECRETS).
        RemoteCredentialUser  = ''
        SecretsCredentialUser = ''
        # Only declared keys survive reload. Query recipes and collection choices are durable.
        'Dashboard.Computer.Layout' = ''
        'Dashboard.Fleet.Layout'    = ''
        'Dashboard.Software.Layout' = ''
        'Widgets.Computer' = ''
        'Widgets.Fleet'    = ''
        'Query.Library' = ''
        'Collection.Concurrency' = '4'
        'Collection.CacheMinutes' = '15'
        # Points 11 and 159: usage profile, then per profile the durations changed by the operator and the window of
        # the background work (JSON texts, no secret).
        'Collection.Profile' = 'Standard'
        'Collection.FreshnessJson' = ''
        'Collection.WindowsJson' = ''
        # The last update of this domain stopped at its limit: '<BaseDn>|<date>|<objects read>' (Accueil warning).
        'Index.Partial'    = ''
        # Point 148: UTC date of the first overview computed with workstations while Accueil was shown; '' until then.
        'Home.DashboardSeen' = ''
        # Lot L01: the "Premiers pas" card of Accueil stays hidden once its four steps were done.
        'Home.FirstStepsDone' = $false
        # SP-15: a click on a workstation of Rechercher pings it only when the operator checked « Vérifier au clic ».
        # The user read on click follows Streaming.VerifyUserOnSelection until the operator changes it ('' = not chosen).
        LiveVerifyOnClick = $false
        LiveUserOnClick = ''
    }
}

function Load-DomeniaSettings {
    $settings = Get-DomeniaDefaultSettings
    $validJsonProfile=$false
    try {
        $text = Read-DomeniaPreference -FileName "Domenia.settings.json"
        if (-not [string]::IsNullOrWhiteSpace($text)) {
            $stored = $text | ConvertFrom-Json
            $validJsonProfile=([string]$stored.UiProfile -in @("Tech","Admin"))
            foreach ($key in @($settings.Keys)) {
                $property = $null
                try { $property = $stored.PSObject.Properties[$key] } catch { Write-DomeniaSwallowed 'Core' 'Load-DomeniaSettings' $_ }
                if ($null -eq $property) { continue }
                if ($null -eq $property.Value) { continue }
                $settings[$key] = $property.Value
            }
            # Domain-scoped preferences (database choice, health policies, approved BIOS references) live under a
            # closed name pattern outside the declared keys; ConvertTo-DomeniaExperienceSettings bounds them.
            foreach ($property in @($stored.PSObject.Properties)) {
                if (($settings.Contains($property.Name)) -or (-not (Test-DomeniaScopedSettingName ([string]$property.Name)))) { continue }
                if ($property.Value -is [string]) { $settings[$property.Name] = $property.Value }
            }
        }
    }
    catch { try { Write-AppLog "Reglages illisibles, valeurs par defaut appliquees : $($_.Exception.Message)" "WARN" } catch { Write-DomeniaSwallowed 'Core' 'Load-DomeniaSettings' $_ } }

    # Meme resolution que le login : le JSON valide prime sur Domenia.theme.cfg.
    # Ne jamais remplacer le choix de l utilisateur par le Light livre dans le ZIP. FO-22 : le choix (Auto compris).
    $settings["Theme"] = Get-DomeniaStoredTheme -Preference
    # Compatibilite avec l ancien fichier de profil d interface.
    try {
        $legacyProfile = Read-DomeniaPreference -FileName "Domenia.ui-profile.cfg"
        if (-not $validJsonProfile -and $legacyProfile -in @("Tech","Admin")) { $settings["UiProfile"] = $legacyProfile }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Load-DomeniaSettings' $_ }

    $settings = ConvertTo-DomeniaExperienceSettings -Values $settings -Defaults (Get-DomeniaDefaultSettings)
    $script:Settings = $settings
    $script:ThemePreference = [string]$settings["Theme"]
    # FO-22: the session paints the resolution of the choice (Auto: the Windows choice), as the login did.
    $script:CurrentTheme = Get-DomeniaStoredTheme
    $script:CurrentUiProfile = [string]$settings["UiProfile"]
    # UX-03: the presence filter always starts on « Toute présence », whatever an older settings file says.
    $script:CurrentPresenceFilter = "Tous"
    return $settings
}

function Save-DomeniaSettings {
    param([switch]$Immediate,[switch]$ThrowOnFailure)
    if ($null -eq $script:Settings) { return }
    if (-not $Immediate) {
        # Ecriture differee : un reglage modifie plusieurs fois de suite ne
        # provoque qu un seul acces disque.
        try {
            if ($null -eq $script:SettingsTimer) {
                # FI-05: protected timer of the engine heartbeat; it keeps running while the window is minimized.
                $script:SettingsTimer = New-DomeniaTimer -Owner 'Timer:Settings' -IntervalMs 1500 -RunWhenHidden -Tick {
                    param($sender,$eventArgs)
                    try { $sender.Stop() } catch { Write-DomeniaSwallowed 'Core' 'Save-DomeniaSettings' $_ }
                    Save-DomeniaSettings -Immediate
                }
            }
            $script:SettingsTimer.Stop()
            $script:SettingsTimer.Start()
            return
        }
        catch { Write-DomeniaSwallowed 'Core' 'Save-DomeniaSettings' $_ }
    }
    try { $script:SettingsTimer.Stop() } catch { Write-DomeniaSwallowed 'Core' 'Save-DomeniaSettings' $_ }
    try {
        $json = ([pscustomobject]$script:Settings) | ConvertTo-Json -Depth 4
        $written=Write-DomeniaPreference -FileName "Domenia.settings.json" -Value $json
        if(-not $written){throw 'Préférences non enregistrées. Vérifiez les droits du stockage et les journaux.'}
    }
    catch {
        try { Write-AppLog "Reglages non enregistres : $($_.Exception.Message)" "WARN" } catch { Write-DomeniaSwallowed 'Core' 'Save-DomeniaSettings' $_ }
        try { Set-Status ('Réglages non enregistrés : '+$_.Exception.Message) 'WARN' } catch { Write-DomeniaSwallowed 'Core' 'Save-DomeniaSettings' $_ }
        if($ThrowOnFailure){throw}
    }
}

function Get-DomeniaSetting {
    param([Parameter(Mandatory=$true)][string]$Name,$Default = $null)
    if ($null -eq $script:Settings) { return $Default }
    if (-not $script:Settings.Contains($Name)) { return $Default }
    $value = $script:Settings[$Name]
    if ($null -eq $value) { return $Default }
    return $value
}

function Set-DomeniaSetting {
    param([Parameter(Mandatory=$true)][string]$Name,$Value)
    if ($null -eq $script:Settings) { $script:Settings = Get-DomeniaDefaultSettings }
    $current = $null
    if ($script:Settings.Contains($Name)) { $current = $script:Settings[$Name] }
    # Case matters (a title or a layout differing only by case is a change).
    if ([string]$current -ceq [string]$Value) { return }
    $script:Settings[$Name] = $Value
    Save-DomeniaSettings
}

function Set-DomeniaComboByContent {
    param([Parameter(Mandatory=$true)][string]$Name,[AllowEmptyString()][string]$Content)
    if ([string]::IsNullOrWhiteSpace($Content)) { return $false }
    $combo = Get-DomeniaControl -Name $Name
    if ($null -eq $combo) { return $false }
    foreach ($item in @($combo.Items)) {
        if (([string]$item.Content) -eq $Content) { $combo.SelectedItem = $item; return $true }
    }
    return $false
}

function Set-DomeniaWindowActivationPolicy {
    # D089: after a voluntary Alt-Tab during the startup, a window opens without taking the foreground.
    # WPF refuses to show a maximized window that is not activated (InvalidOperationException in Show and
    # ShowDialog): a maximized window is therefore always shown activated. Returns the ShowActivated value.
    param($Window,[switch]$UserSwitchedAway)
    if ($null -eq $Window) { return $true }
    $maximized = $false
    try { $maximized = ($Window.WindowState -eq [System.Windows.WindowState]::Maximized) } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaWindowActivationPolicy' $_ }
    $activate = ((-not $UserSwitchedAway) -or $maximized)
    try { $Window.ShowActivated = $activate } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaWindowActivationPolicy' $_ }
    return $activate
}

function Restore-DomeniaWindowGeometry {
    # Une position enregistree sur un ecran desormais absent ne doit pas
    # rendre la fenetre invisible : elle est ignoree si elle sort du bureau.
    $window = $script:Window
    if ($null -eq $window) { return }
    try {
        if ([bool](Get-DomeniaSetting "WindowMaximized" $false)) {
            $window.WindowState = [System.Windows.WindowState]::Maximized
            return
        }
        $width = [double](Get-DomeniaSetting "WindowWidth" 0)
        $height = [double](Get-DomeniaSetting "WindowHeight" 0)
        $left = [double](Get-DomeniaSetting "WindowLeft" -1)
        $top = [double](Get-DomeniaSetting "WindowTop" -1)
        $virtualLeft = [System.Windows.SystemParameters]::VirtualScreenLeft
        $virtualTop = [System.Windows.SystemParameters]::VirtualScreenTop
        $virtualWidth = [System.Windows.SystemParameters]::VirtualScreenWidth
        $virtualHeight = [System.Windows.SystemParameters]::VirtualScreenHeight
        if ($width -ge $window.MinWidth -and $height -ge $window.MinHeight) {
            $window.Width = [Math]::Min($width,$virtualWidth)
            $window.Height = [Math]::Min($height,$virtualHeight)
        }
        if ($left -ge $virtualLeft -and $top -ge $virtualTop -and
            ($left + 120) -le ($virtualLeft + $virtualWidth) -and
            ($top + 60) -le ($virtualTop + $virtualHeight)) {
            $window.WindowStartupLocation = [System.Windows.WindowStartupLocation]::Manual
            $window.Left = $left
            $window.Top = $top
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Restore-DomeniaWindowGeometry' $_ }
}

function Save-DomeniaWindowGeometry {
    $window = $script:Window
    if ($null -eq $window) { return }
    try {
        $maximized = ($window.WindowState -eq [System.Windows.WindowState]::Maximized)
        Set-DomeniaSetting -Name "WindowMaximized" -Value $maximized
        if (-not $maximized -and $window.WindowState -eq [System.Windows.WindowState]::Normal) {
            Set-DomeniaSetting -Name "WindowWidth" -Value ([int]$window.Width)
            Set-DomeniaSetting -Name "WindowHeight" -Value ([int]$window.Height)
            Set-DomeniaSetting -Name "WindowLeft" -Value ([int]$window.Left)
            Set-DomeniaSetting -Name "WindowTop" -Value ([int]$window.Top)
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Save-DomeniaWindowGeometry' $_ }
}

function Restore-DomeniaUiSettings {
    # Applique les reglages enregistres aux controles, une fois l interface
    # construite. Les evenements sont neutralises le temps de la restauration
    # pour ne pas declencher de recherche ni de collecte.
    $script:RestoringSettings = $true
    try {
        # UX-03: the presence filter is never restored from a previous session.
        [void](Set-DomeniaComboByContent -Name "CmbPresenceFilter" -Content "Tous")
        # Le filtre de type ne doit jamais rester coince sur une valeur d une session precedente.
        # Chaque lancement repart volontairement sur Tous ; l operateur peut ensuite filtrer pour la session courante.
        [void](Set-DomeniaComboByContent -Name "CmbGlobalType" -Content "Tous")
        [void](Set-DomeniaComboByContent -Name "CmbSoftwareScope" -Content ([string](Get-DomeniaSetting "SoftwareScope" "Toutes")))
        [void](Set-DomeniaControlText -Name "TxtGlobalLimit" -Text ([string](Get-DomeniaSetting "SearchLimit" "100")))
        [void](Set-DomeniaControlText -Name "TxtWmiLimit" -Text ([string](Get-DomeniaSetting "WmiLimit" "25")))
        foreach ($pair in @(
            @{ Name="ChkSoftwarePerUser"; Key="SoftwarePerUser" },
            @{ Name="ChkSoftwareStore"; Key="SoftwareStore" },
            @{ Name="ChkSoftwareUpdates"; Key="SoftwareUpdates" },
            @{ Name="ChkParkSweepEnabled"; Key="ParkSweepEnabled" }
        )) {
            $control = Get-DomeniaControl -Name ([string]$pair.Name)
            if ($null -ne $control) { $control.IsChecked = [bool](Get-DomeniaSetting ([string]$pair.Key) $false) }
        }
        # UX-36 : un mot de passe remis par le support doit revenir change par son utilisateur.
        # Le reglage Security.ForcePasswordChangeOnReset laisse l operateur decider du contraire.
        $chkMustChange = Get-DomeniaControl -Name "ChkMustChangeAtLogon"
        if ($null -ne $chkMustChange) { $chkMustChange.IsChecked = [bool](Get-CfgValue "Security" "ForcePasswordChangeOnReset" $true) }
        $script:CurrentPresenceFilter = "Tous"
        $script:SoftwareScope = [string](Get-DomeniaSetting "SoftwareScope" "Toutes")
    }
    catch { try { Write-AppLog "Restauration des reglages partielle : $($_.Exception.Message)" "WARN" } catch { Write-DomeniaSwallowed 'Core' 'Restore-DomeniaUiSettings' $_ } }
    finally { $script:RestoringSettings = $false }
}

function Register-DomeniaSettingsWatchers {
    # Chaque controle de preference enregistre sa valeur des qu elle change.
    foreach ($pair in @(
        @{ Name="ChkSoftwarePerUser"; Key="SoftwarePerUser" },
        @{ Name="ChkSoftwareStore"; Key="SoftwareStore" },
        @{ Name="ChkSoftwareUpdates"; Key="SoftwareUpdates" }
    )) {
        $control = Get-DomeniaControl -Name ([string]$pair.Name)
        if ($null -eq $control) { continue }
        $key = [string]$pair.Key
        $handler = [scriptblock]::Create('if (-not $script:RestoringSettings) { $c = Get-DomeniaControl -Name "' + [string]$pair.Name + '"; if ($null -ne $c) { Set-DomeniaSetting -Name "' + $key + '" -Value ([bool]$c.IsChecked) } }')
        $control.Add_Checked($handler)
        $control.Add_Unchecked($handler)
    }
    foreach ($pair in @(
        @{ Name="TxtGlobalLimit"; Key="SearchLimit" },
        @{ Name="TxtWmiLimit"; Key="WmiLimit" }
    )) {
        $control = Get-DomeniaControl -Name ([string]$pair.Name)
        if ($null -eq $control) { continue }
        $control.Add_TextChanged([scriptblock]::Create('if (-not $script:RestoringSettings) { $c = Get-DomeniaControl -Name "' + [string]$pair.Name + '"; if ($null -ne $c) { Set-DomeniaSetting -Name "' + [string]$pair.Key + '" -Value ([string]$c.Text) } }'))
    }
    $workspace = Get-DomeniaControl -Name "WorkspaceTabs"
    if ($null -ne $workspace) {
        $workspace.Add_SelectionChanged({
            if ($script:RestoringSettings) { return }
            try {
                $tabs = Get-DomeniaControl -Name "WorkspaceTabs"
                if ($null -eq $tabs -or $null -eq $tabs.SelectedItem) { return }
                $name = [string]$tabs.SelectedItem.Name
                if (-not [string]::IsNullOrWhiteSpace($name)) { Set-DomeniaSetting -Name "Workspace" -Value $name }
            }
            catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaSettingsWatchers' $_ }
        })
    }
}


# =====================================================================
# Theme des fenetres d amorcage (R1.1).
# Le choix JSON valide prime sur l ancien .cfg, meme lorsque le choix est Light.
# Login, moniteur et fenetre principale partagent ce choix pour toute la session.
# Les fenetres d amorcage ont des ressources explicites pour les fonds, les
# textes, les champs, les boutons et les messages actualises apres creation.
# =====================================================================
function Get-DomeniaThemePreference {
    # FO-22: the stored choice, Light, Dark or Auto (follow Windows). Read once per session.
    # Un theme Light explicite est un choix valide, pas un signal de migration.
    # Core primitive: the report of a refused start-up (module missing, unreadable or not compiled) reads it before any
    # module is loaded, so the choice is recognised here, without ConvertTo-DomeniaThemePreference (same rule: case and
    # spaces ignored).
    if ($script:ThemePreference -in @("Light","Dark","Auto")) { return [string]$script:ThemePreference }
    $theme = ""
    try {
        $text = Read-DomeniaPreference -FileName "Domenia.settings.json"
        if (-not [string]::IsNullOrWhiteSpace($text)) {
            $stored = $text | ConvertFrom-Json -ErrorAction Stop
            $property = $stored.PSObject.Properties["Theme"]
            if ($null -ne $property) {
                $value = ([string]$property.Value).Trim()
                foreach ($known in @("Light","Dark","Auto")) { if ($value -ieq $known) { $theme = $known } }
            }
        }
    }
    catch { $theme = "" }
    # Domenia.theme.cfg (Light ou Dark) est consulte uniquement en l absence d un choix JSON valide.
    if (-not $theme) {
        $value = ""
        try { $value = ([string](Read-DomeniaPreference -FileName "Domenia.theme.cfg")).Trim() }
        catch { $value = "" }
        foreach ($known in @("Light","Dark")) { if ($value -ieq $known) { $theme = $known } }
    }
    $script:ThemePreference = if ($theme) { $theme } else { "Light" }
    return [string]$script:ThemePreference
}

function Get-DomeniaWindowsAppTheme {
    # FO-22: the Windows choice for applications (Parametres > Personnalisation > Couleurs), read in the user hive
    # only: HKCU\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize, AppsUseLightTheme (1 light, 0 dark).
    # Local read, no write, no network. '' when the value is absent (Windows before 1809) or unreadable.
    $key = $null
    try {
        $key = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Software\Microsoft\Windows\CurrentVersion\Themes\Personalize',$false)
        if ($null -eq $key) { return '' }
        $value = $key.GetValue('AppsUseLightTheme',$null)
        if ($null -eq $value) { return '' }
        if ([int]$value -eq 0) { return 'Dark' }
        return 'Light'
    }
    catch { return '' }
    finally { if ($null -ne $key) { $key.Close() } }
}

function Get-DomeniaStoredTheme {
    # Une source par session pour le login, le chargement et la principale : le theme peint (Light ou Dark).
    # FO-22: Auto prend le choix de Windows au moment de la lecture (Update-DomeniaAutoTheme le relit ensuite).
    # -Preference rend le choix enregistre lui-meme (Light, Dark ou Auto), pour les preferences.
    param([switch]$Preference)
    # Core primitive: the bootstrap depends on no module (report of a refused start-up). The rule of
    # Resolve-DomeniaEffectiveTheme is kept here: Light and Dark paint themselves, Auto paints the Windows choice, and
    # Light when Windows says nothing (Test-DomeniaTheme compares both).
    if ($Preference) { return (Get-DomeniaThemePreference) }
    if ($script:BootTheme -in @("Light","Dark")) { return [string]$script:BootTheme }
    $storedPreference = Get-DomeniaThemePreference
    $theme = "Light"
    if ($storedPreference -eq "Dark") { $theme = "Dark" }
    elseif (($storedPreference -eq "Auto") -and ((Get-DomeniaWindowsAppTheme) -eq "Dark")) { $theme = "Dark" }
    $script:BootTheme = $theme
    return [string]$script:BootTheme
}

function Get-DomeniaBootThemePalette {
    param([ValidateSet("Light","Dark")][string]$Theme = (Get-DomeniaStoredTheme))
    # CD-05: one palette. The login, the startup monitor and the fallback dialogs paint roles of SupportSuite.UI.json,
    # like the main window; every module, the presentation contract included, is loaded before the first of them. If
    # that contract cannot be read (damaged package), the colours of the Windows theme are used: readable in every
    # case, and never a second copy of the palette. FO-22: a Windows high contrast theme takes its system colours too.
    # Self-contained: tests extract it alone.
    $roles = [ordered]@{
        Window='WindowBg';Surface='BgCard';Input='BgInput';Text='TextColor';Muted='MutedColor';Border='BorderColor'
        Button='BtnBg';ButtonText='BtnFg';Accent='AccentColor';AccentHover='AccentHover';AccentText='AccentText';OnAccent='OnAccent'
        Error='StatusError';Warning='StatusWarning';Success='StatusSuccess'
    }
    $highContrast = $false
    try { $highContrast = [bool][System.Windows.SystemParameters]::HighContrast } catch { $highContrast = $false }
    $source = $null
    if (-not $highContrast) {
        try { $source = Get-SuitePalette -Theme $Theme } catch { $source = $null }
    }
    $palette = [ordered]@{}
    foreach ($role in @($roles.Keys)) {
        $token = [string]$roles[$role]
        $value = ''
        if (($null -ne $source) -and $source.Contains($token)) { $value = [string]$source[$token] }
        $palette[$role] = $value
    }
    if (@(@($palette.Values) | Where-Object { [string]$_ -notmatch '^#[0-9A-Fa-f]{6}$' }).Count -eq 0) { return $palette }
    $system = @{}
    foreach ($name in @('Window','WindowText','Control','ControlText','Highlight','HighlightText','HotTrack')) {
        $color = [System.Windows.SystemColors]::($name + 'Color')
        $system[$name] = ('#{0:X2}{1:X2}{2:X2}' -f $color.R,$color.G,$color.B)
    }
    return [ordered]@{
        Window=$system.Window;Surface=$system.Window;Input=$system.Window
        Text=$system.WindowText;Muted=$system.WindowText;Border=$system.WindowText
        Button=$system.Control;ButtonText=$system.ControlText
        Accent=$system.Highlight;AccentHover=$system.Highlight;AccentText=$system.HotTrack;OnAccent=$system.HighlightText
        Error=$system.WindowText;Warning=$system.WindowText;Success=$system.WindowText
    }
}

function Get-DomeniaBootStatusColor {
    param([ValidateSet("Text","Muted","AccentText","Error","Warning","Success")][string]$Kind = "Text")
    $palette = Get-DomeniaBootThemePalette
    return [string]$palette[$Kind]
}

function Get-DomeniaBootThemeResources {
    param([ValidateSet("Light","Dark")][string]$Theme = (Get-DomeniaStoredTheme))
    $palette = Get-DomeniaBootThemePalette -Theme $Theme
    $brushes = foreach ($entry in $palette.GetEnumerator()) {
        '    <SolidColorBrush x:Key="DomeniaBoot{0}" Color="{1}"/>' -f $entry.Key,$entry.Value
    }
    # Styles explicites : les styles systeme Windows ne doivent pas reinjecter
    # une police noire ou un bouton blanc au survol sur une surface sombre.
    $styles = @'
    <Style x:Key="DomeniaBootTextBoxBase" TargetType="TextBox">
      <Setter Property="Foreground" Value="{DynamicResource DomeniaBootText}"/>
      <Setter Property="Background" Value="{DynamicResource DomeniaBootInput}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource DomeniaBootBorder}"/>
      <Setter Property="CaretBrush" Value="{DynamicResource DomeniaBootText}"/>
      <Setter Property="SelectionBrush" Value="{DynamicResource DomeniaBootAccent}"/>
    </Style>
    <Style x:Key="DomeniaBootPasswordBoxBase" TargetType="PasswordBox">
      <Setter Property="Foreground" Value="{DynamicResource DomeniaBootText}"/>
      <Setter Property="Background" Value="{DynamicResource DomeniaBootInput}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource DomeniaBootBorder}"/>
      <Setter Property="CaretBrush" Value="{DynamicResource DomeniaBootText}"/>
      <Setter Property="SelectionBrush" Value="{DynamicResource DomeniaBootAccent}"/>
    </Style>
    <Style x:Key="DomeniaBootButtonBase" TargetType="Button">
      <Setter Property="Foreground" Value="{DynamicResource DomeniaBootButtonText}"/>
      <Setter Property="Background" Value="{DynamicResource DomeniaBootButton}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource DomeniaBootBorder}"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="HorizontalContentAlignment" Value="Center"/>
      <Setter Property="VerticalContentAlignment" Value="Center"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Border x:Name="BootButtonBorder" Background="{TemplateBinding Background}"
                    BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}"
                    CornerRadius="8" SnapsToDevicePixels="True">
              <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                VerticalAlignment="{TemplateBinding VerticalContentAlignment}"
                                Margin="{TemplateBinding Padding}" RecognizesAccessKey="True"
                                TextElement.Foreground="{TemplateBinding Foreground}"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="BootButtonBorder" Property="Background" Value="{Binding BorderBrush, RelativeSource={RelativeSource TemplatedParent}}"/></Trigger>
              <Trigger Property="IsPressed" Value="True"><Setter TargetName="BootButtonBorder" Property="Background" Value="{Binding BorderBrush, RelativeSource={RelativeSource TemplatedParent}}"/><Setter TargetName="BootButtonBorder" Property="BorderBrush" Value="{DynamicResource DomeniaBootAccentText}"/></Trigger>
              <Trigger Property="IsEnabled" Value="False"><Setter TargetName="BootButtonBorder" Property="Background" Value="{DynamicResource DomeniaBootInput}"/><Setter TargetName="BootButtonBorder" Property="BorderBrush" Value="{DynamicResource DomeniaBootBorder}"/><Setter Property="Foreground" Value="{DynamicResource DomeniaBootMuted}"/><Setter Property="Cursor" Value="Arrow"/></Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style TargetType="CheckBox">
      <Setter Property="Foreground" Value="{DynamicResource DomeniaBootText}"/>
    </Style>
    <Style TargetType="ToolTip">
      <Setter Property="Foreground" Value="{DynamicResource DomeniaBootText}"/>
      <Setter Property="Background" Value="{DynamicResource DomeniaBootSurface}"/>
      <Setter Property="BorderBrush" Value="{DynamicResource DomeniaBootBorder}"/>
      <Setter Property="Padding" Value="8"/>
    </Style>
'@
    return (($brushes -join "`r`n") + "`r`n" + $styles)
}

function Convert-DomeniaXamlToBootTheme {
    param(
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$Xaml,
        [ValidateSet("Light","Dark")][string]$Theme = (Get-DomeniaStoredTheme)
    )
    # Les quatre fenetres d amorcage utilisent les memes ressources nommees.
    # Aucun remplacement approximatif de couleur : Setter, champs et messages
    # partagent une palette explicite, y compris lorsque le theme est Light.
    $marker = "<Window.Resources>"
    if ([regex]::Matches($Xaml,[regex]::Escape($marker)).Count -ne 1) {
        throw "Fenetre d amorcage : un bloc Window.Resources unique est requis."
    }
    if ($Xaml.Contains('x:Key="DomeniaBootText"')) { return $Xaml }
    $resources = Get-DomeniaBootThemeResources -Theme $Theme
    return $Xaml.Replace($marker,($marker + "`r`n" + $resources))
}

function Load-DomeniaTheme {
    # The setting holds the choice (Light, Dark or Auto); the session paints its resolution (FO-22).
    $value = ConvertTo-DomeniaThemePreference ([string](Get-DomeniaSetting "Theme" "Light"))
    if ($value) {
        $script:ThemePreference = $value
        $windows = ''
        if ($value -eq 'Auto') { $windows = Get-DomeniaWindowsAppTheme }
        $script:CurrentTheme = [string](Resolve-DomeniaEffectiveTheme -Preference $value -WindowsTheme $windows).Theme
        $script:BootTheme = $script:CurrentTheme
    }
    return $script:CurrentTheme
}

function Save-DomeniaTheme {
    # $Theme: the choice to keep, Light, Dark or Auto (FO-22). The session theme becomes its resolution.
    param([ValidateSet("Light","Dark","Auto")][string]$Theme)
    $windows = ''
    if ($Theme -eq 'Auto') { $windows = Get-DomeniaWindowsAppTheme }
    $script:ThemePreference = $Theme
    $script:CurrentTheme = [string](Resolve-DomeniaEffectiveTheme -Preference $Theme -WindowsTheme $windows).Theme
    $script:BootTheme = $script:CurrentTheme
    # Charger les autres preferences avant une premiere sauvegarde isolee.
    if ($null -eq $script:Settings) { [void](Load-DomeniaSettings) }
    Set-DomeniaSetting -Name "Theme" -Value $Theme
    # Le choix doit survivre a une fermeture rapide, sans attendre le timer 1,5 s.
    Save-DomeniaSettings -Immediate -ThrowOnFailure
}

function Apply-DomeniaTheme {
    param(
        [ValidateSet("Light","Dark")][string]$Theme = $script:CurrentTheme,
        [switch]$Persist
    )

    $script:CurrentTheme = $Theme
    $script:BootTheme = $Theme

    try {
        [System.Windows.Window]$window = $script:Window
        if ($null -eq $window) {
            throw "Fenetre principale indisponible."
        }

        # CD-05: one palette. SupportSuite.UI.json paints every token, the window, the journal and the native popup
        # brushes (Set-DomeniaUxPalette); no colour table is kept here. DS-18: the title bar follows the theme.
        Set-DomeniaUxPalette -Window $window -Theme $Theme
        [void](Set-DomeniaWindowFrameTheme -Window $window -Theme $Theme)

        $button = Get-DomeniaControl -Name "BtnThemeToggle"
        if ($null -ne $button) {
            $button.IsEnabled = $true
            $button.IsHitTestVisible = $true
        }

        # Les etats de presence portent une couleur explicite : il faut la
        # recalculer, sinon ils gardent la teinte de l ancien theme.
        foreach ($presenceControl in @("TxtObjPresence","TxtCompPresence","TxtUserPresence")) {
            $current = Get-DomeniaControl -Name $presenceControl
            if ($null -eq $current) { continue }
            # FI-16: the key stored when the state was written, not a new reading of the label.
            $storedKey = ''
            if ($null -ne $script:PresenceTextStates -and $script:PresenceTextStates.ContainsKey($presenceControl)) { $storedKey = [string]$script:PresenceTextStates[$presenceControl] }
            try { Set-DomeniaControlForeground $current (Get-DomeniaPresenceColor -State ([string]$current.Text) -PresenceState $storedKey) } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaTheme' $_ }
        }

        # Restaurer l apparence au demarrage ne reecrit pas les preferences.
        if ($Persist) {
            try { Save-DomeniaTheme -Theme $Theme }
            catch {
                Set-Status "Thème appliqué mais non enregistré : vérifiez les droits du dossier de préférences." 'WARN'
                Set-DomeniaContextHint -Title 'Thème non enregistré' -Text 'Le changement reste visible pour cette session. Le dossier de préférences doit être accessible en écriture pour le conserver.'
            }
        }

        # DS-10 and FO-22: icon of the theme the button switches to, name and tool tip (choice or Automatique).
        Update-DomeniaUxThemeToggle

        # CD-05 / DS-14: chart colours are resolved from the painted palette when a widget is drawn; the boards
        # already drawn are drawn again from the data they hold (nothing read from the directory or the network), a
        # hidden one when it is shown.
        if ($null -ne (Get-Command -Name Update-DomeniaBoardsTheme -CommandType Function -ErrorAction SilentlyContinue)) { Update-DomeniaBoardsTheme }

        Add-DomeniaUiLog -Area "Theme" -Level "INFO" -Text (
            "Theme applique : {0}" -f $Theme
        )
    }
    catch {
        Write-AppLog (
            "Application du theme impossible : {0}" -f
            $_.Exception.Message
        ) "WARN"
    }
}


function Set-DomeniaThemePreference {
    # FO-22: explicit choice of the operator (menu of the theme button): Light, Dark or Auto (follow Windows). The
    # choice is saved, then its resolution painted. A failed save keeps the theme for this session and says so.
    param([Parameter(Mandatory=$true)][ValidateSet("Light","Dark","Auto")][string]$Preference)
    $saved = $true
    try { Save-DomeniaTheme -Theme $Preference }
    catch {
        $saved = $false
        $windows = ''
        if ($Preference -eq 'Auto') { $windows = Get-DomeniaWindowsAppTheme }
        $script:ThemePreference = $Preference
        $script:CurrentTheme = [string](Resolve-DomeniaEffectiveTheme -Preference $Preference -WindowsTheme $windows).Theme
        Set-Status "Thème appliqué mais non enregistré : vérifiez les droits du dossier de préférences." 'WARN'
    }
    Apply-DomeniaTheme -Theme $script:CurrentTheme
    if ($saved -and ($Preference -eq 'Auto')) { Set-Status ("Thème automatique : Domenia suit Windows (" + $(if ($script:CurrentTheme -eq 'Dark') { 'sombre' } else { 'clair' }) + ").") 'INFO' }
}

function Toggle-DomeniaTheme {
    if ($script:CurrentTheme -eq "Dark") {
        Apply-DomeniaTheme -Theme "Light" -Persist
    }
    else {
        Apply-DomeniaTheme -Theme "Dark" -Persist
    }
}

function Get-MainXaml {
    param([string]$WadRoot=$PSScriptRoot)
    # Versioned presentation, verified by the package manifest before the core starts.
    if([string]::IsNullOrWhiteSpace($WadRoot)){throw 'Dossier de la vue principale absent.'}
    $path=Join-Path $WadRoot 'Domenia-Main.xaml'
    if(-not [IO.File]::Exists($path)){throw ('Vue principale introuvable : '+$path)}
    $text=[IO.File]::ReadAllText($path,[Text.UTF8Encoding]::new($false,$true))
    if([string]::IsNullOrWhiteSpace($text)){throw 'Vue principale vide.'}
    return $text
}

function Assert-DomeniaXamlPreflight {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string]$XamlText,
        [string]$Context = "XAML"
    )

    if ([string]::IsNullOrWhiteSpace($XamlText)) {
        throw "$Context : contenu XAML vide."
    }

    try { [xml]$document = $XamlText }
    catch { throw "$Context : XML invalide : $($_.Exception.Message)" }

    if ($null -eq $document.DocumentElement -or $document.DocumentElement.LocalName -ne "Window") {
        throw "$Context : l élément racine doit être Window."
    }

    # Un Button WPF n accepte qu une seule source pour sa propriété Content.
    # Une combinaison Content="..." + enfant visuel, Button.Content + enfant implicite,
    # ou plusieurs enfants implicites déclenche au runtime :
    # "La propriété Content a déjà été définie sur Button".
    $buttonContentConflicts = New-Object System.Collections.Generic.List[string]
    foreach ($button in @($document.SelectNodes("//*[local-name()='Button']"))) {
        $buttonName = ""
        try { $buttonName = [string]$button.GetAttribute("Name","http://schemas.microsoft.com/winfx/2006/xaml") } catch { Write-DomeniaSwallowed 'Core' 'Assert-DomeniaXamlPreflight' $_ }
        if ([string]::IsNullOrWhiteSpace($buttonName)) { $buttonName = "<Button sans x:Name>" }

        $contentSources = 0
        if ($null -ne $button.Attributes["Content"]) { $contentSources++ }

        $explicitContent = 0
        $implicitElements = 0
        $hasLiteralText = $false
        foreach ($child in @($button.ChildNodes)) {
            if ($child.NodeType -eq [System.Xml.XmlNodeType]::Element) {
                if ([string]$child.LocalName -eq "Button.Content") { $explicitContent++ }
                elseif ([string]$child.LocalName -notmatch '^Button\.') { $implicitElements++ }
            }
            elseif (($child.NodeType -eq [System.Xml.XmlNodeType]::Text -or $child.NodeType -eq [System.Xml.XmlNodeType]::CDATA) -and -not [string]::IsNullOrWhiteSpace([string]$child.Value)) {
                $hasLiteralText = $true
            }
        }
        $contentSources += $explicitContent
        $contentSources += $implicitElements
        if ($hasLiteralText) { $contentSources++ }

        if ($contentSources -gt 1) {
            [void]$buttonContentConflicts.Add("$buttonName ($contentSources sources Content)")
        }
    }
    if ($buttonContentConflicts.Count -gt 0) {
        throw "$Context : contenu Button défini plusieurs fois : $($buttonContentConflicts -join ', '). Utilise soit Content=..., soit un unique Button.Content, jamais les deux."
    }

    # DataGridColumn dérive de DependencyObject, pas de FrameworkElement :
    # la propriété directe ToolTip n existe pas. Le ToolTip doit être porté
    # par un élément visuel placé dans DataGridColumn.Header.
    $columnXPath = "//*[local-name()='DataGridTextColumn' or local-name()='DataGridCheckBoxColumn' or local-name()='DataGridComboBoxColumn' or local-name()='DataGridHyperlinkColumn' or local-name()='DataGridTemplateColumn']"
    $invalidColumns = New-Object System.Collections.Generic.List[string]
    foreach ($column in @($document.SelectNodes($columnXPath))) {
        if ($null -ne $column.Attributes["ToolTip"]) {
            $header = [string]$column.GetAttribute("Header")
            if ([string]::IsNullOrWhiteSpace($header)) { $header = "<en-tête complexe>" }
            [void]$invalidColumns.Add("$($column.LocalName) '$header'")
        }
    }
    if ($invalidColumns.Count -gt 0) {
        throw "$Context : propriété ToolTip invalide sur $($invalidColumns -join ', '). Place le ToolTip sur un TextBlock dans DataGridColumn.Header."
    }

    # Sur le moteur XAML embarqué dans certains hôtes Windows PowerShell 5.1 / PS2EXE,
    # ComboBox.IsReadOnly peut être refusé au chargement malgré sa présence dans d autres
    # versions WPF. DOMENIA n en a pas besoin : une ComboBox non éditable utilise IsEditable=False.
    $invalidComboBoxReadOnly = @($document.SelectNodes("//*[local-name()='ComboBox' and @IsReadOnly]"))
    if ($invalidComboBoxReadOnly.Count -gt 0) {
        $invalidNames = @(
            foreach ($combo in $invalidComboBoxReadOnly) {
                $name = ""
                try { $name = [string]$combo.GetAttribute("Name","http://schemas.microsoft.com/winfx/2006/xaml") } catch { Write-DomeniaSwallowed 'Core' 'Assert-DomeniaXamlPreflight' $_ }
                if ([string]::IsNullOrWhiteSpace($name)) { $name = "<sans x:Name>" }
                $name
            }
        )
        throw "$Context : ComboBox.IsReadOnly incompatible avec cet hôte WPF : $($invalidNames -join ', '). Utilise IsEditable=False ou supprime la propriété."
    }

    # DataGrid.RowHeight est un Double. La chaîne "Auto" n est pas convertible par
    # XamlReader sous Windows PowerShell 5.1. Pour des lignes automatiques, il faut
    # laisser RowHeight non défini (valeur Double.NaN par défaut) et utiliser MinRowHeight.
    $invalidAutoRowHeights = New-Object System.Collections.Generic.List[string]
    foreach ($grid in @($document.SelectNodes("//*[local-name()='DataGrid' and @RowHeight]"))) {
        $rowHeightValue = [string]$grid.GetAttribute("RowHeight")
        if ([string]::Equals($rowHeightValue,"Auto",[System.StringComparison]::OrdinalIgnoreCase)) {
            $gridName = ""
            try { $gridName = [string]$grid.GetAttribute("Name","http://schemas.microsoft.com/winfx/2006/xaml") } catch { Write-DomeniaSwallowed 'Core' 'Assert-DomeniaXamlPreflight' $_ }
            if ([string]::IsNullOrWhiteSpace($gridName)) { $gridName = "<DataGrid sans x:Name>" }
            [void]$invalidAutoRowHeights.Add($gridName)
        }
    }
    foreach ($setter in @($document.SelectNodes("//*[local-name()='Setter' and @Property='RowHeight' and @Value]"))) {
        $setterValue = [string]$setter.GetAttribute("Value")
        if ([string]::Equals($setterValue,"Auto",[System.StringComparison]::OrdinalIgnoreCase)) {
            [void]$invalidAutoRowHeights.Add("Setter RowHeight")
        }
    }
    if ($invalidAutoRowHeights.Count -gt 0) {
        throw "$Context : RowHeight='Auto' est incompatible avec WPF/PowerShell 5.1 : $($invalidAutoRowHeights -join ', '). Supprime RowHeight et conserve MinRowHeight."
    }

    # Les doublons x:Name produisent des erreurs difficiles à diagnostiquer
    # lors du chargement WPF ou empêchent FindName de retrouver le bon contrôle.
    $xamlNamespace = "http://schemas.microsoft.com/winfx/2006/xaml"
    $seenNames = @{}
    $templateScopes = @{}
    $duplicateNames = New-Object System.Collections.Generic.List[string]
    foreach ($node in @($document.SelectNodes("//*"))) {
        $controlName = ""
        try { $controlName = [string]$node.GetAttribute("Name",$xamlNamespace) } catch { Write-DomeniaSwallowed 'Core' 'Assert-DomeniaXamlPreflight' $_ }
        if ([string]::IsNullOrWhiteSpace($controlName)) { continue }
        $scopeId = 'window'
        $ancestor = $node.ParentNode
        while ($null -ne $ancestor) {
            if ([string]$ancestor.LocalName -in @('ControlTemplate','DataTemplate','ItemsPanelTemplate')) {
                if (-not $templateScopes.ContainsKey($ancestor)) { $templateScopes[$ancestor]=[string]($templateScopes.Count+1) }
                $scopeId='template'+[string]$templateScopes[$ancestor]
                break
            }
            $ancestor=$ancestor.ParentNode
        }
        $scopedName=$scopeId+'|'+$controlName
        if ($seenNames.ContainsKey($scopedName)) { [void]$duplicateNames.Add($controlName) }
        else { $seenNames[$scopedName] = $true }
    }
    if ($duplicateNames.Count -gt 0) {
        throw "$Context : x:Name dupliqué(s) : $((@($duplicateNames | Select-Object -Unique)) -join ', ')."
    }
}

function Save-DomeniaXamlDiagnostic {
    [CmdletBinding()]
    param(
        [string]$Context,
        [string]$XamlText
    )
    try {
        Initialize-DomeniaDataStore | Out-Null
        $directory = Join-Path $script:DataDir "Diagnostics"
        if (-not (Test-Path -LiteralPath $directory -PathType Container)) {
            [void](New-Item -ItemType Directory -Path $directory -Force)
        }
        $safeContext = (($Context + "XAML") -replace "[^A-Za-z0-9_-]", "-")
        if ($safeContext.Length -gt 48) { $safeContext = $safeContext.Substring(0,48) }
        $fileName = "Domenia-XAML-{0}-{1}-{2}.xaml" -f $safeContext,(Get-Date).ToString("yyyyMMdd-HHmmss-fff"),([guid]::NewGuid().ToString("N").Substring(0,8))
        $path = Join-Path $directory $fileName
        [System.IO.File]::WriteAllText($path,[string]$XamlText,(New-Object System.Text.UTF8Encoding($true)))
        return $path
    }
    catch { return "" }
}

function ConvertFrom-DomeniaXaml {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string]$XamlText,
        [string]$Context = "Fenetre WPF"
    )

    $reader = $null
    try {
        Assert-DomeniaXamlPreflight -XamlText $XamlText -Context $Context
        [xml]$xaml = $XamlText
        $reader = New-Object -TypeName System.Xml.XmlNodeReader -ArgumentList $xaml
        $window = [Windows.Markup.XamlReader]::Load($reader)
        if ($null -eq $window) { throw "$Context : XamlReader.Load a retourne une fenetre vide." }
        if ($null -ne (Get-Command Initialize-DomeniaUxWindowHelp -ErrorAction SilentlyContinue)) {
            Initialize-DomeniaUxWindowHelp -Window $window -XamlText $XamlText
        }
        # DS-18: login, startup monitor and other windows take the dark title bar of the session theme.
        if (($window -is [System.Windows.Window]) -and ($null -ne (Get-Command Set-DomeniaWindowFrameTheme -ErrorAction SilentlyContinue))) {
            [void](Set-DomeniaWindowFrameTheme -Window $window)
        }
        return $window
    }
    catch {
        $sourceError = $_.Exception
        $diagnosticPath = Save-DomeniaXamlDiagnostic -Context $Context -XamlText $XamlText
        $suffix = if ([string]::IsNullOrWhiteSpace($diagnosticPath)) { "" } else { " XAML sauvegarde dans : $diagnosticPath" }
        $message = "$Context : chargement impossible. $($sourceError.Message)$suffix"
        throw (New-Object System.InvalidOperationException -ArgumentList @($message,$sourceError))
    }
    finally {
        if ($null -ne $reader) { try { $reader.Close() } catch { Write-DomeniaSwallowed 'Core' 'ConvertFrom-DomeniaXaml' $_ } }
    }
}

function Test-DomeniaXamlRuntimeCompatibility {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string]$XamlText,
        [Parameter(Mandatory=$true)][string]$Context
    )

    $probeWindow = $null
    try {
        # Contrairement a la simple conversion XML, ceci demande au moteur WPF reel
        # de resoudre chaque type et chaque membre XAML. Le test est execute avant le login.
        $probeWindow = ConvertFrom-DomeniaXaml -XamlText $XamlText -Context "$Context (prechargement WPF)"
        if ($null -eq $probeWindow) { throw "$Context : le moteur WPF a retourne une fenetre vide." }
        return $true
    }
    finally {
        if ($null -ne $probeWindow) {
            try { $probeWindow.Close() } catch { Write-DomeniaSwallowed 'Core' 'Test-DomeniaXamlRuntimeCompatibility' $_ }
            try { $probeWindow = $null } catch { Write-DomeniaSwallowed 'Core' 'Test-DomeniaXamlRuntimeCompatibility' $_ }
        }
    }
}

function Get-DomeniaXamlControlNames {
    # Extrait tous les x:Name declares dans un XAML.
    # Sert a garantir qu aucun controle de l interface ne reste invisible au code.
    param([Parameter(Mandatory=$true)][AllowEmptyString()][string]$XamlText)
    $names = New-Object System.Collections.Generic.List[string]
    try {
        foreach ($match in [regex]::Matches($XamlText,'x:Name\s*=\s*"([^"]+)"')) {
            $candidate = [string]$match.Groups[1].Value
            if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
            if ($names.Contains($candidate)) { continue }
            [void]$names.Add($candidate)
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaXamlControlNames' $_ }
    return $names.ToArray()
}

function Load-XamlWindow {
    $xamlText = [string](Get-MainXaml)
    $script:Window = ConvertFrom-DomeniaXaml -XamlText $xamlText -Context "Interface principale"
    Set-AppWindowIcon $script:Window
    $script:Ctrl = @{}

    # Collecte automatique de tous les x:Name du XAML principal.
    # Remplace l ancienne liste manuelle : tout controle ajoute a l interface
    # est desormais accessible au code sans edition d une seconde liste.
    # Les noms internes aux ControlTemplate (ex. "Bd") ne sont pas resolus par
    # FindName au niveau fenetre et sont simplement ignores.
    $declaredNames = @(Get-DomeniaXamlControlNames -XamlText $xamlText)
    foreach ($name in $declaredNames) {
        $c = $null
        try { $c = $script:Window.FindName($name) } catch { Write-DomeniaSwallowed 'Core' 'Load-XamlWindow' $_ }
        if ($null -ne $c) { $script:Ctrl[$name] = $c }
    }
    try {
        Write-StartupTrace -Stage "Chargement interface WPF" -Status "OK" -Detail (
            "Controles WPF resolus : {0}/{1}." -f $script:Ctrl.Count,$declaredNames.Count
        )
    }
    catch { Write-DomeniaSwallowed 'Core' 'Load-XamlWindow' $_ }

    $missingCriticalControls = @(
        Get-DomeniaCriticalControlNames | Where-Object { -not $script:Ctrl.ContainsKey([string]$_) }
    )
    if ($missingCriticalControls.Count -gt 0) {
        throw "Interface principale : controle(s) WPF critique(s) introuvable(s) : $($missingCriticalControls -join ', ')."
    }
    # Appliquer le choix du login avant le premier affichage de la principale.
    Apply-DomeniaTheme -Theme (Get-DomeniaStoredTheme)
    try { Update-DomeniaWriteModeVisual } catch { Write-DomeniaSwallowed 'Core' 'Load-XamlWindow' $_ }
    Apply-DomeniaGuiElementPolicy
}

function Apply-DomeniaGuiElementPolicy {
    [CmdletBinding()]
    param(
        [System.Windows.Window]$Window = $script:Window,
        [hashtable]$ControlMap = $script:Ctrl
    )

    if ($null -eq $script:GuiElementPolicy) { return }
    foreach ($name in @($script:GuiElementPolicy.Keys)) {
        $mode = [string]$script:GuiElementPolicy[$name]
        if ([string]::IsNullOrWhiteSpace($mode) -or $mode -ieq 'Default') { continue }
        $control = $null
        try { if ($null -ne $ControlMap -and $ControlMap.ContainsKey($name)) { $control = $ControlMap[$name] } } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaGuiElementPolicy' $_ }
        if ($null -eq $control -and $null -ne $Window) { try { $control = $Window.FindName($name) } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaGuiElementPolicy' $_ } }
        if ($null -eq $control) { continue }
        switch -Regex ($mode.Trim()) {
            '^(Hidden|Hide|Collapsed|Masque|Masque)$' {
                try { $control.Visibility = [System.Windows.Visibility]::Collapsed } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaGuiElementPolicy' $_ }
                try { $control.IsEnabled = $false } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaGuiElementPolicy' $_ }
            }
            '^(Disabled|Disable|Grayed|Greyed|Grise|Grise)$' {
                try { $control.Visibility = [System.Windows.Visibility]::Visible } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaGuiElementPolicy' $_ }
                try { $control.IsEnabled = $false } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaGuiElementPolicy' $_ }
                try { $control.ToolTip = "Fonction desactivee dans la configuration de l application." } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaGuiElementPolicy' $_ }
            }
            '^(Visible|Enabled|Show)$' {
                try { $control.Visibility = [System.Windows.Visibility]::Visible } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaGuiElementPolicy' $_ }
                # Ne force pas IsEnabled=True : les droits AD et le mode lecture seule restent prioritaires.
            }
            default {
                try { Write-AppLog "Valeur GuiElementPolicy inconnue pour '$name' : '$mode'." 'WARN' } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaGuiElementPolicy' $_ }
            }
        }
    }
}

function Set-TabVisibility {
    param([string]$Name, [bool]$Visible)
    if (-not $script:Ctrl.ContainsKey($Name)) { return }
    $script:Ctrl[$Name].Visibility = if ($Visible) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
}



function Get-DomeniaTreeHeaderTemplate {
    # FO-04: the header of a branch shows its text and, on hover, a star to pin it; the star stays filled for a
    # favourite (AutomationProperties.ItemStatus = 'Favori'). The Header itself remains the plain branch text.
    if ($null -ne $script:TreeHeaderTemplate) { return $script:TreeHeaderTemplate }
    $xaml = @'
<DataTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <StackPanel x:Name="HeaderRoot" Orientation="Horizontal" Background="Transparent">
    <TextBlock Text="{Binding}" VerticalAlignment="Center"/>
    <Button x:Name="OuStar" Content="☆" Visibility="Hidden" Focusable="False" Margin="6,0,0,0" MinWidth="0" MinHeight="0" Cursor="Hand" FontFamily="Segoe UI Symbol" FontSize="{DynamicResource FontSizeBody}" Foreground="{DynamicResource AccentText}" ToolTip="Épingler cette OU dans les favoris" AutomationProperties.Name="Épingler cette OU">
      <Button.Template><ControlTemplate TargetType="Button"><Border Background="Transparent" Padding="2,0"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Border></ControlTemplate></Button.Template>
    </Button>
  </StackPanel>
  <DataTemplate.Triggers>
    <Trigger SourceName="HeaderRoot" Property="UIElement.IsMouseOver" Value="True"><Setter TargetName="OuStar" Property="UIElement.Visibility" Value="Visible"/></Trigger>
    <DataTrigger Binding="{Binding Path=(AutomationProperties.ItemStatus), RelativeSource={RelativeSource AncestorType=TreeViewItem}}" Value="Favori">
      <Setter TargetName="OuStar" Property="Visibility" Value="Visible"/>
      <Setter TargetName="OuStar" Property="Content" Value="★"/>
      <Setter TargetName="OuStar" Property="ToolTip" Value="Retirer cette OU des favoris"/>
    </DataTrigger>
  </DataTemplate.Triggers>
</DataTemplate>
'@
    $script:TreeHeaderTemplate = [Windows.Markup.XamlReader]::Parse($xaml)
    return $script:TreeHeaderTemplate
}

function New-TreeItem {
    param([string]$Name, [string]$Dn, [string]$Kind)
    $item = New-Object System.Windows.Controls.TreeViewItem
    $item.Header = $Name
    $item.Tag = [pscustomobject]@{ Name = $Name; DN = $Dn; Kind = $Kind; Loaded = $false; RenderId = ""; Loading = $false }
    try { $item.HeaderTemplate = Get-DomeniaTreeHeaderTemplate } catch { Write-DomeniaSwallowed 'Core' 'New-TreeItem' $_ }
    if (-not [string]::IsNullOrWhiteSpace($Dn) -and $null -ne $script:OuFavouriteKeys -and $script:OuFavouriteKeys.ContainsKey($Dn.ToLowerInvariant())) {
        [Windows.Automation.AutomationProperties]::SetItemStatus($item,'Favori')
    }
    [void]$item.Items.Add("Chargement...")
    $item.Add_Expanded({ param($sender,$e) if ($e.OriginalSource -eq $sender) { Load-TreeChildren -Node $sender } })
    $item.Add_Selected({ param($sender,$e) if ($e.OriginalSource -eq $sender) { Set-SelectedBranch -Node $sender; $e.Handled = $true } })
    return $item
}

function New-DomeniaTreeRowItem {
    # One branch returned by TreeChildren. UI-16: TreeChildren reads one level only (no probe per sub-branch); the
    # chevron of a branch without sub-branch falls once that branch is read (Queue-DomeniaTreeRowsToNode).
    param($Row)
    if ($null -eq $Row) { return $null }
    $dn = [string]$Row.DN
    if ([string]::IsNullOrWhiteSpace($dn)) { return $null }
    $prefix = if ([string]$Row.Kind -eq "OU") { "OU" } else { "CN" }
    return (New-TreeItem -Name "$prefix  $([string]$Row.Name)" -Dn $dn -Kind ([string]$Row.Kind))
}

function New-DomeniaTreeSystemGroup {
    # UI-16: System, Program Data, ForeignSecurityPrincipals, LostAndFound... folded under one node. The group has
    # no DN: selecting it never becomes a search root, and unfolding it reads nothing.
    param($Rows)
    $rowArray = @($Rows | Where-Object { $null -ne $_ })
    $group = New-Object System.Windows.Controls.TreeViewItem
    $group.Header = 'Conteneurs système (' + $rowArray.Count + ')'
    $group.Tag = [pscustomobject]@{ Name = 'Conteneurs système'; DN = ''; Kind = 'SystemGroup'; Loaded = $true; RenderId = ""; Loading = $false }
    $group.IsExpanded = $false
    $group.ToolTip = 'Conteneurs créés par Active Directory (System, Program Data, ForeignSecurityPrincipals, LostAndFound…), repliés ici. Users et Computers restent visibles. Déplier ce groupe ne lance aucune lecture.'
    foreach ($row in $rowArray) {
        $child = New-DomeniaTreeRowItem -Row $row
        if ($null -ne $child) { [void]$group.Items.Add($child) }
    }
    return $group
}

function Get-DomeniaTreeRenderRows {
    # UI-16: under the domain root, the system containers become one trailing group entry; elsewhere rows are kept.
    # The rows are written to the pipeline: callers collect them with @().
    param($Node,$Rows)
    $rowArray = @($Rows | Where-Object { $null -ne $_ })
    $parentDn = ''
    try { $parentDn = [string]$Node.Tag.DN } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaTreeRenderRows' $_ }
    if ([string]::IsNullOrWhiteSpace($parentDn) -or [string]::IsNullOrWhiteSpace([string]$script:Conn.BaseDn) -or $parentDn -ine [string]$script:Conn.BaseDn) { return $rowArray }
    $split = Split-DomeniaTreeRows -Rows $rowArray -ParentDn $parentDn -DomainDn ([string]$script:Conn.BaseDn)
    $out = New-Object System.Collections.Generic.List[object]
    foreach ($row in @($split.Visible)) { $out.Add($row) }
    if (@($split.System).Count -gt 0) { $out.Add([pscustomobject]@{ Kind = 'SystemGroup'; Rows = @($split.System); DN = '' }) }
    return $out.ToArray()
}

function New-DomeniaTreeLoadingItem {
    # UI-16: a small turning wheel under the unfolded branch replaces the former greyed node while it is read.
    $panel = New-Object System.Windows.Controls.StackPanel
    $panel.Orientation = [System.Windows.Controls.Orientation]::Horizontal
    $panel.Tag = 'Loading'
    $wheel = New-Object System.Windows.Controls.TextBlock
    $wheel.Text = [string][char]0x21BB
    $wheel.FontFamily = New-Object System.Windows.Media.FontFamily('Segoe UI Symbol')
    $wheel.Margin = New-Object System.Windows.Thickness(0,0,6,0)
    $wheel.RenderTransformOrigin = New-Object System.Windows.Point(0.5,0.5)
    $rotate = New-Object System.Windows.Media.RotateTransform
    $wheel.RenderTransform = $rotate
    try {
        $spin = New-Object System.Windows.Media.Animation.DoubleAnimation(0.0,360.0,(New-Object System.Windows.Duration([TimeSpan]::FromSeconds(1.2))))
        $spin.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        $rotate.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty,$spin)
    } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaTreeLoadingItem' $_ }
    $text = New-Object System.Windows.Controls.TextBlock
    $text.Text = 'Chargement des sous-branches' + [string][char]0x2026
    [void]$panel.Children.Add($wheel)
    [void]$panel.Children.Add($text)
    [System.Windows.Automation.AutomationProperties]::SetName($panel,'Chargement des sous-branches')
    return $panel
}

function Add-DomeniaTreeRowsToNode {
    # Synchronous insertion of a small set of rows. Large branches go through Queue-DomeniaTreeRowsToNode (render timer):
    # no nested message pump here (FI-20).
    param($Node,$Rows)
    if ($null -eq $Node) { return 0 }
    $count = 0
    foreach ($row in @(Get-DomeniaTreeRenderRows -Node $Node -Rows $Rows)) {
        if ($null -eq $row) { continue }
        if ([string]$row.Kind -eq 'SystemGroup') { [void]$Node.Items.Add((New-DomeniaTreeSystemGroup -Rows $row.Rows)); $count += @($row.Rows).Count; continue }
        $item = New-DomeniaTreeRowItem -Row $row
        if ($null -eq $item) { continue }
        [void]$Node.Items.Add($item)
        $count++
    }
    return $count
}

function Initialize-DomeniaTreeRenderTimer {
    if ($null -ne $script:TreeRenderTimer) { return }
    # FI-05: protected timer of the engine heartbeat; it only runs while a branch is being rendered.
    $script:TreeRenderTimer = New-DomeniaTimer -Owner 'Timer:TreeRender' -IntervalMs ([Math]::Max(10,[int](Get-CfgValue "UI" "TreeRenderIntervalMs" 18))) -Tick {
        $finished = New-Object System.Collections.Generic.List[string]
        foreach ($renderId in @($script:TreeRenderJobs.Keys)) {
            $job = $script:TreeRenderJobs[$renderId]
            if ($null -eq $job -or $null -eq $job.Node) { [void]$finished.Add([string]$renderId); continue }
            try {
                $batchSize = [Math]::Max(5,[int]$job.BatchSize)
                $added = 0
                while ([int]$job.Index -lt [int]$job.Rows.Count -and $added -lt $batchSize) {
                    $row = $job.Rows[[int]$job.Index]
                    $job.Index = [int]$job.Index + 1
                    if ($null -eq $row) { continue }
                    if ([string]$row.Kind -eq 'SystemGroup') {
                        [void]$job.Node.Items.Add((New-DomeniaTreeSystemGroup -Rows $row.Rows))
                        $job.Added = [int]$job.Added + @($row.Rows).Count
                        $added++
                        continue
                    }
                    $item = New-DomeniaTreeRowItem -Row $row
                    if ($null -eq $item) { continue }
                    [void]$job.Node.Items.Add($item)
                    $job.Added = [int]$job.Added + 1
                    $added++
                }
                if ([int]$job.Index -ge [int]$job.Rows.Count) {
                    $job.Node.Tag.Loaded = $true
                    $job.Node.Tag.RenderId = ""
                    $job.Node.IsEnabled = $true
                    [void]$finished.Add([string]$renderId)
                    [void](Set-DomeniaControlText -Name "LblTreeStatus" -Text "$($job.Added) sous-branche(s) affichee(s).")
                    Set-Status "Sous-branches pretes : $($job.Added)."
                    # DS-07: a branch read while the OU filter is set follows that filter (local only). PF-10: no command lookup in a tick.
                    try { Update-DomeniaOuTreeFilter -OnlyWhenActive } catch { Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaTreeRenderTimer' $_ }
                }
                else {
                    [void](Set-DomeniaControlText -Name "LblTreeStatus" -Text "Affichage progressif : $($job.Added) / $($job.Rows.Count) sous-branche(s)...")
                }
            }
            catch {
                try {
                    $job.Node.Items.Clear()
                    [void]$job.Node.Items.Add("Erreur d'affichage  replie puis redeplie pour reessayer")
                    $job.Node.Tag.Loaded = $false
                    $job.Node.Tag.RenderId = ""
                    $job.Node.IsEnabled = $true
                } catch { Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaTreeRenderTimer' $_ }
                Write-AppLog "Affichage progressif de l'arborescence : $($_.Exception.ToString())" "ERROR"
                [void]$finished.Add([string]$renderId)
            }
        }
        foreach ($renderId in $finished.ToArray()) { [void]$script:TreeRenderJobs.Remove([string]$renderId) }
        if (@($script:TreeRenderJobs.Keys).Count -eq 0) { try { $script:TreeRenderTimer.Stop() } catch { Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaTreeRenderTimer' $_ } }
    }
}

function Stop-DomeniaTreeRenderForNode {
    param($Node)
    if ($null -eq $Node) { return }
    foreach ($renderId in @($script:TreeRenderJobs.Keys)) {
        $job = $script:TreeRenderJobs[$renderId]
        if ($null -ne $job -and [object]::ReferenceEquals($job.Node,$Node)) { [void]$script:TreeRenderJobs.Remove([string]$renderId) }
    }
    try { $Node.Tag.RenderId = "" } catch { Write-DomeniaSwallowed 'Core' 'Stop-DomeniaTreeRenderForNode' $_ }
    if (@($script:TreeRenderJobs.Keys).Count -eq 0 -and $null -ne $script:TreeRenderTimer) { try { $script:TreeRenderTimer.Stop() } catch { Write-DomeniaSwallowed 'Core' 'Stop-DomeniaTreeRenderForNode' $_ } }
}

function Clear-DomeniaTreeRenderJobs {
    foreach ($renderId in @($script:TreeRenderJobs.Keys)) {
        $job = $script:TreeRenderJobs[$renderId]
        try { if ($null -ne $job.Node) { $job.Node.Tag.RenderId=""; $job.Node.IsEnabled=$true } } catch { Write-DomeniaSwallowed 'Core' 'Clear-DomeniaTreeRenderJobs' $_ }
    }
    $script:TreeRenderJobs.Clear()
    try { if ($null -ne $script:TreeRenderTimer) { $script:TreeRenderTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Clear-DomeniaTreeRenderJobs' $_ }
}

function Queue-DomeniaTreeRowsToNode {
    param($Node,$Rows,[string]$DisplayName="branche")
    if ($null -eq $Node) { throw "Nud d'arborescence absent." }
    Stop-DomeniaTreeRenderForNode -Node $Node
    $Node.Items.Clear()
    try { $Node.Tag | Add-Member -NotePropertyName Loading -NotePropertyValue $false -Force } catch { Write-DomeniaSwallowed 'Core' 'Queue-DomeniaTreeRowsToNode' $_ }
    $rowArray = @(Get-DomeniaTreeRenderRows -Node $Node -Rows $Rows)
    if ($rowArray.Count -eq 0) {
        # UI-16: read and without sub-branch: no item, hence no chevron.
        $Node.Tag.Loaded = $true
        $Node.Tag.RenderId = ""
        $Node.IsEnabled = $true
        [void](Set-DomeniaControlText -Name "LblTreeStatus" -Text "Aucune sous-branche dans $DisplayName.")
        Set-Status "Aucune sous-branche dans $DisplayName."
        return
    }
    $renderId = "tree-render:" + [guid]::NewGuid().ToString("N")
    $Node.Tag.Loaded = $false
    $Node.Tag.RenderId = $renderId
    # UI-16: the node stays enabled while its sub-branches appear (no greyed branch).
    $script:TreeRenderJobs[$renderId] = [pscustomobject]@{
        Id=$renderId; Node=$Node; Rows=$rowArray; Index=0; Added=0
        BatchSize=[Math]::Max(5,[int](Get-CfgValue "UI" "TreeRenderBatchSize" 24))
        DisplayName=$DisplayName
    }
    Initialize-DomeniaTreeRenderTimer
    $script:TreeRenderTimer.Start()
    [void](Set-DomeniaControlText -Name "LblTreeStatus" -Text "$($rowArray.Count) sous-branche(s) recue(s) ; affichage progressif...")
}

function Load-TreeRoot {
    param([switch]$ForceRefresh)
    try {
        $tree = Get-DomeniaControl -Name "TvDirectory"
        if ($null -eq $tree) { throw "Controle d'arborescence introuvable." }
        Clear-DomeniaTreeRenderJobs
        if ($ForceRefresh -and $tree.Items.Count -gt 0) {
            $existingRoot = $tree.Items[0]
            try {
                if ($null -ne $existingRoot -and [string]$existingRoot.Tag.DN -ieq [string]$script:Conn.BaseDn) {
                    Load-TreeChildren -Node $existingRoot -PreserveExisting -Force
                    $existingRoot.IsExpanded = $true
                    [void](Set-DomeniaControlText -Name "LblTreeStatus" -Text "Actualisation de l arborescence en arriere-plan...")
                    Set-Status "Actualisation de lʼarborescence en cours. Lʼarbre actuel reste affiché tant que la nouvelle lecture nʼest pas validée."
                    return
                }
            }
            catch { Write-DomeniaSwallowed 'Core' 'Load-TreeRoot' $_ }
        }
        $tree.Items.Clear()
        $rootName = if ($script:Conn.Domain) { $script:Conn.Domain } else { $script:Conn.BaseDn }
        $root = New-TreeItem -Name $rootName -Dn $script:Conn.BaseDn -Kind "domainDNS"
        [void]$tree.Items.Add($root)
        $script:SelectedBranchDn = $script:Conn.BaseDn
        [void](Set-DomeniaControlText -Name "TxtBranchDn" -Text $script:SelectedBranchDn)
        $script:SuppressBranchAutoLoad = $true
        try { $root.IsSelected = $true } finally { $script:SuppressBranchAutoLoad = $false }

        # Startup uses the same AD -> SQLite -> tree path as an explicit branch read.
        # An old StartupWarmCache contains no committed receipt and cannot render business data.
            $mustLoad = [bool]$ForceRefresh -or [bool](Get-CfgValue "Browser" "ForceFirstLevelAtStartup" $true) -or ((-not [bool](Get-CfgValue "Browser" "FastBoot" $false)) -and [bool](Get-CfgValue "Browser" "LoadFirstLevelOnStartup" $true))
            if ($mustLoad) {
                Load-TreeChildren -Node $root
                $root.IsExpanded = $true
            }
            [void](Set-DomeniaControlText -Name "LblTreeStatus" -Text "Arbre initialise. Chargement des sous-branches en arriere-plan.")
            [void](Set-DomeniaControlText -Name "LblBranchCount" -Text "Aucune branche chargee")
        # FO-04: the favourites pinned above the tree belong to the domain of this session.
        if ($null -ne (Get-Command Update-DomeniaOuFavouritesUi -CommandType Function -ErrorAction SilentlyContinue)) {
            try { Update-DomeniaOuFavouritesUi } catch { Write-AppLog "Favoris d OU : $($_.Exception.Message)" "WARN" }
        }
        Update-Dashboard
    }
    catch {
        [void](Set-DomeniaControlText -Name "LblTreeStatus" -Text "Erreur arbre : $($_.Exception.Message)")
        Write-AppLog "Erreur arbre : $($_.Exception.Message)" "ERROR"
        if (-not $ForceRefresh) { throw }
    }
}


function Set-SelectedBranch {
    param($Node)
    if ($null -eq $Node -or $null -eq $Node.Tag -or [string]::IsNullOrWhiteSpace([string]$Node.Tag.DN)) { return }
    $script:SelectedBranchDn = [string]$Node.Tag.DN
    Update-DomeniaSearchScopeUi
    Update-Dashboard
    if ($script:SuppressBranchAutoLoad) { return }
    Stop-DomeniaFavouriteTreeReveal
    [void](Set-DomeniaControlText -Name 'TxtBranchSearch' -Text '')
    # PF-14: a keyboard walk in the tree waits for its last stop (300 ms); a mouse click reads at once.
    if ($null -ne (Get-Command Request-DomeniaSearchFilterChanged -CommandType Function -ErrorAction SilentlyContinue)) {
        $source = 'Mouse'
        if ($null -ne (Get-Command Get-DomeniaTreeSelectionSource -CommandType Function -ErrorAction SilentlyContinue)) { $source = Get-DomeniaTreeSelectionSource }
        Request-DomeniaSearchFilterChanged -Source $source
        return
    }
    Invoke-DomeniaSearchFilterChanged
}

function Get-DomeniaSearchMode {
    # An upper-bar request and OU browsing are separate query contexts.
    if ([string]$script:SearchMode -eq 'Global') { return 'Global' }
    return 'OU'
}

function Get-DomeniaSearchText {
    param([ValidateSet('Global','OU')][string]$Mode = (Get-DomeniaSearchMode))
    $name = if ($Mode -eq 'Global') { 'TxtGlobalSearch' } else { 'TxtBranchSearch' }
    $box = Get-DomeniaControl -Name $name
    if ($null -eq $box) { return '' }
    return ([string]$box.Text).Trim()
}

function Set-DomeniaSearchMode {
    param([ValidateSet('Global','OU')][string]$Mode)
    $script:SearchMode = $Mode
    # The ancestor style disables only OU/local filters. Child security locks remain authoritative.
    $layout = Get-DomeniaControl -Name 'SearchBrowserLayout'
    if ($null -ne $layout) { $layout.Tag = $Mode }
}

function Get-DomeniaSearchScope {
    # -IgnoreBar: a work view reads the perimeter of its own « Dans : » chip; the chip of the upper bar never narrows it.
    param([ValidateSet('Global','OU')][string]$Mode = (Get-DomeniaSearchMode),[switch]$IgnoreBar)
    $domainDn = ([string]$script:Conn.BaseDn).Trim()
    if ([string]::IsNullOrWhiteSpace($domainDn)) { throw 'Recherche impossible : aucune base AD de session.' }
    if ($Mode -eq 'Global') {
        # FO-05: the chip of the upper bar may narrow the search, explicitly, to the OU chosen in the tree (sub-OU included).
        if ((-not $IgnoreBar) -and ([string]$script:SearchBarScope -eq 'Ou')) {
            $bar = Get-DomeniaSearchBarScope -Choice Ou -OuDn ([string]$script:SelectedBranchDn) -DomainDn $domainDn
            if ([bool]$bar.Explicit) { return [pscustomobject]@{ BaseDn=[string]$bar.BaseDn; Scope='Subtree'; IsDomain=$false; Mode='Global'; Explicit=$true } }
        }
        return [pscustomobject]@{ BaseDn=$domainDn; Scope='Subtree'; IsDomain=$true; Mode='Global'; Explicit=$false }
    }
    $baseDn = ([string]$script:SelectedBranchDn).Trim()
    if ([string]::IsNullOrWhiteSpace($baseDn)) { $baseDn = $domainDn }
    $subtree = Get-DomeniaControl -Name 'ChkSubtree'
    $includeChildren = ($null -eq $subtree -or [bool]$subtree.IsChecked)
    [pscustomobject]@{
        BaseDn = $baseDn
        Scope = $(if ($includeChildren) { 'Subtree' } else { 'OneLevel' })
        IsDomain = [string]::Equals($baseDn,$domainDn,[StringComparison]::OrdinalIgnoreCase)
        Mode = 'OU'
    }
}

function Update-DomeniaSearchScopeUi {
    if ([string]::IsNullOrWhiteSpace([string]$script:Conn.BaseDn)) { return }
    $mode = Get-DomeniaSearchMode
    $ouScope = Get-DomeniaSearchScope -Mode OU
    [void](Set-DomeniaControlText -Name 'TxtBranchDn' -Text ([string]$ouScope.BaseDn))
    Update-DomeniaNewOuParentUi
    if ($null -ne (Get-Command Update-DomeniaUxOuScope -CommandType Function -ErrorAction SilentlyContinue)) {
        Update-DomeniaUxOuScope -Scope $ouScope
    }
    # UX-33 / FO-04: the work view chip ('Dans : Postes') and the pin button follow the chosen OU.
    if ($null -ne (Get-Command Update-DomeniaOuScopeChoices -CommandType Function -ErrorAction SilentlyContinue)) {
        try { Update-DomeniaOuScopeChoices -Scope $ouScope } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSearchScopeUi' $_ }
    }
    # FO-05: the chip « Dans « Postes » » of the upper bar and its waiting text follow the OU chosen in the tree.
    if ($null -ne (Get-Command Update-DomeniaSearchBarUi -CommandType Function -ErrorAction SilentlyContinue)) {
        try { Update-DomeniaSearchBarUi } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSearchScopeUi' $_ }
    }
    Set-DomeniaSearchMode -Mode $mode
    try { Update-DomeniaOuRefreshUi } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSearchScopeUi' $_ }
    # The home overview follows this OU: recomputed now if Accueil is on screen, otherwise when it is shown.
    try { Request-DomeniaFleetRefresh } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSearchScopeUi' $_ }
    $summary = Get-DomeniaControl -Name 'LblSearchScope'
    if ($null -eq $summary) { return }
    if ($mode -eq 'Global') {
        # FO-05: the perimeter and the type of the bar are those of its chip and selector, written in full.
        $globalScope = Get-DomeniaSearchScope -Mode Global
        $barText = $null
        if ($null -ne (Get-Command Get-DomeniaSearchBarState -CommandType Function -ErrorAction SilentlyContinue)) { $barText = Get-DomeniaSearchBarState }
        $summary.Text = if ($null -ne $barText) { [string]$barText.Summary } else { 'Recherche globale · Domaine entier · Tous les types · Aucun filtre de liste' }
        $summary.ToolTip = 'Racine LDAP : '+[string]$globalScope.BaseDn+' (sous-OU incluses)'+"`r`nLa présence et le filtre de la liste ne restreignent pas cette recherche ; le filtre de la liste affine ensuite les lignes chargées. La limite de résultats reste appliquée."
    } else {
        $term = Get-DomeniaSearchText -Mode OU
        if ($term) { $summary.Text += ' · Terme de la recherche enregistrée : '+$term }
    }
}

function Invalidate-DomeniaSearchResults {
    param([switch]$KeepSelection)
    Stop-DomeniaLiveSearch
    # Toute modification de perimetre invalide aussi les retours deja en vol.
    $script:GlobalSearchGeneration = [int]$script:GlobalSearchGeneration + 1
    try { if ($null -ne $script:LiveSearchTimer) { $script:LiveSearchTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Invalidate-DomeniaSearchResults' $_ }
    if ($null -ne $script:AsyncJobs) {
        foreach ($id in @($script:AsyncJobs.Keys)) {
            $job = $script:AsyncJobs[$id]
            if ($null -ne $job -and [string]$job.ReplaceKey -in @('global','branch') -and -not [bool]$job.IsWrite) {
                Request-UiTaskStop -Id $id -Silent -Force -Superseded
            }
        }
    }
    Stop-DomeniaSelectionOpenTimer
    $script:PendingObjectSelection = $null
    $script:BranchObjects = @()
    $script:BranchCountLabel = 'Filtres modifies : recherche a effectuer'
    $wasSuppressed = [bool]$script:SuppressGridSelectionEvents
    $script:SuppressGridSelectionEvents = $true
    try { [void](Set-DomeniaItemsSource -Name 'DgObjects' -Rows @()) }
    finally { $script:SuppressGridSelectionEvents = $wasSuppressed }
    [void](Set-DomeniaControlText -Name 'LblBranchCount' -Text $script:BranchCountLabel)
    # The list is reset: the former selection is no longer shown anywhere (unless it is restored by this search).
    if (-not $KeepSelection) { Clear-DomeniaSelectionEverywhere }
}

function Test-DomeniaSearchStateCurrent {
    param($State)
    if ($null -eq $State -or [int]$State.Generation -ne [int]$script:GlobalSearchGeneration) { return $false }
    $mode = Get-DomeniaSearchMode
    if ($null -ne $State.PSObject.Properties['SearchMode'] -and [string]$State.SearchMode -cne $mode) { return $false }
    # FO-05: a work view list was read without the chip of the upper bar; it is compared with the same perimeter.
    $viewList = (($null -ne $State.PSObject.Properties['ViewId']) -and (-not [string]::IsNullOrEmpty([string]$State.ViewId)))
    $scope = Get-DomeniaSearchScope -Mode $mode -IgnoreBar:$viewList
    if (-not [string]::Equals([string]$State.BaseDn,[string]$scope.BaseDn,[StringComparison]::OrdinalIgnoreCase)) { return $false }
    if ([string]$State.Scope -ne [string]$scope.Scope) { return $false }
    if ([string]$State.TypeFilter -ne [string](Get-GlobalSelectedTypeFilter -Mode $mode)) { return $false }
    if ((Get-DomeniaSearchText -Mode $mode) -cne [string]$State.Search) { return $false }
    # D038: a work view result is current only while that same view is the active query.
    if ($null -ne $State.PSObject.Properties['ViewId'] -and [string]$State.ViewId -cne [string]$script:ActiveSearchViewId) { return $false }
    return $true
}

function Invoke-DomeniaSearchFilterChanged {
    if ($script:RestoringSettings -or $script:SuppressBranchAutoLoad -or -not $script:Conn.Connected) { return }
    if ([string]::IsNullOrWhiteSpace([string]$script:SelectedBranchDn)) { return }
    Select-DomeniaWorkspace -Workspace 'WsSearch'
    Invoke-GlobalSearch -AllowEmpty -SilentError -SearchMode OU
}

function Reset-DomeniaSearchScope {
    param([switch]$NoSearch)
    if ([string]::IsNullOrWhiteSpace([string]$script:Conn.BaseDn)) { return }
    $previousSuppression = [bool]$script:SuppressBranchAutoLoad
    $script:SuppressBranchAutoLoad = $true
    try {
        $script:SelectedBranchDn = [string]$script:Conn.BaseDn
        $check = Get-DomeniaControl -Name 'ChkSubtree'
        if ($null -ne $check) { $check.IsChecked = $true }
        $tree = Get-DomeniaControl -Name 'TvDirectory'
        if ($null -ne $tree -and $tree.Items.Count -gt 0) { $tree.Items[0].IsSelected = $true }
        Update-DomeniaSearchScopeUi
    }
    finally { $script:SuppressBranchAutoLoad = $previousSuppression }
    if (-not $NoSearch) { Invoke-DomeniaSearchFilterChanged }
}

function Get-TypeLdapFilter {
    param([string]$Type)
    switch ($Type) {
        "Utilisateurs" { return "(&(objectCategory=person)(objectClass=user))" }
        "Machines" { return "(objectCategory=computer)" }
        "Groupes" { return "(objectCategory=group)" }
        "OU et conteneurs" { return "(|(objectClass=organizationalUnit)(objectClass=container))" }
        default { return "(|(&(objectCategory=person)(objectClass=user))(objectCategory=computer)(objectCategory=group)(objectClass=organizationalUnit)(objectClass=container))" }
    }
}

function Get-SearchLdapFilter {
    param([string]$Text)
    $t = ($Text + "").Trim()
    if ([string]::IsNullOrWhiteSpace($t) -or $t -eq "*") { return "" }
    $pattern = Escape-LdapValue -Value $t -KeepWildcard
    if (-not $pattern.Contains("*")) { $pattern = "*$pattern*" }
    return "(|(name=$pattern)(displayName=$pattern)(sAMAccountName=$pattern)(userPrincipalName=$pattern)(mail=$pattern)(dNSHostName=$pattern)(description=$pattern))"
}

function Get-GlobalSelectedTypeFilter {
    param([ValidateSet('Global','OU')][string]$Mode = (Get-DomeniaSearchMode))
    if ($Mode -eq 'Global') {
        # FO-05: the type selector of the upper bar (Tout, Personnes, Postes, Groupes); never the type of the OU list.
        $barType = [string]$script:SearchBarType
        if ($barType -notin @('Tous','Utilisateurs','Machines','Groupes')) { $barType = 'Tous' }
        return (Get-TypeLdapFilter -Type $barType)
    }
    $label = 'Tous'
    $control = Get-DomeniaControl -Name 'CmbGlobalType'
    if ($null -ne $control -and $null -ne $control.SelectedItem) { $label = [string]$control.SelectedItem.Content }
    return (Get-TypeLdapFilter -Type $label)
}

function Get-ObjectsStatsText {
    $total = 0; $users = 0; $computers = 0; $groups = 0; $ous = 0; $containers = 0; $others = 0
    try {
        foreach ($r in @($script:BranchObjects)) {
            $total++
            switch ([string]$r.Type) {
                "Utilisateur" { $users++ }
                "Machine" { $computers++ }
                "Groupe" { $groups++ }
                "OU" { $ous++ }
                "Conteneur" { $containers++ }
                default { $others++ }
            }
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Get-ObjectsStatsText' $_ }
    return "Total : $total`r`nUtilisateurs : $users`r`nMachines : $computers`r`nGroupes : $groups`r`nOU : $ous`r`nConteneurs : $containers`r`nAutres : $others"
}





function Go-RootBranch {
    Reset-DomeniaSearchScope
}





function Clear-ObjectDetails {
    try {
        # UX-13 : quitter une fiche en edition laisse des valeurs qui ne partiront jamais. La
        # page le dira sur la fiche suivante, une fois, sans fenetre et sans bloquer la selection.
        if ([bool]$script:FicheEdit["Edition"]) {
            $modifies = @(Get-DomeniaFicheDirtyControls -Type ([string]$script:FicheEdit["Type"]))
            $inconnu = [bool]$script:FicheEdit["DirtyUnknown"]
            $abandon = ""
            if (($modifies.Count -gt 0) -or $inconnu) {
                $nomObjet = ""
                try { $nomObjet = [string]$script:SelectedObject.Name } catch { Write-DomeniaSwallowed 'Core' 'Clear-ObjectDetails' $_ }
                $abandon = if ($inconnu) { "Modifications éventuelles non vérifiées, abandonnées" } else { "Modifications non enregistrées abandonnées" }
                if (-not [string]::IsNullOrWhiteSpace($nomObjet)) { $abandon = $abandon + " sur " + $nomObjet }
                $abandon = $abandon + " en changeant dʼobjet."
            }
            Stop-DomeniaFicheEdit -Type ([string]$script:FicheEdit["Type"]) -Abandon $abandon
        }
    } catch { Write-DomeniaSwallowed 'Core' 'Clear-ObjectDetails' $_ }
    [void](Set-DomeniaItemsSource 'DgSessions' @());[void](Set-DomeniaControlText 'LblSessionsState' 'Sessions non lues pour cette fiche.')
    foreach ($name in @("TxtObjType","TxtObjName","TxtObjClass","TxtObjGuid","TxtObjCreated","TxtObjChanged","TxtObjDn","TxtObjPresence","TxtObjPresenceTarget","TxtUserGivenName","TxtUserSurname","TxtUserDisplayName","TxtUserSam","TxtUserUpn","TxtUserMail","TxtUserPhone","TxtUserOffice","TxtUserDescription","TxtUserTitle","TxtUserDepartment","TxtUserCompany","TxtUserManager","TxtUserState","TxtUserLastLogon","TxtUserPwdLastSet","TxtUserExpires","TxtUserUac",
        "TxtUserStreet","TxtUserCity","TxtUserState2","TxtUserPostalCode","TxtUserCountry",
        "TxtUserHomePhone","TxtUserMobile","TxtUserFax","TxtUserIpPhone","TxtUserWebPage",
        "TxtUserEmployeeId","TxtUserProfilePath","TxtUserScriptPath","TxtUserHomeDirectory",
        "TxtUserHomeDrive","TxtUserWorkstations","TxtCompName","TxtCompDns","TxtCompOs","TxtCompOsVersion","TxtCompDescription","TxtCompLocation","TxtCompManagedBy","TxtCompState","TxtCompLastLogon","TxtCompUac","TxtCompLinkedUser","TxtCompLinkSource","TxtGroupName","TxtGroupDescription","TxtUserLogonByDc","TxtCompLogonByDc")) {
        try { $script:Ctrl[$name].Text = "" } catch { Write-DomeniaSwallowed 'Core' 'Clear-ObjectDetails' $_ }
    }
    # Point 27: the per-controller read waits for the next object (Z02: a missing control is skipped, never swallowed).
    foreach ($name in @("BtnUserLogonByDc","BtnCompLogonByDc")) { $button = $script:Ctrl[$name]; if ($null -ne $button) { $button.IsEnabled = $false } }
    Update-DomeniaUserSupportBand -Entry $null
    Set-DomeniaManagerField -Target 'Utilisateur' -Dn ''
    Set-DomeniaManagerField -Target 'Machine' -Dn ''
    try { [void](Set-DomeniaItemsSource -Name "TxtUserLinkedComputers" -Rows @()) } catch { Write-DomeniaSwallowed 'Core' 'Clear-ObjectDetails' $_ }
    # UI-06: the membership grids of the previous object are emptied (Membership.UI).
    try { Clear-DomeniaMembershipLists } catch { Write-DomeniaSwallowed 'Core' 'Clear-ObjectDetails' $_ }
    try { $script:Ctrl["DgRawAttrs"].ItemsSource = $null } catch { Write-DomeniaSwallowed 'Core' 'Clear-ObjectDetails' $_ }
}



function Reset-DomeniaSelectionBoundViews {
    <#
        Regle stricte :
        aucune donnee de l'objet precedent ne reste affichee pendant le
        chargement d'une nouvelle selection.

        L'increment de generation invalide egalement les callbacks asynchrones
        encore en vol pour l'ancien objet.
    #>
    [CmdletBinding()]
    param(
        [AllowEmptyString()][string]$Dn = "",
        [AllowEmptyString()][string]$Type = "",
        [AllowEmptyString()][string]$Name = "",
        [AllowEmptyString()][string]$Guid = ""
    )

    try {
        $script:SelectedObjectGeneration = [int64]$script:SelectedObjectGeneration + 1
        $script:SelectionLoad = $null
        $script:CurrentObjectRequestState = $null
        $script:SelectedObject = $null
        $script:CurrentCapabilities = @{}
        $script:ActualSecretDeniedDn = ""
        $script:ActiveSecretRequestId = ""

        # Invalide explicitement tout ancien probe user-machine.
        $script:ActiveLinkProbeId = "invalidated-" + [guid]::NewGuid().ToString("N")
        $script:ActiveLinkProbeComputer = ""

        try { Stop-DomeniaSecretReadTasks } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }

        # Stoppe toutes les taches dont le resultat est lie a l'objet precedent.
        foreach ($taskId in @($script:AsyncJobs.Keys)) {
            try {
                $job = $script:AsyncJobs[$taskId]
                if (($null -eq $job) -or ($job.IsWrite)) { continue }
                $replaceKey = [string]$job.ReplaceKey
                if (
                    (([string]$replaceKey) -in @("secrets","computerdiag","permissions","inventory","software","wmi","services")) -or
                    (([string]$replaceKey) -like "lastuser:*")
                ) {
                    Request-UiTaskStop -Id ([string]$taskId) -Silent -Force -Superseded -Reason 'Changement de selection'
                }
            }
            catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }
        }

        Clear-ObjectDetails
        Clear-Secrets
        try { Clear-DomeniaDashboards } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }
        try { Reset-DomeniaComputerAssistViews } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }

        $script:ComputerDiagRows = @()
        $script:PermissionRows = @()
        $script:InventoryRows = @()
        $script:InventoryAccess = @()
        $script:SoftwareRows = @()
        $script:SoftwareAccess = @()
        $script:InventoryComputer = ''
        $script:InventoryCompletedAt = $null
        Update-DomeniaInventoryAgeLine
        $script:SoftwareSource = ''
        $script:SoftwareProvenance = ''
        $script:SoftwareChartSelect = $null
        Update-DomeniaSoftwareFilterChip
        Update-DomeniaSoftwareAccessSummary

        foreach ($gridName in @(
            "DgLinks",
            "DgLinkAttempts",
            "DgComputerDiag",
            "DgPermissions",
            "DgRawAttrs",
            "DgInventory",
            "DgInventoryAccess",
            "DgSoftware",
            "DgSoftwareAccess",
            "DgWmiSchema",
            "DgWmiInstances"
        )) {
            try { [void](Set-DomeniaItemsSource -Name $gridName -Rows @()) } catch {
                try { $script:Ctrl[$gridName].ItemsSource = $null } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }
            }
        }

        try { Clear-DomeniaMembershipLists } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }
        foreach ($listName in @($script:Ctrl.Keys)) {
            if ($listName -like "LstWmi*") {
                try { $script:Ctrl[$listName].Items.Clear() } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }
            }
        }

        foreach ($checkName in @(
            "ChkPwdNeverExpires","ChkPwdNotRequired","ChkReversiblePwd",
            "ChkSmartcardRequired","ChkAccountNotDelegated","ChkNoPreAuth",
            "ChkUseDesOnly","ChkTrustedForDelegation","ChkTrustedToAuthDelegation"
        )) {
            try { $script:Ctrl[$checkName].IsChecked = $false } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }
        }

        $objectLabel = if (-not [string]::IsNullOrWhiteSpace($Name)) {
            "$Type $Name"
        }
        elseif (-not [string]::IsNullOrWhiteSpace($Type)) {
            $Type
        }
        else {
            "Aucun objet"
        }

        [void](Set-DomeniaControlText -Name "LblLinkContext" -Text "$objectLabel : chargement des associations...")
        [void](Set-DomeniaControlText -Name "LblLinkProbeStatus" -Text "En attente du chargement complet de l'objet.")
        try { Update-DomeniaLinkActionUi -RowCount 0 } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }
        try { $script:LastLoadedEntry = $null; Reset-DomeniaDeferredViews } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }
        [void](Set-DomeniaControlText -Name "LblSecretsStatus" -Text "Aucun secret charge pour cette selection.")
        # FI-19: the summary of the last BitLocker/LAPS reading of a workstation (metadata, never a value) is read off
        # the Dispatcher and completes this hint; another selection, or another type of object, cancels the request.
        # Point 9: the GUID of the displayed workstation lets the reading leave out metadata recorded by name before
        # this computer was created (a former holder of the name).
        try { if ($Type -eq "Machine") { Request-DomeniaSecretIndexSummary -Computer ([string]$Name) -Guid ([string]$Guid) } else { Request-DomeniaSecretIndexSummary -Computer '' } } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }
        [void](Set-DomeniaControlText -Name "LblComputerDiag" -Text "Aucun diagnostic lance pour cette selection.")
        [void](Set-DomeniaControlText -Name "LblPermissionSummary" -Text "Droits non evalues pour cette selection.")
        [void](Set-DomeniaControlText -Name "LblInventoryStatus" -Text "Aucun inventaire charge pour cette selection.")
        [void](Set-DomeniaControlText -Name "LblSoftwareStatus" -Text "Aucun logiciel charge pour cette selection.")
        [void](Set-DomeniaControlText -Name "LblWmiStatus" -Text "Aucune lecture WMI chargee pour cette selection.")

        try { Update-DomeniaSecretActionUi } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }
        try { Apply-CurrentPermissionUi } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }
        try { Request-DomeniaDashboardRefresh } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaSelectionBoundViews' $_ }

        if (-not [string]::IsNullOrWhiteSpace($Dn)) {
            Set-Status "Ancienne fiche videe. Chargement de $objectLabel..."
        }
        else {
            Set-Status "Aucun objet sélectionné."
        }
    }
    catch {
        Write-AppLog "Purge stricte de la fiche objet impossible : $($_.Exception.ToString())" "ERROR"
        throw
    }
}






function Fill-GenericObject {
    param($Entry, [string]$Type)
    $script:Ctrl["TxtObjType"].Text = $Type
    $script:Ctrl["TxtObjName"].Text = [string](Get-DeProp $Entry "name" "")
    $script:Ctrl["TxtObjClass"].Text = ((Get-DePropAll $Entry "objectClass") -join ",")
    $script:Ctrl["TxtObjGuid"].Text = Convert-GuidLabel (Get-DeProp $Entry "objectGUID" "")
    $script:Ctrl["TxtObjCreated"].Text = Convert-DateLabel (Get-DeProp $Entry "whenCreated" "")
    $script:Ctrl["TxtObjChanged"].Text = Convert-DateLabel (Get-DeProp $Entry "whenChanged" "")
    $script:Ctrl["TxtObjDn"].Text = [string](Get-DeProp $Entry "distinguishedName" "")
}

function Update-DomeniaUserSupportBand {
    # FO-06 : la fiche laissait au support deviner qu un compte est verrouille ou que son mot de passe
    # est mort. Le bandeau ne dit que ce que le controleur a repondu, et reste muet sinon.
    param($Entry)
    $bande = Get-DomeniaControl -Name "PnlUserSupportBand"
    if ($null -eq $bande) { return }
    $titre = Get-DomeniaControl -Name "TxtUserSupportBand"
    $detail = Get-DomeniaControl -Name "TxtUserSupportDetail"
    $deverrouiller = Get-DomeniaControl -Name "BtnUserSupportUnlock"
    $journal = Get-DomeniaControl -Name "BtnUserSupportLockouts"
    $verrouillages = Get-DomeniaControl -Name "TxtUserSupportLockouts"
    foreach ($c in @($bande, $titre, $detail, $deverrouiller, $journal, $verrouillages)) {
        if ($null -ne $c) { $c.Visibility = [System.Windows.Visibility]::Collapsed }
    }
    if ($null -ne $verrouillages) { $verrouillages.Text = '' }
    $script:UserSupportLockoutTarget = $null
    try {
        if ($null -eq $Entry) { return }
        if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Utilisateur") { return }
        foreach ($n in @('Get-DomeniaUserSupportSummary','Get-DomeniaLockoutDiagnosis','Resolve-DomeniaPasswordPolicy','ConvertTo-DomeniaAdDate')) {
            if (-not (Get-Command $n -ErrorAction SilentlyContinue)) { return }
        }
        $props = @{}
        foreach ($nom in @('userAccountControl','msDS-User-Account-Control-Computed','lockoutTime','pwdLastSet','accountExpires','badPwdCount','badPasswordTime','msDS-UserPasswordExpiryTimeComputed')) {
            $props[$nom] = Get-DeProp $Entry $nom $null
        }
        $maintenant = [datetime]::UtcNow
        $alertes = New-Object 'System.Collections.Generic.List[string]'
        $limites = New-Object 'System.Collections.Generic.List[string]'
        # Point 47: what the 4740 read needs, captured with the generation of this fiche.
        $sam = [string](Get-DeProp $Entry 'sAMAccountName' '')
        $script:UserSupportLockoutTarget = [pscustomobject]@{
            Dn = [string](Get-DeProp $Entry 'distinguishedName' ''); Sid = (ConvertTo-DomeniaSidText (Get-DeProp $Entry 'objectSid' $null)); Sam = $sam
            Properties = $props; AccountKeys = @(Get-DomeniaLockoutAccountKeys -Sam $sam -Upn ([string](Get-DeProp $Entry 'userPrincipalName' '')))
        }
        $diag = Get-DomeniaLockoutDiagnosis -User $props -EventReadState 'NotRequested' -NowUtc $maintenant
        $verrouille = ($null -ne $diag) -and (([string]$diag.Verdict) -ceq 'Verrouille')
        if ($verrouille) {
            $instant = ConvertTo-DomeniaAdDate (Get-DeProp $Entry 'lockoutTime' $null)
            if ($null -ne $instant) { $alertes.Add('Verrouillé depuis le ' + $instant.ToLocalTime().ToString('dd/MM HH:mm')) }
            else { $alertes.Add('Verrouillé') }
            $limites.Add('Heure du dernier verrouillage relevée sur le contrôleur interrogé.')
        }
        $resume = @(Get-DomeniaUserSupportSummary -Properties $props -NowUtc $maintenant)
        $etat = @($resume | Where-Object { [string]$_.Fait -ceq 'Etat du compte' })
        if ($etat.Count -gt 0 -and [string]$etat[0].Limite) {
            $alertes.Add('État du compte non confirmé par le contrôleur')
            $limites.Add('Sans lʼétat calculé par le contrôleur, un verrouillage ne peut être ni affirmé ni nié.')
        }
        $pol = Resolve-DomeniaPasswordPolicy -User $props -ResultantPsoState 'Unreadable' -NowUtc $maintenant
        $echeance = $null
        if ($null -ne $pol) { $echeance = $pol.ExpiresUtc }
        $montree = $false
        if ($null -ne $echeance) {
            $jours = [int][math]::Ceiling(($echeance.ToUniversalTime() - $maintenant).TotalDays)
            if ($jours -le 0) {
                $alertes.Add('Mot de passe expiré depuis le ' + $echeance.ToLocalTime().ToString('dd/MM HH:mm'))
                $montree = $true
            }
            elseif ($jours -le 14) {
                $alertes.Add('Mot de passe expire dans ' + [string]$jours + ' j')
                $montree = $true
            }
        }
        if ($montree) { $limites.Add('Échéance calculée par le contrôleur : la stratégie du domaine nʼest pas lue avec ce compte.') }
        $echecs = 0L
        if ([long]::TryParse([string](Get-DeProp $Entry 'badPwdCount' ''), [ref]$echecs) -and $echecs -gt 0) {
            $alertes.Add([string]$echecs + ' mauvais mots de passe')
            $limites.Add('Compteur dʼéchecs propre au contrôleur interrogé : il nʼest pas répliqué.')
        }
        $dernier = ConvertTo-DomeniaAdDate (Get-DeProp $Entry 'lockoutTime' $null)
        $recent = ((-not $verrouille) -and ($null -ne $dernier) -and ($dernier.ToUniversalTime() -gt $maintenant.AddDays(-7)))
        if ($recent) {
            $alertes.Add('Verrouillé le ' + $dernier.ToLocalTime().ToString('dd/MM HH:mm') + ', plus maintenant')
            $limites.Add('Le contrôleur a levé ce verrouillage ; le journal 4740 dit quel poste lʼa provoqué.')
        }
        if ($alertes.Count -eq 0) { return }
        if ($null -ne $titre) { $titre.Text = ($alertes -join '   ·   ') }
        if ($null -ne $detail -and $limites.Count -gt 0) {
            $detail.Text = ($limites -join ' ')
            $detail.Visibility = [System.Windows.Visibility]::Visible
        }
        $bande.Visibility = [System.Windows.Visibility]::Visible
        if ($verrouille -and $null -ne $deverrouiller) { $deverrouiller.Visibility = [System.Windows.Visibility]::Visible }
        if (($verrouille -or $recent -or ($echecs -gt 0)) -and ($null -ne $journal) -and ($null -ne $script:UserSupportLockoutTarget) -and ([string]$script:UserSupportLockoutTarget.Sid)) { $journal.Visibility = [System.Windows.Visibility]::Visible }
    }
    catch {
        # Un bandeau qui n a pas pu se construire ne doit pas vider la fiche : il reste masque.
        try { $bande.Visibility = [System.Windows.Visibility]::Collapsed } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaUserSupportBand' $_ }
    }
}

function Fill-UserObject {
    param($Entry)
    $uac = Get-DeProp $Entry "userAccountControl" $null
    $lockout = Get-DeProp $Entry "lockoutTime" 0
    $script:Ctrl["TxtUserGivenName"].Text = [string](Get-DeProp $Entry "givenName" "")
    $script:Ctrl["TxtUserSurname"].Text = [string](Get-DeProp $Entry "sn" "")
    $script:Ctrl["TxtUserDisplayName"].Text = [string](Get-DeProp $Entry "displayName" "")
    $script:Ctrl["TxtUserSam"].Text = [string](Get-DeProp $Entry "sAMAccountName" "")
    $script:Ctrl["TxtUserUpn"].Text = [string](Get-DeProp $Entry "userPrincipalName" "")
    $script:Ctrl["TxtUserMail"].Text = [string](Get-DeProp $Entry "mail" "")
    $script:Ctrl["TxtUserPhone"].Text = [string](Get-DeProp $Entry "telephoneNumber" "")
    $script:Ctrl["TxtUserOffice"].Text = [string](Get-DeProp $Entry "physicalDeliveryOfficeName" "")
    $script:Ctrl["TxtUserDescription"].Text = [string](Get-DeProp $Entry "description" "")
    $script:Ctrl["TxtUserTitle"].Text = [string](Get-DeProp $Entry "title" "")
    $script:Ctrl["TxtUserDepartment"].Text = [string](Get-DeProp $Entry "department" "")
    $script:Ctrl["TxtUserCompany"].Text = [string](Get-DeProp $Entry "company" "")
    Set-DomeniaManagerField -Target 'Utilisateur' -Dn ([string](Get-DeProp $Entry "manager" ""))
    $script:Ctrl["TxtUserState"].Text = Get-UacStatusLabel $uac $lockout (Get-DeProp $entry "msDS-User-Account-Control-Computed" $null)
    $script:Ctrl["TxtUserLastLogon"].Text = Convert-FileTimeLabel (Get-DeProp $Entry "lastLogonTimestamp" 0)
    # Point 27: what this approximate date means, and an explicit per-controller read of lastLogon.
    if (${function:Update-DomeniaLogonActivityPanel}) { Update-DomeniaLogonActivityPanel -Kind User -Entry $Entry }
    $script:Ctrl["TxtUserPwdLastSet"].Text = Convert-FileTimeLabel (Get-DeProp $Entry "pwdLastSet" 0)
    $script:Ctrl["TxtUserExpires"].Text = Convert-FileTimeLabel (Get-DeProp $Entry "accountExpires" 0)
    $script:Ctrl["TxtUserUac"].Text = Get-UacFlagsLabel $uac
    Update-DomeniaUserSupportBand -Entry $Entry
    try {
        if (-not $script:RenderingObjectWithoutProbes) { Update-DomeniaSelectedUserPresence -Login ([string](Get-DeProp $Entry "sAMAccountName" "")) -Guid (ConvertTo-DomeniaGuidText (Get-DomeniaEntryFirstString $Entry "objectGUID")) -CreatedUtc (Get-DeProp $Entry "whenCreated" $null) }
        else { Set-DomeniaPresenceText -Name 'TxtUserPresence' -State 'Non verifie (fiche AD uniquement)'; Update-DomeniaObjectPresence -State 'Non verifie' -Target '' }
    }
    catch {
        Set-DomeniaPresenceText -Name "TxtUserPresence" -State "Inconnu"
        Update-DomeniaObjectPresence -State "Inconnu" -Target ""
    }
    try {
        # Point 9: an account recreated under a former login does not list the workstations of the previous account.
        $linked = @(Get-LinksForUser -UserLogin ([string](Get-DeProp $Entry "sAMAccountName" "")) -Guid (ConvertTo-DomeniaGuidText (Get-DomeniaEntryFirstString $Entry "objectGUID")) -CreatedUtc (Get-DeProp $Entry "whenCreated" $null))
        $linkedComputers = @($linked | ForEach-Object { [string]$_.Computer } | Where-Object { $_ } | Sort-Object -Unique)
        [void](Set-DomeniaItemsSource -Name "TxtUserLinkedComputers" -Rows $linkedComputers)
        if ($linkedComputers.Count -gt 0) { $script:Ctrl["TxtUserLinkedComputers"].SelectedIndex = 0 }
    }
    catch {
        [void](Set-DomeniaItemsSource -Name "TxtUserLinkedComputers" -Rows @())
        Write-AppLog "Affichage des postes associes impossible : $($_.Exception.Message)" "WARN"
    }
    $u = 0; try { $u = [int]$uac } catch { Write-DomeniaSwallowed 'Core' 'Fill-UserObject' $_ }
    $script:Ctrl["ChkPwdNeverExpires"].IsChecked = (($u -band 65536) -ne 0)
    $script:Ctrl["ChkPwdNotRequired"].IsChecked = (($u -band 32) -ne 0)
    $script:Ctrl["ChkReversiblePwd"].IsChecked = (($u -band 128) -ne 0)
    if ($script:Ctrl.ContainsKey("ChkSmartcardRequired")) { $script:Ctrl["ChkSmartcardRequired"].IsChecked = (($u -band 262144) -ne 0) }
    if ($script:Ctrl.ContainsKey("ChkAccountNotDelegated")) { $script:Ctrl["ChkAccountNotDelegated"].IsChecked = (($u -band 1048576) -ne 0) }
    if ($script:Ctrl.ContainsKey("ChkNoPreAuth")) { $script:Ctrl["ChkNoPreAuth"].IsChecked = (($u -band 4194304) -ne 0) }
    if ($script:Ctrl.ContainsKey("ChkUseDesOnly")) { $script:Ctrl["ChkUseDesOnly"].IsChecked = (($u -band 2097152) -ne 0) }
    if ($script:Ctrl.ContainsKey("ChkTrustedForDelegation")) { $script:Ctrl["ChkTrustedForDelegation"].IsChecked = (($u -band 524288) -ne 0) }
    if ($script:Ctrl.ContainsKey("ChkTrustedToAuthDelegation")) { $script:Ctrl["ChkTrustedToAuthDelegation"].IsChecked = (($u -band 16777216) -ne 0) }
    Fill-DomeniaUserContact -Entry $Entry
    Snapshot-DomeniaFicheEdit -Type 'Utilisateur'
    # Rendering is read-only. In particular, a cached fiche must never refresh the
    # persistent observation time or replace a newer committed directory record.
    Sync-DomeniaResultRowFromEntry -Entry $Entry -Type "Utilisateur"
    # UI-06: groups as a readable grid (Membership.UI).
    Set-DomeniaMembershipList -Kind MemberOf -Dns @(Get-DePropAll $Entry "memberOf") -ObjectDn ([string](Get-DeProp $Entry "distinguishedName" "")) -Complete ([bool](Get-DeProp $Entry '__memberOfComplete' $true)) -Note ([string](Get-DeProp $Entry '__memberOfNote' ''))
}

