function Fill-ComputerObject {
    param($Entry)
    Sync-DomeniaResultRowFromEntry -Entry $Entry -Type "Machine"
    $uac = Get-DeProp $Entry "userAccountControl" $null
    $script:Ctrl["TxtCompName"].Text = [string](Get-DeProp $Entry "name" "")
    $script:Ctrl["TxtCompDns"].Text = [string](Get-DeProp $Entry "dNSHostName" "")
    $script:Ctrl["TxtCompOs"].Text = [string](Get-DeProp $Entry "operatingSystem" "")
    $script:Ctrl["TxtCompOsVersion"].Text = [string](Get-DeProp $Entry "operatingSystemVersion" "")
    $script:Ctrl["TxtCompDescription"].Text = [string](Get-DeProp $Entry "description" "")
    $script:Ctrl["TxtCompLocation"].Text = [string](Get-DeProp $Entry "location" "")
    Snapshot-DomeniaFicheEdit -Type 'Machine'
    Set-DomeniaManagerField -Target 'Machine' -Dn ([string](Get-DeProp $Entry "managedBy" ""))
    $script:Ctrl["TxtCompState"].Text = Get-UacStatusLabel $uac 0
    $script:Ctrl["TxtCompLastLogon"].Text = Convert-FileTimeLabel (Get-DeProp $Entry "lastLogonTimestamp" 0)
    if (${function:Update-DomeniaLogonActivityPanel}) { Update-DomeniaLogonActivityPanel -Kind Computer -Entry $Entry }
    $script:Ctrl["TxtCompUac"].Text = Get-UacFlagsLabel $uac
    $script:Ctrl["TxtCompNewName"].Text = [string](Get-DeProp $Entry "name" "")
    try {
        $presenceName = [string](Get-DeProp $Entry "name" "")
        $presenceDns = [string](Get-DeProp $Entry "dNSHostName" "")
        if (-not $script:RenderingObjectWithoutProbes) { Start-DomeniaSelectedMachinePresence -Name $presenceName -DnsName $presenceDns }
        else {
            $row=Get-DomeniaSelectedGridRow
            $state=if($null -ne $row -and [string]$row.DN -ieq [string]$script:SelectedObject.DN -and $row.Presence){[string]$row.Presence}else{'Non vérifié'}
            $stateKey=if($null -ne $row -and [string]$row.DN -ieq [string]$script:SelectedObject.DN -and $row.Presence){Get-DomeniaRowPresenceState $row}else{'Unknown'}
            Set-DomeniaPresenceText -Name 'TxtCompPresence' -State $state -PresenceState $stateKey
            Update-DomeniaObjectPresence -State $state -Target $presenceDns -PresenceState $stateKey
        }
    }
    catch {
        Set-DomeniaPresenceText -Name "TxtCompPresence" -State "Inconnu"
        Update-DomeniaObjectPresence -State "Inconnu" -Target ""
    }
    # UI-06: groups as a readable grid (Membership.UI).
    Set-DomeniaMembershipList -Kind MemberOf -Dns @(Get-DePropAll $Entry "memberOf") -ObjectDn ([string](Get-DeProp $Entry "distinguishedName" "")) -Complete ([bool](Get-DeProp $Entry '__memberOfComplete' $true)) -Note ([string](Get-DeProp $Entry '__memberOfNote' ''))
    try {
        $computerForLink = Normalize-LinkComputer ([string](Get-DeProp $Entry "name" ""))
        # Point 9: the association of a former holder of this name (other GUID, or recorded before this computer was
        # created) is not shown on the fiche of the current object.
        $computerGuid = ConvertTo-DomeniaGuidText (Get-DomeniaEntryFirstString $Entry "objectGUID")
        $computerCreated = Get-DeProp $Entry "whenCreated" $null
        $link = Get-ExistingLinkForComputer -Computer $computerForLink -Guid $computerGuid -CreatedUtc $computerCreated
        if ($null -ne $link) {
            $script:Ctrl["TxtCompLinkedUser"].Text = [string]$link.UserLogin
            # D043: badge of the link (relation model), never a percentage.
            $confidenceText = $(if($null -ne (Get-Command Get-DomeniaLinkQualification -CommandType Function -ErrorAction SilentlyContinue)){(Get-DomeniaLinkQualification $link).Suffix}elseif($null -ne $link.PSObject.Properties['Confidence'] -and -not [string]::IsNullOrWhiteSpace([string]$link.Confidence)){'  confiance '+[string]$link.Confidence+'%'}else{''})
            # CO-29: the date of the link in local time (stored in UTC since RC1.14).
            $whenText = ''
            if ($null -ne (Get-Command Format-DomeniaRelationWhen -CommandType Function -ErrorAction SilentlyContinue)) { $whenText = Format-DomeniaRelationWhen ([string]$link.When) }
            if (-not $whenText) { $whenText = [string]$link.When }
            # Point 9: a legacy link without GUID that does not predate this computer is kept, but its identity is not
            # proven: the fiche says so instead of presenting it as an ordinary association.
            $identityText = ''
            if (($computerGuid) -and ((Test-DomeniaLinkIdentity -Link $link -Kind Computer -Guid $computerGuid -CreatedUtc $computerCreated).Match -eq 'Unknown')) { $identityText = ' · identité non vérifiable' }
            $script:Ctrl["TxtCompLinkSource"].Text = "$($link.Source)$confidenceText  $whenText$identityText"
        } else {
            $script:Ctrl["TxtCompLinkedUser"].Text = "Non detecte"
            $script:Ctrl["TxtCompLinkSource"].Text = "Détection manuelle disponible"
        }
    } catch {
        $script:Ctrl["TxtCompLinkedUser"].Text = "Indisponible"
        $script:Ctrl["TxtCompLinkSource"].Text = $_.Exception.Message
    }
    try {
        $targetPc = Get-CurrentSelectedComputerName
        if (-not $script:RenderingObjectWithoutProbes -and -not [string]::IsNullOrWhiteSpace($targetPc)) {
            # Detection automatique a chaque nouvelle machine reellement chargee.
            # ProbeOncePerSession et la presence d'un lien existant evitent les
            # repetitions inutiles.
            Start-ComputerUserLinkProbe -Computer $targetPc
        }
    }
    catch { Write-AppLog "Probe automatique user-machine non lance : $($_.Exception.Message)" "WARN" }
    # DS-08 / UI-07 / UI-17 (X04): fixed header, account card and association line from what was just filled.
    try { Update-DomeniaComputerAssistView -Uac $uac } catch { Write-AppLog "En-tete du poste non mis a jour : $($_.Exception.Message)" "WARN" }
}

function Get-DomeniaMembershipLabel {
    # « 2 000 affichés sur 3 412 membre(s) direct(s) », with the reason when the AD reading stayed partial.
    param([int]$Shown,[int]$Total,[bool]$Complete,[string]$Note,[string]$Noun)
    $text = if ($Total -gt $Shown) { ([string]$Shown + ' affichés sur ' + [string]$Total + ' ' + $Noun) } else { ([string]$Total + ' ' + $Noun) }
    if (-not $Complete) { $text += ' · lecture partielle' + $(if ($Note) { ' : ' + $Note } else { ', couverture non confirmée' }) }
    return $text
}

