function Normalize-LinkComputer {
    param([string]$Computer)
    $c = ($Computer + "").Trim()
    if ([string]::IsNullOrWhiteSpace($c)) { return "" }
    $c = $c.Trim("`"", " ", "`t", "`r", "`n")
    if ($c.EndsWith("$")) { $c = $c.Substring(0, $c.Length - 1) }
    if ($c.Contains(".")) { $c = $c.Split(".")[0] }
    return $c.ToUpperInvariant()
}

function Normalize-LinkUser {
    param([string]$User)
    $u = ($User + "").Trim()
    if ([string]::IsNullOrWhiteSpace($u)) { return "" }
    $u = $u.Trim("`"", " ", "`t", "`r", "`n")
    $slash = [string][char]92
    if ($u.Contains($slash)) { $u = $u.Split($slash)[-1] }
    if ($u.Contains("@")) { $u = $u.Split("@")[0] }
    $dollar = [string][char]36
    if ($u.EndsWith($dollar)) { return "" }
    $bad = @("SYSTEM", "LOCAL SERVICE", "NETWORK SERVICE", "ANONYMOUS LOGON", "DWM-1", "DWM-2", "UMFD-0", "UMFD-1", "DEFAULTUSER0", "ADMINISTRATEUR", "ADMINISTRATOR")
    if ($bad -contains $u.ToUpperInvariant()) { return "" }
    return $u
}

function Get-ExistingLinkForComputer {
    # Point 9: with the GUID of the displayed computer (and its whenCreated when read), a link proven to belong to
    # another object of the same name is skipped (Test-DomeniaLinkIdentity); without GUID the first link of the name.
    # A name is unique among the computers of one domain base: a lookup of the selected workstation's name without GUID
    # (local-first probe, Rimotte, receipts, association line of Assistance poste) uses the selected object's GUID and,
    # once its fiche was read, its whenCreated, so a former holder never answers for it.
    param([string]$Computer,[string]$Guid='',$CreatedUtc=$null)
    $cn = Normalize-LinkComputer $Computer
    if ([string]::IsNullOrWhiteSpace($cn)) { return $null }
    $selectionChecked = [bool]$Guid
    foreach ($l in @($script:UserMachineLinks)) {
        # Called once per workstation of a list analysis: a cheap substring test skips the other computers first
        # (the normalised name is always a case-insensitive substring of the stored one).
        $stored = [string]$l.Computer
        if ($stored.IndexOf($cn,[StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
        if ((Normalize-LinkComputer $stored) -ne $cn) { continue }
        if (-not $selectionChecked) {
            # Only once a link of this name exists: the selection is read once per lookup, never per link.
            $selectionChecked = $true
            if (($null -ne $script:SelectedObject) -and ([string](Get-DomeniaMember $script:SelectedObject 'Type' '') -eq 'Machine') -and ((Normalize-LinkComputer ([string](Get-DomeniaMember $script:SelectedObject 'Name' ''))) -eq $cn)) {
                $Guid = ConvertTo-DomeniaGuidText (Get-DomeniaMember $script:SelectedObject 'Guid' '')
                if ($null -eq $CreatedUtc) { $selectedEntry = Get-DomeniaMemberValue $script:SelectedObject 'Entry'; if ($null -ne $selectedEntry) { $CreatedUtc = Get-DeProp $selectedEntry "whenCreated" $null } }
            }
        }
        if (($Guid) -and ((Test-DomeniaLinkIdentity -Link $l -Kind Computer -Guid $Guid -CreatedUtc $CreatedUtc).Match -eq 'Different')) { continue }
        return $l
    }
    return $null
}



function Remove-LinksForDeletedObject {
    param([string]$Type, [string]$Name, [string]$Sam, [string]$Dns)
    try {
        $previousLinks = @($script:UserMachineLinks)
        $before = $previousLinks.Count
        if ($before -le 0) { return }
        if ($Type -eq "Machine") {
            $targets = @((Normalize-LinkComputer $Name), (Normalize-LinkComputer $Sam), (Normalize-LinkComputer $Dns)) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique
            if ($targets.Count -gt 0) {
                $script:UserMachineLinks = @($script:UserMachineLinks | Where-Object { $targets -notcontains (Normalize-LinkComputer ([string]$_.Computer)) })
            }
        }
        elseif ($Type -eq "Utilisateur") {
            $targets = @((Normalize-LinkUser $Name), (Normalize-LinkUser $Sam), (Normalize-LinkUser $Dns)) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique
            if ($targets.Count -gt 0) {
                $script:UserMachineLinks = @($script:UserMachineLinks | Where-Object { $targets -notcontains (Normalize-LinkUser ([string]$_.UserLogin)) })
            }
        }
        $after = @($script:UserMachineLinks).Count
        if ($after -ne $before) {
            if (-not (Save-UserMachineLinks)) {
                $script:UserMachineLinks = $previousLinks
                Rebuild-UserMachineLinkIndex
                Refresh-LinkGrid
                return
            }
            Refresh-LinkGrid
            Write-AppLog "Liens user-machine nettoyes apres suppression $Type : $($before - $after) lien(s) retire(s)."
        }
    }
    catch { Write-AppLog "Nettoyage liens impossible : $($_.Exception.Message)" "WARN" }
}



function Get-CurrentSelectedComputerName {
    return (Normalize-LinkComputer (Get-SelectedComputerTarget))
}



function Ensure-LinkProbeTimer {
    if ($null -ne $script:LinkProbeTimer) { return }
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromSeconds(2)
    $timer.Add_Tick({ Complete-LinkProbeJobs })
    $script:LinkProbeTimer = $timer
    $script:LinkProbeTimer.Start()
}

function Complete-LinkProbeJobs {
    try {
        $doneKeys = @()
        foreach ($key in @($script:LinkProbeJobs.Keys)) {
            $job = $script:LinkProbeJobs[$key]
            if ($null -eq $job) { $doneKeys += $key; continue }
            if ($job.State -in @("Completed", "Failed", "Stopped")) {
                $result = $null
                try { $result = Receive-Job -Job $job -ErrorAction SilentlyContinue | Select-Object -Last 1 } catch { Write-DomeniaSwallowed 'Core' 'Complete-LinkProbeJobs' $_ }
                try { Remove-Job -Job $job -Force -ErrorAction SilentlyContinue } catch { Write-DomeniaSwallowed 'Core' 'Complete-LinkProbeJobs' $_ }
                $doneKeys += $key
                if ($null -ne $result -and $result.Success -and -not [string]::IsNullOrWhiteSpace([string]$result.UserLogin)) {
                    [void](Add-UserMachineLinkIfMissing -UserLogin ([string]$result.UserLogin) -Computer ([string]$result.Computer) -Source ([string]$result.Source) -Details ([string]$result.Details))
                }
                else {
                    $details = "Aucun dernier utilisateur fiable trouve pour $key"
                    if ($null -ne $result) { $details = [string]$result.Details }
                    Set-Status "Détection terminée : aucun utilisateur suffisamment fiable pour $key." "INFO"
                    try { $script:Ctrl["LblLinkProbeStatus"].Text = "Aucun lien ajoute pour $key. $details" } catch { Write-DomeniaSwallowed 'Core' 'Complete-LinkProbeJobs' $_ }
                    Write-AppLog "Detection user-machine sans resultat fiable pour $key : $details" "INFO"
                }
            }
        }
        foreach ($k in $doneKeys) { $script:LinkProbeJobs.Remove($k) }
        if ($script:LinkProbeJobs.Count -eq 0 -and $null -ne $script:LinkProbeTimer) { $script:LinkProbeTimer.Stop(); $script:LinkProbeTimer = $null }
    }
    catch { Write-AppLog "Erreur fin probe user-machine : $($_.Exception.Message)" "WARN" }
}










# =====================================================================
# Selecteur d objet Active Directory.
# Creer une association demandait de taper le nom du poste de memoire.
# Ce selecteur cherche dans l annuaire, montre ce qu il trouve et ne rend
# que des objets qui existent reellement.
# =====================================================================
function Search-DomeniaPickerObjects {
    param(
        [Parameter(Mandatory=$true)][ValidateSet("Machine","Utilisateur")][string]$Kind,
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$Term,
        [int]$Limit = 60
    )
    $rows = New-Object System.Collections.Generic.List[object]
    $clean = ([string]$Term).Trim()
    if ($clean.Length -lt 2) { return $rows }
    if ($clean.Contains([string][char]92)) { $clean = $clean.Split([char]92)[-1] }
    if ($clean.Contains("@")) { $clean = $clean.Split("@")[0] }
    $clean = $clean.Trim().TrimEnd([char]36)
    if ($clean.Length -lt 2) { return $rows }

    $escaped = Escape-LdapValue -Value $clean
    if ($Kind -eq "Machine") {
        $category = "(objectCategory=computer)"
        $clauses = "(name=$escaped*)(sAMAccountName=$escaped*)(dNSHostName=$escaped*)(description=*$escaped*)"
        $props = @("name","dNSHostName","description","operatingSystem","distinguishedName")
    }
    else {
        $category = "(&(objectCategory=person)(objectClass=user))"
        $clauses = "(sAMAccountName=$escaped*)(name=$escaped*)(displayName=*$escaped*)(mail=$escaped*)"
        $props = @("name","sAMAccountName","displayName","mail","description","distinguishedName")
    }

    $searcher = $null
    $collection = $null
    try {
        $searcher = New-LdapSearcher -BaseDn ([string]$script:Conn.BaseDn) -Filter "(&$category(|$clauses))" -Properties $props -Scope "Subtree" -Limit $Limit
        # Le selecteur s ouvre en fenetre modale : la recherche est bornee
        # pour ne jamais tenir l interface plus de quelques secondes.
        try { $searcher.ServerTimeLimit = [TimeSpan]::FromSeconds(8) } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaPickerObjects' $_ }
        try { $searcher.ClientTimeout = [TimeSpan]::FromSeconds(10) } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaPickerObjects' $_ }
        $collection = $searcher.FindAll()
        # PF-02: the paged collection is enumerated as it arrives; @() would read every page before the first row.
        foreach ($r in $collection) {
            $p = $r.Properties
            $name = ""
            $second = ""
            $description = ""
            try { $name = [string]@($p["name"])[0] } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaPickerObjects' $_ }
            try { $description = [string]@($p["description"])[0] } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaPickerObjects' $_ }
            if ($Kind -eq "Machine") {
                try { $second = [string]@($p["dnshostname"])[0] } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaPickerObjects' $_ }
                if ([string]::IsNullOrWhiteSpace($second)) { try { $second = [string]@($p["operatingsystem"])[0] } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaPickerObjects' $_ } }
            }
            else {
                try { $second = [string]@($p["samaccountname"])[0] } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaPickerObjects' $_ }
                if ([string]::IsNullOrWhiteSpace($description)) { try { $description = [string]@($p["displayname"])[0] } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaPickerObjects' $_ } }
            }
            $dn = ""
            try { $dn = [string]@($p["distinguishedname"])[0] } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaPickerObjects' $_ }
            if ([string]::IsNullOrWhiteSpace($name)) { continue }
            $rows.Add([pscustomobject]@{ Name=$name; Second=$second; Description=$description; DN=$dn })
        }
    }
    finally {
        if ($null -ne $collection) { try { $collection.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaPickerObjects' $_ } }
        if ($null -ne $searcher) { try { $searcher.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaPickerObjects' $_ } }
    }
    return $rows
}

function Show-DomeniaObjectPicker {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][ValidateSet('Machine','Utilisateur')][string]$Kind,
        [string]$Title='', [string]$Prompt='', [string]$InitialTerm='')
    if (-not $Title) { $Title=if($Kind -eq 'Machine'){'Choisir un poste'}else{'Choisir un utilisateur'} }
    if (-not $Prompt) { $Prompt='Rechercher dans le domaine, choisir une ligne puis valider. Aucune sonde de poste.' }
    return (Show-DomeniaInlinePicker -Kind $Kind -Title $Title -Prompt $Prompt -InitialTerm $InitialTerm)
}


# =====================================================================
# Selecteur d unite d organisation pour les deplacements de postes.
# Aucune cible n est memorisee dans l interface : chaque deplacement
# choisit explicitement sa destination, puis affiche une confirmation.
# =====================================================================
function Get-DomeniaParentDn {
    param([string]$Dn)
    if ([string]::IsNullOrWhiteSpace($Dn)) { return "" }
    $escaped = $false
    for ($i = 0; $i -lt $Dn.Length; $i++) {
        $ch = $Dn[$i]
        if ($escaped) { $escaped = $false; continue }
        if ($ch -eq [char]92) { $escaped = $true; continue }
        if ($ch -eq ',') { return $Dn.Substring($i + 1) }
    }
    return ""
}

function Search-DomeniaOuPickerObjects {
    param([AllowEmptyString()][string]$Term = "",[int]$Limit = 250)
    $rows = New-Object System.Collections.Generic.List[object]
    $clean = ([string]$Term).Trim()
    $filter = "(objectClass=organizationalUnit)"
    if (-not [string]::IsNullOrWhiteSpace($clean) -and $clean -ne "*") {
        $escaped = Escape-LdapValue -Value $clean
        $filter = "(&(objectClass=organizationalUnit)(name=*$escaped*))"
    }

    $searcher = $null
    $collection = $null
    try {
        $searcher = New-LdapSearcher -BaseDn ([string]$script:Conn.BaseDn) -Filter $filter -Properties @("name","distinguishedName") -Scope "Subtree" -Limit $Limit
        try { $searcher.ServerTimeLimit = [TimeSpan]::FromSeconds(10) } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaOuPickerObjects' $_ }
        try { $searcher.ClientTimeout = [TimeSpan]::FromSeconds(12) } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaOuPickerObjects' $_ }
        $collection = $searcher.FindAll()
        # PF-02: direct enumeration of the paged collection, bounded by SizeLimit ($Limit).
        foreach ($r in $collection) {
            $name = [string](Get-PropFirst $r.Properties "name" "")
            $dn = [string](Get-PropFirst $r.Properties "distinguishedname" "")
            if ([string]::IsNullOrWhiteSpace($dn)) { continue }
            [void]$rows.Add([pscustomobject]@{ Name=$name; DN=$dn })
        }
    }
    finally {
        if ($null -ne $collection) { try { $collection.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaOuPickerObjects' $_ } }
        if ($null -ne $searcher) { try { $searcher.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaOuPickerObjects' $_ } }
    }
    return @($rows | Sort-Object Name,DN)
}

function Show-DomeniaOuPicker {
    # Point 54: the shared OU picker opens on the current OU of the object; the move itself is confirmed later.
    param([string]$ObjectName,[string]$CurrentParentDn,[string]$ObjectLabel='Poste')
    return (Show-DomeniaInlinePicker -Kind OU -Title 'Choisir la nouvelle OU' -Prompt (
        $ObjectLabel+' : '+$ObjectName+"`r`nOU actuelle : "+$CurrentParentDn+"`r`nRecherchez une OU puis confirmez. Le déplacement n'est pas lancé par cette sélection.") -Purpose 'Effet : aucun déplacement ici ; il sera confirmé séparément.' -InitialDn $CurrentParentDn)
}

function Move-DomeniaSelectedComputerWithOuPicker {
    # FI-20 (L20): the move is planned from the identity of the visible selection, DN and GUID captured before the OU
    # picker: the selected result row on Rechercher, the workstation actually loaded on its fiche (button of the
    # « Compte AD » card, A-REVOIR X01). No wait for a fiche and no nested message pump: the plan is refused if the
    # selection changed while the OU was chosen, and the worker reads the object again on the controller and refuses
    # another GUID before moving it.
    try {
        Assert-WriteAllowed
        $rowIdentity = Get-DomeniaCurrentSelectionIdentity
        if ($null -eq $rowIdentity) { throw "Poste sans identité exacte (domaine et GUID) : relancez la recherche ou rouvrez sa fiche, puis réessayez." }
        if ([string]$rowIdentity.Type -ne "Machine") { throw "Sélectionnez un ordinateur." }
        $dn = [string]$rowIdentity.DN
        if ([string]::IsNullOrWhiteSpace($dn)) { throw "DN du poste introuvable." }
        $currentParent = Get-DomeniaParentDn -Dn $dn
        $picked = Show-DomeniaOuPicker -ObjectName ([string]$rowIdentity.Name) -CurrentParentDn $currentParent
        if ($null -eq $picked) { return }
        $targetDn = [string]$picked.DN
        if ([string]::IsNullOrWhiteSpace($targetDn)) { return }
        if ($targetDn -ieq $currentParent) { Set-Status "Le poste est déjà dans cette OU. Aucune écriture AD."; return }
        Move-SelectedObject -TargetDn $targetDn -RowIdentity $rowIdentity
    }
    catch { Show-ErrorBox "Déplacement impossible : $($_.Exception.Message)" }
}

function Move-DomeniaSelectedUserWithOuPicker {
    # UX-05 : le chemin de l'OU de destination ne se tape plus. Le poste a son selecteur depuis le menu
    # de l'arbre ; la fiche du compte l'emploie aussi. L'ecriture reste celle, unique, de
    # Move-SelectedObject : verification de fraicheur, plan, confirmation, controle du DN cible.
    try {
        Assert-WriteAllowed
        $o = $script:SelectedObject
        if ($null -eq $o -or [string]$o.Type -ne "Utilisateur") { throw "Selectionne un utilisateur dans la liste." }
        $dn = [string]$o.DN
        $name = [string]$o.Name
        if ([string]::IsNullOrWhiteSpace($dn)) { throw "DN du compte introuvable." }
        $currentParent = Get-DomeniaParentDn -Dn $dn
        $picked = Show-DomeniaOuPicker -ObjectName $name -CurrentParentDn $currentParent -ObjectLabel 'Utilisateur'
        if ($null -eq $picked) { return }
        $targetDn = [string]$picked.DN
        if ([string]::IsNullOrWhiteSpace($targetDn)) { return }
        if ($targetDn -ieq $currentParent) { Set-Status "Le compte est déjà dans cette OU. Aucune écriture AD."; return }
        Move-SelectedObject -TargetDn $targetDn
    }
    catch { Show-ErrorBox "Déplacement impossible : $($_.Exception.Message)" }
}

function Get-DomeniaManagerControls {
    param([Parameter(Mandatory=$true)][ValidateSet('Utilisateur','Machine')][string]$Target)
    # Une seule carte pour les deux fiches : le nom se montre, le DN ne vit que dans la variable script.
    if ($Target -eq 'Utilisateur') {
        return [pscustomobject]@{Txt='TxtUserManager'; Pick='BtnUserManagerPick'; Open='BtnUserManagerOpen'; Clear='BtnUserManagerClear'}
    }
    return [pscustomobject]@{Txt='TxtCompManagedBy'; Pick='BtnCompManagedByPick'; Open='BtnCompManagedByOpen'; Clear='BtnCompManagedByClear'}
}

function Get-DomeniaManagerDn {
    param([Parameter(Mandatory=$true)][ValidateSet('Utilisateur','Machine')][string]$Target)
    if ($Target -eq 'Utilisateur') { return [string]$script:UserManagerDn }
    return [string]$script:CompManagedByDn
}

function Set-DomeniaManagerField {
    # UX-14 : la fiche affiche un nom, jamais un DN. Le DN choisi reste la seule valeur transmise a
    # l'ecriture ; Ouvrir et Retirer ne paraissent que quand un responsable est pose.
    param([Parameter(Mandatory=$true)][ValidateSet('Utilisateur','Machine')][string]$Target,[AllowEmptyString()][string]$Dn='')
    $dn = [string]$Dn
    if ($Target -eq 'Utilisateur') { $script:UserManagerDn = $dn } else { $script:CompManagedByDn = $dn }
    $nom = ''
    if ($dn) { $nom = [string](Get-DomeniaCnFromDn $dn); if (-not $nom) { $nom = $dn } }
    $c = Get-DomeniaManagerControls -Target $Target
    try { $script:Ctrl[$c.Txt].Text = $nom } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaManagerField' $_ }
    $visible = if ($dn) { 'Visible' } else { 'Collapsed' }
    try { $script:Ctrl[$c.Open].Visibility = $visible } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaManagerField' $_ }
    try { $script:Ctrl[$c.Clear].Visibility = $visible } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaManagerField' $_ }
}

function Show-DomeniaManagerPicker {
    # Le responsable se cherche dans le domaine, il ne se tape pas : c'est le selecteur commun, en kind
    # Utilisateur, recherche declenchee sur Entree ou sur le bouton. Le choix reste local, l'ecriture
    # se fait a l'enregistrement de la fiche, avec le controle de fraicheur et la confirmation usuels.
    param([Parameter(Mandatory=$true)][ValidateSet('Utilisateur','Machine')][string]$Target)
    try {
        Assert-WriteAllowed
        $actuel = Get-DomeniaManagerDn -Target $Target
        $titre = if ($Target -eq 'Utilisateur') { 'Choisir le responsable du compte' } else { 'Choisir le responsable du poste' }
        $picked = Show-DomeniaObjectPicker -Kind Utilisateur -Title $titre -Prompt (
            'Recherchez un utilisateur par nom, puis confirmez. Le responsable choisi reste local : il ne sera écrit dans l' + [string][char]0x02BC + 'annuaire qu' + [string][char]0x02BC + 'à l' + [string][char]0x02BC + 'enregistrement.')
        if ($null -eq $picked) { return }
        $nouveau = [string]$picked.DN
        if ([string]::IsNullOrWhiteSpace($nouveau)) { return }
        if ($nouveau -ieq $actuel) { Set-Status 'Le responsable choisi est déjà celui de la fiche. Aucune modification.'; return }
        Set-DomeniaManagerField -Target $Target -Dn $nouveau
        Set-Status ('Responsable choisi : ' + [string]$picked.Name + '. Enregistrez la fiche pour l' + [string][char]0x02BC + 'écrire dans l' + [string][char]0x02BC + 'annuaire.')
    }
    catch { Show-ErrorBox "Choix du responsable impossible : $($_.Exception.Message)" }
}

function Clear-DomeniaManagerSelection {
    # Retirer le responsable reste possible : c'est la valeur vide, ecrite plus tard, pas une suppression immediate.
    param([Parameter(Mandatory=$true)][ValidateSet('Utilisateur','Machine')][string]$Target)
    try {
        Assert-WriteAllowed
        if (-not (Get-DomeniaManagerDn -Target $Target)) { return }
        Set-DomeniaManagerField -Target $Target -Dn ''
        Set-Status ('Responsable retiré de la fiche. Enregistrez pour effacer la valeur dans l' + [string][char]0x02BC + 'annuaire.')
    }
    catch { Show-ErrorBox "Retrait du responsable impossible : $($_.Exception.Message)" }
}

function Open-DomeniaManagerObject {
    param([Parameter(Mandatory=$true)][ValidateSet('Utilisateur','Machine')][string]$Target)
    try {
        $dn = Get-DomeniaManagerDn -Target $Target
        if ([string]::IsNullOrWhiteSpace($dn)) { Set-Status 'Aucun responsable sur cette fiche.' 'WARN'; return }
        Open-AdObject -Dn $dn -Type 'Utilisateur'
    }
    catch { Show-ErrorBox "Ouverture du responsable impossible : $($_.Exception.Message)" }
}


function Add-SelectedLink {
    # Aucune fenêtre de sélection : l'association se prépare dans le panneau Ajouter de Relations (UI-09).
    try {
        if(Test-DomeniaAccessBusyWrite){return}
        $s=Get-DomeniaRelationsSubject
        if($null -eq $s -and $null -ne $script:SelectedObject){Set-DomeniaRelationsSelection -Object $script:SelectedObject;$s=Get-DomeniaRelationsSubject}
        if($null -eq $s){Set-Status 'Sélectionnez un utilisateur ou un poste dans Rechercher avant dʼassocier.' 'WARN';return}
        # D041: a workstation is a subject too (search for the user in the page).
        if($s.Type -notin @('Utilisateur','Machine')){Set-Status 'Seul un utilisateur ou un poste peut porter des associations.' 'INFO';return}
        $workspace=Get-DomeniaControl 'WorkspaceTabs';$relations=Get-DomeniaControl 'TabRelations';if($null -ne $workspace -and $null -ne $relations){$workspace.SelectedItem=$relations}
        Show-DomeniaRelationsAddPanel -Mode Search
        $box=Get-DomeniaControl 'TxtRelationComputerSearch';if($null -ne $box){[void]$box.Focus()}
        if($s.Type -eq 'Machine'){Set-Status ('Association pour le poste '+$s.Name+' : lisez sa session ou recherchez lʼutilisateur dans le panneau Ajouter.')}
        else{Set-Status ('Association de poste pour '+$s.Login+' : détectez un poste ou recherchez-le dans le panneau Ajouter.')}
    }
    catch { Set-Status ('Association : '+$_.Exception.Message) 'ERROR' }
}

function Import-LinksCsv {
    # CO-08: the chosen file is shown in Relations > Toutes les associations before any change (Show-DomeniaLinkImportPreview).
    # Points 137-138: the format chosen in « Format de lʼimport » (CSV générique, export GLPI, résultats osquery) selects the
    # adapter and imposes the source (Import CSV, Import GLPI, Import osquery). Rows are imported only after « Importer »,
    # as one rollback batch that « Annuler lʼimport » removes, even after a restart.
    try {
        if (Test-DomeniaAccessBusyWrite) { return }
        $adapter = Get-DomeniaInventoryAdapter (Get-DomeniaLinkImportAdapterChoice)
        $dlg = New-DomeniaFileRequest -Mode Open
        $dlg.Filter = [string]$adapter.FileFilter + "|Tous les fichiers (*.*)|*.*"
        if (-not $dlg.ShowDialog()) { return }
        Show-DomeniaLinkImportPreview -Path ([string]$dlg.FileName) -Adapter ([string]$adapter.Id)
    }
    catch { Show-ErrorBox ("Import impossible : " + $_.Exception.Message) }
}



