$script:WorkerCommon = @'
# BEGIN generated LDAP text rules: tools/sync_worker_ldap_rules.py from modules/Domenia-Search.Model.ps1. Do not edit here.
function Escape-WLdap {
    param([AllowEmptyString()][AllowNull()][string]$Value,[switch]$KeepWildcard)
    $builder = [Text.StringBuilder]::new()
    $previousWildcard = $false
    foreach ($character in ([string]$Value).ToCharArray()) {
        $wildcard = $false
        switch ([int]$character) {
            0  { [void]$builder.Append('\00') }
            40 { [void]$builder.Append('\28') }
            41 { [void]$builder.Append('\29') }
            42 {
                if ($KeepWildcard) { $wildcard = $true; if (-not $previousWildcard) { [void]$builder.Append('*') } }
                else { [void]$builder.Append('\2a') }
            }
            92 { [void]$builder.Append('\5c') }
            default { [void]$builder.Append($character) }
        }
        $previousWildcard = $wildcard
    }
    return $builder.ToString()
}
function ConvertTo-WAdsPathDn {
    param([AllowEmptyString()][AllowNull()][string]$Dn)
    $text = [string]$Dn
    if ($text.IndexOf([char]47) -lt 0) { return $text }
    $builder = [Text.StringBuilder]::new($text.Length + 8)
    $i = 0
    while ($i -lt $text.Length) {
        $c = $text[$i]
        if (($c -eq [char]92) -and (($i + 1) -lt $text.Length)) { [void]$builder.Append($c).Append($text[$i + 1]); $i += 2; continue }
        if ($c -eq [char]47) { [void]$builder.Append([char]92) }
        [void]$builder.Append($c)
        $i++
    }
    return $builder.ToString()
}
# END generated LDAP text rules
function Get-WLdapPath {
    param($Context, [string]$Dn)
    if ([string]::IsNullOrWhiteSpace($Dn)) { $Dn = [string]$Context.BaseDn }
    # CO-33: a '/' inside an RDN value is written '\/' in the ADsPath (generated copy of the Search.Model rule).
    $Dn = ConvertTo-WAdsPathDn $Dn
    if ([string]::IsNullOrWhiteSpace([string]$Context.Server)) { return "LDAP://$Dn" }
    return "LDAP://$($Context.Server)/$Dn"
}
function Get-WDirectoryBindUser {
    param($Context)
    # BindUser est l'identite effectivement validee au login. Toujours la
    # privilegier au UserName historique du PSCredential recu depuis l'UI.
    try {
        if (-not [string]::IsNullOrWhiteSpace([string]$Context.BindUser)) {
            return ([string]$Context.BindUser).Trim()
        }
    }
    catch { }
    try {
        if ($null -ne $Context.Credential -and -not [string]::IsNullOrWhiteSpace([string]$Context.Credential.UserName)) {
            return ([string]$Context.Credential.UserName).Trim()
        }
    }
    catch { }
    return ""
}
function New-WEntry {
    param($Context, [string]$Dn)
    $path = Get-WLdapPath $Context $Dn
    Set-WCredentialAttemptIdentity -Context $Context -Credential $Context.Credential -Channel Directory -UserName $(if($Context.UseCredential){Get-WDirectoryBindUser $Context}else{[string]$Context.ProcessIdentity})
    $lease=Enter-WCredentialAttempt -Context $Context -Channel Directory
    $entry=$null
    try {
        Assert-WCredentialAllowed -Context $Context -Channel Directory
        if (-not [bool]$Context.UseCredential) {
            $entry=New-Object System.DirectoryServices.DirectoryEntry -ArgumentList @($path)
        }else{
            if ($null -eq $Context.Credential) { throw "Credential AD explicite absent du contexte worker." }
            $bindUser=Get-WDirectoryBindUser $Context
            if ([string]::IsNullOrWhiteSpace($bindUser)) { $bindUser=[string]$Context.Credential.UserName }
            # SE-16: DirectoryEntry only accepts the session password as a String, an immutable copy that stays in memory
            # until the garbage collector reclaims it (no assignment can erase it). It is made here, at the last moment,
            # handed to the Windows API at once and never kept in a variable, logged or returned.
            $entry=New-Object System.DirectoryServices.DirectoryEntry -ArgumentList @($path,$bindUser,$Context.Credential.GetNetworkCredential().Password,[System.DirectoryServices.AuthenticationTypes]::Secure)
        }
        # DirectoryEntry is lazy. Force its first bind before releasing this account's authentication lease.
        [void]$entry.psbase.get_NativeObject()
        return $entry
    }catch{
        [void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Directory)
        if($null -ne $entry){try{$entry.Dispose()}catch{}}
        throw
    }finally{Exit-WCredentialAttempt -Lease $lease}
}
function Get-WDirectoryVersionSource {
    param($Context)
    $root=$null;$entry=$null
    try{
        $root=New-WRootDse $Context;$root.psbase.RefreshCache(@('dnsHostName','dsServiceName'))
        $props=$root.psbase.get_Properties();$server=[string]$props.get_Item('dnsHostName').Value;$service=[string]$props.get_Item('dsServiceName').Value
        if(-not $service -or -not $server){throw 'Metadonnees du controleur inaccessibles.'}
        $entry=New-WEntry $Context $service;$entry.psbase.RefreshCache(@('invocationId'))
        $bytes=$entry.psbase.get_Properties().get_Item('invocationId').Value
        $id=Convert-WGuid $bytes;if(-not $id){throw 'Instance du controleur non lue.'}
        return $server+'|'+$id
    }catch{
        # Unknown instance cannot validate equality with an earlier USN.
        if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Directory){throw}
        return ([string]$Context.Server+'|unknown-'+[guid]::NewGuid().ToString('N'))
    }finally{if($null -ne $entry){$entry.Dispose()};if($null -ne $root){$root.Dispose()}}
}
function New-WRootDse {
    param($Context)
    $path = if ([string]::IsNullOrWhiteSpace([string]$Context.Server)) { "LDAP://RootDSE" } else { "LDAP://$($Context.Server)/RootDSE" }
    Set-WCredentialAttemptIdentity -Context $Context -Credential $Context.Credential -Channel Directory -UserName $(if($Context.UseCredential){Get-WDirectoryBindUser $Context}else{[string]$Context.ProcessIdentity})
    $lease=Enter-WCredentialAttempt -Context $Context -Channel Directory
    $entry=$null
    try {
        Assert-WCredentialAllowed -Context $Context -Channel Directory
        if (-not [bool]$Context.UseCredential) {
            $entry=New-Object System.DirectoryServices.DirectoryEntry -ArgumentList @($path)
        }else{
            if ($null -eq $Context.Credential) { throw "Credential AD explicite absent du contexte worker." }
            $bindUser=Get-WDirectoryBindUser $Context
            if ([string]::IsNullOrWhiteSpace($bindUser)) { $bindUser=[string]$Context.Credential.UserName }
            # SE-16: DirectoryEntry only accepts the session password as a String, an immutable copy that stays in memory
            # until the garbage collector reclaims it (no assignment can erase it). It is made here, at the last moment,
            # handed to the Windows API at once and never kept in a variable, logged or returned.
            $entry=New-Object System.DirectoryServices.DirectoryEntry -ArgumentList @($path,$bindUser,$Context.Credential.GetNetworkCredential().Password,[System.DirectoryServices.AuthenticationTypes]::Secure)
        }
        # DirectoryEntry is lazy. Force its first bind before releasing this account's authentication lease.
        [void]$entry.psbase.get_NativeObject()
        return $entry
    }catch{
        [void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Directory)
        if($null -ne $entry){try{$entry.Dispose()}catch{}}
        throw
    }finally{Exit-WCredentialAttempt -Lease $lease}
}
function New-WSearcher {
    param($Context, [string]$BaseDn, [string]$Filter, [string[]]$Properties, [string]$Scope = "OneLevel", [int]$Limit = 0)
    $root = New-WEntry $Context $BaseDn
    $s = New-Object System.DirectoryServices.DirectorySearcher -ArgumentList $root
    $s.Filter = $Filter
    $s.SearchScope = if ($Scope -eq "Subtree") { [System.DirectoryServices.SearchScope]::Subtree } elseif ($Scope -eq "Base") { [System.DirectoryServices.SearchScope]::Base } else { [System.DirectoryServices.SearchScope]::OneLevel }
    $page = [int]$Context.PageSize
    if ($page -lt 1) { $page = 300 }
    $s.PageSize = $page
    if ($Limit -gt 0) { $s.SizeLimit = $Limit }
    $s.ServerTimeLimit = [System.TimeSpan]::FromSeconds(25)
    $s.ClientTimeout = [System.TimeSpan]::FromSeconds(30)
    foreach ($p in @($Properties)) { if (-not [string]::IsNullOrWhiteSpace([string]$p)) { [void]$s.PropertiesToLoad.Add([string]$p) } }
    return $s
}
function Get-WPropFirst {
    param($Props, [string]$Name, $Default = "")
    if ($null -ne $Props -and $Props.Contains($Name) -and $Props[$Name].Count -gt 0) {
        $value=$Props[$Name][0]
        if ($value -is [byte[]]) { return ,$value }
        return $value
    }
    return $Default
}
function Get-WPropAll {
    param($Props, [string]$Name)
    $r = New-Object System.Collections.ArrayList
    try { if ($Props.Contains($Name)) { foreach ($v in $Props[$Name]) { [void]$r.Add($v) } } } catch { }
    return @($r)
}
function Convert-WLargeInteger {
    param($Value)
    if ($null -eq $Value) { return 0L }
    if ($Value -is [int64] -or $Value -is [int]) { return [int64]$Value }
    try {
        # A genuine ADSI IADsLargeInteger exposes no member to PowerShell 5.1: read it through IDispatch first.
        $type = $Value.GetType()
        try {
            $high = $type.InvokeMember('HighPart',[Reflection.BindingFlags]::GetProperty,$null,$Value,$null)
            $low = $type.InvokeMember('LowPart',[Reflection.BindingFlags]::GetProperty,$null,$Value,$null)
        } catch { $high = $Value.HighPart; $low = $Value.LowPart }
        if ($null -eq $high -or $null -eq $low) { return 0L }
        $high = [int64]$high
        $low = [int64]$low
        if ($low -lt 0) { $low += 4294967296 }
        return (($high -shl 32) -bor $low)
    } catch { return 0L }
}
function Convert-WFileTime {
    param($Value)
    $i = Convert-WLargeInteger $Value
    if ($i -le 0 -or $i -eq 9223372036854775807) { return "Jamais" }
    try { return [System.DateTime]::FromFileTimeUtc($i).ToLocalTime().ToString("dd/MM/yyyy HH:mm:ss") } catch { return "" }
}
function Convert-WDate {
    param($Value)
    if ($null -eq $Value -or [string]::IsNullOrWhiteSpace([string]$Value)) { return "" }
    try { return ([System.DateTime]$Value).ToString("dd/MM/yyyy HH:mm:ss") } catch { return [string]$Value }
}
function Convert-WGuid {
    param($Value)
    try {
        if ($Value -is [guid]) { return $Value.ToString('D') }
        if ($Value -is [array]) {
            if ($Value.Count -ne 16) { return '' }
            foreach($part in $Value) {
                if ($part -isnot [byte] -and $part -isnot [int] -and $part -isnot [long]) { return '' }
                if ([long]$part -lt 0 -or [long]$part -gt 255) { return '' }
            }
            return ([guid]::new([byte[]]$Value)).ToString('D')
        }
        $parsed=[guid]::Empty
        if ([guid]::TryParse([string]$Value,[ref]$parsed)) { return $parsed.ToString('D') }
    } catch { }
    return ''
}
function Convert-WSid {
    param($Value)
    try { if ($Value -is [byte[]]) { return (New-Object System.Security.Principal.SecurityIdentifier -ArgumentList @($Value,0)).Value }; return [string]$Value } catch { return "" }
}
function Get-WObjectType {
    param($Props)
    $classes = @((Get-WPropAll $Props "objectclass") | ForEach-Object { ([string]$_).ToLowerInvariant() })
    if ($classes -contains "computer") { return "Machine" }
    if ($classes -contains "user") { return "Utilisateur" }
    if ($classes -contains "group") { return "Groupe" }
    if ($classes -contains "organizationalunit") { return "OU" }
    if ($classes -contains "container" -or $classes -contains "builtindomain") { return "Conteneur" }
    return "Objet"
}
function Get-WUacState {
    param($Value, $Lockout = $null, $Computed = $null)
    if ($null -eq $Value -or [string]::IsNullOrWhiteSpace([string]$Value)) { return 'Etat non determine' }
    $u=0L
    if (-not [long]::TryParse([string]$Value,[ref]$u)) { return 'Etat non determine' }
    $label=if (($u -band 2) -ne 0) { 'Desactive' } else { 'Actif' }
    $c=0L
    if ($null -ne $Computed -and [long]::TryParse([string]$Computed,[ref]$c)) {
        if (($c -band 16) -ne 0) { $label+=' / Verrouille' }
        if (($c -band 8388608) -ne 0) { $label+=' / Mot de passe expire' }
    } elseif ((Convert-WLargeInteger $Lockout) -gt 0) { $label+=' / Verrouillage a verifier' }
    return $label
}
function New-WBranchRow {
    param($Result)
    $p = $Result.Properties
    $type = Get-WObjectType $p
    $upn = [string](Get-WPropFirst $p "userprincipalname" "")
    $login = [string](Get-WPropFirst $p "samaccountname" "")
    if ($type -eq "Machine") {
        $upn = [string](Get-WPropFirst $p "dnshostname" "")
        # Masquage visuel uniquement du suffixe "$" reserve aux comptes ordinateurs.
        $login = $login.TrimEnd([char]36)
    }
    [pscustomobject]@{
        Type = $type
        Name = [string](Get-WPropFirst $p "name" "")
        Login = $login
        UPN = $upn
        State = Get-WUacState (Get-WPropFirst $p 'useraccountcontrol' $null) (Get-WPropFirst $p 'lockouttime' $null) (Get-WPropFirst $p 'msds-user-account-control-computed' $null)
        OS = [string](Get-WPropFirst $p "operatingsystem" "")
        LastLogon = Convert-WFileTime (Get-WPropFirst $p "lastlogontimestamp" 0)
        Mail = [string](Get-WPropFirst $p "mail" "")
        Description = [string](Get-WPropFirst $p "description" "")
        Changed = Convert-WDate (Get-WPropFirst $p "whenchanged" "")
        DN = [string](Get-WPropFirst $p "distinguishedname" "")
    }
}
function Convert-WDirectoryValue {
    param([string]$Name, $Value)
    if ($null -eq $Value) { return "" }
    if ($Value -is [byte[]]) {
        if ($Name -ieq "objectGUID") { return Convert-WGuid $Value }
        if ($Name -ieq "objectSid" -or $Name -ieq "tokenGroups") { return Convert-WSid $Value }
        return [System.BitConverter]::ToString($Value)
    }
    if ($Value.GetType().FullName -eq "System.__ComObject") { return Convert-WLargeInteger $Value }
    return $Value
}
function Get-WAllProperties {
    param($Entry,[string[]]$PropertyNames=@())
    $h=@{};$requested=@($PropertyNames|Where-Object{-not [string]::IsNullOrWhiteSpace($_)}|Select-Object -Unique)
    if(-not $requested.Count){throw 'Liste explicite de proprietes AD requise.'}
    # PF-27 : les appartenances sont relues par plages plus bas ; les demander ici les telechargerait deux fois.
    $initial=@($requested|Where-Object{$_ -notin @('member','memberOf')})
    if(-not $initial.Count){$initial=@('distinguishedName')}
    Assert-WCredentialAllowed -Context $Context -Channel Directory
    $Entry.psbase.RefreshCache([string[]]$initial)
    $properties=$Entry.psbase.get_Properties()
    if($null -eq $properties){throw 'Collection AD indisponible.'}
    foreach($name in $requested){
        if($name -in @('member','memberOf')){continue}
        $vals=[Collections.Generic.List[object]]::new()
        foreach($v in $properties.get_Item([string]$name)){if($null -ne $v){$vals.Add((Convert-WDirectoryValue ([string]$name) $v))}}
        if($vals.Count){$h[[string]$name]=$vals.ToArray()}
    }
    foreach($attribute in @('member','memberOf')){
        if($requested -notcontains $attribute){continue}
        $values=[Collections.Generic.List[object]]::new();$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        $start=0;$complete=$false;$reason='';$watch=[Diagnostics.Stopwatch]::StartNew()
        try {
            for($page=0;$page -lt 64;$page++){
                if($watch.Elapsed.TotalSeconds -gt 10 -or $values.Count -ge 50000){$reason='Limite de temps ou de volume atteinte.';break}
                $range=$attribute+';range='+$start+'-'+($start+1499)
                Assert-WCredentialAllowed -Context $Context -Channel Directory
                $Entry.psbase.RefreshCache([string[]]@($range))
                $properties=$Entry.psbase.get_Properties();$returned=''
                foreach($n in $properties.PropertyNames){if([string]$n -match ('^(?i:'+[regex]::Escape($attribute)+');range='+$start+'-(\*|\d+)$')){$returned=[string]$n;break}}
                if(-not $returned){
                    if($start -eq 0 -and $properties.Contains($attribute)){$returned=$attribute;$complete=$true}
                    elseif($start -eq 0){$complete=$true;break}
                    else{$reason='Plage demandee non renvoyee.';break}
                }
                foreach($v in $properties.get_Item($returned)){
                    if($values.Count -ge 50000){$complete=$false;$reason='Resultat tronque a 50000 valeurs.';break}
                    if($null -ne $v -and $seen.Add([string]$v)){$values.Add([string]$v)}
                }
                if($returned -eq $attribute -or $returned.EndsWith('-*')){$complete=($reason -eq '');break}
                if($returned -match ';range=(\d+)-(\d+)$'){$next=[int]$Matches[2]+1;if($next -le $start){throw 'Plage AD non progressive.'};$start=$next}else{throw 'Plage AD non reconnue.'}
            }
        }catch{
            if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Directory){throw}
            $complete=$false;$reason='Lecture des appartenances partielle : '+$_.Exception.Message
        }
        $h[$attribute]=$values.ToArray();$h['__'+$attribute+'Complete']=@($complete);$h['__'+$attribute+'Note']=@($reason)
    }
    return $h
}

function Get-WAdCredential {
    param($Context)
    Set-WCredentialAttemptIdentity -Context $Context -Credential $Context.Credential -Channel Directory -UserName $(if($Context.UseCredential){Get-WDirectoryBindUser $Context}else{[string]$Context.ProcessIdentity})
    Assert-WCredentialAllowed -Context $Context -Channel Directory
    if (-not [bool]$Context.UseCredential -or $null -eq $Context.Credential) { return $null }
    $bindUser = Get-WDirectoryBindUser $Context
    if ([string]::IsNullOrWhiteSpace($bindUser) -or [string]$Context.Credential.UserName -ieq $bindUser) { return $Context.Credential }
    try { return New-Object System.Management.Automation.PSCredential -ArgumentList @($bindUser,$Context.Credential.Password) }
    catch { return $Context.Credential }
}
function Get-WRemoteAdminCredential {
    param($Context)
    $credential=$null
    if ($null -ne $Context.RemoteAdminCredential) {
        $user = ([string]$Context.RemoteAdminUser).Trim()
        if ([string]::IsNullOrWhiteSpace($user)) { $user = [string]$Context.RemoteAdminCredential.UserName }
        $credential=$Context.RemoteAdminCredential
        if ([string]$credential.UserName -ine $user) {$credential=New-Object System.Management.Automation.PSCredential -ArgumentList @($user,$credential.Password)}
    }elseif ($null -ne $script:RemoteAdminCredential) {$credential=$script:RemoteAdminCredential}
    elseif ([bool]$Context.UseCredential -and $null -ne $Context.Credential) {$credential=$Context.Credential}
    Set-WCredentialAttemptIdentity -Context $Context -Credential $credential -Channel Remote -Target ([string]$Context.CredentialTarget)
    Assert-WCredentialAllowed -Context $Context -Channel Remote
    return $credential
}
function Get-WMachineCredential {
    param($Context)
    # The same selected identity is used for CIM, PsExec, ADMIN$ and schtasks.
    if ($null -eq $Context.MachineCredential) { return (Get-WRemoteAdminCredential $Context) }
    Set-WCredentialAttemptIdentity -Context $Context -Credential $Context.MachineCredential -Channel Remote -Target ([string]$Context.CredentialTarget)
    Assert-WCredentialAllowed -Context $Context -Channel Remote
    return $Context.MachineCredential
}
function New-WDomeniaCimSession {
    param($Context,[string]$Computer,$Credential,[int]$TimeoutSeconds=20)
    if ([string]::IsNullOrWhiteSpace($Computer)) { throw 'Nom de machine vide pour la session CIM.' }
    Set-WCredentialAttemptIdentity -Context $Context -Credential $Credential -Channel Remote -Target $Computer
    $failures = New-Object 'System.Collections.Generic.List[string]'
    foreach ($protocol in @('Dcom','Wsman')) {
        if ($protocol -eq 'Wsman' -and -not [bool]$Context.UseWinRM) { continue }
        Assert-WCredentialAllowed -Context $Context -Channel Remote
        $authLease=Enter-WCredentialAttempt -Context $Context -Channel Remote;$opened=$null
        try {
            $option = New-CimSessionOption -Protocol $protocol -ErrorAction Stop
            $parameters = @{ComputerName=$Computer;SessionOption=$option;ErrorAction='Stop'}
            if ($null -ne $Credential) { $parameters['Credential']=$Credential }
            $command = Get-Command New-CimSession -ErrorAction Stop
            if ($command.Parameters.ContainsKey('OperationTimeoutSec')) { $parameters['OperationTimeoutSec']=[Math]::Max(2,$TimeoutSeconds) }
            $opened=New-CimSession @parameters
            # DCOM opens lazily: the first authenticated read must still hold the account lease.
            [void](Get-CimInstance -CimSession $opened -ClassName Win32_OperatingSystem -Property CSName -OperationTimeoutSec ([Math]::Max(2,$TimeoutSeconds)) -ErrorAction Stop)
            return $opened
        }
        catch {
            if($null -ne $opened){try{Remove-CimSession -CimSession $opened -ErrorAction Ignore}catch{}}
            if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw}
            $failures.Add(($protocol+' : '+[string]$_.Exception.Message))
        }
        finally {Exit-WCredentialAttempt $authLease}
    }
    throw ('Aucune session CIM ouverte sur '+$Computer+'. '+($failures.ToArray() -join ' | '))
}

function Remove-WDomeniaCimSession {
    param($Session)
    if ($null -eq $Session) { return }
    try { Remove-CimSession -CimSession $Session -ErrorAction SilentlyContinue | Out-Null } catch { }
}

function ConvertTo-WProcessQuotedArg {
    param([AllowNull()][string]$Value)
    if ($null -eq $Value -or $Value -eq '') { return '""' }
    if ($Value -notmatch '[\s"]') { return $Value }
    $sb=New-Object System.Text.StringBuilder
    [void]$sb.Append('"')
    $slashes=0
    foreach($ch in $Value.ToCharArray()){
        if($ch -eq '\'){$slashes++;continue}
        if($ch -eq '"'){
            [void]$sb.Append('\' * ($slashes*2+1))
            [void]$sb.Append('"')
            $slashes=0
            continue
        }
        if($slashes -gt 0){[void]$sb.Append('\' * $slashes);$slashes=0}
        [void]$sb.Append($ch)
    }
    if($slashes -gt 0){[void]$sb.Append('\' * ($slashes*2))}
    [void]$sb.Append('"')
    return $sb.ToString()
}
function Invoke-WQuietProcess {
    param([string]$FilePath,[string[]]$Arguments,[int]$TimeoutSeconds=30)
    if([IO.Path]::GetFileName($FilePath) -match '^(?i:PsExec(?:64)?|schtasks)\.exe$'){foreach($arg in @($Arguments)){if([string]$arg -match '^(?i:-p|-password|/p|/rp)(?:$|[:=])'){throw 'Secret dans les arguments de processus interdit.'}}}
    $psi=New-Object Diagnostics.ProcessStartInfo
    $psi.FileName=$FilePath
    $psi.Arguments=(($Arguments|ForEach-Object{ConvertTo-WProcessQuotedArg ([string]$_)})-join ' ')
    $psi.UseShellExecute=$false
    $psi.CreateNoWindow=$true
    $psi.RedirectStandardOutput=$true
    $psi.RedirectStandardError=$true
    try{
        $oem=[Text.Encoding]::GetEncoding([Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage)
        $psi.StandardOutputEncoding=$oem
        $psi.StandardErrorEncoding=$oem
    }catch{}
    $p=New-Object Diagnostics.Process
    $p.StartInfo=$psi
    try{
        if(-not$p.Start()){throw 'Processus non lance.'}
        $outTask=$p.StandardOutput.ReadToEndAsync()
        $errTask=$p.StandardError.ReadToEndAsync()
        if(-not$p.WaitForExit([Math]::Max(1,$TimeoutSeconds)*1000)){
            try{$p.Kill()}catch{}
            try{[void]$p.WaitForExit(1500)}catch{}
            return [pscustomobject]@{ExitCode=1460;Output="Timeout $TimeoutSeconds s"}
        }
        $o='';$e=''
        try{if($outTask.Wait(1500)){$o=[string]$outTask.Result}else{$o='[Sortie standard non fermee dans le delai]'}}catch{}
        try{if($errTask.Wait(1500)){$e=[string]$errTask.Result}else{$e='[Sortie erreur non fermee dans le delai]'}}catch{}
        return [pscustomobject]@{ExitCode=$p.ExitCode;Output=(($o+$e).Trim())}
    }finally{$psi.Arguments="";$Arguments=$null;try{$p.Dispose()}catch{}}
}
function Get-WPsExecPath {
    param($Context)
    $roots=New-Object Collections.ArrayList
    try{
        $r=([string]$Context.RootDir).Trim()
        if(-not[string]::IsNullOrWhiteSpace($r)){[void]$roots.Add($r)}
    }catch{}
    try{
        $sp=([string]$Context.ScriptPath).Trim()
        if(-not[string]::IsNullOrWhiteSpace($sp)){[void]$roots.Add((Split-Path -Parent $sp))}
    }catch{}
    # Portable layout: accept PsExec next to the launcher as well as in wad.
    foreach($rootCandidate in @($roots.ToArray())) {
        try { if ((Split-Path -Leaf $rootCandidate) -ieq 'wad') { [void]$roots.Add((Split-Path -Parent $rootCandidate)) } } catch { }
    }
    foreach($root in @($roots|Select-Object -Unique)){
        foreach($name in @('PsExec.exe','PsExec64.exe','PsExec.exe','psexec64.exe')){
            try{
                $candidate=Join-Path $root $name
                if(Test-Path -LiteralPath $candidate -PathType Leaf){return $candidate}
            }catch{}
        }
    }
    return $null
}
function Get-WRemoteComputerName {
    param([string]$Computer)
    $name = ([string]$Computer).Trim()
    # Une seule cible. Refuser les jokers, listes, chemins et options natives.
    if ($name -notmatch '\A[A-Za-z0-9][A-Za-z0-9_.-]{0,252}\z') {
        throw 'Nom de poste distant invalide : fournir un nom DNS, NetBIOS ou une adresse IPv4 unique.'
    }
    return $name
}
function Format-WRemoteFailureDetail {
    param([string]$Text,[int]$MaxLength=700)
    $detail = ([regex]::Replace(([string]$Text),'\s+',' ')).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { return 'aucun detail retourne' }
    if ($detail -match '(?i)SYSINTERNALS SOFTWARE LICENSE TERMS|BY USING THE SOFTWARE, YOU ACCEPT THESE TERMS') {
        return 'PsExec a renvoye sa licence au lieu du resultat distant. Verifier la ligne de commande, les options -accepteula/-nobanner et le binaire lance ; ce retour ne prouve pas un refus de droits sur la cible.'
    }
    $limit = [Math]::Max(80,$MaxLength)
    if ($detail.Length -gt $limit) { return ($detail.Substring(0,$limit)+' [...]') }
    return $detail
}
function Get-WProbeAttemptSummary {
    param([object[]]$Attempts)
    $parts = New-Object 'System.Collections.Generic.List[string]'
    foreach ($attempt in @($Attempts)) {
        if ([string]$attempt.Status -in @('INFO','OK')) { continue }
        $detail = Format-WRemoteFailureDetail -Text ([string]$attempt.Detail) -MaxLength 220
        $parts.Add(('{0} [{1}] : {2}' -f [string]$attempt.Method,[string]$attempt.Status,$detail))
        if ($parts.Count -ge 6) { break }
    }
    if ($parts.Count -eq 0) { return 'Aucun resultat classique exploitable.' }
    return ($parts.ToArray() -join ' | ')
}
function Assert-WRemoteArtifactPermission {
    param($Context,[string]$Computer)
    $allowed=@([string]$Context.ArtifactTarget)+@($Context.ArtifactAliases)
    if(-not [bool]$Context.AllowRemoteArtifacts -or -not $Computer -or $allowed -notcontains $Computer){
        throw 'Transport avec dépôt de script, service ou tâche non autorisé pour ce poste (désactivé par défaut). Autorisez une intervention dans Assistance poste > Intervenir, « Autoriser une intervention (5 min) », puis relancez votre action.'
    }
}
function Assert-DomeniaReadFallbackPermission {
    # SE-07 : une lecture ne bascule jamais seule sur un transport intrusif. L autorisation
    # d intervention de cinq minutes ne debloque que les interventions ; la lecture exige la
    # sienne, demandee pour elle-meme et consommee par une seule lecture.
    param($Context,[string]$Computer)
    if(-not [bool]$Context.AllowReadFallback){
        throw 'Repli vers PsExec ou une tâche planifiée refusé pour cette lecture : une lecture ne bascule jamais sans demande. Autorisez « Lire ce poste par tâche planifiée » dans Assistance poste > Intervenir, puis relancez la lecture.'
    }
    $allowed=@([string]$Context.ReadFallbackTarget)+@($Context.ReadFallbackAliases)
    if(-not $Computer -or $allowed -notcontains $Computer){
        throw ('Autorisation de lecture par tâche refusée : elle ne couvre pas '+$Computer+'.')
    }
}
function Get-WRemoteWindowsDirectory {
    param($Context,[string]$Computer)
    $session=$null
    try {
        $opt=New-CimSessionOption -Protocol Dcom
        $a=@{ComputerName=$Computer;SessionOption=$opt;OperationTimeoutSec=5;ErrorAction='Stop'}
        $cred=Get-WMachineCredential $Context;if($null -ne $cred){$a.Credential=$cred}
        # Point 41: the session and its first authenticated query hold the account lease; a refusal is shared.
        Set-WCredentialAttemptIdentity -Context $Context -Credential $cred -Channel Remote -Target $Computer
        $lease=Enter-WCredentialAttempt -Context $Context -Channel Remote
        try{
            $session=New-CimSession @a
            $os=Get-CimInstance -CimSession $session -ClassName Win32_OperatingSystem -Property WindowsDirectory -OperationTimeoutSec 5 -ErrorAction Stop
        }catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}
        finally{Exit-WCredentialAttempt $lease}
        $path=[string]$os.WindowsDirectory
        if($path -notmatch '^[A-Za-z]:\\[^\r\n<>"|?*]+$' -or $path -match '[\x00-\x1f]' -or $path.Contains("'")){throw 'Chemin Windows distant non confirme.'}
        return $path.TrimEnd('\')
    } finally {if($null -ne $session){Remove-CimSession $session -ErrorAction SilentlyContinue}}
}
function Invoke-WRemotePsExecScript {
    param($Context,[string]$Computer,[string]$ScriptText,$InputObject,[int]$TimeoutSeconds=45)
    $Computer=Get-WRemoteComputerName -Computer $Computer
    Assert-WRemoteArtifactPermission $Context $Computer
    $exe=Get-WPsExecPath $Context
    if([string]::IsNullOrWhiteSpace([string]$exe)){throw 'PsExec.exe absent du dossier Domenia.'}
    if([string]::IsNullOrWhiteSpace($Computer)){throw 'Nom de poste vide pour PsExec.'}
    $TimeoutSeconds=[Math]::Max(10,[int]$TimeoutSeconds)

    $payloadJson=$InputObject|ConvertTo-Json -Depth 8 -Compress
    $payloadB64=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes([string]$payloadJson))
    $scriptB64=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes([string]$ScriptText))
    $runner=@"
`$ErrorActionPreference='Stop'
`$ProgressPreference='SilentlyContinue'
try {
  `$PayloadJson=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('$payloadB64'))
  `$Payload=`$PayloadJson|ConvertFrom-Json
  `$RemoteCode=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('$scriptB64'))
  `$RemoteBlock=[scriptblock]::Create(`$RemoteCode)
  `$result=& `$RemoteBlock
  `$json=`$result|ConvertTo-Json -Depth 10 -Compress
  if([string]::IsNullOrWhiteSpace([string]`$json)){`$json='null'}
  `$encoded=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes([string]`$json))
  [Console]::Out.WriteLine('__DOMENIA_PSEXEC_BEGIN__'+`$encoded+'__DOMENIA_PSEXEC_END__')
} catch {
  `$err=[pscustomobject]@{__domeniaError=`$_.Exception.Message;__domeniaDetail=`$_.Exception.ToString()}
  `$json=`$err|ConvertTo-Json -Depth 6 -Compress
  `$encoded=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes([string]`$json))
  [Console]::Out.WriteLine('__DOMENIA_PSEXEC_BEGIN__'+`$encoded+'__DOMENIA_PSEXEC_END__')
  exit 97
}
"@
    $encodedCommand=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($runner))
    $svc='DOMENIAPX_'+[guid]::NewGuid().ToString('N').Substring(0,8)
    # Ne pas ecrire @('\\'+$Computer,...) : la virgule est prioritaire sur +
    # et regroupe alors la cible et les options dans un seul argument.
    $target='\\'+$Computer
    [string[]]$processArguments=@($target,'-accepteula','-nobanner','-n',[string][Math]::Min(20,[Math]::Max(5,[int][Math]::Ceiling($TimeoutSeconds/3.0))),'-r',$svc)
    $remoteCred=Get-WMachineCredential $Context
    if ($null -ne $remoteCred) {
        throw 'Ce transport ne prend pas de mot de passe en ligne de commande. Utilisez CIM/DCOM ou une session Windows autorisee.'
    }
    $processArguments+=@('-s',(Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'),'-NoLogo','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-EncodedCommand',$encodedCommand)
    if ($processArguments[0] -cne $target -or $processArguments[1] -cne '-accepteula' -or $processArguments[2] -cne '-nobanner') {
        throw 'Arguments PsExec invalides : execution annulee avant tout acces distant.'
    }
    $watch=[Diagnostics.Stopwatch]::StartNew()
    try { $r=Invoke-WQuietProcess -FilePath $exe -Arguments $processArguments -TimeoutSeconds $TimeoutSeconds }
    finally { $watch.Stop(); $processArguments=$null; $remoteCred=$null }
    $output=[string]$r.Output
    $m=[regex]::Match($output,'__DOMENIA_PSEXEC_BEGIN__(?<b64>[A-Za-z0-9+/=]+)__DOMENIA_PSEXEC_END__',[Text.RegularExpressions.RegexOptions]::Singleline)
    if(-not$m.Success){
        $detail=Format-WRemoteFailureDetail -Text $output -MaxLength 700
        throw ('PsExec KO code '+[string]$r.ExitCode+' : '+$detail)
    }
    try{
        $json=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String([string]$m.Groups['b64'].Value))
        $obj=$json|ConvertFrom-Json
    }catch{throw ('Resultat PsExec illisible : '+$_.Exception.Message)}
    if($null-ne$obj -and $null-ne$obj.PSObject.Properties['__domeniaError']){
        throw ('Script distant PsExec : '+[string]$obj.__domeniaError)
    }
    if ([int]$r.ExitCode -ne 0) { throw ('PsExec : resultat recu mais code de sortie non nul ('+[string]$r.ExitCode+').') }
    if($null-eq$obj){$obj=[pscustomobject]@{Value=$null}}
    $sent=[Text.Encoding]::UTF8.GetByteCount($runner)+[Text.Encoding]::UTF8.GetByteCount($payloadJson)
    $received=[Text.Encoding]::UTF8.GetByteCount($json)
    Add-Member -InputObject $obj -NotePropertyName DomeniaTransport -NotePropertyValue 'PsExec' -Force
    Add-Member -InputObject $obj -NotePropertyName DomeniaBytesSent -NotePropertyValue ([long]$sent) -Force
    Add-Member -InputObject $obj -NotePropertyName DomeniaBytesReceived -NotePropertyValue ([long]$received) -Force
    Add-Member -InputObject $obj -NotePropertyName DomeniaDurationMs -NotePropertyValue ([long]$watch.ElapsedMilliseconds) -Force
    return $obj
}
function Invoke-WSchtasksRemote {
    # Historical entry point, now using the Task Scheduler COM API instead of CLI credentials.
    param($Context,[string]$Computer,[string[]]$Arguments,[int]$TimeoutSeconds=30)
    $Computer=Get-WRemoteComputerName $Computer
    $verb=([string]$Arguments[0]).ToLowerInvariant();$name='';$xmlPath=''
    if($verb -notin @('/create','/run','/delete','/query')){throw 'Operation Planificateur non prise en charge.'}
    for($i=1;$i -lt $Arguments.Count;$i++){
        if($Arguments[$i] -eq '/tn' -and $i+1 -lt $Arguments.Count){$name=[string]$Arguments[++$i]}
        elseif($Arguments[$i] -eq '/xml' -and $i+1 -lt $Arguments.Count){$xmlPath=[string]$Arguments[++$i]}
        elseif($Arguments[$i] -in @('/p','/rp','/u')){throw 'Identifiant ou mot de passe dans les arguments interdit.'}
    }
    if($verb -ne '/query'){
        Assert-WRemoteArtifactPermission $Context $Computer
        if($name -notmatch '^\\?DOMENIA_(Remote|Execution)_[a-f0-9]{12}$'){throw 'Seules les taches propres a cette operation sont autorisees.'}
    }
    $service=$null;$folder=$null;$task=$null;$running=$null;$tasks=$null;$secret=''
    try{
        $service=New-Object -ComObject 'Schedule.Service'
        $cred=Get-WMachineCredential $Context
        # Point 41: the Task Scheduler logon holds the account lease; a rejected account is shared with every job.
        Set-WCredentialAttemptIdentity -Context $Context -Credential $cred -Channel Remote -Target $Computer
        $lease=Enter-WCredentialAttempt -Context $Context -Channel Remote
        try{
            if($null -ne $cred){
                $net=$cred.GetNetworkCredential();$secret=[string]$net.Password
                try{$service.Connect($Computer,[string]$net.UserName,[string]$net.Domain,$secret)}finally{$secret='';$net=$null}
            }else{$service.Connect($Computer)}
        }catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}
        finally{Exit-WCredentialAttempt $lease}
        $folder=$service.GetFolder('\')
        switch($verb){
            '/create' {
                $info=Get-Item -LiteralPath $xmlPath -Force -ErrorAction Stop
                if($info.Length -gt 512KB -or ($info.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Definition de tache invalide.'}
                $xmlText=[IO.File]::ReadAllText($xmlPath)
                $settings=[Xml.XmlReaderSettings]::new();$settings.DtdProcessing=[Xml.DtdProcessing]::Prohibit;$settings.XmlResolver=$null
                $reader=[Xml.XmlReader]::Create([IO.StringReader]::new($xmlText),$settings)
                try{$doc=[Xml.XmlDocument]::new();$doc.XmlResolver=$null;$doc.Load($reader)}finally{$reader.Dispose()}
                $ns=[Xml.XmlNamespaceManager]::new($doc.NameTable);$ns.AddNamespace('t','http://schemas.microsoft.com/windows/2004/02/mit/task')
                $principal=$doc.SelectSingleNode('/t:Task/t:Principals/t:Principal/t:UserId',$ns);if($null -eq $principal){throw 'Principal de la tache absent.'}
                $user=[string]$principal.InnerText;$logon=$doc.SelectSingleNode('/t:Task/t:Principals/t:Principal/t:LogonType',$ns)
                if($user -eq 'S-1-5-18'){$kind=5}
                elseif($null -ne $logon -and $logon.InnerText -eq 'InteractiveToken'){$kind=3}
                else{throw 'Seuls SYSTEM et une session interactive existante sont permis ; aucun mot de passe de tache enregistre.'}
                $task=$folder.RegisterTask($name,$xmlText,2,$user,$null,$kind,'D:P(A;;FA;;;SY)(A;;FA;;;BA)')
                $text='Tache unique creee par API ; aucun mot de passe transmis dans une ligne de commande.'
            }
            '/run' {$task=$folder.GetTask($name);$running=$task.Run($null);$text='Demande de lancement acceptee. Le resultat du programme doit etre verifie separement.'}
            '/delete' {$folder.DeleteTask($name,0);$text='Definition de tache supprimee ; ceci n arrete pas un programme deja demarre.'}
            '/query' {
                if($name){$task=$folder.GetTask($name);$text='Tache : '+$task.Name+' ; etat : '+$task.State+' ; dernier resultat : '+$task.LastTaskResult}
                else{
                    $tasks=$folder.GetTasks(0);$lines=[Collections.Generic.List[string]]::new();$cap=[Math]::Min(200,[int]$tasks.Count)
                    for($j=1;$j -le $cap;$j++){$one=$null;try{$one=$tasks.Item($j);$lines.Add([string]$one.Name+' ; etat : '+$one.State)}finally{if($null -ne $one -and [Runtime.InteropServices.Marshal]::IsComObject($one)){[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($one)}}}
                    $text=($lines -join "`r`n")+"`r`nLecture limitee au dossier racine et a 200 definitions."
                }
            }
        }
        return [pscustomobject]@{ExitCode=0;Output=$text;Transport='TaskScheduler COM'}
    }finally{
        $secret='';$cred=$null
        foreach($com in @($running,$task,$tasks,$folder,$service)){if($null -ne $com -and [Runtime.InteropServices.Marshal]::IsComObject($com)){try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($com)}catch{}}}
    }
}

function Get-WSchtasksHint {
    param([int]$Code)
    switch($Code){
        0 { "OK" }
        1 { "Erreur generique schtasks." }
        2 { "Fichier ou XML introuvable." }
        5 { "Acces refuse : droits administrateur insuffisants sur la cible." }
        53 { "Chemin reseau introuvable : cible SMB/RPC injoignable." }
        1219 { "Connexions multiples au meme serveur : conflit de session reseau." }
        1326 { "Echec de connexion : identifiants refuses." }
        1722 { "RPC indisponible : Planificateur ou pare-feu distant." }
        1460 { "Delai depasse." }
        default { "Code schtasks non documente par Domenia." }
    }
}
function New-WAdminShareDrive {
    param($Context,[string]$Computer)
    $Computer=Get-WRemoteComputerName -Computer $Computer
    $name='A'+[guid]::NewGuid().ToString('N').Substring(0,7)
    $root='\\'+$Computer+'\ADMIN$'
    $credential=Get-WMachineCredential $Context
    $identity='session Windows courante'
    $parameters=@{Name=$name;PSProvider='FileSystem';Root=$root;Scope='Script';ErrorAction='Stop'}
    if ($null -ne $credential) {
        $parameters['Credential']=$credential
        $identity=[string]$credential.UserName
    }
    # Point 41: mapping ADMIN$ with an explicit account holds its lease; a rejected account is shared with every job.
    Set-WCredentialAttemptIdentity -Context $Context -Credential $credential -Channel Remote -Target $Computer
    $lease=Enter-WCredentialAttempt -Context $Context -Channel Remote
    try { return (New-PSDrive @parameters) }
    catch {
        [void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote)
        $detail=Format-WRemoteFailureDetail -Text ([string]$_.Exception.Message) -MaxLength 450
        throw ('ADMIN$ inaccessible sur '+$Computer+' avec '+$identity+' : '+$detail+'. Aucun autre compte n a ete substitue automatiquement.')
    }
    finally { Exit-WCredentialAttempt $lease; $credential=$null; $parameters.Remove('Credential') }
}
function Remove-WAdminShareDrive {
    param($Drive)
    if($null-ne$Drive){try{Remove-PSDrive -Name ([string]$Drive.Name) -Force -ErrorAction SilentlyContinue}catch{}}
}
function New-WRunOnceTaskXml {
    param([string]$TaskName,[string]$ScriptPath)
    $start=(Get-Date).AddSeconds(-30).ToString('yyyy-MM-ddTHH:mm:ss')
    $end=(Get-Date).AddMinutes(15).ToString('yyyy-MM-ddTHH:mm:ss')
    $arg='-NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -File "'+$ScriptPath+'"'
    $argX=[Security.SecurityElement]::Escape($arg)
    $desc=[Security.SecurityElement]::Escape('DOMENIA - fallback distant '+$TaskName)
@"
<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo><Description>$desc</Description><Author>DOMENIA</Author></RegistrationInfo>
  <Triggers/>
  <Principals><Principal id="Author"><UserId>S-1-5-18</UserId><RunLevel>HighestAvailable</RunLevel></Principal></Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>
    <AllowHardTerminate>true</AllowHardTerminate>
    <StartWhenAvailable>true</StartWhenAvailable>
    <RunOnlyIfNetworkAvailable>false</RunOnlyIfNetworkAvailable>
    <AllowStartOnDemand>true</AllowStartOnDemand>
    <Enabled>true</Enabled><Hidden>true</Hidden>
    <ExecutionTimeLimit>PT10M</ExecutionTimeLimit><Priority>5</Priority>

  </Settings>
  <Actions Context="Author"><Exec><Command>%SystemRoot%\System32\WindowsPowerShell\v1.0\powershell.exe</Command><Arguments>$argX</Arguments></Exec></Actions>
</Task>
"@
}
function Invoke-WRemoteScheduledTaskScript {
    param($Context,[string]$Computer,[string]$ScriptText,$InputObject,[int]$TimeoutSeconds=75)
    $Computer=Get-WRemoteComputerName -Computer $Computer
    Assert-WRemoteArtifactPermission $Context $Computer
    if(-not[bool]$Context.UseTaskFallback){throw 'Fallback tache planifiee desactive.'}
    $TimeoutSeconds=[Math]::Max(15,[int]$TimeoutSeconds)
    $taskWatch=[Diagnostics.Stopwatch]::StartNew()
    $phaseTimeout=[Math]::Max(5,[Math]::Min(12,[int][Math]::Ceiling($TimeoutSeconds/3.0)))
    $id=[guid]::NewGuid().ToString('N')
    $task='\DOMENIA_Remote_'+$id.Substring(0,12)
    $base='DOMENIA_'+$id
    $win=Get-WRemoteWindowsDirectory $Context $Computer
    $remoteFolder=$win+'\Temp\'+$base
    $remotePs=$remoteFolder+'\run.ps1'
    $remoteIn=$remoteFolder+'\run.json'
    $remoteOut=$remoteFolder+'\run.out.json'
    $drive=$null
    $localXml=Join-Path $env:TEMP ($base+'.xml')
    $created=$false
    $bytesSent=0
    $bytesReceived=0
    $stage='initialisation'
    $drivePrefix=''
    try{
        $stage='acces ADMIN$ / staging'
        $drive=New-WAdminShareDrive $Context $Computer
        $adminRoot=([string]$drive.Root).TrimEnd('\')
        $expected='\\'+$Computer+'\ADMIN$'
        if([string]::IsNullOrWhiteSpace($adminRoot) -or $adminRoot -ine $expected){
            throw ("Racine ADMIN$ incoherente : attendu '$expected', obtenu '$adminRoot'.")
        }
        # Utiliser le PSDrive authentifie, pas un nouvel acces .NET au chemin UNC.
        $privateFolder=([string]$drive.Name)+':\Temp\'+$base
        if(Test-Path -LiteralPath $privateFolder){throw 'Repertoire operation deja existant.'}
        $directory=New-Item -ItemType Directory -Path $privateFolder -ErrorAction Stop
        if($directory.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Repertoire operation redirige.'}
        $acl=[Security.AccessControl.DirectorySecurity]::new()
        # Changer seulement les permissions du depot, jamais ses regles d'audit.
        $acl.SetSecurityDescriptorSddlForm(
            'D:P(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)',
            [Security.AccessControl.AccessControlSections]::Access
        )
        Set-Acl -LiteralPath $privateFolder -AclObject $acl -ErrorAction Stop
        $drivePrefix=$privateFolder+'\run'
        $inJson=$InputObject|ConvertTo-Json -Depth 8 -Compress
        if($inJson.Length -gt 524288 -or $ScriptText.Length -gt 524288){throw 'Depôt trop volumineux.'}
        $wrapper=@"
`$ErrorActionPreference='Stop'
`$ProgressPreference='SilentlyContinue'
try {
  `$Payload = Get-Content -LiteralPath '$remoteIn' -Raw -Encoding UTF8 | ConvertFrom-Json
  `$result = & {
$ScriptText
  }
  `$result | ConvertTo-Json -Depth 10 -Compress | Set-Content -LiteralPath '$remoteOut.tmp' -Encoding UTF8 -Force
  Move-Item -LiteralPath '$remoteOut.tmp' -Destination '$remoteOut' -Force
} catch {
  [pscustomobject]@{__domeniaError=`$_.Exception.Message;__domeniaDetail=`$_.Exception.ToString()} | ConvertTo-Json -Compress | Set-Content -LiteralPath '$remoteOut.tmp' -Encoding UTF8 -Force
  Move-Item -LiteralPath '$remoteOut.tmp' -Destination '$remoteOut' -Force
} finally {
  try { Remove-Item -LiteralPath '$remoteIn' -Force -ErrorAction SilentlyContinue } catch {}
  try { Start-Process -FilePath (Join-Path `$env:SystemRoot 'System32\schtasks.exe') -ArgumentList @('/delete','/tn','$task','/f') -WindowStyle Hidden } catch {}
}
"@
        Set-Content -LiteralPath ($drivePrefix+'.ps1') -Value $wrapper -Encoding UTF8 -NoNewline -Force -ErrorAction Stop
        Set-Content -LiteralPath ($drivePrefix+'.json') -Value $inJson -Encoding UTF8 -NoNewline -Force -ErrorAction Stop
        if (-not (Test-Path -LiteralPath ($drivePrefix+'.ps1') -PathType Leaf) -or -not (Test-Path -LiteralPath ($drivePrefix+'.json') -PathType Leaf)) {
            throw 'Copie du payload fallback impossible dans ADMIN$\Temp.'
        }
        $bytesSent=[Text.Encoding]::UTF8.GetByteCount($wrapper)+[Text.Encoding]::UTF8.GetByteCount($inJson)
        $stage='preparation XML'
        $xml=New-WRunOnceTaskXml $task $remotePs
        [IO.File]::WriteAllText($localXml,$xml,[Text.Encoding]::Unicode)
        $stage='creation tache planifiee'
        $create=Invoke-WSchtasksRemote $Context $Computer @('/create','/tn',$task,'/xml',$localXml,'/f') $phaseTimeout
        if($create.ExitCode-ne 0){throw "creation tache KO (code $($create.ExitCode), $(Get-WSchtasksHint $create.ExitCode)) : $($create.Output)"}
        $created=$true
        if($taskWatch.Elapsed.TotalSeconds -ge $TimeoutSeconds){throw 'budget fallback depasse apres creation de la tache'}
        $stage='lancement tache planifiee'
        $run=Invoke-WSchtasksRemote $Context $Computer @('/run','/tn',$task) $phaseTimeout
        if($run.ExitCode-ne 0){throw "lancement tache KO (code $($run.ExitCode), $(Get-WSchtasksHint $run.ExitCode)) : $($run.Output)"}
        $stage='attente resultat'
        $remaining=[Math]::Max(3,$TimeoutSeconds-[int][Math]::Ceiling($taskWatch.Elapsed.TotalSeconds))
        $deadline=(Get-Date).AddSeconds($remaining)
        $outPath=$drivePrefix+'.out.json'
        while((Get-Date)-lt$deadline){
            if(Test-Path -LiteralPath $outPath -PathType Leaf){
                $item=Get-Item -LiteralPath $outPath -Force -ErrorAction Stop
                if($item.Length -gt 2097152 -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Resultat distant invalide ou trop volumineux.'}
                $json=Get-Content -LiteralPath $outPath -Raw -Encoding UTF8 -ErrorAction Stop
                $bytesReceived=[Text.Encoding]::UTF8.GetByteCount($json)
                $obj=$json|ConvertFrom-Json
                if($null-ne$obj.PSObject.Properties['__domeniaError']){throw ([string]$obj.__domeniaError)}
                try{Remove-Item -LiteralPath $outPath -Force -ErrorAction Stop}catch{}
                Add-Member -InputObject $obj -NotePropertyName DomeniaTransport -NotePropertyValue 'ScheduledTask' -Force
                Add-Member -InputObject $obj -NotePropertyName DomeniaBytesSent -NotePropertyValue $bytesSent -Force
                Add-Member -InputObject $obj -NotePropertyName DomeniaBytesReceived -NotePropertyValue $bytesReceived -Force
                return $obj
            }
            Start-Sleep -Milliseconds 250
        }
        throw "timeout resultat : budget fallback de $TimeoutSeconds s depasse"
    }catch{
        throw ('fallback 2 tache planifiee ['+$stage+'] : '+$_.Exception.Message)
    }finally{
        if($created){try{[void](Invoke-WSchtasksRemote $Context $Computer @('/delete','/tn',$task,'/f') 8)}catch{}}
        if(-not[string]::IsNullOrWhiteSpace($drivePrefix)){
            foreach($suffix in @('.ps1','.json','.out.json','.out.json.tmp')){try{Remove-Item -LiteralPath ($drivePrefix+$suffix) -Force -ErrorAction SilentlyContinue}catch{}}
        }
        if($drive -and $privateFolder){try{Remove-Item -LiteralPath $privateFolder -ErrorAction Stop}catch{Write-Warning ('Repertoire distant a nettoyer : '+$remoteFolder)}}
        Remove-WAdminShareDrive $drive
        Remove-Item -LiteralPath $localXml -Force -ErrorAction SilentlyContinue
        try{$taskWatch.Stop()}catch{}
    }
}
function Invoke-WRemoteTaskScript {
    param($Context,[string]$Computer,[string]$ScriptText,$InputObject,[int]$TimeoutSeconds=75,[string]$ClassicError='',[string]$Purpose='Read')
    # SE-07 : par defaut cette entree sert une lecture, et le repli intrusif y est refuse tant que
    # l operateur ne l a pas demande pour cette lecture. Une ecriture le dit par -Purpose 'Write'.
    if($Purpose -ne 'Write'){ Assert-DomeniaReadFallbackPermission $Context $Computer }
    $TimeoutSeconds=[Math]::Max(15,[int]$TimeoutSeconds)
    $pxError=''
    $taskError=''
    $fallbackWatch=[Diagnostics.Stopwatch]::StartNew()

    # Ordre impose DOMENIA :
    # 1) methodes classiques dans le worker appelant
    # 2) fallback PsExec portable place a cote de Domenia-Core.ps1
    # 3) fallback tache planifiee RunOnce / execution unique
    #
    # TimeoutSeconds est le budget TOTAL des deux fallbacks. PsExec ne peut
    # donc jamais manger tout le temps et empecher le fallback 2 de demarrer.
    if([bool]$Context.UsePsExecFallback){
        try{
            $pxBudget=[Math]::Max(10,[Math]::Min(15,[int][Math]::Ceiling($TimeoutSeconds*0.35)))
            return (Invoke-WRemotePsExecScript $Context $Computer $ScriptText $InputObject $pxBudget)
        }catch{$pxError=[string]$_.Exception.Message}
    }else{$pxError='desactive'}

    try{
        $remaining=[int][Math]::Floor($TimeoutSeconds-$fallbackWatch.Elapsed.TotalSeconds)
        if($remaining -lt 15){$remaining=15}
        return (Invoke-WRemoteScheduledTaskScript $Context $Computer $ScriptText $InputObject $remaining)
    }catch{$taskError=[string]$_.Exception.Message}
    finally{try{$fallbackWatch.Stop()}catch{}}

    if([string]::IsNullOrWhiteSpace($ClassicError)){$ClassicError='methode classique sans resultat'}
    if([string]::IsNullOrWhiteSpace($pxError)){$pxError='echec sans detail'}
    if([string]::IsNullOrWhiteSpace($taskError)){$taskError='echec sans detail'}
    throw ('Acces distant impossible sur '+$Computer+'. Methode classique : '+$ClassicError+' ; fallback 1 PsExec : '+$pxError+' ; fallback 2 tache planifiee : '+$taskError)
}

function Import-WAdModule {
    param($Context)
    try {
        $required = @($Context.AdRequiredCommands)
        $missing = @($required | Where-Object { $null -eq (Get-Command -Name $_ -CommandType Cmdlet -ErrorAction SilentlyContinue) })
        if ($missing.Count -eq 0) { return $true }
        foreach ($source in @($Context.AdModuleSources)) {
            try {
                $path = [string]$source.Path
                if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path -PathType Leaf)) { continue }
                if ([string]$source.Kind -eq "Binary") {
                    if (-not [Environment]::Is64BitProcess) { throw "Le module Active Directory autonome exige un processus 64 bits." }
                    $resourcePath = [string]$source.ResourcePath
                    if ([string]::IsNullOrWhiteSpace($resourcePath) -or -not (Test-Path -LiteralPath $resourcePath -PathType Leaf)) { throw "DLL de ressources Active Directory absente." }
                    $managementHash = (Get-FileHash -LiteralPath $path -Algorithm SHA256 -ErrorAction Stop).Hash
                    if ($managementHash -ne [string]$Context.AdManagementHash) { throw "Hash Microsoft.ActiveDirectory.Management.dll invalide." }
                    $resourceHash = (Get-FileHash -LiteralPath $resourcePath -Algorithm SHA256 -ErrorAction Stop).Hash
                    if ($resourceHash -ne [string]$Context.AdResourceHash) { throw "Hash ActiveDirectoryPowerShellResources.dll invalide." }
                    $assemblyName = [System.Reflection.AssemblyName]::GetAssemblyName($path)
                    $token = [System.BitConverter]::ToString($assemblyName.GetPublicKeyToken()).Replace("-","").ToLowerInvariant()
                    if ($assemblyName.Name -ne "Microsoft.ActiveDirectory.Management" -or $assemblyName.Version -ne [version]"10.0.0.0" -or $token -ne "31bf3856ad364e35") {
                        throw "Identite de l assembly Active Directory invalide."
                    }
                }
                Import-Module -Name $path -Global -Cmdlet $required -ErrorAction Stop -WarningAction SilentlyContinue
                $adapter = [Microsoft.ActiveDirectory.Management.ADEntityAdapter]
                foreach ($typeName in @($Context.AdTypeNames)) {
                    Update-TypeData -TypeName ([string]$typeName) -TypeAdapter $adapter -Force -ErrorAction Stop
                }
                $missing = @($required | Where-Object { $null -eq (Get-Command -Name $_ -CommandType Cmdlet -ErrorAction SilentlyContinue) })
                if ($missing.Count -eq 0) { return $true }
            }
            catch { }
        }
    }
    catch { }
    return $false
}
function ConvertTo-WByteArray {
    param($Value)
    if ($null -eq $Value) { return $null }
    if ($Value -is [byte[]]) { return ,([byte[]]$Value) }
    if ($Value -is [System.Security.AccessControl.RawSecurityDescriptor]) {
        try {
            $buffer = New-Object byte[] $Value.BinaryLength
            $Value.GetBinaryForm($buffer,0)
            return ,([byte[]]$buffer)
        }
        catch { return $null }
    }
    if ($Value -is [System.Array]) {
        try {
            $buffer = New-Object byte[] $Value.Length
            for ($i = 0; $i -lt $Value.Length; $i++) { $buffer[$i] = [byte]$Value.GetValue($i) }
            return ,([byte[]]$buffer)
        }
        catch { return $null }
    }
    try {
        if ($null -ne $Value.PSObject.Methods["GetSecurityDescriptorBinaryForm"]) {
            return ,([byte[]]$Value.GetSecurityDescriptorBinaryForm())
        }
    }
    catch { }
    return $null
}
function Get-WActiveDirectorySecurity {
    param(
        $Context,
        [string]$Dn,
        [bool]$IncludeOwner = $true
    )
    if ([string]::IsNullOrWhiteSpace($Dn)) { throw "DN vide pour la lecture du descripteur de securite." }

    $errors = New-Object System.Collections.ArrayList
    $searcher = $null
    $searchRoot = $null
    try {
        $searcher = New-WSearcher $Context $Dn "(objectClass=*)" @("ntSecurityDescriptor") "Base" 1
        try { $searchRoot = $searcher.SearchRoot } catch { }
        $mask = [System.DirectoryServices.SecurityMasks]::Dacl
        if ($IncludeOwner) { $mask = $mask -bor [System.DirectoryServices.SecurityMasks]::Owner }
        $searcher.SecurityMasks = $mask
        $result = $searcher.FindOne()
        if ($null -eq $result) { throw "Objet introuvable lors de la lecture ACL : $Dn" }
        $raw = Get-WPropFirst $result.Properties "ntsecuritydescriptor" $null
        if ($raw -is [System.DirectoryServices.ActiveDirectorySecurity]) { return $raw }
        $bytes = ConvertTo-WByteArray $raw
        if ($null -eq $bytes -or $bytes.Length -lt 20) { throw "Le DC n a pas retourne un ntSecurityDescriptor binaire exploitable." }
        $security = New-Object System.DirectoryServices.ActiveDirectorySecurity
        $security.SetSecurityDescriptorBinaryForm([byte[]]$bytes)
        return $security
    }
    catch {
        [void]$errors.Add("DirectorySearcher : $($_.Exception.Message)")
    }
    finally {
        if ($null -ne $searcher) { try { $searcher.Dispose() } catch { } }
        if ($null -ne $searchRoot) { try { $searchRoot.Dispose() } catch { } }
    }

    # Fallback ADSI sans toucher a DirectoryEntry.Options.SecurityMasks :
    # ce chemin evite le binder qui a echoue dans l hote Windows PowerShell 5.1 observe.
    $entry = $null
    try {
        $entry = New-WEntry $Context $Dn
        $entry.RefreshCache(@("ntSecurityDescriptor"))
        $security = $entry.ObjectSecurity
        if ($null -eq $security) { throw "ObjectSecurity vide." }
        return $security
    }
    catch {
        [void]$errors.Add("DirectoryEntry : $($_.Exception.Message)")
    }
    finally {
        if ($null -ne $entry) { try { $entry.Dispose() } catch { } }
    }

    throw ("Descripteur de securite illisible. " + (@($errors) -join " | "))
}
function Test-WTcpPort {
    param([string]$Computer, [int]$Port, [int]$TimeoutMs)
    $client = New-Object System.Net.Sockets.TcpClient
    try {
        $ar = $client.BeginConnect($Computer,$Port,$null,$null)
        if (-not $ar.AsyncWaitHandle.WaitOne($TimeoutMs,$false)) { return $false }
        $client.EndConnect($ar)
        return $true
    } catch { return $false } finally { try { $client.Close() } catch { } }
}
function Normalize-WUser {
    param([string]$Value)
    $u = ($Value + "").Trim().Trim('"')
    if ([string]::IsNullOrWhiteSpace($u)) { return "" }
    if ($u.Contains([string][char]92)) { $u = $u.Split([char]92)[-1] }
    if ($u.Contains("@")) { $u = $u.Split("@")[0] }
    if ($u.EndsWith("$")) { return "" }
    $bad = @("SYSTEM","LOCAL SERVICE","NETWORK SERVICE","ANONYMOUS LOGON","DWM-1","DWM-2","UMFD-0","UMFD-1","DEFAULTUSER0","ADMINISTRATEUR","ADMINISTRATOR","PUBLIC","DEFAULT","ALL USERS")
    if ($bad -contains $u.ToUpperInvariant()) { return "" }
    return $u
}
function Test-WUserInAd {
    param($Context,[string]$User,[switch]$Detailed)
    $searcher=$null; $root=$null
    $result=[pscustomobject]@{Verified=$false;LookupSucceeded=$false;Error=''}
    try {
        if ([string]::IsNullOrWhiteSpace($User)) { $result.LookupSucceeded=$true }
        else {
            $escaped=Escape-WLdap $User
            $searcher=New-WSearcher $Context ([string]$Context.BaseDn) "(&(objectCategory=person)(objectClass=user)(sAMAccountName=$escaped))" @('distinguishedName') 'Subtree' 1
            $root=$searcher.SearchRoot
            $result.Verified=($null -ne $searcher.FindOne())
            $result.LookupSucceeded=$true
        }
    }
    catch { $result.Error=[string]$_.Exception.Message }
    finally {
        # Un incident de liberation ne doit pas annuler un resultat deja obtenu.
        if ($null -ne $searcher) { try { $searcher.Dispose() } catch {} }
        if ($null -ne $root) { try { $root.Dispose() } catch {} }
    }
    if ($Detailed) { return $result }
    return [bool]$result.Verified
}
'@



function Get-NewTaskId {
    param([string]$Name)
    $script:AsyncSequence++
    return "{0}:{1}:{2}" -f $Name,$script:AsyncSequence,([guid]::NewGuid().ToString("N").Substring(0,8))
}

function Set-ControlsBusy {
    param([string[]]$Names,[bool]$Busy)
    foreach ($name in @($Names)) {
        if ([string]::IsNullOrWhiteSpace([string]$name)) { continue }
        $control = Get-DomeniaControl -Name ([string]$name)
        if ($null -eq $control) { continue }
        if (-not $script:ControlBusyRef.ContainsKey([string]$name)) { $script:ControlBusyRef[[string]$name] = 0 }
        if ($Busy) { $script:ControlBusyRef[[string]$name] = [int]$script:ControlBusyRef[[string]$name] + 1 }
        else { $script:ControlBusyRef[[string]$name] = [Math]::Max(0,[int]$script:ControlBusyRef[[string]$name] - 1) }
        try { $control.IsEnabled = ([int]$script:ControlBusyRef[[string]$name] -eq 0) } catch { Write-DomeniaSwallowed 'Core' 'Set-ControlsBusy' $_ }
    }
    if (-not $Busy) { try { Apply-CurrentPermissionUi } catch { Write-DomeniaSwallowed 'Core' 'Set-ControlsBusy' $_ } }
}

function Update-TaskUi {
    param([switch]$Force)

    $count = @($script:AsyncJobs.Keys).Count
    # CO-02: the bar, Annuler and the label follow the foreground tasks (writes, explicit actions, selection). A local
    # save or a background read alone never shows them; the Opérations badge still counts every task.
    $foregroundJobs = New-Object 'System.Collections.Generic.List[object]'
    foreach ($job in @($script:AsyncJobs.Values)) {
        if ($null -eq $job) { continue }
        $flag = $job.PSObject.Properties['Foreground']
        if (($null -eq $flag) -or [bool]$flag.Value) { $foregroundJobs.Add($job) }
    }
    $foregroundCount = $foregroundJobs.Count
    # D017: exact states. A detached read whose native call still runs keeps the bar visible ("nettoyage"),
    # a queued entry is shown as waiting, never as running. Without the engine rules: historical display.
    # PF-10: the closed loader guarantees the rules; a missing rule (isolated test) only falls back to the counter.
    $summary = $null
    try { $summary = Get-DomeniaTaskStateSummary -Jobs $foregroundJobs.ToArray() -Detached @($script:DetachedReadJobs) } catch { $summary = $null }
    $total = $foregroundCount + @($script:DetachedReadJobs).Count; $active = $total; $signature = [string]$count + '|' + [string]$foregroundCount
    if ($null -ne $summary) { $total = [int]$summary.Total; $active = [int]$summary.Active; $signature = [string]$count + '|' + [string]$summary.Text }
    $now = Get-Date
    $refreshMs = [Math]::Max(200,[int](Get-CfgValue "Async" "UiRefreshIntervalMs" 500))
    $stateChanged = (($count -ne [int]$script:LastTaskUiCount) -or ($signature -cne [string]$script:LastTaskUiSignature))
    if (-not $Force -and -not $stateChanged -and (($now - $script:LastTaskUiRefresh).TotalMilliseconds -lt $refreshMs)) { return }

    $script:LastTaskUiRefresh = $now
    $script:LastTaskUiCount = $count
    $script:LastTaskUiSignature = $signature

    try {
        $progress = Get-DomeniaControl -Name "PbTop"
        if ($null -ne $progress) { $progress.IsIndeterminate = ($active -gt 0); $progress.Visibility = if ($total -gt 0) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Hidden } }
        $cancel = Get-DomeniaControl -Name "BtnCancelTask"
        if ($null -ne $cancel) {
            $cancel.Visibility = if ($total -gt 0) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Hidden }
            # Only an entry still held by the engine can be stopped; a detached call is waited for, not cancelled.
            $cancel.IsEnabled = ($foregroundCount -gt 0)
        }
        $elapsedLabel = Get-DomeniaControl -Name "LblTaskElapsed"
        if ($null -ne $elapsedLabel) {
            $elapsedLabel.Visibility = if ($total -gt 0) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Hidden }
            if ($foregroundCount -gt 0) {
                $latest = $null
                if (-not [string]::IsNullOrWhiteSpace([string]$script:LatestTaskId) -and $script:AsyncJobs.Contains($script:LatestTaskId)) { $latest = $script:AsyncJobs[$script:LatestTaskId] }
                if ($null -eq $latest -or -not $foregroundJobs.Contains($latest)) { $latest = $foregroundJobs[$foregroundCount - 1] }
                $since = $null
                if ($null -ne $latest) { $since = $latest.Started; if ([string]$latest.State -eq 'Queued' -and $null -ne $latest.QueuedAt) { $since = $latest.QueuedAt } }
                $elapsed = if ($null -ne $since) { [int]((Get-Date) - [datetime]$since).TotalSeconds } else { 0 }
                if ($null -ne $summary) { $elapsedLabel.Text = "$($summary.Text) · $([string]$latest.Name) · $elapsed s" }
                else { $elapsedLabel.Text = "$foregroundCount tache(s)  $([string]$latest.Name)  $elapsed s" }
            }
            elseif ($total -gt 0 -and $null -ne $summary) { $elapsedLabel.Text = "$($summary.Text) · appel natif encore actif, compte jusqu a sa fin reelle" }
            else { $elapsedLabel.Text = "" }
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Update-TaskUi' $_ }

    # UX-32 / D020: the rows of the operations panel are updated only while it is open; the badge always is.
    try { Update-DomeniaExperienceActivity -Force:([bool]$Force) } catch { Write-DomeniaSwallowed 'Core' 'Update-TaskUi' $_ }
    # PF-11 (decision David 2026-10-08): the session details of Accueil are rebuilt by a task only while they are open.
    $sessionDetailsOpen = $true
    try { if (($null -ne $script:Ctrl) -and $script:Ctrl.ContainsKey('UxSessionDetails') -and ($null -ne $script:Ctrl['UxSessionDetails'])) { $sessionDetailsOpen = [bool]$script:Ctrl['UxSessionDetails'].IsExpanded } } catch { $sessionDetailsOpen = $true }
    # Closed: only marked to rebuild (D020); the expander rebuilds them when it opens.
    if ($Force -or $stateChanged) { if ($sessionDetailsOpen) { Request-DomeniaDashboardRefresh } else { $script:DashboardDirty = $true } }
}


function Get-VisitCacheValue {
    param([string]$Key)
    if ([string]::IsNullOrWhiteSpace($Key)) { return $null }
    if (-not [bool](Get-CfgValue "Cache" "Enabled" $true)) { return $null }
    try {
        if ($script:VisitCache.ContainsKey($Key)) {
            $item = $script:VisitCache[$Key]
            if ($item.Expires -gt (Get-Date)) {
                if ($null -ne $item.PSObject.Properties['Accessed']) { $item.Accessed = Get-Date }
                $script:CacheStats.Hits++; return $item.Value
            }
            $script:VisitCache.Remove($Key); $script:CacheStats.Evictions++
        }
        $script:CacheStats.Misses++
    } catch { $script:CacheStats.Errors++ }
    return $null
}

function Set-VisitCacheValue {
    param([string]$Key,$Value,[int]$TtlSeconds = 0)
    # D025: an empty key means "not cacheable" (no object GUID): nothing is stored.
    if ([string]::IsNullOrWhiteSpace($Key)) { return }
    if (-not [bool](Get-CfgValue "Cache" "Enabled" $true)) { return }
    try {
        if ($TtlSeconds -le 0) { $TtlSeconds = [int](Get-CfgValue "Cache" "TtlSeconds" 90) }
        $TtlSeconds = [Math]::Max(1,[Math]::Min(86400,$TtlSeconds))
        $max = [Math]::Max(1,[Math]::Min(100000,[int](Get-CfgValue "Cache" "MaxEntries" 500)))
        $now = Get-Date
        if ($script:VisitCache.Count -ge $max) {
            # Expired entries leave first. Updating an existing entry does not evict an unrelated live object.
            foreach ($expired in @($script:VisitCache.Keys)) {
                if ($script:VisitCache[$expired].Expires -le $now) { $script:VisitCache.Remove($expired); $script:CacheStats.Evictions++ }
            }
            $needed = $script:VisitCache.Count - $max + $(if ($script:VisitCache.ContainsKey($Key)) { 0 } else { 1 })
            if ($needed -gt 0) {
                $old = @($script:VisitCache.GetEnumerator() | Where-Object { [string]$_.Key -cne $Key } | Sort-Object { if ($null -ne $_.Value.PSObject.Properties['Accessed']) { $_.Value.Accessed } else { $_.Value.Created } } | Select-Object -First $needed)
                foreach ($o in $old) { $script:VisitCache.Remove([string]$o.Key); $script:CacheStats.Evictions++ }
            }
        }
        $script:VisitCache[$Key] = [pscustomobject]@{ Created=$now; Accessed=$now; Expires=$now.AddSeconds($TtlSeconds); Value=$Value }
        $script:CacheStats.Writes++
    } catch { $script:CacheStats.Errors++ }
}

function Clear-VisitCache {
    $script:VisitCache.Clear()
    $script:CacheStats = [ordered]@{ Hits=0; Misses=0; Writes=0; Evictions=0; Errors=0 }
    Set-Status "Cache de visite vide. Aucun objet AD modifie."
    Update-Dashboard
}

function Get-DeProp {
    param($Entry,[string]$Name,$Default = "")
    try {
        $props = $Entry.Properties
        if ($props -is [System.Collections.IDictionary]) {
            foreach ($key in @($props.Keys)) {
                if ([string]$key -ieq $Name) {
                    $vals = @($props[$key])
                    if ($vals.Count -gt 0) { return $vals[0] }
                }
            }
            return $Default
        }
        if ($props[$Name].Count -gt 0) { return $props[$Name][0] }
    } catch { Write-DomeniaSwallowed 'Core' 'Get-DeProp' $_ }
    return $Default
}

function Get-DePropAll {
    param($Entry,[string]$Name)
    try {
        $props = $Entry.Properties
        if ($props -is [System.Collections.IDictionary]) {
            foreach ($key in @($props.Keys)) { if ([string]$key -ieq $Name) { return @($props[$key]) } }
            return @()
        }
        return @($props[$Name])
    } catch { return @() }
}

function Test-DomeniaSensitiveAttributeName {
    param([string]$Name)
    if ([string]::IsNullOrWhiteSpace($Name)) { return $false }
    return ($Name -match "^(?i:unicodePwd|userPassword|unixUserPassword|clearTextPassword|dBCSPwd|supplementalCredentials|ntPwdHistory|lmPwdHistory|currentValue|priorValue|pekList|trustAuthIncoming|trustAuthOutgoing|ms-Mcs-AdmPwd|msLAPS-Password|msLAPS-EncryptedPassword|msLAPS-EncryptedPasswordHistory|msLAPS-EncryptedDSRMPassword|msLAPS-EncryptedDSRMPasswordHistory|msFVE-RecoveryPassword|msFVE-KeyPackage|msDS-ManagedPassword|msDS-ManagedPasswordId|msDS-ManagedPasswordPreviousId|msDS-KeyCredentialLink)$")
}

function Get-DomeniaSafeObjectPropertyNames {
    @(
        "name","distinguishedName","objectClass","objectCategory","objectGUID","objectSid",
        "uSNChanged","whenCreated","whenChanged","adminCount","isCriticalSystemObject",
        "sAMAccountName","userPrincipalName","displayName","givenName","sn","mail",
        "telephoneNumber","physicalDeliveryOfficeName","description","title","department",
        "company","manager","userAccountControl","lockoutTime","msDS-User-Account-Control-Computed","lastLogonTimestamp",
        "pwdLastSet","accountExpires","dNSHostName","operatingSystem","operatingSystemVersion",
        "location","managedBy","member","memberOf","primaryGroupID",
        "streetAddress","l","st","postalCode","co","c","homePhone","mobile",
        "facsimileTelephoneNumber","ipPhone","wWWHomePage","employeeID","employeeNumber",
        "division","profilePath","scriptPath","homeDirectory","homeDrive","userWorkstations",
        "info","directReports","servicePrincipalName","operatingSystemServicePack",
        "msDS-SupportedEncryptionTypes","lastLogoff","badPwdCount","badPasswordTime","msDS-UserPasswordExpiryTimeComputed","logonCount","userCertificate"
    )
}

function Remove-DomeniaSensitiveProperties {
    param($Properties)
    $safe = @{}
    if ($Properties -is [System.Collections.IDictionary]) {
        foreach ($key in @($Properties.Keys)) {
            if (-not (Test-DomeniaSensitiveAttributeName -Name ([string]$key))) { $safe[[string]$key] = @($Properties[$key]) }
        }
    }
    return $safe
}

function Entry-ToRawAttributes {
    param($Entry)
    $rows = New-Object Collections.ArrayList
    try {
        $props = $Entry.Properties
        if ($props -is [System.Collections.IDictionary]) {
            foreach ($name in @($props.Keys | Sort-Object)) {
                if (Test-DomeniaSensitiveAttributeName -Name ([string]$name)) { continue }
                $vals = foreach ($v in @($props[$name])) {
                    if ([string]$name -match "lastlogon|pwdlastset|accountexpires|badpasswordtime|lockouttime|expirationtime") { Convert-FileTimeLabel $v }
                    else { [string]$v }
                }
                [void]$rows.Add([pscustomobject]@{ Attribute=[string]$name; Value=($vals -join " ; ") })
            }
        }
        else {
            foreach ($name in @($props.PropertyNames | Sort-Object)) {
                if (Test-DomeniaSensitiveAttributeName -Name ([string]$name)) { continue }
                $vals = foreach ($v in @($props[$name])) {
                    if ($v -is [byte[]]) { [System.BitConverter]::ToString($v) }
                    elseif ([string]$name -match "lastlogon|pwdlastset|accountexpires|badpasswordtime|lockouttime|expirationtime") { Convert-FileTimeLabel $v }
                    else { [string]$v }
                }
                [void]$rows.Add([pscustomobject]@{ Attribute=[string]$name; Value=($vals -join " ; ") })
            }
        }
    } catch { Write-DomeniaSwallowed 'Core' 'Entry-ToRawAttributes' $_ }
    return @($rows)
}

function Apply-AutoTooltips {
    foreach ($control in @($script:Ctrl.Values)) { Initialize-DomeniaUxControlHelp -Control $control }
}






function Select-DomeniaWorkspace {
    # Amene l utilisateur sur le bon espace de travail et, si demande, sur
    # l onglet precis. Depuis la refonte, chaque espace occupe toute la
    # hauteur : il faut donc naviguer explicitement au lieu de compter sur
    # une pile verticale visible d un seul coup.
    param(
        [Parameter(Mandatory=$true)][string]$Workspace,
        [string]$Inner = "",
        [string]$Tab = ""
    )
    if ($Workspace -eq 'TabDirectory') { $Workspace = 'WsSearch' }
    # Keep previous widget/history routes valid after moving the workshop into Tools.
    if ($Workspace -eq 'WsQueryWorkshop') { $Workspace = 'TabApplicationTools'; $Inner = 'ApplicationToolTabs'; $Tab = 'WsQueryWorkshop' }
    $supportRoute=($Workspace -eq 'TabSupport')
    if ($supportRoute) { $Workspace = 'TabApplicationTools' }
    try {
        $ws = Get-DomeniaControl -Name "WorkspaceTabs"
        $target = Get-DomeniaControl -Name $Workspace
        if ($null -eq $ws -or $null -eq $target -or -not $target.IsEnabled -or $target.Visibility -ne [System.Windows.Visibility]::Visible) { return }
        # L08 (CO-06): a shortcut, a context menu or the palette never changes the profile. An Expert view asked from
        # Essentiel is shown alone for this navigation (hidden again at the next profile or selection update), or
        # refused with its reason; the saved profile is never touched here.
        if ((-not [string]::IsNullOrWhiteSpace($Tab)) -and ($null -ne (Get-Command -Name Get-DomeniaExpertTabDecision -CommandType Function -ErrorAction SilentlyContinue))) {
            $objectType = ''
            try { $objectType = [string]$script:SelectedObject.Type } catch { $objectType = '' }
            $allowExpert = $true
            try { $allowExpert = [bool](Get-CfgValue 'UI' 'AllowExpertProfile' $true) } catch { $allowExpert = $true }
            $decision = Get-DomeniaExpertTabDecision -Tab $Tab -Profile ([string]$script:CurrentUiProfile) -AllowExpert $allowExpert -ObjectType $objectType
            if ([bool]$decision.Expert -and -not [bool]$decision.Show) {
                Set-DomeniaContextHint -Title 'Vue non affichée' -Text ([string]$decision.Reason)
                Set-Status ([string]$decision.Reason) 'WARN'
                $Inner = ''; $Tab = ''
            }
            elseif ([bool]$decision.Temporary) {
                $expertTab = Get-DomeniaControl -Name $Tab
                if ($null -ne $expertTab) { $expertTab.Visibility = [System.Windows.Visibility]::Visible }
                Set-DomeniaContextHint -Title 'Vue Expert ponctuelle' -Text ([string]$decision.Reason)
            }
        }
        $ws.SelectedItem = $target
        if ($supportRoute) {
            (Get-DomeniaControl 'ApplicationToolTabs').SelectedItem=Get-DomeniaControl 'TabSupport'
            Invoke-DomeniaSupportLoad
        }
        if (-not [string]::IsNullOrWhiteSpace($Inner) -and -not [string]::IsNullOrWhiteSpace($Tab)) {
            $innerControl = Get-DomeniaControl -Name $Inner
            $tabControl = Get-DomeniaControl -Name $Tab
            # Decision David 2026-10-07: Fiabilite and Operations et confort are hidden and shown only when routed to.
            if ($null -ne $tabControl -and $Tab -in @('TabGuard') -and $tabControl.Visibility -ne [System.Windows.Visibility]::Visible) { $tabControl.Visibility = [System.Windows.Visibility]::Visible }
            # UX-21 (X04): Assistance poste has five views; a former tab name resolves to its view and inner tab.
            $computerView = (($Inner -eq 'ComputerTabs') -and ($null -ne (Get-Command -Name 'Select-DomeniaComputerView' -CommandType Function -ErrorAction SilentlyContinue)))
            if ($computerView) { [void](Select-DomeniaComputerView -Tab $Tab) }
            elseif (($null -ne $innerControl) -and ($null -ne $tabControl)) { $innerControl.SelectedItem = $tabControl }
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Select-DomeniaWorkspace' $_ }
    try { Sync-DomeniaUxNavigation } catch { Write-DomeniaSwallowed 'Core' 'Select-DomeniaWorkspace' $_ }
}

function Get-DomeniaLandingView {
    # UX-27 : ouvrir la fiche sur ce qui se lit. Le Resume (Type, Classe, GUID, DN) reste le point de chute
    # des objets que l'application ne sait pas nommer ; un utilisateur, un poste, un groupe et une branche
    # ont une page utile, et y tomber evite de deplier deux onglets pour lire la premiere information.
    # Le poste n'habite pas la fiche : sa vue d'ensemble est un onglet de l'espace Poste, d'ou la destination
    # complete (espace, onglets internes, onglet) plutot qu'un simple nom d'onglet. UX-21 : la vue d'ensemble
    # (TabComputer) reunit la fiche du poste et le tableau de bord de son dernier inventaire.
    param([AllowEmptyString()][AllowNull()][string]$Type='')
    switch ($Type) {
        'Utilisateur' { return [pscustomobject]@{Workspace='WsObject';Inner='DetailTabs';Tab='TabUser'} }
        'Machine' { return [pscustomobject]@{Workspace='WsComputer';Inner='ComputerTabs';Tab='TabComputer'} }
        'Groupe' { return [pscustomobject]@{Workspace='WsObject';Inner='DetailTabs';Tab='TabGroup'} }
        'OU' { return [pscustomobject]@{Workspace='WsObject';Inner='DetailTabs';Tab='TabContainer'} }
        'Conteneur' { return [pscustomobject]@{Workspace='WsObject';Inner='DetailTabs';Tab='TabContainer'} }
        default { return [pscustomobject]@{Workspace='WsObject';Inner='DetailTabs';Tab='TabGeneric'} }
    }
}

function Set-VisibleTabsForType {
    # Un utilisateur et un poste n ont pas les memes onglets. Les espaces et
    # les onglets sans objet a montrer sont masques plutot que laisses vides.
    param([string]$Type,[switch]$PreserveWorkspace)

    foreach ($t in @(
        "TabUser","TabUserContact","TabUserAdmin","TabGroup","TabContainer",
        "TabComputer","TabComputerAdmin","TabComputerDetails","TabSecurity","TabComputerHealth","TabComputerChecks","TabInventory","TabSoftware","TabWmi",
        "TabPermissions"
    )) { Set-TabVisibility $t $false }

    # Commandes was removed from the tools (decision David 2026-10-07): it is never shown again here.
    foreach ($t in @("TabDashboard","TabApplicationTools","TabSelfCheck","TabIndex","WsQueryWorkshop","TabDomain","TabLog","WsSearch","TabRelations","TabAccounts")) { Set-TabVisibility $t $true }

    $hasObject = -not [string]::IsNullOrWhiteSpace($Type)
    foreach ($t in @("TabGeneric","TabRaw")) { Set-TabVisibility $t $hasObject }
    Set-TabVisibility "TabMemberOf" ($Type -in @("Utilisateur","Machine","Groupe"))
    Set-TabVisibility "TabPermissions" $hasObject
    # UX-09 (L08): Fiche and Poste stay reachable without a selection; their page then shows its empty state
    # (search field and recent fiches from the local memory, no network), see Update-DomeniaUxEmptyStates.
    Set-TabVisibility "WsObject" $true
    Set-TabVisibility "WsComputer" $true

    switch ($Type) {
        "Utilisateur" {
            foreach ($t in @("TabUser","TabUserContact","TabUserAdmin")) { Set-TabVisibility $t $true }
        }
        "Machine" {
            # UX-21 (X04): Vue d'ensemble, Intervenir, Détails (Inventaire, Logiciels), Diagnostic (Contrôles, WMI), Secrets.
            foreach ($t in @("TabComputer","TabComputerAdmin","TabComputerDetails","TabComputerHealth","TabComputerChecks","TabInventory","TabSoftware","TabWmi","TabSecurity")) { Set-TabVisibility $t $true }
        }
        "Groupe" { Set-TabVisibility "TabGroup" $true }
        "OU" { Set-TabVisibility "TabContainer" $true }
        "Conteneur" { Set-TabVisibility "TabContainer" $true }
    }

    if (-not $PreserveWorkspace -and -not $hasObject) {
        Select-DomeniaWorkspace -Workspace "TabDashboard"
    }
    elseif (-not $PreserveWorkspace) {
        $landing = Get-DomeniaLandingView -Type $Type
        Select-DomeniaWorkspace -Workspace $landing.Workspace -Inner $landing.Inner -Tab $landing.Tab
    }
    Update-DomeniaUxProfileVisibility -ObjectType $Type
    Apply-DomeniaGuiElementPolicy
    Sync-DomeniaUxNavigation
    Assert-DomeniaWorkspaceSelection
    if ($PreserveWorkspace) { Request-DomeniaDashboardRefresh } else { Update-Dashboard }
}

function Assert-DomeniaWorkspaceSelection {
    # Masquer l espace actif laisserait une zone vide : on bascule alors sur
    # le premier espace encore visible.
    try {
        $tabs = Get-DomeniaControl -Name "WorkspaceTabs"
        if ($null -eq $tabs) { return }
        $current = $tabs.SelectedItem
        if ($null -ne $current -and $current.Visibility -eq [System.Windows.Visibility]::Visible) { return }
        foreach ($item in @($tabs.Items)) {
            if ($item.Visibility -eq [System.Windows.Visibility]::Visible) { $tabs.SelectedItem = $item; return }
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Assert-DomeniaWorkspaceSelection' $_ }
}





function Complete-DomeniaTreeChildrenUi {
    param($Result,$State)
    $treeNode = $null
    try { $treeNode = $State.Node } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaTreeChildrenUi' $_ }
    if ($null -eq $treeNode) { throw "Nud d'arborescence absent du callback." }

    try {
        $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Rows","Records")
        if ($null -eq $effective) { throw "Resultat d'arborescence vide ou invalide." }
        Submit-DomeniaDirectoryTreeRead -Result $effective -State $State
    }
    catch {
        try {
            $treeNode.Items.Clear()
            [void]$treeNode.Items.Add("Erreur d'affichage  replie puis redeplie pour reessayer")
            $treeNode.Tag.Loaded = $false
            $treeNode.Tag | Add-Member -NotePropertyName Loading -NotePropertyValue $false -Force
            $treeNode.IsEnabled = $true
        }
        catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaTreeChildrenUi' $_ }
        throw
    }
}

function Fail-DomeniaTreeChildrenUi {
    param($Message,$State)
    if($null -ne $State -and $null -ne $State.PSObject.Properties['DirectoryPipe'] -and -not $State.DirectoryPipe.Completed){
        try{$State.DirectoryPipe.Stop.Cancel()}catch{Write-DomeniaSwallowed 'Core' 'Fail-DomeniaTreeChildrenUi' $_}
        Complete-DomeniaDirectoryReadPipe -Pipe $State.DirectoryPipe -Error ([string]$Message)
        return
    }
    if($null -ne $State -and $null -ne $State.PSObject.Properties['StoreContext'] -and -not (Test-DomeniaDirectoryTreeCurrent $State)){return}
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue." }
    $treeNode = $null
    try { $treeNode = $State.Node } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaTreeChildrenUi' $_ }
    try {
        if ($null -ne $treeNode) {
            Stop-DomeniaTreeRenderForNode -Node $treeNode
            try { $treeNode.Tag | Add-Member -NotePropertyName Loading -NotePropertyValue $false -Force } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaTreeChildrenUi' $_ }
            $preserve = $false
            try { $preserve = [bool]$State.PreserveExisting } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaTreeChildrenUi' $_ }
            if ($preserve -and $null -ne $State.PreviousItems) {
                $treeNode.Items.Clear()
                foreach ($oldItem in @($State.PreviousItems)) { [void]$treeNode.Items.Add($oldItem) }
                try { $treeNode.Tag.Loaded = [bool]$State.PreviousLoaded } catch { $treeNode.Tag.Loaded = $true }
                $treeNode.IsEnabled = $true
            }
            else {
                $treeNode.Items.Clear()
                [void]$treeNode.Items.Add("Erreur : $detail  replie puis redeplie pour reessayer")
                $treeNode.Tag.Loaded = $false
                $treeNode.IsEnabled = $true
            }
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaTreeChildrenUi' $_ }
    [void](Set-DomeniaControlText -Name "LblTreeStatus" -Text "Erreur : $detail")
    Set-Status "Erreur arborescence : $detail" "ERROR"
}

function Load-TreeChildren {
    param($Node,[switch]$PreserveExisting,[switch]$Force)
    try {
        if ($null -eq $Node -or ([bool]$Node.Tag.Loaded -and -not $Force)) { return }
        # UI-16: the node is no longer greyed while it is read; a second unfold during that read starts nothing.
        # A read that never answered (withdrawn from the queue) stops blocking after its timeout.
        $loadingAt = $null
        try { $loadingAt = $Node.Tag.LoadingAt } catch { Write-DomeniaSwallowed 'Core' 'Load-TreeChildren' $_ }
        $reading = ([bool]$Node.Tag.Loading -and $loadingAt -is [datetime] -and ([datetime]::UtcNow - $loadingAt).TotalSeconds -lt ([int](Get-CfgValue "Async" "TreeTimeoutSeconds" 30) + 15))
        if (-not $Force -and ($reading -or -not [string]::IsNullOrWhiteSpace([string]$Node.Tag.RenderId))) { return }
        $dn = [string]$Node.Tag.DN
        $name = [string]$Node.Tag.Name
        Stop-DomeniaTreeRenderForNode -Node $Node
        $previousItems = @()
        $previousLoaded = $false
        if ($PreserveExisting) {
            try { $previousItems = @($Node.Items); $previousLoaded = [bool]$Node.Tag.Loaded } catch { $previousItems = @(); $previousLoaded = $false }
        }
        $Node.Items.Clear(); [void]$Node.Items.Add((New-DomeniaTreeLoadingItem))
        $Node.Tag | Add-Member -NotePropertyName Loading -NotePropertyValue $true -Force
        $Node.Tag | Add-Member -NotePropertyName LoadingAt -NotePropertyValue ([datetime]::UtcNow) -Force
        $requestId=[guid]::NewGuid().ToString('D')
        $treeContext=New-DomeniaStoreContext -RequestId $requestId -Generation ([long]$script:GlobalSearchGeneration) -ScopeDn $dn -Subtree $false
        $Node.Tag|Add-Member NoteProperty DirectoryReadId $requestId -Force
        $treeState=[pscustomobject]@{Node=$Node;DN=$dn;Name=$name;StoreContext=$treeContext;PreserveExisting=[bool]$PreserveExisting;PreviousItems=@($previousItems);PreviousLoaded=$previousLoaded}
        $treePipe=New-DomeniaDirectoryReadPipe -Context $treeContext -CompleteHandler 'Complete-DomeniaDirectoryTreeRead' -ErrorHandler 'Fail-DomeniaDirectoryTreeCommit' -CallbackState $treeState
        $treeState|Add-Member NoteProperty DirectoryPipe $treePipe
        $code = @'
$Payload.DirectoryReadState.Started=$true
try {
$filter = "(|(objectClass=organizationalUnit)(objectClass=container)(objectClass=builtinDomain))"
$props = @("name","distinguishedName","objectClass","objectGUID","whenChanged","uSNChanged","description","managedBy")
$s = New-WSearcher $Context ([string]$Payload.DN) $filter $props "OneLevel" 0
$rows = New-Object Collections.ArrayList
$records = New-Object Collections.ArrayList
$all=$null;$root=$s.SearchRoot
try {
$all=$s.FindAll()
foreach ($r in $all) {
    if($Payload.StopToken.IsCancellationRequested){throw 'Lecture de branche arretee.'}
    $type = Get-WObjectType $r.Properties
    $dn = [string](Get-WPropFirst $r.Properties "distinguishedname" "")
    if ([string]::IsNullOrWhiteSpace($dn)) { continue }
    [void]$rows.Add([pscustomobject]@{ Name=[string](Get-WPropFirst $r.Properties "name" ""); DN=$dn; Kind=$type })
    $record=[pscustomobject]@{Properties=(New-WDirectoryStoreProperties $r.Properties $props);Type=$type;ObservedUtc=[datetime]::UtcNow.ToString('o');Source=[string]$Context.Server}
    while($Payload.Progress.Count -ge 1000){if($Payload.StopToken.IsCancellationRequested){throw 'Lecture de branche arretee.'};[Threading.Thread]::Sleep(10)}
    $Payload.Progress.Enqueue($record)
    [void]$records.Add($record)
}
$final=[pscustomobject]@{Rows=@($rows | Sort-Object Name);Records=@($records)}
$Payload.DirectoryReadState.Final=$final
$final
}finally{if($null -ne $all){$all.Dispose()};$s.Dispose();if($null -ne $root){$root.Dispose()}}
}catch{$Payload.DirectoryReadState.Error=$_.Exception.Message;throw}finally{$Payload.DirectoryReadState.Done=$true}
'@
        Start-UiTask -Name "Arborescence $name" -OperationId "TreeChildren" -Code $code -Payload ([pscustomobject]@{DN=$dn;Progress=$treePipe.Input;DirectoryReadState=$treePipe.Collector;StopToken=$treePipe.Stop.Token}) -CallbackState $treeState -ReplaceKey "tree:$dn" -TimeoutSeconds ([int](Get-CfgValue "Async" "TreeTimeoutSeconds" 30)) -StatusText "Chargement des sous-branches de $name..." -SuccessHandler "Complete-DomeniaTreeChildrenUi" -ErrorHandler "Fail-DomeniaTreeChildrenUi" | Out-Null
    }
    catch {
        $message = [string]$_.Exception.Message
        try {
            $Node.Items.Clear(); [void]$Node.Items.Add("Erreur : $message  replie puis redeplie pour reessayer")
            $Node.Tag.Loaded = $false
            $Node.Tag | Add-Member -NotePropertyName Loading -NotePropertyValue $false -Force
            $Node.IsEnabled = $true
        } catch { Write-DomeniaSwallowed 'Core' 'Load-TreeChildren' $_ }
        [void](Set-DomeniaControlText -Name "LblTreeStatus" -Text "Erreur : $message")
        Set-Status "Erreur arborescence : $message" "ERROR"
    }
}

function Get-BranchQueryData {
    # Compatibilite des appels internes : les controles visibles font autorite.
    $scope = Get-DomeniaSearchScope -Mode OU
    $typeFilter = Get-GlobalSelectedTypeFilter -Mode OU
    $searchFilter = Get-SearchLdapFilter (Get-DomeniaSearchText -Mode OU)
    $filter = if ([string]::IsNullOrWhiteSpace($searchFilter)) { $typeFilter } else { "(&$typeFilter$searchFilter)" }
    $limit = 100
    try { $limit = [int](Get-DomeniaControl -Name 'TxtGlobalLimit').Text } catch { Write-DomeniaSwallowed 'Core' 'Get-BranchQueryData' $_ }
    if ($limit -le 0) { $limit = 100 }; $limit = [Math]::Min(20000,$limit)
    [pscustomobject]@{BaseDn=$scope.BaseDn;Scope=$scope.Scope;Filter=$filter;Limit=$limit}
}



function Complete-DomeniaBranchObjectsUi {
    param($Result,$State)
    if (-not (Test-DomeniaSearchStateCurrent -State $State)) { return }
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Rows")
    if ($null -eq $effective) { throw "Resultat de branche vide ou invalide." }
    if ([string](Get-DomeniaMember $effective 'DataSource' '') -cne 'SQLite') { throw 'Affichage refuse : branche non relue depuis la base locale.' }
    $rows = @($effective.Rows)
    Set-VisitCacheValue -Key ([string]$State.CacheKey) -Value $rows
    Show-ObjectRows -Rows $rows -Label "$($rows.Count) objet(s)"
    Set-Status "Branche chargee : $($rows.Count) objet(s)."
}

function Load-BranchObjects {
    # Anciennes actions de branche : un seul moteur et une seule generation.
    # -Browse: an OU-side gesture (branch button, OU search box, OU type filter, tree menu) browses the OU even
    # when the last search was global (D032); without it, a refresh re-runs the current search mode.
    param([switch]$Browse)
    Update-DomeniaSearchScopeUi
    $mode = if ($Browse) { 'OU' } else { Get-DomeniaSearchMode }
    Invoke-GlobalSearch -AllowEmpty -SilentError -PreserveSelection -SearchMode $mode
}

function Complete-DomeniaGlobalSearchUi {
    param($Result,$State)
    if ($null -ne $State -and $null -ne $State.PSObject.Properties["LiveState"]) { Complete-DomeniaLiveSearch -Result $Result -State $State; return }

    # Une ancienne recherche peut finir apres avoir ete remplacee. Elle ne doit
    # jamais repeupler la grille ni modifier le statut d'une recherche plus recente.
    $generation = 0
    try { $generation = [int]$State.Generation } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaGlobalSearchUi' $_ }
    if ($generation -ne [int]$script:GlobalSearchGeneration) {
        Add-DomeniaUiLog -Area "Recherche" -Level "DEBUG" -Text "Resultat obsolete ignore."
        return
    }

    if (-not (Test-DomeniaSearchStateCurrent -State $State)) { return }

    $query = ""
    try { $query = [string]$State.Search } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaGlobalSearchUi' $_ }
    try {
        $box = Get-DomeniaControl -Name "TxtGlobalSearch"
        if ($null -ne $box -and ([string]$box.Text).Trim() -ne $query) {
            Add-DomeniaUiLog -Area "Recherche" -Level "DEBUG" -Text "Resultat ignore : le texte de recherche a change."
            return
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaGlobalSearchUi' $_ }

    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Rows")
    if ($null -eq $effective) { throw "Resultat de recherche vide ou invalide." }
    if ([string](Get-DomeniaMember $effective 'DataSource' '') -cne 'SQLite') { throw 'Affichage refuse : recherche non relue depuis la base locale.' }

    if (-not [string]::Equals([string]$effective.BaseDn,[string]$State.BaseDn,[StringComparison]::OrdinalIgnoreCase) -or [string]$effective.Scope -ne [string]$State.Scope) {
        throw 'Resultat rejete : le perimetre retourne ne correspond pas a la requete.'
    }
    $rows = @($effective.Rows)
    $resultLabel = "$($rows.Count) resultat(s)"
    if ([bool]$effective.LimitReached) { $resultLabel += ' | limite atteinte, affinez la recherche' }
    $rawCount = 0
    $durationMs = 0
    $serverUsed = ""
    $baseUsed = ""
    $filtersUsed = @()
    try { $rawCount = [int]$effective.RawCount } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaGlobalSearchUi' $_ }
    try { $durationMs = [long]$effective.DurationMs } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaGlobalSearchUi' $_ }
    try { $serverUsed = [string]$effective.Server } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaGlobalSearchUi' $_ }
    try { $baseUsed = [string]$effective.BaseDn } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaGlobalSearchUi' $_ }
    try { $filtersUsed = @($effective.Filters) } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaGlobalSearchUi' $_ }

    $cacheKey = [string]$State.CacheKey
    if ($rows.Count -gt 0) {
        Set-VisitCacheValue -Key $cacheKey -Value $rows
    }
    else {
        try { if ($script:VisitCache.ContainsKey($cacheKey)) { [void]$script:VisitCache.Remove($cacheKey) } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaGlobalSearchUi' $_ }
    }

    # La recherche n ouvre aucune fiche automatiquement. En revanche, chaque
    # machine nouvellement listee recoit un UNIQUE echo ICMP court en arriere-plan
    # pour renseigner Presence. Un resultat de presence encore frais est reutilise,
    # ce qui evite de repinger la meme machine lors du passage base locale -> AD.
    $renderWatch = [System.Diagnostics.Stopwatch]::StartNew()
    if ($rows.Count -eq 0) {
        # La selection a deja ete purgee AVANT le lancement de la recherche.
        # Repasser par Reset-DomeniaSelectionBoundViews ici coutait jusqu'a ~1 s
        # meme pour zero resultat. On ne fait que vider la grille.
        $script:BranchObjects = @()
        $script:BranchCountLabel = "0 resultat(s) dans ce perimetre"
        $script:SuppressGridSelectionEvents = $true
        try {
            [void](Set-DomeniaItemsSource -Name "DgObjects" -Rows @())
            $grid0 = Get-DomeniaControl -Name "DgObjects"
            if ($null -ne $grid0) { $grid0.SelectedItem = $null; $grid0.SelectedIndex = -1 }
        }
        finally { $script:SuppressGridSelectionEvents = $false }
        [void](Set-DomeniaControlText -Name "LblBranchCount" -Text "0 resultat(s) dans ce perimetre")
        Request-DomeniaDashboardRefresh
    }
    else {
        Show-ObjectRows -Rows $rows -Label $resultLabel -NoAutoOpen -PreserveSelectionDn ([string]$State.PreserveSelectionDn)
    }
    $renderWatch.Stop()
    if ($renderWatch.ElapsedMilliseconds -gt 250) {
        Write-AppLog "Recherche globale : rendu UI lent, $([long]$renderWatch.ElapsedMilliseconds) ms pour $($rows.Count) ligne(s)." "WARN"
    }

    $serverLabel = if ([string]::IsNullOrWhiteSpace($serverUsed)) { "controleur decouvert automatiquement" } else { $serverUsed }
    if ($rows.Count -eq 0) {
        # Aucun calcul flou ici. L ancienne suggestion parcourait tout l index local
        # sur le thread WPF et pouvait figer l interface pendant plusieurs dizaines
        # de secondes, jusqu a proposer exactement le texte deja saisi.
        $typeLabel = "Tous"
        try {
            $typeItem = (Get-DomeniaControl -Name "CmbGlobalType").SelectedItem
            if ($null -ne $typeItem -and -not [string]::IsNullOrWhiteSpace([string]$typeItem.Content)) {
                $typeLabel = [string]$typeItem.Content
            }
        }
        catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaGlobalSearchUi' $_ }
        $filterNote = if ($typeLabel -eq "Tous") { "" } else { " Filtre actif : $typeLabel." }
        Set-Status "Aucun résultat dans $($State.BaseDn) pour « $query ».$filterNote" "WARN"
    }
    else {
        Set-Status "Recherche terminée : $($rows.Count) résultat(s) en $durationMs ms sur $serverLabel."
    }

    $filterSummary = (@($filtersUsed) -join " || ")
    Write-AppLog "Recherche globale '$query' : affiches=$($rows.Count), bruts=$rawCount, duree=${durationMs}ms, serveur=$serverLabel, base=$baseUsed, filtres=$filterSummary" "INFO"
}

function Fail-DomeniaGlobalSearchUi {
    param($Message,$State)
    if ($null -ne $State -and $null -ne $State.PSObject.Properties["LiveState"]) { Fail-DomeniaLiveSearch -Message $Message -State $State; return }

    $generation = 0
    try { $generation = [int]$State.Generation } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaGlobalSearchUi' $_ }
    if ($generation -ne [int]$script:GlobalSearchGeneration) {
        Add-DomeniaUiLog -Area "Recherche" -Level "DEBUG" -Text "Erreur d'une recherche obsolete ignoree."
        return
    }

    if (-not (Test-DomeniaSearchStateCurrent -State $State)) { return }

    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue." }
    $query = ""
    try { $query = [string]$State.Search } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaGlobalSearchUi' $_ }
    [void](Set-DomeniaControlText -Name "LblBranchCount" -Text "Recherche en erreur")
    $noPopup = $false
    try { $noPopup = [bool]$State.NoPopup } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaGlobalSearchUi' $_ }
    [void](Show-DomeniaOperationError -Operation "Recherche Active Directory '$query'" -ErrorRecordOrException $detail -NoPopup:$noPopup)
}

function Clear-DomeniaGlobalSearch {
    Stop-DomeniaLiveSearch
    try {
        $localFilter=Get-DomeniaControl 'TxtSuiteResultFilter'
        if($null -ne $localFilter){$localFilter.Clear()}
        $script:GlobalSearchGeneration++
        try { if ($null -ne $script:LiveSearchTimer) { $script:LiveSearchTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Clear-DomeniaGlobalSearch' $_ }

        foreach ($id in @($script:AsyncJobs.Keys)) {
            $job = $script:AsyncJobs[$id]
            if ($null -ne $job -and [string]$job.ReplaceKey -in @("global","branch") -and -not [bool]$job.IsWrite) {
                Request-UiTaskStop -Id $id -Silent -Force -Superseded
            }
        }

        [void](Set-DomeniaControlText -Name "TxtGlobalSearch" -Text "")
        $script:BranchObjects = @()
        $script:BranchCountLabel = "0 resultat"
        [void](Set-DomeniaControlText -Name 'TxtBranchSearch' -Text '')
        Set-DomeniaSearchMode -Mode OU
        Stop-DomeniaSelectionOpenTimer
        $script:PendingObjectSelection = $null
        [void](Set-DomeniaItemsSource -Name "DgObjects" -Rows @())
        [void](Set-DomeniaControlText -Name "LblBranchCount" -Text "0 resultat")
        Reset-DomeniaSelectionBoundViews
        Request-DomeniaDashboardRefresh
        Update-DomeniaSearchScopeUi
        Select-DomeniaWorkspace -Workspace 'WsSearch'
        Set-Status "Recherche effacee. Le filtre OU est conserve."
    }
    catch {
        Write-AppLog "Effacement de la recherche impossible : $($_.Exception.ToString())" "ERROR"
        Set-Status "Erreur lors de l'effacement de la recherche : $($_.Exception.Message)" "ERROR"
    }
}

function Invoke-GlobalSearch {
    # D037 / UX-33: -ViewScope, -ExpectBaseDn and -ExpectScope let 'Charger la suite' read the same perimeter again
    # (view chip choice, base and depth of the list), whatever the chip or the tree show now.
    # CO-05: -KeepLocalFilter keeps the filter of the list for a gesture that brings its own (favourite, history list).
    # MO-07: -Continuation (New-DomeniaContinuationRequest) adds only the next rows to the list on screen: same search,
    # same generation, no new history entry, the rows already loaded stay where they are.
    # FO-01: -Contains reads the names that contain the typed words (explicit chip, upper bar only), same limit and perimeter.
    param([switch]$SilentError,[switch]$AllowEmpty,[switch]$PreserveSelection,
        [ValidateSet('Global','OU')][string]$SearchMode = 'Global',
        [string]$ViewId = '',[int]$LimitOverride = 0,
        [ValidateSet('','OU','Domain')][string]$ViewScope = '',[string]$ExpectBaseDn = '',[string]$ExpectScope = '',
        [switch]$KeepLocalFilter,$Continuation = $null,[switch]$Contains)

    if(Test-DomeniaAccessBusyWrite){Set-Status 'Recherche différée : écriture active ou à vérifier.' 'WARN';return}
    if(-not (Test-DomeniaDraftNavigation -DN "")){return}
    if (($null -ne $Continuation) -and ((-not [bool](Get-DomeniaMember $Continuation 'Valid' $false)) -or (-not (Test-DomeniaLiveSearchActive)) -or
        (-not (Test-DomeniaContinuationCurrent -Continuation $Continuation -Reader ([string]$script:Live.Identity) -Generation ([long]$script:GlobalSearchGeneration) -BaseDn ([string]$script:Live.Search.State.BaseDn))))) {
        Set-Status 'Suite non chargée : la liste affichée nʼest plus la recherche courante. Relancez la recherche.' 'WARN'
        return
    }
    $navHook = $null
    try {
        $searchBox = Get-DomeniaControl -Name "TxtGlobalSearch"
        if ($null -eq $searchBox) { throw "Champ de recherche introuvable." }

        # D038: a work view is a read-only filter chosen in a list. It replaces the typed text of its
        # own mode and never carries an account, a right or a write mode.
        $view = $null
        $viewChoice = ''
        if (-not [string]::IsNullOrWhiteSpace($ViewId)) {
            $view = @(Get-DomeniaWorkViews | Where-Object { [string]$_.Id -ceq $ViewId } | Select-Object -First 1)
            if ($view.Count -eq 0) { Set-Status 'Requête inconnue : aucune recherche lancée.' 'WARN'; return }
            $view = $view[0]
            # UX-33: the view applies to the OU chosen in the tree; the whole domain only on the explicit secondary
            # choice of the 'Dans :' chip, and such a list never offers a survey of its workstations.
            $viewChoice = 'OU'
            if ($ViewScope) { $viewChoice = $ViewScope }
            elseif ($null -ne (Get-Command Get-DomeniaWorkViewScopeChoice -CommandType Function -ErrorAction SilentlyContinue)) { $viewChoice = Get-DomeniaWorkViewScopeChoice }
            $viewOu = Get-DomeniaSearchScope -Mode OU
            $viewOuName = ''
            if ($null -ne (Get-Command Get-DomeniaUxOuDisplay -CommandType Function -ErrorAction SilentlyContinue)) { try { $viewOuName = [string](Get-DomeniaUxOuDisplay -DistinguishedName ([string]$viewOu.BaseDn) -IsDomain ([bool]$viewOu.IsDomain)).Name } catch { Write-DomeniaSwallowed 'Core' 'Invoke-GlobalSearch' $_ } }
            $viewPlan = Get-DomeniaWorkViewPlan -View $view -Choice $viewChoice -OuDn ([string]$viewOu.BaseDn) -DomainDn ([string]$script:Conn.BaseDn) -Subtree ([string]$viewOu.Scope -eq 'Subtree') -OuName $viewOuName
            $SearchMode = [string]$viewPlan.SearchMode
            if ($SearchMode -eq 'OU' -and [string]::IsNullOrWhiteSpace([string]$script:SelectedBranchDn)) { Set-Status 'Choisissez dʼabord une OU dans lʼarbre pour cette vue.' 'WARN'; return }
            [void](Set-DomeniaControlText -Name $(if ($SearchMode -eq 'Global') { 'TxtGlobalSearch' } else { 'TxtBranchSearch' }) -Text '')
        }

        $textValue = Get-DomeniaSearchText -Mode $SearchMode
        # FO-05: the chip of the upper bar narrows the bar search only; a work view « Dans : tout le domaine » reads the
        # domain root (its own chip), never the OU chosen for the bar.
        $scope = Get-DomeniaSearchScope -Mode $SearchMode -IgnoreBar:($null -ne $view)
        # D037: a continuation reads the perimeter of its list or nothing.
        if (($ExpectBaseDn -and -not [string]::Equals([string]$scope.BaseDn,$ExpectBaseDn,[StringComparison]::OrdinalIgnoreCase)) -or ($ExpectScope -and [string]$scope.Scope -ne $ExpectScope)) {
            Set-Status 'Suite non chargée : le périmètre de la liste a changé. Relancez la recherche.' 'WARN'
            return
        }
        $minChars = [Math]::Max(1,[int](Get-CfgValue "Browser" "GlobalSearchMinChars" 2))
        # CO-34: checked before any request and according to the mode. The upper bar refuses a text made only of
        # asterisks (it would list the whole domain); in an OU such a text lists the OU, as browsing does.
        $textCheck = Get-DomeniaSearchTextCheck -Text $textValue -Mode $SearchMode -MinimumLength $minChars
        if (-not [bool]$textCheck.Valid) {
            [void](Set-DomeniaControlText -Name 'LblSearchHint' -Text ([string]$textCheck.Reason))
            Set-Status ([string]$textCheck.Reason) 'WARN'
            return
        }
        $isBrowse = [bool]$textCheck.Browse
        # D033/D035/D036: optional explicit syntax, pasted identifiers and multi-word fallback (global bar only).
        $searchPlan = $null
        $searchHint = ''
        if ($null -ne $view) {
            $searchHint = 'Vue : ' + [string]$view.Name + ' · ' + [string]$viewPlan.ChipText + $(if ([string]$view.Note) { ' · ' + [string]$view.Note } else { '' })
            if (-not [bool]$viewPlan.SurveyAllowed) { $searchHint += ' · ' + [string]$viewPlan.Reason }
        }
        elseif ($SearchMode -eq 'Global' -and -not $isBrowse) {
            $searchPlan = Get-DomeniaGlobalSearchPlan -Text $textValue -TypeFilter (Get-GlobalSelectedTypeFilter -Mode Global) -MinimumLength $minChars -SyntaxEnabled (Get-DomeniaFeatureFlag -Name 'SearchSyntax' -Default $true)
            $searchHint = [string]$searchPlan.Hint
            if (-not [bool]$searchPlan.Valid) {
                [void](Set-DomeniaControlText -Name 'LblSearchHint' -Text $searchHint)
                Set-Status ([string]$searchPlan.Reason) 'WARN'
                return
            }
        }
        # FO-01: the « contains » chip asks for the names that contain the words; nothing else changes (limit, perimeter).
        $containsPlan = $null
        if ($Contains -and ($SearchMode -eq 'Global') -and ($null -eq $view) -and (-not $isBrowse)) {
            $containsPlan = New-DomeniaContainsFilter -Text $textValue -TypeFilter (Get-GlobalSelectedTypeFilter -Mode Global)
            if (-not [bool]$containsPlan.Valid) {
                [void](Set-DomeniaControlText -Name 'LblSearchHint' -Text ([string]$containsPlan.Reason))
                Set-Status ([string]$containsPlan.Reason) 'WARN'
                return
            }
            $searchHint = 'Noms qui contiennent « ' + $textValue.Trim() + ' » : lecture plus longue, lʼannuaire parcourt tous les noms du périmètre.'
        }

        $preserveDn = ''
        if ($PreserveSelection) {
            $selectedGrid = Get-DomeniaControl -Name 'DgObjects'
            if ($null -ne $selectedGrid -and $null -ne $selectedGrid.SelectedItem) { $preserveDn = [string]$selectedGrid.SelectedItem.DN }
        }
        # MO-07: a continuation adds rows to the list on screen; it is not a new place of the history.
        $continuing = ($null -ne $Continuation)
        if (-not $continuing) {
            # D040: the place being left is saved before this search changes the list (no request involved).
            $navHook = Get-Command Enter-DomeniaNavSearch -CommandType Function -ErrorAction SilentlyContinue
            if ($null -ne $navHook) { Enter-DomeniaNavSearch }
        }
        # CO-05: a new search starts with an empty filter of the list, after the place being left was saved with it.
        # A refresh, a continuation, a favourite or a history list keep the filter that goes with their list.
        if ((-not $PreserveSelection) -and (-not $KeepLocalFilter) -and ($LimitOverride -le 0) -and (-not $continuing)) {
            $localFilter = Get-DomeniaControl -Name 'TxtSuiteResultFilter'
            if (($null -ne $localFilter) -and (-not [string]::IsNullOrEmpty([string]$localFilter.Text))) {
                $oldExperience = [bool]$script:ExperienceRestoring
                $script:ExperienceRestoring = $true
                try { $localFilter.Text = '' } finally { $script:ExperienceRestoring = $oldExperience }
            }
        }
        if (-not $continuing) {
            Set-DomeniaSearchMode -Mode $SearchMode
            Invalidate-DomeniaSearchResults -KeepSelection:([bool]$preserveDn)
        }
        $generation = [int]$script:GlobalSearchGeneration
        $script:ActiveSearchViewId = $(if ($null -ne $view) { [string]$view.Id } else { '' })
        # UX-33: a work view listed over the whole domain refuses ping, detection and analysis of its rows.
        $script:ListSurveyBlocked = ($null -ne $view -and -not [bool]$viewPlan.SurveyAllowed)
        [void](Set-DomeniaControlText -Name 'LblSearchHint' -Text $searchHint)
        if (-not $continuing) { Update-DomeniaSearchScopeUi }
        if (-not $PreserveSelection) { Select-DomeniaWorkspace -Workspace 'WsSearch' }

        $limit = [int](Get-CfgValue "Browser" "GlobalSearchLimit" 100)
        try { $limit = [int]((Get-DomeniaControl -Name "TxtGlobalLimit").Text) } catch { Write-DomeniaSwallowed 'Core' 'Invoke-GlobalSearch' $_ }
        # D037: an explicit 'Charger la suite' raises the bound for this query only; the field keeps the operator value.
        if ($LimitOverride -gt 0) { $limit = $LimitOverride }
        # MO-07: the list is brought to the target size of the continuation; only Target - Loaded rows are read.
        if ($continuing) { $limit = [int](Get-DomeniaMember $Continuation 'Target' $limit) }
        if ($limit -le 0) { $limit = 100 }
        # Decision David 2026-10-05: at least 10 000 results must be displayable (former cap 500).
        if ($limit -gt 20000) { $limit = 20000 }
        if (($LimitOverride -le 0) -and (-not $continuing)) { [void](Set-DomeniaControlText -Name "TxtGlobalLimit" -Text ([string]$limit)) }

        # Une nouvelle recherche repart toujours sans selection. DOMENIA affiche les
        # resultats mais ne choisit jamais une ligne a la place de l'operateur,
        # meme lorsqu'il n'y a qu'un seul resultat. Cette purge est faite sous
        # garde pour ne pas declencher un SelectionChanged intermediaire.
        if (-not $PreserveSelection) {
        $searchGrid = Get-DomeniaControl -Name "DgObjects"
        $script:SuppressGridSelectionEvents = $true
        try {
            if ($null -ne $searchGrid) {
                try { $searchGrid.UnselectAll() } catch { Write-DomeniaSwallowed 'Core' 'Invoke-GlobalSearch' $_ }
                try { $searchGrid.SelectedItem = $null } catch { Write-DomeniaSwallowed 'Core' 'Invoke-GlobalSearch' $_ }
                try { $searchGrid.SelectedIndex = -1 } catch { Write-DomeniaSwallowed 'Core' 'Invoke-GlobalSearch' $_ }
            }
        }
        finally { $script:SuppressGridSelectionEvents = $false }
        Stop-DomeniaSelectionOpenTimer
        $script:PendingObjectSelection = $null
        $script:SelectionResetDn = ""
        if ($null -ne $script:SelectedObject -or -not [string]::IsNullOrWhiteSpace([string]$script:CurrentObjectRequestId)) {
            Clear-DomeniaCurrentObjectRequest -RequestId ([string]$script:CurrentObjectRequestId)
            Reset-DomeniaSelectionBoundViews
        }

        }

        $typeFilter = Get-GlobalSelectedTypeFilter -Mode $SearchMode
        # FO-05: key of the type selector of the bar (same normalisation as Get-GlobalSelectedTypeFilter).
        $barTypeKey = [string]$script:SearchBarType
        if ($barTypeKey -notin @('Tous','Utilisateurs','Machines','Groupes')) { $barTypeKey = 'Tous' }
        # UX-25: the object type shown when this list is produced comes back with it from the history.
        $typeLabel = 'Tous'
        try { $typeItem = (Get-DomeniaControl -Name 'CmbGlobalType').SelectedItem; if ($null -ne $typeItem -and [string]$typeItem.Content) { $typeLabel = [string]$typeItem.Content } } catch { Write-DomeniaSwallowed 'Core' 'Invoke-GlobalSearch' $_ }
        $prefixFilter = ""
        $fastFilter = ""
        $exactFilter = ""
        $anrFilter = ""
        $broadFilter = ""

        if ($isBrowse) {
            $broadFilter = $typeFilter
        }
        elseif ($textValue.Contains("*")) {
            # Les jokers ne sont utilises que lorsqu'ils sont saisis explicitement.
            # Cela evite le "*terme*" implicite qui peut balayer tout un gros domaine.
            $wildcard = Escape-LdapValue -Value $textValue -KeepWildcard
            $broadFilter = "(&$typeFilter(|(name=$wildcard)(displayName=$wildcard)(sAMAccountName=$wildcard)(userPrincipalName=$wildcard)(mail=$wildcard)(dNSHostName=$wildcard)(description=$wildcard)))"
        }
        else {
            $rawExact = $textValue
            $shortExact = $rawExact
            if ($shortExact.Contains([string][char]92)) { $shortExact = $shortExact.Split([char]92)[-1] }
            if ($shortExact.Contains("@")) { $shortExact = $shortExact.Split("@")[0] }
            $shortExact = $shortExact.Trim().TrimEnd([char]36)

            $escapedRaw = Escape-LdapValue -Value $rawExact
            $escapedShort = Escape-LdapValue -Value $shortExact
            $computerSam = $escapedShort + '$'

            # Premiere passe volontairement courte : attributs d identite exacts.
            # Elle couvre notamment les comptes machine via sAMAccountName=POSTE$,
            # sans gonfler le filtre avec des doublons et des attributs de presentation.
            $exactClauses = New-Object System.Collections.ArrayList
            $exactSeen = @{}
            foreach ($clause in @(
                "(sAMAccountName=$escapedRaw)",
                "(userPrincipalName=$escapedRaw)",
                "(mail=$escapedRaw)",
                "(dNSHostName=$escapedRaw)",
                "(name=$escapedRaw)"
            )) {
                if (-not $exactSeen.ContainsKey($clause)) {
                    $exactSeen[$clause] = $true
                    [void]$exactClauses.Add($clause)
                }
            }

            if (-not [string]::IsNullOrWhiteSpace($escapedShort)) {
                foreach ($clause in @(
                    "(sAMAccountName=$escapedShort)",
                    "(sAMAccountName=$computerSam)",
                    "(name=$escapedShort)",
                    "(dNSHostName=$escapedShort)"
                )) {
                    if (-not $exactSeen.ContainsKey($clause)) {
                        $exactSeen[$clause] = $true
                        [void]$exactClauses.Add($clause)
                    }
                }
            }

            $domain = [string]$script:Conn.Domain
            if (-not [string]::IsNullOrWhiteSpace($escapedShort) -and -not [string]::IsNullOrWhiteSpace($domain)) {
                $escapedDomain = Escape-LdapValue -Value $domain
                [void]$exactClauses.Add("(dNSHostName=$escapedShort.$escapedDomain)")
                [void]$exactClauses.Add("(userPrincipalName=$escapedShort@$escapedDomain)")
            }

            # Recherche bare = recherche de prefixe coherente. Le prefixe est
            # interroge AVANT ANR pour garantir qu'un terme plus large ne puisse
            # pas renvoyer moins de resultats qu'un terme plus precis. On reste
            # volontairement sur les attributs d'identite les plus utiles.
            if ($rawExact.Contains("@")) {
                $prefixFilter = "(&$typeFilter(|(userPrincipalName=$escapedRaw*)(mail=$escapedRaw*)))"
            }
            elseif (-not [string]::IsNullOrWhiteSpace($escapedShort)) {
                $prefixFilter = "(&$typeFilter(|(name=$escapedShort*)(sAMAccountName=$escapedShort*)(dNSHostName=$escapedShort*)))"
                if ($SearchMode -eq 'Global') {
                    # Include identity and human-name attributes in the first pass, not only as a fallback.
                    $prefixFilter = "(&$typeFilter(|(name=$escapedRaw*)(displayName=$escapedRaw*)(givenName=$escapedRaw*)(sn=$escapedRaw*)(sAMAccountName=$escapedShort*)(dNSHostName=$escapedShort*)(mail=$escapedRaw*)(userPrincipalName=$escapedRaw*)(anr=$escapedRaw)))"
                }
            }

            # Passe d'identite exacte conservee comme secours rapide si le
            # prefixe ne trouve rien (cas de syntaxes atypiques).
            if ($rawExact.Contains("@")) {
                $fastFilter = "(&$typeFilter(|(userPrincipalName=$escapedRaw)(mail=$escapedRaw)))"
            }
            elseif (-not [string]::IsNullOrWhiteSpace($escapedShort)) {
                $fastFilter = "(&$typeFilter(|(sAMAccountName=$escapedShort)(sAMAccountName=$computerSam)))"
            }

            $exactFilter = "(&$typeFilter(|$(@($exactClauses) -join '')))"
            $anrFilter = "(&$typeFilter(anr=$escapedRaw))"

            # Fallback borne : prefixe uniquement. Pour une sous-chaine arbitraire,
            # l'utilisateur peut saisir explicitement *terme*.
            $prefix = $escapedRaw + "*"
            $broadFilter = "(&$typeFilter(|(name=$prefix)(displayName=$prefix)(sAMAccountName=$prefix)(dNSHostName=$prefix)))"
        }

        if ($null -ne $view) {
            # The view filter carries its own object type; the global type filter keeps the allowed classes.
            $prefixFilter = ''; $fastFilter = ''; $exactFilter = ''; $anrFilter = ''
            $broadFilter = '(&' + (Get-TypeLdapFilter -Type 'Tous') + [string]$view.Filter + ')'
        }
        elseif ($null -ne $searchPlan) {
            if ([string]$searchPlan.Kind -in @('Identifier','Syntax')) {
                # Only what the operator typed refines the search: no hidden widening pass is added.
                $prefixFilter = [string]$searchPlan.Filter; $fastFilter = ''; $exactFilter = ''; $anrFilter = ''; $broadFilter = ''
            }
            elseif (-not [string]::IsNullOrWhiteSpace([string]$searchPlan.MultiWordFilter)) {
                $broadFilter = [string]$searchPlan.MultiWordFilter
            }
        }
        if ($null -ne $containsPlan) {
            # FO-01: one filter only, the names that contain every word; no prefix, exact or ANR pass first.
            $prefixFilter = ''; $fastFilter = ''; $exactFilter = ''; $anrFilter = ''
            $broadFilter = [string]$containsPlan.Filter
        }

        $serverKey = ([string]$script:Conn.Server).ToLowerInvariant()
        $baseKey = ([string]$scope.BaseDn).ToLowerInvariant()
        $cacheKey = "scope-v214|$SearchMode|$serverKey|$baseKey|$($scope.Scope)|$typeFilter|$textValue|$limit"
        if ($null -ne $view) { $cacheKey += '|view:' + [string]$view.Id }
        if ($null -ne $containsPlan) { $cacheKey += '|contains' }
        # Cache previews are read in a worker; the WPF thread performs no SQLite query here.

        # D021: the list projection is the single source of truth; heavy attributes are refused before the worker.
        $props = @(Get-DomeniaProjection -Kind List)
        $projectionCheck = Test-DomeniaProjectionMinimal $props
        if (-not [bool]$projectionCheck.Minimal) { throw 'Projection de liste trop lourde.' }

        $code = @'
$watch = [System.Diagnostics.Stopwatch]::StartNew()
if($null -ne $Payload.DirectoryReadState){$Payload.DirectoryReadState.Started=$true}
try {
if ($null -ne $Payload.StopToken -and $Payload.StopToken.IsCancellationRequested) { throw "Lecture remplacee ou arretee." }
if ([string]::IsNullOrWhiteSpace([string]$Payload.BaseDn)) { throw "Recherche impossible : Base DN vide." }
if ([string]$Payload.Scope -notin @("Subtree","OneLevel")) { throw "Portee de recherche invalide." }

$filters = New-Object Collections.ArrayList
$seenFilter = @{}
# MO-07: 'Charger la suite' reads only the next rows of the filter that produced the list, sorted by name from the
# last name read; the DNs already listed are skipped and never published twice.
$continuation = $null
$known = $null
if (($null -ne $Payload.PSObject.Properties['Continuation']) -and ($null -ne $Payload.Continuation)) { $continuation = $Payload.Continuation }
if ($null -ne $continuation) {
    $f = ([string]$continuation.Filter).Trim()
    if ((-not $f.StartsWith('(')) -or (-not $f.EndsWith(')')) -or ($f.Length -gt 16500)) { throw 'Filtre de suite invalide : aucune lecture.' }
    [void]$filters.Add($f)
    $known = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach ($knownKey in @($continuation.KnownKeys)) { if (-not [string]::IsNullOrWhiteSpace([string]$knownKey)) { [void]$known.Add(([string]$knownKey).Trim()) } }
}
else {
    foreach ($candidate in @([string]$Payload.PrefixFilter,[string]$Payload.FastFilter,[string]$Payload.ExactFilter,[string]$Payload.AnrFilter,[string]$Payload.BroadFilter)) {
        $f = ([string]$candidate).Trim()
        if ([string]::IsNullOrWhiteSpace($f)) { continue }
        if (-not $seenFilter.ContainsKey($f)) {
            $seenFilter[$f] = $true
            [void]$filters.Add($f)
        }
    }
}
if ($filters.Count -eq 0) { throw "Aucun filtre LDAP valide n'a ete construit." }

$contexts = New-Object Collections.ArrayList
[void]$contexts.Add($Context)
if (-not [string]::IsNullOrWhiteSpace([string]$Context.Server)) {
    # Serverless retry: a copy of the whole context (account, account generation, operation, guard keys), only the
    # server differs. A partial copy read as generation 0 would be refused after any in-place correction (point 44).
    $serverless = $Context.PSObject.Copy()
    $serverless.Server = ""
    [void]$contexts.Add($serverless)
}

$rows = New-Object Collections.ArrayList
$seenDn = @{}
$diagnostics = New-Object Collections.ArrayList
$rawCount = 0
$successfulQuery = $false
$serverUsed = ""
$limitReached = $false
$partial = $false
$failure = ""
$filterUsed = ""
$lastName = ""

foreach ($ctx in @($contexts)) {
    $serverLabel = if ([string]::IsNullOrWhiteSpace([string]$ctx.Server)) { "auto" } else { [string]$ctx.Server }

    foreach ($filterText in @($filters)) {
        $searcher = $null
        $collection = $null
        $rootEntry = $null
        $queryWatch = [System.Diagnostics.Stopwatch]::StartNew()
        $filterRaw = 0
        $filterAdded = 0
        try {
            # One extra LDAP result proves truncation; exactly Limit rows is not evidence of an incomplete list.
            $resultLimit=[int]$Payload.Limit
            if($resultLimit -lt 1 -or $resultLimit -gt 20000){throw 'Budget de recherche invalide (1 a 20000 objets).'}
            $ldapLimit=$resultLimit+1
            # MO-07: a continuation may meet the rows already listed again (same name, or a first unsorted list).
            if ($null -ne $known) { $ldapLimit += $known.Count }
            $searcher = New-WSearcher $ctx ([string]$Payload.BaseDn) $filterText @($Payload.Properties) ([string]$Payload.Scope) $ldapLimit
            $searcher.ServerTimeLimit = [TimeSpan]::FromSeconds([Math]::Max(3,[int]$Payload.ServerTimeLimitSeconds))
            $searcher.ClientTimeout = [TimeSpan]::FromSeconds([Math]::Max(5,[int]$Payload.ClientTimeoutSeconds))
            $searcher.PageSize = [Math]::Max(100,[Math]::Min(1000,[int]$Payload.StreamPageSize))
            $searcher.CacheResults = $false
            $searcher.Asynchronous = $true
            if (($null -ne $continuation) -and ([string]$continuation.SortAttribute -eq 'name')) { $searcher.Sort = New-Object System.DirectoryServices.SortOption('name',[System.DirectoryServices.SortDirection]::Ascending) }
            $rootEntry = $searcher.SearchRoot
            $collection = $searcher.FindAll()
            $serverUsed = $serverLabel
            $filterUsed = [string]$filterText

            foreach ($result in $collection) {
                if ($null -ne $Payload.StopToken -and $Payload.StopToken.IsCancellationRequested) { throw "Lecture remplacée ou arrêtée." }
                # Only a result received from LDAP extends the inactivity budget. Cached rows,
                # UI rendering and a retry without results never refresh this monotonic clock.
                if ($null -ne $Payload.SearchReadProgress) {
                    [Threading.Monitor]::Enter($Payload.SearchReadProgress.SyncRoot)
                    try {
                        $Payload.SearchReadProgress.RowsRead = [long]$Payload.SearchReadProgress.RowsRead + 1L
                        $Payload.SearchReadProgress.LastRowTimestamp = [Diagnostics.Stopwatch]::GetTimestamp()
                    } finally { [Threading.Monitor]::Exit($Payload.SearchReadProgress.SyncRoot) }
                }
                $rawCount++
                $filterRaw++
                $row = New-WBranchRow $result
                $g=Get-WPropFirst $result.Properties 'objectguid' $null
                $guidText=if($g -is [array] -and $g.Count -eq 16){([guid]([byte[]]$g)).ToString('D')}else{Convert-WGuid $g}
                Add-Member -InputObject $row -NotePropertyName Guid -NotePropertyValue $guidText
                # D034: protection marker, display only (the list marks administration accounts; no right is inferred).
                Add-Member -InputObject $row -NotePropertyName AdminCount -NotePropertyValue ([string](Get-WPropFirst $result.Properties 'admincount' '')) -Force
                if ([string]$row.Type -notin @("Utilisateur","Machine","Groupe","OU","Conteneur")) { continue }

                $dn = ([string]$row.DN).Trim()
                $key = if ([string]::IsNullOrWhiteSpace($dn)) {
                    ("{0}|{1}|{2}" -f [string]$row.Type,[string]$row.Name,[string]$row.Login).ToLowerInvariant()
                }
                else { $dn.ToLowerInvariant() }

                if (($null -ne $known) -and $known.Contains($key)) { continue }
                if ($seenDn.ContainsKey($key)) { continue }
                $seenDn[$key] = $true
                $beyondDisplayLimit=($rows.Count -ge $resultLimit)
                if(-not $beyondDisplayLimit){[void]$rows.Add($row);$filterAdded++;$lastName=[string]$row.Name}
                # Even the look-ahead observation is stored. The publication pipe enforces the requested display budget.
                if ($null -ne $Payload.Progress) {
                    $observedUtc=[datetime]::UtcNow.ToString('o')
                    $properties=New-WDirectoryStoreProperties -Properties $result.Properties -Names @($Payload.Properties)
                    # Bound the unpublished buffer. Only actual LDAP arrivals update the read clock.
                    while($Payload.Progress.Count -ge 1000){
                        if($null -ne $Payload.StopToken -and $Payload.StopToken.IsCancellationRequested){throw 'Lecture remplacee ou arretee.'}
                        [Threading.Thread]::Sleep(10)
                    }
                    $Payload.Progress.Enqueue([pscustomobject]@{Kind='DirectoryRead';Properties=$properties;Type=[string]$row.Type;ObservedUtc=$observedUtc;Source=$serverLabel})
                }

                if ($beyondDisplayLimit) {
                    $limitReached = $true
                    break
                }
            }
            if(-not $limitReached -and $filterRaw -ge $ldapLimit){
                # Duplicate/unsupported rows can exhaust the LDAP budget without proving the visible set complete.
                $partial=$true;$failure='Budget LDAP atteint avant de confirmer la liste complete. Affinez le perimetre.'
            }

            $successfulQuery = $true
            [void]$diagnostics.Add("$serverLabel : $filterText => bruts=$filterRaw, ajoutes=$filterAdded, $($queryWatch.ElapsedMilliseconds) ms")

            # Des qu'un filtre prioritaire a trouve quelque chose, il est inutile
            # de lancer les recherches plus larges.
            if ($rows.Count -gt 0 -or $limitReached) { break }
        }
        catch {
            if(Register-WCredentialFailure -Context $ctx -ErrorValue $_ -Channel Directory){throw}
            $accessError=Get-DomeniaStructuredError $_ -Phase 'DirectorySearch' -Provider 'LDAP'
            if($accessError.Kind -in @('LogonFailure','AccountLocked','AccountUnavailable')){throw}
            [void]$diagnostics.Add("$serverLabel : $filterText => ERREUR : $($_.Exception.Message)")
            if ($null -ne $Payload.StopToken -and $Payload.StopToken.IsCancellationRequested) { throw }
            if ($rows.Count -gt 0) { $partial=$true; $failure=$_.Exception.Message; break }
        }
        finally {
            $queryWatch.Stop()
            try { if ($null -ne $collection) { $collection.Dispose() } } catch { }
            try { if ($null -ne $searcher) { $searcher.Dispose() } } catch { }
            try { if ($null -ne $rootEntry) { $rootEntry.Dispose() } } catch { }
        }
    }

    if ($rows.Count -gt 0 -or $successfulQuery) { break }
}

if (-not $successfulQuery -and -not $partial) {
    throw "La recherche LDAP a echoue sur tous les contextes essayes. $(@($diagnostics) -join ' | ')"
}

$watch.Stop()
$final=[pscustomobject]@{
    Rows=@($rows)
    Partial=[bool]$partial
    Failure=[string]$failure
    RawCount=[int]$rawCount
    DurationMs=[long]$watch.ElapsedMilliseconds
    Server=[string]$serverUsed
    BaseDn=[string]$Payload.BaseDn
    Scope=[string]$Payload.Scope
    LimitReached=[bool]$limitReached
    Filters=@($diagnostics)
    FilterUsed=[string]$filterUsed
    Continuation=($null -ne $continuation)
    LastName=[string]$lastName
}
if($null -ne $Payload.DirectoryReadState){$Payload.DirectoryReadState.Final=$final;if($partial){$Payload.DirectoryReadState.Error=$failure}}
$final
}catch{if($null -ne $Payload.DirectoryReadState){$Payload.DirectoryReadState.Error=$_.Exception.Message};throw}finally{if($null -ne $Payload.DirectoryReadState){$Payload.DirectoryReadState.Done=$true}}
'@


        # Large OUs may take several minutes while still returning rows. The former 45 s
        # total setting now has a 120 s inactivity floor; a separate total cap remains finite.
        $searchIdleSeconds = [Math]::Max(120,[Math]::Min(600,[int](Get-CfgValue 'Async' 'SearchTimeoutSeconds' 120)))
        $searchMaxSeconds = [Math]::Max($searchIdleSeconds,[Math]::Min(3600,[int](Get-CfgValue 'Async' 'SearchMaxDurationSeconds' 900)))
        $searchServerSeconds = [Math]::Max(60,[Math]::Min(300,[int](Get-CfgValue 'Browser' 'SearchServerTimeLimitSeconds' 60)))
        $searchClientSeconds = [Math]::Max(($searchServerSeconds + 30),[Math]::Min(600,[int](Get-CfgValue 'Browser' 'SearchClientTimeoutSeconds' 90)))
        $payload = [pscustomobject]@{
            BaseDn = [string]$scope.BaseDn
            Scope = [string]$scope.Scope
            PrefixFilter = $prefixFilter
            FastFilter = $fastFilter
            ExactFilter = $exactFilter
            AnrFilter = $anrFilter
            BroadFilter = $broadFilter
            Limit = $limit
            Properties = $props
            ServerTimeLimitSeconds = $searchServerSeconds
            ClientTimeoutSeconds = $searchClientSeconds
            StreamPageSize = [Math]::Max(100,[Math]::Min(1000,[int](Get-CfgValue 'Browser' 'SearchPageSize' 250)))
            SearchReadProgress = [hashtable]::Synchronized(@{StartedTimestamp=0L;LastRowTimestamp=0L;RowsRead=0L})
        }
        if ($continuing) {
            # MO-07: one filter (the one that produced the list), sorted by name, a budget of new rows only.
            $payload.PrefixFilter = ''; $payload.FastFilter = ''; $payload.ExactFilter = ''; $payload.AnrFilter = ''; $payload.BroadFilter = ''
            $payload.Limit = [Math]::Max(1,[Math]::Min(20000,[int]$Continuation.Page))
            Add-Member -InputObject $payload -NotePropertyName Continuation -NotePropertyValue ([pscustomobject]@{
                Filter=[string]$Continuation.Filter;SortAttribute=[string]$Continuation.SortAttribute;AfterName=[string]$Continuation.AfterName;KnownKeys=@($Continuation.KnownKeys)
            })
        }
        $callbackState = [pscustomobject]@{
            SearchMode = $SearchMode
            BaseDn = [string]$scope.BaseDn
            Scope = [string]$scope.Scope
            TypeFilter = $typeFilter
            Limit = $limit
            PreserveSelectionDn = $preserveDn
            CacheKey = $cacheKey
            Search = $textValue
            RequestedAt = Get-Date
            NoPopup = [bool]$SilentError
            Generation = $generation
            ViewId = [string]$script:ActiveSearchViewId
            SurveyAllowed = (-not [bool]$script:ListSurveyBlocked)
            ViewChoice = [string]$viewChoice
            TypeLabel = $typeLabel
            # FO-05: the chip and the type of the bar that produced a global list (history, continuation).
            BarScope = $(if (($SearchMode -eq 'Global') -and ($null -ne $scope.PSObject.Properties['Explicit']) -and [bool]$scope.Explicit) { 'Ou' } else { 'Everywhere' })
            BarType = $(if ($SearchMode -eq 'Global') { $barTypeKey } else { '' })
            # FO-01: a « contains » list and the kind of plain-text plan that may offer it.
            MatchMode = $(if ($null -ne $containsPlan) { 'Contains' } else { '' })
            PlanKind = $(if ($null -ne $searchPlan) { [string]$searchPlan.Kind } else { '' })
            StoreContext = (New-DomeniaStoreContext -RequestId ([guid]::NewGuid().ToString('D')) -Generation $generation -ScopeDn ([string]$scope.BaseDn) -Subtree ([string]$scope.Scope -eq 'Subtree'))
        }

        # D031 / FO-05: the request actually sent by the upper bar is checked against the strict global contract. Only the
        # chip of the bar may name an OU (explicit scope) and only its type selector may restrict the type.
        if ($SearchMode -eq 'Global') {
            $explicitDn = ''
            if (($null -ne $scope.PSObject.Properties['Explicit']) -and [bool]$scope.Explicit) { $explicitDn = [string]$scope.BaseDn }
            $contract = [pscustomobject]@{Mode='Global';BaseDn=[string]$payload.BaseDn;Scope=[string]$payload.Scope;PresenceFilter='';LocalFilter='';OuDn='';ExplicitScopeDn=$explicitDn}
            if ((-not (Test-DomeniaGlobalSearchRequest $contract ([string]$script:Conn.BaseDn))) -or ($typeFilter -cne (Get-TypeLdapFilter -Type $barTypeKey))) {
                throw 'Contrat de recherche globale non respecte : perimetre herite refuse.'
            }
        }

        if ($continuing) {
            # MO-07: the list on screen receives the next rows; its rows, its selection and its filter stay.
            Add-Member -InputObject $callbackState -NotePropertyName ContinuationPage -NotePropertyValue ([int]$payload.Limit) -Force
            [void](Resume-DomeniaLiveSearch -State $callbackState -Payload $payload)
        }
        else { [void](Begin-DomeniaLiveSearch -State $callbackState -Payload $payload) }

        Add-DomeniaUiLog -Area "Recherche" -Level "INFO" -Text ("Recherche $SearchMode '$textValue' demandee, base=$($scope.BaseDn), portee=$($scope.Scope), limite=$limit" + $(if ($continuing) { ", suite de $($payload.Limit) ligne(s) apres '$([string]$Continuation.AfterName)'." } else { '.' }))
        Write-DomeniaTrace -Area 'Recherche' -Text "Budgets : sans progression=$($searchIdleSeconds)s, maximum=$($searchMaxSeconds)s, LDAP serveur=$($searchServerSeconds)s/client=$($searchClientSeconds)s, page=$($payload.StreamPageSize)."
        if ($generation -ne [int]$script:GlobalSearchGeneration) { return }
        if (-not $PreserveSelection) { Select-DomeniaWorkspace -Workspace 'WsSearch' }
        [void](Set-DomeniaControlText -Name 'LblBranchCount' -Text $(if ($continuing) { 'Chargement de la suite…' } else { 'Recherche en cours...' }))
        Start-UiTask -Name "Recherche dans l annuaire" -OperationId "GlobalSearch" -Code $code -Payload $payload -CallbackState $callbackState -ReplaceKey "global" -DisableControls @("BtnGlobalSearch") -TimeoutSeconds $searchIdleSeconds -HardTimeoutSeconds $searchMaxSeconds -StatusText "Recherche Active Directory en arriere-plan..." -SuccessHandler "Complete-DomeniaGlobalSearchUi" -ErrorHandler "Fail-DomeniaGlobalSearchUi" | Out-Null
    }
    catch {
        if ($null -ne $callbackState -and $null -ne $callbackState.PSObject.Properties['LiveState']) { Fail-DomeniaLiveSearch -Message $_.Exception.Message -State $callbackState }
        [void](Show-DomeniaOperationError -Operation "Preparation de la recherche Active Directory" -ErrorRecordOrException $_ -NoPopup:$SilentError)
    }
    finally {
        if ($null -ne $navHook) { Exit-DomeniaNavSearch }
    }
}

function Get-DomeniaSelectedGridRow {
    $grid = Get-DomeniaControl -Name "DgObjects"
    if ($null -eq $grid) { return $null }
    try { return $grid.SelectedItem } catch { return $null }
}

function Stop-DomeniaSelectionOpenTimer {
    try { if ($null -ne $script:SelectionOpenTimer) { $script:SelectionOpenTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Stop-DomeniaSelectionOpenTimer' $_ }
}

function Test-DomeniaGridSelectionMatches {
    param([AllowNull()][string]$Dn)
    if ([string]::IsNullOrWhiteSpace([string]$Dn)) { return $false }
    $selectedRows = @(Get-DomeniaSelectedGridRows)
    if ($selectedRows.Count -ne 1) { return $false }

    $row = Get-DomeniaSelectedGridRow
    if ($null -eq $row) { return $false }
    try { return ([string]$row.DN -ieq [string]$Dn) } catch { return $false }
}

function Clear-DomeniaCurrentObjectRequest {
    param([AllowNull()][string]$RequestId)
    if ([string]::IsNullOrWhiteSpace([string]$RequestId) -or [string]$script:CurrentObjectRequestId -ceq [string]$RequestId) {
        $script:CurrentObjectRequestId = ''
        $script:CurrentObjectRequestDn = ''
        $script:CurrentObjectRequestState = $null
    }
}

function Test-DomeniaObjectCallbackIsCurrent {
    param($State)
    if ($null -eq $State -or -not $State.RequestId -or $State.RequestId -cne $script:CurrentObjectRequestId) { return $false }
    if ($State.PSObject.Properties['Epoch'] -and $State.Epoch -ne [long]$script:SessionEpoch) { return $false }
    if ($State.PSObject.Properties['Identity'] -and $State.Identity -cne (Get-DomeniaObjectReadIdentity)) { return $false }
    if ($State.SelectionBound) {
        if (-not (Test-DomeniaGridSelectionMatches -Dn ([string]$State.Dn))) { return $false }
        if ($State.PSObject.Properties['SelectionToken']) {
            if ($null -eq $script:SelectionLoad -or $State.SelectionToken -cne $script:SelectionLoad.Token) { return $false }
            if (-not (Test-DomeniaSelectionLoadCurrent)) { return $false }
        }
    }
    return $true
}

function Invoke-DomeniaPendingSelectionOpen {
    $pending = $script:PendingObjectSelection
    if ($null -eq $pending -or $script:AsyncEngineClosing) { return }
    if ($null -eq $script:SelectionLoad -or $pending.Token -cne $script:SelectionLoad.Token) {
        $script:PendingObjectSelection = $null
        return
    }
    if (Test-DomeniaAccessBusyWrite) {
        Update-DomeniaSelectionReadUi -Phase Paused
        if ($null -ne $script:SelectionOpenTimer) { $script:SelectionOpenTimer.Interval=[TimeSpan]::FromMilliseconds(300);$script:SelectionOpenTimer.Start() }
        return
    }
    if (-not (Test-DomeniaSelectionLoadCurrent)) {
        $script:PendingObjectSelection = $null
        return
    }
    $script:PendingObjectSelection = $null
    Open-AdObject -Dn ([string]$pending.Dn) -Type ([string]$pending.Type) -Force:([bool]$pending.Force) -SelectionBound -NoNavigate -SuppressRemoteProbes
}

function Queue-DomeniaSelectedObjectOpen {
    [CmdletBinding()]
    param([switch]$Immediate,[switch]$Force,[switch]$ReadOnlyRetry)
    if ($script:SuppressGridSelectionEvents -or $script:AsyncEngineClosing -or (Test-DomeniaAccessBusyWrite)) { return }
    $context = Get-DomeniaSelectionContext
    $dn = if ($null -ne $context) { $context.DN } else { '' }
    # No remote request, context update or clearing before the draft decision.
    if (-not (Test-DomeniaDraftNavigation -DN $dn -Refresh:$Force)) {
        Restore-DomeniaRefusedSelection -DN ([string]$script:DraftState.DN)
        return
    }
    if ($null -eq $context) {
        Clear-DomeniaSelectionEverywhere
        return
    }
    $same = ($null -ne $script:SelectionLoad -and (Test-DomeniaSameSelectionContext $script:SelectionLoad.Context $context))
    if (-not $same) { Enter-DomeniaSelectionContext $context }
    Set-DomeniaRelationsGridSelection
    if (-not $ReadOnlyRetry) { Select-DomeniaLiveResult }
    Update-DomeniaSelectionReadUi
    if ($Immediate -and -not $ReadOnlyRetry) {
        $landing = Get-DomeniaLandingView -Type ([string]$context.Type)
        Select-DomeniaWorkspace -Workspace $landing.Workspace -Inner $landing.Inner -Tab $landing.Tab
    }
    # Opening never means refreshing: share the outstanding read and keep its callback non-navigating.
    if ($script:CurrentObjectRequestDn -ieq $context.DN -and $script:CurrentObjectRequestId) { return }
    if ($same -and -not $Force -and $script:SelectionLoad.Phase -in @('Ready','Failed')) { return }
    $script:PendingObjectSelection = [pscustomobject]@{
        Dn=$context.DN;Type=$context.Type;Name=$context.Name;ExpectedGuid=$context.Guid
        Force=[bool]$Force;Token=$script:SelectionLoad.Token;Context=$context;QueuedAt=[datetime]::UtcNow
    }
    if ($Immediate) {
        Stop-DomeniaSelectionOpenTimer
        Invoke-DomeniaPendingSelectionOpen
        return
    }
    if ($null -eq $script:SelectionOpenTimer) {
        # FI-05: protected timer of the engine heartbeat (selection debounce).
        $script:SelectionOpenTimer = New-DomeniaTimer -Owner 'Timer:SelectionOpen' -IntervalMs 180 -Tick {
            try { Stop-DomeniaSelectionOpenTimer; Invoke-DomeniaPendingSelectionOpen }
            catch {
                $script:LastObjectOpenError = [string]$_.Exception.Message
                Update-DomeniaSelectionReadUi -Phase Failed -Message $script:LastObjectOpenError
                Write-AppLog ('Prechargement de la selection : '+$script:LastObjectOpenError) 'ERROR'
            }
        }
    }
    $delay = [Math]::Max(80,[Math]::Min(500,[int](Get-CfgValue 'Browser' 'SelectionDebounceMs' 180)))
    Stop-DomeniaSelectionOpenTimer
    $script:SelectionOpenTimer.Interval = [TimeSpan]::FromMilliseconds($delay)
    $script:SelectionOpenTimer.Start()
}

function Open-SelectedObject {
    param([switch]$Force)
    Queue-DomeniaSelectedObjectOpen -Immediate -Force:$Force
}

function Start-PermissionAnalysis {
    param([switch]$UserInitiated)
    try {
        if ($null -eq $script:SelectedObject -or [string]::IsNullOrWhiteSpace([string]$script:SelectedObject.DN)) { return }
        $dn = [string]$script:SelectedObject.DN
        $generation = [int64]$script:SelectedObjectGeneration
        $code = @'
function New-CapRow { param($Capability,$State,$Source,$Detail) [pscustomobject]@{ Capability=$Capability; State=$State; Source=$Source; Detail=$Detail } }
function Get-CapState {
    param([long]$Allow,[long]$Deny,[long]$Mask,[bool]$GenericAllow,[bool]$GenericDeny)
    if ($GenericDeny -or (($Deny -band $Mask) -ne 0)) { return "Refuse" }
    if ($GenericAllow -or (($Allow -band $Mask) -ne 0)) { return "Autorise" }
    return "Indetermine"
}
$login = [string]$Context.BindUser
if ($login.Contains([string][char]92)) { $login = $login.Split([char]92)[-1] }
if ($login.Contains("@")) { $login = $login.Split("@")[0] }
$tokenSids = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
[void]$tokenSids.Add("S-1-1-0")
[void]$tokenSids.Add("S-1-5-11")
try {
    $esc = Escape-WLdap $login
    $us = New-WSearcher $Context ([string]$Context.BaseDn) "(&(objectCategory=person)(objectClass=user)(sAMAccountName=$esc))" @("objectSid","tokenGroups","distinguishedName") "Subtree" 1
    $ur = $us.FindOne()
    if ($null -ne $ur) {
        foreach ($v in @(Get-WPropAll $ur.Properties "objectsid")) { $sid = Convert-WSid $v; if ($sid) { [void]$tokenSids.Add($sid) } }
        foreach ($v in @(Get-WPropAll $ur.Properties "tokengroups")) { $sid = Convert-WSid $v; if ($sid) { [void]$tokenSids.Add($sid) } }
    }
} catch { }
$security = $null
$securityError = ""
try {
    $security = Get-WActiveDirectorySecurity -Context $Context -Dn ([string]$Payload.DN) -IncludeOwner $true
}
catch {
    $securityError = [string]$_.Exception.Message
}
if ($null -eq $security) {
    if ([string]::IsNullOrWhiteSpace($securityError)) { $securityError = "Le descripteur de securite n a pas ete retourne par le controleur de domaine." }
    $cap = [ordered]@{
        Edit="Indetermine"; Account="Indetermine"; Password="Indetermine"; Group="Indetermine";
        Move="Indetermine"; Delete="Indetermine"; Create="Indetermine"; Secrets="Indetermine";
        Read="Indetermine"; Acl="Indetermine"
    }
    $rows = @(
        (New-CapRow "Lecture objet" "Indetermine" "ACL indisponible" $securityError),
        (New-CapRow "Modifier attributs" "Indetermine" "ACL indisponible" $securityError),
        (New-CapRow "Gestion compte" "Indetermine" "ACL indisponible" $securityError),
        (New-CapRow "Reset mot de passe" "Indetermine" "ACL indisponible" $securityError),
        (New-CapRow "Gestion groupes" "Indetermine" "ACL indisponible" $securityError),
        (New-CapRow "Déplacer ou renommer" "Indetermine" "ACL indisponible" $securityError),
        (New-CapRow "Supprimer objet" "Indetermine" "ACL indisponible" $securityError),
        (New-CapRow "Creer enfant" "Indetermine" "ACL indisponible" $securityError),
        (New-CapRow "Lire secrets" "Indetermine" "ACL indisponible" $securityError),
        (New-CapRow "Modifier ACL" "Indetermine" "ACL indisponible" $securityError)
    )
    return [pscustomobject]@{
        Available=$false; Reason=$securityError; Rows=$rows; Capabilities=$cap;
        MatchingAces=0; TokenSidCount=$tokenSids.Count; Owner="Non lu"
    }
}
$rules = @($security.GetAccessRules([bool]$true,[bool]$true,[type][System.Security.Principal.SecurityIdentifier]))
$allow = 0L; $deny = 0L; $genericAllow = $false; $genericDeny = $false
$resetAllow = $false; $resetDeny = $false
$resetGuid = [guid]"00299570-246d-11d0-a768-00aa006e0529"
$matching = 0
foreach ($rule in $rules) {
    $sid = [string]$rule.IdentityReference.Value
    if (-not $tokenSids.Contains($sid)) { continue }
    $matching++
    $rights = [long]$rule.ActiveDirectoryRights
    $isDeny = ($rule.AccessControlType -eq [System.Security.AccessControl.AccessControlType]::Deny)
    if ($isDeny) { $deny = $deny -bor $rights } else { $allow = $allow -bor $rights }
    if (($rights -band [long][System.DirectoryServices.ActiveDirectoryRights]::GenericAll) -ne 0) { if ($isDeny) { $genericDeny=$true } else { $genericAllow=$true } }
    if (($rights -band [long][System.DirectoryServices.ActiveDirectoryRights]::ExtendedRight) -ne 0) {
        if ($rule.ObjectType -eq [guid]::Empty -or $rule.ObjectType -eq $resetGuid) { if ($isDeny) { $resetDeny=$true } else { $resetAllow=$true } }
    }
}
$readMask = [long]([System.DirectoryServices.ActiveDirectoryRights]::GenericRead -bor [System.DirectoryServices.ActiveDirectoryRights]::ReadProperty -bor [System.DirectoryServices.ActiveDirectoryRights]::ListObject -bor [System.DirectoryServices.ActiveDirectoryRights]::ListChildren)
$editMask = [long]([System.DirectoryServices.ActiveDirectoryRights]::GenericWrite -bor [System.DirectoryServices.ActiveDirectoryRights]::WriteProperty)
$accountMask = [long]([System.DirectoryServices.ActiveDirectoryRights]::GenericWrite -bor [System.DirectoryServices.ActiveDirectoryRights]::WriteProperty -bor [System.DirectoryServices.ActiveDirectoryRights]::ExtendedRight)
$groupMask = [long]([System.DirectoryServices.ActiveDirectoryRights]::GenericWrite -bor [System.DirectoryServices.ActiveDirectoryRights]::WriteProperty)
$moveMask = [long]([System.DirectoryServices.ActiveDirectoryRights]::Delete -bor [System.DirectoryServices.ActiveDirectoryRights]::DeleteTree -bor [System.DirectoryServices.ActiveDirectoryRights]::WriteProperty)
$deleteMask = [long]([System.DirectoryServices.ActiveDirectoryRights]::Delete -bor [System.DirectoryServices.ActiveDirectoryRights]::DeleteTree)
$createMask = [long]([System.DirectoryServices.ActiveDirectoryRights]::CreateChild)
$aclMask = [long]([System.DirectoryServices.ActiveDirectoryRights]::WriteDacl -bor [System.DirectoryServices.ActiveDirectoryRights]::WriteOwner)
$read = Get-CapState $allow $deny $readMask $genericAllow $genericDeny
$edit = Get-CapState $allow $deny $editMask $genericAllow $genericDeny
$account = Get-CapState $allow $deny $accountMask $genericAllow $genericDeny
$group = Get-CapState $allow $deny $groupMask $genericAllow $genericDeny
$move = Get-CapState $allow $deny $moveMask $genericAllow $genericDeny
$delete = Get-CapState $allow $deny $deleteMask $genericAllow $genericDeny
$create = Get-CapState $allow $deny $createMask $genericAllow $genericDeny
$acl = Get-CapState $allow $deny $aclMask $genericAllow $genericDeny
$password = if ($genericDeny -or $resetDeny) { "Refuse" } elseif ($genericAllow -or $resetAllow) { "Autorise" } else { "Indetermine" }
$secrets = if ($genericDeny) { "Refuse" } elseif ($genericAllow) { "Autorise" } else { "Indetermine" }
$rows = @(
    (New-CapRow "Lecture objet" $read "DACL" "Lecture proprietes, liste et acces generique"),
    (New-CapRow "Modifier attributs" $edit "DACL" "WriteProperty ou GenericWrite"),
    (New-CapRow "Gestion compte" $account "DACL" "Activation, verrouillage, expiration et options"),
    (New-CapRow "Reset mot de passe" $password "DACL" "Extended Right Reset Password"),
    (New-CapRow "Gestion groupes" $group "DACL" "Modification de member / memberOf"),
    (New-CapRow "Déplacer ou renommer" $move "DACL" "Necessite aussi des droits sur la cible"),
    (New-CapRow "Supprimer objet" $delete "DACL" "Delete ou DeleteTree"),
    (New-CapRow "Creer enfant" $create "DACL" "CreateChild sur le conteneur"),
    (New-CapRow "Lire secrets" $secrets "DACL" "BitLocker et LAPS utilisent des attributs confidentiels"),
    (New-CapRow "Modifier ACL" $acl "DACL" "WriteDacl ou WriteOwner")
)
$cap = [ordered]@{ Edit=$edit; Account=$account; Password=$password; Group=$group; Move=$move; Delete=$delete; Create=$create; Secrets=$secrets; Read=$read; Acl=$acl }
$owner = try { [string]$security.GetOwner([System.Security.Principal.SecurityIdentifier]).Value } catch { "" }
[pscustomobject]@{ Available=$true; Reason=""; Rows=$rows; Capabilities=$cap; MatchingAces=$matching; TokenSidCount=$tokenSids.Count; Owner=$owner }
'@
        $permissionState = [pscustomobject]@{ DN=$dn; Generation=$generation; UserInitiated=[bool]$UserInitiated }
        Start-UiTask -Name "Analyse des droits" -OperationId "PermissionAnalysis" -Code $code -Payload ([pscustomobject]@{ DN=$dn }) -CallbackState $permissionState -ReplaceKey "permissions" -DisableControls @("BtnPermissionRefresh") -TimeoutSeconds 35 -StatusText "Analyse des ACL en lecture seule..." -OnSuccess {
            param($result,$state)
            if ($null -eq $script:SelectedObject -or [string]$script:SelectedObject.DN -ine [string]$state.DN -or [int64]$script:SelectedObjectGeneration -ne [int64]$state.Generation) {
                Write-AppLog "Resultat d'estimation ACL obsolete ignore pour $([string]$state.DN)." "INFO"
                return
            }
            $script:PermissionRows = @($result.Rows)
            [void](Set-DomeniaItemsSource -Name "DgPermissions" -Rows $script:PermissionRows)
            $script:CurrentCapabilities = @{}
            if ($result.Capabilities -is [System.Collections.IDictionary]) {
                foreach ($k in $result.Capabilities.Keys) { $script:CurrentCapabilities[[string]$k] = [string]$result.Capabilities[$k] }
            }
            elseif ($null -ne $result.Capabilities) {
                foreach ($p in $result.Capabilities.PSObject.Properties) { $script:CurrentCapabilities[$p.Name] = [string]$p.Value }
            }
            $available = $true
            try { if ($null -ne $result.PSObject.Properties["Available"]) { $available = [bool]$result.Available } } catch { Write-DomeniaSwallowed 'Core' 'Start-PermissionAnalysis' $_ }
            if ($available) {
                $summary = "$($result.MatchingAces) ACE correspondante(s), $($result.TokenSidCount) SID de jeton, proprietaire $($result.Owner)."
                $script:Ctrl["LblPermissionSummary"].Text = $summary
                Apply-CurrentPermissionUi
                Set-Status "Estimation ACL terminee. Par defaut, seul un refus reel du DC verrouille une action."
            }
            else {
                $reason = "ACL non disponible"
                try { if (-not [string]::IsNullOrWhiteSpace([string]$result.Reason)) { $reason = [string]$result.Reason } } catch { Write-DomeniaSwallowed 'Core' 'Start-PermissionAnalysis' $_ }
                $script:Ctrl["LblPermissionSummary"].Text = "Analyse ACL indisponible : $reason. Les actions restent soumises au contrôle du DC et au preflight Domenia."
                Apply-CurrentPermissionUi
                Write-AppLog "Analyse ACL non disponible pour $dn : $reason" "WARN"
                Set-Status "Objet chargé. Les droits nʼont pas pu être pré-évalués ; le DC vérifiera chaque action." "WARN"
            }
        } -OnError {
            param($message,$state)
            if ($null -eq $script:SelectedObject -or [string]$script:SelectedObject.DN -ine [string]$state.DN -or [int64]$script:SelectedObjectGeneration -ne [int64]$state.Generation) { return }
            $script:CurrentCapabilities = @{}
            $script:Ctrl["LblPermissionSummary"].Text = "Analyse impossible : $message. Les actions restent disponibles et seront vérifiées par AD à lʼexécution."
            Apply-CurrentPermissionUi
            $noPopup = -not [bool]$state.UserInitiated
            [void](Show-DomeniaOperationError -Operation "Estimation des droits Active Directory" -ErrorRecordOrException ([string]$message) -NoPopup:$noPopup)
        } | Out-Null
    } catch { [void](Show-DomeniaOperationError -Operation "Preparation de l'estimation des droits" -ErrorRecordOrException $_ -NoPopup:(-not $UserInitiated)) }
}

function Copy-PermissionReport {
    try {
        $lines = @("Domenia - estimation des droits (autorite finale : le controleur de domaine)", "Objet : $($script:SelectedObject.DN)")
        foreach ($r in @($script:PermissionRows)) { $lines += "$($r.Capability) | $($r.State) | $($r.Source) | $($r.Detail)" }
        Set-ClipboardSafe ($lines -join [Environment]::NewLine)
        Set-Status "Rapport de droits copie."
    } catch { Show-ErrorBox "Copie du rapport de droits impossible : $($_.Exception.Message)" }
}

function Start-SelfCheck {
    param([switch]$Full)
    try {
        $iterations = if ($Full) { [int](Get-CfgValue "SelfCheck" "FullBenchmarkIterations" 3) } else { 1 }
        $code = @'
$rows = New-Object Collections.ArrayList
function Add-Check {
    param([string]$Category,[string]$Test,[scriptblock]$Action)
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $status = "OK"; $detail = ""
    try { $detail = [string](& $Action) }
    catch { $status = "ERREUR"; $detail = $_.Exception.Message }
    $sw.Stop()
    [void]$rows.Add([pscustomobject]@{ Category=$Category; Test=$Test; Status=$status; DurationMs=[int]$sw.ElapsedMilliseconds; Detail=$detail })
}
Add-Check "Moteur" "PowerShell 5.1+" { "Version $($Context.PowerShellVersion)" }
Add-Check "Moteur" "Thread GUI STA" { if (-not [bool]$Context.IsSta) { throw "Le thread principal ne semble pas STA" }; "STA confirme" }
Add-Check "GUI" "Controles WPF collectes" { if ([int]$Context.ExpectedControls -lt 120) { throw "Seulement $($Context.ExpectedControls) controles detectes" }; "$($Context.ExpectedControls) controles" }
Add-Check "Code" "Fonctions critiques" { if (@($Context.MissingCriticalFunctions).Count -gt 0) { throw "Manquantes : $(@($Context.MissingCriticalFunctions) -join ', ')" }; "$($Context.CriticalFunctionCount) fonctions critiques presentes" }
Add-Check "Securite" "Politique d ecriture" {
    if (-not [bool]$Context.RequireFreshObject) { throw "Preflight de fraicheur desactive" }
    if (-not [bool]$Context.SingleWriteChannel) { throw "Canal d ecriture unique desactive" }
    if (-not [bool]$Context.BlockProtectedObjects) { throw "Blocage des objets proteges desactive" }
    if ([bool]$Context.AllowRawAttributeWrite) { throw "Ecriture brute activee : validation manuelle requise" }
    "Fraicheur, serialisation, objets proteges et editeur brut securise"
}
Add-Check "Securite" "Audit statique du script" {
    $path=[string]$Context.ScriptPath
    if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path -PathType Leaf) -or [IO.Path]::GetExtension($path) -ine ".ps1") { return "Mode EXE ou source non lisible : controle runtime uniquement" }
    $src=[IO.File]::ReadAllText($path)
    if ($src -notmatch "DOMENIA_MASTER_LAST_V1") { throw "Marqueur master absent" }
    if ($src -match "\.DeleteTree\s*\(") { throw "DeleteTree detecte" }
    if ($src -match "(?i)Recursive\s*=\s*\$true") { throw "Suppression recursive detectee" }
    if ($src -notmatch "DomeniaWriteDispatched") { throw "Garde d ecriture incertaine absente" }
    if ($src -match "\.Options\.SecurityMasks\s*=") { throw "Ancien acces DirectoryEntry.Options.SecurityMasks detecte" }
    "Aucune suppression recursive ; garde etat inconnu presente"
}
Add-Check "Securite" "Self-check non destructif" { "Aucune cmdlet Set/Add/Remove/New/Enable/Disable/Unlock/Move/Rename-AD n est invoquee par ce self-check" }
Add-Check "GUI" "Controles critiques" { if (@($Context.MissingCriticalControls).Count -gt 0) { throw "Manquants : $(@($Context.MissingCriticalControls) -join ', ')" }; "$($Context.CriticalControlCount) controles critiques presents" }
Add-Check "Module" "Source ActiveDirectory" { $sources=@($Context.AdModuleSources); if($sources.Count -gt 0){(@($sources | ForEach-Object { "$($_.Kind) : $($_.Path)" }) -join " | ")}else{"RSAT et DLL lateraux absents ; fallback LDAP disponible"} }
Add-Check "Association" "Moteur user-machine" { "Moteur charge, stockage local et fallbacks distants disponibles" }
Add-Check "Moteur" "Runspaces fermes" { if (-not [bool]$Context.AsyncEngineReady) { throw "Moteur asynchrone non initialise" }; "Moteur hash-pinne pret" }
Add-Check "Stockage local" "Dossier autonome" {
    if ([string]::IsNullOrWhiteSpace([string]$Context.DataDir)) { throw "Dossier de donnees vide" }
    if (-not (Test-Path -LiteralPath ([string]$Context.DataDir))) { throw "Dossier absent : $($Context.DataDir)" }
    $tmp=Join-Path ([string]$Context.DataDir) ("selfcheck-"+[guid]::NewGuid().ToString("N")+".tmp")
    [IO.File]::WriteAllText($tmp,"DOMENIA self-check local"); Remove-Item -LiteralPath $tmp -Force
    "Lecture/ecriture locale OK : $($Context.DataDir)"
}
Add-Check "LDAP" "Bind RootDSE" {
    $root = New-WRootDse $Context
    $dc = [string]$root.Properties["defaultNamingContext"].Value
    if ([string]::IsNullOrWhiteSpace($dc)) { throw "defaultNamingContext vide" }
    "Base detectee : $dc"
}
Add-Check "LDAP" "Lecture base AD" {
    $de = New-WEntry $Context ([string]$Context.BaseDn)
    $de.RefreshCache(@("distinguishedName","objectClass"))
    "DN : $($de.Properties["distinguishedName"].Value)"
}
Add-Check "LDAP" "Recherche utilisateur" {
    $s = New-WSearcher $Context ([string]$Context.BaseDn) "(&(objectCategory=person)(objectClass=user))" @("name") "Subtree" 1
    $r = $s.FindOne(); if ($null -eq $r) { throw "Aucun utilisateur lisible" }
    $sample = [string](Get-WPropFirst $r.Properties "name" "")
    "Exemple : $sample"
}
Add-Check "LDAP" "Recherche machine" {
    $s = New-WSearcher $Context ([string]$Context.BaseDn) "(objectCategory=computer)" @("name") "Subtree" 1
    $r = $s.FindOne(); if ($null -eq $r) { throw "Aucune machine lisible" }
    $sample = [string](Get-WPropFirst $r.Properties "name" "")
    "Exemple : $sample"
}
Add-Check "LDAP" "Recherche groupe" {
    $s = New-WSearcher $Context ([string]$Context.BaseDn) "(objectCategory=group)" @("name") "Subtree" 1
    $r = $s.FindOne(); if ($null -eq $r) { throw "Aucun groupe lisible" }
    $sample = [string](Get-WPropFirst $r.Properties "name" "")
    "Exemple : $sample"
}
Add-Check "LDAP" "Lecture arborescence" {
    $s = New-WSearcher $Context ([string]$Context.BaseDn) "(|(objectClass=organizationalUnit)(objectClass=container))" @("name") "OneLevel" 5
    $c = @($s.FindAll()).Count
    "$c branche(s) lue(s)"
}
Add-Check "Securite" "Lecture DACL base" {
    $security = Get-WActiveDirectorySecurity -Context $Context -Dn ([string]$Context.BaseDn) -IncludeOwner $false
    $c = @($security.GetAccessRules([bool]$true,[bool]$true,[type][System.Security.Principal.SecurityIdentifier])).Count
    "$c ACE"
}
Add-Check "Module" "ActiveDirectory" {
    if (Import-WAdModule $Context) { "$(@($Context.AdRequiredCommands | Where-Object { $null -ne (Get-Command -Name $_ -CommandType Cmdlet -ErrorAction SilentlyContinue) }).Count) cmdlet(s) DOMENIA disponibles" }
    else { "Absent, fallback LDAP disponible" }
}
Add-Check "Outils" "Outils Windows" {
    $tools = @("mstsc.exe","eventvwr.exe","compmgmt.msc")
    $found = foreach ($t in $tools) { if (Get-Command $t -ErrorAction SilentlyContinue) { $t } }
    "$(@($found).Count)/$($tools.Count) presents : $($found -join ", ")"
}
Add-Check "WAPT" "wapt-get" {
    $candidates = @([string]$Context.WaptGetPath,"$env:ProgramFiles\wapt\wapt-get.exe","${env:ProgramFiles(x86)}\wapt\wapt-get.exe") | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
    $hit = $candidates | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
    if ($hit) { "Detecte : $hit" } else { "Non detecte, fonction WAPT optionnelle" }
}
if ([int]$Payload.Iterations -gt 1) {
    Add-Check "Benchmark" "Recherches LDAP repetees" {
        $times = New-Object Collections.ArrayList
        for ($i=0; $i -lt [int]$Payload.Iterations; $i++) {
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            $s = New-WSearcher $Context ([string]$Context.BaseDn) "(|(&(objectCategory=person)(objectClass=user))(objectCategory=computer))" @("name") "Subtree" 25
            [void]@($s.FindAll()).Count
            $sw.Stop(); [void]$times.Add([int]$sw.ElapsedMilliseconds)
        }
        $avg = [Math]::Round((($times | Measure-Object -Average).Average),0)
        "Mesures : $($times -join " / ") ms, moyenne $avg ms"
    }
}
[pscustomobject]@{ Rows=@($rows); Full=[bool]$Payload.Full }
'@
        $selfCheckTaskName = if ($Full) { "Self-check complet" } else { "Self-check rapide" }
        Start-UiTask -Name $selfCheckTaskName -OperationId "SelfCheck" -Code $code -Payload ([pscustomobject]@{ Full=[bool]$Full; Iterations=$iterations }) -ReplaceKey "selfcheck" -DisableControls @("BtnSelfCheckQuick","BtnSelfCheckFull") -TimeoutSeconds ([int](Get-CfgValue "Async" "SelfCheckTimeoutSeconds" 120)) -StatusText "Self-check en lecture seule..." -OnSuccess {
            param($result)
            $script:SelfCheckRows = @($result.Rows)
            [void](Set-DomeniaItemsSource -Name "DgSelfCheck" -Rows $script:SelfCheckRows)
            $ok = @($script:SelfCheckRows | Where-Object { $_.Status -eq "OK" }).Count
            $err = @($script:SelfCheckRows | Where-Object { $_.Status -ne "OK" }).Count
            $totalMs = [int](($script:SelfCheckRows | Measure-Object DurationMs -Sum).Sum)
            $script:LastSelfCheckSummary = "$ok OK  $err erreur(s)  $totalMs ms"
            $script:Ctrl["LblSelfCheckStatus"].Text = "$($script:LastSelfCheckSummary). Aucune écriture AD effectuée."
            Update-Dashboard
            Set-Status "Self-check termine : $($script:LastSelfCheckSummary)."
        } -OnError {
            param($message)
            $script:LastSelfCheckSummary = "Erreur : $message"
            $script:Ctrl["LblSelfCheckStatus"].Text = $script:LastSelfCheckSummary
            Update-Dashboard
            [void](Show-DomeniaOperationError -Operation "Self-check DOMENIA" -ErrorRecordOrException ([string]$message))
        } | Out-Null
    } catch { [void](Show-DomeniaOperationError -Operation "Preparation du self-check DOMENIA" -ErrorRecordOrException $_) }
}

