function Export-CurrentResults {
    param([ValidateSet('Visible','Selected')][string]$Mode)
    try {
        $grid=Get-DomeniaControl 'DgObjects'
        if($null -eq $grid){return}
        # Point 60: one scope for the export: the one chosen beside the results (the list as shown, or the selected rows
        # only), or -Mode Selected from the bar of a multiple selection (FO-18). The confirmation repeats what was
        # excluded and what is known of the completeness of the list.
        $plan = if ($Mode) { Get-DomeniaResultScopePlan -Mode $Mode } else { Get-DomeniaResultScopePlan }
        if ([int]$plan.Count -eq 0) { Set-Status ('Aucune ligne à exporter : ' + [string]$plan.Label) "WARN"; return }
        $scope = if ([string]$plan.Mode -eq 'Selected') { 'lignes sélectionnées' } else { 'liste affichée' }
        # DS-20: the merged association cell still exports its source and its qualification as their own columns.
        $columns = @(Expand-DomeniaResultExportColumns -Columns @(Get-DomeniaGridExportColumns -Grid $grid))
        Show-DomeniaExportResult -Result (Export-DomeniaCsv -Rows @($plan.Rows) -Columns $columns -Grid $grid -Subject (Get-DomeniaSearchExportSubject)) -Scope $scope -Also ([string]$plan.Label + '.')
    } catch { Show-ErrorBox "Erreur export : $($_.Exception.Message)" }
}

function Clear-DomeniaSecretClipboard {
    param([switch]$Silent)
    try { if ($null -ne $script:SecretClipboardTimer) { $script:SecretClipboardTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Clear-DomeniaSecretClipboard' $_ }
    $script:SecretClipboardTimer = $null
    $expected = [string]$script:SecretClipboardValue
    try {
        if (-not [string]::IsNullOrEmpty($expected) -and [System.Windows.Clipboard]::ContainsText() -and [System.Windows.Clipboard]::GetText() -ceq $expected) {
            [System.Windows.Clipboard]::Clear()
            if (-not $Silent) { Set-Status "Presse-papiers secret efface." }
        }
    }
    catch { try { Write-AppLog "Effacement du presse-papiers secret impossible : $($_.Exception.Message)" "WARN" } catch { Write-DomeniaSwallowed 'Core' 'Clear-DomeniaSecretClipboard' $_ } }
    finally { $script:SecretClipboardValue = "" }
}

function Clear-Secrets {
    Clear-DomeniaSecretClipboard -Silent
    $script:ActiveSecretRequestId = ''
    try { if ($null -ne $script:SecretLifetimeTimer) { $script:SecretLifetimeTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Clear-Secrets' $_ }
    try { if ($null -ne $script:SecretRevealTimer) { $script:SecretRevealTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Clear-Secrets' $_ }
    foreach ($row in @($script:SecretRows)) { try { $row.Value = '' } catch { Write-DomeniaSwallowed 'Core' 'Clear-Secrets' $_ } }
    $script:SecretRows = @()
    $script:SecretsVisible = $false
    $script:RevealedSecretIndex = -1
    $script:SecretReveal = $null
    $script:BitLockerKeyList = @()
    $script:BitLockerKeyContext = $null
    try { $script:Ctrl["DgSecrets"].ItemsSource = $null; $script:Ctrl["LblSecretsStatus"].Text = "Aucun secret conservé en mémoire." } catch { Write-DomeniaSwallowed 'Core' 'Clear-Secrets' $_ }
    # UX-18: the BitLocker key card is emptied and hidden with the grid.
    try { Update-DomeniaSecretsView } catch { Write-DomeniaSwallowed 'Core' 'Clear-Secrets' $_ }
    try { Update-DomeniaSecretActionUi } catch { Write-DomeniaSwallowed 'Core' 'Clear-Secrets' $_ }
}

function Update-SecretsGrid {
    $rows = New-Object 'System.Collections.Generic.List[object]'
    $index = 0
    # D059: with a single reveal, only the row chosen by an explicit gesture is shown ($script:RevealedSecretIndex);
    # -1 keeps the previous whole-grid reveal (Features.SecretSingleCopy = false).
    $revealedIndex = -1
    if ($null -ne $script:RevealedSecretIndex) { $revealedIndex = [int]$script:RevealedSecretIndex }
    # UX-18: a BitLocker key revealed alone is read in its card, by blocks, not in the narrow cell of the grid.
    $cardIndex = -1
    try { $cardKey = Get-DomeniaRevealedBitLockerKey; if ($null -ne $cardKey) { $cardIndex = [int]$cardKey.Index } } catch { $cardIndex = -1 }
    foreach ($r in @($script:SecretRows)) {
        $hasValue = -not [string]::IsNullOrWhiteSpace([string]$r.Value)
        $shown = ($script:SecretsVisible -and ($revealedIndex -lt 0 -or $revealedIndex -eq $index))
        $display = if (-not $hasValue) { '' } elseif (($shown) -and ($index -eq $cardIndex)) { 'Affichée dans la carte ci-dessus' } elseif ($shown) { [string]$r.Value } else { '********' }
        # UX-18: the DN of a recovery object is not a detail for the operator; its identifier is.
        $detail = [string]$r.Detail
        if (([string]$r.Kind -match '(?i)BitLocker') -and ($detail -match '^(?i)(CN|OU|DC)=')) { $detail = '' }
        $rows.Add([pscustomobject]@{ Kind=$r.Kind; Account=$r.Account; DisplayValue=$display; Timestamp=$r.Timestamp; Source=$r.Source; Detail=$detail; SecretIndex=$index; HasValue=$hasValue })
        $index++
    }
    [void](Set-DomeniaItemsSource -Name 'DgSecrets' -Rows $rows.ToArray())
    try { Update-DomeniaSecretsView } catch { try { Write-AppLog ('Carte de la clé BitLocker : ' + $_.Exception.Message) 'WARN' } catch { Write-DomeniaSwallowed 'Core' 'Update-SecretsGrid' $_ } }
    # UI-31: the reveal button gets its label from Update-DomeniaSecretActionUi only.
    try { Update-DomeniaSecretActionUi } catch { Write-DomeniaSwallowed 'Core' 'Update-SecretsGrid' $_ }
}

function Test-DomeniaSecretCallbackCurrent {
    param($State)
    if ($null -eq $State -or $null -eq $script:SelectedObject) { return $false }
    if ([string]$script:ActiveSecretRequestId -ne [string]$State.RequestId) { return $false }
    if ([int64]$script:SelectedObjectGeneration -ne [int64]$State.Generation) { return $false }
    if ([string]$script:SelectedObject.DN -ine [string]$State.DN) { return $false }
    $currentGuid = ""
    try { $currentGuid = [string]$script:SelectedObject.Safety.Guid } catch { Write-DomeniaSwallowed 'Core' 'Test-DomeniaSecretCallbackCurrent' $_ }
    if (-not [string]::IsNullOrWhiteSpace([string]$State.ObjectGuid) -and $currentGuid -ine [string]$State.ObjectGuid) { return $false }
    return $true
}

function Clear-DomeniaSecretResultValues {
    param($Result)
    try { foreach ($row in @($Result.Rows)) { if ($null -ne $row.PSObject.Properties["Value"]) { $row.Value = "" } } } catch { Write-DomeniaSwallowed 'Core' 'Clear-DomeniaSecretResultValues' $_ }
}

function Stop-DomeniaSecretReadTasks {
    foreach ($taskId in @($script:AsyncJobs.Keys)) {
        $job = $script:AsyncJobs[$taskId]
        if ($null -ne $job -and [string]$job.ReplaceKey -eq "secrets" -and -not [bool]$job.IsWrite) {
            try { Request-UiTaskStop -Id ([string]$taskId) -Silent -Force -Superseded } catch { Write-DomeniaSwallowed 'Core' 'Stop-DomeniaSecretReadTasks' $_ }
        }
    }
    $script:ActiveSecretRequestId = ""
}

function Complete-DomeniaSecretLoadUi {
    param($Result,$State)
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Rows","Mode","Success")
    if ($null -eq $effective) { Fail-DomeniaSecretLoadUi -Message "Le worker n'a retourne aucun resultat exploitable." -State $State; return }
    if (-not (Test-DomeniaSecretCallbackCurrent -State $State)) {
        Clear-DomeniaSecretResultValues -Result $effective
        Write-AppLog "Resultat secret obsolete ignore pour $([string]$State.DN), requete $([string]$State.RequestId)." "WARN"
        return
    }
    $script:ActiveSecretRequestId = ""
    # D057: LAPS read and LAPS decryption are distinct. The worker returns metadata (Meta) without any password;
    # ConvertTo-DomeniaLapsView turns it into an explained state and facts (source, publication, expiration, decryptor).
    $lapsView = $null
    if ($effective.Mode -eq "LAPS" -and $null -ne $effective.PSObject.Properties["Meta"] -and $null -ne $effective.Meta) {
        try { $lapsView = ConvertTo-DomeniaLapsView -Result $effective.Meta } catch { $lapsView = $null }
    }
    $lapsFacts = ""
    if ($null -ne $lapsView) { $lapsFacts = ((@($lapsView.Facts) | ForEach-Object { [string]$_.Fait + " : " + [string]$_.Valeur }) -join " ; ") }
    if (-not [bool]$effective.Success) {
        Clear-DomeniaSecretResultValues -Result $effective
        $detail = if (-not [string]::IsNullOrWhiteSpace([string]$effective.ErrorMessage)) { [string]$effective.ErrorMessage } else { "Aucune valeur secrete lisible n'a ete retournee." }
        $errorKind = ""
        try { $errorKind = [string]$effective.ErrorKind } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaSecretLoadUi' $_ }
        if($errorKind -eq 'LogonFailure' -and $null -ne $script:AccessState){$scope=if($State.Mode -eq 'LAPS'){'ReadLaps'}else{'ReadBitLocker'};$script:AccessState.Faults[$scope]=$true}
        # A decryption refusal is not a read refusal: the resource is not marked denied, no fault is recorded and
        # BitLocker is untouched. Only a refused READ marks this resource for this computer.
        $readDenied = ($errorKind -eq "AccessDenied" -and ($null -eq $lapsView -or [string]$lapsView.State -eq 'ReadDenied'))
        if ($readDenied) {
            Set-DomeniaSecretDenied -Mode ([string]$State.Mode) -DN ([string]$State.DN)
            Write-AppLog "Lecture $($State.Mode) refusee. L autre ressource reste disponible." 'WARN'
        }
        Update-SecretsGrid
        if ($null -ne $lapsView) {
            $script:Ctrl["LblSecretsStatus"].Text = ("Lecture LAPS : " + [string]$lapsView.Message + $(if ($lapsFacts) { " " + $lapsFacts + "." } else { "" }))
        }
        else { $script:Ctrl["LblSecretsStatus"].Text = "Lecture impossible : $detail" }
        $op=if($State.Mode -eq 'LAPS'){'ReadLaps'}else{'ReadBitLocker'}
        $offerValue = if ($errorKind -eq 'AccessDenied') { 'Acces refuse. '+$detail } else { $detail }
        $offerPossible = ($errorKind -eq 'NoReadableValue' -or ($null -ne $lapsView -and [string]$lapsView.State -eq 'Unconfirmed'))
        $offered = $false
        if ($null -eq $lapsView -or [bool]$lapsView.OfferOtherAccount -or $errorKind -eq 'LogonFailure') {
            $offered=Request-DomeniaAccessRecovery -Operation "Lecture $($State.Mode)" -ErrorValue $offerValue -OperationId $op -DN ([string]$State.DN) -Interactive:([int]$State.RetryAttempt -eq 0) -Possible:$offerPossible
        }
        [void](Show-DomeniaOperationError -Operation "Lecture $($State.Mode)" -ErrorRecordOrException $detail -NoPopup:$offered)
        return
    }
    Set-DomeniaSecretDenied -Mode ([string]$State.Mode) -DN ([string]$State.DN) -Denied $false
    foreach($oldSecret in @($script:SecretRows)){try{$oldSecret.Value=''}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaSecretLoadUi' $_}}
    $script:SecretRows = @($effective.Rows | Where-Object { $null -ne $_ })
    $script:SecretsVisible = $false
    Restart-DomeniaSecretLifetime
    Update-SecretsGrid
    $count = @($script:SecretRows | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.Value) }).Count
    $extra = ""
    if ($effective.Mode -eq "LAPS" -and $null -ne $effective.PSObject.Properties["ModuleState"]) { $extra = " Module : $([string]$effective.ModuleState)  $([string]$effective.ModuleDetail)" }
    if ($effective.Mode -eq "BitLocker" -and $null -ne $effective.PSObject.Properties["RecoveryObjectsFound"] -and [int]$effective.RecoveryObjectsFound -eq 0) {
        $script:Ctrl["LblSecretsStatus"].Text = "Aucun objet de récupération visible avec ce compte. Lʼabsence de résultat ne prouve pas lʼabsence de clé."
        Set-Status "BitLocker : aucun objet de récupération visible avec ce compte." "WARN"
        [void](Request-DomeniaAccessRecovery -Operation 'Lecture BitLocker' -ErrorValue 'Aucune cle visible.' -OperationId 'ReadBitLocker' -DN ([string]$State.DN) -Possible -Interactive:([int]$State.RetryAttempt -eq 0))
        try { [void](Save-DomeniaSecretIndexEntry -Computer (Get-CurrentSelectedComputerName) -BitLockerKeys 0 -Verdict "aucune cle visible avec ce compte") }
        catch { Write-AppLog ("Index local des secrets non mis à jour (BitLocker) : " + $_.Exception.Message) "WARN" }
        return
    }
    $lapsSuffix = if ($lapsFacts) { " " + $lapsFacts + "." } else { "" }
    $script:Ctrl["LblSecretsStatus"].Text = "$count valeur(s) $($effective.Mode) chargée(s). Valeurs masquées et uniquement en mémoire.$extra$lapsSuffix"
    try {
        $verdict = "lisible par ton compte"
        if ($count -eq 0) { $verdict = "present mais non lisible par ton compte" }
        [void](Update-DomeniaSecretIndexFromRows -Computer (Get-CurrentSelectedComputerName) -Mode ([string]$effective.Mode) -Rows $script:SecretRows -Verdict $verdict)
    }
    catch {
        # P-CD-09: the values are loaded, but the local index of secret metadata keeps its previous state: say so.
        Write-AppLog ("Index local des secrets non mis à jour ($([string]$effective.Mode)) : " + $_.Exception.Message) "WARN"
    }

    try {
        $secretGrid = Get-DomeniaControl -Name "DgSecrets"
        if ($null -ne $secretGrid -and $secretGrid.Items.Count -gt 0) {
            $firstReadable = $secretGrid.Items | Where-Object {
                $null -ne $_ -and [bool]$_.HasValue
            } | Select-Object -First 1
            if ($null -ne $firstReadable) {
                $secretGrid.SelectedItem = $firstReadable
                try { $secretGrid.ScrollIntoView($firstReadable) } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaSecretLoadUi' $_ }
            }
        }
        Update-DomeniaSecretActionUi
    }
    catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaSecretLoadUi' $_ }

    Set-Status "$($effective.Mode) : $count valeur(s) lisible(s).$extra"
}

function Fail-DomeniaSecretLoadUi {
    param($Message,$State)
    if ($null -ne $State -and -not (Test-DomeniaSecretCallbackCurrent -State $State)) { return }
    $script:ActiveSecretRequestId = ''
    $mode=if($null -ne $State){[string]$State.Mode}else{'LAPS'}
    $kind=Get-DomeniaAccessFailureKind $Message
    # D057: an explicit decryption refusal does not mark the LAPS read as denied for this computer.
    $decryptOnly=$false
    try{$decryptOnly=([string](Get-DomeniaErrorDecision -Structured (Get-DomeniaStructuredError $Message) -Text ([string]$Message)).Category -eq 'DecryptionDenied')}catch{Write-DomeniaSwallowed 'Core' 'Fail-DomeniaSecretLoadUi' $_}
    if($kind -eq 'AccessDenied' -and -not $decryptOnly -and $null -ne $State){Set-DomeniaSecretDenied -Mode $mode -DN ([string]$State.DN)}
    Update-SecretsGrid
    [void](Set-DomeniaControlText 'LblSecretsStatus' ("Lecture $mode non confirmee : "+$Message))
    $op=if($mode -eq 'LAPS'){'ReadLaps'}else{'ReadBitLocker'}
    $offered=Request-DomeniaAccessRecovery -Operation "Lecture $mode" -ErrorValue $Message -OperationId $op -DN ([string]$State.DN) -Interactive:([int]$State.RetryAttempt -eq 0)
    [void](Show-DomeniaOperationError -Operation "Lecture $mode" -ErrorRecordOrException $Message -NoPopup:$offered)
}

function Start-LoadComputerSecrets {
    param([ValidateSet("BitLocker","LAPS")][string]$Mode,[ValidateRange(0,1)][int]$RetryAttempt=0)
    try {
        if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Machine") { Set-Status "Sélectionnez une machine." "WARN"; return }
        $opScope=if($Mode -eq 'LAPS'){'ReadLaps'}else{'ReadBitLocker'}
        # D055: the current Windows token, or the account already chosen for this resource, is used without any
        # prompt. Another account is asked only after a refusal for this resource (Get-DomeniaOperationAuthNeed).
        $authNeed = Get-DomeniaSecretIdentityReason -Mode $Mode
        if ([bool]$authNeed.Prompt) {
            [void](Request-DomeniaAccessRecovery -Operation "Lecture $Mode" -ErrorValue 'Acces refuse avec ce compte.' -OperationId $opScope -DN ([string]$script:SelectedObject.DN) -Interactive -Force)
            return
        }
        if ($script:CurrentCapabilities.ContainsKey("Secrets") -and $script:CurrentCapabilities["Secrets"] -eq "Refuse") {
            Write-AppLog "L'estimation ACL indique un refus pour la lecture des secrets sur $([string]$script:SelectedObject.DN). Tentative reelle maintenue ; le DC ou Windows LAPS reste l'autorite finale." "WARN"
            Set-Status "ACL estimee defavorable ; tentative reelle de lecture maintenue et controlee par AD." "WARN"
        }
        $dn = [string]$script:SelectedObject.DN
        $name = [string]$script:Ctrl["TxtCompName"].Text
        $secretOperationId = if ($Mode -eq "BitLocker") { "ReadBitLocker" } else { "ReadLaps" }
        $successHandler = "Complete-DomeniaSecretLoadUi"
        if ($Mode -eq "BitLocker" -and (Test-DomeniaBitLockerKeySelection)) {
            # D058 (Features.BitLockerKeySelection): metadata first. No recovery password is requested here;
            # one key is read later, on an explicit reveal or copy of the chosen line (ReadBitLockerKey).
            $code = Get-DomeniaBitLockerListWorkerCode
            $secretOperationId = "ReadBitLockerList"
            $successHandler = "Complete-DomeniaBitLockerListUi"
        }
        elseif ($Mode -eq "BitLocker") {
            $code = @'
$s = New-WSearcher $Context ([string]$Payload.DN) "(objectClass=msFVE-RecoveryInformation)" @("name","distinguishedName","msFVE-RecoveryPassword","msFVE-RecoveryGuid","whenCreated","whenChanged") "OneLevel" 0
$rows = New-Object Collections.ArrayList
$objectCount = 0
$collection = $null;$rootEntry = $s.SearchRoot
try {
    $collection = $s.FindAll()
    foreach ($r in $collection) {
        $objectCount++
        $p = $r.Properties
        $value = [string](Get-WPropFirst $p "msfve-recoverypassword" "")
        $rid = Convert-WGuid (Get-WPropFirst $p "msfve-recoveryguid" "")
        if ([string]::IsNullOrWhiteSpace($rid)) { $rid = [string](Get-WPropFirst $p "name" "") }
        if (-not [string]::IsNullOrWhiteSpace($value)) { [void]$rows.Add([pscustomobject]@{ Kind="BitLocker"; Account=$rid; Value=$value; Timestamp=(Convert-WDate (Get-WPropFirst $p "whencreated" "")); Source="msFVE-RecoveryInformation"; Detail=[string](Get-WPropFirst $p "distinguishedname" "") }) }
    }
}
finally {
    if ($null -ne $collection) { try { $collection.Dispose() } catch { } }
    try { $s.Dispose() } catch { }
    if ($null -ne $rootEntry) { try { $rootEntry.Dispose() } catch { } }
}
$readableCount = @($rows).Count
$success = ($objectCount -eq 0 -or $readableCount -gt 0)
$errorMessage = if ($objectCount -gt 0 -and $readableCount -eq 0) { "Des objets de recuperation existent, mais aucune cle n'est lisible avec le compte utilise." } else { "" }
[pscustomobject]@{ Rows=@($rows); Mode="BitLocker"; Success=$success; ErrorKind=$(if($success){""}else{"AccessDenied"}); ErrorMessage=$errorMessage; RecoveryObjectsFound=$objectCount; ReadableValues=$readableCount }
'@
        }
        else {
            $code = @'
$de=$null
$rows=[Collections.Generic.List[object]]::new()
$errorKind='';$errorMessage='';$moduleState='Non requis';$moduleDetail=''
$lapsSource='';$lapsPublished=$false;$lapsExpiration='';$lapsAccount='';$lapsDecryptor='';$decryptStatus='NotAttempted'
try{
    $de=New-WEntry $Context ([string]$Payload.DN)
    $p=Get-WAllProperties -Entry $de -PropertyNames @('ms-Mcs-AdmPwd','ms-Mcs-AdmPwdExpirationTime','msLAPS-Password','msLAPS-PasswordExpirationTime','msLAPS-EncryptedPassword')
    function FirstValue([string]$name){foreach($key in @($p.Keys)){if([string]$key -ieq $name){$v=@($p[$key]);if($v.Count){return $v[0]}}};return ''}
    function ExpirationUtc($value){$i=Convert-WLargeInteger $value;if($i -le 0 -or $i -eq 9223372036854775807){return ''};try{return [DateTime]::FromFileTimeUtc($i).ToString('o')}catch{return ''}}
    # Metadata only (D057): source, publication and expiration. No password value ever goes into Meta.
    $legacyExpiry=FirstValue 'ms-Mcs-AdmPwdExpirationTime'
    if($legacyExpiry){$lapsSource='LegacyLaps';$lapsPublished=$true;$lapsExpiration=ExpirationUtc $legacyExpiry}
    $modernExpiry=FirstValue 'msLAPS-PasswordExpirationTime'
    if($modernExpiry){$lapsSource='WindowsLaps';$lapsPublished=$true;$lapsExpiration=ExpirationUtc $modernExpiry}
    if(FirstValue 'msLAPS-EncryptedPassword'){$lapsSource='WindowsLaps';$lapsPublished=$true}
    $legacy=FirstValue 'ms-Mcs-AdmPwd'
    if($legacy){$lapsSource='LegacyLaps';$lapsPublished=$true;$decryptStatus='NotEncrypted';$lapsAccount='Administrateur local';$rows.Add([pscustomobject]@{Kind='LAPS historique';Account='Administrateur local';Value=$legacy;Timestamp=(Convert-WFileTime (FirstValue 'ms-Mcs-AdmPwdExpirationTime'));Source='ms-Mcs-AdmPwd';Detail='Lecture attribut LAPS historique'})}
    $modern=FirstValue 'msLAPS-Password'
    if($modern){
        try{$o=$modern|ConvertFrom-Json -ErrorAction Stop;if([string]$o.p){$lapsSource='WindowsLaps';$lapsPublished=$true;$decryptStatus='NotEncrypted';$lapsAccount=[string]$o.n;$rows.Add([pscustomobject]@{Kind='Windows LAPS';Account=[string]$o.n;Value=[string]$o.p;Timestamp=(Convert-WFileTime (FirstValue 'msLAPS-PasswordExpirationTime'));Source='msLAPS-Password';Detail='Lecture attribut Windows LAPS'})}}
        catch{throw 'Attribut LAPS JSON invalide. Son contenu brut n est pas journalise.'}
    }
    if(-not $rows.Count){
        $cmd=Get-Command Get-LapsADPassword -ErrorAction SilentlyContinue
        if($null -eq $cmd){
            try{Import-Module LAPS -ErrorAction Stop;$cmd=Get-Command Get-LapsADPassword -ErrorAction Stop}
            catch{$errorKind='ModuleMissing';throw 'Module Windows LAPS absent. Aucun decryptage possible. Le changement de compte ne remplace pas ce module.'}
        }
        $params=@{Identity=[string]$Payload.DN;ErrorAction='Stop'}
        if($cmd.Parameters.ContainsKey('AsPlainText')){$params.AsPlainText=$true}
        if($cmd.Parameters.ContainsKey('DomainController') -and $Context.Server){$params.DomainController=[string]$Context.Server}
        $cred=Get-WAdCredential $Context
        if($null -ne $cred){
            if(-not $cmd.Parameters.ContainsKey('Credential')){throw 'Cette version du module LAPS ne prend pas en charge le compte choisi.'}
            $params.Credential=$cred
            if($cmd.Parameters.ContainsKey('DecryptionCredential')){$params.DecryptionCredential=$cred}
        }
        # One call with the chosen identity; no fallback to Windows or another principal.
        $values=@(Get-LapsADPassword @params)
        foreach($v in $values){
            $lapsSource='WindowsLaps'
            if([string]$v.Account){$lapsAccount=[string]$v.Account}
            if($null -ne $v.PSObject.Properties['AuthorizedDecryptor']){$lapsDecryptor=[string]$v.AuthorizedDecryptor}
            if($null -ne $v.PSObject.Properties['ExpirationTimestamp'] -and $null -ne $v.ExpirationTimestamp){try{$lapsExpiration=([datetime]$v.ExpirationTimestamp).ToUniversalTime().ToString('o')}catch{}}
            $plain=''
            if($v.Password -is [Security.SecureString]){$plain=([Management.Automation.PSCredential]::new('value',$v.Password)).GetNetworkCredential().Password}else{$plain=[string]$v.Password}
            if($plain){$lapsPublished=$true;$decryptStatus='OK';$rows.Add([pscustomobject]@{Kind='Windows LAPS';Account=[string]$v.Account;Value=$plain;Timestamp=[string]$v.ExpirationTimestamp;Source='Get-LapsADPassword';Detail='Lecture et decryptage avec le compte explicitement choisi'})}
            elseif([string]$v.DecryptionStatus -match '(?i)Unauthorized|AccessDenied'){
                # Published and read, decryption refused: neither an empty password nor a refusal of the whole account.
                $lapsPublished=$true;$decryptStatus='Unauthorized';$errorKind='DecryptionDenied';$errorMessage='Le compte ne dispose pas du droit de dechiffrement LAPS.'
            }
            $plain=''
        }
        $moduleState='Disponible';$moduleDetail='Une demande Windows LAPS, aucune variante automatique.'
    }
}catch{
    if(-not $errorKind){
        $errorKind=if($_.Exception.Message -match '(?i)access.*denied|acc[eè]s.*refus|unauthori[sz]ed'){'AccessDenied'}elseif($_.Exception.Message -match '(?i)logon failure|mot de passe.*incorrect|invalid.*credential'){'LogonFailure'}else{'ReadFailed'}
    }
    $errorMessage=$_.Exception.Message;$moduleDetail=$errorMessage
}finally{if($null -ne $de){try{$de.Dispose()}catch{}}}
if(-not $rows.Count -and -not $errorMessage){$errorKind='NoReadableValue';$errorMessage='Aucune valeur LAPS visible avec ce compte : publication ou droits a verifier.'}
$readStatus='OK'
if($errorKind -eq 'ModuleMissing'){$readStatus='ModuleMissing'}
elseif($errorKind -eq 'AccessDenied'){$readStatus='AccessDenied'}
elseif($errorKind -in @('LogonFailure','ReadFailed')){$readStatus='Failed'}
elseif($errorKind -eq 'NoReadableValue'){$readStatus='Unconfirmed'}
$reader=[string]$Context.BindUser;if(-not $reader){$reader=[string]$Context.ProcessIdentity}
$meta=[pscustomobject]@{Source=$lapsSource;Published=$lapsPublished;ExpirationUtc=$lapsExpiration;Account=$lapsAccount;Decryptor=$lapsDecryptor;PasswordPresent=($rows.Count -gt 0);ReadStatus=$readStatus;DecryptStatus=$decryptStatus;Reader=$reader}
[pscustomobject]@{Rows=$rows.ToArray();Mode='LAPS';Success=($rows.Count -gt 0);ErrorKind=$errorKind;ErrorMessage=$errorMessage;ModuleState=$moduleState;ModuleDetail=$moduleDetail;Meta=$meta}
'@
        }
        $requestId = [guid]::NewGuid().ToString("N")
        $script:ActiveSecretRequestId = $requestId
        $objectGuid = ""
        try { $objectGuid = [string]$script:SelectedObject.Safety.Guid } catch { Write-DomeniaSwallowed 'Core' 'Start-LoadComputerSecrets' $_ }
        $callbackState = [pscustomobject]@{
            RequestId=$requestId; DN=$dn; ObjectGuid=$objectGuid
            Generation=[int64]$script:SelectedObjectGeneration; Mode=$Mode; RetryAttempt=$RetryAttempt
        }
        Start-UiTask -Name "Lecture $Mode" -OperationId $secretOperationId -Code $code -Payload ([pscustomobject]@{ DN=$dn; Name=$name }) -CallbackState $callbackState -ReplaceKey "secrets" -DisableControls @("BtnLoadBitLocker","BtnLoadLaps") -TimeoutSeconds 40 -StatusText ("Lecture $Mode en arriere-plan... Identite : " + [string]$authNeed.Reason) -SuccessHandler $successHandler -ErrorHandler "Fail-DomeniaSecretLoadUi" | Out-Null
    }
    catch {
        $script:ActiveSecretRequestId = ""
        [void](Show-DomeniaOperationError -Operation "Lecture $Mode" -ErrorRecordOrException $_)
    }
}

function Toggle-SecretsVisibility {
    if (@($script:SecretRows).Count -eq 0) { return }
    if (Test-DomeniaSecretSingleExposure) {
        # D058/D059 (Features.SecretSingleCopy): only the selected value is revealed, after this explicit gesture,
        # for the exposure policy duration. A BitLocker line holding metadata only triggers the read of that ONE key.
        try { if ($null -ne $script:SecretRevealTimer) { $script:SecretRevealTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Toggle-SecretsVisibility' $_ }
        if ($script:SecretsVisible) { $script:SecretsVisible = $false; $script:RevealedSecretIndex = -1; Update-SecretsGrid; return }
        $grid = Get-DomeniaControl -Name 'DgSecrets'
        $selectedCount = 0
        if ($null -ne $grid -and $null -ne $grid.SelectedItem) { $selectedCount = 1 }
        if (-not (Test-DomeniaSecretRevealAllowed -Trigger 'ExplicitReveal' -SelectedCount $selectedCount)) { Set-Status "Selectionnez la valeur a afficher. Une seule valeur est revelee a la fois."; return }
        $source = Get-DomeniaSelectedSecretSource
        if ($null -eq $source) { return }
        if ([string]::IsNullOrWhiteSpace([string]$source.Value)) {
            if ([bool](Get-DomeniaMember $source 'Metadata' $false)) { [void](Request-DomeniaBitLockerKey -Trigger 'ExplicitReveal') }
            return
        }
        [void](Start-DomeniaSecretReveal -Index (Get-DomeniaSelectedSecretIndex))
        return
    }
    $script:RevealedSecretIndex = -1
    $script:SecretsVisible = -not $script:SecretsVisible
    try { if ($null -ne $script:SecretRevealTimer) { $script:SecretRevealTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Toggle-SecretsVisibility' $_ }
    if ($script:SecretsVisible) {
        # FI-05: protected timer of the engine heartbeat.
        $script:SecretRevealTimer = New-DomeniaTimer -Owner 'Timer:SecretReveal' -IntervalMs 60000 -Start -Tick {
            param($sender,$eventArgs)
            $sender.Stop()
            $script:SecretsVisible = $false
            Update-SecretsGrid
        }
    }
    Update-SecretsGrid
}

function Start-SecretClipboardAutoClear {
    param([string]$Value)
    try {
        if ($null -ne $script:SecretClipboardTimer) { $script:SecretClipboardTimer.Stop() }
        $script:SecretClipboardValue = $Value
        $seconds = [int](Get-CfgValue "Security" "AutoClearSecretClipboardSeconds" 30)
        if ($seconds -le 0) { return }
        # FI-05: protected timer of the engine heartbeat; it also runs while the window is minimized.
        $script:SecretClipboardTimer = New-DomeniaTimer -Owner 'Timer:SecretClipboard' -IntervalMs ($seconds * 1000) -RunWhenHidden -Start -Tick {
            param($sender,$eventArgs)
            try { $sender.Stop() } catch { Write-DomeniaSwallowed 'Core' 'Start-SecretClipboardAutoClear' $_ }
            try {
                Clear-DomeniaSecretClipboard
                Set-Status "Presse-papiers secret efface automatiquement."
            }
            catch { try { Write-AppLog "Timer presse-papiers secret : $($_.Exception.ToString())" "WARN" } catch { Write-DomeniaSwallowed 'Core' 'Start-SecretClipboardAutoClear' $_ } }
        }
    } catch { try { Write-AppLog "Programmation de l'effacement du presse-papiers impossible : $($_.Exception.ToString())" "WARN" } catch { Write-DomeniaSwallowed 'Core' 'Start-SecretClipboardAutoClear' $_ } }
}

function Copy-SelectedSecret {
    try {
        $row = Get-DomeniaSelectedSecretSource
        # D059: the limits of third-party clipboard history stay explicit at every copy.
        $clipboardLimit = [string](Get-DomeniaSecretExposurePolicy).ClipboardLimit
        if ($null -ne $row -and [string]::IsNullOrWhiteSpace([string]$row.Value) -and [bool](Get-DomeniaMember $row 'Metadata' $false)) {
            # D058: a BitLocker line holding metadata only. The chosen key is read, then copied, after this confirmation.
            if (-not (Confirm-Action ("Lire puis copier temporairement la clé BitLocker " + [string]$row.Account + " ? Seule cette clé est lue. " + $clipboardLimit))) { return }
            [void](Request-DomeniaBitLockerKey -Trigger 'ExplicitCopy')
            return
        }
        if ($null -eq $row -or [string]::IsNullOrWhiteSpace([string]$row.Value)) { Set-Status "Aucun secret sélectionné." "WARN"; return }
        if (-not (Confirm-Action ("Copier temporairement ce secret dans le presse-papiers ? " + $clipboardLimit))) { return }
        Set-DomeniaProtectedClipboard -Value ([string]$row.Value) -MaxLength 1024
        Start-SecretClipboardAutoClear ([string]$row.Value)
        Write-AppLog "Secret copie temporairement : $($row.Kind) / $($row.Account)" "WARN"
        Set-Status ("Secret copie. Effacement automatique programme. " + $clipboardLimit)
    } catch { Show-ErrorBox "Erreur copie secret : $($_.Exception.Message)" }
}

function Copy-AllSecrets {
    # D059 (Features.SecretSingleCopy): one value at a time. The previous "copy all" stays available only when the switch is off.
    if (Test-DomeniaSecretSingleExposure) { Set-Status "Copie groupee desactivee : copiez la seule valeur necessaire." "WARN"; return }
    if(-not (Confirm-Action -Title 'Copie de plusieurs secrets' -Message 'Copier toutes les valeurs augmente leur exposition. Preferez la copie de la seule valeur necessaire. Continuer ?')){return}
    try {
        $usable = @($script:SecretRows | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.Value) })
        if ($usable.Count -eq 0) { return }
        if (-not (Confirm-Action "Copier les $($usable.Count) secrets dans le presse-papiers ?")) { return }
        $value = (($usable | ForEach-Object { "$($_.Kind) | $($_.Account) | $($_.Value) | $($_.Timestamp)" }) -join [Environment]::NewLine)
        Set-DomeniaProtectedClipboard -Value $value
        Start-SecretClipboardAutoClear $value
        Write-AppLog "$($usable.Count) secrets copies temporairement." "WARN"
    } catch { Show-ErrorBox "Erreur copie secrets : $($_.Exception.Message)" }
}

function Set-MachineCredentialFromUi {
    try {
        $user = ($script:Ctrl["TxtMachineAdminUser"].Text + "").Trim()
        if ([string]::IsNullOrWhiteSpace($user)) { throw "Compte poste vide." }
        # SE-16: the account is built from the SecureString of the PasswordBox, never from its plain text.
        $secure = $script:Ctrl["PwdMachineAdmin"].SecurePassword
        if (($null -eq $secure) -or ($secure.Length -eq 0)) { if ($null -ne $secure) { $secure.Dispose() }; throw "Mot de passe du compte poste vide." }
        $secure.MakeReadOnly()
        Hide-DomeniaSecretPeek -Owner 'Timer:MachineAdminPeek'
        $script:MachineCredential = New-Object System.Management.Automation.PSCredential -ArgumentList @($user,$secure)
        # Point 44: every change of the account in use moves the account generation, like the other account changes
        # (a survey started with the previous account stops instead of mixing two accounts). Not a validation: a
        # pause recorded for this account stays until it is validated in Comptes.
        $script:DomeniaAccountGeneration = [long]$script:DomeniaAccountGeneration + 1
        $script:Ctrl["PwdMachineAdmin"].Password = ""
        Update-DomeniaMachineAccountUi -Force
        Set-Status "Compte poste chargé en mémoire uniquement, jamais enregistré."
    } catch { Show-ErrorBox "Compte poste non utilisé : $($_.Exception.Message)" }
}

function Clear-MachineCredential {
    if ($null -ne $script:MachineCredential) { $script:DomeniaAccountGeneration = [long]$script:DomeniaAccountGeneration + 1 }
    $script:MachineCredential = $null
    Hide-DomeniaSecretPeek -Owner 'Timer:MachineAdminPeek'
    try { if ($script:Ctrl.ContainsKey("PwdMachineAdmin")) { $script:Ctrl["PwdMachineAdmin"].Password = "" } } catch { Write-DomeniaSwallowed 'Core' 'Clear-MachineCredential' $_ }
    try { Update-DomeniaMachineAccountUi -Force } catch { Write-DomeniaSwallowed 'Core' 'Clear-MachineCredential' $_ }
    Set-Status ("Compte poste oublié. " + (Get-DomeniaMachineOperationAccountText))
}


# =====================================================================
# Inventaire poste : collecte CIM/WMI source par source.
# Chaque source est isolee afin qu un refus d acces sur l une n empeche
# pas les autres, et le rapport d acces indique exactement ce qui a
# repondu, ce qui a ete refuse et ce qui est indisponible.
# =====================================================================
function Get-DomeniaInventoryWorkerCode {
    return @'
$DomeniaCollectedResult = & {
$rows = New-Object Collections.ArrayList
$access = New-Object Collections.ArrayList
# Numbers for the workstation dashboard (decision David 2026-10-07); the rows stay the textual inventory.
$metrics = [pscustomobject]@{ MemoryTotal=0.0; MemoryFree=0.0; MemorySource=''; MemorySlots=-1; MemoryModules=-1; LastBoot=''; CpuLoad=-1.0; Battery=-1.0; ClockSkewSeconds=$null; ClockReference=''; LogicalProcessors=0; Disks=(New-Object Collections.ArrayList); Hotfixes=(New-Object Collections.ArrayList); Processes=(New-Object Collections.ArrayList); ProcessSample=$null; Certificates=$null; Services=@{} }
$computer = [string]$Payload.Computer
$deep = [bool]$Payload.Deep
$cred = Get-WMachineCredential $Context
$totalWatch = [System.Diagnostics.Stopwatch]::StartNew()
$budgetMs = [Math]::Max(20000,[int]$Payload.BudgetMs)

$script:PrimarySession = $null
$script:AltSession = $null
$script:AltTried = $false
$script:PrimaryLabel = 'DCOM'
$script:AltLabel = 'WinRM'
$script:CollectorDeadline = [long]0
$script:CollectorTruncated = ''
$script:CollectorTransport = ''
$script:WinrmReady = $false

function Add-Item {
    param([string]$Category,[string]$Name,$Value,[string]$Source)
    $text = ''
    if ($null -ne $Value) { $text = ([string]$Value).Trim() }
    if ([string]::IsNullOrWhiteSpace($text)) {
        # An empty answer is said in words: nobody connected, no proxy, a field the maker left blank.
        $text = switch -Regex ($Name) {
            '^Utilisateur connecte$' { 'Aucun'; break }
            '^Proxy' { 'Aucun (acces direct)'; break }
            '^Site Active Directory$' { 'Non determine'; break }
            '^Suffixe DNS' { 'Aucun'; break }
            'serie|UUID|Reference produit' { 'Non fourni par le fabricant'; break }
            default { 'Non renseigne' }
        }
    }
    [void]$rows.Add([pscustomobject]@{ Category=$Category; Item=$Name; Value=$text; Source=$Source })
}
function Add-Access {
    param([string]$Category,[string]$Status,[string]$Detail,[int]$Ms,[int]$Count)
    [void]$access.Add([pscustomobject]@{ Category=$Category; Status=$Status; Items=$Count; DurationMs=$Ms; Detail=$Detail })
}
function Format-Size {
    param($Bytes)
    $v = 0.0
    try { $v = [double]$Bytes } catch { return '' }
    if ($v -le 0) { return '0 o' }
    $units = @('o','Ko','Mo','Go','To')
    $i = 0
    while ($v -ge 1024 -and $i -lt 4) { $v = $v / 1024.0; $i++ }
    $rounded = [Math]::Round($v,2)
    $unit = $units[$i]
    return ('' + $rounded + ' ' + $unit)
}
function Get-CimDate {
    param($Value)
    if ($null -eq $Value) { return '' }
    try { return ([datetime]$Value).ToString('dd/MM/yyyy HH:mm:ss') } catch { return [string]$Value }
}
# Point 96: exact copies of the Workstation.Model rules (the worker runspace does not load the modules).
function Get-DomeniaCommandExecutable {
    # Point 96: the program of a startup command, without its arguments, which may hold a password, a token or a
    # private path. A quoted program is taken whole. Only an unquoted absolute path (drive, UNC or %VARIABLE%\) may
    # run across spaces, up to the first known program extension, and never across a switch (a space then - or /),
    # another drive, a character Windows refuses in a path, an assignment (=) or a chained command (&): such an
    # unquoted path is ambiguous for Windows itself, the scan stops at the first program it can name. Anything else
    # keeps its first word only, so an argument written before a later program never survives. The ComputerInventory
    # worker carries an exact copy of this function (checked by the Workstation rules): the arguments never leave
    # the worker.
    param([AllowEmptyString()][AllowNull()][string]$Command)
    $text = ([string]$Command).Trim()
    if (-not $text) { return '' }
    if ($text.StartsWith('"')) {
        $end = $text.IndexOf('"', 1)
        if ($end -gt 1) { return $text.Substring(1, $end - 1).Trim() }
        return ''
    }
    $program = [regex]::Match($text, '^(?:[A-Za-z]:\\|\\\\|%[A-Za-z0-9_()]+%\\)(?:[^"<>|?*:=&,\s]|\s(?![-/]))*?\.(?:exe|com|bat|cmd|ps1|vbs|vbe|js|jse|wsf|lnk|scr|msc|cpl|pif|hta|msi|dll)(?=\s|,|$)', [Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if ($program.Success) { return $program.Value }
    return @($text -split '[\s,]', 2)[0]
}
function ConvertFrom-DomeniaTaskCacheDynamicInfo {
    # Point 96: dates the Task Scheduler keeps in the DynamicInfo value of its registry cache
    # (HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Schedule\TaskCache\Tasks\{id}), read by StdRegProv when WinRM
    # is not available. Microsoft does not document this binary value: only the two dates every known layout shares
    # are decoded, registration (offset 4) and last start (offset 12), as UTC FILETIME. The last result is never
    # guessed from it. A value shorter than 20 bytes or a date outside 2000-2100 decodes nothing. The ComputerInventory
    # worker carries an exact copy of this function (checked by the Workstation rules).
    param([AllowNull()][byte[]]$Bytes)
    $result = [pscustomobject]@{ Decoded = $false; RegisteredUtc = $null; LastStartUtc = $null; NeverStarted = $false }
    if (($null -eq $Bytes) -or ($Bytes.Length -lt 20)) { return $result }
    $dates = @()
    foreach ($offset in @(4, 12)) {
        $ticks = [BitConverter]::ToInt64($Bytes, $offset)
        if ($ticks -eq 0) { $dates += ,$null; continue }
        $date = $null
        try { $date = [datetime]::FromFileTimeUtc($ticks) } catch { return $result }
        if (($date.Year -lt 2000) -or ($date.Year -gt 2100)) { return $result }
        $dates += ,$date
    }
    if ($null -eq $dates[0]) { return $result }
    $result.Decoded = $true
    $result.RegisteredUtc = $dates[0]
    $result.LastStartUtc = $dates[1]
    $result.NeverStarted = ($null -eq $dates[1])
    return $result
}
function Get-InventoryControllerClockOffset {
    # Seconds between the currentTime of the connected controller's RootDSE and this computer's clock; $null when not
    # read. One read of the controller already used by the session, nothing else on the network.
    $root = $null
    try {
        $root = New-WRootDse $Context
        $root.RefreshCache(@('currentTime'))
        $raw = $root.Properties['currentTime'].Value
        $readUtc = (Get-Date).ToUniversalTime()
        $controllerUtc = $null
        if ($raw -is [datetime]) { $controllerUtc = [datetime]::SpecifyKind($raw,[DateTimeKind]::Utc) }
        else {
            $parsed = [datetime]::MinValue
            if ([datetime]::TryParseExact(([string]$raw).Trim(),'yyyyMMddHHmmss.0Z',[Globalization.CultureInfo]::InvariantCulture,([Globalization.DateTimeStyles]::AssumeUniversal -bor [Globalization.DateTimeStyles]::AdjustToUniversal),[ref]$parsed)) { $controllerUtc = $parsed }
        }
        if ($null -eq $controllerUtc) { return $null }
        return ($controllerUtc - $readUtc).TotalSeconds
    }
    catch { return $null }
    finally { if ($null -ne $root) { try { $root.Dispose() } catch { } } }
}
function Test-Budget { return ($totalWatch.ElapsedMilliseconds -lt $budgetMs) }
function Test-CollectorBudget {
    if ($script:CollectorDeadline -le 0) { return $true }
    if (-not (Test-Budget)) { return $false }
    return ($totalWatch.ElapsedMilliseconds -lt $script:CollectorDeadline)
}
function Set-CollectorTruncated { param([string]$Reason) $script:CollectorTruncated = $Reason }

function Get-FailureStatus {
    param([string]$Message)
    if ($Message -match '(?i)access is denied|acces refuse|refus|denied|0x80070005|authoris') { return 'REFUSE' }
    if ($Message -match '(?i)invalid class|invalid namespace|not supported|introuvable|not found|non pris en charge|0x80041010') { return 'INDISPONIBLE' }
    if ($Message -match '(?i)timeout|delai|expire|RPC server is unavailable|serveur RPC|WinRM cannot complete') { return 'INJOIGNABLE' }
    return 'ERREUR'
}
function Invoke-InventoryTaskFallback {
    param([string]$ClassicError)
    $sw=[Diagnostics.Stopwatch]::StartNew()
    try {
        $local=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
        $fb=Invoke-WRemoteTaskScript $Context $computer $local ([pscustomobject]@{Deep=$deep}) ([Math]::Min(75,[int]$Context.TaskFallbackTimeoutSeconds)) $ClassicError
        $fallbackLabel=if([string]$fb.DomeniaTransport -eq 'PsExec'){'PsExec'}else{'Tache planifiee'}
        foreach($rr in @($fb.Rows)) { Add-Item ([string]$rr.Category) ([string]$rr.Item) ([string]$rr.Value) ($fallbackLabel+' local SYSTEM / '+[string]$rr.Source) }
        $sw.Stop(); Add-Access ('Fallback '+$fallbackLabel) 'OK' ('Collecte locale SYSTEM terminee via '+$fallbackLabel+'.') ([int]$sw.ElapsedMilliseconds) @($fb.Rows).Count
        $bytes=0;try{$bytes=[long]$fb.DomeniaBytesSent+[long]$fb.DomeniaBytesReceived}catch{}
        return [pscustomobject]@{Computer=$computer;Rows=@($rows);Access=@($access);DurationMs=[long]$totalWatch.ElapsedMilliseconds;Success=$true;FallbackTasks=1;TaskBytes=$bytes}
    }
    catch {
        $sw.Stop(); Add-Access 'Fallbacks PsExec / tache' (Get-FailureStatus ([string]$_.Exception.Message)) ([string]$_.Exception.Message) ([int]$sw.ElapsedMilliseconds) 0
        return [pscustomobject]@{Computer=$computer;Rows=@($rows);Access=@($access);DurationMs=[long]$totalWatch.ElapsedMilliseconds;Success=$false;FallbackTasks=1;TaskBytes=0}
    }
}

function Invoke-Collector {
    param([string]$Category,[scriptblock]$Action,[int]$MaxMs = 12000)
    if (-not (Test-Budget)) { Add-Access $Category 'IGNORE' 'Budget global epuise avant cette source.' 0 0; return }
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $before = $rows.Count
    $script:CollectorDeadline = [long]$totalWatch.ElapsedMilliseconds + [long]$MaxMs
    $script:CollectorTruncated = ''
    $script:CollectorTransport = ''
    try {
        & $Action
        $sw.Stop()
        $produced = $rows.Count - $before
        $status = 'OK'
        $detail = ''
        if ($produced -eq 0) { $status = 'VIDE'; $detail = 'La source a repondu sans aucune donnee.' }
        elseif (-not [string]::IsNullOrWhiteSpace($script:CollectorTruncated)) { $status = 'PARTIEL'; $detail = $script:CollectorTruncated }
        if (-not [string]::IsNullOrWhiteSpace($script:CollectorTransport)) {
            $prefix = 'Transport ' + $script:CollectorTransport + '.'
            if ([string]::IsNullOrWhiteSpace($detail)) { $detail = $prefix } else { $detail = $prefix + ' ' + $detail }
        }
        Add-Access $Category $status $detail ([int]$sw.ElapsedMilliseconds) $produced
    }
    catch {
        if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw}
        $sw.Stop()
        $message = [string]$_.Exception.Message
        Add-Access $Category (Get-FailureStatus $message) $message ([int]$sw.ElapsedMilliseconds) ($rows.Count - $before)
    }
    finally { $script:CollectorDeadline = 0 }
}

function New-InventorySession {
    param([string]$Protocol,[int]$TimeoutSeconds = 18)
    $option = New-CimSessionOption -Protocol $Protocol -ErrorAction Stop
    $params = @{ ComputerName=$computer; SessionOption=$option; ErrorAction='Stop' }
    if ($null -ne $cred) { $params['Credential'] = $cred }
    try {
        $command = Get-Command New-CimSession -ErrorAction Stop
        if ($command.Parameters.ContainsKey('OperationTimeoutSec')) { $params['OperationTimeoutSec'] = [Math]::Max(2,$TimeoutSeconds) }
    }
    catch { }
    $lease=Enter-WCredentialAttempt -Context $Context -Channel Remote;$opened=$null
    try{
        Assert-WCredentialAllowed -Context $Context -Channel Remote
        $opened=New-CimSession @params
        # DCOM session creation is lazy: validate the first authenticated operation while the account lease is held.
        [void](Get-CimInstance -CimSession $opened -ClassName Win32_OperatingSystem -Property CSName -OperationTimeoutSec ([Math]::Max(2,$TimeoutSeconds)) -ErrorAction Stop)
        return $opened
    }catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);if($null -ne $opened){Remove-CimSession $opened -ErrorAction Ignore};throw}
    finally{Exit-WCredentialAttempt -Lease $lease}
}

function Get-AltSession {
    # Ouverture paresseuse du transport de repli : on ne paie son cout que si
    # une source echoue reellement sur le transport principal.
    if ($null -ne $script:AltSession) { return $script:AltSession }
    if ($script:AltTried) { return $null }
    $script:AltTried = $true
    $protocol = 'Wsman'
    if ($script:PrimaryLabel -eq 'WinRM') { $protocol = 'Dcom' }
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        $script:AltSession = New-InventorySession $protocol 15
        $sw.Stop()
        Add-Access 'Repli de transport' 'OK' ('Session ' + $script:AltLabel + ' ouverte en repli du transport principal.') ([int]$sw.ElapsedMilliseconds) 0
    }
    catch {
        if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw}
        $sw.Stop()
        $message = [string]$_.Exception.Message
        Add-Access 'Repli de transport' (Get-FailureStatus $message) ('Repli ' + $script:AltLabel + ' impossible : ' + $message) ([int]$sw.ElapsedMilliseconds) 0
        $script:AltSession = $null
    }
    return $script:AltSession
}

function Get-Cim {
    param([string]$Class,[string]$Namespace = 'root\cimv2',[string]$Filter = '',[string]$Query = '')
    $build = {
        param($Session)
        $p = @{ CimSession=$Session; Namespace=$Namespace; ErrorAction='Stop' }
        if (-not [string]::IsNullOrWhiteSpace($Query)) { $p['Query'] = $Query }
        else {
            $p['ClassName'] = $Class
            if (-not [string]::IsNullOrWhiteSpace($Filter)) { $p['Filter'] = $Filter }
        }
        Assert-WCredentialAllowed -Context $Context -Channel Remote
        return @(Get-CimInstance @p)
    }
    try {
        $result = & $build $script:PrimarySession
        if ([string]::IsNullOrWhiteSpace($script:CollectorTransport)) { $script:CollectorTransport = $script:PrimaryLabel }
        return $result
    }
    catch {
        if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw}
        $primaryError = [string]$_.Exception.Message
        $alt = Get-AltSession
        if ($null -eq $alt) { throw }
        $result = & $build $alt
        $script:CollectorTransport = $script:AltLabel + ' apres echec ' + $script:PrimaryLabel
        return $result
    }
}

function Invoke-Remote {
    # Execution distante par WinRM. Un aller-retour unique remplace des
    # centaines d appels registre, quand le service le permet.
    param([Parameter(Mandatory=$true)][scriptblock]$ScriptBlock,[int]$TimeoutSeconds = 25)
    if (-not $script:WinrmReady) { throw 'WinRM indisponible sur ce poste.' }
    $option = New-PSSessionOption -OpenTimeout ($TimeoutSeconds * 1000) -OperationTimeout ($TimeoutSeconds * 1000)
    $params = @{ ComputerName=$computer; ScriptBlock=$ScriptBlock; SessionOption=$option; ErrorAction='Stop' }
    if ($null -ne $cred) { $params['Credential'] = $cred; $params['Authentication'] = 'Default' }
    $lease=Enter-WCredentialAttempt -Context $Context -Channel Remote
    try{Assert-WCredentialAllowed -Context $Context -Channel Remote;return @(Invoke-Command @params)}catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}finally{Exit-WCredentialAttempt -Lease $lease}
}

$HKLM = [uint32]2147483650
function Get-RegString {
    param([uint32]$Hive,[string]$Key,[string]$Name)
    Assert-WCredentialAllowed -Context $Context -Channel Remote
    $session = $script:PrimarySession
    try{$r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'GetStringValue' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key; sValueName=$Name } -ErrorAction Stop}catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}
    if ([int]$r.ReturnValue -ne 0) { return '' }
    return [string]$r.sValue
}
function Get-RegDword {
    param([uint32]$Hive,[string]$Key,[string]$Name)
    Assert-WCredentialAllowed -Context $Context -Channel Remote
    $session = $script:PrimarySession
    try{$r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'GetDWORDValue' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key; sValueName=$Name } -ErrorAction Stop}catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}
    if ([int]$r.ReturnValue -ne 0) { return $null }
    return $r.uValue
}
function Get-RegSubKeys {
    param([uint32]$Hive,[string]$Key)
    Assert-WCredentialAllowed -Context $Context -Channel Remote
    $session = $script:PrimarySession
    try{$r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'EnumKey' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key } -ErrorAction Stop}catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}
    if ([int]$r.ReturnValue -ne 0) { return @() }
    return @($r.sNames)
}
function Get-RegSubKeyRead {
    # EnumKey with its return code: 0 = read, 2 = key absent (nothing to list); any other code (5 = access denied)
    # means the key was not read and must never be reported as empty.
    param([uint32]$Hive,[string]$Key)
    Assert-WCredentialAllowed -Context $Context -Channel Remote
    $session = $script:PrimarySession
    try{$r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'EnumKey' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key } -ErrorAction Stop}catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}
    return [pscustomobject]@{ Code=[int]$r.ReturnValue; Names=@(@($r.sNames) | Where-Object { $null -ne $_ }) }
}
function Get-RegMultiString {
    # REG_MULTI_SZ read by StdRegProv; $null when the value is absent or not readable.
    param([uint32]$Hive,[string]$Key,[string]$Name)
    Assert-WCredentialAllowed -Context $Context -Channel Remote
    $session = $script:PrimarySession
    try{$r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'GetMultiStringValue' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key; sValueName=$Name } -ErrorAction Stop}catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}
    if ([int]$r.ReturnValue -ne 0) { return $null }
    $values = @(@($r.sValue) | Where-Object { $null -ne $_ } | ForEach-Object { [string]$_ })
    return ,([string[]]$values)
}
function Get-RegBinary {
    # REG_BINARY read by StdRegProv; $null when the value is absent or not readable.
    param([uint32]$Hive,[string]$Key,[string]$Name)
    Assert-WCredentialAllowed -Context $Context -Channel Remote
    $session = $script:PrimarySession
    try{$r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'GetBinaryValue' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key; sValueName=$Name } -ErrorAction Stop}catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}
    if (([int]$r.ReturnValue -ne 0) -or ($null -eq $r.uValue)) { return $null }
    return ,([byte[]]@($r.uValue))
}
function Test-RegKey {
    param([uint32]$Hive,[string]$Key)
    try {
        $session = $script:PrimarySession
        $r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'EnumKey' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key } -ErrorAction Stop
        return ([int]$r.ReturnValue -eq 0)
    }
    catch { return $false }
}

# ---------------------------------------------------------------------
# Sonde des ports. Elle determine le transport principal et evite
# d attendre le delai complet d une session sur un poste injoignable.
# ---------------------------------------------------------------------
$portMap = @(
    @{ Port=135;  Label='RPC / DCOM' },
    @{ Port=5985; Label='WinRM HTTP' },
    @{ Port=5986; Label='WinRM HTTPS' },
    @{ Port=445;  Label='SMB' },
    @{ Port=3389; Label='Bureau a distance' }
)
$openPorts = @{}
$probeWatch = [System.Diagnostics.Stopwatch]::StartNew()
foreach ($entry in $portMap) {
    $isOpen = $false
    try { $isOpen = Test-WTcpPort $computer ([int]$entry.Port) 1800 } catch { }
    $openPorts[[int]$entry.Port] = $isOpen
    $state = 'ferme ou filtre'
    if ($isOpen) { $state = 'ouvert' }
    Add-Item 'Joignabilite' ([string]$entry.Label + ' (' + [string]$entry.Port + ')') $state 'Sonde TCP'
}
$probeWatch.Stop()
$dcomOpen = [bool]$openPorts[135]
$winrmOpen = ([bool]$openPorts[5985] -or [bool]$openPorts[5986])
$script:WinrmReady = $winrmOpen

if (-not $dcomOpen -and -not $winrmOpen) {
    Add-Access 'Joignabilite' 'INJOIGNABLE' 'Ni RPC 135 ni WinRM 5985/5986 ne repondent. Fallback PsExec puis tache planifiee.' ([int]$probeWatch.ElapsedMilliseconds) @($rows).Count
    $fallback=Invoke-InventoryTaskFallback 'Ni DCOM ni WinRM disponibles.'
    $totalWatch.Stop(); $fallback.DurationMs=[long]$totalWatch.ElapsedMilliseconds
    return $fallback
}
Add-Access 'Joignabilite' 'OK' ('Sonde TCP terminee. DCOM ouvert : ' + $dcomOpen + '. WinRM ouvert : ' + $winrmOpen + '.') ([int]$probeWatch.ElapsedMilliseconds) @($rows).Count

try {
    $sessionWatch = [System.Diagnostics.Stopwatch]::StartNew()
    $order = @()
    if ($dcomOpen) { $order += @{ Protocol='Dcom'; Label='DCOM' } }
    if ($winrmOpen) { $order += @{ Protocol='Wsman'; Label='WinRM' } }
    if ([bool]$Payload.PreferWinrm -and $winrmOpen) {
        $order = @(@{ Protocol='Wsman'; Label='WinRM' }) + @($order | Where-Object { [string]$_.Protocol -ne 'Wsman' })
    }
    $lastError = ''
    foreach ($candidate in $order) {
        try {
            $script:PrimarySession = New-InventorySession ([string]$candidate.Protocol) 18
            $script:PrimaryLabel = [string]$candidate.Label
            if ($script:PrimaryLabel -eq 'DCOM') { $script:AltLabel = 'WinRM' } else { $script:AltLabel = 'DCOM' }
            break
        }
        catch { $lastError = [string]$_.Exception.Message }
    }
    $sessionWatch.Stop()
    if ($null -eq $script:PrimarySession) {
        Add-Access 'Connexion CIM' (Get-FailureStatus $lastError) ('Aucun transport classique utilisable. Dernier message : ' + $lastError) ([int]$sessionWatch.ElapsedMilliseconds) 0
        $fallback=Invoke-InventoryTaskFallback $lastError
        $totalWatch.Stop(); $fallback.DurationMs=[long]$totalWatch.ElapsedMilliseconds
        return $fallback
    }
    $identity = 'session Windows du poste DOMENIA'
    if ($null -ne $cred) { $identity = [string]$cred.UserName }
    Add-Access 'Connexion CIM' 'OK' ('Transport principal ' + $script:PrimaryLabel + ', identite ' + $identity + '.') ([int]$sessionWatch.ElapsedMilliseconds) 0

    Invoke-Collector 'Systeme' {
        foreach ($cs in (Get-Cim 'Win32_ComputerSystem')) {
            Add-Item 'Systeme' 'Nom' $cs.Name 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Domaine' $cs.Domain 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Fabricant' $cs.Manufacturer 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Modele' $cs.Model 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Memoire physique totale' (Format-Size $cs.TotalPhysicalMemory) 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Processeurs logiques' $cs.NumberOfLogicalProcessors 'Win32_ComputerSystem'
            try { if ([int]$cs.NumberOfLogicalProcessors -gt 0) { $metrics.LogicalProcessors = [int]$cs.NumberOfLogicalProcessors } } catch { }
            Add-Item 'Systeme' 'Utilisateur connecte' $cs.UserName 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Role dans le domaine' $cs.DomainRole 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Type de systeme' $cs.SystemType 'Win32_ComputerSystem'
            Add-Item 'Systeme' 'Demarrage PXE ou etat' $cs.BootupState 'Win32_ComputerSystem'
        }
        foreach ($se in (Get-Cim 'Win32_SystemEnclosure')) {
            Add-Item 'Systeme' 'Numero de serie chassis' $se.SerialNumber 'Win32_SystemEnclosure'
            Add-Item 'Systeme' 'Type de chassis' (@($se.ChassisTypes) -join ', ') 'Win32_SystemEnclosure'
        }
        foreach ($cp in (Get-Cim 'Win32_ComputerSystemProduct')) {
            Add-Item 'Systeme' 'Identifiant materiel UUID' $cp.UUID 'Win32_ComputerSystemProduct'
            Add-Item 'Systeme' 'Reference produit' $cp.Name 'Win32_ComputerSystemProduct'
        }
    }

    Invoke-Collector 'BIOS et firmware' {
        foreach ($b in (Get-Cim 'Win32_BIOS')) {
            Add-Item 'BIOS et firmware' 'Fabricant' $b.Manufacturer 'Win32_BIOS'
            Add-Item 'BIOS et firmware' 'Version' (@($b.BIOSVersion) -join ' / ') 'Win32_BIOS'
            Add-Item 'BIOS et firmware' 'Version SMBIOS' $b.SMBIOSBIOSVersion 'Win32_BIOS'
            Add-Item 'BIOS et firmware' 'Date' (Get-CimDate $b.ReleaseDate) 'Win32_BIOS'
            Add-Item 'BIOS et firmware' 'Numero de serie' $b.SerialNumber 'Win32_BIOS'
        }
        # Point 99: UEFISecureBootEnabled is a DWORD written by Windows at boot; it is read, never inferred.
        $secureBoot = $null
        try { $secureBoot = Get-RegDword $HKLM 'SYSTEM\CurrentControlSet\Control\SecureBoot\State' 'UEFISecureBootEnabled' } catch { }
        if ($null -eq $secureBoot) {
            $present = Test-RegKey $HKLM 'SYSTEM\CurrentControlSet\Control\SecureBoot\State'
            $label = 'Non expose (BIOS herite ou systeme sans Secure Boot)'
            if ($present) { $label = 'Cle presente, valeur non lisible' }
            Add-Item 'BIOS et firmware' 'Secure Boot' $label 'Registre SecureBoot\State'
        }
        else {
            $label = 'Desactive'
            if ([int]$secureBoot -eq 1) { $label = 'Active' }
            Add-Item 'BIOS et firmware' 'Secure Boot' $label 'Registre SecureBoot\State'
        }
        $firmware = 'BIOS herite'
        try {
            $pe = Get-RegString $HKLM 'SYSTEM\CurrentControlSet\Control' 'PEFirmwareType'
            if ($pe -eq '2') { $firmware = 'UEFI' }
        }
        catch { $firmware = 'Non determine' }
        Add-Item 'BIOS et firmware' 'Type de firmware' $firmware 'Registre Control'
    }

    Invoke-Collector 'Carte mere' {
        foreach ($bb in (Get-Cim 'Win32_BaseBoard')) {
            Add-Item 'Carte mere' 'Fabricant' $bb.Manufacturer 'Win32_BaseBoard'
            Add-Item 'Carte mere' 'Produit' $bb.Product 'Win32_BaseBoard'
            Add-Item 'Carte mere' 'Numero de serie' $bb.SerialNumber 'Win32_BaseBoard'
        }
    }

    Invoke-Collector 'Processeur' {
        $index = 0
        foreach ($cpu in (Get-Cim 'Win32_Processor')) {
            $index++
            $prefix = 'CPU ' + $index
            Add-Item 'Processeur' ($prefix + ' modele') $cpu.Name 'Win32_Processor'
            Add-Item 'Processeur' ($prefix + ' coeurs') $cpu.NumberOfCores 'Win32_Processor'
            Add-Item 'Processeur' ($prefix + ' processeurs logiques') $cpu.NumberOfLogicalProcessors 'Win32_Processor'
            Add-Item 'Processeur' ($prefix + ' frequence max MHz') $cpu.MaxClockSpeed 'Win32_Processor'
            Add-Item 'Processeur' ($prefix + ' charge actuelle %') $cpu.LoadPercentage 'Win32_Processor'
            try { if ($null -ne $cpu.LoadPercentage) { $metrics.CpuLoad = [Math]::Max([double]$metrics.CpuLoad,[double]$cpu.LoadPercentage) } } catch { }
            Add-Item 'Processeur' ($prefix + ' virtualisation firmware') $cpu.VirtualizationFirmwareEnabled 'Win32_Processor'
        }
    }

    Invoke-Collector 'Memoire' {
        $total = 0
        $index = 0
        foreach ($m in (Get-Cim 'Win32_PhysicalMemory')) {
            $index++
            try { $total = $total + [double]$m.Capacity } catch { }
            $label = 'Barrette ' + $index
            $slot = [string]$m.DeviceLocator
            $size = Format-Size $m.Capacity
            $speed = [string]$m.Speed
            $value = $size + ' a ' + $speed + ' MHz, emplacement ' + $slot
            Add-Item 'Memoire' $label $value 'Win32_PhysicalMemory'
        }
        if ($index -gt 0) { Add-Item 'Memoire' 'Total installe' (Format-Size $total) 'Win32_PhysicalMemory'; $metrics.MemoryTotal = [double]$total; $metrics.MemorySource = 'Barrettes' }
        $metrics.MemoryModules = $index
        # Point 81: slots and firmware maximum from the SMBIOS memory arrays; a missing table leaves them unknown.
        # Only system memory arrays (Use 3) count: a video, flash or NVRAM array declares no RAM slot.
        try {
            $slots = 0; $maximum = 0.0; $slotsKnown = $true; $maximumKnown = $true; $arrays = 0
            foreach ($array in (Get-Cim 'Win32_PhysicalMemoryArray')) {
                if (($null -ne $array.Use) -and ([int]$array.Use -ne 3)) { continue }
                $arrays++
                if (($null -eq $array.MemoryDevices) -or ([int]$array.MemoryDevices -le 0)) { $slotsKnown = $false } else { $slots += [int]$array.MemoryDevices }
                if (($null -eq $array.MaxCapacityEx) -or ([double]$array.MaxCapacityEx -le 0)) { $maximumKnown = $false } else { $maximum += [double]$array.MaxCapacityEx * 1024 }
            }
            if (($arrays -gt 0) -and $slotsKnown) { Add-Item 'Memoire' 'Emplacements' ([string]$slots + ' emplacement(s), ' + [string]$index + ' occupe(s)') 'Win32_PhysicalMemoryArray'; $metrics.MemorySlots = $slots }
            if (($arrays -gt 0) -and $maximumKnown) { Add-Item 'Memoire' 'Capacite maximale declaree' (Format-Size $maximum) 'Win32_PhysicalMemoryArray' }
        } catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw} }
        foreach ($os in (Get-Cim 'Win32_OperatingSystem')) {
            Add-Item 'Memoire' 'Memoire libre' (Format-Size ([double]$os.FreePhysicalMemory * 1024)) 'Win32_OperatingSystem'
            Add-Item 'Memoire' 'Memoire visible par Windows' (Format-Size ([double]$os.TotalVisibleMemorySize * 1024)) 'Win32_OperatingSystem'
            try { $metrics.MemoryFree = [double]$os.FreePhysicalMemory * 1024 } catch { }
            # Virtual machines expose no memory module: the visible memory of the system gives the total, and says so.
            if ($metrics.MemoryTotal -le 0) { try { $metrics.MemoryTotal = [double]$os.TotalVisibleMemorySize * 1024; $metrics.MemorySource = 'Visible' } catch { } }
        }
        foreach ($pf in (Get-Cim 'Win32_PageFileUsage')) {
            $value = 'taille ' + [string]$pf.AllocatedBaseSize + ' Mo, pic ' + [string]$pf.PeakUsage + ' Mo'
            Add-Item 'Memoire' ('Fichier d echange ' + [string]$pf.Name) $value 'Win32_PageFileUsage'
        }
    }

    Invoke-Collector 'Systeme d exploitation' {
        foreach ($os in (Get-Cim 'Win32_OperatingSystem')) {
            Add-Item 'Systeme d exploitation' 'Nom' $os.Caption 'Win32_OperatingSystem'
            Add-Item 'Systeme d exploitation' 'Version' $os.Version 'Win32_OperatingSystem'
            Add-Item 'Systeme d exploitation' 'Build' $os.BuildNumber 'Win32_OperatingSystem'
            Add-Item 'Systeme d exploitation' 'Architecture' $os.OSArchitecture 'Win32_OperatingSystem'
            Add-Item 'Systeme d exploitation' 'Installe le' (Get-CimDate $os.InstallDate) 'Win32_OperatingSystem'
            Add-Item 'Systeme d exploitation' 'Dernier demarrage' (Get-CimDate $os.LastBootUpTime) 'Win32_OperatingSystem'
            try { $metrics.LastBoot = ([datetime]$os.LastBootUpTime).ToString('o') } catch { }
            # Clock offset of the workstation (Kerberos refuses more than 5 minutes); includes the read latency.
            # CO-09: measured against the connected domain controller (currentTime of its RootDSE, read during this
            # requested inventory only). Both offsets are taken against this computer's clock, so its own drift cancels.
            try {
                $workstationOffset = (([datetime]$os.LocalDateTime).ToUniversalTime() - (Get-Date).ToUniversalTime()).TotalSeconds
                $metrics.ClockSkewSeconds = [Math]::Round($workstationOffset)
                $metrics.ClockReference = 'Poste'
                $controllerOffset = Get-InventoryControllerClockOffset
                if ($null -ne $controllerOffset) { $metrics.ClockSkewSeconds = [Math]::Round($workstationOffset - [double]$controllerOffset); $metrics.ClockReference = 'Controleur' }
            } catch { }
            try {
                $uptime = (Get-Date) - [datetime]$os.LastBootUpTime
                $days = [int]$uptime.Days
                $hours = [int]$uptime.Hours
                $minutes = [int]$uptime.Minutes
                Add-Item 'Systeme d exploitation' 'Duree de fonctionnement' ('' + $days + ' j ' + $hours + ' h ' + $minutes + ' min') 'Win32_OperatingSystem'
            }
            catch { }
            Add-Item 'Systeme d exploitation' 'Repertoire Windows' $os.WindowsDirectory 'Win32_OperatingSystem'
            Add-Item 'Systeme d exploitation' 'Langue' $os.OSLanguage 'Win32_OperatingSystem'
        }
        $release = ''
        try { $release = Get-RegString $HKLM 'SOFTWARE\Microsoft\Windows NT\CurrentVersion' 'DisplayVersion' } catch { }
        if (-not [string]::IsNullOrWhiteSpace($release)) { Add-Item 'Systeme d exploitation' 'Version commerciale' $release 'Registre CurrentVersion' }
        $ubr = $null
        try { $ubr = Get-RegDword $HKLM 'SOFTWARE\Microsoft\Windows NT\CurrentVersion' 'UBR' } catch { }
        if ($null -ne $ubr) { Add-Item 'Systeme d exploitation' 'Revision de build' $ubr 'Registre CurrentVersion' }
        foreach ($tz in (Get-Cim 'Win32_TimeZone')) {
            Add-Item 'Systeme d exploitation' 'Fuseau horaire' $tz.Caption 'Win32_TimeZone'
        }
    }

    Invoke-Collector 'Appartenance et site' {
        $domain = ''
        try { $domain = Get-RegString $HKLM 'SYSTEM\CurrentControlSet\Services\Tcpip\Parameters' 'Domain' } catch { }
        Add-Item 'Appartenance et site' 'Suffixe DNS principal' $domain 'Registre Tcpip'
        $site = ''
        try { $site = Get-RegString $HKLM 'SYSTEM\CurrentControlSet\Services\Netlogon\Parameters' 'DynamicSiteName' } catch { }
        if ([string]::IsNullOrWhiteSpace($site)) {
            try { $site = Get-RegString $HKLM 'SYSTEM\CurrentControlSet\Services\Netlogon\Parameters' 'SiteName' } catch { }
        }
        Add-Item 'Appartenance et site' 'Site Active Directory' $site 'Registre Netlogon'
        $proxy = ''
        try { $proxy = Get-RegString $HKLM 'SOFTWARE\Microsoft\Windows\CurrentVersion\Internet Settings' 'ProxyServer' } catch { }
        Add-Item 'Appartenance et site' 'Proxy machine' $proxy 'Registre Internet Settings'
    }

    Invoke-Collector 'Disques logiques' {
        foreach ($d in (Get-Cim 'Win32_LogicalDisk' 'root\cimv2' 'DriveType=3')) {
            $free = 0.0
            $size = 0.0
            try { $free = [double]$d.FreeSpace } catch { }
            try { $size = [double]$d.Size } catch { }
            $pct = 0
            if ($size -gt 0) { $pct = [Math]::Round(100.0 * $free / $size,1) }
            $value = (Format-Size $size) + ' dont ' + (Format-Size $free) + ' libres (' + $pct + ' %)'
            $label = [string]$d.DeviceID + ' ' + [string]$d.VolumeName
            Add-Item 'Disques logiques' $label $value 'Win32_LogicalDisk'
            [void]$metrics.Disks.Add([pscustomobject]@{ Name=[string]$d.DeviceID; Label=[string]$d.VolumeName; Size=$size; Free=$free })
            if ($pct -lt 10 -and $size -gt 0) { Add-Item 'Disques logiques' ($label + ' alerte') 'Espace libre inferieur a 10 pour cent' 'Win32_LogicalDisk' }
        }
    }

    Invoke-Collector 'Disques physiques' {
        $index = 0
        foreach ($d in (Get-Cim 'Win32_DiskDrive')) {
            $index++
            $label = 'Disque ' + $index
            $value = [string]$d.Model + ', ' + (Format-Size $d.Size) + ', interface ' + [string]$d.InterfaceType
            Add-Item 'Disques physiques' $label $value 'Win32_DiskDrive'
            Add-Item 'Disques physiques' ($label + ' numero de serie') $d.SerialNumber 'Win32_DiskDrive'
            Add-Item 'Disques physiques' ($label + ' etat SMART') $d.Status 'Win32_DiskDrive'
        }
        try {
            foreach ($pd in (Get-Cim 'MSFT_PhysicalDisk' 'root\Microsoft\Windows\Storage')) {
                $media = 'Type non precise'
                if ([int]$pd.MediaType -eq 3) { $media = 'HDD' }
                elseif ([int]$pd.MediaType -eq 4) { $media = 'SSD' }
                # Point 83: only the codes 0, 1 and 2 are states; an absent or unknown code is never 'Sain'.
                $health = 'inconnu'
                if ($null -ne $pd.HealthStatus) {
                    if ([int]$pd.HealthStatus -eq 0) { $health = 'Sain' }
                    elseif ([int]$pd.HealthStatus -eq 1) { $health = 'Avertissement' }
                    elseif ([int]$pd.HealthStatus -eq 2) { $health = 'Defaillant' }
                    else { $health = 'inconnu (code ' + [string]$pd.HealthStatus + ')' }
                }
                Add-Item 'Disques physiques' ('Support ' + [string]$pd.DeviceId) ($media + ', etat ' + $health + ' selon le pilote') 'MSFT_PhysicalDisk'
            }
        }
        catch { }
    }

    Invoke-Collector 'BitLocker' {
        foreach ($v in (Get-Cim 'Win32_EncryptableVolume' 'root\cimv2\Security\MicrosoftVolumeEncryption')) {
            $protection = 'Desactive'
            if ([int]$v.ProtectionStatus -eq 1) { $protection = 'Active' }
            elseif ([int]$v.ProtectionStatus -eq 2) { $protection = 'Inconnu' }
            $label = 'Volume ' + [string]$v.DriveLetter
            Add-Item 'BitLocker' $label ('Protection ' + $protection) 'Win32_EncryptableVolume'
            Add-Item 'BitLocker' ($label + ' methode') $v.EncryptionMethod 'Win32_EncryptableVolume'
            # Point 99: encrypted and protected are two facts; an encrypted volume may have its protection suspended.
            $conversion = 'Non renseigne'
            if ($null -ne $v.ConversionStatus) {
                switch ([int]$v.ConversionStatus) { 0 { $conversion = 'Non chiffre' } 1 { $conversion = 'Entierement chiffre' } 2 { $conversion = 'Chiffrement en cours' } 3 { $conversion = 'Dechiffrement en cours' } 4 { $conversion = 'Chiffrement en pause' } 5 { $conversion = 'Dechiffrement en pause' } default { $conversion = 'Code ' + [string]$v.ConversionStatus } }
            }
            Add-Item 'BitLocker' ($label + ' chiffrement') $conversion 'Win32_EncryptableVolume'
        }
    }

    Invoke-Collector 'TPM' {
        foreach ($t in (Get-Cim 'Win32_Tpm' 'root\cimv2\Security\MicrosoftTpm')) {
            $enabled = 'Non'
            if ([bool]$t.IsEnabled_InitialValue) { $enabled = 'Oui' }
            $activated = 'Non'
            if ([bool]$t.IsActivated_InitialValue) { $activated = 'Oui' }
            Add-Item 'TPM' 'Present' 'Oui' 'Win32_Tpm'
            Add-Item 'TPM' 'Active' $enabled 'Win32_Tpm'
            Add-Item 'TPM' 'Operationnel' $activated 'Win32_Tpm'
            Add-Item 'TPM' 'Version specification' $t.SpecVersion 'Win32_Tpm'
            Add-Item 'TPM' 'Fabricant' $t.ManufacturerIdTxt 'Win32_Tpm'
        }
    }

    Invoke-Collector 'Reseau' {
        foreach ($n in (Get-Cim 'Win32_NetworkAdapterConfiguration' 'root\cimv2' 'IPEnabled=True')) {
            $label = [string]$n.Description
            Add-Item 'Reseau' ($label + ' adresses IP') (@($n.IPAddress) -join ', ') 'Win32_NetworkAdapterConfiguration'
            Add-Item 'Reseau' ($label + ' masque') (@($n.IPSubnet) -join ', ') 'Win32_NetworkAdapterConfiguration'
            Add-Item 'Reseau' ($label + ' passerelle') (@($n.DefaultIPGateway) -join ', ') 'Win32_NetworkAdapterConfiguration'
            Add-Item 'Reseau' ($label + ' DNS') (@($n.DNSServerSearchOrder) -join ', ') 'Win32_NetworkAdapterConfiguration'
            Add-Item 'Reseau' ($label + ' MAC') $n.MACAddress 'Win32_NetworkAdapterConfiguration'
            $dhcp = 'Non'
            if ([bool]$n.DHCPEnabled) { $dhcp = 'Oui' }
            Add-Item 'Reseau' ($label + ' DHCP') $dhcp 'Win32_NetworkAdapterConfiguration'
            if ([bool]$n.DHCPEnabled) {
                Add-Item 'Reseau' ($label + ' serveur DHCP') $n.DHCPServer 'Win32_NetworkAdapterConfiguration'
                Add-Item 'Reseau' ($label + ' bail obtenu') (Get-CimDate $n.DHCPLeaseObtained) 'Win32_NetworkAdapterConfiguration'
                Add-Item 'Reseau' ($label + ' bail expire') (Get-CimDate $n.DHCPLeaseExpires) 'Win32_NetworkAdapterConfiguration'
            }
        }
    }

    Invoke-Collector 'Cartes reseau' {
        foreach ($a in (Get-Cim 'Win32_NetworkAdapter' 'root\cimv2' 'PhysicalAdapter=True')) {
            $speed = ''
            try { if ([double]$a.Speed -gt 0) { $speed = ', ' + [Math]::Round([double]$a.Speed / 1000000.0,0) + ' Mb/s' } } catch { }
            Add-Item 'Cartes reseau' $a.Name ([string]$a.NetConnectionStatus + $speed) 'Win32_NetworkAdapter'
        }
    }

    Invoke-Collector 'Pare-feu' {
        # CO-12: one effective state per profile; the group policy key wins over the local key.
        foreach ($profile in @(
            @{ Policy='SOFTWARE\Policies\Microsoft\WindowsFirewall\DomainProfile'; Local='SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy\DomainProfile'; Label='Profil domaine' },
            @{ Policy='SOFTWARE\Policies\Microsoft\WindowsFirewall\StandardProfile'; Local='SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy\StandardProfile'; Label='Profil prive' },
            @{ Policy='SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile'; Local='SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy\PublicProfile'; Label='Profil public' }
        )) {
            $policyValue = $null; $localValue = $null
            try { $policyValue = Get-RegDword $HKLM ([string]$profile.Policy) 'EnableFirewall' } catch { }
            try { $localValue = Get-RegDword $HKLM ([string]$profile.Local) 'EnableFirewall' } catch { }
            $value = $policyValue; $origin = 'strategie'
            if ($null -eq $value) { $value = $localValue; $origin = 'local' }
            if ($null -eq $value) { continue }
            $state = 'Desactive'
            if ([int]$value -eq 1) { $state = 'Active' }
            Add-Item 'Pare-feu' ([string]$profile.Label) ($state + ' (' + $origin + ')') 'Registre FirewallPolicy'
            if (($null -ne $policyValue) -and ($null -ne $localValue) -and ([int]$policyValue -ne [int]$localValue)) {
                $localText = 'desactive'
                if ([int]$localValue -eq 1) { $localText = 'active' }
                Add-Item 'Pare-feu' ([string]$profile.Label + ' reglage local') ('Reglage local ' + $localText + ', remplace par la strategie') 'Registre SharedAccess FirewallPolicy'
            }
        }
        # Point 98: the category of each active connection names the profile Windows applies to it.
        try {
            foreach ($connection in (Get-Cim 'MSFT_NetConnectionProfile' 'root\StandardCimv2')) {
                $category = 'Categorie ' + [string]$connection.NetworkCategory
                if (([string]$connection.NetworkCategory -eq '2') -or ([string]$connection.NetworkCategory -eq 'DomainAuthenticated')) { $category = 'Domaine' }
                elseif (([string]$connection.NetworkCategory -eq '1') -or ([string]$connection.NetworkCategory -eq 'Private')) { $category = 'Prive' }
                elseif (([string]$connection.NetworkCategory -eq '0') -or ([string]$connection.NetworkCategory -eq 'Public')) { $category = 'Public' }
                Add-Item 'Pare-feu' ('Profil applique a ' + [string]$connection.InterfaceAlias) ($category + ' (reseau ' + [string]$connection.Name + ')') 'MSFT_NetConnectionProfile'
            }
        } catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw} }
    }

    Invoke-Collector 'Antivirus' {
        foreach ($av in (Get-Cim 'AntiVirusProduct' 'root\SecurityCenter2')) {
            $state = 0
            try { $state = [int]$av.productState } catch { }
            $hex = '{0:X6}' -f $state
            $enabled = 'Inconnu'
            $updated = 'Inconnu'
            try {
                $mid = [Convert]::ToInt32($hex.Substring(2,2),16)
                $low = [Convert]::ToInt32($hex.Substring(4,2),16)
                if ($mid -ge 16) { $enabled = 'Actif' } else { $enabled = 'Inactif' }
                if ($low -eq 0) { $updated = 'A jour' } else { $updated = 'Signatures obsoletes' }
            }
            catch { }
            Add-Item 'Antivirus' $av.displayName ($enabled + ', ' + $updated) 'root\SecurityCenter2'
        }
    }

    Invoke-Collector 'Correctifs' {
        $all = @(Get-Cim 'Win32_QuickFixEngineering')
        Add-Item 'Correctifs' 'Nombre total' (@($all).Count) 'Win32_QuickFixEngineering'
        foreach ($h in $all) {
            $installed = [datetime]::MinValue
            if ([datetime]::TryParse([string]$h.InstalledOn,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::None,[ref]$installed)) { [void]$metrics.Hotfixes.Add($installed.ToString('yyyy-MM-dd')) }
        }
        foreach ($h in ($all | Sort-Object -Property InstalledOn -Descending | Select-Object -First 15)) {
            Add-Item 'Correctifs' $h.HotFixID ([string]$h.Description + ' installe le ' + (Get-CimDate $h.InstalledOn)) 'Win32_QuickFixEngineering'
        }
    } 12000

    Invoke-Collector 'Windows Update' {
        foreach ($entry in @(
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\Results\Detect'; Label='Derniere recherche' },
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\Results\Download'; Label='Dernier telechargement' },
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\Results\Install'; Label='Derniere installation' }
        )) {
            $value = ''
            try { $value = Get-RegString $HKLM ([string]$entry.Key) 'LastSuccessTime' } catch { }
            if (-not [string]::IsNullOrWhiteSpace($value)) { Add-Item 'Windows Update' ([string]$entry.Label) $value 'Registre WindowsUpdate' }
        }
        $wsus = ''
        try { $wsus = Get-RegString $HKLM 'SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate' 'WUServer' } catch { }
        if (-not [string]::IsNullOrWhiteSpace($wsus)) { Add-Item 'Windows Update' 'Serveur WSUS' $wsus 'Registre WindowsUpdate' }
        # Point 92: a WSUS address without UseWUServer=1 is not used by the update client.
        $useWsus = $null
        try { $useWsus = Get-RegDword $HKLM 'SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU' 'UseWUServer' } catch { }
        if ($null -ne $useWsus) { Add-Item 'Windows Update' 'Strategie WSUS appliquee' $(if ([int]$useWsus -eq 1) { 'Oui' } else { 'Non' }) 'Registre WindowsUpdate\AU' }
    }

    Invoke-Collector 'Logiciels installes' {
        $seen = @{}
        $names = New-Object Collections.ArrayList
        $source = ''

        # 1. Inventaire SCCM : une seule requete.
        try {
            foreach ($p in (Get-Cim 'Win32Reg_AddRemovePrograms')) {
                $display = [string]$p.DisplayName
                if ([string]::IsNullOrWhiteSpace($display)) { continue }
                $key = $display.ToLowerInvariant()
                if ($seen.ContainsKey($key)) { continue }
                $seen[$key] = $true
                [void]$names.Add([pscustomobject]@{ Name=$display; Version=[string]$p.Version })
            }
            if (@($names).Count -gt 0) { $source = 'Win32Reg_AddRemovePrograms' }
        }
        catch { }

        # 2. WinRM : un aller-retour unique remplace des centaines d appels.
        if ([string]::IsNullOrWhiteSpace($source) -and $script:WinrmReady) {
            try {
                $remote = Invoke-Remote -TimeoutSeconds 30 -ScriptBlock {
                    $paths = @(
                        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
                        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
                    )
                    Get-ItemProperty -Path $paths -ErrorAction SilentlyContinue |
                        Where-Object { $_.DisplayName } |
                        Select-Object DisplayName,DisplayVersion,Publisher,InstallDate
                }
                foreach ($p in @($remote)) {
                    $display = [string]$p.DisplayName
                    if ([string]::IsNullOrWhiteSpace($display)) { continue }
                    $key = $display.ToLowerInvariant()
                    if ($seen.ContainsKey($key)) { continue }
                    $seen[$key] = $true
                    [void]$names.Add([pscustomobject]@{ Name=$display; Version=[string]$p.DisplayVersion })
                }
                if (@($names).Count -gt 0) { $source = 'Registre via WinRM' ; $script:CollectorTransport = 'WinRM (un seul aller-retour)' }
            }
            catch { }
        }

        # 3. Repli registre par appels unitaires, borne en cles et en temps.
        if ([string]::IsNullOrWhiteSpace($source)) {
            $source = 'Registre Uninstall'
            $maxKeys = [Math]::Max(50,[int]$Payload.MaxSoftwareKeys)
            $scanned = 0
            $stopped = $false
            foreach ($base in @('SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall','SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall')) {
                if ($stopped) { break }
                $subKeys = @()
                try { $subKeys = Get-RegSubKeys $HKLM $base } catch { continue }
                foreach ($sub in $subKeys) {
                    if ($scanned -ge $maxKeys) { Set-CollectorTruncated ('Lecture arretee apres ' + $maxKeys + ' cles de registre.'); $stopped = $true; break }
                    if (-not (Test-CollectorBudget)) { Set-CollectorTruncated ('Lecture arretee apres ' + $scanned + ' cles : budget de la source atteint.'); $stopped = $true; break }
                    $scanned++
                    $key = $base + '\' + [string]$sub
                    $display = ''
                    try { $display = Get-RegString $HKLM $key 'DisplayName' } catch { continue }
                    if ([string]::IsNullOrWhiteSpace($display)) { continue }
                    $dedupe = $display.ToLowerInvariant()
                    if ($seen.ContainsKey($dedupe)) { continue }
                    $seen[$dedupe] = $true
                    $version = ''
                    try { $version = Get-RegString $HKLM $key 'DisplayVersion' } catch { }
                    [void]$names.Add([pscustomobject]@{ Name=$display; Version=$version })
                }
            }
        }

        Add-Item 'Logiciels installes' 'Nombre detecte' (@($names).Count) $source
        foreach ($n in ($names.ToArray() | Sort-Object -Property Name)) { Add-Item 'Logiciels installes' $n.Name $n.Version $source }
    } 20000

    Invoke-Collector 'Demarrage automatique' {
        # Point 96: only the program of each entry leaves the worker; its arguments may hold a secret and are dropped.
        foreach ($s in (@(Get-Cim '' 'root\cimv2' '' 'SELECT Name,User,Location,Command FROM Win32_StartupCommand') | Select-Object -First 40)) {
            $program = Get-DomeniaCommandExecutable ([string]$s.Command)
            if (-not $program) { $program = 'programme non declare' }
            Add-Item 'Demarrage automatique' ([string]$s.Name + ' (' + [string]$s.User + ')') ($program + ' depuis ' + [string]$s.Location) 'Win32_StartupCommand (programme seul, arguments non conserves)'
        }
    }

    Invoke-Collector 'Services en defaut' {
        $allServices = @(Get-Cim 'Win32_Service')
        $stateByName = @{}
        foreach ($service in $allServices) { $stateByName[([string]$service.Name).ToLowerInvariant()] = [string]$service.State }
        $stopped = @($allServices | Where-Object { ([string]$_.StartMode -eq 'Auto') -and ([string]$_.State -eq 'Stopped') })
        foreach ($s in (@($stopped) | Select-Object -First 40)) {
            # Point 94: declared dependencies (registry DependOnService) and their state, read only.
            $dependencies = ''
            try {
                $depends = Get-RegMultiString $HKLM ('SYSTEM\CurrentControlSet\Services\' + [string]$s.Name) 'DependOnService'
                $parts = @(foreach ($name in @($depends | Select-Object -First 8)) { if ([string]::IsNullOrWhiteSpace($name)) { continue }; $state = $stateByName[([string]$name).ToLowerInvariant()]; if (-not $state) { $state = 'pilote ou groupe' }; [string]$name + ' (' + $state + ')' })
                if ($parts.Count) { $dependencies = ' Depend de : ' + ($parts -join ', ') + '.' }
            } catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw} }
            $exit = ''
            if (($null -ne $s.ExitCode) -and ([int]$s.ExitCode -ne 0) -and ([int]$s.ExitCode -ne 1077)) { $exit = ' Code de sortie ' + [string]$s.ExitCode + '.' }
            Add-Item 'Services en defaut' $s.DisplayName ('Demarrage automatique mais arrete.' + $exit + $dependencies + ' Nom : ' + [string]$s.Name) 'Win32_Service'
        }
        if (@($stopped).Count -eq 0) { Add-Item 'Services en defaut' 'Etat' 'Aucun service automatique arrete' 'Win32_Service' }
        # Distribution of all services for the dashboard ring, from the same read.
        foreach ($service in $allServices) {
            $key = if ([string]$service.StartMode -eq 'Disabled') { 'Desactives' } elseif ([string]$service.State -eq 'Running') { 'En cours' } elseif ([string]$service.StartMode -eq 'Auto') { 'Arretes (automatiques)' } else { 'Arretes (manuels)' }
            $metrics.Services[$key] = 1 + [int]$metrics.Services[$key]
        }
    }

    Invoke-Collector 'Peripheriques en erreur' {
        $bad = @(Get-Cim 'Win32_PnPEntity' 'root\cimv2' 'ConfigManagerErrorCode<>0')
        foreach ($d in (@($bad) | Select-Object -First 30)) {
            Add-Item 'Peripheriques en erreur' ([string]$d.Name) ('Code ' + [string]$d.ConfigManagerErrorCode + ', ' + [string]$d.DeviceID) 'Win32_PnPEntity'
        }
        if (@($bad).Count -eq 0) { Add-Item 'Peripheriques en erreur' 'Etat' 'Aucun peripherique en erreur' 'Win32_PnPEntity' }
    } 15000

    Invoke-Collector 'Affichage' {
        foreach ($g in (Get-Cim 'Win32_VideoController')) {
            $ram = Format-Size $g.AdapterRAM
            Add-Item 'Affichage' ([string]$g.Name) ($ram + ', pilote ' + [string]$g.DriverVersion + ', resolution ' + [string]$g.CurrentHorizontalResolution + 'x' + [string]$g.CurrentVerticalResolution) 'Win32_VideoController'
        }
        try {
            $index = 0
            foreach ($m in (Get-Cim 'WmiMonitorID' 'root\wmi')) {
                $index++
                $name = ''
                try { $name = -join ([char[]]@($m.UserFriendlyName | Where-Object { $_ -gt 0 })) } catch { }
                $serial = ''
                try { $serial = -join ([char[]]@($m.SerialNumberID | Where-Object { $_ -gt 0 })) } catch { }
                Add-Item 'Affichage' ('Ecran ' + $index) ($name + ', serie ' + $serial + ', annee ' + [string]$m.YearOfManufacture) 'WmiMonitorID'
            }
        }
        catch { }
    }

    Invoke-Collector 'Batterie' {
        $found = 0
        foreach ($b in (Get-Cim 'Win32_Battery')) {
            $found++
            Add-Item 'Batterie' ([string]$b.Name) ('Charge ' + [string]$b.EstimatedChargeRemaining + ' %, etat ' + [string]$b.BatteryStatus) 'Win32_Battery'
            try { if ($null -ne $b.EstimatedChargeRemaining) { $metrics.Battery = [double]$b.EstimatedChargeRemaining } } catch { }
        }
        if ($found -eq 0) { Add-Item 'Batterie' 'Etat' 'Aucune batterie : poste fixe ou alimentation secteur uniquement' 'Win32_Battery' }
    }

    Invoke-Collector 'Pilotes non signes' {
        $unsigned = @(Get-Cim 'Win32_PnPSignedDriver' 'root\cimv2' 'IsSigned=False')
        foreach ($d in (@($unsigned) | Select-Object -First 25)) {
            Add-Item 'Pilotes non signes' ([string]$d.DeviceName) ([string]$d.DriverProviderName + ' version ' + [string]$d.DriverVersion) 'Win32_PnPSignedDriver'
        }
        if (@($unsigned).Count -eq 0) { Add-Item 'Pilotes non signes' 'Etat' 'Tous les pilotes remontes sont signes' 'Win32_PnPSignedDriver' }
    } 20000

    Invoke-Collector 'Comptes et sessions' {
        foreach ($u in (Get-Cim 'Win32_UserAccount' 'root\cimv2' 'LocalAccount=True')) {
            $flags = New-Object Collections.ArrayList
            if ([bool]$u.Disabled) { [void]$flags.Add('desactive') } else { [void]$flags.Add('actif') }
            if ([bool]$u.Lockout) { [void]$flags.Add('verrouille') }
            if ([bool]$u.PasswordRequired) { [void]$flags.Add('mot de passe requis') }
            if ([bool]$u.PasswordExpires) { [void]$flags.Add('mot de passe expirable') }
            Add-Item 'Comptes et sessions' ('Compte local ' + [string]$u.Name) (@($flags) -join ', ') 'Win32_UserAccount'
        }
        foreach ($l in (@(Get-Cim 'Win32_LogonSession' 'root\cimv2' 'LogonType=2 OR LogonType=10') | Select-Object -First 20)) {
            $type = 'interactive'
            if ([int]$l.LogonType -eq 10) { $type = 'bureau a distance' }
            Add-Item 'Comptes et sessions' ('Session ' + [string]$l.LogonId) ($type + ' ouverte le ' + (Get-CimDate $l.StartTime)) 'Win32_LogonSession'
        }
    }

    Invoke-Collector 'Administrateurs locaux' {
        $group = @(Get-Cim 'Win32_Group' 'root\cimv2' 'LocalAccount=True AND SID="S-1-5-32-544"') | Select-Object -First 1
        if ($null -eq $group) { throw 'Groupe Administrateurs local introuvable.' }
        $groupName = [string]$group.Name
        $quote = [string][char]39
        $query = 'SELECT * FROM Win32_GroupUser WHERE GroupComponent="Win32_Group.Domain=' + $quote + $quote + [string]$computer + $quote + $quote + ',Name=' + $quote + $quote + $groupName + $quote + $quote + '"'
        $members = @(Get-Cim '' 'root\cimv2' '' $query)
        foreach ($m in $members) {
            $part = [string]$m.PartComponent
            $clean = $part
            try {
                $domainMatch = [regex]::Match($part,'Domain="([^"]+)"')
                $nameMatch = [regex]::Match($part,'Name="([^"]+)"')
                if ($domainMatch.Success -and $nameMatch.Success) { $clean = $domainMatch.Groups[1].Value + '\' + $nameMatch.Groups[1].Value }
            }
            catch { }
            Add-Item 'Administrateurs locaux' 'Membre' $clean 'Win32_GroupUser'
        }
        if (@($members).Count -eq 0) { Add-Item 'Administrateurs locaux' 'Etat' 'Aucun membre lisible' 'Win32_GroupUser' }
    }

    Invoke-Collector 'Partages' {
        foreach ($s in (Get-Cim 'Win32_Share')) {
            Add-Item 'Partages' $s.Name ([string]$s.Path + ' ' + [string]$s.Description) 'Win32_Share'
        }
    }

    Invoke-Collector 'Imprimantes' {
        foreach ($p in (@(Get-Cim 'Win32_Printer') | Select-Object -First 40)) {
            $default = ''
            if ([bool]$p.Default) { $default = ' (par defaut)' }
            Add-Item 'Imprimantes' $p.Name ([string]$p.PortName + ' ' + [string]$p.DriverName + $default) 'Win32_Printer'
        }
    }

    Invoke-Collector 'Redemarrage en attente' {
        # Point 93: one row per indicator with its source. Confirmed: servicing, Windows Update or a computer rename
        # waits for a restart. Partial: hints often left by installers, not an obligation on their own.
        $confirmed = New-Object Collections.ArrayList
        $partial = New-Object Collections.ArrayList
        $unread = 0
        foreach ($c in @(
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending'; Label='Maintenance des composants (CBS)'; Kind='Confirme' },
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired'; Label='Windows Update'; Kind='Confirme' },
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootInProgress'; Label='Maintenance CBS en cours'; Kind='Partiel' },
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\PackagesPending'; Label='Paquets CBS en attente'; Kind='Partiel' },
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\PostRebootReporting'; Label='Rapport Windows Update apres redemarrage'; Kind='Partiel' },
            @{ Key='SYSTEM\CurrentControlSet\Services\Netlogon\JoinDomain'; Label='Jonction au domaine en attente'; Kind='Partiel' }
        )) {
            $present = Test-RegKey $HKLM ([string]$c.Key)
            if ($present) { if ([string]$c.Kind -eq 'Confirme') { [void]$confirmed.Add([string]$c.Label) } else { [void]$partial.Add([string]$c.Label) } }
            Add-Item 'Redemarrage en attente' ([string]$c.Label) $(if ($present) { 'Present (' + $(if ([string]$c.Kind -eq 'Confirme') { 'obligation confirmee' } else { 'indice partiel' }) + ')' } else { 'Absent' }) ('Registre HKLM\' + [string]$c.Key)
        }
        $renames = $null
        try { $renames = Get-RegMultiString $HKLM 'SYSTEM\CurrentControlSet\Control\Session Manager' 'PendingFileRenameOperations' } catch { $unread++ }
        $operations = @(@($renames) | Where-Object { [string]$_ -like '\??\*' }).Count
        if ($operations -gt 0) { [void]$partial.Add('Renommages de fichiers en attente') }
        Add-Item 'Redemarrage en attente' 'Renommages de fichiers en attente' $(if ($operations -gt 0) { 'Present (indice partiel) : ' + [string]$operations + ' operation(s)' } elseif (($null -eq $renames) -and ($unread -gt 0)) { 'Non lu' } else { 'Absent' }) 'Registre Session Manager\PendingFileRenameOperations'
        $active = ''; $pendingName = ''
        try { $active = Get-RegString $HKLM 'SYSTEM\CurrentControlSet\Control\ComputerName\ActiveComputerName' 'ComputerName' } catch { }
        try { $pendingName = Get-RegString $HKLM 'SYSTEM\CurrentControlSet\Control\ComputerName\ComputerName' 'ComputerName' } catch { }
        if (($active) -and ($pendingName)) {
            $renamed = ($active -ine $pendingName)
            if ($renamed) { [void]$confirmed.Add('Renommage du poste') }
            Add-Item 'Redemarrage en attente' 'Renommage du poste' $(if ($renamed) { 'Present (obligation confirmee) : ' + $active + ' deviendra ' + $pendingName } else { 'Absent' }) 'Registre ComputerName'
        }
        else { Add-Item 'Redemarrage en attente' 'Renommage du poste' 'Non lu' 'Registre ComputerName' }
        $volatile = $null
        try { $volatile = Get-RegDword $HKLM 'SOFTWARE\Microsoft\Updates' 'UpdateExeVolatile' } catch { }
        if (($null -ne $volatile) -and ([int]$volatile -ne 0)) { [void]$partial.Add('Mise a jour en cours (UpdateExeVolatile)') }
        Add-Item 'Redemarrage en attente' 'Mise a jour en cours (UpdateExeVolatile)' $(if (($null -ne $volatile) -and ([int]$volatile -ne 0)) { 'Present (indice partiel)' } else { 'Absent' }) 'Registre Updates\UpdateExeVolatile'
        if (@($confirmed).Count -gt 0) { Add-Item 'Redemarrage en attente' 'Etat' ('Redemarrage requis : ' + (@($confirmed) -join ', ') + $(if (@($partial).Count) { ' ; indices partiels : ' + (@($partial) -join ', ') } else { '' })) 'Registre' }
        elseif (@($partial).Count -gt 0) { Add-Item 'Redemarrage en attente' 'Etat' ('Indices partiels seulement : ' + (@($partial) -join ', ')) 'Registre' }
        else { Add-Item 'Redemarrage en attente' 'Etat' 'Aucun redemarrage en attente' 'Registre' }
    }

    if ($deep) {
        Invoke-Collector 'Processus' {
            # Point 95: two reads of the same class over a bounded interval give the processor time used meanwhile.
            # The query projects times, sizes and names only: no command line or argument is read on the workstation.
            # The idle pseudo-process (PID 0) holds the unused processor time: it is never sampled as a consumer.
            $processQuery = 'SELECT ProcessId,Name,CreationDate,KernelModeTime,UserModeTime,WorkingSetSize FROM Win32_Process WHERE ProcessId <> 0'
            $sampleWatch = [System.Diagnostics.Stopwatch]::StartNew()
            $firstRead = @(Get-Cim '' 'root\cimv2' '' $processQuery)
            $firstMs = [long]$sampleWatch.ElapsedMilliseconds
            $intervalMs = 2000
            if ($null -ne $Payload.PSObject.Properties['ProcessSampleMs']) { $intervalMs = [Math]::Max(1000,[Math]::Min(5000,[int]$Payload.ProcessSampleMs)) }
            Start-Sleep -Milliseconds $intervalMs
            $secondRead = @(Get-Cim '' 'root\cimv2' '' $processQuery)
            $secondMs = [long]$sampleWatch.ElapsedMilliseconds
            $sampledUtc = [datetime]::UtcNow.ToString('o')
            $before = @{}
            foreach ($p in $firstRead) { try { $before[[string]$p.ProcessId] = [pscustomobject]@{ Time=([double]$p.KernelModeTime + [double]$p.UserModeTime); Created=[string]$p.CreationDate } } catch { } }
            $items = New-Object Collections.ArrayList
            foreach ($p in @($secondRead | Select-Object -First 600)) {
                if ([long]$p.ProcessId -eq 0) { continue }
                $previous = $before[[string]$p.ProcessId]
                $time = $null; try { $time = [double]$p.KernelModeTime + [double]$p.UserModeTime } catch { }
                [void]$items.Add([pscustomobject]@{ Pid=[long]$p.ProcessId; Name=[string]$p.Name; FirstTime=$(if (($null -ne $previous) -and ([string]$previous.Created -eq [string]$p.CreationDate)) { $previous.Time } else { $null }); SecondTime=$time; WorkingSet=$(try { [double]$p.WorkingSetSize } catch { $null }) })
            }
            $metrics.ProcessSample = [pscustomobject]@{ IntervalMs=($secondMs - $firstMs); SampledUtc=$sampledUtc; LogicalProcessors=[int]$metrics.LogicalProcessors; FirstCount=$firstRead.Count; SecondCount=$secondRead.Count; Truncated=($secondRead.Count -gt 600); Items=@($items) }
            Add-Item 'Processus' 'Mesure de charge' ('Deux lectures a ' + [string]($secondMs - $firstMs) + ' ms d intervalle, terminees le ' + (Get-CimDate ([datetime]::Now))) 'Win32_Process'
            foreach ($p in (@($secondRead) | Sort-Object WorkingSetSize -Descending | Select-Object -First 12)) {
                Add-Item 'Processus' ([string]$p.Name + ' (PID ' + [string]$p.ProcessId + ')') (Format-Size $p.WorkingSetSize) 'Win32_Process'
                try { [void]$metrics.Processes.Add([pscustomobject]@{ Name=[string]$p.Name; Mb=[Math]::Round([double]$p.WorkingSetSize / 1MB) }) } catch { }
            }
        } 20000

        Invoke-Collector 'Evenements systeme' {
            $since = (Get-Date).AddDays(-3)
            $stamp = $since.ToUniversalTime().ToString('yyyyMMddHHmmss') + '.000000+000'
            $query = 'SELECT * FROM Win32_NTLogEvent WHERE Logfile="System" AND EventType=1 AND TimeGenerated>="' + $stamp + '"'
            $events = @(Get-Cim '' 'root\cimv2' '' $query | Select-Object -First 15)
            foreach ($e in $events) {
                $msg = [string]$e.Message
                if ($msg.Length -gt 220) { $msg = $msg.Substring(0,220) + '...' }
                Add-Item 'Evenements systeme' ([string]$e.SourceName + ' ID ' + [string]$e.EventCode) ((Get-CimDate $e.TimeGenerated) + ' : ' + $msg) 'Win32_NTLogEvent'
            }
            if (@($events).Count -eq 0) { Add-Item 'Evenements systeme' 'Etat' 'Aucune erreur systeme sur 3 jours' 'Win32_NTLogEvent' }
        } 30000

        Invoke-Collector 'Taches planifiees' {
            # Point 96: author, last run, last result and missed runs of the non-Microsoft tasks, by the read-only
            # Get-ScheduledTaskInfo in the same WinRM round trip. Actions, arguments and principals are never read.
            # Without WinRM, or when its session fails for a reason other than the credential (listener or HTTP policy,
            # Kerberos or SPN, remoting error): the documented MSFT_ScheduledTask class, projected on its name, folder,
            # state and author through the CIM session, gives the inventory; the last start date comes from the Task
            # Scheduler registry cache (StdRegProv: Tree\<task> Id, then Tasks\{id} DynamicInfo, a binary value Microsoft
            # does not document). The Actions value, the arguments and the last result are not read this way.
            $readTasksByCim = {
                $cacheRoot = 'SOFTWARE\Microsoft\Windows NT\CurrentVersion\Schedule\TaskCache'
                $stateText = @{ '0'='Unknown'; '1'='Disabled'; '2'='Queued'; '3'='Ready'; '4'='Running' }
                $listed = @(Get-Cim '' 'root\Microsoft\Windows\TaskScheduler' '' 'SELECT TaskName,TaskPath,State,Author FROM MSFT_ScheduledTask' | Where-Object { ([string]$_.State -ne '1') -and ([string]$_.TaskPath -notlike '\Microsoft\*') } | Select-Object -First 40)
                $unread = 0
                foreach ($t in $listed) {
                    $author = [string]$t.Author; if ([string]::IsNullOrWhiteSpace($author)) { $author = 'non declare' }
                    $taskPath = [string]$t.TaskPath; $taskName = [string]$t.TaskName
                    $state = [string]$t.State; if ($stateText.ContainsKey($state)) { $state = [string]$stateText[$state] }
                    $run = 'non lu'
                    if (Test-CollectorBudget) {
                        try {
                            $taskId = Get-RegString $HKLM ($cacheRoot + '\Tree' + $taskPath.TrimEnd('\') + '\' + $taskName) 'Id'
                            if ($taskId -match '^\{[0-9A-Fa-f-]{36}\}$') {
                                $cache = ConvertFrom-DomeniaTaskCacheDynamicInfo (Get-RegBinary $HKLM ($cacheRoot + '\Tasks\' + $taskId) 'DynamicInfo')
                                if ([bool]$cache.Decoded) { if ([bool]$cache.NeverStarted) { $run = 'jamais' } else { $run = ([datetime]$cache.LastStartUtc).ToLocalTime().ToString('dd/MM/yyyy HH:mm') } }
                            }
                        } catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw} }
                    }
                    if ($run -eq 'non lu') { $unread++ }
                    Add-Item 'Taches planifiees' $taskName ($taskPath + ' etat ' + $state + ' ; auteur ' + $author + ' ; dernier demarrage ' + $run + ' ; resultat non lu (WinRM requis)') 'MSFT_ScheduledTask (CIM) et cache du Planificateur (registre, format non documente)'
                }
                if ($unread -gt 0) { Set-CollectorTruncated ('Dernier demarrage non lu pour ' + [string]$unread + ' tache(s) : cache du Planificateur reserve aux administrateurs du poste, absent ou budget atteint.') }
                if ($listed.Count -eq 0) { Add-Item 'Taches planifiees' 'Etat' 'Aucune tache hors Microsoft active' 'MSFT_ScheduledTask (CIM)' }
            }
            if (-not $script:WinrmReady) { & $readTasksByCim; return }
            $tasks = @()
            $winrmError = ''
            try {
                $tasks = Invoke-Remote -TimeoutSeconds 30 -ScriptBlock {
                    Get-ScheduledTask -ErrorAction SilentlyContinue |
                        Where-Object { ($_.State -ne 'Disabled') -and ($_.TaskPath -notlike '\Microsoft\*') } |
                        Select-Object -First 40 |
                        ForEach-Object {
                            $info = $null
                            try { $info = $_ | Get-ScheduledTaskInfo -ErrorAction Stop } catch { $info = $null }
                            [pscustomobject]@{ TaskName = [string]$_.TaskName; TaskPath = [string]$_.TaskPath; State = [string]$_.State; Author = [string]$_.Author; InfoRead = ($null -ne $info); LastRunTime = $(if ($null -ne $info) { $info.LastRunTime } else { $null }); LastTaskResult = $(if ($null -ne $info) { $info.LastTaskResult } else { $null }); MissedRuns = $(if ($null -ne $info) { $info.NumberOfMissedRuns } else { $null }) }
                        }
                }
            }
            catch {
                # A refused or paused credential stops the collection; any other WinRM failure is said, then read by CIM.
                if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw}
                $winrmError = (([string]$_.Exception.Message) -replace '\s+', ' ').Trim()
                if (-not $winrmError) { $winrmError = 'erreur sans message' }
                if ($winrmError.Length -gt 160) { $winrmError = $winrmError.Substring(0, 160) + '...' }
            }
            if ($winrmError) {
                try { & $readTasksByCim }
                catch {
                    if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw}
                    throw ('WinRM : ' + $winrmError + ' ; lecture CIM : ' + [string]$_.Exception.Message)
                }
                $cimLabel = [string]$script:CollectorTransport
                if ([string]::IsNullOrWhiteSpace($cimLabel)) { $cimLabel = 'CIM' }
                $script:CollectorTransport = $cimLabel + ' apres echec WinRM (' + $winrmError + ')'
                return
            }
            foreach ($t in (@($tasks) | Select-Object -First 40)) {
                $author = [string]$t.Author; if ([string]::IsNullOrWhiteSpace($author)) { $author = 'non declare' }
                $run = 'non lue'; $result = 'non lu'; $missed = ''
                if ([bool]$t.InfoRead) {
                    $run = 'jamais'
                    try { $last = [datetime]$t.LastRunTime; if ($last.Year -ge 2000) { $run = $last.ToString('dd/MM/yyyy HH:mm') } } catch { $run = 'illisible' }
                    try { if ($null -ne $t.LastTaskResult) { $result = '0x' + ([uint32]([int64]$t.LastTaskResult -band 0xFFFFFFFFL)).ToString('X') } } catch { $result = 'illisible' }
                    try { if ([int]$t.MissedRuns -gt 0) { $missed = ' ; executions manquees ' + [string][int]$t.MissedRuns } } catch { }
                }
                Add-Item 'Taches planifiees' ([string]$t.TaskName) ([string]$t.TaskPath + ' etat ' + [string]$t.State + ' ; auteur ' + $author + ' ; derniere execution ' + $run + ' ; resultat ' + $result + $missed) 'Get-ScheduledTask et Get-ScheduledTaskInfo via WinRM'
            }
            if (@($tasks).Count -eq 0) { Add-Item 'Taches planifiees' 'Etat' 'Aucune tache hors Microsoft active' 'Get-ScheduledTask via WinRM' }
        } 35000

        Invoke-Collector 'Certificats machine' {
            # Point 100: the Personal store of the computer only, read in the registry by StdRegProv. Each Blob holds the
            # certificate (property 32) and its properties; private keys are stored elsewhere and are never read.
            $storeKey = 'SOFTWARE\Microsoft\SystemCertificates\MY\Certificates'
            $registryRead = $false
            $truncated = ''
            $thumbprints = @()
            $found = New-Object Collections.ArrayList
            try {
                # Return code 0: store listed; 2: no certificate key, a true empty store; any other code: not read,
                # the WinRM path below is tried instead of reporting an empty store.
                $enum = Get-RegSubKeyRead $HKLM $storeKey
                if ($enum.Code -eq 0) { $thumbprints = @($enum.Names); $registryRead = $true }
                elseif ($enum.Code -eq 2) { $registryRead = $true }
                foreach ($thumbprint in @($thumbprints | Select-Object -First 50)) {
                    if (-not (Test-CollectorBudget)) { $truncated = 'Lecture arretee : budget de la source atteint.'; Set-CollectorTruncated $truncated; break }
                    $blob = $null
                    try { $blob = Get-RegBinary $HKLM ($storeKey + '\' + [string]$thumbprint) 'Blob' } catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw} }
                    if ($null -eq $blob) { continue }
                    $der = $null; $keyDeclared = $false; $offset = 0
                    while ($offset + 12 -le $blob.Length) {
                        $propertyId = [BitConverter]::ToUInt32($blob,$offset); $length = [BitConverter]::ToUInt32($blob,$offset + 8)
                        if ($length -gt ($blob.Length - $offset - 12)) { break }
                        if ($propertyId -eq 2) { $keyDeclared = $true }
                        if ($propertyId -eq 32) { $der = New-Object byte[] $length; [Array]::Copy($blob,$offset + 12,$der,0,$length) }
                        $offset = $offset + 12 + [int]$length
                    }
                    if ($null -eq $der) { continue }
                    try {
                        $certificate = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 (,$der)
                        $usages = @()
                        foreach ($extension in @($certificate.Extensions)) { if ($extension.Oid.Value -eq '2.5.29.37') { $usages = @($extension.EnhancedKeyUsages | ForEach-Object { if ($_.FriendlyName) { [string]$_.FriendlyName } else { [string]$_.Value } }) } }
                        [void]$found.Add([pscustomobject]@{ Subject=[string]$certificate.Subject; Issuer=[string]$certificate.Issuer; NotBeforeUtc=$certificate.NotBefore.ToUniversalTime().ToString('o'); NotAfterUtc=$certificate.NotAfter.ToUniversalTime().ToString('o'); Thumbprint=[string]$certificate.Thumbprint; Usages=@($usages | Select-Object -First 6); KeyDeclared=$keyDeclared; Store='Ordinateur local\Personnel' })
                        $days = [int][Math]::Floor(($certificate.NotAfter.ToUniversalTime() - [datetime]::UtcNow).TotalDays)
                        Add-Item 'Certificats machine' ([string]$certificate.Subject) ('expire le ' + $certificate.NotAfter.ToString('dd/MM/yyyy') + ' (' + [string]$days + ' jour(s)) ; emetteur ' + [string]$certificate.Issuer + ' ; empreinte ' + [string]$certificate.Thumbprint) 'Registre SystemCertificates\MY'
                        $certificate.Dispose()
                    } catch { }
                }
                if ((-not $truncated) -and (@($thumbprints).Count -gt 50)) { $truncated = [string]@($thumbprints).Count + ' certificats, 50 lus.'; Set-CollectorTruncated $truncated }
            } catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw}; $registryRead = $false }
            if ($registryRead) {
                $metrics.Certificates = [pscustomobject]@{ Source='Registre SystemCertificates\MY'; Items=@($found); ReadUtc=[datetime]::UtcNow.ToString('o'); StoreCount=@($thumbprints).Count; Truncated=[bool]$truncated }
                if ($found.Count -eq 0) { Add-Item 'Certificats machine' 'Etat' 'Aucun certificat machine' 'Registre SystemCertificates\MY' }
                return
            }
            $certs = Invoke-Remote -TimeoutSeconds 25 -ScriptBlock {
                Get-ChildItem -Path 'Cert:\LocalMachine\My' -ErrorAction SilentlyContinue |
                    Select-Object Subject,NotAfter,Thumbprint,Issuer
            }
            foreach ($c in (@($certs) | Select-Object -First 25)) {
                $days = 0
                try { $days = [int]((([datetime]$c.NotAfter) - (Get-Date)).TotalDays) } catch { }
                $flag = ''
                if ($days -lt 0) { $flag = ' EXPIRE' }
                elseif ($days -lt 30) { $flag = ' expire bientot' }
                Add-Item 'Certificats machine' ([string]$c.Subject) ('valide jusqu au ' + [string]$c.NotAfter + ', ' + $days + ' jour(s)' + $flag) 'Cert:\LocalMachine\My via WinRM'
            }
            if (@($certs).Count -eq 0) { Add-Item 'Certificats machine' 'Etat' 'Aucun certificat machine' 'WinRM' }
        } 30000

        Invoke-Collector 'Connexions reseau' {
            $conns = Invoke-Remote -TimeoutSeconds 25 -ScriptBlock {
                Get-NetTCPConnection -State Established -ErrorAction SilentlyContinue |
                    Select-Object -First 30 LocalPort,RemoteAddress,RemotePort,OwningProcess
            }
            foreach ($c in @($conns)) {
                Add-Item 'Connexions reseau' ('Port local ' + [string]$c.LocalPort) ('vers ' + [string]$c.RemoteAddress + ':' + [string]$c.RemotePort + ', PID ' + [string]$c.OwningProcess) 'Get-NetTCPConnection via WinRM'
            }
            if (@($conns).Count -eq 0) { Add-Item 'Connexions reseau' 'Etat' 'Aucune connexion etablie remontee' 'WinRM' }
        } 30000
    }
}
finally {
    try { Remove-WDomeniaCimSession $script:PrimarySession } catch { }
    try { Remove-WDomeniaCimSession $script:AltSession } catch { }
}

$totalWatch.Stop()
[pscustomobject]@{
    Computer = $computer
    Rows = @($rows)
    Access = @($access)
    Metrics = $metrics
    DurationMs = [long]$totalWatch.ElapsedMilliseconds
    Success = $true
}

}
foreach($DomeniaCollectedItem in @($DomeniaCollectedResult)){if($null -ne $DomeniaCollectedItem -and $DomeniaCollectedItem -isnot [string] -and $DomeniaCollectedItem -isnot [ValueType]){$DomeniaCollectedItem|Add-Member -NotePropertyName SourceCompletedUtc -NotePropertyValue ([datetime]::UtcNow.ToString('o')) -Force};$DomeniaCollectedItem}

'@
}

function Apply-DomeniaInventoryFilter {
    try {
        $rows = @($script:InventoryRows)
        $category = [string]$script:InventoryCategory
        if (-not [string]::IsNullOrWhiteSpace($category) -and $category -ne "Toutes") {
            $rows = @($rows | Where-Object { [string]$_.Category -eq $category })
        }
        [void](Set-DomeniaItemsSource -Name "DgInventory" -Rows $rows)
    }
    catch { Add-DomeniaUiLog -Level "ERROR" -Area "Inventaire" -Text $_.Exception.Message }
}

function Update-DomeniaInventoryCategories {
    $combo = Get-DomeniaControl -Name "CmbInventoryCategory"
    if ($null -eq $combo) { return }
    $categories = New-Object System.Collections.Generic.List[string]
    [void]$categories.Add("Toutes")
    foreach ($row in @($script:InventoryRows)) {
        $c = [string]$row.Category
        if (-not [string]::IsNullOrWhiteSpace($c) -and -not $categories.Contains($c)) { [void]$categories.Add($c) }
    }
    $script:SuppressInventoryCategoryEvent = $true
    try {
        $combo.Items.Clear()
        foreach ($c in $categories) {
            $item = New-Object System.Windows.Controls.ComboBoxItem
            $item.Content = $c
            [void]$combo.Items.Add($item)
        }
        $combo.SelectedIndex = 0
        $script:InventoryCategory = "Toutes"
    }
    finally { $script:SuppressInventoryCategoryEvent = $false }
}

function Complete-DomeniaInventoryUi {
    param($Result,$State)
    if(-not (Test-DomeniaClassicResultCurrent $Result $State)){return}
    if (([string]::IsNullOrWhiteSpace([string]$State.DN)) -or (([string]$State.DN) -ine ([string]$script:SelectedObject.DN))) { return }
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Access")
    if ($null -eq $effective) { throw "Resultat d inventaire vide ou invalide." }

    $script:InventoryRows = @($effective.Rows)
    $script:InventoryAccess = @($effective.Access)
    # PF-22 : l'onglet Logiciels a besoin de savoir de quel poste et de quelle heure vient cette liste.
    $script:InventoryComputer = [string]$State.Computer
    $script:InventoryCompletedAt = ConvertTo-DomeniaUtcDate $effective.SourceCompletedUtc
    try { Update-DomeniaComputerDashboard -Result $effective } catch { Add-DomeniaUiLog -Area "Tableau de bord" -Level "WARN" -Text ("Tableau de bord du poste non construit : " + $_.Exception.Message) }
    Update-DomeniaInventoryCategories
    Apply-DomeniaInventoryFilter
    [void](Set-DomeniaItemsSource -Name "DgInventoryAccess" -Rows $script:InventoryAccess)

    # FO-07 : la lecture vient de finir, elle rejoint le cache de session du poste. La cle est la regle
    # du depot pour nommer un poste, pas une seconde regle inventee ici.
    $cacheKey = Normalize-LinkComputer ([string]$State.Computer)
    if ($cacheKey) { $script:InventoryCacheByComputer[$cacheKey] = [pscustomobject]@{ Computer = [string]$State.Computer; Effective = $effective; CompletedAt = $script:InventoryCompletedAt; Guid=$State.StoreGuid; StoreId=$State.StoreContext.StoreId; Epoch=$State.StoreContext.SessionEpoch; AccountGeneration=$State.AccountGeneration } }
    $summary = Get-DomeniaInventorySummaryText -Computer ([string]$State.Computer) -Rows $script:InventoryRows -Access $script:InventoryAccess -DurationMs ([long]$effective.DurationMs)
    [void](Set-DomeniaControlText -Name "LblInventoryStatus" -Text $summary)
    Update-DomeniaInventoryAgeLine
    Set-Status $summary
    Add-DomeniaUiLog -Area "Inventaire" -Text $summary
    $inventoryMethods = New-Object System.Collections.Generic.List[string]
    foreach($a in @($script:InventoryAccess | Where-Object { [string]$_.Status -eq "OK" })) {
        $d=[string]$a.Detail
        if([string]$a.Category -match '(?i)Fallback PsExec' -or $d -match '(?i)via PsExec|Transport PsExec'){ if(-not $inventoryMethods.Contains("PsExec")){$inventoryMethods.Add("PsExec")} }
        elseif([string]$a.Category -match '(?i)Fallback Tache|Fallback Task' -or $d -match '(?i)tache planifiee|TaskScheduler'){ if(-not $inventoryMethods.Contains("TaskScheduler")){$inventoryMethods.Add("TaskScheduler")} }
        elseif($d -match '(?i)WinRM'){ if(-not $inventoryMethods.Contains("WinRM")){$inventoryMethods.Add("WinRM")} }
        elseif($d -match '(?i)DCOM|CIM|WMI'){ if(-not $inventoryMethods.Contains("CIM/DCOM")){$inventoryMethods.Add("CIM/DCOM")} }
    }
    if($inventoryMethods.Count -gt 0){ Add-DomeniaUiLog -Area "Inventaire" -Text ("{0} : methodes d'acquisition = {1}." -f [string]$State.Computer,($inventoryMethods -join ", ")) }
    try { Register-DomeniaOperationSample -Operation "ComputerInventory" -Mode $(if([int]$effective.FallbackTasks -gt 0){"Classic+TaskFallback"}else{"Classic"}) -ItemCount 1 -DurationMs ([long]$effective.DurationMs) -BytesEstimated $(if([long]$effective.TaskBytes -gt 0){[long]$effective.TaskBytes}else{250000}) -RemoteAttempts 1 -FallbackTasks ([int]$effective.FallbackTasks) -SuccessCount $(if([bool]$effective.Success){1}else{0}) -FailureCount $(if([bool]$effective.Success){0}else{1}) } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaInventoryUi' $_ }
}

function Fail-DomeniaInventoryUi {
    param($Message,$State)
    if(-not (Test-DomeniaClassicResultCurrent -State $State -ContextOnly)){return}
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue." }
    [void](Set-DomeniaControlText -Name "LblInventoryStatus" -Text ("Inventaire impossible : " + $detail))
    Set-Status ("Inventaire impossible : " + $detail) "ERROR"
    Add-DomeniaUiLog -Area "Inventaire" -Level "ERROR" -Text $detail
}

function Update-DomeniaInventoryAgeLine {
    # FO-07 : la ligne d'age suit l'etat courant de l'onglet, elle ne le devine jamais. Sans poste ou sans
    # heure de lecture, elle se retire : une ligne figee a « il y a 0 min » serait un mensonge.
    $line = Get-DomeniaControl "TxtInventoryAge"
    if ($null -eq $line) { return }
    $label = ''
    if ($null -ne $script:InventoryCompletedAt) { $label = Get-DomeniaInventoryAgeLabel -CompletedAt $script:InventoryCompletedAt }
    if ([string]::IsNullOrWhiteSpace($label) -or [string]::IsNullOrWhiteSpace([string]$script:InventoryComputer)) {
        $line.Visibility = [Windows.Visibility]::Collapsed
        try { Update-DomeniaComputerHeader } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaInventoryAgeLine' $_ }
        return
    }
    [void](Set-DomeniaControlText -Name "LblInventoryAge" -Text $label)
    # DS-08 (X04): the header of the workstation says the same age.
    try { Update-DomeniaComputerHeader } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaInventoryAgeLine' $_ }
    $line.ToolTip = ("Dernière lecture de {0} : {1}. La liste vient de cette session, sans nouvelle requête." -f `
        [string]$script:InventoryComputer, $script:InventoryCompletedAt.ToString('dd/MM/yyyy HH:mm:ss',[Globalization.CultureInfo]::InvariantCulture))
    $line.Visibility = [Windows.Visibility]::Visible
}

function Show-DomeniaCachedInventory {
    param($Computer)
    if(-not $Computer -or $null -eq $script:SelectedObject){return $false}
    try{
        $state=New-DomeniaClassicCollectionState -Computer ([string]$Computer) -ResultKind 'ClassicInventory' -RequestKey 'inventory-cache' -PublishHandler 'Complete-DomeniaInventoryUi' -PublishErrorHandler 'Fail-DomeniaInventoryUi'
        $job=Request-DomeniaStoreRead -Context $state.StoreContext -Query ([pscustomobject]@{Kind='Detail';Guids=@($state.StoreGuid);ResultKind='ClassicInventory';Offset=0;Limit=20}) -SuccessHandler 'Complete-DomeniaCachedInventoryRead' -ErrorHandler 'Fail-DomeniaCachedInventoryRead' -CallbackState $state
        return (-not [string]::IsNullOrWhiteSpace([string]$job))
    }catch{Write-AppLog ('Inventaire local non relu : '+$_.Exception.Message) 'WARN';return $false}
}

function Start-DomeniaComputerInventory {
    param([switch]$Deep)
    try {
        if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Machine") {
            Set-Status "Sélectionnez une machine avant de lancer lʼinventaire." "WARN"
            return
        }
        $computer = Assert-DomeniaComputerTarget -Computer (Get-CurrentSelectedComputerName)
        $mode = "rapide"
        if ($Deep) { $mode = "complet" }
        [void](Set-DomeniaControlText -Name "LblInventoryStatus" -Text ("Inventaire " + $mode + " en cours sur " + $computer + "..."))

        # Le budget interne doit rester nettement inferieur au delai de la
        # tache : le worker s arrete de lui-meme et rend un resultat partiel,
        # au lieu d etre tue et de tout perdre.
        $budget = 55000
        $softwareKeys = 250
        $timeout = 110
        if ($Deep) { $budget = 150000; $softwareKeys = 1200; $timeout = 260 }

        $collectionState=New-DomeniaClassicCollectionState -Computer $computer -ResultKind 'ClassicInventory' -RequestKey ('inventory-'+$mode) -PublishHandler 'Complete-DomeniaInventoryUi' -PublishErrorHandler 'Fail-DomeniaInventoryUi'
        Start-UiTask `
            -Name "Inventaire poste" `
            -OperationId "ComputerInventory" `
            -Code (Get-DomeniaInventoryWorkerCode) `
            -Payload ([pscustomobject]@{ Computer=$computer; Deep=[bool]$Deep; BudgetMs=$budget; MaxSoftwareKeys=$softwareKeys; PreferWinrm=[bool](Get-CfgValue "Inventory" "PreferWinrm" $false) }) `
            -CallbackState $collectionState `
            -ReplaceKey "inventory" `
            -DisableControls @("BtnRunInventory","BtnRunInventoryDeep") `
            -TimeoutSeconds $timeout `
            -StatusText ("Inventaire " + $mode + " de " + $computer + " en arriere-plan...") `
            -SuccessHandler "Complete-DomeniaClassicCollected" `
            -ErrorHandler "Fail-DomeniaClassicCollected" | Out-Null
    }
    catch { [void](Show-DomeniaOperationError -Operation "Inventaire poste" -ErrorRecordOrException $_) }
}

function Get-DomeniaInventoryReportText {
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add("=== INVENTAIRE POSTE ===")
    $current = ""
    foreach ($row in @($script:InventoryRows)) {
        $c = [string]$row.Category
        if ($c -ne $current) { $current = $c; [void]$lines.Add(""); [void]$lines.Add("[" + $c + "]") }
        [void]$lines.Add(("  {0} = {1}" -f [string]$row.Item,[string]$row.Value))
    }
    [void]$lines.Add("")
    [void]$lines.Add("=== RAPPORT D ACCES ===")
    foreach ($row in @($script:InventoryAccess)) {
        [void]$lines.Add(("  {0,-26} {1,-14} {2,4} element(s) {3,6} ms  {4}" -f `
            [string]$row.Category,[string]$row.Status,[int]$row.Items,[int]$row.DurationMs,[string]$row.Detail))
    }
    return ([string]::Join([Environment]::NewLine,$lines.ToArray()))
}

function Copy-DomeniaInventory {
    if (@($script:InventoryRows).Count -eq 0 -and @($script:InventoryAccess).Count -eq 0) {
        Set-Status "Aucun inventaire a copier." "WARN"
        return
    }
    Set-ClipboardSafe (Get-DomeniaInventoryReportText)
    Set-Status "Inventaire copie dans le presse-papiers."
}

function Export-DomeniaInventory {
    try {
        if (@($script:InventoryRows).Count -eq 0) { Set-Status "Aucun inventaire a exporter." "WARN"; return }
        # CO-04: the workstation is named in both files (it was computed but unused).
        $computer = Get-DomeniaExportComputerName
        $inventory = Export-DomeniaCsv -Rows @($script:InventoryRows) -Grid (Get-DomeniaControl -Name 'DgInventory') -Subject ($computer + '-inventaire')
        $access = Export-DomeniaCsv -Rows @($script:InventoryAccess) -Grid (Get-DomeniaControl -Name 'DgInventoryAccess') -Subject ($computer + '-acces')
        Add-DomeniaUiLog -Area "Inventaire" -Text ("Export CSV : " + [string]$inventory.Path + " et " + [string]$access.Path)
        # Point 50: what the second file kept out is said too, never only the first file's total.
        $also = 'Accès : ' + [string]$access.RowCount + ' ligne(s) dans ' + [IO.Path]::GetFileName([string]$access.Path) + '.'
        $accessMasked = [int](Get-DomeniaMember $access 'Masked' 0)
        if ($accessMasked -eq 1) { $also += ' 1 valeur ressemblant à un secret y a été masquée.' }
        elseif ($accessMasked -gt 1) { $also += ' ' + $accessMasked + ' valeurs ressemblant à un secret y ont été masquées.' }
        Show-DomeniaExportResult -Result $inventory -Also $also
    }
    catch { [void](Show-DomeniaOperationError -Operation "Export de l inventaire" -ErrorRecordOrException $_) }
}


# =====================================================================
# Vue domaine : lecture seule. Chaque section est isolee afin qu un refus
# de droits sur l une n empeche pas les autres de remonter.
# =====================================================================
function Get-DomeniaDomainWorkerCode {
    return @'
$rows = New-Object Collections.ArrayList
$watch = [System.Diagnostics.Stopwatch]::StartNew()
$baseDn = [string]$Context.BaseDn
if ([string]::IsNullOrWhiteSpace($baseDn)) { throw 'Base DN vide : analyse du domaine impossible.' }

function Add-Row {
    param([string]$Category,[string]$Name,$Value,[string]$Status = 'OK')
    $text = ''
    if ($null -ne $Value) { $text = ([string]$Value).Trim() }
    if ([string]::IsNullOrWhiteSpace($text)) { $text = 'Non renseigne' }
    [void]$rows.Add([pscustomobject]@{ Category=$Category; Item=$Name; Value=$text; Status=$Status })
}
function Invoke-Section {
    param([string]$Category,[scriptblock]$Action)
    $before = $rows.Count
    try {
        & $Action
        if ($rows.Count -eq $before) { Add-Row $Category 'Resultat' 'Aucune donnee retournee' 'VIDE' }
    }
    catch {
        $message = [string]$_.Exception.Message
        $status = 'ERREUR'
        if ($message -match '(?i)access|denied|refus|droit') { $status = 'REFUSE' }
        elseif ($message -match '(?i)introuvable|not found|invalid|inexistant') { $status = 'INDISPONIBLE' }
        Add-Row $Category 'Erreur' $message $status
    }
}
function Get-BehaviorLabel {
    param($Value)
    $v = -1
    try { $v = [int]$Value } catch { return 'Inconnu' }
    switch ($v) {
        0 { return 'Windows 2000' }
        1 { return 'Windows Server 2003 interim' }
        2 { return 'Windows Server 2003' }
        3 { return 'Windows Server 2008' }
        4 { return 'Windows Server 2008 R2' }
        5 { return 'Windows Server 2012' }
        6 { return 'Windows Server 2012 R2' }
        7 { return 'Windows Server 2016' }
        default { return ('Niveau ' + $v) }
    }
}
function Convert-Duration {
    param($Value)
    $ticks = Convert-WLargeInteger $Value
    if ($ticks -eq 0) { return 'Jamais' }
    try {
        $span = [TimeSpan]::FromTicks([Math]::Abs($ticks))
        if ($span.TotalDays -ge 1) { return ('' + [Math]::Round($span.TotalDays,2) + ' jour(s)') }
        if ($span.TotalHours -ge 1) { return ('' + [Math]::Round($span.TotalHours,2) + ' heure(s)') }
        return ('' + [Math]::Round($span.TotalMinutes,1) + ' minute(s)')
    }
    catch { return [string]$ticks }
}

$rootDse = $null
$configNc = ''
$schemaNc = ''
try {
    $rootDse = New-WRootDse $Context
    $rootDse.RefreshCache(@('defaultNamingContext','configurationNamingContext','schemaNamingContext','rootDomainNamingContext','dnsHostName','serverName','domainFunctionality','forestFunctionality','domainControllerFunctionality','supportedCapabilities','highestCommittedUSN','currentTime','namingContexts'))
    $configNc = [string]$rootDse.Properties['configurationNamingContext'].Value
    $schemaNc = [string]$rootDse.Properties['schemaNamingContext'].Value
}
catch { }

Invoke-Section 'Annuaire' {
    if ($null -eq $rootDse) { throw 'RootDSE illisible sur le controleur courant.' }
    Add-Row 'Annuaire' 'Controleur interroge' ([string]$rootDse.Properties['dnsHostName'].Value)
    Add-Row 'Annuaire' 'Serveur' ([string]$rootDse.Properties['serverName'].Value)
    Add-Row 'Annuaire' 'Contexte de nommage par defaut' ([string]$rootDse.Properties['defaultNamingContext'].Value)
    Add-Row 'Annuaire' 'Contexte de configuration' $configNc
    Add-Row 'Annuaire' 'Contexte de schema' $schemaNc
    Add-Row 'Annuaire' 'Domaine racine de foret' ([string]$rootDse.Properties['rootDomainNamingContext'].Value)
    Add-Row 'Annuaire' 'Niveau fonctionnel du domaine' (Get-BehaviorLabel $rootDse.Properties['domainFunctionality'].Value)
    Add-Row 'Annuaire' 'Niveau fonctionnel de la foret' (Get-BehaviorLabel $rootDse.Properties['forestFunctionality'].Value)
    Add-Row 'Annuaire' 'Niveau du controleur' (Get-BehaviorLabel $rootDse.Properties['domainControllerFunctionality'].Value)
    Add-Row 'Annuaire' 'USN le plus haut valide' ([string]$rootDse.Properties['highestCommittedUSN'].Value)
    Add-Row 'Annuaire' 'Heure du controleur' ([string]$rootDse.Properties['currentTime'].Value)
    $contexts = @()
    try { foreach ($nc in $rootDse.Properties['namingContexts']) { $contexts += [string]$nc } } catch { }
    Add-Row 'Annuaire' 'Partitions publiees' (@($contexts) -join ' | ')
}

Invoke-Section 'Roles FSMO' {
    $domainEntry = New-WEntry $Context $baseDn
    $domainEntry.RefreshCache(@('fSMORoleOwner'))
    $pdc = [string]$domainEntry.Properties['fSMORoleOwner'].Value
    Add-Row 'Roles FSMO' 'Emulateur PDC' $pdc

    if (-not [string]::IsNullOrWhiteSpace($schemaNc)) {
        $schemaEntry = New-WEntry $Context $schemaNc
        $schemaEntry.RefreshCache(@('fSMORoleOwner'))
        Add-Row 'Roles FSMO' 'Maitre de schema' ([string]$schemaEntry.Properties['fSMORoleOwner'].Value)
    }
    if (-not [string]::IsNullOrWhiteSpace($configNc)) {
        $partitionsDn = 'CN=Partitions,' + $configNc
        $partitionsEntry = New-WEntry $Context $partitionsDn
        $partitionsEntry.RefreshCache(@('fSMORoleOwner','msDS-EnabledFeature'))
        Add-Row 'Roles FSMO' 'Maitre de nommage de domaine' ([string]$partitionsEntry.Properties['fSMORoleOwner'].Value)
    }
    $ridDn = 'CN=RID Manager$,CN=System,' + $baseDn
    try {
        $ridEntry = New-WEntry $Context $ridDn
        $ridEntry.RefreshCache(@('fSMORoleOwner','rIDAvailablePool'))
        Add-Row 'Roles FSMO' 'Maitre RID' ([string]$ridEntry.Properties['fSMORoleOwner'].Value)
        $pool = Convert-WLargeInteger $ridEntry.Properties['rIDAvailablePool'].Value
        if ($pool -gt 0) {
            $total = [int64]($pool -shr 32)
            $allocated = [int64]($pool -band 4294967295)
            $remaining = $total - $allocated
            Add-Row 'Roles FSMO' 'RID restants dans le pool' $remaining
        }
    }
    catch { Add-Row 'Roles FSMO' 'Maitre RID' ([string]$_.Exception.Message) 'INDISPONIBLE' }
    $infraDn = 'CN=Infrastructure,' + $baseDn
    try {
        $infraEntry = New-WEntry $Context $infraDn
        $infraEntry.RefreshCache(@('fSMORoleOwner'))
        Add-Row 'Roles FSMO' 'Maitre d infrastructure' ([string]$infraEntry.Properties['fSMORoleOwner'].Value)
    }
    catch { Add-Row 'Roles FSMO' 'Maitre d infrastructure' ([string]$_.Exception.Message) 'INDISPONIBLE' }
}

Invoke-Section 'Strategie de mot de passe' {
    $domainEntry = New-WEntry $Context $baseDn
    $domainEntry.RefreshCache(@('minPwdLength','pwdHistoryLength','maxPwdAge','minPwdAge','lockoutThreshold','lockoutDuration','lockOutObservationWindow','pwdProperties','ms-DS-MachineAccountQuota'))
    Add-Row 'Strategie de mot de passe' 'Longueur minimale' ([string]$domainEntry.Properties['minPwdLength'].Value)
    Add-Row 'Strategie de mot de passe' 'Historique conserve' ([string]$domainEntry.Properties['pwdHistoryLength'].Value)
    Add-Row 'Strategie de mot de passe' 'Age maximal' (Convert-Duration $domainEntry.Properties['maxPwdAge'].Value)
    Add-Row 'Strategie de mot de passe' 'Age minimal' (Convert-Duration $domainEntry.Properties['minPwdAge'].Value)
    Add-Row 'Strategie de mot de passe' 'Seuil de verrouillage' ([string]$domainEntry.Properties['lockoutThreshold'].Value)
    Add-Row 'Strategie de mot de passe' 'Duree de verrouillage' (Convert-Duration $domainEntry.Properties['lockoutDuration'].Value)
    Add-Row 'Strategie de mot de passe' 'Fenetre d observation' (Convert-Duration $domainEntry.Properties['lockOutObservationWindow'].Value)
    $props = 0
    try { $props = [int]$domainEntry.Properties['pwdProperties'].Value } catch { }
    $complex = 'Non'
    if (($props -band 1) -ne 0) { $complex = 'Oui' }
    Add-Row 'Strategie de mot de passe' 'Complexite exigee' $complex
    $reversible = 'Non'
    if (($props -band 16) -ne 0) { $reversible = 'Oui' }
    Add-Row 'Strategie de mot de passe' 'Chiffrement reversible' $reversible
    Add-Row 'Strategie de mot de passe' 'Quota de comptes machine par utilisateur' ([string]$domainEntry.Properties['ms-DS-MachineAccountQuota'].Value)
}

Invoke-Section 'Strategies affinees' {
    $psoDn = 'CN=Password Settings Container,CN=System,' + $baseDn
    $searcher = New-WSearcher $Context $psoDn '(objectClass=msDS-PasswordSettings)' @('name','msDS-PasswordSettingsPrecedence','msDS-MinimumPasswordLength','msDS-LockoutThreshold','msDS-PSOAppliesTo') 'OneLevel' 50
    $found = 0
    foreach ($r in @($searcher.FindAll())) {
        $found++
        $p = $r.Properties
        $name = [string](Get-WPropFirst $p 'name' '')
        $precedence = [string](Get-WPropFirst $p 'msds-passwordsettingsprecedence' '')
        $minLength = [string](Get-WPropFirst $p 'msds-minimumpasswordlength' '')
        $threshold = [string](Get-WPropFirst $p 'msds-lockoutthreshold' '')
        $applies = @(Get-WPropAll $p 'msds-psoappliesto').Count
        $value = 'precedence ' + $precedence + ', longueur mini ' + $minLength + ', seuil ' + $threshold + ', ' + $applies + ' cible(s)'
        Add-Row 'Strategies affinees' $name $value
    }
    if ($found -eq 0) { Add-Row 'Strategies affinees' 'Etat' 'Aucun objet Password Settings defini' }
}

Invoke-Section 'Corbeille AD' {
    if ([string]::IsNullOrWhiteSpace($configNc)) { throw 'Contexte de configuration inconnu.' }
    $partitionsEntry = New-WEntry $Context ('CN=Partitions,' + $configNc)
    $partitionsEntry.RefreshCache(@('msDS-EnabledFeature'))
    $enabled = $false
    try {
        foreach ($f in $partitionsEntry.Properties['msDS-EnabledFeature']) {
            if (([string]$f) -match '(?i)Recycle Bin Feature') { $enabled = $true }
        }
    }
    catch { }
    $label = 'Desactivee'
    if ($enabled) { $label = 'Activee' }
    Add-Row 'Corbeille AD' 'Fonctionnalite optionnelle' $label
    if ($enabled) {
        $deletedDn = 'CN=Deleted Objects,' + $baseDn
        try {
            $searcher = New-WSearcher $Context $deletedDn '(isDeleted=TRUE)' @('name') 'OneLevel' 25
            $searcher.Tombstone = $true
            $deleted = @($searcher.FindAll()).Count
            Add-Row 'Corbeille AD' 'Objets supprimes visibles' ('' + $deleted + ' (limite de lecture 25)')
        }
        catch { Add-Row 'Corbeille AD' 'Objets supprimes visibles' ([string]$_.Exception.Message) 'REFUSE' }
    }
}

Invoke-Section 'Controleurs de domaine' {
    $searcher = New-WSearcher $Context $baseDn '(&(objectCategory=computer)(userAccountControl:1.2.840.113556.1.4.803:=8192))' @('name','dNSHostName','operatingSystem','operatingSystemVersion','whenCreated','lastLogonTimestamp') 'Subtree' 100
    foreach ($r in @($searcher.FindAll())) {
        $p = $r.Properties
        $name = [string](Get-WPropFirst $p 'name' '')
        $dns = [string](Get-WPropFirst $p 'dnshostname' '')
        $os = [string](Get-WPropFirst $p 'operatingsystem' '')
        $last = Convert-WFileTime (Get-WPropFirst $p 'lastlogontimestamp' 0)
        $value = $dns + ' | ' + $os + ' | derniere ouverture ' + $last
        Add-Row 'Controleurs de domaine' $name $value
    }
}

Invoke-Section 'Sites et sous-reseaux' {
    if ([string]::IsNullOrWhiteSpace($configNc)) { throw 'Contexte de configuration inconnu.' }
    $sitesDn = 'CN=Sites,' + $configNc
    $searcher = New-WSearcher $Context $sitesDn '(objectClass=site)' @('name','description') 'OneLevel' 200
    $siteCount = 0
    foreach ($r in @($searcher.FindAll())) {
        $siteCount++
        $p = $r.Properties
        Add-Row 'Sites et sous-reseaux' ('Site ' + [string](Get-WPropFirst $p 'name' '')) ([string](Get-WPropFirst $p 'description' ''))
    }
    Add-Row 'Sites et sous-reseaux' 'Nombre de sites' $siteCount
    $subnetDn = 'CN=Subnets,CN=Sites,' + $configNc
    try {
        $subnetSearcher = New-WSearcher $Context $subnetDn '(objectClass=subnet)' @('name','siteObject') 'OneLevel' 500
        $subnets = @($subnetSearcher.FindAll()).Count
        Add-Row 'Sites et sous-reseaux' 'Nombre de sous-reseaux' $subnets
    }
    catch { Add-Row 'Sites et sous-reseaux' 'Nombre de sous-reseaux' ([string]$_.Exception.Message) 'INDISPONIBLE' }
}

Invoke-Section 'Approbations' {
    $systemDn = 'CN=System,' + $baseDn
    $searcher = New-WSearcher $Context $systemDn '(objectClass=trustedDomain)' @('name','trustDirection','trustType','trustAttributes','flatName') 'OneLevel' 100
    $found = 0
    foreach ($r in @($searcher.FindAll())) {
        $found++
        $p = $r.Properties
        $name = [string](Get-WPropFirst $p 'name' '')
        $direction = 0
        try { $direction = [int](Get-WPropFirst $p 'trustdirection' 0) } catch { }
        $label = 'Inconnue'
        if ($direction -eq 1) { $label = 'Entrante' }
        elseif ($direction -eq 2) { $label = 'Sortante' }
        elseif ($direction -eq 3) { $label = 'Bidirectionnelle' }
        $flat = [string](Get-WPropFirst $p 'flatname' '')
        Add-Row 'Approbations' $name ($label + ', NetBIOS ' + $flat)
    }
    if ($found -eq 0) { Add-Row 'Approbations' 'Etat' 'Aucune approbation declaree' }
}

Invoke-Section 'Strategies de groupe' {
    $policiesDn = 'CN=Policies,CN=System,' + $baseDn
    $searcher = New-WSearcher $Context $policiesDn '(objectClass=groupPolicyContainer)' @('displayName','versionNumber','whenChanged') 'OneLevel' 500
    $all = @($searcher.FindAll())
    Add-Row 'Strategies de groupe' 'Nombre d objets GPO' (@($all).Count)
    $recent = @($all | Select-Object -First 12)
    foreach ($r in $recent) {
        $p = $r.Properties
        $name = [string](Get-WPropFirst $p 'displayname' '')
        $changed = Convert-WDate (Get-WPropFirst $p 'whenchanged' '')
        Add-Row 'Strategies de groupe' $name ('modifiee le ' + $changed)
    }
}

Invoke-Section 'Groupes privilegies' {
    $groups = @('Domain Admins','Enterprise Admins','Schema Admins','Administrators','Account Operators','Backup Operators','Server Operators','Admins du domaine','Administrateurs de l entreprise','Administrateurs du schema','Administrateurs')
    $seen = @{}
    foreach ($g in $groups) {
        $escaped = Escape-WLdap -Value $g
        $searcher = New-WSearcher $Context $baseDn ('(&(objectCategory=group)(name=' + $escaped + '))') @('name','member','distinguishedName') 'Subtree' 5
        foreach ($r in @($searcher.FindAll())) {
            $p = $r.Properties
            $dn = [string](Get-WPropFirst $p 'distinguishedname' '')
            if ([string]::IsNullOrWhiteSpace($dn)) { continue }
            $key = $dn.ToLowerInvariant()
            if ($seen.ContainsKey($key)) { continue }
            $seen[$key] = $true
            $members = @(Get-WPropAll $p 'member')
            $shortNames = New-Object Collections.ArrayList
            foreach ($m in ($members | Select-Object -First 12)) {
                $text = [string]$m
                $first = $text.Split(',')[0]
                if ($first.Length -gt 3) { $first = $first.Substring(3) }
                [void]$shortNames.Add($first)
            }
            $value = '' + @($members).Count + ' membre(s) : ' + ((@($shortNames)) -join ', ')
            Add-Row 'Groupes privilegies' ([string](Get-WPropFirst $p 'name' '')) $value
        }
    }
    if ($seen.Count -eq 0) { Add-Row 'Groupes privilegies' 'Etat' 'Aucun groupe privilegie lisible' 'REFUSE' }
}

Invoke-Section 'Comptes a surveiller' {
    $never = 65536
    $searcher = New-WSearcher $Context $baseDn '(&(objectCategory=person)(objectClass=user)(userAccountControl:1.2.840.113556.1.4.803:=65536))' @('name','sAMAccountName') 'Subtree' 60
    $rowsNever = @($searcher.FindAll())
    Add-Row 'Comptes a surveiller' 'Mot de passe sans expiration' ('' + @($rowsNever).Count + ' compte(s) lus, limite 60')
    $disabledSearcher = New-WSearcher $Context $baseDn '(&(objectCategory=person)(objectClass=user)(userAccountControl:1.2.840.113556.1.4.803:=2))' @('name') 'Subtree' 200
    Add-Row 'Comptes a surveiller' 'Comptes desactives' ('' + @($disabledSearcher.FindAll()).Count + ' compte(s) lus, limite 200')
    $noPreAuth = New-WSearcher $Context $baseDn '(&(objectCategory=person)(objectClass=user)(userAccountControl:1.2.840.113556.1.4.803:=4194304))' @('name') 'Subtree' 60
    Add-Row 'Comptes a surveiller' 'Sans pre-authentification Kerberos' ('' + @($noPreAuth.FindAll()).Count + ' compte(s), risque AS-REP roasting')
    $spnSearcher = New-WSearcher $Context $baseDn '(&(objectCategory=person)(objectClass=user)(servicePrincipalName=*))' @('name','sAMAccountName') 'Subtree' 60
    Add-Row 'Comptes a surveiller' 'Comptes de service avec SPN' ('' + @($spnSearcher.FindAll()).Count + ' compte(s), cible de Kerberoasting')
    $delegSearcher = New-WSearcher $Context $baseDn '(&(objectCategory=person)(objectClass=user)(userAccountControl:1.2.840.113556.1.4.803:=524288))' @('name') 'Subtree' 60
    Add-Row 'Comptes a surveiller' 'Delegation non contrainte' ('' + @($delegSearcher.FindAll()).Count + ' compte(s)')
    try {
        $krbtgt = New-WSearcher $Context $baseDn '(sAMAccountName=krbtgt)' @('pwdLastSet','name') 'Subtree' 1
        $k = $krbtgt.FindOne()
        if ($null -ne $k) {
            Add-Row 'Comptes a surveiller' 'Dernier changement du mot de passe krbtgt' (Convert-WFileTime (Get-WPropFirst $k.Properties 'pwdlastset' 0))
        }
    }
    catch { }
}

$watch.Stop()
[pscustomobject]@{
    Rows = @($rows)
    BaseDn = $baseDn
    DurationMs = [long]$watch.ElapsedMilliseconds
    Success = $true
}

'@
}

function Complete-DomeniaDomainUi {
    param($Result,$State)
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Rows")
    if ($null -eq $effective) { throw "Resultat d analyse du domaine vide ou invalide." }
    $script:DomainRows = @($effective.Rows)
    [void](Set-DomeniaItemsSource -Name "DgDomain" -Rows $script:DomainRows)
    $sections = @($script:DomainRows | ForEach-Object { [string]$_.Category } | Sort-Object -Unique).Count
    $refused = @($script:DomainRows | Where-Object { [string]$_.Status -eq "REFUSE" }).Count
    $errors = @($script:DomainRows | Where-Object { [string]$_.Status -notin @("OK","VIDE") }).Count
    $summary = "{0} : {1} information(s) sur {2} section(s), {3} refus, {4} anomalie(s), en {5} ms." -f `
        ([string]$effective.BaseDn),@($script:DomainRows).Count,$sections,$refused,$errors,([long]$effective.DurationMs)
    [void](Set-DomeniaControlText -Name "LblDomainStatus" -Text $summary)
    Set-Status $summary
    Add-DomeniaUiLog -Area "Domaine" -Text $summary
}

function Fail-DomeniaDomainUi {
    param($Message,$State)
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue." }
    [void](Set-DomeniaControlText -Name "LblDomainStatus" -Text ("Analyse impossible : " + $detail))
    Set-Status ("Analyse du domaine impossible : " + $detail) "ERROR"
    Add-DomeniaUiLog -Area "Domaine" -Level "ERROR" -Text $detail
}

function Start-DomeniaDomainOverview {
    # MO-04: the directory is never counted as a whole. The overview reads the state of the domain; the totals come
    # from the local copy with its date (Start-DomeniaDomainLocalTotals, local read in the background).
    try {
        $script:DomainRows = @()
        [void](Set-DomeniaItemsSource -Name "DgDomain" -Rows @())
        [void](Set-DomeniaControlText -Name "LblDomainStatus" -Text "Analyse du domaine en cours...")
        Start-DomeniaDomainLocalTotals
        Start-UiTask `
            -Name "Analyse du domaine" `
            -OperationId "DomainOverview" `
            -Code (Get-DomeniaDomainWorkerCode) `
            -Payload ([pscustomobject]@{}) `
            -CallbackState ([pscustomobject]@{}) `
            -ReplaceKey "domain" `
            -DisableControls @("BtnLoadDomain") `
            -TimeoutSeconds 90 `
            -StatusText "Analyse du domaine en arriere-plan..." `
            -SuccessHandler "Complete-DomeniaDomainUi" `
            -ErrorHandler "Fail-DomeniaDomainUi" | Out-Null
    }
    catch { [void](Show-DomeniaOperationError -Operation "Analyse du domaine" -ErrorRecordOrException $_) }
}

function Copy-DomeniaDomainReport {
    if (@($script:DomainRows).Count -eq 0) { Set-Status "Aucune analyse de domaine a copier." "WARN"; return }
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add("=== DOMAINE ACTIVE DIRECTORY ===")
    $current = ""
    foreach ($row in @($script:DomainRows)) {
        $c = [string]$row.Category
        if ($c -ne $current) { $current = $c; [void]$lines.Add(""); [void]$lines.Add("[" + $c + "]") }
        [void]$lines.Add(("  {0,-42} {1}  [{2}]" -f [string]$row.Item,[string]$row.Value,[string]$row.Status))
    }
    Set-ClipboardSafe ([string]::Join([Environment]::NewLine,$lines.ToArray()))
    Set-Status "Rapport de domaine copie dans le presse-papiers."
}


# =====================================================================
# Menus contextuels. Ils sont construits en code plutot qu en XAML afin
# que chaque entree puisse etre activee ou grisee selon le type de la
# ligne cliquee et selon le mode lecture seule.
# =====================================================================
function New-DomeniaMenuItem {
    param(
        [Parameter(Mandatory=$true)][string]$Header,
        [scriptblock]$Action,
        [bool]$Enabled = $true,
        [string]$ToolTip = ""
    )
    $item = New-Object System.Windows.Controls.MenuItem
    $item.Header = $Header
    $item.IsEnabled = $Enabled
    if (-not [string]::IsNullOrWhiteSpace($ToolTip)) { $item.ToolTip = $ToolTip }
    if ($null -ne $Action) {
        $item.Add_Click({
            param($sender,$e)
            try { & $sender.Tag }
            catch { [void](Show-DomeniaOperationError -Operation "Action du menu contextuel" -ErrorRecordOrException $_) }
        })
        $item.Tag = $Action
    }
    return $item
}

function Add-DomeniaMenuSeparator {
    param([Parameter(Mandatory=$true)]$Menu)
    [void]$Menu.Items.Add((New-Object System.Windows.Controls.Separator))
}

function Get-DomeniaRowText {
    # Serialise une ligne de grille en texte tabule, colonnes dans l ordre.
    param($Row)
    if ($null -eq $Row) { return "" }
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($p in $Row.PSObject.Properties) {
        if ($p.MemberType -notin @("NoteProperty","Property")) { continue }
        [void]$parts.Add(("{0}={1}" -f $p.Name,[string]$p.Value))
    }
    return ([string]::Join("`t",$parts.ToArray()))
}

function Copy-DomeniaGridSelection {
    param([Parameter(Mandatory=$true)][string]$Name)
    $grid = Get-DomeniaControl -Name $Name
    if ($null -eq $grid) { return }
    $rows = @($grid.SelectedItems)
    if ($rows.Count -eq 0 -and $null -ne $grid.SelectedItem) { $rows = @($grid.SelectedItem) }
    if ($rows.Count -eq 0) { Set-Status "Aucune ligne sélectionnée." "WARN"; return }
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($r in $rows) { [void]$lines.Add((Get-DomeniaRowText $r)) }
    Set-ClipboardSafe ([string]::Join([Environment]::NewLine,$lines.ToArray()))
    Set-Status ("{0} ligne(s) copiee(s)." -f $rows.Count)
}

function Copy-DomeniaRowProperty {
    param([Parameter(Mandatory=$true)]$Row,[Parameter(Mandatory=$true)][string]$Property)
    if ($null -eq $Row) { return }
    $value = ""
    try { $value = [string]$Row.$Property } catch { Write-DomeniaSwallowed 'Core' 'Copy-DomeniaRowProperty' $_ }
    if ([string]::IsNullOrWhiteSpace($value)) { Set-Status "Valeur vide, rien a copier." "WARN"; return }
    Set-ClipboardSafe $value
    Set-Status ("Copie : " + $value)
}

function Start-DomeniaSearchFor {
    # Place un terme dans la recherche globale et lance la requete.
    param([Parameter(Mandatory=$true)][AllowEmptyString()][string]$Term)
    $clean = ([string]$Term).Trim()
    if ([string]::IsNullOrWhiteSpace($clean)) { Set-Status "Rien a rechercher." "WARN"; return }
    # D036: a pasted DN, GUID or SID is an exact identifier and is never cut at its commas or backslashes.
    $exactIdentifier = ([string](Get-DomeniaPastedIdentifier $clean).Kind -in @('DN','Guid','Sid'))
    if (-not $exactIdentifier) {
        # Une association peut contenir plusieurs entrees : on prend la premiere.
        foreach ($sep in @(",",";","|")) {
            if ($clean.Contains($sep)) { $clean = $clean.Split([char]$sep)[0].Trim() }
        }
        if ($clean.Contains([string][char]92)) { $clean = $clean.Split([char]92)[-1] }
        $clean = $clean.Trim().TrimEnd([char]36)
    }
    if ([string]::IsNullOrWhiteSpace($clean)) { Set-Status "Terme de recherche vide." "WARN"; return }
    [void](Set-DomeniaControlText -Name "TxtGlobalSearch" -Text $clean)
    Select-DomeniaWorkspace -Workspace "WsSearch"
    Add-DomeniaUiLog -Area "Recherche" -Text ("Recherche depuis le menu contextuel : " + $clean)
    Invoke-GlobalSearch
}

function Start-DomeniaSearchAssociated {
    # Depuis une machine, recherche son utilisateur ; depuis un utilisateur,
    # recherche son poste. C est le trajet le plus frequent en support.
    param($Row)
    if ($null -eq $Row) { Set-Status "Aucune ligne sélectionnée." "WARN"; return }
    $association = ""
    try { $association = [string]$Row.Association } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaSearchAssociated' $_ }
    if ([string]::IsNullOrWhiteSpace($association) -or $association -match "(?i)^(aucun|non detect|inconnu)") {
        $type = ""
        try { $type = [string]$Row.Type } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaSearchAssociated' $_ }
        $label = "associe"
        if ($type -eq "Machine") { $label = "Aucun utilisateur associe a ce poste. Lance la detection dans l onglet Liens user-machine." }
        elseif ($type -eq "Utilisateur") { $label = "Aucun poste associe a ce compte." }
        Set-Status $label "WARN"
        return
    }
    Start-DomeniaSearchFor -Term $association
}

function New-DomeniaObjectsContextMenu {
    $menu = New-Object System.Windows.Controls.ContextMenu
    $menu.Add_Opened({
        param($sender,$e)
        try { Build-DomeniaObjectsContextMenu -Menu $sender }
        catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaObjectsContextMenu' $_ }
    })
    return $menu
}


function Get-DomeniaSelectedGridRows {
    $grid = Get-DomeniaControl -Name "DgObjects"
    if ($null -eq $grid) { return @() }
    try { return @($grid.SelectedItems | Where-Object { $null -ne $_ }) } catch { return @() }
}

function Get-DomeniaSelectedMachineRows {
    return @(Get-DomeniaSelectedGridRows | Where-Object { [string]$_.Type -eq "Machine" -and -not [string]::IsNullOrWhiteSpace([string]$_.Name) })
}

function Show-DomeniaBatchNetworkReport {
    # Point 48: $Rows is the whole selection. The exact machines, the rows left out and why, and the impact are shown
    # in the page; nothing leaves before the operator confirms there.
    # An empty selection is a normal answer (status line), never a binding error in the palette handler.
    param([Parameter(Mandatory=$true)][AllowEmptyCollection()][AllowNull()]$Rows,[ValidateRange(1,200)][int]$Limit=50)
    $items = @($Rows | Where-Object { $null -ne $_ })
    if ($items.Count -eq 0) { Set-Status "Aucun poste sélectionné." "WARN"; return }

    $code = @'
$results = New-Object Collections.ArrayList
foreach($row in @($Payload.Rows)){
    $name=[string]$row.Name
    $sw=[Diagnostics.Stopwatch]::StartNew()
    $ping=$false
    try {
        $ping=Test-Connection -ComputerName $name -Count 1 -Quiet -ErrorAction Stop
    } catch { $ping=$false }
    $ports=[ordered]@{}
    foreach($p in @(445,135,5985,5986)){
        try { $ports[[string]$p]=[bool](Test-NetConnection -ComputerName $name -Port $p -InformationLevel Quiet -WarningAction SilentlyContinue -ErrorAction Stop) }
        catch { $ports[[string]$p]=$false }
    }
    $sw.Stop()
    [void]$results.Add([pscustomobject]@{
        Nom=$name
        Ping=if($ping){"OK"}else{"KO"}
        SMB445=if($ports["445"]){"OK"}else{"KO"}
        RPC135=if($ports["135"]){"OK"}else{"KO"}
        WinRM5985=if($ports["5985"]){"OK"}else{"KO"}
        WinRM5986=if($ports["5986"]){"OK"}else{"KO"}
        DureeMs=[long]$sw.ElapsedMilliseconds
    })
}
[pscustomobject]@{Rows=@($results);Count=$results.Count}
'@

    # Every selected row is a candidate. A machine without a usable host name is left out first, with its reason; the
    # preview then keeps the exact targets (machine, DN and GUID, no duplicate, explicit limit) from the rows
    # themselves. A select-all of the grid runs on the interface thread: direct property reads, no function call nor
    # copy per row; past the limit the preview only counts the rows.
    $candidates=New-Object 'System.Collections.Generic.List[object]';$excluded=New-Object 'System.Collections.Generic.List[object]'
    foreach($row in $items){
        $name='';$type=''
        if($row -is [Collections.IDictionary]){$name=[string](Get-DomeniaMember $row 'Name' '');$type=[string](Get-DomeniaMember $row 'Type' '')}
        else{
            $property=$row.PSObject.Properties['Name'];if($null -ne $property){$name=[string]$property.Value}
            $property=$row.PSObject.Properties['Type'];if($null -ne $property){$type=[string]$property.Value}
        }
        if(($type -eq 'Machine') -and ($name.Trim() -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]{0,252}$')){
            $dn=[string](Get-DomeniaMember $row 'DN' '')
            $label=$name.Trim();if(-not $label){$label=$dn}
            $excluded.Add([pscustomobject]@{Name=$label;DN=$dn;Reason='Nom de poste absent ou non valide'});continue
        }
        $candidates.Add($row)
    }
    $timeoutSeconds=[Math]::Max(20,[int](Get-CfgValue "Async" "ComputerTimeoutSeconds" 90))
    $impact='un poste après lʼautre ; la tâche sʼarrête au bout de '+$timeoutSeconds+' s, sans résultat partiel.'
    $preview=New-DomeniaCollectivePreview -OperationId 'BatchNetworkDiag' -Candidates $candidates.ToArray() -Excluded $excluded.ToArray() -ExpectedType 'Machine' -Change 'écho ICMP puis ports TCP 445, 135, 5985 et 5986' -Impact $impact -Limit $Limit
    if([int]$preview.Count -eq 0){Set-Status ('Aucun poste exploitable dans la sélection : '+[string]$preview.ExcludedCount+' ligne(s) exclue(s).') 'WARN';return}
    $targets=@($preview.Targets)
    $request=[pscustomobject]@{Code=$code;Rows=$targets;Count=$targets.Count;TimeoutSeconds=$timeoutSeconds;Payload=[pscustomobject]@{Rows=@($targets | ForEach-Object {[pscustomobject]@{Name=[string]$_.Name;DN=[string]$_.DN}})}}
    $start={
        param($s)
        $callbackState=[pscustomobject]@{Rows=$s.Rows;Started=Get-Date}
        Start-UiTask -Name "Diagnostic reseau groupe" -OperationId "BatchNetworkDiag" -Code $s.Code -Payload $s.Payload -CallbackState $callbackState -ReplaceKey "batch-network-diag" -TimeoutSeconds $s.TimeoutSeconds -StatusText ("Diagnostic reseau de {0} poste(s)..." -f $s.Count) -SuccessHandler "Complete-DomeniaBatchNetworkReportUi" -ErrorHandler "Fail-DomeniaBatchNetworkReportUi" | Out-Null
    }
    $message='Lecture réseau seule : aucun compte nʼest envoyé et rien nʼest modifié sur les postes.'
    [void](Request-DomeniaInlineConfirmation -Title 'Diagnostic réseau groupé' -Target ([string]$script:Conn.Domain) -Message $message -ConfirmText 'Diagnostiquer' -CancelText 'Annuler' -OnConfirm ({ & $start $request }.GetNewClosure()) -Changes @($preview.Lines) -Details ([string]$preview.Details) -DetailsTitle 'Liste exacte des cibles et des exclusions' -TypedConfirmation ([string]$preview.TypedText))
}

function Complete-DomeniaBatchNetworkReportUi {
    param($Result,$State)
    try {
        $effective=Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Rows","Count")
        $rows=@($effective.Rows)
        if($rows.Count -eq 0){Set-Status "Aucun résultat de diagnostic." "WARN";return}
        $okPing=@($rows|Where-Object{$_.Ping -eq "OK"}).Count
        $ok445=@($rows|Where-Object{$_.SMB445 -eq "OK"}).Count
        $okWinrm=@($rows|Where-Object{$_.WinRM5985 -eq "OK" -or $_.WinRM5986 -eq "OK"}).Count
        $report = ($rows | Format-Table -AutoSize | Out-String -Width 240).Trim()
        Set-ClipboardSafe $report
        Set-Status ("Diagnostic termine : {0} poste(s), ping {1}/{0}, SMB {2}/{0}, WinRM {3}/{0}. Rapport copie." -f $rows.Count,$okPing,$ok445,$okWinrm)
        Show-DomeniaDialog -Title "Diagnostic réseau groupé" -Message ("$($rows.Count) poste(s) testés.`r`n`r`nPing : $okPing/$($rows.Count)`r`nSMB 445 : $ok445/$($rows.Count)`r`nWinRM : $okWinrm/$($rows.Count)`r`n`r`nLe rapport complet a été copié dans le presse-papiers.")
        Add-DomeniaUiLog -Area "Diagnostic groupe" -Level "INFO" -Text ("$($rows.Count) poste(s) testes ; ping=$okPing ; SMB=$ok445 ; WinRM=$okWinrm.")
    } catch { Show-DomeniaOperationError -Operation "Affichage du diagnostic reseau groupe" -ErrorRecordOrException $_ }
}

function Fail-DomeniaBatchNetworkReportUi {
    param($Message,$State)
    Set-Status ("Diagnostic réseau groupé en échec : " + [string]$Message) "ERROR"
}

function Copy-DomeniaSelectedRowsForTicket {
    # SP-05: one readable line per selected row (Type · Nom · Compte · Présence · Utilisateur console · OU), without
    # GUID nor internal field, masked by the secret rule before the clipboard.
    $rows = @(Get-DomeniaSelectedGridRows)
    if ($rows.Count -eq 0) { Set-Status 'Aucune ligne sélectionnée.' 'WARN'; return }
    $text = ConvertTo-DomeniaTicketText -Rows $rows
    if ([string]::IsNullOrWhiteSpace($text)) { Set-Status 'Rien à copier pour un ticket dans la sélection.' 'WARN'; return }
    Set-ClipboardSafe $text
    Set-Status ('{0} ligne(s) copiée(s) pour un ticket, sans identifiant interne.' -f $rows.Count)
}

function Open-DomeniaResultRowParentOu {
    # UX-26: lists the OU (or container) of the clicked row in Rechercher. Read-only: the selected fiche, the tree
    # and the other filters are left as they are.
    param($Row)
    if ($null -eq $Row) { Set-Status 'Aucune ligne sélectionnée.' 'WARN'; return }
    $parent = Get-DomeniaRawDnParent ([string]$Row.DN)
    if ([string]::IsNullOrWhiteSpace($parent)) { Set-Status 'Cette ligne nʼa pas de conteneur parent lisible.' 'WARN'; return }
    $script:SelectedBranchDn = $parent
    [void](Set-DomeniaControlText -Name 'TxtBranchDn' -Text $parent)
    [void](Set-DomeniaControlText -Name 'TxtBranchSearch' -Text '')
    Select-DomeniaWorkspace -Workspace 'WsSearch'
    Load-BranchObjects -Browse
    Set-Status ('OU parente affichée : ' + (Get-DomeniaOuDisplayPath $parent))
}

function Open-DomeniaResultRowSupport {
    # UX-26: « Assistance poste » opens the workstation on its Intervenir view, where the remote tools and the writes
    # stay behind their own confirmation. The menu itself starts nothing on the workstation.
    $row = Get-DomeniaSelectedGridRow
    if ($null -eq $row -or [string]$row.Type -ne 'Machine') { Set-Status 'Sélectionnez un seul poste.' 'WARN'; return }
    Queue-DomeniaSelectedObjectOpen -Immediate -Force
    Select-DomeniaWorkspace -Workspace 'WsComputer' -Inner 'ComputerTabs' -Tab 'TabComputerAdmin'
}

function Build-DomeniaObjectsContextMenu {
    # UX-26 / CO-35: a short menu without any write: open, support of the workstation, one-workstation recheck that
    # stays in Rechercher, associated account, parent OU, copies and export. Writes, remote tools and collections
    # live in the fiche and in Assistance poste, each with its own confirmation.
    param([Parameter(Mandatory=$true)]$Menu)
    $Menu.Items.Clear()
    $row = Get-DomeniaSelectedGridRow
    $rows = @(Get-DomeniaSelectedGridRows)
    if ($null -eq $row -or $rows.Count -eq 0) {
        [void]$Menu.Items.Add((New-DomeniaMenuItem -Header "Aucune ligne sélectionnée" -Enabled $false))
        return
    }
    $type = ""
    $name = ""
    $association = ""
    try { $type = [string]$row.Type } catch { Write-DomeniaSwallowed 'Core' 'Build-DomeniaObjectsContextMenu' $_ }
    try { $name = [string]$row.Name } catch { Write-DomeniaSwallowed 'Core' 'Build-DomeniaObjectsContextMenu' $_ }
    try { $association = [string]$row.Association } catch { Write-DomeniaSwallowed 'Core' 'Build-DomeniaObjectsContextMenu' $_ }
    $single = ($rows.Count -eq 1)
    $isMachine = ($type -eq "Machine")
    $isUser = ($type -eq "Utilisateur")
    $hasAssociation = (-not [string]::IsNullOrWhiteSpace($association)) -and ($association -notmatch "(?i)^(aucun|non detect|non détect|inconnu)")
    $grid = Get-DomeniaControl -Name "DgObjects"
    $gridReady = ($null -ne $grid -and [bool]$grid.IsEnabled)
    $singleTip = "Une seule ligne sélectionnée."

    [void]$Menu.Items.Add((New-DomeniaMenuItem -Header ("Ouvrir la fiche de " + $name) -Enabled $single -ToolTip $(if ($single) { "" } else { $singleTip }) -Action { Open-SelectedObject -Force }))
    if ($isMachine) {
        [void]$Menu.Items.Add((New-DomeniaMenuItem -Header "Assistance poste" -Enabled $single `
            -ToolTip "Ouvre la vue Intervenir du poste : Bureau à distance, disque C, consoles et stratégies. Chaque action garde sa confirmation ; ce menu ne lance rien." `
            -Action { Open-DomeniaResultRowSupport }))
        # CO-35: one ping (and the console when allowed) of this workstation, without leaving the list.
        [void]$Menu.Items.Add((New-DomeniaMenuItem -Header "Revérifier ce poste" -Enabled ($single -and $gridReady) `
            -ToolTip "Un seul ping de ce poste, et son utilisateur connecté si lʼoption est cochée. La liste reste affichée." `
            -Action { Request-DomeniaLiveRecheck }))
        [void]$Menu.Items.Add((New-DomeniaMenuItem -Header "Rechercher lʼutilisateur associé" -Enabled ($single -and $hasAssociation) `
            -ToolTip "Lance une recherche globale sur le compte associé à ce poste." `
            -Action { Start-DomeniaSearchAssociated -Row (Get-DomeniaSelectedGridRow) }))
    }
    elseif ($isUser) {
        [void]$Menu.Items.Add((New-DomeniaMenuItem -Header "Rechercher le poste associé" -Enabled ($single -and $hasAssociation) `
            -ToolTip "Lance une recherche globale sur le poste associé à ce compte." `
            -Action { Start-DomeniaSearchAssociated -Row (Get-DomeniaSelectedGridRow) }))
    }
    [void]$Menu.Items.Add((New-DomeniaMenuItem -Header "Ouvrir lʼOU parente" -Enabled $single `
        -ToolTip "Liste dans Rechercher le contenu de lʼOU ou du conteneur parent. Rien nʼest modifié." `
        -Action { Open-DomeniaResultRowParentOu -Row (Get-DomeniaSelectedGridRow) }))
    Add-DomeniaMenuSeparator -Menu $Menu

    $copy = New-Object System.Windows.Controls.MenuItem
    $copy.Header = "Copier"
    [void]$copy.Items.Add((New-DomeniaMenuItem -Header "Pour un ticket" `
        -ToolTip "Une ligne lisible par objet sélectionné : type, nom, compte, présence, utilisateur console et OU. Sans GUID ni champ interne." `
        -Action { Copy-DomeniaSelectedRowsForTicket }))
    [void]$copy.Items.Add((New-Object System.Windows.Controls.Separator))
    foreach ($entry in @(
        @{ H="Le nom"; P="Name" },
        @{ H="Le compte"; P="Login" },
        @{ H="LʼUPN ou le DNS"; P="UPN" },
        @{ H="Le chemin (DN)"; P="DN" }
    )) {
        $prop = [string]$entry.P
        $value = ""
        try { $value = [string]$row.$prop } catch { Write-DomeniaSwallowed 'Core' 'Build-DomeniaObjectsContextMenu' $_ }
        [void]$copy.Items.Add((New-DomeniaMenuItem -Header ([string]$entry.H) -Enabled ($single -and (-not [string]::IsNullOrWhiteSpace($value))) `
            -Action ([scriptblock]::Create('Copy-DomeniaRowProperty -Row (Get-DomeniaSelectedGridRow) -Property "' + $prop + '"'))))
    }
    [void]$copy.Items.Add((New-DomeniaMenuItem -Header "Les lignes, toutes les valeurs" -ToolTip "Toutes les valeurs des lignes sélectionnées, séparées par des tabulations, pour un tableur." -Action { Copy-DomeniaGridSelection -Name "DgObjects" }))
    [void]$copy.Items.Add((New-DomeniaMenuItem -Header "Le résumé de la fiche ouverte" -Enabled ($null -ne $script:SelectedObject) -Action { Copy-ObjectSummary }))
    [void]$Menu.Items.Add($copy)
    # Point 60: the export follows the scope chosen beside the results; the menu names that scope.
    $exportHeader = "Exporter la liste affichée en CSV"
    $exportTip = "Exporte la liste affichée, après ses filtres. La portée se choisit à côté des résultats."
    if ((Get-DomeniaResultScopeMode) -eq 'Selected') { $exportHeader = "Exporter les lignes sélectionnées en CSV"; $exportTip = "Exporte seulement les lignes sélectionnées encore affichées. La portée se choisit à côté des résultats." }
    [void]$Menu.Items.Add((New-DomeniaMenuItem -Header $exportHeader -ToolTip $exportTip -Action { Export-CurrentResults }))
}

function New-DomeniaTreeContextMenu {
    $menu = New-Object System.Windows.Controls.ContextMenu
    $menu.Add_Opened({
        param($sender,$e)
        try { Build-DomeniaTreeContextMenu -Menu $sender }
        catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaTreeContextMenu' $_ }
    })
    return $menu
}

function Build-DomeniaTreeContextMenu {
    param([Parameter(Mandatory=$true)]$Menu)
    $Menu.Items.Clear()
    $dn = [string]$script:SelectedBranchDn
    $hasBranch = -not [string]::IsNullOrWhiteSpace($dn)
    $readOnly = [bool]$script:ReadOnlyMode

    [void]$Menu.Items.Add((New-DomeniaMenuItem -Header "Afficher le contenu de cette branche" -Enabled $hasBranch -Action { Load-BranchObjects -Browse }))
    [void]$Menu.Items.Add((New-DomeniaMenuItem -Header "Actualiser l arborescence" -Action { Load-TreeRoot -ForceRefresh }))
    Add-DomeniaMenuSeparator -Menu $Menu
    [void]$Menu.Items.Add((New-DomeniaMenuItem -Header "Copier le chemin (DN)" -Enabled $hasBranch `
        -Action { if (-not [string]::IsNullOrWhiteSpace($script:SelectedBranchDn)) { Set-ClipboardSafe $script:SelectedBranchDn; Set-Status "DN copie." } }))
    Add-DomeniaMenuSeparator -Menu $Menu
    $create = New-Object System.Windows.Controls.MenuItem
    $create.Header = "Nouveau dans cette branche"
    $create.IsEnabled = ($hasBranch -and -not $readOnly)
    if ($readOnly) { $create.ToolTip = "Le mode lecture seule est actif." }
    [void]$create.Items.Add((New-DomeniaMenuItem -Header "Unite d organisation" -Action {
        # CO-27: un seul parcours. Le menu ne cueille plus le nom dans une fenetre modale, il amene
        # l'operateur sur l'onglet, ou la branche parente s'affiche avant toute confirmation.
        $tab = Get-DomeniaControl -Name 'TabContainer'
        if ($null -ne $tab -and $tab.Visibility -ne [System.Windows.Visibility]::Visible) {
            $tab.Visibility = [System.Windows.Visibility]::Visible
        }
        Select-DomeniaWorkspace -Workspace 'WsObject' -Inner 'DetailTabs' -Tab 'TabContainer'
        Update-DomeniaNewOuParentUi
        $box = Get-DomeniaControl -Name 'TxtNewOuName'
        if ($null -ne $box) { [void]$box.Focus(); $box.SelectAll() }
        Set-Status ('Nouvelle unité dʼorganisation sous ' + (Get-DomeniaOuDisplayPath ([string]$script:SelectedBranchDn)) + ' : saisissez son nom puis confirmez.')
    }))
    [void]$Menu.Items.Add($create)
    Add-DomeniaMenuSeparator -Menu $Menu
    [void]$Menu.Items.Add((New-DomeniaMenuItem -Header "Analyser les droits sur cette branche" -Enabled $hasBranch -Action { Start-PermissionAnalysis -UserInitiated }))
}

function New-DomeniaCopyContextMenu {
    # Menu generique de copie pour les grilles de rapport.
    param([Parameter(Mandatory=$true)][string]$GridName,[string[]]$Properties = @())
    $menu = New-Object System.Windows.Controls.ContextMenu
    [void]$menu.Items.Add((New-DomeniaMenuItem -Header "Copier la ou les lignes selectionnees" `
        -Action ([scriptblock]::Create('Copy-DomeniaGridSelection -Name "' + $GridName + '"'))))
    foreach ($p in @($Properties)) {
        [void]$menu.Items.Add((New-DomeniaMenuItem -Header ("Copier " + $p) `
            -Action ([scriptblock]::Create('$g = Get-DomeniaControl -Name "' + $GridName + '"; if ($null -ne $g) { Copy-DomeniaRowProperty -Row $g.SelectedItem -Property "' + $p + '" }'))))
    }
    return $menu
}

function Register-DomeniaContextMenus {
    # Branche les menus contextuels sur tous les controles qui en beneficient.
    $applied = 0
    try {
        $grid = Get-DomeniaControl -Name "DgObjects"
        if ($null -ne $grid) { $grid.ContextMenu = New-DomeniaObjectsContextMenu; $applied++ }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaContextMenus' $_ }
    try {
        $tree = Get-DomeniaControl -Name "TvDirectory"
        if ($null -ne $tree) { $tree.ContextMenu = New-DomeniaTreeContextMenu; $applied++ }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaContextMenus' $_ }

    $simple = @(
        @{ N="DgLinks"; P=@("UserLogin","Computer","Source","Details") },
        @{ N="DgLinkAttempts"; P=@("Method","User","Detail") },
        @{ N="DgRawAttrs"; P=@("Attribute","Value") },
        # DgSecrets has no generic copy menu: a revealed value is copied only by Copy-SelectedSecret (protected
        # clipboard, one value at a time, automatic clearing - D059).
        @{ N="DgComputerDiag"; P=@("Check","Detail") },
        @{ N="DgPermissions"; P=@("Capability","State","Detail") },
        @{ N="DgSelfCheck"; P=@("Test","Detail") },
        @{ N="DgInventory"; P=@("Item","Value","Source") },
        @{ N="DgInventoryAccess"; P=@("Category","Status","Detail") },
        @{ N="DgSoftware"; P=@("Name","Version","Publisher","Location","UninstallString") },
        @{ N="DgSoftwareAccess"; P=@("Category","Status","Detail") },
        @{ N="DgWmiSchema"; P=@("Property","Type","Qualifiers") },
        @{ N="DgWmiInstances"; P=@("Property","Value") },
        @{ N="DgDomain"; P=@("Item","Value") },
        @{ N="DgIndex"; P=@("Name","Login","Upn","DN") },
        @{ N="DgCmdlets"; P=@("Name","Parameters","Synopsis") }
    )
    foreach ($entry in $simple) {
        try {
            $control = Get-DomeniaControl -Name ([string]$entry.N)
            if ($null -eq $control) { continue }
            $control.ContextMenu = New-DomeniaCopyContextMenu -GridName ([string]$entry.N) -Properties @($entry.P)
            $applied++
        }
        catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaContextMenus' $_ }
    }

    # UI-06: the membership grids offer the search of the clicked object, the copy of its DN and, for the groups of the
    # fiche, « Pourquoi membre ? » and the nested groups (Membership.UI).
    try { $applied += [int](Register-DomeniaMembershipUi) } catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaContextMenus' $_ }

    Add-DomeniaUiLog -Area "Interface" -Text ("Menus contextuels actifs sur {0} controle(s)." -f $applied)
    return $applied
}


# =====================================================================
# Onglet Logiciels. La liste est constituee de trois portees collectees
# separement : installations machine, installations par profil et paquets
# du Store. Chaque portee possede sa propre ligne dans le rapport d acces.
# =====================================================================
function Get-DomeniaSoftwareWorkerCode {
    return @'
$DomeniaCollectedResult = & {
$rows = New-Object Collections.ArrayList
$access = New-Object Collections.ArrayList
$computer = [string]$Payload.Computer
$cred = Get-WMachineCredential $Context
$includePerUser = [bool]$Payload.IncludePerUser
$includeStore = [bool]$Payload.IncludeStore
$includeUpdates = [bool]$Payload.IncludeUpdates
$maxKeys = [Math]::Max(100,[int]$Payload.MaxKeys)
$watch = [System.Diagnostics.Stopwatch]::StartNew()
$session = $null
$winrmReady = $false
$fallbackTransport = ''
$fallbackTasks = 0
$taskBytes = 0

function Add-Access {
    param([string]$Category,[string]$Status,[string]$Detail,[int]$Ms,[int]$Count,[string]$Method='')
    [void]$access.Add([pscustomobject]@{ Category=$Category; Status=$Status; Method=$Method; Items=$Count; DurationMs=$Ms; Detail=$Detail })
}
function Get-FailureStatus {
    param([string]$Message)
    if ($Message -match '(?i)access is denied|acces refuse|refus|denied|0x80070005|authoris') { return 'REFUSE' }
    if ($Message -match '(?i)invalid class|invalid namespace|not supported|introuvable|not found|non pris en charge') { return 'INDISPONIBLE' }
    if ($Message -match '(?i)timeout|delai|expire|RPC server is unavailable|serveur RPC|WinRM cannot') { return 'INJOIGNABLE' }
    return 'ERREUR'
}
function Format-Size {
    param($Bytes)
    $v = 0.0
    try { $v = [double]$Bytes } catch { return '' }
    if ($v -le 0) { return '' }
    $units = @('o','Ko','Mo','Go','To')
    $i = 0
    while ($v -ge 1024 -and $i -lt 4) { $v = $v / 1024.0; $i++ }
    return ('' + [Math]::Round($v,1) + ' ' + $units[$i])
}
function Convert-InstallDate {
    param($Value)
    $text = ([string]$Value).Trim()
    if ([string]::IsNullOrWhiteSpace($text)) { return '' }
    if ($text -match '^\d{8}$') {
        try {
            $y = $text.Substring(0,4)
            $m = $text.Substring(4,2)
            $d = $text.Substring(6,2)
            return ($d + '/' + $m + '/' + $y)
        }
        catch { return $text }
    }
    try { return ([datetime]$text).ToString('dd/MM/yyyy') } catch { return $text }
}
$seen = @{}
$seenProducts = @{}
function Add-Software {
    param(
        [string]$Name,[string]$Version,[string]$Publisher,$InstallDate,$SizeKb,
        [string]$Location,[string]$Architecture,[string]$Scope,[string]$Kind,
        [string]$UninstallString,[string]$Source,[string]$Owner = ''
    )
    $clean = ([string]$Name).Trim()
    if ([string]::IsNullOrWhiteSpace($clean)) { return }
    # Point 91: one row per uninstall entry of a scope, an architecture and, for the user scope, a profile. The same
    # product installed in both registry views or for two users stays two rows: duplicates are shown, not merged.
    # The profile is keyed by its SID when the source gives it, so two transports naming one account differently
    # still meet. A source without architecture (SCCM) cannot tell the registry views apart: its row and any row
    # of the same product merge, in either order, so a later transport never lists the same entry twice.
    # PowerShell names are case-insensitive: the keys below never reuse a parameter name ($Owner, $Architecture).
    $ownerKey = ''
    if ($Scope -eq 'Utilisateur') { $ownerKey = if (-not [string]::IsNullOrWhiteSpace($Owner)) { $Owner.Trim() } else { [string]$Kind } }
    $archKey = ([string]$Architecture).Trim()
    $key = ($Scope + '|' + $ownerKey + '|' + $archKey + '|' + $clean + '|' + [string]$Version).ToLowerInvariant()
    if ($seen.ContainsKey($key)) { return }
    $product = ($Scope + '|' + $ownerKey + '|' + $clean + '|' + [string]$Version).ToLowerInvariant()
    if ($seenProducts.ContainsKey($product)) {
        if ((-not $archKey) -or ($seenProducts[$product].ContainsKey(''))) { return }
    }
    else { $seenProducts[$product] = @{} }
    $seen[$key] = $true
    $seenProducts[$product][$archKey.ToLowerInvariant()] = $true
    $size = ''
    try { if ([double]$SizeKb -gt 0) { $size = Format-Size ([double]$SizeKb * 1024) } } catch { }
    [void]$rows.Add([pscustomobject]@{
        Name = $clean
        Version = ([string]$Version).Trim()
        Publisher = ([string]$Publisher).Trim()
        InstallDate = Convert-InstallDate $InstallDate
        Size = $size
        SizeKb = $(try { [double]$SizeKb } catch { 0.0 })
        Scope = $Scope
        Architecture = $Architecture
        Kind = $Kind
        Location = ([string]$Location).Trim()
        UninstallString = ([string]$UninstallString).Trim()
        Source = $Source
    })
}

function New-SoftwareSession {
    param([string]$Protocol,[int]$TimeoutSeconds = 18)
    $option = New-CimSessionOption -Protocol $Protocol -ErrorAction Stop
    $params = @{ ComputerName=$computer; SessionOption=$option; ErrorAction='Stop' }
    if ($null -ne $cred) { $params['Credential'] = $cred }
    try {
        $command = Get-Command New-CimSession -ErrorAction Stop
        if ($command.Parameters.ContainsKey('OperationTimeoutSec')) { $params['OperationTimeoutSec'] = [Math]::Max(2,$TimeoutSeconds) }
    }
    catch { }
    $lease=Enter-WCredentialAttempt -Context $Context -Channel Remote;$opened=$null
    try{
        Assert-WCredentialAllowed -Context $Context -Channel Remote
        $opened=New-CimSession @params
        # DCOM session creation is lazy: validate the first authenticated operation while the account lease is held.
        [void](Get-CimInstance -CimSession $opened -ClassName Win32_OperatingSystem -Property CSName -OperationTimeoutSec ([Math]::Max(2,$TimeoutSeconds)) -ErrorAction Stop)
        return $opened
    }catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);if($null -ne $opened){Remove-CimSession $opened -ErrorAction Ignore};throw}
    finally{Exit-WCredentialAttempt -Lease $lease}
}
function Invoke-Remote {
    param([Parameter(Mandatory=$true)][scriptblock]$ScriptBlock,[int]$TimeoutSeconds = 40,$ArgumentList = @())
    $option = New-PSSessionOption -OpenTimeout ($TimeoutSeconds * 1000) -OperationTimeout ($TimeoutSeconds * 1000)
    $params = @{ ComputerName=$computer; ScriptBlock=$ScriptBlock; SessionOption=$option; ErrorAction='Stop' }
    if (@($ArgumentList).Count -gt 0) { $params['ArgumentList'] = $ArgumentList }
    if ($null -ne $cred) { $params['Credential'] = $cred; $params['Authentication'] = 'Default' }
    $lease=Enter-WCredentialAttempt -Context $Context -Channel Remote
    try{Assert-WCredentialAllowed -Context $Context -Channel Remote;return @(Invoke-Command @params)}catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}finally{Exit-WCredentialAttempt -Lease $lease}
}

$HKLM = [uint32]2147483650
function Get-RegString {
    param([uint32]$Hive,[string]$Key,[string]$Name)
    Assert-WCredentialAllowed -Context $Context -Channel Remote
    try{$r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'GetStringValue' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key; sValueName=$Name } -ErrorAction Stop}catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}
    if ([int]$r.ReturnValue -ne 0) { return '' }
    return [string]$r.sValue
}
function Get-RegDword {
    param([uint32]$Hive,[string]$Key,[string]$Name)
    Assert-WCredentialAllowed -Context $Context -Channel Remote
    try{$r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'GetDWORDValue' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key; sValueName=$Name } -ErrorAction Stop}catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}
    if ([int]$r.ReturnValue -ne 0) { return 0 }
    return $r.uValue
}
function Get-RegSubKeys {
    param([uint32]$Hive,[string]$Key)
    $r = Invoke-CimMethod -CimSession $session -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'EnumKey' -Arguments @{ hDefKey=$Hive; sSubKeyName=$Key } -ErrorAction Stop
    if ([int]$r.ReturnValue -ne 0) { return @() }
    return @($r.sNames)
}

# ---------------------------------------------------------------------
# Joignabilite et transports
# ---------------------------------------------------------------------
$probe = [System.Diagnostics.Stopwatch]::StartNew()
$dcomOpen = $false
$winrmOpen = $false
try { $dcomOpen = Test-WTcpPort $computer 135 1800 } catch { }
try { $winrmOpen = Test-WTcpPort $computer 5985 1800 } catch { }
if (-not $winrmOpen) { try { $winrmOpen = Test-WTcpPort $computer 5986 1500 } catch { } }
$probe.Stop()
$winrmReady = $winrmOpen
if (-not $dcomOpen -and -not $winrmOpen) {
    # V10.22 : l absence de WMI/WinRM n est PAS une fin de traitement.
    # On journalise l echec classique puis on continue jusqu au fallback
    # PsExec, puis Task Scheduler.
    Add-Access 'Joignabilite' 'INJOIGNABLE' 'Ni RPC 135 ni WinRM 5985/5986 ne repondent. Passage aux fallbacks.' ([int]$probe.ElapsedMilliseconds) 0 'TCP'
}
else {
    Add-Access 'Joignabilite' 'OK' ('DCOM ouvert : ' + $dcomOpen + '. WinRM ouvert : ' + $winrmOpen + '.') ([int]$probe.ElapsedMilliseconds) 0 'TCP'
}

$sessionProtocol = ''
$sessionWatch = [System.Diagnostics.Stopwatch]::StartNew()
foreach ($candidate in @('Dcom','Wsman')) {
    if ($candidate -eq 'Dcom' -and -not $dcomOpen) { continue }
    if ($candidate -eq 'Wsman' -and -not $winrmOpen) { continue }
    try { $session = New-SoftwareSession $candidate 18; $sessionProtocol = $candidate; break } catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw} }
}
$sessionWatch.Stop()
if ($null -eq $session) {
    Add-Access 'Connexion CIM' 'INJOIGNABLE' 'Aucune session CIM ouverte.' ([int]$sessionWatch.ElapsedMilliseconds) 0 'CIM'
}
else {
    Add-Access 'Connexion CIM' 'OK' ('Session CIM ouverte via ' + $sessionProtocol + '.') ([int]$sessionWatch.ElapsedMilliseconds) 0 ('CIM/' + $sessionProtocol)
}

try {
    # -----------------------------------------------------------------
    # Portee machine. Trois chemins par ordre de cout croissant.
    # -----------------------------------------------------------------
    $machineWatch = [System.Diagnostics.Stopwatch]::StartNew()
    $machineBefore = $rows.Count
    $machineSource = ''
    $machineDetail = ''
    $machineStatus = 'OK'

    if ($winrmReady) {
        try {
            $remote = Invoke-Remote -TimeoutSeconds 45 -ScriptBlock {
                $out = New-Object System.Collections.ArrayList
                $map = @(
                    @{ Path='HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'; Arch='x64' },
                    @{ Path='HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'; Arch='x86' }
                )
                foreach ($m in $map) {
                    foreach ($p in (Get-ItemProperty -Path $m.Path -ErrorAction SilentlyContinue)) {
                        if (-not $p.DisplayName) { continue }
                        [void]$out.Add([pscustomobject]@{
                            DisplayName = $p.DisplayName
                            DisplayVersion = $p.DisplayVersion
                            Publisher = $p.Publisher
                            InstallDate = $p.InstallDate
                            EstimatedSize = $p.EstimatedSize
                            InstallLocation = $p.InstallLocation
                            UninstallString = $p.UninstallString
                            SystemComponent = $p.SystemComponent
                            ReleaseType = $p.ReleaseType
                            ParentKeyName = $p.ParentKeyName
                            WindowsInstaller = $p.WindowsInstaller
                            Architecture = $m.Arch
                        })
                    }
                }
                return $out.ToArray()
            }
            foreach ($p in @($remote)) {
                $isUpdate = $false
                try { if ([int]$p.SystemComponent -eq 1) { $isUpdate = $true } } catch { }
                if (-not [string]::IsNullOrWhiteSpace([string]$p.ParentKeyName)) { $isUpdate = $true }
                if (([string]$p.ReleaseType) -match '(?i)update|hotfix|security') { $isUpdate = $true }
                if ($isUpdate -and -not $includeUpdates) { continue }
                $kind = 'Application'
                if ($isUpdate) { $kind = 'Mise a jour' }
                elseif (([string]$p.WindowsInstaller) -eq '1') { $kind = 'Paquet MSI' }
                Add-Software -Name ([string]$p.DisplayName) -Version ([string]$p.DisplayVersion) -Publisher ([string]$p.Publisher) `
                    -InstallDate $p.InstallDate -SizeKb $p.EstimatedSize -Location ([string]$p.InstallLocation) `
                    -Architecture ([string]$p.Architecture) -Scope 'Machine' -Kind $kind `
                    -UninstallString ([string]$p.UninstallString) -Source 'Registre via WinRM'
            }
            if ($rows.Count -gt $machineBefore) { $machineSource = 'WinRM'; $machineDetail = 'Un seul aller-retour pour les deux ruches.' }
        }
        catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};$machineDetail = 'WinRM indisponible : ' + [string]$_.Exception.Message }
    }

    if ([string]::IsNullOrWhiteSpace($machineSource) -and $null -ne $session) {
        try {
            foreach ($p in @(Get-CimInstance -CimSession $session -ClassName 'Win32Reg_AddRemovePrograms' -ErrorAction Stop)) {
                if ([string]::IsNullOrWhiteSpace([string]$p.DisplayName)) { continue }
                Add-Software -Name ([string]$p.DisplayName) -Version ([string]$p.Version) -Publisher ([string]$p.Publisher) `
                    -InstallDate $p.InstallDate -SizeKb 0 -Location '' -Architecture '' -Scope 'Machine' -Kind 'Application' `
                    -UninstallString '' -Source 'Win32Reg_AddRemovePrograms'
            }
            if ($rows.Count -gt $machineBefore) { $machineSource = 'SCCM'; $machineDetail = 'Inventaire SCCM present, une seule requete.' }
        }
        catch { }
    }

    if ([string]::IsNullOrWhiteSpace($machineSource) -and $null -ne $session) {
        $machineSource = 'Registre unitaire'
        $scanned = 0
        $stopped = $false
        foreach ($base in @(
            @{ Key='SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall'; Arch='x64' },
            @{ Key='SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'; Arch='x86' }
        )) {
            if ($stopped) { break }
            $subKeys = @()
            try { $subKeys = Get-RegSubKeys $HKLM ([string]$base.Key) } catch { continue }
            foreach ($sub in $subKeys) {
                if ($scanned -ge $maxKeys) { $machineStatus = 'PARTIEL'; $machineDetail = 'Lecture arretee apres ' + $maxKeys + ' cles.'; $stopped = $true; break }
                $scanned++
                $key = [string]$base.Key + '\' + [string]$sub
                $display = ''
                try { $display = Get-RegString $HKLM $key 'DisplayName' } catch { continue }
                if ([string]::IsNullOrWhiteSpace($display)) { continue }
                $version = ''
                $publisher = ''
                $installDate = ''
                $location = ''
                $uninstall = ''
                $size = 0
                try { $version = Get-RegString $HKLM $key 'DisplayVersion' } catch { }
                try { $publisher = Get-RegString $HKLM $key 'Publisher' } catch { }
                try { $installDate = Get-RegString $HKLM $key 'InstallDate' } catch { }
                try { $location = Get-RegString $HKLM $key 'InstallLocation' } catch { }
                try { $uninstall = Get-RegString $HKLM $key 'UninstallString' } catch { }
                try { $size = Get-RegDword $HKLM $key 'EstimatedSize' } catch { }
                Add-Software -Name $display -Version $version -Publisher $publisher -InstallDate $installDate `
                    -SizeKb $size -Location $location -Architecture ([string]$base.Arch) -Scope 'Machine' -Kind 'Application' `
                    -UninstallString $uninstall -Source 'Registre Uninstall'
            }
        }
        if ([string]::IsNullOrWhiteSpace($machineDetail)) { $machineDetail = 'Lecture cle par cle : ' + $scanned + ' cle(s) parcourue(s).' }
    }

    $machineWatch.Stop()
    $machineCount = $rows.Count - $machineBefore
    if ($machineCount -eq 0 -and $machineStatus -eq 'OK') { $machineStatus = 'VIDE' }
    $machineMethod = if ($machineSource -eq 'WinRM') { 'WinRM' } elseif ($machineSource -in @('SCCM','Registre unitaire')) { 'CIM/' + $sessionProtocol } else { 'Classique' }
    Add-Access 'Machine' $machineStatus $machineDetail ([int]$machineWatch.ElapsedMilliseconds) $machineCount $machineMethod

    # -----------------------------------------------------------------
    # Portee utilisateur
    # -----------------------------------------------------------------
    if ($includePerUser) {
        # HKU (0x80000003) par StdRegProv, sur la session CIM deja ouverte. Une ruche n'est montee que
        # pour un profil en session : les ruches chargees sont les utilisateurs connectes, et c'est tout
        # ce que cette portee promet. WinRM n'est pas exige ici ; un echec se rend « non lu », sans repli.
        $HKU = [uint32]2147483651
        $userWatch = [System.Diagnostics.Stopwatch]::StartNew()
        $userBefore = $rows.Count
        if ($null -eq $session) {
            $userWatch.Stop()
            Add-Access 'Utilisateur' 'INDISPONIBLE' 'Non lu : aucune session CIM ouverte pour lire HKU.' ([int]$userWatch.ElapsedMilliseconds) 0 'CIM'
        }
        else {
            try {
                $userHives = 0
                $userScanned = 0
                $userStopped = ''
                foreach ($sid in @(Get-RegSubKeys $HKU '' | Where-Object { [string]$_ -match '^S-1-5-21-' })) {
                    $userHives++
                    $account = [string]$sid
                    try {
                        $acct = @(Get-CimInstance -CimSession $session -ClassName 'Win32_UserAccount' -Filter ('SID="' + [string]$sid + '"') -ErrorAction Stop | Select-Object -First 1)
                        if (@($acct).Count -gt 0) { $account = [string]$acct[0].Domain + '\' + [string]$acct[0].Name }
                    } catch { }
                    $base = [string]$sid + '\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall'
                    $subKeys = @()
                    try { $subKeys = @(Get-RegSubKeys $HKU $base) } catch { }
                    foreach ($sub in $subKeys) {
                        if ($userScanned -ge $maxKeys) { $userStopped = 'Lecture arretee apres ' + [string]$maxKeys + ' cles.'; break }
                        $userScanned++
                        $key = $base + '\' + [string]$sub
                        $display = ''
                        try { $display = Get-RegString $HKU $key 'DisplayName' } catch { continue }
                        if ([string]::IsNullOrWhiteSpace($display)) { continue }
                        $version = ''
                        $publisher = ''
                        $installDate = ''
                        $location = ''
                        $uninstall = ''
                        $size = 0
                        try { $version = Get-RegString $HKU $key 'DisplayVersion' } catch { }
                        try { $publisher = Get-RegString $HKU $key 'Publisher' } catch { }
                        try { $installDate = Get-RegString $HKU $key 'InstallDate' } catch { }
                        try { $location = Get-RegString $HKU $key 'InstallLocation' } catch { }
                        try { $uninstall = Get-RegString $HKU $key 'UninstallString' } catch { }
                        try { $size = Get-RegDword $HKU $key 'EstimatedSize' } catch { }
                        Add-Software -Name $display -Version $version -Publisher $publisher -InstallDate $installDate `
                            -SizeKb $size -Location $location -Architecture '' -Scope 'Utilisateur' -Kind $account `
                            -UninstallString $uninstall -Source 'HKU via StdRegProv' -Owner ([string]$sid)
                    }
                    if ($userStopped -ne '') { break }
                }
                $userWatch.Stop()
                $count = $rows.Count - $userBefore
                $status = 'OK'
                if ($count -eq 0) { $status = 'VIDE' }
                $detail = 'Ruches chargees sous HKU : ' + [string]$userHives + ' profil(s) monte(s), ' + [string]$userScanned + ' cle(s) parcourue(s).'
                if ($userStopped -ne '') { $status = 'PARTIEL'; $detail = $userStopped }
                Add-Access 'Utilisateur' $status $detail ([int]$userWatch.ElapsedMilliseconds) $count ('CIM/' + $sessionProtocol)
            }
            catch {
                $userWatch.Stop()
                $message = [string]$_.Exception.Message
                Add-Access 'Utilisateur' (Get-FailureStatus $message) ('Non lu : ' + $message) ([int]$userWatch.ElapsedMilliseconds) ($rows.Count - $userBefore) ('CIM/' + $sessionProtocol)
            }
        }
    }

    # -----------------------------------------------------------------
    # Applications du Store
    # -----------------------------------------------------------------
    if ($includeStore) {
        $storeWatch = [System.Diagnostics.Stopwatch]::StartNew()
        $storeBefore = $rows.Count
        if (-not $winrmReady) {
            $storeWatch.Stop()
            Add-Access 'Store' 'INDISPONIBLE' 'La lecture des paquets Appx necessite WinRM.' ([int]$storeWatch.ElapsedMilliseconds) 0 'WinRM'
        }
        else {
            try {
                $remote = Invoke-Remote -TimeoutSeconds 60 -ScriptBlock {
                    Get-AppxPackage -AllUsers -ErrorAction SilentlyContinue |
                        Select-Object Name,Publisher,Version,InstallLocation,Architecture,IsFramework
                }
                foreach ($p in @($remote)) {
                    $kind = 'Application Store'
                    try { if ([bool]$p.IsFramework) { $kind = 'Framework Store' } } catch { }
                    Add-Software -Name ([string]$p.Name) -Version ([string]$p.Version) -Publisher ([string]$p.Publisher) `
                        -InstallDate '' -SizeKb 0 -Location ([string]$p.InstallLocation) `
                        -Architecture ([string]$p.Architecture) -Scope 'Store' -Kind $kind `
                        -UninstallString '' -Source 'Get-AppxPackage via WinRM'
                }
                $storeWatch.Stop()
                $count = $rows.Count - $storeBefore
                $status = 'OK'
                if ($count -eq 0) { $status = 'VIDE' }
                Add-Access 'Store' $status 'Paquets Appx tous utilisateurs.' ([int]$storeWatch.ElapsedMilliseconds) $count 'WinRM'
            }
            catch {
                $storeWatch.Stop()
                $message = [string]$_.Exception.Message
                Add-Access 'Store' (Get-FailureStatus $message) $message ([int]$storeWatch.ElapsedMilliseconds) ($rows.Count - $storeBefore) 'WinRM'
            }
        }
    }
}
finally {
    try { Remove-WDomeniaCimSession $session } catch { }
}

# Si les transports classiques n'ont pas rendu les portees demandees,
# une seule tache locale complete la collecte. Add-Software deduplique : profil par SID, ligne sans
# architecture (SCCM) fusionnee avec la meme entree lue ensuite par x64 ou x86.
$needTask = ($rows.Count -eq 0)
# MO-09 : une portee utilisateur vide n'est pas un echec, c'est souvent qu'aucun utilisateur n'est
# connecte. Elle ne declenche plus la collecte locale SYSTEM ; seul un inventaire machine entierement
# vide la declenche encore.
if ($includeStore -and @($rows | Where-Object {[string]$_.Scope -eq 'Store'}).Count -eq 0) { $needTask=$true }
if ($needTask) {
    try {
        $classic='Inventaire logiciel classique vide ou incomplet.'
        $local=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
        $fb=Invoke-WRemoteTaskScript $Context $computer $local ([pscustomobject]@{IncludePerUser=$includePerUser;IncludeStore=$includeStore;IncludeUpdates=$includeUpdates}) ([Math]::Min(90,[int]$Context.TaskFallbackTimeoutSeconds)) $classic
        $fallbackLabel=if([string]$fb.DomeniaTransport -eq 'PsExec'){'PsExec'}else{'TaskScheduler'}
        $fallbackTransport = $fallbackLabel
        foreach($p in @($fb.Rows)) { Add-Software -Name ([string]$p.Name) -Version ([string]$p.Version) -Publisher ([string]$p.Publisher) -InstallDate $p.InstallDate -SizeKb $p.SizeKb -Location ([string]$p.Location) -Architecture ([string]$p.Architecture) -Scope ([string]$p.Scope) -Kind ([string]$p.Kind) -UninstallString ([string]$p.UninstallString) -Source ($fallbackLabel+' local SYSTEM / '+[string]$p.Source) -Owner ([string]$p.Owner) }
        $fallbackTasks=if($fallbackLabel -eq 'TaskScheduler'){1}else{0};try{$taskBytes=[long]$fb.DomeniaBytesSent+[long]$fb.DomeniaBytesReceived}catch{}
        $fbCount = @($fb.Rows).Count
        $fbStatus = if ($fbCount -gt 0) { 'OK' } else { 'VIDE' }
        Add-Access ('Fallback '+$fallbackLabel) $fbStatus ('Collecte locale SYSTEM executee via '+$fallbackLabel+'.') 0 $fbCount $fallbackLabel
    }
    catch { Add-Access 'Fallbacks PsExec / tache' (Get-FailureStatus ([string]$_.Exception.Message)) ([string]$_.Exception.Message) 0 0 'PsExec -> TaskScheduler' }
}

$watch.Stop()
[pscustomobject]@{
    Computer = $computer
    Rows = @($rows)
    Access = @($access)
    DurationMs = [long]$watch.ElapsedMilliseconds
    Success = ($rows.Count -gt 0)
    FallbackTransport = $fallbackTransport
    FallbackTasks = $fallbackTasks
    TaskBytes = $taskBytes
}

}
foreach($DomeniaCollectedItem in @($DomeniaCollectedResult)){if($null -ne $DomeniaCollectedItem -and $DomeniaCollectedItem -isnot [string] -and $DomeniaCollectedItem -isnot [ValueType]){$DomeniaCollectedItem|Add-Member -NotePropertyName SourceCompletedUtc -NotePropertyValue ([datetime]::UtcNow.ToString('o')) -Force};$DomeniaCollectedItem}

'@
}

function Apply-DomeniaSoftwareFilter {
    try {
        $rows = @($script:SoftwareRows)
        $scope = [string]$script:SoftwareScope
        if (-not [string]::IsNullOrWhiteSpace($scope) -and $scope -ne "Toutes") {
            $rows = @($rows | Where-Object { [string]$_.Scope -eq $scope })
        }
        # FO-09 : le critere venu d'un clic sur un graphique s'ajoute aux deux autres, il ne les remplace pas.
        $select = $script:SoftwareChartSelect
        if ($null -ne $select) { $rows = @($rows | Where-Object { Test-DomeniaSoftwareRowMatchesSelect -Row $_ -Select $select }) }
        $filter = ""
        try { $filter = ([string](Get-DomeniaControl -Name "TxtSoftwareFilter").Text).Trim() } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaSoftwareFilter' $_ }
        if (-not [string]::IsNullOrWhiteSpace($filter)) {
            $rows = @($rows | Where-Object {
                ([string]$_.Name -like ("*" + $filter + "*")) -or
                ([string]$_.Publisher -like ("*" + $filter + "*")) -or
                ([string]$_.Version -like ("*" + $filter + "*")) -or
                ([string]$_.Location -like ("*" + $filter + "*"))
            })
        }
        # CO-03 : le worker Logiciels (corps epingle) publie InstallDate en texte et SizeKb en nombre.
        # La cle datee est ajoutee a l entree de la grille, sans toucher au corps epingle.
        foreach ($row in @($rows | Where-Object { $null -ne $_ })) { [void](Add-DomeniaGridDateKeys -Row $row -Fields @('InstallDate')) }
        [void](Set-DomeniaGridRows -Name "DgSoftware" -Rows $rows -KeyProperty "Name")
        $total = @($script:SoftwareRows).Count
        $statusText = ("{0} logiciel(s) affiche(s) sur {1}." -f @($rows).Count,$total)
        # La provenance se relit apres chaque filtre : une liste reprise de l'inventaire ne doit jamais
        # se presenter comme le resultat d'une lecture des logiciels.
        if (-not [string]::IsNullOrWhiteSpace([string]$script:SoftwareProvenance)) {
            $statusText = $statusText + ' ' + [string]$script:SoftwareProvenance
        }
        [void](Set-DomeniaControlText -Name "LblSoftwareStatus" -Text $statusText)
        Update-DomeniaSoftwareFilterChip
    }
    catch { Add-DomeniaUiLog -Level "ERROR" -Area "Logiciels" -Text $_.Exception.Message }
}

function Complete-DomeniaSoftwareUi {
    param($Result,$State)
    if(-not (Test-DomeniaClassicResultCurrent $Result $State)){return}
    if (([string]::IsNullOrWhiteSpace([string]$State.DN)) -or (([string]$State.DN) -ine ([string]$script:SelectedObject.DN))) { return }
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Access")
    if ($null -eq $effective) { throw "Resultat logiciels vide ou invalide." }
    $script:SoftwareRows = @($effective.Rows)
    # Lecture complete : la provenance n'est plus l'inventaire, les colonnes reprennent leur place.
    $script:SoftwareSource = "Poste"
    $script:SoftwareProvenance = ""
    Update-DomeniaSoftwareColumnVisibility
    try { Update-DomeniaSoftwareDashboard -Rows $script:SoftwareRows } catch { Add-DomeniaUiLog -Area "Tableau de bord" -Level "WARN" -Text ("Synthese des logiciels non construite : " + $_.Exception.Message) }
    $script:SoftwareAccess = @($effective.Access)
    [void](Set-DomeniaItemsSource -Name "DgSoftwareAccess" -Rows $script:SoftwareAccess)
    Update-DomeniaSoftwareAccessSummary
    Apply-DomeniaSoftwareFilter

    $machine = @($script:SoftwareRows | Where-Object { [string]$_.Scope -eq "Machine" }).Count
    $user = @($script:SoftwareRows | Where-Object { [string]$_.Scope -eq "Utilisateur" }).Count
    $store = @($script:SoftwareRows | Where-Object { [string]$_.Scope -eq "Store" }).Count
    $summary = "{0} : {1} logiciel(s) au total, dont {2} machine, {3} utilisateur et {4} Store, en {5} ms." -f `
        ([string]$State.Computer),@($script:SoftwareRows).Count,$machine,$user,$store,([long]$effective.DurationMs)
    Set-Status $summary
    Add-DomeniaUiLog -Area "Logiciels" -Text $summary
    $softwareMethods = New-Object System.Collections.Generic.List[string]
    # Les methodes sont desormais remontees explicitement par le worker.
    # Ne jamais deduire WinRM a partir de "WinRM ouvert : False".
    foreach($a in @($script:SoftwareAccess | Where-Object { [string]$_.Status -in @("OK","VIDE","PARTIEL") })) {
        $m = ([string]$a.Method).Trim()
        if ([string]::IsNullOrWhiteSpace($m) -or $m -eq "TCP" -or $m -eq "Classique") { continue }
        if (-not $softwareMethods.Contains($m)) { $softwareMethods.Add($m) }
    }
    foreach($r in @($script:SoftwareRows)) {
        $src = [string]$r.Source
        $m = ""
        if ($src -match '(?i)PsExec') { $m = "PsExec" }
        elseif ($src -match '(?i)Tache planifiee|TaskScheduler') { $m = "TaskScheduler" }
        elseif ($src -match '(?i)WinRM') { $m = "WinRM" }
        elseif ($src -match '(?i)Win32Reg|Registre Uninstall|SCCM') { $m = "CIM/Registre" }
        if ($m -and -not $softwareMethods.Contains($m)) { $softwareMethods.Add($m) }
    }
    if($softwareMethods.Count -gt 0){
        Add-DomeniaUiLog -Area "Logiciels" -Text ("{0} : methode(s) reellement utilisee(s) = {1}." -f [string]$State.Computer,($softwareMethods -join ", "))
    } else {
        Add-DomeniaUiLog -Area "Logiciels" -Level "WARN" -Text ("{0} : aucune methode d'acquisition n'a retourne de donnees." -f [string]$State.Computer)
    }
    $sampleMode = "Classic"
    try {
        if ([string]$effective.FallbackTransport -eq "PsExec") { $sampleMode = "Classic+PsExec" }
        elseif ([string]$effective.FallbackTransport -eq "TaskScheduler") { $sampleMode = "Classic+TaskScheduler" }
    } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaSoftwareUi' $_ }
    try { Register-DomeniaOperationSample -Operation "SoftwareInventory" -Mode $sampleMode -ItemCount 1 -DurationMs ([long]$effective.DurationMs) -BytesEstimated $(if([long]$effective.TaskBytes -gt 0){[long]$effective.TaskBytes}else{500000}) -RemoteAttempts 1 -FallbackTasks ([int]$effective.FallbackTasks) -SuccessCount $(if(@($script:SoftwareRows).Count -gt 0){1}else{0}) -FailureCount $(if(@($script:SoftwareRows).Count -gt 0){0}else{1}) } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaSoftwareUi' $_ }
}

function Fail-DomeniaSoftwareUi {
    param($Message,$State)
    if(-not (Test-DomeniaClassicResultCurrent -State $State -ContextOnly)){return}
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue." }
    # Une lecture ratee reste ratee : l'onglet ne se remplit pas avec l'inventaire par-dessus l'echec.
    Update-DomeniaSoftwareAccessSummary
    [void](Set-DomeniaControlText -Name "LblSoftwareStatus" -Text ("Lecture impossible : " + $detail))
    Set-Status ("Lecture des logiciels impossible : " + $detail) "ERROR"
    Add-DomeniaUiLog -Area "Logiciels" -Level "ERROR" -Text $detail
}

function Update-DomeniaSoftwareColumnVisibility {
    # Une seule fonction decide de la visibilite des colonnes, pour que le bouton « Colonnes » et la
    # provenance de la liste ne se contredisent jamais : ce que la lecture a vraiment fourni, et ce que
    # l'operateur reclame. La table est dans le modele (Get-DomeniaSoftwareColumnVisibility), testee.
    $grid = Get-DomeniaControl -Name 'DgSoftware'
    if ($null -eq $grid) { return }
    $technique = $false
    try {
        $bouton = Get-DomeniaControl -Name 'BtnSoftwareColumns'
        if ($null -ne $bouton) { $technique = [bool]$bouton.IsChecked }
    } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSoftwareColumnVisibility' $_ }
    $entetes = @()
    foreach ($column in @($grid.Columns)) { $entetes += [string]$column.Header }
    $visibilites = Get-DomeniaSoftwareColumnVisibility -Headers $entetes -FromInventory ([bool](([string]$script:SoftwareSource) -eq 'Inventaire')) -ShowTechnical $technique
    foreach ($column in @($grid.Columns)) {
        $header = [string]$column.Header
        if (-not $visibilites.ContainsKey($header)) { continue }
        if ($visibilites[$header]) { $column.Visibility = [System.Windows.Visibility]::Visible }
        else { $column.Visibility = [System.Windows.Visibility]::Collapsed }
    }
}

function Update-DomeniaSoftwareSyntheseVisibility {
    # Le selecteur « Liste | Synthese » est la seule commande de l'affichage de l'onglet : la liste reste
    # ce que l'operateur voit par defaut, les graphiques ne se montrent que sur demande.
    $panneau = Get-DomeniaControl -Name 'PnlSoftwareSynthese'
    if ($null -eq $panneau) { return }
    $synthese = $false
    try {
        $selecteur = Get-DomeniaControl -Name 'CmbSoftwareView'
        if ($null -ne $selecteur) { $synthese = ([int]$selecteur.SelectedIndex -eq 1) }
    } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSoftwareSyntheseVisibility' $_ }
    if ($synthese) { $panneau.Visibility = [System.Windows.Visibility]::Visible }
    else { $panneau.Visibility = [System.Windows.Visibility]::Collapsed }
}

function Update-DomeniaSoftwareAccessSummary {
    # Le detail par portee tient en une ligne, reprise de ce que le worker a rapporte. Rien n'est invente
    # quand aucune portee n'a ete lue : le texte par defaut est « Aucune portee lue. ».
    [void](Set-DomeniaControlText -Name 'LblSoftwareAccessSummary' -Text ([string](Get-DomeniaSoftwareAccessSummary -Rows $script:SoftwareAccess)))
}

function Update-DomeniaSoftwareFilterChip {
    # La pastille est la seule trace du filtre venu d'un graphique : le selecteur de portee, lui, reste visible
    # dans la barre d'outils. Pas de filtre, pas de pastille ; le texte de la pastille est une regle pure du modele.
    $texte = [string](Get-DomeniaSoftwareSelectLabel -Select $script:SoftwareChartSelect)
    [void](Set-DomeniaControlText -Name 'LblSoftwareFilterChip' -Text $texte)
    $pastille = Get-DomeniaControl -Name 'UxSoftwareFilterChip'
    if ($null -eq $pastille) { return }
    if ($texte) { $pastille.Visibility = [System.Windows.Visibility]::Visible }
    else { $pastille.Visibility = [System.Windows.Visibility]::Collapsed }
}

function Request-DomeniaSoftwareChartFilter {
    # FO-09 : un clic sur une part ou une barre filtre la liste, un second clic sur la meme part le retire.
    # La portee a deja son selecteur dans l'onglet : le clic le pilote au lieu d'empiler un second filtre sur le
    # meme champ, qui viderait la grille sans que rien ne le dise. Les autres criteres n'ont pas de temoins
    # visible : c'est la pastille qui les montre.
    param($Select)
    try {
        if ($null -eq $Select) { return }
        if (([string]$Select.Field) -eq 'Scope') {
            $suivant = 'Toutes'
            if (([string]$script:SoftwareScope) -ine ([string]$Select.Value)) { $suivant = [string]$Select.Value }
            [void](Set-DomeniaComboByContent -Name 'CmbSoftwareScope' -Content $suivant)
            return
        }
        $script:SoftwareChartSelect = Get-DomeniaSoftwareSelectToggle -Current $script:SoftwareChartSelect -Incoming $Select
        Update-DomeniaSoftwareFilterChip
        Apply-DomeniaSoftwareFilter
    } catch { Add-DomeniaUiLog -Area 'Logiciels' -Level 'ERROR' -Text $_.Exception.Message }
}

function Clear-DomeniaSoftwareChartFilter {
    # Le bouton « ✕ » de la pastille. Le filtre ne survit pas non plus a une nouvelle lecture ni a
    # un nouveau poste : la liste qu'il decrivait n'existe plus.
    $script:SoftwareChartSelect = $null
    Update-DomeniaSoftwareFilterChip
    Apply-DomeniaSoftwareFilter
}

function Show-DomeniaSoftwareFromInventory {
    # Appelle a l'ouverture de l'onglet, jamais pendant une lecture en cours : une liste qui se
    # remplit sous les yeux de l'operateur ne se explique plus.
    if ([string]$script:SoftwareSource -ne '') { return }
    if (@($script:SoftwareRows).Count -gt 0) { return }
    if (@($script:InventoryRows).Count -eq 0) { return }
    if (([string]$script:InventoryComputer) -ine ([string](Get-CurrentSelectedComputerName))) { return }
    $vue = ConvertTo-DomeniaSoftwareFromInventory -Items $script:InventoryRows -CompletedAt $script:InventoryCompletedAt
    if ([int]$vue.Count -eq 0) { return }
    $script:SoftwareRows = @($vue.Rows)
    $script:SoftwareSource = 'Inventaire'
    $script:SoftwareProvenance = [string]$vue.ProvenanceText
    $panel = Get-DomeniaControl -Name 'PnlSoftwareDashboard'
    if ($null -ne $panel) { $panel.Children.Clear() }
    [void](Set-DomeniaControlText -Name 'LblSoftwareDashboard' -Text ([string]$vue.DashboardText))
    Update-DomeniaSoftwareColumnVisibility
    Apply-DomeniaSoftwareFilter
    Add-DomeniaUiLog -Area 'Logiciels' -Text ("{0} logiciel(s) repris de l'inventaire du poste, sans nouvelle requete." -f [int]$vue.Count)
}

function Start-DomeniaSoftwareInventory {
    try {
        if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Machine") {
            Set-Status "Sélectionnez une machine avant de charger les logiciels." "WARN"
            return
        }
        $computer = Assert-DomeniaComputerTarget -Computer (Get-CurrentSelectedComputerName)
        $script:SoftwareSource = "Poste"
        $script:SoftwareProvenance = ""
        $script:SoftwareChartSelect = $null
        Update-DomeniaSoftwareFilterChip
        Update-DomeniaSoftwareAccessSummary
        [void](Set-DomeniaControlText -Name "LblSoftwareStatus" -Text ("Lecture des logiciels de " + $computer + "..."))

        $perUser = $false
        $store = $false
        $updates = $false
        try { $perUser = [bool](Get-DomeniaControl -Name "ChkSoftwarePerUser").IsChecked } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaSoftwareInventory' $_ }
        try { $store = [bool](Get-DomeniaControl -Name "ChkSoftwareStore").IsChecked } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaSoftwareInventory' $_ }
        try { $updates = [bool](Get-DomeniaControl -Name "ChkSoftwareUpdates").IsChecked } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaSoftwareInventory' $_ }

        $timeout = 130
        if ($store) { $timeout = 200 }

        $collectionState=New-DomeniaClassicCollectionState -Computer $computer -ResultKind 'ClassicSoftware' -RequestKey ('software-'+[string]$perUser+'-'+[string]$store+'-'+[string]$updates) -PublishHandler 'Complete-DomeniaSoftwareUi' -PublishErrorHandler 'Fail-DomeniaSoftwareUi'
        Start-UiTask `
            -Name "Logiciels installes" `
            -OperationId "SoftwareInventory" `
            -Code (Get-DomeniaSoftwareWorkerCode) `
            -Payload ([pscustomobject]@{ Computer=$computer; IncludePerUser=$perUser; IncludeStore=$store; IncludeUpdates=$updates; MaxKeys=400 }) `
            -CallbackState $collectionState `
            -ReplaceKey "software" `
            -DisableControls @("BtnLoadSoftware") `
            -TimeoutSeconds $timeout `
            -StatusText ("Lecture des logiciels de " + $computer + " en arriere-plan...") `
            -SuccessHandler "Complete-DomeniaClassicCollected" `
            -ErrorHandler "Fail-DomeniaClassicCollected" | Out-Null
    }
    catch { [void](Show-DomeniaOperationError -Operation "Lecture des logiciels" -ErrorRecordOrException $_) }
}

function Copy-DomeniaSoftware {
    if (@($script:SoftwareRows).Count -eq 0) { Set-Status "Aucun logiciel a copier." "WARN"; return }
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add("Nom`tVersion`tEditeur`tInstalle le`tTaille`tPortee`tArchi`tType`tEmplacement")
    foreach ($r in @($script:SoftwareRows)) {
        [void]$lines.Add(("{0}`t{1}`t{2}`t{3}`t{4}`t{5}`t{6}`t{7}`t{8}" -f `
            [string]$r.Name,[string]$r.Version,[string]$r.Publisher,[string]$r.InstallDate,`
            [string]$r.Size,[string]$r.Scope,[string]$r.Architecture,[string]$r.Kind,[string]$r.Location))
    }
    Set-ClipboardSafe ([string]::Join([Environment]::NewLine,$lines.ToArray()))
    $copie = "{0} logiciel(s) copie(s)." -f @($script:SoftwareRows).Count
    if (-not [string]::IsNullOrWhiteSpace([string]$script:SoftwareProvenance)) {
        $copie += ' Liste reprise de lʼinventaire : nom et version seulement.'
    }
    Set-Status $copie
}

function Export-DomeniaSoftware {
    try {
        if (@($script:SoftwareRows).Count -eq 0) { Set-Status "Aucun logiciel a exporter." "WARN"; return }
        # Le nom du fichier porte la provenance : un CSV « -logiciels-inventaire » ne se revendique pas
        # comme une lecture complete des logiciels du poste.
        $sujet = '-logiciels'
        if (-not [string]::IsNullOrWhiteSpace([string]$script:SoftwareProvenance)) { $sujet = '-logiciels-inventaire' }
        $result = Export-DomeniaCsv -Rows @($script:SoftwareRows) -Grid (Get-DomeniaControl -Name 'DgSoftware') -Subject ((Get-DomeniaExportComputerName) + $sujet)
        Add-DomeniaUiLog -Area "Logiciels" -Text ("Export CSV : " + [string]$result.Path)
        Show-DomeniaExportResult -Result $result
    }
    catch { [void](Show-DomeniaOperationError -Operation "Export des logiciels" -ErrorRecordOrException $_) }
}


# =====================================================================
# Explorateur WMI. Trois operations distinctes : enumeration des espaces
# de noms, enumeration des classes, lecture des instances. Toutes sont en
# lecture seule : la requete est construite dans le worker sous la seule
# forme SELECT et aucune methode WMI n est jamais invoquee.
# =====================================================================
function Get-DomeniaWmiNamespacesWorkerCode {
    return @'
$DomeniaCollectedResult = & {
$computer=[string]$Payload.Computer;$root=[string]$Payload.Root;if([string]::IsNullOrWhiteSpace($root)){$root='root'}
$maxCount=[Math]::Max(20,[Math]::Min(500,[int]$Payload.MaxCount));$watch=[Diagnostics.Stopwatch]::StartNew();$cred=Get-WMachineCredential $Context;$classicError='';$session=$null
$lease=Enter-WCredentialAttempt -Context $Context -Channel Remote;try{$session=New-WDomeniaCimSession $Context $computer $cred 12;$rows=New-Object Collections.ArrayList;[void]$rows.Add([pscustomobject]@{Namespace=$root;Depth=0});foreach($c in @(Get-CimInstance -CimSession $session -Namespace $root -ClassName '__NAMESPACE' -ErrorAction Stop|Select-Object -First ($maxCount-1))){if($c.Name){[void]$rows.Add([pscustomobject]@{Namespace=($root+'\'+[string]$c.Name);Depth=1})}};$watch.Stop();[pscustomobject]@{Computer=$computer;Namespaces=@($rows|Sort-Object Namespace);Errors=@();Truncated=($rows.Count-ge$maxCount);DurationMs=[long]$watch.ElapsedMilliseconds;Transport='CIM';Success=$true};return}catch{if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};$classicError=$_.Exception.Message}finally{Exit-WCredentialAttempt -Lease $lease;Remove-WDomeniaCimSession $session}
$local=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
Assert-WCredentialAllowed -Context $Context -Channel Remote
$r=Invoke-WRemoteTaskScript $Context $computer $local ([pscustomobject]@{Root=$root;MaxCount=$maxCount}) ([int]$Context.TaskFallbackTimeoutSeconds) $classicError;$watch.Stop();$r.DurationMs=[long]$watch.ElapsedMilliseconds;$r
}
foreach($DomeniaCollectedItem in @($DomeniaCollectedResult)){if($null -ne $DomeniaCollectedItem -and $DomeniaCollectedItem -isnot [string] -and $DomeniaCollectedItem -isnot [ValueType]){$DomeniaCollectedItem|Add-Member -NotePropertyName SourceCompletedUtc -NotePropertyValue ([datetime]::UtcNow.ToString('o')) -Force};$DomeniaCollectedItem}

'@
}

function Get-DomeniaWmiClassesWorkerCode {
    return @'
$DomeniaCollectedResult = & {
$computer=[string]$Payload.Computer;$namespace=[string]$Payload.Namespace;$watch=[Diagnostics.Stopwatch]::StartNew();$cred=Get-WMachineCredential $Context;$classicError='';$session=$null
function Convert-Classes($items){$rows=New-Object Collections.ArrayList;foreach($c in @($items)){$abstract=$false;$dynamic=$false;try{foreach($q in @($c.CimClassQualifiers)){if([string]$q.Name-ieq'Abstract'){$abstract=$true};if([string]$q.Name-ieq'Dynamic'){$dynamic=$true}}}catch{};$kind='Statique';if($abstract){$kind='Abstraite'}elseif($dynamic){$kind='Dynamique'};[void]$rows.Add([pscustomobject]@{Class=[string]$c.CimClassName;Properties=@($c.CimClassProperties).Count;Methods=@($c.CimClassMethods).Count;Kind=$kind;System=([string]$c.CimClassName).StartsWith('__')})};return @($rows|Sort-Object Class)}
$lease=Enter-WCredentialAttempt -Context $Context -Channel Remote;try{$session=New-WDomeniaCimSession $Context $computer $cred 12;$rows=Convert-Classes @(Get-CimClass -CimSession $session -Namespace $namespace -ErrorAction Stop);$watch.Stop();[pscustomobject]@{Computer=$computer;Namespace=$namespace;Classes=$rows;DurationMs=[long]$watch.ElapsedMilliseconds;Transport='CIM';Success=$true};return}catch{if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};$classicError=$_.Exception.Message}finally{Exit-WCredentialAttempt -Lease $lease;Remove-WDomeniaCimSession $session}
$local=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
Assert-WCredentialAllowed -Context $Context -Channel Remote
$r=Invoke-WRemoteTaskScript $Context $computer $local ([pscustomobject]@{Namespace=$namespace}) ([int]$Context.TaskFallbackTimeoutSeconds) $classicError;$watch.Stop();$r.DurationMs=[long]$watch.ElapsedMilliseconds;$r
}
foreach($DomeniaCollectedItem in @($DomeniaCollectedResult)){if($null -ne $DomeniaCollectedItem -and $DomeniaCollectedItem -isnot [string] -and $DomeniaCollectedItem -isnot [ValueType]){$DomeniaCollectedItem|Add-Member -NotePropertyName SourceCompletedUtc -NotePropertyValue ([datetime]::UtcNow.ToString('o')) -Force};$DomeniaCollectedItem}

'@
}

function Get-DomeniaWmiQueryWorkerCode {
    return @'
$DomeniaCollectedResult = & {
$msiNames=@();if($null-ne$Payload.PSObject.Properties['MsiClassNames']){foreach($msiName in @($Payload.MsiClassNames)){if(-not[string]::IsNullOrWhiteSpace([string]$msiName)){$msiNames+=[string]$msiName}}}
if(-not$msiNames.Count){throw 'Garde MSI absente de la charge utile : lecture refusee.'}
$msiStem=@(@([string]$Payload.ClassName) -split '[:\\]');$msiStem=@($msiStem[-1] -split '[.=]')[0].Trim()
foreach($msiName in $msiNames){if($msiStem-ieq$msiName){throw 'Classe du fournisseur MSI bloquee : sa lecture peut declencher des verifications/reparations MSI. Utilise le panneau Logiciels.'}}
if ([string]$Payload.ClassName -notmatch '^[A-Za-z_][A-Za-z0-9_]{0,127}$' -or [string]$Payload.Namespace -notmatch '^root(?:\\[A-Za-z_][A-Za-z0-9_]*)*$') { throw 'Classe ou namespace WMI invalide.' }
if ([int]$Payload.Limit -lt 1 -or [int]$Payload.Limit -gt 500 -or ([string]$Payload.Where).Length -gt 2048 -or ([string]$Payload.Where).IndexOf([char]0) -ge 0) { throw 'Limite ou filtre WMI invalide.' }
$computer=[string]$Payload.Computer;$namespace=[string]$Payload.Namespace;$className=[string]$Payload.ClassName;$where=([string]$Payload.Where).Trim();$limit=[Math]::Max(1,[Math]::Min(500,[int]$Payload.Limit));if($className-notmatch'^[A-Za-z_][A-Za-z0-9_]{0,127}$'){throw 'Nom de classe invalide.'};if($where-match'(?i)\b(insert|update|delete|drop|exec|call)\b'){throw 'Condition interdite.'};$query='SELECT * FROM '+$className;if($where){$query+=' WHERE '+$where}
$watch=[Diagnostics.Stopwatch]::StartNew();$cred=Get-WMachineCredential $Context;$classicError='';$session=$null
function Flatten($class,$instances){$schema=New-Object Collections.ArrayList;$values=New-Object Collections.ArrayList;try{foreach($p in @($class.CimClassProperties)){[void]$schema.Add([pscustomobject]@{Property=[string]$p.Name;Type=[string]$p.CimType;IsKey='';Qualifiers=''})}}catch{};$ix=0;foreach($instance in @($instances)){$ix++;foreach($p in $instance.PSObject.Properties){$n=[string]$p.Name;if($n.StartsWith('Cim')-or$n.StartsWith('PS')){continue};$v='';try{if($null-ne$p.Value){if($p.Value-is[Array]){$v=@($p.Value)-join', '}else{$v=[string]$p.Value}}}catch{$v='(illisible)'};if($v.Length-gt600){$v=$v.Substring(0,600)+'...'};[void]$values.Add([pscustomobject]@{Instance=$ix;Property=$n;Value=$v})}};[pscustomobject]@{Schema=@($schema|Sort-Object Property);Instances=@($values);InstanceCount=$ix}}
$lease=Enter-WCredentialAttempt -Context $Context -Channel Remote;try{$session=New-WDomeniaCimSession $Context $computer $cred 12;$class=Get-CimClass -CimSession $session -Namespace $namespace -ClassName $className -ErrorAction Stop;$instances=@(Get-CimInstance -CimSession $session -Namespace $namespace -Query $query -ErrorAction Stop|Select-Object -First $limit);$f=Flatten $class $instances;$watch.Stop();[pscustomobject]@{Computer=$computer;Namespace=$namespace;ClassName=$className;Query=$query;Schema=$f.Schema;Instances=$f.Instances;InstanceCount=$f.InstanceCount;DurationMs=[long]$watch.ElapsedMilliseconds;Transport='CIM';Success=$true};return}catch{if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};$classicError=$_.Exception.Message}finally{Exit-WCredentialAttempt -Lease $lease;Remove-WDomeniaCimSession $session}
$local=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
Assert-WCredentialAllowed -Context $Context -Channel Remote
$r=Invoke-WRemoteTaskScript $Context $computer $local ([pscustomobject]@{Namespace=$namespace;ClassName=$className;Query=$query;Limit=$limit}) ([int]$Context.TaskFallbackTimeoutSeconds) $classicError;$watch.Stop();$r.DurationMs=[long]$watch.ElapsedMilliseconds;$r
}
foreach($DomeniaCollectedItem in @($DomeniaCollectedResult)){if($null -ne $DomeniaCollectedItem -and $DomeniaCollectedItem -isnot [string] -and $DomeniaCollectedItem -isnot [ValueType]){$DomeniaCollectedItem|Add-Member -NotePropertyName SourceCompletedUtc -NotePropertyValue ([datetime]::UtcNow.ToString('o')) -Force};$DomeniaCollectedItem}

'@
}

function Get-DomeniaWmiComputer {
    if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Machine") {
        Set-Status "Sélectionnez une machine avant dʼutiliser lʼexplorateur WMI." "WARN"
        return ""
    }
    return (Assert-DomeniaComputerTarget -Computer (Get-CurrentSelectedComputerName))
}

function Complete-DomeniaWmiNamespacesUi {
    param($Result,$State)
    if(-not (Test-DomeniaClassicResultCurrent $Result $State)){return}
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Namespaces")
    if ($null -eq $effective) { throw "Resultat d enumeration vide ou invalide." }
    $script:WmiNamespaces = @($effective.Namespaces)
    $list = Get-DomeniaControl -Name "LstWmiNamespaces"
    if ($null -ne $list) {
        $list.Items.Clear()
        foreach ($n in $script:WmiNamespaces) { [void]$list.Items.Add([string]$n.Namespace) }
    }
    [void](Set-DomeniaControlText -Name "LblWmiNamespaceCount" -Text ("{0} espace(s)" -f @($script:WmiNamespaces).Count))
    $suffix = ""
    if ([bool]$effective.Truncated) { $suffix = " Limite atteinte, la liste est tronquee." }
    $failures = @($effective.Errors).Count
    $transport="";try{$transport=[string]$effective.Transport}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWmiNamespacesUi' $_}; if([string]::IsNullOrWhiteSpace($transport)){try{$transport=[string]$effective.DomeniaTransport}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWmiNamespacesUi' $_}}; $summary = "{0} espace(s) de noms lus en {1} ms via {2}, {3} branche(s) refusee(s).{4}" -f `
        @($script:WmiNamespaces).Count,([long]$effective.DurationMs),$(if($transport){$transport}else{"CIM"}),$failures,$suffix
    [void](Set-DomeniaControlText -Name "LblWmiStatus" -Text $summary)
    Set-Status $summary
    Add-DomeniaUiLog -Area "WMI" -Text $summary
    try { $fb=if([string]$effective.DomeniaTransport -eq "TaskFallback"){1}else{0};$bytes=24000;try{$bytes=[long]$effective.DomeniaBytesSent+[long]$effective.DomeniaBytesReceived}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWmiNamespacesUi' $_};Register-DomeniaOperationSample -Operation "WmiNamespaces" -Mode $(if($fb){"Classic+TaskFallback"}else{"Classic"}) -ItemCount 1 -DurationMs ([long]$effective.DurationMs) -BytesEstimated $bytes -RemoteAttempts 1 -FallbackTasks $fb -SuccessCount 1 } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWmiNamespacesUi' $_ }
}

function Complete-DomeniaWmiClassesUi {
    param($Result,$State)
    if(-not (Test-DomeniaClassicResultCurrent $Result $State)){return}
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Classes")
    if ($null -eq $effective) { throw "Resultat de classes vide ou invalide." }
    $script:WmiClasses = @($effective.Classes)
    $script:WmiNamespace = [string]$effective.Namespace
    Apply-DomeniaWmiClassFilter
    $transport="";try{$transport=[string]$effective.Transport}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWmiClassesUi' $_};if([string]::IsNullOrWhiteSpace($transport)){try{$transport=[string]$effective.DomeniaTransport}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWmiClassesUi' $_}};$summary = "{0} : {1} classe(s) en {2} ms via {3}." -f [string]$effective.Namespace,@($script:WmiClasses).Count,([long]$effective.DurationMs),$(if($transport){$transport}else{"CIM"})
    [void](Set-DomeniaControlText -Name "LblWmiStatus" -Text $summary)
    Set-Status $summary
    Add-DomeniaUiLog -Area "WMI" -Text $summary
    try { $fb=if([string]$effective.DomeniaTransport -eq "TaskFallback"){1}else{0};$bytes=80000;try{$bytes=[long]$effective.DomeniaBytesSent+[long]$effective.DomeniaBytesReceived}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWmiClassesUi' $_};Register-DomeniaOperationSample -Operation "WmiClasses" -Mode $(if($fb){"Classic+TaskFallback"}else{"Classic"}) -ItemCount 1 -DurationMs ([long]$effective.DurationMs) -BytesEstimated $bytes -RemoteAttempts 1 -FallbackTasks $fb -SuccessCount 1 } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWmiClassesUi' $_ }
}

function Complete-DomeniaWmiQueryUi {
    param($Result,$State)
    if(-not (Test-DomeniaClassicResultCurrent $Result $State)){return}
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Instances")
    if ($null -eq $effective) { throw "Resultat de requete vide ou invalide." }
    $script:WmiSchema = @($effective.Schema)
    $script:WmiInstances = @($effective.Instances)
    # CO-04: the export file names the workstation that answered, not the one selected later.
    $script:WmiInstancesComputer = [string]$State.Computer
    [void](Set-DomeniaItemsSource -Name "DgWmiSchema" -Rows $script:WmiSchema)
    [void](Set-DomeniaItemsSource -Name "DgWmiInstances" -Rows $script:WmiInstances)
    $summary = "{0} : {1} instance(s), {2} propriete(s) de schema, {3} valeur(s), en {4} ms. Requete : {5}" -f `
        [string]$effective.ClassName,[int]$effective.InstanceCount,@($script:WmiSchema).Count,`
        @($script:WmiInstances).Count,([long]$effective.DurationMs),[string]$effective.Query
    if([int](Get-DomeniaMemberValue $effective 'RedactedSecretRows') -gt 0){$summary+=' '+[string]$effective.RedactedSecretRows+' champ(s) de secret exclus du stockage et de la vue.'}
    [void](Set-DomeniaControlText -Name "LblWmiStatus" -Text $summary)
    Set-Status $summary
    Add-DomeniaUiLog -Area "WMI" -Text $summary
    try { $fb=if([string]$effective.DomeniaTransport -eq "TaskFallback"){1}else{0};$bytes=160000;try{$bytes=[long]$effective.DomeniaBytesSent+[long]$effective.DomeniaBytesReceived}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWmiQueryUi' $_};Register-DomeniaOperationSample -Operation "WmiQuery" -Mode $(if($fb){"Classic+TaskFallback"}else{"Classic"}) -ItemCount 1 -DurationMs ([long]$effective.DurationMs) -BytesEstimated $bytes -RemoteAttempts 1 -FallbackTasks $fb -SuccessCount 1 } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWmiQueryUi' $_ }
}

function Fail-DomeniaWmiUi {
    param($Message,$State)
    if(-not (Test-DomeniaClassicResultCurrent -State $State -ContextOnly)){return}
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue." }
    [void](Set-DomeniaControlText -Name "LblWmiStatus" -Text ("Echec : " + $detail))
    Set-Status ("Explorateur WMI : " + $detail) "ERROR"
    Add-DomeniaUiLog -Area "WMI" -Level "ERROR" -Text $detail
}

function Apply-DomeniaWmiClassFilter {
    try {
        $filter = ""
        try { $filter = ([string](Get-DomeniaControl -Name "TxtWmiClassFilter").Text).Trim() } catch { Write-DomeniaSwallowed 'Core' 'Apply-DomeniaWmiClassFilter' $_ }
        $rows = @($script:WmiClasses)
        if (-not [string]::IsNullOrWhiteSpace($filter)) {
            $rows = @($rows | Where-Object { [string]$_.Class -like ("*" + $filter + "*") })
        }
        $list = Get-DomeniaControl -Name "LstWmiClasses"
        if ($null -ne $list) {
            $list.Items.Clear()
            foreach ($c in $rows) {
                $label = "{0}  [{1} prop, {2} meth, {3}]" -f [string]$c.Class,[int]$c.Properties,[int]$c.Methods,[string]$c.Kind
                [void]$list.Items.Add($label)
            }
        }
        [void](Set-DomeniaControlText -Name "LblWmiClassCount" -Text ("{0} classe(s) sur {1}" -f @($rows).Count,@($script:WmiClasses).Count))
    }
    catch { Add-DomeniaUiLog -Level "ERROR" -Area "WMI" -Text $_.Exception.Message }
}

function Get-DomeniaWmiSelectedNamespace {
    $list = Get-DomeniaControl -Name "LstWmiNamespaces"
    if ($null -ne $list -and $null -ne $list.SelectedItem) { return [string]$list.SelectedItem }
    if (-not [string]::IsNullOrWhiteSpace([string]$script:WmiNamespace)) { return [string]$script:WmiNamespace }
    return "root\cimv2"
}

function Get-DomeniaWmiSelectedClass {
    $list = Get-DomeniaControl -Name "LstWmiClasses"
    if ($null -eq $list -or $null -eq $list.SelectedItem) { return "" }
    $label = [string]$list.SelectedItem
    $cut = $label.IndexOf("  [")
    if ($cut -gt 0) { return $label.Substring(0,$cut).Trim() }
    return $label.Trim()
}

function Start-DomeniaWmiNamespaces {
    try {
        $computer = Get-DomeniaWmiComputer
        if ([string]::IsNullOrWhiteSpace($computer)) { return }
        [void](Set-DomeniaControlText -Name "LblWmiStatus" -Text ("Enumeration des espaces de noms de " + $computer + "..."))
        # Ne jamais parcourir recursivement tout WMI ici. Le diagnostic distant
        # prouve deja la connectivite CIM ; ce bouton ne charge que root + ses
        # enfants directs (dont root\cimv2). Les classes sont ensuite chargees
        # a la demande pour l espace selectionne. Cela evite qu un provider WMI
        # lent dans une branche profonde monopolise le worker pendant 90 s.
        $collectionState=New-DomeniaClassicCollectionState -Computer $computer -ResultKind 'WmiNamespaces' -RequestKey 'root-depth1' -PublishHandler 'Complete-DomeniaWmiNamespacesUi' -PublishErrorHandler 'Fail-DomeniaWmiUi'
        Start-UiTask `
            -Name "Espaces de noms WMI" `
            -OperationId "WmiNamespaces" `
            -Code (Get-DomeniaWmiNamespacesWorkerCode) `
            -Payload ([pscustomobject]@{ Computer=$computer; Root="root"; MaxDepth=1; MaxCount=120 }) `
            -CallbackState $collectionState `
            -ReplaceKey "wmi" `
            -DisableControls @("BtnWmiNamespaces","BtnWmiClasses","BtnWmiQuery") `
            -TimeoutSeconds 35 `
            -StatusText "Lecture des espaces WMI principaux en arriere-plan..." `
            -SuccessHandler "Complete-DomeniaClassicCollected" `
            -ErrorHandler "Fail-DomeniaClassicCollected" | Out-Null
    }
    catch { [void](Show-DomeniaOperationError -Operation "Espaces de noms WMI" -ErrorRecordOrException $_) }
}

function Start-DomeniaWmiClasses {
    try {
        $computer = Get-DomeniaWmiComputer
        if ([string]::IsNullOrWhiteSpace($computer)) { return }
        $namespace = Get-DomeniaWmiSelectedNamespace
        [void](Set-DomeniaControlText -Name "LblWmiStatus" -Text ("Lecture des classes de " + $namespace + "..."))
        $collectionState=New-DomeniaClassicCollectionState -Computer $computer -ResultKind 'WmiClasses' -RequestKey (Get-DomeniaStoreHash $namespace.ToLowerInvariant()) -PublishHandler 'Complete-DomeniaWmiClassesUi' -PublishErrorHandler 'Fail-DomeniaWmiUi'
        Start-UiTask `
            -Name "Classes WMI" `
            -OperationId "WmiClasses" `
            -Code (Get-DomeniaWmiClassesWorkerCode) `
            -Payload ([pscustomobject]@{ Computer=$computer; Namespace=$namespace }) `
            -CallbackState $collectionState `
            -ReplaceKey "wmi" `
            -DisableControls @("BtnWmiNamespaces","BtnWmiClasses","BtnWmiQuery") `
            -TimeoutSeconds 90 `
            -StatusText ("Lecture des classes de " + $namespace + "...") `
            -SuccessHandler "Complete-DomeniaClassicCollected" `
            -ErrorHandler "Fail-DomeniaClassicCollected" | Out-Null
    }
    catch { [void](Show-DomeniaOperationError -Operation "Classes WMI" -ErrorRecordOrException $_) }
}

function Start-DomeniaWmiQuery {
    try {
        $computer = Get-DomeniaWmiComputer
        if ([string]::IsNullOrWhiteSpace($computer)) { return }
        $className = Get-DomeniaWmiSelectedClass
        if ([string]::IsNullOrWhiteSpace($className)) { Set-Status "Sélectionnez dʼabord une classe." "WARN"; return }
        $namespace = Get-DomeniaWmiSelectedNamespace
        $where = ""
        $limit = 25
        try { $where = ([string](Get-DomeniaControl -Name "TxtWmiWhere").Text).Trim() } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaWmiQuery' $_ }
        try { $limit = [int]([string](Get-DomeniaControl -Name "TxtWmiLimit").Text) } catch { $limit = 25 }
        if ($limit -le 0) { $limit = 25 }
        $limit = [Math]::Min(500,$limit)
        Assert-DomeniaWmiReadQuery -ClassName $className -Namespace $namespace -Where $where -Limit $limit
        [void](Set-DomeniaControlText -Name "LblWmiStatus" -Text ("Lecture des instances de " + $className + "..."))
        $collectionState=New-DomeniaClassicCollectionState -Computer $computer -ResultKind 'WmiExplorer' -RequestKey (Get-DomeniaStoreHash ($namespace.ToLowerInvariant()+'|'+$className.ToLowerInvariant()+'|'+$where+'|'+$limit)) -PublishHandler 'Complete-DomeniaWmiQueryUi' -PublishErrorHandler 'Fail-DomeniaWmiUi'
        Start-UiTask `
            -Name "Instances WMI" `
            -OperationId "WmiQuery" `
            -Code (Get-DomeniaWmiQueryWorkerCode) `
            -Payload ([pscustomobject]@{ Computer=$computer; Namespace=$namespace; ClassName=$className; Where=$where; Limit=$limit; MsiClassNames=@(Get-DomeniaMsiProviderClassNames) }) `
            -CallbackState $collectionState `
            -ReplaceKey "wmi" `
            -DisableControls @("BtnWmiNamespaces","BtnWmiClasses","BtnWmiQuery") `
            -TimeoutSeconds 90 `
            -StatusText ("Lecture des instances de " + $className + "...") `
            -SuccessHandler "Complete-DomeniaClassicCollected" `
            -ErrorHandler "Fail-DomeniaClassicCollected" | Out-Null
    }
    catch { [void](Show-DomeniaOperationError -Operation "Instances WMI" -ErrorRecordOrException $_) }
}

function Copy-DomeniaWmi {
    if (@($script:WmiInstances).Count -eq 0) { Set-Status "Aucune instance a copier." "WARN"; return }
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add("Instance`tPropriete`tValeur")
    foreach ($r in @($script:WmiInstances)) {
        [void]$lines.Add(("{0}`t{1}`t{2}" -f [int]$r.Instance,[string]$r.Property,[string]$r.Value))
    }
    Set-ClipboardSafe ([string]::Join([Environment]::NewLine,$lines.ToArray()))
    Set-Status ("{0} valeur(s) copiee(s)." -f @($script:WmiInstances).Count)
}

function Export-DomeniaWmi {
    try {
        # The grid is emptied when the selection changes: only the instances still shown are exported.
        $grid = Get-DomeniaControl -Name 'DgWmiInstances'
        $rows = if ($null -ne $grid) { @($grid.Items | Where-Object { $_ -ne [System.Windows.Data.CollectionView]::NewItemPlaceholder }) } else { @($script:WmiInstances) }
        if ($rows.Count -eq 0) { Set-Status "Aucune instance à exporter." "WARN"; return }
        Show-DomeniaExportResult -Result (Export-DomeniaCsv -Rows $rows -Grid $grid -Subject ((Get-DomeniaExportComputerName -Computer ([string]$script:WmiInstancesComputer)) + '-wmi'))
    }
    catch { [void](Show-DomeniaOperationError -Operation "Export WMI" -ErrorRecordOrException $_) }
}


# =====================================================================
# Detection inverse. La sonde historique part d un poste pour trouver son
# utilisateur. Depuis un compte, aucun chemin n existait : il fallait
# ouvrir les postes un par un. Trois sources sont interrogees, de la plus
# fiable a la plus approximative, et chaque candidat est verifie dans
# l annuaire avant d etre propose.
# =====================================================================

function Complete-DomeniaUserComputersUi {
    param($Result,$State)
    Complete-DomeniaRelationsSearch -Result $Result -State $State
}

function Fail-DomeniaUserComputersUi {
    param($Message,$State)
    Fail-DomeniaRelationsSearch -Message $Message -State $State
}

function Start-DomeniaUserComputerProbe {
    Start-DomeniaRelationsSearch
}


# =====================================================================
# Index local des objets de l annuaire.
# Le cache d origine ne vivait que le temps de la session et ne servait
# qu a reafficher un resultat deja obtenu. Cet index est un instantane
# complet, ecrit sur disque, relu au demarrage, et interrogeable sans
# aucun appel reseau. Il porte aussi la correspondance approchee, qui
# rattrape les fautes de frappe.
# =====================================================================
function Rebuild-DomeniaIndexLookup {
    $usersByLogin = @{}
    $usersByGuid = @{}
    $computersByName = @{}
    $computersByGuid = @{}
    foreach ($r in @($script:IndexRows)) {
        if ($null -ne $r) {
            $guid = ""
            try { $guid = ([string]$r.Guid).Trim().ToLowerInvariant() } catch { Write-DomeniaSwallowed 'Core' 'Rebuild-DomeniaIndexLookup' $_ }
            if ([string]$r.Type -eq "Utilisateur") {
                $login = Normalize-LinkUser ([string]$r.Login)
                if (-not [string]::IsNullOrWhiteSpace($login)) { $usersByLogin[$login.ToLowerInvariant()] = $r }
                if (-not [string]::IsNullOrWhiteSpace($guid)) { $usersByGuid[$guid] = $r }
            }
            elseif ([string]$r.Type -eq "Machine") {
                foreach ($candidate in @([string]$r.Name,[string]$r.Login,[string]$r.Upn)) {
                    $key = Normalize-LinkComputer $candidate
                    if (-not [string]::IsNullOrWhiteSpace($key)) { $computersByName[$key] = $r }
                }
                if (-not [string]::IsNullOrWhiteSpace($guid)) { $computersByGuid[$guid] = $r }
            }
        }
    }
    $script:IndexUsersByLogin = $usersByLogin
    $script:IndexUsersByGuid = $usersByGuid
    $script:IndexComputersByName = $computersByName
    $script:IndexComputersByGuid = $computersByGuid
}

function Save-DomeniaIndex {
    param([Parameter(Mandatory=$true)]$Rows,[string]$Server='', [string]$BaseDn='', [long]$HighestUsn=0,[int]$TotalCount=0,[string]$InvocationId='',[string]$SyncScope='directory',$Transfer=$null,$Reconcile=$null)
    if(@($Rows).Count -gt 5000000){throw 'Index trop volumineux (5000000 objets maximum par reconstruction).'}
    $copy=[object[]]@($Rows)
    $queued = Queue-DomeniaMetadata -Kind IndexBulk -Row ([pscustomobject]@{Rows=$copy;Transfer=$Transfer;RowCount=$(if($null -ne $Transfer){[long]$Transfer.RowCount}else{[long]$copy.Count});Server=$Server;BaseDn=$BaseDn;HighestUsn=$HighestUsn;TotalCount=$TotalCount;ReplaceAll=$true;InvocationId=$InvocationId;SyncScope=$SyncScope;Complete=$true;Reconcile=$Reconcile;At=[datetime]::UtcNow.ToString('o')})
    if (-not $queued) { throw 'La reconstruction nʼa pas été mise en file : stockage indisponible ou saturé. La base précédente est conservée.' }
    return $true
}

function Update-DomeniaIndexDatabaseRows {
    param([Parameter(Mandatory=$true)]$Rows,[string]$Server='', [string]$BaseDn='', [long]$HighestUsn=0,[int]$TotalCount=0,[string]$InvocationId='',[string]$SyncScope='directory',[bool]$Complete=$true,[bool]$WalkStep=$false,$Transfer=$null,$Reconcile=$null,[string]$RefreshOperationId='')
    if(@($Rows).Count -gt 5000000){throw 'Index trop volumineux (5000000 objets maximum par reconstruction).'}
    $copy=[object[]]@($Rows)
    # Every batch owns its queue entry. Coalescing by domain used to discard an earlier OU while storage was busy.
    $queued = Queue-DomeniaMetadata -Kind IndexBulk -Row ([pscustomobject]@{Rows=$copy;Transfer=$Transfer;RowCount=$(if($null -ne $Transfer){[long]$Transfer.RowCount}else{[long]$copy.Count});Server=$Server;BaseDn=$BaseDn;HighestUsn=$HighestUsn;TotalCount=$TotalCount;ReplaceAll=$false;InvocationId=$InvocationId;SyncScope=$SyncScope;Complete=$Complete;WalkStep=$WalkStep;Reconcile=$Reconcile;RefreshOperationId=$RefreshOperationId;At=[datetime]::UtcNow.ToString('o')})
    if (-not $queued) { throw 'Le lot nʼa pas été mis en file : stockage indisponible ou saturé. Relancez la mise à jour après résolution.' }
    return $true
}

function Get-DomeniaDatabaseObjectCount {
    # FI-19: objects of the local base as last read by Request-DomeniaIndexMetadata, never read here on the
    # Dispatcher. -1 means not read yet: the caller says so instead of treating the base as empty.
    return [int]$script:IndexDbCount
}

function Search-DomeniaDatabaseRows {
    # Recherche SQLite directe et indexee. Cela evite de materialiser 60 000+
    # objets PowerShell en RAM juste pour repondre a une recherche.
    param([Parameter(Mandatory=$true)][AllowEmptyString()][string]$Term,[int]$Limit=50)
    $results = New-Object System.Collections.Generic.List[object]
    try {
        Initialize-DomeniaDatabase | Out-Null
        $clean = ([string]$Term).Trim()
        if ($clean.Contains([string][char]92)) { $clean = $clean.Split([char]92)[-1] }
        $clean = $clean.Trim().TrimEnd([char]36)
        if ($clean.Length -lt 2) { return $results }
        $Limit = [Math]::Max(1,[Math]::Min(500,$Limit))

        $termSql = ConvertTo-DomeniaSqlLiteral $clean
        $prefixSql = ConvertTo-DomeniaSqlLiteral ((ConvertTo-DomeniaSqlLikeText $clean) + "%")
        $containsSql = ConvertTo-DomeniaSqlLiteral ("%" + (ConvertTo-DomeniaSqlLikeText $clean.ToLowerInvariant()) + "%")
        $sql = @"
SELECT object_type,name,login,upn,display_name,description,extra,state,distinguished_name,when_changed,usn_changed,last_logon,object_guid,
       CASE
         WHEN name=$termSql COLLATE NOCASE OR login=$termSql COLLATE NOCASE OR upn=$termSql COLLATE NOCASE THEN 100
         WHEN name LIKE $prefixSql ESCAPE '!' COLLATE NOCASE OR login LIKE $prefixSql ESCAPE '!' COLLATE NOCASE OR upn LIKE $prefixSql ESCAPE '!' COLLATE NOCASE THEN 90
         ELSE 70
       END AS match_score
FROM ad_objects
WHERE name=$termSql COLLATE NOCASE
   OR login=$termSql COLLATE NOCASE
   OR upn=$termSql COLLATE NOCASE
   OR name LIKE $prefixSql ESCAPE '!' COLLATE NOCASE
   OR login LIKE $prefixSql ESCAPE '!' COLLATE NOCASE
   OR upn LIKE $prefixSql ESCAPE '!' COLLATE NOCASE
   OR search_key LIKE $containsSql ESCAPE '!'
ORDER BY match_score DESC,name COLLATE NOCASE
LIMIT $Limit;
"@
        $seen = @{}
        foreach ($r in @(Invoke-DomeniaDbQuery $sql)) {
            $dn = [string]$r.distinguished_name
            $guid = [string]$r.object_guid
            $key = if (-not [string]::IsNullOrWhiteSpace($guid)) { $guid.ToLowerInvariant() } else { $dn.ToLowerInvariant() }
            if ($seen.ContainsKey($key)) { continue }
            $seen[$key] = $true
            $row = [pscustomobject]@{
                Type=[string]$r.object_type
                Name=[string]$r.name
                Login=[string]$r.login
                Upn=[string]$r.upn
                Display=[string]$r.display_name
                Description=[string]$r.description
                Extra=[string]$r.extra
                State=[string]$r.state
                DN=$dn
                WhenChanged=[string]$r.when_changed
                Usn=[long]$r.usn_changed
                LastLogon=[string]$r.last_logon
                Guid=$guid
                Key=(([string]$r.name+" "+[string]$r.login+" "+[string]$r.upn+" "+[string]$r.display_name+" "+[string]$r.description+" "+[string]$r.extra).ToLowerInvariant())
                NameKey=([string]$r.name).ToLowerInvariant()
                LoginKey=([string]$r.login).ToLowerInvariant()
                Score=[int]$r.match_score
                Reason=$(if([int]$r.match_score -ge 100){"Correspondance exacte"}elseif([int]$r.match_score -ge 90){"Debut du nom"}else{"Contenu dans la fiche"})
            }
            $row | Add-Member -NotePropertyName Association -NotePropertyValue (Get-DomeniaIndexAssociationText -Row $row) -Force
            $results.Add($row)
        }
        return $results
    }
    catch {
        Write-AppLog "Recherche SQLite locale ignoree : $($_.Exception.Message)" "WARN"
        return $results
    }
}

function Merge-DomeniaIndexRows {
    # Le GUID est l identite stable d un objet. Un renommage ou un deplacement
    # change son DN mais pas son GUID : la nouvelle fiche remplace donc bien
    # l ancienne au lieu de creer un doublon dans la base autonome.
    param([Parameter(Mandatory=$true)]$Existing,[Parameter(Mandatory=$true)]$Changed)
    $byKey = [ordered]@{}
    $dnToKey = @{}
    foreach ($r in @($Existing)) {
        $dn = [string]$r.DN
        $guid = ""
        try { $guid = ([string]$r.Guid).Trim().ToLowerInvariant() } catch { Write-DomeniaSwallowed 'Core' 'Merge-DomeniaIndexRows' $_ }
        if ([string]::IsNullOrWhiteSpace($dn) -and [string]::IsNullOrWhiteSpace($guid)) { continue }
        $key = if (-not [string]::IsNullOrWhiteSpace($guid)) { "g:" + $guid } else { "d:" + $dn.ToLowerInvariant() }
        $byKey[$key] = $r
        if (-not [string]::IsNullOrWhiteSpace($dn)) { $dnToKey[$dn.ToLowerInvariant()] = $key }
    }
    $updated = 0
    $added = 0
    foreach ($r in @($Changed)) {
        $dn = [string]$r.DN
        $guid = ""
        try { $guid = ([string]$r.Guid).Trim().ToLowerInvariant() } catch { Write-DomeniaSwallowed 'Core' 'Merge-DomeniaIndexRows' $_ }
        if ([string]::IsNullOrWhiteSpace($dn) -and [string]::IsNullOrWhiteSpace($guid)) { continue }
        $key = if (-not [string]::IsNullOrWhiteSpace($guid)) { "g:" + $guid } else { "d:" + $dn.ToLowerInvariant() }
        $existingKey = ""
        if ($byKey.Contains($key)) { $existingKey = $key }
        elseif (-not [string]::IsNullOrWhiteSpace($dn) -and $dnToKey.ContainsKey($dn.ToLowerInvariant())) { $existingKey = [string]$dnToKey[$dn.ToLowerInvariant()] }
        if (-not [string]::IsNullOrWhiteSpace($existingKey)) {
            if ($existingKey -ne $key) { [void]$byKey.Remove($existingKey) }
            $updated++
        }
        else { $added++ }
        $byKey[$key] = $r
        if (-not [string]::IsNullOrWhiteSpace($dn)) { $dnToKey[$dn.ToLowerInvariant()] = $key }
    }
    return [pscustomobject]@{ Rows=@($byKey.Values); Updated=$updated; Added=$added; Total=$byKey.Count }
}

function Complete-DomeniaIndexRefreshUi {
    param($Result,$State)
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Rows")
    if ($null -eq $effective) { throw "Actualisation sans resultat exploitable." }
    $changed = @($effective.Rows)
    $transfer = $null; if ($null -ne $effective.PSObject.Properties['Transfer']) { $transfer = $effective.Transfer }
    $rowCount = if ($null -ne $effective.PSObject.Properties['RowCount']) { [long]$effective.RowCount } else { [long]@($changed).Count }

    $checkpoint = $null
    try {
        $checkpoint = [pscustomobject]@{
            Dc=[string]$script:IndexInfo.Server
            InvocationId=[string]$script:IndexInfo.InvocationId
            Usn=[string]$script:IndexInfo.Usn
            ScopeDn=[string]$script:IndexInfo.BaseDn
        }
    } catch { $checkpoint = $null }

    $scopeDn = [string]$effective.BaseDn
    $response = [pscustomobject]@{
        Dc=[string]$effective.Server
        InvocationId=[string]$effective.InvocationId
        HighestUsn=[string]$effective.HighestUsn
        Partial=[bool]$effective.Truncated
        VisibilityReduced=$false
        ScopeDn=$scopeDn
        Rows=$changed
        KnownGuids=@()
        KnownDnByGuid=$null
        ScopeComplete=(-not [bool]$effective.Truncated)
    }
    $sync = Resolve-DomeniaIncrementalSync $checkpoint $response
    if ([string](Get-DomeniaMember $effective 'CheckpointRejected' '') -eq 'UsnAhead') {
        Add-DomeniaUiLog -Area "Index" -Text 'Repère au-delà du dernier USN validé par ce contrôleur (restauration ou retour arrière) : lecture complète, aucun USN extrapolé.'
    }

    $canReplace = ((-not [bool]$effective.Incremental) -and (-not [bool]$effective.Truncated))
    if ($canReplace) {
        # Le controleur a change ou l index n avait pas de repere : la passe
        # a tout relu sans troncature, on repart d un index neuf.
        [void](Save-DomeniaIndex -Rows $changed -Transfer $transfer -Server ([string]$effective.Server) -BaseDn ([string]$effective.BaseDn) -HighestUsn ([long]$effective.HighestUsn) -InvocationId ([string]$effective.InvocationId) -Reconcile $effective.Reconcile)
        $script:IndexRows = @()
        # FI-19: the figures are read again off the Dispatcher; the committed save reads them once more (storage).
        Request-DomeniaIndexMetadata
        $summary = "Lecture complète terminée, enregistrement local en attente : {0} objet(s), en {1} ms. Le repère de la passe précédente nʼétait pas utilisable." -f `
            $rowCount,([long]$effective.DurationMs)
    }
    else {
        if ($null -eq $transfer -and @($script:IndexRows).Count -gt 0) {
            $merge = Merge-DomeniaIndexRows -Existing @($script:IndexRows) -Changed $changed
            [void](Update-DomeniaIndexDatabaseRows -Rows $changed -Transfer $transfer -Server ([string]$effective.Server) -BaseDn ([string]$effective.BaseDn) -Complete (-not [bool]$effective.Truncated) -HighestUsn ([long]$effective.HighestUsn) -TotalCount ([int]$merge.Total) -InvocationId ([string]$effective.InvocationId) -Reconcile $effective.Reconcile)
            $totalAfter = [int]$merge.Total
            $updated = [int]$merge.Updated
            $added = [int]$merge.Added
        } else {
            [void](Update-DomeniaIndexDatabaseRows -Rows $changed -Transfer $transfer -Server ([string]$effective.Server) -BaseDn ([string]$effective.BaseDn) -Complete (-not [bool]$effective.Truncated) -HighestUsn ([long]$effective.HighestUsn) -TotalCount 0 -InvocationId ([string]$effective.InvocationId) -Reconcile $effective.Reconcile)
            # The batch is only queued: the base still holds the count read before it (FI-19, read off the Dispatcher).
            $totalAfter = [Math]::Max(0,[int]$script:IndexDbCount)
            Request-DomeniaIndexMetadata
            $updated = $rowCount
            $added = 0
        }
        if ([bool]$effective.Truncated) {
            $cut = Get-DomeniaIndexCut -Effective $effective
            Set-DomeniaIndexPartial -BaseDn ([string]$effective.BaseDn) -Count $rowCount -Reason $cut.Reason -Limit $cut.Limit
            $reasonText = if ($cut.Reason -eq 'erreur') { ' Une lecture AD a échoué.' } else { ' La passe a atteint une limite.' }
            $summary = ("Synchronisation partielle : {0} fiche(s) reçue(s), {1} objet(s) présents. Le repère nʼavance pas.{2}" -f $rowCount,$totalAfter,$reasonText)
        }
        elseif ($rowCount -eq 0) {
            $summary = "Base autonome déjà à jour : aucun objet modifié depuis la dernière passe."
        }
        else {
            $summary = "Lecture terminée : {0} fiche(s) à enregistrer, {1} objet(s) avant validation." -f $rowCount,$totalAfter
        }
    }

    # The committed storage receipt reloads InvocationId and the checkpoint together.
    if (@($sync.Moves).Count -gt 0) {
        Add-DomeniaUiLog -Area "Index" -Text ('Deplacements detectes : ' + @($sync.Moves).Count)
    }

    [void](Set-DomeniaControlText -Name "LblIndexStatus" -Text $summary)
    Set-DomeniaIndexProgress -Mode Busy -Message ($summary + ' Validation de lʼécriture en cours…')
    Set-Status $summary
    # DS-09: the duration of the AD read goes to the journal only.
    $logText = $summary + " Durée de la lecture AD : " + [string]([long]$effective.DurationMs) + " ms. Filtre : " + [string]$effective.DeltaClause
    if (@($sync.Notes).Count -gt 0) { $logText += ' ' + [string]::Join(' ',$sync.Notes) }
    Add-DomeniaUiLog -Area "Index" -Text $logText
    $mode = "AD full fallback"
    if ([bool]$effective.Incremental) { $mode = "AD delta" }
    try { Register-DomeniaOperationSample -Operation "IndexBuild" -Mode $mode -ItemCount ([Math]::Max(1,$rowCount)) -DurationMs ([long]$effective.DurationMs) -BytesEstimated ([long]([Math]::Max(1,$rowCount)*1800)) -AdQueries ([Math]::Max(1,[int][Math]::Ceiling([Math]::Max(1,$rowCount)/1000.0))) -SuccessCount $rowCount } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaIndexRefreshUi' $_ }
    Update-DomeniaIndexStats
}

function Start-DomeniaIndexRefresh {
    param([switch]$Silent,[switch]$Confirmed)
    if (-not (Test-DomeniaIndexWriteReady)) { return }
    try {
        $lastUsn = [long]0
        $lastServer = ""
        $since = ""
        $lastInvocationId = ""
        try { $lastUsn = [long]$script:IndexInfo.Usn } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaIndexRefresh' $_ }
        try { $lastServer = [string]$script:IndexInfo.Server } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaIndexRefresh' $_ }
        try { $since = [string]$script:IndexInfo.Date } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaIndexRefresh' $_ }
        try { $lastInvocationId = [string]$script:IndexInfo.InvocationId } catch { $lastInvocationId = "" }
        $dbCount = Get-DomeniaDatabaseObjectCount
        if ($dbCount -lt 0) {
            # FI-19: the figures of the base are being read off the Dispatcher; nothing is started on a guess.
            if (-not $Silent) { Set-Status "État de la base locale en cours de lecture : relancez la mise à jour dans un instant." "WARN" }
            try { Request-DomeniaIndexMetadata } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaIndexRefresh' $_ }
            return
        }
        if ($dbCount -eq 0) {
            if (-not $Silent) { Set-Status "Aucune base autonome : utilisez  Mettre à jour tout  dʼabord." "WARN" }
            return
        }
        # Point 21: the checkpoint is reused only on its controller and instance, with the data it describes;
        # otherwise the pass reads everything again and the journal says why. No USN goes to another controller.
        $checkpointCheck = Test-DomeniaSyncCheckpoint -Checkpoint $script:IndexInfo -Server ([string]$script:Conn.Server) -DomainDn ([string]$script:Conn.BaseDn) -ObjectCount ([long]$dbCount)
        $fullPass = (-not [bool]$checkpointCheck.Usable)
        if ($fullPass) {
            $lastUsn = [long]0; $lastInvocationId = ''; $since = ''
            if ($Silent -or $Confirmed) { Add-DomeniaUiLog -Area "Index" -Text ([string]$checkpointCheck.Reason) }
        }
        if (-not $Silent) {
            if (-not $Confirmed) {
                # UX-07: the estimate is confirmed in the page; the refresh starts again from the answer, once.
                # V10.20: a rejected checkpoint means a complete read of the domain, estimated and named as such.
                if ($fullPass) {
                    $why = ([string]$checkpointCheck.Reason) -replace '\s*:\s*lecture complète.*$',''
                    $impact=Get-DomeniaOperationImpactEstimate -Operation "IndexBuild" -ItemCount ([int][Math]::Min([long][int]::MaxValue,[Math]::Max([long]1,[long]$dbCount)))
                    [void](Request-DomeniaOperationImpact -Estimate $impact -Title ("Relecture complète du domaine : " + $why) -Target 'impact:IndexRefresh' -OnConfirm { Start-DomeniaIndexRefresh -Confirmed })
                    return
                }
                $impact=Get-DomeniaOperationImpactEstimate -Operation "IndexBuild" -ItemCount ([Math]::Max(1000,[int]($dbCount*0.05)))
                [void](Request-DomeniaOperationImpact -Estimate $impact -Title "Mettre à jour les changements" -Target 'impact:IndexRefresh' -OnConfirm { Start-DomeniaIndexRefresh -Confirmed })
                return
            }
            [void](Set-DomeniaControlText -Name "LblIndexStatus" -Text $(if ($fullPass) { "Relecture complète du domaine..." } else { "Recherche des objets modifies..." }))
        }
        Set-DomeniaIndexProgress -Mode Busy -Message $(if ($fullPass) { 'Relecture complète du domaine (repère de synchronisation non réutilisable)… progression exacte indisponible pendant la requête.' } else { 'Synchronisation incrémentale avec Active Directory… progression exacte indisponible pendant la requête.' })
        Start-UiTask `
            -Name "Mise a jour des changements" `
            -OperationId "IndexBuild" `
            -Code (Get-DomeniaIndexWorkerCode) `
            -Payload ([pscustomobject]@{
                Path = [string]$script:DatabaseScopedPath
                Progress = (New-DomeniaIndexProgressChannel)
                MaxObjects = (Get-DomeniaIndexLimits).MaxObjects
                BudgetMs = (Get-DomeniaIndexLimits).BudgetMs
                LastUsn = $lastUsn
                LastServer = $lastServer
                Since = $since
                LastInvocationId = $lastInvocationId
                ComputerFirst = [bool](Get-CfgValue "Index" "ComputerFirst" $true)
            }) `
            -CallbackState ([pscustomobject]@{ Started=(Get-Date) }) `
            -ReplaceKey "index" `
            -DisableControls @("BtnIndexBuild","BtnIndexRefresh") `
            -TimeoutSeconds ((Get-DomeniaIndexLimits).TimeoutSeconds) `
            -StatusText "Recherche des objets modifies en arriere-plan..." `
            -SuccessHandler "Complete-DomeniaIndexRefreshUi" `
            -ErrorHandler "Fail-DomeniaIndexBuildUi" | Out-Null
    }
    catch { Set-DomeniaIndexProgress -Mode Error -Message ('Synchronisation impossible : ' + $_.Exception.Message); [void](Show-DomeniaOperationError -Operation "Mise a jour des changements" -ErrorRecordOrException $_) }
}

function Request-DomeniaIndexAutoRefresh {
    # V10.20 : aucune operation longue ne part automatiquement a l'ouverture.
    # Une mise a jour d'index peut charger le DC plusieurs minutes et doit passer
    # par l'estimation d'impact + confirmation de l'operateur.
    try {
        # Unknown (-1, not read yet) or empty base: no notice on the age of the base.
        if ((Get-DomeniaDatabaseObjectCount) -le 0) { return }
        $when = ""
        try { $when = [string]$script:IndexInfo.Date } catch { Write-DomeniaSwallowed 'Core' 'Request-DomeniaIndexAutoRefresh' $_ }
        $ageMinutes = 999999
        if (-not [string]::IsNullOrWhiteSpace($when)) { try { $ageMinutes = ((Get-Date) - [datetime]$when).TotalMinutes } catch { Write-DomeniaSwallowed 'Core' 'Request-DomeniaIndexAutoRefresh' $_ } }
        $minutes = [Math]::Max(1,[int](Get-CfgValue "Index" "StartupDeltaMaxAgeMinutes" 30))
        if ($ageMinutes -ge $minutes) {
            Add-DomeniaUiLog -Area "Index" -Text ("Base locale agee de " + [int]$ageMinutes + " min : mise a jour recommandee, non lancee automatiquement. Utilise Outils > Base locale.")
        }
    } catch { Write-DomeniaSwallowed 'Core' 'Request-DomeniaIndexAutoRefresh' $_ }
}

function Sync-DomeniaIndexEntry {
    # Compatibility entry point for a real AD read; never called by a renderer.
    param([Parameter(Mandatory=$true)]$Entry,[string]$Type='',
        [Parameter(Mandatory=$true)][string]$ObservedAtUtc,[Parameter(Mandatory=$true)]$StoreContext)
    $pipe=New-DomeniaDirectoryReadPipe -Context $StoreContext
    $pipe.Input.Enqueue([pscustomobject]@{Properties=$Entry.Properties;Type=$Type;ObservedUtc=$ObservedAtUtc;Source=''})
    Complete-DomeniaDirectoryReadPipe -Pipe $pipe
    return 'Lecture AD en attente de confirmation SQLite.'
}

function Flush-DomeniaIndex {
    if (-not $script:IndexDirty) { return $false }
    $server = ""
    $baseDn = ""
    $usn = [long]0
    try { $server = [string]$script:IndexInfo.Server } catch { Write-DomeniaSwallowed 'Core' 'Flush-DomeniaIndex' $_ }
    try { $baseDn = [string]$script:IndexInfo.BaseDn } catch { Write-DomeniaSwallowed 'Core' 'Flush-DomeniaIndex' $_ }
    try { $usn = [long]$script:IndexInfo.Usn } catch { Write-DomeniaSwallowed 'Core' 'Flush-DomeniaIndex' $_ }
    $ok = Save-DomeniaIndex -Rows @($script:IndexRows) -Server $server -BaseDn $baseDn -HighestUsn $usn
    if ($ok) {
        $script:IndexDirty = $false
        Add-DomeniaUiLog -Area "Index" -Text ("Index enregistre : " + @($script:IndexRows).Count + " objet(s).")
    }
    return $ok
}

function Request-DomeniaIndexFirstBuild {
    # V10.20 : pas de construction massive automatique ni de popup surprise.
    # La creation complete reste disponible dans Outils > Base locale et passe
    # par l'estimateur reseau/DC avant lancement.
    try {
        if ((Get-DomeniaDatabaseObjectCount) -eq 0) {
            Add-DomeniaUiLog -Area "Index" -Text "Aucune base locale : construction disponible manuellement dans Outils > Base locale. Aucun scan AD automatique au demarrage."
        }
    } catch { Write-DomeniaSwallowed 'Core' 'Request-DomeniaIndexFirstBuild' $_ }
}


# =====================================================================
# Releve incrementiel du parc.
#
# Chercher sur quel poste travaille un compte coute une centaine de
# secondes si l on part de zero. Ce releve etale ce cout : a chaque
# lancement, un lot borne de postes est interroge en arriere-plan, et le
# resultat est conserve. Au bout de quelques jours, la reponse est deja
# la quand on en a besoin.
#
# Un point de prudence : un poste change d utilisateur. Une association
# relevee une fois et jamais reverifiee devient fausse tout en gardant
# l apparence d une information fiable. Chaque releve porte donc une date
# et une peremption, et les postes les plus anciennement vus repassent en
# tete de file.
# =====================================================================

# =====================================================================
# Releve partage entre consoles.
#
# Sans partage, chaque console refait le meme travail sur le meme parc.
# A vingt consoles, ce sont vingt fois les memes postes sondes, vingt
# fois les memes tickets demandes au controleur, et vingt fois les memes
# ouvertures de session reseau inscrites dans les journaux de securite
# des postes bureautiques. En rafale, depuis des comptes d administration,
# c est la signature d une reconnaissance laterale.
#
# Avec un fichier partage, le travail est fait une fois pour tout le monde.
# =====================================================================
function Get-DomeniaParkSharedPath {
    $configured = ""
    try { $configured = ([string](Get-CfgValue "ParkSweep" "SharedPath" "")).Trim() } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaParkSharedPath' $_ }
    if ([string]::IsNullOrWhiteSpace($configured)) { return "" }
    return $configured
}

function Merge-DomeniaParkState {
    # Fusion par poste, la ligne la plus recente gagne. Deux consoles qui
    # relevent le meme poste ne se detruisent donc pas mutuellement.
    param([Parameter(Mandatory=$true)]$Base,[Parameter(Mandatory=$true)]$Incoming)
    $merged = @{}
    foreach ($key in @($Base.Keys)) { $merged[$key] = $Base[$key] }
    $ajoutes = 0
    $remplaces = 0
    foreach ($key in @($Incoming.Keys)) {
        $new = $Incoming[$key]
        if (-not $merged.ContainsKey($key)) { $merged[$key] = $new; $ajoutes++; continue }
        $old = $merged[$key]
        $plusRecent = $false
        try { $plusRecent = ([datetime]$new.LastProbe -gt [datetime]$old.LastProbe) } catch { $plusRecent = $true }
        if ($plusRecent) { $merged[$key] = $new; $remplaces++ }
    }
    return [pscustomobject]@{ State=$merged; Ajoutes=$ajoutes; Remplaces=$remplaces; Total=$merged.Count }
}

function Sync-DomeniaParkShared {
    # Lit le fichier partage, fusionne avec l etat local, reecrit le tout.
    # Un verrou par fichier evite que deux consoles ecrivent en meme temps ;
    # s il n est pas obtenu, la console travaille en local et retentera.
    # D014: the file access (possibly UNC), the lock retries and the rewrite run in the ParkSharedSync worker
    # (Start-DomeniaParkSharedSync); the merged state comes back through Complete-DomeniaParkSharedSyncUi.
    # Nothing waits here, so the caller receives $null and the shared counters are logged when the worker ends.
    param([switch]$WriteBack)
    $path = Get-DomeniaParkSharedPath
    if ([string]::IsNullOrWhiteSpace($path)) { return $null }
    try { [void](Start-DomeniaParkSharedSync -WriteBack:$WriteBack) }
    catch { Add-DomeniaUiLog -Area "Parc" -Level "WARN" -Text ("Releve partage non synchronise, travail en local : " + $_.Exception.Message) }
    return $null
}

# =====================================================================
# Moisson du journal du controleur.
# Une seule requete rend des milliers de couples utilisateur-poste, sans
# toucher un seul poste de travail. C est la source a privilegier ; la
# sonde poste par poste ne sert plus qu a completer ce qui manque.
# =====================================================================
function Complete-DomeniaLogonHarvestUi {
    param($Result,$State)
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Pairs")
    if ($null -eq $effective) { throw "Moisson du journal sans resultat exploitable." }
    # D014: the stored park state is read off the Dispatcher; this result is applied once it is loaded.
    if ($null -eq $script:ParkState) { Add-DomeniaParkDeferredResult -Handler 'Complete-DomeniaLogonHarvestUi' -Result $Result -State $State; return }

    if (-not [bool]$effective.Success) {
        $detail = [string]$effective.Detail
        $message = "Journal du controleur illisible : " + $detail
        if ([string]$effective.Status -eq "REFUSE") {
            $message = "Lecture du journal de securite du controleur refusee. Sans ce droit, seule la sonde poste par poste peut alimenter le releve, et elle coute bien plus cher."
        }
        [void](Set-DomeniaControlText -Name "LblParkStatus" -Text $message)
        Set-Status $message "WARN"
        Add-DomeniaUiLog -Area "Parc" -Level "WARN" -Text $message
        return
    }

    $now = (Get-Date).ToString("s")
    $nouveaux = 0
    $connus = 0
    foreach ($p in @($effective.Pairs)) {
        $name = [string]$p.Computer
        $user = [string]$p.User
        if ([string]::IsNullOrWhiteSpace($name) -or [string]::IsNullOrWhiteSpace($user)) { continue }
        $key = $name.ToUpperInvariant()
        $connus++
        $attempts = 1
        if ($script:ParkState.ContainsKey($key)) {
            try { $attempts = [int]$script:ParkState[$key].Attempts + 1 } catch { $attempts = 1 }
        }
        $script:ParkState[$key] = [pscustomobject]@{
            Computer = $name; LastProbe = $now; Status = "Session"; User = $user; Attempts = $attempts
            ProbedBy = [string]$script:ProcessIdentityDisplay
        }
        if (Add-UserMachineLinkIfMissing -UserLogin $user -Computer $name -Source "Journal du controleur" -Details ("Ouverture de session enregistree le " + [string]$p.When + ".") -Confidence 90) { $nouveaux++ }
    }
    [void](Save-DomeniaParkState)
    $partage = Sync-DomeniaParkShared -WriteBack

    $summary = "Journal du controleur {0} : {1} evenement(s) lus, {2} couple(s) utilisateur-poste, {3} association(s) creee(s), en {4} ms. Aucun poste contacte." -f `
        ([string]$effective.Server),[int]$effective.Events,$connus,$nouveaux,([long]$effective.DurationMs)
    if ($null -ne $partage) { $summary = $summary + (" Partage : {0} recu(s), {1} actualise(s), {2} au total." -f [int]$partage.Recus,[int]$partage.Actualises,[int]$partage.Total) }
    [void](Set-DomeniaControlText -Name "LblParkStatus" -Text (Get-DomeniaParkStatusTextSafe))
    if (-not [bool]$State.Silent) { Set-Status $summary }
    Add-DomeniaUiLog -Area "Parc" -Text $summary
    try{Register-DomeniaOperationSample -Operation "LogonHarvest" -Mode "DC EventLog" -ItemCount ([int]$Result.Events) -DurationMs ([long]$Result.DurationMs) -BytesEstimated ([long]$Result.Events*2200) -AdQueries 1 -SuccessCount @($Result.Pairs).Count} catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaLogonHarvestUi' $_}
    try { Refresh-LinkGrid } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaLogonHarvestUi' $_ }
}

function Fail-DomeniaLogonHarvestUi {
    param($Message,$State)
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue." }
    [void](Set-DomeniaControlText -Name "LblParkStatus" -Text ("Moisson interrompue : " + $detail))
    Add-DomeniaUiLog -Area "Parc" -Level "WARN" -Text ("Moisson du journal interrompue : " + $detail)
    if (-not [bool]$State.Silent) { Set-Status ("Moisson du journal impossible : " + $detail) "ERROR" }
}

function Start-DomeniaLogonHarvest {
    param([switch]$Silent,[switch]$Confirmed)
    try {
        $maxEvents=[int](Get-CfgValue "ParkSweep" "HarvestMaxEvents" 5000)
        if((-not $Silent) -and (-not $Confirmed)){
            # UX-07: the estimate is confirmed in the page; the reading starts again from the answer, once.
            $impact=Get-DomeniaOperationImpactEstimate -Operation "LogonHarvest" -MaxEvents $maxEvents
            [void](Request-DomeniaOperationImpact -Estimate $impact -Title "Lire le journal du contrôleur" -Target 'impact:LogonHarvest' -OnConfirm { Start-DomeniaLogonHarvest -Confirmed })
            return
        }
        [void](Set-DomeniaControlText -Name "LblParkStatus" -Text "Lecture du journal du controleur...")
        Start-UiTask `
            -Name "Journal du controleur" `
            -OperationId "LogonHarvest" `
            -Code (Get-DomeniaLogonHarvestWorkerCode) `
            -Payload ([pscustomobject]@{
                Days = [int](Get-CfgValue "ParkSweep" "HarvestDays" 7)
                MaxEvents = [int](Get-CfgValue "ParkSweep" "HarvestMaxEvents" 5000)
            }) `
            -CallbackState ([pscustomobject]@{ Silent=[bool]$Silent }) `
            -ReplaceKey "harvest" `
            -DisableControls @("BtnParkHarvest") `
            -TimeoutSeconds 180 `
            -StatusText "Lecture du journal du controleur en arriere-plan..." `
            -SuccessHandler "Complete-DomeniaLogonHarvestUi" `
            -ErrorHandler "Fail-DomeniaLogonHarvestUi" | Out-Null
    }
    catch { [void](Show-DomeniaOperationError -Operation "Journal du controleur" -ErrorRecordOrException $_) }
}

function Get-DomeniaLogonHarvestWorkerCode {
    return @'
$watch = [System.Diagnostics.Stopwatch]::StartNew()
$pairs = New-Object Collections.ArrayList
$server = ([string]$Context.Server).Trim()
if ([string]::IsNullOrWhiteSpace($server)) { throw 'Aucun controleur de domaine connu.' }
$days = [Math]::Max(1,[Math]::Min(30,[int]$Payload.Days))
$maxEvents = [Math]::Max(200,[Math]::Min(20000,[int]$Payload.MaxEvents))

# Une seule requete sur le controleur rend des milliers de couples
# utilisateur-poste. Aucun poste de travail n est contacte, aucun
# evenement n est genere sur le parc, aucun ticket supplementaire n est
# demande. C est incomparablement moins couteux qu une sonde par poste.
$since = (Get-Date).AddDays(-$days)
$filter = @{ LogName='Security'; Id=@(4768,4769,4624); StartTime=$since }
$params = @{ ComputerName=$server; FilterHashtable=$filter; MaxEvents=$maxEvents; ErrorAction='Stop' }
if ([bool]$Context.UseCredential -and $null -ne $Context.Credential) { $params['Credential'] = Get-WAdCredential $Context }

$events = @()
$lease = Enter-WCredentialAttempt -Context $Context -Channel Directory
try { $events = @(Get-WinEvent @params) }
catch {
    # return quitte Invoke-DomeniaPinnedOperation avant le catch du wrapper.
    # Sans cet appel, Register-WCredentialFailure ne voit jamais le refus
    # et les collectes suivantes reessaient le meme compte.
    # Le statut reste retourne : Complete-DomeniaLogonHarvestUi lit REFUSE/ERREUR.
    [void](Register-WCredentialFailure -Context $Context -ErrorValue $_)
    $message = [string]$_.Exception.Message
    $status = 'ERREUR'
    if ($message -match '(?i)access|denied|refus|non autoris|privil') { $status = 'REFUSE' }
    $watch.Stop()
    return [pscustomobject]@{ Pairs=@(); Status=$status; Detail=$message; Events=0; Server=$server; DurationMs=[long]$watch.ElapsedMilliseconds; Success=$false }
} finally { Exit-WCredentialAttempt -Lease $lease }

$index = @{}
foreach ($ev in $events) {
    $xml = $null
    try { $xml = [xml]$ev.ToXml() } catch { continue }
    $target = ''
    $station = ''
    foreach ($d in @($xml.Event.EventData.Data)) {
        $n = [string]$d.Name
        if ($n -eq 'TargetUserName') { $target = [string]$d.'#text' }
        elseif ($n -eq 'WorkstationName') { $station = [string]$d.'#text' }
    }
    if ([string]::IsNullOrWhiteSpace($target) -or [string]::IsNullOrWhiteSpace($station)) { continue }
    # Un nom se terminant par le signe dollar est un compte machine, pas
    # un utilisateur : ces couples n ont aucun interet ici.
    if ($target.EndsWith([string][char]36)) { continue }
    $station = $station.Trim().TrimEnd([char]36)
    if ($station.Contains('.')) { $station = $station.Split('.')[0] }
    if ($station.Length -lt 3) { continue }
    if ($station -match '^(-|::1|127\.)') { continue }
    $key = $station.ToUpperInvariant()
    $when = $ev.TimeCreated
    if ($index.ContainsKey($key)) {
        if ($index[$key].When -ge $when) { continue }
    }
    $index[$key] = [pscustomobject]@{ Computer=$station; User=$target.Trim(); When=$when }
}

foreach ($key in @($index.Keys)) {
    $e = $index[$key]
    [void]$pairs.Add([pscustomobject]@{
        Computer = [string]$e.Computer
        User = [string]$e.User
        When = ([datetime]$e.When).ToString('s')
    })
}

$watch.Stop()
[pscustomobject]@{
    Pairs = @($pairs)
    Status = 'OK'
    Detail = ''
    Events = @($events).Count
    Server = $server
    DurationMs = [long]$watch.ElapsedMilliseconds
    Success = $true
}

'@
}

function Save-DomeniaParkState {
    if($null -eq $script:ParkState){return $false}
    $ok=$true
    foreach($key in @($script:ParkState.Keys)){
        $r=$script:ParkState[$key]
        $copy=[pscustomobject]@{Key=[string]$key;Computer=[string]$r.Computer;LastProbe=[string]$r.LastProbe;Status=[string]$r.Status;User=[string]$r.User;Attempts=[int]$r.Attempts}
        if(-not (Queue-DomeniaMetadata -Kind Park -Key $key -Row $copy)){$ok=$false;break}
    }
    return $ok
}

function Get-DomeniaParkPriority {
    # File de priorite. Jamais releves d abord, puis les releves perimes,
    # du plus ancien au plus recent. Un poste vu recemment avec une session
    # n est pas redemande : c est tout l interet du cache.
    param([int]$Limit = 150)
    $rows = @($script:IndexRows | Where-Object { [string]$_.Type -eq "Machine" -and [string]$_.State -ne "Desactive" })
    if (@($rows).Count -eq 0) { return @() }
    # FI-19: the stored survey is read off the Dispatcher (LocalIndexRead ParkState). Until it is in memory no priority
    # is computed: a queue built without the stored probes would ask again the workstations already surveyed.
    if ($null -eq $script:ParkState) { Request-DomeniaParkStateReload; return @() }

    $refreshDays = [int](Get-CfgValue "ParkSweep" "RefreshDays" 14)
    $retryDays = [int](Get-CfgValue "ParkSweep" "RetryDays" 2)
    $now = Get-Date

    $jamais = New-Object System.Collections.Generic.List[object]
    $perimes = New-Object System.Collections.Generic.List[object]
    $script:ParkDormants = 0
    foreach ($r in $rows) {
        $name = [string]$r.Name
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        $entry = $null
        $key = $name.ToUpperInvariant()
        if ($script:ParkState.ContainsKey($key)) { $entry = $script:ParkState[$key] }
        if ($null -eq $entry) { $jamais.Add([pscustomobject]@{ Name=$name; Age=[double]999999 }); continue }
        $age = [double]999999
        try { $age = ((Get-Date) - [datetime]$entry.LastProbe).TotalDays } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaParkPriority' $_ }
        $seuil = $refreshDays
        if ([string]$entry.Status -ne "Session") { $seuil = $retryDays }
        if ($age -lt $seuil) { continue }

        # Un poste qui ne s est pas authentifie depuis notre dernier releve
        # n a pas pu changer de session : inutile de le redemander. C est
        # lastLogonTimestamp qui porte cette information, pas whenChanged,
        # lequel ne bouge qu au renouvellement du mot de passe machine.
        $dormant = $false
        try {
            $logon = [string]$r.LastLogon
            if (-not [string]::IsNullOrWhiteSpace($logon)) {
                if ([datetime]$logon -le [datetime]$entry.LastProbe) { $dormant = $true }
            }
        }
        catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaParkPriority' $_ }
        if ($dormant) { $script:ParkDormants++; continue }

        $perimes.Add([pscustomobject]@{ Name=$name; Age=$age })
    }

    $queue = New-Object System.Collections.Generic.List[string]
    foreach ($j in $jamais) {
        if ($queue.Count -ge $Limit) { break }
        $queue.Add([string]$j.Name)
    }
    foreach ($p in ($perimes.ToArray() | Sort-Object -Property Age -Descending)) {
        if ($queue.Count -ge $Limit) { break }
        $queue.Add([string]$p.Name)
    }
    return $queue.ToArray()
}

function Get-DomeniaParkCoverage {
    # FI-19: no SQLite read here. The stored survey is read by the LocalIndexRead worker (Request-DomeniaParkStateReload);
    # the active workstation count comes from the in-memory index, the figures of the base (IndexMetadata) or that survey.
    if ($null -eq $script:ParkState) { Request-DomeniaParkStateReload }
    return (Get-DomeniaParkCoverageFigures -State $script:ParkState -IndexRows @($script:IndexRows) -KnownMachineCount (Get-DomeniaParkMachineCount) -Dormants ([int]$script:ParkDormants))
}

function Get-DomeniaParkCoverageText {
    $c = Get-DomeniaParkCoverage
    if ([int]$c.Machines -lt 0) { return (Get-DomeniaParkCoverageWaitingText -Surveyed ([int]$c.Releves)) }
    if ([int]$c.Machines -eq 0) { return 'Aucun poste indexé : construisez dʼabord lʼindex.' }
    $pct = [Math]::Round(100.0 * [int]$c.Releves / [int]$c.Machines,0)
    $age = ""
    if (-not [string]::IsNullOrWhiteSpace([string]$c.Dernier)) {
        try {
            $span = (Get-Date) - [datetime]$c.Dernier
            if ([int]$span.TotalDays -ge 1) { $age = ", dernier passage il y a " + [int]$span.TotalDays + " jour(s)" }
            else { $age = ", dernier passage il y a " + [int]$span.TotalHours + " heure(s)" }
        }
        catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaParkCoverageText' $_ }
    }
    $dormants = ""
    if ([int]$c.Dormants -gt 0) { $dormants = ", " + [int]$c.Dormants + " écarté(s) faute dʼactivité depuis le dernier relevé" }
    return ("{0} poste(s) actif(s), {1} relevé(s) soit {2} pour cent, {3} avec un utilisateur connu{4}{5}." -f `
        [int]$c.Machines,[int]$c.Releves,$pct,[int]$c.AvecSession,$dormants,$age)
}

function Complete-DomeniaParkSweepUi {
    param($Result,$State)
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Results")
    if ($null -eq $effective) { throw "Releve du parc sans resultat exploitable." }
    # D014: the stored park state is read off the Dispatcher; this result is applied once it is loaded.
    if ($null -eq $script:ParkState) { Add-DomeniaParkDeferredResult -Handler 'Complete-DomeniaParkSweepUi' -Result $Result -State $State; return }

    $now = (Get-Date).ToString("s")
    $nouveaux = 0
    foreach ($r in @($effective.Results)) {
        $name = [string]$r.Computer
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        if ([string]$r.Status -eq "Reporte") { continue }
        $key = $name.ToUpperInvariant()
        $attempts = 1
        if ($script:ParkState.ContainsKey($key)) {
            try { $attempts = [int]$script:ParkState[$key].Attempts + 1 } catch { $attempts = 1 }
        }
        $script:ParkState[$key] = [pscustomobject]@{
            Computer = $name; LastProbe = $now; Status = [string]$r.Status; User = [string]$r.User; Attempts = $attempts
        }
        if ([string]$r.Status -eq "Session" -and -not [string]::IsNullOrWhiteSpace([string]$r.User)) {
            # L association existante n est jamais ecrasee : c est la regle
            # commune a toutes les sources.
            if (Add-UserMachineLinkIfMissing -UserLogin ([string]$r.User) -Computer $name -Source "Releve du parc" -Details ([string]$r.Detail) -Confidence 95) { $nouveaux++ }
        }
    }
    [void](Save-DomeniaParkState)
    $partage = Sync-DomeniaParkShared -WriteBack

    $summary = "Releve du parc : {0} poste(s) demandes, {1} joignable(s), {2} interroge(s), {3} session(s) trouvee(s), {4} association(s) creee(s), en {5} ms." -f `
        [int]$effective.Requested,[int]$effective.Reachable,[int]$effective.Probed,[int]$effective.Found,$nouveaux,([long]$effective.DurationMs)
    if ($null -ne $partage) { $summary = $summary + (" Partage : {0} recu(s), {1} actualise(s), {2} au total." -f [int]$partage.Recus,[int]$partage.Actualises,[int]$partage.Total) }
    Add-DomeniaUiLog -Area "Parc" -Text $summary
    try{$fb=0;$tb=0;try{$fb=[int]$Result.FallbackTasks}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaParkSweepUi' $_};try{$tb=[long]$Result.TaskBytes}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaParkSweepUi' $_};Register-DomeniaOperationSample -Operation "ParkSweep" -Mode "Classic+TaskFallback" -ItemCount ([int]$Result.Requested) -DurationMs ([long]$Result.DurationMs) -BytesEstimated ([Math]::Max([long]$tb,[long]$Result.Requested*24000)) -RemoteAttempts ([int]$Result.Probed) -FallbackTasks $fb -SuccessCount ([int]$Result.Found) -FailureCount ([Math]::Max(0,[int]$Result.Probed-[int]$Result.Found))}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaParkSweepUi' $_}
    [void](Set-DomeniaControlText -Name "LblParkStatus" -Text (Get-DomeniaParkStatusTextSafe))
    if (-not [bool]$State.Silent) { Set-Status $summary }
    try { Refresh-LinkGrid } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaParkSweepUi' $_ }
}

function Start-DomeniaParkSweep {
    param([switch]$Silent)
    # Decision David 2026-10-05: no whole-park detection any more (too wide, it disturbed the associations).
    # Detection runs only on the rows displayed in Rechercher, after the user's filters.
    if(-not $Silent){Set-Status 'Détection sur tout le parc retirée : filtrez la liste dans Rechercher puis Détecter la liste.' 'WARN'}
}

function Request-DomeniaParkSweepAtStartup {
    # V10.20 : jamais de balayage distant, journal DC ou Task/PsExec en douce au
    # demarrage. Toutes les operations longues sont lancees manuellement apres
    # estimation d'impact et confirmation.
    try {
        if ([bool](Get-DomeniaSetting "ParkSweepEnabled" $false)) {
            Add-DomeniaUiLog -Area "Parc" -Text "Releve automatique configure mais differe : aucun balayage du parc n'est lance au demarrage."
        }
    } catch { Write-DomeniaSwallowed 'Core' 'Request-DomeniaParkSweepAtStartup' $_ }
}


function Get-DomeniaParkSweepWorkerCode {
    return @'
$results = New-Object Collections.ArrayList
$watch = [System.Diagnostics.Stopwatch]::StartNew()
$budgetMs = [Math]::Max(10000,[int]$Payload.BudgetMs)
$targets = @($Payload.Computers)
$cred = Get-WMachineCredential $Context
if (@($targets).Count -eq 0) { throw 'Aucun poste a relever.' }

function Test-Budget { return ($watch.ElapsedMilliseconds -lt $budgetMs) }

function Get-ReachableSet {
    # Ping parallele par lots : sur un parc, la grande majorite des postes
    # sont eteints, et les ecarter coute mille fois moins cher qu ouvrir
    # une session sur chacun.
    param([string[]]$Names,[int]$TimeoutMs = 800,[int]$Batch = 64)
    $reachable = New-Object Collections.ArrayList
    $index = 0
    $total = @($Names).Count
    while ($index -lt $total) {
        if (-not (Test-Budget)) { break }
        $last = [Math]::Min($index + $Batch - 1,$total - 1)
        $pending = New-Object Collections.ArrayList
        for ($i = $index; $i -le $last; $i++) {
            $name = [string]$Names[$i]
            if ([string]::IsNullOrWhiteSpace($name)) { continue }
            try {
                $ping = New-Object Net.NetworkInformation.Ping
                [void]$pending.Add([pscustomobject]@{ Name=$name; Ping=$ping; Task=$ping.SendPingAsync($name,$TimeoutMs) })
            }
            catch { }
        }
        if ($pending.Count -gt 0) {
            $tasks = @(@($pending) | ForEach-Object { $_.Task })
            try { [void][System.Threading.Tasks.Task]::WaitAll($tasks,($TimeoutMs + 1500)) } catch { }
            foreach ($entry in @($pending)) {
                try {
                    if ($entry.Task.IsCompleted -and $null -ne $entry.Task.Result -and $entry.Task.Result.Status -eq 'Success') {
                        [void]$reachable.Add([string]$entry.Name)
                    }
                }
                catch { }
                try { $entry.Ping.Dispose() } catch { }
            }
        }
        $index = $last + 1
    }
    return @($reachable)
}

$pingWatch = [System.Diagnostics.Stopwatch]::StartNew()
$reachable = Get-ReachableSet $targets 800 64
$pingWatch.Stop()
$reachableSet = @{}
foreach ($r in @($reachable)) { $reachableSet[([string]$r).ToUpperInvariant()] = $true }

$probed = 0
$found = 0
$fallbackTasks = 0
$taskBytes = 0
foreach ($computer in @($targets)) {
    $name = ([string]$computer).Trim()
    if ([string]::IsNullOrWhiteSpace($name)) { continue }
    if (-not $reachableSet.ContainsKey($name.ToUpperInvariant())) {
        [void]$results.Add([pscustomobject]@{ Computer=$name; Status='Eteint'; User=''; Detail='Ne repond pas au ping.' })
        continue
    }
    if (-not (Test-Budget)) {
        [void]$results.Add([pscustomobject]@{ Computer=$name; Status='Reporte'; User=''; Detail='Budget de temps atteint, sera repris au prochain lancement.' })
        continue
    }
    $probed++
    $session = $null
    try {
        $session = New-WDomeniaCimSession $Context $name $null 6
        $cs = Get-CimInstance -CimSession $session -ClassName 'Win32_ComputerSystem' -Property 'UserName' -ErrorAction Stop
        $current = [string]$cs.UserName
        if ([string]::IsNullOrWhiteSpace($current)) {
            [void]$results.Add([pscustomobject]@{ Computer=$name; Status='Aucune session'; User=''; Detail='Poste allume, aucune session ouverte.' })
        }
        else {
            $short = $current
            if ($short.Contains([string][char]92)) { $short = $short.Split([char]92)[-1] }
            if ($short.Contains('@')) { $short = $short.Split('@')[0] }
            $short = $short.Trim()
            $found++
            [void]$results.Add([pscustomobject]@{ Computer=$name; Status='Session'; User=$short; Detail=('Session de ' + $current + '.') })
        }
    }
    catch {
        $classicError=[string]$_.Exception.Message
        try {
            $local='$cs=Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop;$u=[string]$cs.UserName;[pscustomobject]@{UserName=$u}'
            $fb=Invoke-WRemoteTaskScript $Context $name $local ([pscustomobject]@{}) ([Math]::Min(45,[int]$Context.TaskFallbackTimeoutSeconds)) $classicError
            $fallbackTasks++;try{$taskBytes += [long]$fb.DomeniaBytesSent+[long]$fb.DomeniaBytesReceived}catch{}
            $current=[string]$fb.UserName
            if([string]::IsNullOrWhiteSpace($current)){[void]$results.Add([pscustomobject]@{Computer=$name;Status='Aucune session';User='';Detail='Lu localement via tache planifiee.'})}
            else{$short=$current;if($short.Contains([string][char]92)){$short=$short.Split([char]92)[-1]};if($short.Contains('@')){$short=$short.Split('@')[0]};$found++;[void]$results.Add([pscustomobject]@{Computer=$name;Status='Session';User=$short.Trim();Detail=('Session '+$current+' via tache planifiee.')})}
        } catch {[void]$results.Add([pscustomobject]@{Computer=$name;Status='Acces distant impossible';User='';Detail=$_.Exception.Message})}
    }
    finally { try { Remove-WDomeniaCimSession $session } catch { } }
}

$watch.Stop()
[pscustomobject]@{
    Results = @($results)
    Requested = @($targets).Count
    Reachable = @($reachable).Count
    Probed = $probed
    Found = $found
    PingMs = [long]$pingWatch.ElapsedMilliseconds
    DurationMs = [long]$watch.ElapsedMilliseconds
    FallbackTasks = $fallbackTasks
    TaskBytes = $taskBytes
    Success = $true
}

'@
}

function Complete-DomeniaIndexBuildUi {
    param($Result,$State)
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Rows")
    if ($null -eq $effective) { throw "Indexation sans resultat exploitable." }
    $rows = @($effective.Rows)
    $transfer = $null; if ($null -ne $effective.PSObject.Properties['Transfer']) { $transfer = $effective.Transfer }
    $rowCount = if ($null -ne $effective.PSObject.Properties['RowCount']) { [long]$effective.RowCount } else { [long]@($rows).Count }
    if ([bool]$effective.Truncated) {
        # A pass stopped at its limit never replaces a fuller base and never moves the checkpoint: the next update reads
        # everything again, and the Accueil warns that its figures may be underestimated.
        [void](Update-DomeniaIndexDatabaseRows -Rows $rows -Transfer $transfer -Server ([string]$effective.Server) -BaseDn ([string]$effective.BaseDn) -HighestUsn 0 -TotalCount 0 -Complete $false)
        $cut = Get-DomeniaIndexCut -Effective $effective
        Set-DomeniaIndexPartial -BaseDn ([string]$effective.BaseDn) -Count $rowCount -Reason $cut.Reason -Limit $cut.Limit
    } else {
        [void](Save-DomeniaIndex -Rows $rows -Transfer $transfer -Server ([string]$effective.Server) -BaseDn ([string]$effective.BaseDn) -HighestUsn ([long]$effective.HighestUsn) -InvocationId ([string]$effective.InvocationId) -Reconcile $effective.Reconcile)
    }
    $script:IndexRows = @()
    # FI-19: figures read again off the Dispatcher; Complete-DomeniaIndexMetadataUi updates the page.
    Request-DomeniaIndexMetadata
    $linkChanges = 0

    $users = $(if ($null -ne $transfer) { [long]$effective.UserCount } else { @($rows | Where-Object { [string]$_.Type -eq "Utilisateur" }).Count })
    $computers = $(if ($null -ne $transfer) { [long]$effective.ComputerCount } else { @($rows | Where-Object { [string]$_.Type -eq "Machine" }).Count })
    $suffix = ""
    if ([bool]$effective.Truncated) {
        $suffix = if ([string]$effective.LimitReason -eq 'erreur') { ' Index partiel : une lecture AD a échoué.' } else { ' Index partiel : limite atteinte.' }
    }
    # Lot L01: the LAPS expiration is read with the computers; the schema tells whether it exists in this domain.
    $lapsSchemaProperty = $effective.PSObject.Properties['LapsSchema']
    if (($null -ne $lapsSchemaProperty) -and ([string]$lapsSchemaProperty.Value -eq 'Absent')) { $suffix += " Expiration LAPS non disponible dans ce domaine." }
    $summary = "Lecture terminée, enregistrement local en attente : {0} objet(s), dont {1} compte(s) et {2} poste(s).{3}" -f `
        $rowCount,$users,$computers,$suffix
    [void](Set-DomeniaControlText -Name "LblIndexStatus" -Text $summary)
    Set-DomeniaIndexProgress -Mode Busy -Message ($summary + ' Validation de lʼécriture en cours…')
    Set-Status $summary
    # DS-09: the duration of the AD read goes to the journal only.
    Add-DomeniaUiLog -Area "Index" -Text ($summary + " Durée de la lecture AD : " + [string]([long]$effective.DurationMs) + " ms. Associations resynchronisées : " + $linkChanges + ". " + ((@($effective.Diagnostics)) -join " | "))
    Update-DomeniaIndexStats
    # The home overview reads this base: out of date now, computed again once the queued index is saved (storage).
    $script:FleetStale = $true
    try{Register-DomeniaOperationSample -Operation "IndexBuild" -Mode "AD" -ItemCount $rowCount -DurationMs ([long]$effective.DurationMs) -BytesEstimated ([long]($rowCount*1800)) -AdQueries ([Math]::Max(1,[int][Math]::Ceiling($rowCount/1000.0))) -SuccessCount $rowCount -StartedAt $(if($null-ne$State.PSObject.Properties['StartedAt']){[string]$State.StartedAt}else{""})}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaIndexBuildUi' $_}
    if ($null -ne $State -and [bool]$State.UpdateLinks) {
        try { Start-DomeniaLogonHarvest -Silent } catch { Add-DomeniaUiLog -Area "Base autonome" -Level "WARN" -Text ("Mise a jour des associations via journal non lancee : " + $_.Exception.Message) }
    }
}

function Fail-DomeniaIndexBuildUi {
    param($Message,$State)
    if($null -ne $State -and $null -ne $State.PSObject.Properties['RefreshOperationId'] -and [string]$State.RefreshOperationId){Fail-DomeniaOuRefresh -OperationId ([string]$State.RefreshOperationId) -Message ([string]$Message)}
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue." }
    [void](Set-DomeniaControlText -Name "LblIndexStatus" -Text ("Base autonome impossible : " + $detail))
    Set-DomeniaIndexProgress -Mode Error -Message ("Échec de mise à jour : " + $detail)
    Set-Status ("Base autonome impossible : " + $detail) "ERROR"
    Add-DomeniaUiLog -Area "Index" -Level "ERROR" -Text $detail
}

function Get-DomeniaIndexLimits {
    # Zero means no object quota. Time budgets remain explicit; an interrupted pass never replaces the base.
    $max = [long](Get-CfgValue "Index" "MaxObjects" 0)
    if ($max -lt 0) { $max = 0 }
    $budget = [int](Get-CfgValue "Index" "BudgetMs" 1200000); if ($budget -eq 240000) { $budget = 1200000 }
    $budget = [Math]::Max(30000,$budget)
    return [pscustomobject]@{ MaxObjects = $max; BudgetMs = $budget; TimeoutSeconds = [Math]::Max(300,[int]($budget / 1000) + 120) }
}

function Get-DomeniaIndexCut {
    # The limit that cut the last pass, as the worker reported it: 'volume' names Index.MaxObjects, 'temps' names
    # Index.BudgetMs, 'serveur' names the controller's own cut (ServerTimeLimit), which the worker cannot read back
    # from the reply. A pass that never hit a limit, or a worker older than these fields, answers an empty reason.
    param($Effective)
    if ($null -eq $Effective) { return [pscustomobject]@{ Reason = ''; Limit = 0 } }
    $reason = ''
    $reasonProperty = $Effective.PSObject.Properties['LimitReason']
    if ($null -ne $reasonProperty) { $reason = [string]$reasonProperty.Value }
    $limit = 0
    if ($reason -eq 'temps') { try { $limit = [int]$Effective.LimitBudgetMs } catch { $limit = 0 } }
    elseif ($reason -eq 'volume') { try { $limit = [int]$Effective.LimitMaxObjects } catch { $limit = 0 } }
    elseif ($reason -eq 'serveur') { try { $limit = [int]$Effective.LimitServerSeconds } catch { $limit = 0 } }
    elseif ($reason -eq 'erreur') { $limit = 0 }
    else { $reason = '' }
    return [pscustomobject]@{ Reason = $reason; Limit = $limit }
}

function Set-DomeniaIndexPartial {
    # Remembers that the last update of this domain stopped at its limit (the Accueil warns); cleared by a complete pass.
    # $Count is what this pass read. $Reason and $Limit name the limit that cut it, so the warning points at the key to
    # raise instead of only saying "limite". A marker written before these two fields still reads, with no limit named.
    param([string]$BaseDn = '',[int]$Count = 0,[string]$Reason = '',[int]$Limit = 0,[switch]$Clear)
    $value = if ($Clear) { '' } else { $BaseDn + '|' + [datetime]::Now.ToString('dd/MM/yyyy HH:mm',[Globalization.CultureInfo]::InvariantCulture) + '|' + [string]$Count + '|' + [string]$Reason + '|' + [string]$Limit }
    # P-CD-09: without this marker Accueil would present a partial base as complete; a failure is said in the journal.
    try { Set-DomeniaSetting 'Index.Partial' $value; Save-DomeniaSettings -Immediate }
    catch {
        $what = if ($Clear) { 'La fin de la mise à jour partielle' } else { 'La mise à jour partielle de la base locale' }
        Add-DomeniaUiLog -Area 'Index' -Level 'WARN' -Text ($what + ' nʼa pas pu être enregistrée dans les préférences : lʼavertissement dʼAccueil peut être faux après un redémarrage. ' + $_.Exception.Message)
    }
}

function Get-DomeniaIndexPartialText {
    $value = [string](Get-DomeniaSetting 'Index.Partial' '')
    if (-not $value) { return '' }
    $parts = $value -split '\|'
    if ($parts.Count -lt 3 -or $parts[0] -ine [string]$script:Conn.BaseDn) { return '' }
    $detail = [string]$parts[2] + ' objet(s) relu(s) dans la passe'
    if ($parts.Count -ge 5 -and [string]$parts[3] -eq 'erreur') { $detail += ' ; au moins une lecture AD a échoué' }
    elseif ($parts.Count -ge 5 -and [string]$parts[3]) { $detail += ' sur une limite de ' + [string]$parts[4] + $(if ([string]$parts[3] -eq 'temps') { ' ms' } elseif ([string]$parts[3] -eq 'serveur') { ' s' } else { ' objets' }) }
    return ('la dernière mise à jour était incomplète le ' + $parts[1] + ' (' + $detail + ').')
}

function Test-DomeniaIndexWriteReady {
    # A new directory pass must observe the committed checkpoint of the previous one.
    if ($null -ne $script:IndexWalk) { Set-Status 'Une passe par OU est déjà en cours.' 'WARN'; return $false }
    # Points 32 and 35: no new directory pass during a base maintenance, a suspended writer or a nearly full disk.
    $storageRefusal = Get-DomeniaStorageCollectionRefusal
    if ($storageRefusal) { Set-Status $storageRefusal 'WARN'; return $false }
    if ($null -ne $script:Persistence) {
        if ($script:Persistence.Job) { Set-Status 'Enregistrement local en cours : attendez sa confirmation avant une nouvelle lecture.' 'WARN'; return $false }
        foreach ($item in $script:Persistence.Pending.Values) {
            if ($item.Kind -eq 'IndexBulk') { Set-Status 'Une mise à jour attend son enregistrement. Vérifiez lʼonglet Stockage de la base.' 'WARN'; return $false }
        }
    }
    return $true
}

function Start-DomeniaIndexScopeBuild {
    # Reconcile this OU only. An empty scope or the domain root is refused.
    param([string]$Dn,[string]$RefreshOperationId='')
    if (-not (Test-DomeniaIndexWriteReady)) { return }
    try {
        $target = ([string]$Dn).Trim()
        if (-not $target -or $target -ieq [string]$script:Conn.BaseDn) { Set-Status 'Choisissez une OU avant de lancer sa mise à jour.' 'WARN'; return }
        $limits = Get-DomeniaIndexLimits
        Set-DomeniaIndexProgress -Mode Busy -Message ('Lecture de ' + $target + ' dans Active Directory… progression exacte indisponible pendant la requête.')
        [void](Set-DomeniaControlText -Name "LblFleetDashboard" -Text "Lecture de lʼOU dans lʼannuaire en arrière-plan...")
        try { Set-DomeniaFleetDashboardToolTip } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaIndexScopeBuild' $_ }
        $job = Start-UiTask `
            -Name "Mise à jour de lʼOU dans la base autonome" `
            -OperationId "IndexBuild" `
            -Code (Get-DomeniaIndexWorkerCode) `
            -Payload ([pscustomobject]@{ Path = [string]$script:DatabaseScopedPath; Progress = (New-DomeniaIndexProgressChannel); MaxObjects = $limits.MaxObjects; BudgetMs = $limits.BudgetMs; LastUsn = [long]0; LastServer = ""; Since = ""; ComputerFirst = $true; SearchBase = $target }) `
            -CallbackState ([pscustomobject]@{ Started = (Get-Date); SearchBase = $target; Epoch = [long]$script:SessionEpoch; Path = [string]$script:DatabaseScopedPath; RefreshOperationId = $RefreshOperationId }) `
            -ReplaceKey "index" `
            -DisableControls @("BtnIndexBuild","BtnIndexRefresh","BtnIndexWalk","BtnIndexScopeUpdate","BtnFleetIndexScope") `
            -TimeoutSeconds $limits.TimeoutSeconds `
            -StatusText "Lecture de lʼOU dans lʼannuaire en arrière-plan..." `
            -SuccessHandler "Complete-DomeniaIndexScopeUi" `
            -ErrorHandler "Fail-DomeniaIndexBuildUi"
        return $job
    } catch { if($RefreshOperationId){Fail-DomeniaOuRefresh -OperationId $RefreshOperationId -Message $_.Exception.Message}; Set-DomeniaIndexProgress -Mode Error -Message ('Mise à jour de lʼOU impossible : ' + $_.Exception.Message); Set-Status ('Mise à jour de lʼOU impossible : ' + $_.Exception.Message) 'WARN' }
}

function Complete-DomeniaIndexScopeUi {
    param($Result,$State)
    if ($null -ne $State -and [long]$State.Epoch -ne [long]$script:SessionEpoch) { return }
    if ($null -ne $State -and $null -ne $State.PSObject.Properties['Path'] -and [string]$State.Path -cne [string]$script:DatabaseScopedPath) { return }
    $refreshId = if($null -ne $State -and $null -ne $State.PSObject.Properties['RefreshOperationId']){[string]$State.RefreshOperationId}else{''}
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Rows")
    if ($null -eq $effective) { if($refreshId){Fail-DomeniaOuRefresh -OperationId $refreshId -Message "Réponse AD inexploitable : relevé des postes non lancé."}; throw "Mise à jour de lʼOU sans résultat exploitable." }
    $rows = @($effective.Rows)
    $transfer = $null; if ($null -ne $effective.PSObject.Properties['Transfer']) { $transfer = $effective.Transfer }
    $rowCount = if ($null -ne $effective.PSObject.Properties['RowCount']) { [long]$effective.RowCount } else { [long]@($rows).Count }
    # An OU pass has its own successful coverage date and never modifies the domain checkpoint.
    $scopeKey = 'ou:' + ([string]$State.SearchBase).Trim().ToLowerInvariant()
    [void](Update-DomeniaIndexDatabaseRows -Rows $rows -Transfer $transfer -Server ([string]$effective.Server) -BaseDn ([string]$State.SearchBase) -HighestUsn 0 -SyncScope $scopeKey -Complete (-not [bool]$effective.Truncated) -InvocationId ([string]$effective.InvocationId) -Reconcile $effective.Reconcile -RefreshOperationId $refreshId)
    $computers = $(if ($null -ne $transfer) { [long]$effective.ComputerCount } else { @($rows | Where-Object { [string]$_.Type -eq "Machine" }).Count })
    if ([bool]$effective.Truncated) {
        $cut = Get-DomeniaIndexCut -Effective $effective
        Set-DomeniaIndexPartial -BaseDn ([string]$script:Conn.BaseDn) -Count $rowCount -Reason $cut.Reason -Limit $cut.Limit
    }
    $suffix = if ([bool]$effective.Truncated) { ' Lecture incomplète : consultez le motif, puis relancez cette OU.' } else { '' }
    $summary = ("OU lue, enregistrement local en attente : {0} objet(s), dont {1} poste(s), en {2} s.{3}" -f $rowCount,$computers,[int]([long]$effective.DurationMs / 1000),$suffix)
    [void](Set-DomeniaControlText -Name "LblIndexStatus" -Text $summary)
    Set-DomeniaIndexProgress -Mode Busy -Message ($summary + ' Validation de lʼécriture en cours…')
    Set-Status $summary
    Add-DomeniaUiLog -Area "Index" -Text ($summary + " OU : " + [string]$effective.SearchBase)
    $script:FleetStale = $true
    if($refreshId){
        if([bool]$effective.Truncated){Fail-DomeniaOuRefresh -OperationId $refreshId -Message "Lecture AD incomplète : données partielles conservées, relevé des postes non lancé."}
        else{Set-DomeniaOuRefreshAwaitingCommit -OperationId $refreshId}
    }
}

$script:IndexWalk = $null

function Start-DomeniaIndexWalkStep {
    $walk = $script:IndexWalk
    if ($null -eq $walk) { return }
    if ($walk.Queue.Count -eq 0) { Complete-DomeniaIndexWalkUi; return }
    # Points 32 and 35: the saved branches stay; the next branch is not read during a maintenance or on a full disk.
    $storageRefusal = Get-DomeniaStorageCollectionRefusal
    if ($storageRefusal) { $walk.Queue.Clear(); Complete-DomeniaIndexWalkUi -Aborted -Detail $storageRefusal; return }
    $dn = $walk.Queue.Dequeue()
    $walk.Done = $walk.Done + 1
    $isRoot = $dn.Equals([string]$script:Conn.BaseDn,[StringComparison]::OrdinalIgnoreCase)
    $limits = Get-DomeniaIndexLimits
    Set-DomeniaIndexProgress -Mode Walk -Current ($walk.Done - 1) -Total $walk.Total -Message ('Lecture de lʼOU ' + $walk.Done + '/' + $walk.Total + ' : ' + $dn + '…')
    try {
        Start-UiTask `
            -Name ('Passe par OU ' + $walk.Done + '/' + $walk.Total) `
            -OperationId 'IndexBuild' `
            -Code (Get-DomeniaIndexWorkerCode) `
            -Payload ([pscustomobject]@{ Path = [string]$script:DatabaseScopedPath; Progress = (New-DomeniaIndexProgressChannel); MaxObjects = $limits.MaxObjects; BudgetMs = $limits.BudgetMs; LastUsn = [long]0; LastServer = ""; Since = ""; ComputerFirst = [bool](Get-CfgValue "Index" "ComputerFirst" $true); SearchBase = $dn; SearchScope = $(if ($isRoot) { 'OneLevel' } else { 'Subtree' }) }) `
            -CallbackState ([pscustomobject]@{ Epoch = [long]$script:SessionEpoch; SearchBase = $dn; Done = $walk.Done; Total = $walk.Total }) `
            -ReplaceKey "index" `
            -DisableControls @("BtnIndexBuild","BtnIndexRefresh","BtnIndexWalk","BtnIndexScopeUpdate","BtnFleetIndexScope") `
            -TimeoutSeconds $limits.TimeoutSeconds `
            -StatusText ('Passe par OU (' + $walk.Done + '/' + $walk.Total + ') : ' + $dn) `
            -SuccessHandler 'Complete-DomeniaIndexWalkStepUi' `
            -ErrorHandler 'Fail-DomeniaIndexWalkUi' | Out-Null
    }
    catch {
        # Le moteur refuse d'admettre une tâche de plus : la marche s'arrête là, sur un message, sans relancer en boucle.
        $walk.Queue.Clear()
        Complete-DomeniaIndexWalkUi -Aborted -Detail ([string]$_.Exception.Message)
    }
}

function Complete-DomeniaIndexWalkStepUi {
    param($Result,$State)
    if ($null -ne $State -and [long]$State.Epoch -ne [long]$script:SessionEpoch) { return }
    $walk = $script:IndexWalk
    if ($null -eq $walk) { return }
    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Rows")
    if ($null -eq $effective) { Complete-DomeniaIndexWalkUi -Aborted -Detail 'Passe sans résultat exploitable.'; return }
    $rows = @($effective.Rows)
    $transfer = $null; if ($null -ne $effective.PSObject.Properties['Transfer']) { $transfer = $effective.Transfer }
    $rowCount = if ($null -ne $effective.PSObject.Properties['RowCount']) { [long]$effective.RowCount } else { [long]@($rows).Count }
    try {
        $scopeKey = 'ou:' + ([string]$State.SearchBase).Trim().ToLowerInvariant()
        [void](Update-DomeniaIndexDatabaseRows -Rows $rows -Transfer $transfer -Server ([string]$effective.Server) -BaseDn ([string]$State.SearchBase) -SyncScope $scopeKey -Complete (-not [bool]$effective.Truncated) -WalkStep $true -InvocationId ([string]$effective.InvocationId) -Reconcile $effective.Reconcile)
        $walk.Objects = $walk.Objects + $rowCount
    }
    catch {
        $walk.Errors = $walk.Errors + 1
        Complete-DomeniaIndexWalkUi -Aborted -Detail ('Lot non enregistré : ' + $_.Exception.Message)
        return
    }
    $cut = Get-DomeniaIndexCut -Effective $effective
    if ([bool]$effective.Truncated) { $walk.Limited = $walk.Limited + 1 }
    $script:FleetStale = $true
    $summary = 'OU ' + $walk.Done + '/' + $walk.Total + ' lue : enregistrement de ' + $rowCount + ' objet(s)…'
    [void](Set-DomeniaControlText -Name "LblIndexStatus" -Text $summary)
    Set-DomeniaIndexProgress -Mode Walk -Current $walk.Saved -Total $walk.Total -Message $summary
    # The storage receipt advances to the next OU. Memory stays bounded to one pending OU batch.

}

function Fail-DomeniaIndexWalkUi {
    param($Message,$State)
    if ($null -ne $State -and [long]$State.Epoch -ne [long]$script:SessionEpoch) { return }
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = 'Erreur inconnue.' }
    # Une passe qui échoue (annuaire injoignable, annulation) arrête la marche : le reste serait relu pour rien.
    Complete-DomeniaIndexWalkUi -Aborted -Detail $detail
}

function Complete-DomeniaIndexWalkUi {
    param([switch]$Aborted,[string]$Detail = '')
    $walk = $script:IndexWalk
    $script:IndexWalk = $null
    if ($null -eq $walk) { return }
    $seconds = [int](((Get-Date) - $walk.Started).TotalSeconds)
    $summary = 'Passe par OU {0} : {1} lecture(s) sur {2}, {3} objet(s) relu(s) en {4} s.' -f $(if ($Aborted) { 'interrompue' } else { 'terminée' }),$walk.Done,$walk.Total,$walk.Objects,$seconds
    if ($Aborted -and $Detail) { $summary += ' ' + $Detail }
    if ($walk.Limited -gt 0) { $summary += ' ' + $walk.Limited + ' OU ont atteint leur limite : relisez-les une par une depuis Accueil.' }
    if ($walk.Errors -gt 0) { $summary += ' ' + $walk.Errors + ' OU trop volumineuse(s) non écrite(s).' }
    if ((-not $Aborted) -and ($walk.Limited -eq 0) -and ($walk.Errors -eq 0)) {
        # Toutes les OU ont été relues sans coupure : la base autonome n'est plus incomplète.
        Set-DomeniaIndexPartial -Clear
        $summary += ' Tous les périmètres prévus sont enregistrés et réconciliés. La mise à jour du domaine réconcilie aussi les branches supprimées depuis la liste des OU.'
    }
    if ($Aborted -or $walk.Limited -gt 0 -or $walk.Errors -gt 0) {
        Set-DomeniaIndexPartial -BaseDn ([string]$script:Conn.BaseDn) -Count $walk.Objects -Reason $(if ($Aborted -or $walk.Errors -gt 0) { 'erreur' } else { 'volume' })
    }
    [void](Set-DomeniaControlText -Name "LblIndexStatus" -Text $summary)
    Set-DomeniaIndexProgress -Mode $(if ($Aborted -or $walk.Limited -gt 0 -or $walk.Errors -gt 0) { 'Error' } else { 'Complete' }) -Message $summary
    Set-Status $summary $(if ($Aborted -or $walk.Limited -gt 0 -or $walk.Errors -gt 0) { 'WARN' } else { 'INFO' })
    Add-DomeniaUiLog -Area "Index" -Text $summary
    $script:FleetStale = $true
    try { Request-DomeniaIndexMetadata } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaIndexWalkUi' $_ }
}

function Get-DomeniaIndexScope {
    # Outils owns its update scope. An invalid or absent OU resolves to the current domain.
    # The selected OU includes its descendants; selections in Search and Dashboard stay independent.
    $dn = ''
    try { $dn = ([string]$script:IndexScopeDn).Trim() } catch { $dn = '' }
    $domainDn = ([string]$script:Conn.BaseDn).Trim()
    if ($dn -and $dn -ieq $domainDn) { return [pscustomobject]@{ BaseDn = $domainDn; Scope = 'Subtree'; IsDomain = $true; Mode = 'OU' } }
    if ($dn -and -not $dn.EndsWith(',' + $domainDn,[StringComparison]::OrdinalIgnoreCase)) { $dn = '' }
    if ($dn) { return [pscustomobject]@{ BaseDn = $dn; Scope = 'Subtree'; IsDomain = $false } }
    return [pscustomobject]@{ BaseDn = $domainDn; Scope = 'Subtree'; IsDomain = $true; Mode = 'OU' }
}

function Start-DomeniaSelectedIndexScopeBuild {
    # The primary action never silently expands a missing OU to the domain.
    $scope=Get-DomeniaIndexScope
    if($null -eq $scope -or [bool]$scope.IsDomain){
        $picked=Show-DomeniaInlinePicker -Kind OU -Title 'Choisir lʼOU à relire' -Prompt 'Choisissez lʼOU à relire avec ses sous-OU.' -DepthMode Subtree -Purpose 'Effet : la lecture AD de cette OU et de ses sous-OU démarre après ce choix.'
        if($null -eq $picked){return}
        $candidate=([string]$picked.DN).Trim()
        $previous=$script:IndexScopeDn;$script:IndexScopeDn=$candidate
        $scope=Get-DomeniaIndexScope
        if(-not $candidate -or $null -eq $scope -or [bool]$scope.IsDomain){
            $script:IndexScopeDn=$previous
            Set-Status 'Choisissez une OU valide pour limiter la lecture à cette branche.' 'WARN'
            return
        }
        Update-DomeniaIndexStats
        Request-DomeniaIndexSearch
    }
    Invoke-DomeniaOuRefresh -Source Index -Mode AD
}

function Start-DomeniaIndexBuild {
    param([switch]$UpdateLinks,[switch]$Confirmed)
    if (-not (Test-DomeniaIndexWriteReady)) { return }
    try {
        if (-not $Confirmed) {
            # UX-07: the estimate is confirmed in the page; the update starts again from the answer, once.
            $impact=Get-DomeniaOperationImpactEstimate -Operation "IndexBuild" -ItemCount @($script:IndexRows).Count
            $run = { Start-DomeniaIndexBuild -Confirmed }
            if ($UpdateLinks) { $run = { Start-DomeniaIndexBuild -UpdateLinks -Confirmed } }
            $impactText=Format-DomeniaOperationImpact -Estimate $impact
            $warning='Domaine complet : opération longue et occasionnelle, selon le volume et le réseau. À réserver au premier chargement ou à une remise à jour globale. Privilégiez lʼOU choisie au quotidien. Seule la copie locale est mise à jour ; aucune modification dans Active Directory. '
            [void](Request-DomeniaInlineConfirmation -Title 'Tout relire dans le domaine' -Message ($warning+[string]$impactText.Sentence) -Target 'impact:IndexBuild' -ConfirmText 'Relire tout le domaine' -CancelText 'Annuler' -OnConfirm $run -Details ([string]$impactText.Details) -DetailsTitle 'Détails de lʼestimation' -DetailsExpertOnly)
            return
        }
        [void](Set-DomeniaControlText -Name "LblIndexStatus" -Text "Mise a jour complete de la base autonome en cours...")
        Set-DomeniaIndexProgress -Mode Busy -Message 'Lecture complète du domaine vers la base locale… progression exacte indisponible pendant les lectures AD.'
        Start-UiTask `
            -Name "Mise a jour complete de la base autonome" `
            -OperationId "IndexBuild" `
            -Code (Get-DomeniaIndexWorkerCode) `
            -Payload ([pscustomobject]@{
                Path = [string]$script:DatabaseScopedPath
                Progress = (New-DomeniaIndexProgressChannel)
                MaxObjects = (Get-DomeniaIndexLimits).MaxObjects
                BudgetMs = (Get-DomeniaIndexLimits).BudgetMs
                LastUsn = [long]0
                LastServer = ""
                Since = ""
                ComputerFirst = [bool](Get-CfgValue "Index" "ComputerFirst" $true)
            }) `
            -CallbackState ([pscustomobject]@{ Started=(Get-Date); StartedAt=(Get-Date).ToString("o"); UpdateLinks=[bool]$UpdateLinks }) `
            -ReplaceKey "index" `
            -DisableControls @("BtnIndexBuild","BtnIndexRefresh","BtnIndexWalk","BtnIndexScopeUpdate","BtnFleetIndexScope") `
            -TimeoutSeconds ((Get-DomeniaIndexLimits).TimeoutSeconds) `
            -StatusText "Mise a jour complete de la base autonome en arriere-plan..." `
            -SuccessHandler "Complete-DomeniaIndexBuildUi" `
            -ErrorHandler "Fail-DomeniaIndexBuildUi" | Out-Null
    }
    catch { Set-DomeniaIndexProgress -Mode Error -Message ('Démarrage impossible : ' + $_.Exception.Message); [void](Show-DomeniaOperationError -Operation "Indexation de l annuaire" -ErrorRecordOrException $_) }
}

function New-DomeniaIndexProgressChannel {
    if($null -ne $script:IndexProgressTimer){$script:IndexProgressTimer.Stop()}
    $script:IndexTransferProgress=[hashtable]::Synchronized(@{Phase='Lecture';Count=0L;Total=0L;Started=[datetime]::UtcNow;Epoch=[long]$script:SessionEpoch})
    $script:IndexProgressTimer=New-DomeniaTimer -Owner 'Timer:IndexProgress' -IntervalMs 500 -SessionBound -Tick {
        $p=$script:IndexTransferProgress
        if($null -eq $p -or [long]$p.Epoch -ne [long]$script:SessionEpoch){$script:IndexProgressTimer.Stop();return}
        if($p.Phase -notin @('Lecture','Recensement GUID','Empreinte','Enregistrement','Validation')){return}
        $elapsed=[Math]::Max(1,([datetime]::UtcNow-[datetime]$p.Started).TotalSeconds)
        $text=if($p.Phase -eq 'Lecture'){'Lecture AD : {0:N0} objets reçus · {1:N0} objets/s · {2:N0} s. Total inconnu avant la fin.' -f [long]$p.Count,([long]$p.Count/$elapsed),$elapsed}elseif($p.Phase -eq 'Recensement GUID'){'Vérification des identités : {0:N0} GUID reçus. Total inconnu avant la fin ; aucune absence validée pendant la lecture.' -f [long]$p.Count}elseif($p.Phase -eq 'Empreinte'){'Lecture terminée : {0:N0} objets. Vérification du transfert sur disque…' -f [long]$p.Count}elseif($p.Phase -eq 'Validation'){'Validation de lʼempreinte du lot avant écriture…'}else{'Écritures préparées : {0:N0}/{1:N0}. La transaction doit encore être confirmée.' -f [long]$p.Count,[long]$p.Total}
        Set-DomeniaIndexProgress -Mode $(if($p.Phase -eq 'Enregistrement'){'Walk'}else{'Busy'}) -Current ([long]$p.Count) -Total ([long]$p.Total) -Message $text
    }
    $script:IndexProgressTimer.Start()
    return $script:IndexTransferProgress
}

function Set-DomeniaIndexProgress {
    param([ValidateSet('Busy','Walk','Complete','Error','Idle')][string]$Mode,[string]$Message='', [long]$Current=0,[long]$Total=0)
    if($Mode -in @('Complete','Error','Idle') -and $null -ne $script:IndexTransferProgress){$script:IndexTransferProgress.Phase=$Mode;if($null -ne $script:IndexProgressTimer){$script:IndexProgressTimer.Stop()}}
    $bar = Get-DomeniaControl 'PbIndexProgress'
    $label = Get-DomeniaControl 'LblIndexProgress'
    if ($null -ne $bar) {
        $bar.Visibility = if ($Mode -in @('Busy','Walk')) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
        $bar.IsIndeterminate = ($Mode -eq 'Busy')
        if ($Mode -eq 'Walk') { $bar.Value = if ($Total -gt 0) { [Math]::Min(100,100.0 * $Current / $Total) } else { 0 } }
        elseif ($Mode -eq 'Complete') { $bar.IsIndeterminate = $false; $bar.Value = 100 }
        elseif ($Mode -in @('Error','Idle')) { $bar.Value = 0 }
    }
    if ($null -ne $label) { $label.Text = [string]$Message }
}

function Update-DomeniaIndexStats {
    # FI-19: shows the figures last read by Request-DomeniaIndexMetadata; it never reads the base itself.
    try {
        $target = Get-DomeniaIndexScope
        $scopeKey = if ([bool]$target.IsDomain) { 'directory' } else { 'ou:' + ([string]$target.BaseDn).ToLowerInvariant() }
        $targetText = if ([bool]$target.IsDomain) { 'Aucune OU choisie · sélectionnez une OU pour limiter la lecture' } else { [string]$target.BaseDn + ' et ses sous-OU' }
        [void](Set-DomeniaControlText -Name 'LblIndexScopeChoice' -Text $targetText)
        if ($script:IndexMetadataError) {
            # DS-09: an unreadable base shows no figure, never zero.
            Set-DomeniaIndexTiles -Tiles (Get-DomeniaIndexTiles -Unreadable)
            [void](Set-DomeniaControlText -Name 'LblIndexFreshness' -Text 'La base locale ne peut pas être lue ; son contenu nʼest pas considéré comme vide. Vérifiez lʼonglet Stockage avant de relire lʼOU choisie.')
            [void](Set-DomeniaControlText -Name 'LblIndexStats' -Text ([string]$script:IndexMetadataError))
            return
        }
        if ([int]$script:IndexDbCount -lt 0) {
            # Not read yet in this session: the base is not presented as empty. The answer calls this function again.
            [void](Set-DomeniaControlText -Name 'LblIndexOverview' -Text 'Lecture de lʼétat de la base locale en arrière-plan…')
            [void](Set-DomeniaControlText -Name 'LblIndexFreshness' -Text 'La fraîcheur du périmètre sʼaffiche dès que la base locale est lue.')
            [void](Set-DomeniaControlText -Name 'LblIndexStats' -Text ('Fichier : {0}.' -f (Get-DomeniaDatabasePath)))
            return
        }
        $count = [Math]::Max(0,[int]$script:IndexDbCount)
        $freshness = New-Object 'System.Collections.Generic.List[string]'
        $server = ''; $usn = 0L
        if ($null -ne $script:IndexInfo) { $server = [string]$script:IndexInfo.Server; $usn = [long]$script:IndexInfo.Usn }
        $coverage=Get-DomeniaFleetFreshness -ScopeDn $(if($target.IsDomain){''}else{[string]$target.BaseDn}) -DomainDn ([string]$script:Conn.BaseDn) -SyncStates $script:IndexSyncStates
        # DS-09: four tiles (accounts, workstations, associations, last complete read of the chosen perimeter).
        Set-DomeniaIndexTiles -Tiles (Get-DomeniaIndexTiles -Users ([long]$script:IndexDbUsers) -Computers ([long]$script:IndexDbComputers) -Active ([long]$script:IndexDbMachinesActive) -Disabled ([long]$script:IndexDbMachinesDisabled) -Links ([long]@($script:UserMachineLinks).Count) -LastUtc $coverage.At)
        if ($count -eq 0) { $freshness.Add('Aucun objet enregistré. Choisissez un périmètre, puis lancez sa mise à jour.') }
        if($null -ne $coverage.At){
            $date=$coverage.At.ToLocalTime()
            $age=if($coverage.At -gt [datetime]::UtcNow.AddMinutes(5)){'date future : vérifier lʼhorloge'}else{Format-DomeniaAge -FromUtc $coverage.At -NowUtc ([datetime]::UtcNow)}
            $freshness.Add(('Dernière lecture complète couvrant le périmètre : {0} ({1}).' -f $date.ToString('dd/MM/yyyy HH:mm'),$age))
            $freshness.Add('Source de cette lecture : '+$coverage.SourceDn+'.')
        }else{$freshness.Add('Aucune lecture complète couvrant ce périmètre. Choisissez une OU, puis mettez-la à jour.')}
        if($coverage.Partial){$freshness.Add(('Dernière tentative incomplète le {0}. Les données reçues sont conservées ; la date de lecture complète reste inchangée.' -f $coverage.AttemptAt.ToLocalTime().ToString('dd/MM/yyyy HH:mm')))}
        $partial = if($target.IsDomain){[string](Get-DomeniaIndexPartialText)}else{''}
        if ($partial) { $freshness.Add('À vérifier : ' + $partial) }
        # Point 22: a complete census of this scope is advised when due; it is never started automatically.
        if (${function:Get-DomeniaCensusAdvice}) {
            $gap = 0L; try { $gap = [long]$script:IndexInfo.CensusGap } catch { $gap = 0L }
            # Index.FullRebuildDays (7 by default) is the age after which a complete read of the scope is advised.
            $days = 7; try { $days = [int](Get-CfgValue 'Index' 'FullRebuildDays' 7) } catch { $days = 7 }
            $census = Get-DomeniaCensusAdvice -Coverage $coverage -GapCount ([int]$gap) -MaxAgeDays $days -NowUtc ([datetime]::UtcNow) -IsDomain ([bool]$target.IsDomain)
            if ([bool]$census.Due) { $freshness.Add([string]$census.Text) }
        }
        if (${function:Update-DomeniaCensusAdviceUi}) { Update-DomeniaCensusAdviceUi }
        [void](Set-DomeniaControlText -Name 'LblIndexFreshness' -Text ($freshness -join "`n"))
        # DS-09: the synchronisation mark (USN) goes to the journal, once per change; the page keeps readable facts.
        $mark = $server + '|' + [string]$usn
        if (($usn -gt 0) -and ([string]$script:IndexStatsLoggedMark -cne $mark)) {
            $script:IndexStatsLoggedMark = $mark
            Add-DomeniaUiLog -Area 'Index' -Text ('Repère de synchronisation de la base locale : ' + [string]$usn + ' (contrôleur ' + $server + ').')
        }
        $details = ('Contrôleur de la dernière lecture : {0}. Objets enregistrés : {1:N0}. Associations utilisateur-poste : {2:N0}.' -f $(if($server){$server}else{'inconnu'}),$count,@($script:UserMachineLinks).Count)
        [void](Set-DomeniaControlText -Name 'LblIndexStats' -Text $details)
    } catch { Write-AppLog ('État de la base non affiché : ' + $_.Exception.Message) 'WARN' }
    try { Update-DomeniaIndexLocation } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaIndexStats' $_ }
}

function Search-DomeniaIndexUi {
    try {
        $term = ""
        try { $term = ([string](Get-DomeniaControl -Name "TxtIndexSearch").Text).Trim() } catch { Write-DomeniaSwallowed 'Core' 'Search-DomeniaIndexUi' $_ }
        if ($term.Length -eq 1) {
            $script:DomeniaIndexSearchGeneration = [long]$script:DomeniaIndexSearchGeneration + 1
            [void](Set-DomeniaItemsSource -Name "DgIndex" -Rows @())
            [void](Set-DomeniaControlText -Name "LblIndexStatus" -Text "Saisissez au moins deux caractères, ou laissez vide pour tous les objets.")
            return
        }
        # D014: the SQLite query (busy timeout up to several seconds on a locked base) no longer runs on the
        # Dispatcher: the LocalIndexRead worker answers, Complete-DomeniaIndexSearchUi fills the grid.
        $attempt = 0;$offset=0;$limit=200;$sort=Get-DomeniaIndexSearchSort
        $retry = $script:DomeniaIndexSearchRetry
        $script:DomeniaIndexSearchRetry = $null
        $scope=Get-DomeniaIndexScope
        $scopeDn=if($null -ne $scope -and -not $scope.IsDomain){[string]$scope.BaseDn}else{''}
        if ($null -ne $retry -and [string]$retry.Term -ceq $term -and
            [long](Get-DomeniaMember $retry 'Epoch' -1) -eq [long]$script:SessionEpoch -and
            [long](Get-DomeniaMember $retry 'Generation' -1) -eq [long]$script:DomeniaIndexSearchGeneration -and
            [string]::Equals([string](Get-DomeniaMember $retry 'Scope' ''),$scopeDn,[StringComparison]::OrdinalIgnoreCase) -and
            [string](Get-DomeniaMember $retry 'SortField' '') -ceq [string]$sort.Field -and
            [bool](Get-DomeniaMember $retry 'Descending' $false) -eq [bool]$sort.Descending) {
            $attempt = [int]$retry.Attempt;$offset=[int](Get-DomeniaMember $retry 'Offset' 0)
            $limit=[Math]::Max(1,[Math]::Min(500,[int](Get-DomeniaMember $retry 'Limit' 200)))
        }
        [void](Start-DomeniaIndexSearch -Term $term -Limit $limit -Attempt $attempt -Offset $offset -SortField ([string]$sort.Field) -Descending ([bool]$sort.Descending))
    }
    catch {
        [void](Set-DomeniaControlText -Name "LblIndexStatus" -Text ("Recherche locale non lancee : " + $_.Exception.Message))
        Add-DomeniaUiLog -Level "ERROR" -Area "Index" -Text $_.Exception.Message
    }
}

function Open-DomeniaIndexSelection {
    try {
        $grid = Get-DomeniaControl -Name "DgIndex"
        if ($null -eq $grid -or $null -eq $grid.SelectedItem) { Set-Status "Sélectionnez une ligne." "WARN"; return }
        $row=$grid.SelectedItem
        if (-not [string]$row.DN) { return }
        Open-AdObject -Dn ([string]$row.DN) -Type ([string]$row.Type) -ObjectGuid ([string]$row.Guid) -SuppressRemoteProbes
    }
    catch { [void](Show-DomeniaOperationError -Operation "Ouverture de lʼobjet de la base locale" -ErrorRecordOrException $_ -NoPopup) }
}

function Get-DomeniaIndexOuListWorkerCode {
    # Corps épinglé (IndexOuList) : une seule lecture OneLevel sous la racine pour connaître les OU à relire une par
    # une. Le filtre reprend celui du cache d'accueil : OU et conteneurs (CN=Computers, CN=Domain Controllers...).
    return @'
$watch = [System.Diagnostics.Stopwatch]::StartNew()
$baseDn = [string]$Context.BaseDn
if ([string]::IsNullOrWhiteSpace($baseDn)) { throw 'Base DN vide : lecture des OU impossible.' }
$searchBase = $baseDn
$scopeProperty = $Payload.PSObject.Properties['SearchBase']
if ($null -ne $scopeProperty -and -not [string]::IsNullOrWhiteSpace([string]$scopeProperty.Value)) {
    $scopeText = ([string]$scopeProperty.Value).Trim()
    if (-not ($scopeText -ieq $baseDn -or $scopeText.EndsWith(',' + $baseDn,[StringComparison]::OrdinalIgnoreCase))) { throw 'OU hors du domaine : lecture refusee.' }
    $searchBase = $scopeText
}
$rows = New-Object Collections.ArrayList
$searcher = $null
$collection = $null
$rootEntry = $null
try {
    $searcher = New-WSearcher $Context $searchBase '(|(objectClass=organizationalUnit)(objectClass=container))' @('name','distinguishedName') 'OneLevel' 0
    $rootEntry = $searcher.SearchRoot
    $searcher.PageSize = 200
    $searcher.ServerTimeLimit = [TimeSpan]::FromSeconds(60)
    $searcher.ClientTimeout = [TimeSpan]::FromSeconds(90)
    $collection = $searcher.FindAll()
    foreach ($r in $collection) {
        $dn = [string](Get-WPropFirst $r.Properties 'distinguishedName' '')
        if ([string]::IsNullOrWhiteSpace($dn)) { continue }
        if ($dn.Equals($searchBase,[StringComparison]::OrdinalIgnoreCase)) { continue }
        [void]$rows.Add([pscustomobject]@{ Name = [string](Get-WPropFirst $r.Properties 'name' ''); DN = $dn })
    }
}
finally {
    if ($null -ne $collection) { try { $collection.Dispose() } catch { } }
    if ($null -ne $searcher) { try { $searcher.Dispose() } catch { } }
    if ($null -ne $rootEntry) { try { $rootEntry.Dispose() } catch { } }
}
$sorted = @($rows | Sort-Object @{Expression = {[string]$_.DN}; Descending = $false })
return [pscustomobject]@{ Success = $true; Rows = $sorted; SearchBase = $searchBase; BaseDn = $baseDn; DurationMs = [int]$watch.ElapsedMilliseconds }
'@
}

function Get-DomeniaIndexWorkerCode {
    return @'
$startedUtc = [datetime]::UtcNow.ToString('o')
$watch = [System.Diagnostics.Stopwatch]::StartNew()
$progress=$null;if($null -ne $Payload.PSObject.Properties['Progress']){$progress=$Payload.Progress}
$baseDn = [string]$Context.BaseDn
if ([string]::IsNullOrWhiteSpace($baseDn)) { throw 'Base DN vide : indexation impossible.' }
function Get-IdxParentDn {
    param([string]$Dn)
    $escaped=$false
    for($n=0;$n -lt $Dn.Length;$n++){
        if($escaped){$escaped=$false;continue}
        if($Dn[$n] -eq [char]92){$escaped=$true;continue}
        if($Dn[$n] -eq ','){return $Dn.Substring($n+1).Trim()}
    }
    return ''
}
function Test-IdxDnInScope {
    param([string]$Dn,[string]$ScopeDn,[string]$SearchScope)
    if($SearchScope -eq 'OneLevel'){return (Get-IdxParentDn $Dn) -ieq $ScopeDn}
    $part=$Dn
    while($part){if($part -ieq $ScopeDn){return $true};$part=Get-IdxParentDn $part}
    return $false
}
# Scoped pass (« Mettre à jour cette OU »): only this OU subtree is read, and it must be inside the domain.
$searchBase = $baseDn
$scopeProperty = $Payload.PSObject.Properties['SearchBase']
if ($null -ne $scopeProperty -and -not [string]::IsNullOrWhiteSpace([string]$scopeProperty.Value)) {
    $scopeText = ([string]$scopeProperty.Value).Trim()
    if (-not (Test-IdxDnInScope $scopeText $baseDn 'Subtree')) { throw 'OU hors du domaine : mise a jour refusee.' }
    $searchBase = $scopeText
}
# Portée de la passe : la marche par OU relit chaque OU en Subtree ; le reste posé directement sur la
# racine du domaine (objets hors OU) se lit à un seul niveau. Toute autre valeur retombe sur Subtree.
$searchScope = 'Subtree'
$scopeKindProperty = $Payload.PSObject.Properties['SearchScope']
if ($null -ne $scopeKindProperty -and ([string]$scopeKindProperty.Value) -ieq 'OneLevel') { $searchScope = 'OneLevel' }
# Streaming runs have no artificial object ceiling; explicit positive quotas remain supported.
$maxObjects = [Math]::Max(0L,[long]$Payload.MaxObjects)
$budgetMs = [Math]::Max(30000,[int]$Payload.BudgetMs)

# Le compteur uSNChanged est propre a chaque controleur. Il ne sert donc de
# repere que si l on interroge le meme serveur que la fois precedente ;
# sinon on retombe sur la date de modification, qui est repliquee.
$lastUsn = 0
try { $lastUsn = [int64]$Payload.LastUsn } catch { $lastUsn = 0 }
$lastInvocationId = ''
try { $lastInvocationId = [string]$Payload.LastInvocationId } catch { $lastInvocationId = '' }
$sameServer = ([string]$Payload.LastServer -ieq [string]$Context.Server)
$versionSource = ''
try { $versionSource = [string](Get-WDirectoryVersionSource $Context) } catch { $versionSource = '' }
$invocationId = ''
if ($versionSource -match '^(?<dc>[^|]+)\|(?<id>[^|]+)$') { $invocationId = $matches['id'] }
$sameInstance = (($sameServer) -and ($lastInvocationId) -and ($invocationId) -and ($lastInvocationId -ieq $invocationId))
$since = ([string]$Payload.Since).Trim()
$incremental = $false
$deltaClause = ''
if (($lastUsn -gt 0) -and $sameInstance) {
    $incremental = $true
    $deltaClause = '(uSNChanged>=' + ($lastUsn + 1) + ')'
}
elseif ((-not [string]::IsNullOrWhiteSpace($since)) -and $sameInstance) {
    try {
        # On recule de cinq minutes : la date de modification a une seconde
        # de granularite et la replication n est pas instantanee.
        $stamp = ([datetime]$since).AddMinutes(-5).ToUniversalTime().ToString('yyyyMMddHHmmss.0Z')
        $incremental = $true
        $deltaClause = '(whenChanged>=' + $stamp + ')'
    }
    catch { }
}

$highestUsn = 0
$schemaNc = ''
try {
    $rootDse = New-WRootDse $Context
    $rootDse.RefreshCache(@('highestCommittedUSN','schemaNamingContext'))
    $highestUsn = [int64]$rootDse.Properties['highestCommittedUSN'].Value
    try { $schemaNc = [string]$rootDse.Properties['schemaNamingContext'].Value } catch { $schemaNc = '' }
}
catch { }
# Point 21: a checkpoint above what this instance has committed cannot describe its data (restored or rolled back
# controller): the pass becomes a complete read. No USN is ever extrapolated.
$checkpointRejected = ''
if ($incremental -and ($lastUsn -gt 0) -and ($highestUsn -gt 0) -and ($lastUsn -gt $highestUsn)) {
    $incremental = $false
    $deltaClause = ''
    $checkpointRejected = 'UsnAhead'
}

# LAPS expiration (legacy and Windows LAPS) is read with the computers, never the password. One small read of the
# schema tells "attribute absent from this domain" (NoSchema) from "not visible with this account" (None).
$lapsSchema = ''
if (-not [string]::IsNullOrWhiteSpace($schemaNc)) {
    $schemaSearcher = $null
    $schemaResults = $null
    try {
        $schemaSearcher = New-WSearcher $Context $schemaNc '(&(objectClass=attributeSchema)(|(lDAPDisplayName=ms-Mcs-AdmPwdExpirationTime)(lDAPDisplayName=msLAPS-PasswordExpirationTime)))' @('lDAPDisplayName') 'OneLevel' 0
        $schemaResults = $schemaSearcher.FindAll()
        $schemaCount = 0
        foreach ($schemaResult in $schemaResults) { $schemaCount++ }
        $lapsSchema = if ($schemaCount -gt 0) { 'Present' } else { 'Absent' }
    }
    catch { $lapsSchema = '' }
    finally {
        if ($null -ne $schemaResults) { try { $schemaResults.Dispose() } catch { } }
        if ($null -ne $schemaSearcher) { try { $schemaSearcher.Dispose() } catch { } }
    }
}
function ConvertTo-IdxUtcText {
    # Directory date (generalized time or large integer) as 'yyyy-MM-ddTHH:mm:ssZ'; '' when absent or never.
    param($Value)
    if ($null -eq $Value -or [string]$Value -eq '') { return '' }
    try {
        if ($Value -is [datetime]) {
            $date = $Value
            if ($date.Kind -eq [DateTimeKind]::Local) { $date = $date.ToUniversalTime() }
            return $date.ToString('yyyy-MM-ddTHH:mm:ssZ',[Globalization.CultureInfo]::InvariantCulture)
        }
        $ticks = Convert-WLargeInteger $Value
        if ($ticks -le 0 -or $ticks -eq [long]::MaxValue) { return '' }
        return [DateTime]::FromFileTimeUtc($ticks).ToString('yyyy-MM-ddTHH:mm:ssZ',[Globalization.CultureInfo]::InvariantCulture)
    }
    catch { return '' }
}

$rows = New-Object Collections.ArrayList
$rowCount = 0L; $userCount = 0L; $computerCount = 0L
$censusCount=0L; $identities=[Collections.Generic.List[object]]::new()
$rowGuids=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
$spoolPath = ''; $spoolWriter = $null; $spoolStream = $null
# Compatibility test callers without Path retain the bounded in-memory path. Runtime always supplies Path.
if ($null -ne $Payload.PSObject.Properties['Path'] -and [string]$Payload.Path) {
    $folder = Join-Path ([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath([string]$Payload.Path))) 'index-spool'
    [void][IO.Directory]::CreateDirectory($folder)
    if (([IO.File]::GetAttributes($folder) -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'Dossier temporaire redirige : indexation refusee.' }
    $spoolPath = Join-Path $folder ([guid]::NewGuid().ToString('N') + '.jsonl')
    $spoolStream = [IO.FileStream]::new($spoolPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None,65536)
    $spoolWriter = [IO.StreamWriter]::new($spoolStream,[Text.UTF8Encoding]::new($false),65536)
} elseif ($maxObjects -eq 0 -or $maxObjects -gt 5000000) { $maxObjects = 5000000 }

$diagnostics = New-Object Collections.ArrayList
$truncated = $false
# Which limit cut this pass ('volume' for Index.MaxObjects, 'temps' for Index.BudgetMs), so the warning can name it.
$limitReason = ''

function Clean-Field {
    param($Value)
    $text = ''
    if ($null -ne $Value) { $text = [string]$Value }
    $text = $text -replace "`t",' '
    $text = $text -replace "`r",' '
    $text = $text -replace "`n",' '
    return $text.Trim()
}

$userPlan = @{ Kind='Utilisateur'; Filter='(&(objectCategory=person)(objectClass=user))'; Props=@('name','sAMAccountName','userPrincipalName','displayName','description','department','title','mail','distinguishedName','objectGUID','userAccountControl','whenChanged','uSNChanged') }
$computerPlan = @{ Kind='Machine'; Filter='(objectCategory=computer)'; Props=@('name','sAMAccountName','dNSHostName','description','operatingSystem','location','distinguishedName','objectGUID','userAccountControl','whenChanged','uSNChanged','lastLogonTimestamp','operatingSystemVersion','whenCreated','pwdLastSet','ms-Mcs-AdmPwdExpirationTime','msLAPS-PasswordExpirationTime') }
$plan = if ([bool]$Payload.ComputerFirst) { @($computerPlan,$userPlan) } else { @($userPlan,$computerPlan) }

$serverTimeLimitSeconds = 120
$plansLeft = @($plan).Count + $(if($incremental){1}else{0})
try {
foreach ($entry in $plan) {
    # Budget par plan : Index.BudgetMs était un plafond global sans réserve, donc le plan lu en premier pouvait
    # tout le manger et le second était déclaré « non indexé » sans jamais démarrer -- une base à 60 000 postes
    # et 0 compte. Chaque plan reçoit la part restante du budget ; un plan qui finit tôt rend son reste au
    # suivant, et la passe ne peut jamais dépasser Index.BudgetMs.
    $planDeadlineMs = $watch.ElapsedMilliseconds + [int][Math]::Ceiling([Math]::Max(1,($budgetMs - $watch.ElapsedMilliseconds)) / [Math]::Max(1,$plansLeft))
    $plansLeft = [Math]::Max(0,$plansLeft - 1)
    if (($maxObjects -gt 0 -and $rowCount -ge $maxObjects) -or $watch.ElapsedMilliseconds -ge $planDeadlineMs) {
        $truncated = $true
        $cut = if (($maxObjects -gt 0 -and $rowCount -ge $maxObjects)) { 'volume' } else { 'temps' }
        if (-not $limitReason) { $limitReason = $cut }
        [void]$diagnostics.Add([string]$entry.Kind + ' : non indexe, limite de ' + $cut + ' atteinte.')
        continue
    }
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $searcher = $null
    $collection = $null
    $added = 0
    try {
        $filter = [string]$entry.Filter
        if ($incremental) { $filter = '(&' + $filter + $deltaClause + ')' }
        # PF-02: the directory stops at the remaining volume plus one (that extra result proves the cut).
        $sizeLimit = 0
        if ($maxObjects -gt 0) { $sizeLimit = [Math]::Max(1,$maxObjects - $rowCount) + 1 }
        $searcher = New-WSearcher $Context $searchBase $filter @($entry.Props) $searchScope $sizeLimit
        $searcher.PageSize = 1000
        $searcher.CacheResults = $false
        $searcher.ServerTimeLimit = [TimeSpan]::FromSeconds($serverTimeLimitSeconds)
        $searcher.ClientTimeout = [TimeSpan]::FromSeconds($serverTimeLimitSeconds + 30)
        $collection = $searcher.FindAll()
        foreach ($r in $collection) {
            if (($maxObjects -gt 0 -and $rowCount -ge $maxObjects)) { $truncated = $true; if (-not $limitReason) { $limitReason = 'volume' }; break }
            if ($watch.ElapsedMilliseconds -ge $planDeadlineMs) { $truncated = $true; if (-not $limitReason) { $limitReason = 'temps' }; break }
            $p = $r.Properties
            $name = Clean-Field (Get-WPropFirst $p 'name' '')
            if ([string]::IsNullOrWhiteSpace($name)) { throw 'Nom absent dans un objet : lecture tenue pour incomplete.' }
            $login = Clean-Field (Get-WPropFirst $p 'samaccountname' '')
            $upn = ''
            $extra = ''
            if ([string]$entry.Kind -eq 'Utilisateur') {
                $upn = Clean-Field (Get-WPropFirst $p 'userprincipalname' '')
                $extra = Clean-Field (Get-WPropFirst $p 'department' '')
                $title = Clean-Field (Get-WPropFirst $p 'title' '')
                if (-not [string]::IsNullOrWhiteSpace($title)) {
                    if ([string]::IsNullOrWhiteSpace($extra)) { $extra = $title } else { $extra = $extra + ' / ' + $title }
                }
            }
            else {
                $upn = Clean-Field (Get-WPropFirst $p 'dnshostname' '')
                $extra = Clean-Field (Get-WPropFirst $p 'operatingsystem' '')
                $location = Clean-Field (Get-WPropFirst $p 'location' '')
                if (-not [string]::IsNullOrWhiteSpace($location)) {
                    if ([string]::IsNullOrWhiteSpace($extra)) { $extra = $location } else { $extra = $extra + ' / ' + $location }
                }
            }
            $uac = 0
            try { $uac = [int](Get-WPropFirst $p 'useraccountcontrol' 0) } catch { }
            $state = 'Actif'
            if (($uac -band 2) -ne 0) { $state = 'Desactive' }
            $usn = 0
            try { $usn = [int64](Get-WPropFirst $p 'usnchanged' 0) } catch { }
            # lastLogonTimestamp est replique avec un retard de neuf a
            # quatorze jours par conception. C est donc un signal grossier,
            # mais suffisant a l echelle de la peremption utilisee ici.
            $lastLogon = ''
            try { $lastLogon = Clean-Field (Convert-WFileTime (Get-WPropFirst $p 'lastlogontimestamp' 0)) } catch { }
            $facts = $false; $osVersion = ''; $created = ''; $pwdSet = ''; $lapsKind = ''; $lapsExpiry = ''
            if ([string]$entry.Kind -eq 'Machine') {
                $facts = $true
                $osVersion = Clean-Field (Get-WPropFirst $p 'operatingsystemversion' '')
                $created = ConvertTo-IdxUtcText (Get-WPropFirst $p 'whencreated' $null)
                $pwdSet = ConvertTo-IdxUtcText (Get-WPropFirst $p 'pwdlastset' $null)
                $windowsLaps = ConvertTo-IdxUtcText (Get-WPropFirst $p 'mslaps-passwordexpirationtime' $null)
                $legacyLaps = ConvertTo-IdxUtcText (Get-WPropFirst $p 'ms-mcs-admpwdexpirationtime' $null)
                if ($windowsLaps) { $lapsKind = 'Windows'; $lapsExpiry = $windowsLaps }
                elseif ($legacyLaps) { $lapsKind = 'Legacy'; $lapsExpiry = $legacyLaps }
                elseif ($lapsSchema -eq 'Absent') { $lapsKind = 'NoSchema' }
                elseif ($lapsSchema -eq 'Present') { $lapsKind = 'None' }
            }
            $record = [pscustomobject]@{
                Type = [string]$entry.Kind
                WhenChanged = Clean-Field (Convert-WDate (Get-WPropFirst $p 'whenchanged' ''))
                Usn = $usn
                LastLogon = $lastLogon
                Name = $name
                Login = $login
                Upn = $upn
                Display = Clean-Field (Get-WPropFirst $p 'displayname' '')
                Description = Clean-Field (Get-WPropFirst $p 'description' '')
                Extra = $extra
                State = $state
                DN = Clean-Field (Get-WPropFirst $p 'distinguishedname' '')
                Guid = Clean-Field (Convert-WGuid (Get-WPropFirst $p 'objectguid' ''))
                Facts = $facts
                OsVersion = $osVersion
                WhenCreated = $created
                PwdLastSet = $pwdSet
                LapsKind = $lapsKind
                LapsExpiry = $lapsExpiry
            }
            $recordGuid=[guid]::Empty
            if(-not [guid]::TryParse([string]$record.Guid,[ref]$recordGuid) -or $recordGuid -eq [guid]::Empty -or
               -not (Test-IdxDnInScope ([string]$record.DN) $searchBase $searchScope)){throw 'GUID ou DN invalide dans un objet : lecture tenue pour incomplete.'}
            $record.Guid=$recordGuid.ToString('D').ToLowerInvariant()
            if(-not $rowGuids.Add([string]$record.Guid)){throw 'GUID duplique dans les objets : lecture tenue pour incomplete.'}
            if ($null -ne $spoolWriter) { $spoolWriter.WriteLine((ConvertTo-Json -InputObject $record -Depth 3 -Compress)) }
            else { [void]$rows.Add($record) }
            $rowCount++; if($null -ne $progress -and ($rowCount % 1000) -eq 0){$progress.Count=$rowCount}; if ([string]$entry.Kind -eq 'Machine') { $computerCount++ } else { $userCount++ }
            $added++
        }
        $sw.Stop()
        # Le serveur borne lui-meme une recherche au maxDuration du controleur (ServerTimeLimit ci-dessus) et rend
        # alors sa reponse partielle, sans exception et sans drapeau que ce code puisse lire. La passe passerait donc
        # pour complete, et ReplaceAll viderait la base pour ne la remplir que de ce lot incomplet : a chaque mise a
        # jour. Une passe qui a dure au moins ce delai est tenue pour coupee par le serveur, et ne remplace jamais.
        if (-not $truncated -and $sw.Elapsed.TotalSeconds -ge $serverTimeLimitSeconds) {
            $truncated = $true
            if (-not $limitReason) { $limitReason = 'serveur' }
            [void]$diagnostics.Add([string]$entry.Kind + ' : reponse du serveur coupee a ' + [string]$serverTimeLimitSeconds + ' s, lot tenu pour incomplet.')
        }
        [void]$diagnostics.Add([string]$entry.Kind + ' : ' + $added + ' objet(s) en ' + [int]$sw.ElapsedMilliseconds + ' ms.')
    }
    catch {
        $sw.Stop()
        # Any AD read failure makes the class pass incomplete. In particular, a failed user query must never be
        # mistaken for an empty directory and committed with ReplaceAll after the computer query succeeded.
        $truncated = $true
        if (-not $limitReason) { $limitReason = 'erreur' }
        [void]$diagnostics.Add([string]$entry.Kind + ' : ERREUR ' + [string]$_.Exception.Message)
    }
    finally {
        if ($null -ne $collection) { try { $collection.Dispose() } catch { } }
        if ($null -ne $searcher) { try { $searcher.Dispose() } catch { } }
    }
}

# The USN above was captured BEFORE either read. The census never advances it to a
# later rootDSE value: modifications concurrent with this pass are read next time.
if($incremental -and -not $truncated){
    $searcher=$null;$collection=$null;$sw=[Diagnostics.Stopwatch]::StartNew()
    $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    try{
        if($watch.ElapsedMilliseconds -ge $budgetMs){throw 'Budget du recensement des identites depasse.'}
        if($null -ne $progress){$progress.Phase='Recensement GUID';$progress.Count=0L}
        $filter='(|(&(objectCategory=person)(objectClass=user))(objectCategory=computer))'
        # PF-02: MaxObjects + 1 at most; the extra identity proves the limit and the census is then refused.
        $censusLimit=0;if($maxObjects -gt 0){$censusLimit=$maxObjects+1}
        # Point 22: uSNChanged lets the storage tell an identity missed by the delta (USN at or below the checkpoint of
        # this pass) from one created or changed during the pass, which the next delta returns anyway.
        $searcher=New-WSearcher $Context $searchBase $filter @('objectGUID','distinguishedName','uSNChanged') $searchScope $censusLimit
        $searcher.PageSize=1000;$searcher.CacheResults=$false
        $searcher.ServerTimeLimit=[TimeSpan]::FromSeconds($serverTimeLimitSeconds)
        $searcher.ClientTimeout=[TimeSpan]::FromSeconds($serverTimeLimitSeconds+30)
        $collection=$searcher.FindAll()
        foreach($r in $collection){
            if($watch.ElapsedMilliseconds -ge $budgetMs){throw 'Budget du recensement des identites depasse.'}
            if($maxObjects -gt 0 -and $censusCount -ge $maxObjects){throw 'Limite du recensement des identites atteinte.'}
            $guidText=Clean-Field (Convert-WGuid (Get-WPropFirst $r.Properties 'objectguid' ''))
            $guid=[guid]::Empty
            if(-not [guid]::TryParse($guidText,[ref]$guid) -or $guid -eq [guid]::Empty){throw 'GUID absent ou invalide dans le recensement.'}
            $guidText=$guid.ToString('D').ToLowerInvariant()
            if(-not $seen.Add($guidText)){throw 'GUID duplique dans le recensement.'}
            $dn=Clean-Field (Get-WPropFirst $r.Properties 'distinguishedname' '')
            if(-not (Test-IdxDnInScope $dn $searchBase $searchScope)){throw 'DN absent ou hors perimetre dans le recensement.'}
            $identityUsn=0L;try{$identityUsn=[int64](Get-WPropFirst $r.Properties 'usnchanged' 0)}catch{$identityUsn=0L}
            $identity=[pscustomobject]@{Kind='Identity';Guid=$guidText;DN=$dn;Usn=$identityUsn}
            if($null -ne $spoolWriter){$spoolWriter.WriteLine((ConvertTo-Json -InputObject $identity -Compress))}else{$identities.Add($identity)}
            $censusCount++;if($null -ne $progress -and ($censusCount % 1000) -eq 0){$progress.Count=$censusCount}
        }
        if($sw.Elapsed.TotalSeconds -ge $serverTimeLimitSeconds){throw 'Recensement tenu pour incomplet apres la limite du serveur.'}
        # An empty domain after an established checkpoint needs an explicit full rebuild.
        if($censusCount -eq 0){throw 'Recensement vide : relancez une reconstruction complete pour confirmer une base vide.'}
        [void]$diagnostics.Add(('Recensement : '+$censusCount+' identites verifiees, sans relecture des attributs.'))
    }catch{
        $truncated=$true;if(-not $limitReason){$limitReason='erreur'}
        [void]$diagnostics.Add(('Recensement incomplet : '+$_.Exception.Message+' Aucune absence ni nouveau repere ne sont valides.'))
    }finally{
        if($null -ne $collection){try{$collection.Dispose()}catch{}}
        if($null -ne $searcher){try{$searcher.Dispose()}catch{}}
    }
}
if(-not $truncated -and $invocationId){
    try{
        if([string](Get-WDirectoryVersionSource $Context) -ine $versionSource){throw 'Instance du controleur changee pendant la lecture.'}
    }catch{$truncated=$true;if(-not $limitReason){$limitReason='erreur'};[void]$diagnostics.Add(('Lecture non reconciliee : '+$_.Exception.Message))}
}

} finally { if ($null -ne $spoolWriter) { $spoolWriter.Dispose() } elseif ($null -ne $spoolStream) { $spoolStream.Dispose() } }
$transfer = $null
if ($spoolPath) {
    if($null -ne $progress){$progress.Count=$rowCount;$progress.Phase='Empreinte'}
    # The hash and count bind the receipt to the exact file. Storage verifies both before commit.
    $hash = (Get-FileHash -LiteralPath $spoolPath -Algorithm SHA256 -ErrorAction Stop).Hash
    $transfer = [pscustomobject]@{Path=$spoolPath;Sha256=$hash;RowCount=$rowCount;CensusRowCount=$censusCount;Progress=$progress}
}
if($null -ne $progress){$progress.Phase='Attente'}
$watch.Stop()
[pscustomobject]@{
    Rows = @($rows)
    Transfer = $transfer
    RowCount = $rowCount
    UserCount = $userCount
    ComputerCount = $computerCount
    Diagnostics = @($diagnostics)
    Truncated = $truncated
    LimitReason = $limitReason
    LimitMaxObjects = $maxObjects
    LimitBudgetMs = $budgetMs
    LimitServerSeconds = $serverTimeLimitSeconds
    SearchBase = $searchBase
    SearchScope = $searchScope
    Reconcile = [pscustomobject]@{Mode=$(if($incremental){'Census'}else{'Rows'});ScopeDn=$searchBase;SearchScope=$searchScope;Complete=(-not $truncated);ExpectedCount=$(if($incremental){$censusCount}else{$rowCount});Identities=$identities.ToArray();StartedUtc=$startedUtc;Server=[string]$Context.Server;InvocationId=$invocationId}
    Scoped = (-not [string]::Equals($searchBase,$baseDn,[StringComparison]::OrdinalIgnoreCase))
    Incremental = $incremental
    DeltaClause = $deltaClause
    CheckpointRejected = $checkpointRejected
    HighestUsn = $highestUsn
    Server = [string]$Context.Server
    BaseDn = $baseDn
    DurationMs = [long]$watch.ElapsedMilliseconds
    Success = $true
    InvocationId = $invocationId
    LapsSchema = $lapsSchema
}

'@
}


# =====================================================================
# Index des secrets, sans secret.
#
# Une cle BitLocker et un mot de passe LAPS sont protegees dans l annuaire
# par des droits revocables, et chaque lecture y laisse une trace. Les
# recopier sur un poste, meme chiffres, deplace ces valeurs vers un
# stockage qui n a ni l un ni l autre, et sert des secrets perimes quand
# LAPS a fait tourner le mot de passe.
#
# Ce qui est conserve ici ne permet donc jamais de retrouver une valeur :
# le nombre de cles, leurs dates, le schema LAPS, la date d expiration et
# le verdict d acces. Cela suffit a savoir, sans aucun appel, si un poste
# possede des cles et si le compte courant peut les lire.
# =====================================================================

function Save-DomeniaSecretIndexEntry {
    param([Parameter(Mandatory=$true)][AllowEmptyString()][string]$Computer,[int]$BitLockerKeys=-1,[string]$BitLockerLast='', [string]$LapsScheme='', [string]$LapsExpiry='', [string]$Verdict='', [string]$Detail='')
    if(-not $Computer.Trim()){return $false}
    # Do not persist provider error details in the secrets index.
    $row=[pscustomobject]@{Computer=$Computer;BitLockerKeys=$BitLockerKeys;BitLockerLast=$BitLockerLast;LapsScheme=$LapsScheme;LapsExpiry=$LapsExpiry;Verdict=$Verdict;At=[datetime]::UtcNow.ToString('o')}
    return Queue-DomeniaMetadata -Kind SecretMeta -Key $Computer.ToUpperInvariant() -Row $row
}

function Update-DomeniaSecretIndexFromRows {
    # Appelee apres chaque chargement. Ne lit que des metadonnees : le
    # champ Value n est jamais consulte ici, seule son existence compte.
    param([Parameter(Mandatory=$true)][AllowEmptyString()][string]$Computer,[string]$Mode = "",$Rows = @(),[string]$Verdict = "")
    try {
        if ([string]::IsNullOrWhiteSpace($Computer)) { return $false }
        $rows = @($Rows)
        if ($Mode -eq "BitLocker") {
            $keys = @($rows | Where-Object { [string]$_.Kind -eq "BitLocker" })
            $last = ""
            foreach ($r in $keys) {
                $stamp = [string]$r.Timestamp
                if ([string]::IsNullOrWhiteSpace($stamp)) { continue }
                if ([string]::IsNullOrWhiteSpace($last)) { $last = $stamp; continue }
                try { if ([datetime]$stamp -gt [datetime]$last) { $last = $stamp } } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSecretIndexFromRows' $_ }
            }
            return (Save-DomeniaSecretIndexEntry -Computer $Computer -BitLockerKeys (@($keys).Count) -BitLockerLast $last -Verdict $Verdict)
        }
        if ($Mode -eq "LAPS") {
            $scheme = ""
            $expiry = ""
            foreach ($r in $rows) {
                $kind = [string]$r.Kind
                if ($kind -notlike "*LAPS*") { continue }
                if ([string]::IsNullOrWhiteSpace($scheme)) { $scheme = $kind }
                if ([string]::IsNullOrWhiteSpace($expiry)) { $expiry = [string]$r.Timestamp }
            }
            if ([string]::IsNullOrWhiteSpace($scheme)) { $scheme = "aucun attribut LAPS" }
            return (Save-DomeniaSecretIndexEntry -Computer $Computer -LapsScheme $scheme -LapsExpiry $expiry -Verdict $Verdict)
        }
        return $false
    }
    catch { return $false }
}


# =====================================================================
# Remplissage paresseux.
#
# Le journal signalait des rappels d interface de 1 300 a 3 000 ms a
# chaque ouverture d objet. La cause n est pas la lecture dans l annuaire,
# qui se fait en arriere-plan, mais le remplissage : la grille de tous les
# attributs bruts et l analyse des droits etaient recalculees a chaque clic,
# y compris quand l onglet correspondant n etait pas affiche.
#
# Ces deux travaux sont desormais differes jusqu a l affichage de leur
# onglet. Le contenu est marque perime a chaque changement d objet, et
# recalcule une seule fois, au moment ou il devient visible.
# =====================================================================
function Reset-DomeniaDeferredViews {
    param([string]$Dn = "")
    $script:DeferredRawDn = ""
    $script:DeferredPermissionsDn = ""
    $script:DeferredTargetDn = [string]$Dn
    try { [void](Set-DomeniaItemsSource -Name "DgRawAttrs" -Rows @()) } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaDeferredViews' $_ }
}

function Ensure-DomeniaRawAttributes {
    # Recalcule la grille des attributs uniquement si elle est perimee.
    if ($null -eq $script:SelectedObject) { return }
    $dn = [string]$script:SelectedObject.DN
    if ([string]::IsNullOrWhiteSpace($dn)) { return }
    if ([string]$script:DeferredRawDn -ieq $dn) { return }
    $entry = $script:LastLoadedEntry
    if ($null -eq $entry) { return }
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        [void](Set-DomeniaItemsSource -Name "DgRawAttrs" -Rows (Entry-ToRawAttributes $entry))
        $script:DeferredRawDn = $dn
        $sw.Stop()
        Add-DomeniaUiLog -Area "Attributs" -Text ("Attributs affiches en " + [int]$sw.ElapsedMilliseconds + " ms.")
    }
    catch {
        $sw.Stop()
        Write-AppLog "Attributs non affiches : $($_.Exception.Message)" "WARN"
    }
}

function Ensure-DomeniaPermissions {
    # Lance l analyse des droits uniquement si elle est perimee.
    if ($null -eq $script:SelectedObject) { return }
    $dn = [string]$script:SelectedObject.DN
    if ([string]::IsNullOrWhiteSpace($dn)) { return }
    if ([string]$script:DeferredPermissionsDn -ieq $dn) { return }
    $script:DeferredPermissionsDn = $dn
    try { Start-PermissionAnalysis }
    catch { Write-AppLog "Analyse des droits non lancee : $($_.Exception.Message)" "WARN" }
}

function Register-DomeniaDeferredViewHandlers {
    # Chaque conteneur d onglets declenche le calcul de ce qui vient d etre
    # affiche, et rien d autre.
    foreach ($name in @("DetailTabs","WorkspaceTabs")) {
        $control = Get-DomeniaControl -Name $name
        if ($null -eq $control) { continue }
        $control.Add_SelectionChanged({
            param($sender,$e)
            try {
                if ($null -eq $e -or $e.OriginalSource -ne $sender) { return }
                $tabs = Get-DomeniaControl -Name "DetailTabs"
                if ($null -eq $tabs -or $null -eq $tabs.SelectedItem) { return }
                $selected = [string]$tabs.SelectedItem.Name
                if ($selected -eq "TabRaw") { Ensure-DomeniaRawAttributes }
                elseif ($selected -eq "TabPermissions") { Ensure-DomeniaPermissions }
            }
            catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaDeferredViewHandlers' $_ }
        })
    }
}

# =====================================================================
# Raccourcis clavier.
# =====================================================================
function Register-DomeniaShortcuts {
    $window = $script:Window
    if ($null -eq $window) { return 0 }

    $poses = 0
    $script:DomeniaShortcutActions = @{}
    $map = @(
        @{ Key="F5"; Modifiers="None"; Action={ Load-TreeRoot -ForceRefresh } },
        @{ Key="K"; Modifiers="Control"; Action={ Show-DomeniaCommandPalette } },
        @{ Key="C"; Modifiers="Control+Shift"; Action={ Copy-ObjectSummary } },
        @{ Key="F1"; Modifiers="None"; Action={ Select-DomeniaWorkspace -Workspace "TabApplicationTools" } },
        @{ Key="F"; Modifiers="Control"; Action={
            Select-DomeniaWorkspace -Workspace "WsSearch"
            $box = Get-DomeniaControl -Name "TxtGlobalSearch"
            if ($null -ne $box) { [void]$box.Focus(); $box.SelectAll() }
        } },
        @{ Key="D"; Modifiers="Control"; Action={ Select-DomeniaWorkspace -Workspace "TabDashboard" } },
        # L08 (CO-06): Ctrl+L never changes the profile. Essentiel unfolds the session journal; Expert opens Outils > Journal.
        @{ Key="L"; Modifiers="Control"; Action={ Invoke-DomeniaJournalShortcut } },
        @{ Key="I"; Modifiers="Control"; Action={ Select-DomeniaWorkspace -Workspace "TabApplicationTools" -Inner "ApplicationToolTabs" -Tab "TabIndex" } },
        @{ Key="T"; Modifiers="Control"; Action={ Toggle-DomeniaTheme } },
        @{ Key="Escape"; Modifiers="None"; Action={
            # W13 (point 115): Échap closes the open layer (palette, operations panel) or clears the text typed in the
            # search bar. It never empties a result list: the list stays until the next search.
            try { if (Test-DomeniaCommandPaletteOpen) { Hide-DomeniaCommandPalette; return } } catch { $script:DomeniaInterfaceFaults = [int]$script:DomeniaInterfaceFaults + 1 }
            try { if (Test-DomeniaOperationsPanelOpen) { Hide-DomeniaOperationsPanel; return } } catch { $script:DomeniaInterfaceFaults = [int]$script:DomeniaInterfaceFaults + 1 }
            $box = Get-DomeniaControl -Name "TxtGlobalSearch"
            if ($null -ne $box -and $box.IsKeyboardFocusWithin -and -not [string]::IsNullOrEmpty([string]$box.Text)) {
                try { $box.Text = "" } catch { $script:DomeniaInterfaceFaults = [int]$script:DomeniaInterfaceFaults + 1 }
            }
        } }
    )

    foreach ($entry in $map) {
        try {
            $key = [System.Windows.Input.Key]([System.Enum]::Parse([System.Windows.Input.Key],[string]$entry.Key,$true))
            $modifiers = [System.Windows.Input.ModifierKeys]::None
            foreach ($part in @(([string]$entry.Modifiers) -split '\+')) {
                $piece = ([string]$part).Trim()
                if ([string]::IsNullOrWhiteSpace($piece) -or $piece -eq "None") { continue }
                $parsed = [System.Windows.Input.ModifierKeys]([System.Enum]::Parse([System.Windows.Input.ModifierKeys],$piece,$true))
                $modifiers = [System.Windows.Input.ModifierKeys]([int]$modifiers -bor [int]$parsed)
            }

            $gesture = New-Object System.Windows.Input.KeyGesture -ArgumentList @($key,$modifiers)
            $commandName = "DomeniaShortcut{0}" -f $poses
            $command = New-Object System.Windows.Input.RoutedCommand -ArgumentList @($commandName,[System.Windows.Window])
            $script:DomeniaShortcutActions[$commandName] = [scriptblock]$entry.Action

            $binding = New-Object System.Windows.Input.CommandBinding -ArgumentList @($command)
            $binding.Add_Executed({
                param($sender,$args)
                try {
                    $name = [string]$args.Command.Name
                    if ($script:DomeniaShortcutActions.ContainsKey($name)) {
                        & $script:DomeniaShortcutActions[$name]
                    }
                }
                catch { Write-AppLog "Raccourci clavier : $($_.Exception.Message)" "WARN" }
            })

            [void]$window.CommandBindings.Add($binding)
            [void]$window.InputBindings.Add((New-Object System.Windows.Input.KeyBinding -ArgumentList @($command,$gesture)))
            $poses++
        }
        catch {
            Write-AppLog ("Raccourci non enregistré ({0}+{1}) : {2}" -f [string]$entry.Modifiers,[string]$entry.Key,$_.Exception.Message) "WARN"
        }
    }

    Add-DomeniaUiLog -Area "Interface" -Text ("{0} raccourci(s) clavier actifs : F5 arbre, Ctrl+K palette, Ctrl+Maj+C résumé, F1 outils, Ctrl+F rechercher, Ctrl+D accueil, Ctrl+L journal de session, Ctrl+I index, Ctrl+T thème, Échap fermer ou effacer la saisie. Liste complète : palette, Afficher les raccourcis clavier." -f $poses)
    return $poses
}

function Start-ComputerDiagnostics {
    try {
        if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Machine") { Set-Status "Sélectionnez un poste." "WARN"; return }
        $computer = Assert-DomeniaComputerTarget -Computer (Get-CurrentSelectedComputerName)
        $diagnosticState = New-DomeniaClassicCollectionState -Computer $computer -ResultKind 'ComputerDiagnostics' -RequestKey 'diagnostics-v1' -PublishHandler 'Publish-DomeniaComputerDiagnostics' -PublishErrorHandler 'Fail-DomeniaComputerDiagnostics'
        [void](Set-DomeniaControlText -Name "LblComputerDiag" -Text ("Diagnostic de " + $computer + " en cours..."))
        $code = @'
$rows = New-Object Collections.ArrayList
$watch = [System.Diagnostics.Stopwatch]::StartNew()
$budgetMs = [Math]::Max(15000,[int]$Payload.BudgetMs)
$computer = [string]$Payload.Computer
$cred = Get-WMachineCredential $Context
$portTimeout = [Math]::Max(400,[Math]::Min(3000,[int]$Context.PortTimeoutMs))
$script:DiagFallbackTasks=0
$script:DiagTaskBytes=0

function Add-Row {
    param([string]$Check,[string]$Status,[string]$Detail,[int]$Ms,[string]$Method='Classique')
    if([string]::IsNullOrWhiteSpace($Method)){$Method='Classique'}
    [void]$rows.Add([pscustomobject]@{ Check=$Check; Status=$Status; Method=$Method; DurationMs=$Ms; Detail=$Detail })
}
function Test-DiagBudget { return ($watch.ElapsedMilliseconds -lt $budgetMs) }
function Add-Diag {
    param([string]$Check,[scriptblock]$Action,[string]$Method='Classique')
    if (-not (Test-DiagBudget)) { Add-Row $Check 'IGNORE' 'Budget de temps epuise avant ce controle.' 0 $Method; return }
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $status = 'OK'
    $detail = ''
    try { $detail = [string](& $Action) }
    catch {
        if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw}
        $detail = [string]$_.Exception.Message
        $status = 'ERREUR'
        if ($detail -match '(?i)access is denied|acces refuse|denied|0x80070005|authoris') { $status = 'REFUSE' }
        elseif ($detail -match '(?i)timeout|delai|expire|RPC server is unavailable|serveur RPC') { $status = 'INJOIGNABLE' }
    }
    $sw.Stop()
    Add-Row $Check $status $detail ([int]$sw.ElapsedMilliseconds) $Method
}
function Add-Skipped {
    param([string]$Check,[string]$Reason,[string]$Method='Classique')
    Add-Row $Check 'IGNORE' $Reason 0 $Method
}

Add-Diag 'Resolution DNS' {
    $addresses = @([Net.Dns]::GetHostAddresses($computer) | ForEach-Object { $_.IPAddressToString })
    if (@($addresses).Count -eq 0) { throw 'Aucune adresse retournee' }
    return (@($addresses) -join ', ')
}
Add-Diag 'Ping' {
    $ping = New-Object Net.NetworkInformation.Ping
    try {
        $reply = $ping.Send($computer,1500)
        if ($null -eq $reply -or $reply.Status -ne 'Success') { throw ([string]$reply.Status) }
        return ('' + [int]$reply.RoundtripTime + ' ms')
    }
    finally { try { $ping.Dispose() } catch { } }
}

# Les sondes de ports viennent en premier : elles sont bornees et servent
# ensuite a decider quels controles lents valent la peine d etre tentes.
$portMap = @(
    @{ Port=445;  Label='Partage de fichiers SMB' },
    @{ Port=135;  Label='RPC / DCOM' },
    @{ Port=5985; Label='WinRM HTTP' },
    @{ Port=5986; Label='WinRM HTTPS' },
    @{ Port=3389; Label='Bureau a distance' }
)
$open = @{}
foreach ($entry in $portMap) {
    $port = [int]$entry.Port
    $label = [string]$entry.Label
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $isOpen = $false
    try { $isOpen = Test-WTcpPort $computer $port $portTimeout } catch { }
    $sw.Stop()
    $open[$port] = $isOpen
    $status = 'INJOIGNABLE'
    $detail = 'Ferme ou filtre'
    if ($isOpen) { $status = 'OK'; $detail = 'Ouvert' }
    Add-Row ('TCP ' + $port + ' ' + $label) $status $detail ([int]$sw.ElapsedMilliseconds) 'Classique'
}

# Connectivite des fallbacks. Ces controles n'alterent pas le poste :
# PsExec execute seulement une sonde SYSTEM qui renvoie l'identite,
# Task Scheduler effectue uniquement un /query distant.
$pxPath = Get-WPsExecPath $Context
if ([string]::IsNullOrWhiteSpace([string]$pxPath)) {
    Add-Row 'Transport PsExec' 'INDISPONIBLE' 'PsExec.exe / PsExec64.exe absent du dossier Domenia.' 0 'PsExec'
}
elseif (Test-DiagBudget) {
    $pxSw=[Diagnostics.Stopwatch]::StartNew()
    try {
        $pxProbe = '[pscustomobject]@{Computer=[string]$env:COMPUTERNAME;Identity=[string][Security.Principal.WindowsIdentity]::GetCurrent().Name;Ok=$true}'
        $px = Invoke-WRemotePsExecScript $Context $computer $pxProbe ([pscustomobject]@{}) 10
        $pxSw.Stop()
        Add-Row 'Transport PsExec' 'OK' ('Execution distante SYSTEM OK. Identite : '+[string]$px.Identity+'. Executable : '+[IO.Path]::GetFileName([string]$pxPath)) ([int]$pxSw.ElapsedMilliseconds) 'PsExec'
    }
    catch {
        $pxSw.Stop()
        $m=[string]$_.Exception.Message
        $s='ERREUR'
        if($m -match '(?i)access is denied|acces refuse|denied|0x80070005'){$s='REFUSE'}
        elseif($m -match '(?i)timeout|delai|RPC|network path|chemin reseau|injoignable'){$s='INJOIGNABLE'}
        Add-Row 'Transport PsExec' $s $m ([int]$pxSw.ElapsedMilliseconds) 'PsExec'
    }
}
else { Add-Skipped 'Transport PsExec' 'Budget de temps epuise.' 'PsExec' }

if (Test-DiagBudget) {
    $tsSw=[Diagnostics.Stopwatch]::StartNew()
    try {
        $ts = Invoke-WSchtasksRemote $Context $computer @('/query','/fo','LIST') 8
        $tsSw.Stop()
        if([int]$ts.ExitCode -ne 0){throw ('schtasks code '+[string]$ts.ExitCode+' : '+(Get-WSchtasksHint ([int]$ts.ExitCode))+' : '+[string]$ts.Output)}
        Add-Row 'Transport Task Scheduler' 'OK' 'Planificateur distant accessible avec le credential Domenia.' ([int]$tsSw.ElapsedMilliseconds) 'TaskScheduler'
    }
    catch {
        $tsSw.Stop()
        $m=[string]$_.Exception.Message
        $s='ERREUR'
        if($m -match '(?i)access is denied|acces refuse|denied|code 5'){$s='REFUSE'}
        elseif($m -match '(?i)timeout|delai|1722|RPC|53|injoignable'){$s='INJOIGNABLE'}
        Add-Row 'Transport Task Scheduler' $s $m ([int]$tsSw.ElapsedMilliseconds) 'TaskScheduler'
    }
}
else { Add-Skipped 'Transport Task Scheduler' 'Budget de temps epuise.' 'TaskScheduler' }

if ([bool]$open[445]) {
    Add-Diag 'Partage C$' {
        $path = '\\' + $computer + '\C$'
        # Field report 2026-10-07: Test-Path runs under the Windows session; the share is first opened with the
        # operations account (same SMB API as the Ouvrir C$ button).
        if ($null -ne $cred) {
            if (-not ('Domenia.NetUse' -as [type])) { try { Add-Type -TypeDefinition ([string]$Payload.NetUseSource) } catch { if (-not ('Domenia.NetUse' -as [type])) { throw } } }
            $net = $cred.GetNetworkCredential(); $user = if ($net.Domain) { $net.Domain + '\' + $net.UserName } else { $net.UserName }
            if (-not $net.Domain -and $user -notmatch '@' -and [string]$Payload.NetbiosDomain) { $user = [string]$Payload.NetbiosDomain + '\' + $user }
            # Point 41: the SMB logon holds the account lease; the native code travels with the refusal, which is shared.
            Set-WCredentialAttemptIdentity -Context $Context -Credential $cred -Channel Remote -Target $computer
            $shareLease = Enter-WCredentialAttempt -Context $Context -Channel Remote
            try {
                $rc = [Domenia.NetUse]::Connect($path,$user,$net.Password)
                if ($rc -eq 1219) { [void][Domenia.NetUse]::Disconnect('\\' + $computer + '\IPC$'); [void][Domenia.NetUse]::Disconnect($path); $rc = [Domenia.NetUse]::Connect($path,$user,$net.Password) }
            } finally { Exit-WCredentialAttempt $shareLease }
            if ($rc -ne 0) { $failure = [ComponentModel.Win32Exception]::new([int]$rc,('Refuse pour ' + $user + ' : ' + (New-Object ComponentModel.Win32Exception $rc).Message)); [void](Register-WCredentialFailure -Context $Context -ErrorValue $failure -Channel Remote); throw $failure }
        }
        if (-not (Test-Path -LiteralPath $path)) { throw $(if ($null -ne $cred) { 'Inaccessible avec le compte des operations poste' } else { 'Inaccessible avec ta session Windows' }) }
        return $path
    }
}
else { Add-Skipped 'Partage C$' 'Le port 445 ne repond pas : test non tente pour ne pas bloquer le diagnostic.' }

if ([bool]$open[5985] -or [bool]$open[5986]) {
    Add-Diag 'WinRM' {
        $params = @{ ComputerName=$computer; ErrorAction='Stop' }
        if ($null -ne $cred) { $params['Credential'] = $cred; $params['Authentication'] = 'Default' }
        # Point 41: the WinRM logon holds the account lease; Add-Diag records a refusal for every job.
        Set-WCredentialAttemptIdentity -Context $Context -Credential $cred -Channel Remote -Target $computer
        $winrmLease = Enter-WCredentialAttempt -Context $Context -Channel Remote
        try { $r = Test-WSMan @params } finally { Exit-WCredentialAttempt $winrmLease }
        return ('Protocole ' + [string]$r.ProductVersion)
    }
}
else { Add-Skipped 'WinRM' 'Les ports 5985 et 5986 ne repondent pas : test non tente.' }

$cimSession = $null
$cimError = ''
if ([bool]$open[135] -or [bool]$open[5985]) {
    if (Test-DiagBudget) {
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        try {
            $cimSession = New-WDomeniaCimSession $Context $computer $cred ([Math]::Max(5,[Math]::Min(20,[int]$Context.RemoteCommandTimeoutSeconds)))
            $sw.Stop()
            Add-Row 'Session CIM' 'OK' 'Session ouverte.' ([int]$sw.ElapsedMilliseconds)
        }
        catch {
            $sw.Stop()
            $cimError = [string]$_.Exception.Message
            $status = 'ERREUR'
            if ($cimError -match '(?i)access is denied|acces refuse|denied|0x80070005') { $status = 'REFUSE' }
            elseif ($cimError -match '(?i)timeout|RPC server is unavailable|serveur RPC') { $status = 'INJOIGNABLE' }
            Add-Row 'Session CIM' $status $cimError ([int]$sw.ElapsedMilliseconds)
        }
    }
    else { Add-Skipped 'Session CIM' 'Budget de temps epuise.' }
}
else { Add-Skipped 'Session CIM' 'Ni le port 135 ni le port 5985 ne repondent : session non tentee.' }

try {
    if ($null -ne $cimSession) {
        Add-Diag 'Systeme' {
            $cs = Get-CimInstance -CimSession $cimSession -ClassName 'Win32_ComputerSystem' -ErrorAction Stop
            $ram = [Math]::Round([double]$cs.TotalPhysicalMemory / 1GB,1)
            return ('Session ouverte par ' + [string]$cs.UserName + ', ' + $ram + ' Go de memoire, domaine ' + [string]$cs.Domain)
        }
        Add-Diag 'Systeme d exploitation' {
            $os = Get-CimInstance -CimSession $cimSession -ClassName 'Win32_OperatingSystem' -ErrorAction Stop
            $uptime = (Get-Date) - $os.LastBootUpTime
            $days = [int]$uptime.TotalDays
            $hours = [int]$uptime.Hours
            return ([string]$os.Caption + ' ' + [string]$os.Version + ', demarre le ' + [string]$os.LastBootUpTime + ', en service depuis ' + $days + ' j ' + $hours + ' h')
        }
        Add-Diag 'Disque systeme' {
            $d = Get-CimInstance -CimSession $cimSession -ClassName 'Win32_LogicalDisk' -Filter "DeviceID='C:'" -ErrorAction Stop
            $free = [Math]::Round([double]$d.FreeSpace / 1GB,1)
            $size = [Math]::Round([double]$d.Size / 1GB,1)
            $pct = 0
            if ([double]$d.Size -gt 0) { $pct = [Math]::Round(100.0 * [double]$d.FreeSpace / [double]$d.Size,0) }
            # Field report 2026-10-05: number + text converted the text to a number and failed. Formatted as text.
            return ('{0:N1} Go libres sur {1:N1} Go, soit {2:N0} pour cent' -f $free,$size,$pct)
        }
        Add-Diag 'Redemarrage en attente' {
            $keys = @(
                'SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending',
                'SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired'
            )
            $pending = New-Object Collections.ArrayList
            foreach ($key in $keys) {
                $r = Invoke-CimMethod -CimSession $cimSession -Namespace 'root\cimv2' -ClassName 'StdRegProv' -MethodName 'EnumKey' -Arguments @{ hDefKey=[uint32]2147483650; sSubKeyName=$key } -ErrorAction Stop
                if ([int]$r.ReturnValue -eq 0) { [void]$pending.Add($key.Split('\')[-1]) }
            }
            if (@($pending).Count -eq 0) { return 'Aucun redemarrage en attente' }
            return ('Redemarrage requis : ' + (@($pending) -join ', '))
        }
        Add-Diag 'Service de deploiement' {
            $services = @(Get-CimInstance -CimSession $cimSession -ClassName 'Win32_Service' -Filter "Name LIKE '%wapt%'" -ErrorAction Stop)
            if (@($services).Count -eq 0) { return 'Aucun service de deploiement detecte' }
            return ((@($services) | ForEach-Object { [string]$_.Name + ' : ' + [string]$_.State }) -join ', ')
        }
    }
    else {
        $reason = 'Session CIM indisponible.'
        if (-not [string]::IsNullOrWhiteSpace($cimError)) { $reason = 'Session CIM indisponible : ' + $cimError }
        try {
            $local = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
            $fbWatch=[Diagnostics.Stopwatch]::StartNew()
            $fb=Invoke-WRemoteTaskScript $Context $computer $local ([pscustomobject]@{}) ([Math]::Min(60,[int]$Context.TaskFallbackTimeoutSeconds)) $reason
            $fbWatch.Stop()
            $fallbackLabel=if([string]$fb.DomeniaTransport -eq 'PsExec'){'PsExec'}else{'Tache planifiee'}
            Add-Row ('Fallback '+$fallbackLabel) 'OK' ('Collecte locale SYSTEM executee via '+$fallbackLabel+'.') ([int]$fbWatch.ElapsedMilliseconds) $fallbackLabel
            foreach($rr in @($fb.Rows)) { Add-Row ([string]$rr.Check) ([string]$rr.Status) ([string]$rr.Detail) ([int]$rr.DurationMs) $fallbackLabel }
            $script:DiagFallbackTasks=1
            try{$script:DiagTaskBytes=[long]$fb.DomeniaBytesSent+[long]$fb.DomeniaBytesReceived}catch{$script:DiagTaskBytes=0}
        }
        catch {
            Add-Row 'Fallbacks PsExec / tache' 'ERREUR' ([string]$_.Exception.Message) 0 'PsExecTaskScheduler'
            foreach ($check in @('Systeme','Systeme d exploitation','Disque systeme','Redemarrage en attente','Service de deploiement')) {
                Add-Skipped $check ('Acces distant impossible. '+$reason)
            }
        }
    }
}
finally { try { Remove-WDomeniaCimSession $cimSession } catch { } }

$watch.Stop()
$methodsUsed=@($rows | Where-Object { [string]$_.Status -eq 'OK' -and -not [string]::IsNullOrWhiteSpace([string]$_.Method) } | ForEach-Object { [string]$_.Method } | Sort-Object -Unique)
[pscustomobject]@{ SourceCompletedUtc=[datetime]::UtcNow.ToString('o');Reader=$(if($null -ne $cred){[string]$cred.UserName}else{[string]$Context.ProcessIdentity});Rows=@($rows); Computer=$computer; DurationMs=[long]$watch.ElapsedMilliseconds; FallbackTasks=[int]$script:DiagFallbackTasks; TaskBytes=[long]$script:DiagTaskBytes; MethodsUsed=($methodsUsed -join ', ') }

'@
        Start-UiTask `
            -Name ("Diagnostic " + $computer) `
            -OperationId "ComputerDiagnostics" `
            -Code $code `
            -Payload ([pscustomobject]@{ Computer=$computer; BudgetMs=55000; NetUseSource=(Get-DomeniaNetUseSource); NetbiosDomain=[string]$script:Conn.Netbios }) `
            -CallbackState $diagnosticState `
            -ReplaceKey "computerdiag" `
            -DisableControls @("BtnRunComputerDiag") `
            -TimeoutSeconds ([int](Get-CfgValue "Async" "RemoteTimeoutSeconds" 90)) `
            -StatusText ("Diagnostic de " + $computer + " en arriere-plan...") `
            -SuccessHandler 'Complete-DomeniaClassicCollected' `
            -ErrorHandler 'Fail-DomeniaClassicCollected' | Out-Null
    }
    catch { [void](Show-DomeniaOperationError -Operation "Diagnostic du poste" -ErrorRecordOrException $_) }
}

function Publish-DomeniaComputerDiagnostics {
                param($result,$state)
                if(-not (Test-DomeniaClassicResultCurrent $result $state)){return}
                # Seul le poste compte : une relecture de la fiche pendant le
                # diagnostic ne doit pas faire jeter un resultat valide.
                if ($null -eq $script:SelectedObject -or [string]$script:SelectedObject.DN -ine [string]$state.DN) {
                    Write-AppLog "Diagnostic ignore : la selection a change pendant l execution." "INFO"
                    return
                }
                # UX-17 : la vue classe les lignes (reussi, echec, facultatif, non tente) et rend la phrase
                # du haut. Les lignes gardees dans $script:ComputerDiagRows gardent Status, Method et
                # DurationMs : la copie au presse-papiers et le journal de session restent en codes bruts.
                $diagView = ConvertTo-DomeniaDiagVerdict -Rows @($result.Rows) -Computer ([string]$result.Computer)
                $script:ComputerDiagRows = @($diagView.Rows)
                [void](Set-DomeniaItemsSource -Name "DgComputerDiag" -Rows $script:ComputerDiagRows)
                $ok = [int]$diagView.Ok
                $skipped = [int]$diagView.Skipped
                $failed = [int]$diagView.Failed
                $account = [string]$result.Reader
                $summary = "{0} : {1} controle(s) reussi(s), {2} en echec, {3} non tente(s), {4} facultatif(s), en {5} ms. Compte utilise : {6}." -f `
                    ([string]$result.Computer),$ok,$failed,$skipped,[int]$diagView.Info,([long]$result.DurationMs),([string]$account)
                $diagText = [string]$diagView.Verdict
                if ([string]::IsNullOrWhiteSpace($diagText)) { $diagText = [string]$diagView.EmptyText }
                [void](Set-DomeniaControlText -Name "LblComputerDiag" -Text $diagText)
                Set-Status $summary
                Add-DomeniaUiLog -Area "Diagnostic" -Text $summary
                $methods = ""
                try { $methods = [string]$result.MethodsUsed } catch { Write-DomeniaSwallowed 'Core' 'Publish-DomeniaComputerDiagnostics' $_ }
                if (-not [string]::IsNullOrWhiteSpace($methods)) {
                    Add-DomeniaUiLog -Area "Diagnostic" -Text ("{0} : methodes disponibles/utilisees : {1}." -f [string]$result.Computer,$methods)
                }
                foreach($diagRow in @($script:ComputerDiagRows)) {
                    try {
                        Add-DomeniaUiLog -Area "Diagnostic" -Level "DEBUG" -Text ("{0} | {1} | methode={2} | etat={3} | {4} ms | {5}" -f [string]$result.Computer,[string]$diagRow.Check,[string]$diagRow.Method,[string]$diagRow.Status,[int]$diagRow.DurationMs,[string]$diagRow.Detail)
                    } catch { Write-DomeniaSwallowed 'Core' 'Publish-DomeniaComputerDiagnostics' $_ }
                }
                try { Register-DomeniaOperationSample -Operation "ComputerDiagnostics" -Mode $(if([int]$result.FallbackTasks -gt 0){"Classic+TaskFallback"}else{"Classic"}) -ItemCount 1 -DurationMs ([long]$result.DurationMs) -BytesEstimated $(if([long]$result.TaskBytes -gt 0){[long]$result.TaskBytes}else{32000}) -RemoteAttempts 1 -FallbackTasks ([int]$result.FallbackTasks) -SuccessCount $ok -FailureCount $failed } catch { Write-DomeniaSwallowed 'Core' 'Publish-DomeniaComputerDiagnostics' $_ }

}
function Fail-DomeniaComputerDiagnostics {
                param($message,$state)
                if(-not (Test-DomeniaClassicResultCurrent -State $state -ContextOnly)){return}
                if ($null -eq $script:SelectedObject -or [string]$script:SelectedObject.DN -ine [string]$state.DN) { return }
                $detail = ([string]$message).Trim()
                if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue." }
                [void](Set-DomeniaControlText -Name "LblComputerDiag" -Text ("Diagnostic impossible : " + $detail))
                Set-Status ("Diagnostic impossible : " + $detail) "ERROR"
                Add-DomeniaUiLog -Area "Diagnostic" -Level "ERROR" -Text $detail

}

function Copy-ComputerDiagnostics {
    try {
        $lines=@("Domenia - diagnostic de $((Get-CurrentSelectedComputerName))", "Utilisateur associe : $(Get-SelectedAssociationSummary)")
        foreach ($r in @($script:ComputerDiagRows)) { $lines += "$($r.Check) | $($r.Status) | $($r.Method) | $($r.DurationMs) ms | $($r.Detail)" }
        Set-ClipboardSafe ($lines -join [Environment]::NewLine)
        Set-Status "Diagnostic copie."
    } catch { Show-ErrorBox "Copie du diagnostic impossible : $($_.Exception.Message)" }
}




function Get-DomeniaRunningComputerUserProbe {
    param([string]$Computer)
    $normalized = Normalize-LinkComputer $Computer
    if ([string]::IsNullOrWhiteSpace($normalized)) { return $null }
    foreach ($taskId in @($script:AsyncJobs.Keys)) {
        $job = $script:AsyncJobs[$taskId]
        if ($null -eq $job -or [string]$job.OperationId -ne 'ComputerLastUser') { continue }
        if ([bool]$job.CancelRequested -or [bool]$job.Superseded) { continue }
        if ([long]$job.SessionEpoch -ne [long]$script:SessionEpoch) { continue }
        $target = Normalize-LinkComputer ([string]$job.CallbackState.Computer)
        if ($target -ieq $normalized) { return $job }
    }
    return $null
}

function Clear-DomeniaComputerUserProbeState {
    param([string]$ProbeId,[string]$Computer)
    # Un ancien arret ne doit pas effacer l identifiant d une nouvelle detection.
    if ([string]::IsNullOrWhiteSpace($ProbeId) -or [string]$script:ActiveLinkProbeId -ne $ProbeId) { return }
    $normalized = Normalize-LinkComputer $Computer
    if ([string]$script:ActiveLinkProbeComputer -ine $normalized) { return }
    $script:ActiveLinkProbeId = ''
    $script:ActiveLinkProbeComputer = ''
    try { if ($script:LinkProbeDone.ContainsKey($normalized)) { [void]$script:LinkProbeDone.Remove($normalized) } } catch { Write-DomeniaSwallowed 'Core' 'Clear-DomeniaComputerUserProbeState' $_ }
}

function Receive-DomeniaComputerUserProbeProgress {
    param($Job)
    if ($null -eq $Job -or [string]$Job.OperationId -ne 'ComputerLastUser') { return }
    if ([long]$Job.SessionEpoch -ne [long]$script:SessionEpoch) { return }
    $queue = $null
    try { $queue = $Job.CallbackState.Progress } catch { Write-DomeniaSwallowed 'Core' 'Receive-DomeniaComputerUserProbeProgress' $_ }
    if ($null -eq $queue) { return }
    $computer = Normalize-LinkComputer ([string]$Job.CallbackState.Computer)
    $probeId = [string]$Job.CallbackState.ProbeId
    # File thread-safe, bornee par le nombre fixe de methodes et le budget du resolver.
    for ($i=0; $i -lt 32; $i++) {
        $item = $null
        if (-not $queue.TryDequeue([ref]$item)) { break }
        if ($null -eq $item) { continue }
        $detail = ([regex]::Replace(([string]$item.Detail),'\s+',' ')).Trim()
        if ($detail.Length -gt 1200) { $detail = $detail.Substring(0,1200)+' [...]' }
        $level = if ([string]$item.Status -in @('KO','VALIDATION AD KO')) { 'WARN' } else { 'INFO' }
        Write-AppLog ("Association {0} [probe={1}] | {2} [{3}] | {4}" -f $computer,$probeId,[string]$item.Method,[string]$item.Status,$detail) $level
        if ([string]$item.Status -eq 'EN COURS' -and [string]$script:ActiveLinkProbeId -eq $probeId -and
            (Get-CurrentSelectedComputerName) -ieq $computer) {
            [void](Set-DomeniaControlText -Name 'LblLinkProbeStatus' -Text ("Detection de {0} : {1}..." -f $computer,[string]$item.Method))
        }
    }
}

function Stop-DomeniaComputerUserProbeUi {
    param($Job,[string]$Reason)
    if ($null -eq $Job -or [string]$Job.OperationId -ne 'ComputerLastUser') { return }
    $computer = Normalize-LinkComputer ([string]$Job.CallbackState.Computer)
    $probeId = [string]$Job.CallbackState.ProbeId
    $wasCurrent = (-not [string]::IsNullOrWhiteSpace($probeId) -and [string]$script:ActiveLinkProbeId -eq $probeId)
    Receive-DomeniaComputerUserProbeProgress -Job $Job
    Clear-DomeniaComputerUserProbeState -ProbeId $probeId -Computer $computer
    $elapsed = [Math]::Max(0,[int]((Get-Date)-$Job.Started).TotalSeconds)
    Write-AppLog ("Association interrompue : {0} [probe={1}], apres {2}s, motif={3}, remplacee={4}." -f $computer,$probeId,$elapsed,$Reason,[bool]$Job.Superseded) 'WARN'
    if ($wasCurrent -and -not [bool]$Job.Superseded -and -not [bool]$Job.TimeoutErrorDelivered -and
        (Get-CurrentSelectedComputerName) -ieq $computer) {
        [void](Set-DomeniaControlText -Name 'LblLinkProbeStatus' -Text ("Detection annulee pour {0}. Association en cache conservee ; relance possible apres nettoyage." -f $computer))
    }
    if ((Get-CurrentSelectedComputerName) -ieq $computer) { Refresh-AssociationContext -SkipResultRefresh }
}

function Complete-DomeniaComputerUserProbeUi {
    param($Result,$State)
    if([string](Get-DomeniaMemberValue $Result 'DataSource') -cne 'SQLite'){return}
    $computer = ""
    $probeId = ""
    try { $computer = Normalize-LinkComputer ([string]$State.Computer) } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerUserProbeUi' $_ }
    try { $probeId = [string]$State.ProbeId } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerUserProbeUi' $_ }
    if ([string]::IsNullOrWhiteSpace($computer)) { $computer = "machine inconnue" }

    # Un ancien worker ne doit jamais ecraser la fiche d'une machine selectionnee ensuite.
    if (-not [string]::IsNullOrWhiteSpace($probeId) -and [string]$script:ActiveLinkProbeId -ne $probeId) {
        Write-AppLog "Resultat obsolete ignore pour $computer (probe=$probeId)." "INFO"
        return
    }

    # Double verrou : meme un callback portant encore le bon probeId est
    # rejete si l'utilisateur a change de machine dans la grille.
    $currentComputer = ""
    try {
        if ($null -ne $script:SelectedObject -and [string]$script:SelectedObject.Type -eq "Machine") {
            $currentComputer = Get-CurrentSelectedComputerName
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerUserProbeUi' $_ }
    if ([string]::IsNullOrWhiteSpace($currentComputer) -or $currentComputer -ine $computer) {
        Write-AppLog "Resultat user-machine ignore : machine courante '$currentComputer', resultat pour '$computer'." "INFO"
        return
    }

    try {
        $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Computer","Success","Attempts")
        if ($null -eq $effective) { throw "Le worker n'a retourne aucun resultat de detection exploitable." }
        [void](Set-DomeniaItemsSource -Name "DgLinkAttempts" -Rows @($effective.Attempts))
        foreach ($attempt in @($effective.Attempts)) {
            if ([string]$attempt.Status -eq 'OK') { continue }
            $attemptDetail=([regex]::Replace(([string]$attempt.Detail),'\s+',' ')).Trim()
            if ($attemptDetail.Length -gt 1600) { $attemptDetail=$attemptDetail.Substring(0,1600)+' [...]' }
            Add-DomeniaUiLog -Area 'Association' -Level $(if([string]$attempt.Status -in @('KO','VALIDATION AD KO')){'WARN'}else{'INFO'}) -Text ("{0} | {1} [{2}] | {3}" -f $computer,[string]$attempt.Method,[string]$attempt.Status,$attemptDetail)
        }

        $minimumConfidence = 60
        try { $minimumConfidence = [Math]::Max(0,[Math]::Min(100,[int](Get-CfgValue "UserMachineLink" "MinimumConfidence" 60))) } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerUserProbeUi' $_ }
        $confidence = 0
        try { $confidence = [int]$effective.Confidence } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerUserProbeUi' $_ }
        $user = Normalize-LinkUser ([string]$effective.UserLogin)

        if ([bool]$effective.Success -and [bool]$effective.VerifiedInAD -and $confidence -ge $minimumConfidence -and -not [string]::IsNullOrWhiteSpace($user)) {
            $added = Add-DomeniaRelation -Relation ([pscustomobject]@{UserLogin=$user;Computer=[string]$effective.Computer;Source=[string]$effective.Source;Details=[string]$effective.Details;Confidence=$confidence;VerifiedInAD=$true;When=[string]$effective.SourceCompletedUtc;ComputerGuid=[string]$State.StoreGuid;ComputerDn=[string]$State.StoreDn}) -NoSave -Quiet
            $message = if ($added) { "Utilisateur detecte pour $computer : $user ($([string]$effective.Source), confiance $confidence%)." } else { "Utilisateur detecte pour $computer : $user. Le stockage local n'a pas ete modifie." }
            [void](Set-DomeniaControlText -Name "LblLinkProbeStatus" -Text $message)
            $messageLevel = if ($added) { "INFO" } else { "WARN" }
            Set-Status $message $messageLevel
            Write-AppLog $message $messageLevel
            $probeMethod = "Classique"
            try {
                if (-not [string]::IsNullOrWhiteSpace([string]$effective.FallbackTransport)) { $probeMethod = [string]$effective.FallbackTransport }
                elseif ([string]$effective.Source -match '(?i)CIM|WMI|registre|Security|profil|description|LogonUI') { $probeMethod = "Classique" }
            } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerUserProbeUi' $_ }
            Add-DomeniaUiLog -Area "Association" -Text ("{0} : information dernier utilisateur obtenue via {1} ; source={2} ; utilisateur={3} ; confiance={4}%." -f $computer,$probeMethod,[string]$effective.Source,$user,$confidence)
            try { Refresh-AssociationContext } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerUserProbeUi' $_ }
            try { Register-DomeniaOperationSample -Operation "ComputerLastUser" -Mode $(if($probeMethod -eq "PsExec"){"Classic+PsExec"}elseif($probeMethod -eq "Tache planifiee"){"Classic+TaskScheduler"}else{"Classic"}) -ItemCount 1 -DurationMs 0 -BytesEstimated $(if([long]$effective.TaskBytes -gt 0){[long]$effective.TaskBytes}else{16000}) -RemoteAttempts 1 -FallbackTasks ([int]$effective.FallbackTasks) -SuccessCount 1 } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerUserProbeUi' $_ }
        }
        else {
            try { if ($script:LinkProbeDone.ContainsKey($computer)) { [void]$script:LinkProbeDone.Remove($computer) } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerUserProbeUi' $_ }
            $remoteFailed = $false
            try { if ($null -ne $effective.PSObject.Properties["RemoteAccessFailed"]) { $remoteFailed = [bool]$effective.RemoteAccessFailed } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerUserProbeUi' $_ }
            if ($remoteFailed) {
                $cached = Get-ExistingLinkForComputer $computer
                if ($null -ne $cached -and -not [string]::IsNullOrWhiteSpace([string]$cached.UserLogin)) {
                    $message = "Utilisateur conserve depuis le cache : $($cached.UserLogin). Confirmation distante indisponible, aucune donnee locale perdue."
                    [void](Set-DomeniaControlText -Name "LblLinkProbeStatus" -Text $message)
                    Set-Status $message "WARN"

                }
                else {
                    $message = "Utilisateur non determine pour $computer. Voir les tentatives et le journal Association pour le compte utilise et l'erreur de chaque transport."
                    [void](Set-DomeniaControlText -Name "LblLinkProbeStatus" -Text $message)
                    Set-Status $message "WARN"
                }
            }
            else {
                $message = "Aucun utilisateur AD suffisamment fiable pour $computer apres methodes classiques et fallback tache planifiee."
                [void](Set-DomeniaControlText -Name "LblLinkProbeStatus" -Text $message)
                Set-Status $message "WARN"
            }
            Write-AppLog $message 'WARN'
        }
    }
    catch {
        Fail-DomeniaComputerUserProbeUi -Message $_.Exception.Message -State ([pscustomobject]@{ Computer=$computer; ProbeId=$probeId })
    }
    finally {
        if ([string]$script:ActiveLinkProbeId -eq $probeId) {
            $script:ActiveLinkProbeId = ""
            $script:ActiveLinkProbeComputer = ""
        }
        try { Refresh-AssociationContext -SkipResultRefresh } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerUserProbeUi' $_ }
    }
}

function Fail-DomeniaComputerUserProbeUi {
    param($Message,$State)
    $computer = ""
    $probeId = ""
    try { $computer = Normalize-LinkComputer ([string]$State.Computer) } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaComputerUserProbeUi' $_ }
    try { $probeId = [string]$State.ProbeId } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaComputerUserProbeUi' $_ }
    if ([string]::IsNullOrWhiteSpace($computer)) { $computer = "machine inconnue" }
    if (-not [string]::IsNullOrWhiteSpace($probeId) -and [string]$script:ActiveLinkProbeId -ne $probeId) { return }
    if ((Get-CurrentSelectedComputerName) -ine $computer) {
        Clear-DomeniaComputerUserProbeState -ProbeId $probeId -Computer $computer
        return
    }
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue du worker." }
    try { if ($script:LinkProbeDone.ContainsKey($computer)) { [void]$script:LinkProbeDone.Remove($computer) } } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaComputerUserProbeUi' $_ }
    if ([string]$script:ActiveLinkProbeId -eq $probeId) { $script:ActiveLinkProbeId=""; $script:ActiveLinkProbeComputer="" }
    [void](Set-DomeniaControlText -Name "LblLinkProbeStatus" -Text "Echec pour $computer : $detail")
    Set-Status "Détection du dernier utilisateur de $computer : $detail" "ERROR"
    Write-AppLog "Detection du dernier utilisateur de $computer : $detail" "ERROR"
    try { Refresh-AssociationContext -SkipResultRefresh } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaComputerUserProbeUi' $_ }
}

function Start-ComputerUserLinkProbe {
    param([string]$Computer,[switch]$Force,[string]$Origin='',$RelationsSubject=$null)
    $computerNorm = Normalize-LinkComputer $Computer
    # D048: only an explicit gesture or the selected workstation may start a probe; a list render never does.
    if ([string]::IsNullOrWhiteSpace($Origin)) { $Origin = if ($Force) { 'ExplicitRecheck' } else { 'SelectedMachine' } }
    $probeRule = Get-Command -Name 'Test-DomeniaProbeAllowed' -CommandType Function -ErrorAction SilentlyContinue
    if ($null -ne $probeRule -and -not (Test-DomeniaProbeAllowed $Origin)) {
        Write-AppLog ("Sonde user-machine refusee pour {0} : origine '{1}' non explicite." -f $computerNorm,$Origin) 'INFO'
        return
    }
    if ($null -ne $script:Live -and -not $Force -and (Request-DomeniaLiveSelectedProbe -Computer $Computer)) { return }
    if ($null -ne $script:Live -and $Force -and (Test-DomeniaLiveSearchActive)) {
        foreach ($row in $script:Live.Search.Rows) {
            if ($row.Type -eq 'Machine' -and (Normalize-LinkComputer $row.Name) -eq $computerNorm -and $script:Live.Busy.ContainsKey((Get-DomeniaLiveObjectKey $row))) {
                Set-Status 'Une détection est déjà en cours pour ce poste. Aucune sonde en double.'
                return
            }
        }
    }

    try {
        if ([string]::IsNullOrWhiteSpace($computerNorm)) { return }

        # Le registre des vraies taches fait autorite, pas un ancien drapeau.
        $runningProbe = Get-DomeniaRunningComputerUserProbe -Computer $computerNorm
        if ($null -ne $runningProbe) {
            $script:ActiveLinkProbeId = [string]$runningProbe.CallbackState.ProbeId
            $script:ActiveLinkProbeComputer = $computerNorm
            [void](Set-DomeniaControlText -Name 'LblLinkProbeStatus' -Text "Detection deja en cours pour $computerNorm : requete conservee.")
            if ($Force) { Write-AppLog "Detection deja en cours pour $computerNorm : aucun redemarrage du worker." 'INFO' }
            return
        }
        if ([string]$script:ActiveLinkProbeComputer -ieq $computerNorm) {
            Clear-DomeniaComputerUserProbeState -ProbeId ([string]$script:ActiveLinkProbeId) -Computer $computerNorm
        }

        # LOCAL-FIRST : une association connue est immédiatement exploitable.
        # On ne bloque jamais l'interface en attendant une confirmation distante.
        $existing = Get-ExistingLinkForComputer $computerNorm
        $existingAgeHours = 99999.0
        $existingConfidence = 0
        $existingManual = $false
        if ($null -ne $existing) {
            try { $existingAgeHours = ((Get-Date) - [datetime]([string]$existing.When)).TotalHours } catch { Write-DomeniaSwallowed 'Core' 'Start-ComputerUserLinkProbe' $_ }
            try { $existingConfidence = [int]$existing.Confidence } catch { Write-DomeniaSwallowed 'Core' 'Start-ComputerUserLinkProbe' $_ }
            $existingManual = ([string]$existing.Source -match '^(?i:Saisie manuelle|Manual)')

            $cacheHours = 4.0
            try { $cacheHours = [Math]::Max(0.25,[double](Get-CfgValue "UserMachineLink" "ObjectRefreshHours" 4)) } catch { Write-DomeniaSwallowed 'Core' 'Start-ComputerUserLinkProbe' $_ }
            $fresh = ($existingAgeHours -lt $cacheHours)

            # D043: the stored source and its age qualify the association; no percentage is shown.
            $cachedMessage = "Utilisateur associe : $($existing.UserLogin) | source $($existing.Source) | age " + ($(if($existingAgeHours -lt 1){"$([Math]::Round($existingAgeHours*60,0)) min"}else{"$([Math]::Round($existingAgeHours,1)) h"}))
            [void](Set-DomeniaControlText -Name "LblLinkProbeStatus" -Text $cachedMessage)
            Set-Status $cachedMessage
            Add-DomeniaUiLog -Area "Association" -Text ("LOCAL-FIRST {0} : association {1}, source {2}, age {3} h." -f $computerNorm,[string]$existing.UserLogin,[string]$existing.Source,[Math]::Round($existingAgeHours,2))

            # Une association manuelle ou tres recente est une source forte :
            # elle ne doit pas etre remplacée par une sonde automatique.
            if (-not $Force -and ($fresh -or $existingManual)) {
                return
            }
        }

        $probeId = [guid]::NewGuid().ToString("N")
        $script:ActiveLinkProbeId = $probeId
        $script:ActiveLinkProbeComputer = $computerNorm

        $classicTimeout = [Math]::Max(4,[Math]::Min(10,[int](Get-CfgValue "UserMachineLink" "ClassicProbeTimeoutSeconds" 7)))
        $taskFallbackTimeout = [Math]::Max(12,[Math]::Min(30,[int](Get-CfgValue "UserMachineLink" "TaskFallbackProbeTimeoutSeconds" 18)))
        $methodTimeout = [Math]::Max(1000,[Math]::Min(4000,[int](Get-CfgValue "UserMachineLink" "ProbeMethodTimeoutMs" 2500)))
        # Inclut le plancher 10s PsExec + 15s schtasks et le nettoyage distant.
        # Les appels natifs non cooperatifs restent geres par le moteur existant.
        $overallTimeout = $classicTimeout + [Math]::Max(25,$taskFallbackTimeout) + 20
        $probeProgress = New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]' 

        $code = @'
$attempts = New-Object Collections.ArrayList
$totalWatch = [System.Diagnostics.Stopwatch]::StartNew()
$classicTimeoutMs = [Math]::Max(3000,[int]$Payload.ClassicTimeoutMs)
$taskFallbackTimeoutSeconds = [Math]::Max(12,[int]$Payload.TaskFallbackTimeoutSeconds)
$methodTimeoutMs = [Math]::Max(1000,[int]$Payload.MethodTimeoutMs)
function Add-Attempt {
    param($Method,$Status,$User,$Score,$Ms,$Detail)
    $attempt = [pscustomobject]@{ Method=$Method; Status=$Status; User=$User; Score=$Score; DurationMs=$Ms; Detail=$Detail }
    [void]$attempts.Add($attempt)
    # Completed attempt details are published after SQLite commit; only step names are streamed.
}
function Set-ProbeStep {
    param([string]$Method)
    try {
        if ($null -ne $Payload.Progress) {
            $Payload.Progress.Enqueue([pscustomobject]@{ Method=$Method; Status='EN COURS'; Detail='Appel en cours.' })
        }
    } catch { }
}
function Test-ProbeBudget {
    Assert-WCredentialAllowed -Context $Context -Channel Remote
    Assert-WCredentialAllowed -Context $Context -Channel Directory
    if ($totalWatch.ElapsedMilliseconds -ge $classicTimeoutMs) { throw "Budget des methodes classiques depasse (${classicTimeoutMs} ms)." }
}
function Get-RemainingMethodTimeout {
    $remaining = $classicTimeoutMs - [int]$totalWatch.ElapsedMilliseconds
    return [Math]::Max(500,[Math]::Min($methodTimeoutMs,$remaining))
}
function Return-Candidate {
    param([string]$Method,[string]$Raw,[int]$Score,[string]$Detail,[int]$Ms)
    $u = Normalize-WUser $Raw
    if ([string]::IsNullOrWhiteSpace($u)) { Add-Attempt $Method "VIDE" "" 0 $Ms $Detail; return $null }
    # D049: a local account or an account of another authority is not the AD account with the same login.
    # The next source is tried instead of stopping the pipeline; the UI applies Test-DomeniaAccountIdentityMatch.
    $rawAccount = ($Raw + "").Trim().Trim('"')
    if ($rawAccount.Contains([string][char]92)) {
        $authority = $rawAccount.Substring(0,$rawAccount.IndexOf([char]92))
        $shortComputer = ([string]$Payload.Computer).Split('.')[0]
        $knownAuthorities = @(@([string]$Context.Netbios,[string]$Context.Domain) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
        if ($authority -eq '.' -or $authority -ieq $shortComputer) { Add-Attempt $Method 'COMPTE LOCAL' $rawAccount 0 $Ms ('Compte local du poste, pas un compte du domaine. '+$Detail); return $null }
        if ($knownAuthorities.Count -gt 0 -and @($knownAuthorities | Where-Object { $_ -ieq $authority }).Count -eq 0) { Add-Attempt $Method 'HORS DOMAINE' $rawAccount 0 $Ms ('Compte d une autre autorite ('+$authority+'). '+$Detail); return $null }
    }
    Set-ProbeStep ('Validation AD du candidat ('+$Method+')')
    $validation = Test-WUserInAd $Context $u -Detailed
    if (-not [bool]$validation.LookupSucceeded) {
        Add-Attempt $Method 'VALIDATION AD KO' $u 0 $Ms ('Candidat lu, verification LDAP impossible : '+[string]$validation.Error)
        return $null
    }
    $verified = [bool]$validation.Verified
    Add-Attempt $Method $(if($verified){"OK"}else{"HORS AD"}) $u $Score $Ms $Detail
    if ($verified) {
        return [pscustomobject]@{ Computer=[string]$Payload.Computer; UserLogin=$u; RawAccount=$rawAccount; Source=$Method; Confidence=$Score; VerifiedInAD=$true; Details=$Detail; Attempts=@($attempts); Success=$true; SourceCompletedUtc=[datetime]::UtcNow.ToString('o') }
    }
    return $null
}
$computer = [string]$Payload.Computer
$cred = Get-WMachineCredential $Context
$taskFallbackError = ""
$machineIdentity=if($null -ne $cred){[string]$cred.UserName}else{[string]$Context.ProcessIdentity}
$adIdentity=if([bool]$Context.UseCredential){[string]$Context.BindUser}else{[string]$Context.ProcessIdentity}
Add-Attempt 'Comptes effectifs' 'INFO' '' 0 0 ('Lecture AD='+$adIdentity+' ; acces poste='+$machineIdentity+'. Aucun mot de passe journalise.')

# RESOLVER RAPIDE : on cherche d'abord les sources peu couteuses et tres
# discriminantes. Une preuve valide arrete immediatement le pipeline.
# 1. CIM : utilisateur courant puis dernier compte LogonUI via la meme session.
# StdRegProv passe par CIM ; ne demarre pas le service RemoteRegistry.
try {
    Test-ProbeBudget
    Set-ProbeStep 'Ouverture session CIM'
    $sw=[System.Diagnostics.Stopwatch]::StartNew(); $cimSession=$null
    try {
        $cimSession=New-WDomeniaCimSession $Context $computer $cred ([Math]::Max(2,[int]([Math]::Ceiling((Get-RemainingMethodTimeout)/1000.0))))
        try {
            Test-ProbeBudget
            Set-ProbeStep 'CIM utilisateur courant'
            $cs=Get-CimInstance -CimSession $cimSession -ClassName 'Win32_ComputerSystem' -Property UserName -OperationTimeoutSec ([Math]::Max(1,[int][Math]::Ceiling((Get-RemainingMethodTimeout)/1000.0))) -ErrorAction Stop
            $hit=Return-Candidate 'CIM utilisateur courant' ([string]$cs.UserName) 97 'Win32_ComputerSystem.UserName' ([int]$sw.ElapsedMilliseconds)
            if($null -ne $hit){$hit;return}
        } catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};Add-Attempt 'CIM utilisateur courant' 'KO' '' 0 ([int]$sw.ElapsedMilliseconds) $_.Exception.Message }
        if ([bool]$Payload.UseRemoteRegistry) {
            foreach ($valueName in @('LastLoggedOnSAMUser','LastLoggedOnUser')) {
                if ($totalWatch.ElapsedMilliseconds -ge $classicTimeoutMs) { break }
                try {
                    Test-ProbeBudget
                    Set-ProbeStep ('CIM LogonUI '+$valueName)
                    $reg = Invoke-CimMethod -CimSession $cimSession -Namespace 'root\default' -ClassName 'StdRegProv' -MethodName 'GetStringValue' -Arguments @{
                        hDefKey=[uint32]2147483650
                        sSubKeyName='SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI'
                        sValueName=$valueName
                    } -OperationTimeoutSec ([Math]::Max(1,[int][Math]::Ceiling((Get-RemainingMethodTimeout)/1000.0))) -ErrorAction Stop
                    if ([uint32]$reg.ReturnValue -ne 0) { throw ("StdRegProv $valueName : code "+[string]$reg.ReturnValue) }
                    $hit=Return-Candidate 'CIM dernier utilisateur LogonUI' ([string]$reg.sValue) 91 $valueName ([int]$sw.ElapsedMilliseconds)
                    if($null -ne $hit){$hit;return}
                } catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};Add-Attempt 'CIM dernier utilisateur LogonUI' 'KO' '' 0 ([int]$sw.ElapsedMilliseconds) $_.Exception.Message }
            }
        }
    }
    finally { Remove-WDomeniaCimSession $cimSession; $sw.Stop() }
} catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};Add-Attempt 'Session CIM' 'KO' '' 0 0 $_.Exception.Message }

# 2. WinRM uniquement si le transport est vraisemblablement disponible.
# Cela evite un appel long sur les postes dont 5985/5986 sont fermes.
if ([bool]$Context.UseWinRM) {
try {
    Test-ProbeBudget
    Set-ProbeStep 'WinRM session'
    $open5985=$false;$open5986=$false
    try{$open5985=Test-WTcpPort $computer 5985 350}catch{}
    if(-not $open5985){try{$open5986=Test-WTcpPort $computer 5986 350}catch{}}
    if($open5985 -or $open5986){
        $sw=[System.Diagnostics.Stopwatch]::StartNew(); $remaining=Get-RemainingMethodTimeout
        $so=New-PSSessionOption -OpenTimeout $remaining -OperationTimeout $remaining
        $params=@{ComputerName=$computer;ErrorAction="Stop";SessionOption=$so;ScriptBlock={
            $cs=Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
            $owners=@()
            Get-CimInstance Win32_Process -Filter "Name='explorer.exe'" -ErrorAction SilentlyContinue | ForEach-Object { try{$o=Invoke-CimMethod -InputObject $_ -MethodName GetOwner -ErrorAction Stop;if($o.User){$owners += "$($o.Domain)\$($o.User)"}}catch{} }
            $last="";try{$last=(Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI" -ErrorAction Stop).LastLoggedOnSAMUser}catch{}
            [pscustomobject]@{Current=[string]$cs.UserName;Explorer=@($owners);Last=[string]$last}
        }}
        if($null -ne $cred){$params["Credential"]=$cred;$params["Authentication"]="Default"}
        if (-not $open5985 -and $open5986) { $params['UseSSL']=$true }
        # Point 41: the WinRM logon holds the account lease, like the CIM sessions of this probe.
        Set-WCredentialAttemptIdentity -Context $Context -Credential $cred -Channel Remote -Target $computer
        $winrmLease=Enter-WCredentialAttempt -Context $Context -Channel Remote
        try{$r=Invoke-Command @params}finally{Exit-WCredentialAttempt $winrmLease}
        $sw.Stop()
        # Each value keeps its own nature: current session, explorer owner, or LogonUI history (D042/D043).
        $winrmCandidates=@([pscustomobject]@{Method='WinRM utilisateur courant';Raw=[string]$r.Current;Detail='Win32_ComputerSystem.UserName'})
        foreach($owner in @($r.Explorer)){$winrmCandidates+=[pscustomobject]@{Method='WinRM session explorer';Raw=[string]$owner;Detail='Proprietaire explorer.exe'}}
        $winrmCandidates+=[pscustomobject]@{Method='WinRM dernier utilisateur LogonUI';Raw=[string]$r.Last;Detail='LastLoggedOnSAMUser'}
        foreach($candidate in $winrmCandidates){
            $hit=Return-Candidate $candidate.Method $candidate.Raw 100 $candidate.Detail ([int]$sw.ElapsedMilliseconds)
            if($null -ne $hit){$hit;return}
        }
    } else { Add-Attempt "WinRM session" "NON DISPONIBLE" "" 0 0 "5985/5986 fermes ou filtres." }
} catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};Add-Attempt "WinRM session" "KO" "" 0 0 $_.Exception.Message }
} else { Add-Attempt 'WinRM session' 'DESACTIVE' '' 0 0 'WinRM desactive dans la configuration ; aucune sonde de port.' }

# 3. Registre distant seulement si explicitement autorise.
if ([bool]$Payload.AllowUnboundedFallbacks -and [bool]$Payload.UseRemoteRegistry) {
    try {
        Test-ProbeBudget
        Set-ProbeStep 'Registre distant optionnel'
        $sw=[System.Diagnostics.Stopwatch]::StartNew();$base=[Microsoft.Win32.RegistryKey]::OpenRemoteBaseKey("LocalMachine",$computer);$key=$base.OpenSubKey("SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI");$sw.Stop()
        foreach($n in @("LastLoggedOnSAMUser","LastLoggedOnUser")){$raw=[string]$key.GetValue($n,"");$hit=Return-Candidate "Registre LogonUI" $raw 88 "$n=$raw" ([int]$sw.ElapsedMilliseconds);if($null -ne $hit){try{$key.Dispose();$base.Dispose()}catch{};$hit;return}}
        try{$key.Dispose();$base.Dispose()}catch{}
    } catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};Add-Attempt "Registre LogonUI" "KO" "" 0 0 $_.Exception.Message }
}

# 4. Profils CIM : une seule session, pas de reconnexion par profil.
try {
    Test-ProbeBudget
    Set-ProbeStep 'CIM profil recent'
    $sw=[System.Diagnostics.Stopwatch]::StartNew();$cimSession=$null
    try{$cimSession=New-WDomeniaCimSession $Context $computer $cred ([Math]::Max(2,[int]([Math]::Ceiling((Get-RemainingMethodTimeout)/1000.0))));$profiles=@(Get-CimInstance -CimSession $cimSession -ClassName "Win32_UserProfile" -Property LocalPath,LastUseTime,Special,Loaded -OperationTimeoutSec ([Math]::Max(1,[int][Math]::Ceiling((Get-RemainingMethodTimeout)/1000.0))) -ErrorAction Stop | Where-Object {-not $_.Special -and $_.LocalPath} | Sort-Object LastUseTime -Descending)}
    finally{Remove-WDomeniaCimSession $cimSession}
    $sw.Stop()
    foreach($p in ($profiles|Select-Object -First 5)){$raw=Split-Path -Leaf ([string]$p.LocalPath);$hit=Return-Candidate "CIM profil recent" $raw 82 "LastUse=$($p.LastUseTime), Loaded=$($p.Loaded)" ([int]$sw.ElapsedMilliseconds);if($null -ne $hit){$hit;return}}
} catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};Add-Attempt "CIM profil recent" "KO" "" 0 0 $_.Exception.Message }

# 5. Security 4624 : uniquement si active dans la configuration.
if ([bool]$Payload.UseSecurityLog) {
    try {
        Test-ProbeBudget
        Set-ProbeStep 'Journal Security 4624 optionnel'
        # Point 41: this read goes out with the Windows session of Domenia, not the workstation account: its lease and
        # any refusal belong to the session identity, never to the account of the previous CIM step.
        Set-WCredentialAttemptIdentity -Context $Context -Credential $null -Channel Remote -Target $computer
        $eventLease=Enter-WCredentialAttempt -Context $Context -Channel Remote
        $sw=[System.Diagnostics.Stopwatch]::StartNew();try{$events=@(Get-WinEvent -ComputerName $computer -FilterHashtable @{LogName="Security";Id=4624} -MaxEvents 40 -ErrorAction Stop)}finally{Exit-WCredentialAttempt $eventLease};$sw.Stop()
        foreach($ev in $events){try{$lt=[string]$ev.Properties[8].Value;if($lt -notin @("2","10","11")){continue};$raw=[string]$ev.Properties[5].Value;$hit=Return-Candidate "Security 4624" $raw 80 "LogonType=$lt, Time=$($ev.TimeCreated)" ([int]$sw.ElapsedMilliseconds);if($null -ne $hit){$hit;return}}catch{}}
    } catch { if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};Add-Attempt "Security 4624" "KO" "" 0 0 $_.Exception.Message }
}

# 7. Dernier recours : execution locale SYSTEM par une seule tache RunOnce.
# IMPORTANT : ce fallback possede son propre budget. Il est toujours tente
# apres les methodes classiques, meme si leur budget est entierement consomme.
try {
    Assert-WCredentialAllowed -Context $Context -Channel Remote
    Assert-WCredentialAllowed -Context $Context -Channel Directory
    $sw=[Diagnostics.Stopwatch]::StartNew()
    $local=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
    Set-ProbeStep 'Secours PsExec / tache planifiee'
    $classicDetail=Get-WProbeAttemptSummary -Attempts @($attempts)
    $fb=Invoke-WRemoteTaskScript $Context $computer $local ([pscustomobject]@{}) ([Math]::Min($taskFallbackTimeoutSeconds,[int]$Context.TaskFallbackTimeoutSeconds)) $classicDetail
    $sw.Stop()
    $fallbackLabel=if([string]$fb.DomeniaTransport -eq 'PsExec'){'PsExec'}else{'Tache planifiee'}
    # Current sessions (ComputerSystem, QUSER) are tried before LogonUI and profiles; stable order for equal ranks.
    $fallbackOrder=@();$fallbackIndex=0
    foreach($candidate in @($fb.Candidates)){$fallbackOrder+=[pscustomobject]@{Index=$fallbackIndex;Rank=[int]$candidate.Score;Item=$candidate};$fallbackIndex++}
    foreach($candidate in @($fallbackOrder|Sort-Object -Property @{Expression='Rank';Descending=$true},@{Expression='Index';Descending=$false}|ForEach-Object{$_.Item})) {
        $hit=Return-Candidate ([string]$candidate.Source) ([string]$candidate.Raw) ([int]$candidate.Score) ([string]$candidate.Detail) ([int]$sw.ElapsedMilliseconds)
        if($null -ne $hit){ Add-Member -InputObject $hit -NotePropertyName FallbackTasks -NotePropertyValue 1 -Force; Add-Member -InputObject $hit -NotePropertyName FallbackTransport -NotePropertyValue $fallbackLabel -Force; try{Add-Member -InputObject $hit -NotePropertyName TaskBytes -NotePropertyValue ([long]$fb.DomeniaBytesSent+[long]$fb.DomeniaBytesReceived) -Force}catch{}; $hit; return }
    }
    Add-Attempt ($fallbackLabel+" local SYSTEM") "VIDE" "" 0 ([int]$sw.ElapsedMilliseconds) ($fallbackLabel+" execute correctement, aucun utilisateur AD fiable dans les donnees locales.")
}
catch {
    if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw}
    $taskFallbackError = [string]$_.Exception.Message
    Add-Attempt "Fallbacks PsExec / tache" "KO" "" 0 0 $taskFallbackError
}


[pscustomobject]@{
    Computer=$computer
    SourceCompletedUtc=[datetime]::UtcNow.ToString('o')
    UserLogin=""
    Source=if($taskFallbackError){"Acces distant indisponible"}else{"Aucune preuve concluante"}
    Confidence=0
    VerifiedInAD=$false
    Details=if($taskFallbackError){$taskFallbackError}else{"Aucune preuve utilisateur fiable disponible apres le resolver rapide."}
    Attempts=@($attempts)
    Success=$false
    FallbackTasks=if($taskFallbackError){1}else{0}
    RemoteAccessFailed=[bool](-not [string]::IsNullOrWhiteSpace($taskFallbackError))
}
'@
        [void](Set-DomeniaControlText -Name "LblLinkProbeStatus" -Text "Rafraichissement distant de $computerNorm en arriere-plan...")
        Add-DomeniaUiLog -Area "Association" -Text ("Resolver user-machine lance pour {0} : cache conserve, confirmation distante en arriere-plan." -f $computerNorm)
        # D041/D044/D049: the result is checked by exact identity and by nature, and is attached to the Relations
        # subject captured here (CD-06: the RC1.10.7 handlers remain only when the Relations module is absent).
        $successHandler = "Complete-DomeniaComputerUserProbeUi"
        $errorHandler = "Fail-DomeniaComputerUserProbeUi"
        if ($null -ne (Get-Command -Name 'Complete-DomeniaRelationsComputerProbe' -CommandType Function -ErrorAction SilentlyContinue)) {
            $successHandler = "Complete-DomeniaRelationsComputerProbe"
            $errorHandler = "Fail-DomeniaRelationsComputerProbe"
        }
        $subject=if($null -ne $RelationsSubject){Get-DomeniaRelationsSubject}else{$script:SelectedObject}
        $targetDn=[string](Get-DomeniaMemberValue $subject 'DN');$targetGuid=[string](Get-DomeniaMemberValue $subject 'Guid')
        if(-not $targetGuid){$targetGuid=[string](Get-DomeniaMemberValue (Get-DomeniaMemberValue $subject 'Safety') 'Guid')}
        $callbackState=[pscustomobject]@{Computer=$computerNorm;ProbeId=$probeId;Progress=$probeProgress;Origin=$Origin;RelationsSubject=$RelationsSubject;ResultKind='ComputerLastUser';RequestKey='last-user-v1';RemoteStartedUtc=[datetime]::UtcNow.ToString('o');PublishHandler=$successHandler;PublishErrorHandler=$errorHandler}
        [void](Initialize-DomeniaRemoteStoreState -State $callbackState -Guid $targetGuid -DN $targetDn -Generation ([long]$script:GlobalSearchGeneration) -RequestId $probeId)
        $probeTaskId = Start-UiTask -Name "Dernier user $computerNorm" -OperationId "ComputerLastUser" -Code $code -Payload ([pscustomobject]@{
            Computer=$computerNorm
            Progress=$probeProgress
            ClassicTimeoutMs=($classicTimeout*1000)
            TaskFallbackTimeoutSeconds=$taskFallbackTimeout
            MethodTimeoutMs=$methodTimeout
            UseSecurityLog=[bool](Get-CfgValue "Remote" "UseSecurityLog" $false)
            UseRemoteRegistry=[bool](Get-CfgValue "Remote" "UseRemoteRegistry" $true)
            UseProfilesShare=[bool](Get-CfgValue "Remote" "UseProfilesShare" $false)
            AllowUnboundedFallbacks=[bool](Get-CfgValue "Remote" "AllowUnboundedFallbacks" $false)
        }) -CallbackState $callbackState -ReplaceKey "lastuser:$computerNorm" -DisableControls @("BtnRefreshMachineLink") -TimeoutSeconds $overallTimeout -StatusText "Rafraichissement utilisateur de $computerNorm en arriere-plan..." -SuccessHandler 'Complete-DomeniaLastUserCollected' -ErrorHandler 'Fail-DomeniaLastUserCollected'
        Write-AppLog ("Association demarree : {0}, probe={1}, tache={2}, budget={3}s, build={4}." -f $computerNorm,$probeId,$probeTaskId,$overallTimeout,$script:MasterBuild) 'INFO' 
    }
    catch {
        Fail-DomeniaComputerUserProbeUi -Message $_.Exception.Message -State ([pscustomobject]@{ Computer=$computerNorm; ProbeId=$probeId })
    }
}

function Start-ProbeForSelectedComputer {
    param([switch]$Force)
    if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Machine") { Set-Status "Sélectionnez une machine." "WARN"; return }
    $computer=Get-CurrentSelectedComputerName
    if (-not [string]::IsNullOrWhiteSpace($computer)) { Start-ComputerUserLinkProbe -Computer $computer -Force:$Force }
}

function Refresh-SelectedObject {
    # FI-21: 'Relire l objet depuis AD' drops only the cached reads of this object (by GUID, by DN without GUID)
    # and rereads its fiche. The list and the other cached objects are left as they are.
    if ($null -eq $script:SelectedObject) { return }
    $guid = ''
    try { $guid = [string]$script:SelectedObject.Safety.Guid } catch { Write-DomeniaSwallowed 'Core' 'Refresh-SelectedObject' $_ }
    [void](Clear-DomeniaVisitCacheForObject -Guid $guid -Dn ([string]$script:SelectedObject.DN))
    Open-AdObject -Dn $script:SelectedObject.DN -Type $script:SelectedObject.Type -Force
}

function Queue-LiveGlobalSearch {
    if (-not [bool](Get-CfgValue "Browser" "AllowLiveGlobalSearch" $false)) { return }
    if (-not [bool](Get-CfgValue "Browser" "LiveGlobalSearch" $false)) { return }
    try {
        if ($null -eq $script:LiveSearchTimer) {
            $timer=New-Object System.Windows.Threading.DispatcherTimer
            $timer.Add_Tick({
                $script:LiveSearchTimer.Stop()
                $text=($script:Ctrl["TxtGlobalSearch"].Text+"").Trim()
                $min=[int](Get-CfgValue "Browser" "GlobalSearchMinChars" 2)
                # Point 29: typing never starts a broad LDAP read ('*', a leading wildcard or a short text);
                # the explicit Rechercher still can, with its own limits.
                $typed=Test-DomeniaTypedSearchAllowed -Text $text -MinimumLength $min
                if ([bool]$typed.Allowed) { Invoke-GlobalSearch -SilentError }
                elseif ($text) { [void](Set-DomeniaControlText -Name 'LblSearchHint' -Text ([string]$typed.Reason)) }
            })
            $script:LiveSearchTimer=$timer
        }
        $script:LiveSearchTimer.Stop()
        $script:LiveSearchTimer.Interval=[System.TimeSpan]::FromMilliseconds([int](Get-CfgValue "Browser" "LiveSearchDelayMs" 900))
        $script:LiveSearchTimer.Start()
    } catch { Write-DomeniaSwallowed 'Core' 'Queue-LiveGlobalSearch' $_ }
}

function Load-AdCmdlets {
    try {
        $code=@'
$rows=New-Object Collections.ArrayList
$modules=New-Object Collections.ArrayList
if(Import-WAdModule $Context){
    $adCommand=Get-Command -Name "Get-ADObject" -CommandType Cmdlet -ErrorAction SilentlyContinue
    if($null -ne $adCommand -and -not [string]::IsNullOrWhiteSpace([string]$adCommand.ModuleName)){[void]$modules.Add([string]$adCommand.ModuleName)}
}
if(Get-Module -ListAvailable LAPS -ErrorAction SilentlyContinue){try{Import-Module LAPS -ErrorAction Stop;[void]$modules.Add("LAPS")}catch{}}
foreach($module in @($modules)){
    foreach($c in @(Get-Command -Module $module -CommandType Cmdlet,Function -ErrorAction SilentlyContinue | Sort-Object Name)){
        $names=@($c.Parameters.Keys | Sort-Object)
        $synopsis=""
        try { $synopsis=([string](Get-Help -Name $c.Name -ErrorAction SilentlyContinue).Synopsis).Trim() } catch {}
        if([string]::IsNullOrWhiteSpace($synopsis) -or $synopsis -match "^\s*$($c.Name)\s*$"){ $synopsis="Aide locale non installee ou synopsis indisponible." }
        [void]$rows.Add([pscustomobject]@{
            Name=[string]$c.Name
            Module=[string]$c.ModuleName
            CommandType=[string]$c.CommandType
            HasCredential=$(if($c.Parameters.ContainsKey("Credential")){"Oui"}else{"Non"})
            ParameterCount=[int]$names.Count
            Parameters=($names -join ", ")
            Synopsis=$synopsis
        })
    }
}
[pscustomobject]@{Loaded=($rows.Count -gt 0);Rows=@($rows);Modules=@($modules);Detail="$($rows.Count) commande(s) disponible(s) dans $(@($modules) -join ', ')"}
'@
        Start-UiTask -Name "Inventaire cmdlets" -OperationId "CmdletInventory" -Code $code -ReplaceKey "cmdlets" -DisableControls @("BtnLoadCmdlets") -TimeoutSeconds 45 -StatusText "Inventaire des modules ActiveDirectory et Windows LAPS..." -OnSuccess {
            param($result)
            $script:CmdletReferenceRows = @($result.Rows)
            $script:CurrentCmdletHelp = ""
            $script:CurrentCmdletSyntax = ""
            $script:Ctrl["TxtCmdletHelp"].Text = if($result.Loaded){"Sélectionnez une commande pour charger son aide détaillée."}else{"Aucune cmdlet ActiveDirectory ou LAPS nʼest disponible sur ce poste."}
            Filter-AdCmdletReference
            if ($result.Loaded) { Set-Status ([string]$result.Detail) } else { Set-Status ([string]$result.Detail) "WARN" }
        } -OnError { param($message) Set-Status "Cmdlets : $message" "ERROR" } | Out-Null
    } catch { Show-ErrorBox "Erreur cmdlets : $($_.Exception.Message)" }
}

function Assert-WriteAllowed {
    # C2: first guard, before receipts or the read-only box: nothing is ever written in demonstration.
    if ([bool]$script:DemoMode) { throw 'Ecritures desactivees en demonstration - aucune connexion AD. Aucune ecriture tentee.' }
    if(-not $script:ReceiptReady -or $script:ReceiptPending -gt 0){throw 'Ouvrez Operations : verification des recus non terminee ou action precedente a verifier.'}
    # P-CD-09: a read-only switch that cannot be read blocks the write (Get-DomeniaReadOnlyState, Safety.Model).
    $readOnly=Get-DomeniaReadOnlyState -Controls $script:Ctrl -Fallback ([bool]$script:ReadOnlyMode)
    if ([bool]$readOnly.Unreadable) {
        Write-DomeniaSwallowed 'Core' 'Assert-WriteAllowed' $readOnly.Error
        throw "Lʼétat du mode lecture seule nʼa pas pu être lu. Aucune écriture AD nʼa été tentée."
    }
    if ([bool]$readOnly.ReadOnly) { throw "Mode lecture seule actif. Aucune ecriture AD n a ete tentee." }
}

# =====================================================================
# DOMENIA MASTER LAST V1 - ecritures AD asynchrones et outils poste non bloquants
# =====================================================================



function Invoke-DomeniaPostWriteRefresh {
    param(
        [string]$Message,
        [switch]$RefreshObject,
        [switch]$RefreshBranch
    )
    try { $script:VisitCache.Clear() } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaPostWriteRefresh' $_ }
    if (-not [string]::IsNullOrWhiteSpace($Message)) {
        Write-AppLog $Message
        Set-Status $Message
    }
    if ($RefreshObject -and $null -ne $script:SelectedObject) {
        Open-AdObject -Dn ([string]$script:SelectedObject.DN) -Type ([string]$script:SelectedObject.Type) -Force
    }
    if ($RefreshBranch -and -not [string]::IsNullOrWhiteSpace([string]$script:SelectedBranchDn)) {
        Load-BranchObjects
    }
    Update-Dashboard
}



































function Get-DomeniaRemotePostconditionText {
    # D093 for remote actions: the delivery is not the effect. Without a re-read of the workstation the status
    # stays "A verifier" and the check to do is stated; the process return is never taken as proof.
    param([string]$OperationId,$Result)
    $post = Get-DomeniaWritePostcondition -OperationId $OperationId -Result $Result
    $script:LastWritePostcondition = $post
    if ($null -eq $post) { return '' }
    $text = ' - ' + [string]$post.Label + ' : ' + [string]$post.Proof
    try {
        $check = [string](Get-DomeniaPostconditionRule $OperationId).Check
        if ($check) { $text += ' Verification a faire : ' + $check }
    } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaRemotePostconditionText' $_ }
    return $text
}

function Complete-DomeniaComputerToolUi {
    param($Result,$State)
    $tool = [string]$State.Tool
    $computer = [string]$State.Computer
    $effective = $Result
    if (($Result -is [System.Array]) -and ($Result.Count -gt 0)) { $effective = $Result[-1] }
    $message = ""
    try { $message = [string]$effective.Message } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerToolUi' $_ }
    if ([string]::IsNullOrWhiteSpace($message)) { $message = "Demande envoyée à $computer." }
    $remoteOperation = ""
    if ($tool -eq "GPUpdate") { $remoteOperation = "ComputerGpUpdate" } elseif ($tool -eq "Redemarrage") { $remoteOperation = "ComputerRestart" }
    if ($remoteOperation) { $message += (Get-DomeniaRemotePostconditionText -OperationId $remoteOperation -Result $effective) }
    # SE-08: the restart panel closes once the request is accepted; its result stays in the status and the journal.
    if ($tool -eq "Redemarrage") { try { Close-DomeniaComputerRestartPanel -Computer $computer } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerToolUi' $_ } }
    if ($tool -eq "Ping") { Set-Status "Ping $computer : $message" }
    else { Set-Status $message; try { Add-DomeniaUiLog -Area 'Poste' -Text $message } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaComputerToolUi' $_ } }
}

function Fail-DomeniaComputerToolUi {
    param([string]$Message,$State)
    $tool = [string]$State.Tool
    $computer = [string]$State.Computer
    $label = switch ($tool) { 'GPUpdate' { 'Actualisation des stratégies' } 'Redemarrage' { 'Redémarrage' } '' { 'Outil du poste' } default { $tool } }
    $operation = if ([string]::IsNullOrWhiteSpace($computer)) { $label } else { "$label de $computer" }
    [void](Show-DomeniaOperationError -Operation $operation -ErrorRecordOrException ([string]$Message))
}

function Assert-DomeniaRemoteWriteAllowed {
    param([string]$Operation)
    if ([bool]$script:DemoMode) { throw "$Operation non disponible en demonstration - aucune connexion au poste. Aucune action tentee." }
    # P-CD-09: a read-only switch that cannot be read blocks the remote change (Get-DomeniaReadOnlyState, Safety.Model).
    $readOnly = Get-DomeniaReadOnlyState -Controls $script:Ctrl -Fallback ([bool]$script:ReadOnlyMode)
    if ([bool]$readOnly.Unreadable) {
        Write-DomeniaSwallowed 'Core' 'Assert-DomeniaRemoteWriteAllowed' $readOnly.Error
        throw "$Operation : lʼétat du mode lecture seule nʼa pas pu être lu. Aucune action nʼa été tentée sur le poste."
    }
    if ([bool]$readOnly.ReadOnly) { throw "$Operation est une modification distante et reste bloquee tant que le mode lecture seule est actif." }
    if((Get-DomeniaSelectionCachePolicy).Offline){throw 'Hors ligne : relisez Active Directory avant toute modification.'}
}

# DOMENIA_COMPUTER_TOOL_CALLBACKS_NAMED


function Get-DomeniaRimotteWorkerCode {
    return @'
$computer=([string]$Payload.Computer).Trim()
$command=([string]$Payload.Command).Trim()
$arguments=[string]$Payload.Arguments
$mode=[string]$Payload.Mode
$runUser=([string]$Payload.RunUser).Trim()
$elevated=[bool]$Payload.Elevated
if([string]::IsNullOrWhiteSpace($computer)){throw "Poste cible vide : aucune tâche créée."}
if([string]::IsNullOrWhiteSpace($command)){throw "Programme à lancer vide : aucune tâche créée."}
if($mode -notin @('System','Interactive')){throw "Mode dʼexécution inconnu : aucune tâche créée."}
$id=[guid]::NewGuid().ToString('N')
$task='\DOMENIA_Execution_'+$id.Substring(0,12)
$start=(Get-Date).AddSeconds(-30).ToString('yyyy-MM-ddTHH:mm:ss')
$end=(Get-Date).AddMinutes(15).ToString('yyyy-MM-ddTHH:mm:ss')
Assert-WRemoteArtifactPermission $Context $computer
$cmdX=[Security.SecurityElement]::Escape($command)
$argX=[Security.SecurityElement]::Escape($arguments)
$argBlock=$(if([string]::IsNullOrWhiteSpace($arguments)){''}else{"      <Arguments>$argX</Arguments>`r`n"})
$runLevel=$(if($elevated){'HighestAvailable'}else{'LeastPrivilege'})
$logonType='ServiceAccount';$taskUser='S-1-5-18';$createExtra=@();$interactive=$false
if($mode -eq 'Interactive'){
    if([string]::IsNullOrWhiteSpace($runUser)){throw "Session de lʼutilisateur : compte vide, aucune tâche créée."}
    $taskUser=$runUser;$logonType='InteractiveToken';$interactive=$true
}
$userX=[Security.SecurityElement]::Escape($taskUser)
$logonBlock=$(if($logonType-eq'ServiceAccount'){''}else{"      <LogonType>$logonType</LogonType>`r`n"})
$xml=@"
<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo><Description>DOMENIA - exécution unique, supprimée après lancement</Description><Author>DOMENIA</Author></RegistrationInfo>
  <Triggers/>
  <Principals><Principal id="Author"><UserId>$userX</UserId>
$logonBlock      <RunLevel>$runLevel</RunLevel></Principal></Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>
    <AllowHardTerminate>true</AllowHardTerminate>
    <StartWhenAvailable>true</StartWhenAvailable>
    <RunOnlyIfNetworkAvailable>false</RunOnlyIfNetworkAvailable>
    <AllowStartOnDemand>true</AllowStartOnDemand>
    <Enabled>true</Enabled><Hidden>true</Hidden>
    <ExecutionTimeLimit>PT2H</ExecutionTimeLimit><Priority>5</Priority>

  </Settings>
  <Actions Context="Author"><Exec><Command>$cmdX</Command>
$argBlock    </Exec></Actions>
</Task>
"@
$xmlPath=Join-Path $env:TEMP ('domenia_execution_'+$id+'.xml')
$created=$false;$watch=[Diagnostics.Stopwatch]::StartNew()
try{
    [IO.File]::WriteAllText($xmlPath,$xml,[Text.Encoding]::Unicode)
    $createArgs=@('/create','/tn',$task,'/xml',$xmlPath,'/f')+$createExtra
    $DomeniaWriteDispatched=$true
    $r=Invoke-WSchtasksRemote $Context $computer $createArgs 35
    if($r.ExitCode-ne0){throw "creation KO code $($r.ExitCode), $(Get-WSchtasksHint $r.ExitCode) : $($r.Output)"};$created=$true
    $runArgs=@('/run','/tn',$task);if($interactive){$runArgs+='/i'}
    $r2=Invoke-WSchtasksRemote $Context $computer $runArgs 35
    if($r2.ExitCode-ne0){throw "lancement KO code $($r2.ExitCode), $(Get-WSchtasksHint $r2.ExitCode) : $($r2.Output)"}
    Start-Sleep -Milliseconds 900
    $q=Invoke-WSchtasksRemote $Context $computer @('/query','/tn',$task,'/v','/fo','LIST') 20
    $watch.Stop()
    $detail='Tache declenchee.';if ((($q.ExitCode -eq 0)) -and ((-not [string]::IsNullOrWhiteSpace([string]$q.Output)))) {$detail=(([string]$q.Output)-replace '[\r\n]+',' ');if($detail.Length-gt500){$detail=$detail.Substring(0,500)}}
    [pscustomobject]@{Computer=$computer;Command=$command;Arguments=$arguments;Mode=$mode;RunUser=$taskUser;TaskName=$task;Message=("Exécution demandée sur "+$computer+" par une tâche unique, supprimée après lancement. Le lancement du programme nʼest pas vérifié.");Detail=$detail;DurationMs=[long]$watch.ElapsedMilliseconds;Transport='ScheduledTask';Success=$true;Delivered=$true}
}
catch{throw ("Exécution impossible sur "+$computer+" : "+$_.Exception.Message)}
finally{
    if($created){try{[void](Invoke-WSchtasksRemote $Context $computer @('/delete','/tn',$task,'/f') 15)}catch{}}
    try{Remove-Item -LiteralPath $xmlPath -Force -ErrorAction SilentlyContinue}catch{}
}
'@
}

function Complete-DomeniaRimotteUi {
    param($Result,$State)
    $effective=$Result;if($Result-is[System.Array]-and$Result.Count-gt0){$effective=$Result[-1]}
    $msg=[string]$effective.Message
    if([string]::IsNullOrWhiteSpace($msg)){$msg="Exécution demandée."}
    $msg+=(Get-DomeniaRemotePostconditionText -OperationId "RimotteRun" -Result $effective)
    Set-Status $msg
    Add-DomeniaUiLog -Area "Poste" -Text ($msg+" "+[string]$effective.Detail)
    # UI-26: the panel closes once the task is accepted; the run of the program itself is not verified.
    try{Close-DomeniaRunProgramPanel -Computer ([string]$State.Computer)}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaRimotteUi' $_}
    try{Register-DomeniaOperationSample -Operation "RimotteRun" -Mode "ScheduledTask" -ItemCount 1 -DurationMs ([long]$effective.DurationMs) -BytesEstimated 6000 -RemoteAttempts 1 -FallbackTasks 1 -SuccessCount 1}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaRimotteUi' $_}
}

function Fail-DomeniaRimotteUi {
    param([string]$Message,$State)
    try{Register-DomeniaOperationSample -Operation "RimotteRun" -Mode "ScheduledTask" -ItemCount 1 -DurationMs 0 -BytesEstimated 3000 -RemoteAttempts 1 -FallbackTasks 1 -FailureCount 1}catch{Write-DomeniaSwallowed 'Core' 'Fail-DomeniaRimotteUi' $_}
    [void](Show-DomeniaOperationError -Operation ("Exécution sur "+[string]$State.Computer) -ErrorRecordOrException ([string]$Message))
}

function Start-DomeniaRimotteRun {
    param($Settings)
    Assert-WriteAllowed
    $computer=Assert-DomeniaComputerTarget -Computer ([string]$Settings.Computer)
    $correlation=[guid]::NewGuid().ToString('N')
    $payload=[pscustomobject]@{Computer=$computer;Command=[string]$Settings.Command;Arguments=[string]$Settings.Arguments;Mode=[string]$Settings.Mode;RunUser=[string]$Settings.RunUser;Elevated=[bool]$Settings.Elevated;Target=$computer;DN=$computer;CorrelationId=$correlation;SingleRequest=$true}
    Start-UiTask -Name ("Exécution sur "+$computer) -OperationId "RimotteRun" -Code (Get-DomeniaRimotteWorkerCode) -Payload $payload -CallbackState ([pscustomobject]@{Computer=$computer}) -ReplaceKey ("execution:"+$computer) -DisableControls @("BtnCompRimotte","BtnCompRunStart") -TimeoutSeconds 95 -NonCancellable -StatusText ("Exécution sur "+$computer+" : création de la tâche unique...") -SuccessHandler "Complete-DomeniaRimotteUi" -ErrorHandler "Fail-DomeniaRimotteUi" -IsWrite -CorrelationId $correlation | Out-Null
}

function Get-DomeniaMachineOperationCredential {
    # Same order as the worker context: account typed for workstations, remote admin account, then the account used
    # to log into Domenia. $null means the Windows session (login without password).
    if ($null -ne $script:MachineCredential) { return $script:MachineCredential }
    if ($null -ne $script:RemoteAdminCredential) { return $script:RemoteAdminCredential }
    if ([bool]$script:Conn.UseCredential -and $null -ne $script:Conn.Credential) { return $script:Conn.Credential }
    return $null
}

function Get-DomeniaMachineOperationAccountText {
    # UX-15: same order and words as the « Compte poste » pill (Get-DomeniaMachineAccountInUse), temporary accounts
    # accepted after a refusal included. Names only, never a secret.
    param([string]$Target = '')
    $label = Get-DomeniaMachineAccountInUse -Target $Target
    return ('Opérations poste : ' + [string]$label.Long + '.')
}

function Get-DomeniaNetUseSource {
    # Shared with the diagnostic worker (same text): opens an SMB connection under an explicit account.
    return 'using System; using System.Runtime.InteropServices; namespace Domenia { public static class NetUse { [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Unicode)] private class NETRESOURCE { public int dwScope; public int dwType; public int dwDisplayType; public int dwUsage; public string lpLocalName; public string lpRemoteName; public string lpComment; public string lpProvider; } [DllImport("mpr.dll", CharSet=CharSet.Unicode)] private static extern int WNetAddConnection2(NETRESOURCE resource, string password, string user, int flags); [DllImport("mpr.dll", CharSet=CharSet.Unicode)] private static extern int WNetCancelConnection2(string name, int flags, bool force); public static int Connect(string remote, string user, string password) { NETRESOURCE r = new NETRESOURCE(); r.lpRemoteName = remote; return WNetAddConnection2(r, password, user, 0); } public static int Disconnect(string remote) { return WNetCancelConnection2(remote, 0, true); } } }'
}

function Start-DomeniaAdminShareOpen {
    # Field report 2026-10-07: Explorer and the MMC consoles run under the Windows session, which has no rights on the
    # workstations. The share is first opened with the account used for workstation operations, so Windows does not
    # ask for credentials. The 445 check and the SMB connection run in a worker (no wait on the Dispatcher, D014);
    # the password goes to the Windows API only, never on a command line. The tool opens when the share answers.
    param([Parameter(Mandatory=$true)][string]$Computer,[string]$Share='C$',[Parameter(Mandatory=$true)][string]$Tool)
    if ($null -eq (Get-DomeniaMachineOperationCredential)) { Complete-DomeniaAdminShareOpen -Result ([pscustomobject]@{ Connected=$false; Account='' }) -State ([pscustomobject]@{ Computer=$Computer; Share=$Share; Tool=$Tool }); return }
    $code=@'
$computer=[string]$Payload.Computer;$share=[string]$Payload.Share
$cred=Get-WMachineCredential $Context
if($null -eq $cred){return [pscustomobject]@{Connected=$false;Account=''}}
$client=New-Object Net.Sockets.TcpClient
try{$wait=$client.BeginConnect($computer,445,$null,$null);if(-not $wait.AsyncWaitHandle.WaitOne(1500) -or -not $client.Connected){throw 'le partage du poste ne repond pas (port 445).'}}finally{$client.Close()}
if(-not ('Domenia.NetUse' -as [type])){try{Add-Type -TypeDefinition ([string]$Payload.NetUseSource)}catch{if(-not ('Domenia.NetUse' -as [type])){throw}}}
$remote='\\'+$computer+'\'+$share
$net=$cred.GetNetworkCredential();$user=if($net.Domain){$net.Domain+'\'+$net.UserName}else{$net.UserName}
if(-not $net.Domain -and $user -notmatch '@' -and [string]$Payload.NetbiosDomain){$user=[string]$Payload.NetbiosDomain+'\'+$user}
# Point 41: the SMB logon holds the account lease; the native code travels with the refusal, which is shared.
Set-WCredentialAttemptIdentity -Context $Context -Credential $cred -Channel Remote -Target $computer
$shareLease=Enter-WCredentialAttempt -Context $Context -Channel Remote
try{
$rc=[Domenia.NetUse]::Connect($remote,$user,$net.Password)
if($rc -eq 1219){foreach($existing in @(('\\'+$computer+'\IPC$'),$remote)){[void][Domenia.NetUse]::Disconnect($existing)};$rc=[Domenia.NetUse]::Connect($remote,$user,$net.Password)}
}finally{Exit-WCredentialAttempt $shareLease}
if($rc -ne 0){$failure=[ComponentModel.Win32Exception]::new([int]$rc,('acces a '+$remote+' refuse pour '+$user+' : '+(New-Object ComponentModel.Win32Exception $rc).Message));[void](Register-WCredentialFailure -Context $Context -ErrorValue $failure -Channel Remote);throw $failure}
[pscustomobject]@{Connected=$true;Account=$user}
'@
    Start-UiTask -Name ("Partage $Share de $Computer") -OperationId "ComputerAdminShare" -Code $code -Payload ([pscustomobject]@{ Computer=$Computer; Share=$Share; NetUseSource=(Get-DomeniaNetUseSource); NetbiosDomain=[string]$script:Conn.Netbios }) -CallbackState ([pscustomobject]@{ Computer=$Computer; Share=$Share; Tool=$Tool }) -ReplaceKey ("share:" + $Computer + ":" + $Tool) -TimeoutSeconds 30 -StatusText ("Ouverture du partage $Share de $Computer avec le compte des operations poste...") -SuccessHandler "Complete-DomeniaAdminShareOpen" -ErrorHandler "Fail-DomeniaAdminShareOpen" | Out-Null
}
function Complete-DomeniaAdminShareOpen {
    param($Result,$State)
    $computer=[string]$State.Computer;$account='';try{$account=[string]$Result.Account}catch{Write-DomeniaSwallowed 'Core' 'Complete-DomeniaAdminShareOpen' $_}
    Start-DomeniaComputerToolProcess -Tool ([string]$State.Tool) -Computer $computer
    if ($account) {
        $what = if ([string]$State.Share -eq 'C$') { "Disque C (C$)" } else { "Partage " + [string]$State.Share }
        Set-Status ($what + " de $computer ouvert avec $account.")
    }
}
function Fail-DomeniaAdminShareOpen {
    param([string]$Message,$State)
    $computer=[string]$State.Computer;$tool=[string]$State.Tool
    if ($tool -eq 'C') { [void](Show-DomeniaOperationError -Operation ("Ouvrir le disque C de $computer") -ErrorRecordOrException ([string]$Message)); return }
    # Consoles still open, under the Windows session, as before.
    Set-Status ("Console ouverte avec la session Windows : " + $Message) "WARN"
    Start-DomeniaComputerToolProcess -Tool $tool -Computer $computer
}
function Start-DomeniaComputerToolProcess {
    param([string]$Tool,[string]$Computer)
    switch ($Tool) {
        "C" { Start-Process -FilePath "explorer.exe" -ArgumentList @("\\$Computer\C$") }
        "Manage" { Start-Process -FilePath "compmgmt.msc" -ArgumentList @("/computer=$Computer") }
        "Events" { Start-Process -FilePath "eventvwr.exe" -ArgumentList @("/computer:$Computer") }
        # UX-38 (X04): services.msc ignores /computer; Gestion de l'ordinateur opens on the workstation, Services included.
        "Services" { Start-Process -FilePath "compmgmt.msc" -ArgumentList @("/computer=$Computer") }
    }
}
function Invoke-ComputerTool {
    # Tools of the selected workstation. Reads and Windows tools leave on the click; GPUpdate and the restart are remote
    # writes: the click prepares them in the page (in-page confirmation, sessions read first for the restart) and only
    # the confirmed request reaches its pinned worker, once (-Confirmed, -Restart). CD-11: no scheduled-task fallback.
    param([string]$Tool,$Restart=$null,[switch]$Confirmed)
    try {
        $name=Assert-DomeniaComputerTarget -Computer (Get-CurrentSelectedComputerName)
        # D002: the demonstration directory has no real workstation; external tools are never started.
        if([bool]$script:DemoMode -and $Tool -in @('RDP','C','Manage','Events','Services','PSRemote')){throw "Outil poste $Tool non disponible en demonstration - aucune connexion au poste."}
        switch($Tool){
            "Ping" {
                $guid=[string](Get-DomeniaMemberValue (Get-DomeniaMemberValue $script:SelectedObject 'Safety') 'Guid')
                Start-DomeniaCommittedPresence -Computer $name -Guid $guid -DN ([string]$script:SelectedObject.DN) -DisplayDN ([string]$script:SelectedObject.DN) -DisplayKind 'Machine' -Explicit
            }
            "RDP" { Start-Process -FilePath "mstsc.exe" -ArgumentList @("/v:$name") }
            "C" { Start-DomeniaAdminShareOpen -Computer $name -Share 'C$' -Tool 'C' }
            { $_ -in @("Manage","Events","Services") } { Start-DomeniaAdminShareOpen -Computer $name -Share 'IPC$' -Tool $Tool }
            "PSRemote" {
                # UX-42: the account of the workstation operations is named (-Credential), never its password; the
                # message stays in the page.
                $account=''
                $credential=Get-DomeniaMachineOperationCredential
                if($null -ne $credential){$account=[string]$credential.UserName}
                $command=Get-DomeniaPsRemoteCommand -Computer $name -UserName $account
                Set-ClipboardSafe ([string]$command.Text)
                $shown=$false
                try{$shown=[bool](Show-DomeniaBanner -Kind Info -Message ([string]$command.Status) -Key 'psremote-copied')}catch{$shown=$false}
                Set-Status ([string]$command.Status)
                if(-not $shown){Add-DomeniaUiLog -Area 'Poste' -Text ([string]$command.Status)}
            }
            "GpUpdate" {
                Assert-DomeniaRemoteWriteAllowed -Operation "Actualisation des stratégies"
                Assert-WriteAllowed
                # The request travels by WinRM only: a configuration that forbids WinRM refuses it before any confirmation.
                if(-not [bool](Get-CfgValue 'Remote' 'UseWinRM' $true)){throw 'Actualisation des stratégies indisponible : WinRM est désactivé par la configuration (Remote.UseWinRM). Rien nʼest envoyé au poste.'}
                if(-not $Confirmed){Request-DomeniaComputerToolConfirmation -Tool 'GpUpdate' -Computer $name;return}
                $code=@'
$computer=[string]$Payload.Computer
# The configuration may forbid WinRM (Remote.UseWinRM): no connection is attempted and the receipt says NotSent.
if(-not [bool]$Context.UseWinRM){throw 'Non envoyé : WinRM est désactivé par la configuration (Remote.UseWinRM).'}
$cred=Get-WMachineCredential $Context;$session=$null
# CD-11: one transport and no fallback. A refused connection sends nothing (receipt NotSent); once the session is open
# the request is dispatched and never replayed. Point 41: the WinRM logon holds the lease of the account it sends.
Set-WCredentialAttemptIdentity -Context $Context -Credential $cred -Channel Remote -Target $computer
$lease=Enter-WCredentialAttempt -Context $Context -Channel Remote
try{
    $p=@{ComputerName=$computer;ErrorAction='Stop'};if($cred){$p.Credential=$cred}
    try{$session=New-PSSession @p}catch{if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};throw ("Non envoyé : le poste nʼaccepte pas la commande à distance (WinRM). "+$_.Exception.Message)}
}finally{Exit-WCredentialAttempt -Lease $lease}
try{
    $DomeniaWriteDispatched=$true
    $o=Invoke-Command -Session $session -ScriptBlock {& "$env:SystemRoot\System32\gpupdate.exe" /force /wait:0 2>&1 | Out-String} -ErrorAction Stop
    $text=((@($o) -join ' ') -replace '\s+',' ').Trim()
    [pscustomobject]@{Message=("Actualisation des stratégies lancée sur "+$computer+". "+$text).Trim();Transport='WinRM';Delivered=$true}
}finally{if($null -ne $session){Remove-PSSession -Session $session -ErrorAction SilentlyContinue}}
'@
                $correlation = [guid]::NewGuid().ToString("N")
                $payload = [pscustomobject]@{Computer=$name;Target=$name;DN=$name;CorrelationId=$correlation;SingleRequest=$true}
                Start-UiTask -Name "Actualisation des stratégies de $name" -OperationId "ComputerGpUpdate" -Code $code -Payload $payload -CallbackState ([pscustomobject]@{ Tool="GPUpdate"; Computer=$name }) -ReplaceKey "gpupdate:$name" -DisableControls @("BtnCompGpUpdate") -TimeoutSeconds 35 -StatusText "Actualisation des stratégies sur $name..." -SuccessHandler "Complete-DomeniaComputerToolUi" -ErrorHandler "Fail-DomeniaComputerToolUi" -IsWrite -CorrelationId $correlation | Out-Null
            }
            "Restart" {
                Assert-DomeniaRemoteWriteAllowed -Operation "Redémarrage du poste"
                Assert-WriteAllowed
                # SE-08: the click opens the restart panel of the page, which reads the open sessions first; only the
                # plan confirmed there comes back here (-Restart).
                if($null -eq $Restart){Request-DomeniaComputerRestart -Computer $name;return}
                if(([string]$Restart.Computer) -ine $name){throw 'Le poste sélectionné a changé : redémarrage non envoyé.'}
                $code=@'
$computer=[string]$Payload.Computer;$mode=[string]$Payload.Mode;$delay=[int]$Payload.DelaySeconds;$message=[string]$Payload.Message
if($mode -notin @('Delayed','Now')){throw 'Mode de redémarrage inconnu : aucune demande envoyée.'}
if(($mode -eq 'Delayed') -and (($delay -lt 60) -or ($delay -gt 3600) -or ($message.Length -gt 400) -or ($message.IndexOf([char]34) -ge 0))){throw 'Délai ou message de redémarrage refusé : aucune demande envoyée.'}
# The delayed restart travels by WinRM only: a configuration that forbids WinRM (Remote.UseWinRM) sends nothing.
if(($mode -eq 'Delayed') -and (-not [bool]$Context.UseWinRM)){throw 'Non envoyé : le redémarrage différé passe par WinRM, désactivé par la configuration (Remote.UseWinRM).'}
$cred=Get-WMachineCredential $Context;$session=$null;$cim=$null
$notSent="Non envoyé : le poste nʼaccepte pas la commande à distance. "
# CD-11: one transport per choice and no fallback. Delayed: shutdown.exe through WinRM, so that the user sees the
# message. Now: Restart-Computer -Force after a CIM session proved the workstation answers. A refused connection
# sends nothing (receipt NotSent); a known refusal of shutdown.exe restarts nothing; nothing is ever replayed.
# Point 41: every logon with the account holds its lease, attributed to the account this transport sends.
Set-WCredentialAttemptIdentity -Context $Context -Credential $cred -Channel Remote -Target $computer
$lease=Enter-WCredentialAttempt -Context $Context -Channel Remote
try{
    if($mode -eq 'Delayed'){
        $p=@{ComputerName=$computer;ErrorAction='Stop'};if($cred){$p.Credential=$cred}
        try{$session=New-PSSession @p}catch{if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};throw ($notSent+"(WinRM) "+$_.Exception.Message)}
    }else{
        try{$cim=New-WDomeniaCimSession $Context $computer $cred 12}catch{if(Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote){throw};throw ($notSent+$_.Exception.Message)}
    }
}finally{Exit-WCredentialAttempt -Lease $lease;Remove-WDomeniaCimSession $cim}
try{
    if($mode -eq 'Delayed'){
        $DomeniaWriteDispatched=$true
        $r=Invoke-Command -Session $session -ScriptBlock {param($seconds,$text) $out=& "$env:SystemRoot\System32\shutdown.exe" /r /t $seconds /d p:4:1 /c $text 2>&1 | Out-String;[pscustomobject]@{ExitCode=[int]$LASTEXITCODE;Output=[string]$out}} -ArgumentList $delay,$message -ErrorAction Stop
        $exit=[int]$r.ExitCode
        if($exit -ne 0){
            # shutdown.exe refused the request: nothing is scheduled by Domenia (1190: a shutdown is already pending).
            $DomeniaWriteDispatched=$false
            $why=if($exit -eq 1190){'un arrêt ou un redémarrage est déjà programmé sur ce poste'}elseif($exit -eq 5){'accès refusé'}else{(([string]$r.Output) -replace '\s+',' ').Trim()}
            throw ("Redémarrage refusé par le poste (code "+$exit+") : "+$why+". Rien nʼest programmé par Domenia.")
        }
        [pscustomobject]@{Message=("Redémarrage programmé sur "+$computer+" dans "+[int][Math]::Ceiling($delay/60.0)+" min, avec message à lʼutilisateur.");Mode='Delayed';DelaySeconds=$delay;Transport='WinRM';Delivered=$true}
    }else{
        $p=@{ComputerName=$computer;Force=$true;ErrorAction='Stop'};if($cred){$p.Credential=$cred}
        # Point 41: Restart-Computer logs on again with the account: it holds the lease too, and a refusal is shared.
        $restartLease=Enter-WCredentialAttempt -Context $Context -Channel Remote
        try{$DomeniaWriteDispatched=$true;Restart-Computer @p}catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Remote);throw}finally{Exit-WCredentialAttempt -Lease $restartLease}
        [pscustomobject]@{Message=("Redémarrage immédiat demandé à "+$computer+".");Mode='Now';DelaySeconds=0;Transport='Classic';Delivered=$true}
    }
}finally{if($null -ne $session){Remove-PSSession -Session $session -ErrorAction SilentlyContinue}}
'@
                $correlation = [guid]::NewGuid().ToString("N")
                $payload = [pscustomobject]@{Computer=$name;Target=$name;DN=$name;Mode=[string]$Restart.Mode;DelaySeconds=[int]$Restart.DelaySeconds;Message=[string]$Restart.Message;CorrelationId=$correlation;SingleRequest=$true}
                Start-UiTask -Name "Redémarrage de $name" -OperationId "ComputerRestart" -Code $code -Payload $payload -CallbackState ([pscustomobject]@{ Tool="Redemarrage"; Computer=$name; Mode=[string]$Restart.Mode }) -ReplaceKey "restart:$name" -DisableControls @("BtnCompRestart","BtnCompRestartSend") -TimeoutSeconds 45 -StatusText "Redémarrage de $name : envoi de la demande..." -SuccessHandler "Complete-DomeniaComputerToolUi" -ErrorHandler "Fail-DomeniaComputerToolUi" -IsWrite -CorrelationId $correlation | Out-Null
            }
        }
    } catch {
        $failure = $_
        $label = switch ($Tool) { 'Ping' { 'Test de réponse' } 'RDP' { 'Bureau à distance' } 'C' { 'Ouvrir le disque C' } 'Manage' { 'Gestion de lʼordinateur' } 'Events' { 'Observateur dʼévénements' } 'Services' { 'Console des services' } 'PSRemote' { 'Commande PowerShell' } 'GpUpdate' { 'Actualisation des stratégies' } 'Restart' { 'Redémarrage du poste' } default { 'Outil du poste' } }
        [void](Show-DomeniaOperationError -Operation $label -ErrorRecordOrException $failure)
    }
}

# =====================================================================
# Domenia 1.0 - diagnostic login detaille, audit local,
# integrite runtime et maintenance des liens user-machine.
# =====================================================================

$script:DataDir = ""
$script:AuditPath = ""
$script:LoginAuthStarted = $null
$script:AuthCleanupSessions = @{}
$script:AuthCleanupTimer = $null





function ConvertTo-DomeniaLogFileLines {
    # FI-09: one record never spans raw lines. CR, LF and TAB of the message are escaped (\r, \n, \t); .NET and
    # PowerShell stack frames go to continuation lines prefixed with "|" under the same timestamp, so a directory
    # value holding a line break can never forge a Domenia.log record.
    param([datetime]$Time,[string]$Level,[string]$AdIdentity='',[string]$WinIdentity='',[AllowEmptyString()][string]$Text='')
    $stamp = $Time.ToString('yyyy-MM-dd HH:mm:ss.fff')
    $escape = { param([string]$Value) return ([string]$Value).Replace("`r",'\r').Replace("`n",'\n').Replace("`t",'\t') }
    $message = New-Object 'System.Collections.Generic.List[string]'
    $stack = New-Object 'System.Collections.Generic.List[string]'
    foreach ($part in @(([string]$Text) -split "\r\n|\n|\r")) {
        $frame = (($message.Count -gt 0) -and (($part -match '^\s*(at|à)\s+\S') -or ($part -match '^\s*--- ')))
        if (($stack.Count -gt 0) -or $frame) { if ($part.Trim()) { $stack.Add($part.Trim()) } }
        else { $message.Add($part) }
    }
    $lines = New-Object 'System.Collections.Generic.List[string]'
    $lines.Add(("{0}`t{1}`tAD={2}`tWIN={3}`t{4}" -f $stamp,(& $escape $Level),(& $escape $AdIdentity),(& $escape $WinIdentity),(& $escape ([string]::Join("`n",$message.ToArray())))))
    foreach ($item in $stack) { $lines.Add(("{0}`t{1}`t| {2}" -f $stamp,(& $escape $Level),(& $escape $item))) }
    return $lines.ToArray()
}

function Get-DomeniaAppLogFallbackPaths {
    # FI-10: same fallback chain as the connection trace when Domenia.log cannot be written: LOCALAPPDATA, then TEMP.
    $paths = New-Object 'System.Collections.Generic.List[string]'
    if (-not [string]::IsNullOrWhiteSpace([string]$env:LOCALAPPDATA)) { $paths.Add((Join-Path (Join-Path ([string]$env:LOCALAPPDATA) 'DOMENIA\Logs') 'Domenia.log')) }
    try { $paths.Add((Join-Path (Join-Path ([IO.Path]::GetTempPath()) 'DOMENIA\Logs') 'Domenia.log')) } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaAppLogFallbackPaths' $_ }
    return $paths.ToArray()
}

function Write-DomeniaAppLogFile {
    # PF-09: Domenia.log is written from an in-memory queue, flushed every 500 ms on the Dispatcher idle priority
    # and at closing, instead of a data-store check, a size probe and a file append for every line.
    param([AllowEmptyString()][string]$Text,[string]$Level='INFO',[datetime]$Time=(Get-Date),[ValidateSet('AppLog','Status')][string]$Source='AppLog')
    # FI-08: a caller that gives the same sentence to Set-Status and to Write-AppLog gets one Domenia.log line.
    $last = $script:AppLogLastLine
    if (($null -ne $last) -and ([string]$last.Source -ne $Source) -and ([string]$last.Level -eq $Level) -and ([string]$last.Text -ceq [string]$Text) -and ([Math]::Abs(($Time - [datetime]$last.Time).TotalSeconds) -lt 2)) {
        $script:AppLogLastLine = $null
        return
    }
    $script:AppLogLastLine = [pscustomobject]@{ Source=$Source; Level=$Level; Text=[string]$Text; Time=$Time }
    $adIdentity = ''; try { $adIdentity = [string]$script:Conn.BindUser } catch { Write-DomeniaSwallowed 'Core' 'Write-DomeniaAppLogFile' $_ }
    $winIdentity = ''; try { $winIdentity = [string]$script:ProcessIdentity } catch { Write-DomeniaSwallowed 'Core' 'Write-DomeniaAppLogFile' $_ }
    if ($null -eq $script:AppLogQueue) { $script:AppLogQueue = New-Object 'System.Collections.Generic.List[string]' }
    foreach ($line in @(ConvertTo-DomeniaLogFileLines -Time $Time -Level $Level -AdIdentity $adIdentity -WinIdentity $winIdentity -Text $Text)) { $script:AppLogQueue.Add([string]$line) }
    # Bounded memory while every target refuses the write: the oldest queued lines go first, and are counted.
    if ($script:AppLogQueue.Count -gt 5000) {
        $drop = $script:AppLogQueue.Count - 5000
        $script:AppLogQueue.RemoveRange(0,$drop)
        $script:AppLogDropped = [int]$script:AppLogDropped + $drop
    }
    if (-not (Start-DomeniaAppLogFlushTimer)) { Flush-DomeniaAppLog }
}

function Start-DomeniaAppLogFlushTimer {
    # The queue is used only on the Dispatcher of the main window; before it (login, startup) and after closing
    # every line is written at once, as before.
    if ($null -eq $script:Window) { return $false }
    $sameWindow = [object]::ReferenceEquals($script:AppLogFlushWindow,$script:Window)
    if ($sameWindow -and [bool]$script:AppLogQueueClosed) { return $false }
    # PF-06: the flush timer is armed by a queued line and stops once the queue is written: nothing ticks at rest.
    if ($sameWindow -and $null -ne $script:AppLogFlushTimer) {
        try { if (-not [bool]$script:AppLogFlushTimer.IsEnabled) { $script:AppLogFlushTimer.Start() } } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaAppLogFlushTimer' $_ }
        return $true
    }
    try { if (-not $script:Window.Dispatcher.CheckAccess()) { return $false } } catch { return $false }
    try { if ($null -ne $script:AppLogFlushTimer) { $script:AppLogFlushTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaAppLogFlushTimer' $_ }
    # FI-05: protected timer of the engine heartbeat, also while the window is minimized.
    $timer = New-DomeniaTimer -Owner 'Timer:AppLog' -IntervalMs 500 -RunWhenHidden -Tick {
        param($sender,$eventArgs)
        try { Flush-DomeniaAppLog } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaAppLogFlushTimer' $_ }
        if ($null -eq $script:AppLogQueue -or $script:AppLogQueue.Count -eq 0) { try { $sender.Stop() } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaAppLogFlushTimer' $_ } }
    }
    $script:AppLogFlushTimer = $timer
    $script:AppLogFlushWindow = $script:Window
    $script:AppLogQueueClosed = $false
    try { $script:Window.Add_Closed({ try { Stop-DomeniaAppLogQueue } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaAppLogFlushTimer' $_ } }) } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaAppLogFlushTimer' $_ }
    $timer.Start()
    return $true
}

function Stop-DomeniaAppLogQueue {
    # Closing: stop the timer, write what is queued, and write every later line at once.
    $script:AppLogQueueClosed = $true
    try { if ($null -ne $script:AppLogFlushTimer) { $script:AppLogFlushTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Stop-DomeniaAppLogQueue' $_ }
    $script:AppLogFlushTimer = $null
    Flush-DomeniaAppLog -Force
}

function Invoke-DomeniaAppLogRotation {
    # Size check at the first write of a file then every 200 written lines (PF-09), same 5 MB limit and single .1
    # generation as before, for Domenia.log and for its fallback journal alike.
    param([string]$Path,[int]$Written)
    if ($null -eq $script:AppLogRotationCounters) { $script:AppLogRotationCounters = @{} }
    $key = ([string]$Path).ToUpperInvariant()
    if ($script:AppLogRotationCounters.ContainsKey($key)) {
        $count = [int]$script:AppLogRotationCounters[$key] + $Written
        if ($count -lt 200) { $script:AppLogRotationCounters[$key] = $count; return }
    }
    $script:AppLogRotationCounters[$key] = 0
    $file = [IO.FileInfo]::new($Path)
    if ($file.Exists -and $file.Length -gt 5242880) {
        $old = $Path + '.1'
        if ([IO.File]::Exists($old)) { [IO.File]::Delete($old) }
        [IO.File]::Move($Path,$old)
    }
}

function Flush-DomeniaAppLog {
    # -Force: closing or opening the journal; otherwise a flush waits 10 s after every journal refused the write.
    param([switch]$Force)
    if ($null -eq $script:AppLogQueue -or $script:AppLogQueue.Count -eq 0) { return }
    # A line logged while flushing (data store initialisation) waits in the queue for the next flush.
    if ([bool]$script:AppLogFlushing) { return }
    if ((-not $Force) -and ($null -ne $script:AppLogRetryAt) -and ((Get-Date) -lt [datetime]$script:AppLogRetryAt)) { return }
    $script:AppLogFlushing = $true
    try { Invoke-DomeniaAppLogFlush }
    finally { $script:AppLogFlushing = $false }
}

function Invoke-DomeniaAppLogFlush {
    $queued = $script:AppLogQueue.ToArray()
    $script:AppLogQueue.Clear()
    # The count of lost lines is cleared only once its note is written.
    $dropped = [int]$script:AppLogDropped
    $lines = $queued
    if ($dropped -gt 0) {
        $lines = @((ConvertTo-DomeniaLogFileLines -Time (Get-Date) -Level 'WARN' -Text ([string]$dropped + ' ligne(s) de journal perdue(s) : aucun emplacement inscriptible.'))) + $queued
    }
    $text = [string]::Join([Environment]::NewLine,[string[]]$lines) + [Environment]::NewLine
    $utf8 = New-Object System.Text.UTF8Encoding($false)
    $primary = ''; $failure = ''
    try { Initialize-DomeniaDataStore | Out-Null; $primary = [string]$script:AuditPath } catch { $failure = $_.Exception.Message }
    if ($primary) {
        try {
            try { Invoke-DomeniaAppLogRotation -Path $primary -Written $lines.Count } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaAppLogFlush' $_ }
            [IO.File]::AppendAllText($primary,$text,$utf8)
            $script:AppLogDropped = [Math]::Max(0,[int]$script:AppLogDropped - $dropped)
            $script:AppLogRetryAt = $null
            if ([bool]$script:AppLogUnavailable) {
                # Back on Domenia.log: say where the meantime lines are, once.
                $note = @(ConvertTo-DomeniaLogFileLines -Time (Get-Date) -Level 'WARN' -Text ('Journal Domenia.log de nouveau inscriptible. Lignes intermédiaires : ' + [string]$script:AppLogFallbackPath))
                try { [IO.File]::AppendAllText($primary,([string]::Join([Environment]::NewLine,[string[]]$note) + [Environment]::NewLine),$utf8) } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaAppLogFlush' $_ }
                Set-DomeniaAppLogAvailability -Available $true
            }
            return
        } catch { $failure = $_.Exception.Message }
    }
    # FI-10: Domenia.log refused (lock, full disk, ACL): LOCALAPPDATA then TEMP, and a visible pill.
    foreach ($candidate in @(Get-DomeniaAppLogFallbackPaths)) {
        try {
            $folder = [IO.DirectoryInfo]::new([IO.Path]::GetDirectoryName($candidate))
            $probe = $folder
            while ($null -ne $probe) { if ($probe.Exists -and ($probe.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Journal redirige refuse.' }; $probe = $probe.Parent }
            [void][IO.Directory]::CreateDirectory($folder.FullName)
            # The fallback journal is bounded like Domenia.log.
            try { Invoke-DomeniaAppLogRotation -Path $candidate -Written $lines.Count } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaAppLogFlush' $_ }
            [IO.File]::AppendAllText($candidate,$text,$utf8)
            $script:AppLogDropped = [Math]::Max(0,[int]$script:AppLogDropped - $dropped)
            $script:AppLogRetryAt = $null
            Set-DomeniaAppLogAvailability -Available $false -Fallback $candidate -Reason $failure
            return
        } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaAppLogFlush' $_ }
    }
    # Every target refused the write: the lines go back to the head of the queue for the next flush. The queue
    # stays bounded; what it drops is counted and announced by the first line that reaches a journal.
    $script:AppLogQueue.InsertRange(0,[string[]]$queued)
    if ($script:AppLogQueue.Count -gt 5000) {
        $drop = $script:AppLogQueue.Count - 5000
        $script:AppLogQueue.RemoveRange(0,$drop)
        $script:AppLogDropped = [int]$script:AppLogDropped + $drop
    }
    $script:AppLogRetryAt = (Get-Date).AddSeconds(10)
    Set-DomeniaAppLogAvailability -Available $false -Fallback '' -Reason $failure
}

function Set-DomeniaAppLogAvailability {
    param([bool]$Available,[string]$Fallback='',[string]$Reason='')
    $script:AppLogUnavailable = -not $Available
    $script:AppLogFallbackPath = if ($Available) { '' } else { [string]$Fallback }
    $script:AppLogUnavailableReason = if ($Available) { '' } else { [string]$Reason }
    try { Update-DomeniaExperienceLogBadge } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaAppLogAvailability' $_ }
}

function Write-AppLog {
    # -Area Technique: the technical twin of a sentence already given to the operator (incident code, .NET text):
    # Domenia.log, raw Expert view and Support incident, never the readable journal nor its red pill.
    param([string]$Text, [string]$Level = "INFO", [string]$Area = "Journal")
    $now = Get-Date
    if ([string]::IsNullOrWhiteSpace($Area)) { $Area = "Journal" }
    # PF-09: masked once; the session journal and Domenia.log receive the same masked text.
    $Text = Protect-DomeniaLogText $Text
    $script:UiLogProtectedText = $Text
    try { Add-DomeniaUiLog -Text $Text -Level $Level -Area $Area } catch { Write-DomeniaSwallowed 'Core' 'Write-AppLog' $_ }
    $script:UiLogProtectedText = $null
    try {
        if ($script:Ctrl.ContainsKey("TxtLog")) {
            # PF-13: the technical journal keeps the last 5000 lines; a purge rebuilds the box once per 500 lines.
            if ($null -eq $script:TechLogLines) { $script:TechLogLines = New-Object 'System.Collections.Generic.List[string]' }
            $techLine = "[$($now.ToString('HH:mm:ss'))][$Level] $Text"
            $script:TechLogLines.Add($techLine)
            $box = $script:Ctrl["TxtLog"]
            if ($script:TechLogLines.Count -gt 5000) {
                $script:TechLogLines.RemoveRange(0,$script:TechLogLines.Count - 4500)
                $box.Text = [string]::Join("`r`n",$script:TechLogLines.ToArray()) + "`r`n"
            }
            else { $box.AppendText($techLine + "`r`n") }
            $box.ScrollToEnd()
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Write-AppLog' $_ }
    try { Write-DomeniaAppLogFile -Text $Text -Level $Level -Time $now -Source 'AppLog' } catch { Write-DomeniaSwallowed 'Core' 'Write-AppLog' $_ }
}

function Open-DomeniaAuditLog {
    try {
        try { Flush-DomeniaAppLog -Force } catch { Write-DomeniaSwallowed 'Core' 'Open-DomeniaAuditLog' $_ }
        Initialize-DomeniaDataStore | Out-Null
        if (-not (Test-Path -LiteralPath $script:AuditPath)) { [System.IO.File]::WriteAllText($script:AuditPath,"",(New-Object System.Text.UTF8Encoding($false))) }
        Start-Process notepad.exe -ArgumentList @($script:AuditPath)
    }
    catch { Show-ErrorBox "Impossible dʼouvrir le journal local : $($_.Exception.Message)" }
}



function Get-DomeniaCriticalControlNames {
    @(
        "TvDirectory","TxtGlobalSearch","BtnGlobalSearch","DgObjects","DetailTabs","LblStatus","PbTop","BtnCancelTask",
        "TabDashboard","TabUser","TabUserAdmin","TabComputer","TabComputerAdmin","TabSecurity","TabComputerHealth",
        "TabPermissions","TabApplicationTools","TabSelfCheck","TabRelations","TabAccounts","TxtLog","ChkReadOnlyMode","WriteModeHalo","WriteModeBanner","BtnLoadBitLocker","BtnLoadLaps",
        "BtnRunComputerDiag","BtnRefreshMachineLink","BtnPermissionRefresh","BtnSelfCheckFull",
        # Bandeau et journal : ces controles etaient absents de la collecte et
        # leurs evenements n etaient jamais branches, sans aucune erreur.
        # Les rendre critiques transforme une regression silencieuse en echec
        # de demarrage explicite.
        "BtnThemeToggle","LstUiProfile","CmbPresenceFilter","TxtUiLog","BtnClearUiLog",
        "TxtCompPresence","TxtUserPresence"
    )
}

function Get-DomeniaIntegritySnapshot {
    $missingFunctions = New-Object System.Collections.Generic.List[string]
    foreach ($name in (Get-DomeniaCriticalFunctionNames)) {
        if ($null -eq (Get-Command -Name $name -CommandType Function -ErrorAction SilentlyContinue)) { [void]$missingFunctions.Add($name) }
    }
    $missingControls = New-Object System.Collections.Generic.List[string]
    foreach ($name in (Get-DomeniaCriticalControlNames)) {
        if (-not $script:Ctrl.ContainsKey($name)) { [void]$missingControls.Add($name) }
    }
    [pscustomobject]@{
        MissingFunctions = $missingFunctions.ToArray()
        MissingControls = $missingControls.ToArray()
        CriticalFunctionCount = @(Get-DomeniaCriticalFunctionNames).Count
        CriticalControlCount = @(Get-DomeniaCriticalControlNames).Count
    }
}



function Invoke-DomeniaInProcessAuthProbe {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]$Request,
        [Parameter(Mandatory=$true)]$Progress
    )

    $ErrorActionPreference = "Stop"
    $ProgressPreference = "SilentlyContinue"
    $VerbosePreference = "SilentlyContinue"
    $DebugPreference = "SilentlyContinue"
    $InformationPreference = "SilentlyContinue"

    function Set-AuthProgress {
        param([string]$Stage,[string]$Detail="")
        try {
            $Progress["Stage"] = $Stage
            $Progress["Detail"] = $Detail
            $Progress["UpdatedAt"] = [datetime]::UtcNow
            $Progress["Sequence"] = ([int]$Progress["Sequence"]) + 1
        }
        catch { }
    }

    function Add-UniqueServer {
        param([System.Collections.ArrayList]$List,[string]$Value)
        if ([string]::IsNullOrWhiteSpace($Value)) { return }
        $candidate = $Value.Trim().TrimStart([char]92).TrimEnd(".")
        if (-not [string]::IsNullOrWhiteSpace($candidate) -and -not ($List -contains $candidate)) {
            [void]$List.Add($candidate)
        }
    }


    function Get-AuthOptionalFlag {
        param($Object,[string]$Name)
        if ($null -eq $Object) { return $false }
        if ($Object -is [System.Collections.IDictionary]) {
            if (-not $Object.Contains($Name)) { return $false }
            return ($Object[$Name] -eq $true)
        }
        # Do not index a possibly absent PSObject.Properties collection.
        foreach ($property in $Object.PSObject.Properties) {
            if ($null -ne $property -and $property.Name -eq $Name) {
                return ($property.Value -eq $true)
            }
        }
        return $false
    }

    function Get-AuthAdsiAttributeFirst {
        param([AllowNull()]$Entry,[Parameter(Mandatory=$true)][string]$Name)
        if ($null -eq $Entry) {
            throw [System.InvalidOperationException]::new('DOMENIA_AUTH_ENTRY_NULL : objet ADSI absent.')
        }
        # psbase selects CLR members, but property syntax can still hide getter exceptions.
        # Explicit getter METHOD calls preserve COM errors instead of yielding a silent null.
        $properties = $Entry.psbase.get_Properties()
        if ($null -eq $properties) {
            throw [System.InvalidOperationException]::new('DOMENIA_AUTH_PROPERTIES_NULL : collection ADSI absente.')
        }
        $values = $properties.get_Item($Name)
        if ($null -eq $values -or $values.Count -eq 0) { return '' }
        $value = $values[0]
        if ($null -eq $value) { return '' }
        return [string]$value
    }

    function Read-AuthAdsiBase {
        param([AllowNull()]$Entry)
        if ($null -eq $Entry) {
            throw [System.InvalidOperationException]::new('DOMENIA_AUTH_ENTRY_NULL : base ADSI absente.')
        }
        # A refresh failure must remain the original failure. Never replace it
        # with a second, unguarded Properties[...] read in a catch block.
        $Entry.psbase.RefreshCache([string[]]@('distinguishedName'))
        $dn = Get-AuthAdsiAttributeFirst -Entry $Entry -Name 'distinguishedName'
        if ([string]::IsNullOrWhiteSpace($dn)) {
            throw [System.InvalidOperationException]::new('DOMENIA_AUTH_METADATA_MISSING : distinguishedName absent apres lecture de la base AD.')
        }
        return $dn
    }

    function Protect-AuthDiagnosticText {
        param([AllowNull()][string]$Text,[AllowNull()][string]$Secret='')
        $safe=[string]$Text
        if (-not [string]::IsNullOrEmpty($Secret)) { $safe=$safe.Replace($Secret,'[SECRET MASQUE]') }
        # No invocation source / request / credential serialization. Bound diagnostic size.
        if ($safe.Length -gt 4096) { $safe=$safe.Substring(0,4096)+' [tronque]' }
        return $safe
    }

    function ConvertFrom-AuthLdapSubCode {
        # The LDAP answer carries the precise Windows sub-code ("data 52f") while the HRESULT can stay the
        # generic 0x8007052E (logon failure). Except 525 and 52e, these codes are account states or restrictions.
        # Field report 2026-10-05: an EXPIRED password also came back as 52f, so 52f names it first.
        param([AllowNull()][string]$ExtendedMessage)
        $code = ''
        if (([string]$ExtendedMessage) -match '(?i)\bdata\s+([0-9a-f]{3,4})\b') { $code = $matches[1].ToLowerInvariant() }
        $category = ''; $summary = ''
        if ($code -ceq '525') { $category = 'Credentials'; $summary = 'Compte inconnu du controleur (code AD 525).' }
        elseif ($code -ceq '52e') { $category = 'Credentials'; $summary = 'Identifiant ou mot de passe refuse (code AD 52e).' }
        elseif ($code -ceq '52f') { $category = 'AccountRestriction'; $summary = 'Connexion refusee par une restriction du compte (code AD 52f). Cause la plus frequente : mot de passe expire ou a changer. Sinon : regle du compte (compte protege, postes ou horaires autorises).' }
        elseif ($code -ceq '530') { $category = 'AccountRestriction'; $summary = 'Connexion interdite a cette heure pour ce compte (code AD 530).' }
        elseif ($code -ceq '531') { $category = 'AccountRestriction'; $summary = 'Connexion interdite depuis ce poste pour ce compte (code AD 531).' }
        elseif ($code -ceq '532') { $category = 'AccountRestriction'; $summary = 'Le mot de passe de ce compte a expire (code AD 532).' }
        elseif ($code -ceq '533') { $category = 'AccountRestriction'; $summary = 'Ce compte est desactive (code AD 533).' }
        elseif ($code -ceq '701') { $category = 'AccountRestriction'; $summary = 'Ce compte a expire (code AD 701).' }
        elseif ($code -ceq '773') { $category = 'AccountRestriction'; $summary = 'Ce compte doit changer de mot de passe avant la connexion (code AD 773).' }
        elseif ($code -ceq '775') { $category = 'AccountRestriction'; $summary = 'Ce compte est verrouille (code AD 775). Arrete les essais et verifie son etat.' }
        return [pscustomobject]@{ SubCode = $code; Category = $category; Summary = $summary }
    }

    function Get-AuthNativeFailure {
        param($Record)
        $deep=Get-DeepestException -ErrorRecord $Record
        $hr=''; $nativeMessage=''; $extendedCode=''; $extendedMessage=''; $ldapCode=''
        try { if ($null -ne $deep) { $hr=('0x{0:X8}' -f $deep.HResult); $nativeMessage=[string]$deep.Message } } catch { }
        $cursor=$null
        try { $cursor=$Record.Exception } catch { }
        if ($null -eq $cursor -and $Record -is [System.Exception]) { $cursor=$Record }
        for ($i=0; $null -ne $cursor -and $i -lt 12; $i++) {
            if ($cursor -is [System.DirectoryServices.Protocols.LdapException]) {
                $ldapCode=[string]$cursor.ErrorCode
                $extendedMessage=[string]$cursor.ServerErrorMessage
            }
            if ($cursor -is [System.DirectoryServices.DirectoryServicesCOMException]) {
                $extendedCode=[string]$cursor.ExtendedError
                $extendedMessage=[string]$cursor.ExtendedErrorMessage
            }
            $cursor=$cursor.InnerException
        }
        $category=''; $summary=''
        switch ($hr) {
            '0x80070525' { $category='Credentials'; $summary='Compte inconnu du fournisseur d authentification.' }
            '0x8007052E' { $category='Credentials'; $summary='Identifiant ou mot de passe refuse. Le code ne distingue pas les deux.' }
            '0x8007052F' { $category='AccountRestriction'; $summary='Une restriction du compte interdit cette connexion.' }
            '0x80070530' { $category='AccountRestriction'; $summary='Connexion interdite a cette heure pour ce compte.' }
            '0x80070531' { $category='AccountRestriction'; $summary='Connexion interdite depuis ce poste pour ce compte.' }
            '0x80070532' { $category='AccountRestriction'; $summary='Le mot de passe de ce compte a expire.' }
            '0x80070533' { $category='AccountRestriction'; $summary='Ce compte est desactive.' }
            '0x80070701' { $category='AccountRestriction'; $summary='Ce compte a expire.' }
            '0x80070773' { $category='AccountRestriction'; $summary='Ce compte doit changer de mot de passe avant la connexion.' }
            '0x80070775' { $category='AccountRestriction'; $summary='Ce compte est verrouille. Arrete les essais et verifie son etat.' }
            '0x80070005' { $category='AccessDenied'; $summary='Acces refuse pendant cette etape.' }
            '0x8007051F' { $category='DomainUnavailable'; $summary='Aucun serveur d ouverture de session disponible.' }
            '0x8007054B' { $category='DomainUnavailable'; $summary='Le domaine n existe pas ou ne peut pas etre contacte.' }
            '0x8007203A' { $category='DomainUnavailable'; $summary='Le serveur d annuaire n est pas operationnel.' }
            '0x800705B4' { $category='Timeout'; $summary='Le delai de l operation est depasse.' }
        }
        # A precise AD sub-code wins over the generic logon failure, except 52e which says the same thing.
        $sub=ConvertFrom-AuthLdapSubCode -ExtendedMessage $extendedMessage
        if ((-not [string]::IsNullOrWhiteSpace($sub.Category)) -and ($sub.SubCode -cne '52e')) { $category=$sub.Category; $summary=$sub.Summary }
        return [pscustomobject]@{
            HResult=$hr; Category=$category; Summary=$summary; NativeMessage=$nativeMessage
            ExtendedCode=$extendedCode; ExtendedMessage=$extendedMessage; LdapCode=$ldapCode; SubCode=$sub.SubCode
        }
    }

    function Get-AuthFailureDiagnostic {
        param($Record,[string]$Stage,[string]$ServerName,[bool]$CredentialAttempted=$false,[string]$BindIdentity='',[AllowNull()][string]$Secret='')
        $errorId=''; $line=0; $stack=''; $exceptionType=''; $hresult=''
        try { $errorId=[string]$Record.FullyQualifiedErrorId } catch { }
        try { $line=[int]$Record.InvocationInfo.ScriptLineNumber } catch { }
        try { $stack=[string]$Record.ScriptStackTrace } catch { }
        try {
            $deep=Get-DeepestException -ErrorRecord $Record
            if ($null -ne $deep) {
                $exceptionType=$deep.GetType().FullName
                $hresult=('0x{0:X8}' -f $deep.HResult)
            }
        } catch { }
        $native=Get-AuthNativeFailure -Record $Record
        $errorId=Protect-AuthDiagnosticText -Text $errorId -Secret $Secret
        $stack=Protect-AuthDiagnosticText -Text $stack -Secret $Secret
        # Fixed whitelist: identity and native error scalars only. No Request/Credential/source.
        return [pscustomobject]@{
            Stage=$Stage; Server=$ServerName; CredentialAttempted=$CredentialAttempted
            ErrorId=$errorId; ExceptionType=$exceptionType; HResult=$hresult
            WorkerLine=$line; Stack=$stack; BindIdentity=$BindIdentity
            NativeMessage=(Protect-AuthDiagnosticText -Text $native.NativeMessage -Secret $Secret)
            ExtendedCode=$native.ExtendedCode
            ExtendedMessage=(Protect-AuthDiagnosticText -Text $native.ExtendedMessage -Secret $Secret)
            LdapCode=$native.LdapCode
        }
    }

    function Get-AuthFailureCategory {
        param($Record,[string]$Detail,[string]$Stage)
        $id=''; try { $id=[string]$Record.FullyQualifiedErrorId } catch { }
        $deep=Get-DeepestException -ErrorRecord $Record
        if ($id -match '(?i)NullArray|NullReference|IndexOutOfRange|PropertyNotFound|MethodNotFound' -or
            $Detail -match '(?i)DOMENIA_AUTH_(ENTRY|PROPERTIES|NATIVE)_NULL|Cannot index into a null array|Indexation impossible dans un tableau Null' -or
            $deep -is [System.NullReferenceException] -or $deep -is [System.IndexOutOfRangeException]) {
            return 'Internal'
        }
        if ($Detail -match '(?i)DOMENIA_AUTH_METADATA_MISSING|defaultNamingContext absent') { return 'Metadata' }
        $native=Get-AuthNativeFailure -Record $Record
        if (-not [string]::IsNullOrWhiteSpace($native.Category)) { return $native.Category }
        if ($native.LdapCode -eq '49') { return 'Credentials' }
        if ($native.LdapCode -eq '50') { return 'AccessDenied' }
        if ($native.LdapCode -eq '81') { return 'DomainUnavailable' }
        if ($native.LdapCode -eq '85') { return 'Timeout' }
        $nativeCode=$native.HResult
        if ($deep -is [System.UnauthorizedAccessException] -or $nativeCode -eq '0x80070005' -or
            $Detail -match '(?i)access[ _-]?denied|acc[eè]s.*refus[eé]|insufficient access rights') { return 'AccessDenied' }
        if ($Detail -match '(?i)identifiant|mot de passe|compte.*verrouill|compte.*desactiv|compte.*expir|ouvrir une session') { return 'Credentials' }
        if ($deep -is [System.TimeoutException] -or $Detail -match '(?i)timeout|delai depasse') { return 'Timeout' }
        if ($Stage -like 'Preparation*') { return 'Internal' }
        if ($Stage -eq 'Explicit.NativeBind') { return 'Authentication' }
        return 'DomainUnavailable'
    }

    function Get-LdapAttributeFirst {
        param($Entry,[string]$Name)
        try {
            if ($null -ne $Entry -and $Entry.Attributes.Contains($Name) -and $Entry.Attributes[$Name].Count -gt 0) {
                return [string]$Entry.Attributes[$Name][0]
            }
        }
        catch { }
        return ""
    }

    function Get-DeepestException {
        param($ErrorRecord)
        $exception = $null
        try { $exception = $ErrorRecord.Exception } catch { }
        if ($null -eq $exception -and $ErrorRecord -is [System.Exception]) { $exception = $ErrorRecord }
        $last = $exception
        $guard = 0
        while ($null -ne $exception -and $null -ne $exception.InnerException -and $guard -lt 12) {
            $exception = $exception.InnerException
            $last = $exception
            $guard++
        }
        return $last
    }

    function Format-LdapError {
        param($ErrorRecord,[string]$ServerName,[AllowNull()][string]$Secret='')
        $native=Get-AuthNativeFailure -Record $ErrorRecord
        if (-not [string]::IsNullOrWhiteSpace($native.Summary)) {
            return (Protect-AuthDiagnosticText -Text ("{0} (HRESULT={1}; serveur={2})" -f $native.Summary,$native.HResult,$ServerName) -Secret $Secret)
        }
        $outer = $null
        try { $outer = $ErrorRecord.Exception } catch { }
        $deepest = Get-DeepestException -ErrorRecord $ErrorRecord
        $ldapException = $null
        $cursor = $outer
        $guard = 0
        while ($null -ne $cursor -and $guard -lt 12) {
            if ($cursor -is [System.DirectoryServices.Protocols.LdapException]) { $ldapException = $cursor; break }
            $cursor = $cursor.InnerException
            $guard++
        }
        $code = -1
        $messages = New-Object System.Collections.ArrayList
        foreach ($candidate in @($outer,$deepest,$ldapException)) {
            try {
                $message = ([string]$candidate.Message).Trim()
                if (-not [string]::IsNullOrWhiteSpace($message) -and -not $messages.Contains($message)) { [void]$messages.Add($message) }
            }
            catch { }
        }
        if ($null -ne $ldapException) {
            try { $code = [int]$ldapException.ErrorCode } catch { }
            try {
                $serverMessage = ([string]$ldapException.ServerErrorMessage).Trim()
                if (-not [string]::IsNullOrWhiteSpace($serverMessage) -and -not $messages.Contains($serverMessage)) { [void]$messages.Add($serverMessage) }
            }
            catch { }
        }
        if (-not [string]::IsNullOrWhiteSpace($native.ExtendedMessage) -and -not $messages.Contains($native.ExtendedMessage)) {
            [void]$messages.Add($native.ExtendedMessage)
        }
        $messageText = Protect-AuthDiagnosticText -Text (($messages.ToArray() | ForEach-Object { [string]$_ }) -join " | ") -Secret $Secret
        if ($code -eq 49) {
            # Le controleur renvoie un sous-code hexadecimal dans le message,
            # sous la forme  data 775 . Il distingue huit situations que
            # rien d autre ne permet de separer.
            $sub = ""
            $subMatch = [regex]::Match($messageText,"(?i)data\s+([0-9a-f]{3,4})")
            if ($subMatch.Success) { $sub = $subMatch.Groups[1].Value.ToLowerInvariant() }
            switch ($sub) {
                "525" { return "Ce compte n existe pas dans l annuaire." }
                "52e" { return "Identifiant ou mot de passe refuse. Arrete les essais avant de verifier le compte." }
                "530" { return "Ce compte n est pas autorise a ouvrir une session a cette heure-ci." }
                "531" { return "Ce compte n est pas autorise a ouvrir une session depuis ce poste." }
                "532" { return "Le mot de passe de ce compte a expire. Change-le, puis reconnecte-toi." }
                "533" { return "Ce compte est desactive." }
                "701" { return "Ce compte a expire." }
                "773" { return "Ce compte doit changer de mot de passe avant de pouvoir se connecter." }
                "775" { return "Ce compte est VERROUILLE. Arrete les essais et verifie son etat." }
                default { return "Identifiant ou mot de passe refuse par $ServerName." }
            }
        }
        if ($messageText -match "(?i)0x8007052e|8007052e|invalid credentials|logon failure|unknown user|bad password|identifiants? (?:non valides?|incorrects?)|nom d.?utilisateur.*mot de passe.*incorrect|user name or password.*incorrect|username or password.*incorrect|mot de passe.*incorrect") { return "Identifiant ou mot de passe incorrect." }
        if ($code -eq 81 -or $messageText -match "(?i)server.*not operational|cannot contact|unavailable|connexion.*impossible|nom de serveur.*introuvable|no such host") { return "Controleur $ServerName injoignable." }
        if ($code -eq 85 -or $messageText -match "(?i)time.?out|delai|delai|operation.*expir") { return "Timeout LDAP sur $ServerName." }
        if ([string]::IsNullOrWhiteSpace($messageText) -or $messageText -eq "0") { return "Echec LDAP sans detail sur $ServerName (code $code)." }
        if ($code -lt 0) { return "$messageText (ADSI/PowerShell, HRESULT=$($native.HResult), serveur=$ServerName)" }
        return "$messageText (LDAP=$code, serveur=$ServerName)"
    }

    function New-AuthResult {
        param(
            [bool]$Success,
            [string]$BindUser="",
            [string]$AuthMode="",
            [string]$AuthMethod="",
            [string]$BaseDn="",
            [string]$Server="",
            [string]$Domain="",
            [string]$Netbios="",
            [string]$RootPath="",
            [string]$Error="",
            [string]$ErrorCategory="",
            [int]$Attempts=0,
            [long]$DurationMs=0,
            $Diagnostic=$null
        )
        [pscustomobject]@{
            Success=$Success; BindUser=$BindUser; AuthMode=$AuthMode; AuthMethod=$AuthMethod
            BaseDn=$BaseDn; Server=$Server; Domain=$Domain; Netbios=$Netbios; RootPath=$RootPath
            Error=$Error; ErrorCategory=$ErrorCategory; Attempts=$Attempts; DurationMs=$DurationMs
            Diagnostic=$(if ($Success) { $null } elseif ($null -ne $Diagnostic) { $Diagnostic } else { $lastFailure })
            InProcess=$true; WorkerThreadId=[System.Threading.Thread]::CurrentThread.ManagedThreadId
            Apartment=[System.Threading.Thread]::CurrentThread.GetApartmentState().ToString()
        }
    }

    # Enterprise multi-infrastructure path. The legacy block below is kept only
    # as inert source compatibility; every real request returns from this path.
    function Escape-AuthLdapValue {
        param([string]$Value)
        $builder = New-Object System.Text.StringBuilder
        foreach ($character in ([string]$Value).ToCharArray()) {
            # Numeric cases: under 5.1 a string case compares with the culture and U+00AD (soft hyphen) equals "`0".
            switch ([int]$character) {
                92 { [void]$builder.Append("\5c") }
                40 { [void]$builder.Append("\28") }
                41 { [void]$builder.Append("\29") }
                0 { [void]$builder.Append("\00") }
                42 { [void]$builder.Append("\2a") }
                default { [void]$builder.Append($character) }
            }
        }
        return $builder.ToString()
    }

    function Convert-AuthNamingContextToDns {
        param([string]$NamingContext)
        $labels = New-Object System.Collections.ArrayList
        foreach ($match in [regex]::Matches([string]$NamingContext,"(?i)(?:^|,)DC=([^,]+)")) {
            $label = ([string]$match.Groups[1].Value).Trim()
            if (-not [string]::IsNullOrWhiteSpace($label)) { [void]$labels.Add($label) }
        }
        return (@($labels) -join ".")
    }

    function Get-AuthNetbiosName {
        param($Connection,[string]$ConfigurationNamingContext,[string]$DefaultNamingContext)
        if ([string]::IsNullOrWhiteSpace($ConfigurationNamingContext) -or [string]::IsNullOrWhiteSpace($DefaultNamingContext)) { return "" }
        try {
            $escapedNc = Escape-AuthLdapValue -Value $DefaultNamingContext
            $request = [System.DirectoryServices.Protocols.SearchRequest]::new(
                $ConfigurationNamingContext,
                "(&(objectClass=crossRef)(nCName=$escapedNc))",
                [System.DirectoryServices.Protocols.SearchScope]::Subtree,
                [string[]]@("nETBIOSName")
            )
            $response = [System.DirectoryServices.Protocols.SearchResponse]$Connection.SendRequest($request)
            if ($response.Entries.Count -gt 0) { return Get-LdapAttributeFirst -Entry $response.Entries[0] -Name "nETBIOSName" }
        }
        catch { }
        return ""
    }

    $watch = [System.Diagnostics.Stopwatch]::StartNew()
    $authStage = 'Preparation.Request'
    $lastFailure = $null
    $lastCategory = 'DomainUnavailable'
    try {
        if (Get-AuthOptionalFlag -Object $Request -Name 'SelfTestOnly') {
            Set-AuthProgress -Stage "Auto-test" -Detail "Runspace d authentification interne operationnel."
            $watch.Stop()
            return New-AuthResult -Success $true -AuthMode "SelfTest" -AuthMethod "InProcess.Runspace" -DurationMs $watch.ElapsedMilliseconds
        }
        if (Get-AuthOptionalFlag -Object $Request -Name 'DemoOnly') {
            # D002: demonstration provider. No discovery, no bind, no credential: only the demo identity is checked
            # (same rule as Test-DomeniaDemoIdentity, repeated here because this runspace has no module).
            # AuthMode stays Explicit for the existing secondary checks; AuthMethod marks the demonstration.
            $demoIdentity = ([string]$Request.DemoIdentity).Trim()
            $watch.Stop()
            if ($demoIdentity -cnotmatch '^DEMO\\[A-Za-z0-9._-]{1,64}$') {
                return New-AuthResult -Success $false -AuthMode "Explicit" -AuthMethod "Demo.InMemory" -Error "Identite de demonstration attendue (DEMO\nom)." -ErrorCategory "Input" -DurationMs $watch.ElapsedMilliseconds
            }
            Set-AuthProgress -Stage "Demonstration" -Detail "Identite de demonstration acceptee, aucune connexion AD."
            return New-AuthResult -Success $true -BindUser $demoIdentity -AuthMode "Explicit" -AuthMethod "Demo.InMemory" -BaseDn "DC=demo,DC=invalid" -Domain "demo.invalid" -Netbios "DEMO" -Server "" -RootPath "" -DurationMs $watch.ElapsedMilliseconds
        }

        $authStage = 'Preparation.Assemblies'
        Add-Type -AssemblyName System.DirectoryServices.Protocols -ErrorAction Stop | Out-Null
        $useCurrentCredentials = [bool]$Request.UseCurrentCredentials
        $rawLogin = ([string]$Request.Login).Trim()
        if (-not $useCurrentCredentials -and $null -eq $Request.Credential) {
            $watch.Stop()
            return New-AuthResult -Success $false -AuthMode "Explicit" -AuthMethod "LDAP.Protocols.Negotiate" -Error "Identifiant ou mot de passe manquant." -ErrorCategory "Input" -DurationMs $watch.ElapsedMilliseconds
        }
        if (-not $useCurrentCredentials -and [string]::IsNullOrWhiteSpace($rawLogin)) {
            try { $rawLogin = [string]$Request.Credential.UserName } catch { }
        }

        if (-not $useCurrentCredentials) {
            try {
                Set-AuthProgress -Stage "Authentification Active Directory" -Detail "Decouverte du contexte AD puis validation unique du compte saisi"
            }
            catch { }
        }

        $authStage = 'Discovery.Candidates'
        $configuredBase = ([string]$Request.ConfiguredBase).Trim()
        $configuredServer = ([string]$Request.ConfiguredServer).Trim().TrimStart([char]92).TrimEnd(".")
        $domainHint = ([string]$Request.Domain).Trim()
        $netbiosHint = ([string]$Request.Netbios).Trim()
        if ($rawLogin.Contains("@")) {
            $upnSuffix = $rawLogin.Split("@",2)[1].Trim()
            if (-not [string]::IsNullOrWhiteSpace($upnSuffix)) { $domainHint = $upnSuffix }
        }

        $servers = New-Object System.Collections.ArrayList
        Add-UniqueServer -List $servers -Value $configuredServer
        Add-UniqueServer -List $servers -Value $domainHint
        if ($rawLogin.Contains([string][char]92)) { Add-UniqueServer -List $servers -Value ($rawLogin.Split([char]92,2)[0]) }
        try { Add-UniqueServer -List $servers -Value ([string]$env:USERDNSDOMAIN) } catch { }
        try {
            $computerDomain = [System.DirectoryServices.ActiveDirectory.Domain]::GetComputerDomain()
            try { Add-UniqueServer -List $servers -Value ([string]$computerDomain.Name) }
            finally { if ($null -ne $computerDomain) { $computerDomain.Dispose() } }
        }
        catch { }
        try { Add-UniqueServer -List $servers -Value ([string]$env:LOGONSERVER) } catch { }

        $maxServers = [Math]::Max(1,[Math]::Min(8,[int]$Request.MaxServers))
        while ($servers.Count -gt $maxServers) { $servers.RemoveAt($servers.Count - 1) }
        if ($servers.Count -eq 0) {
            $watch.Stop()
            return New-AuthResult -Success $false -AuthMode $(if($useCurrentCredentials){"Windows"}else{"Explicit"}) -AuthMethod "LDAP.Protocols.Negotiate" -Error "Aucun domaine ou controleur AD ne peut etre decouvert. Verifie le DNS ou renseigne -Server." -ErrorCategory "Configuration" -DurationMs $watch.ElapsedMilliseconds
        }

        $overallTimeout = [Math]::Max(8,[int]$Request.OverallTimeoutSeconds)
        $perServerTimeout = [Math]::Max(2,[Math]::Min(10,[int]$Request.PerServerTimeoutSeconds))
        $attempt = 0
        $lastError = "Aucune tentative effectuee."
        foreach ($serverName in @($servers)) {
            if ($watch.Elapsed.TotalSeconds -ge $overallTimeout) { break }
            $attempt++
            $connection = $null
            try {
                Set-AuthProgress -Stage "Decouverte Active Directory" -Detail "Bind LDAP et lecture RootDSE sur $serverName"
                # Pour un login explicite, utiliser ADSI/DirectoryEntry avec
                # l'identite EXACTEMENT telle qu'elle a ete saisie.
                #
                # LdapConnection + NetworkCredential interprete parfois un
                # sAMAccountName nu differemment selon le type de compte ou le
                # contexte Windows. C'est notamment visible avec certains
                # comptes administratifs qui fonctionnent dans les autres
                # outils ADSI mais sont refuses ici.
                #
                # Important securite : on ne tente aucune variante automatique
                # DOMAIN\user / user@domain. Une seule identite, une seule
                # tentative d'authentification par controleur.
                if (-not $useCurrentCredentials) {
                    # Separer strictement deux operations :
                    #   1) decouverte RootDSE avec l'identite Windows courante ;
                    #   2) UNE SEULE validation du compte explicite sur la base AD decouverte.
                    #
                    # Le mot de passe saisi ne doit jamais servir a decouvrir le domaine ou
                    # plusieurs controleurs. Cela evite de transformer une erreur de decouverte
                    # RootDSE en plusieurs tentatives d'authentification et donc en risque de lockout.
                    $discoveryRoot = $null
                    $baseAdsi = $null
                    $plainPassword = $null
                    $explicitBindAttempted = $false
                    try {
                        # RootDSE est une operation de decouverte. Sur un poste joint au domaine,
                        # la session Windows courante suffit pour lire ces metadonnees, meme si le
                        # compte administratif saisi est different.
                        $rootPath = "LDAP://$serverName/RootDSE"
                        $authStage = 'Discovery.NativeBind'
                        $discoveryRoot = New-Object System.DirectoryServices.DirectoryEntry -ArgumentList @($rootPath)
                        $nativeRoot = $discoveryRoot.psbase.get_NativeObject()
                        if ($null -eq $nativeRoot) { throw [System.InvalidOperationException]::new('DOMENIA_AUTH_NATIVE_NULL : RootDSE non valide.') }
                        $nativeRoot = $null
                        $authStage = 'Discovery.RootDSE' 

                        $detectedBase = ""
                        $configurationNc = ""
                        $detectedDc = ""
                        $detectedBase = Get-AuthAdsiAttributeFirst -Entry $discoveryRoot -Name 'defaultNamingContext'
                        $configurationNc = Get-AuthAdsiAttributeFirst -Entry $discoveryRoot -Name 'configurationNamingContext'
                        $detectedDc = Get-AuthAdsiAttributeFirst -Entry $discoveryRoot -Name 'dnsHostName'

                        # Si un serveur logique (ex. CNAMTS.LOCAL) ne renvoie pas RootDSE, on peut
                        # essayer le candidat suivant SANS utiliser le mot de passe explicite.
                        if ([string]::IsNullOrWhiteSpace($detectedBase)) {
                            throw "Decouverte RootDSE incomplete sur $serverName : defaultNamingContext absent."
                        }

                        $effectiveBase = if ([string]::IsNullOrWhiteSpace($configuredBase)) { $detectedBase } else { $configuredBase }
                        $detectedDomain = Convert-AuthNamingContextToDns -NamingContext $detectedBase
                        if ([string]::IsNullOrWhiteSpace($detectedDomain)) { $detectedDomain = $domainHint }

                        # Resoudre UNE identite canonique avant le bind. Un sAMAccountName court
                        # est qualifie une seule fois avec le NETBIOS connu du domaine. On ne tente
                        # aucune succession raw / DOMAIN\\user / user@domain.
                        $authStage = 'Identity.Resolve'
                        $detectedNetbios = $netbiosHint
                        try {
                            if ([string]::IsNullOrWhiteSpace($detectedNetbios) -and
                                -not [string]::IsNullOrWhiteSpace([string]$env:USERDOMAIN) -and
                                [string]$env:USERDOMAIN -ine [string]$env:COMPUTERNAME) {
                                $detectedNetbios = ([string]$env:USERDOMAIN).Trim()
                            }
                        }
                        catch { }
                        if ([string]::IsNullOrWhiteSpace($detectedNetbios) -and -not [string]::IsNullOrWhiteSpace($detectedDomain)) {
                            try { $detectedNetbios = (($detectedDomain -split '\.')[0]).ToUpperInvariant() } catch { }
                        }

                        $bindLogin = $rawLogin
                        if (-not $bindLogin.Contains([string][char]92) -and -not $bindLogin.Contains("@") -and -not [string]::IsNullOrWhiteSpace($detectedNetbios)) {
                            $bindLogin = "$detectedNetbios\$rawLogin"
                        }

                        $plainPassword = [string]$Request.Credential.GetNetworkCredential().Password
                        $selectedServer = if ([string]::IsNullOrWhiteSpace($detectedDc)) { [string]$serverName } else { $detectedDc }
                        $basePath = "LDAP://$selectedServer/$effectiveBase"
                        Set-AuthProgress -Stage "Authentification Active Directory" -Detail "Validation unique de $bindLogin sur $selectedServer (ADSI get_NativeObject)"

                        $authStage = 'Explicit.NativeBind'
                        $explicitBindAttempted = $true
                        $baseAdsi = New-Object System.DirectoryServices.DirectoryEntry -ArgumentList @(
                            $basePath,
                            $bindLogin,
                            $plainPassword,
                            [System.DirectoryServices.AuthenticationTypes]::Secure
                        )
                        # R1.7.2: call the CLR getter as a METHOD, not a property. PowerShell can
                        # silently turn a throwing property getter into null, hiding the real HRESULT.
                        # Keep both the genuine-null guard and the subsequent base read.
                        $nativeBase = $baseAdsi.psbase.get_NativeObject()
                        if ($null -eq $nativeBase) { throw [System.InvalidOperationException]::new('DOMENIA_AUTH_NATIVE_NULL : authentification ADSI non confirmee.') }
                        $nativeBase = $null
                        $authStage = 'Explicit.ReadBase'
                        Set-AuthProgress -Stage "Lecture de la base AD" -Detail "Verification de la lecture apres authentification sur $selectedServer"
                        [void](Read-AuthAdsiBase -Entry $baseAdsi)

                        Set-AuthProgress -Stage "Termine" -Detail "Contexte AD valide sur $selectedServer"
                        $watch.Stop()
                        # BindUser est renvoye au thread UI puis devient aussi le UserName du
                        # PSCredential de session. Tous les workers utiliseront donc le meme couple
                        # identite/mot de passe que celui qui vient de reussir ce bind.
                        return New-AuthResult -Success $true -BindUser $bindLogin -AuthMode "Explicit" -AuthMethod "ADSI.DirectoryEntry+ContextDiscovery" -BaseDn $effectiveBase -Server $selectedServer -Domain $detectedDomain -Netbios $detectedNetbios -RootPath "LDAP://$selectedServer/$effectiveBase" -Attempts 1 -DurationMs $watch.ElapsedMilliseconds
                    }
                    catch {
                        $failure = $_
                        $failureServer = if ($explicitBindAttempted) { [string]$selectedServer } else { [string]$serverName }
                        $diagnosticIdentity = if ($explicitBindAttempted) { [string]$bindLogin } else { '' }
                        $lastFailure = Get-AuthFailureDiagnostic -Record $failure -Stage $authStage -ServerName $failureServer -CredentialAttempted $explicitBindAttempted -BindIdentity $diagnosticIdentity -Secret $plainPassword
                        $detail = Format-LdapError -ErrorRecord $failure -ServerName $failureServer -Secret $plainPassword
                        $category = Get-AuthFailureCategory -Record $failure -Detail $detail -Stage $authStage
                        $lastCategory = $category

                        if ($explicitBindAttempted -or $category -eq 'Internal') {
                            # Une fois le mot de passe envoye UNE fois, ne jamais essayer un autre DC.
                            # Qu'il s'agisse d'un refus d'identite ou d'une panne reseau apres bind,
                            # l'utilisateur pourra relancer volontairement. DOMENIA ne multiplie pas les essais.
                            $watch.Stop()
                            Set-AuthProgress -Stage "Termine" -Detail $detail
                            return New-AuthResult -Success $false -AuthMode "Explicit" -AuthMethod "ADSI.DirectoryEntry+ContextDiscovery" -Error $detail -ErrorCategory $category -Server $failureServer -Attempts ([int]$explicitBindAttempted) -DurationMs $watch.ElapsedMilliseconds
                        }

                        # Ici aucun mot de passe explicite n'a encore ete utilise. On peut donc
                        # continuer la decouverte sur le prochain candidat sans risque de lockout.
                        $lastError = $detail
                        continue
                    }
                    finally {
                        # SE-16: only drops this reference. The String handed to DirectoryEntry (and kept for masking
                        # the error text) is immutable and stays in memory until the garbage collector reclaims it;
                        # no assignment erases it. It is created just before the single bind and never logged.
                        $plainPassword = $null
                        try { if ($null -ne $baseAdsi) { $baseAdsi.psbase.Dispose() } } catch { }
                        try { if ($null -ne $discoveryRoot) { $discoveryRoot.psbase.Dispose() } } catch { }
                    }
                }

                # La session Windows continue d'utiliser LDAP.Protocols avec
                # Negotiate, puisqu'aucun mot de passe explicite n'est fourni.
                $authStage = 'Windows.NativeBind'
                $isFullyQualified = ([string]$serverName).Contains(".")
                $identifier = New-Object System.DirectoryServices.Protocols.LdapDirectoryIdentifier -ArgumentList @([string]$serverName,389,$isFullyQualified,$false)
                $connection = New-Object System.DirectoryServices.Protocols.LdapConnection -ArgumentList @($identifier)
                $connection.AuthType = [System.DirectoryServices.Protocols.AuthType]::Negotiate
                $connection.Timeout = [TimeSpan]::FromSeconds($perServerTimeout)
                $connection.SessionOptions.ProtocolVersion = 3
                try { $connection.SessionOptions.Signing = $true } catch { }
                try { $connection.SessionOptions.Sealing = $true } catch { }
                try { $connection.Bind() }
                catch [System.DirectoryServices.Protocols.LdapException] {
                    $ldapCode = 0
                    try { $ldapCode = [int]$_.Exception.ErrorCode } catch { }
                    if ($ldapCode -eq 49) {
                        # Refus d identite : inutile et dangereux d insister
                        # sur les autres controleurs, ils repondront pareil et
                        # chaque essai rapproche du verrouillage du compte.
                        $watch.Stop()
                        $detail = Format-LdapError -ErrorRecord $_ -ServerName $serverName
                        Set-AuthProgress -Stage "Termine" -Detail $detail
                        return New-AuthResult -Success $false -AuthMode $(if($useCurrentCredentials){"Windows"}else{"Explicit"}) -AuthMethod "LDAP.Protocols.Negotiate" -Error $detail -ErrorCategory "Credentials" -Server $serverName -Attempts ($attempt) -DurationMs $watch.ElapsedMilliseconds
                    }
                    throw
                }

                $rootRequest = [System.DirectoryServices.Protocols.SearchRequest]::new(
                    "",
                    "(objectClass=*)",
                    [System.DirectoryServices.Protocols.SearchScope]::Base,
                    [string[]]@("defaultNamingContext","rootDomainNamingContext","configurationNamingContext","dnsHostName")
                )
                $rootResponse = [System.DirectoryServices.Protocols.SearchResponse]$connection.SendRequest($rootRequest)
                if ($rootResponse.Entries.Count -lt 1) { throw "RootDSE ne retourne aucune entree." }
                if ($null -eq $rootResponse -or $null -eq $rootResponse.Entries -or $rootResponse.Entries.Count -eq 0) {
                    throw [System.InvalidOperationException]::new('DOMENIA_AUTH_METADATA_MISSING : reponse RootDSE vide.')
                }
                $rootEntry = $rootResponse.Entries[0]
                $detectedBase = Get-LdapAttributeFirst -Entry $rootEntry -Name "defaultNamingContext"
                if ([string]::IsNullOrWhiteSpace($detectedBase)) { throw "RootDSE ne retourne aucun defaultNamingContext." }
                $configurationNc = Get-LdapAttributeFirst -Entry $rootEntry -Name "configurationNamingContext"
                $detectedDc = Get-LdapAttributeFirst -Entry $rootEntry -Name "dnsHostName"
                $effectiveBase = if ([string]::IsNullOrWhiteSpace($configuredBase)) { $detectedBase } else { $configuredBase }

                $baseRequest = [System.DirectoryServices.Protocols.SearchRequest]::new(
                    $effectiveBase,
                    "(objectClass=*)",
                    [System.DirectoryServices.Protocols.SearchScope]::Base,
                    [string[]]@("distinguishedName")
                )
                $baseResponse = [System.DirectoryServices.Protocols.SearchResponse]$connection.SendRequest($baseRequest)
                if ($baseResponse.Entries.Count -lt 1) { throw "La base LDAP '$effectiveBase' est introuvable ou illisible." }

                $detectedDomain = Convert-AuthNamingContextToDns -NamingContext $detectedBase
                if ([string]::IsNullOrWhiteSpace($detectedDomain)) { $detectedDomain = $domainHint }
                $detectedNetbios = Get-AuthNetbiosName -Connection $connection -ConfigurationNamingContext $configurationNc -DefaultNamingContext $detectedBase
                if ([string]::IsNullOrWhiteSpace($detectedNetbios)) { $detectedNetbios = $netbiosHint }
                $selectedServer = if ([string]::IsNullOrWhiteSpace($detectedDc)) { [string]$serverName } else { $detectedDc }
                $bindIdentity = if ($useCurrentCredentials) {
                    try { [System.Security.Principal.WindowsIdentity]::GetCurrent().Name } catch { "Session Windows" }
                }
                else { [string]$Request.Credential.UserName }

                Set-AuthProgress -Stage "Termine" -Detail "Contexte AD valide sur $selectedServer"
                $watch.Stop()
                return New-AuthResult -Success $true -BindUser $bindIdentity -AuthMode $(if($useCurrentCredentials){"Windows"}else{"Explicit"}) -AuthMethod "LDAP.Protocols.Negotiate+RootDSE" -BaseDn $effectiveBase -Server $selectedServer -Domain $detectedDomain -Netbios $detectedNetbios -RootPath "LDAP://$selectedServer/$effectiveBase" -Attempts $attempt -DurationMs $watch.ElapsedMilliseconds
            }
            catch {
                $failure = $_
                $lastFailure = Get-AuthFailureDiagnostic -Record $failure -Stage $authStage -ServerName ([string]$serverName)
                $lastError = Format-LdapError -ErrorRecord $failure -ServerName ([string]$serverName)
                $lastCategory = Get-AuthFailureCategory -Record $failure -Detail $lastError -Stage $authStage
                if ($lastCategory -eq 'Internal') { break }
            }
            finally { try { if ($null -ne $connection) { $connection.Dispose() } } catch { } }
        }

        $watch.Stop()
        return New-AuthResult -Success $false -AuthMode $(if($useCurrentCredentials){"Windows"}else{"Explicit"}) -AuthMethod "LDAP.Protocols.Negotiate+RootDSE" -Domain $domainHint -Netbios $netbiosHint -Error $lastError -ErrorCategory $lastCategory -Attempts $attempt -DurationMs $watch.ElapsedMilliseconds
    }
    catch {
        $watch.Stop()
        $serverForError = ""
        try { $serverForError = [string]$Request.ConfiguredServer } catch { }
        if([string]::IsNullOrWhiteSpace($serverForError)){ $serverForError = "Active Directory" }
        $failure = $_
        $lastFailure = Get-AuthFailureDiagnostic -Record $failure -Stage $authStage -ServerName $serverForError
        $friendly = Format-LdapError -ErrorRecord $failure -ServerName $serverForError
        $cat = Get-AuthFailureCategory -Record $failure -Detail $friendly -Stage $authStage
        return New-AuthResult -Success $false -AuthMode $(if([bool]$Request.UseCurrentCredentials){"Windows"}else{"Explicit"}) -AuthMethod "LDAP.Protocols.Negotiate+RootDSE" -Error $friendly -ErrorCategory $cat -DurationMs $watch.ElapsedMilliseconds
    }

}
$script:AuthCleanupSessions = @{}
$script:AuthCleanupTimer = $null

function Complete-DomeniaLoginAuthRunspaceCleanup {
    param($Session)
    if ($null -eq $Session) { return }
    try { if ([bool]$Session.Cleaned) { return } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaLoginAuthRunspaceCleanup' $_ }
    # A cancellation request is not completion: an active worker still owns this secret.
    if($null -ne $Session.AsyncResult -and -not [bool]$Session.AsyncResult.IsCompleted){return}
    try {
        if ($null -ne $Session.AsyncResult -and [bool]$Session.AsyncResult.IsCompleted -and -not [bool]$Session.EndInvoked) {
            try { [void]$Session.PowerShell.EndInvoke($Session.AsyncResult) } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaLoginAuthRunspaceCleanup' $_ }
            $Session.EndInvoked = $true
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaLoginAuthRunspaceCleanup' $_ }
    try { if ($null -ne $Session.PowerShell) { $Session.PowerShell.Dispose() } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaLoginAuthRunspaceCleanup' $_ }
    try { if ($null -ne $Session.Runspace) { $Session.Runspace.Close(); $Session.Runspace.Dispose() } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaLoginAuthRunspaceCleanup' $_ }
    try { if ($null -ne $Session.Request) { $Session.Request.Credential = $null } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaLoginAuthRunspaceCleanup' $_ }
    try { if ($null -ne $Session.PSObject.Properties['OwnedSecret'] -and $null -ne $Session.OwnedSecret) { $Session.OwnedSecret.Dispose(); $Session.OwnedSecret=$null } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaLoginAuthRunspaceCleanup' $_ }
    try {
        $Session.PowerShell = $null
        $Session.Runspace = $null
        $Session.AsyncResult = $null
        $Session.Cleaned = $true
    }
    catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaLoginAuthRunspaceCleanup' $_ }
}

function Ensure-DomeniaAuthCleanupTimer {
    if ($null -ne $script:AuthCleanupTimer) { return }
    # FI-05: protected standalone timer (connection, before and after the engine).
    $script:AuthCleanupTimer = New-DomeniaTimer -Owner 'Timer:AuthCleanup' -IntervalMs 350 -Standalone -RunWhenHidden -Tick {
        try {
            foreach ($key in @($script:AuthCleanupSessions.Keys)) {
                $session = $script:AuthCleanupSessions[$key]
                if ($null -eq $session) { $script:AuthCleanupSessions.Remove($key); continue }
                $completed = $false
                try { $completed = [bool]$session.AsyncResult.IsCompleted } catch { $completed = $true }
                if ($completed) {
                    Complete-DomeniaLoginAuthRunspaceCleanup -Session $session
                    $script:AuthCleanupSessions.Remove($key)
                    continue
                }
                if ((Get-Date) -gt $session.CleanupRetryAt) {
                    try { [void]$session.PowerShell.BeginStop($null,$null) } catch { Write-DomeniaSwallowed 'Core' 'Ensure-DomeniaAuthCleanupTimer' $_ }
                    $session.CleanupRetryAt = (Get-Date).AddSeconds(2)
                }
                if ((Get-Date) -gt $session.CleanupGiveUpAt) {
                    # Ne jamais bloquer le thread WPF pour forcer la destruction d'un
                    # appel domaine deja en cours. On libere seulement nos references ;
                    # le CLR recuperera le runspace lorsqu'il aura rendu la main.
                    try { $session.Request.Credential = $null } catch { Write-DomeniaSwallowed 'Core' 'Ensure-DomeniaAuthCleanupTimer' $_ }
                    $script:AuthCleanupSessions.Remove($key)
                }
            }
            if ($script:AuthCleanupSessions.Count -eq 0) {
                $script:AuthCleanupTimer.Stop()
                $script:AuthCleanupTimer = $null
            }
        }
        catch { Write-DomeniaSwallowed 'Core' 'Ensure-DomeniaAuthCleanupTimer' $_ }
    }
    $script:AuthCleanupTimer.Start()
}

function Queue-DomeniaLoginAuthRunspaceCleanup {
    param($Session)
    if ($null -eq $Session) { return }
    try {
        $Session.CleanupRetryAt = Get-Date
        $Session.CleanupGiveUpAt = (Get-Date).AddSeconds(30)
        $script:AuthCleanupSessions[[string]$Session.Id] = $Session
        Ensure-DomeniaAuthCleanupTimer
    }
    catch { Write-DomeniaSwallowed 'Core' 'Queue-DomeniaLoginAuthRunspaceCleanup' $_ }
}

function Start-DomeniaLoginAuthRunspace {
    param([Parameter(Mandatory=$true)]$Request)

    $runspace = $null
    $powerShell = $null
    try {
        $definition = [string](Get-Command -Name Invoke-DomeniaInProcessAuthProbe -CommandType Function -ErrorAction Stop).Definition
        $initialState = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
        $functionEntry = New-Object System.Management.Automation.Runspaces.SessionStateFunctionEntry -ArgumentList @("Invoke-DomeniaInProcessAuthProbe",$definition)
        $initialState.Commands.Add($functionEntry)

        $runspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace($initialState)
        $runspace.ApartmentState = [System.Threading.ApartmentState]::MTA
        $runspace.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
        $runspace.Open()

        $progress = [hashtable]::Synchronized(@{
            Stage = "Preparation"
            Detail = "Initialisation du controle Active Directory en memoire"
            UpdatedAt = [datetime]::UtcNow
            Sequence = 0
        })

        $powerShell = [System.Management.Automation.PowerShell]::Create()
        $powerShell.Runspace = $runspace
        [void]$powerShell.AddCommand("Invoke-DomeniaInProcessAuthProbe")
        [void]$powerShell.AddParameter("Request",$Request)
        [void]$powerShell.AddParameter("Progress",$progress)
        $asyncResult = $powerShell.BeginInvoke()

        return [pscustomobject]@{
            Id = [guid]::NewGuid().ToString("N")
            Request = $Request
            Progress = $progress
            PowerShell = $powerShell
            Runspace = $runspace
            AsyncResult = $asyncResult
            StartedAt = Get-Date
            EndInvoked = $false
            Cleaned = $false
            CancelRequested = $false
            CleanupRetryAt = [datetime]::MinValue
            CleanupGiveUpAt = [datetime]::MinValue
        }
    }
    catch {
        try { if ($null -ne $powerShell) { $powerShell.Dispose() } } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaLoginAuthRunspace' $_ }
        try { if ($null -ne $runspace) { $runspace.Close(); $runspace.Dispose() } } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaLoginAuthRunspace' $_ }
        throw
    }
}

function Read-DomeniaAuthRunspaceResult {
    param([Parameter(Mandatory=$true)]$Session)
    if ($null -eq $Session.AsyncResult -or -not [bool]$Session.AsyncResult.IsCompleted) { throw "La validation Active Directory n est pas terminee." }
    if ([bool]$Session.EndInvoked) { throw "Le resultat de la validation a deja ete consomme." }

    $rows = @()
    try {
        $rows = @($Session.PowerShell.EndInvoke($Session.AsyncResult))
        $Session.EndInvoked = $true
    }
    catch {
        $Session.EndInvoked = $true
        $streamDetail = ""
        try { $streamDetail = (@($Session.PowerShell.Streams.Error) | ForEach-Object { $_.ToString() }) -join " | " } catch { Write-DomeniaSwallowed 'Core' 'Read-DomeniaAuthRunspaceResult' $_ }
        if ([string]::IsNullOrWhiteSpace($streamDetail)) { $streamDetail = [string]$_.Exception.Message }
        throw $streamDetail
    }

    $result = @($rows | Where-Object { $null -ne $_ -and $null -ne $_.PSObject.Properties["Success"] } | Select-Object -Last 1)
    if ($result.Count -eq 0) {
        $streamDetail = ""
        try { $streamDetail = (@($Session.PowerShell.Streams.Error) | ForEach-Object { $_.ToString() }) -join " | " } catch { Write-DomeniaSwallowed 'Core' 'Read-DomeniaAuthRunspaceResult' $_ }
        if ([string]::IsNullOrWhiteSpace($streamDetail)) { $streamDetail = "Le runspace d authentification n a retourne aucun objet exploitable." }
        throw $streamDetail
    }
    return $result[0]
}

function Stop-DomeniaLoginAuthRunspace {
    param($Session,[switch]$Terminate)
    if ($null -eq $Session -or [bool]$Session.Cleaned) { return }
    $completed = $false
    try { $completed = [bool]$Session.AsyncResult.IsCompleted } catch { $completed = $true }
    if (-not $completed -and $Terminate -and -not [bool]$Session.CancelRequested) {
        try {
            $Session.CancelRequested = $true
            [void]$Session.PowerShell.BeginStop($null,$null)
        }
        catch { Write-DomeniaSwallowed 'Core' 'Stop-DomeniaLoginAuthRunspace' $_ }
    }
    try { $completed = [bool]$Session.AsyncResult.IsCompleted } catch { $completed = $true }
    if ($completed) { Complete-DomeniaLoginAuthRunspaceCleanup -Session $Session }
    else { Queue-DomeniaLoginAuthRunspaceCleanup -Session $Session }
}

function Stop-DomeniaLoginAuth {
    param([switch]$Terminate)
    try {
        if ($null -ne $script:FastLoginState -and $null -ne $script:FastLoginState.Session) {
            Stop-DomeniaLoginAuthRunspace -Session $script:FastLoginState.Session -Terminate:$Terminate
            $script:FastLoginState.Session = $null
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Stop-DomeniaLoginAuth' $_ }
}

function Start-PruneOrphanLinks {
    try {
        $links = @($script:UserMachineLinks | Where-Object {-not (Test-DomeniaProtectedAssociationSource ([string]$_.Source))})
        if ($links.Count -eq 0) { Set-Status "Aucune association automatique à vérifier ; associations déclarées et importées conservées." "WARN"; return }
        $payload = [pscustomobject]@{ Links=$links }
        $code = @'
$foundUsers = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
$foundComputers = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
$users = @($Payload.Links | ForEach-Object { Normalize-WUser ([string]$_.UserLogin) } | Where-Object { $_ } | Sort-Object -Unique)
$computers = @($Payload.Links | ForEach-Object { ([string]$_.Computer).Trim().TrimEnd('$').Split('.')[0] } | Where-Object { $_ } | Sort-Object -Unique)
for($i=0;$i -lt $users.Count;$i+=40) {
    $slice=@($users[$i..([Math]::Min($i+39,$users.Count-1))])
    $parts=@($slice | ForEach-Object { "(sAMAccountName=$(Escape-WLdap $_))" })
    $s=New-WSearcher $Context ([string]$Context.BaseDn) "(&(objectCategory=person)(objectClass=user)(|$($parts -join '')))" @("sAMAccountName") "Subtree" 0
    $all=$null;$root=$s.SearchRoot
    try { $all=$s.FindAll(); foreach($r in $all) { [void]$foundUsers.Add([string](Get-WPropFirst $r.Properties "samaccountname" "")) } }
    finally { if($null -ne $all){$all.Dispose()};$s.Dispose();if($null -ne $root){$root.Dispose()} }
}
for($i=0;$i -lt $computers.Count;$i+=40) {
    $slice=@($computers[$i..([Math]::Min($i+39,$computers.Count-1))])
    $parts=@($slice | ForEach-Object { "(name=$(Escape-WLdap $_))" })
    $s=New-WSearcher $Context ([string]$Context.BaseDn) "(&(objectCategory=computer)(|$($parts -join '')))" @("name") "Subtree" 0
    $all=$null;$root=$s.SearchRoot
    try { $all=$s.FindAll(); foreach($r in $all) { [void]$foundComputers.Add([string](Get-WPropFirst $r.Properties "name" "")) } }
    finally { if($null -ne $all){$all.Dispose()};$s.Dispose();if($null -ne $root){$root.Dispose()} }
}
$rows=foreach($l in @($Payload.Links)) {
    $u=Normalize-WUser ([string]$l.UserLogin)
    $c=([string]$l.Computer).Trim().TrimEnd('$').Split('.')[0]
    [pscustomobject]@{ UserLogin=[string]$l.UserLogin; Computer=[string]$l.Computer; UserExists=$foundUsers.Contains($u); ComputerExists=$foundComputers.Contains($c); When=[string]$l.When }
}
[pscustomobject]@{ Rows=@($rows); Checked=$rows.Count }
'@
        # UX-40: the orphans are listed in Relations with their reason and a box each (Show-DomeniaOrphanLinks); the
        # removal is confirmed in the page, journaled and restorable (Remove-DomeniaRelations). Nothing is removed here.
        Start-UiTask -Name "Controle liens user-machine" -OperationId "PruneLinks" -Code $code -Payload $payload -ReplaceKey "prunelinks" -DisableControls @("BtnPruneLinks") -TimeoutSeconds 90 -StatusText "Vérification des associations en lecture seule..." -OnSuccess {
            param($result)
            Show-DomeniaOrphanLinks -Result $result
        } -OnError { param($message) Set-Status "Contrôle des associations : $message" "ERROR" } | Out-Null
    }
    catch { Show-ErrorBox "Erreur contrôle des liens : $($_.Exception.Message)" }
}


# =====================================================================
# Association user-machine : diffusion dans les listes, fiches et dashboard.
# Le stockage reste local. Un lien existant n est jamais remplace automatiquement.
# =====================================================================




function Get-AssociationForRow {
    param($Row)
    if ($null -eq $Row) { return "" }
    try {
        switch ([string]$Row.Type) {
            "Machine" {
                $link = @(Get-LinksForComputer -Computer ([string]$Row.Name) -Guid ([string](Get-DomeniaMember $Row 'Guid' '')) | Select-Object -First 1)
                if ($link.Count -gt 0) { return [string]$link[0].UserLogin }
                return "Non detecte"
            }
            "Utilisateur" {
                $links = @(Get-LinksForUser -UserLogin ([string]$Row.Login) -Guid ([string](Get-DomeniaMember $Row 'Guid' '')))
                if ($links.Count -gt 0) { return (($links | ForEach-Object { [string]$_.Computer }) -join ", ") }
                return "Aucun poste"
            }
            default { return "" }
        }
    }
    catch { return "" }
}

function Get-SelectedAssociationSummary {
    if ($null -eq $script:SelectedObject) { return "Aucun objet selectionne" }
    try {
        if ($script:SelectedObject.Type -eq "Machine") {
            $computer = ""
            try { $computer = [string]$script:Ctrl["TxtCompName"].Text } catch { Write-DomeniaSwallowed 'Core' 'Get-SelectedAssociationSummary' $_ }
            if ([string]::IsNullOrWhiteSpace($computer)) { $computer = [string]$script:SelectedObject.Name }
            # P-CD-09: without a name to look up, "no link" would be a guess.
            if ([string]::IsNullOrWhiteSpace($computer)) { return "Association indisponible" }
            $links = @(Get-LinksForComputer -Computer $computer -Guid ([string](Get-DomeniaMember $script:SelectedObject 'Guid' '')))
            if ($links.Count -eq 0) { return "Aucun utilisateur lie" }
            $l = $links[0]
            $confidence = $(if($null -ne (Get-Command Get-DomeniaLinkQualification -CommandType Function -ErrorAction SilentlyContinue)){(Get-DomeniaLinkQualification $l).Suffix}elseif($null -ne $l.PSObject.Properties['Confidence'] -and -not [string]::IsNullOrWhiteSpace([string]$l.Confidence)){'  confiance '+[string]$l.Confidence+'%'}else{''})
            # CO-29: local time of the stored UTC date.
            $whenText = ''
            if ($null -ne (Get-Command Format-DomeniaRelationWhen -CommandType Function -ErrorAction SilentlyContinue)) { $whenText = Format-DomeniaRelationWhen ([string]$l.When) }
            if (-not $whenText) { $whenText = [string]$l.When }
            return "$($l.UserLogin)  $($l.Source)$confidence  $whenText"
        }
        if ($script:SelectedObject.Type -eq "Utilisateur") {
            $user = ""
            try { $user = [string]$script:Ctrl["TxtUserSam"].Text } catch { Write-DomeniaSwallowed 'Core' 'Get-SelectedAssociationSummary' $_ }
            if ([string]::IsNullOrWhiteSpace($user)) { return "Association indisponible" }
            $links = @(Get-LinksForUser -UserLogin $user -Guid ([string](Get-DomeniaMember $script:SelectedObject 'Guid' '')))
            if ($links.Count -eq 0) { return "Aucun poste lie" }
            return (($links | ForEach-Object { "$($_.Computer) [$($_.Source)]" }) -join ", ")
        }
    }
    catch { return "Association indisponible" }
    return "Non applicable"
}

# =====================================================================
# DOMENIA MASTER LAST V1 - associations user-machine integrees a toutes les vues.
# =====================================================================

function Rebuild-UserMachineLinkIndex {
    $byComputer = @{}
    $byUser = @{}
    foreach ($link in @($script:UserMachineLinks)) {
        if ($null -eq $link) { continue }
        $computer = Normalize-LinkComputer ([string]$link.Computer)
        $user = Normalize-LinkUser ([string]$link.UserLogin)
        if (-not [string]::IsNullOrWhiteSpace($computer)) {
            if (-not $byComputer.ContainsKey($computer)) { $byComputer[$computer] = [System.Collections.ArrayList]::new() }
            [void]$byComputer[$computer].Add($link)
        }
        if (-not [string]::IsNullOrWhiteSpace($user)) {
            $userKey = $user.ToLowerInvariant()
            if (-not $byUser.ContainsKey($userKey)) { $byUser[$userKey] = [System.Collections.ArrayList]::new() }
            [void]$byUser[$userKey].Add($link)
        }
    }
    $script:LinkByComputer = $byComputer
    $script:LinksByUser = $byUser
    $script:LinkIndexCount = @($script:UserMachineLinks).Count
    $script:LinkIndexGeneration = [int]$script:LinkIndexGeneration + 1
}

function Ensure-UserMachineLinkIndex {
    if ($null -eq $script:LinkByComputer -or $null -eq $script:LinksByUser -or [int]$script:LinkIndexCount -ne @($script:UserMachineLinks).Count) {
        Rebuild-UserMachineLinkIndex
    }
}

function Get-LinksForComputer {
    # Point 9: with the GUID of the displayed object, a recycled or reassigned name never shows the associations
    # recorded for another object (Select-DomeniaLinksForIdentity). Without GUID the index answers by name.
    # $CreatedUtc (whenCreated of the displayed object, when the caller read it) also leaves out a legacy link without
    # GUID recorded before the object existed.
    param([string]$Computer,[string]$Guid='',$CreatedUtc=$null)
    $normalized = Normalize-LinkComputer $Computer
    if ([string]::IsNullOrWhiteSpace($normalized)) { return }
    Ensure-UserMachineLinkIndex
    if ($null -eq $script:LinkByComputer -or -not $script:LinkByComputer.ContainsKey($normalized)) { return }
    $list = $script:LinkByComputer[$normalized]
    if ($null -eq $list) { return }
    if ($Guid) { foreach ($item in @(Select-DomeniaLinksForIdentity -Links @($list) -Kind Computer -Guid $Guid -CreatedUtc $CreatedUtc)) { Write-Output $item }; return }
    foreach ($item in $list) { Write-Output $item }
}

function Get-LinksForUser {
    # Point 9: same identity rule as Get-LinksForComputer for an account recreated under a former login.
    param([string]$UserLogin,[string]$Guid='',$CreatedUtc=$null)
    $normalized = Normalize-LinkUser $UserLogin
    if ([string]::IsNullOrWhiteSpace($normalized)) { return }
    Ensure-UserMachineLinkIndex
    $key = $normalized.ToLowerInvariant()
    if ($null -eq $script:LinksByUser -or -not $script:LinksByUser.ContainsKey($key)) { return }
    $list = $script:LinksByUser[$key]
    if ($null -eq $list) { return }
    if ($Guid) { foreach ($item in @(Select-DomeniaLinksForIdentity -Links @($list) -Kind User -Guid $Guid -CreatedUtc $CreatedUtc)) { Write-Output $item }; return }
    foreach ($item in $list) { Write-Output $item }
}

function Find-DomeniaCachedUserRow {
    param([string]$Login,[string]$Guid="")
    $guidKey = ([string]$Guid).Trim().ToLowerInvariant()
    if (-not [string]::IsNullOrWhiteSpace($guidKey) -and $script:IndexUsersByGuid.ContainsKey($guidKey)) { return $script:IndexUsersByGuid[$guidKey] }
    $userKey = Normalize-LinkUser $Login
    if (-not [string]::IsNullOrWhiteSpace($userKey)) {
        $key = $userKey.ToLowerInvariant()
        if ($script:IndexUsersByLogin.ContainsKey($key)) { return $script:IndexUsersByLogin[$key] }
    }
    return $null
}

function Find-DomeniaCachedComputerRow {
    param([string]$Computer,[string]$Guid="")
    $guidKey = ([string]$Guid).Trim().ToLowerInvariant()
    if (-not [string]::IsNullOrWhiteSpace($guidKey) -and $script:IndexComputersByGuid.ContainsKey($guidKey)) { return $script:IndexComputersByGuid[$guidKey] }
    $computerKey = Normalize-LinkComputer $Computer
    if (-not [string]::IsNullOrWhiteSpace($computerKey) -and $script:IndexComputersByName.ContainsKey($computerKey)) { return $script:IndexComputersByName[$computerKey] }
    return $null
}

function Sync-DomeniaLinksAgainstIndex {
    param([switch]$Full)
    if (@($script:UserMachineLinks).Count -eq 0 -or @($script:IndexRows).Count -eq 0) { return 0 }
    $changed = 0
    foreach ($link in @($script:UserMachineLinks)) {
        $userGuid = ""; $computerGuid = ""
        try { $userGuid = [string]$link.UserGuid } catch { Write-DomeniaSwallowed 'Core' 'Sync-DomeniaLinksAgainstIndex' $_ }
        try { $computerGuid = [string]$link.ComputerGuid } catch { Write-DomeniaSwallowed 'Core' 'Sync-DomeniaLinksAgainstIndex' $_ }
        # Point 9: a link carrying a GUID is matched by that GUID only. Once its object is gone, a namesake never
        # adopts it (rename keeps the GUID; a recycled name gets a new one); the link then stays unverified.
        $userRow = Find-DomeniaCachedUserRow -Login (Get-DomeniaLinkLookupName -Link $link -Kind User) -Guid $userGuid
        $computerRow = Find-DomeniaCachedComputerRow -Computer (Get-DomeniaLinkLookupName -Link $link -Kind Computer) -Guid $computerGuid
        if ($null -ne $userRow) {
            if ([string]$link.UserLogin -ine [string]$userRow.Login -and -not [string]::IsNullOrWhiteSpace([string]$userRow.Login)) { $link.UserLogin = Normalize-LinkUser ([string]$userRow.Login); $changed++ }
            if ($link.PSObject.Properties.Name -notcontains "UserGuid") { $link | Add-Member -NotePropertyName UserGuid -NotePropertyValue ([string]$userRow.Guid); $changed++ } elseif ([string]$link.UserGuid -ne [string]$userRow.Guid) { $link.UserGuid=[string]$userRow.Guid; $changed++ }
            if ($link.PSObject.Properties.Name -notcontains "UserDn") { $link | Add-Member -NotePropertyName UserDn -NotePropertyValue ([string]$userRow.DN); $changed++ } elseif ([string]$link.UserDn -ne [string]$userRow.DN) { $link.UserDn=[string]$userRow.DN; $changed++ }
        }
        if ($null -ne $computerRow) {
            if ([string]$link.Computer -ine [string]$computerRow.Name -and -not [string]::IsNullOrWhiteSpace([string]$computerRow.Name)) { $link.Computer = Normalize-LinkComputer ([string]$computerRow.Name); $changed++ }
            if ($link.PSObject.Properties.Name -notcontains "ComputerGuid") { $link | Add-Member -NotePropertyName ComputerGuid -NotePropertyValue ([string]$computerRow.Guid); $changed++ } elseif ([string]$link.ComputerGuid -ne [string]$computerRow.Guid) { $link.ComputerGuid=[string]$computerRow.Guid; $changed++ }
            if ($link.PSObject.Properties.Name -notcontains "ComputerDn") { $link | Add-Member -NotePropertyName ComputerDn -NotePropertyValue ([string]$computerRow.DN); $changed++ } elseif ([string]$link.ComputerDn -ne [string]$computerRow.DN) { $link.ComputerDn=[string]$computerRow.DN; $changed++ }
        }
        $verified = ($null -ne $userRow -and $null -ne $computerRow)
        if ($verified -or $Full) {
            $oldVerified = $false
            try { $oldVerified = [bool]$link.VerifiedInAD } catch { Write-DomeniaSwallowed 'Core' 'Sync-DomeniaLinksAgainstIndex' $_ }
            if ($oldVerified -ne $verified) { $link.VerifiedInAD = $verified; $changed++ }
        }
    }
    if ($changed -gt 0) { [void](Save-UserMachineLinks) } else { Rebuild-UserMachineLinkIndex }
    return $changed
}

function Get-DomeniaIndexAssociationText {
    param($Row)
    if ($null -eq $Row) { return "" }
    if ([string]$Row.Type -eq "Machine") {
        $links = @(Get-LinksForComputer -Computer ([string]$Row.Name) -Guid ([string](Get-DomeniaMember $Row 'Guid' '')))
        return (@($links | ForEach-Object { [string]$_.UserLogin } | Where-Object { $_ } | Sort-Object -Unique) -join ", ")
    }
    if ([string]$Row.Type -eq "Utilisateur") {
        $links = @(Get-LinksForUser -UserLogin ([string]$Row.Login) -Guid ([string](Get-DomeniaMember $Row 'Guid' '')))
        return (@($links | ForEach-Object { [string]$_.Computer } | Where-Object { $_ } | Sort-Object -Unique) -join ", ")
    }
    return ""
}

function Get-AssociationStatsText {
    $links = @($script:UserMachineLinks)
    $users = @($links | ForEach-Object { Normalize-LinkUser ([string]$_.UserLogin) } | Where-Object { $_ } | Sort-Object -Unique)
    $computers = @($links | ForEach-Object { Normalize-LinkComputer ([string]$_.Computer) } | Where-Object { $_ } | Sort-Object -Unique)
    $verified = @($links | Where-Object { ([string]$_.VerifiedInAD) -match "^(?i:true|1)$" }).Count
    return "Liens : $($links.Count)`r`nUtilisateurs : $($users.Count)`r`nMachines : $($computers.Count)`r`nVerifies AD : $verified"
}

function Get-AssociationSummaryForObject {
    param([string]$Type,[string]$Name,[string]$Login,[string]$Dns)
    if ($Type -eq "Machine") {
        $candidate = if (-not [string]::IsNullOrWhiteSpace($Dns)) { $Dns } elseif (-not [string]::IsNullOrWhiteSpace($Name)) { $Name } else { $Login }
        $links = @(Get-LinksForComputer $candidate)
        if ($links.Count -eq 0) { return "Aucun utilisateur associe." }
        $l = $links[0]
        if ($null -ne (Get-Command -Name Get-DomeniaLinkQualification -CommandType Function -ErrorAction SilentlyContinue)) {
            # D043: badge and rule of the link, never a percentage (relation model).
            $qualification = Get-DomeniaLinkQualification $l
            # CO-29: Date in local time (Get-DomeniaLinkQualification), the stored text only when unreadable.
            if ($qualification.Label -eq 'Qualification') { return "Utilisateur : $($l.UserLogin)`r`nSource : $($l.Source)`r`nQualification : $($qualification.Value) ($($qualification.Rule))`r`nDate : $($qualification.When)" }
        }
        return "Utilisateur : $($l.UserLogin)`r`nSource : $($l.Source)`r`nConfiance : $($l.Confidence)`r`nDate : $($l.When)"
    }
    if ($Type -eq "Utilisateur") {
        $candidate = if (-not [string]::IsNullOrWhiteSpace($Login)) { $Login } else { $Name }
        $links = @(Get-LinksForUser $candidate)
        if ($links.Count -eq 0) { return "Aucun poste associe." }
        $machines = @($links | ForEach-Object { [string]$_.Computer } | Where-Object { $_ } | Sort-Object -Unique)
        return "Postes : $($machines -join ", ")`r`nNombre : $($machines.Count)"
    }
    return "Aucune association pour ce type d objet."
}

function Set-RowAssociationMetadata {
    param($Rows)

    # L'association user-machine est un enrichissement local facultatif.
    # Elle ne doit jamais empecher l'affichage d'un resultat AD.
    $result = New-Object System.Collections.ArrayList
    $enrichmentErrors = 0
    # D043/DS-17: the LinkConfidence column carries the qualification label of the link (Get-DomeniaLinkQualification).
    $qualify = ($null -ne (Get-Command -Name Get-DomeniaLinkQualification -CommandType Function -ErrorAction SilentlyContinue))

    foreach ($row in @($Rows)) {
        if ($null -eq $row) { continue }

        $association = ""
        $source = ""
        $confidence = ""

        try {
            if ([string]$row.Type -eq "Machine") {
                $computerKey = [string]$row.UPN
                if ([string]::IsNullOrWhiteSpace($computerKey)) { $computerKey = [string]$row.Name }

                $links = @(Get-LinksForComputer -Computer $computerKey -Guid ([string](Get-DomeniaMember $row 'Guid' '')))
                if ($links.Count -gt 0) {
                    $association = [string]$links[0].UserLogin
                    $source = [string]$links[0].Source
                    $confidence = if ($qualify) { [string](Get-DomeniaLinkQualification $links[0]).Value } else { [string]$links[0].Confidence }
                }
            }
            elseif ([string]$row.Type -eq "Utilisateur") {
                $userKey = [string]$row.Login
                if ([string]::IsNullOrWhiteSpace($userKey)) { $userKey = [string]$row.Name }

                $links = @(Get-LinksForUser -UserLogin $userKey -Guid ([string](Get-DomeniaMember $row 'Guid' '')))
                if ($links.Count -gt 0) {
                    $association = (@($links | ForEach-Object { [string]$_.Computer } | Where-Object { $_ } | Sort-Object -Unique) -join ", ")
                    $source = (@($links | ForEach-Object { [string]$_.Source } | Where-Object { $_ } | Sort-Object -Unique) -join ", ")
                    if ($qualify) {
                        $bestLink = Select-DomeniaBestLink $links
                        if ($null -ne $bestLink) { $confidence = [string](Get-DomeniaLinkQualification $bestLink).Value }
                    }
                    else {
                        $bestLink = $links | Sort-Object `
                            @{ Expression = { try { [int]$_.Confidence } catch { 0 } }; Descending = $true }, `
                            @{ Expression = { [string]$_.When }; Descending = $true } | Select-Object -First 1
                        if ($null -ne $bestLink) { $confidence = [string]$bestLink.Confidence }
                    }
                }
            }
        }
        catch {
            $enrichmentErrors++
            if ($enrichmentErrors -le 3) {
                Write-AppLog "Association locale ignoree pour '$([string]$row.Name)' : $($_.Exception.Message)" "WARN"
            }
        }

        try { Set-DomeniaLiveRowValue $row "Association" $association } catch { Write-DomeniaSwallowed 'Core' 'Set-RowAssociationMetadata' $_ }
        try { Set-DomeniaLiveRowValue $row "LinkSource" $source } catch { Write-DomeniaSwallowed 'Core' 'Set-RowAssociationMetadata' $_ }
        try { Set-DomeniaLiveRowValue $row "LinkConfidence" $confidence } catch { Write-DomeniaSwallowed 'Core' 'Set-RowAssociationMetadata' $_ }
        [void]$result.Add($row)
    }

    if ($enrichmentErrors -gt 3) {
        Write-AppLog "$enrichmentErrors enrichissement(s) d'association locale ont ete ignores ; les resultats AD restent affiches." "WARN"
    }

    return @($result)
}

function Show-ObjectRows {
    param(
        $Rows,
        [string]$Label,
        [switch]$SkipPresenceScan,
        [switch]$NoAutoOpen,
        [AllowEmptyString()][string]$PreserveSelectionDn = ""
    )

    $previousWorkspace = ''
    try { $previousWorkspace = [string](Get-DomeniaControl -Name 'WorkspaceTabs').SelectedItem.Name } catch { Write-DomeniaSwallowed 'Core' 'Show-ObjectRows' $_ }
    $rawRows = @()
    if ($null -ne $Rows) { $rawRows = @($Rows) }
    try {
        Ensure-UserMachineLinkIndex
        $script:BranchObjects = @(
            foreach ($row in @(Set-RowAssociationMetadata -Rows $rawRows)) {
                $initialPresence = ""
                try {
                    if ($null -ne $row.PSObject.Properties["Presence"]) { $initialPresence = [string]$row.Presence }
                }
                catch { Write-DomeniaSwallowed 'Core' 'Show-ObjectRows' $_ }
                if ([string]::IsNullOrWhiteSpace($initialPresence) -or $initialPresence -eq "Inconnu") {
                    try { $initialPresence = Get-DomeniaCachedPresenceState -Dn ([string]$row.DN) } catch { $initialPresence = "" }
                }
                if ([string]::IsNullOrWhiteSpace($initialPresence)) {
                    $initialPresence = if ([string]$row.Type -eq "Machine" -and -not $SkipPresenceScan) { "Test en cours..." } else { "Inconnu" }
                }
                Add-Member -InputObject $row -NotePropertyName Presence -NotePropertyValue $initialPresence -Force
                # FI-16: the pill and the presence filter read this key, not the label above.
                $initialState = if ([string]$row.Type -eq "Machine") { ConvertTo-DomeniaPresenceStateKey $initialPresence } else { 'None' }
                Add-Member -InputObject $row -NotePropertyName PresenceState -NotePropertyValue $initialState -Force
                $row
            }
        )
    }
    catch {
        Write-AppLog "Enrichissement local ignore : $($_.Exception.Message)" "WARN"
        $script:BranchObjects = @($rawRows)
        foreach ($row in @($script:BranchObjects)) {
            try {
                if ($null -eq $row.PSObject.Properties["Presence"]) {
                    Add-Member -InputObject $row -NotePropertyName Presence -NotePropertyValue "Inconnu" -Force
                }
            }
            catch { Write-DomeniaSwallowed 'Core' 'Show-ObjectRows' $_ }
        }
    }

    # Une recherche depuis la base autonome peut etre selectionnee pendant que la
    # validation AD est encore en vol. Quand cette validation revient, elle doit
    # remplacer les lignes SANS deselectionner l'objet deja ouvert.
    $preserveDn = [string]$PreserveSelectionDn
    try {
        $selectedBefore = Get-DomeniaSelectedGridRow
        if ($null -ne $selectedBefore) { $preserveDn = ([string]$selectedBefore.DN).Trim() }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Show-ObjectRows' $_ }
    # Pour une recherche globale (-NoAutoOpen), seule une selection reellement
    # faite par l'operateur dans la grille peut etre conservee. Une ancienne fiche
    # ouverte ou une requete de selection en attente ne doit jamais provoquer une
    # preselection automatique dans le nouveau jeu de resultats.
    if (-not $NoAutoOpen) {
        if ([string]::IsNullOrWhiteSpace($preserveDn)) {
            try { if ($null -ne $script:PendingObjectSelection) { $preserveDn = ([string]$script:PendingObjectSelection.Dn).Trim() } } catch { Write-DomeniaSwallowed 'Core' 'Show-ObjectRows' $_ }
        }
        if ([string]::IsNullOrWhiteSpace($preserveDn)) {
            try { if ($null -ne $script:SelectedObject) { $preserveDn = ([string]$script:SelectedObject.DN).Trim() } } catch { Write-DomeniaSwallowed 'Core' 'Show-ObjectRows' $_ }
        }
    }

    $script:BranchCountLabel = [string]$Label
    $grid = Get-DomeniaControl -Name "DgObjects"
    $autoOpen = $false
    $selectionPreserved = $false
    $preservedRow = $null

    if (-not [string]::IsNullOrWhiteSpace($preserveDn)) {
        foreach ($candidate in @($script:BranchObjects)) {
            try {
                if ([string]$candidate.DN -ieq $preserveDn) { $preservedRow = $candidate; break }
            }
            catch { Write-DomeniaSwallowed 'Core' 'Show-ObjectRows' $_ }
        }
    }

    $script:SuppressGridSelectionEvents = $true
    try {
        if (-not (Set-DomeniaItemsSource -Name "DgObjects" -Rows $script:BranchObjects)) {
            throw "La grille des resultats n'a pas accepte la collection recue."
        }
        if ($null -ne $grid) {
            if ($null -ne $preservedRow) {
                $grid.SelectedItem = $preservedRow
                try { $grid.ScrollIntoView($preservedRow) } catch { Write-DomeniaSwallowed 'Core' 'Show-ObjectRows' $_ }
                $selectionPreserved = $true
            }
            else {
                $grid.SelectedItem = $null
            }
        }
    }
    finally {
        $script:SuppressGridSelectionEvents = $false
    }

    [void](Set-DomeniaControlText -Name "LblBranchCount" -Text $Label)

    try {
        if ($selectionPreserved) {
            # Ne touche ni a la fiche, ni a la requete objet, ni au timer de
            # selection : leur DN est encore present dans les resultats frais.
            Add-DomeniaUiLog -Area "Recherche" -Level "DEBUG" -Text ("Selection conservee apres actualisation des resultats : " + $preserveDn)
        }
        else {
            Stop-DomeniaSelectionOpenTimer
            $script:PendingObjectSelection = $null
            if ($autoOpen) {
                Queue-DomeniaSelectedObjectOpen -Immediate
            }
            else {
                $script:SelectionResetDn = ""
                Reset-DomeniaSelectionBoundViews
            }
        }
    }
    catch {
        Write-AppLog "Restauration de selection apres mise a jour des resultats impossible : $($_.Exception.Message)" "WARN"
    }

    if ($NoAutoOpen -and -not [string]::IsNullOrWhiteSpace($previousWorkspace)) {
        Select-DomeniaWorkspace -Workspace $previousWorkspace
    }
    Request-DomeniaDashboardRefresh

    # Rendering a result list never initiates a network scan. Explicit diagnostics remain available.
}


function Update-DomeniaLinkActionUi {
    param([int]$RowCount=0)
    Update-DomeniaRelationsActions
}

function Refresh-LinkGrid {
    param([switch]$All)
    # Compatibility switch: never changes the chosen tab or leaks all links into the selection.
    Refresh-DomeniaRelationViews
}

function Refresh-AssociationContext {
    param([switch]$SkipResultRefresh)
    $linksShown = $false
    try {
        if ($script:Ctrl.ContainsKey("TxtCompLinkedUser")) { $script:Ctrl["TxtCompLinkedUser"].Text = "" }
        if ($script:Ctrl.ContainsKey("TxtCompLinkSource")) { $script:Ctrl["TxtCompLinkSource"].Text = "" }
        if ($script:Ctrl.ContainsKey("TxtCompLinkConfidence")) { $script:Ctrl["TxtCompLinkConfidence"].Text = "" }
        if ($script:Ctrl.ContainsKey("TxtCompLinkWhen")) { $script:Ctrl["TxtCompLinkWhen"].Text = "" }
        if ($script:Ctrl.ContainsKey("TxtUserLinkedComputers")) { $script:Ctrl["TxtUserLinkedComputers"].ItemsSource = $null }
        if ($script:Ctrl.ContainsKey("LblUserLinkSummary")) { $script:Ctrl["LblUserLinkSummary"].Text = "Aucun poste associé." }
        # Point 9: identity of the displayed object (GUID, and whenCreated once its AD fiche was read); the associations of
        # a former holder of the same name stay out of this context.
        $selectedGuid = ConvertTo-DomeniaGuidText (Get-DomeniaMember $script:SelectedObject 'Guid' '')
        $selectedEntry = Get-DomeniaMemberValue $script:SelectedObject 'Entry'
        $selectedCreated = if ($null -ne $selectedEntry) { Get-DeProp $selectedEntry "whenCreated" $null } else { $null }

        if ($null -ne $script:SelectedObject -and [string]$script:SelectedObject.Type -eq "Machine") {
            $computer = Get-CurrentSelectedComputerName
            $links = @(Get-LinksForComputer -Computer $computer -Guid $selectedGuid -CreatedUtc $selectedCreated)
            if ($links.Count -gt 0) {
                $link = $links[0]
                $script:Ctrl["TxtCompLinkedUser"].Text = [string]$link.UserLogin
                $script:Ctrl["TxtCompLinkSource"].Text = [string]$link.Source
                $script:Ctrl["TxtCompLinkConfidence"].Text = if ($null -ne (Get-Command -Name Get-DomeniaLinkQualification -CommandType Function -ErrorAction SilentlyContinue)) { [string](Get-DomeniaLinkQualification $link).Value } else { [string]$link.Confidence }
                # CO-29: local time of the stored UTC date.
                $whenText = ''
                if ($null -ne (Get-Command Format-DomeniaRelationWhen -CommandType Function -ErrorAction SilentlyContinue)) { $whenText = Format-DomeniaRelationWhen ([string]$link.When) }
                if (-not $whenText) { $whenText = [string]$link.When }
                $script:Ctrl["TxtCompLinkWhen"].Text = $whenText
            }
            else {
                $activeProbe = Get-DomeniaRunningComputerUserProbe -Computer $computer
                $script:Ctrl["TxtCompLinkedUser"].Text = if ($null -ne $activeProbe) { 'Détection en cours...' } else { 'Non determine' }
                $script:Ctrl["TxtCompLinkSource"].Text = if ($null -ne $activeProbe) { 'Interrogation distante en cours' } else { 'Aucune association en cache ; détection disponible' }
            }
        }
        elseif ($null -ne $script:SelectedObject -and [string]$script:SelectedObject.Type -eq "Utilisateur") {
            $user = [string]$script:Ctrl["TxtUserSam"].Text
            $links = @(Get-LinksForUser -UserLogin $user -Guid $selectedGuid -CreatedUtc $selectedCreated)
            $computers = @($links | ForEach-Object { [string]$_.Computer } | Where-Object { $_ } | Sort-Object -Unique)
            if ($script:Ctrl.ContainsKey("TxtUserLinkedComputers")) {
                [void](Set-DomeniaItemsSource -Name "TxtUserLinkedComputers" -Rows $computers)
                if ($computers.Count -gt 0) { $script:Ctrl["TxtUserLinkedComputers"].SelectedIndex = 0 }
            }
            if ($script:Ctrl.ContainsKey("LblUserLinkSummary")) {
                $script:Ctrl["LblUserLinkSummary"].Text = if ($computers.Count -gt 0) { "$($computers.Count) poste(s) associe(s) : $($computers -join ', ')" } else { "Aucun poste associé." }
            }
        }
        $linksShown = $true
        Refresh-LinkGrid
        if (-not $SkipResultRefresh -and @($script:BranchObjects).Count -gt 0) {
            # Set-RowAssociationMetadata enrichit les objets existants en place.
            # Ne JAMAIS reaffecter ItemsSource ici : WPF deselectionne alors la
            # ligne courante, declenche DgObjects.SelectionChanged, puis
            # Queue-DomeniaSelectedObjectOpen purge toute la fiche avec
            # "Aucun objet selectionne". C'etait la regression V10.12 visible
            # juste apres la detection du dernier utilisateur.
            [void](Set-RowAssociationMetadata -Rows $script:BranchObjects)
            try {
                $grid = Get-DomeniaControl -Name "DgObjects"
                if ($null -ne $grid -and $null -ne $grid.Items) {
                    # Refresh garde la meme collection et le meme SelectedItem.
                    $grid.Items.Refresh()
                }
            }
            catch {
                Write-AppLog "Actualisation visuelle des associations ignoree : $($_.Exception.Message)" "WARN"
            }
        }
        Request-DomeniaDashboardRefresh
    }
    catch {
        Write-AppLog "Contexte association impossible : $($_.Exception.ToString())" "WARN"
        # P-CD-09: the fields cleared above do not stay on "no association" when the links of this object were not read.
        if (-not $linksShown) {
            try {
                if ($script:Ctrl.ContainsKey("TxtCompLinkedUser")) { $script:Ctrl["TxtCompLinkedUser"].Text = "Inconnu : associations illisibles" }
                if ($script:Ctrl.ContainsKey("TxtCompLinkSource")) { $script:Ctrl["TxtCompLinkSource"].Text = "Liens locaux non relus" }
                if ($script:Ctrl.ContainsKey("LblUserLinkSummary")) { $script:Ctrl["LblUserLinkSummary"].Text = "Associations illisibles : postes associés non vérifiés." }
            }
            catch { Write-DomeniaSwallowed 'Core' 'Refresh-AssociationContext' $_ }
        }
    }
}

function Start-OpenLinkedObject {
    param([ValidateSet("Utilisateur","Machine")][string]$Type,[string]$Identity)
    try {
        if ([string]::IsNullOrWhiteSpace($Identity)) { Set-Status "Aucune association sélectionnée." "WARN"; return }
        $escaped = Escape-LdapValue $Identity
        $filter = if ($Type -eq "Utilisateur") { "(&(objectCategory=person)(objectClass=user)(sAMAccountName=$escaped))" } else { "(&(objectCategory=computer)(|(name=$escaped)(sAMAccountName=$escaped`$)(dNSHostName=$escaped)))" }
        $code = @'
$s=New-WSearcher $Context ([string]$Context.BaseDn) ([string]$Payload.Filter) @("distinguishedName","name","objectClass") "Subtree" 1
$r=$s.FindOne()
if($null -eq $r){throw "Objet associe introuvable dans AD."}
[pscustomobject]@{DN=[string](Get-WPropFirst $r.Properties "distinguishedname" "");Name=[string](Get-WPropFirst $r.Properties "name" "")}
'@
        $linkedSuccess = {
            param($result,$state)
            Open-AdObject -Dn ([string]$result.DN) -Type ([string]$state.Type)
        }

        $linkedError = {
            param($message,$state)
            Set-Status "Association : $message" "ERROR"
        }

        Start-UiTask -Name "Ouverture association" -OperationId "OpenLinkedObject" -Code $code -Payload ([pscustomobject]@{Filter=$filter}) -CallbackState ([pscustomobject]@{ Type=$Type }) -ReplaceKey "openlinked" -DisableControls @("BtnOpenLinkedUser","BtnOpenLinkedComputer") -TimeoutSeconds 30 -StatusText "Recherche de l objet associe..." -OnSuccess $linkedSuccess -OnError $linkedError | Out-Null
    }
    catch { Set-Status "Association : $($_.Exception.Message)" "ERROR" }
}

function Open-LinkedUserFromMachine {
    # UI-17 / DS-08 (X04): the association kept in the local memory is the source; its DN opens the fiche directly,
    # the login is looked up otherwise. No placeholder text of the fiche is ever searched.
    $link = $null
    try { $link = Get-ExistingLinkForComputer -Computer (Get-CurrentSelectedComputerName) } catch { $link = $null }
    if (($null -eq $link) -or ([string]::IsNullOrWhiteSpace([string]$link.UserLogin))) { Set-Status "Aucun utilisateur associé à ce poste." "INFO"; return }
    $dn = ""
    try { $dn = [string]$link.UserDn } catch { $dn = "" }
    if ($dn) { Open-AdObject -Dn $dn -Type "Utilisateur"; return }
    Start-OpenLinkedObject -Type "Utilisateur" -Identity ([string]$link.UserLogin)
}

function Open-LinkedComputerFromUser {
    $computer = ""
    try { $computer = [string]$script:Ctrl["TxtUserLinkedComputers"].SelectedItem } catch { Write-DomeniaSwallowed 'Core' 'Open-LinkedComputerFromUser' $_ }
    Start-OpenLinkedObject -Type "Machine" -Identity $computer
}





