function Add-UserMachineLinkIfMissing {
    param([string]$UserLogin,[string]$Computer,[string]$Source="Manual",[string]$Details="",[int]$Confidence=100,[bool]$VerifiedInAD=$true,[string]$UserGuid="",[string]$ComputerGuid="",[string]$UserDn="",[string]$ComputerDn="",[string]$Declarant="")
    try {
        $u=Normalize-LinkUser $UserLogin; $c=Normalize-LinkComputer $Computer
        if ([string]::IsNullOrWhiteSpace($u) -or [string]::IsNullOrWhiteSpace($c)) { return $false }
        $userRow = Find-DomeniaCachedUserRow -Login $u -Guid $UserGuid
        $computerRow = Find-DomeniaCachedComputerRow -Computer $c -Guid $ComputerGuid
        $userGuid = if ($UserGuid) { $UserGuid } elseif ($null -ne $userRow) { [string]$userRow.Guid } else { "" }
        $computerGuid = if ($ComputerGuid) { $ComputerGuid } elseif ($null -ne $computerRow) { [string]$computerRow.Guid } else { "" }
        $userDn = if ($UserDn) { $UserDn } elseif ($null -ne $userRow) { [string]$userRow.DN } else { "" }
        $computerDn = if ($ComputerDn) { $ComputerDn } elseif ($null -ne $computerRow) { [string]$computerRow.DN } else { "" }
        if ($null -ne $userRow -and $null -ne $computerRow) { $VerifiedInAD = $true }

        # D042/D049/D050: one relation per user, workstation and nature (Resolve-DomeniaRelationUpsert in
        # Add-DomeniaRelation). Another account on the same workstation never overwrites a relation, a declared
        # assignment is never replaced by an observation, and no fixed score is stored (Confidence=0, unmeasured).
        # CO-29: the date is stored in UTC ISO 8601. CD-06: the RC1.10.7 replacement path is removed.
        $incoming = [pscustomobject]@{ UserLogin=$u; Computer=$c; Source=$Source; Confidence=0; VerifiedInAD=$VerifiedInAD; When=[datetime]::UtcNow.ToString('o'); Details=$Details; UserGuid=$userGuid; ComputerGuid=$computerGuid; UserDn=$userDn; ComputerDn=$computerDn; Kind=(Get-DomeniaRelationKind $Source) }
        $outcome = Add-DomeniaRelation -Relation $incoming -Declarant $Declarant
        $badge = Get-DomeniaEvidenceBadge $incoming
        if ($outcome.SaveFailed) { $msg = "Lien non enregistré : $u -> $c. $($outcome.Reason)"; Set-Status $msg "WARN"; Write-AppLog $msg "WARN"; return $false }
        if ($outcome.Action -eq 'Refresh') { Write-AppLog "Lien actualisé : $u -> $c ($Source, $($badge.Label))." "INFO"; Refresh-AssociationContext; return $false }
        if ($outcome.Placement -eq 'Session') { $msg = "Relation $u -> $c ($Source, $($badge.Label)) conservée pour la session. $($outcome.Reason)"; Set-Status $msg; Write-AppLog $msg "INFO"; Refresh-AssociationContext; return $false }
        $msg = "Lien ajouté : $u -> $c ($Source, $($badge.Label))."
        if ($outcome.Placement -eq 'Replace' -and $null -ne $outcome.Demoted) { $msg += " Relation précédente ($([string]$outcome.Demoted.UserLogin)) conservée pour la session." }
        Set-Status $msg; [void](Set-DomeniaControlText -Name "LblLinkProbeStatus" -Text $msg); Write-AppLog $msg
        return $true
    }
    catch {
        $detail = "Erreur ajout lien user-machine : $($_.Exception.Message)"
        Write-AppLog $detail "ERROR"
        Set-Status $detail "ERROR"
        [void](Set-DomeniaControlText -Name "LblLinkProbeStatus" -Text $detail)
        return $false
    }
}

function Remove-SelectedLink {
    try {
        if(Test-DomeniaAccessBusyWrite){return}
        $activeGrid=Get-DomeniaRelationsActiveGrid
        $row=if($null -ne $activeGrid){$activeGrid.SelectedItem}else{$null}
        if ($null -eq $row) { Set-Status "Sélectionnez une association à supprimer." "WARN"; return }
        # D050: the removal is journaled (declarant, source, dates) and can be restored; AD is never touched.
        # The exact row is removed, not every row sharing its login, workstation and date (CD-06: no other path).
        Request-DomeniaRelationRemoval -Relation $row
    }
    catch { Show-ErrorBox "Erreur suppression lien : $($_.Exception.Message)" }
}


function Show-DomeniaCommandPalette {
    # W13 (point 117): the palette is a view of the page (Domenia-Commands.UI.ps1, Domenia-CommandPalette.xaml): it
    # follows the selection and the rights, and a write only brings its own button forward. A second Ctrl+K closes it.
    try {
        if (Test-DomeniaCommandPaletteOpen) { Hide-DomeniaCommandPalette; return }
        if (-not (Show-DomeniaCommandPaletteView)) { Set-Status 'Palette indisponible : une demande attend votre réponse dans la page, ou la vue nʼa pas pu se charger (voir le journal).' 'WARN' }
    }
    catch { [void](Show-DomeniaOperationError -Operation 'Palette de commandes' -ErrorRecordOrException $_ -NoPopup) }
}


function Get-DomeniaCredentialUserName {
    param($Credential)
    try {
        if ($null -ne $Credential) { return ([string]$Credential.UserName).Trim() }
    } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaCredentialUserName' $_ }
    return ""
}

function New-DomeniaAccountAuthRequest {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string]$UserName,
        [Parameter(Mandatory=$true)][System.Security.SecureString]$Password,
        [ValidateRange(2,45)][int]$TimeoutSeconds = 8
    )
    $user = ([string]$UserName).Trim()
    if ([string]::IsNullOrWhiteSpace($user)) { throw 'Identifiant vide.' }
    if ($null -eq $Password -or $Password.Length -eq 0) { throw 'Mot de passe vide.' }
    if ($null -eq $script:Conn) { throw 'Connecte-toi a Active Directory avant de tester un compte secondaire.' }
    if ([bool]$script:DemoMode) {
        # D003: alternate account in demonstration. The typed password never leaves this panel: the request
        # carries no credential and the authentication runspace answers from the demo identity only.
        if (-not (Test-DomeniaDemoIdentity $user)) { throw 'Identite de demonstration attendue (DEMO\nom).' }
        return [pscustomobject]@{
            Login=$user; Credential=$null; UseCurrentCredentials=$false; DemoOnly=$true; DemoIdentity=$user
            ConfiguredServer=''; ConfiguredBase=([string]$script:Conn.BaseDn).Trim()
            Domain=[string]$script:Conn.Domain; Netbios=[string]$script:Conn.Netbios
            MaxServers=1; OverallTimeoutSeconds=$TimeoutSeconds; PerServerTimeoutSeconds=$TimeoutSeconds
        }
    }
    $server = ([string]$script:Conn.Server).Trim()
    $baseDn = ([string]$script:Conn.BaseDn).Trim()
    if ([string]::IsNullOrWhiteSpace($server) -or [string]::IsNullOrWhiteSpace($baseDn)) {
        throw 'Contexte AD incomplet : reconnecte DOMENIA pour obtenir le controleur et la base AD.'
    }
    # Reutiliser exactement le moteur du login et son contexte deja decouvert.
    # Aucun mot de passe utilise pour essayer une succession de domaines/identites.
    # Copie privee : la fermeture du champ WPF ne peut pas invalider le worker.
    $passwordCopy = $Password.Copy()
    try {
        $passwordCopy.MakeReadOnly()
        $credential = [System.Management.Automation.PSCredential]::new($user,$passwordCopy)
        return [pscustomobject]@{
            Login=$user; Credential=$credential; UseCurrentCredentials=$false
            ConfiguredServer=$server; ConfiguredBase=$baseDn
            Domain=[string]$script:Conn.Domain; Netbios=[string]$script:Conn.Netbios
            MaxServers=1; OverallTimeoutSeconds=$TimeoutSeconds; PerServerTimeoutSeconds=$TimeoutSeconds
        }
    }
    catch { $passwordCopy.Dispose(); throw }
}

function Test-DomeniaCredentialBind {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][string]$UserName,[Parameter(Mandatory=$true)][Security.SecureString]$Password,[string]$Operation='Test du compte',[ValidateRange(2,45)][int]$TimeoutSeconds=12)
    return Start-DomeniaAccountValidation -UserName $UserName -Password $Password -Operation $Operation -TimeoutSeconds $TimeoutSeconds
}

function Update-DomeniaAccountUi {
    # IMPORTANT : cette fonction ne touche JAMAIS aux champs editables.
    # Les evenements GotFocus/Click remontent depuis les enfants du TabItem ;
    # recharger TxtAccount* ici effacait donc la saisie des que l utilisateur
    # changeait de champ ou cliquait sur Tester/Activer.
    try {
        $ad = Get-DomeniaControl -Name "LblAccountAdIdentity"
        $adStatus = Get-DomeniaControl -Name "LblAccountAdStatus"
        $remote = Get-DomeniaControl -Name "LblAccountRemoteIdentity"
        $remoteStatus = Get-DomeniaControl -Name "LblAccountRemoteStatus"
        $secrets = Get-DomeniaControl -Name "LblAccountSecretsIdentity"
        $secretsStatus = Get-DomeniaControl -Name "LblAccountSecretsStatus"

        Update-DomeniaExperienceIdentity
        # CO-31: read-only card, the account that really bound the directory and how; no field to edit.
        $currentAd = [string]$script:Conn.BindUser
        if ([string]::IsNullOrWhiteSpace($currentAd)) { $currentAd = [string]$script:Conn.User }
        $card = Get-DomeniaDirectoryAccountText -Account $currentAd -AuthMode ([string]$script:Conn.AuthMode) -Server ([string]$script:Conn.Server) -Domain ([string]$script:Conn.Domain)
        if ($null -ne $ad) { $ad.Text = [string]$card.Identity }
        if ($null -ne $adStatus) { $adStatus.Text = [string]$card.Detail }

        $remoteCred = $script:RemoteAdminCredential
        $remoteName = Get-DomeniaCredentialUserName $remoteCred
        if ($null -ne $remote) { $remote.Text = if ($remoteName) { "$remoteName  ·  compte Postes actif" } else { 'Aucun compte Postes : le compte de connexion sert aux postes.' } }
        if ($null -ne $remoteStatus) { $remoteStatus.Text = if ($remoteName) { 'Les opérations sur les postes utilisent ce compte pendant cette session. Le coffre Windows reste facultatif.' } else { 'Saisissez un compte et son mot de passe puis « Activer » si les postes exigent dʼautres droits.' } }

        $secretCred = $script:SecretsCredential
        $secretName = Get-DomeniaCredentialUserName $secretCred
        if ($null -ne $secrets) { $secrets.Text = if ($secretName) { "$secretName  ·  compte Secrets actif" } else { 'Aucun compte Secrets : le compte de connexion lit LAPS et BitLocker.' } }
        if ($null -ne $secretsStatus) { $secretsStatus.Text = if ($secretName) { 'LAPS et BitLocker utilisent ce compte pendant cette session. Le coffre Windows reste facultatif.' } else { 'Saisissez un compte et son mot de passe puis « Activer » si les secrets exigent dʼautres droits.' } }

        Update-DomeniaRemoteTrialUi
        # UI-27: no forced rebuild here. GotFocus bubbles from the « Oublier » buttons themselves: rebuilding the grid
        # on mouse down would remove the button before its Click. The rows change only when a text changes.
        Update-DomeniaAccountsInUse
        try {
            $remoteClear = Get-DomeniaControl -Name "BtnAccountRemoteClear"
            $secretClear = Get-DomeniaControl -Name "BtnAccountSecretsClear"
            if ($null -ne $remoteClear) { $remoteClear.IsEnabled = ($null -ne $remoteCred) }
            if ($null -ne $secretClear) { $secretClear.IsEnabled = ($null -ne $secretCred) }
        } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaAccountUi' $_ }
        # Point 44: the in-place correction of the connection account exists for an explicit sign-in only; its row of the
        # read-only Annuaire card (CO-31) is hidden otherwise. Which account each use takes, its origin and what the
        # protection recorded (point 42), with the names the directory confirmed (point 45), are in « En ce moment ».
        try {
            $correctable = (([bool]$script:Conn.UseCredential) -and ($null -ne $script:Conn.Credential) -and (-not [bool]$script:DemoMode))
            foreach ($name in @('PwdAccountAdCorrection','BtnAccountAdCorrect')) {
                $control = Get-DomeniaControl -Name $name
                if (($null -ne $control) -and (-not (Test-DomeniaControlIsBusy -Name $name))) { $control.IsEnabled = $correctable }
            }
            $correct = Get-DomeniaControl -Name 'BtnAccountAdCorrect'
            if (($null -ne $correct) -and ($correct.Parent -is [Windows.UIElement])) {
                $shown = if ($correctable) { [Windows.Visibility]::Visible } else { [Windows.Visibility]::Collapsed }
                if ($correct.Parent.Visibility -ne $shown) { $correct.Parent.Visibility = $shown }
            }
        } catch { Write-AppLog "Correction du compte de connexion non affichée : $($_.Exception.Message)" "WARN" }
    }
    catch { Write-AppLog "Mise à jour de la page Comptes impossible : $($_.Exception.Message)" "WARN" }
}

function Save-DomeniaSecondaryCredential {
    [CmdletBinding()]
    param([ValidateSet('Remote','Secrets')][string]$Scope,[string]$UserName,[Security.SecureString]$Password)
    $remember=Get-DomeniaControl ('ChkAccount'+$Scope+'Remember')
    [void](Start-DomeniaAccountValidation -UserName $UserName -Password $Password -Operation ('Activation compte '+$Scope) -ActivateScope $Scope -RememberSecret:($null -ne $remember -and [bool]$remember.IsChecked))
}

function Clear-DomeniaSecondaryCredential {
    param([ValidateSet("Remote","Secrets")][string]$Scope)
    if ($Scope -eq "Remote") {
        $script:RemoteAdminCredential = $null
        Set-DomeniaSetting -Name "RemoteCredentialUser" -Value ""
        [void](Save-DomeniaAccountPreference -Scope Remote -UserName '')
        $userField=Get-DomeniaControl -Name 'TxtAccountRemoteUser';if($null -ne $userField){$userField.Text=''}
        $pwd = Get-DomeniaControl -Name "PwdAccountRemote"; if ($null -ne $pwd) { $pwd.Password = "" }
        Add-DomeniaUiLog -Area "Comptes" -Text "Compte Postes effacé de la mémoire."
    } else {
        $script:SecretsCredential = $null
        Set-DomeniaSetting -Name "SecretsCredentialUser" -Value ""
        [void](Save-DomeniaAccountPreference -Scope Secrets -UserName '')
        $userField=Get-DomeniaControl -Name 'TxtAccountSecretsUser';if($null -ne $userField){$userField.Text=''}
        $pwd = Get-DomeniaControl -Name "PwdAccountSecrets"; if ($null -ne $pwd) { $pwd.Password = "" }
        Add-DomeniaUiLog -Area "Comptes" -Text "Compte Secrets effacé de la mémoire."
    }
    if($null -ne $script:AccessState){
        $scopes=if($Scope -eq 'Secrets'){@('ReadLaps','ReadBitLocker')}else{@('Remote')}
        foreach($k in $scopes){[void]$script:AccessState.Credentials.Remove($k);[void]$script:AccessState.Faults.Remove($k)}
        $script:DomeniaAccountGeneration=[long]$script:DomeniaAccountGeneration+1
        if($Scope -eq 'Secrets'){$script:AccessState.Denied=@{}}
    }
    Update-DomeniaAccountUi
    Set-Status ('Compte ' + $(if ($Scope -eq 'Remote') { 'Postes' } else { 'Secrets' }) + ' effacé : le compte de connexion reprend ce rôle.')
}

function Start-DomeniaAccountRelogin {
    try {
        Complete-DomeniaDetachedReadJobs
        if (@($script:AsyncJobs.Keys).Count -gt 0 -or @($script:DetachedReadJobs).Count -gt 0) {
            Show-InfoBox 'Changement de compte refusé pendant une opération. Terminez ou annulez les lectures, puis attendez leur nettoyage. Une écriture envoyée au contrôleur nʼest jamais interrompue.'
            return
        }
        if ([string]$script:WriteState -in @('Running','Unknown','UnknownPending')) {
            Show-InfoBox 'Une écriture reste à vérifier. Contrôlez son résultat avant de changer de compte.'
            return
        }
        # Persist dirty data using the previous connection scope, before opening the login.
        if ([bool]$script:IndexDirty -and -not (Flush-DomeniaIndex)) {
            throw 'Le cache modifié ne peut pas être enregistré. Changement de compte interrompu pour garder les données en mémoire.'
        }
        $previousBase = [string]$script:Conn.BaseDn
        # CO-31: the sign-in is pre-filled with the account typed for this session; nothing is written in the settings
        # (the sign-in reads only Auth.LastLogin, saved by its own Se souvenir de mon identifiant box).
        $prefill = ''
        if ([string]$script:Conn.AuthMode -eq 'Explicit') {
            $prefill = ([string]$script:Conn.User).Trim()
            if ([string]::IsNullOrWhiteSpace($prefill)) { $prefill = ([string]$script:Conn.BindUser).Trim() }
        }
        try { if ($null -ne $script:LiveSearchTimer) { $script:LiveSearchTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaAccountRelogin' $_ }
        Stop-DomeniaSelectionOpenTimer
        # UX-28: a change of account opens the form first; the Windows session stays proposed under it.
        if (-not (Show-LoginWindow -PreferForm -PrefillLogin $prefill)) { Set-Status 'Changement de compte annulé : la session courante est conservée.' 'WARN'; return }

        $script:SessionEpoch = [long]$script:SessionEpoch + 1
        # Fleet observations and analysis targets belong to the previous session.
        $script:FleetObservations = $null; $script:FleetLast = $null; $script:FleetComputedKey = ''; $script:FleetStale = $true
        $script:FleetQuerySnapshotKey='';if($null -ne $script:DomeniaQueryState){$script:DomeniaQueryState.Generation++;$script:DomeniaQueryState.Records=$null;$script:DomeniaQueryState.Widgets=@{};$script:DomeniaQueryState.SearchRecipe=$null;$script:DomeniaQueryState.SearchRecords=@{}}
    try { Reset-DomeniaSupportSession } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaAccountRelogin' $_ }
        $script:GlobalSearchGeneration++
        $script:PresenceScanGeneration++
        $script:SelectedObjectGeneration++
        Clear-DomeniaTreeRenderJobs
        Clear-Secrets
        Clear-ObjectDetails
        $script:SelectedObject = $null
        $script:LastLoadedEntry = $null
        $script:PendingObjectSelection = $null
        $script:CurrentObjectRequestId = ''
        $script:CurrentObjectRequestDn = ''
        $script:DeferredRawDn = ''; $script:DeferredPermissionsDn = ''; $script:DeferredTargetDn = ''
        $script:VisitCache = @{}; $script:PresenceCache = @{}
        $script:StartupWarmCache = $null; $script:ShowingCachedObject = $false
        $script:ActualSecretDeniedDn = ''; $script:ComputerDiagRows = @()
        $script:LinkIndexGeneration++
        $script:CurrentCapabilities = @{}; $script:ActualDeniedCapabilities = @{}
        $script:PermissionRows = @(); $script:SelfCheckRows = @()
        $script:IndexRows = @(); $script:IndexInfo = $null; $script:IndexDirty = $false
        $script:IndexUsersByLogin = @{}; $script:IndexUsersByGuid = @{}
        $script:IndexComputersByName = @{}; $script:IndexComputersByGuid = @{}
        $script:UserMachineLinks = @(); $script:LinkByComputer = @{}; $script:LinksByUser = @{}; $script:LinkIndexCount = -1
        $script:ParkState = @{}
        $script:InventoryRows = @(); $script:InventoryAccess = @()
        $script:SoftwareRows = @(); $script:SoftwareAccess = @()
        $script:InventoryComputer = ''; $script:InventoryCompletedAt = $null
        $script:InventoryCacheByComputer = @{}
        $script:SoftwareSource = ''; $script:SoftwareProvenance = ''
        $script:SoftwareChartSelect = $null; Update-DomeniaSoftwareFilterChip
        $script:DomainRows = @(); $script:WmiNamespaces = @(); $script:WmiClasses = @(); $script:WmiSchema = @(); $script:WmiInstances = @()
        $script:WorkerContextStatic = $null
        $script:DirectoryCredentialFaulted = $false; $script:DirectoryCredentialFaultMessage = ''
        $script:DatabaseScopeIdentity = ''; $script:DatabaseScopedPath = ''; $script:DomeniaDatabaseReady = $false
        $script:ReadOnlyMode = $true
        $readOnly = Get-DomeniaControl -Name 'ChkReadOnlyMode'
        if ($null -ne $readOnly) { $readOnly.IsChecked = $true }
        # Clear all previously bound result grids, including cached permission reports.
        foreach ($control in @($script:Ctrl.Values)) {
            if ($control -is [System.Windows.Controls.DataGrid]) { $control.ItemsSource = $null }
        }
        $script:RemoteAdminCredential = $null; $script:SecretsCredential = $null; $script:MachineCredential = $null
        Clear-DomeniaAccessAccounts
        # The base of the new session is opened as at startup: schema created or migrated here (Initialize-DomeniaDatabase).
        # Its content is read by the LocalIndexRead worker (FI-19): the figures and the associations complete the views
        # when they arrive; the associations reloaded from the base also end a conflict state (D028).
        Reset-DomeniaIndexMetadataState
        # No reference of the previous base survives the change of session (D028): the associations are empty here.
        $script:LinkLoad = $null
        Reset-DomeniaLinkBaseline
        try {
            [void](Initialize-DomeniaDatabase)
            Request-DomeniaIndexMetadata
            Request-DomeniaUserMachineLinks
        }
        catch {
            $script:IndexMetadataError = [string]$_.Exception.Message
            Write-AppLog ('Base locale de la nouvelle session indisponible : ' + $script:IndexMetadataError) 'ERROR'
        }
        Update-DomeniaIndexStats
        Load-TreeRoot
        # Point 57: the personal views listed are those of the domain of the new session.
        try { Reset-DomeniaSearchWorkspaceSession } catch { Write-AppLog ("Vues personnelles : " + $_.Exception.Message) "WARN" }
        Initialize-DomeniaAccountPanel
        Update-DomeniaAccountUi
        Apply-CurrentPermissionUi
        Request-DomeniaDashboardRefresh
        try { Request-DomeniaFleetRefresh -Force } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaAccountRelogin' $_ }
        Set-Status ('Nouvelle session : ' + [string]$script:Conn.BindUser + '. Vues rechargées, lecture seule active.')
    }
    catch { [void](Show-DomeniaOperationError -Operation 'Changement de compte' -ErrorRecordOrException $_) }
}

function Initialize-DomeniaAccountPanel {
    try {
        Initialize-DomeniaAccountPreferences
        $savedRemote = Get-DomeniaRememberedAccount -Scope Remote
        $savedSecrets = Get-DomeniaRememberedAccount -Scope Laps
        $currentAd = [string]$script:Conn.BindUser
        if ([string]::IsNullOrWhiteSpace($currentAd)) { $currentAd = [string]$script:Conn.User }
        $remoteUser = Get-DomeniaControl -Name "TxtAccountRemoteUser"
        $secretUser = Get-DomeniaControl -Name "TxtAccountSecretsUser"
        if ($null -ne $remoteUser) { $remoteUser.Text = $savedRemote;$script:AccountPreferences.FieldSeeds['TxtAccountRemoteUser']=$savedRemote }
        if ($null -ne $secretUser) { $secretUser.Text = $savedSecrets;$script:AccountPreferences.FieldSeeds['TxtAccountSecretsUser']=$savedSecrets }
        Sync-DomeniaAccountPreferences
        Update-DomeniaAccountUi
        Add-DomeniaUiLog -Area "Comptes" -Text "Page Comptes prête : champs modifiables conservés aux changements de focus, coffre Windows seulement sur choix explicite."
    }
    catch { Add-DomeniaUiLog -Area "Comptes" -Level "WARN" -Text "Initialisation panneau comptes : $($_.Exception.Message)" }
}

function Wire-Events {
    Register-DomeniaReliabilityUi
    Initialize-DomeniaAccountVaultUi
    Add-DomeniaUiLog -Area "Interface" -Level "INFO" -Text "Branchement des evenements de l'interface."

    

    if ($script:Ctrl.ContainsKey("BtnCommandPalette")) {
        $script:Ctrl["BtnCommandPalette"].Add_Click({ Show-DomeniaCommandPalette })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountsHeader")) {
        $script:Ctrl["BtnAccountsHeader"].Add_Click({ Select-DomeniaWorkspace -Workspace "TabAccounts"; Update-DomeniaAccountUi })
    }
    if ($script:Ctrl.ContainsKey("BtnThemeToggle")) {
        $script:Ctrl["BtnThemeToggle"].IsEnabled = $true
        $script:Ctrl["BtnThemeToggle"].IsHitTestVisible = $true
        $script:Ctrl["BtnThemeToggle"].Add_Click({ Toggle-DomeniaTheme })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountAdRelogin")) {
        $script:Ctrl["BtnAccountAdRelogin"].Add_Click({ Start-DomeniaAccountRelogin })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountAdCorrect")) {
        # Point 44: correct the password of the connection account in place, without reconnecting Domenia. Another
        # account goes through « Changer de compte » (CO-31: the identity of the card is read-only).
        $script:Ctrl["BtnAccountAdCorrect"].Add_Click({
            try { Start-DomeniaDirectoryCorrection }
            catch { [void](Show-DomeniaOperationError -Operation "Correction du compte de connexion" -ErrorRecordOrException $_) }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountRemoteTry")) {
        # FO-19: Tester only repeated the AD authentication of Activer; the real question is the right on a workstation.
        $script:Ctrl["BtnAccountRemoteTry"].Add_Click({
            try { Start-DomeniaRemoteAccountTrial } catch { [void](Show-DomeniaOperationError -Operation "Essai du compte poste" -ErrorRecordOrException $_) }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountRemoteSave")) {
        $script:Ctrl["BtnAccountRemoteSave"].Add_Click({
            try {
                Save-DomeniaSecondaryCredential -Scope Remote -UserName ([string]$script:Ctrl["TxtAccountRemoteUser"].Text) -Password ($script:Ctrl["PwdAccountRemote"].SecurePassword)
            } catch { [void](Show-DomeniaOperationError -Operation "Activation compte Remote" -ErrorRecordOrException $_) }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountRemoteClear")) {
        $script:Ctrl["BtnAccountRemoteClear"].Add_Click({ Clear-DomeniaSecondaryCredential -Scope Remote })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountSecretsTest")) {
        $script:Ctrl["BtnAccountSecretsTest"].Add_Click({
            try {
                $u = ([string]$script:Ctrl["TxtAccountSecretsUser"].Text).Trim()
                $p = $script:Ctrl["PwdAccountSecrets"].SecurePassword
                [void](Test-DomeniaCredentialBind -UserName $u -Password $p -Operation "Test compte Secrets")
            } catch { [void](Show-DomeniaOperationError -Operation "Test compte Secrets" -ErrorRecordOrException $_) }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountSecretsSave")) {
        $script:Ctrl["BtnAccountSecretsSave"].Add_Click({
            try {
                Save-DomeniaSecondaryCredential -Scope Secrets -UserName ([string]$script:Ctrl["TxtAccountSecretsUser"].Text) -Password ($script:Ctrl["PwdAccountSecrets"].SecurePassword)
            } catch { [void](Show-DomeniaOperationError -Operation "Activation compte Secrets" -ErrorRecordOrException $_) }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnAccountSecretsClear")) {
        $script:Ctrl["BtnAccountSecretsClear"].Add_Click({ Clear-DomeniaSecondaryCredential -Scope Secrets })
    }
    Initialize-DomeniaRelationsUi
    if ($script:Ctrl.ContainsKey("TabAccounts")) {
        $script:Ctrl["TabAccounts"].Add_GotFocus({ try { Update-DomeniaAccountUi } catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ } })
    }

    if ($script:Ctrl.ContainsKey("BtnClearUiLog")) {
        $script:Ctrl["BtnClearUiLog"].Add_Click({
            Add-DomeniaUiLog -Area "Interface" -Level "INFO" -Text "Effacement manuel du journal demande."
            Clear-DomeniaUiLog
        })
    }
    
    if ($script:Ctrl.ContainsKey("CmbPresenceFilter")) {
        $script:Ctrl["CmbPresenceFilter"].Add_SelectionChanged({
            try {
                $item = $script:Ctrl["CmbPresenceFilter"].SelectedItem
                $script:CurrentPresenceFilter = if ($null -ne $item) { [string]$item.Content } else { "Tous" }
                # UX-03: a session filter, never saved in the preferences.
                Apply-DomeniaPresenceFilter
                # Presence is only filtered from known data; no implicit scan on a filter change.
                Add-DomeniaUiLog -Area "Filtre" -Text "Presence : $($script:CurrentPresenceFilter)"
            }
            catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ }
        })
    }
    if ($script:Ctrl.ContainsKey("LstUiProfile")) {
        # UI-30: explicit Essentiel | Expert choice at the foot of the menu, the only place that changes the profile.
        $script:Ctrl["LstUiProfile"].Add_SelectionChanged({
            try {
                $item = $script:Ctrl["LstUiProfile"].SelectedItem
                $profile = if ($null -ne $item -and [string]$item.Tag -eq "Admin") { "Admin" } else { "Tech" }
                if ($profile -ne $script:CurrentUiProfile) { Apply-DomeniaUiProfile -Profile $profile }
            }
            catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ }
        })
    }

    $script:Ctrl["BtnTreeRefresh"].Add_Click({ Load-TreeRoot -ForceRefresh })
    $script:Ctrl["ChkSubtree"].Add_Checked({ Invoke-DomeniaSearchFilterChanged })
    $script:Ctrl["ChkSubtree"].Add_Unchecked({ Invoke-DomeniaSearchFilterChanged })
    # PF-14: a change of object type waits 300 ms, so that scrolling through the list sends one request only.
    $script:Ctrl["CmbGlobalType"].Add_SelectionChanged({ Request-DomeniaSearchFilterChanged -Source Type })
    $script:Ctrl["BtnLoadBranch"].Add_Click({ Load-BranchObjects -Browse })
    $script:Ctrl["BtnClearBranch"].Add_Click({ Clear-DomeniaGlobalSearch })
    $script:Ctrl["BtnGlobalSearch"].Add_Click({
        try { Invoke-GlobalSearch -SearchMode Global }
        catch {
            Write-AppLog "Clic Recherche : $($_.Exception.ToString())" "ERROR"
            Set-Status "La recherche n'a pas pu etre lancee : $($_.Exception.Message)" "ERROR"
        }
    })
    $script:Ctrl["BtnGlobalClear"].Add_Click({ Clear-DomeniaGlobalSearch })
    $script:Ctrl["TxtGlobalSearch"].Add_KeyDown({
        param($s,$e)
        if ($e.Key -eq "Enter") {
            $e.Handled = $true
            try { Invoke-GlobalSearch -SearchMode Global }
            catch {
                Write-AppLog "Recherche Entree : $($_.Exception.ToString())" "ERROR"
                Set-Status "La recherche n'a pas pu etre lancee : $($_.Exception.Message)" "ERROR"
            }
        }
    })

    $script:Ctrl["BtnDashCopy"].Add_Click({ Copy-DashboardSummary })
    $script:Ctrl["TxtBranchSearch"].Add_KeyDown({ param($s,$e) if ($e.Key -eq "Enter") { Load-BranchObjects -Browse } })
    $script:Ctrl["CmbObjectFilter"].Add_SelectionChanged({ if ($script:Window -and $script:Conn.Connected -and -not [string]::IsNullOrWhiteSpace($script:SelectedBranchDn)) { Load-BranchObjects -Browse } })
    Initialize-DomeniaSelectionPreload
    $script:Ctrl["DgObjects"].Add_SelectionChanged({
        param($sender,$e)
        if($e.OriginalSource -eq $sender){Update-DomeniaSearchActionStates;Queue-DomeniaSelectedObjectOpen}
    })
    $script:Ctrl["DgObjects"].Add_IsEnabledChanged({ Update-DomeniaSearchActionStates })
    $script:Ctrl["DgObjects"].Add_PreviewMouseRightButtonDown({
        param($sender,$e)
        try {
            $node = $e.OriginalSource
            while ($null -ne $node -and -not ($node -is [System.Windows.Controls.DataGridRow])) {
                try { $node = [System.Windows.Media.VisualTreeHelper]::GetParent($node) }
                catch { try { $node = $node.Parent } catch { $node = $null } }
            }
            # SP-05 / FO-18: a right click inside the selection keeps it (copy or export of several rows); elsewhere
            # it selects the clicked row only.
            if ($null -ne $node -and $null -ne $node.Item -and -not [bool]$node.IsSelected) {
                $sender.SelectedItem = $node.Item
                $sender.CurrentItem = $node.Item
                $node.IsSelected = $true
            }
        }
        catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ }
    })
    $script:Ctrl["DgObjects"].Add_PreviewMouseLeftButtonUp({
        param($sender,$e)
        $container=[Windows.Controls.ItemsControl]::ContainerFromElement($sender,$e.OriginalSource)
        if($container -is [Windows.Controls.DataGridRow]){Queue-DomeniaSelectedObjectOpen}
    })
    $script:Ctrl["DgObjects"].Add_MouseDoubleClick({
        param($sender,$e)
        $container=[Windows.Controls.ItemsControl]::ContainerFromElement($sender,$e.OriginalSource)
        if($container -is [Windows.Controls.DataGridRow] -and @($sender.SelectedItems).Count -eq 1){
            Open-SelectedObject
            $e.Handled=$true
        }
    })
    $script:Ctrl["DgObjects"].Add_KeyDown({
        param($s,$e)
        if ($e.Key -eq "Enter" -and @($s.SelectedItems).Count -eq 1) {
            Open-SelectedObject
            $e.Handled = $true
        }
    })
    $script:Ctrl["BtnCopyObjectSummary"].Add_Click({ Copy-ObjectSummary })
    if ($script:Ctrl.ContainsKey("TxtObjDn")) {
        $dnMenu = New-Object System.Windows.Controls.ContextMenu
        [void]$dnMenu.Items.Add((New-DomeniaMenuItem -Header "Copier le DN" -Action {
            if ($null -ne $script:SelectedObject -and -not [string]::IsNullOrWhiteSpace([string]$script:SelectedObject.DN)) {
                Set-ClipboardSafe ([string]$script:SelectedObject.DN)
                Set-Status "DN copie."
            }
        }))
        [void]$dnMenu.Items.Add((New-DomeniaMenuItem -Header "Copier le nom" -Action {
            if ($null -ne $script:SelectedObject) { Set-ClipboardSafe ([string]$script:SelectedObject.Name); Set-Status "Nom copie." }
        }))
        [void]$dnMenu.Items.Add((New-Object System.Windows.Controls.Separator))
        [void]$dnMenu.Items.Add((New-DomeniaMenuItem -Header "Ouvrir le parent" -Action { Open-SelectedParentBranch }))
        $script:Ctrl["TxtObjDn"].ContextMenu = $dnMenu
    }
    $script:Ctrl["BtnOpenParentBranch"].Add_Click({ Open-SelectedParentBranch })
    # FI-21: rereads the open object only (its cached reads by GUID or DN are dropped), never the list.
    $script:Ctrl["BtnObjectReread"].Add_Click({ Refresh-SelectedObject })
    # UX-27 : la suppression ne se clique plus a cote des boutons de lecture. Elle se choisit dans « Plus… »,
    # et garde ses deux confirmations : le nom de l'objet a saisir, puis SUPPRIMER.
    $more = $script:Ctrl["BtnObjectMore"]
    if ($null -ne $more) {
        $moreMenu = New-Object System.Windows.Controls.ContextMenu
        [void]$moreMenu.Items.Add((New-DomeniaMenuItem -Header "Supprimer lʼobjet" -ToolTip "Supprime définitivement lʼobjet, sans récursivité. Le nom de lʼobjet est demandé pour confirmer." -Action { Delete-SelectedObject }))
        $more.ContextMenu = $moreMenu
        $more.Add_Click({
            param($sender,$e)
            if ($null -ne $sender.ContextMenu) {
                $sender.ContextMenu.PlacementTarget = $sender
                $sender.ContextMenu.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Bottom
                $sender.ContextMenu.IsOpen = $true
            }
        })
    }
    $script:Ctrl["BtnUserSave"].Add_Click({ Save-UserProfile })
    $script:Ctrl["BtnUserEdit"].Add_Click({ Start-DomeniaFicheEdit -Type "Utilisateur" })
    $script:Ctrl["BtnUserCancelEdit"].Add_Click({ Stop-DomeniaFicheEdit -Type "Utilisateur" -Restaurer })
    Register-DomeniaFicheEditWatch
    $script:Ctrl["BtnUserUnlock"].Add_Click({ Unlock-UserAccount })
    $script:Ctrl["BtnUserEnable"].Add_Click({ Set-AccountDisabled $false })
    $script:Ctrl["BtnUserDisable"].Add_Click({ Set-AccountDisabled $true })
    $script:Ctrl["BtnRevealUserNew"].Add_Click({ Toggle-PasswordBox "PwdUserNew" "TxtUserNewVisible" "BtnRevealUserNew" "__UserNewReveal" })
    $script:Ctrl["BtnRevealUserConfirm"].Add_Click({ Toggle-PasswordBox "PwdUserConfirm" "TxtUserConfirmVisible" "BtnRevealUserConfirm" "__UserConfirmReveal" })
    $script:Ctrl["BtnUserGenPassword"].Add_Click({ Show-DomeniaGeneratedPassword })
    $script:Ctrl["BtnUserSupportUnlock"].Add_Click({ Unlock-UserAccount })
    $script:Ctrl["BtnUserSupportLockouts"].Add_Click({ Start-DomeniaLockoutEventRead })
    $script:Ctrl["BtnUserLogonByDc"].Add_Click({ Start-DomeniaLogonByDcRead -Kind User })
    $script:Ctrl["BtnCompLogonByDc"].Add_Click({ Start-DomeniaLogonByDcRead -Kind Computer })
    $script:Ctrl["BtnUserResetPwd"].Add_Click({ Reset-UserPassword })
    $script:Ctrl["BtnApplyAccountOptions"].Add_Click({ Apply-UserAccountOptions })
    $script:Ctrl["BtnSetExpiration"].Add_Click({ Set-UserExpiration $false })
    $script:Ctrl["BtnNeverExpires"].Add_Click({ Set-UserExpiration $true })
    $script:Ctrl["BtnExpirePwdNow"].Add_Click({ Expire-UserPasswordNow })
    $script:Ctrl["BtnUserMove"].Add_Click({ Move-DomeniaSelectedUserWithOuPicker })
    $script:Ctrl["BtnUserManagerPick"].Add_Click({ Show-DomeniaManagerPicker -Target 'Utilisateur' })
    $script:Ctrl["BtnUserManagerOpen"].Add_Click({ Open-DomeniaManagerObject -Target 'Utilisateur' })
    $script:Ctrl["BtnUserManagerClear"].Add_Click({ Clear-DomeniaManagerSelection -Target 'Utilisateur' })
    $script:Ctrl["BtnUserAddGroup"].Add_Click({ AddOrRemoveObjectGroup $script:Ctrl["TxtUserGroupTarget"].Text $true })
    $script:Ctrl["BtnUserRemoveGroup"].Add_Click({ AddOrRemoveObjectGroup $script:Ctrl["TxtUserGroupTarget"].Text $false })
    $script:Ctrl["BtnCompSave"].Add_Click({ Save-ComputerProfile })
    $script:Ctrl["BtnCompEdit"].Add_Click({ Start-DomeniaFicheEdit -Type "Machine" })
    $script:Ctrl["BtnCompCancelEdit"].Add_Click({ Stop-DomeniaFicheEdit -Type "Machine" -Restaurer })
    $script:Ctrl["BtnCompManagedByPick"].Add_Click({ Show-DomeniaManagerPicker -Target 'Machine' })
    $script:Ctrl["BtnCompManagedByOpen"].Add_Click({ Open-DomeniaManagerObject -Target 'Machine' })
    $script:Ctrl["BtnCompManagedByClear"].Add_Click({ Clear-DomeniaManagerSelection -Target 'Machine' })
    $script:Ctrl["BtnCompEnable"].Add_Click({ Set-AccountDisabled $false })
    $script:Ctrl["BtnCompDisable"].Add_Click({ Set-AccountDisabled $true })
    $script:Ctrl["BtnCompPing"].Add_Click({ Invoke-ComputerTool "Ping" })
    $script:Ctrl["BtnCompRdp"].Add_Click({ Invoke-ComputerTool "RDP" })
    $script:Ctrl["BtnCompC"].Add_Click({ Invoke-ComputerTool "C" })
    $script:Ctrl["BtnCompManage"].Add_Click({ Invoke-ComputerTool "Manage" })
    $script:Ctrl["BtnCompEvents"].Add_Click({ Invoke-ComputerTool "Events" })
    $script:Ctrl["BtnCompServices"].Add_Click({ Invoke-ComputerTool "Services" })
    $script:Ctrl["BtnCompPSRemote"].Add_Click({ Invoke-ComputerTool "PSRemote" })
    if ($script:Ctrl.ContainsKey("BtnCompRimotte")) { $script:Ctrl["BtnCompRimotte"].Add_Click({ Show-DomeniaRunProgramPanel }) }
    $script:Ctrl["BtnCompRename"].Add_Click({ Rename-ComputerObject })
    $script:Ctrl["BtnCompMove"].Add_Click({ Move-DomeniaSelectedComputerWithOuPicker })
    $script:Ctrl["BtnCompAddGroup"].Add_Click({ AddOrRemoveObjectGroup $script:Ctrl["TxtCompGroupTarget"].Text $true })
    $script:Ctrl["BtnCompRemoveGroup"].Add_Click({ AddOrRemoveObjectGroup $script:Ctrl["TxtCompGroupTarget"].Text $false })
    $script:Ctrl["BtnGroupSave"].Add_Click({ Save-GroupProfile })
    $script:Ctrl["BtnGroupAddMember"].Add_Click({ AddOrRemoveGroupMember $true })
    $script:Ctrl["BtnGroupRemoveMember"].Add_Click({ AddOrRemoveGroupMember $false })
    $script:Ctrl["BtnCreateOu"].Add_Click({ Create-OuUnderSelected })
    $script:Ctrl["BtnRawSet"].Add_Click({ Set-OrClearRawAttribute $false })
    $script:Ctrl["BtnRawCopyAll"].Add_Click({ Copy-RawAttributesToClipboard })
    $script:Ctrl["BtnRawClear"].Add_Click({ Set-OrClearRawAttribute $true })
    $script:Ctrl["BtnLinkSelected"].Add_Click({ Add-SelectedLink })
    if ($script:Ctrl.ContainsKey("BtnDetectUserComputers")) { $script:Ctrl["BtnDetectUserComputers"].Add_Click({ Start-DomeniaUserComputerProbe }) }
    $script:Ctrl["BtnRemoveLink"].Add_Click({ Remove-SelectedLink })
    if ($script:Ctrl.ContainsKey("DgLinks")) {
        $script:Ctrl["DgLinks"].Add_SelectionChanged({
            try {
                $grid = Get-DomeniaControl -Name "DgLinks"
                $remove = Get-DomeniaControl -Name "BtnRemoveLink"
                Update-DomeniaRelationsActions
            }
            catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ }
        })
    }
    if ($script:Ctrl.ContainsKey("DgAllLinks")) { $script:Ctrl["DgAllLinks"].Add_MouseDoubleClick({ param($sender,$e) Open-DomeniaAllLinksCell -Source $e.OriginalSource }) }
    $script:Ctrl["BtnImportLinks"].Add_Click({ Import-LinksCsv })
    $script:Ctrl["BtnOpenLinksCsv"].Add_Click({ Export-DomeniaLinksCsv })
    $script:Ctrl["BtnLoadCmdlets"].Add_Click({ Load-AdCmdlets })
    $script:Ctrl["BtnCopyCmdlet"].Add_Click({ Copy-SelectedCmdlet })
    $script:Ctrl["BtnCopyCmdletSyntax"].Add_Click({ Copy-SelectedCmdletSyntax })
    $script:Ctrl["BtnCopyCmdletHelp"].Add_Click({ Copy-SelectedCmdletHelp })
    $script:Ctrl["BtnCmdletClearFilter"].Add_Click({ Clear-AdCmdletFilter })
    $script:Ctrl["TxtCmdletFilter"].Add_TextChanged({ Filter-AdCmdletReference })
    $script:Ctrl["CmbCmdletModule"].Add_SelectionChanged({ Filter-AdCmdletReference })
    $script:Ctrl["DgCmdlets"].Add_SelectionChanged({ Start-SelectedCmdletHelp })
    $script:Ctrl["BtnCancelTask"].Add_Click({ Stop-LatestUiTask })
    $script:Ctrl["BtnExportResults"].Add_Click({ Export-CurrentResults })
    $script:Ctrl["BtnLoadBitLocker"].Add_Click({ Start-LoadComputerSecrets -Mode "BitLocker" })
    $script:Ctrl["BtnLoadLaps"].Add_Click({ Start-LoadComputerSecrets -Mode "LAPS" })
    $script:Ctrl["BtnToggleSecrets"].Add_Click({ Toggle-SecretsVisibility })
    $script:Ctrl["BtnCopySecret"].Add_Click({ Copy-SelectedSecret })
    $script:Ctrl["BtnCopyAllSecrets"].Add_Click({ Copy-AllSecrets })
    $script:Ctrl["BtnClearSecrets"].Add_Click({ Clear-Secrets })
    $script:Ctrl["DgSecrets"].Add_SelectionChanged({ Update-DomeniaSecretActionUi })
    $script:Ctrl["DgSecrets"].Add_MouseDoubleClick({
        if ($null -ne $script:Ctrl["DgSecrets"].SelectedItem) { Copy-SelectedSecret }
    })
    # UX-15: the workstation account fields live in the side panel of Assistance poste (Domenia-MachineAccount.xaml);
    # Initialize-DomeniaMachineAccountPanel wires them when the « Compte poste » pill opens it for the first time.
    $script:Ctrl["BtnRunComputerDiag"].Add_Click({ Start-ComputerDiagnostics })
    if ($script:Ctrl.ContainsKey("BtnUserSaveContact")) { $script:Ctrl["BtnUserSaveContact"].Add_Click({ Save-DomeniaUserContact }) }
    if ($script:Ctrl.ContainsKey("BtnIndexScopePick")) { $script:Ctrl["BtnIndexScopePick"].Add_Click({
        $picked = Show-DomeniaInlinePicker -Kind OU -Title ('Choisir lʼunité organisationnelle de la base') -Prompt ('Choisissez une OU : la lecture couvrira cette branche et ses sous-OU.') -DepthMode Subtree -Purpose 'Effet : cette OU devient la portée de la base locale, relue sur ce poste ; aucune lecture AD avant « Mettre à jour lʼOU choisie ».' -InitialDn ([string]$script:IndexScopeDn)
        if ($null -eq $picked) { return }
        $pickedDn = ([string]$picked.DN).Trim()
        if (-not $pickedDn) { return }
        $script:IndexScopeDn = $pickedDn
        Update-DomeniaIndexStats
        Request-DomeniaIndexSearch
        Set-Status ('Portée de la base : ' + $pickedDn) 'INFO'
    }) }
    if ($script:Ctrl.ContainsKey("BtnIndexScopeUpdate")) { $script:Ctrl["BtnIndexScopeUpdate"].Add_Click({
        Start-DomeniaSelectedIndexScopeBuild
    }) }
    if ($script:Ctrl.ContainsKey("BtnIndexBuild")) { $script:Ctrl["BtnIndexBuild"].Add_Click({ Start-DomeniaIndexBuild -UpdateLinks }) }
    foreach($name in @('BtnStorageMove','BtnStorageRestore','BtnStorageResume','BtnStorageRollback','BtnStoragePolicySave','BtnStorageRetentionPreview','BtnStorageRetentionApply','BtnStorageIntegrity')){
        $button=Get-DomeniaControl $name
        if($null -ne $button){$button.Add_Click({param($sender,$eventArgs)
            switch([string]$sender.Name){
                'BtnStorageMove'{Request-DomeniaStorageMaintenance -Mode Move}
                'BtnStorageRestore'{Request-DomeniaStorageMaintenance -Mode Restore}
                'BtnStorageResume'{Resume-DomeniaStorageMaintenance}
                'BtnStorageRollback'{Resume-DomeniaStorageMaintenance -Rollback}
                'BtnStoragePolicySave'{Save-DomeniaStoragePolicy}
                'BtnStorageRetentionPreview'{Start-DomeniaStorageRetention}
                'BtnStorageRetentionApply'{Request-DomeniaStorageRetention}
                'BtnStorageIntegrity'{Start-DomeniaStorageIntegrity}
            }
        })}
    }
    if ($script:Ctrl.ContainsKey("BtnStorageUsage")) { $script:Ctrl["BtnStorageUsage"].Add_Click({ Start-DomeniaStorageUsage }) }
    if ($script:Ctrl.ContainsKey("BtnStoragePurgePreview")) { $script:Ctrl["BtnStoragePurgePreview"].Add_Click({ Start-DomeniaStoragePurge }) }
    if ($script:Ctrl.ContainsKey("BtnStoragePurge")) { $script:Ctrl["BtnStoragePurge"].Add_Click({ Request-DomeniaStoragePurge }) }
    foreach($name in @('Observations','Snapshots','History','Index')){
        $control=Get-DomeniaControl ('ChkStoragePurge'+$name)
        if($control){$control.Add_Checked({Reset-DomeniaStoragePurgePreview});$control.Add_Unchecked({Reset-DomeniaStoragePurgePreview})}
    }
    $age=Get-DomeniaControl 'TxtStorageHistoryDays';if($age){$age.Add_TextChanged({Reset-DomeniaStoragePurgePreview})}
    if ($script:Ctrl.ContainsKey("BtnParkHarvest")) { $script:Ctrl["BtnParkHarvest"].Add_Click({ Start-DomeniaLogonHarvest }) }
    # UI-23: « Vérifier la liste ▾ » (main part: last reading of the session, or Arrêter while it runs; arrow: choices).
    # Point 60: it reads the scope chosen beside the results (the list as shown, or the selected rows).
    if ($script:Ctrl.ContainsKey("BtnParkVerify")) { $script:Ctrl["BtnParkVerify"].Add_Click({ param($sender,$eventArgs) Invoke-DomeniaParkVerify -Anchor $sender }) }
    if ($script:Ctrl.ContainsKey("BtnParkVerifyMenu")) { $script:Ctrl["BtnParkVerifyMenu"].Add_Click({ param($sender,$eventArgs) Open-DomeniaParkVerifyMenu -Anchor $sender }) }
    # CO-19: the outcome pills of the last ping of the list filter it by presence (local filter only).
    if ($script:Ctrl.ContainsKey("BtnParkOutcomeOnline")) { $script:Ctrl["BtnParkOutcomeOnline"].Add_Click({ Set-DomeniaParkOutcomeFilter -Outcome Online }) }
    if ($script:Ctrl.ContainsKey("BtnParkOutcomeNoReply")) { $script:Ctrl["BtnParkOutcomeNoReply"].Add_Click({ Set-DomeniaParkOutcomeFilter -Outcome NoReply }) }
    if ($script:Ctrl.ContainsKey("BtnParkOutcomeError")) { $script:Ctrl["BtnParkOutcomeError"].Add_Click({ Set-DomeniaParkOutcomeFilter -Outcome Error }) }
    # FO-18: actions of a multiple selection of the list (same confirmation and ceiling as the list). They always act on
    # the selected rows, whatever the scope chosen beside the results (point 60).
    if ($script:Ctrl.ContainsKey("BtnSelectionPing")) { $script:Ctrl["BtnSelectionPing"].Add_Click({ Start-DomeniaParkSelectionSurvey -Mode Ping }) }
    if ($script:Ctrl.ContainsKey("BtnSelectionConsole")) { $script:Ctrl["BtnSelectionConsole"].Add_Click({ Start-DomeniaParkSelectionSurvey -Mode Console }) }
    if ($script:Ctrl.ContainsKey("BtnSelectionCopy")) { $script:Ctrl["BtnSelectionCopy"].Add_Click({ Copy-DomeniaSelectedRowsForTicket }) }
    if ($script:Ctrl.ContainsKey("BtnSelectionExport")) { $script:Ctrl["BtnSelectionExport"].Add_Click({ Export-CurrentResults -Mode Selected }) }
    # FI-18: the survey of the open workstation is stopped beside its board.
    if ($script:Ctrl.ContainsKey("BtnComputerParkStop")) { $script:Ctrl["BtnComputerParkStop"].Add_Click({ Stop-DomeniaOnlinePark -Slot Computer }) }
    if ($script:Ctrl.ContainsKey("BtnParkReset")) {
        # FI-13: confirmed in the page, preceded by a verified backup; park_state is really deleted from the base.
        $script:Ctrl["BtnParkReset"].Add_Click({ Request-DomeniaParkReset })
    }
    if ($script:Ctrl.ContainsKey("ChkParkSweepEnabled")) {
        $handler = {
            if ($script:RestoringSettings) { return }
            try {
                $c = Get-DomeniaControl -Name "ChkParkSweepEnabled"
                if ($null -ne $c) { Set-DomeniaSetting -Name "ParkSweepEnabled" -Value ([bool]$c.IsChecked) }
            }
            catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ }
        }
        $script:Ctrl["ChkParkSweepEnabled"].Add_Checked($handler)
        $script:Ctrl["ChkParkSweepEnabled"].Add_Unchecked($handler)
    }
    if ($script:Ctrl.ContainsKey("BtnIndexRefresh")) { $script:Ctrl["BtnIndexRefresh"].Add_Click({ Start-DomeniaIndexRefresh }) }
    if ($script:Ctrl.ContainsKey("BtnIndexOpen")) { $script:Ctrl["BtnIndexOpen"].Add_Click({ Open-DomeniaIndexSelection }) }
    if ($script:Ctrl.ContainsKey("BtnIndexOpenFolder")) { $script:Ctrl["BtnIndexOpenFolder"].Add_Click({ Open-DomeniaIndexLocation }) }
    if ($script:Ctrl.ContainsKey("BtnIndexCopyPath")) { $script:Ctrl["BtnIndexCopyPath"].Add_Click({ Copy-DomeniaIndexLocationPath }) }
    if ($script:Ctrl.ContainsKey("BtnIndexBackup")) { $script:Ctrl["BtnIndexBackup"].Add_Click({ Invoke-DomeniaIndexBackup }) }
    if ($script:Ctrl.ContainsKey("BtnIndexBackupTo")) { $script:Ctrl["BtnIndexBackupTo"].Add_Click({ Invoke-DomeniaIndexBackup -ChooseDestination }) }
    if ($script:Ctrl.ContainsKey("BtnIndexExport")) {
        $script:Ctrl["BtnIndexExport"].Add_Click({
            try {
                $grid = Get-DomeniaControl -Name "DgIndex"
                if ($null -eq $grid -or $null -eq $grid.ItemsSource) { Set-Status "Aucun résultat à exporter." "WARN"; return }
                Show-DomeniaExportResult -Result (Export-DomeniaCsv -Rows @($grid.ItemsSource) -Grid $grid -Subject 'index')
            }
            catch { [void](Show-DomeniaOperationError -Operation "Export de l index" -ErrorRecordOrException $_) }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnOperationStatsRefresh")) { $script:Ctrl["BtnOperationStatsRefresh"].Add_Click({ Request-DomeniaOperationStats }) }
    if ($script:Ctrl.ContainsKey("BtnOperationStatsExport")) { $script:Ctrl["BtnOperationStatsExport"].Add_Click({ Request-DomeniaOperationStats -Export }) }
    if ($script:Ctrl.ContainsKey("ApplicationToolTabs") -and $script:Ctrl.ContainsKey("TabOperationStats")) {
        $script:Ctrl["ApplicationToolTabs"].Add_SelectionChanged({
            param($sender,$e)
            try {
                # SelectionChanged est un evenement route : ignorer ceux des controles enfants.
                if ($null -ne $e -and $e.OriginalSource -ne $sender) { return }
                if ($sender.SelectedItem -eq $script:Ctrl["TabOperationStats"]) {
                    Request-DomeniaOperationStats
                }
                elseif (($script:Ctrl.ContainsKey('TabIndex')) -and ($sender.SelectedItem -eq $script:Ctrl['TabIndex'])) {
                    # FI-19: figures not read yet, or last reading failed (base busy): read again off the Dispatcher.
                    Request-DomeniaIndexMetadataIfNeeded
                }
                elseif ($sender.SelectedItem -eq $script:Ctrl['WsQueryWorkshop']) {
                    # A manual tool-tab change remembers the previous tool; programmatic routes retain their origin.
                    if (-not [bool]$script:DomeniaQueryNavigating -and $null -ne $e -and $e.RemovedItems.Count -gt 0) {
                        $previousTool = [string]$e.RemovedItems[0].Name
                        if ($previousTool -and $previousTool -ne 'WsQueryWorkshop') {
                            $script:DomeniaQueryReturnRoute = 'TabApplicationTools'
                            $script:DomeniaQueryReturnInner = 'ApplicationToolTabs'
                            $script:DomeniaQueryReturnTab = $previousTool
                            $script:DomeniaQueryReturnFocus = $null
                        }
                    }
                    # Direct tool-tab navigation updates the context only; execution stays explicit.
                    Show-DomeniaQueryWorkshop
                }
            }
            catch {
                Write-AppLog ("Actualisation des statistiques ignoree : " + $_.Exception.Message) "WARN"
            }
        })
    }
    if ($script:Ctrl.ContainsKey("TxtIndexSearch")) { $script:Ctrl["TxtIndexSearch"].Add_TextChanged({ Request-DomeniaIndexSearch }) }
    if ($script:Ctrl.ContainsKey('BtnIndexBrowse')) { $script:Ctrl['BtnIndexBrowse'].Add_Click({Search-DomeniaIndexUi}) }
    if ($script:Ctrl.ContainsKey('BtnIndexPrevious')) { $script:Ctrl['BtnIndexPrevious'].Add_Click({Move-DomeniaIndexSearchPage -Direction -1}) }
    if ($script:Ctrl.ContainsKey('BtnIndexNext')) { $script:Ctrl['BtnIndexNext'].Add_Click({Move-DomeniaIndexSearchPage -Direction 1}) }
    if ($script:Ctrl.ContainsKey("DgIndex")) { $script:Ctrl["DgIndex"].Add_MouseDoubleClick({ Open-DomeniaIndexSelection }) }
    if ($script:Ctrl.ContainsKey("DgIndex")) { $script:Ctrl["DgIndex"].Add_Sorting({param($sender,$eventArgs)Set-DomeniaIndexSearchSort -Grid $sender -EventArgs $eventArgs}) }
    if ($script:Ctrl.ContainsKey("BtnIndexResetSort")) { $script:Ctrl["BtnIndexResetSort"].Add_Click({Set-DomeniaIndexSearchSort -Reset}) }
    if ($script:Ctrl.ContainsKey("BtnLoadDomain")) { $script:Ctrl["BtnLoadDomain"].Add_Click({ Start-DomeniaDomainOverview }) }
    if ($script:Ctrl.ContainsKey("BtnCopyDomain")) { $script:Ctrl["BtnCopyDomain"].Add_Click({ Copy-DomeniaDomainReport }) }
    if ($script:Ctrl.ContainsKey("BtnWmiNamespaces")) { $script:Ctrl["BtnWmiNamespaces"].Add_Click({ Start-DomeniaWmiNamespaces }) }
    if ($script:Ctrl.ContainsKey("BtnWmiClasses")) { $script:Ctrl["BtnWmiClasses"].Add_Click({ Start-DomeniaWmiClasses }) }
    if ($script:Ctrl.ContainsKey("BtnWmiQuery")) { $script:Ctrl["BtnWmiQuery"].Add_Click({ Start-DomeniaWmiQuery }) }
    if ($script:Ctrl.ContainsKey("BtnWmiCopy")) { $script:Ctrl["BtnWmiCopy"].Add_Click({ Copy-DomeniaWmi }) }
    if ($script:Ctrl.ContainsKey("BtnWmiExport")) { $script:Ctrl["BtnWmiExport"].Add_Click({ Export-DomeniaWmi }) }
    if ($script:Ctrl.ContainsKey("TxtWmiClassFilter")) { $script:Ctrl["TxtWmiClassFilter"].Add_TextChanged({ Apply-DomeniaWmiClassFilter }) }
    if ($script:Ctrl.ContainsKey("LstWmiNamespaces")) { $script:Ctrl["LstWmiNamespaces"].Add_MouseDoubleClick({ Start-DomeniaWmiClasses }) }
    if ($script:Ctrl.ContainsKey("LstWmiClasses")) { $script:Ctrl["LstWmiClasses"].Add_MouseDoubleClick({ Start-DomeniaWmiQuery }) }
    if ($script:Ctrl.ContainsKey("BtnLoadSoftware")) { $script:Ctrl["BtnLoadSoftware"].Add_Click({ Start-DomeniaSoftwareInventory }) }
    # PF-22 : a l'ouverture de l'onglet, la liste deja rapportee par l'inventaire du meme poste est
    # affichee au lieu de repartir pour une seconde requete. Le geste complet reste le bouton.
    # TabItem ne possede pas d'evenement Selected (sonde en invite : Add_Selected n'existe pas) ; le
    # branchement se fait donc sur le TabControl, comme les onglets de workspace plus haut.
    # UI-08 : la liste est l'affichage par defaut de l'onglet ; les graphiques et les colonnes
    # techniques ne se montrent que sur demande explicite de l'operateur.
    if ($script:Ctrl.ContainsKey("CmbSoftwareView")) { $script:Ctrl["CmbSoftwareView"].Add_SelectionChanged({ param($sender,$e) if ($sender -eq $e.OriginalSource) { try { Update-DomeniaSoftwareSyntheseVisibility } catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ } } }) }
    if ($script:Ctrl.ContainsKey("BtnSoftwareColumns")) {
        $script:Ctrl["BtnSoftwareColumns"].Add_Checked({ param($sender,$e) try { Update-DomeniaSoftwareColumnVisibility } catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ } })
        $script:Ctrl["BtnSoftwareColumns"].Add_Unchecked({ param($sender,$e) try { Update-DomeniaSoftwareColumnVisibility } catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ } })
    }
    if ($script:Ctrl.ContainsKey("ComputerTabs")) {
        $script:Ctrl["ComputerTabs"].Add_SelectionChanged({
            param($sender,$e)
            if ($sender -ne $e.OriginalSource) { return }
            try {
                $onglet = $sender.SelectedItem
                # UX-21 (X04): Logiciels is an inner tab of Détails; the account line of Intervenir is said again.
                if (($null -ne $onglet) -and (([string]$onglet.Name) -eq 'TabComputerDetails')) { $onglet = (Get-DomeniaControl 'ComputerDetailTabs').SelectedItem }
                if ($null -ne $onglet -and ([string]$onglet.Name) -eq 'TabSoftware') { Show-DomeniaSoftwareFromInventory }
                if (($null -ne $onglet) -and (([string]$onglet.Name) -eq 'TabComputerAdmin')) { Update-DomeniaComputerOperationAccount }
            }
            catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnCopySoftware")) { $script:Ctrl["BtnCopySoftware"].Add_Click({ Copy-DomeniaSoftware }) }
    if ($script:Ctrl.ContainsKey("BtnExportSoftware")) { $script:Ctrl["BtnExportSoftware"].Add_Click({ Export-DomeniaSoftware }) }
    if ($script:Ctrl.ContainsKey("TxtSoftwareFilter")) { $script:Ctrl["TxtSoftwareFilter"].Add_TextChanged({ Apply-DomeniaSoftwareFilter }) }
    if ($script:Ctrl.ContainsKey("BtnSoftwareFilterClear")) { $script:Ctrl["BtnSoftwareFilterClear"].Add_Click({ Clear-DomeniaSoftwareChartFilter }) }
    if ($script:Ctrl.ContainsKey("LnkInventoryRefresh")) { $script:Ctrl["LnkInventoryRefresh"].Add_Click({ Start-DomeniaComputerInventory }) }
    if ($script:Ctrl.ContainsKey("CmbSoftwareScope")) {
        $script:Ctrl["CmbSoftwareScope"].Add_SelectionChanged({
            try {
                $item = $script:Ctrl["CmbSoftwareScope"].SelectedItem
                $script:SoftwareScope = if ($null -ne $item) { [string]$item.Content } else { "Toutes" }
                if (-not $script:RestoringSettings) { Set-DomeniaSetting -Name "SoftwareScope" -Value $script:SoftwareScope }
                Apply-DomeniaSoftwareFilter
            }
            catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ }
        })
    }
    if ($script:Ctrl.ContainsKey("BtnRunInventory")) { $script:Ctrl["BtnRunInventory"].Add_Click({ Start-DomeniaComputerInventory }) }
    if ($script:Ctrl.ContainsKey("BtnRunInventoryDeep")) { $script:Ctrl["BtnRunInventoryDeep"].Add_Click({ Start-DomeniaComputerInventory -Deep }) }
    # Home overview (decision David 2026-10-08): it follows the OU of Rechercher and only displays; the analyses
    # stay in Rechercher on the displayed list. It is recomputed when Accueil is shown and its OU or data changed.
    if ($script:Ctrl.ContainsKey("BtnFleetDashboardRefresh")) { $script:Ctrl["BtnFleetDashboardRefresh"].Add_Click({ try { Start-DomeniaFleetDashboard } catch { Set-Status ('Vue dʼensemble non calculée : ' + $_.Exception.Message) 'WARN' } }) }
    if ($script:Ctrl.ContainsKey("BtnFleetScope")) { $script:Ctrl["BtnFleetScope"].Add_Click({ try { Show-DomeniaFleetScopeSource } catch { Set-Status ('Sélecteur dʼOU indisponible : ' + $_.Exception.Message) 'WARN' } }) }
    if ($script:Ctrl.ContainsKey("BtnFleetScopeReset")) { $script:Ctrl["BtnFleetScopeReset"].Add_Click({ $script:FleetScopeDn = ''; $script:FleetStale = $true; Request-DomeniaFleetRefresh; Set-Status 'Tableau de bord : tout le domaine depuis la base locale.' }) }
    Initialize-DomeniaUiZoom
    Initialize-DomeniaQueryWorkshop
    if ($script:Ctrl.ContainsKey("BtnFleetShowMachines")) { $script:Ctrl["BtnFleetShowMachines"].Add_Click({ Show-DomeniaQueryWorkshop -Evaluate }) }
    if ($script:Ctrl.ContainsKey("TxtFleetMachineFilter")) { $script:Ctrl["TxtFleetMachineFilter"].Add_TextChanged({ Update-DomeniaFleetMachineList }) }
    if ($script:Ctrl.ContainsKey("CmbFleetMachineState")) { $script:Ctrl["CmbFleetMachineState"].Add_SelectionChanged({ Update-DomeniaFleetMachineList }) }
    if ($script:Ctrl.ContainsKey("BtnFleetIndexScope")) { $script:Ctrl["BtnFleetIndexScope"].Add_Click({ try { Invoke-DomeniaOuRefresh -Source Fleet -Mode AD } catch { Set-Status ('Mise à jour de lʼOU impossible : ' + $_.Exception.Message) 'WARN' } }) }
    foreach($source in @('Fleet','Search')){
        $map=if($source -eq 'Fleet'){@{Ping='BtnFleetRefreshPostes';Wmi='BtnFleetRefreshBoth'}}else{@{AD='BtnSearchRefreshBase';Ping='BtnSearchRefreshPostes';Wmi='BtnSearchRefreshBoth'}}
        foreach($mode in $map.Keys){
            $button=Get-DomeniaControl $map[$mode]
            if($null -ne $button){$button.Tag=[pscustomobject]@{Source=$source;Mode=$mode};$button.Add_Click({param($sender,$eventArgs) Invoke-DomeniaOuRefresh -Source ([string]$sender.Tag.Source) -Mode ([string]$sender.Tag.Mode)})}
        }
        $stop=Get-DomeniaControl ('Btn'+$source+'RefreshStop')
        if($null -ne $stop){$stop.Tag=$source;$stop.Add_Click({param($sender,$eventArgs) Stop-DomeniaOuRefresh -Source ([string]$sender.Tag)})}
    }
    Update-DomeniaOuRefreshUi
    if ($script:Ctrl.ContainsKey("BtnFleetOpenSearch")) { $script:Ctrl["BtnFleetOpenSearch"].Add_Click({ try { Show-DomeniaFleetAnalyzeSource } catch { Set-Status ('Rechercher indisponible : ' + $_.Exception.Message) 'WARN' } }) }
    # First steps (UX-20): each step opens its screen and starts nothing.
    foreach ($firstStep in @('Connection','Ou','Base','Dashboard')) {
        $firstStepName = 'BtnFirstStep' + $firstStep
        if ($script:Ctrl.ContainsKey($firstStepName)) { $script:Ctrl[$firstStepName].Tag = $firstStep; $script:Ctrl[$firstStepName].Add_Click({ param($sender,$eventArgs) try { Open-DomeniaFirstStep -Step ([string]$sender.Tag) } catch { Set-Status ('Étape non ouverte : ' + $_.Exception.Message) 'WARN' } }) }
    }
    # PF-11: the session details are rebuilt when they are opened.
    if ($script:Ctrl.ContainsKey("UxSessionDetails")) { $script:Ctrl["UxSessionDetails"].Add_Expanded({ try { Update-Dashboard -Force } catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ } }) }
    $workspaceTabs = Get-DomeniaControl 'WorkspaceTabs'
    # Deferred: a tab selected for an instant (a search started from another page passes through Accueil) starts nothing.
    # FI-19: Outils shown again with Base locale already selected inside it reads missing figures (-IfShown checks the page).
    if ($null -ne $workspaceTabs) { $workspaceTabs.Add_SelectionChanged({ param($sender,$eventArgs) if ($sender -eq $eventArgs.OriginalSource) { try { [void]$sender.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Background,[Action]{ try { Request-DomeniaFleetRefresh } catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ }; try { Request-DomeniaIndexMetadataIfNeeded -IfShown } catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ } }) } catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ } } }) }
    if ($script:Ctrl.ContainsKey("BtnDashboardInventory")) { $script:Ctrl["BtnDashboardInventory"].Add_Click({ Start-DomeniaComputerInventory }) }
    if ($script:Ctrl.ContainsKey("BtnDashboardInventoryDeep")) { $script:Ctrl["BtnDashboardInventoryDeep"].Add_Click({ Start-DomeniaComputerInventory -Deep }) }
    if ($script:Ctrl.ContainsKey("BtnCopyInventory")) { $script:Ctrl["BtnCopyInventory"].Add_Click({ Copy-DomeniaInventory }) }
    if ($script:Ctrl.ContainsKey("BtnExportInventory")) { $script:Ctrl["BtnExportInventory"].Add_Click({ Export-DomeniaInventory }) }
    if ($script:Ctrl.ContainsKey("CmbInventoryCategory")) {
        $script:Ctrl["CmbInventoryCategory"].Add_SelectionChanged({
            if ($script:SuppressInventoryCategoryEvent) { return }
            try {
                $item = $script:Ctrl["CmbInventoryCategory"].SelectedItem
                $script:InventoryCategory = if ($null -ne $item) { [string]$item.Content } else { "Toutes" }
                Apply-DomeniaInventoryFilter
            }
            catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ }
        })
    }
    $script:Ctrl["BtnCopyComputerDiag"].Add_Click({ Copy-ComputerDiagnostics })
    $script:Ctrl["BtnPermissionRefresh"].Add_Click({ $script:DeferredPermissionsDn = ""; Start-PermissionAnalysis -UserInitiated })
    $script:Ctrl["BtnPermissionCopy"].Add_Click({ Copy-PermissionReport })
    $script:Ctrl["BtnSelfCheckQuick"].Add_Click({ Start-SelfCheck -Full:$false })
    $script:Ctrl["BtnSelfCheckFull"].Add_Click({ Start-SelfCheck -Full:$true })
    $script:Ctrl["BtnSelfCheckCopy"].Add_Click({ Copy-SelfCheckReport })
    $script:Ctrl["BtnSelfCheckExport"].Add_Click({ Export-SelfCheckReport })
    if ($script:Ctrl.ContainsKey("ChkReadOnlyMode")) {
        # DS-02 / SE-06 (L08): leaving read-only is confirmed by one sentence in a panel of the page, never a window;
        # the switch stays on read-only until the answer. Going back to read-only is immediate and never asks.
        $script:Ctrl["ChkReadOnlyMode"].Add_Checked({ Enter-DomeniaReadOnlyMode })
        $script:Ctrl["ChkReadOnlyMode"].Add_Unchecked({
            # C2: in demonstration the read-only lock cannot be lifted (no request, no write mode).
            if ([bool]$script:DemoMode) {
                $script:ReadOnlyMode = $true
                $script:Ctrl["ChkReadOnlyMode"].IsChecked = $true
                Set-Status "Écritures désactivées en démonstration : la lecture seule reste active." "WARN"
                return
            }
            Request-DomeniaWriteMode
        })
    }
    if ($script:Ctrl.ContainsKey("BtnReadOnlyResume")) { $script:Ctrl["BtnReadOnlyResume"].Add_Click({ Exit-DomeniaWriteMode -Reason Manual }) }
    if ($script:Ctrl.ContainsKey("BtnDashSelfCheck")) { $script:Ctrl["BtnDashSelfCheck"].Add_Click({ Select-DomeniaWorkspace -Workspace "TabApplicationTools"; try { $script:Ctrl["ApplicationToolTabs"].SelectedItem=$script:Ctrl["TabSelfCheck"] } catch { Write-DomeniaSwallowed 'Core' 'Wire-Events' $_ }; Start-SelfCheck -Full }) }
    if ($script:Ctrl.ContainsKey("BtnDashClearCache")) { $script:Ctrl["BtnDashClearCache"].Add_Click({ Clear-VisitCache }) }
    if ($script:Ctrl.ContainsKey("BtnDashOpenLog")) { $script:Ctrl["BtnDashOpenLog"].Add_Click({ Open-DomeniaAuditLog }) }
    if ($script:Ctrl.ContainsKey("BtnPruneLinks")) { $script:Ctrl["BtnPruneLinks"].Add_Click({ Start-PruneOrphanLinks }) }
    if ($script:Ctrl.ContainsKey("BtnCompGpUpdate")) { $script:Ctrl["BtnCompGpUpdate"].Add_Click({ Invoke-ComputerTool "GpUpdate" }) }
    if ($script:Ctrl.ContainsKey("BtnCompRestart")) { $script:Ctrl["BtnCompRestart"].Add_Click({ Invoke-ComputerTool "Restart" }) }
    if ($script:Ctrl.ContainsKey("BtnOpenLinkedUser")) { $script:Ctrl["BtnOpenLinkedUser"].Add_Click({ Open-LinkedUserFromMachine }) }
    if ($script:Ctrl.ContainsKey("BtnOpenLinkedComputer")) { $script:Ctrl["BtnOpenLinkedComputer"].Add_Click({ Open-LinkedComputerFromUser }) }
    if ($script:Ctrl.ContainsKey("BtnRefreshMachineLink")) { $script:Ctrl["BtnRefreshMachineLink"].Add_Click({ Start-ProbeForSelectedComputer -Force }) }
    if ($script:Ctrl.ContainsKey("TxtUserLinkedComputers")) { $script:Ctrl["TxtUserLinkedComputers"].Add_MouseDoubleClick({ Open-LinkedComputerFromUser }) }
    if (
        $script:Ctrl.ContainsKey("TxtGlobalSearch") -and
        [bool](Get-CfgValue "Browser" "AllowLiveGlobalSearch" $false) -and
        [bool](Get-CfgValue "Browser" "LiveGlobalSearch" $false)
    ) {
        $script:Ctrl["TxtGlobalSearch"].Add_TextChanged({ Queue-LiveGlobalSearch })
    }
    [void](Register-DomeniaContextMenus)
    Register-DomeniaDeferredViewHandlers
    [void](Register-DomeniaShortcuts)
    # Points 102 to 110: the Audit AD and Assistance tools load their own view at the first opening of their tab.
    try { Register-DomeniaAdAuditTool } catch { Write-AppLog ('Audit AD non raccordé : ' + $_.Exception.Message) 'ERROR' }
    try { Register-DomeniaAssistanceTool } catch { Write-AppLog ('Assistance non raccordée : ' + $_.Exception.Message) 'ERROR' }
}




# =====================================================================
# DOMENIA MASTER LAST V1 - couche finale de consolidation et de securite
# =====================================================================
# DOMENIA_MASTER_LAST_V1 = TRUE
$script:Version = "1.0"
$script:AppName = "Domenia"
$script:MasterBuild = "2026.10.16-DOMENIA-1.0-RC1.17.9-D120"
$script:ActiveWriteTaskId = ""
$script:WriteState = "Idle"
$script:UnknownWriteTargetDn = ""
$script:LastDispatcherErrorPopupAt = [datetime]::MinValue
$script:StartupWindow = $null
$script:StartupCtrl = @{}
$script:StartupTracePath = ""
$script:StartupCorrelation = [guid]::NewGuid().ToString("N")
$script:ShowingCachedObject = $false
$script:DashboardRefreshTimer = $null
$script:ActiveLinkProbeId = ""
$script:ActiveLinkProbeComputer = ""
$script:LinkIndexGeneration = 0
$script:RawAttributeBlockList = @(
    "objectGUID","objectSid","sIDHistory","nTSecurityDescriptor","unicodePwd","dBCSPwd",
    "supplementalCredentials","ntPwdHistory","lmPwdHistory","userPassword","unixUserPassword","clearTextPassword","currentValue","priorValue","pekList","trustAuthIncoming","trustAuthOutgoing","userAccountControl","adminCount",
    "isCriticalSystemObject","msDS-KeyCredentialLink","msDS-ManagedPassword","msDS-ManagedPasswordId","msDS-ManagedPasswordPreviousId","ms-Mcs-AdmPwd","ms-Mcs-AdmPwdExpirationTime",
    "msLAPS-Password","msLAPS-EncryptedPassword","msLAPS-EncryptedPasswordHistory","msLAPS-EncryptedDSRMPassword","msLAPS-EncryptedDSRMPasswordHistory","msLAPS-PasswordExpirationTime",
    "msFVE-RecoveryPassword","msFVE-KeyPackage","member","memberOf","primaryGroupID",
    "distinguishedName","objectClass","objectCategory","uSNChanged","uSNCreated","whenCreated","whenChanged"
)

function New-DefaultConfig {
    [ordered]@{
        Conf = [ordered]@{
            AutoDiscover = $true
            DOMAINE = ""
            NETBIOS = ""
            SearchBase = ""
            Server = ""
            UsersBase = ""
            ComputersBase = ""
            ADM = ""
        }
        Auth = [ordered]@{
            VaultDomainDn = ""
            VaultUserName = ""
            # UX-28: « Se souvenir de mon identifiant » is unchecked until the operator ticks it once (kept in HKCU).
            RememberLogin = $false
            LastLogin = ""
            LoginWindowMode = "Standard"
            AllowWindowsSession = $true
            LoginTimeoutSeconds = 30
            PerServerTimeoutSeconds = 6
            MaxServerCandidates = 4
            DetailedLoginTrace = $true
            # D120: in-memory demonstration directory. Only the JSON value true enables it.
            DemoProvider = $false
        }
        # D120 (F5): switches for behaviours that replace an existing path. Read by Get-DomeniaFeatureFlag.
        Features = [ordered]@{
            Scheduler = $true
            IdlePolicy = $true
            BitLockerKeySelection = $true
            SecretSingleCopy = $true
            ScopedLocks = $true
            SearchSyntax = $true
            SearchRanking = $true
            ColumnProfiles = $true
            InlineConfirm = $true
            IsolatedReads = $false
            WakeOnLan = $false
            LocalAssistant = $false
            ReadTrace = $false
        }
        Demo = [ordered]@{
            Identity = "DEMO\demo.operateur"
            LatencyMs = 0
        }
        Streaming = [ordered]@{
            VerifyUserOnSelection = $true
            # SE-13: nothing goes to the network without a gesture. An administrator may enable it; the page then
            # shows 'Liste vérifiée à HH:mm' and a switch to stop it for the session.
            RevalidateListedObjects = $false
            RevalidateIntervalSeconds = 60
            ReconcileSeconds = 180
            MaxUserProbes = 2
        }
        # SE-05: ceiling of a survey of the displayed list or of its selection (ping, console, analysis).
        Park = [ordered]@{
            MaxTargets = 500
        }
        Browser = [ordered]@{
            FastBoot = $false
            LoadFirstLevelOnStartup = $true
            ForceFirstLevelAtStartup = $true
            IncludeContainers = $true
            DefaultObjectFilter = "Tous"
            DefaultScope = "OneLevel"
            DefaultLimit = 100
            GlobalSearchLimit = 100
            GlobalSearchMinChars = 2
            SearchPageSize = 250
            SearchServerTimeLimitSeconds = 60
            SearchClientTimeoutSeconds = 90
            MaxPageSize = 300
            AutoLoadBranchOnSelect = $true
            SelectRootWithoutLoading = $false
            LiveGlobalSearch = $false
            AllowLiveGlobalSearch = $false
            LiveSearchDelayMs = 900
            SelectionDebounceMs = 180
        }
        Dashboard = [ordered]@{
            Enabled = $true
            RefreshAfterEachAction = $true
            # Lot L01: observations older than this are left out of the overview (greyed past 7 days).
            ObservationMaxAgeDays = 30
            # FO-17: team layout of each board, set by the administrator: the JSON list exported by « Exporter » (or the
            # whole exported document, or its text). Empty: the delivered layout. Applied by « Par défaut » and to a board
            # never customised; an unreadable value is ignored and the delivered layout stays.
            DefaultLayoutComputer = ''
            DefaultLayoutFleet = ''
            DefaultLayoutSoftware = ''
        }
        UI = [ordered]@{
            WindowWidth = 1720
            WindowHeight = 930
            TreeWidth = 430
            ObjectListHeight = 360
            AppleLike = $true
            ReadOnlyDefault = $true
            # SP-13 (L08): false hides the Expert profile (menu foot) and keeps Ctrl+L on the session journal.
            AllowExpertProfile = $true
            ShowStartupMonitor = $true
            TreeRenderBatchSize = 16
            TreeRenderIntervalMs = 20
        }
        Async = [ordered]@{
            Enabled = $true
            MinThreads = 2
            MaxThreads = 6
            MaxOutstandingWorkers = 12
            # D015 (Features.Scheduler): bounded priority queue and places kept for explicit actions.
            MaxQueued = 32
            ReservedForeground = 2
            MaxQueueWaitSeconds = 120
            PollIntervalMs = 250
            UiRefreshIntervalMs = 500
            # PF-04: time budget of one engine tick for the promotions and the completions (replaces MaxCompletionsPerTick).
            TickBudgetMs = 25
            CallbackWarningMs = 120
            CancelGraceSeconds = 5
            DefaultTimeoutSeconds = 60
            SearchTimeoutSeconds = 120
            SearchMaxDurationSeconds = 900
            ObjectTimeoutSeconds = 35
            TreeTimeoutSeconds = 30
            RemoteTimeoutSeconds = 45
            SelfCheckTimeoutSeconds = 120
            WriteSoftTimeoutSeconds = 90
            WriteHardTimeoutSeconds = 300
        }
        Cache = [ordered]@{
            Enabled = $true
            TtlSeconds = 90
            ObjectTtlSeconds = 45
            MaxEntries = 400
            StartupGlobalCache = $false
            WarmRootTree = $true
            WarmRootObjects = $true
            WarmRootObjectLimit = 100
            WarmupTimeoutSeconds = 45
            WarmupRetries = 2
            WarmupRetryDelayMs = 1200
        }
        Security = [ordered]@{
            EvaluateRightsOnObjectOpen = $true
            DisableDeniedControls = $true
            BlockOnAclEstimate = $false
            DisableIndeterminateControls = $false
            AutoClearSecretClipboardSeconds = 30
            # UX-36: a support-issued password must come back changed by its own user; the
            # operator may turn this off, the page then leaves the box as the XAML sets it.
            ForcePasswordChangeOnReset = $true
            # UX-36: length of the password built by the generate button (floor 14, ceiling 64).
            GeneratedPasswordLength = 16
            AlternateCredentialIdleMinutes = 30
            MaskSecretsByDefault = $true
            SecretMemorySeconds = 300
            RequireFreshObject = $true
            MaxObjectAgeMinutes = 15
            BlockProtectedObjects = $true
            # SE-06 (L08): write mode goes back to read-only after this many minutes without a write (5 to 120);
            # a write in progress is never interrupted.
            ReadOnlyReturnMinutes = 15
            AllowProtectedObjectWrites = $false
            AllowContainerDelete = $false
            RequireTypedDeleteConfirmation = $true
            AllowRawAttributeWrite = $false
            BlockSensitiveRawAttributes = $true
            RequireTypedHighRiskConfirmation = $true
            SingleWriteChannel = $true
            NeverPersistLaps = $true
            NeverPersistBitLockerRecovery = $true
            NeverLogSecretValues = $true
            SecretClipboardSeconds = 20
        }
        SelfCheck = [ordered]@{
            AutoQuickAfterLogin = $false
            FullBenchmarkIterations = 3
        }
        Startup = [ordered]@{
            AutoLongOperations = $false
            DetailedTrace = $true
            ShowMonitor = $true
            KeepMonitorUntilReady = $true
            WarnStageSeconds = 8
        }
        Remote = [ordered]@{
            PortTimeoutMs = 1200
            CommandTimeoutSeconds = 10
            UseWinRM = $true
            UseCim = $true
            UseRemoteRegistry = $true
            UseProfilesShare = $true
            UseSecurityLog = $false
            AllowUnboundedFallbacks = $false
            AllowRemoteArtifacts = $false
            UseTaskFallback = $true
            UsePsExecFallback = $true
            TaskFallbackTimeoutSeconds = 75
            TaskFallbackKeepFailedArtifacts = $false
            TaskFallbackPreferSystem = $true
        }
        # SE-08 (X04): delay of the restart with a message to the user, from 60 to 3600 seconds (300 by default).
        Restart = [ordered]@{
            DefaultDelaySeconds = 300
        }
        WAPT = [ordered]@{
            Enabled = $false
            LinkCsv = "Domenia-user-machine-links.csv"
            WaptGetPath = ""
            ServerUrl = ""
        }
        UserMachineLink = [ordered]@{
            AutoProbeOnComputerSelect = $false
            AllowAutoProbeOnSelect = $false
            ProbeTimeoutSeconds = 25
            ProbeMethodTimeoutMs = 3000
            ClassicProbeTimeoutSeconds = 8
            TaskFallbackProbeTimeoutSeconds = 30
            ProbeOncePerSession = $true
            DoNotOverwriteExisting = $true
            VerifyUserInAd = $true
            MinimumConfidence = 60
            SecurityLogDays = 14
            SecurityLogMaxEvents = 5000
            ScanCandidates = 1200
            ScanProbes = 250
            ProbeBudgetMs = 120000
            ScanBudgetMs = 300000
        }
        Modules = [ordered]@{
            ActiveDirectoryPath = ""
            AutoLoad = $true
            PreferActiveDirectoryModule = $true
            UseCredential = $true
            FallbackToLdap = $true
            ShowModuleStatus = $true
        }
        Index = [ordered]@{
            StartupDeltaEnabled = $true
            StartupDeltaMaxAgeMinutes = 5
            FullRebuildDays = 7
            MaxObjects = 0
            BudgetMs = 1200000
            ComputerFirst = $true
        }
        LocalStore = [ordered]@{
            AtomicWrites = $true
            KeepBackup = $true
            MutexTimeoutMilliseconds = 350
            DatabaseFile = "Domenia.db"
            BackupTimeoutSeconds = 30
            DatabaseBusyTimeoutMs = 2500
            KeepLegacyFiles = $true
            TelemetryRetentionDays = 365
        }
    }
}

function Initialize-DomeniaDataStore {
    if($script:DataStoreValidated -and $script:DataDir){return [string]$script:DataDir}
    $script:StorageLayout=$null;$script:StoragePreferenceWarning=''
    $mode=[string](Get-CfgValue 'LocalStore' 'Mode' 'Compatible')
    if($mode -notin @('Compatible','UserLocal','Portable')){throw 'LocalStore.Mode doit valoir Compatible, UserLocal ou Portable.'}
    $portable=Join-Path ([string]$script:RootDir) 'data'
    try {$hasLegacy=[IO.Directory]::Exists($portable) -and (@([IO.Directory]::EnumerateFileSystemEntries($portable)|Select-Object -First 1).Count -gt 0)}
    catch {throw ('Stockage portable illisible : '+$portable+'. Aucun repli silencieux. '+$_.Exception.Message)}
    $usePortable=($mode -eq 'Portable' -or ($mode -eq 'Compatible' -and $hasLegacy))
    $userLocalRoot=Get-DomeniaUserLocalRoot
    if(-not $usePortable -and [string]::IsNullOrWhiteSpace($userLocalRoot)){throw 'DOMENIA_STORE_LAYOUT : profil local absent. Aucun repli silencieux.'}
    $dir=if($usePortable){$portable}else{Join-Path $userLocalRoot 'Domenia\Data'}
    $dir=[IO.Path]::GetFullPath($dir)
    if($dir.StartsWith('\\') -or ([IO.DriveInfo]::new([IO.Path]::GetPathRoot($dir))).DriveType -eq [IO.DriveType]::Network){throw 'Une base active SQLite doit etre locale. Choisissez UserLocal ; les sources existantes seront conservees.'}
    $probe=[IO.DirectoryInfo]::new($dir)
    while($null -ne $probe){if($probe.Exists -and ($probe.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Stockage redirige par un lien : choisissez un dossier local non redirige.'};$probe=$probe.Parent}
    try {[void][IO.Directory]::CreateDirectory($dir)}catch{throw ('Stockage non inscriptible : '+$dir+'. Aucun repli silencieux. Configurez UserLocal.')}
    if(-not $usePortable){
        $sid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;$acl=[Security.AccessControl.DirectorySecurity]::new()
        # DACL only. Never request access to the SACL, owner or group.
        $acl.SetSecurityDescriptorSddlForm(
            ('D:P(A;OICI;FA;;;'+$sid+')(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)'),
            [Security.AccessControl.AccessControlSections]::Access
        )
        try {[IO.Directory]::SetAccessControl($dir,$acl)}
        catch {
            throw [InvalidOperationException]::new(
                ('DOMENIA_STORE_DACL : impossible de proteger le dossier des donnees locales "'+$dir+'". '+$_.Exception.Message),
                $_.Exception
            )
        }
    }
    $test=Join-Path $dir ('.write-'+[guid]::NewGuid().ToString('N'))
    try{$stream=[IO.File]::Open($test,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);$stream.Dispose()}catch{throw ('Stockage non inscriptible : '+$dir+'. Aucun repli silencieux. Configurez UserLocal.')}finally{if([IO.File]::Exists($test)){[IO.File]::Delete($test)}}

    # The rule must exist and agree with the selected mode. No fallback or logging here:
    # both loggers can enter this function until DataStoreValidated becomes true.
    $installRoot=[IO.Path]::GetDirectoryName([IO.Path]::GetFullPath(([string]$script:RootDir).TrimEnd('\')))
    try {
        $layout=Get-DomeniaStorageLayout -Mode $mode -InstallRoot $installRoot -UserLocalRoot $userLocalRoot -PortableHasData $hasLegacy -Writable @{Cache=$true}
        if($null -eq $layout -or [string]::IsNullOrWhiteSpace([string]$layout.DataRoot) -or [IO.Path]::GetFullPath([string]$layout.DataRoot).TrimEnd('\') -ine $dir.TrimEnd('\')){throw 'Dossier de donnees incoherent.'}
        $cache=@($layout.Categories | Where-Object {$_.Category -eq 'Cache'})
        $preference=@($layout.Categories | Where-Object {$_.Category -eq 'Preference'})
        if($cache.Count -ne 1 -or $cache[0].State -ne 'Pret' -or $preference.Count -ne 1 -or [string]$preference[0].Path -ine (Join-Path $dir 'Preferences')){throw 'Categories de stockage incoherentes.'}
        $areas=@($cache[0].Areas)
        if(($areas.Name -join ',') -cne 'Logs,Backups,Diagnostics,Exports,Legacy,Domains'){throw 'Zones de cache absentes ou incoherentes.'}
        foreach($area in $areas){if([string]$area.Path -ine (Join-Path $dir ([string]$area.Name))){throw ('Zone incoherente : '+$area.Name)}}
    } catch {throw ('DOMENIA_STORE_LAYOUT : '+$_.Exception.Message+' Aucun repli silencieux.')}
    foreach($area in $areas){
        $folder=[IO.DirectoryInfo]::new([string]$area.Path)
        if($folder.Exists -and ($folder.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw ('Stockage redirige refuse : '+$area.Path)}
        [void][IO.Directory]::CreateDirectory([string]$area.Path)
    }
    $preferencePath=[string]$preference[0].Path;$preferenceWritable=$false;$preferenceFailure=''
    $preferenceProbe=Join-Path $preferencePath ('.write-'+[guid]::NewGuid().ToString('N'))
    try {
        $folder=[IO.DirectoryInfo]::new($preferencePath)
        if($folder.Exists -and ($folder.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Lien de dossier refuse.'}
        [void][IO.Directory]::CreateDirectory($preferencePath)
        $stream=[IO.File]::Open($preferenceProbe,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
        $stream.Dispose();$preferenceWritable=$true
    } catch {$preferenceFailure=$_.Exception.Message}
    finally {if([IO.File]::Exists($preferenceProbe)){[IO.File]::Delete($preferenceProbe)}}
    $observed=@{Cache=$true;Preference=$preferenceWritable};$observed[$preferencePath]=$preferenceWritable
    try {
        $layout=Get-DomeniaStorageLayout -Mode $mode -InstallRoot $installRoot -UserLocalRoot $userLocalRoot -PortableHasData $hasLegacy -Writable $observed
        if($null -eq $layout -or [string]$layout.DataRoot -ine $dir){throw 'Disposition finale incoherente.'}
    } catch {throw ('DOMENIA_STORE_LAYOUT : '+$_.Exception.Message+' Aucun repli silencieux.')}
    if(-not $preferenceWritable){$script:StoragePreferenceWarning='Les preferences ne pourront pas etre enregistrees dans '+$preferencePath+'. '+$preferenceFailure+' Aucun autre emplacement ne sera utilise.'}
    $logs=[string](@($areas | Where-Object {$_.Name -eq 'Logs'})[0].Path)
    $script:StorageLayout=$layout
    $script:DataDir=$dir;$script:AuditPath=Join-Path $logs 'Domenia.log';$script:StartupTracePath=Join-Path $logs 'Domenia-startup.log'
    $script:DataStoreValidated=$true;return $dir
}


function Write-StartupTrace {
    param(
        [string]$Stage,
        [string]$Status = "INFO",
        [string]$Detail = "",
        [long]$DurationMs = 0
    )
    $Detail = Protect-DomeniaLogText $Detail
    try {
        Initialize-DomeniaDataStore | Out-Null
        $clean = (($Detail + "") -replace "[\r\n\t]+", " ").Trim()
        $thread = [System.Threading.Thread]::CurrentThread.ManagedThreadId
        $line = "{0}`t{1}`t{2}`t{3}`t{4}`t{5}`t{6}{7}" -f (Get-Date).ToString("yyyy-MM-dd HH:mm:ss.fff"),$script:StartupCorrelation,$thread,$Stage,$Status,$DurationMs,$clean,[Environment]::NewLine
        [System.IO.File]::AppendAllText($script:StartupTracePath,$line,(New-Object System.Text.UTF8Encoding($false)))
    }
    catch { Write-DomeniaSwallowed 'Core' 'Write-StartupTrace' $_ }
}

function Get-DomeniaStartupXaml {
    return (Convert-DomeniaXamlToBootTheme -Xaml @"
<Window Foreground="{DynamicResource DomeniaBootText}" xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Domenia 1.0  Initialisation" Width="650" Height="360" ResizeMode="NoResize" WindowStartupLocation="CenterScreen"
        Background="{DynamicResource DomeniaBootWindow}" ShowInTaskbar="True" Topmost="False">
  <Window.Resources>

    <Style TargetType="Button" BasedOn="{StaticResource DomeniaBootButtonBase}"><Setter Property="Margin" Value="4"/><Setter Property="Padding" Value="12,7"/><Setter Property="Background" Value="{DynamicResource DomeniaBootSurface}"/><Setter Property="BorderBrush" Value="{DynamicResource DomeniaBootBorder}"/><Setter Property="BorderThickness" Value="1"/></Style>
    <Style TargetType="TextBox" BasedOn="{StaticResource DomeniaBootTextBoxBase}"/>
    <Style TargetType="PasswordBox" BasedOn="{StaticResource DomeniaBootPasswordBoxBase}"/>
  </Window.Resources>
  <Border Margin="18" Padding="20" CornerRadius="20" Background="{DynamicResource DomeniaBootSurface}" BorderBrush="{DynamicResource DomeniaBootBorder}" BorderThickness="1">
    <Grid>
      <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
      <TextBlock Foreground="{DynamicResource DomeniaBootText}" Grid.Row="0" FontSize="27" FontWeight="Bold"><Run Text="Domenia" Foreground="{DynamicResource DomeniaBootText}"/></TextBlock>
      <TextBlock Foreground="{DynamicResource DomeniaBootText}" Grid.Row="1" x:Name="LblStartupStage" Text="Preparation..." FontSize="16" FontWeight="SemiBold" Margin="0,8,0,6"/>
      <ProgressBar Grid.Row="2" Height="8" IsIndeterminate="True" Foreground="{DynamicResource DomeniaBootAccentText}" Margin="0,0,0,10"/>
      <TextBox Grid.Row="3" x:Name="TxtStartupDetail" Foreground="{DynamicResource DomeniaBootText}" CaretBrush="{DynamicResource DomeniaBootText}" IsReadOnly="True" AcceptsReturn="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" Background="{DynamicResource DomeniaBootInput}" BorderBrush="{DynamicResource DomeniaBootBorder}" Padding="10"/>
      <Grid Grid.Row="4" Margin="0,10,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
        <TextBlock Grid.Column="0" x:Name="LblStartupElapsed" Text="0 s" Foreground="{DynamicResource DomeniaBootMuted}" VerticalAlignment="Center"/>
        <Button Grid.Column="1" x:Name="BtnStartupLog" Content="Ouvrir le journal"/>
        <Button Grid.Column="2" x:Name="BtnStartupCancel" Content="Annuler"/>
      </Grid>
    </Grid>
  </Border>
</Window>
"@)
}

function New-DomeniaStartupWindow {
    if (-not [bool](Get-CfgValue "Startup" "ShowMonitor" $true)) { return }
    try {
        $xamlText = Get-DomeniaStartupXaml
        $win = ConvertFrom-DomeniaXaml -XamlText $xamlText -Context "Moniteur de demarrage"
        Set-AppWindowIcon $win
        $script:StartupWindow = $win
        $script:StartupCtrl = @{
            Stage = $win.FindName("LblStartupStage")
            Detail = $win.FindName("TxtStartupDetail")
            Elapsed = $win.FindName("LblStartupElapsed")
            Log = $win.FindName("BtnStartupLog")
            Cancel = $win.FindName("BtnStartupCancel")
        }
        $script:StartupCancelled = $false
        $script:StartupCtrl.Log.Add_Click({ try { Start-Process notepad.exe -ArgumentList @($script:StartupTracePath) } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaStartupWindow' $_ } })
        $script:StartupCtrl.Cancel.Add_Click({
            $script:StartupCancelled = $true
            try { $script:StartupCtrl.Cancel.IsEnabled = $false } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaStartupWindow' $_ }
            Set-DomeniaStartupStage -Stage "Annulation..." -Detail "Annulation demandee ; arret propre du worker en cours."
        })
        $win.Add_Closing({ if (-not $script:StartupReady) { $script:StartupCancelled = $true } })
        # FI-05: protected standalone timer, registered with its owner by the factory (the engine is not started yet).
        $script:StartupTimer = New-DomeniaTimer -Owner 'Timer:StartupMonitor' -IntervalMs 1000 -Standalone -RunWhenHidden -Start -Tick {
            try {
                if ($null -ne $script:LoginAuthStarted -and $script:StartupCtrl.ContainsKey("Elapsed")) {
                    $script:StartupCtrl.Elapsed.Text = "$([int]((Get-Date)-$script:LoginAuthStarted).TotalSeconds) s"
                }
            } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaStartupWindow' $_ }
        }
        # D089: the monitor prolongs the explicit launch. It is never Topmost; one activation request, and a
        # voluntary Alt-Tab of the operator is remembered for the switch to the main window.
        try { Register-DomeniaUserSwitchWatch -Window $win } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaStartupWindow' $_ }
        try { [void](Set-DomeniaWindowActivationPolicy -Window $win -UserSwitchedAway:(Test-DomeniaUserSwitchedAway)) } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaStartupWindow' $_ }
        $win.Show() | Out-Null
        try { [void](Request-DomeniaWindowActivation -Window $win -Trigger 'StartupMonitor') } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaStartupWindow' $_ }
        [System.Windows.Forms.Application]::DoEvents()
    }
    catch {
        try { Write-StartupTrace -Stage "Moniteur de demarrage" -Status "WARN" -Detail $_.Exception.ToString() } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaStartupWindow' $_ }
        $script:StartupWindow = $null
        $script:StartupCtrl = @{}
    }
}

function Set-DomeniaStartupStage {
    param([string]$Stage,[string]$Detail="")
    try {
        if ($null -eq $script:StartupWindow) { return }
        $script:StartupCtrl.Stage.Text = $Stage
        if (-not [string]::IsNullOrWhiteSpace($Detail)) {
            $script:StartupCtrl.Detail.AppendText("[$((Get-Date).ToString('HH:mm:ss'))] $Detail`r`n")
            $script:StartupCtrl.Detail.ScrollToEnd()
        }
        if ($null -ne $script:LoginAuthStarted) { $script:StartupCtrl.Elapsed.Text = "$([int]((Get-Date)-$script:LoginAuthStarted).TotalSeconds) s" }
        [System.Windows.Forms.Application]::DoEvents()
    }
    catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaStartupStage' $_ }
}

function Close-DomeniaStartupWindow {
    try { if ($null -ne $script:StartupTimer) { $script:StartupTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Close-DomeniaStartupWindow' $_ }
    $script:StartupTimer = $null
    try { if ($null -ne $script:StartupWindow) { $script:StartupWindow.Close() } } catch { Write-DomeniaSwallowed 'Core' 'Close-DomeniaStartupWindow' $_ }
    $script:StartupWindow = $null
    $script:StartupCtrl = @{}
}

function Invoke-DomeniaStartupStage {
    param([string]$Stage,[scriptblock]$Action)
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    Set-DomeniaStartupStage -Stage $Stage -Detail "$Stage : demarrage"
    Write-StartupTrace -Stage $Stage -Status "START"
    try {
        $result = & $Action
        $sw.Stop()
        Set-DomeniaStartupStage -Stage $Stage -Detail "$Stage : termine en $($sw.ElapsedMilliseconds) ms"
        Write-StartupTrace -Stage $Stage -Status "OK" -DurationMs $sw.ElapsedMilliseconds
        return $result
    }
    catch {
        $sw.Stop()
        $detail = $_.Exception.ToString()
        Set-DomeniaStartupStage -Stage "$Stage - ERREUR" -Detail $detail
        Write-StartupTrace -Stage $Stage -Status "ERROR" -Detail $detail -DurationMs $sw.ElapsedMilliseconds
        throw
    }
}

$script:DomeniaDatabaseReady = $false
$script:DomeniaDatabaseRecoveryAttempted = $false
$script:WinSqliteNative = $null

function Get-DomeniaDatabasePath {
    Initialize-DomeniaDataStore | Out-Null
    $name = [string](Get-CfgValue 'LocalStore' 'DatabaseFile' 'Domenia.db')
    if ([string]::IsNullOrWhiteSpace($name)) { $name = 'Domenia.db' }
    if ($name -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]*\.db$' -or $name.Contains('..')) {
        throw 'LocalStore.DatabaseFile doit etre un nom de fichier .db, sans chemin.'
    }
    if([bool]$script:DemoMode){
        if([string]$script:Conn.BaseDn -ine 'DC=demo,DC=invalid'){throw 'Base de demonstration invalide : aucun stockage du domaine reel utilise.'}
        $demoDirectory=Join-Path ([string]$script:DataDir) 'Demonstration'
        if(-not [IO.Directory]::Exists($demoDirectory)){[void][IO.Directory]::CreateDirectory($demoDirectory)}
        $demoPath=Join-Path $demoDirectory 'Domenia-demo.db'
        if([string]$script:DatabaseScopedPath -cne $demoPath){$script:DomeniaDatabaseReady=$false;$script:DomeniaDatabaseRecoveryAttempted=$false}
        $script:DatabaseScopeIdentity='demonstration|dc=demo,dc=invalid';$script:DatabaseScopedPath=$demoPath
        return $demoPath
    }
    $legacy = Join-Path ([string]$script:DataDir) $name
    if($name -ieq 'Domenia.db' -and -not [IO.File]::Exists($legacy)){
        $old=Join-Path ([string]$script:DataDir) 'ADCC.db'
        if([IO.File]::Exists($old)){$legacy=$old}
    }
    $baseDn = ([string]$script:Conn.BaseDn).Trim().ToLowerInvariant()
    if ([string]::IsNullOrWhiteSpace($baseDn)) { return $legacy }
    if ([string]$script:DatabaseScopeIdentity -ceq $baseDn -and -not [string]::IsNullOrWhiteSpace([string]$script:DatabaseScopedPath)) {
        return [string]$script:DatabaseScopedPath
    }
    $preferred=[string](Get-DomeniaSetting (Get-DomeniaDatabasePreferenceKey $baseDn) '')
    if($preferred){
        # Fail visibly if a chosen disk disappeared; silently creating an empty default would hide the real inventory.
        $preferred=Get-DomeniaLocalDatabasePath -Path $preferred -Existing
        $preferenceDb=[IntPtr]::Zero
        try{
            $preferenceDb=Open-DomeniaDatabase -Path $preferred -ReadOnly
            $identity=@(Invoke-DomeniaDbQuery 'SELECT store_id,domain_dn FROM domenia_store_state WHERE id=1;' $preferenceDb)
            if($identity.Count -ne 1 -or [string]$identity[0].domain_dn -ine $baseDn -or [string]$identity[0].store_id -cne (Get-DomeniaStoreId $preferred $baseDn)){throw 'La base choisie ne confirme pas son domaine ou son emplacement. Restaurez-la avec lʼassistant de stockage.'}
        }finally{Close-DomeniaDatabase $preferenceDb}
        $script:DatabaseScopeIdentity=$baseDn;$script:DatabaseScopedPath=$preferred
        $script:DomeniaDatabaseReady=$false;$script:DomeniaDatabaseRecoveryAttempted=$false
        return $preferred
    }
    # Adopt the previous database only when its AD scope is positively identified.
    # Never move/delete the user's legacy database or merge two domains by short name.
    $chosen = $null
    if ([IO.File]::Exists($legacy)) {
        $probeDb = [IntPtr]::Zero
        try {
            $probeDb = Open-DomeniaDatabase -Path $legacy -ReadOnly
            $metadata = @(Invoke-DomeniaDbQuery -Sql "SELECT base_dn FROM sync_state WHERE scope='directory' LIMIT 1;" -DatabaseHandle $probeDb)
            if ($metadata.Count -eq 1 -and ([string]$metadata[0].base_dn).Trim().ToLowerInvariant() -ceq $baseDn) { $chosen = $legacy }
        } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaDatabasePath' $_ } finally { Close-DomeniaDatabase $probeDb }
    }
    if ([string]::IsNullOrWhiteSpace([string]$chosen)) {
        $scopeDirectory = Join-Path (Join-Path ([string]$script:DataDir) 'Domains') (Get-DomeniaScopeKey $baseDn)
        if (-not [IO.Directory]::Exists($scopeDirectory)) { [void][IO.Directory]::CreateDirectory($scopeDirectory) }
        $chosen = Join-Path $scopeDirectory $name
        if($name -ieq 'Domenia.db' -and -not [IO.File]::Exists($chosen)){
            $old=Join-Path $scopeDirectory 'ADCC.db'
            if([IO.File]::Exists($old)){$chosen=$old}
        }
    }
    $script:DomeniaDatabaseReady = $false
    $script:DomeniaDatabaseRecoveryAttempted = $false
    $script:DatabaseScopeIdentity = $baseDn
    $script:DatabaseScopedPath = $chosen
    return $chosen
}

function Initialize-DomeniaWinSqliteNative {
    if ($null -ne $script:WinSqliteNative) { return $script:WinSqliteNative }
    $loaded = [Type]::GetType("Domenia.WinSqliteNative, Domenia.WinSqlite.Dynamic", $false)
    if ($null -ne $loaded) { $script:WinSqliteNative = $loaded; return $loaded }

    $assemblyName = New-Object System.Reflection.AssemblyName("Domenia.WinSqlite.Dynamic")
    $assembly = [AppDomain]::CurrentDomain.DefineDynamicAssembly($assemblyName,[System.Reflection.Emit.AssemblyBuilderAccess]::Run)
    $module = $assembly.DefineDynamicModule("Domenia.WinSqlite.Dynamic.Module")
    $typeBuilder = $module.DefineType("Domenia.WinSqliteNative",[System.Reflection.TypeAttributes]::Public -bor [System.Reflection.TypeAttributes]::Sealed -bor [System.Reflection.TypeAttributes]::Abstract)
    $attrs = [System.Reflection.MethodAttributes]::Public -bor [System.Reflection.MethodAttributes]::Static -bor [System.Reflection.MethodAttributes]::PinvokeImpl
    $preserve = [System.Reflection.MethodImplAttributes]::PreserveSig
    $cdecl = [System.Runtime.InteropServices.CallingConvention]::Cdecl
    $ansi = [System.Runtime.InteropServices.CharSet]::Ansi

    $defs = @(
        @{N="sqlite3_open_v2"; R=[int]; P=[Type[]]@([IntPtr],[IntPtr].MakeByRefType(),[int],[IntPtr])},
        @{N="sqlite3_close"; R=[int]; P=[Type[]]@([IntPtr])},
        @{N="sqlite3_backup_init"; R=[IntPtr]; P=[Type[]]@([IntPtr],[IntPtr],[IntPtr],[IntPtr])},
        @{N="sqlite3_backup_step"; R=[int]; P=[Type[]]@([IntPtr],[int])},
        @{N="sqlite3_backup_finish"; R=[int]; P=[Type[]]@([IntPtr])},
        @{N="sqlite3_exec"; R=[int]; P=[Type[]]@([IntPtr],[IntPtr],[IntPtr],[IntPtr],[IntPtr].MakeByRefType())},
        @{N="sqlite3_free"; R=[void]; P=[Type[]]@([IntPtr])},
        @{N="sqlite3_errmsg"; R=[IntPtr]; P=[Type[]]@([IntPtr])},
        @{N="sqlite3_busy_timeout"; R=[int]; P=[Type[]]@([IntPtr],[int])},
        @{N="sqlite3_prepare_v2"; R=[int]; P=[Type[]]@([IntPtr],[IntPtr],[int],[IntPtr].MakeByRefType(),[IntPtr])},
        @{N="sqlite3_step"; R=[int]; P=[Type[]]@([IntPtr])},
        @{N="sqlite3_finalize"; R=[int]; P=[Type[]]@([IntPtr])},
        @{N="sqlite3_column_count"; R=[int]; P=[Type[]]@([IntPtr])},
        @{N="sqlite3_column_name"; R=[IntPtr]; P=[Type[]]@([IntPtr],[int])},
        @{N="sqlite3_column_type"; R=[int]; P=[Type[]]@([IntPtr],[int])},
        @{N="sqlite3_column_text"; R=[IntPtr]; P=[Type[]]@([IntPtr],[int])},
        @{N="sqlite3_column_bytes"; R=[int]; P=[Type[]]@([IntPtr],[int])},
        @{N="sqlite3_column_int64"; R=[long]; P=[Type[]]@([IntPtr],[int])},
        @{N="sqlite3_column_double"; R=[double]; P=[Type[]]@([IntPtr],[int])},
        # Point 39 (bound reads of LocalIndexRead) and PF-07 (prepared bulk writes of LocalStore): one set of prepared
        # statement bindings for every worker. Text is bound as UTF-16 (CharSet Unicode, explicit byte length,
        # SQLITE_TRANSIENT so that SQLite copies it during the call); nothing typed is concatenated into SQL.
        @{N="sqlite3_bind_parameter_count"; R=[int]; P=[Type[]]@([IntPtr])},
        @{N="sqlite3_bind_null"; R=[int]; P=[Type[]]@([IntPtr],[int])},
        @{N="sqlite3_bind_int64"; R=[int]; P=[Type[]]@([IntPtr],[int],[long])},
        @{N="sqlite3_bind_double"; R=[int]; P=[Type[]]@([IntPtr],[int],[double])},
        @{N="sqlite3_bind_text16"; R=[int]; P=[Type[]]@([IntPtr],[int],[string],[int],[IntPtr]); C=[System.Runtime.InteropServices.CharSet]::Unicode},
        @{N="sqlite3_reset"; R=[int]; P=[Type[]]@([IntPtr])},
        @{N="sqlite3_clear_bindings"; R=[int]; P=[Type[]]@([IntPtr])}
    )
    foreach ($d in $defs) {
        $charset = $ansi
        if ($d.ContainsKey('C')) { $charset = $d.C }
        $m = $typeBuilder.DefinePInvokeMethod([string]$d.N,"winsqlite3.dll",$attrs,[System.Reflection.CallingConventions]::Standard,[Type]$d.R,[Type[]]$d.P,$cdecl,$charset)
        $m.SetImplementationFlags($m.GetMethodImplementationFlags() -bor $preserve)
    }
    $script:WinSqliteNative = $typeBuilder.CreateType()
    return $script:WinSqliteNative
}

function New-DomeniaUtf8Ptr {
    param([AllowEmptyString()][string]$Text)
    $bytes = [System.Text.Encoding]::UTF8.GetBytes(([string]$Text) + [char]0)
    $ptr = [System.Runtime.InteropServices.Marshal]::AllocHGlobal($bytes.Length)
    [System.Runtime.InteropServices.Marshal]::Copy($bytes,0,$ptr,$bytes.Length)
    return $ptr
}

function ConvertFrom-DomeniaUtf8Ptr {
    param([IntPtr]$Pointer,[int]$Length = -1)
    if ($Pointer -eq [IntPtr]::Zero) { return "" }
    if ($Length -lt 0) {
        $Length = 0
        while ([System.Runtime.InteropServices.Marshal]::ReadByte($Pointer,$Length) -ne 0) { $Length++ }
    }
    if ($Length -le 0) { return "" }
    $bytes = New-Object byte[] $Length
    [System.Runtime.InteropServices.Marshal]::Copy($Pointer,$bytes,0,$Length)
    return [System.Text.Encoding]::UTF8.GetString($bytes)
}

function Open-DomeniaDatabase {
    param([string]$Path = '',[switch]$ReadOnly)
    $native = Initialize-DomeniaWinSqliteNative
    $db = [IntPtr]::Zero
    $pathPtr = [IntPtr]::Zero
    $lease=$null
    try {
        if ([string]::IsNullOrWhiteSpace($Path)) { $Path = Get-DomeniaDatabasePath }
        if(-not $ReadOnly){$lease=Enter-StoreWDatabaseLease -Path $Path -TimeoutMs 1000}
        $pathPtr = New-DomeniaUtf8Ptr $Path
        $flags = if ($ReadOnly) { 1 -bor 65536 } else { 2 -bor 4 -bor 65536 }
        $rc = [Domenia.WinSqliteNative]::sqlite3_open_v2($pathPtr,[ref]$db,$flags,[IntPtr]::Zero)
        if ($rc -ne 0 -or $db -eq [IntPtr]::Zero) { throw "Ouverture SQLite impossible (code $rc)." }
        # FI-12: same documented default as the workers (2 500 ms) when the setting is absent.
        [void][Domenia.WinSqliteNative]::sqlite3_busy_timeout($db,[Math]::Max(100,[Math]::Min(5000,[int](Get-CfgValue 'LocalStore' 'DatabaseBusyTimeoutMs' 2500))))
        if(-not $ReadOnly){
            Assert-StoreWDatabaseWritable -Db $db
            if($null -eq $script:DomeniaDatabaseLeases){$script:DomeniaDatabaseLeases=@{}}
            $script:DomeniaDatabaseLeases[$db.ToInt64()]=$lease;$lease=$null
        }
        return $db
    }
    catch {
        # sqlite3_open_v2 can return a non-null handle even on failure.
        if ($db -ne [IntPtr]::Zero) { [void][Domenia.WinSqliteNative]::sqlite3_close($db) }
        throw
    }
    finally { if($null -ne $lease){Exit-StoreWDatabaseLease $lease}; if ($pathPtr -ne [IntPtr]::Zero) { [Runtime.InteropServices.Marshal]::FreeHGlobal($pathPtr) } }
}

function Close-DomeniaDatabase {
    param([IntPtr]$DatabaseHandle)
    if($DatabaseHandle -eq [IntPtr]::Zero){return}
    Initialize-DomeniaWinSqliteNative | Out-Null
    $rc=[Domenia.WinSqliteNative]::sqlite3_close($DatabaseHandle)
    if($rc -ne 0){throw ('Fermeture SQLite non confirmee (code '+$rc+'). Verrou local conserve.')}
    if($null -ne $script:DomeniaDatabaseLeases -and $script:DomeniaDatabaseLeases.ContainsKey($DatabaseHandle.ToInt64())){
        $lease=$script:DomeniaDatabaseLeases[$DatabaseHandle.ToInt64()];$script:DomeniaDatabaseLeases.Remove($DatabaseHandle.ToInt64())
        Exit-StoreWDatabaseLease $lease
    }
}

function Invoke-DomeniaDbExec {
    param([Parameter(Mandatory=$true)][AllowEmptyString()][string]$Sql,[IntPtr]$DatabaseHandle = [IntPtr]::Zero)
    $own = ($DatabaseHandle -eq [IntPtr]::Zero)
    $sqlPtr = [IntPtr]::Zero
    $errPtr = [IntPtr]::Zero
    try {
        if ($own) { $DatabaseHandle = Open-DomeniaDatabase }
        $native = Initialize-DomeniaWinSqliteNative
        $sqlPtr = New-DomeniaUtf8Ptr $Sql
        $rc = [Domenia.WinSqliteNative]::sqlite3_exec($DatabaseHandle,$sqlPtr,[IntPtr]::Zero,[IntPtr]::Zero,[ref]$errPtr)
        if ($rc -ne 0) {
            $msg = if ($errPtr -ne [IntPtr]::Zero) { ConvertFrom-DomeniaUtf8Ptr $errPtr } else { ConvertFrom-DomeniaUtf8Ptr ([Domenia.WinSqliteNative]::sqlite3_errmsg($DatabaseHandle)) }
            throw "SQLite code $rc : $msg"
        }
        return $true
    }
    finally {
        if ($errPtr -ne [IntPtr]::Zero) { try { Initialize-DomeniaWinSqliteNative | Out-Null; [Domenia.WinSqliteNative]::sqlite3_free($errPtr) } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaDbExec' $_ } }
        if ($sqlPtr -ne [IntPtr]::Zero) { [System.Runtime.InteropServices.Marshal]::FreeHGlobal($sqlPtr) }
        if ($own) { Close-DomeniaDatabase $DatabaseHandle }
    }
}

function Invoke-DomeniaDbQuery {
    param([Parameter(Mandatory=$true)][AllowEmptyString()][string]$Sql,[IntPtr]$DatabaseHandle = [IntPtr]::Zero)
    $own = ($DatabaseHandle -eq [IntPtr]::Zero)
    $sqlPtr = [IntPtr]::Zero
    $stmt = [IntPtr]::Zero
    $rows = New-Object System.Collections.Generic.List[object]
    try {
        if ($own) { $DatabaseHandle = Open-DomeniaDatabase }
        $native = Initialize-DomeniaWinSqliteNative
        $sqlPtr = New-DomeniaUtf8Ptr $Sql
        $rc = [Domenia.WinSqliteNative]::sqlite3_prepare_v2($DatabaseHandle,$sqlPtr,-1,[ref]$stmt,[IntPtr]::Zero)
        if ($rc -ne 0) { throw "SQLite prepare code $rc : $(ConvertFrom-DomeniaUtf8Ptr ([Domenia.WinSqliteNative]::sqlite3_errmsg($DatabaseHandle)))" }
        $count = [Domenia.WinSqliteNative]::sqlite3_column_count($stmt)
        while (($step = [Domenia.WinSqliteNative]::sqlite3_step($stmt)) -eq 100) {
            $o = [ordered]@{}
            for ($i=0;$i -lt $count;$i++) {
                $name = ConvertFrom-DomeniaUtf8Ptr ([Domenia.WinSqliteNative]::sqlite3_column_name($stmt,$i))
                $type = [Domenia.WinSqliteNative]::sqlite3_column_type($stmt,$i)
                $value = $null
                switch ($type) {
                    1 { $value = [long][Domenia.WinSqliteNative]::sqlite3_column_int64($stmt,$i) }
                    2 { $value = [double][Domenia.WinSqliteNative]::sqlite3_column_double($stmt,$i) }
                    3 { $p=[Domenia.WinSqliteNative]::sqlite3_column_text($stmt,$i); $n=[Domenia.WinSqliteNative]::sqlite3_column_bytes($stmt,$i); $value=ConvertFrom-DomeniaUtf8Ptr $p $n }
                    5 { $value = $null }
                    default { $p=[Domenia.WinSqliteNative]::sqlite3_column_text($stmt,$i); $n=[Domenia.WinSqliteNative]::sqlite3_column_bytes($stmt,$i); $value=ConvertFrom-DomeniaUtf8Ptr $p $n }
                }
                $o[$name] = $value
            }
            $rows.Add([pscustomobject]$o)
        }
        if ($step -ne 101) { throw "SQLite step code $step : $(ConvertFrom-DomeniaUtf8Ptr ([Domenia.WinSqliteNative]::sqlite3_errmsg($DatabaseHandle)))" }
        return $rows.ToArray()
    }
    finally {
        if ($stmt -ne [IntPtr]::Zero) { try { Initialize-DomeniaWinSqliteNative | Out-Null; [void][Domenia.WinSqliteNative]::sqlite3_finalize($stmt) } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaDbQuery' $_ } }
        if ($sqlPtr -ne [IntPtr]::Zero) { [System.Runtime.InteropServices.Marshal]::FreeHGlobal($sqlPtr) }
        if ($own) { Close-DomeniaDatabase $DatabaseHandle }
    }
}

function ConvertTo-DomeniaSqlLiteral {
    param($Value)
    if ($null -eq $Value) { return "NULL" }
    if ($Value -is [bool]) { return $(if ($Value) { "1" } else { "0" }) }
    if ($Value -is [byte] -or $Value -is [int16] -or $Value -is [int32] -or $Value -is [int64] -or $Value -is [double] -or $Value -is [decimal]) { return ([Convert]::ToString($Value,[Globalization.CultureInfo]::InvariantCulture)) }
    return "'" + (([string]$Value) -replace "'","''") + "'"
}


function Backup-DomeniaDatabase {
    param([switch]$IfNeeded,[switch]$Migration)
    $dbPath = Get-DomeniaDatabasePath
    if (-not [IO.File]::Exists($dbPath)) { return $null }
    $backupDir = Get-DomeniaStoreBackupDirectory
    # D115: a backup taken before a schema migration lives outside the normal rotation and is never pruned here.
    if ($Migration) {
        $backupDir = Join-Path $backupDir 'migrations'
        [void][IO.Directory]::CreateDirectory($backupDir)
    }
    if ($IfNeeded -and (-not $Migration)) {
        $latest = Get-ChildItem -LiteralPath $backupDir -Filter 'Domenia-*.db' -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
        if ($null -ne $latest -and ((Get-Date) - $latest.LastWriteTime).TotalHours -lt 20) { return [string]$latest.FullName }
    }
    $stamp = (Get-Date -Format 'yyyyMMdd-HHmmss-fff') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8)
    if ($Migration) { $stamp = 'migration-' + $stamp }
    $dest = Join-Path $backupDir ('Domenia-' + $stamp + '.db')
    $temporary = $dest + '.partial'
    $sourceDb = [IntPtr]::Zero; $targetDb = [IntPtr]::Zero; $backup = [IntPtr]::Zero; $mainPtr = [IntPtr]::Zero
    $complete = $false
    try {
        $sourceDb = Open-DomeniaDatabase -Path $dbPath -ReadOnly
        $targetDb = Open-DomeniaDatabase -Path $temporary
        $mainPtr = New-DomeniaUtf8Ptr 'main'
        $backup = [Domenia.WinSqliteNative]::sqlite3_backup_init($targetDb,$mainPtr,$sourceDb,$mainPtr)
        if ($backup -eq [IntPtr]::Zero) { throw 'Initialisation de la sauvegarde SQLite impossible.' }
        $watch = [Diagnostics.Stopwatch]::StartNew()
        $budget = [Math]::Max(5,[Math]::Min(120,[int](Get-CfgValue 'LocalStore' 'BackupTimeoutSeconds' 30)))
        do {
            $rc = [Domenia.WinSqliteNative]::sqlite3_backup_step($backup,256)
            if ($rc -eq 101) { break }
            if ($rc -notin @(0,5,6)) { throw "Sauvegarde SQLite : code $rc." }
            if ($watch.Elapsed.TotalSeconds -ge $budget) { throw "Sauvegarde SQLite interrompue apres $budget secondes. L'original est intact." }
            if ($rc -in @(5,6)) { Start-Sleep -Milliseconds 25 }
        } while ($true)
        $finish = [Domenia.WinSqliteNative]::sqlite3_backup_finish($backup); $backup = [IntPtr]::Zero
        if ($finish -ne 0) { throw "Finalisation de sauvegarde SQLite : code $finish." }
        $check = @(Invoke-DomeniaDbQuery -Sql 'PRAGMA quick_check;' -DatabaseHandle $targetDb)
        if ($check.Count -ne 1 -or [string]$check[0].quick_check -cne 'ok') { throw 'La sauvegarde ne passe pas le controle SQLite.' }
        Close-DomeniaDatabase $targetDb; $targetDb = [IntPtr]::Zero
        Close-DomeniaDatabase $sourceDb; $sourceDb = [IntPtr]::Zero
        [IO.File]::Move($temporary,$dest)
        $complete = $true
        if (-not $Migration) {
            $keep = [Math]::Max(2,[Math]::Min(30,[int](Get-CfgValue 'LocalStore' 'DatabaseBackupCount' 7)))
            Get-ChildItem -LiteralPath $backupDir -Filter 'Domenia-*.db' -File | Sort-Object LastWriteTime -Descending | Select-Object -Skip $keep | ForEach-Object {
                Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue
            }
        }
        return $dest
    }
    finally {
        if ($backup -ne [IntPtr]::Zero) { [void][Domenia.WinSqliteNative]::sqlite3_backup_finish($backup) }
        Close-DomeniaDatabase $targetDb; Close-DomeniaDatabase $sourceDb
        if ($mainPtr -ne [IntPtr]::Zero) { [Runtime.InteropServices.Marshal]::FreeHGlobal($mainPtr) }
        if (-not $complete) {
            foreach ($suffix in @('','-wal','-shm','-journal')) { Remove-Item -LiteralPath ($temporary + $suffix) -Force -ErrorAction SilentlyContinue }
        }
    }
}

function Recover-DomeniaDatabase {
    param([string]$Reason)
    # Recovery requires an explicit operator decision, never an automatic data move.
    throw ('Le cache SQLite est illisible. Aucune base ni sauvegarde n''a ete deplacee ou ecrasee. Ferme DOMENIA, conserve le fichier .db ET ses fichiers -wal/-shm, puis restaure une sauvegarde verifiee. Detail : ' + $Reason)
}

function Get-DomeniaSqliteSchemaText {
    return @"
PRAGMA journal_mode=WAL;
PRAGMA synchronous=FULL;
PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS schema_info(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO schema_info(key,value) VALUES('schema_version','11');
CREATE TABLE IF NOT EXISTS ad_objects(
 object_key TEXT PRIMARY KEY, object_guid TEXT, object_type TEXT NOT NULL,
 name TEXT COLLATE NOCASE, login TEXT COLLATE NOCASE, upn TEXT COLLATE NOCASE,
 display_name TEXT, description TEXT, extra TEXT, state TEXT, distinguished_name TEXT,
 when_changed TEXT, usn_changed INTEGER DEFAULT 0, last_logon TEXT, search_key TEXT,
 source_dc TEXT, synced_at TEXT);
CREATE INDEX IF NOT EXISTS ix_ad_objects_guid ON ad_objects(object_guid);
CREATE INDEX IF NOT EXISTS ix_ad_objects_name ON ad_objects(name COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS ix_ad_objects_login ON ad_objects(login COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS ix_ad_objects_upn ON ad_objects(upn COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS ix_ad_objects_dn ON ad_objects(distinguished_name COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS ix_ad_objects_usn ON ad_objects(usn_changed);
CREATE INDEX IF NOT EXISTS ix_ad_objects_type ON ad_objects(object_type);
CREATE INDEX IF NOT EXISTS ix_ad_objects_type_name ON ad_objects(object_type,name COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS user_machine_links(
 computer_key TEXT PRIMARY KEY,user_login TEXT,computer TEXT,source TEXT,confidence INTEGER,
 verified_in_ad INTEGER,observed_at TEXT,details TEXT,user_guid TEXT,computer_guid TEXT,user_dn TEXT,computer_dn TEXT);
CREATE INDEX IF NOT EXISTS ix_links_user ON user_machine_links(user_login COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS user_machine_history(
 id INTEGER PRIMARY KEY AUTOINCREMENT,user_login TEXT,computer_key TEXT,computer TEXT,source TEXT,
 confidence INTEGER,verified_in_ad INTEGER,observed_at TEXT,details TEXT,user_guid TEXT,computer_guid TEXT);
CREATE INDEX IF NOT EXISTS ix_history_computer ON user_machine_history(computer_key,observed_at);
CREATE INDEX IF NOT EXISTS ix_history_user ON user_machine_history(user_login COLLATE NOCASE,observed_at);
CREATE TABLE IF NOT EXISTS park_state(computer_key TEXT PRIMARY KEY,computer TEXT,last_probe TEXT,status TEXT,user_login TEXT,attempts INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS presence_cache(object_key TEXT PRIMARY KEY,state TEXT,target TEXT,checked_at TEXT);
CREATE TABLE IF NOT EXISTS sync_state(scope TEXT PRIMARY KEY,server TEXT,base_dn TEXT,highest_usn INTEGER DEFAULT 0,last_sync TEXT,item_count INTEGER DEFAULT 0,details TEXT);
CREATE TABLE IF NOT EXISTS user_scan_history(
 login_key TEXT PRIMARY KEY,login TEXT,scanned_at TEXT,scanned INTEGER DEFAULT 0,
 candidates INTEGER DEFAULT 0,reachable INTEGER DEFAULT 0,probed INTEGER DEFAULT 0,found TEXT);
CREATE TABLE IF NOT EXISTS secret_state(
 computer_key TEXT PRIMARY KEY,computer TEXT,checked_at TEXT,bitlocker_keys INTEGER DEFAULT 0,
 bitlocker_last TEXT,laps_scheme TEXT,laps_expiry TEXT,verdict TEXT,detail TEXT);
CREATE TABLE IF NOT EXISTS operation_runs(
 id INTEGER PRIMARY KEY AUTOINCREMENT,operation TEXT NOT NULL,mode TEXT,item_count INTEGER DEFAULT 0,
 duration_ms INTEGER DEFAULT 0,bytes_estimated INTEGER DEFAULT 0,ad_queries INTEGER DEFAULT 0,
 remote_attempts INTEGER DEFAULT 0,fallback_tasks INTEGER DEFAULT 0,success_count INTEGER DEFAULT 0,
 failure_count INTEGER DEFAULT 0,started_at TEXT,finished_at TEXT,notes TEXT);
CREATE INDEX IF NOT EXISTS ix_runs_operation ON operation_runs(operation,finished_at);
CREATE VIEW IF NOT EXISTS operation_stats AS
 SELECT operation,count(*) AS samples,avg(duration_ms) AS avg_duration_ms,min(duration_ms) AS min_duration_ms,max(duration_ms) AS max_duration_ms,
        avg(bytes_estimated) AS avg_bytes,avg(CASE WHEN remote_attempts>0 THEN fallback_tasks*1.0/remote_attempts ELSE NULL END) AS fallback_ratio,
        sum(success_count) AS successes,sum(failure_count) AS failures
 FROM operation_runs GROUP BY operation;
CREATE TABLE IF NOT EXISTS domenia_provenance(object_guid TEXT PRIMARY KEY,domain_dn TEXT,reader TEXT,source_dc TEXT,invocation_id TEXT,usn_changed INTEGER,observed_at TEXT);
CREATE TABLE IF NOT EXISTS ad_computer_facts(object_guid TEXT PRIMARY KEY,object_key TEXT,os_version TEXT,when_created TEXT,pwd_last_set TEXT,laps_kind TEXT,laps_expiry TEXT,read_at TEXT);
CREATE TABLE IF NOT EXISTS fleet_snapshots(scope_key TEXT NOT NULL,snapshot_day TEXT NOT NULL,taken_at TEXT,scope_dn TEXT,machines INTEGER DEFAULT 0,figures TEXT,PRIMARY KEY(scope_key,snapshot_day));
CREATE TABLE IF NOT EXISTS park_session_cache(object_key TEXT PRIMARY KEY,checked_utc TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS domenia_store_state(id INTEGER PRIMARY KEY CHECK(id=1),store_id TEXT NOT NULL,domain_dn TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS domenia_store_batches(batch_id TEXT PRIMARY KEY,payload_hash TEXT NOT NULL,request_id TEXT NOT NULL,sequence INTEGER NOT NULL,revision INTEGER NOT NULL,committed_at TEXT NOT NULL,changes_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_store_batches_revision ON domenia_store_batches(revision);
CREATE TABLE IF NOT EXISTS domenia_directory_data(object_guid TEXT PRIMARY KEY,payload TEXT NOT NULL,field_times TEXT NOT NULL,revision INTEGER NOT NULL,observed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS domenia_observations(object_guid TEXT NOT NULL,family TEXT NOT NULL,dn TEXT NOT NULL,definition_hash TEXT NOT NULL DEFAULT '',attempt_at TEXT NOT NULL,status TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',success_at TEXT NOT NULL DEFAULT '',payload TEXT,attempt_payload TEXT,summary_payload TEXT,attempt_summary TEXT,revision INTEGER NOT NULL,PRIMARY KEY(object_guid,family));
CREATE INDEX IF NOT EXISTS idx_store_observations_dn ON domenia_observations(dn);
CREATE TABLE IF NOT EXISTS domenia_legacy_observation_imports(object_guid TEXT PRIMARY KEY,payload_hash TEXT NOT NULL,imported_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS domenia_account_preferences(domain_dn TEXT NOT NULL,scope TEXT NOT NULL,user_name TEXT NOT NULL,updated_at TEXT NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(domain_dn,scope));
CREATE TABLE IF NOT EXISTS domenia_details(object_guid TEXT NOT NULL,result_kind TEXT NOT NULL,request_key TEXT NOT NULL,dn TEXT NOT NULL,attempt_at TEXT NOT NULL,status TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',success_at TEXT NOT NULL DEFAULT '',payload TEXT,attempt_payload TEXT,summary_payload TEXT,attempt_summary TEXT,revision INTEGER NOT NULL,PRIMARY KEY(object_guid,result_kind,request_key));
CREATE TABLE IF NOT EXISTS domenia_domain_metadata(domain_dn TEXT NOT NULL,family TEXT NOT NULL,request_key TEXT NOT NULL,attempt_at TEXT NOT NULL,status TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',success_at TEXT NOT NULL DEFAULT '',payload TEXT,attempt_payload TEXT,revision INTEGER NOT NULL,PRIMARY KEY(domain_dn,family,request_key));
$(Get-DomeniaQueryLibrarySchema)
UPDATE ad_objects SET search_key=COALESCE(search_key,'')||' '||lower(extra) WHERE NOT EXISTS(SELECT 1 FROM sync_state WHERE scope='repair:search_key_extra') AND object_type IN ('Utilisateur','Machine') AND COALESCE(extra,'')<>'' AND instr(lower(COALESCE(search_key,'')),lower(extra))=0;
INSERT OR IGNORE INTO sync_state(scope,details) VALUES('repair:search_key_extra','CO-26');
INSERT OR IGNORE INTO schema_info(key,value) VALUES('domenia_schema','1');
COMMIT;
"@
}

function Initialize-DomeniaDatabase {
    [void](Get-DomeniaDatabasePath)
    if ($script:DomeniaDatabaseReady) { return $true }
    Initialize-DomeniaDataStore | Out-Null
    $migrationBackup = ''
    try {
        # D115/D113: forward-only schema decided by the pure rule (Release.Model). A newer, unreadable, too old or
        # interrupted base is refused untouched, with the rule's message; an older base is migrated only after a
        # migration backup kept outside the rotation.
        $schemaExists=(@(Invoke-DomeniaDbQuery "SELECT name FROM sqlite_master WHERE type='table' AND name='schema_info';").Count -gt 0)
        $dbVersion='';$dbRevision=''
        if($schemaExists){
            $versionRows=@(Invoke-DomeniaDbQuery "SELECT value FROM schema_info WHERE key='schema_version';")
            $revisionRows=@(Invoke-DomeniaDbQuery "SELECT value FROM schema_info WHERE key='domenia_schema';")
            if($versionRows.Count -gt 1 -or $revisionRows.Count -gt 1){throw 'Schema de base ambigu (cle schema_info en double). La base reste intacte.'}
            if($versionRows.Count -eq 1){$dbVersion=[string]$versionRows[0].value}
            if($revisionRows.Count -eq 1){$dbRevision=[string]$revisionRows[0].value}
        }
        $schemaPlan=Test-DomeniaSchemaCompatibility -DatabaseVersion $dbVersion -DatabaseRevision $dbRevision -DatabaseExists $schemaExists -BackupVerified $false
        if((-not [bool]$schemaPlan.CanOpen) -and (-not [bool]$schemaPlan.RequiresBackup)){throw ([string]$schemaPlan.Message)}
        if([bool]$schemaPlan.RequiresBackup){
            $migrationBackup=Backup-DomeniaDatabase -Migration
            if([string]::IsNullOrWhiteSpace([string]$migrationBackup)){throw 'Sauvegarde de migration impossible : la base reste intacte, aucune migration.'}
            Write-AppLog ('Sauvegarde avant migration du schema : '+[string]$migrationBackup) 'INFO'
        }
        $schema = Get-DomeniaSqliteSchemaText
        # PF-26 (lot X06): park_session_cache joins the script (additive, schema_info unchanged), so that the LocalStore
        # worker no longer creates it for each observation of the park.
        # Lot L01 (decision David 2026-10-08): two additive tables (computer facts, daily fleet snapshots) created like the
        # others, schema_info unchanged (11/1, never updated): an RC1.13 ignores them. The UPDATE repairs the search keys
        # written without the extra field by the single-row updates of RC1.13.0 and before (CO-26), once per base: the
        # marker row of sync_state (scope 'repair:search_key_extra', read by nothing else) skips the scan at every later
        # start, whatever the case of the extra field (SQLite lower() only folds ASCII).
        # Demarrage ultra-court : creation/upgrade du schema uniquement.
        # Aucun quick_check complet, aucune migration TSV/CSV et aucune copie
        # de sauvegarde ne doivent bloquer le thread WPF au lancement.
        $migrationDb=Open-DomeniaDatabase
        try{
            [void](Invoke-DomeniaDbExec -Sql ($schema -replace '(?m)^COMMIT;\s*$','') -DatabaseHandle $migrationDb)
            foreach($table in @('domenia_details','domenia_observations')){
                $columns=@(Invoke-DomeniaDbQuery ('PRAGMA table_info('+$table+');') $migrationDb|ForEach-Object{[string]$_.name})
                foreach($column in @('summary_payload','attempt_summary')){
                    if($column -notin $columns){[void](Invoke-DomeniaDbExec ('ALTER TABLE '+$table+' ADD COLUMN '+$column+' TEXT;') $migrationDb)}
                }
            }
            # Point 36: targeted check of the result inside the same transaction. A missing table or column rolls the
            # whole step back; the base stays as it was, with its migration backup when one was required.
            $schemaTables=@(Invoke-DomeniaDbQuery "SELECT name FROM sqlite_master WHERE type='table';" $migrationDb|ForEach-Object{[string]$_.name})
            $schemaColumns=@{};foreach($table in @((Get-DomeniaStorageSchemaExpectation).Columns.Keys)){$schemaColumns[[string]$table]=@(Invoke-DomeniaDbQuery ('PRAGMA table_info('+[string]$table+');') $migrationDb|ForEach-Object{[string]$_.name})}
            $schemaGaps=@(Get-DomeniaStorageSchemaGaps -Tables $schemaTables -Columns $schemaColumns)
            if($schemaGaps.Count){throw ('Schéma incomplet après mise à niveau, transaction annulée : '+($schemaGaps -join ', ')+'.')}
            [void](Invoke-DomeniaDbExec 'COMMIT;' $migrationDb)
        }catch{try{[void](Invoke-DomeniaDbExec 'ROLLBACK;' $migrationDb)}catch{Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaDatabase' $_};throw}finally{Close-DomeniaDatabase $migrationDb}
        $probe = @(Invoke-DomeniaDbQuery "SELECT value FROM schema_info WHERE key='schema_version' LIMIT 1;")
        if ($probe.Count -eq 0) { throw "Schema SQLite initialise mais illisible." }
        $script:DomeniaDatabaseReady = $true
        return $true
    }
    catch {
        $script:DomeniaDatabaseReady = $false
        $msg=[string]$_.Exception.Message
        if (-not $script:DomeniaDatabaseRecoveryAttempted -and $msg -match "(?i)quick_check|malformed|corrupt|disk image|SQLite code 11") {
            $script:DomeniaDatabaseRecoveryAttempted=$true
            try { [void](Recover-DomeniaDatabase -Reason $msg); return (Initialize-DomeniaDatabase) }
            catch { $msg = $msg + " ; restauration impossible : " + $_.Exception.Message }
        }
        if ([string]$migrationBackup) { $msg = $msg + ' Sauvegarde faite avant la migration, conservée : ' + [string]$migrationBackup + '.' }
        Write-AppLog "Base autonome indisponible : $msg" "ERROR"
        throw $msg
    }
}

function Import-DomeniaLegacyStoreIfNeeded {
    param([switch]$DryRun,[string]$ExpectedFingerprint='')
    return (Invoke-DomeniaLegacyImport -DryRun:$DryRun -ExpectedFingerprint $ExpectedFingerprint)
}

function Invoke-DomeniaDatabaseMaintenance {
    # Migration simulation never initializes the database or records an operation sample.
    param([switch]$ImportLegacy,[switch]$IntegrityCheck,[switch]$Backup,[switch]$DryRun,[string]$ExpectedFingerprint='')
    if ($ImportLegacy) {
        if ($IntegrityCheck -or $Backup) { throw 'La reprise des anciennes donnees doit etre demandee seule.' }
        return (Import-DomeniaLegacyStoreIfNeeded -DryRun:$DryRun -ExpectedFingerprint $ExpectedFingerprint)
    }
    if ($DryRun) { throw 'La simulation est reservee a la reprise des anciennes donnees.' }
    $sw=[Diagnostics.Stopwatch]::StartNew()
    Initialize-DomeniaDatabase | Out-Null
    try {
        if ($IntegrityCheck) {
            $check=@(Invoke-DomeniaDbQuery 'PRAGMA quick_check;')
            if ($check.Count -eq 0 -or [string]$check[0].quick_check -ne 'ok') { throw 'PRAGMA quick_check a signale une incoherence.' }
        }
        if ($Backup) { [void](Backup-DomeniaDatabase) }
        try { Request-DomeniaIndexMetadata } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaDatabaseMaintenance' $_ }
        $sw.Stop()
        try { Register-DomeniaOperationSample -Operation 'DatabaseMaintenance' -Mode 'Local SQLite' -ItemCount 1 -DurationMs $sw.ElapsedMilliseconds -SuccessCount 1 } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaDatabaseMaintenance' $_ }
        return $true
    } catch {
        $sw.Stop()
        try { Register-DomeniaOperationSample -Operation 'DatabaseMaintenance' -Mode 'Local SQLite' -ItemCount 1 -DurationMs $sw.ElapsedMilliseconds -FailureCount 1 -Notes $_.Exception.Message } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaDatabaseMaintenance' $_ }
        throw
    }
}


function Register-DomeniaOperationSample {
    param([string]$Operation,[string]$Mode='', [int]$ItemCount=0,[long]$DurationMs=0,[long]$BytesEstimated=0,[int]$AdQueries=0,[int]$RemoteAttempts=0,[int]$FallbackTasks=0,[int]$SuccessCount=0,[int]$FailureCount=0,[string]$StartedAt='', [string]$Notes='')
    if($Operation -in @('LocalStore','ReceiptStore','DocumentStore')){return}
    $r=[ordered]@{}
    foreach($n in @('Operation','Mode','ItemCount','DurationMs','BytesEstimated','AdQueries','RemoteAttempts','FallbackTasks','SuccessCount','FailureCount','StartedAt')){$r[$n]=Get-Variable -Name $n -ValueOnly}
    $r.Finished=[datetime]::UtcNow.ToString('o');$r.Notes='' # Structured counters, not raw provider messages.
    [void](Queue-DomeniaMetadata -Kind Sample -Row ([pscustomobject]$r))
}

function Get-DomeniaOperationHistoryModel {
    # FI-19: the measured history comes from the last OperationStats reading kept in memory, never from SQLite on the
    # Dispatcher. Each estimate also asks for a new reading, so that the next one includes the latest samples; until a
    # first reading of this session arrives, the estimate uses its initial values (Confidence 'Initiale').
    param([string]$Operation)
    $models = $script:OperationHistoryModels
    $current = (($null -ne $models) -and ([long]$script:OperationHistoryModelsEpoch -eq [long]$script:SessionEpoch))
    try { Request-DomeniaOperationStats -Quiet } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaOperationHistoryModel' $_ }
    if ((-not $current) -or (-not $models.ContainsKey($Operation))) { return $null }
    return $models[$Operation]
}




function Export-DomeniaOperationStatsCsv {
    # Exports the statistics grid as Complete-DomeniaOperationStatsUi has just filled it (Request-DomeniaOperationStats
    # -Export): the measures are never read on the Dispatcher (FI-19).
    try {
        $grid=Get-DomeniaControl -Name "DgOperationStats"
        if(($null -eq $grid) -or (@($grid.ItemsSource).Count -eq 0)){Set-Status "Aucune statistique à exporter." "WARN";return}
        Show-DomeniaExportResult -Result (Export-DomeniaCsv -Rows @($grid.ItemsSource) -Grid $grid -Subject 'statistiques')
    } catch { [void](Show-DomeniaOperationError -Operation "Export statistiques" -ErrorRecordOrException $_) }
}

function Get-DomeniaOperationImpactEstimate {
    param([string]$Operation,[int]$ItemCount=0,[int]$MaxEvents=0,[int]$BudgetMs=0)
    $model=Get-DomeniaOperationHistoryModel $Operation
    $samples=0; try{$samples=[int]$model.n}catch{Write-DomeniaSwallowed 'Core' 'Get-DomeniaOperationImpactEstimate' $_}
    $durationMs=[long]0; $bytes=[long]0; $adQueries=0; $remote=0; $fallback=[double]0; $impact="Faible"; $initialBpi=24000.0; $initialMpi=1200.0
    switch($Operation){
        "IndexBuild" {
            if($ItemCount -le 0){$ItemCount=@($script:IndexRows).Count}; if($ItemCount -le 0){$ItemCount=100000}
            $initialBpi=1800.0;$initialMpi=0.8;$adQueries=[Math]::Max(1,[int][Math]::Ceiling($ItemCount/1000.0));$impact=$(if($ItemCount -gt 150000){"Eleve"}elseif($ItemCount -gt 40000){"Modere"}else{"Faible"})
        }
        "LogonHarvest" { if($MaxEvents-le0){$MaxEvents=[int](Get-CfgValue "ParkSweep" "HarvestMaxEvents" 5000)};$ItemCount=$MaxEvents;$initialBpi=2200.0;$initialMpi=3.0;$adQueries=1;$impact="Modere" }
        "ParkSweep" { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount;$initialBpi=24000.0;$initialMpi=1200.0;$impact=$(if($ItemCount-gt500){"Eleve"}elseif($ItemCount-gt100){"Modere"}else{"Faible"}) }
        "UserComputerProbe" { if($ItemCount-le0){$ItemCount=250};$remote=$ItemCount;$initialBpi=18000.0;$initialMpi=1100.0;$adQueries=4;$impact=$(if($ItemCount-gt200){"Eleve"}elseif($ItemCount-gt60){"Modere"}else{"Faible"}) }
        "ComputerInventory" { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount;$initialBpi=250000.0;$initialMpi=15000.0;$impact="Aucun appel AD direct" }
        "SoftwareInventory" { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount;$initialBpi=500000.0;$initialMpi=20000.0;$impact="Aucun appel AD direct" }
        "ComputerDiagnostics" { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount;$initialBpi=32000.0;$initialMpi=8000.0;$impact="Aucun appel AD direct" }
        "ComputerLastUser" { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount;$initialBpi=16000.0;$initialMpi=5000.0;$impact="Faible";$adQueries=$ItemCount }
        "WmiNamespaces" { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount;$initialBpi=24000.0;$initialMpi=6000.0;$impact="Aucun appel AD direct" }
        "WmiClasses" { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount;$initialBpi=80000.0;$initialMpi=8000.0;$impact="Aucun appel AD direct" }
        "WmiQuery" { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount;$initialBpi=160000.0;$initialMpi=9000.0;$impact="Aucun appel AD direct" }
        "ComputerGpUpdate" { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount;$initialBpi=8000.0;$initialMpi=10000.0;$impact="Aucun appel AD direct" }
        "ComputerRestart" { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount;$initialBpi=5000.0;$initialMpi=6000.0;$impact="Aucun appel AD direct" }
        "RimotteRun" { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount;$initialBpi=6000.0;$initialMpi=3500.0;$impact="Aucun appel AD direct" }
        "ComputerServiceControl" { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount;$initialBpi=4000.0;$initialMpi=8000.0;$impact="Aucun appel AD direct" }
        default { if($ItemCount-le0){$ItemCount=1};$remote=$ItemCount }
    }
    $bpi=$initialBpi;if($samples-gt0-and[double]$model.bytes_per_item-gt0){$bpi=[double]$model.bytes_per_item}
    $mpi=$initialMpi;if($samples-gt0-and[double]$model.ms_per_item-gt0){$mpi=[double]$model.ms_per_item}
    $bytes=[long]([Math]::Max(0,$ItemCount*$bpi));$durationMs=[long]([Math]::Max(0,$ItemCount*$mpi))
    if($BudgetMs-gt0){$durationMs=[Math]::Min($durationMs,[long]$BudgetMs)}
    if($remote-gt0){$ratio=0.25;if($samples-gt0-and$null-ne$model.fallback_ratio){$ratio=[Math]::Max(0,[Math]::Min(1,[double]$model.fallback_ratio))};$fallback=[Math]::Ceiling($remote*$ratio)}
    $minMs=0;$maxMs=0;$successPct=0
    try{$minMs=[double]$model.min_ms_per_item}catch{Write-DomeniaSwallowed 'Core' 'Get-DomeniaOperationImpactEstimate' $_};try{$maxMs=[double]$model.max_ms_per_item}catch{Write-DomeniaSwallowed 'Core' 'Get-DomeniaOperationImpactEstimate' $_};try{$successPct=[Math]::Round(100*[double]$model.success_ratio,0)}catch{Write-DomeniaSwallowed 'Core' 'Get-DomeniaOperationImpactEstimate' $_}
    $seconds=[Math]::Max(0.001,$durationMs/1000.0)
    $avgBps=[double]$bytes/$seconds
    $avgMbit=[double]($avgBps*8/1000000.0)
    $adQps=$(if($adQueries-gt0){[double]$adQueries/$seconds}else{0.0})
    $schedulerRpc=[int]$fallback*4
    $concurrency=1
    if($Operation -notin @("IndexBuild","LogonHarvest","ParkSweep","UserComputerProbe") -and $ItemCount -gt 1){$concurrency=[Math]::Max(1,[Math]::Min([int](Get-CfgValue "Async" "MaxThreads" 6),$ItemCount))}
    $peakMbit=[double]$avgMbit*[double]$concurrency
    $confidence=$(if($samples-ge10){"Haute"}elseif($samples-ge3){"Moyenne"}elseif($samples-gt0){"Faible"}else{"Initiale"})
    return [pscustomobject]@{Operation=$Operation;ItemCount=$ItemCount;DurationMs=$durationMs;Bytes=$bytes;AdQueries=$adQueries;RemoteAttempts=$remote;FallbackTasks=[int]$fallback;SchedulerRpc=$schedulerRpc;Concurrency=$concurrency;Impact=$impact;Samples=$samples;AverageMsPerItem=[double]$mpi;MinMsPerItem=$minMs;MaxMsPerItem=$maxMs;SuccessPct=$successPct;AverageBytesPerSecond=$avgBps;AverageMbitPerSecond=$avgMbit;PeakMbitPerSecond=$peakMbit;AdQueriesPerSecond=$adQps;Confidence=$confidence}
}



function Request-DomeniaOperationImpact {
    # UX-07: before a long operation, a panel of the page with one sentence, then Lancer and Annuler; the technical
    # figures stay in a folded part shown in the Expert profile only. No window. Returns at once: the operation
    # starts from -OnConfirm, once, when the operator confirms.
    param($Estimate,[string]$Title='Opération longue',[Parameter(Mandatory=$true)][scriptblock]$OnConfirm,[scriptblock]$OnCancel=$null,[AllowEmptyString()][string]$Target='')
    if ($null -eq $OnCancel) { $OnCancel = { Set-Status 'Opération annulée : rien nʼa été lancé.' 'INFO' } }
    $text = Format-DomeniaOperationImpact -Estimate $Estimate
    return (Request-DomeniaInlineConfirmation -Title $Title -Message ([string]$text.Sentence) -Target $Target -ConfirmText 'Lancer' -CancelText 'Annuler' -OnConfirm $OnConfirm -OnCancel $OnCancel -Details ([string]$text.Details) -DetailsTitle 'Détails de lʼestimation' -DetailsExpertOnly)
}

function Get-LinkCsvPath {
    Initialize-DomeniaDataStore | Out-Null
    $dir=Join-Path ([string]$script:DataDir) "Exports"
    if(-not(Test-Path -LiteralPath $dir -PathType Container)){[void](New-Item -ItemType Directory -Path $dir -Force)}
    return (Join-Path $dir "Domenia-user-machine-links.csv")
}


function Export-DomeniaLinksCsv {
    try {
        $grid=Get-DomeniaRelationsActiveGrid
        if($null -eq $grid){Show-InfoBox 'Ouvrez Utilisateur sélectionné ou Toutes les associations pour exporter les liens visibles.';return}
        $rows=@($grid.Items)
        if(-not $rows.Count){Set-Status 'Aucune association visible à exporter.' 'INFO';return}
        # CO-04: exchange file re-read by Import-LinksCsv: its field names stay the import names (UserLogin,
        # Computer...), the separator and the encoding follow the common export; confirmation in the page.
        $result=Export-DomeniaCsv -Rows @(ConvertTo-DomeniaCanonicalLinks -Links $rows) -Directory ([IO.Path]::GetDirectoryName((Get-LinkCsvPath))) -Subject 'associations'
        Show-DomeniaExportResult -Result $result
    } catch { Show-ErrorBox "Export des associations impossible : $($_.Exception.Message)" }
}

function ConvertTo-DomeniaCanonicalLinks {
    param($Links)
    # CD-06: the relation model applies whenever the Relations module is loaded (always in the application).
    $relationModel = ($null -ne (Get-Command -Name 'Get-DomeniaRelationKind' -CommandType Function -ErrorAction SilentlyContinue))
    if ($relationModel) {
        # D042/D049: deduplicate by relation (user, workstation, nature) instead of keeping the most recent row per
        # workstation, which let an observed console evict a declared assignment. While the local store keeps one row
        # per workstation (computer_key), its row is the primary relation (declared first, otherwise the most recent);
        # with a relation-keyed store ($script:DomeniaLinkStoreMultiRelation) every relation is kept, primary first.
        # Each row carries Kind and StorageKey (Get-DomeniaRelationStorageKey) for the storage queue.
        $multi = [bool]$script:DomeniaLinkStoreMultiRelation
        $groups = [ordered]@{}
        # CO-29: most recent first by instant, whatever the stored form (UTC ISO or older local text). Review L04: the
        # instants are read once for all rows (Get-DomeniaRelationWhenTicks, memoized) and sorted natively; equal
        # instants keep their order (the row position is part of the key). [Array]::Sort(keys,items) is not used: under
        # Windows PowerShell 5.1 it receives a converted copy of the items and leaves them unsorted.
        $items = New-Object 'System.Collections.Generic.List[object]'
        foreach ($link in @($Links)) { if ($null -ne $link) { $items.Add($link) } }
        $texts = New-Object 'string[]' $items.Count
        for ($i = 0; $i -lt $items.Count; $i++) { $texts[$i] = [string]$items[$i].When }
        $ticks = Get-DomeniaRelationWhenTicks -Values $texts
        $ordered = New-Object 'System.Collections.Generic.SortedDictionary[decimal,object]'
        for ($i = 0; $i -lt $items.Count; $i++) { $ordered.Add((([decimal]$ticks[$i]) * -1000000) + $i,$items[$i]) }
        foreach ($link in @($ordered.Values)) {
            $user = Normalize-LinkUser ([string]$link.UserLogin)
            $computer = Normalize-LinkComputer ([string]$link.Computer)
            if ([string]::IsNullOrWhiteSpace($user) -or [string]::IsNullOrWhiteSpace($computer)) { continue }
            $verified = $false
            try { if ($null -ne $link.PSObject.Properties['VerifiedInAD']) { $verified = [bool]$link.VerifiedInAD } } catch { Write-DomeniaSwallowed 'Core' 'ConvertTo-DomeniaCanonicalLinks' $_ }
            $confidence = 0
            try { if ($null -ne $link.PSObject.Properties['Confidence']) { $confidence = [int]$link.Confidence } } catch { Write-DomeniaSwallowed 'Core' 'ConvertTo-DomeniaCanonicalLinks' $_ }
            $when = [string]$link.When
            if ([string]::IsNullOrWhiteSpace($when)) { $when = [datetime]::UtcNow.ToString('o') }
            $row = [pscustomobject]@{
                UserLogin=$user; Computer=$computer; Source=[string]$link.Source; Confidence=$confidence; VerifiedInAD=$verified; When=$when; Details=[string]$link.Details
                UserGuid=[string]$link.UserGuid; ComputerGuid=[string]$link.ComputerGuid; UserDn=[string]$link.UserDn; ComputerDn=[string]$link.ComputerDn
                Kind=(Get-DomeniaRelationKind ([string]$link.Source)); StorageKey=''
            }
            $computerKey = $computer.ToUpperInvariant()
            if (-not $groups.Contains($computerKey)) { $groups[$computerKey] = [System.Collections.ArrayList]::new() }
            $duplicate = $false
            foreach ($kept in $groups[$computerKey]) { if (Test-DomeniaSameRelation $kept $row) { $duplicate = $true; break } }
            if (-not $duplicate) { [void]$groups[$computerKey].Add($row) }
        }
        foreach ($computerKey in @($groups.Keys)) {
            $items = @($groups[$computerKey])
            $primary = Select-DomeniaPrimaryRelation $items
            $primary.StorageKey = Get-DomeniaRelationStorageKey $primary $true
            Write-Output $primary
            if (-not $multi) { continue }
            foreach ($item in $items) {
                if ([object]::ReferenceEquals($item,$primary)) { continue }
                $item.StorageKey = Get-DomeniaRelationStorageKey $item $false
                Write-Output $item
            }
        }
        return
    }
    $valid = [System.Collections.ArrayList]::new()
    $seen = @{}
    foreach ($link in @($Links | Sort-Object When -Descending)) {
        if ($null -eq $link) { continue }
        $user = Normalize-LinkUser ([string]$link.UserLogin)
        $computer = Normalize-LinkComputer ([string]$link.Computer)
        if ([string]::IsNullOrWhiteSpace($user) -or [string]::IsNullOrWhiteSpace($computer)) { continue }
        $computerKey = $computer.ToUpperInvariant()
        if ($seen.ContainsKey($computerKey)) { continue }
        $seen[$computerKey] = $true
        $confidence = 0
        $verified = $false
        try { if ($null -ne $link.PSObject.Properties['Confidence']) { $confidence = [int]$link.Confidence } } catch { Write-DomeniaSwallowed 'Core' 'ConvertTo-DomeniaCanonicalLinks' $_ }
        try { if ($null -ne $link.PSObject.Properties['VerifiedInAD']) { $verified = [bool]$link.VerifiedInAD } } catch { Write-DomeniaSwallowed 'Core' 'ConvertTo-DomeniaCanonicalLinks' $_ }
        $when = [string]$link.When
        if ([string]::IsNullOrWhiteSpace($when)) { $when = Get-Date -Format 'yyyy-MM-dd HH:mm:ss' }
        $userGuid=""; $computerGuid=""; $userDn=""; $computerDn=""
        try { $userGuid=[string]$link.UserGuid } catch { Write-DomeniaSwallowed 'Core' 'ConvertTo-DomeniaCanonicalLinks' $_ }
        try { $computerGuid=[string]$link.ComputerGuid } catch { Write-DomeniaSwallowed 'Core' 'ConvertTo-DomeniaCanonicalLinks' $_ }
        try { $userDn=[string]$link.UserDn } catch { Write-DomeniaSwallowed 'Core' 'ConvertTo-DomeniaCanonicalLinks' $_ }
        try { $computerDn=[string]$link.ComputerDn } catch { Write-DomeniaSwallowed 'Core' 'ConvertTo-DomeniaCanonicalLinks' $_ }
        [void]$valid.Add([pscustomobject]@{
            UserLogin=$user
            Computer=$computer
            Source=[string]$link.Source
            Confidence=$confidence
            VerifiedInAD=$verified
            When=$when
            Details=[string]$link.Details
            UserGuid=$userGuid
            ComputerGuid=$computerGuid
            UserDn=$userDn
            ComputerDn=$computerDn
        })
    }
    if ($valid.Count -eq 0) { return }
    foreach ($item in $valid.ToArray()) { Write-Output $item }
}

function Save-UserMachineLinks {
    return Queue-DomeniaLinkChanges
}

function ConvertTo-DomeniaCanonicalWorkerCode {
    param([AllowEmptyString()][string]$Code)
    return (($Code -replace "`r`n","`n") -replace "`r","`n")
}

function Get-DomeniaWorkerCodeHash {
    param([AllowEmptyString()][string]$Code)
    $canonical = ConvertTo-DomeniaCanonicalWorkerCode -Code $Code
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [System.Text.UTF8Encoding]::new($false).GetBytes($canonical)
        return (($sha.ComputeHash($bytes) | ForEach-Object { $_.ToString("x2") }) -join "").ToUpperInvariant()
    }
    finally { $sha.Dispose() }
}

function Get-DomeniaWorkerOperationHashes {
    # Registre ferme : seules ces operations internes, avec leur corps exact, peuvent entrer dans un runspace.
    return [ordered]@{
