function Assert-DomeniaWorkerRegistry {
    [CmdletBinding()]
    param([AllowNull()][System.Collections.IDictionary]$Registry = (Get-DomeniaWorkerOperationHashes))
    # Pin the entire reviewed map, not a separately maintained operation counter.
    # This digest is updated only by the DEV release tool after contract review.
    $expectedFingerprint = "CD884422D4FCB3F02E75DA049E9E4F1226E8ABF094BF042B69915B4ACD5E6A05"
    if ($null -eq $Registry -or $Registry.Count -eq 0) {
        throw 'Registre worker absent ou vide.'
    }
    [string[]]$names = @($Registry.Keys)
    [Array]::Sort($names,[StringComparer]::Ordinal)
    $records = [Collections.Generic.List[string]]::new()
    foreach ($name in $names) {
        if ($name -cnotmatch '^[A-Za-z][A-Za-z0-9]{2,63}$') { throw 'Identifiant du registre worker invalide.' }
        $hash = [string]$Registry[$name]
        if ($hash -cnotmatch '^[A-F0-9]{64}$') { throw "Empreinte worker invalide pour $name." }
        $records.Add($name + '=' + $hash)
    }
    $canonical = [string]::Join("`n",$records.ToArray())
    $actual = Get-DomeniaWorkerCodeHash -Code $canonical
    if (-not [string]::Equals($actual,$expectedFingerprint,[StringComparison]::Ordinal)) {
        throw ("Registre worker non conforme ({0} operation(s), empreinte={1}). Composant manquant, ajoute ou modifie ; reinstallez un paquet coherent." -f $Registry.Count,$actual)
    }
    return [int]$Registry.Count
}

function Assert-DomeniaWorkerOperationCode {
    param(
        [Parameter(Mandatory=$true)][ValidatePattern('^[A-Za-z][A-Za-z0-9]{2,63}$')][string]$OperationId,
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$Code
    )
    $registry = Get-DomeniaWorkerOperationHashes
    if (-not $registry.Contains($OperationId)) { throw "Operation worker non autorisee : $OperationId" }
    $expected = [string]$registry[$OperationId]
    $actual = Get-DomeniaWorkerCodeHash -Code $Code
    if (-not [string]::Equals($expected,$actual,[System.StringComparison]::OrdinalIgnoreCase)) {
        throw "Integrite worker refusee pour $OperationId (attendu=$expected, obtenu=$actual)."
    }
    return $actual
}

function Get-DomeniaWorkerEngineSelfTestCode {
    return @'
[pscustomobject]@{ Success=$true; Echo=[string]$Payload.Echo; WorkerThreadId=[System.Threading.Thread]::CurrentThread.ManagedThreadId; Apartment=[System.Threading.Thread]::CurrentThread.GetApartmentState().ToString() }
'@
}

function New-DomeniaWorkerRunspace {
    param(
        [Parameter(Mandatory=$true)][string]$OperationId,
        [Parameter(Mandatory=$true)][string]$Code,
        [switch]$IsWrite
    )
    # PF-05: the whole cost paid on the Dispatcher to obtain a worker is measured (series Dispatcher|RunspaceOpen:<op>).
    $openWatch = [System.Diagnostics.Stopwatch]::StartNew()
    $verifiedHash = Assert-DomeniaWorkerOperationCode -OperationId $OperationId -Code $Code
    # PF-05: the reads opened most often reuse a pool of prepared runspaces (pinned body and worker helpers loaded once)
    # instead of opening a runspace on the Dispatcher at each task: flag Pool of the operation table
    # (Get-DomeniaOperationTable, Domenia-Engine.Model.ps1). A write never uses a pool.
    $operationRow = Get-DomeniaOperationRow $OperationId
    $pooled = (($null -ne $operationRow) -and ([bool]$operationRow.Pooled) -and (-not $IsWrite))
    if ($pooled) {
        if ($null -eq $script:LiveWorkerPools) { $script:LiveWorkerPools=@{} }
        if ($script:LiveWorkerPools.ContainsKey($OperationId)) {
            $existing=$script:LiveWorkerPools[$OperationId]
            if ($existing.CodeHash -cne $verifiedHash) { throw 'Empreinte de pool incohérente.' }
            $openWatch.Stop()
            try { Add-DomeniaRuntimeMetric -Provenance 'Dispatcher' -OperationId ('RunspaceOpen:' + $OperationId) -DurationMs ([double]$openWatch.Elapsed.TotalMilliseconds) } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaWorkerRunspace' $_ }
            return $existing
        }
    }
    $businessCode = [string]$Code
    if ($IsWrite) {
        # Persist intent before dispatch. Fail closed when the receipt cannot be stored.
        $body=$businessCode.Replace('$DomeniaWriteDispatched=$true',"Set-WReceiptStage 'Sent';`$DomeniaWriteDispatched=`$true")
        $businessCode=@'
$DomeniaWriteDispatched=$false;$receiptLock=$null
try {
    $root=Get-WReceiptRoot $Context
    $receiptLock=[IO.File]::Open((Join-Path $root 'writer.lock'),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
    $null=Invoke-WReceiptCompaction $root
    $pendingFiles=@([IO.Directory]::EnumerateFiles($root,'*.json')|Select-Object -First 513)
    if($pendingFiles.Count -gt 512){throw 'Plus de 512 recus non resolus : verification requise avant une nouvelle operation.'}
    foreach($pendingFile in $pendingFiles){
        if((Get-Item -LiteralPath $pendingFile -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Recu redirige refuse.'}
        if(([IO.FileInfo]::new($pendingFile)).Length -gt 65536){throw 'Recu invalide a verifier.'}
        $pending=[IO.File]::ReadAllText($pendingFile)|ConvertFrom-Json
        if($pending.Format -ne 1){throw 'Recu non reconnu.'}
        if ((($pending.Domain -ieq $Context.BaseDn)) -and (($pending.Stage -notin @('Verified','NotSent','Reviewed','Delivered')))) {throw 'Une operation precedente reste a verifier. Aucun envoi.'}
        $pendingFingerprint=''
        if ($null -ne $pending.PSObject.Properties['PlanFingerprint']) { $pendingFingerprint=[string]$pending.PlanFingerprint }
        $payloadFingerprint=''
        if ((($null -ne $Payload)) -and ((($null -ne $Payload.PSObject.Properties['PlanFingerprint'])))) { $payloadFingerprint=[string]$Payload.PlanFingerprint }
        if ((($pending.Domain -ieq $Context.BaseDn)) -and ($payloadFingerprint) -and (((($pendingFingerprint -ceq $payloadFingerprint)) -or ((([string]$pending.Id) -ceq $payloadFingerprint)))) -and (($pending.Stage -ne 'NotSent'))) {throw 'Demande identique deja envoyee ou a verifier.'}
    }
    New-WReceipt $Context $Payload
    $businessResult=. {
'@ + "`r`n"+$body+"`r`n"+@'
    }
    $proof=@($businessResult|Where-Object{$null -ne $_.PSObject.Properties['Verified']}|Select-Object -Last 1)
    $delivered=@($businessResult|Where-Object{$null -ne $_.PSObject.Properties['Delivered']}|Select-Object -Last 1)
    if ((($proof.Count -eq 1)) -and (($proof[0].Verified)) -and ((-not $proof[0].Partial))) {Set-WReceiptStage 'Verified'}
    elseif ((($delivered.Count -eq 1)) -and ([bool]$delivered[0].Delivered)) {Set-WReceiptStage 'Delivered'}
    else {Set-WReceiptStage 'Unknown'}
    $businessResult
} catch {
    if($null -ne $script:ReceiptRecord){
        try{if($DomeniaWriteDispatched){Set-WReceiptStage 'Unknown'}else{Set-WReceiptStage 'NotSent'}}catch{}
    }
    if($DomeniaWriteDispatched){throw ('ETAT INCONNU apres envoi. Recu conserve ; aucun rejeu automatique. '+$_.Exception.Message)}
    throw
} finally {if($null -ne $receiptLock){$receiptLock.Dispose()};$script:ReceiptRecord=$null}
'@
    }
    $definition = @'
param($Context,$Payload)
$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"
$VerbosePreference = "SilentlyContinue"
$DebugPreference = "SilentlyContinue"
$InformationPreference = "SilentlyContinue"
'@
    # PF-10: the error contract copied into every worker is read once per session, not looked up at each task.
    if ([string]::IsNullOrEmpty([string]$script:DomeniaWorkerErrorContract)) {
        $parts=foreach($helper in @('Get-DomeniaStructuredError','Get-DomeniaCredentialAccountKey','Set-WCredentialAttemptIdentity','Get-WCredentialGuardKeys','Assert-WCredentialAllowed','Enter-WCredentialAttempt','Exit-WCredentialAttempt','Register-WCredentialFailure')){
            "function $helper {`r`n"+(Get-Command $helper -CommandType Function).Definition+"`r`n}"
        }
        $script:DomeniaWorkerErrorContract=$parts -join "`r`n"
    }
    $errorContract=[string]$script:DomeniaWorkerErrorContract
    $businessCode="try {`r`nAssert-WCredentialAllowed -Context `$Context`r`n"+$businessCode+"`r`n}"+@'
 catch {
    [void](Register-WCredentialFailure -Context $Context -ErrorValue $_)
    $diagnostic=Get-DomeniaStructuredError $_ -Phase ([string]$Context.OperationId) -Provider 'Windows' -Target ([string]$Context.Server)
    $marker='[DOMENIA:'+ $diagnostic.Kind +';'+$diagnostic.NativeCode+';'+$diagnostic.Code+'] '
    throw [InvalidOperationException]::new($marker+$_.Exception.Message,$_.Exception)
}
'@
    $definition += "`r`n" + $errorContract + "`r`n" + [string]$script:WorkerCommon + "`r`n" + (Get-DomeniaDirectoryStoreWorkerPrelude) + "`r`n" + $businessCode
    $functionName = "Invoke-DomeniaPinnedOperation"
    $iss = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault2()
    $entry = New-Object System.Management.Automation.Runspaces.SessionStateFunctionEntry -ArgumentList @($functionName,$definition)
    [void]$iss.Commands.Add($entry)
    if ($pooled) {
        # PF-05: up to MaxThreads runspaces per operation (a cancelled native call that keeps its runspace never makes the
        # next read wait in the pool); idle extra runspaces are closed after two minutes, one stays prepared.
        $poolMax=[Math]::Max(3,[Math]::Min(32,[int](Get-CfgValue 'Async' 'MaxThreads' 6)))
        $pool=[Management.Automation.Runspaces.RunspaceFactory]::CreateRunspacePool(1,$poolMax,$iss,$Host)
        try {
            $pool.ApartmentState=[Threading.ApartmentState]::MTA
            $pool.ThreadOptions=[Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
            $pool.CleanupInterval=[TimeSpan]::FromMinutes(2)
            $pool.Open()
            $record=[pscustomobject]@{Runspace=$null;Pool=$pool;CommandName=$functionName;OperationId=$OperationId;CodeHash=$verifiedHash}
            $script:LiveWorkerPools[$OperationId]=$record
            # D019: the pool has an owner and is closed by the registry at shutdown.
            try { [void](Register-DomeniaWorkerPool -OperationId $OperationId -Pool $pool) } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaWorkerRunspace' $_ }
            $openWatch.Stop()
            try { Add-DomeniaRuntimeMetric -Provenance 'Dispatcher' -OperationId ('RunspaceOpen:' + $OperationId) -DurationMs ([double]$openWatch.Elapsed.TotalMilliseconds) } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaWorkerRunspace' $_ }
            return $record
        } catch { $pool.Dispose(); throw }
    }
    $runspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace($Host,$iss)
    try {
        $runspace.ApartmentState = [System.Threading.ApartmentState]::MTA
        $runspace.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
        $runspace.Open()
        $openWatch.Stop()
        # D014: the synchronous Open() on the Dispatcher is measured (series 'Dispatcher' of C7). PF-10: no lookup.
        try { Add-DomeniaRuntimeMetric -Provenance 'Dispatcher' -OperationId ('RunspaceOpen:' + $OperationId) -DurationMs ([double]$openWatch.Elapsed.TotalMilliseconds) } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaWorkerRunspace' $_ }
        return [pscustomobject]@{ Runspace=$runspace; CommandName=$functionName; OperationId=$OperationId; CodeHash=$verifiedHash }
    }
    catch {
        try { $runspace.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaWorkerRunspace' $_ }
        throw
    }
}

function Register-DomeniaAsyncEngineFault {
    # FI-02: the poll timer no longer writes a line and a status every 250 ms while Complete-UiTasks fails.
    # The same engine error is written once a minute; after three consecutive failures the timer stops and one
    # clear message is shown (no window loop). Returns $true when the engine has been stopped.
    param($ErrorRecord)
    $script:AsyncEngineTickFailures = [int]$script:AsyncEngineTickFailures + 1
    $exception = if ($ErrorRecord -is [System.Management.Automation.ErrorRecord]) { $ErrorRecord.Exception } else { $ErrorRecord }
    $occurrence = Register-DomeniaErrorOccurrence -Signature (Get-DomeniaErrorSignature -ErrorRecordOrException $ErrorRecord -Source 'Moteur asynchrone')
    $code = [string]$occurrence.Code
    if ([bool]$occurrence.Write) {
        $repeat = if ([int]$occurrence.Count -gt 1) { ' (même erreur ×' + [int]$occurrence.Count + ')' } else { '' }
        try { Write-AppLog ("[$code] Moteur asynchrone$repeat : " + [string]$exception) 'ERROR' -Area 'Technique' } catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaAsyncEngineFault' $_ }
        # The readable journal says it as often as Domenia.log, with the same code.
        if ([int]$script:AsyncEngineTickFailures -lt 3) { try { Set-Status ("Erreur interne du moteur des tâches ($code). Nouvel essai automatique.") 'ERROR' -NoFileLog } catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaAsyncEngineFault' $_ } }
    }
    if ([int]$script:AsyncEngineTickFailures -lt 3) { return $false }
    try { if ($null -ne $script:AsyncTimer) { $script:AsyncTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaAsyncEngineFault' $_ }
    if ([bool]$script:AsyncEngineFaultStopped) { return $true }
    $script:AsyncEngineFaultStopped = $true
    try { Write-AppLog ("[$code] Moteur asynchrone arrete apres 3 echecs consecutifs ; aucun nouvel essai automatique.") 'ERROR' -Area 'Technique' } catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaAsyncEngineFault' $_ }
    try { Set-Status ("Moteur des tâches arrêté après 3 erreurs consécutives ($code). Fermez puis relancez Domenia.") 'ERROR' -NoFileLog } catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaAsyncEngineFault' $_ }
    # The closing guard lets the operator leave after a confirmation when a write was in progress (Initialize-Window).
    try { Show-ErrorBox ("Le moteur des tâches sʼest arrêté après 3 erreurs consécutives : les lectures en cours nʼaboutiront plus.`r`n`r`nFermez puis relancez Domenia. Si une écriture AD était en cours, la fermeture demande une confirmation : son reçu local est conservé et sera à vérifier dans les reçus au prochain démarrage.`r`n`r`nCode incident : $code. Le détail technique est enregistré dans le journal Domenia.") } catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaAsyncEngineFault' $_ }
    return $true
}

function Initialize-AsyncEngine {
    if ($script:AsyncEngineReady) { return }
    # Une nouvelle initialisation apres authentification reussie rearme le canal AD.
    $script:DirectoryCredentialFaulted = $false
    $script:DirectoryCredentialFaultMessage = ""
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    Write-StartupTrace -Stage "Moteur multithread" -Status "START"
    try {
        $registry = Get-DomeniaWorkerOperationHashes
        $registeredOperations = Assert-DomeniaWorkerRegistry -Registry $registry
        [void](Assert-DomeniaWorkerOperationCode -OperationId "EngineSelfTest" -Code (Get-DomeniaWorkerEngineSelfTestCode))
        $script:AsyncEngineReady = $true
        $script:AsyncEngineClosing = $false
        $script:AsyncEngineTickFailures = 0
        $script:AsyncEngineFaultStopped = $false

        # PF-06: the poll is a subscriber of the engine heartbeat. It runs while a task, a queued entry or a detached
        # read exists (Complete-UiTasks stops it at rest, Start-UiTask resumes it) and also while the window is minimized.
        $timer = New-DomeniaTimer -Owner 'Timer:Async' -IntervalMs ([Math]::Max(100,[int](Get-CfgValue "Async" "PollIntervalMs" 250))) -RunWhenHidden -Tick {
            # FI-02: a failing poll is counted; three consecutive failures stop the timer with one message.
            try { Complete-UiTasks; $script:AsyncEngineTickFailures = 0 }
            catch { try { [void](Register-DomeniaAsyncEngineFault -ErrorRecord $_) } catch { Write-DomeniaSwallowed 'Core' 'Initialize-AsyncEngine' $_ } }
        }
        $script:AsyncTimer = $timer
        $script:AsyncTimer.Start()
        $sw.Stop()
        Write-StartupTrace -Stage "Moteur multithread" -Status "OK" -DurationMs $sw.ElapsedMilliseconds -Detail ("Moteur ferme pret ; {0} operations hash-pinnees, registre verifie. Pools de lecture et runspaces dedies selon operation." -f $registeredOperations)
    }
    catch {
        $sw.Stop()
        Write-StartupTrace -Stage "Moteur multithread" -Status "ERROR" -Detail $_.Exception.ToString() -DurationMs $sw.ElapsedMilliseconds
        $script:AsyncEngineReady = $false
        throw
    }
}

function Get-AllWriteControlNames {
    $all = New-Object System.Collections.Generic.List[string]
    foreach ($v in (Get-WriteControlMap).Values) {
        foreach ($n in @($v)) { if (-not $all.Contains([string]$n)) { [void]$all.Add([string]$n) } }
    }
    return $all.ToArray()
}

function Invoke-DomeniaUiHandler {
    param([string]$HandlerName,$Argument,$CallbackState)
    if ([string]::IsNullOrWhiteSpace([string]$HandlerName)) { return }
    $handler = Get-Command -Name $HandlerName -CommandType Function -ErrorAction Stop | Select-Object -First 1
    if ($null -eq $handler) { throw "Callback UI introuvable : $HandlerName" }
    & $handler $Argument $CallbackState
}

function Invoke-DomeniaJobSuccessUi {
    param($Job,$Output)
    $previousAccessJob=$script:AccessCurrentJob
    $script:AccessCurrentJob=$Job
    try {
    if (-not [string]::IsNullOrWhiteSpace([string]$Job.SuccessHandler)) {
        Invoke-DomeniaUiHandler -HandlerName ([string]$Job.SuccessHandler) -Argument $Output -CallbackState $Job.CallbackState
    }
    elseif ($null -ne $Job.OnSuccess) { & $Job.OnSuccess $Output $Job.CallbackState }
        Inspect-DomeniaAccessResult -Job $Job -Output $Output
    } finally { $script:AccessCurrentJob=$previousAccessJob }
}

function Invoke-DomeniaJobErrorUi {
    param($Job,[string]$Message)
    $previousAccessJob=$script:AccessCurrentJob
    $script:AccessCurrentJob=$Job
    try {
[void](Request-DomeniaAccessRecovery -Operation ([string]$Job.Name) -OperationId ([string]$Job.OperationId) -ErrorValue $Message -Interactive:([int]$Job.CallbackState.RetryAttempt -eq 0))
try {
        Add-DomeniaUiLog -Area "Erreur tache" -Level "ERROR" -Text (
            "Nom={0}  operation={1}  message={2}" -f
            [string]$Job.Name,[string]$Job.OperationId,$Message
        )
    }
    catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaJobErrorUi' $_ }

    if (-not [string]::IsNullOrWhiteSpace([string]$Job.ErrorHandler)) {
        Invoke-DomeniaUiHandler -HandlerName ([string]$Job.ErrorHandler) -Argument $Message -CallbackState $Job.CallbackState
    }
    elseif ($null -ne $Job.OnError) { & $Job.OnError $Message $Job.CallbackState }
    else { Set-Status "$($Job.Name) : $Message" "ERROR" }
    } finally { $script:AccessCurrentJob=$previousAccessJob }
}

function Start-UiTask {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)][ValidatePattern('^[A-Za-z][A-Za-z0-9]{2,63}$')][string]$OperationId,
        [Parameter(Mandatory=$true)][string]$Code,
        $Payload = $null,
        [scriptblock]$OnSuccess = $null,
        [scriptblock]$OnError = $null,
        [string]$SuccessHandler = "",
        [string]$ErrorHandler = "",
        [string[]]$DisableControls = @(),
        [string]$ReplaceKey = "",
        [int]$TimeoutSeconds = 0,
        [int]$HardTimeoutSeconds = 0,
        [string]$StatusText = "",
        [switch]$IsWrite,
        [switch]$NonCancellable,
        [string]$CorrelationId = "",
        # W13 (point 123): identifier shared by every event of one request; empty = Resolve-DomeniaTraceId.
        [string]$TraceId = "",
        $CallbackState = $null,
        # D015: the caller may state the class of its request (automatic work = Background).
        [ValidateSet('','Explicit','Selection','Background')][string]$TaskClass = "",
        [string]$ReaderIdentity = "",
        [long]$Generation = 0
    )
try {
        $payloadCount = 0
        if ($null -ne $Payload) {
            try { $payloadCount = @($Payload).Count } catch { $payloadCount = 1 }
        }
        # UX-04: engine detail at the Trace level (Domenia.log only), never in the session journal.
        Write-DomeniaTrace -Area 'Tache' -Text (
            "Préparation : nom={0}, opération={1}, charge={2}, délai={3} s, remplacement={4}" -f
            $Name,$OperationId,$payloadCount,$TimeoutSeconds,$ReplaceKey
        )
    }
    catch { Write-DomeniaSwallowed 'Core' 'Start-UiTask' $_ }

    if (-not [bool](Get-CfgValue "Async" "Enabled" $true)) { throw "Moteur multithread desactive dans la configuration." }
    if ($script:AsyncEngineClosing) { throw "Le moteur multithread est en cours de fermeture." }
    # Points 32 and 34: while a base maintenance holds its lock (copy, switch to finish, unreadable base), no other writer
    # of the base is admitted; reads, the receipts journal and chosen documents stay available, and collected results wait
    # in the single queue. This refusal used to sit inside the trace block above, whose empty catch swallowed it.
    if(($null -ne $script:StorageMaintenance) -and [bool]$script:StorageMaintenance.Locked -and (Test-DomeniaStorageLockedWriter -OperationId $OperationId)){throw 'Maintenance de la base en cours : terminez ou reprenez la bascule avant une nouvelle écriture locale.'}
    if($OperationId -eq 'StoragePurge'){Assert-DomeniaStoragePurgeReady}
    if($OperationId -ne 'ReceiptStore' -and (@($script:AsyncJobs.Values|Where-Object{$_.OperationId -eq 'StoragePurge'}).Count -or @($script:DetachedReadJobs|Where-Object{$_.OperationId -eq 'StoragePurge'}).Count)){throw 'Une simulation ou purge locale est encore active. Attendez sa fin.'}
    # D094: durable receipt required before dispatch for known mutations only.
    # Unknown operations must not break Start-UiTask; they remain to be classified.
    $receiptRequirement = Get-DomeniaReceiptRequirement -OperationId $OperationId
    if (([bool]$receiptRequirement.Required) -and (($receiptRequirement.Effect -in @('DirectoryWrite','RemoteMutation'))) -and ((-not [bool]$IsWrite))) {
        throw 'Reçu durable requis : cette operation doit partir par le canal ecriture.'
    }
    Initialize-AsyncEngine
    # D011: engine state built lazily from the model modules, never at script level of the core.
    Initialize-DomeniaEngineState
    # C2: in demonstration no write is sent: no runspace, no receipt, no queue entry.
    if ([bool]$script:DemoMode -and $IsWrite) { throw 'DOMENIA_DEMO_WRITE : ecritures desactivees en demonstration. Aucune ecriture tentee.' }

    $scheduler = Test-DomeniaSchedulerEnabled
    $taskClassValue = ''; $providerValue = ''; $providerTarget = ''; $providerGroup = ''; $dedupKey = ''
    # CO-02: only a foreground task (Write, Explicit, Selection) becomes the target of Annuler and of the progress label.
    $foregroundValue = $true
    try {
        $trackedClass = Get-DomeniaTaskClass -OperationId $OperationId -IsWrite ([bool]$IsWrite) -ReplaceKey $ReplaceKey -Hint $TaskClass
        $foregroundValue = [bool](Test-DomeniaForegroundTaskClass -Class $trackedClass)
    } catch { $foregroundValue = $true }
    if ($scheduler) {
        $taskClassValue = Get-DomeniaTaskClass -OperationId $OperationId -IsWrite ([bool]$IsWrite) -ReplaceKey $ReplaceKey -Hint $TaskClass
        $providerValue = Get-DomeniaOperationProvider $OperationId
        $providerTarget = [string](Get-DomeniaMember $Payload 'Computer' '')
        # Presence checks name their machine Target; the shared park file is its own resource. Without this,
        # their outcomes land on the provider-wide entry that every target of the provider checks.
        if ([string]::IsNullOrWhiteSpace($providerTarget)) { $providerTarget = [string](Get-DomeniaMember $Payload 'Target' '') }
        if ([string]::IsNullOrWhiteSpace($providerTarget) -and $OperationId -eq 'ParkSharedSync') { $providerTarget = 'park:' + [string](Get-DomeniaMember $Payload 'Path' '') }
        # D018: a LAPS or BitLocker refusal is kept on its own resource, never on the whole directory.
        if ([string]::IsNullOrWhiteSpace($providerTarget)) {
            $secretResource = [string](Get-DomeniaOperationCredentialNeeds -OperationId $OperationId).Resource
            if ($secretResource -in @('Laps','BitLocker')) { $providerTarget = $secretResource }
        }
        # Point 15: the controller of the session or the presumed subnet of the workstation has its own budget.
        try { $providerGroup = [string](Get-DomeniaKnownTargetGroup -Provider $providerValue -Target $providerTarget) } catch { $providerGroup = '' }
        if (-not $IsWrite) {
            # D015 / point 12: a strictly identical read joins the one already queued or running: same operation and
            # request, same accounts (reader, process identity, account generation), same session and generation, same
            # requirements (delays, protection, class).
            $bindUser = ''
            if ($null -ne $script:Conn) { $bindUser = [string]$script:Conn.BindUser }
            $readerValue = Get-DomeniaTaskReaderIdentity -Reader $ReaderIdentity -BindUser $bindUser -ProcessIdentity ([string]$script:ProcessIdentity) -AccountGeneration ([long]$script:DomeniaAccountGeneration)
            $requirements = Get-DomeniaTaskRequirements -TimeoutSeconds $TimeoutSeconds -HardTimeoutSeconds $HardTimeoutSeconds -NonCancellable ([bool]$NonCancellable) -TaskClass $taskClassValue
            $dedupKey = Get-DomeniaTaskDedupKey -OperationId $OperationId -ReaderIdentity $readerValue -Epoch ([long]$script:SessionEpoch) -Generation $Generation -Payload $Payload -Requirements $requirements
            if (-not [string]::IsNullOrWhiteSpace($dedupKey)) {
                $sharedId = Add-DomeniaTaskSubscriber -DedupKey $dedupKey -ReplaceKey $ReplaceKey -SuccessHandler $SuccessHandler -ErrorHandler $ErrorHandler -OnSuccess $OnSuccess -OnError $OnError -CallbackState $CallbackState -DisableControls $DisableControls
                if (-not [string]::IsNullOrWhiteSpace($sharedId)) { Update-TaskUi -Force; return $sharedId }
            }
        }
    }

    if (-not [string]::IsNullOrWhiteSpace($ReplaceKey)) {
        foreach ($oldId in @($script:AsyncJobs.Keys)) {
            $old = $script:AsyncJobs[$oldId]
            if ($null -ne $old -and [string]$old.ReplaceKey -eq $ReplaceKey -and -not [bool]$old.IsWrite) {
                Request-UiTaskStop -Id $oldId -Silent -Force -Superseded -Reason 'Remplacement de tache'
            }
        }
    }

    Complete-DomeniaDetachedReadJobs
    $maxConcurrent = [Math]::Max(1,[Math]::Min(32,[int](Get-CfgValue "Async" "MaxThreads" 6)))
    $physicalCount = @($script:AsyncJobs.Keys).Count + @($script:DetachedReadJobs).Count
    $maxOutstanding = [Math]::Max($maxConcurrent,[Math]::Min(64,[int](Get-CfgValue 'Async' 'MaxOutstandingWorkers' 12)))
    $admission = 'Start'; $admissionReason = ''
    if (-not $scheduler) {
        # Features.Scheduler=false: historical limits, unchanged.
        if ($physicalCount -ge $maxOutstanding) {
            throw "Limite physique atteinte : $physicalCount workers encore actifs ou en annulation. Attends leur nettoyage ; aucun nouveau thread n'a ete cree."
        }
        $activeCount = @($script:AsyncJobs.Values | Where-Object { $null -ne $_ -and -not [bool]$_.CancelRequested }).Count
        if ($activeCount -ge $maxConcurrent) {
            throw "Le moteur asynchrone execute deja $activeCount tache(s), limite $maxConcurrent. Attends une fin de tache ou annule une lecture en cours."
        }
    }
    else {
        # D015: start, wait in the bounded priority queue, or refuse (a refusal still throws its reason).
        # FI-03: a write admitted on its reserved place while reads finish carries a reason shown to the operator.
        $admissionResult = Get-DomeniaUiTaskAdmission -Class $taskClassValue
        $admission = [string]$admissionResult.Decision
        $admissionReason = [string](Get-DomeniaMember $admissionResult 'Reason' '')
    }

    if ($TimeoutSeconds -le 0) { $TimeoutSeconds = [int](Get-CfgValue "Async" "DefaultTimeoutSeconds" 60) }
    if ($HardTimeoutSeconds -le 0) { $HardTimeoutSeconds = if ($IsWrite) { [int](Get-CfgValue "Async" "WriteHardTimeoutSeconds" 300) } else { $TimeoutSeconds } }
    if ([string]::IsNullOrWhiteSpace($CorrelationId)) { $CorrelationId = [guid]::NewGuid().ToString("N") }

    $id = Get-NewTaskId $Name
    $now = Get-Date
    $job = [pscustomobject]@{
        Id=$id; Name=$Name; OperationId=$OperationId; CodeHash=''; ReplaceKey=$ReplaceKey; PowerShell=$null; Runspace=$null; Handle=$null; StopHandle=$null; Started=$now
        TimeoutSeconds=$TimeoutSeconds; HardTimeoutSeconds=$HardTimeoutSeconds; OnSuccess=$OnSuccess; OnError=$OnError
        SuccessHandler=$SuccessHandler; ErrorHandler=$ErrorHandler; CallbackState=$CallbackState
        DisableControls=@($DisableControls); IsWrite=[bool]$IsWrite; NonCancellable=([bool]$NonCancellable -or [bool]$IsWrite)
        SessionEpoch=[long]$script:SessionEpoch; TimeoutNotified=$false; TimeoutErrorDelivered=$false; CancelRequested=$false; CancelRequestedAt=$null; Superseded=$false; CorrelationId=$CorrelationId
        State='Starting'; Class=$taskClassValue; Provider=$providerValue; ProviderTarget=$providerTarget; ProviderGroup=$providerGroup; Sequence=(Get-DomeniaNextTaskSequence); QueuedAt=$null
        Subscribers=(New-Object System.Collections.ArrayList); BusyApplied=$false; Code=$Code; Payload=$Payload; StatusText=$StatusText
        ExecutedOperationId=''; Demo=$false; Isolated=$false; DedupKey=$dedupKey; SchedulerManaged=[bool]$scheduler; CredentialIdentity=''
        Foreground=[bool]$foregroundValue; ErrorInfo=$null
    }
    # W13 (point 123): the job joins the trace of its request before it is queued or dispatched.
    try { [void](Start-DomeniaJobTrace -Job $job -RequestedTraceId $TraceId -Payload $Payload -CallbackState $CallbackState) } catch { $script:DomeniaTraceFaults = [int]$script:DomeniaTraceFaults + 1 }
    if ($admission -eq 'Queue') {
        # Nothing is sent yet: the pinned body is checked now, the worker starts when Complete-UiTasks promotes it.
        try { [void](Assert-DomeniaWorkerOperationCode -OperationId $OperationId -Code $Code) }
        catch {
            # W13 (point 123): a body refused before queueing ends the trace of the job, like a refusal before dispatch.
            try { [void](Complete-DomeniaJobTrace -Job $job -Outcome 'Refused' -NotDispatched) } catch { $script:DomeniaTraceFaults = [int]$script:DomeniaTraceFaults + 1 }
            throw
        }
        $job.State = 'Queued'
        $job.QueuedAt = $now
        Set-ControlsBusy -Names $DisableControls -Busy $true
        $job.BusyApplied = $true
        $script:AsyncJobs[$id] = $job
        if ($foregroundValue) { Set-Status ("En attente : $Name. Aucune lecture envoyée pour lʼinstant.") }
        if ($foregroundValue) { $script:LatestTaskId = $id }
        try { Resume-DomeniaAsyncPoll } catch { Write-DomeniaSwallowed 'Core' 'Start-UiTask' $_ }
        Update-TaskUi -Force
        return $id
    }
    # D015/C2/D016/D018/D019: the launch body lives in Invoke-DomeniaUiTaskDispatch (Domenia-Engine.UI.ps1).
    try { [void](Invoke-DomeniaUiTaskDispatch -Job $job) }
    catch {
        # W13 (point 123): a refusal before dispatch ends the trace of the job; the refusal itself still reaches the caller.
        try { [void](Complete-DomeniaJobTrace -Job $job -Outcome 'Refused' -NotDispatched) } catch { $script:DomeniaTraceFaults = [int]$script:DomeniaTraceFaults + 1 }
        throw
    }
    $script:AsyncJobs[$id] = $job
    # CO-02: LatestTaskId follows the foreground tasks only; a local save never becomes the target of Annuler.
    if ($foregroundValue) { $script:LatestTaskId = $id }
    if ($admissionReason -and [bool]$IsWrite) { try { Set-Status $admissionReason } catch { Write-DomeniaSwallowed 'Core' 'Start-UiTask' $_ } }
    # PF-06: the engine poll stops at rest; a new task resumes it.
    try { Resume-DomeniaAsyncPoll } catch { Write-DomeniaSwallowed 'Core' 'Start-UiTask' $_ }
    Update-TaskUi -Force
    return $id
}

function Request-UiTaskStop {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][string]$Id,[switch]$Silent,[switch]$Force,[switch]$Superseded,[string]$Reason='Demande d arret')
    if (-not $script:AsyncJobs.Contains($Id)) { return }
    $job = $script:AsyncJobs[$Id]
    if ($null -eq $job) { return }
    if ([string]$job.State -eq 'Queued') {
        # D017: an entry never sent is withdrawn at once; no call to stop, no cleanup to wait for.
        if ([bool]$job.NonCancellable -and -not $Force) {
            if (-not $Silent) { Set-Status "Cette demande protégée reste en file : elle partira dès quʼune place se libère." "WARN" }
            return
        }
        Stop-DomeniaLiveJob -Job $job
        try { Stop-DomeniaComputerUserProbeUi -Job $job -Reason $Reason } catch {
            Write-AppLog ("Nettoyage etat de detection : " + $_.Exception.Message) 'WARN'
        }
        if ([string]$job.ReplaceKey -eq "object") {
            $objectRequestId = ""
            try { $objectRequestId = [string]$job.CallbackState.RequestId } catch { Write-DomeniaSwallowed 'Core' 'Request-UiTaskStop' $_ }
            if (-not $Superseded -and $objectRequestId -ceq [string]$script:CurrentObjectRequestId -and (Test-DomeniaSelectionLoadCurrent)) {
                Update-DomeniaSelectionReadUi -Phase Failed -Message 'Lecture interrompue. Aucune relance automatique ; utilisez Reessayer la lecture.'
            }
            if (-not [string]::IsNullOrWhiteSpace($objectRequestId)) { Clear-DomeniaCurrentObjectRequest -RequestId $objectRequestId }
        }
        Remove-DomeniaQueuedTask -Job $job -Silent:([bool]$Silent -or [bool]$Superseded) -TraceOutcome $(if ([bool]$Superseded) { 'Superseded' } else { 'Withdrawn' })
        Update-TaskUi -Force
        return
    }
    if ([bool]$job.NonCancellable -and -not $Force) {
        # CO-02: a local save is not an AD write: it says that it ends by itself.
        if (-not $Silent) {
            if ([bool]$job.IsWrite) { Set-Status "Cette écriture AD ne peut pas être annulée après envoi. Attendez la relecture de vérification." "WARN" }
            elseif ([string]$job.Provider -eq 'Storage' -or [string]$job.OperationId -in @('LocalStore','LiveCache','ReceiptStore','DocumentStore','LinkHistoryStore')) { Set-Status 'Enregistrement local : il se termine seul.' }
            else { Set-Status ([string]$job.Name + ' : opération locale protégée, elle se termine seule.') }
        }
        return
    }
    if ([bool]$job.CancelRequested) {
        if ($Superseded) { $job.Superseded = $true }
        return
    }

    $job.CancelRequested = $true
    $job.CancelRequestedAt = Get-Date
    $job.Superseded = [bool]$Superseded
    Stop-DomeniaLiveJob -Job $job
    try { Stop-DomeniaComputerUserProbeUi -Job $job -Reason $Reason } catch {
        Write-AppLog ("Nettoyage etat de detection : " + $_.Exception.Message) 'WARN'
    }
    if ([string]$job.ReplaceKey -eq "object") {
        $objectRequestId = ""
        try { $objectRequestId = [string]$job.CallbackState.RequestId } catch { Write-DomeniaSwallowed 'Core' 'Request-UiTaskStop' $_ }
        if (-not $Superseded -and $objectRequestId -ceq [string]$script:CurrentObjectRequestId -and (Test-DomeniaSelectionLoadCurrent)) {
            Update-DomeniaSelectionReadUi -Phase Failed -Message 'Lecture interrompue. Aucune relance automatique ; utilisez Reessayer la lecture.'
        }
        if (-not [string]::IsNullOrWhiteSpace($objectRequestId)) { Clear-DomeniaCurrentObjectRequest -RequestId $objectRequestId }
    }
    try { $job.StopHandle = $job.PowerShell.BeginStop($null,$null) }
    catch {
        Write-AppLog "[$($job.CorrelationId)] Demande d'arret asynchrone impossible pour $($job.Name) : $($_.Exception.Message)" "WARN"
    }
    if (-not $Silent -and -not $Superseded) {
        # D017: a stop request is never presented as a finished cancellation.
        $stopText = "Annulation demandee : $($job.Name). Le thread graphique reste disponible."
        try { $stopText = Get-DomeniaCancelStatusText -Name ([string]$job.Name) -State 'StopRequested' -IsWrite ([bool]$job.IsWrite) } catch { Write-DomeniaSwallowed 'Core' 'Request-UiTaskStop' $_ }
        Set-Status $stopText "WARN"
    }
    Update-TaskUi -Force
}

function Stop-UiTask {
    param([string]$Id,[switch]$Silent,[switch]$Force)
    Request-UiTaskStop -Id $Id -Silent:$Silent -Force:$Force
}

function Stop-LatestUiTask {
    # CO-02: Annuler targets the most recent cancellable foreground task (search, record, explicit action), then a
    # cancellable background read; never a local save. A write is refused; a lone local save ends by itself.
    $jobs = @($script:AsyncJobs.Values | Where-Object { $null -ne $_ })
    if ($jobs.Count -eq 0) { return }
    $target = $null
    if (-not [string]::IsNullOrWhiteSpace($script:LatestTaskId) -and $script:AsyncJobs.Contains($script:LatestTaskId)) {
        $latest = $script:AsyncJobs[$script:LatestTaskId]
        if ($null -ne $latest -and -not [bool]$latest.IsWrite -and -not [bool]$latest.NonCancellable -and -not [bool]$latest.CancelRequested) { $target = $latest }
    }
    foreach ($foreground in @($true,$false)) {
        if ($null -ne $target) { break }
        for ($i = $jobs.Count - 1; $i -ge 0; $i--) {
            $job = $jobs[$i]
            if ([bool]$job.IsWrite -or [bool]$job.NonCancellable -or [bool]$job.CancelRequested) { continue }
            $flag = $job.PSObject.Properties['Foreground']
            $isForeground = (($null -eq $flag) -or [bool]$flag.Value)
            if ($foreground -and -not $isForeground) { continue }
            $target = $job; break
        }
    }
    if ($null -eq $target) {
        if (@($jobs | Where-Object { [bool]$_.IsWrite }).Count) { Set-Status "Annulation refusée : une écriture AD est en cours ou en attente de confirmation du DC." "WARN"; return }
        if (@($jobs | Where-Object { -not [bool]$_.CancelRequested }).Count) { Set-Status 'Enregistrement local : il se termine seul.' }
        return
    }
    Request-UiTaskStop -Id ([string]$target.Id) -Reason 'Annulation utilisateur'
}

function Detach-DomeniaReadUiTask {
    param([Parameter(Mandatory=$true)][string]$Id,[string]$Reason="Worker non stoppable")
    if (-not $script:AsyncJobs.Contains($Id)) { return $false }
    $job = $script:AsyncJobs[$Id]
    if ($null -eq $job -or [bool]$job.IsWrite) { return $false }
    # A queued entry holds no native call: it is withdrawn by Request-UiTaskStop, never detached.
    if ([string]$job.State -eq 'Queued') { return $false }

    # Un appel LDAP/WMI natif peut ignorer l'annulation PowerShell. Dans ce cas
    # il ne doit surtout pas garder l'interface en etat "tache active" pendant
    # plusieurs minutes. On detache uniquement les LECTURES : aucun callback UI
    # ne sera rejoue, et le worker deja lance finira/sera stoppe hors du flux UI.
    try { Set-ControlsBusy -Names $job.DisableControls -Busy $false } catch { Write-DomeniaSwallowed 'Core' 'Detach-DomeniaReadUiTask' $_ }
    [void]$script:AsyncJobs.Remove($Id)
    if ([string]$script:LatestTaskId -eq $Id) { $script:LatestTaskId = "" }
    # W13 (point 123): the trace ends here for the interface; the native call may still finish its cleanup.
    $traceOutcome = 'Stopped'
    if ([bool]$job.Superseded) { $traceOutcome = 'Superseded' } elseif ([bool]$job.TimeoutErrorDelivered) { $traceOutcome = 'TimedOut' }
    try { [void](Complete-DomeniaJobTrace -Job $job -Outcome $traceOutcome -Detail 'lecture détachée de lʼinterface') } catch { $script:DomeniaTraceFaults = [int]$script:DomeniaTraceFaults + 1 }
    if ($null -eq $script:DetachedReadJobs) { $script:DetachedReadJobs = New-Object System.Collections.ArrayList }
    if ([string]$job.OperationId -eq 'ComputerLastUser') {
        Clear-DomeniaComputerUserProbeState -ProbeId ([string]$job.CallbackState.ProbeId) -Computer ([string]$job.CallbackState.Computer)
    }
    $job.OnSuccess = $null; $job.OnError = $null; $job.CallbackState = $null
    try { [void]$script:DetachedReadJobs.Add($job) } catch { Write-DomeniaSwallowed 'Core' 'Detach-DomeniaReadUiTask' $_ }
    try {
        Write-AppLog "[$($job.CorrelationId)] Lecture detachee du GUI apres annulation non cooperative : $($job.Name). $Reason" "WARN"
    } catch { Write-DomeniaSwallowed 'Core' 'Detach-DomeniaReadUiTask' $_ }
    # D017: the native call still runs and stays counted; say so instead of announcing a finished cancellation.
    if (-not [bool]$job.Superseded) {
        try { Set-Status (Get-DomeniaCancelStatusText -Name ([string]$job.Name) -State 'Cleanup') "WARN" } catch { Write-DomeniaSwallowed 'Core' 'Detach-DomeniaReadUiTask' $_ }
    }
    try { Update-TaskUi -Force } catch { Write-DomeniaSwallowed 'Core' 'Detach-DomeniaReadUiTask' $_ }
    return $true
}

function Complete-UiTasks {
    Sync-DomeniaCredentialGuardUi
    Complete-DomeniaDetachedReadJobs
    # D019: per-job resources are released once their job is neither active nor detached.
    try { Initialize-DomeniaEngineState; [void](Sync-DomeniaJobResources) } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
    $removed = $false
    # PF-04: a time budget per tick (Async.TickBudgetMs, about 25 ms) replaces MaxCompletionsPerTick, and finished
    # jobs are handled by class priority: Write, Explicit, Selection, then Background.
    $budgetMs = 25
    try { $budgetMs = [int](Get-DomeniaEngineLimits).TickBudgetMs } catch { $budgetMs = [Math]::Max(5,[Math]::Min(250,[int](Get-CfgValue "Async" "TickBudgetMs" 25))) }
    $callbackWarningMs = [Math]::Max(25,[int](Get-CfgValue "Async" "CallbackWarningMs" 120))
    $tickWatch = [System.Diagnostics.Stopwatch]::StartNew()
    $finished = New-Object 'System.Collections.Generic.List[object]'

    foreach ($id in @($script:AsyncJobs.Keys)) {
        $job = $script:AsyncJobs[$id]
        if ($null -eq $job) { continue }
        # D015: a queued entry has no worker yet; Invoke-DomeniaQueuedTaskPromotion handles it below.
        if ([string]$job.State -eq 'Queued') { continue }
        try { Receive-DomeniaComputerUserProbeProgress -Job $job } catch {
            Write-AppLog ("Progression detection : " + $_.Exception.Message) 'WARN'
        }
        $elapsed = ((Get-Date) - $job.Started).TotalSeconds
        $invokeCompleted = $false
        $stopCompleted = $false
        try { $invokeCompleted = [bool]$job.Handle.IsCompleted } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
        try { if ($null -ne $job.StopHandle) { $stopCompleted = [bool]$job.StopHandle.IsCompleted } } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }

        if (-not $invokeCompleted -or ($null -ne $job.StopHandle -and -not $stopCompleted)) {
            if ([bool]$job.CancelRequested -and -not [bool]$job.IsWrite) {
                $cancelAge = 0.0
                try { if ($null -ne $job.CancelRequestedAt) { $cancelAge = ((Get-Date) - [datetime]$job.CancelRequestedAt).TotalSeconds } } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
                $cancelGrace = [Math]::Max(1,[int](Get-CfgValue "Async" "CancelGraceSeconds" 5))
                if ($cancelAge -ge $cancelGrace) {
                    if (Detach-DomeniaReadUiTask -Id $id -Reason ("BeginStop sans retour apres " + [int]$cancelAge + " s")) { $removed = $true }
                    continue
                }
            }
            if ([bool]$job.IsWrite) {
                if ($elapsed -gt [int]$job.TimeoutSeconds -and -not [bool]$job.TimeoutNotified) {
                    $job.TimeoutNotified = $true
                    $script:WriteState = "UnknownPending"
                    $message = "Ecriture AD lente apres $([int]$elapsed)s : etat encore inconnu. Aucun rejeu automatique."
                    Set-Status $message "WARN"
                    Write-AppLog "[$($job.CorrelationId)] $message" "WARN"
                }
                if ($elapsed -gt [int]$job.HardTimeoutSeconds -and -not [bool]$job.CancelRequested) {
                    $script:WriteState = "Unknown"
                    $message = "ETAT INCONNU apres $([int]$elapsed)s : $($job.Name). Ne relance pas l'action avant relecture de l'objet."
                    if (-not [bool]$job.TimeoutErrorDelivered) {
                        try { Invoke-DomeniaJobErrorUi -Job $job -Message $message } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
                        $job.TimeoutErrorDelivered = $true
                    }
                    Request-UiTaskStop -Id $id -Silent -Force
                }
            }
            elseif (-not [bool]$job.CancelRequested) {
                $deadline = Get-DomeniaReadTimeoutState -Job $job -ElapsedSeconds $elapsed
                if ($deadline.Expired) {
                    $message = [string]$deadline.Message
                    if (-not [bool]$job.TimeoutErrorDelivered) {
                        try { Invoke-DomeniaJobErrorUi -Job $job -Message $message } catch { Set-Status $message "ERROR" }
                        $job.TimeoutErrorDelivered = $true
                        # D018: repeated outages of one provider pause its background reads, never the explicit ones.
                        try { [void](Register-DomeniaTaskOutcome -Job $job -TimedOut) } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
                        try { Invoke-DomeniaTaskSubscribers -Job $job -Output $null -ErrorMessage $message } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
                    }
                    Request-UiTaskStop -Id $id -Silent -Force -Reason 'Delai de lecture depasse'
                }
            }
            continue
        }

        $finished.Add([pscustomobject]@{Key=$id;Job=$job;Class=[string]$job.Class;Sequence=[long]$job.Sequence;InvokeCompleted=$invokeCompleted;StopCompleted=$stopCompleted})
    }
    $ordered = $finished.ToArray()
    try { $ordered = @(Get-DomeniaTaskOrder -Jobs $finished.ToArray()) } catch { $ordered = $finished.ToArray() }
    $handled = 0
    foreach ($entry in $ordered) {
        $id = $entry.Key; $job = $entry.Job
        if (-not $script:AsyncJobs.Contains($id)) { continue }
        # Une rafale de callbacks WPF ne doit jamais monopoliser le dispatcher : au moins une fin par tick, puis le budget.
        if ($handled -gt 0 -and $tickWatch.ElapsedMilliseconds -ge $budgetMs) { break }
        $handled++
        $invokeCompleted = [bool]$entry.InvokeCompleted
        $stopCompleted = [bool]$entry.StopCompleted
        # W13 (points 121, 123): end of the worker as seen by the poll, and start of the reception and validation.
        $traceWorkerEnd = Get-Date
        $traceMark = [Diagnostics.Stopwatch]::GetTimestamp()
        $traceValidateMs = [double]-1
        $traceSlowText = ''
        $traceCallbackFailed = $false

        $errorMessage = ""
        $output = $null
        if ([bool]$job.CancelRequested) {
            try { if ($stopCompleted) { $job.PowerShell.EndStop($job.StopHandle) } } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
            try {
                if ($invokeCompleted) {
                    $collection=$job.PowerShell.EndInvoke($job.Handle)
                    if($null -ne $collection){if($collection.Count -eq 1){$output=$collection[0]}else{$output=@($collection)}}
                }
            } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
        }
        else {
            try {
                $collection = $job.PowerShell.EndInvoke($job.Handle)
                if ($job.PowerShell.Streams.Error.Count -gt 0) { $errorMessage = (($job.PowerShell.Streams.Error | ForEach-Object { $_.ToString() }) -join " | ") }
                if ($null -eq $collection) { $output = $null }
                elseif ($collection.Count -eq 1) { $output = $collection[0] }
                else { $output = @($collection) }
            }
            catch { $errorMessage = $_.Exception.Message }
        }

        # D019: the registry releases what the job owned; the direct calls stay as an idempotent fallback.
        try { if ($null -ne $script:DomeniaResources) { [void](Release-DomeniaResources -Registry $script:DomeniaResources -Owner ([string]$id)) } } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
        try { $job.PowerShell.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
        try { $job.Runspace.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
        if ($null -eq $job.PSObject.Properties['BusyApplied'] -or [bool]$job.BusyApplied) { Set-ControlsBusy -Names $job.DisableControls -Busy $false }
        [void]$script:AsyncJobs.Remove($id)
        $removed = $true
        if ($script:ActiveWriteTaskId -eq $id) {
            $script:ActiveWriteTaskId = ""
            if ($script:WriteState -ne "Unknown") { $script:WriteState = "Idle" }
        }
        if ([bool]$job.IsWrite) { try { [void](Update-DomeniaIdlePolicy) } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ } }
        # W13/W14 (points 121, 122): one measure of the worker per job. The Collect phase of its trace (dispatch to the end
        # seen by this poll) is the duration kept for the percentiles of the operations panel, so an explained slowness
        # and a percentile never come from two clocks.
        $traceCollectMs = [double]-1
        try { $traceCollectMs = [double](Get-DomeniaJobPhaseMeasures -Job $job -WorkerEnd $traceWorkerEnd).CollectMs } catch { $script:DomeniaTraceFaults = [int]$script:DomeniaTraceFaults + 1 }
        try { Add-DomeniaTaskRuntimeMetric -Job $job -DurationMs $traceCollectMs } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }

        if([bool]$job.CancelRequested -or [bool]$job.Superseded -or [long]$job.SessionEpoch -ne [long]$script:SessionEpoch){
            try{[void](Save-DomeniaSupersededCollection -Job $job -Output $output -ErrorMessage $errorMessage)}
            catch{Write-AppLog ('Conservation du releve termine impossible : '+$_.Exception.Message) 'ERROR'}
        }

        if ([bool]$job.CancelRequested) {
            if (-not [bool]$job.Superseded -and -not [bool]$job.TimeoutErrorDelivered) {
                $endText = "Operation annulee : $($job.Name)."
                try { $endText = Get-DomeniaCancelStatusText -Name ([string]$job.Name) -State 'Completed' } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
                Set-Status $endText "WARN"
            }
            # A write stopped by its hard deadline has an unknown result; a read is stopped, replaced or out of time.
            $traceOutcome = 'Stopped'
            if ([bool]$job.IsWrite) { $traceOutcome = 'Unknown' } elseif ([bool]$job.TimeoutErrorDelivered) { $traceOutcome = 'TimedOut' } elseif ([bool]$job.Superseded) { $traceOutcome = 'Superseded' }
            try { [void](Complete-DomeniaJobTrace -Job $job -Outcome $traceOutcome -WorkerEnd $traceWorkerEnd) } catch { $script:DomeniaTraceFaults = [int]$script:DomeniaTraceFaults + 1 }
            continue
        }

        if ([bool]$script:AsyncEngineClosing -or [bool]$job.Superseded -or [long]$job.SessionEpoch -ne [long]$script:SessionEpoch) {
            $output = $null
            $traceOutcome = 'Superseded'
            if ([bool]$job.IsWrite) { $traceOutcome = 'Unknown' }
            try { [void](Complete-DomeniaJobTrace -Job $job -Outcome $traceOutcome -WorkerEnd $traceWorkerEnd) } catch { $script:DomeniaTraceFaults = [int]$script:DomeniaTraceFaults + 1 }
            continue
        }
        # CD-12: the error of a task is analysed once; the same object feeds the provider outcome, the anti-lockout
        # breaker and the callbacks (on the job: $Job.ErrorInfo, reachable through $script:AccessCurrentJob).
        $errorInfo = $null
        if (-not [string]::IsNullOrWhiteSpace($errorMessage)) { $errorInfo = ConvertTo-DomeniaTaskErrorInfo -Job $job -Message $errorMessage }
        try { [void](Register-DomeniaTaskOutcome -Job $job -ErrorMessage $errorMessage -ErrorInfo $errorInfo) } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
        # FI-12: a SQLite lock wait that ran out is counted for the Operations panel (session counter, no retry).
        try { [void](Register-DomeniaSqliteBusyOutcome -Job $job -Output $output -ErrorMessage $errorMessage) } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
        $traceValidateMs = [double](([Diagnostics.Stopwatch]::GetTimestamp() - $traceMark) * 1000.0 / [Diagnostics.Stopwatch]::Frequency)
        if ([string]::IsNullOrWhiteSpace($errorMessage)) {
            $callbackWatch = [System.Diagnostics.Stopwatch]::StartNew()
            $modalBefore = [long]$script:ModalBlockedMs
            try { Invoke-DomeniaJobSuccessUi -Job $job -Output $output }
            catch {
                $callbackMessage = [string]$_.Exception.Message
                $callbackStack = [string]$_.ScriptStackTrace
                $errorMessage = "Callback UI ($($job.Name)) : $callbackMessage"
                $traceCallbackFailed = $true
                Write-AppLog "[$($job.CorrelationId)] $errorMessage  pile=$callbackStack" "ERROR"
            }
            finally {
                $callbackWatch.Stop()
                $modalMs = [long]$script:ModalBlockedMs - $modalBefore
                $effectiveMs = [long]$callbackWatch.ElapsedMilliseconds - $modalMs
                if ($effectiveMs -lt 0) { $effectiveMs = 0 }
                # Keep UI completion costs distinct from worker/network duration in the local bounded metrics.
                try { Add-DomeniaRuntimeMetric -Provenance 'Dispatcher' -OperationId ('Callback:' + [string]$job.OperationId) -DurationMs ([double]$effectiveMs) } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
                # W13 (point 121): the cost, the volume received and the handler are kept for the trace; a slow callback
                # is explained by its operation, its phases, its volume and its handler.
                $traceVolume = [long]-1
                try { $traceVolume = [long](Get-DomeniaOutputVolume $output) } catch { $script:DomeniaTraceFaults = [int]$script:DomeniaTraceFaults + 1 }
                try { $traceSlowText = [string](Register-DomeniaJobPublication -Job $job -PublishMs ([double]$effectiveMs) -Volume $traceVolume -ThresholdMs ([double]$callbackWarningMs) -ValidateMs $traceValidateMs -WorkerEnd $traceWorkerEnd) } catch { $traceSlowText = '' }
                if ($effectiveMs -gt $callbackWarningMs) {
                    if (-not $traceSlowText) { $traceSlowText = "Callback UI lent : $($job.Name), $effectiveMs ms (seuil $callbackWarningMs ms ; operation $($job.OperationId) ; traitement $($job.SuccessHandler))." }
                    Write-AppLog "[$($job.CorrelationId)] $traceSlowText Hors $modalMs ms d'attente modale." "WARN"
                }
            }
            # D015: each subscriber of a shared read gets its own callback (access inspection ran once above).
            if ([string]::IsNullOrWhiteSpace($errorMessage)) { try { Invoke-DomeniaTaskSubscribers -Job $job -Output $output } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ } }
        }
        if (-not [string]::IsNullOrWhiteSpace($errorMessage)) {
            # Circuit breaker anti-lockout : un seul rejet d'identifiants par un
            # worker AD suspend tout nouveau bind explicite. On ne transforme pas
            # l'identite et on ne retente pas automatiquement avec une variante.
            $credentialRejected = ($errorMessage -match "(?i)(nom d.utilisateur ou le mot de passe est incorrect|user name or password is incorrect|logon failure|identifiant ou mot de passe|credentials?.*(invalid|incorrect)|compte.*verrouill|account.*locked)")
            # D052: the structured decision (native code or worker marker, French and English alike) joins the text rule;
            # a delay or a refused right never trips the anti-lockout breaker. CD-12: computed once, above.
            if ($null -eq $errorInfo) { $errorInfo = ConvertTo-DomeniaTaskErrorInfo -Job $job -Message $errorMessage }
            if (-not $credentialRejected -and $null -ne $errorInfo) { $credentialRejected = ([string](Get-DomeniaMember $errorInfo 'Category' '') -in @('CredentialsRejected','AccountState')) }
            if ($credentialRejected) {
                # C3/D018: only an operation that can carry the AD account trips the AD breaker. A refused
                # workstation, WTS or local-storage account (SessionsList, LocalStore...) never suspends the directory.
                $directoryBreaker = $true
                try { $directoryBreaker = [bool](Get-DomeniaOperationCredentialNeeds ([string]$job.OperationId)).DirectoryBreaker } catch { $directoryBreaker = $true }
                # LAPS and BitLocker keep their own account and refusals (ReadBitLockerList and ReadBitLockerKey included).
                $separate=([string](Get-DomeniaOperationCredentialNeeds ([string]$job.OperationId)).Resource -in @('Laps','BitLocker') -or $null -ne (Get-DomeniaRetryCredential ([string]$job.OperationId)))
                if($separate -and $null -ne $script:AccessState){$script:AccessState.Faults[(Get-DomeniaAccessScope ([string]$job.OperationId))]=$true}
                if (-not $separate -and $directoryBreaker) {
                    $script:DirectoryCredentialFaulted = $true
                    $script:DirectoryCredentialFaultMessage = [string]$errorMessage
                    Set-Status "Authentification AD rejetee : canal AD suspendu pour eviter un verrouillage de compte. Reconnecte Domenia." "ERROR"
                    Write-AppLog "[$($job.CorrelationId)] Circuit breaker AD active apres rejet d'authentification ; aucun nouveau bind explicite ne sera lance dans cette session." "ERROR"
                }
            }
            if (-not [bool]$job.TimeoutErrorDelivered) {
                try { Invoke-DomeniaJobErrorUi -Job $job -Message $errorMessage }
                catch {
                    Set-Status "$($job.Name) : $errorMessage" "ERROR"
                    Write-AppLog "[$($job.CorrelationId)] Callback d'erreur UI impossible : $($_.Exception.Message)" "ERROR"
                }
                try { Invoke-DomeniaTaskSubscribers -Job $job -Output $null -ErrorMessage $errorMessage } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
            }
            Write-AppLog "[$($job.CorrelationId)] $($job.Name) : $errorMessage" "ERROR"
        }
        # W13 (point 123): end of the trace of this job, with its error category (a code, never the message).
        try {
            if ([string]::IsNullOrWhiteSpace($errorMessage)) { [void](Complete-DomeniaJobTrace -Job $job -Outcome 'Succeeded' -ValidateMs $traceValidateMs -WorkerEnd $traceWorkerEnd) }
            else {
                $traceCategory = [string](Get-DomeniaMember $errorInfo 'Category' '')
                if ($traceCallbackFailed) { $traceCategory = 'InterfaceCallback' }
                $traceOutcome = 'Failed'
                if ([bool]$job.IsWrite -and ([string]$script:WriteState -in @('Unknown','UnknownPending'))) { $traceOutcome = 'Unknown' }
                [void](Complete-DomeniaJobTrace -Job $job -Outcome $traceOutcome -ValidateMs $traceValidateMs -Category $traceCategory -WorkerEnd $traceWorkerEnd)
            }
        } catch { $script:DomeniaTraceFaults = [int]$script:DomeniaTraceFaults + 1 }
    }
    # D015 / PF-04: queued entries start by priority while the admission and the tick budget allow; stale or expired
    # entries leave the queue.
    try { if (Invoke-DomeniaQueuedTaskPromotion -BudgetMs ([Math]::Max(5,$budgetMs - [int]$tickWatch.ElapsedMilliseconds))) { $removed = $true } }
    catch { try { Write-AppLog ("Promotion de la file : " + $_.Exception.Message) "ERROR" } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ } }
    if ($removed) { Update-TaskUi -Force } else { Update-TaskUi }
    # PF-06: without task, queued entry or detached read, the poll stops; Start-UiTask resumes it.
    if ((@($script:AsyncJobs.Keys).Count -eq 0) -and (@($script:DetachedReadJobs).Count -eq 0)) {
        try { if ($null -ne $script:AsyncTimer -and [bool]$script:AsyncTimer.IsEnabled) { $script:AsyncTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Complete-UiTasks' $_ }
    }
}


function Dispose-AsyncEngine {
    Stop-DomeniaLive -Closing
    $script:AsyncEngineClosing = $true
    try {
        if ($null -ne $script:AccountCredentialTestSession) {
            Stop-DomeniaLoginAuthRunspace -Session $script:AccountCredentialTestSession -Terminate
            $script:AccountCredentialTestSession = $null
        }
    } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
    try { Stop-DomeniaSelectionOpenTimer } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
    try { Clear-DomeniaTreeRenderJobs } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
    # D019: every timer registered with an owner is stopped by the registry; the historical list stays as a
    # fallback for timers created outside it. Active jobs are never disposed here (see below).
    try { Initialize-DomeniaEngineState; [void](Release-DomeniaResources -Registry $script:DomeniaResources -Kind 'Timer') } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
    foreach ($timerName in @('AsyncTimer','TreeRenderTimer','SelectionOpenTimer','SettingsTimer','SecretLifetimeTimer','SecretRevealTimer','SecretClipboardTimer','LinkProbeTimer','LiveSearchTimer','DashboardRefreshTimer','DomeniaIndexSearchTimer')) {
        try { $timer = Get-Variable -Name $timerName -Scope Script -ValueOnly -ErrorAction SilentlyContinue; if ($null -ne $timer) { $timer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
    }
    foreach ($id in @($script:AsyncJobs.Keys)) { Request-UiTaskStop -Id $id -Silent -Force }
    foreach ($id in @($script:AsyncJobs.Keys)) {
        $job = $script:AsyncJobs[$id]
        if ($null -eq $job) { [void]$script:AsyncJobs.Remove($id); continue }
        $done = $false; $stopDone = $true
        try { $done = [bool]$job.Handle.IsCompleted } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
        try { if ($null -ne $job.StopHandle) { $stopDone = [bool]$job.StopHandle.IsCompleted } } catch { $stopDone = $false }
        if ($done -and $stopDone) {
            try { if ($null -ne $job.StopHandle) { $job.PowerShell.EndStop($job.StopHandle) } } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
            try { [void]($job.PowerShell.EndInvoke($job.Handle)) } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
            try { $job.PowerShell.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
            try { $job.Runspace.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
            [void]$script:AsyncJobs.Remove($id)
        } elseif (-not [bool]$job.IsWrite) {
            [void](Detach-DomeniaReadUiTask -Id $id -Reason 'Fermeture de la fenetre')
        }
        # Pending writes are never declared successful or silently replayed.
    }
    Complete-DomeniaDetachedReadJobs
    try { [void](Sync-DomeniaJobResources) } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
    $script:PendingObjectSelection = $null
    $script:CurrentObjectRequestId = ''
    $script:CurrentObjectRequestDn = ''
    $script:AsyncEngineReady = $false
    $script:AsyncTimer = $null
    # D019: the shared read pools are owned by the registry; the historical loop closes any pool left outside it.
    try { [void](Release-DomeniaResources -Registry $script:DomeniaResources -Kind 'RunspacePool') } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
    if ($null -ne $script:LiveWorkerPools) {
        foreach ($record in @($script:LiveWorkerPools.Values)) {
            try { [void]$record.Pool.BeginClose($null,$null) } catch { Write-DomeniaSwallowed 'Core' 'Dispose-AsyncEngine' $_ }
        }
        $script:LiveWorkerPools=@{}
    }
}

function Initialize-DomeniaWorkerContextCache {
    if ($null -ne $script:WorkerContextStatic) { return }
    Initialize-DomeniaDataStore | Out-Null
    $integrity = Get-DomeniaIntegritySnapshot
    $script:WorkerContextStatic = [pscustomobject]@{
        AdModuleSources = @(Get-DomeniaAdModuleSources)
        AdRequiredCommands = @(Get-DomeniaRequiredAdCommands)
        AdTypeNames = @(Get-DomeniaAdTypeNames)
        AdManagementHash = "1A6AF7B8F8BCE5B35FF873E2528746480C980526D86E38CA5ACD04C2E9037157"
        AdResourceHash = "E233D92238AA31EA1B3C60145D8811EDB2E517E1B9B53F4BC496883EE5D9973B"
        MissingCriticalFunctions = @($integrity.MissingFunctions)
        MissingCriticalControls = @($integrity.MissingControls)
        CriticalFunctionCount = [int]$integrity.CriticalFunctionCount
        CriticalControlCount = [int]$integrity.CriticalControlCount
        PowerShellVersion = [string]$PSVersionTable.PSVersion
        IsSta = ([System.Threading.Thread]::CurrentThread.ApartmentState -eq [System.Threading.ApartmentState]::STA)
    }
}

function Get-WorkerContext {
    param([string]$OperationId = "",$Payload=$null)
    Initialize-DomeniaWorkerContextCache
    $credentialNeeds = Get-DomeniaOperationCredentialNeeds -OperationId $OperationId
    $acceptsCredential=([bool]$credentialNeeds.DirectoryCredential -or [bool]$credentialNeeds.Machine -or [bool]$credentialNeeds.RemoteAdmin -or [bool]$credentialNeeds.Secrets)
    $retryCredential=$null;$retryScope=''
    if($acceptsCredential){
        $retryCredential=Get-DomeniaRetryCredential $OperationId
        $retryScope=Get-DomeniaAccessScope $OperationId
        if($null -ne $script:AccessState -and $script:AccessState.Faults.ContainsKey($retryScope)){throw 'Authentification rejetee pour cette ressource. Utilisez un autre compte avant de recommencer.'}
    }
    $static = $script:WorkerContextStatic
    # PF-23: the configuration part of the context is read once per configuration object (Load-AppConfig builds a
    # new one); only the identities are computed per operation. Without a loaded configuration it is read each time.
    $cfg = $script:WorkerContextConfig
    if (($null -eq $script:Config) -or ($null -eq $cfg) -or (-not [object]::ReferenceEquals($cfg.Config,$script:Config))) {
        # FI-12: the SQLite lock wait of every worker comes from LocalStore.DatabaseBusyTimeoutMs (2 500 ms documented),
        # clamped like the interface connection (100 to 5 000 ms); an unreadable value keeps the documented default.
        $busyTimeoutMs = 2500
        $busyTimeoutValue = 0
        if ([int]::TryParse([string](Get-CfgValue 'LocalStore' 'DatabaseBusyTimeoutMs' 2500),[ref]$busyTimeoutValue)) { $busyTimeoutMs = [Math]::Max(100,[Math]::Min(5000,$busyTimeoutValue)) }
        $cfg = [pscustomobject]@{
            Config = $script:Config
            PageSize = [int](Get-CfgValue "Browser" "MaxPageSize" 300)
            PreferModule = [bool](Get-CfgValue "Modules" "PreferActiveDirectoryModule" $true)
            ModuleUseCredential = [bool](Get-CfgValue "Modules" "UseCredential" $true)
            PortTimeoutMs = [int](Get-CfgValue "Remote" "PortTimeoutMs" 1200)
            RemoteCommandTimeoutSeconds = [Math]::Max(3,[int](Get-CfgValue "Remote" "CommandTimeoutSeconds" 10))
            UseCim = [bool](Get-CfgValue "Remote" "UseCim" $true)
            UseWinRM = [bool](Get-CfgValue "Remote" "UseWinRM" $true)
            UsePsExecFallback = [bool](Get-CfgValue "Remote" "UsePsExecFallback" $true)
            UseTaskFallback = [bool](Get-CfgValue "Remote" "UseTaskFallback" $true)
            TaskFallbackTimeoutSeconds = [Math]::Max(15,[int](Get-CfgValue "Remote" "TaskFallbackTimeoutSeconds" 75))
            WaptEnabled = [bool](Get-CfgValue "WAPT" "Enabled" $false)
            WaptGetPath = [string](Get-CfgValue "WAPT" "WaptGetPath" "")
            WaptServerUrl = [string](Get-CfgValue "WAPT" "ServerUrl" "")
            BlockProtectedObjects = [bool](Get-CfgValue "Security" "BlockProtectedObjects" $true)
            AllowProtectedObjectWrites = [bool](Get-CfgValue "Security" "AllowProtectedObjectWrites" $false)
            AllowContainerDelete = [bool](Get-CfgValue "Security" "AllowContainerDelete" $false)
            AllowRawAttributeWrite = [bool](Get-CfgValue "Security" "AllowRawAttributeWrite" $false)
            BlockSensitiveRawAttributes = [bool](Get-CfgValue "Security" "BlockSensitiveRawAttributes" $true)
            RequireFreshObject = [bool](Get-CfgValue "Security" "RequireFreshObject" $true)
            SingleWriteChannel = [bool](Get-CfgValue "Security" "SingleWriteChannel" $true)
            DatabaseBusyTimeoutMs = [int]$busyTimeoutMs
        }
        if ($null -ne $script:Config) { $script:WorkerContextConfig = $cfg }
    }
    # C3 (D018): one reviewed table, Get-DomeniaOperationCredentialNeeds (Domenia-Engine.Model.ps1), replaces the
    # three historical lists; its golden test keeps every registered operation identical to RC1.10.7.
    # "LiveSelectedPing" stays credential free (local/network list of the table).
    # ComputerLastUser valide les candidats dans LDAP : ce n est pas une
    # operation exclusivement distante, contrairement au ping/inventaire.
    $needsDirectoryCredential = [bool]$credentialNeeds.Directory
    if($OperationId -eq 'LiveConsole' -and $null -ne $Payload -and -not [bool](Get-DomeniaMember $Payload 'ValidateConsoleIdentity' $true)){$needsDirectoryCredential=$false}
    $directoryRecovery=($null -ne $retryCredential -and $retryScope -ne 'Remote') -or ([bool]$credentialNeeds.Secrets -and $null -ne $script:SecretsCredential)
    if ($needsDirectoryCredential -and [bool]$script:DirectoryCredentialFaulted -and -not $directoryRecovery) {
        $fault = [string]$script:DirectoryCredentialFaultMessage
        if ([string]::IsNullOrWhiteSpace($fault)) { $fault = "authentification AD rejetee" }
        throw "Canal Active Directory suspendu apres un rejet d'authentification ($fault). Reconnecte DOMENIA avant toute nouvelle lecture AD."
    }
    $useDirectoryCredential = ([bool]$credentialNeeds.DirectoryCredential -and ($needsDirectoryCredential -or $OperationId -eq 'ReceiptStore') -and [bool]$cfg.ModuleUseCredential -and [bool]$script:Conn.UseCredential -and $null -ne $script:Conn.Credential)
    $useRemoteAdminCredential = ([bool]$credentialNeeds.RemoteAdmin -and ($null -ne $script:RemoteAdminCredential -or ([bool]$script:Conn.UseCredential -and $null -ne $script:Conn.Credential)))
    $useSecretsCredential = ([bool]$credentialNeeds.Secrets -and ($null -ne $script:SecretsCredential -or ([bool]$script:Conn.UseCredential -and $null -ne $script:Conn.Credential)))
    $workerDirectoryCredential = if ($useSecretsCredential -and $null -ne $script:SecretsCredential) { $script:SecretsCredential } elseif ($useDirectoryCredential) { $script:Conn.Credential } elseif ($useSecretsCredential) { $script:Conn.Credential } else { $null }
    # SE-07 : l autorisation de lecture par transport intrusif est distincte de celle d une
    # intervention. Elle est lue ici, sur le fil UI ou le plan des modules est disponible, puis
    # retiree : une demande ne vaut que pour la prochaine lecture de ce poste.
    $readConsentActive = ($null -ne $script:ReadFallbackConsent -and $script:ReadFallbackConsent.Epoch -eq [long]$script:SessionEpoch -and $script:ReadFallbackConsent.Expires -gt [datetime]::UtcNow)
    $readGate = Test-DomeniaTransportFallbackAllowed -Transport 'PsExec / Planificateur' -Intrusive $true -IsRead $true -ReadConsentGiven $readConsentActive
    $result=[pscustomobject]@{
        Server = [string]$script:Conn.Server
        BaseDn = [string]$script:Conn.BaseDn
        Domain = [string]$script:Conn.Domain
        Netbios = [string]$script:Conn.Netbios
        # Un compte Secrets dedie ne doit jamais recevoir le nom du compte AD.
        BindUser = if ($null -ne $workerDirectoryCredential) { [string]$workerDirectoryCredential.UserName } else { [string]$script:Conn.BindUser }
        Credential = $workerDirectoryCredential
        PageSize = [int]$cfg.PageSize
        AdModuleSources = @($static.AdModuleSources)
        AdRequiredCommands = @($static.AdRequiredCommands)
        AdTypeNames = @($static.AdTypeNames)
        AdManagementHash = [string]$static.AdManagementHash
        AdResourceHash = [string]$static.AdResourceHash
        PreferModule = [bool]$cfg.PreferModule
        UseCredential = ($useDirectoryCredential -or $useSecretsCredential)
        AuthMode = [string]$script:Conn.AuthMode
        RootDir = [string]$script:RootDir
        ReceiptRoot = (Join-Path ([Environment]::GetFolderPath('LocalApplicationData')) 'Domenia\Receipts')
        DataDir = [string]$script:DataDir
        AuditPath = [string]$script:AuditPath
        ScriptPath = [string]$script:LaunchPath
        AppVersion = [string]$script:Version
        MasterBuild = [string]$script:MasterBuild
        ProcessIdentity = [string]$script:ProcessIdentity
        MachineCredential = if ([bool]$credentialNeeds.Machine) { if ($null -ne $script:MachineCredential) { $script:MachineCredential } elseif ($null -ne $script:RemoteAdminCredential) { $script:RemoteAdminCredential } elseif ([bool]$script:Conn.UseCredential) { $script:Conn.Credential } else { $null } } else { $null }
        RemoteAdminUser = if ($useRemoteAdminCredential) { if ($null -ne $script:RemoteAdminCredential) { [string]$script:RemoteAdminCredential.UserName } else { [string]$script:Conn.BindUser } } else { "" }
        RemoteAdminCredential = if ($useRemoteAdminCredential) { if ($null -ne $script:RemoteAdminCredential) { $script:RemoteAdminCredential } elseif ([bool]$script:Conn.UseCredential) { $script:Conn.Credential } else { $null } } else { $null }
        OperationId = $OperationId
        PortTimeoutMs = [int]$cfg.PortTimeoutMs
        RemoteCommandTimeoutSeconds = [int]$cfg.RemoteCommandTimeoutSeconds
        UseCim = [bool]$cfg.UseCim
        UseWinRM = [bool]$cfg.UseWinRM
        UsePsExecFallback = [bool]$cfg.UsePsExecFallback
        AllowRemoteArtifacts = ($null -ne $script:ArtifactConsent -and $script:ArtifactConsent.Epoch -eq $script:SessionEpoch -and $script:ArtifactConsent.Expires -gt [datetime]::UtcNow)
        ArtifactTarget = $(if($null -ne $script:ArtifactConsent){[string]$script:ArtifactConsent.Target}else{''})
        ArtifactAliases = $(if($null -ne $script:ArtifactConsent){[string[]]$script:ArtifactConsent.Aliases}else{@()})
        ReadFallbackTarget = $(if($null -ne $script:ReadFallbackConsent){[string]$script:ReadFallbackConsent.Target}else{''})
        ReadFallbackAliases = $(if($null -ne $script:ReadFallbackConsent){[string[]]$script:ReadFallbackConsent.Aliases}else{@()})
        AllowReadFallback = $(if($readConsentActive -and [bool]$readGate.Allowed){$script:ReadFallbackConsent=$null;$true}else{$false})
        ReadFallbackReason = $(if([bool]$readGate.Allowed){''}else{[string]$readGate.Reason})
        UseTaskFallback = [bool]$cfg.UseTaskFallback
        TaskFallbackTimeoutSeconds = [int]$cfg.TaskFallbackTimeoutSeconds
        ExpectedControls = if ($null -ne $script:Ctrl) { [int]$script:Ctrl.Count } else { 0 }
        MissingCriticalFunctions = @($static.MissingCriticalFunctions)
        MissingCriticalControls = @($static.MissingCriticalControls)
        CriticalFunctionCount = [int]$static.CriticalFunctionCount
        CriticalControlCount = [int]$static.CriticalControlCount
        AsyncEngineReady = [bool]$script:AsyncEngineReady
        PowerShellVersion = [string]$static.PowerShellVersion
        IsSta = [bool]$static.IsSta
        WaptEnabled = [bool]$cfg.WaptEnabled
        WaptGetPath = [string]$cfg.WaptGetPath
        WaptServerUrl = [string]$cfg.WaptServerUrl
        BlockProtectedObjects = [bool]$cfg.BlockProtectedObjects
        AllowProtectedObjectWrites = [bool]$cfg.AllowProtectedObjectWrites
        AllowContainerDelete = [bool]$cfg.AllowContainerDelete
        AllowRawAttributeWrite = [bool]$cfg.AllowRawAttributeWrite
        BlockSensitiveRawAttributes = [bool]$cfg.BlockSensitiveRawAttributes
        RawAttributeBlockList = @($script:RawAttributeBlockList)
        RequireFreshObject = [bool]$cfg.RequireFreshObject
        SingleWriteChannel = [bool]$cfg.SingleWriteChannel
        BusyTimeoutMs = [int]$cfg.DatabaseBusyTimeoutMs
        ReadOnlyMode = [bool]$script:ReadOnlyMode
        WriteState = [string]$script:WriteState
    }
    if($OperationId -eq 'UserComputerProbe'){
        $remoteRetry=Get-DomeniaRetryCredential 'LiveConsole'
        if($null -ne $remoteRetry){$result.MachineCredential=$remoteRetry;$result.RemoteAdminCredential=$remoteRetry;$result.RemoteAdminUser=$remoteRetry.UserName}
        $blocked=($null -ne $script:AccessState -and $script:AccessState.Faults.ContainsKey('Remote'))
        $result|Add-Member -NotePropertyName RelationRemoteBlocked -NotePropertyValue $blocked
    }
    if(-not $acceptsCredential){return $result}
    return Set-DomeniaRetryWorkerContext -Context $result -OperationId $OperationId
}

# Helpers injectes dans chaque runspace. Ils ne realisent aucune ecriture seuls.
$script:WorkerCommon += @'
function Convert-WIsoDate {
    param($Value)
    if ($null -eq $Value -or [string]::IsNullOrWhiteSpace([string]$Value)) { return "" }
    try { return ([datetime]$Value).ToUniversalTime().ToString("o") } catch { return [string]$Value }
}
function Get-WObjectSnapshot {
    param($Context,[string]$Dn)
    if ([string]::IsNullOrWhiteSpace($Dn)) { return [pscustomobject]@{Exists=$false;DN=""} }
    $s=$null;$ownedRoot=$null
    try {
        $props=@("distinguishedName","objectGUID","uSNChanged","whenChanged","adminCount","isCriticalSystemObject","objectClass","objectCategory","name","sAMAccountName","userAccountControl","lockoutTime","msDS-User-Account-Control-Computed")
        $s=New-WSearcher $Context $Dn "(objectClass=*)" $props "Base" 1
        $ownedRoot=$s.SearchRoot
        $r=$s.FindOne()
        if($null -eq $r){return [pscustomobject]@{Exists=$false;DN=$Dn}}
        $classes=@(Get-WPropAll $r.Properties "objectclass" | ForEach-Object {[string]$_})
        [pscustomobject]@{
            Exists=$true
            DN=[string](Get-WPropFirst $r.Properties "distinguishedname" $Dn)
            Guid=[string](Convert-WGuid (Get-WPropFirst $r.Properties "objectguid" $null))
            Usn=[string](Get-WPropFirst $r.Properties "usnchanged" "")
            WhenChanged=(Convert-WIsoDate (Get-WPropFirst $r.Properties "whenchanged" ""))
            AdminCount=[string](Get-WPropFirst $r.Properties "admincount" "")
            Critical=([string](Get-WPropFirst $r.Properties "iscriticalsystemobject" "false") -match "^(?i:true|1)$")
            Classes=$classes
            Name=[string](Get-WPropFirst $r.Properties "name" "")
            Sam=[string](Get-WPropFirst $r.Properties "samaccountname" "")
            Uac=[int](Get-WPropFirst $r.Properties "useraccountcontrol" 0)
            Lockout=[string](Get-WPropFirst $r.Properties "lockouttime" "0")
        }
    } catch { throw }
    finally {if($null -ne $s){$s.Dispose()};if($null -ne $ownedRoot){$ownedRoot.Dispose()}}
}
function Test-WProtectedSnapshot {
    param($Snapshot)
    if($null -eq $Snapshot){return $false}
    return (([string]$Snapshot.AdminCount -eq "1") -or [bool]$Snapshot.Critical)
}
function Assert-WObjectFresh {
    param($Context,$Safety,[switch]$AllowMissing,[switch]$AllowProtected)
    $snap=Get-WObjectSnapshot $Context ([string]$Safety.ExpectedDn)
    if(-not [bool]$snap.Exists){if($AllowMissing){return $snap};throw "Objet AD introuvable ou deplace depuis l ouverture de la fiche : $([string]$Safety.ExpectedDn)"}
    if(-not [string]::IsNullOrWhiteSpace([string]$Safety.ExpectedGuid) -and [string]$snap.Guid -ine [string]$Safety.ExpectedGuid){throw "Conflit de concurrence : objectGUID different. Recharge la fiche."}
    if(-not [string]::IsNullOrWhiteSpace([string]$Safety.ExpectedUsn) -and [string]$snap.Usn -ne [string]$Safety.ExpectedUsn){throw "Conflit de concurrence : uSNChanged a evolue. Un autre outil a modifie l objet. Recharge la fiche."}
    if(-not [string]::IsNullOrWhiteSpace([string]$Safety.ExpectedWhenChanged) -and [string]$snap.WhenChanged -ne [string]$Safety.ExpectedWhenChanged){throw "Conflit de concurrence : whenChanged a evolue. Recharge la fiche avant d ecrire."}
    if([bool]$Context.BlockProtectedObjects -and -not [bool]$Context.AllowProtectedObjectWrites -and -not $AllowProtected -and (Test-WProtectedSnapshot $snap)){throw "Objet protege (adminCount=1 ou isCriticalSystemObject). Ecriture bloquee par la politique Domenia."}
    return $snap
}
function Get-WWriteBackend {
    param($Context,[string[]]$RequiredCommands)
    if([bool]$Context.PreferModule -and (Import-WAdModule $Context)){
        $missing=@($RequiredCommands | Where-Object {$null -eq (Get-Command -Name $_ -ErrorAction SilentlyContinue)})
        if($missing.Count -eq 0){return "Module"}
    }
    return "ADSI"
}
function Get-WAttributeFirst {
    param($Context,[string]$Dn,[string]$Name)
    if ($Name -notmatch '^[A-Za-z][A-Za-z0-9-]{0,126}$') { throw 'Nom d attribut LDAP invalide.' }
    $s=$null;$root=$null
    try {
        $s=New-WSearcher $Context $Dn '(objectClass=*)' @($Name) 'Base' 1;$root=$s.SearchRoot
        $r=$s.FindOne();if($null -eq $r){throw 'Objet non visible pendant la verification.'}
        return Get-WPropFirst $r.Properties $Name $null
    } finally {if($null -ne $s){$s.Dispose()};if($null -ne $root){$root.Dispose()}}
}
function Test-WDirectMembership {
    param($Context,[string]$GroupDn,[string]$ObjectDn)
    if ([string]::IsNullOrWhiteSpace($ObjectDn)) { throw 'Membre vide.' }
    $s=$null;$root=$null
    try {
        # Base search distinguishes an unreadable/missing group from a member not matching.
        $s=New-WSearcher $Context $GroupDn '(objectCategory=group)' @('objectGUID') 'Base' 1
        $root=$s.SearchRoot
        if ($null -eq $s.FindOne()) { throw 'Groupe absent ou non visible ; appartenance non determinee.' }
        $s.Filter='(&(objectCategory=group)(member='+(Escape-WLdap $ObjectDn)+'))'
        return ($null -ne $s.FindOne())
    } finally { if($null -ne $s){$s.Dispose()};if($null -ne $root){$root.Dispose()} }
}
function Get-WChildCount {
    # PF-02, kept on purpose: the delete refusal states the exact number of children, so the one-level collection is
    # counted in full. It is read once, for the single object an operator asked to delete, and released at once.
    param($Context,[string]$Dn)
    $s=$null;$root=$null;$results=$null
    try {
        $s=New-WSearcher $Context $Dn '(objectClass=*)' @('distinguishedName') 'OneLevel' 0
        $root=$s.SearchRoot;$results=$s.FindAll();return $results.Count
    } finally {if($null -ne $results){$results.Dispose()};if($null -ne $s){$s.Dispose()};if($null -ne $root){$root.Dispose()}}
}
function Get-WParentDn {
    param([string]$Dn)
    $escaped=$false
    for($i=0;$i -lt $Dn.Length;$i++){
        $ch=$Dn[$i]
        if($escaped){$escaped=$false;continue}
        if($ch -eq [char]92){$escaped=$true;continue}
        if($ch -eq ','){return $Dn.Substring($i+1)}
    }
    return ""
}
function Test-WRawAttributeAllowed {
    param($Context,[string]$Attribute)
    if(-not [bool]$Context.AllowRawAttributeWrite){throw "Ecriture brute desactivee par Security.AllowRawAttributeWrite."}
    if([bool]$Context.BlockSensitiveRawAttributes){foreach($a in @($Context.RawAttributeBlockList)){if([string]$a -ieq $Attribute){throw "Attribut sensible, modification bloquee : $Attribute"}}}
    return $true
}
function Test-WFormAttribute {
    # SE-02: the text and DN attributes written by the user, computer and group forms. Anything else is a raw write.
    param([string]$Name)
    return (([string]$Name).ToLowerInvariant() -in @('givenname','sn','displayname','userprincipalname','mail','telephonenumber','physicaldeliveryofficename','description','title','department','company','location','manager','managedby'))
}
function Assert-WAttributeChangesAllowed {
    # SE-02: the WriteAttributes worker applies the raw attribute rule itself (same rule as Test-DomeniaRawAttributeAllowed),
    # before anything is read or sent: a change outside the form attributes, or flagged Raw, is a raw write.
    param($Context,[object[]]$Changes)
    foreach($c in @($Changes)){
        if($null -eq $c){continue}
        $name=[string]$c.Name
        if($name -notmatch '^[A-Za-z][A-Za-z0-9-]{0,126}$'){throw 'Nom d attribut LDAP invalide : rien n est envoye.'}
        $raw=$false
        if($null -ne $c.PSObject.Properties['Raw']){$raw=[bool]$c.Raw}
        if($raw -or (-not (Test-WFormAttribute $name))){[void](Test-WRawAttributeAllowed $Context $name)}
    }
}
'@

function Get-DomeniaEntryFirstString {
    param($Entry,[string]$Name)
    $v = Get-DeProp $Entry $Name ""
    if ($null -eq $v) { return "" }
    if ($v -is [datetime]) { return $v.ToUniversalTime().ToString("o") }
    return [string]$v
}

function Get-DomeniaSafetyDescriptor {
    param([switch]$AllowNoSelection)
    if ($null -eq $script:SelectedObject) {
        if ($AllowNoSelection) { return $null }
        throw "Aucun objet AD selectionne."
    }
    if ($null -ne $script:SelectionLoad -and $script:SelectionLoad.Context.DN -ieq $script:SelectedObject.DN -and $script:SelectionLoad.Phase -ne 'Ready') { throw 'Fiche AD non confirmee. Attendez la lecture ou utilisez Reessayer avant de modifier cet objet.' }
    $cachePolicy=Get-DomeniaSelectionCachePolicy
    if(-not $cachePolicy.CanEdit){throw $cachePolicy.Reason}
    $maxAge = [Math]::Max(1,[int](Get-CfgValue "Security" "MaxObjectAgeMinutes" 15))
    if ([bool](Get-CfgValue "Security" "RequireFreshObject" $true)) {
        $age = ((Get-Date) - [datetime]$script:SelectedObject.LoadedAt).TotalMinutes
        if ($age -gt $maxAge) { throw "Fiche trop ancienne ($([int]$age) min). Recharge l objet avant toute ecriture." }
    }
    $entry = $script:SelectedObject.Entry
    [pscustomobject]@{
        ExpectedDn = [string]$script:SelectedObject.DN
        ExpectedGuid = Get-DomeniaEntryFirstString $entry "objectGUID"
        ExpectedUsn = Get-DomeniaEntryFirstString $entry "uSNChanged"
        ExpectedWhenChanged = Get-DomeniaEntryFirstString $entry "whenChanged"
        Type = [string]$script:SelectedObject.Type
        Name = if($script:SelectedObject.PSObject.Properties["Name"]){[string]$script:SelectedObject.Name}else{Get-DomeniaEntryFirstString $entry "name"}
        LoadedAt = ([datetime]$script:SelectedObject.LoadedAt).ToString("o")
    }
}

function Get-DomeniaRowMoveSafety {
    # FI-20: freshness descriptor of a result row moved without its fiche. Assert-WObjectFresh reads the object again by
    # DN on the controller and refuses another objectGUID; no attribute value of the row is relied upon.
    param([Parameter(Mandatory=$true)]$Identity)
    if (($Identity -isnot [Domenia.SelectionIdentity]) -or ([string]::IsNullOrWhiteSpace([string]$Identity.DN))) { throw 'Ligne sans identité exacte (domaine et GUID) : rien nʼest envoyé.' }
    return [pscustomobject]@{
        ExpectedDn = [string]$Identity.DN
        ExpectedGuid = [string]$Identity.Guid
        ExpectedUsn = ''
        ExpectedWhenChanged = ''
        Type = [string]$Identity.Type
        Name = [string]$Identity.Name
        LoadedAt = [datetime]::Now.ToString('o')
    }
}

function Confirm-TextAction {
    param([string]$Message,[string]$Expected,[string]$Title="Confirmation renforcee")
    $form = Show-DomeniaFormDialog `
        -Title $Title `
        -Message "$Message`r`n`r`nSaisis exactement : $Expected" `
        -AcceptText "Confirmer" `
        -Fields @(
            @{ Name="Confirmation"; Label="Texte de confirmation"; Value="" }
        )
    if ($null -eq $form) { return $false }
    return ([string]$form.Confirmation -ceq [string]$Expected)
}

function Get-DomeniaOriginalValue {
    param([string]$Attribute)
    if ($null -eq $script:SelectedObject) { return "" }
    return (Get-DomeniaEntryFirstString $script:SelectedObject.Entry $Attribute)
}

function New-DomeniaAttributeChange {
    param([string]$Name,[AllowEmptyString()][string]$NewValue)
    if ($Name -notmatch '^[A-Za-z][A-Za-z0-9-]{0,126}$') { throw 'Nom d attribut invalide.' }
    $old = [string](Get-DomeniaOriginalValue $Name)
    $new = [string]$NewValue
    if ([string]::Equals($old,$new,[StringComparison]::Ordinal)) { return $null }
    # An empty field is an explicit clear; whitespace alone is not silently converted to deletion.
    return [pscustomobject]@{ Name=$Name; Old=$old; New=$new; Clear=($new.Length -eq 0) }
}

function Complete-DomeniaOpenObjectUi {
    param(
        $Result,
        [Parameter(Mandatory=$true)][string]$CacheKey,
        [Parameter(Mandatory=$true)][string]$Dn,
        [Parameter(Mandatory=$true)][string]$Type,
        [switch]$NoNavigate,[switch]$SuppressRemoteProbes
    )

    $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Properties")
    if ($null -eq $effective) { throw "Resultat de lecture objet vide ou invalide pour $Dn." }
    if ($null -eq $effective.Properties) { throw "Proprietes AD absentes du resultat pour $Dn." }
    if ([string](Get-DomeniaMember $effective 'DataSource' '') -cne 'SQLite') { throw 'Affichage refuse : fiche non relue depuis la base locale.' }
    $effective.Properties = Remove-DomeniaSensitiveProperties -Properties $effective.Properties

    Set-VisitCacheValue -Key $CacheKey -Value $effective -TtlSeconds ([int](Get-CfgValue "Cache" "ObjectTtlSeconds" 45))
    $script:ShowingCachedObject = $false
    Show-AdObjectResult -Result $effective -Dn $Dn -Type $Type -NoNavigate:$NoNavigate -SuppressRemoteProbes:$SuppressRemoteProbes
}

function Fail-DomeniaOpenObjectUi {
    param(
        [AllowNull()][string]$Message,
        [Parameter(Mandatory=$true)][string]$Dn
    )

    $script:ShowingCachedObject = $false
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue." }
    Set-Status "Erreur objet : $detail" "ERROR"
    Write-AppLog "Lecture de l'objet $Dn : $detail" "ERROR"
}

function Complete-DomeniaOpenObjectTaskUi {
    param($Result,$State)
    if ($null -eq $State) { throw 'Etat du callback objet absent.' }
    try {
        $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @('Properties')
        Assert-DomeniaObjectResultIdentity -Result $effective -State $State
        # Even a replaced selection is saved to its captured store. Repaint happens only after readback.
        Submit-DomeniaDirectoryObjectRead -Result $effective -State $State
    }
    catch { Fail-DomeniaOpenObjectTaskUi -Message $_.Exception.Message -State $State }
}

function Fail-DomeniaOpenObjectTaskUi {
    param($Message,$State)
    if($null -ne $State -and $null -ne $State.PSObject.Properties['DirectoryPipe'] -and -not $State.DirectoryPipe.Completed){
        try{$State.DirectoryPipe.Stop.Cancel()}catch{Write-DomeniaSwallowed 'Core' 'Fail-DomeniaOpenObjectTaskUi' $_}
        Complete-DomeniaDirectoryReadPipe -Pipe $State.DirectoryPipe -Error ([string]$Message)
    }
    if ($null -eq $State -or -not (Test-DomeniaObjectCallbackIsCurrent $State)) { return }
    $script:LastObjectOpenError = [string]$Message
    if ($State.SelectionBound -and (Test-DomeniaSelectionLoadCurrent)) { Update-DomeniaSelectionReadUi -Phase Failed -Message ([string]$Message) }
    if(-not [bool]$State.SelectionBound -and $null -ne $script:SelectedObject -and [string]$script:SelectedObject.DN -ieq [string]$State.Dn){
        $cachePolicy=Get-DomeniaSelectionCachePolicy
        foreach($kind in @('Object','Computer')){
            [void](Set-DomeniaControlText ('Lbl'+$kind+'ReadStatus') ('Lecture non confirmee. '+$cachePolicy.Reason))
        }
    }
    Clear-DomeniaCurrentObjectRequest ([string]$State.RequestId)
    Fail-DomeniaOpenObjectUi -Message ([string]$Message) -Dn ([string]$State.Dn)
    # Selection errors stay inside the fiche. No surprise dialog and no automatic retry.
    if ($State.UserInitiated -and -not $State.SelectionBound) {
        [void](Show-DomeniaOperationError -Operation 'Lecture de l objet AD' -ErrorRecordOrException ([string]$Message))
    }
}

function Open-AdObject {
    [CmdletBinding()]
    param([string]$Dn,[string]$Type,[switch]$Force,[switch]$SelectionBound,[switch]$NoNavigate,[switch]$SuppressRemoteProbes,[string]$ObjectGuid='')
    $requestId = ''
    try {
        if ([string]::IsNullOrWhiteSpace($Dn) -or (Test-DomeniaAccessBusyWrite)) { return }
        if (-not (Test-DomeniaDraftNavigation -DN $Dn -Refresh:$Force)) { return }
        if ($SelectionBound -and -not (Test-DomeniaSelectionLoadCurrent)) { return }
        $identity = Get-DomeniaObjectReadIdentity
        $expectedGuid = $ObjectGuid
        if($expectedGuid){$parsedGuid=[guid]::Empty;if(-not [guid]::TryParse($expectedGuid,[ref]$parsedGuid)){throw 'GUID de l objet invalide.'};$expectedGuid=$parsedGuid.ToString('D')}
        $token = ''
        if ($SelectionBound) { $expectedGuid=$script:SelectionLoad.Context.Guid; $token=$script:SelectionLoad.Token }
        $active = $script:CurrentObjectRequestState
        if ($null -ne $active -and $script:CurrentObjectRequestId -and $active.Dn -ieq $Dn -and $active.Identity -ceq $identity -and $active.ExpectedGuid -ieq $expectedGuid) {
            if (-not $NoNavigate) { Select-DomeniaWorkspace -Workspace 'WsObject' }
            return
        }
        if (-not $Force -and -not $ObjectGuid -and $null -ne $script:SelectedObject -and $script:SelectedObject.DN -ieq $Dn -and -not $script:CurrentObjectRequestId) {
            $ready = ($null -eq $script:SelectionLoad -or $script:SelectionLoad.Phase -eq 'Ready')
            if ($ready) { if (-not $NoNavigate) { Select-DomeniaWorkspace -Workspace 'WsObject' }; return }
        }
        $requestId = [guid]::NewGuid().ToString('N')
        $cacheKey = Get-DomeniaObjectCacheKey -DN $Dn -Guid $expectedGuid -Identity $identity
        $state = [pscustomobject]@{
            CacheKey=$cacheKey;Dn=$Dn;Type=$Type;RequestId=$requestId;SelectionBound=[bool]$SelectionBound
            UserInitiated=(-not [bool]$NoNavigate);NoNavigate=[bool]$NoNavigate;SuppressRemoteProbes=[bool]$SuppressRemoteProbes
            ExpectedGuid=$expectedGuid;Epoch=[long]$script:SessionEpoch;Identity=$identity;SelectionToken=$token
            StoreContext=(New-DomeniaStoreContext -RequestId $requestId -Generation ([long]$script:SelectedObjectGeneration) -ScopeDn $Dn -Subtree $false)
        }
        $script:CurrentObjectRequestId = $requestId
        $script:CurrentObjectRequestDn = $Dn
        $script:CurrentObjectRequestState = $state
        $objectPipe=New-DomeniaDirectoryReadPipe -Context $state.StoreContext -CommitHandler 'Complete-DomeniaDirectoryObjectCommit' -ErrorHandler 'Fail-DomeniaDirectoryObjectCommit' -CallbackState $state
        $state|Add-Member NoteProperty DirectoryPipe $objectPipe
        if ($SelectionBound) { Update-DomeniaSelectionReadUi -Phase Loading }
        $cacheItem = $null
        if (-not $Force) {
            try { if ($script:VisitCache.ContainsKey($cacheKey)) { $cacheItem = $script:VisitCache[$cacheKey] } } catch { $cacheItem = $null }
        }
        $cached = if (-not $Force) { Get-VisitCacheValue $cacheKey } else { $null }
        if ($null -ne $cached) {
            $cacheCreated = $null
            if ($null -ne $cacheItem) { $cacheCreated = $cacheItem.Created }
            $effective = Get-DomeniaEffectiveWorkerResult -Result $cached -RequiredProperties @('Properties')
            if ($null -ne $effective) {
                try { Assert-DomeniaObjectResultIdentity -Result $effective -State $state }
                catch {
                    Write-AppLog ('Projection locale ignoree, relecture AD maintenue : '+$_.Exception.Message) 'WARN'
                    $effective=$null
                }
                if ($null -ne $effective -and [string](Get-DomeniaMember $effective 'DataSource' '') -ceq 'SQLite' -and (Test-DomeniaObjectCallbackIsCurrent $state)) {
                    $script:ShowingCachedObject = $true
                    $script:ShowingCachedObjectCreated = $cacheCreated
                    try { Show-AdObjectResult -Result $effective -Dn $Dn -Type $Type -NoNavigate:$NoNavigate -SuppressRemoteProbes }
                    finally { $script:ShowingCachedObject = $false; $script:ShowingCachedObjectCreated = $null }
                    if ($SelectionBound) { Update-DomeniaSelectionReadUi -Phase Cached }
                }
            }
        }
        $code = @'
$Payload.DirectoryReadState.Started=$true
$de=$null
try {
$de = New-WEntry $Context ([string]$Payload.DN)
$props = Get-WAllProperties -Entry $de -PropertyNames @($Payload.Properties)
$final=[pscustomobject]@{Properties=$props;DN=[string]$Payload.DN;Type=[string]$Payload.Type;Live=$true;ObservedUtc=[datetime]::UtcNow.ToString('o');Source=[string]$Context.Server}
$Payload.Progress.Enqueue([pscustomobject]@{Properties=$props;Type=[string]$Payload.Type;ObservedUtc=$final.ObservedUtc;Source=$final.Source})
$Payload.DirectoryReadState.Final=$final
$final
}catch{$Payload.DirectoryReadState.Error=$_.Exception.Message;throw}finally{if($null -ne $de){$de.Dispose()};$Payload.DirectoryReadState.Done=$true}
'@
        Start-UiTask -Name "Lecture objet $Type" -OperationId 'OpenAdObject' -Code $code -Payload ([pscustomobject]@{DN=$Dn;Type=$Type;Properties=@(Get-DomeniaSafeObjectPropertyNames);Progress=$objectPipe.Input;DirectoryReadState=$objectPipe.Collector;StopToken=$objectPipe.Stop.Token}) -CallbackState $state -ReplaceKey 'object' -DisableControls @() -TimeoutSeconds ([int](Get-CfgValue 'Async' 'ObjectTimeoutSeconds' 35)) -StatusText "Lecture de $Type en arriere-plan..." -SuccessHandler 'Complete-DomeniaOpenObjectTaskUi' -ErrorHandler 'Fail-DomeniaOpenObjectTaskUi' | Out-Null
    }
    catch {
        $script:ShowingCachedObject = $false
        $script:LastObjectOpenError = [string]$_.Exception.Message
        if ($SelectionBound -and (Test-DomeniaSelectionLoadCurrent)) { Update-DomeniaSelectionReadUi -Phase Failed -Message $script:LastObjectOpenError }
        if ($requestId) { Clear-DomeniaCurrentObjectRequest $requestId }
        Set-Status ('Erreur de lecture AD : '+$script:LastObjectOpenError) 'ERROR'
        Write-AppLog ('Lecture de '+$Dn+' : '+$script:LastObjectOpenError) 'ERROR'
    }
}

function Show-AdObjectResult {
    param($Result,[string]$Dn,[string]$Type,[switch]$NoNavigate,[switch]$SuppressRemoteProbes)
    if ($null -eq $Result) { throw "Resultat objet absent pour $Dn." }
    if ($null -eq $Result.PSObject.Properties["Properties"] -or $null -eq $Result.Properties) { throw "Table des proprietes AD absente pour $Dn." }
    if ([string](Get-DomeniaMember $Result 'DataSource' '') -cne 'SQLite') { throw 'Affichage refuse : fiche non relue depuis la base locale.' }
    if ([string]::IsNullOrWhiteSpace($Type)) {
        try { $Type = [string]$Result.Type } catch { Write-DomeniaSwallowed 'Core' 'Show-AdObjectResult' $_ }
    }
    if ([string]::IsNullOrWhiteSpace($Type)) { $Type = "Objet" }

    if(Keep-DomeniaDraftOnResult -Result $Result -DN $Dn -Type $Type){return}
    Clear-ObjectDetails
    $isLiveRead = $false
    try { if ($null -ne $Result.PSObject.Properties["Live"]) { $isLiveRead = [bool]$Result.Live } } catch { Write-DomeniaSwallowed 'Core' 'Show-AdObjectResult' $_ }
    if (-not [bool]$script:ShowingCachedObject -and $isLiveRead) {
        # Une relecture reelle permet de retenter apres correction des ACL.
        $script:ActualSecretDeniedDn = ""
        Clear-DomeniaActualCapabilityDenials -Dn $Dn
    }
    $safeProperties = Remove-DomeniaSensitiveProperties -Properties $Result.Properties
    $entry = [pscustomobject]@{ Properties = $safeProperties }
    $name = Get-DomeniaEntryFirstString $entry "name"
    $attributesObservedUtc = ConvertTo-DomeniaUtcDate (Get-DomeniaMember $Result 'ObservedUtc' '')
    if($null -eq $attributesObservedUtc){throw 'Date de lecture AD absente du resultat enregistre.'}
    $loadedAt = $attributesObservedUtc.ToLocalTime()
    $isLiveRead = -not [bool]$script:ShowingCachedObject
    $script:SelectedObject = [pscustomobject]@{
        DN=$Dn; Type=$Type; Name=$name; Entry=$entry; LoadedAt=$loadedAt; Guid=(Get-DomeniaEntryFirstString $entry 'objectGUID')
        Safety=[pscustomobject]@{
            Guid=Get-DomeniaEntryFirstString $entry "objectGUID"
            Usn=Get-DomeniaEntryFirstString $entry "uSNChanged"
            WhenChanged=Get-DomeniaEntryFirstString $entry "whenChanged"
            AdminCount=Get-DomeniaEntryFirstString $entry "adminCount"
            Critical=([string](Get-DomeniaEntryFirstString $entry "isCriticalSystemObject") -match "(?i)true|1")
        }
    }
    $script:SelectedObjectGeneration = [int64]$script:SelectedObjectGeneration + 1
    [void](Set-DomeniaObservationTime $script:SelectedObject 'Attributes' $attributesObservedUtc -Succeeded:$isLiveRead)
    $freshnessTable = $null
    try { $freshnessTable = Get-DomeniaActiveFreshnessTable } catch { $freshnessTable = $null }
    $attributesFreshness = Get-DomeniaRecordFreshness $script:SelectedObject 'Attributes' -Table $freshnessTable
    $script:SelectedObject | Add-Member -NotePropertyName AttributesFreshness -NotePropertyValue $attributesFreshness -Force
    Set-DomeniaRelationsSelection -Object $script:SelectedObject
    # Rendering is read-only: the producer has already committed every attribute to SQLite.
    Stop-DomeniaSecretReadTasks
    foreach ($taskId in @($script:AsyncJobs.Keys)) {
        $boundJob = $script:AsyncJobs[$taskId]
        if ($null -ne $boundJob -and [string]$boundJob.ReplaceKey -in @("computerdiag","permissions")) {
            try { Request-UiTaskStop -Id ([string]$taskId) -Silent -Force -Superseded } catch { Write-DomeniaSwallowed 'Core' 'Show-AdObjectResult' $_ }
        }
    }
    $script:CurrentCapabilities = @{}
    $oldProbeGuard=[bool]$script:RenderingObjectWithoutProbes
    $script:RenderingObjectWithoutProbes=([bool]$SuppressRemoteProbes -or [bool]$script:ShowingCachedObject)
    try {
    Fill-GenericObject $entry $Type
    switch ($Type) {
        "Utilisateur" { Fill-UserObject $entry }
        "Machine" { Fill-ComputerObject $entry }
        "Groupe" { Fill-GroupObject $entry }
        "OU" { Fill-ContainerObject $entry }
        "Conteneur" { Fill-ContainerObject $entry }
    }

    } finally { $script:RenderingObjectWithoutProbes=$oldProbeGuard }

    # Le contexte d'association est recalcule pour l'objet qui vient
    # reellement d'etre charge. Une grille vide reste vide.
    Refresh-AssociationContext -SkipResultRefresh
    $script:SelectionResetDn = $Dn

    $script:LastLoadedEntry = $entry
    try { Set-DomeniaSupportObjectSource -Dn $Dn -IsLive:($isLiveRead -and -not [bool]$script:ShowingCachedObject) } catch { Write-DomeniaSwallowed 'Core' 'Show-AdObjectResult' $_ }
    Reset-DomeniaDeferredViews -Dn $Dn
    Clear-Secrets
    Set-VisibleTabsForType -Type $Type -PreserveWorkspace:$NoNavigate
    Apply-CurrentPermissionUi
    if (-not $script:ShowingCachedObject) { Set-Status $(if([bool](Get-DomeniaMember $Result 'Demo' $false)){"$Type fictif relu dans la base de demonstration."}else{"$Type charge depuis la base locale après lecture AD."}) }

    # Les attributs bruts et les droits ne sont calcules que si leur onglet
    # est deja devant les yeux de l operateur.
    try {
        $tabs = Get-DomeniaControl -Name "DetailTabs"
        $selected = ""
        if ($null -ne $tabs -and $null -ne $tabs.SelectedItem) { $selected = [string]$tabs.SelectedItem.Name }
        if (-not $NoNavigate -and $selected -eq "TabRaw") { Ensure-DomeniaRawAttributes }
        elseif (-not $NoNavigate -and $selected -eq "TabPermissions" -and [bool](Get-CfgValue "Security" "EvaluateRightsOnObjectOpen" $true)) { Ensure-DomeniaPermissions }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Show-AdObjectResult' $_ }
    Update-Dashboard
    if (-not $NoNavigate) {
        $script:SelectionLoad=$null
        foreach ($kind in @('Object','Computer')) {
            $contentHost=Get-DomeniaControl ($kind+'ReadContent');$empty=Get-DomeniaControl ($kind+'ReadPlaceholder')
            if($null -ne $contentHost){$contentHost.Visibility='Visible';$contentHost.IsEnabled=(-not [bool]$script:ShowingCachedObject)}
            if($null -ne $empty){$empty.Visibility='Collapsed'}
            [void](Set-DomeniaControlText ('Lbl'+$kind+'ReadStatus') ($Type+' : '+$name+' | '+$(if($script:ShowingCachedObject){'Cache, verification AD en cours.'}else{'Fiche AD chargee.'})))
        }
    }
    Save-DomeniaDraftBaseline -DN $Dn

}

function Get-WriteControlMap {
    [ordered]@{
        Edit = @("BtnUserSave","BtnUserEdit","BtnUserSaveContact","BtnCompSave","BtnCompEdit","BtnGroupSave")
        Raw = @("BtnRawSet","BtnRawClear")
        Account = @("BtnUserUnlock","BtnUserSupportUnlock","BtnUserEnable","BtnUserDisable","BtnCompEnable","BtnCompDisable","BtnApplyAccountOptions","BtnSetExpiration","BtnNeverExpires","BtnExpirePwdNow")
        Password = @("BtnUserResetPwd","BtnUserGenPassword")
        Group = @("BtnUserAddGroup","BtnUserRemoveGroup","BtnCompAddGroup","BtnCompRemoveGroup","BtnGroupAddMember","BtnGroupRemoveMember")
        Move = @("BtnUserMove","BtnCompRename","BtnCompMove")
        Delete = @("BtnObjectMore")
        Create = @("BtnCreateOu")
    }
}

function Test-DomeniaControlIsBusy {
    param([string]$Name)
    try {
        return ($script:ControlBusyRef.ContainsKey($Name) -and [int]$script:ControlBusyRef[$Name] -gt 0)
    }
    catch { return $false }
}

function Update-DomeniaSecretActionUi {
    <#
        BitLocker et LAPS sont des lectures AD sensibles, mais ce ne sont pas
        des ecritures. Elles doivent donc rester disponibles en mode lecture
        seule des qu'une machine est reellement selectionnee. Le DC et la
        cmdlet LAPS restent les autorites finales : l'estimation ACL locale ne
        bloque jamais preventivement une tentative de lecture.
        D056 : chaque bouton grise porte un motif (Get-DomeniaCapabilityExplanation)
        et une route sure vers le prerequis (BtnSecretsPrerequisite, dans la page).
    #>
    try {
        $machineDn = ""
        try { if ($null -ne $script:SelectedObject -and [string]$script:SelectedObject.Type -eq "Machine") { $machineDn = [string]$script:SelectedObject.DN } } catch { $machineDn = "" }
        $prerequisiteRoute = ""
        $prerequisiteReason = ""
        foreach ($name in @("BtnLoadBitLocker","BtnLoadLaps")) {
            $control = Get-DomeniaControl -Name $name
            if ($null -eq $control) { continue }
            $busy = Test-DomeniaControlIsBusy -Name $name
            $mode=if($name -eq 'BtnLoadLaps'){'LAPS'}else{'BitLocker'}
            # Per-resource refusal: a LAPS refusal never disables BitLocker, and the reverse.
            $actualDenied=Test-DomeniaSecretDenied -Mode $mode -DN $machineDn
            $explanation = Get-DomeniaSecretButtonExplanation -Name $name -Busy $busy
            $control.IsEnabled = [bool]$explanation.Enabled
            $tip = [string]$explanation.ToolTip
            if (($actualDenied) -and ($tip -notmatch 'autre compte')) { $tip += ' Lecture refusée avec ce compte : cliquez pour proposer un autre compte.' }
            $control.ToolTip = $tip
            try { [Windows.Automation.AutomationProperties]::SetHelpText($control,$tip) } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSecretActionUi' $_ }
            if (-not [bool]$explanation.Enabled -and [string]$explanation.Route -and -not $prerequisiteRoute) { $prerequisiteRoute = [string]$explanation.Route; $prerequisiteReason = $tip }
        }
        Update-DomeniaSecretsPrerequisite -Route $prerequisiteRoute -Reason $prerequisiteReason

        $rows = @($script:SecretRows)
        $hasRows = ($rows.Count -gt 0)
        $hasReadableValue = (@($rows | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.Value) }).Count -gt 0)
        $single = Test-DomeniaSecretSingleExposure
        $selectedSecret = $null
        try { $selectedSecret = Get-DomeniaSelectedSecretSource } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSecretActionUi' $_ }
        $selectedMetadata = ($null -ne $selectedSecret -and [bool](Get-DomeniaMember $selectedSecret 'Metadata' $false) -and [string]::IsNullOrWhiteSpace([string]$selectedSecret.Value))
        $canCopySelected = ($null -ne $selectedSecret -and (-not [string]::IsNullOrWhiteSpace([string]$selectedSecret.Value) -or $selectedMetadata))
        $exposure = Get-DomeniaSecretExposurePolicy

        # UI-31: the label of the reveal button and the presence of "copy all" come from one rule only.
        $selectedKind = ""
        try { if ($null -ne $selectedSecret) { $selectedKind = [string]$selectedSecret.Kind } } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSecretActionUi' $_ }
        $view = Get-DomeniaSecretActionView -Single $single -Visible ([bool]$script:SecretsVisible) -HasRows $hasRows -HasReadableValue $hasReadableValue -CanUseSelected $canCopySelected -SelectedMetadata $selectedMetadata -RevealSeconds ([int]$exposure.RevealSeconds) -SelectedKind $selectedKind -ClipboardLimit ([string]$exposure.ClipboardLimit)
        $toggle = Get-DomeniaControl -Name "BtnToggleSecrets"
        if ($null -ne $toggle) {
            $toggle.Content = [string]$view.ToggleText
            $toggle.IsEnabled = [bool]$view.ToggleEnabled
            $toggle.ToolTip = [string]$view.ToggleToolTip
            try { [Windows.Automation.AutomationProperties]::SetName($toggle,[string]$view.ToggleText); [Windows.Automation.AutomationProperties]::SetHelpText($toggle,[string]$view.ToggleToolTip) } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSecretActionUi' $_ }
        }

        $copyAll = Get-DomeniaControl -Name "BtnCopyAllSecrets"
        if ($null -ne $copyAll) {
            $copyAll.Visibility = if ([bool]$view.CopyAllVisible) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
            $copyAll.IsEnabled = [bool]$view.CopyAllEnabled
            $copyAll.ToolTip = [string]$view.CopyAllToolTip
            try { [Windows.Automation.AutomationProperties]::SetHelpText($copyAll,[string]$view.CopyAllToolTip) } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSecretActionUi' $_ }
        }

        $clear = Get-DomeniaControl -Name "BtnClearSecrets"
        if ($null -ne $clear) {
            $clear.IsEnabled = $hasRows
            $clear.ToolTip = if ($hasRows) { "Efface immédiatement les secrets conservés en mémoire par Domenia." } else { "Aucun secret nʼest conservé en mémoire." }
        }

        $copySelected = Get-DomeniaControl -Name "BtnCopySecret"
        if ($null -ne $copySelected) {
            $copySelected.IsEnabled = [bool]$view.CopyEnabled
            $copySelected.Content = [string]$view.CopyText
            $copySelected.ToolTip = [string]$view.CopyToolTip
        }

        $recoveryBox = Get-DomeniaControl -Name "TxtBitLockerRecoveryId"
        if ($null -ne $recoveryBox) { $recoveryBox.IsEnabled = (@($script:BitLockerKeyList).Count -gt 0) }
    }
    catch {
        try { Write-AppLog "Etat des actions LAPS/BitLocker : $($_.Exception.Message)" "WARN" } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaSecretActionUi' $_ }
    }
}

function Assert-DomeniaReadWriteControlClassification {
    $writeNames = @(Get-AllWriteControlNames)
    foreach ($readName in @("BtnLoadBitLocker","BtnLoadLaps")) {
        if ($writeNames -contains $readName) {
            throw "$readName est une action de lecture et ne doit jamais etre classee comme controle d'ecriture."
        }
    }
}

function Update-DomeniaWriteModeVisual {
    $writeEnabled = -not [bool]$script:ReadOnlyMode
    try {
        $visibility = if ($writeEnabled) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed }
        # DS-02 (L08): solid 3-unit frame and « Repasser en lecture » in the fixed state slot, theme colours only.
        foreach ($name in @("WriteModeHalo","WriteModeBanner")) {
            if ($script:Ctrl.ContainsKey($name)) { $script:Ctrl[$name].Visibility = $visibility }
        }
        if ($script:Ctrl.ContainsKey("LblWriteMode")) { $script:Ctrl["LblWriteMode"].Text = "Repasser en lecture" }
        # SE-06 / UI-01: switch label with its countdown, and the window title with the page and its subject.
        $uxReady = ($null -ne (Get-Command -Name Update-DomeniaReadOnlySwitch -CommandType Function -ErrorAction SilentlyContinue))
        if ($uxReady) { Update-DomeniaReadOnlySwitch; Update-DomeniaUxPageTitle }
        elseif ($null -ne $script:Window) {
            $script:Window.Title = if ($writeEnabled) { "$($script:BaseWindowTitle)  [ÉCRITURE AD ACTIVE]" } else { $script:BaseWindowTitle }
        }
        if ($script:Ctrl.ContainsKey("LblPrivilegeTop")) {
            $script:Ctrl["LblPrivilegeTop"].SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty,$(if ($writeEnabled) { "DangerColor" } else { "PrivilegeFg" }))
            $script:Ctrl["LblPrivilegeTop"].FontWeight = if ($writeEnabled) { [System.Windows.FontWeights]::Bold } else { [System.Windows.FontWeights]::Normal }
        }
    } catch { Write-AppLog "Indicateur mode ecriture : $($_.Exception.Message)" "WARN" }
}

function Get-DomeniaCapabilityDenialKey {
    param([string]$Dn,[string]$Capability)
    return (([string]$Dn).Trim().ToLowerInvariant() + "|" + ([string]$Capability).Trim().ToLowerInvariant())
}

function Set-DomeniaActualCapabilityDenied {
    param([string]$Dn,[string]$Capability,[string]$Reason="Refus reel d'Active Directory")
    if ([string]::IsNullOrWhiteSpace($Dn) -or [string]::IsNullOrWhiteSpace($Capability)) { return }
    $key = Get-DomeniaCapabilityDenialKey -Dn $Dn -Capability $Capability
    $script:ActualDeniedCapabilities[$key] = [pscustomobject]@{
        Dn=$Dn; Capability=$Capability; Reason=$Reason; DetectedAt=Get-Date; Identity=[string]$script:Conn.BindUser
    }
}

function Test-DomeniaActualCapabilityDenied {
    param([string]$Dn,[string]$Capability)
    if ([string]::IsNullOrWhiteSpace($Dn) -or [string]::IsNullOrWhiteSpace($Capability)) { return $false }
    return $script:ActualDeniedCapabilities.ContainsKey((Get-DomeniaCapabilityDenialKey -Dn $Dn -Capability $Capability))
}

function Clear-DomeniaActualCapabilityDenials {
    param([string]$Dn)
    if ([string]::IsNullOrWhiteSpace($Dn)) { return }
    $prefix = ([string]$Dn).Trim().ToLowerInvariant() + "|"
    foreach ($key in @($script:ActualDeniedCapabilities.Keys)) {
        if (([string]$key).StartsWith($prefix,[System.StringComparison]::OrdinalIgnoreCase)) { [void]$script:ActualDeniedCapabilities.Remove($key) }
    }
}

function Apply-CurrentPermissionUi {
    param([switch]$StartupFastPath)
    $map = Get-WriteControlMap
    $cachePolicy=Get-DomeniaSelectionCachePolicy
    # P-CD-09: the guards fail closed (Safety.Model): an unreadable read-only switch counts as read-only, unreadable
    # protection markers as a protected object, an unreadable DN blocks the writes on it.
    $readOnlyState = Get-DomeniaReadOnlyState -Controls $script:Ctrl -Fallback ([bool]$script:ReadOnlyMode)
    if ([bool]$readOnlyState.Unreadable) { Write-DomeniaSwallowed 'Core' 'Apply-CurrentPermissionUi' $readOnlyState.Error }
    $readOnly = [bool]$readOnlyState.ReadOnly
    $script:ReadOnlyMode = $readOnly
    $subject = Get-DomeniaWriteGuardSubject -Selected $script:SelectedObject
    foreach ($fault in @($subject.Errors)) { Write-DomeniaSwallowed 'Core' 'Apply-CurrentPermissionUi' $fault }
    $protected = [bool]$subject.Protected
    $blockProtected = $protected -and [bool](Get-CfgValue "Security" "BlockProtectedObjects" $true) -and -not [bool](Get-CfgValue "Security" "AllowProtectedObjectWrites" $false)
    $blockEstimatedDenied = [bool](Get-CfgValue "Security" "BlockOnAclEstimate" $false)
    $disableIndeterminate = [bool](Get-CfgValue "Security" "DisableIndeterminateControls" $false)
    $writeActive = (-not [string]::IsNullOrWhiteSpace($script:ActiveWriteTaskId)) -or ($script:WriteState -in @("Unknown","UnknownPending"))
    $currentDn = [string]$subject.Dn
    foreach ($cap in $map.Keys) {
        $lookup = if($cap -eq "Raw"){"Edit"}else{$cap}
        $state = "Indetermine"
        if ($script:CurrentCapabilities.ContainsKey($lookup)) { $state = [string]$script:CurrentCapabilities[$lookup] }
        foreach ($name in @($map[$cap])) {
            if (-not $script:Ctrl.ContainsKey($name)) { continue }
            $busy = $false
            if ($script:ControlBusyRef.ContainsKey($name)) { $busy = ([int]$script:ControlBusyRef[$name] -gt 0) }
            $actualDenied = Test-DomeniaActualCapabilityDenied -Dn $currentDn -Capability $lookup
            $denied = [bool]$subject.DnUnreadable -or $actualDenied -or ($blockEstimatedDenied -and $state -eq "Refuse") -or ($disableIndeterminate -and $state -eq "Indetermine")
            $rawBlocked = ($cap -eq "Raw" -and -not [bool](Get-CfgValue "Security" "AllowRawAttributeWrite" $false))
            $dangerProtected = $blockProtected -and ($cap -in @("Edit","Raw","Account","Password","Group","Move","Delete"))
            $enabled = -not ($readOnly -or $denied -or $busy -or $writeActive -or $rawBlocked -or $dangerProtected -or -not $cachePolicy.CanEdit)
            $script:Ctrl[$name].IsEnabled = $enabled
            Restore-DomeniaUxBaseToolTip -Name $name
            if ([bool]$readOnlyState.Unreadable) { $script:Ctrl[$name].ToolTip = "Désactivé : lʼétat du mode lecture seule nʼa pas pu être lu ; aucune écriture tant quʼil nʼest pas relu." }
            elseif ($readOnly) { $script:Ctrl[$name].ToolTip = "Desactive : mode lecture seule actif." }
            elseif ($writeActive) { $script:Ctrl[$name].ToolTip = "Desactive : une ecriture AD est deja en cours de verification." }
            elseif (-not $cachePolicy.CanEdit) { $script:Ctrl[$name].ToolTip=(Get-DomeniaDisabledHelp -Action 'Modifier cet objet' -Reason $(if($cachePolicy.Offline){'Offline'}else{'Stale'})).ToolTip }
            elseif ($dangerProtected -and [bool]$subject.ProtectionUnreadable) { $script:Ctrl[$name].ToolTip = "Désactivé : la protection de lʼobjet (adminCount, isCriticalSystemObject) nʼa pas pu être lue. Rechargez lʼobjet." }
            elseif ($dangerProtected) { $script:Ctrl[$name].ToolTip = "Desactive : objet protege adminCount/isCriticalSystemObject." }
            elseif ($rawBlocked) { $script:Ctrl[$name].ToolTip = "Ecriture brute desactivee dans la configuration de securite." }
            elseif ([bool]$subject.DnUnreadable) { $script:Ctrl[$name].ToolTip = "Désactivé : lʼobjet sélectionné nʼa pas pu être relu (nom distinctif illisible). Rechargez-le avant toute modification." }
            elseif ($actualDenied) { $script:Ctrl[$name].ToolTip = "Desactive apres un refus d'acces reel du controleur de domaine pour l'identite connectee. Recharge l'objet apres correction des droits." }
            elseif ($denied) { $script:Ctrl[$name].ToolTip = "Desactive par la politique locale a partir de l'estimation ACL." }
            elseif ($state -eq "Refuse") { $script:Ctrl[$name].ToolTip = "Estimation ACL defavorable, non bloquante par defaut. Le preflight et le controleur de domaine restent l'autorite finale." }
            elseif ($state -eq "Indetermine") { $script:Ctrl[$name].ToolTip = "Droit indéterminé localement : le DC vérifiera à lʼexécution et le preflight reste obligatoire." }
        }
    }
    foreach ($name in @("BtnCompGpUpdate","BtnCompRestart","BtnCompRimotte")) {
        if (-not $script:Ctrl.ContainsKey($name)) { continue }
        $busy = ($script:ControlBusyRef.ContainsKey($name) -and [int]$script:ControlBusyRef[$name] -gt 0)
        $script:Ctrl[$name].IsEnabled = (-not $readOnly -and -not $busy -and -not $writeActive -and -not $cachePolicy.Offline)
        Restore-DomeniaUxBaseToolTip -Name $name
        if ([bool]$readOnlyState.Unreadable) { $script:Ctrl[$name].ToolTip = "Désactivé : lʼétat du mode lecture seule nʼa pas pu être lu ; aucune action distante tant quʼil nʼest pas relu." }
        elseif ($readOnly) { $script:Ctrl[$name].ToolTip = "Desactive : cette action modifie le poste distant et le mode lecture seule est actif." }
        elseif ($cachePolicy.Offline) { $script:Ctrl[$name].ToolTip=(Get-DomeniaDisabledHelp -Action 'Modifier le poste distant' -Reason Offline).ToolTip }
        elseif ($busy) { $script:Ctrl[$name].ToolTip = "Action distante en cours." }
        elseif ($writeActive) { $script:Ctrl[$name].ToolTip = "Desactive pendant la verification d'une ecriture AD." }
    }
    # X04: the restart, run and service panels of Assistance poste follow the same switch.
    try { Update-DomeniaComputerAssistPermissions } catch { Write-DomeniaSwallowed 'Core' 'Apply-CurrentPermissionUi' $_ }
    try {
        $label = if ($readOnly) { "Mode lecture seule" } elseif ($blockProtected) { "Objet protege : ecritures bloquees" } elseif ($writeActive) { "Ecriture AD en cours" } elseif ($script:CurrentCapabilities.Count -eq 0) { "Estimation ACL : analyse en attente" } else {
            $ok = @($script:CurrentCapabilities.Values | Where-Object { $_ -eq "Autorise" }).Count
            $no = @($script:CurrentCapabilities.Values | Where-Object { $_ -eq "Refuse" }).Count
            "Estimation ACL : $ok favorable(s), $no defavorable(s)"
        }
        $script:Ctrl["LblPrivilegeTop"].Text = $label
    } catch { Write-DomeniaSwallowed 'Core' 'Apply-CurrentPermissionUi' $_ }
    Update-DomeniaWriteModeVisual
    # SP-04 (L08): « AD injoignable depuis HH:MM » while the directory does not answer, back by itself at the next success.
    if ($null -ne (Get-Command -Name Update-DomeniaUxSessionBadge -CommandType Function -ErrorAction SilentlyContinue)) { try { Update-DomeniaUxSessionBadge } catch { Write-DomeniaSwallowed 'Core' 'Apply-CurrentPermissionUi' $_ } }
    Update-DomeniaSecretActionUi
    # Pendant le bootstrap, ne pas refaire tout le tableau de bord ni parcourir
    # les politiques GUI : ces operations sont purement visuelles et doivent
    # attendre que la fenetre principale soit reellement peinte.
    if (-not $StartupFastPath) {
        Update-Dashboard
        Apply-DomeniaGuiElementPolicy
    }
}

function Initialize-DomeniaPresentation {
    # Apparence et identite visuelle : appele une seule fois au demarrage.
    # Auparavant execute depuis Apply-CurrentPermissionUi, donc a chaque
    # selection de ligne : deux lectures et deux ecritures disque, un decodage
    # d icone et plusieurs lignes de journal parasites par clic.
    if ($script:PresentationInitialized) { return }
    $script:PresentationInitialized = $true

    try { [void](Load-DomeniaSettings) } catch { Write-AppLog ("Préférences non chargées, valeurs par défaut pour cette session : " + $_.Exception.Message) "WARN" }
    # Non-blocking startup (FI-19): the page shows that the figures are being read; the LocalIndexRead worker reads
    # them once the window is painted (ContentRendered). The park and the detailed AD rows are loaded on demand.
    try { Update-DomeniaIndexStats } catch { Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaPresentation' $_ }
    try { Restore-DomeniaUiSettings } catch { Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaPresentation' $_ }
    try { Register-DomeniaSettingsWatchers } catch { Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaPresentation' $_ }
    try { Restore-DomeniaWindowGeometry } catch { Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaPresentation' $_ }

    try {
        Load-DomeniaUiProfile | Out-Null
        Apply-DomeniaUiProfile -Profile $script:CurrentUiProfile
    }
    catch { try { Write-AppLog "Profil d'interface : $($_.Exception.Message)" "WARN" } catch { Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaPresentation' $_ } }

    try {
        Load-DomeniaTheme | Out-Null
        Apply-DomeniaTheme -Theme $script:CurrentTheme
    }
    catch { try { Write-AppLog "Theme : $($_.Exception.Message)" "WARN" } catch { Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaPresentation' $_ } }

    try { Enable-DomeniaUxHints } catch { try { Write-AppLog "UX hints : $($_.Exception.Message)" "WARN" } catch { Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaPresentation' $_ } }

    try {
        $domeniaIconPath = Ensure-DomeniaIcon
        if ($null -ne $domeniaIconPath) {
            $bitmap = New-Object System.Windows.Media.Imaging.BitmapImage
            $bitmap.BeginInit()
            $bitmap.UriSource = New-Object System.Uri($domeniaIconPath)
            $bitmap.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
            $bitmap.EndInit()
            $bitmap.Freeze()
            if ($null -ne $script:Window) { $script:Window.Icon = $bitmap }
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaPresentation' $_ }

    # Le lancement ramene toujours sur l Accueil. Reprendre le dernier
    # espace visite depose l operateur sur un ecran sans rapport avec ce
    # qu il vient d ouvrir, et sans objet selectionne.
    try { Initialize-DomeniaAccess; Initialize-DomeniaContinuity } catch { Write-AppLog ('Initialisation assistance : '+$_.Exception.Message) 'ERROR' }
    try { Select-DomeniaWorkspace -Workspace "TabDashboard" } catch { Write-DomeniaSwallowed 'Core' 'Initialize-DomeniaPresentation' $_ }

    $sessionButton=Get-DomeniaControl 'BtnSessionsRead';if($null -ne $sessionButton){$sessionButton.Add_Click({Start-DomeniaSessionsRead})}
    # UX-39 : la grille des sessions se parcourt au double-clic et au clic droit, comme celle des associations.
    $sessionGrid=Get-DomeniaControl 'DgSessions';if($null -ne $sessionGrid){$sessionGrid.ContextMenu=New-DomeniaSessionsContextMenu;$sessionGrid.Add_MouseDoubleClick({param($sender,$e) Open-DomeniaSessionFiche -Source $e.OriginalSource});$sessionGrid.Add_PreviewMouseRightButtonDown({param($sender,$e) $hit=Get-DomeniaGridHit $e.OriginalSource;if($null -ne $hit -and $null -ne $hit.Row){$sender.SelectedItem=$hit.Row.Item}})}
    Initialize-DomeniaGuard
    Initialize-DomeniaAssist
    # X03 (UX-15, UI-27): « Compte poste » pill, its side panel and the « En ce moment » section of Comptes.
    try { Initialize-DomeniaAccountsUi } catch { Write-AppLog ('Initialisation des comptes : '+$_.Exception.Message) 'WARN' }
    Initialize-DomeniaLive
    Initialize-DomeniaReconcile
    try { Initialize-DomeniaSupportUi } catch { Stop-DomeniaSupportUi; Write-AppLog ('Initialisation du diagnostic : '+$_.Exception.Message) 'ERROR' }
    # Points 22, 24 and 30: census, disappeared objects and snapshots, as a tab of the autonomous base page.
    try { Initialize-DomeniaDirectorySyncUi } catch { Write-AppLog ('Onglet Contrôles de la base indisponible : ' + $_.Exception.Message) 'ERROR' }
    Add-DomeniaUiLog -Area "Application" -Text "Domenia 1.0 pret."
}

function Assert-DomeniaCapability {
    param([string]$Capability)
    Assert-WriteAllowed
    if (-not [string]::IsNullOrWhiteSpace($script:ActiveWriteTaskId)) { throw "Une ecriture est deja en cours. Les ecritures sont traitees une par une." }
    if ($script:WriteState -in @("Unknown","UnknownPending")) { throw "Une ecriture precedente est dans un etat inconnu. Ouvrez Operations et verifiez le recu concerne avant toute nouvelle ecriture." }
    if((Get-DomeniaSelectionCachePolicy).Offline){throw 'Hors ligne : relisez Active Directory avant toute modification.'}
    # P-CD-09: an object whose DN cannot be read leaves no recorded refusal to check: the write is blocked.
    $subject = Get-DomeniaWriteGuardSubject -Selected $script:SelectedObject
    if ([bool]$subject.DnUnreadable) {
        foreach ($fault in @($subject.Errors)) { Write-DomeniaSwallowed 'Core' 'Assert-DomeniaCapability' $fault }
        throw "Action bloquée : lʼobjet sélectionné nʼa pas pu être relu (nom distinctif illisible). Rechargez-le avant toute modification."
    }
    $currentDn = [string]$subject.Dn
    if (Test-DomeniaActualCapabilityDenied -Dn $currentDn -Capability $Capability) {
        throw "Action bloquee apres un refus d'acces reel d'Active Directory pour la capacite $Capability sur cette cible. Recharge l'objet apres correction des droits."
    }
    if ([bool](Get-CfgValue "Security" "BlockOnAclEstimate" $false) -and -not [string]::IsNullOrWhiteSpace($Capability) -and $script:CurrentCapabilities.ContainsKey($Capability)) {
        $state = [string]$script:CurrentCapabilities[$Capability]
        if ($state -eq "Refuse") { throw "Action bloquee par la politique locale : l'estimation ACL est defavorable pour la capacite $Capability sur cette cible. Rafraichis les droits apres toute delegation recente." }
    }
}

function Invoke-DomeniaWritePostAction {
    param($Result,$State)
    $action = "RefreshObjectBranch"
    $actionState = $null
    try { if ($null -ne $State -and $null -ne $State.PSObject.Properties["AfterSuccessAction"] -and -not [string]::IsNullOrWhiteSpace([string]$State.AfterSuccessAction)) { $action = [string]$State.AfterSuccessAction } } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaWritePostAction' $_ }
    try { if ($null -ne $State -and $null -ne $State.PSObject.Properties["AfterSuccessState"]) { $actionState = $State.AfterSuccessState } } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaWritePostAction' $_ }
    $message = "Operation verifiee."
    try { if ($null -ne $Result -and -not [string]::IsNullOrWhiteSpace([string]$Result.Message)) { $message = [string]$Result.Message } } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaWritePostAction' $_ }

    switch ($action) {
        "None" { return }
        "RefreshObject" {
            Invoke-DomeniaPostWriteRefresh -Message $message -RefreshObject
        }
        "RefreshObjectBranch" {
            Invoke-DomeniaPostWriteRefresh -Message $message -RefreshObject -RefreshBranch
        }
        "ResetPassword" {
            foreach ($name in @("PwdUserNew","PwdUserConfirm")) {
                $control = Get-DomeniaControl -Name $name
                if ($null -ne $control) { try { $control.Password = "" } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaWritePostAction' $_ } }
            }
            foreach ($name in @("TxtUserNewVisible","TxtUserConfirmVisible")) {
                [void](Set-DomeniaControlText -Name $name -Text "")
            }
            Invoke-DomeniaPostWriteRefresh -Message $message -RefreshObject
        }
        "UpdateDnRefreshObjectBranch" {
            $newDn = ""; $oldDn = ""
            try { $newDn = [string]$Result.NewDn } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaWritePostAction' $_ }
            try { $oldDn = [string]$Result.Before.DN } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaWritePostAction' $_ }
            # FI-20: a row moved without its fiche may leave another object in the fiche; only the moved one follows.
            if ((-not [string]::IsNullOrWhiteSpace($newDn)) -and ($null -ne $script:SelectedObject) -and ((-not $oldDn) -or ([string]$script:SelectedObject.DN -ieq $oldDn))) { $script:SelectedObject.DN = $newDn }
            Invoke-DomeniaPostWriteRefresh -Message $message -RefreshObject -RefreshBranch
        }
        "GroupMemberRefreshObject" {
            [void](Set-DomeniaControlText -Name "TxtGroupMemberTarget" -Text "")
            Invoke-DomeniaPostWriteRefresh -Message $message -RefreshObject
        }
        "RenameComputer" {
            $newDn = ""
            try { $newDn = [string]$Result.NewDn } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaWritePostAction' $_ }
            if (-not [string]::IsNullOrWhiteSpace($newDn) -and $null -ne $script:SelectedObject) { $script:SelectedObject.DN = $newDn }
            [void](Set-DomeniaControlText -Name "TxtCompNewName" -Text "")
            Invoke-DomeniaPostWriteRefresh -Message $message -RefreshObject -RefreshBranch
        }
        "CreateOu" {
            [void](Set-DomeniaControlText -Name "TxtNewOuName" -Text "")
            Invoke-DomeniaPostWriteRefresh -Message $message -RefreshBranch
            Load-TreeRoot
        }
        "DeleteObject" {
            $deletedType = ""; $deletedName = ""; $deletedSam = ""; $deletedDns = ""
            try { $deletedType = [string]$actionState.DeletedType } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaWritePostAction' $_ }
            try { $deletedName = [string]$actionState.DeletedName } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaWritePostAction' $_ }
            try { $deletedSam = [string]$actionState.DeletedSam } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaWritePostAction' $_ }
            try { $deletedDns = [string]$actionState.DeletedDns } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaWritePostAction' $_ }
            Remove-LinksForDeletedObject -Type $deletedType -Name $deletedName -Sam $deletedSam -Dns $deletedDns
            Clear-Secrets
            Clear-ObjectDetails
            $script:SelectedObject = $null
            Apply-CurrentPermissionUi
            Invoke-DomeniaPostWriteRefresh -Message $message -RefreshBranch
        }
        default {
            Write-AppLog "Action post-ecriture inconnue '$action'. Repli sur rafraichissement complet." "WARN"
            Invoke-DomeniaPostWriteRefresh -Message $message -RefreshObject -RefreshBranch
        }
    }
}

function Get-DomeniaWritePostcondition {
    param([string]$OperationId,$Result)
    if ($null -eq $Result) { return $null }
    $pc = $null
    try { $pc = $Result.Postcondition } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaWritePostcondition' $_ }
    $expected = $null
    $observed = $null
    $sent = $null
    if ($null -ne $pc) {
        try { $expected = $pc.Expected } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaWritePostcondition' $_ }
        try { $observed = $pc.Observed } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaWritePostcondition' $_ }
        try { $sent = $pc.SentUtc } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaWritePostcondition' $_ }
    }
    if ($null -eq (Get-Command -Name 'Resolve-DomeniaPostcondition' -ErrorAction SilentlyContinue)) { return $null }
    try {
        return Resolve-DomeniaPostcondition -Rule ([string]$OperationId) -Expected $expected -Observed $observed -SentUtc $sent
    } catch { return $null }
}

function Get-DomeniaWriteCompensationText {
    # SE-09 / D100: after a verified attribute write, the compensation rule (Get-DomeniaCompensation) says from the
    # values re-read by the worker whether a reverse change could be prepared, or why not. It is only shown: nothing
    # is prepared or sent; a reverse change is a new write with its own plan and confirmation.
    param($State,$Result)
    $plan = $null
    try { $plan = $State.Plan } catch { $plan = $null }
    if (($plan -isnot [Domenia.InterventionPlan]) -or ([string]$plan.Operation -cne ('Write' + 'Attributes'))) { return '' }
    $observed = $null
    try { $observed = $Result.Postcondition.Observed } catch { $observed = $null }
    $guid = ''
    try { $guid = [string]$Result.After.Guid } catch { $guid = '' }
    $current = [pscustomobject]@{ ReadStatus=[string](Get-DomeniaMember $observed 'ReadStatus' ''); Guid=$guid; Values=(Get-DomeniaMemberValue $observed 'Values' $null) }
    $compensation = Get-DomeniaCompensation -Plan $plan -OriginalStatus 'Verifie' -Current $current
    if ([bool]$compensation.Offered) {
        $lines = @(Get-DomeniaPlanChangeText -Changes @($compensation.Changes))
        return ('retour arrière possible par une nouvelle modification à confirmer (' + ($lines -join ' ; ') + '). Rien nʼest préparé ni envoyé automatiquement.')
    }
    return ('retour arrière non proposé : ' + [string]$compensation.Reason)
}

function Complete-DomeniaWriteTaskUi {
    param($Result,$State)
    $script:ReceiptReady=$false; $script:ReceiptRefreshNeeded=$true
    $name = "Ecriture AD"
    $correlation = ""
    try { if ($null -ne $State) { $name = [string]$State.Name; $correlation = [string]$State.Correlation } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWriteTaskUi' $_ }
    if ([string]::IsNullOrWhiteSpace($name)) { $name = "Ecriture AD" }
    $verifiedOperation = $false
    try {
        $script:ActiveWriteTaskId = ""
        $script:ActiveWriteLock = $null
        $script:WriteState = "Idle"
        $effective = Get-DomeniaEffectiveWorkerResult -Result $Result -RequiredProperties @("Verified")
        $verified = $false
        try { if ($null -ne $effective) { $verified = [bool]$effective.Verified } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWriteTaskUi' $_ }
        if (-not $verified) {
            $script:WriteState = "Unknown"
            try { $script:UnknownWriteTargetDn = [string]$State.TargetDn } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWriteTaskUi' $_ }
            [void](Set-DomeniaWriteTaskOutcome -State $State -Outcome Uncertain)
            $msg = "Ecriture retournee sans verification positive. Etat verrouille : recharge l'objet avant toute autre ecriture."
            Write-AppLog "[$correlation] $name : $msg" "ERROR"
            Set-Status $msg "ERROR"
            Show-ErrorBox $msg
            Apply-CurrentPermissionUi
            return
        }
        $verifiedOperation = $true
        [void](Set-DomeniaWriteTaskOutcome -State $State -Outcome Verified)
        try {
            $compensation = Get-DomeniaWriteCompensationText -State $State -Result $effective
            if ($compensation) { Add-DomeniaUiLog -Area "Ecritures" -Text ($name + ' : ' + $compensation) }
        } catch { Write-AppLog ('Retour arriere non evalue : ' + $_.Exception.Message) 'WARN' }
        $script:WriteState = "Idle"
        $script:UnknownWriteTargetDn = ""
        $message = "Operation verifiee."
        try { if (-not [string]::IsNullOrWhiteSpace([string]$effective.Message)) { $message = [string]$effective.Message } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWriteTaskUi' $_ }
        $backend = ""
        try { $backend = [string]$effective.Backend } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWriteTaskUi' $_ }
        $partial = $false
        # P-CD-09: an unreadable Partial flag never reads as a complete success: the operator checks the steps.
        try { if ($null -ne $effective.PSObject.Properties["Partial"]) { $partial = [bool]$effective.Partial } } catch { $partial = $true; Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWriteTaskUi' $_ }
        $post = Get-DomeniaWritePostcondition -OperationId ([string]$State.OperationId) -Result $effective
        $script:LastWritePostcondition = $post
        $postStatus = ""
        $postLabel = ""
        $postProof = ""
        if ($null -ne $post) {
            try { $postStatus = [string]$post.Status } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWriteTaskUi' $_ }
            try { $postLabel = [string]$post.Label } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWriteTaskUi' $_ }
            try { $postProof = [string]$post.Proof } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWriteTaskUi' $_ }
        }
        if ($postLabel) {
            $postLevel = "INFO"
            if ($postStatus -ne "Verifie") { $postLevel = "WARN" }
            Write-AppLog "[$correlation] POSTCONDITION $name : $postLabel - $postProof" $postLevel
        }
        if ($postStatus -eq "Verifie") {
            if ($partial) {
                Write-AppLog "[$correlation] PARTIEL $name via $backend : $message" "WARN"
                Set-Status "$message (Partiel)" "WARN"
                Show-InfoBox "$name a été accepté en partie par le contrôleur de domaine.`r`n`r`n$message`r`n`r`nVérifiez les étapes signalées en échec avant toute nouvelle tentative."
            }
            else {
                Write-AppLog "[$correlation] SUCCES $name via $backend : $message" "INFO"
                Set-Status "$message (Vérifié)"
            }
        }
        elseif ($postStatus -eq "Partiel" -or $postStatus -eq "A verifier") {
            $ruleCheck = ""
            try { $ruleCheck = [string](Get-DomeniaPostconditionRule ([string]$State.OperationId)).Check } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWriteTaskUi' $_ }
            $info = "$name : $postLabel`r`n`r`nPreuve : $postProof"
            if ($ruleCheck) { $info += "`r`n`r`nVerification a faire : $ruleCheck" }
            Set-Status "$name : $postLabel - $postProof" "WARN"
            Show-InfoBox $info
        }
        elseif ($partial) {
            Write-AppLog "[$correlation] PARTIEL $name via $backend : $message" "WARN"
            Set-Status $message "WARN"
            Show-InfoBox "$name a été accepté en partie par le contrôleur de domaine.`r`n`r`n$message`r`n`r`nVérifiez les étapes signalées en échec avant toute nouvelle tentative."
        }
        else {
            Write-AppLog "[$correlation] SUCCES $name via $backend : $message" "INFO"
            Set-Status $message
        }
        $script:DraftState=$null
        Invoke-DomeniaWritePostAction -Result $effective -State $State
        Apply-CurrentPermissionUi
        Request-DomeniaDashboardRefresh -Immediate
    }
    catch {
        if ($verifiedOperation) {
            $script:WriteState = "Idle"
            $script:UnknownWriteTargetDn = ""
            $detail = "L'ecriture a ete verifiee par le DC, mais le rafraichissement de l'interface a echoue : $($_.Exception.Message)"
            Write-AppLog "[$correlation] $name : ecriture verifiee ; erreur UI  $($_.Exception.ToString())" "WARN"
            Set-Status $detail "WARN"
            Show-InfoBox "$name : $detail`r`n`r`nRechargez manuellement lʼobjet ; ne rejouez pas lʼécriture."
        }
        else {
            $script:WriteState = "Unknown"
            try { $script:UnknownWriteTargetDn = [string]$State.TargetDn } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaWriteTaskUi' $_ }
            $detail = "Resultat d'ecriture non verifie : $($_.Exception.Message)"
            Write-AppLog "[$correlation] $name : $detail  $($_.Exception.ToString())" "ERROR"
            Set-Status $detail "ERROR"
            Show-ErrorBox "$name : $detail"
        }
        Apply-CurrentPermissionUi
    }
}

function Fail-DomeniaWriteTaskUi {
    param($Message,$State)
    $script:ReceiptReady=$false; $script:ReceiptRefreshNeeded=$true
    $name = "Ecriture AD"
    $correlation = ""
    try { if ($null -ne $State) { $name = [string]$State.Name; $correlation = [string]$State.Correlation } } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaWriteTaskUi' $_ }
    if ([string]::IsNullOrWhiteSpace($name)) { $name = "Ecriture AD" }
    $detail = ([string]$Message).Trim()
    if ([string]::IsNullOrWhiteSpace($detail)) { $detail = "Erreur inconnue pendant l'ecriture AD." }
    $capability = ""
    $targetDn = ""
    try { $capability = [string]$State.Capability; $targetDn = [string]$State.TargetDn } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaWriteTaskUi' $_ }
    $errorInfo = ConvertTo-DomeniaErrorInfo -ErrorRecordOrException $detail -Operation $name
    $script:ActiveWriteTaskId = ""
    $script:ActiveWriteLock = $null
    if ($detail -match "(?i)etat inconnu") {
        $script:WriteState = "Unknown"
        $script:UnknownWriteTargetDn = $targetDn
        # SE-09: sent without proof (no answer, client-side LDAP code from 81 up, timeout): to verify, never sent again.
        [void](Set-DomeniaWriteTaskOutcome -State $State -Outcome Uncertain)
    }
    else {
        $script:WriteState = "Idle"
        $script:UnknownWriteTargetDn = ""
        # Refused before dispatch or by the controller itself (LDAP 1-80): certainly not applied.
        [void](Set-DomeniaWriteTaskOutcome -State $State -Outcome NotSent)
    }
    if ($errorInfo.Kind -eq "AccessDenied" -and -not [string]::IsNullOrWhiteSpace($capability)) {
        $script:CurrentCapabilities[$capability] = "Refuse"
        Set-DomeniaActualCapabilityDenied -Dn $targetDn -Capability $capability -Reason $detail
        Write-AppLog "[$correlation] Capacite $capability verrouillee apres refus reel du controleur sur $targetDn." "WARN"
    }
    Write-AppLog "[$correlation] ECHEC $name [$($errorInfo.Kind)] : $detail" "ERROR"
    Set-Status $errorInfo.Friendly "ERROR"
    Apply-CurrentPermissionUi
    if ($detail -match "(?i)etat inconnu") {
        $info = "$name : $detail`r`n`r`nAucun rejeu automatique ne sera effectue."
        try {
            $check = [string](Get-DomeniaPostconditionRule ([string]$State.OperationId)).Check
            if ($check) { $info += "`r`n`r`nIssue : A verifier. Verification a faire : $check" }
        } catch { Write-DomeniaSwallowed 'Core' 'Fail-DomeniaWriteTaskUi' $_ }
        Show-InfoBox $info
    }
    else { Show-ErrorBox "$($errorInfo.Friendly)`r`n`r`nLe détail technique a été enregistré dans le journal Domenia." }
}

function Get-DomeniaWriteRoute {
    $server = ''
    try { $server = [string]$script:Conn.Server } catch { $server = '' }
    $limit = ''
    if ([string]::IsNullOrWhiteSpace($server)) {
        try { $server = [string]$script:Conn.Domain } catch { $server = '' }
        $limit = 'Aucun controleur fixe : le domaine choisit le controleur qui recoit la demande.'
    }
    $account = ''
    try { $account = [string](Get-DomeniaDirectoryBindUser) } catch { $account = '' }
    if ([string]::IsNullOrWhiteSpace($account)) {
        try { $account = [string]([Security.Principal.WindowsIdentity]::GetCurrent().Name) } catch { $account = '' }
    }
    if ([string]::IsNullOrWhiteSpace($server)) { throw 'Aucun destinataire fixe : impossible de preparer une ecriture.' }
    if ([string]::IsNullOrWhiteSpace($account)) { throw 'Aucun compte d execution : impossible de preparer une ecriture.' }
    return [pscustomobject]@{ Server=$server; Account=$account; Limit=$limit }
}

function New-DomeniaSelectionWritePlan {
    param(
        [Parameter(Mandatory=$true)][string]$OperationId,
        [object[]]$Changes=@(),
        [string[]]$Effects=@()
    )
    if ($null -eq $Changes) { $Changes = @() }
    if ($null -eq $Effects) { $Effects = @() }
    $identity = Get-DomeniaCurrentSelectionIdentity
    if ($null -eq $identity) { throw 'Selection sans identite exacte (domaine et GUID) : relire l objet avant toute ecriture.' }
    $route = Get-DomeniaWriteRoute
    $effectList = New-Object Collections.ArrayList
    foreach ($e in @($Effects)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$e)) { [void]$effectList.Add([string]$e) }
    }
    if ($null -ne $route.PSObject.Properties['Limit'] -and -not [string]::IsNullOrWhiteSpace([string]$route.Limit)) {
        $routeLimit = [string]$route.Limit
        $exists = $false
        foreach ($e in $effectList) { if ([string]$e -ceq $routeLimit) { $exists = $true; break } }
        if (-not $exists) { [void]$effectList.Add($routeLimit) }
    }
    $attributeOperation = ('Write' + 'Attributes')
    if ($OperationId -ne $attributeOperation) {
        $fixedLimit = 'Pas de condition atomique : objet relu sur le controleur prevu juste avant l envoi (version de l objet), puis relu apres. Aucune transaction entre plusieurs requetes.'
        $exists = $false
        foreach ($e in $effectList) { if ([string]$e -ceq $fixedLimit) { $exists = $true; break } }
        if (-not $exists) { [void]$effectList.Add($fixedLimit) }
    }
    return New-DomeniaInterventionPlan -OperationId $OperationId -Target $identity -Server ([string]$route.Server) -Account ([string]$route.Account) -Changes $Changes -Effects @($effectList.ToArray()) -Simulation $false
}



function Request-DomeniaWriteConfirmation {
    # UX-08: every directory write is confirmed by one panel of the page (Request-DomeniaInlineConfirmation), never
    # a window: a sentence, the changes in plain words (Get-DomeniaPlanChangeText) and, folded, the technical
    # details of the plan (GUID, DN, controller, account, fingerprint). The write leaves only from the continuation,
    # once, and Start-DomeniaWriteTask checks the plan against the current selection again at that moment.
    param(
        [AllowNull()]$Plan=$null,
        [Parameter(Mandatory=$true)][string]$Title,
        [AllowEmptyString()][string]$Message='',
        [string]$ConfirmText='Confirmer',
        [ValidateSet('Normal','Danger')][string]$Risk='Normal',
        [AllowEmptyString()][string]$TypedConfirmation='',
        [AllowEmptyString()][string]$TypedPrompt='',
        [string[]]$Changes=@(),
        [AllowEmptyString()][string]$Details='',
        [AllowEmptyString()][string]$Target='',
        [Parameter(Mandatory=$true)][scriptblock]$Send,
        $State=$null,
        [string]$CancelStatus='Modification annulée : rien nʼa été envoyé à lʼannuaire.'
    )
    $isPlan = ($Plan -is [Domenia.InterventionPlan])
    if ((-not $PSBoundParameters.ContainsKey('Changes')) -and $isPlan) { $Changes = @(Get-DomeniaPlanChangeText -Changes @($Plan.Changes)) }
    if ((-not $PSBoundParameters.ContainsKey('Details')) -and $isPlan) { $Details = Format-DomeniaPlanConfirmation -Plan $Plan }
    if ((-not $Target) -and $isPlan) { $Target = 'ad:' + ([string]$Plan.Target.Guid).ToLowerInvariant() }
    # The continuations are closures over plain script blocks of this script: the functions they call resolve here.
    $send = $Send; $sendState = $State; $cancelStatusText = $CancelStatus
    $cancel = { param([string]$text) Set-Status $text 'INFO' }
    $onConfirm = { & $send $sendState }.GetNewClosure()
    $onCancel = { & $cancel $cancelStatusText }.GetNewClosure()
    return (Request-DomeniaInlineConfirmation -Title $Title -Message $Message -Target $Target -ConfirmText $ConfirmText -CancelText 'Annuler' -OnConfirm $onConfirm -OnCancel $onCancel -Risk $Risk -Changes @($Changes) -Details $Details -TypedConfirmation $TypedConfirmation -TypedPrompt $TypedPrompt)
}

function Test-DomeniaPlanDispatch {
    param(
        $Plan,
        [object[]]$Changes=@(),
        [string]$OperationId='',
        [string]$PayloadDn=''
    )
    if ($null -eq $Changes) { $Changes = @() }
    $reasons = New-Object 'System.Collections.Generic.List[string]'
    $fingerprint = ''
    if ($Plan -isnot [Domenia.InterventionPlan]) {
        return [pscustomobject]@{ Valid=$false; Reasons=@('Aucun plan confirme : rien n est execute.'); Fingerprint='' }
    }
    $current = Get-DomeniaCurrentSelectionIdentity
    $server = ''
    $account = ''
    try {
        $route = Get-DomeniaWriteRoute
        $server = [string]$route.Server
        $account = [string]$route.Account
    } catch {
        [void]$reasons.Add([string]$_.Exception.Message)
    }
    $maxAge = [Math]::Min(1440,[Math]::Max(1,[int](Get-CfgValue "Security" "MaxObjectAgeMinutes" 15)))
    $check = Test-DomeniaPlanStillValid -Plan $Plan -Current $current -Server $server -Account $account -Changes $Changes -OperationId $OperationId -NowUtc ([DateTime]::UtcNow) -MaxAgeMinutes $maxAge
    $valid = $false
    if ($null -ne $check) {
        if ($null -ne $check.PSObject.Properties['Reasons']) {
            foreach ($reason in @($check.Reasons)) {
                if ($reason) { [void]$reasons.Add([string]$reason) }
            }
        }
        if ($null -ne $check.PSObject.Properties['Fingerprint']) { $fingerprint = [string]$check.Fingerprint }
        $valid = [bool]$check.Valid
    }
    $plannedDn = ([string]$Plan.Target.DN).Trim()
    $payloadDn = ([string]$PayloadDn).Trim()
    if ($payloadDn -and ($payloadDn -ine $plannedDn)) {
        [void]$reasons.Add('Le payload ne designe pas la cible confirmee : rien n est execute.')
    }
    if ($reasons.Count -gt 0) { $valid = $false }
    return [pscustomobject]@{ Valid=$valid; Reasons=$reasons.ToArray(); Fingerprint=$fingerprint }
}

function Start-DomeniaWriteTask {
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][ValidatePattern('^Write[A-Za-z0-9]{2,59}$')][string]$OperationId,
        [Parameter(Mandatory)][string]$Code,
        $Payload,
        [AllowEmptyString()][string]$PlanFingerprint = "",
        [string]$Capability = "Edit",
        [string[]]$DisableControls = @(),
        [string]$AfterSuccessAction = "RefreshObjectBranch",
        $AfterSuccessState = $null,
        [int]$TimeoutSeconds = 0,
        [object]$Plan = $null,
        [object[]]$PlanChanges = @(),
        [AllowEmptyString()][string]$BranchDn = ""
    )
    if ($null -eq $Payload) { $Payload = [pscustomobject]@{} }
    if ($null -eq $PlanChanges) { $PlanChanges = @() }
    $planProvided = ($Plan -is [Domenia.InterventionPlan])
    if (((Get-DomeniaOperationEffect $OperationId) -eq 'DirectoryWrite') -and (-not $planProvided)) {
        # Seule exception : la creation d OU vise une branche de l arbre, sans identite GUID. Son DN fige avant la
        # confirmation doit etre encore la branche selectionnee et le parent du payload.
        $branchNow = ([string]$script:SelectedBranchDn).Trim()
        $branchPlanned = ([string]$BranchDn).Trim()
        if (($OperationId -cne 'WriteCreateOu') -or (-not $branchPlanned)) { Show-ErrorBox 'Aucun plan confirmé pour cette écriture : rien nʼest envoyé.'; return }
        if (($branchNow -ine $branchPlanned) -or (([string](Get-DomeniaMember $Payload 'ParentDn' '')).Trim() -ine $branchPlanned)) {
            Show-ErrorBox 'La branche cible a changé depuis la confirmation : rien nʼest envoyé.'
            Write-AppLog "PLAN INVALIDE $Name : branche $branchPlanned devenue $branchNow" "WARN"
            return
        }
    }
    if ($planProvided) {
        $planTargetDn = ''
        if ($null -ne $Payload.PSObject.Properties['DN']) { $planTargetDn = [string]$Payload.DN }
        elseif ($null -ne $Payload.PSObject.Properties['ParentDn']) { $planTargetDn = [string]$Payload.ParentDn }
        elseif ($null -ne $Payload.PSObject.Properties['GroupDn']) { $planTargetDn = [string]$Payload.GroupDn }
        elseif ($null -ne $Payload.PSObject.Properties['ObjectDn']) { $planTargetDn = [string]$Payload.ObjectDn }
        $dispatch = Test-DomeniaPlanDispatch -Plan $Plan -Changes $PlanChanges -OperationId $OperationId -PayloadDn $planTargetDn
        if (-not [bool]$dispatch.Valid) {
            $msg = 'Plan invalide avant envoi : rien n est envoye.'
            if ($null -ne $dispatch.PSObject.Properties['Reasons'] -and @($dispatch.Reasons).Count -gt 0) { $msg += "`r`n" + (@($dispatch.Reasons) -join "`r`n") }
            Show-ErrorBox $msg
            Write-AppLog "PLAN INVALIDE $Name : $msg" "WARN"
            return
        }
    }
    $explicitPlanFingerprint = [string]$PlanFingerprint
    if ($planProvided) {
        $PlanFingerprint = [string]$Plan.Fingerprint
        if (-not [string]::IsNullOrWhiteSpace($explicitPlanFingerprint) -and ($explicitPlanFingerprint -cne $PlanFingerprint)) {
            $msg = 'Empreinte explicite differente du plan confirme : rien n est envoye.'
            Show-ErrorBox $msg
            Write-AppLog "PLAN REFUSE $Name : $msg" "WARN"
            return
        }
    }
    $planFingerprint = [string]$PlanFingerprint
    if ([string]::IsNullOrWhiteSpace($planFingerprint)) { $planFingerprint = [string](Get-DomeniaMember $Payload 'PlanFingerprint' '') }
    $planKey = ''
    $receipts = @()
    if ($null -ne $script:ReceiptRows) { $receipts = @($script:ReceiptRows) }
    if (-not [string]::IsNullOrWhiteSpace($planFingerprint)) {
        $planKey = ([string]$planFingerprint).Trim().ToUpperInvariant()
        if ($null -eq $script:SubmittedWritePlans) { $script:SubmittedWritePlans = @{} }
        $admissionCheck = Test-DomeniaWriteAdmission -Fingerprint $planKey -Submitted $script:SubmittedWritePlans -Receipts $receipts -Active $script:AsyncJobs -Origin Operator -CheckOnly
        if (-not [bool]$admissionCheck.Admit) { Show-ErrorBox ([string]$admissionCheck.Reason); return }
    }
    # SE-09: locks by target and action class (Test-DomeniaOperationAllowed). The write running in this session and
    # the receipts left to verify hold their own target; while a directory write runs, the others wait one by one.
    $lockTargets = @()
    if ($planProvided) { $lockTargets = @($Plan.Target) } else { $lockTargets = @(([string]$BranchDn).Trim()) }
    $lockCheck = Test-DomeniaOperationAllowed -OperationId $OperationId -Targets $lockTargets -Locks @(Get-DomeniaWriteLocks -Receipts $receipts)
    if (-not [bool]$lockCheck.Allowed) {
        Show-ErrorBox ([string]$lockCheck.Reason)
        Write-AppLog "VERROU $Name : $([string]$lockCheck.Reason)" "WARN"
        return
    }
    try { Assert-DomeniaCapability $Capability }
    catch { Show-ErrorBox $_.Exception.Message; return }
    if($null -ne $script:Continuity){$script:Continuity.Mutation++}
    if (-not [string]::IsNullOrWhiteSpace($planKey)) {
        $admission = Test-DomeniaWriteAdmission -Fingerprint $planKey -Submitted $script:SubmittedWritePlans -Receipts $receipts -Active $script:AsyncJobs -Origin Operator
        if (-not [bool]$admission.Admit) { Show-ErrorBox ([string]$admission.Reason); return }
        if ($null -eq $Payload.PSObject.Properties['PlanFingerprint']) { $Payload | Add-Member -NotePropertyName PlanFingerprint -NotePropertyValue $planKey } else { $Payload.PlanFingerprint = $planKey }
        # SE-09: the reserved entry names its operation, so that Set-DomeniaWriteOutcome can tell a directory write.
        $entry = $script:SubmittedWritePlans[$planKey]
        if (($null -ne $entry) -and ($null -eq $entry.PSObject.Properties['Operation'])) { $entry | Add-Member -NotePropertyName Operation -NotePropertyValue $OperationId }
    }
    $correlation = [guid]::NewGuid().ToString("N")
    if ($null -eq $Payload.PSObject.Properties["CorrelationId"]) { $Payload | Add-Member -NotePropertyName CorrelationId -NotePropertyValue $correlation }
    $allControls = @((Get-AllWriteControlNames) + @($DisableControls) + @("ChkLiveVerifyOnClick","BtnLiveRecheck","TvDirectory","DgObjects","TxtGlobalSearch","BtnGlobalSearch","BtnGlobalClear","BtnTreeRefresh","BtnDashRoot","BtnSearchAllDomain","BtnSearchInOu","ChkSubtree","CmbGlobalType","BtnLoadBranch") | Select-Object -Unique)
    if ($TimeoutSeconds -le 0) { $TimeoutSeconds = [int](Get-CfgValue "Async" "WriteSoftTimeoutSeconds" 90) }
    $hard = [int](Get-CfgValue "Async" "WriteHardTimeoutSeconds" 300)
    Write-AppLog "[$correlation] DEBUT $Name sur $([string]$Payload.DN)" "INFO"
    [void](Assert-DomeniaWorkerOperationCode -OperationId $OperationId -Code $Code)
    $targetDn = ""
    if ($null -ne $Payload.PSObject.Properties["DN"]) { $targetDn = [string]$Payload.DN }
    elseif ($null -ne $Payload.PSObject.Properties["ParentDn"]) { $targetDn = [string]$Payload.ParentDn }
    elseif ($null -ne $Payload.PSObject.Properties["GroupDn"]) { $targetDn = [string]$Payload.GroupDn }
    elseif ($null -ne $Payload.PSObject.Properties["ObjectDn"]) { $targetDn = [string]$Payload.ObjectDn }
    if ([string]::IsNullOrWhiteSpace($targetDn)) { try { $targetDn = [string]$script:SelectedObject.DN } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaWriteTask' $_ } }
    $callbackState = [pscustomobject]@{
        Name = $Name
        OperationId = $OperationId
        Correlation = $correlation
        Capability = $Capability
        TargetDn = $targetDn
        AfterSuccessAction = $AfterSuccessAction
        AfterSuccessState = $AfterSuccessState
        PlanKey = $planKey
        Plan = $Plan
    }
    try {
        $id = Start-UiTask -Name $Name -OperationId $OperationId -Code $Code -Payload $Payload -ReplaceKey "domenia-write-channel" -DisableControls $allControls -TimeoutSeconds $TimeoutSeconds -HardTimeoutSeconds $hard -StatusText "$Name en cours, GUI disponible..." -SuccessHandler "Complete-DomeniaWriteTaskUi" -ErrorHandler "Fail-DomeniaWriteTaskUi" -CallbackState $callbackState -IsWrite -NonCancellable -CorrelationId $correlation
    } catch {
        if ((-not [string]::IsNullOrWhiteSpace($planKey)) -and (($null -ne $script:SubmittedWritePlans)) -and ($script:SubmittedWritePlans.ContainsKey($planKey))) {
            $script:SubmittedWritePlans.Remove($planKey)
        }
        throw
    }
    $script:ActiveWriteTaskId = [string]$id
    $script:ActiveWriteLock = New-DomeniaOperationLock -OperationId $OperationId -Targets $lockTargets -State Running -Id ([string]$id)
    $script:WriteState = "Running"
    Apply-CurrentPermissionUi
}

function Get-DomeniaWriteLocks {
    # SE-09: the locks a new write is checked against: the directory write running in this session and the locks of
    # the receipts left to verify (Get-DomeniaReceiptLocks). An unreadable receipt list keeps the running lock only;
    # the worker refuses any write while a receipt of the domain stays to verify in any case.
    param([object[]]$Receipts=@())
    $locks = New-Object 'System.Collections.Generic.List[object]'
    if ($null -ne $script:ActiveWriteLock) { $locks.Add($script:ActiveWriteLock) }
    try { foreach ($lock in @(Get-DomeniaReceiptLocks -Receipts @($Receipts))) { if ($null -ne $lock) { $locks.Add($lock) } } }
    catch { Write-AppLog ('Verrous des recus illisibles : ' + $_.Exception.Message) 'WARN' }
    return $locks.ToArray()
}

function Set-DomeniaWriteTaskOutcome {
    # SE-09: records the issue of an admitted request in the admission registry with the shared rule
    # Set-DomeniaWriteOutcome: Verified, Uncertain (sent without proof: never sent again before its receipt is
    # verified) or NotSent (certainly not applied: a new explicit confirmation may send the same change again).
    param($State,[Parameter(Mandatory=$true)][ValidateSet('Verified','Uncertain','NotSent')][string]$Outcome)
    $key = ''
    try { $key = [string]$State.PlanKey } catch { $key = '' }
    if ([string]::IsNullOrWhiteSpace($key) -or ($null -eq $script:SubmittedWritePlans)) { return $null }
    $answer = Set-DomeniaWriteOutcome -Registry ([pscustomobject]@{Entries=$script:SubmittedWritePlans}) -Key $key -Outcome $Outcome
    if (-not [bool]$answer.Accepted) { Write-AppLog ('Issue de la demande non enregistree (' + $Outcome + ') : ' + [string]$answer.Reason) 'WARN' }
    return $answer
}

$script:WorkerCommon += @'
function Resolve-WDirectoryIdentityDn {
    # SE-12: a typed DN is checked by the shared rule (syntax, connected domain, never the configuration or DNS
    # partitions), then the object is read and named by its GUID: the DN used is the one the directory returns
    # for that GUID, never the typed text. Nothing is sent when one of these steps fails.
    param($Context,[string]$Dn)
    $check=Test-DomeniaWriteTargetDn -Dn $Dn -BaseDn ([string]$Context.BaseDn)
    if(-not [bool]$check.Valid){throw [string]$check.Reason}
    $snap=Get-WObjectSnapshot $Context ([string]$check.Dn)
    $guid=([string]$snap.Guid).Trim([char[]]'{}')
    if((-not [bool]$snap.Exists) -or [string]::IsNullOrWhiteSpace($guid)){throw ('Cible introuvable dans l annuaire : '+[string]$check.Name+'. Rien n est envoye.')}
    $byGuid=Get-WObjectSnapshot $Context ('<GUID='+$guid+'>')
    if((-not [bool]$byGuid.Exists) -or (([string]$byGuid.Guid).Trim([char[]]'{}') -ine $guid)){throw ('Cible non confirmee par son GUID : '+[string]$check.Name+'. Rien n est envoye.')}
    $final=Test-DomeniaWriteTargetDn -Dn ([string]$byGuid.DN) -BaseDn ([string]$Context.BaseDn)
    if(-not [bool]$final.Valid){throw [string]$final.Reason}
    return [string]$byGuid.DN
}
function Resolve-WGroupDn {
    param($Context,[string]$Value)
    if($Value -match "(?i)^\s*(CN|OU|DC)\s*="){return (Resolve-WDirectoryIdentityDn $Context $Value)}
    $e=Escape-WLdap $Value
    $s=New-WSearcher $Context ([string]$Context.BaseDn) "(&(objectCategory=group)(|(sAMAccountName=$e)(name=$e)))" @("distinguishedName") "Subtree" 2
    # PF-02: at most two results (SizeLimit 2 proves an ambiguity); the collection and its root are released at once.
    $collection=$null;$root=$s.SearchRoot
    try{$collection=$s.FindAll();$all=@($collection)}finally{if($null -ne $collection){$collection.Dispose()};$s.Dispose();if($null -ne $root){$root.Dispose()}}
    if($all.Count -eq 0){throw "Groupe introuvable : $Value"}
    if($all.Count -gt 1){throw "Groupe ambigu : $Value. Utilise son DN complet."}
    return (Resolve-WDirectoryIdentityDn $Context ([string](Get-WPropFirst $all[0].Properties "distinguishedname" "")))
}
function Resolve-WObjectDn {
    param($Context,[string]$Value)
    if($Value -match "(?i)^\s*(CN|OU|DC)\s*="){return (Resolve-WDirectoryIdentityDn $Context $Value)}
    $e=Escape-WLdap $Value
    $s=New-WSearcher $Context ([string]$Context.BaseDn) "(|(sAMAccountName=$e)(name=$e)(dNSHostName=$e)(userPrincipalName=$e))" @("distinguishedName") "Subtree" 2
    # PF-02: at most two results (SizeLimit 2 proves an ambiguity); the collection and its root are released at once.
    $collection=$null;$root=$s.SearchRoot
    try{$collection=$s.FindAll();$all=@($collection)}finally{if($null -ne $collection){$collection.Dispose()};$s.Dispose();if($null -ne $root){$root.Dispose()}}
    if($all.Count -eq 0){throw "Objet introuvable : $Value"}
    if($all.Count -gt 1){throw "Objet ambigu : $Value. Utilise son DN complet."}
    return (Resolve-WDirectoryIdentityDn $Context ([string](Get-WPropFirst $all[0].Properties "distinguishedname" "")))
}
function Escape-WRdn {
    param([string]$Value)
    $r=$Value.Replace("\","\\").Replace(",","\,").Replace("+","\+").Replace('"','\"').Replace("<","\<").Replace(">","\>").Replace(";","\;")
    if($r.StartsWith(" ")){$r="\ "+$r.Substring(1)}
    if($r.EndsWith(" ")){$r=$r.Substring(0,$r.Length-1)+"\ "}
    if($r.StartsWith("#")){$r="\#"+$r.Substring(1)}
    return $r
}
'@

$script:WorkerCommon += @'
function Invoke-WConditionalModify {
    param($Context,[string]$Dn,[object[]]$Modifications)
    try { Add-Type -AssemblyName System.DirectoryServices.Protocols -ErrorAction Stop } catch { return [pscustomobject]@{ResultCode=-1;Message=[string]$_.Exception.Message;Sent=$false} }
    $conn = $null
    $netCred = $null
    $secure = $null
    $net = $null
    $mods = $null
    $identifier = $null
    $request = $null
    $so = $null
    $sent = $false
    try {
        $mods = New-Object 'System.Collections.Generic.List[System.DirectoryServices.Protocols.DirectoryAttributeModification]'
        foreach ($m in @($Modifications)) {
            if ($null -eq $m) { continue }
            $name = [string]$m.Name
            if ([string]::IsNullOrWhiteSpace($name)) { continue }
            $op = [string]$m.Op
            $val = [string]$m.Value
            $mod = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
            $mod.Name = $name
            if ($op -ieq 'Delete') {
                $mod.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete
                if (-not [string]::IsNullOrEmpty($val)) { [void]$mod.Add($val) }
            } elseif ($op -ieq 'Add') {
                if ([string]::IsNullOrEmpty($val)) { continue }
                $mod.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Add
                [void]$mod.Add($val)
            } elseif ($op -ieq 'Replace') {
                $mod.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
                [void]$mod.Add($val)
            } elseif ($op -ieq 'Clear') {
                $mod.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete
            } else { continue }
            [void]$mods.Add($mod)
        }
        if ($mods.Count -eq 0) { return [pscustomobject]@{ResultCode=0;Message='Aucune modification.';Sent=$false} }
        if ([string]::IsNullOrWhiteSpace($Dn)) { return [pscustomobject]@{ResultCode=-1;Message='DN absent : aucune ecriture envoyee.';Sent=$false} }
        $server = ([string]$Context.Server).Trim().Trim('/').Trim()
        if ($server -match '(?i)^LDAP://(.*)$') { $server = $matches[1].Trim().Trim('/').Trim() }
        if ([string]::IsNullOrWhiteSpace($server)) {
            $server = ([string]$Context.Domain).Trim().Trim('/').Trim()
            if ($server -match '(?i)^LDAP://(.*)$') { $server = $matches[1].Trim().Trim('/').Trim() }
        }
        if ($server -match '^([^:]+):(\d+)$') { $server = $matches[1].Trim() }
        if ([string]::IsNullOrWhiteSpace($server)) { return [pscustomobject]@{ResultCode=-1;Message='Serveur ou domaine absent du contexte.';Sent=$false} }
        $identifier = New-Object System.DirectoryServices.Protocols.LdapDirectoryIdentifier -ArgumentList @($server, 389)
        if ([bool]$Context.UseCredential -and ($null -ne $Context.Credential)) {
            $net = $Context.Credential.GetNetworkCredential()
            if ($null -eq $net) { throw 'Credential sans GetNetworkCredential.' }
            $bindUser = Get-WDirectoryBindUser $Context
            if ([string]::IsNullOrWhiteSpace($bindUser)) { $bindUser = [string]$Context.Credential.UserName }
            # Same identity as the login and the other write paths: only DOMAIN\user is split, a UPN stays whole.
            if ([string]::IsNullOrWhiteSpace($bindUser)) { $bindUser = [string]$net.UserName }
            $user = $bindUser
            $domain = ''
            if ($bindUser -match '^([^\\@]+)\\(.+)$') { $domain = $matches[1]; $user = $matches[2] }
            if ($Context.Credential.PSObject.Properties['Password']) { $secure = $Context.Credential.Password }
            if ($secure -is [Security.SecureString]) {
                $netCred = New-Object System.Net.NetworkCredential -ArgumentList @($user, $secure, $domain)
            } else {
                # SE-16: a credential without SecureString only gives a String; it goes straight to NetworkCredential.
                $netCred = New-Object System.Net.NetworkCredential -ArgumentList @($user, [string]$net.Password, $domain)
            }
            $net = $null
            $secure = $null
            $conn = New-Object System.DirectoryServices.Protocols.LdapConnection -ArgumentList @($identifier, $netCred, [System.DirectoryServices.Protocols.AuthType]::Negotiate)
        } else {
            $conn = New-Object System.DirectoryServices.Protocols.LdapConnection -ArgumentList @($identifier)
            $conn.AuthType = [System.DirectoryServices.Protocols.AuthType]::Negotiate
        }
        $so = $conn.SessionOptions
        $so.ProtocolVersion = 3
        $so.Signing = $true
        $so.Sealing = $true
        $conn.Timeout = [TimeSpan]::FromSeconds(30)
        $request = New-Object System.DirectoryServices.Protocols.ModifyRequest -ArgumentList @([string]$Dn, $mods.ToArray())
        # Bind first: a failed bind sends nothing. From here on the request may reach the controller.
        # Point 41: the write bind holds the account lease; a rejected account is shared at once with every job.
        Set-WCredentialAttemptIdentity -Context $Context -Credential $Context.Credential -Channel Directory -UserName $(if($Context.UseCredential){Get-WDirectoryBindUser $Context}else{[string]$Context.ProcessIdentity})
        $bindLease=Enter-WCredentialAttempt -Context $Context -Channel Directory
        try{$conn.Bind()}catch{[void](Register-WCredentialFailure -Context $Context -ErrorValue $_ -Channel Directory);throw}finally{Exit-WCredentialAttempt $bindLease}
        $sent = $true
        $response = $conn.SendRequest($request)
        if ($null -eq $response) { return [pscustomobject]@{ResultCode=-1;Message='Reponse du controleur absente.';Sent=$true} }
        $responseCode = [int]$response.ResultCode
        if ($responseCode -ne 0) {
            # Referral (10) and the other non-throwing answers: the request was not applied by this controller.
            $responseText = [string]$response.ErrorMessage
            if ($null -ne $response.Referral -and @($response.Referral).Count -gt 0) { $responseText = ($responseText + ' Renvoi : ' + ((@($response.Referral) | ForEach-Object { [string]$_ }) -join ', ')).Trim() }
            return [pscustomobject]@{ResultCode=$responseCode;Message=$responseText;Sent=$true}
        }
        return [pscustomobject]@{ResultCode=0;Message='';Sent=$true}
    } catch [System.DirectoryServices.Protocols.DirectoryOperationException] {
        $code = -1
        $msg = [string]$_.Exception.Message
        if ($null -ne $_.Exception.Response) {
            $code = [int]$_.Exception.Response.ResultCode
            if (-not [string]::IsNullOrWhiteSpace([string]$_.Exception.Response.ErrorMessage)) { $msg = [string]$_.Exception.Response.ErrorMessage }
        }
        return [pscustomobject]@{ResultCode=$code;Message=$msg;Sent=$sent}
    } catch [System.DirectoryServices.Protocols.LdapException] {
        return [pscustomobject]@{ResultCode=[int]$_.Exception.ErrorCode;Message=[string]$_.Exception.Message;Sent=$sent}
    } catch {
        return [pscustomobject]@{ResultCode=-1;Message=[string]$_.Exception.Message;Sent=$sent}
    } finally {
        if ($null -ne $conn) { try { $conn.Dispose() } catch {} }
        $conn = $null
        $netCred = $null
        $net = $null
        $secure = $null
        $mods = $null
        $identifier = $null
        $request = $null
        $so = $null
    }
}
'@

function Get-DomeniaWorkerRulesCommon {
    # SE-09 / SE-12: the write workers read the controller answer (Resolve-DomeniaConditionalWrite), re-read the
    # preconditions (Test-DomeniaPreconditionCurrent) and check a typed DN (Test-DomeniaWriteTargetDn) with the very
    # rules of Domenia-Safety.Model.ps1, copied into the runspace as text like the error contract, with their call
    # closure. A rule missing from the closed loader stops the start-up: no write runs with another copy of a rule.
    $names=@(
        'Test-DomeniaDictionaryKey','Get-DomeniaMember','ConvertTo-DomeniaFlatText','Split-DomeniaDn','ConvertFrom-DomeniaDnValue',
        'ConvertTo-DomeniaDnKey','ConvertTo-DomeniaDnDisplayName','Test-DomeniaWriteTargetDn','Test-DomeniaSecretAttribute',
        'Test-DomeniaMemberPresent','Test-DomeniaDnValuedAttribute','ConvertTo-DomeniaComparableValue','ConvertTo-DomeniaPlanChanges',
        'Test-DomeniaPreconditionCurrent','Resolve-DomeniaConditionalWrite',
        # Point 49: the receipt keeps the state to re-read (expectation) and the receipt worker judges the re-read.
        'Get-DomeniaReceiptExpectation','Resolve-DomeniaReceiptCheck'
    )
    $parts=New-Object 'System.Collections.Generic.List[string]'
    foreach($name in $names){
        $command=Get-Command -Name $name -CommandType Function -ErrorAction SilentlyContinue
        if($null -eq $command){throw ('Regle d ecriture absente du chargeur : '+$name)}
        $parts.Add('function '+$name+" {`r`n"+[string]$command.Definition+"`r`n}")
    }
    return ($parts.ToArray() -join "`r`n")
}

function Get-DomeniaAttributeWriteStrategy {
    param([Parameter(Mandatory=$true)][object]$Change)
    $name = [string]$Change.Name
    $lower = $name.ToLowerInvariant()
    $clear = [bool]$Change.Clear
    $new = [string]$Change.New
    $after = ''
    if (-not $clear) { $after = $new }
    $before = [string]$Change.Old
    $syntax = 'Other'
    $singleValued = $true
    $singleText = @{
        'givenname'=$true
        'sn'=$true
        'displayname'=$true
        'userprincipalname'=$true
        'mail'=$true
        'telephonenumber'=$true
        'physicaldeliveryofficename'=$true
        'description'=$true
        'title'=$true
        'department'=$true
        'company'=$true
        'location'=$true
    }
    $dnAttrs = @{
        'manager'=$true
        'managedby'=$true
    }
    if ($dnAttrs.ContainsKey($lower)) {
        $syntax = 'DN'
    } elseif ($singleText.ContainsKey($lower)) {
        $syntax = 'Text'
    }
    # description is multi-valued in the schema; only SAM objects (user, computer, group) hold a single value.
    if ($lower -eq 'description') {
        $type = ''
        try { $type = [string]$script:SelectedObject.Type } catch { $type = '' }
        if ($type -notin @('Utilisateur','Machine','Groupe')) { $singleValued = $false }
    }
    return Get-DomeniaAtomicStrategy -Attribute $name -Syntax $syntax -SingleValued $singleValued -Before $before -After $after
}

function Start-DomeniaAttributeWrite {
    param(
        [string]$OperationName,
        [object[]]$Changes,
        [string]$Capability = "Edit",
        [string[]]$DisableControls = @(),
        [string]$AfterSuccessAction = "RefreshObjectBranch",
        $AfterSuccessState = $null,
        [switch]$RawEdit,
        [AllowEmptyString()][string]$TypedConfirmation = ''
    )
    $raw = @($Changes | Where-Object { $null -ne $_ })
    if ($raw.Count -eq 0) { Set-Status "Aucune modification détectée. Aucun appel dʼécriture AD."; return }
    $cleanList = New-Object Collections.ArrayList
    $conditionalNames = New-Object Collections.ArrayList
    $checkedNames = New-Object Collections.ArrayList
    $transactionLimit = ''
    foreach ($c in $raw) {
        $strategy = Get-DomeniaAttributeWriteStrategy -Change $c
        $conditional = $false
        $strategyName = ''
        if ($null -ne $strategy) {
            if ($strategy.PSObject.Properties['Strategy']) { $strategyName = [string]$strategy.Strategy }
            if ($strategy.PSObject.Properties['TransactionLimit'] -and -not $transactionLimit) { $transactionLimit = [string]$strategy.TransactionLimit }
        }
        if ($strategyName -like 'Conditional*') { $conditional = $true }
        # SE-02: a raw edit is flagged for the worker, which applies the raw attribute rule again on its own.
        $copy = [pscustomobject]@{ Name=[string]$c.Name; Old=[string]$c.Old; New=[string]$c.New; Clear=[bool]$c.Clear; Conditional=$conditional; Raw=[bool]$RawEdit }
        [void]$cleanList.Add($copy)
        if ($conditional) { [void]$conditionalNames.Add([string]$c.Name) }
        elseif ($strategyName -ne 'NoChange' -and $strategyName -ne 'NotApplicable') { [void]$checkedNames.Add([string]$c.Name) }
    }
    $effectList = New-Object Collections.ArrayList
    if ($conditionalNames.Count -gt 0) {
        [void]$effectList.Add((($conditionalNames.ToArray()) -join ', ') + ' : condition verifiee par le controleur dans la meme requete ; une valeur modifiee ailleurs fait refuser la requete sans rien ecraser. La comparaison suit la regle de l attribut (insensible a la casse pour ces textes) : une modification ailleurs qui ne change que la casse n est pas detectee.')
    }
    if ($checkedNames.Count -gt 0) {
        [void]$effectList.Add((($checkedNames.ToArray()) -join ', ') + ' : pas de condition atomique ; objet relu sur le controleur prevu juste avant l envoi (version de l objet), puis valeurs relues apres. Une ecriture concurrente entre ces deux lectures n est ni empechee ni detectee.')
    }
    if ($transactionLimit) { [void]$effectList.Add($transactionLimit) }
    $clean = @($cleanList.ToArray())
    $effects = @($effectList.ToArray() | ForEach-Object { [string]$_ })
    try { $plan = New-DomeniaSelectionWritePlan -OperationId 'WriteAttributes' -Changes $clean -Effects $effects } catch { Show-ErrorBox $_.Exception.Message; return }
    try { $safety = Get-DomeniaSafetyDescriptor } catch { Show-ErrorBox $_.Exception.Message; return }
    $payload = [pscustomobject]@{ DN=[string]$plan.Target.DN; Changes=$clean; Safety=$safety }
    $code = @'
Assert-WAttributeChangesAllowed $Context @($Payload.Changes)
$before=Assert-WObjectFresh $Context $Payload.Safety
# SE-09: a form attribute written without a controller condition is re-read on the planned controller just before
# sending; any difference with the confirmed plan sends nothing (Test-DomeniaPreconditionCurrent, shared rule).
$preChanges=New-Object Collections.ArrayList
$preCurrent=@{}
foreach($c in @($Payload.Changes)){
    if(($null -eq $c) -or [bool]$c.Conditional){continue}
    $name=[string]$c.Name
    if(-not (Test-WFormAttribute $name)){continue}
    $kind='Replace';$target=[string]$c.New
    if([bool]$c.Clear){$kind='Clear';$target=''}
    [void]$preChanges.Add([pscustomobject]@{Attribute=$name;Kind=$kind;Before=[string]$c.Old;After=$target})
    $current=Get-WAttributeFirst $Context ([string]$Payload.DN) $name
    if($null -eq $current){$preCurrent[$name]=@()}else{$preCurrent[$name]=@([string]$current)}
}
if($preChanges.Count -gt 0){
    $pre=Test-DomeniaPreconditionCurrent -Changes @($preChanges.ToArray()) -Current $preCurrent -Server ([string]$Context.Server)
    if(-not [bool]$pre.Current){throw [string]$pre.Text}
}
$hasConditional=$false
foreach($c in @($Payload.Changes)){if([bool]$c.Conditional){$hasConditional=$true;break}}
if($hasConditional){
    $mods=New-Object Collections.ArrayList
    foreach($c in @($Payload.Changes)){
        if($null -eq $c){continue}
        $name=[string]$c.Name
        if([string]::IsNullOrWhiteSpace($name)){continue}
        if([bool]$c.Conditional){
            $old=[string]$c.Old
            $new=''
            if(-not [bool]$c.Clear){$new=[string]$c.New}
            if(-not [string]::IsNullOrEmpty($old)){[void]$mods.Add([pscustomobject]@{Name=$name;Op='Delete';Value=$old})}
            if(-not [string]::IsNullOrEmpty($new)){[void]$mods.Add([pscustomobject]@{Name=$name;Op='Add';Value=$new})}
        }else{
            if([bool]$c.Clear){[void]$mods.Add([pscustomobject]@{Name=$name;Op='Clear';Value=''})}
            else{[void]$mods.Add([pscustomobject]@{Name=$name;Op='Replace';Value=[string]$c.New})}
        }
    }
    if($mods.Count -eq 0){
        $backend="Conditional"
        $SentUtc=""
    }else{
        $SentUtc=[DateTime]::UtcNow.ToString('o')
        $DomeniaWriteDispatched=$true
        $res=Invoke-WConditionalModify $Context ([string]$Payload.DN) @($mods.ToArray())
        $ldapCode=-1
        if($null -ne $res){
            $ldapCodeText=[string]$res.ResultCode
            if(-not [int]::TryParse($ldapCodeText,[ref]$ldapCode)){$ldapCode=-1}
        }
        if(($null -ne $res) -and (-not [bool]$res.Sent) -and ($ldapCode -ne 0)){
            $DomeniaWriteDispatched=$false
            $notSentText="Requete non envoyee au controleur (code LDAP $ldapCode) : rien n a ete applique. $([string]$res.Message)"
            # Keep the bind failure classifiable like the ADSI path: 49 = logon failure, 81 = directory server down.
            if($ldapCode -eq 49){throw [Runtime.InteropServices.COMException]::new($notSentText,-2147023570)}
            if($ldapCode -eq 81){throw [Runtime.InteropServices.COMException]::new($notSentText,-2147016646)}
            throw $notSentText
        }
        # SE-09: the controller answer is read by the shared rule Resolve-DomeniaConditionalWrite. 0: applied.
        # 1-80: refused by the controller, nothing applied (16, 19, 20: changed elsewhere, nothing overwritten).
        # No answer, or a client-side code from 81 up: the write may have applied; the receipt stays to verify
        # (the dispatch flag stays set) and nothing is ever retried.
        $answer=Resolve-DomeniaConditionalWrite -Strategy ([pscustomobject]@{Strategy='ConditionalReplace'}) -ResultCode $ldapCode
        $controllerText=''
        if($null -ne $res){$controllerText=[string]$res.Message}
        $outcome=[string]$answer.Outcome
        if($outcome -eq 'Applied'){
            $backend="Conditional"
        }elseif($outcome -eq 'Conflict'){
            $DomeniaWriteDispatched=$false
            throw ('Conflit (code LDAP '+$ldapCode+') : '+[string]$answer.Text+' '+$controllerText)
        }elseif($outcome -eq 'Error'){
            $DomeniaWriteDispatched=$false
            if($ldapCode -eq 50){throw [UnauthorizedAccessException]::new(('Acces refuse par le controleur. '+[string]$answer.Text+' '+$controllerText))}
            throw ([string]$answer.Text+' '+$controllerText)
        }else{
            throw ([string]$answer.Text+' '+$controllerText)
        }
    }
}else{
$backend=Get-WWriteBackend $Context @("Set-ADObject")
$replace=@{};$clear=New-Object Collections.ArrayList
foreach($c in @($Payload.Changes)){if([bool]$c.Clear){[void]$clear.Add([string]$c.Name)}else{$replace[[string]$c.Name]=[string]$c.New}}
$SentUtc=""
if($backend -eq "Module"){
    $p=@{Identity=[string]$Payload.DN;ErrorAction="Stop"}
    if($Context.Server){$p.Server=[string]$Context.Server}
    $cred=Get-WAdCredential $Context;if($cred){$p.Credential=$cred}
    if($replace.Count -gt 0){$p.Replace=$replace}
    if($clear.Count -gt 0){$p.Clear=@($clear)}
    $SentUtc=[DateTime]::UtcNow.ToString('o')
    $DomeniaWriteDispatched=$true
    Set-ADObject @p
}else{
    $de=New-WEntry $Context ([string]$Payload.DN)
    foreach($c in @($Payload.Changes)){if([bool]$c.Clear){$de.Properties[[string]$c.Name].Clear()}else{$de.Properties[[string]$c.Name].Value=[string]$c.New}}
    $SentUtc=[DateTime]::UtcNow.ToString('o')
    $DomeniaWriteDispatched=$true
    $de.CommitChanges()
}
}
$failed=New-Object Collections.ArrayList
$expectedValues=@{}
$observedValues=@{}
foreach($c in @($Payload.Changes)){
    $name=[string]$c.Name
    $expectedValue=""
    if([bool]$c.Clear){$expectedValue=""}else{$expectedValue=[string]$c.New}
    $expectedValues[$name]=$expectedValue
    $actual=Get-WAttributeFirst $Context ([string]$Payload.DN) $name
    if([bool]$c.Clear){
        if($null -ne $actual -and -not [string]::IsNullOrWhiteSpace([string]$actual)){$observedValues[$name]=[string]$actual}else{$observedValues[$name]=$null}
        if($null -ne $actual -and -not [string]::IsNullOrWhiteSpace([string]$actual)){[void]$failed.Add("$name non efface")}
    }else{
        if($null -eq $actual){$observedValues[$name]=$null}else{$observedValues[$name]=[string]$actual}
        if(-not [string]::Equals([string]$actual,[string]$c.New,[StringComparison]::Ordinal)){[void]$failed.Add("$name attendu [$($c.New)] obtenu [$actual]")}
    }
}
if($failed.Count -gt 0){throw "Verification post-ecriture echouee : $($failed -join ' ; ')"}
$after=Get-WObjectSnapshot $Context ([string]$Payload.DN)
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message="$(@($Payload.Changes).Count) attribut(s) modifie(s) et verifie(s).";Before=$before;After=$after;Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=[pscustomobject]@{Server=[string]$Context.Server;Values=$expectedValues};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Values=$observedValues}}}
'@
    # UX-08: confirmed in the page; the write leaves from the continuation, with the plan confirmed here.
    $state = [pscustomobject]@{ Name=$OperationName; Code=$code; Payload=$payload; Plan=$plan; Changes=$clean; Capability=$Capability; DisableControls=@($DisableControls); AfterSuccessAction=$AfterSuccessAction; AfterSuccessState=$AfterSuccessState }
    $send = {
        param($s)
        Start-DomeniaWriteTask -Name $s.Name -OperationId "WriteAttributes" -Code $s.Code -Payload $s.Payload -Plan $s.Plan -PlanChanges $s.Changes -Capability $s.Capability -DisableControls $s.DisableControls -AfterSuccessAction $s.AfterSuccessAction -AfterSuccessState $s.AfterSuccessState
    }
    $message = 'Seules les valeurs ci-dessous sont envoyées à lʼannuaire pour « ' + [string]$plan.Target.Name + ' ».'
    $risk = 'Normal'
    if ($RawEdit) {
        $message = 'Écriture brute sur « ' + [string]$plan.Target.Name + ' » : la valeur est envoyée telle quelle, sans contrôle de forme.'
        $risk = 'Danger'
    }
    [void](Request-DomeniaWriteConfirmation -Plan $plan -Title $OperationName -Message $message -ConfirmText 'Enregistrer' -Risk $risk -TypedConfirmation $TypedConfirmation -Send $send -State $state)
}

function Get-DomeniaFicheEditControls {
    # Les champs que la fiche d un objet ouvre en edition. Les coordonnees comptent avec l
    # utilisateur : un seul crayon mene les deux onglets, sinon la moitie de la fiche resterait
    # verrouillee pendant que l autre se saisit.
    param([string]$Type)
    $carte = $script:FicheEditChamps
    if ($null -eq $carte) { return @() }
    if ($Type -eq 'Utilisateur') { return @($carte['Utilisateur']) + @($carte['Coordonnees']) }
    if ($Type -eq 'Machine') { return @($carte['Machine']) }
    return @()
}

function Get-DomeniaFicheDirtyControls {
    # Un champ est modifie quand son texte differe de ce que l annuaire a repondu, a la casse pres
    # sur les noms : « jeaan » et « Jean » ne sont pas la meme saisie pour un operateur.
    # P-CD-09: a comparison that fails is not "nothing changed": FicheEdit.DirtyUnknown tells the fiche and the
    # abandon notice that the modified fields are not known.
    param([string]$Type)
    $sortie = New-Object System.Collections.Generic.List[string]
    $inconnu = $false
    try {
        foreach ($nom in (Get-DomeniaFicheEditControls -Type $Type)) {
            $c = Get-DomeniaControl -Name $nom
            if ($null -eq $c) { continue }
            $avant = [string]$script:FicheEdit['Originaux'][$nom]
            if (-not [string]::Equals([string]$c.Text, $avant, [System.StringComparison]::Ordinal)) {
                [void]$sortie.Add($nom)
            }
        }
    } catch { $inconnu = $true; Write-DomeniaSwallowed 'Core' 'Get-DomeniaFicheDirtyControls' $_ }
    try { $script:FicheEdit['DirtyUnknown'] = $inconnu } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaFicheDirtyControls' $_ }
    return $sortie.ToArray()
}

function Set-DomeniaFicheFieldLock {
    # Verrouille = saisie fermee et fond de lecture seule. En edition = saisie ouverte, et le
    # champ qui a bouge prend le fond d accent : la difference se voit sans relire la fiche.
    param([string]$Type, [bool]$Edition, [string[]]$Modifies = @())
    $fond = $null
    $alerte = $null
    try {
        $source = Get-DomeniaControl -Name 'TxtUserDisplayName'
        if ($null -ne $source) {
            $fond = $source.TryFindResource('BgReadonly')
            $alerte = $source.TryFindResource('AccentSoft')
        }
    } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaFicheFieldLock' $_ }
    foreach ($nom in (Get-DomeniaFicheEditControls -Type $Type)) {
        $c = Get-DomeniaControl -Name $nom
        if ($null -eq $c) { continue }
        try {
            $c.IsReadOnly = (-not $Edition)
            if ($Edition -and @($Modifies) -contains $nom) {
                if ($null -ne $alerte) { $c.Background = $alerte }
            } else {
                # ClearValue, pas $null : $null laisserait un fond local qui ecrase le style.
                [void]$c.ClearValue([System.Windows.Controls.Control]::BackgroundProperty)
                if ((-not $Edition) -and ($null -ne $fond)) { $c.Background = $fond }
            }
        } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaFicheFieldLock' $_ }
    }
}

function Update-DomeniaFicheEditUi {
    # Un seul endroit decide de ce que la fiche montre : verrouillee, en edition, ou en alerte.
    param([string]$Type)
    try {
        if ([string]::IsNullOrWhiteSpace($Type)) { $Type = [string]$script:FicheEdit["Type"] }
        if ([string]::IsNullOrWhiteSpace($Type)) { return }
        $modifies = @(Get-DomeniaFicheDirtyControls -Type $Type)
        $edition = [bool]$script:FicheEdit["Edition"]
        Set-DomeniaFicheFieldLock -Type $Type -Edition $edition -Modifies ([string[]]$modifies)
        $nomAlerte = if ($Type -eq 'Machine') { 'LblCompEditState' } else { 'LblUserEditState' }
        $alerte = Get-DomeniaControl -Name $nomAlerte
        $nomCrayon = if ($Type -eq 'Machine') { 'BtnCompEdit' } else { 'BtnUserEdit' }
        $nomAnnuler = if ($Type -eq 'Machine') { 'BtnCompCancelEdit' } else { 'BtnUserCancelEdit' }
        $crayon = Get-DomeniaControl -Name $nomCrayon
        $annuler = Get-DomeniaControl -Name $nomAnnuler
        if ($null -ne $crayon) {
            $crayon.Visibility = if ($edition) { [System.Windows.Visibility]::Collapsed }
            else { [System.Windows.Visibility]::Visible }
        }
        if ($null -ne $annuler) {
            $annuler.Visibility = if ($edition) { [System.Windows.Visibility]::Visible }
            else { [System.Windows.Visibility]::Collapsed }
        }
        if ($null -eq $alerte) { return }
        $texte = ""
        if ($edition) {
            $texte = "Mode modification : " + [string]$modifies.Count + " champ(s) changes. Rien ne partira dans lʼannuaire avant Enregistrer."
            if ([bool]$script:FicheEdit["DirtyUnknown"]) { $texte = "Mode modification : comparaison avec la fiche lue impossible, les champs changés ne sont pas connus. Rien ne partira dans lʼannuaire avant Enregistrer." }
        }
        elseif (-not [string]::IsNullOrWhiteSpace([string]$script:FicheEdit["Abandon"])) {
            $texte = [string]$script:FicheEdit["Abandon"]
            $script:FicheEdit["Abandon"] = ""
        }
        if ([string]::IsNullOrWhiteSpace($texte)) {
            $alerte.Visibility = [System.Windows.Visibility]::Collapsed
        } else {
            $alerte.Text = $texte
            $alerte.Visibility = [System.Windows.Visibility]::Visible
        }
    } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaFicheEditUi' $_ }
}

function Start-DomeniaFicheEdit {
    # Le crayon. Il n ecrit rien et ne demande rien a l annuaire : il ouvre la saisie.
    param([string]$Type)
    try {
        if ($script:ReadOnlyMode) {
            Set-Status "La fiche reste verrouillée : la lecture seule est active." "WARN"
            return
        }
        if ($null -eq $script:SelectedObject) { return }
        $script:FicheEdit["Edition"] = $true
        $script:FicheEdit["Type"] = $Type
        $script:FicheEdit["Abandon"] = ""
        Update-DomeniaFicheEditUi -Type $Type
        Set-Status "Mode modification : les champs de la fiche sont ouverts, Annuler les reprend tels quʼils ont été lus."
    }
    catch { Show-ErrorBox "Mode modification indisponible : $($_.Exception.Message)" }
}

function Stop-DomeniaFicheEdit {
    # Le crayon se rouvre par Annuler, qui remet chaque champ a la valeur lue. Abandon sert quand
    # c est le changement d objet qui ferme la fiche : le message sera montre sur la fiche suivante.
    param([string]$Type, [switch]$Restaurer, [string]$Abandon = "")
    try {
        if ([string]::IsNullOrWhiteSpace($Type)) { $Type = [string]$script:FicheEdit["Type"] }
        if ($Restaurer) {
            foreach ($nom in (Get-DomeniaFicheEditControls -Type $Type)) {
                $c = Get-DomeniaControl -Name $nom
                if ($null -eq $c) { continue }
                $avant = [string]$script:FicheEdit['Originaux'][$nom]
                if (-not [string]::Equals([string]$c.Text, $avant, [System.StringComparison]::Ordinal)) {
                    $c.Text = $avant
                }
            }
        }
        $script:FicheEdit["Edition"] = $false
        if (-not [string]::IsNullOrWhiteSpace($Abandon)) { $script:FicheEdit["Abandon"] = $Abandon }
        Update-DomeniaFicheEditUi -Type $Type
    } catch { Write-DomeniaSwallowed 'Core' 'Stop-DomeniaFicheEdit' $_ }
}

function Snapshot-DomeniaFicheEdit {
    # Apres un remplissage, ce que l annuaire a repondu devient la reference des differences.
    # Une relecture du meme objet n est pas un abandon : le message en attente est purge.
    param([string]$Type)
    try {
        $dn = ""
        try { $dn = [string]$script:SelectedObject.DN } catch { Write-DomeniaSwallowed 'Core' 'Snapshot-DomeniaFicheEdit' $_ }
        if ((-not [string]::IsNullOrWhiteSpace($dn)) -and $dn -ceq [string]$script:FicheEdit["Dn"]) {
            $script:FicheEdit["Abandon"] = ""
        }
        $script:FicheEdit["Type"] = $Type
        $script:FicheEdit["Dn"] = $dn
        $orig = @{}
        foreach ($nom in (Get-DomeniaFicheEditControls -Type $Type)) {
            $c = Get-DomeniaControl -Name $nom
            if ($null -ne $c) { $orig[$nom] = [string]$c.Text }
        }
        $script:FicheEdit["Originaux"] = $orig
        Update-DomeniaFicheEditUi -Type $Type
    } catch { Write-DomeniaSwallowed 'Core' 'Snapshot-DomeniaFicheEdit' $_ }
}

function Register-DomeniaFicheEditWatch {
    # Une sonde par champ, posee a la construction : chaque frappe reevalue ce qui est modifie.
    try {
        foreach ($Type in @('Utilisateur','Machine')) {
            foreach ($nom in (Get-DomeniaFicheEditControls -Type $Type)) {
                $c = Get-DomeniaControl -Name $nom
                if ($null -eq $c) { continue }
                try { $c.Add_TextChanged({ Update-DomeniaFicheEditUi }) } catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaFicheEditWatch' $_ }
            }
        }
        Update-DomeniaFicheEditUi -Type 'Utilisateur'
        Update-DomeniaFicheEditUi -Type 'Machine'
    } catch { Write-DomeniaSwallowed 'Core' 'Register-DomeniaFicheEditWatch' $_ }
}

