function Set-AccountDisabled {
    param([bool]$Disabled)
    try {
        if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -notin @("Utilisateur","Machine")) { return }
        $oldUac=0; [void][int]::TryParse((Get-DomeniaOriginalValue "userAccountControl"),[ref]$oldUac)
        $beforeState = if ((($oldUac -band 2) -ne 0)) { "Desactive" } else { "Active" }
        $afterState = if ($Disabled) { "Desactive" } else { "Active" }
        $changes = @([pscustomobject]@{ Attribute="userAccountControl"; Kind="Replace"; Before=$beforeState; After=$afterState })
        try { $plan = New-DomeniaSelectionWritePlan -OperationId "WriteAccountDisabled" -Changes $changes -Effects @() } catch { Show-ErrorBox $_.Exception.Message; return }
        try { $safety = Get-DomeniaSafetyDescriptor } catch { Show-ErrorBox $_.Exception.Message; return }
        $action=if($Disabled){"Desactiver"}else{"Activer"}
        $payload=[pscustomobject]@{DN=[string]$plan.Target.DN;Disabled=$Disabled;Safety=$safety}
        $code=@'
$before=Assert-WObjectFresh $Context $Payload.Safety
$currentDisabled=(([int]$before.Uac -band 2) -ne 0)
if($currentDisabled -eq [bool]$Payload.Disabled){
    $ReadUtc=[DateTime]::UtcNow.ToString('o')
    [pscustomobject]@{Verified=$true;Backend="None";Message="Etat deja conforme. Aucune ecriture AD.";Before=$before;After=$before;Postcondition=[pscustomobject]@{SentUtc="";Expected=[pscustomobject]@{Server=[string]$Context.Server;Flags=[pscustomobject]@{Disabled=[string][bool]$Payload.Disabled}};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Flags=[pscustomobject]@{Disabled=[string]((([int]$before.Uac) -band 2) -ne 0)}}}};return}
$command=if([bool]$Payload.Disabled){"Disable-ADAccount"}else{"Enable-ADAccount"};$backend=Get-WWriteBackend $Context @($command)
$SentUtc=""
if($backend -eq "Module"){
    $p=@{Identity=[string]$Payload.DN;Confirm=$false;ErrorAction="Stop"};if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c}
    $SentUtc=[DateTime]::UtcNow.ToString('o')
    $DomeniaWriteDispatched=$true
    if([bool]$Payload.Disabled){Disable-ADAccount @p}else{Enable-ADAccount @p}
}else{
    $de=New-WEntry $Context ([string]$Payload.DN);$u=[int]$de.Properties["userAccountControl"].Value
    if([bool]$Payload.Disabled){$u=$u -bor 2}else{$u=$u -band (-bnot 2)}
    $de.Properties["userAccountControl"].Value=$u;$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;$de.CommitChanges()
}
$after=Get-WObjectSnapshot $Context ([string]$Payload.DN)
$actual=(([int]$after.Uac -band 2) -ne 0)
if($actual -ne [bool]$Payload.Disabled){throw "Verification post-ecriture : etat Enabled/Disabled non conforme."}
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message=$(if([bool]$Payload.Disabled){"Compte desactive et verifie."}else{"Compte active et verifie."});Before=$before;After=$after;Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=[pscustomobject]@{Server=[string]$Context.Server;Flags=[pscustomobject]@{Disabled=[string][bool]$Payload.Disabled}};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Flags=[pscustomobject]@{Disabled=[string]((([int]$after.Uac) -band 2) -ne 0)}}}}
'@
        $state=[pscustomobject]@{Name="$action compte";Code=$code;Payload=$payload;Plan=$plan;Changes=$changes}
        $send={
            param($s)
            try { Start-DomeniaWriteTask -Name $s.Name -OperationId "WriteAccountDisabled" -Code $s.Code -Payload $s.Payload -Plan $s.Plan -PlanChanges $s.Changes -Capability "Account" -DisableControls @("BtnUserEnable","BtnUserDisable","BtnCompEnable","BtnCompDisable") -AfterSuccessAction "RefreshObjectBranch" }
            catch { Show-ErrorBox "Changement dʼétat du compte impossible : $($_.Exception.Message)" }
        }
        $who=[string]$plan.Target.Name
        if($Disabled){[void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Désactiver le compte' -Message ('« '+$who+' » ne pourra plus ouvrir de session tant que le compte reste désactivé.') -ConfirmText 'Désactiver' -Risk Danger -Send $send -State $state)}
        else{[void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Activer le compte' -Message ('« '+$who+' » pourra de nouveau ouvrir une session.') -ConfirmText 'Activer' -Send $send -State $state)}
    } catch { Show-ErrorBox "Erreur état du compte : $($_.Exception.Message)" }
}

function Unlock-UserAccount {
    try {
        if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Utilisateur") { return }
        $changes = @([pscustomobject]@{ Attribute="lockoutTime"; Kind="Clear"; Before=(Get-DomeniaOriginalValue "lockoutTime"); After="" })
        try { $plan = New-DomeniaSelectionWritePlan -OperationId "WriteUnlock" -Changes $changes -Effects @() } catch { Show-ErrorBox $_.Exception.Message; return }
        try { $safety = Get-DomeniaSafetyDescriptor } catch { Show-ErrorBox $_.Exception.Message; return }
        $payload=[pscustomobject]@{DN=[string]$plan.Target.DN;Safety=$safety}
        $code=@'
$before=Assert-WObjectFresh $Context $Payload.Safety
if([int64]$before.Lockout -eq 0){
    $ReadUtc=[DateTime]::UtcNow.ToString('o')
    [pscustomobject]@{Verified=$true;Backend="None";Message="Compte deja deverrouille. Aucune ecriture AD.";Before=$before;After=$before;Postcondition=[pscustomobject]@{SentUtc="";Expected=[pscustomobject]@{Server=[string]$Context.Server;Flags=[pscustomobject]@{Locked="False"}};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Flags=[pscustomobject]@{Locked=[string](([int64]$before.Lockout) -ne 0)}}}};return}
$backend=Get-WWriteBackend $Context @("Unlock-ADAccount")
$SentUtc=""
if($backend -eq "Module"){$p=@{Identity=[string]$Payload.DN;ErrorAction="Stop"};if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c};$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;Unlock-ADAccount @p}
else{$de=New-WEntry $Context ([string]$Payload.DN);$de.Properties["lockoutTime"].Value=0;$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;$de.CommitChanges()}
$after=Get-WObjectSnapshot $Context ([string]$Payload.DN)
if([int64]$after.Lockout -ne 0){throw "Le compte reste verrouille apres l operation."}
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message="Compte utilisateur deverrouille et verifie.";Before=$before;After=$after;Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=[pscustomobject]@{Server=[string]$Context.Server;Flags=[pscustomobject]@{Locked="False"}};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Flags=[pscustomobject]@{Locked=[string](([int64]$after.Lockout) -ne 0)}}}}
'@
        Start-DomeniaWriteTask -Name "Deverrouillage utilisateur" -OperationId "WriteUnlock" -Code $code -Payload $payload -Plan $plan -PlanChanges $changes -Capability "Account" -DisableControls @("BtnUserUnlock") -AfterSuccessAction "RefreshObject"
    } catch { Show-ErrorBox "Erreur deverrouillage : $($_.Exception.Message)" }
}

function Get-DomeniaRandomBelow {
    # Un secret ne se tire pas dans Random-Object : quatre octets forts, reduits par modulo.
    param([Parameter(Mandatory=$true)]$Rng,[Parameter(Mandatory=$true)][ValidateRange(1,2147483647)][int]$Maximum)
    $buffer = New-Object byte[] 4
    [void]$Rng.GetBytes($buffer)
    $value = [int64]$buffer[0] * 16777216 + [int64]$buffer[1] * 65536 + [int64]$buffer[2] * 256 + [int64]$buffer[3]
    return [int]($value % $Maximum)
}

function New-DomeniaTemporaryPassword {
    # UX-36 : quatre classes obligatoires et aucun caractere ambigu (ni 0/O, ni 1/l/I), car le mot de
    # passe se dicte au telephone. Le melange final empeche les quatre premiers de se ressembler.
    param([int]$Length = 16)
    if ($Length -lt 14) { $Length = 14 }
    if ($Length -gt 64) { $Length = 64 }
    $classes = @('ABCDEFGHJKLMNPQRSTUVWXYZ','abcdefghijkmnopqrstuvwxyz','23456789','!@#$%^&*()-_=+')
    $alphabet = ($classes -join '')
    $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    try {
        $chosen = New-Object 'System.Collections.Generic.List[char]'
        foreach ($set in $classes) { $chosen.Add($set[(Get-DomeniaRandomBelow -Rng $rng -Maximum $set.Length)]) }
        while ($chosen.Count -lt $Length) { $chosen.Add($alphabet[(Get-DomeniaRandomBelow -Rng $rng -Maximum $alphabet.Length)]) }
        for ($i = $chosen.Count - 1; $i -gt 0; $i--) {
            $j = Get-DomeniaRandomBelow -Rng $rng -Maximum ($i + 1)
            $tmp = $chosen[$i]; $chosen[$i] = $chosen[$j]; $chosen[$j] = $tmp
        }
        return (-join $chosen.ToArray())
    } finally { try { $rng.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'New-DomeniaTemporaryPassword' $_ } }
}

function Show-DomeniaGeneratedPassword {
    # UX-36 : le mot de passe genere entre par les champs existants, pour que la revelation, la
    # confirmation et la relecture a l enregistrement (UX-08) restent le seul chemin vers l ecriture.
    $mot = ''
    try {
        Assert-WriteAllowed
        if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Utilisateur") { return }
        $longueur = 16
        try { $longueur = [int](Get-CfgValue "Security" "GeneratedPasswordLength" 16) } catch { Write-DomeniaSwallowed 'Core' 'Show-DomeniaGeneratedPassword' $_ }
        $mot = New-DomeniaTemporaryPassword -Length $longueur
        $script:Ctrl["PwdUserNew"].Password = $mot
        $script:Ctrl["PwdUserConfirm"].Password = $mot
        # Il doit se lire une fois a l ecran, le temps de le noter ou de le dicter.
        if (-not [bool](Get-Variable -Name '__UserNewReveal' -Scope Script -ValueOnly -ErrorAction SilentlyContinue)) {
            Toggle-PasswordBox "PwdUserNew" "TxtUserNewVisible" "BtnRevealUserNew" "__UserNewReveal"
        }
        if (-not [bool](Get-Variable -Name '__UserConfirmReveal' -Scope Script -ValueOnly -ErrorAction SilentlyContinue)) {
            Toggle-PasswordBox "PwdUserConfirm" "TxtUserConfirmVisible" "BtnRevealUserConfirm" "__UserConfirmReveal"
        }
        Set-ClipboardSafe $mot
        Start-SecretClipboardAutoClear $mot
        $script:Ctrl["ChkMustChangeAtLogon"].IsChecked = $true
        Set-Status ('Mot de passe temporaire généré (' + [string]$mot.Length + ' caractères, quatre classes) et copié dans le presse-papiers. L' + [string][char]0x02BC + 'utilisateur devra le changer à sa prochaine ouverture de session.')
    }
    catch { Show-ErrorBox "Génération du mot de passe impossible : $($_.Exception.Message)" }
    finally { $mot = $null }
}

function Reset-UserPassword {
    try {
        if ($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Utilisateur") { return }
        $pw=Get-PasswordPair
        if([string]::IsNullOrWhiteSpace([string]$pw.New)){throw "Nouveau mot de passe vide."}
        if([string]$pw.New -ne [string]$pw.Confirm){throw "Confirmation differente."}
        $mustChange=[bool]$script:Ctrl["ChkMustChangeAtLogon"].IsChecked
        $changes = @([pscustomobject]@{ Attribute="unicodePwd"; Kind="Reset"; Before=""; After="nouveau mot de passe" })
        if ($mustChange) { $changes = @($changes + [pscustomobject]@{ Attribute="pwdLastSet"; Kind="Replace"; Before=(Get-DomeniaOriginalValue "pwdLastSet"); After="0" }) }
        try { $plan = New-DomeniaSelectionWritePlan -OperationId "WriteResetPassword" -Changes $changes -Effects @() } catch { Show-ErrorBox $_.Exception.Message; return }
        try { $safety = Get-DomeniaSafetyDescriptor } catch { Show-ErrorBox $_.Exception.Message; return }
        # UX-08: no password is kept while the confirmation waits in the page; it is read again from the fields when
        # the operator confirms, then the fields are cleared.
        $pw = $null
        $unlockAfter=[bool]$script:Ctrl["ChkUnlockAfterReset"].IsChecked
        $code=@'
$before=Assert-WObjectFresh $Context $Payload.Safety
$PreviousUtc=$null
$previousRaw=$null
try { $previousRaw=Get-WAttributeFirst $Context ([string]$Payload.DN) "pwdLastSet" } catch { }
if($null -ne $previousRaw){
    $previousTicks=Convert-WLargeInteger $previousRaw
    if($previousTicks -gt 0){ try { $PreviousUtc=[DateTime]::FromFileTimeUtc([int64]$previousTicks).ToString('o') } catch { $PreviousUtc=$null } }
}
$required=New-Object Collections.ArrayList;[void]$required.Add("Set-ADAccountPassword");if([bool]$Payload.Unlock){[void]$required.Add("Unlock-ADAccount")};if([bool]$Payload.MustChange){[void]$required.Add("Set-ADUser")}
$backend=Get-WWriteBackend $Context @($required)
$steps=New-Object Collections.ArrayList
$SentUtc=""
$PwdLastSetUtc=$null
$PwdReadStatus="OK"
if($backend -eq "Module"){
    $base=@{Identity=[string]$Payload.DN;ErrorAction="Stop"};if($Context.Server){$base.Server=[string]$Context.Server};$cred=Get-WAdCredential $Context;if($cred){$base.Credential=$cred}
    $p=@{};foreach($k in $base.Keys){$p[$k]=$base[$k]};$p.Reset=$true;$p.NewPassword=[System.Security.SecureString]$Payload.SecurePassword
    $SentUtc=[DateTime]::UtcNow.ToString('o')
    $DomeniaWriteDispatched=$true
    Set-ADAccountPassword @p;[void]$steps.Add("mot de passe reinitialise")
    $pwdRaw=$null
    try { $pwdRaw=Get-WAttributeFirst $Context ([string]$Payload.DN) "pwdLastSet" } catch { $PwdReadStatus="Unavailable" }
    if($PwdReadStatus -eq "OK" -and $null -ne $pwdRaw){
        $pwdTicks=Convert-WLargeInteger $pwdRaw
        if($pwdTicks -gt 0){ try { $PwdLastSetUtc=[DateTime]::FromFileTimeUtc([int64]$pwdTicks).ToString('o') } catch { $PwdLastSetUtc=$null } }
    }
    if([bool]$Payload.Unlock){try{Unlock-ADAccount @base;[void]$steps.Add("compte deverrouille")}catch{[void]$steps.Add("deverrouillage en echec : $($_.Exception.Message)")}}
    if([bool]$Payload.MustChange){try{$u=@{};foreach($k in $base.Keys){$u[$k]=$base[$k]};$u.ChangePasswordAtLogon=$true;Set-ADUser @u;[void]$steps.Add("changement impose au prochain logon")}catch{[void]$steps.Add("option prochain logon en echec : $($_.Exception.Message)")}}
}else{
    $de=New-WEntry $Context ([string]$Payload.DN)
    # SE-16: the new password becomes a String only for the ADSI SetPassword call. That String is immutable and stays
    # in memory until the garbage collector reclaims it; no assignment erases it, the finally block only drops this
    # reference. It is never logged nor returned.
    $plainPassword=$null
    try {
        $plainPassword=[System.Net.NetworkCredential]::new("",[System.Security.SecureString]$Payload.SecurePassword).Password
        $SentUtc=[DateTime]::UtcNow.ToString('o')
        $DomeniaWriteDispatched=$true
        $de.Invoke("SetPassword",$plainPassword)|Out-Null;[void]$steps.Add("mot de passe reinitialise")
        $pwdRaw=$null
        try { $pwdRaw=Get-WAttributeFirst $Context ([string]$Payload.DN) "pwdLastSet" } catch { $PwdReadStatus="Unavailable" }
        if($PwdReadStatus -eq "OK" -and $null -ne $pwdRaw){
            $pwdTicks=Convert-WLargeInteger $pwdRaw
            if($pwdTicks -gt 0){ try { $PwdLastSetUtc=[DateTime]::FromFileTimeUtc([int64]$pwdTicks).ToString('o') } catch { $PwdLastSetUtc=$null } }
        }
    }
    finally { $plainPassword=$null }
    if([bool]$Payload.Unlock){try{$de.Properties["lockoutTime"].Value=0;[void]$steps.Add("compte deverrouille")}catch{[void]$steps.Add("deverrouillage en echec : $($_.Exception.Message)")}}
    if([bool]$Payload.MustChange){try{$de.Properties["pwdLastSet"].Value=0;[void]$steps.Add("changement impose au prochain logon")}catch{[void]$steps.Add("option prochain logon en echec : $($_.Exception.Message)")}}
    $de.CommitChanges()
}
$after=Get-WObjectSnapshot $Context ([string]$Payload.DN)
if(-not [bool]$after.Exists){throw "Objet introuvable apres le reset."}
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message=("Reset accepte par le DC ; "+($steps -join " ; "));Before=$before;After=$after;Partial=(@($steps|Where-Object{$_ -match "echec"}).Count -gt 0);Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=[pscustomobject]@{Server=[string]$Context.Server;PreviousUtc=$PreviousUtc};Observed=[pscustomobject]@{ReadStatus=$PwdReadStatus;Server=[string]$Context.Server;ReadUtc=$ReadUtc;PwdLastSetUtc=$PwdLastSetUtc}}}
'@
        $state=[pscustomobject]@{Code=$code;Plan=$plan;Changes=$changes;Safety=$safety;Unlock=$unlockAfter;MustChange=$mustChange}
        $send={
            param($s)
            try {
                $pair=Get-PasswordPair
                if([string]::IsNullOrWhiteSpace([string]$pair.New)){throw "Nouveau mot de passe vide."}
                if([string]$pair.New -ne [string]$pair.Confirm){throw "Confirmation differente."}
                $securePassword = ConvertTo-DomeniaSecureString -Text ([string]$pair.New)
                $pair = $null
                $payload=[pscustomobject]@{DN=[string]$s.Plan.Target.DN;SecurePassword=$securePassword;Unlock=[bool]$s.Unlock;MustChange=[bool]$s.MustChange;Safety=$s.Safety}
                foreach ($controlName in @("PwdUserNew","PwdUserConfirm")) { try { $script:Ctrl[$controlName].Password = "" } catch { Write-DomeniaSwallowed 'Core' 'Reset-UserPassword' $_ } }
                foreach ($controlName in @("TxtUserNewVisible","TxtUserConfirmVisible")) { try { $script:Ctrl[$controlName].Text = "" } catch { Write-DomeniaSwallowed 'Core' 'Reset-UserPassword' $_ } }
                Start-DomeniaWriteTask -Name "Reset mot de passe" -OperationId "WriteResetPassword" -Code $s.Code -Payload $payload -Plan $s.Plan -PlanChanges $s.Changes -Capability "Password" -DisableControls @("BtnUserResetPwd") -AfterSuccessAction "ResetPassword"
                $securePassword = $null
            } catch { Show-ErrorBox "Erreur reset mot de passe : $($_.Exception.Message)" }
        }
        $extra=@()
        if($unlockAfter){$extra+='Compte : déverrouillé après la réinitialisation'}
        $lines=@(@(Get-DomeniaPlanChangeText -Changes @($plan.Changes))+$extra)
        [void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Réinitialiser le mot de passe' -Message ('Le mot de passe saisi remplace celui de « '+[string]$plan.Target.Name+' ». Il nʼest ni journalisé ni conservé.') -ConfirmText 'Réinitialiser' -Risk Danger -Changes $lines -Send $send -State $state)
    } catch { Show-ErrorBox "Erreur reset mot de passe : $($_.Exception.Message)" }
}

function Apply-UserAccountOptions {
    try {
        if($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Utilisateur"){return}
        $oldUac=0;[void][int]::TryParse((Get-DomeniaOriginalValue "userAccountControl"),[ref]$oldUac)
        $options=[ordered]@{
            PasswordNeverExpires=[bool]$script:Ctrl["ChkPwdNeverExpires"].IsChecked
            PasswordNotRequired=[bool]$script:Ctrl["ChkPwdNotRequired"].IsChecked
            AllowReversiblePasswordEncryption=[bool]$script:Ctrl["ChkReversiblePwd"].IsChecked
            SmartcardLogonRequired=[bool]$script:Ctrl["ChkSmartcardRequired"].IsChecked
            AccountNotDelegated=[bool]$script:Ctrl["ChkAccountNotDelegated"].IsChecked
            DoesNotRequirePreAuth=[bool]$script:Ctrl["ChkNoPreAuth"].IsChecked
            UseDESKeyOnly=[bool]$script:Ctrl["ChkUseDesOnly"].IsChecked
            TrustedForDelegation=[bool]$script:Ctrl["ChkTrustedForDelegation"].IsChecked
            TrustedToAuthForDelegation=[bool]$script:Ctrl["ChkTrustedToAuthDelegation"].IsChecked
        }
        $masks=[ordered]@{PasswordNeverExpires=65536;PasswordNotRequired=32;AllowReversiblePasswordEncryption=128;SmartcardLogonRequired=262144;AccountNotDelegated=1048576;DoesNotRequirePreAuth=4194304;UseDESKeyOnly=2097152;TrustedForDelegation=524288;TrustedToAuthForDelegation=16777216}
        $target=$oldUac;$changed=New-Object Collections.ArrayList;$planChanges=New-Object Collections.ArrayList;$highRisk=$false
        foreach($k in $options.Keys){$old=(($oldUac -band [int]$masks[$k]) -ne 0);$new=[bool]$options[$k];if($old -ne $new){[void]$changed.Add("$k : $old -> $new");[void]$planChanges.Add([pscustomobject]@{ Attribute=$k; Kind="Replace"; Before=[string]$old; After=[string]$new });if($k -in @("PasswordNotRequired","AllowReversiblePasswordEncryption","DoesNotRequirePreAuth","UseDESKeyOnly","TrustedForDelegation","TrustedToAuthForDelegation")){$highRisk=$true}};if($new){$target=$target -bor [int]$masks[$k]}else{$target=$target -band (-bnot [int]$masks[$k])}}
        if($changed.Count -eq 0){Set-Status "Aucune option UAC modifiée. Aucun appel AD.";return}
        $changes=@($planChanges)
        try { $plan = New-DomeniaSelectionWritePlan -OperationId "WriteAccountOptions" -Changes $changes -Effects @() } catch { Show-ErrorBox $_.Exception.Message; return }
        try { $safety = Get-DomeniaSafetyDescriptor } catch { Show-ErrorBox $_.Exception.Message; return }
        $typedRisk=''
        if($highRisk -and [bool](Get-CfgValue "Security" "RequireTypedHighRiskConfirmation" $true)){$typedRisk='RISQUE'}
        $payload=[pscustomobject]@{DN=[string]$plan.Target.DN;Options=[pscustomobject]$options;Masks=[pscustomobject]$masks;TargetUac=$target;Safety=$safety}
        $code=@'
$before=Assert-WObjectFresh $Context $Payload.Safety
$backend=Get-WWriteBackend $Context @("Set-ADAccountControl")
$SentUtc=""
if($backend -eq "Module"){
    $p=@{Identity=[string]$Payload.DN;ErrorAction="Stop"};if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c}
    foreach($prop in $Payload.Options.PSObject.Properties){$p[$prop.Name]=[bool]$prop.Value}
    $SentUtc=[DateTime]::UtcNow.ToString('o')
    $DomeniaWriteDispatched=$true
    Set-ADAccountControl @p
}else{
    $de=New-WEntry $Context ([string]$Payload.DN);$de.Properties["userAccountControl"].Value=[int]$Payload.TargetUac;$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;$de.CommitChanges()
}
$after=Get-WObjectSnapshot $Context ([string]$Payload.DN)
$expectedFlags=@{}
$observedFlags=@{}
foreach($maskProp in $Payload.Masks.PSObject.Properties){
    $name=[string]$maskProp.Name
    $mask=[int]$maskProp.Value
    $target=$false
    try { $target=[bool]$Payload.Options.($name) } catch { $target=(([int]$Payload.TargetUac -band $mask) -ne 0) }
    $expectedBool=(([int]$Payload.TargetUac -band $mask) -ne 0)
    $observedBool=(([int]$after.Uac -band $mask) -ne 0)
    $expectedFlags[$name]=[string]$expectedBool
    $observedFlags[$name]=[string]$observedBool
    if($observedBool -ne $target){throw "Verification UAC echouee pour $name."}
}
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message="Options UAC appliquees et verifiees.";Before=$before;After=$after;Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=[pscustomobject]@{Server=[string]$Context.Server;Flags=$expectedFlags};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Flags=$observedFlags}}}
'@
        $state=[pscustomobject]@{Code=$code;Payload=$payload;Plan=$plan;Changes=$changes}
        $send={
            param($s)
            try { Start-DomeniaWriteTask -Name "Options du compte" -OperationId "WriteAccountOptions" -Code $s.Code -Payload $s.Payload -Plan $s.Plan -PlanChanges $s.Changes -Capability "Account" -DisableControls @("BtnApplyAccountOptions") -AfterSuccessAction "RefreshObject" }
            catch { Show-ErrorBox "Erreur options compte : $($_.Exception.Message)" }
        }
        $who=[string]$plan.Target.Name
        if($highRisk){[void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Options du compte à haut risque' -Message ('Ces options affaiblissent la sécurité du compte « '+$who+' » : vérifiez chaque ligne avant de confirmer.') -ConfirmText 'Appliquer' -Risk Danger -TypedConfirmation $typedRisk -Send $send -State $state -CancelStatus 'Modification des options du compte annulée : rien nʼa été envoyé.')}
        else{[void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Options du compte' -Message ('Options du compte « '+$who+' » à appliquer :') -ConfirmText 'Appliquer' -Send $send -State $state)}
    } catch { Show-ErrorBox "Erreur options compte : $($_.Exception.Message)" }
}

function Set-UserExpiration {
    param([bool]$Never)
    try {
        if($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Utilisateur"){return}
        $date=""
        if(-not $Never){if($null -eq $script:Ctrl["DpAccountExpires"].SelectedDate){throw "Choisis une date d expiration."};$date=([datetime]$script:Ctrl["DpAccountExpires"].SelectedDate).Date.ToString("o")}
        $beforeRaw = [string](Get-DomeniaOriginalValue "accountExpires")
        $beforeTicks = 0L
        $beforeText = "Aucune expiration"
        if ([int64]::TryParse($beforeRaw, [ref]$beforeTicks)) {
            if ($beforeTicks -gt 0 -and $beforeTicks -ne 9223372036854775807) {
                try { $beforeText = ([datetime]::FromFileTimeUtc($beforeTicks).ToLocalTime().ToString("dd/MM/yyyy")) } catch { $beforeText = $beforeRaw }
            }
        }
        $afterText = "Aucune expiration"
        if (-not $Never) { $afterText = ([datetime]$date).ToString("dd/MM/yyyy") }
        $changes = @([pscustomobject]@{ Attribute="accountExpires"; Kind="Replace"; Before=$beforeText; After=$afterText })
        try { $plan = New-DomeniaSelectionWritePlan -OperationId "WriteExpiration" -Changes $changes -Effects @() } catch { Show-ErrorBox $_.Exception.Message; return }
        try { $safety = Get-DomeniaSafetyDescriptor } catch { Show-ErrorBox $_.Exception.Message; return }
        $payload=[pscustomobject]@{DN=[string]$plan.Target.DN;Never=$Never;Date=$date;Safety=$safety}
        $code=@'
$before=Assert-WObjectFresh $Context $Payload.Safety
$command=if([bool]$Payload.Never){"Clear-ADAccountExpiration"}else{"Set-ADAccountExpiration"}
$backend=Get-WWriteBackend $Context @($command)
$SentUtc=""
$ExpectedValue="0"
if($backend -eq "Module"){
    $p=@{Identity=[string]$Payload.DN;ErrorAction="Stop"};if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c}
    if([bool]$Payload.Never){$ExpectedValue="0"}else{$dt=[datetime]::Parse([string]$Payload.Date);$ExpectedValue=[string]$dt.ToUniversalTime().ToFileTimeUtc();$p.DateTime=$dt}
    $SentUtc=[DateTime]::UtcNow.ToString('o')
    $DomeniaWriteDispatched=$true
    if([bool]$Payload.Never){Clear-ADAccountExpiration @p}else{Set-ADAccountExpiration @p}
}else{
    $de=New-WEntry $Context ([string]$Payload.DN)
    if([bool]$Payload.Never){$ExpectedValue="0";$de.Properties["accountExpires"].Value=0}else{$dt=[datetime]::Parse([string]$Payload.Date);$ExpectedValue=[string]$dt.ToUniversalTime().ToFileTimeUtc();$de.Properties["accountExpires"].Value=$dt.ToUniversalTime().ToFileTimeUtc()}
    $SentUtc=[DateTime]::UtcNow.ToString('o')
    $DomeniaWriteDispatched=$true
    $de.CommitChanges()
}
$actual=Get-WAttributeFirst $Context ([string]$Payload.DN) "accountExpires"
$i=Convert-WLargeInteger $actual
if([bool]$Payload.Never){if($i -ne 0 -and $i -ne 9223372036854775807){throw "L expiration est toujours definie apres l operation."}}
else{
    if($i -le 0 -or $i -eq 9223372036854775807){throw "Aucune date d expiration valide n est relue apres l operation."}
    $actualDate=[datetime]::FromFileTimeUtc([int64]$i).ToLocalTime().Date
    $expectedDate=([datetime]::Parse([string]$Payload.Date)).Date
    if($actualDate -ne $expectedDate){throw "Date d expiration relue $($actualDate.ToString('dd/MM/yyyy')) au lieu de $($expectedDate.ToString('dd/MM/yyyy'))."}
}
$after=Get-WObjectSnapshot $Context ([string]$Payload.DN)
# Compared by local day, like the check above: 0 and 9223372036854775807 both mean "never".
$ExpectedValue="Jamais"
if(-not [bool]$Payload.Never){$ExpectedValue=([datetime]::Parse([string]$Payload.Date)).Date.ToString("yyyy-MM-dd")}
$observedAccountExpires=$null
if($null -ne $actual){if($i -eq 0 -or $i -eq 9223372036854775807){$observedAccountExpires="Jamais"}else{$observedAccountExpires=[datetime]::FromFileTimeUtc([int64]$i).ToLocalTime().Date.ToString("yyyy-MM-dd")}}
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message=$(if([bool]$Payload.Never){"Expiration du compte supprimee et verifiee."}else{"Expiration du compte definie et verifiee."});Before=$before;After=$after;Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=[pscustomobject]@{Server=[string]$Context.Server;Values=@{accountExpires=$ExpectedValue}};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Values=@{accountExpires=$observedAccountExpires}}}}
'@
        $state=[pscustomobject]@{Code=$code;Payload=$payload;Plan=$plan;Changes=$changes}
        $send={
            param($s)
            try { Start-DomeniaWriteTask -Name "Expiration utilisateur" -OperationId "WriteExpiration" -Code $s.Code -Payload $s.Payload -Plan $s.Plan -PlanChanges $s.Changes -Capability "Account" -DisableControls @("BtnSetExpiration","BtnNeverExpires") -AfterSuccessAction "RefreshObject" }
            catch { Show-ErrorBox "Erreur expiration : $($_.Exception.Message)" }
        }
        $who=[string]$plan.Target.Name
        if($Never){[void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Supprimer lʼexpiration du compte' -Message ('Le compte « '+$who+' » nʼexpirera plus.') -ConfirmText 'Supprimer lʼexpiration' -Send $send -State $state)}
        else{[void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Définir lʼexpiration du compte' -Message ('Le compte « '+$who+' » expirera le '+$afterText+'.') -ConfirmText 'Définir' -Send $send -State $state)}
    } catch { Show-ErrorBox "Erreur expiration : $($_.Exception.Message)" }
}

function Expire-UserPasswordNow {
    try {
        if($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Utilisateur"){return}
        $changes = @([pscustomobject]@{ Attribute="pwdLastSet"; Kind="Replace"; Before=(Get-DomeniaOriginalValue "pwdLastSet"); After="0" })
        try { $plan = New-DomeniaSelectionWritePlan -OperationId "WriteExpirePassword" -Changes $changes -Effects @() } catch { Show-ErrorBox $_.Exception.Message; return }
        try { $safety = Get-DomeniaSafetyDescriptor } catch { Show-ErrorBox $_.Exception.Message; return }
        $payload=[pscustomobject]@{DN=[string]$plan.Target.DN;Safety=$safety}
        $code=@'
$before=Assert-WObjectFresh $Context $Payload.Safety
$backend=Get-WWriteBackend $Context @("Set-ADUser")
$SentUtc=""
if($backend -eq "Module"){$p=@{Identity=[string]$Payload.DN;ChangePasswordAtLogon=$true;ErrorAction="Stop"};if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c};$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;Set-ADUser @p}
else{$de=New-WEntry $Context ([string]$Payload.DN);$de.Properties["pwdLastSet"].Value=0;$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;$de.CommitChanges()}
$raw=Get-WAttributeFirst $Context ([string]$Payload.DN) "pwdLastSet"
$actual=Convert-WLargeInteger $raw
if($actual -ne 0){throw "pwdLastSet n est pas a zero apres l operation."}
$after=Get-WObjectSnapshot $Context ([string]$Payload.DN)
$observedPwdLastSet=$null
if($null -ne $raw){$observedPwdLastSet=[string]$actual}
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message="Changement du mot de passe impose au prochain logon.";Before=$before;After=$after;Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=[pscustomobject]@{Server=[string]$Context.Server;Values=@{pwdLastSet="0"}};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Values=@{pwdLastSet=$observedPwdLastSet}}}}
'@
        $state=[pscustomobject]@{Code=$code;Payload=$payload;Plan=$plan;Changes=$changes}
        $send={
            param($s)
            try { Start-DomeniaWriteTask -Name "Expiration immediate du mot de passe" -OperationId "WriteExpirePassword" -Code $s.Code -Payload $s.Payload -Plan $s.Plan -PlanChanges $s.Changes -Capability "Account" -DisableControls @("BtnExpirePwdNow") -AfterSuccessAction "RefreshObject" }
            catch { Show-ErrorBox "Erreur expiration mot de passe : $($_.Exception.Message)" }
        }
        [void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Imposer un nouveau mot de passe' -Message ('« '+[string]$plan.Target.Name+' » devra choisir un nouveau mot de passe à sa prochaine connexion ; lʼactuel nʼest pas modifié.') -ConfirmText 'Imposer' -Send $send -State $state)
    } catch { Show-ErrorBox "Erreur expiration mot de passe : $($_.Exception.Message)" }
}

function Move-SelectedObject {
    # -RowIdentity (FI-20): a result row moved without its fiche. Its identity was captured before the OU was chosen and
    # must still be the current selection; the worker checks the GUID on the controller (Assert-WObjectFresh).
    param([string]$TargetDn,$RowIdentity=$null)
    try {
        $rowMove = ($null -ne $RowIdentity)
        if ($rowMove) {
            if (($RowIdentity -isnot [Domenia.SelectionIdentity]) -or ([string]::IsNullOrWhiteSpace([string]$RowIdentity.DN))) { Show-ErrorBox 'Ligne sans identité exacte (domaine et GUID) : rien nʼest envoyé.'; return }
            if (-not (Test-DomeniaIdentityCurrent $RowIdentity (Get-DomeniaCurrentSelectionIdentity))) { Show-ErrorBox 'La sélection a changé pendant le choix de lʼOU : rien nʼest envoyé. Sélectionnez de nouveau le poste.'; return }
            $objectDn = [string]$RowIdentity.DN
        }
        else {
            if($null -eq $script:SelectedObject){return}
            $objectDn = [string]$script:SelectedObject.DN
        }
        $target=($TargetDn+"").Trim();if([string]::IsNullOrWhiteSpace($target)){throw "OU cible vide."}
        if($target -ieq $objectDn){throw "La cible ne peut pas etre l objet lui-meme."}
        # SE-12: the destination is a DN of the connected domain, outside the configuration and DNS partitions.
        $targetCheck = Test-DomeniaWriteTargetDn -Dn $target -BaseDn ([string]$script:Conn.BaseDn)
        if (-not [bool]$targetCheck.Valid) { Show-ErrorBox ([string]$targetCheck.Reason) -Details $target; return }
        $identity = Get-DomeniaCurrentSelectionIdentity
        if ($null -eq $identity) { Show-ErrorBox 'Sélection sans identité exacte (domaine et GUID) : relire lʼobjet avant toute écriture.'; return }
        $oldDn = [string]$identity.DN
        $parts = @()
        try { $parts = @(Split-DomeniaDn $oldDn) } catch { $parts = @($oldDn -split ',') }
        $newDn = $target
        if ($parts.Count -gt 0) { $newDn = $parts[0] + ',' + $target }
        $changes = @([pscustomobject]@{ Attribute="distinguishedName"; Kind="Move"; Before=$oldDn; After=$newDn })
        try { $plan = New-DomeniaSelectionWritePlan -OperationId "WriteMoveObject" -Changes $changes -Effects @() } catch { Show-ErrorBox $_.Exception.Message; return }
        # A row moved without its fiche carries no uSNChanged/whenChanged: the worker checks DN and GUID on the controller.
        try { $safety = if ($rowMove) { Get-DomeniaRowMoveSafety -Identity $identity } else { Get-DomeniaSafetyDescriptor } } catch { Show-ErrorBox $_.Exception.Message; return }
        $payload=[pscustomobject]@{DN=[string]$plan.Target.DN;TargetDn=$target;Safety=$safety}
        $code=@'
$targetCheck=Test-DomeniaWriteTargetDn -Dn ([string]$Payload.TargetDn) -BaseDn ([string]$Context.BaseDn)
if(-not [bool]$targetCheck.Valid){throw [string]$targetCheck.Reason}
$before=Assert-WObjectFresh $Context $Payload.Safety
$target=Get-WObjectSnapshot $Context ([string]$Payload.TargetDn)
if(-not [bool]$target.Exists){throw "OU ou conteneur cible introuvable."}
if(-not (@($target.Classes) -contains "organizationalUnit") -and -not (@($target.Classes) -contains "container") -and -not (@($target.Classes) -contains "domainDNS")){throw "La cible n est pas une OU ou un conteneur AD."}
$currentParent=Get-WParentDn ([string]$before.DN)
if($currentParent -ieq [string]$Payload.TargetDn){
    $ReadUtc=[DateTime]::UtcNow.ToString('o')
    [pscustomobject]@{Verified=$true;Backend="None";Message="Objet deja dans cette branche. Aucune ecriture AD.";NewDn=[string]$before.DN;Before=$before;After=$before;Postcondition=[pscustomobject]@{SentUtc="";Expected=[pscustomobject]@{Server=[string]$Context.Server;Guid=[string]$before.Guid;NewDn=[string]$before.DN};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Guid=[string]$before.Guid;DN=[string]$before.DN}}};return}
$backend=Get-WWriteBackend $Context @("Move-ADObject")
$newDn=""
$SentUtc=""
if($backend -eq "Module"){$p=@{Identity=[string]$Payload.DN;TargetPath=[string]$Payload.TargetDn;PassThru=$true;ErrorAction="Stop"};if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c};$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;$o=Move-ADObject @p;$newDn=[string]$o.DistinguishedName}
else{$de=New-WEntry $Context ([string]$Payload.DN);$t=New-WEntry $Context ([string]$Payload.TargetDn);$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;$de.MoveTo($t);$de.CommitChanges();$de.RefreshCache(@("distinguishedName"));$newDn=[string]$de.Properties["distinguishedName"].Value}
if([string]::IsNullOrWhiteSpace($newDn)){throw "Le DC n a pas retourne le nouveau DN."}
$after=Get-WObjectSnapshot $Context $newDn
if(-not [bool]$after.Exists -or -not ([string]$after.DN).EndsWith(","+[string]$Payload.TargetDn,[System.StringComparison]::OrdinalIgnoreCase)){throw "Verification du deplacement echouee : $newDn"}
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message="Objet deplace et verifie.";NewDn=$newDn;Before=$before;After=$after;Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=[pscustomobject]@{Server=[string]$Context.Server;Guid=[string]$before.Guid;NewDn=$newDn};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Guid=[string]$after.Guid;DN=[string]$after.DN}}}
'@
        $state=[pscustomobject]@{Code=$code;Payload=$payload;Plan=$plan;Changes=$changes}
        $send={
            param($s)
            try { Start-DomeniaWriteTask -Name "Deplacement objet AD" -OperationId "WriteMoveObject" -Code $s.Code -Payload $s.Payload -Plan $s.Plan -PlanChanges $s.Changes -Capability "Move" -DisableControls @("BtnUserMove","BtnCompMove") -AfterSuccessAction "UpdateDnRefreshObjectBranch" }
            catch { Show-ErrorBox "Erreur deplacement : $($_.Exception.Message)" }
        }
        [void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Déplacer lʼobjet' -Message ('« '+[string]$plan.Target.Name+' » sera déplacé vers « '+(Get-DomeniaOuDisplayPath $target)+' ».') -ConfirmText 'Déplacer' -Send $send -State $state)
    } catch { Show-ErrorBox "Erreur deplacement : $($_.Exception.Message)" }
}

function AddOrRemoveObjectGroup {
    param([string]$GroupValue,[bool]$Add)
    try {
        if($null -eq $script:SelectedObject){return}
        $value=($GroupValue+"").Trim();if([string]::IsNullOrWhiteSpace($value)){throw "Groupe vide."}
        # SE-12: a group typed as a DN must be a DN of the connected domain; it is shown by its readable name.
        $groupName = $value
        if ($value -match '^(?i:CN|OU|DC)\s*=') {
            $groupCheck = Test-DomeniaWriteTargetDn -Dn $value -BaseDn ([string]$script:Conn.BaseDn)
            if (-not [bool]$groupCheck.Valid) { Show-ErrorBox ([string]$groupCheck.Reason) -Details $value; return }
            $groupName = [string]$groupCheck.Name
        }
        $verb=if($Add){"Ajouter au groupe"}else{"Retirer du groupe"}
        if ($Add) {
            $changes = @([pscustomobject]@{ Attribute="memberOf"; Kind="Add"; Before=""; After=$value })
        } else {
            $changes = @([pscustomobject]@{ Attribute="memberOf"; Kind="Remove"; Before=$value; After="" })
        }
        try { $plan = New-DomeniaSelectionWritePlan -OperationId "WriteObjectGroup" -Changes $changes -Effects @() } catch { Show-ErrorBox $_.Exception.Message; return }
        try { $safety = Get-DomeniaSafetyDescriptor } catch { Show-ErrorBox $_.Exception.Message; return }
        $payload=[pscustomobject]@{ObjectDn=[string]$plan.Target.DN;GroupValue=$value;Add=$Add;Safety=$safety}
        $code=@'
$before=Assert-WObjectFresh $Context $Payload.Safety
$gdn=Resolve-WGroupDn $Context ([string]$Payload.GroupValue)
$gs=Get-WObjectSnapshot $Context $gdn
if([bool]$Context.BlockProtectedObjects -and -not [bool]$Context.AllowProtectedObjectWrites -and (Test-WProtectedSnapshot $gs)){throw "Groupe protege : modification d appartenance bloquee."}
$member=Test-WDirectMembership $Context $gdn ([string]$Payload.ObjectDn)
if($member -eq [bool]$Payload.Add){
    $ReadUtc=[DateTime]::UtcNow.ToString('o')
    $members=@()
    if($member){$members=@([string]$Payload.ObjectDn)}
    if([bool]$Payload.Add){$expectedMembership=[pscustomobject]@{Server=[string]$Context.Server;Add=@([string]$Payload.ObjectDn)}}else{$expectedMembership=[pscustomobject]@{Server=[string]$Context.Server;Remove=@([string]$Payload.ObjectDn)}}
    [pscustomobject]@{Verified=$true;Backend="None";Message=$(if([bool]$Payload.Add){"Objet deja membre direct. Aucune ecriture AD."}else{"Objet non membre direct. Aucune ecriture AD."});GroupDn=$gdn;Before=$before;After=$before;Postcondition=[pscustomobject]@{SentUtc="";Expected=$expectedMembership;Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Members=$members}}};return}
$command=if([bool]$Payload.Add){"Add-ADGroupMember"}else{"Remove-ADGroupMember"}
$backend=Get-WWriteBackend $Context @($command)
$SentUtc=""
if($backend -eq "Module"){$p=@{Identity=$gdn;Members=[string]$Payload.ObjectDn;Confirm=$false;ErrorAction="Stop"};if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c};$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;if([bool]$Payload.Add){Add-ADGroupMember @p}else{Remove-ADGroupMember @p}}
else{$g=New-WEntry $Context $gdn;$objPath=Get-WLdapPath $Context ([string]$Payload.ObjectDn);$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;if([bool]$Payload.Add){$g.Invoke("Add",$objPath)|Out-Null}else{$g.Invoke("Remove",$objPath)|Out-Null};$g.CommitChanges()}
$members=@()
$readStatus="OK"
$afterMember=Test-WDirectMembership $Context $gdn ([string]$Payload.ObjectDn)
if($afterMember){$members=@([string]$Payload.ObjectDn)}
if($afterMember -ne [bool]$Payload.Add){throw "Verification de l appartenance directe au groupe echouee."}
if([bool]$Payload.Add){$expectedMembership=[pscustomobject]@{Server=[string]$Context.Server;Add=@([string]$Payload.ObjectDn)}}else{$expectedMembership=[pscustomobject]@{Server=[string]$Context.Server;Remove=@([string]$Payload.ObjectDn)}}
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message=$(if([bool]$Payload.Add){"Objet ajoute au groupe et verifie."}else{"Objet retire du groupe et verifie."});GroupDn=$gdn;Before=$before;After=(Get-WObjectSnapshot $Context ([string]$Payload.ObjectDn));Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=$expectedMembership;Observed=[pscustomobject]@{ReadStatus=$readStatus;Server=[string]$Context.Server;ReadUtc=$ReadUtc;Members=$members}}}
'@
        $state=[pscustomobject]@{Name="$verb AD";Code=$code;Payload=$payload;Plan=$plan;Changes=$changes}
        $send={
            param($s)
            try { Start-DomeniaWriteTask -Name $s.Name -OperationId "WriteObjectGroup" -Code $s.Code -Payload $s.Payload -Plan $s.Plan -PlanChanges $s.Changes -Capability "Group" -DisableControls @("BtnUserAddGroup","BtnUserRemoveGroup","BtnCompAddGroup","BtnCompRemoveGroup") -AfterSuccessAction "RefreshObject" }
            catch { Show-ErrorBox "Erreur groupe : $($_.Exception.Message)" }
        }
        $who=[string]$plan.Target.Name
        if($Add){[void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Ajouter au groupe' -Message ('« '+$who+' » devient membre direct du groupe « '+$groupName+' ».') -ConfirmText 'Ajouter' -Send $send -State $state)}
        else{[void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Retirer du groupe' -Message ('« '+$who+' » ne sera plus membre direct du groupe « '+$groupName+' ».') -ConfirmText 'Retirer' -Risk Danger -Send $send -State $state)}
    } catch { Show-ErrorBox "Erreur groupe : $($_.Exception.Message)" }
}

function AddOrRemoveGroupMember {
    param([bool]$Add)
    try {
        if($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Groupe"){return}
        $target=($script:Ctrl["TxtGroupMemberTarget"].Text+"").Trim();if([string]::IsNullOrWhiteSpace($target)){throw "Membre cible vide."}
        # SE-12: a member typed as a DN must be a DN of the connected domain; it is shown by its readable name.
        $memberName = $target
        if ($target -match '^(?i:CN|OU|DC)\s*=') {
            $memberCheck = Test-DomeniaWriteTargetDn -Dn $target -BaseDn ([string]$script:Conn.BaseDn)
            if (-not [bool]$memberCheck.Valid) { Show-ErrorBox ([string]$memberCheck.Reason) -Details $target; return }
            $memberName = [string]$memberCheck.Name
        }
        $verb=if($Add){"Ajouter le membre"}else{"Retirer le membre"}
        if ($Add) {
            $changes = @([pscustomobject]@{ Attribute="member"; Kind="Add"; Before=""; After=$target })
        } else {
            $changes = @([pscustomobject]@{ Attribute="member"; Kind="Remove"; Before=$target; After="" })
        }
        try { $plan = New-DomeniaSelectionWritePlan -OperationId "WriteGroupMember" -Changes $changes -Effects @() } catch { Show-ErrorBox $_.Exception.Message; return }
        try { $safety = Get-DomeniaSafetyDescriptor } catch { Show-ErrorBox $_.Exception.Message; return }
        $payload=[pscustomobject]@{GroupDn=[string]$plan.Target.DN;ObjectValue=$target;Add=$Add;Safety=$safety}
        $code=@'
$before=Assert-WObjectFresh $Context $Payload.Safety
$odn=Resolve-WObjectDn $Context ([string]$Payload.ObjectValue)
$member=Test-WDirectMembership $Context ([string]$Payload.GroupDn) $odn
if($member -eq [bool]$Payload.Add){
    $ReadUtc=[DateTime]::UtcNow.ToString('o')
    $members=@()
    if($member){$members=@($odn)}
    if([bool]$Payload.Add){$expectedMembership=[pscustomobject]@{Server=[string]$Context.Server;Add=@($odn)}}else{$expectedMembership=[pscustomobject]@{Server=[string]$Context.Server;Remove=@($odn)}}
    [pscustomobject]@{Verified=$true;Backend="None";Message=$(if([bool]$Payload.Add){"Membre deja present directement. Aucune ecriture AD."}else{"Membre deja absent directement. Aucune ecriture AD."});ObjectDn=$odn;Before=$before;After=$before;Postcondition=[pscustomobject]@{SentUtc="";Expected=$expectedMembership;Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Members=$members}}};return}
$command=if([bool]$Payload.Add){"Add-ADGroupMember"}else{"Remove-ADGroupMember"}
$backend=Get-WWriteBackend $Context @($command)
$SentUtc=""
if($backend -eq "Module"){$p=@{Identity=[string]$Payload.GroupDn;Members=$odn;Confirm=$false;ErrorAction="Stop"};if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c};$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;if([bool]$Payload.Add){Add-ADGroupMember @p}else{Remove-ADGroupMember @p}}
else{$g=New-WEntry $Context ([string]$Payload.GroupDn);$objPath=Get-WLdapPath $Context $odn;$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;if([bool]$Payload.Add){$g.Invoke("Add",$objPath)|Out-Null}else{$g.Invoke("Remove",$objPath)|Out-Null};$g.CommitChanges()}
$members=@()
$readStatus="OK"
$afterMember=Test-WDirectMembership $Context ([string]$Payload.GroupDn) $odn
if($afterMember){$members=@($odn)}
if($afterMember -ne [bool]$Payload.Add){throw "Verification de l appartenance directe au groupe echouee."}
if([bool]$Payload.Add){$expectedMembership=[pscustomobject]@{Server=[string]$Context.Server;Add=@($odn)}}else{$expectedMembership=[pscustomobject]@{Server=[string]$Context.Server;Remove=@($odn)}}
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message=$(if([bool]$Payload.Add){"Membre ajoute et verifie."}else{"Membre retire et verifie."});ObjectDn=$odn;Before=$before;After=(Get-WObjectSnapshot $Context ([string]$Payload.GroupDn));Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=$expectedMembership;Observed=[pscustomobject]@{ReadStatus=$readStatus;Server=[string]$Context.Server;ReadUtc=$ReadUtc;Members=$members}}}
'@
        $state=[pscustomobject]@{Name="$verb au groupe";Code=$code;Payload=$payload;Plan=$plan;Changes=$changes}
        $send={
            param($s)
            try { Start-DomeniaWriteTask -Name $s.Name -OperationId "WriteGroupMember" -Code $s.Code -Payload $s.Payload -Plan $s.Plan -PlanChanges $s.Changes -Capability "Group" -DisableControls @("BtnGroupAddMember","BtnGroupRemoveMember") -AfterSuccessAction "GroupMemberRefreshObject" }
            catch { Show-ErrorBox "Erreur membre groupe : $($_.Exception.Message)" }
        }
        $groupName=[string]$plan.Target.Name
        if($Add){[void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Ajouter un membre' -Message ('« '+$memberName+' » devient membre direct du groupe « '+$groupName+' ».') -ConfirmText 'Ajouter' -Send $send -State $state)}
        else{[void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Retirer un membre' -Message ('« '+$memberName+' » ne sera plus membre direct du groupe « '+$groupName+' ».') -ConfirmText 'Retirer' -Risk Danger -Send $send -State $state)}
    } catch { Show-ErrorBox "Erreur membre groupe : $($_.Exception.Message)" }
}

function Rename-ComputerObject {
    try {
        if($null -eq $script:SelectedObject -or $script:SelectedObject.Type -ne "Machine"){return}
        $newName=($script:Ctrl["TxtCompNewName"].Text+"").Trim();if([string]::IsNullOrWhiteSpace($newName)){throw "Nouveau nom vide."}
        if($newName -notmatch "^[A-Za-z0-9][A-Za-z0-9-]{0,62}$"){throw "Nom ordinateur invalide."}
        $identity = Get-DomeniaCurrentSelectionIdentity
        if ($null -eq $identity) { Show-ErrorBox 'Sélection sans identité exacte (domaine et GUID) : relire lʼobjet avant toute écriture.'; return }
        $oldName = [string]$identity.Name
        if ([string]::IsNullOrWhiteSpace($oldName)) { $oldName = [string](Get-DomeniaOriginalValue "name") }
        $changes = @([pscustomobject]@{ Attribute="name"; Kind="Move"; Before=$oldName; After=$newName })
        try { $plan = New-DomeniaSelectionWritePlan -OperationId "WriteRenameComputer" -Changes $changes -Effects @() } catch { Show-ErrorBox $_.Exception.Message; return }
        try { $safety = Get-DomeniaSafetyDescriptor } catch { Show-ErrorBox $_.Exception.Message; return }
        $payload=[pscustomobject]@{DN=[string]$plan.Target.DN;NewName=$newName;Safety=$safety}
        $code=@'
$before=Assert-WObjectFresh $Context $Payload.Safety
if([string]$before.Name -ieq [string]$Payload.NewName){
    $ReadUtc=[DateTime]::UtcNow.ToString('o')
    [pscustomobject]@{Verified=$true;Backend="None";Message="Nom deja conforme. Aucune ecriture AD.";NewDn=[string]$before.DN;Before=$before;After=$before;Postcondition=[pscustomobject]@{SentUtc="";Expected=[pscustomobject]@{Server=[string]$Context.Server;Guid=[string]$before.Guid;NewDn=[string]$before.DN};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Guid=[string]$before.Guid;DN=[string]$before.DN}}};return}
$backend=Get-WWriteBackend $Context @("Rename-ADObject")
$newDn=""
$SentUtc=""
if($backend -eq "Module"){$p=@{Identity=[string]$Payload.DN;NewName=[string]$Payload.NewName;PassThru=$true;ErrorAction="Stop"};if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c};$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;$o=Rename-ADObject @p;$newDn=[string]$o.DistinguishedName}
else{$de=New-WEntry $Context ([string]$Payload.DN);$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;$de.Rename("CN="+(Escape-WRdn ([string]$Payload.NewName)));$de.CommitChanges();$de.RefreshCache(@("distinguishedName"));$newDn=[string]$de.Properties["distinguishedName"].Value}
$after=Get-WObjectSnapshot $Context $newDn
if(-not [bool]$after.Exists -or [string]$after.Name -ine [string]$Payload.NewName){throw "Verification du renommage echouee."}
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message="Objet ordinateur renomme et verifie.";NewDn=$newDn;Before=$before;After=$after;Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=[pscustomobject]@{Server=[string]$Context.Server;Guid=[string]$before.Guid;NewDn=$newDn};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Guid=[string]$after.Guid;DN=[string]$after.DN}}}
'@
        $state=[pscustomobject]@{Code=$code;Payload=$payload;Plan=$plan;Changes=$changes}
        $send={
            param($s)
            try { Start-DomeniaWriteTask -Name "Renommage machine AD" -OperationId "WriteRenameComputer" -Code $s.Code -Payload $s.Payload -Plan $s.Plan -PlanChanges $s.Changes -Capability "Move" -DisableControls @("BtnCompRename") -AfterSuccessAction "RenameComputer" }
            catch { Show-ErrorBox "Erreur renommage : $($_.Exception.Message)" }
        }
        [void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Renommer lʼobjet ordinateur' -Message ('« '+$oldName+' » devient « '+$newName+' » dans lʼannuaire. Le poste Windows lui-même nʼest pas renommé.') -ConfirmText 'Renommer' -Send $send -State $state)
    } catch { Show-ErrorBox "Erreur renommage : $($_.Exception.Message)" }
}

function Update-DomeniaNewOuParentUi {
    # CO-27: l'onglet affiche la branche ou la nouvelle OU sera reellement creee. C'est le noeud choisi
    # dans l'arborescence, pas l'objet ouvert dans la fiche : les deux peuvent diverger, et c'est bien le
    # DN de ce champ que Create-OuUnderSelected transmet au worker.
    $box = Get-DomeniaControl -Name 'TxtNewOuParent'
    if ($null -eq $box) { return }
    $dn = ([string]$script:SelectedBranchDn).Trim()
    if ([string]::IsNullOrWhiteSpace($dn)) { $box.Text = 'Aucune branche sélectionnée'; return }
    $box.Text = Get-DomeniaOuDisplayPath $dn
}

function Create-OuUnderSelected {
    try {
        if ([string]::IsNullOrWhiteSpace([string]$script:SelectedBranchDn)) { throw "Selectionne une branche cible." }
        $name = ($script:Ctrl["TxtNewOuName"].Text + "").Trim()
        if ([string]::IsNullOrWhiteSpace($name)) { throw "Nom de l OU vide." }
        if ($name.IndexOfAny([IO.Path]::GetInvalidFileNameChars()) -ge 0) { throw "Le nom contient des caracteres invalides." }
        # La branche de l arbre n a pas d identite GUID : son DN est fige avant la confirmation et reverifie a l envoi.
        $parentDn = ([string]$script:SelectedBranchDn).Trim()
        # SE-12: the parent branch is a DN of the connected domain, outside the configuration and DNS partitions.
        $parentCheck = Test-DomeniaWriteTargetDn -Dn $parentDn -BaseDn ([string]$script:Conn.BaseDn)
        if (-not [bool]$parentCheck.Valid) { Show-ErrorBox ([string]$parentCheck.Reason) -Details $parentDn; return }
        $payload = [pscustomobject]@{ ParentDn=$parentDn; Name=$name; DN=$parentDn }
        $code = @'
$parentCheck=Test-DomeniaWriteTargetDn -Dn ([string]$Payload.ParentDn) -BaseDn ([string]$Context.BaseDn)
if(-not [bool]$parentCheck.Valid){throw [string]$parentCheck.Reason}
$parent=Get-WObjectSnapshot $Context ([string]$Payload.ParentDn)
if(-not [bool]$parent.Exists){throw "Branche parente introuvable."}
if(-not (@($parent.Classes) -contains "organizationalUnit") -and -not (@($parent.Classes) -contains "container") -and -not (@($parent.Classes) -contains "domainDNS")){throw "La cible n est pas une OU, un conteneur ou la racine du domaine."}
$escaped=Escape-WLdap ([string]$Payload.Name)
$check=New-WSearcher $Context ([string]$Payload.ParentDn) "(&(objectClass=organizationalUnit)(name=$escaped))" @("distinguishedName") "OneLevel" 1
$checkRoot=$check.SearchRoot;$existing=$null
try{$existing=$check.FindOne()}finally{$check.Dispose();if($null -ne $checkRoot){$checkRoot.Dispose()}}
if($null -ne $existing){throw "Une OU portant deja ce nom existe sous la branche cible."}
$backend=Get-WWriteBackend $Context @("New-ADOrganizationalUnit")
$dn=""
$SentUtc=""
if($backend -eq "Module"){
    $p=@{Name=[string]$Payload.Name;Path=[string]$Payload.ParentDn;ProtectedFromAccidentalDeletion=$true;PassThru=$true;ErrorAction="Stop"}
    if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c}
    $SentUtc=[DateTime]::UtcNow.ToString('o')
    $DomeniaWriteDispatched=$true
    $o=New-ADOrganizationalUnit @p;$dn=[string]$o.DistinguishedName
}else{
    $de=New-WEntry $Context ([string]$Payload.ParentDn)
    $SentUtc=[DateTime]::UtcNow.ToString('o')
    $DomeniaWriteDispatched=$true
    $ou=$de.Children.Add("OU="+(Escape-WRdn ([string]$Payload.Name)),"organizationalUnit")
    $ou.CommitChanges();$ou.RefreshCache(@("distinguishedName"));$dn=[string]$ou.Properties["distinguishedName"].Value
}
if([string]::IsNullOrWhiteSpace($dn)){$dn="OU="+(Escape-WRdn ([string]$Payload.Name))+","+[string]$Payload.ParentDn}
$after=Get-WObjectSnapshot $Context $dn
if(-not [bool]$after.Exists -or -not (@($after.Classes) -contains "organizationalUnit")){throw "La verification de l OU creee a echoue."}
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message=$(if($backend -eq "Module"){"OU creee, protegee et verifiee : $dn"}else{"OU creee et verifiee via ADSI : $dn. La protection contre suppression accidentelle necessite le module AD."});DN=$dn;Before=$parent;After=$after;Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=[pscustomobject]@{Server=[string]$Context.Server;Guid=""};Observed=[pscustomobject]@{ReadStatus="OK";Server=[string]$Context.Server;ReadUtc=$ReadUtc;Exists=[bool]$after.Exists;Guid=[string]$after.Guid}}}
'@
        $state=[pscustomobject]@{Code=$code;Payload=$payload;ParentDn=$parentDn}
        $send={
            param($s)
            try { Start-DomeniaWriteTask -Name "Creation OU" -OperationId "WriteCreateOu" -Code $s.Code -Payload $s.Payload -BranchDn $s.ParentDn -Capability "Create" -DisableControls @("BtnCreateOu") -AfterSuccessAction "CreateOu" }
            catch { Show-ErrorBox "Erreur creation OU : $($_.Exception.Message)" }
        }
        $where=Get-DomeniaOuDisplayPath $parentDn
        # CO-27: la protection contre la suppression accidentelle n'est posee que par la voie module AD,
        # et Get-WWriteBackend ne tranche que dans le worker (Import-WAdModule n'a rien a faire dans le
        # thread GUI). Le message ne promet donc plus une protection qu'ADSI peut ne pas poser : il renvoie
        # au resultat de l'operation, qui lui sait quelle voie a ete prise.
        $details='Parent : '+$parentDn+"`r`nNom relatif : OU="+$name+"`r`nProtection contre la suppression accidentelle : posée par le module AD, pas par ADSI. Le résultat de l'opération indique la voie utilisée."
        [void](Request-DomeniaWriteConfirmation -Title 'Créer une unité dʼorganisation' -Message ('Nouvelle unité dʼorganisation « '+$name+' » dans « '+$where+' ».') -Changes @('Unité dʼorganisation : création de « '+$name+' » dans « '+$where+' »') -Details $details -Target ('ad:branch:'+$parentDn.ToLowerInvariant()) -ConfirmText 'Créer' -Send $send -State $state -CancelStatus 'Création de lʼOU annulée : rien nʼa été envoyé.')
    }
    catch { Show-ErrorBox "Erreur creation OU : $($_.Exception.Message)" }
}

function Set-OrClearRawAttribute {
    param([bool]$Clear)
    try {
        if ($null -eq $script:SelectedObject) { return }
        $attr = ($script:Ctrl["TxtRawAttrName"].Text + "").Trim()
        # SE-02: the same rule as the WriteAttributes worker (Security.AllowRawAttributeWrite, then the block list when
        # Security.BlockSensitiveRawAttributes is set); the worker applies it again whatever the interface did.
        $rule = Test-DomeniaRawAttributeAllowed -Attribute $attr -AllowRaw ([bool](Get-CfgValue "Security" "AllowRawAttributeWrite" $false)) -BlockSensitive ([bool](Get-CfgValue "Security" "BlockSensitiveRawAttributes" $true)) -BlockList @($script:RawAttributeBlockList)
        if (-not [bool]$rule.Allowed) { throw ([string]$rule.Reason) }
        $value = [string]$script:Ctrl["TxtRawAttrValue"].Text
        $old = Get-DomeniaOriginalValue $attr
        if ($Clear -and [string]::IsNullOrWhiteSpace($old)) { Set-Status "Attribut déjà vide. Aucune écriture AD."; return }
        if ((-not $Clear) -and ([string]$old -ceq $value)) { Set-Status "Valeur déjà conforme. Aucune écriture AD."; return }
        $change = [pscustomobject]@{ Name=$attr; Old=[string]$old; New=$value; Clear=$Clear }
        Start-DomeniaAttributeWrite -OperationName "Attribut brut $attr" -Changes @($change) -Capability "Edit" -DisableControls @("BtnRawSet","BtnRawClear") -RawEdit -TypedConfirmation "MODIFIER"
    }
    catch { Show-ErrorBox "Erreur attribut brut : $($_.Exception.Message)" }
}

function Delete-SelectedObject {
    try {
        if ($null -eq $script:SelectedObject) { return }
        Assert-DomeniaCapability "Delete"
        $identity = Get-DomeniaCurrentSelectionIdentity
        if ($null -eq $identity) { Show-ErrorBox 'Sélection sans identité exacte (domaine et GUID) : relire lʼobjet avant toute écriture.'; return }
        $dn = [string]$identity.DN
        if ([string]::IsNullOrWhiteSpace($dn)) { Show-ErrorBox 'La sélection courante nʼa pas de DN exact : relire lʼobjet avant suppression.'; return }
        $type = [string]$script:SelectedObject.Type
        $name = [string]$script:SelectedObject.Name
        if ([string]::IsNullOrWhiteSpace($name)) { $name = [string]$script:Ctrl["TxtObjName"].Text }
        if ($dn -ieq [string]$script:Conn.BaseDn) { throw "La racine du domaine ne peut jamais etre supprimee par Domenia." }
        if ($type -in @("OU","Conteneur") -and -not [bool](Get-CfgValue "Security" "AllowContainerDelete" $false)) { throw "Suppression des unites d organisation bloquee par defaut. Aucune suppression recursive n est possible." }
        $effects = @('Suppression de l objet ' + $dn + ' (recursive : non)')
        try { $plan = New-DomeniaSelectionWritePlan -OperationId "WriteDeleteObject" -Changes @() -Effects $effects } catch { Show-ErrorBox $_.Exception.Message; return }
        try { $safety = Get-DomeniaSafetyDescriptor } catch { Show-ErrorBox $_.Exception.Message; return }
        $expected = if ([string]::IsNullOrWhiteSpace($name)) { $dn } else { $name }
        $deletedType=$type;$deletedName=$name;$deletedSam="";$deletedDns=""
        if($type -eq "Utilisateur"){$deletedSam=[string]$script:Ctrl["TxtUserSam"].Text}
        if($type -eq "Machine"){$deletedSam=[string]$script:Ctrl["TxtCompName"].Text;$deletedDns=[string]$script:Ctrl["TxtCompDns"].Text}
        $payload=[pscustomobject]@{DN=$dn;Safety=$safety;Type=$type;Name=$name}
        $code=@'
$before=Assert-WObjectFresh $Context $Payload.Safety
$children=Get-WChildCount $Context ([string]$Payload.DN)
if($children -gt 0){throw "Suppression bloquee : cet objet possede $children objet(s) enfant(s). Aucune suppression recursive n est autorisee."}
if(@($before.Classes) -contains "domainDNS"){throw "Suppression de la racine domaine interdite."}
if((@($before.Classes) -contains "organizationalUnit" -or @($before.Classes) -contains "container") -and -not [bool]$Context.AllowContainerDelete){throw "Suppression OU/conteneur bloquee par la politique Domenia."}
$backend=Get-WWriteBackend $Context @("Remove-ADObject")
$SentUtc=""
if($backend -eq "Module"){
    $p=@{Identity=[string]$Payload.DN;Confirm=$false;Recursive=$false;ErrorAction="Stop"};if($Context.Server){$p.Server=[string]$Context.Server};$c=Get-WAdCredential $Context;if($c){$p.Credential=$c};$SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;Remove-ADObject @p
}else{
    $parentDn=Get-WParentDn ([string]$Payload.DN);if([string]::IsNullOrWhiteSpace($parentDn)){throw "Parent DN introuvable."}
    $parent=New-WEntry $Context $parentDn;$child=New-WEntry $Context ([string]$Payload.DN)
    $class=if(@($before.Classes) -contains "computer"){"computer"}elseif(@($before.Classes) -contains "user"){"user"}elseif(@($before.Classes) -contains "group"){"group"}elseif(@($before.Classes) -contains "organizationalUnit"){"organizationalUnit"}else{[string](@($before.Classes)[-1])}
    $SentUtc=[DateTime]::UtcNow.ToString('o');$DomeniaWriteDispatched=$true;$parent.Children.Remove($child);$parent.CommitChanges()
}
Start-Sleep -Milliseconds 250
$after=Get-WObjectSnapshot $Context ([string]$Payload.DN)
if([bool]$after.Exists){throw "Verification impossible : l objet existe encore apres la demande de suppression."}
$pcReadStatus="OK"
$pcExists=$false
$pcGuid=""
$guidText=[string]$before.Guid
if($guidText.StartsWith("{") -and $guidText.EndsWith("}")){$guidText=$guidText.Substring(1,$guidText.Length-2)}
if([string]::IsNullOrWhiteSpace($guidText)){$pcReadStatus="Unavailable"}
else{
    try {
        $guidSnapshot=Get-WObjectSnapshot $Context ('<GUID=' + $guidText + '>')
        $pcExists=[bool]$guidSnapshot.Exists
        $pcGuid=[string]$guidSnapshot.Guid
    } catch {
        $ex=$_.Exception
        $h=0
        try { $h=[int]$ex.HResult } catch { }
        if($h -eq 0 -and $null -ne $ex.InnerException){ try { $h=[int]$ex.InnerException.HResult } catch { } }
        $msg=[string]$ex.Message
        if($null -ne $ex.InnerException){ $msg += " " + [string]$ex.InnerException.Message }
        if($h -eq -2147016656 -or $msg -match "(?i)not found|introuvable"){ $pcExists=$false; $pcReadStatus="OK" }
        elseif($h -eq -2147024891 -or $msg -match "(?i)access is denied" -or $msg -match "(?i)acc.*s refus"){ $pcReadStatus="Refused" }
        else { $pcReadStatus="Unavailable" }
    }
}
$ReadUtc=[DateTime]::UtcNow.ToString('o')
[pscustomobject]@{Verified=$true;Backend=$backend;Message="Objet supprime sans recursivite et absence verifiee.";Before=$before;After=$after;Postcondition=[pscustomobject]@{SentUtc=$SentUtc;Expected=[pscustomobject]@{Server=[string]$Context.Server;Guid=[string]$before.Guid};Observed=[pscustomobject]@{ReadStatus=$pcReadStatus;Server=[string]$Context.Server;ReadUtc=$ReadUtc;Exists=$pcExists;Guid=$pcGuid}}}
'@
        $deleteState = [pscustomobject]@{ DeletedType=$deletedType; DeletedName=$deletedName; DeletedSam=$deletedSam; DeletedDns=$deletedDns }
        # UX-08: two confirmations in the page, as before in two windows: the name of the object, then SUPPRIMER.
        $send={
            param($s)
            try { Start-DomeniaWriteTask -Name "Suppression objet AD" -OperationId "WriteDeleteObject" -Code $s.Code -Payload $s.Payload -Plan $s.Plan -PlanChanges @() -Capability "Delete" -DisableControls @("BtnObjectMore") -AfterSuccessAction "DeleteObject" -AfterSuccessState $s.DeleteState }
            catch { Show-ErrorBox "Erreur suppression : $($_.Exception.Message)" }
        }
        $finalStep={
            param($s)
            [void](Request-DomeniaWriteConfirmation -Plan $s.Plan -Title 'Supprimer : dernière confirmation' -Message ('Seul « '+$s.Name+' » est supprimé de lʼannuaire ; un objet protégé ou qui contient dʼautres objets est refusé.') -Changes $s.Lines -ConfirmText 'Supprimer' -Risk Danger -TypedConfirmation 'SUPPRIMER' -Send $s.Send -State $s -CancelStatus 'Suppression annulée : rien nʼa été envoyé.')
        }
        $lines=@('Objet : « '+$expected+' » supprimé de lʼannuaire, sans suppression récursive')
        $state=[pscustomobject]@{Code=$code;Payload=$payload;Plan=$plan;DeleteState=$deleteState;Name=$expected;Lines=$lines;Send=$send}
        [void](Request-DomeniaWriteConfirmation -Plan $plan -Title 'Supprimer lʼobjet (1 sur 2)' -Message ('Suppression non récursive de « '+$expected+' ». Les objets protégés ou qui contiennent dʼautres objets sont refusés.') -Changes $lines -ConfirmText 'Continuer' -Risk Danger -TypedConfirmation $expected -TypedPrompt ('Pour continuer, saisissez exactement le nom de lʼobjet : '+$expected) -Send $finalStep -State $state -CancelStatus 'Suppression annulée : rien nʼa été envoyé.')
    }
    catch { Show-ErrorBox "Erreur suppression : $($_.Exception.Message)" }
}

function ConvertTo-DomeniaSafeValue {
    param($Value,[string]$Key="")
    $sensitive = "(?i)password|passwd|secret|token|credential|api.?key|recoverypassword|laps|unicodepwd|keypackage|private"
    if ($Key -match $sensitive) { return "<MASQUE>" }
    if ($null -eq $Value) { return $null }
    if ($Value -is [System.Management.Automation.PSCredential] -or $Value -is [Security.SecureString]) { return "<MASQUE>" }
    if ($Value -is [System.Collections.IDictionary]) {
        $h=[ordered]@{};foreach($k in $Value.Keys){$h[[string]$k]=ConvertTo-DomeniaSafeValue $Value[$k] ([string]$k)};return [pscustomobject]$h
    }
    if ($Value -is [System.Management.Automation.PSObject] -and -not ($Value -is [string]) -and -not ($Value -is [ValueType])) {
        $h=[ordered]@{};foreach($p in $Value.PSObject.Properties){$h[$p.Name]=ConvertTo-DomeniaSafeValue $p.Value $p.Name};return [pscustomobject]$h
    }
    if ($Value -is [System.Collections.IEnumerable] -and -not ($Value -is [string])) { return @($Value | ForEach-Object { ConvertTo-DomeniaSafeValue $_ $Key }) }
    $text=[string]$Value
    if($text.Length -gt 4096){return $text.Substring(0,4096)+"...<tronque>"}
    return $Value
}

function Export-SelfCheckReport {
    try {
        Initialize-DomeniaDataStore | Out-Null
        $dlg = New-DomeniaFileRequest -Mode Save
        $dlg.Filter = "Archive diagnostic ZIP (*.zip)|*.zip"
        $dlg.FileName = "Domenia-Diagnostic-$((Get-Date).ToString('yyyyMMdd-HHmmss')).zip"
        if (-not $dlg.ShowDialog()) { return }
        $work = Join-Path (Join-Path $script:DataDir "Diagnostics") ("diag-"+[guid]::NewGuid().ToString("N"))
        New-Item -ItemType Directory -Path $work -Force | Out-Null
        try {
            $runtime=[ordered]@{
                App="DOMENIA";Build=$script:MasterBuild;Version=$script:Version;Generated=(Get-Date).ToString("o")
                PowerShell=[string]$PSVersionTable.PSVersion;OS=[Environment]::OSVersion.VersionString
                RootDir=$script:RootDir;DataDir=$script:DataDir;ProcessIdentity=$script:ProcessIdentity
                AdIdentity=[string]$script:Conn.BindUser;Domain=[string]$script:Conn.Domain;Server=[string]$script:Conn.Server;BaseDn=[string]$script:Conn.BaseDn
                ReadOnly=[bool]$script:ReadOnlyMode;WriteState=[string]$script:WriteState
                AsyncEngineReady=[bool]$script:AsyncEngineReady;AsyncJobs=@($script:AsyncJobs.Keys).Count
                ModuleSources=@(Get-DomeniaAdModuleSources);ModuleLoaded=[bool](Test-DomeniaAdCommandsAvailable)
                Integrity=(Get-DomeniaIntegritySnapshot)
            }
            (ConvertTo-DomeniaSafeValue $runtime | ConvertTo-Json -Depth 12) | Set-Content -LiteralPath (Join-Path $work "runtime.json") -Encoding UTF8
            (ConvertTo-DomeniaSafeValue $script:Config | ConvertTo-Json -Depth 12) | Set-Content -LiteralPath (Join-Path $work "configuration-sanitized.json") -Encoding UTF8
            if(@($script:SelfCheckRows).Count -gt 0){[void](Export-DomeniaCsv -Rows @($script:SelfCheckRows) -Grid (Get-DomeniaControl -Name 'DgSelfCheck') -Path (Join-Path $work "self-check.csv"))}


            @("DOMENIA diagnostic en lecture seule","Journaux bruts exclus. Les identites, noms de machines, domaines et chemins ne sont pas anonymises. Relire avant partage.","Build: $($script:MasterBuild)","Version: $($script:Version)") | Set-Content -LiteralPath (Join-Path $work "README.txt") -Encoding UTF8
            Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
            $zipTemp = $dlg.FileName + '.' + [guid]::NewGuid().ToString('N') + '.partial'
            try {
                [System.IO.Compression.ZipFile]::CreateFromDirectory($work,$zipTemp,[System.IO.Compression.CompressionLevel]::Optimal,$false)
                if ([IO.File]::Exists($dlg.FileName)) { [IO.File]::Replace($zipTemp,$dlg.FileName,[NullString]::Value,$true) }
                else { [IO.File]::Move($zipTemp,$dlg.FileName) }
            } finally { Remove-Item -LiteralPath $zipTemp -Force -ErrorAction SilentlyContinue }
            Set-Status "ZIP diagnostic exporte : $($dlg.FileName)"
            Write-AppLog "ZIP diagnostic exporte : $($dlg.FileName)" "INFO"
        }
        finally { Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue }
    }
    catch { Show-ErrorBox "Erreur export diagnostic : $($_.Exception.Message)" }
}

