function Request-DomeniaDashboardRefresh {
    param([switch]$Immediate)
    if ($Immediate) {
        try { Update-Dashboard } catch { Write-DomeniaSwallowed 'Core' 'Request-DomeniaDashboardRefresh' $_ }
        return
    }
    # D020 / UX-30: a hidden page or a minimized window is not rebuilt; it is marked dirty and rebuilt once when shown
    # again. An inactive but visible window keeps its home page current. PF-10: no command lookup.
    $dashboardAllowed = $true
    try { $dashboardAllowed = [bool](Test-DomeniaBackgroundWorkAllowed -Source 'Dashboard') } catch { $dashboardAllowed = $true }
    if (-not $dashboardAllowed) { $script:DashboardDirty = $true; return }
    $script:DashboardDirty = $false
    try {
        if ($null -eq $script:DashboardRefreshTimer) {
            # FI-05: protected timer of the engine heartbeat, owned and registered by the factory.
            $script:DashboardRefreshTimer = New-DomeniaTimer -Owner 'Timer:DashboardRefresh' -IntervalMs 160 -Tick {
                param($sender,$eventArgs)
                # Stop the timer that ticked, not the script variable: a replaced or cleared variable left it ticking forever.
                try { $sender.Stop() } catch { Write-DomeniaSwallowed 'Core' 'Request-DomeniaDashboardRefresh' $_ }
                # D020: the page may have been hidden since the request; it is then rebuilt once when shown again.
                $tickAllowed = $true
                try { $tickAllowed = [bool](Test-DomeniaBackgroundWorkAllowed -Source 'Dashboard') } catch { $tickAllowed = $true }
                if (-not $tickAllowed) { $script:DashboardDirty = $true; return }
                try { Update-Dashboard } catch { Write-DomeniaSwallowed 'Core' 'Request-DomeniaDashboardRefresh' $_ }
            }
        }
        $script:DashboardRefreshTimer.Stop()
        $script:DashboardRefreshTimer.Start()
    }
    catch { try { Update-Dashboard } catch { Write-DomeniaSwallowed 'Core' 'Request-DomeniaDashboardRefresh' $_ } }
}

function Update-Dashboard {
    # PF-11: the fields live in the "Details de la session" expander, closed most of the time; they are rebuilt when it
    # opens (Wire-Events) and while it stays open. Without the expander (older layouts) they keep refreshing.
    param([switch]$Force)
    $detailsOpen = $true
    try { if (($null -ne $script:Ctrl) -and $script:Ctrl.ContainsKey('UxSessionDetails') -and ($null -ne $script:Ctrl['UxSessionDetails'])) { $detailsOpen = [bool]$script:Ctrl['UxSessionDetails'].IsExpanded } } catch { $detailsOpen = $true }
    if ((-not $Force) -and (-not $detailsOpen)) { $script:SessionDetailsDirty = $true; return }
    $script:SessionDetailsDirty = $false
    try {
        # D014: no command lookup in series on each refresh; the AD module state is read once per change of module.
        $rows=@($script:BranchObjects)
        $stats=Get-ObjectsStatsText $rows
        $script:Ctrl["TxtDashDomain"].Text=[string]$script:Conn.Domain
        $script:Ctrl["TxtDashServer"].Text=[string]$script:Conn.Server
        $script:Ctrl["TxtDashUser"].Text=[string]$script:Conn.BindUser
        $script:Ctrl["TxtDashMode"].Text=if($script:ReadOnlyMode){"Lecture seule (sécurité par défaut)"}else{"Écriture autorisée sous contrôles"}
        $script:Ctrl["TxtDashBaseDn"].Text=[string]$script:Conn.BaseDn
        $script:Ctrl["TxtDashBranch"].Text=[string]$script:SelectedBranchDn
        $script:Ctrl["TxtDashRows"].Text=[string]$rows.Count
        $adCheckDue=($null -eq $script:DashboardAdModuleCheckedAt)
        if(-not $adCheckDue -and -not [bool]$script:DashboardAdModuleLoaded){$adCheckDue=(((Get-Date)-[datetime]$script:DashboardAdModuleCheckedAt).TotalSeconds -ge 30)}
        # Demonstration: Get-Command on an AD cmdlet auto-imports ActiveDirectory, whose AD: drive binds to a domain controller.
        if($adCheckDue -and [bool]$script:DemoMode){$script:DashboardAdModuleLoaded=$false;$script:DashboardAdModuleCheckedAt=Get-Date;$adCheckDue=$false}
        if($adCheckDue){$script:DashboardAdModuleLoaded=[bool](Test-DomeniaAdCommandsAvailable);$script:DashboardAdModuleCheckedAt=Get-Date}
        $script:Ctrl["TxtDashModule"].Text=if([bool]$script:DashboardAdModuleLoaded){"ActiveDirectory charge"}else{"À la demande : RSAT/DLL vérifiés/LDAP"}
        $script:Ctrl["TxtDashStats"].Text=[string]$stats
        $script:Ctrl["TxtDashSelected"].Text=if($null -ne $script:SelectedObject){"$($script:SelectedObject.Type)  $($script:SelectedObject.Name)"}else{"Aucun"}
        if($script:Ctrl.ContainsKey("TxtDashRights")){$script:Ctrl["TxtDashRights"].Text=if($script:CurrentCapabilities.Count -gt 0){($script:CurrentCapabilities.GetEnumerator()|ForEach-Object{"$($_.Key)=$($_.Value)"}) -join "  "}else{"Analyse à lʼouverture de lʼobjet"}}
        if($script:Ctrl.ContainsKey("TxtDashTasks")){$script:Ctrl["TxtDashTasks"].Text="$(@($script:AsyncJobs.Keys).Count) tâche(s)  écriture=$($script:WriteState)"}
        if($script:Ctrl.ContainsKey("TxtDashCache")){
            $limit=[Math]::Max(1,[Math]::Min(100000,[int](Get-CfgValue 'Cache' 'MaxEntries' 500)))
            $ttl=[Math]::Max(1,[Math]::Min(86400,[int](Get-CfgValue 'Cache' 'TtlSeconds' 90)))
            $fresh=0;$oldest=$null;$now=Get-Date
            foreach($item in $script:VisitCache.Values){if($item.Expires -gt $now){$fresh++;if($null -eq $oldest -or $item.Created -lt $oldest){$oldest=$item.Created}}}
            $reads=[long]$script:CacheStats.Hits+[long]$script:CacheStats.Misses
            $ratio=if($reads){[Math]::Round(100.0*$script:CacheStats.Hits/$reads).ToString()+' % réutilisées'}else{'aucune lecture'}
            $age=if($null -ne $oldest){[Math]::Floor(($now-$oldest).TotalSeconds).ToString()+' s'}else{'—'}
            $script:Ctrl['TxtDashCache'].Text=$fresh.ToString()+'/'+$limit+' entrées fraîches · '+($script:VisitCache.Count-$fresh)+' expirées · durée par défaut '+$ttl+' s'+[Environment]::NewLine+$ratio+' · '+$script:CacheStats.Evictions+' évictions · '+$script:CacheStats.Errors+' erreurs · plus ancienne : '+$age+[Environment]::NewLine+'Cache de visite en mémoire ; la base locale et les relevés sont conservés séparément.'
        }
        if($script:Ctrl.ContainsKey("TxtDashSelfCheck")){$script:Ctrl["TxtDashSelfCheck"].Text=[string]$script:LastSelfCheckSummary}
        if($script:Ctrl.ContainsKey("TxtDashLinks")){$script:Ctrl["TxtDashLinks"].Text=(Get-AssociationStatsText)}
    }
    catch { Write-DomeniaSwallowed 'Core' 'Update-Dashboard' $_ }
}

function Invoke-DomeniaStartupCacheWarmup {
    # The old pre-window AD warmup duplicated the normal tree/object collectors and
    # published an uncommitted snapshot. Startup now uses the regular store pipeline.
    # Keep the registered operation inert for compatible older deployment manifests.
    $code = @'
[pscustomobject]@{Deferred=$true;WorkerThreadId=[Threading.Thread]::CurrentThread.ManagedThreadId}
'@
    $script:StartupWarmCache=$null
    $script:StartupWarmupDone=$true
    $script:StartupWarmupError=''
    $script:StartupWorkerReady=[bool]$script:AsyncEngineReady
    $script:StartupReady=[bool]$script:AsyncEngineReady
    Write-StartupTrace -Stage 'Preparation des donnees' -Status 'OK' -Detail 'Les branches passent par la collecte normale, la base locale puis son readback ; aucune seconde collecte initiale.'
}

function Assert-DomeniaStartupReadiness {
    if(-not $script:AsyncEngineReady){throw "Le moteur multithread ferme n'est pas pret."}
    if(-not $script:StartupWarmupDone){throw "La preparation des donnees n'est pas terminee."}
    if($script:StartupWarmupError){throw ('Preparation en erreur : '+$script:StartupWarmupError)}
    $script:StartupReady=$true
}

function Initialize-Window {
    if ([string]::IsNullOrWhiteSpace([string]$script:StartupCorrelation)) {
        $script:StartupCorrelation = [guid]::NewGuid().ToString("N")
    }
    $script:LoginAuthStarted = Get-Date
    $script:StartupCancelled = $false
    Initialize-DomeniaDataStore | Out-Null
    New-DomeniaStartupWindow
    try {
        Invoke-DomeniaStartupStage "Chargement interface WPF" { Load-XamlWindow } | Out-Null
        Invoke-DomeniaStartupStage "Protection erreurs interface" { Register-DomeniaDispatcherExceptionHandler } | Out-Null
        Invoke-DomeniaStartupStage "Moteur multithread" { Initialize-AsyncEngine; Initialize-DomeniaWorkerContextCache } | Out-Null
        Invoke-DomeniaStartupStage "Branchement des evenements" { Wire-Events } | Out-Null
        Invoke-DomeniaStartupStage "Vues de recherche" { Initialize-DomeniaSearchWorkspace } | Out-Null
        Invoke-DomeniaStartupStage "Gestion des comptes" { Initialize-DomeniaAccountPanel } | Out-Null
        # Decision David 2026-10-07: the Atelier support workspace is removed; it is no longer loaded.
        Invoke-DomeniaStartupStage "Aides et ergonomie" { Apply-AutoTooltips; Apply-DomeniaGuiElementPolicy } | Out-Null
        Invoke-DomeniaStartupStage "Base autonome DOMENIA" {
            $dbBoot=[Diagnostics.Stopwatch]::StartNew()
            try{Initialize-DomeniaDatabase | Out-Null}catch{
                $bootError=[string]$_.Exception.Message
                $redirected=($bootError -match 'StorageRedirected')
                # Point 36: a proven corrupt base no longer stops the start. The UI stays reachable for the restore
                # assistant; the file stays untouched and every collection waits behind the maintenance lock.
                $unreadable=((-not $redirected) -and [bool](Test-DomeniaStorageUnreadableMessage $bootError) -and (-not [string]::IsNullOrWhiteSpace([string]$script:DatabaseScopedPath)))
                if((-not $redirected) -and (-not $unreadable)){throw}
                if($unreadable){
                    $script:StorageMaintenance=[pscustomobject]@{Id='recovery-unreadable';Mode='Restore';Recovery=$true;Locked=$true;Hold=$true;Draining=$false;DrainNext='';DrainUntil=[datetime]::MinValue;Epoch=[long]$script:SessionEpoch;Path=[string]$script:DatabaseScopedPath;DomainDn=[string]$script:Conn.BaseDn;SourcePath='';TargetPath='';Fingerprint='';Job='';Receipt=$null}
                    [void](Set-DomeniaControlText 'LblStorageMaintenance' ('Base locale illisible, laissée intacte : '+[string]$script:DatabaseScopedPath+'. Restaurez une sauvegarde vérifiée avec « Restaurer une sauvegarde… ». Détail : '+$bootError))
                    Write-AppLog ('Base locale illisible au démarrage, mode restauration : '+$bootError) 'ERROR'
                    Set-DomeniaStartupStage -Stage 'Base locale illisible' -Detail 'Restaurez une sauvegarde vérifiée dans Outils, Base autonome, Stockage.'
                    return
                }
                # Keep the UI reachable for recovery. Never silently write to an old copy after a move.
                $script:StorageMaintenance=[pscustomobject]@{Id='recovery-pending';Locked=$true;Hold=$true;Draining=$false;Recovery=$false;Epoch=[long]$script:SessionEpoch;Path=[string]$script:DatabaseScopedPath;Job='';Receipt=$null}
                [void](Request-DomeniaStorageRecovery -Path ([string]$script:DatabaseScopedPath) -DomainDn ([string]$script:Conn.BaseDn))
                Set-DomeniaStartupStage -Stage 'Base locale en attente' -Detail 'Une bascule doit être reprise dans Outils, Base autonome, Stockage.'
                return
            }
            $dbBoot.Stop()
            Set-DomeniaStartupStage -Stage "Base autonome DOMENIA" -Detail ("SQLite pret en " + $dbBoot.ElapsedMilliseconds + " ms")
            # FI-19: the content is read off the Dispatcher by the LocalIndexRead worker. The associations are asked now,
            # the figures of the base once the window is painted (ContentRendered), followed by the startup notices.
            Request-DomeniaUserMachineLinks
            Set-DomeniaStartupStage -Stage "Base autonome DOMENIA" -Detail 'Associations et état de la base : lecture en arrière-plan.'
        } | Out-Null
        Invoke-DomeniaStartupStage 'Réglages du stockage local' {Initialize-DomeniaStoragePolicy} | Out-Null
        Invoke-DomeniaStartupStage "Etat initial de securite" {
            Set-DomeniaStartupStage -Stage "Etat initial de securite" -Detail "Preparation des controles..."
            Set-VisibleTabsForType ""
            if($script:Ctrl.ContainsKey("TxtBranchLimit")){$script:Ctrl["TxtBranchLimit"].Text=[string](Get-CfgValue "Browser" "DefaultLimit" 100)}
            $script:Ctrl["TxtGlobalLimit"].Text=[string](Get-CfgValue "Browser" "GlobalSearchLimit" 100)
            # Toujours demarrer en lecture seule. L administrateur peut lever le verrou explicitement dans le GUI.
            $script:ReadOnlyMode=$true
            if($script:Ctrl.ContainsKey("ChkReadOnlyMode")){$script:Ctrl["ChkReadOnlyMode"].IsChecked=$true}
            try{Update-DomeniaMachineAccountUi -Force}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
            Assert-DomeniaReadWriteControlClassification
            Set-DomeniaStartupStage -Stage "Etat initial de securite" -Detail "Application des droits et du mode lecture seule..."
            Apply-CurrentPermissionUi
            Set-DomeniaStartupStage -Stage "Etat initial de securite" -Detail "Chargement de la presentation legere..."
            Initialize-DomeniaPresentation
            Set-DomeniaStartupStage -Stage "Etat initial de securite" -Detail "Presentation prete."
        } | Out-Null
        # D002/C2: after the presentation (which sets the session badge), the demonstration banner and the
        # write lock are applied; they stay for the whole session.
        if ([bool]$script:DemoMode) { Invoke-DomeniaStartupStage "Mode demonstration" { Set-DomeniaDemoShellPresentation } | Out-Null }
        Invoke-DomeniaStartupStage "Prechargement cache AD" { Invoke-DomeniaStartupCacheWarmup } | Out-Null
        Invoke-DomeniaStartupStage "Preparation arbre AD" {
            if($null -ne $script:StorageMaintenance -and $script:StorageMaintenance.Locked){
                if([string]$script:StorageMaintenance.Id -ceq 'recovery-unreadable'){Set-Status 'Base locale illisible : restaurez une sauvegarde vérifiée dans Outils > Base autonome > Stockage. Les collectes sont suspendues.' 'WARN'}
                else{Set-Status 'Bascule locale à reprendre dans Outils > Base autonome > Stockage. Les collectes sont suspendues.' 'WARN'}
            }else{Load-TreeRoot;Update-Dashboard}
        } | Out-Null
        Invoke-DomeniaStartupStage "Barriere de disponibilite" { Assert-DomeniaStartupReadiness } | Out-Null
        # D020: Activated, Deactivated, StateChanged and the page selector drive the idle policy (C1).
        try { Initialize-DomeniaIdlePolicy -Window $script:Window } catch { Write-AppLog ("Politique de repos non initialisee : " + $_.Exception.Message) "WARN" }
        # D089: a voluntary Alt-Tab during the startup is respected: the main window then opens without taking the foreground.
        try { [void](Set-DomeniaWindowActivationPolicy -Window $script:Window -UserSwitchedAway:(Test-DomeniaUserSwitchedAway)) } catch { Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_ }
        $script:Window.Add_Closing({param($s,$e)
            $writeJobStillAlive = $false
            $writeJobsUnreadable = $false
            try {
                # PowerShell can turn a failing adapted property getter into null. Reject an invalid registry
                # before reading Values, so an unreadable task list is never mistaken for an empty one.
                if ($script:AsyncJobs -isnot [Collections.IDictionary]) { throw 'Registre des tâches indisponible.' }
                $writeJobStillAlive = (@($script:AsyncJobs.Values | Where-Object { $null -ne $_ -and [bool]$_.IsWrite }).Count -gt 0)
            } catch { $writeJobsUnreadable = $true; Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_ }
            # P-CD-09: when the running tasks cannot be read, closing could interrupt a write still being confirmed:
            # the operator decides, as when the engine stopped.
            if($writeJobsUnreadable -and [string]::IsNullOrWhiteSpace($script:ActiveWriteTaskId)){
                $leave=$false
                try{$leave=Confirm-WarningAction "Domenia nʼa pas pu vérifier sʼil reste une écriture AD en cours de confirmation.`r`n`r`nSi vous fermez maintenant, vérifiez les reçus au prochain démarrage avant toute autre modification.`r`n`r`nFermer Domenia maintenant ?"}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
                if($leave){Write-AppLog "Fermeture confirmée sans pouvoir lire les tâches en cours ; reçus à vérifier au prochain démarrage." "WARN";return}
                $e.Cancel=$true;return
            }
            if(-not [string]::IsNullOrWhiteSpace($script:ActiveWriteTaskId) -or $writeJobStillAlive){
                # FI-02: a stopped engine will never confirm this write; its durable receipt keeps it to be verified.
                if([bool]$script:AsyncEngineFaultStopped){
                    $leave=$false
                    try{$leave=Confirm-WarningAction "Le moteur des tâches est arrêté : Domenia ne pourra plus confirmer lʼécriture AD en cours.`r`n`r`nSon reçu local est conservé. Au prochain démarrage, vérifiez cette écriture dans les reçus avant toute autre modification.`r`n`r`nFermer Domenia maintenant ?"}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
                    if($leave){Write-AppLog "Fermeture confirmee avec une ecriture AD non confirmee (moteur arrete) ; recu conserve." "WARN";return}
                    $e.Cancel=$true;return
                }
                $e.Cancel=$true
                # A refusal to close stays on screen until it is read (UX-06: a warning banner is not closed after 5 s).
                Show-WarningBox "Une écriture AD est en cours de confirmation par le DC. La fenêtre ne peut pas être fermée tant que son état est inconnu."
            }
        })
        $script:Window.Add_Closed({
            try{Stop-DomeniaOuTreeFilter}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
            try{Stop-DomeniaFavouriteTreeReveal}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
            try{Save-DomeniaWindowGeometry}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
            try{Save-DomeniaSettings -Immediate}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
            try{[void](Flush-DomeniaIndex)}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
            try{Stop-DomeniaAccountValidation}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
            try{Dispose-AsyncEngine}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
            try{Clear-DomeniaSecretClipboard -Silent}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
            try{Clear-Secrets}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
            try{$script:MachineCredential=$null}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
            try{$script:Conn.Credential=$null}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
            try{Stop-DomeniaLoginAuth}catch{Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_}
        })
        $script:Window.Add_ContentRendered({
            try{
                if ([bool]$script:DemoMode) { Set-Status ("Prêt. " + (Get-DomeniaDemoBannerText) + ".") "WARN" }
                else { Set-Status "Pret. Connexion validee, mode lecture seule actif." }
                try { Update-DomeniaMachineAccountUi -Force } catch { Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_ }
                # After every ContentRendered handler: the remembered OU of Rechercher is then known to be restoring.
                try { [void]$script:Window.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::ApplicationIdle,[Action]{ try { Request-DomeniaFleetRefresh } catch { Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_ } }) } catch { Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_ }
                Write-AppLog "Pret. Base=$($script:Conn.BaseDn) Server=$($script:Conn.Server) AD=$($script:Conn.BindUser) WIN=$script:ProcessIdentity Demo=$([bool]$script:DemoMode)" "INFO"
                Update-Dashboard
            }catch{Write-AppLog "ContentRendered : $($_.Exception.ToString())" "ERROR"}
            # D089: one activation request at the switch from login to main window, logged, never repeated.
            try { [void](Request-DomeniaWindowActivation -Window $script:Window -Trigger 'LoginToMain') } catch { Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_ }
            try { [void](Update-DomeniaIdlePolicy) } catch { Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_ }
            # Tout ce qui peut ouvrir une fenetre attend que la principale
            # soit peinte et que le fil graphique soit libre. Sinon la boite
            # n a pas de proprietaire et se cache derriere l ecran de
            # demarrage, qui reste au premier plan.
            try{
                [void]$script:Window.Dispatcher.BeginInvoke(
                    [System.Windows.Threading.DispatcherPriority]::ApplicationIdle,
                    [Action]{
                        # FI-19: figures read off the Dispatcher; the notices on the age of the base and on its first
                        # build follow the answer (Complete-DomeniaIndexMetadataUi).
                        try { Request-DomeniaIndexMetadata -StartupChecks } catch { Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_ }
                        try { [void](Set-DomeniaControlText -Name "LblParkStatus" -Text "Etat du parc charge a la demande.") } catch { Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_ }
                        try { Request-DomeniaParkSweepAtStartup } catch { Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_ }
                        try { Add-DomeniaUiLog -Area "Demarrage" -Text "Politique V10.22 : aucune operation longue AD/reseau n'est lancee automatiquement ; recherche globale verifie toujours LDAP ; comptes editables sans reset." } catch { Write-DomeniaSwallowed 'Core' 'Initialize-Window' $_ }
                    })
            }catch{Write-AppLog "Amorcage differe de l index impossible : $($_.Exception.Message)" "WARN"}
        })
        if (-not $script:StartupReady) { throw "La fenetre principale ne peut pas etre affichee : barriere de disponibilite non validee." }
        Write-StartupTrace -Stage "Initialisation" -Status "OK" -Detail "Fenetre principale prete ; moteur asynchrone valide et cache initial facultatif"
    }
    catch {
        Write-StartupTrace -Stage "Initialisation" -Status "ERROR" -Detail $_.Exception.ToString()
        throw
    }
    finally { Close-DomeniaStartupWindow }
}



# =====================================================================
# Domenia 1.0
# Authentification courte et bornee dans un runspace MTA interne.
# Le login effectue un bind LDAP reel, lit RootDSE et valide la base detectee
# dans un runspace borne afin que le thread WPF ne soit jamais bloque.
# =====================================================================
$script:DomeniaBuild = "Domenia 1.0"
$script:FastLoginUi = $null
$script:FastLoginState = $null
$script:FastLoginTimer = $null
$script:FastLoginLogPath = ""
$script:FastLoginMode = "Standard"

function Get-DomeniaFastLoginLogPath {
    $validated=$false
    try {Initialize-DomeniaDataStore | Out-Null;$validated=[bool]$script:DataStoreValidated}catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaFastLoginLogPath' $_ }
    if(-not [string]::IsNullOrWhiteSpace([string]$script:FastLoginLogPath)){return [string]$script:FastLoginLogPath}
    $candidates=New-Object 'System.Collections.Generic.List[string]'
    if($validated){
        foreach($category in @($script:StorageLayout.Categories)){
            if([string]$category.Category -eq 'Cache'){
                foreach($area in @($category.Areas)){if([string]$area.Name -eq 'Logs' -and [string]$area.Path){$candidates.Add([string]$area.Path)}}
            }
        }
    } else {
        # Explicit emergency trace when data storage is refused; preferences never follow it.
        if(-not [string]::IsNullOrWhiteSpace([string]$env:LOCALAPPDATA)){$candidates.Add((Join-Path $env:LOCALAPPDATA 'DOMENIA\Logs'))}
        $candidates.Add((Join-Path ([IO.Path]::GetTempPath()) 'DOMENIA\Logs'))
    }
    foreach($logs in $candidates){
        $probe=''
        try {
            $folder=[IO.DirectoryInfo]::new($logs)
            while($null -ne $folder){if($folder.Exists -and ($folder.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Journal redirige refuse.'};$folder=$folder.Parent}
            [void][IO.Directory]::CreateDirectory($logs)
            $probe=Join-Path $logs ('.write-'+[guid]::NewGuid().ToString('N'))
            $stream=[IO.File]::Open($probe,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);$stream.Dispose()
            $script:FastLoginLogPath=Join-Path $logs 'Domenia-login.log'
            return [string]$script:FastLoginLogPath
        } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaFastLoginLogPath' $_ }
        finally {if($probe -and [IO.File]::Exists($probe)){[IO.File]::Delete($probe)}}
    }
    return ''
}


function Write-DomeniaFastLoginLog {
    param(
        [string]$Stage,
        [string]$Status = "INFO",
        [string]$Detail = "",
        [long]$DurationMs = 0
    )
    $Detail = Protect-DomeniaLogText $Detail
    try {
        $path = Get-DomeniaFastLoginLogPath
        $clean = (($Detail + "") -replace "[\r\n\t]+", " ").Trim()
        $line = "{0}`tPID={1}`tTID={2}`tBUILD={3}`t{4}`t{5}`t{6}`t{7}{8}" -f `
            (Get-Date).ToString("yyyy-MM-dd HH:mm:ss.fff"), `
            $PID, `
            [System.Threading.Thread]::CurrentThread.ManagedThreadId, `
            $script:DomeniaBuild, `
            $Stage, `
            $Status, `
            $DurationMs, `
            $clean, `
            [Environment]::NewLine
        [System.IO.File]::AppendAllText($path, $line, (New-Object System.Text.UTF8Encoding($false)))
    }
    catch { Write-DomeniaSwallowed 'Core' 'Write-DomeniaFastLoginLog' $_ }
    try { Write-StartupTrace -Stage "Login/$Stage" -Status $Status -Detail $Detail -DurationMs $DurationMs } catch { Write-DomeniaSwallowed 'Core' 'Write-DomeniaFastLoginLog' $_ }
}

function New-DomeniaFastLoginSession {
    param(
        [string]$Login,
        [Security.SecureString]$SecurePassword,
        [string]$Domain,
        [string]$Netbios,
        [string]$ConfiguredBase,
        [string]$ConfiguredServer,
        [int]$TimeoutSeconds = 20,
        [switch]$UseCurrentCredentials,
        [switch]$Demo
    )

    $overallTimeout = [Math]::Max(8,[Math]::Min(45,$TimeoutSeconds))
    $perServerTimeout = [Math]::Max(2,[Math]::Min(10,[int](Get-CfgValue "Auth" "PerServerTimeoutSeconds" 6)))
    $maxServers = [Math]::Max(1,[Math]::Min(8,[int](Get-CfgValue "Auth" "MaxServerCandidates" 4)))
    $credential = $null
    $secure = $null
    if ($Demo) {
        # D002: no SecureString, no PSCredential: the demonstration request carries only the identity.
        $demoRequest = [pscustomobject]@{
            Login = [string]$Login; Credential = $null; PasswordLength = 0; UseCurrentCredentials = $false
            DemoOnly = $true; DemoIdentity = [string]$Login
            Domain = "demo.invalid"; Netbios = "DEMO"; ConfiguredBase = "DC=demo,DC=invalid"; ConfiguredServer = ""
            OverallTimeoutSeconds = $overallTimeout; PerServerTimeoutSeconds = $perServerTimeout; MaxServers = 1
        }
        return [pscustomobject]@{
            Id = [guid]::NewGuid().ToString("N"); Request = $demoRequest; Progress = $null; PowerShell = $null; Runspace = $null; AsyncResult = $null
            StartedAt = Get-Date; Deadline = (Get-Date).AddSeconds($overallTimeout + 3); LastProgressSequence = -1; LastHeartbeat = -1
            UseCurrentCredentials = $false; EndInvoked = $false; Cleaned = $false; CancelRequested = $false
            CleanupRetryAt = [datetime]::MinValue; CleanupGiveUpAt = [datetime]::MinValue
        }
    }
    if (-not $UseCurrentCredentials) {
        # SE-16: the secret arrives as the SecureString of the PasswordBox or of the Windows vault. It is copied and
        # sealed for the worker; it is never rebuilt from a plain string.
        if (($null -eq $SecurePassword) -or ($SecurePassword.Length -eq 0)) { throw 'Mot de passe requis.' }
        $secure = $SecurePassword.Copy()
        $secure.MakeReadOnly()
        $credential = New-Object System.Management.Automation.PSCredential -ArgumentList @([string]$Login,$secure)
    }

    $request = [pscustomobject]@{
        Login = if ($UseCurrentCredentials) { "" } else { [string]$Login }
        Credential = $credential
        PasswordLength = if ($UseCurrentCredentials) { 0 } else { $secure.Length }
        UseCurrentCredentials = [bool]$UseCurrentCredentials
        Domain = [string]$Domain
        Netbios = [string]$Netbios
        ConfiguredBase = [string]$ConfiguredBase
        ConfiguredServer = [string]$ConfiguredServer
        OverallTimeoutSeconds = $overallTimeout
        PerServerTimeoutSeconds = $perServerTimeout
        MaxServers = $maxServers
    }

    return [pscustomobject]@{
        Id = [guid]::NewGuid().ToString("N")
        Request = $request
        OwnedSecret = $secure
        Progress = $null
        PowerShell = $null
        Runspace = $null
        AsyncResult = $null
        StartedAt = Get-Date
        Deadline = (Get-Date).AddSeconds($overallTimeout + 3)
        LastProgressSequence = -1
        LastHeartbeat = -1
        UseCurrentCredentials = [bool]$UseCurrentCredentials
        EndInvoked = $false
        Cleaned = $false
        CancelRequested = $false
        CleanupRetryAt = [datetime]::MinValue
        CleanupGiveUpAt = [datetime]::MinValue
    }
}

function Start-DomeniaFastLoginWorker {
    param([Parameter(Mandatory=$true)]$Session)
    $worker = Start-DomeniaLoginAuthRunspace -Request $Session.Request
    $Session.Progress = $worker.Progress
    $Session.PowerShell = $worker.PowerShell
    $Session.Runspace = $worker.Runspace
    $Session.AsyncResult = $worker.AsyncResult
    $Session.StartedAt = $worker.StartedAt
    $Session.EndInvoked = $false
    $Session.Cleaned = $false
    $authMode = if ([bool]$Session.UseCurrentCredentials) { "Windows" } else { "Explicit" }
    Write-DomeniaFastLoginLog -Stage "AUTH_STARTED" -Status "OK" -Detail "Mode=$authMode Runspace=MTA Processus=$PID"
    return $Session
}

function Stop-DomeniaFastLoginWorker {
    param($Session,[switch]$Kill,[switch]$KeepDiagnostics)
    if ($null -eq $Session) { return }
    try {
        if ($Kill) { Write-DomeniaFastLoginLog -Stage "AUTH_CANCEL" -Status "WARN" -Detail "Annulation asynchrone du runspace interne." }
        if($null -eq $Session.AsyncResult){Complete-DomeniaLoginAuthRunspaceCleanup -Session $Session}
        else{Stop-DomeniaLoginAuthRunspace -Session $Session -Terminate:$Kill}
    }
    catch { Write-DomeniaFastLoginLog -Stage "AUTH_CANCEL" -Status "ERROR" -Detail $_.Exception.Message }
    try { if ($null -ne $Session.Request) { $Session.Request.Credential = $null } } catch { Write-DomeniaSwallowed 'Core' 'Stop-DomeniaFastLoginWorker' $_ }
}

function Get-DomeniaFastLoginVaultIdentity {
    # Metadata only. Merely opening the form or changing the login never reads the vault.
    $ui=$script:FastLoginUi
    if($null -eq $ui -or [bool]$script:DemoMode){return $null}
    $domain=([string](Get-CfgValue 'Auth' 'VaultDomainDn' '')).Trim()
    $account=([string](Get-CfgValue 'Auth' 'VaultUserName' '')).Trim()
    if(-not $domain -or -not $account -or ([string]$ui.Login.Text).Trim() -ine $account){return $null}
    $configured=if([bool](Get-CfgValue 'Conf' 'AutoDiscover' $true)){''}else{([string](Get-CfgValue 'Conf' 'SearchBase' '')).Trim()}
    if([string]$SearchBase){$configured=([string]$SearchBase).Trim()}
    if($configured -and $configured -ine $domain -and -not $configured.EndsWith(','+$domain,[StringComparison]::OrdinalIgnoreCase)){return $null}
    try{$target=Get-DomeniaCredentialVaultTarget -DomainDn $domain -Scope Directory -UserName $account}catch{return $null}
    return [pscustomobject]@{DomainDn=$domain;UserName=$account;Target=$target}
}

function Update-DomeniaFastLoginVaultUi {
    param([bool]$Busy=$false)
    $ui=$script:FastLoginUi;if($null -eq $ui){return}
    $identity=Get-DomeniaFastLoginVaultIdentity
    $blocked=($null -ne $identity -and $null -ne $script:FastLoginVaultRejected -and $script:FastLoginVaultRejected.ContainsKey($identity.Target))
    if($null -ne $ui.VaultUse){$ui.VaultUse.IsEnabled=(-not $Busy -and $null -ne $identity -and -not $blocked)}
    if($null -ne $ui.VaultForget){$ui.VaultForget.IsEnabled=(-not $Busy -and $null -ne $identity)}
    if($null -ne $ui.VaultRemember){$ui.VaultRemember.IsEnabled=(-not $Busy -and -not [bool]$script:DemoMode)}
    if($null -ne $ui.VaultUse){$ui.VaultUse.ToolTip=if($blocked){'Cet identifiant du coffre a déjà été essayé. Corrigez manuellement le mot de passe avant un nouvel usage.'}else{'Utilise une fois le compte exact affiché, sur ce PC. Aucune lecture automatique du coffre.'}}
}

function Remove-DomeniaFastLoginVault {
    $state=$script:FastLoginState;if($null -eq $state -or $null -ne $state.Session){return}
    $identity=Get-DomeniaFastLoginVaultIdentity;if($null -eq $identity){return}
    $deleted=$false
    try{
        [void](Remove-DomeniaCredentialVaultCredential -DomainDn $identity.DomainDn -Scope Directory -UserName $identity.UserName -Enabled)
        $deleted=$true
        $script:Config.Auth.VaultDomainDn='';$script:Config.Auth.VaultUserName='';Save-AppConfig -ThrowOnFailure
        $script:FastLoginUi.Error.Text='Identifiant oublié dans le coffre de ce PC.'
    }catch{$script:FastLoginUi.Error.Text=if($deleted){'Secret supprimé du coffre ; préférence locale HKCU non effacée.'}else{'Impossible de supprimer cet identifiant du coffre Windows.'}}
    Update-DomeniaFastLoginVaultUi
}

function Save-DomeniaFastLoginVaultPreference {
    param($Result,[Management.Automation.PSCredential]$Credential)
    $state=$script:FastLoginState
    if($null -eq $state -or $null -eq $Credential -or [bool]$script:DemoMode -or -not [bool]$Result.Success -or [bool]$state.UseCurrentCredentials){return}
    $domain=Convert-DomainToDn ([string]$Result.Domain)
    if(-not $domain){$domain=([string]$Result.BaseDn).Trim()}
    $account=([string]$Credential.UserName).Trim()
    $target=Get-DomeniaCredentialVaultTarget -DomainDn $domain -Scope Directory -UserName $account
    # A successful manual correction can re-enable this exact remembered identity. No shared account guard is reset.
    if($null -ne $script:FastLoginVaultRejected){[void]$script:FastLoginVaultRejected.Remove($target)}
    if(-not [bool]$state.VaultRemember){return}
    $vaultSaved=$false
    try{
        [void](Save-DomeniaCredentialVaultCredential -DomainDn $domain -Scope Directory -Credential $Credential -Enabled -AuthenticationConfirmed)
        $vaultSaved=$true
        $script:Config.Auth.VaultDomainDn=$domain;$script:Config.Auth.VaultUserName=$account;Save-AppConfig -ThrowOnFailure
    }catch{
        # Login stays valid if optional persistence is unavailable; never fall back to a file or SQLite secret.
        $message=if($vaultSaved){'Connexion validée et secret dans le coffre Windows ; mémorisation du domaine et du compte dans HKCU impossible.'}else{'Connexion validée ; enregistrement facultatif dans le coffre Windows impossible.'}
        Write-DomeniaFastLoginLog -Stage 'VAULT_SAVE' -Status 'WARN' -Detail $message
        try{Write-AppLog $message 'WARN'}catch{Write-DomeniaSwallowed 'Core' 'Save-DomeniaFastLoginVaultPreference' $_}
    }
}

function Set-DomeniaFastLoginBusy {
    param([bool]$Busy)
    $ui = $script:FastLoginUi
    if ($null -eq $ui) { return }
    # SE-16: a validation never starts or runs with the password shown.
    if ($Busy) { try { Hide-DomeniaSecretPeek -Owner 'Timer:LoginPasswordPeek' } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaFastLoginBusy' $_ } }
    foreach ($name in @("Login","Password","Reveal","Remember","Connect","OtherAccount")) {
        try { $ui[$name].IsEnabled = -not $Busy } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaFastLoginBusy' $_ }
    }
    try {
        $allowWindowsSession = [bool](Get-CfgValue "Auth" "AllowWindowsSession" $true)
        $windowsIdentity = Get-DomeniaProcessWindowsIdentity
        $ui.Windows.IsEnabled = ((-not $Busy) -and $allowWindowsSession -and -not [string]::IsNullOrWhiteSpace($windowsIdentity))
    }
    catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaFastLoginBusy' $_ }
    if ([bool]$script:DemoMode) {
        # D002: in demonstration no password can be typed and no Windows session is offered, busy or not.
        foreach ($name in @("Password","Reveal","Remember","Windows")) {
            try { $ui[$name].IsEnabled = $false } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaFastLoginBusy' $_ }
        }
    }
    # Standard view keeps the same outer dimensions throughout a validation attempt.
    # Debug view deliberately keeps its existing diagnostic presentation.
    if ($ui.Window -is [Windows.Window] -and $null -ne $ui.Window.FindName('PanelSplash')) {
        if ($Busy -and $ui.Window.IsLoaded) {
            $height = $ui.Window.ActualHeight
            $ui.Window.SizeToContent = [Windows.SizeToContent]::Manual
            $ui.Window.Height = [Math]::Min($height,$ui.Window.MaxHeight)
        }
        elseif (-not $Busy) {
            $ui.Window.SizeToContent = [Windows.SizeToContent]::Height
            $ui.Window.Height = [double]::NaN
        }
    }
    Update-DomeniaFastLoginVaultUi -Busy $Busy
    try { $ui.Cancel.Content = if ($Busy) { 'Arrêter' } else { 'Annuler' } } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaFastLoginBusy' $_ }
    try { $ui.Progress.Visibility = if ($Busy) { [System.Windows.Visibility]::Visible } else { [System.Windows.Visibility]::Collapsed } } catch { Write-DomeniaSwallowed 'Core' 'Set-DomeniaFastLoginBusy' $_ }
}

function Add-DomeniaFastLoginDetail {
    param([string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text) -or $null -eq $script:FastLoginUi) { return }
    try {
        $script:FastLoginUi.Technical.AppendText("[$((Get-Date).ToString('HH:mm:ss.fff'))] $Text`r`n")
        $script:FastLoginUi.Technical.ScrollToEnd()
    }
    catch { Write-DomeniaSwallowed 'Core' 'Add-DomeniaFastLoginDetail' $_ }
}

function Reset-DomeniaFastLoginAttempt {
    param([switch]$Kill,[switch]$KeepDiagnostics)
    try { if ($null -ne $script:FastLoginTimer) { $script:FastLoginTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Reset-DomeniaFastLoginAttempt' $_ }
    $script:FastLoginTimer = $null
    if ($null -ne $script:FastLoginState -and $null -ne $script:FastLoginState.Session) {
        Stop-DomeniaFastLoginWorker -Session $script:FastLoginState.Session -Kill:$Kill -KeepDiagnostics:$KeepDiagnostics
    }
    if ($null -ne $script:FastLoginState) {
        $script:FastLoginState.Session = $null
    }
    Set-DomeniaFastLoginBusy $false
}

function Complete-DomeniaFastLoginSuccess {
    param($Result,$Credential)
    $state = $script:FastLoginState
    $ui = $script:FastLoginUi
    if ($null -eq $state -or $null -eq $ui) { return }

    # D002/C2: a demonstration result is accepted only in demonstration mode, and the reverse.
    $isDemo = ($null -ne $Result.PSObject.Properties["AuthMethod"] -and [string]$Result.AuthMethod -ceq 'Demo.InMemory')
    if ($isDemo -ne [bool]$script:DemoMode) { throw 'Mode demonstration incoherent : connexion refusee.' }
    if ($isDemo) {
        $script:Conn.Connected = $true
        $script:Conn.AuthMode = 'Demo'
        $script:Conn.UseCredential = $false
        $script:Conn.Credential = $null
        $script:Conn.User = [string]$Result.BindUser
        $script:Conn.BindUser = [string]$Result.BindUser
        $script:Conn.Domain = [string]$Result.Domain
        $script:Conn.Netbios = [string]$Result.Netbios
        $script:Conn.BaseDn = [string]$Result.BaseDn
        $script:Conn.Server = [string]$Result.Server
        $script:Conn.RootPath = [string]$Result.RootPath
        $script:Conn.LastError = ""
        $script:DirectoryCredentialFaulted = $false
        $script:DirectoryCredentialFaultMessage = ""
        $script:ActualDeniedCapabilities = @{}
        $script:ActualSecretDeniedDn = ""
        try { if ($null -ne $script:DomeniaProviderState) { Reset-DomeniaProviderState -State $script:DomeniaProviderState } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaFastLoginSuccess' $_ }
        # Nothing is remembered in HKCU in demonstration (no Save-AppConfig).
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Success")
        $ui.Error.Text = "Identité de démonstration acceptée — aucune connexion AD."
        $ui.Stage.Text = "Démonstration prête en $([Math]::Round(([long]$Result.DurationMs / 1000),2)) s."
        Write-DomeniaFastLoginLog -Stage "LOGIN_OK" -Status "OK" -Detail "Compte=$($Result.BindUser) Mode=Demo Base=$($Result.BaseDn)" -DurationMs ([long]$Result.DurationMs)
        $state.LoginOk = $true
        Set-DomeniaSurfaceResult $ui.Window $true
        return
    }

    $windowsSession = [bool]$state.UseCurrentCredentials
    if ($null -ne $Result.PSObject.Properties["AuthMode"] -and [string]$Result.AuthMode -eq "Windows") { $windowsSession = $true }
    $script:Conn.Connected = $true
    $script:Conn.AuthMode = if ($windowsSession) { "Windows" } else { "Explicit" }
    $script:Conn.UseCredential = -not $windowsSession
    $script:Conn.User = if ($windowsSession) { [string]$Result.BindUser } else { [string]$state.Login }
    $script:Conn.BindUser = [string]$Result.BindUser

    # Conserver le mot de passe uniquement en SecureString, mais reconstruire le
    # PSCredential avec l'identite QUI A REELLEMENT REUSSI le bind de validation.
    # Sans cela, le login peut reussir avec CNAMTS\user puis les workers recevoir
    # encore le PSCredential "user" d'origine et echouer immediatement sur FindAll.
    if ($windowsSession) {
        $script:Conn.Credential = $null
    }
    else {
        if ($null -eq $Credential) { throw "Credential AD explicite absent apres validation." }
        $validatedBindUser = ([string]$Result.BindUser).Trim()
        if ([string]::IsNullOrWhiteSpace($validatedBindUser)) { $validatedBindUser = ([string]$Credential.UserName).Trim() }
        if ([string]$Credential.UserName -ieq $validatedBindUser) {
            $script:Conn.Credential = $Credential
        }
        else {
            $script:Conn.Credential = New-Object System.Management.Automation.PSCredential -ArgumentList @($validatedBindUser,$Credential.Password)
        }
    }
    # Un login valide rearme explicitement le coupe-circuit AD, meme si le moteur
    # asynchrone etait deja initialise dans ce processus.
    $script:DirectoryCredentialFaulted = $false
    $script:DirectoryCredentialFaultMessage = ""
    # D018: an explicit reconnection is the change of account that lifts the per-resource refusals.
    try { if ($null -ne $script:DomeniaProviderState) { Reset-DomeniaProviderState -State $script:DomeniaProviderState } } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaFastLoginSuccess' $_ }
    $script:Conn.Domain = [string]$Result.Domain
    $script:Conn.Netbios = [string]$Result.Netbios
    $script:Conn.BaseDn = [string]$Result.BaseDn
    $script:Conn.Server = [string]$Result.Server
    $script:Conn.RootPath = [string]$Result.RootPath
    $script:Conn.LastError = ""
    $script:ActualDeniedCapabilities = @{}
    $script:ActualSecretDeniedDn = ""

    if (-not $windowsSession) {
        $script:Config.Auth.RememberLogin = [bool]$ui.Remember.IsChecked
        $script:Config.Auth.LastLogin = if ([bool]$ui.Remember.IsChecked) { [string]$state.Login } else { "" }
        Save-AppConfig
    }

    if(-not $windowsSession){Save-DomeniaFastLoginVaultPreference -Result $Result -Credential $script:Conn.Credential}
    $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Success")
    $ui.Error.Text = if ($windowsSession) { 'Session Windows validée.' } else { 'Compte validé.' }
    $ui.Stage.Text = "Connexion terminée en $([Math]::Round(([long]$Result.DurationMs / 1000),2)) s."
    $authMethod = if ($null -ne $Result.PSObject.Properties["AuthMethod"]) { [string]$Result.AuthMethod } else { "LDAP" }
    Add-DomeniaFastLoginDetail "Compte valide : $($Result.BindUser) ; mode=$($script:Conn.AuthMode) ; methode=$authMethod ; serveur=$($Result.Server) ; base=$($Result.BaseDn)."
    Write-DomeniaFastLoginLog -Stage "LOGIN_OK" -Status "OK" -Detail "Compte=$($Result.BindUser) Mode=$($script:Conn.AuthMode) Serveur=$($Result.Server) Base=$($Result.BaseDn)" -DurationMs ([long]$Result.DurationMs)

    if (-not $windowsSession -and $null -eq $script:Conn.Credential) {
        throw "Le credential de la session AD n a pas ete conserve en memoire. Connexion annulee pour eviter une interface inutilisable."
    }
    $state.LoginOk = $true
    try { $ui.Password.Password = "" } catch { Write-DomeniaSwallowed 'Core' 'Complete-DomeniaFastLoginSuccess' $_ }
    Set-DomeniaSurfaceResult $ui.Window $true
}

function Update-DomeniaFastLoginAttempt {
    $state = $script:FastLoginState
    $ui = $script:FastLoginUi
    if ($null -eq $state -or $null -eq $state.Session -or $null -eq $ui) { return }
    $session = $state.Session

    try {
        $elapsed = [int]((Get-Date) - $session.StartedAt).TotalSeconds
        $sequence = -1
        try { $sequence = [int]$session.Progress["Sequence"] } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaFastLoginAttempt' $_ }
        if ($sequence -ne [int]$session.LastProgressSequence) {
            $session.LastProgressSequence = $sequence
            $stage = ""
            $detail = ""
            try { $stage = [string]$session.Progress["Stage"] } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaFastLoginAttempt' $_ }
            try { $detail = [string]$session.Progress["Detail"] } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaFastLoginAttempt' $_ }
            if (-not [string]::IsNullOrWhiteSpace($stage) -or -not [string]::IsNullOrWhiteSpace($detail)) {
                $signature = "$stage|$detail"
                $ui.Stage.Text = "$stage  $detail  ${elapsed}s"
                Add-DomeniaFastLoginDetail "$stage : $detail"
                Write-DomeniaFastLoginLog -Stage "PROGRESS" -Detail $signature
            }
        }
        else {
            $ui.Stage.Text = "Validation Active Directory en mémoire, ${elapsed} s"
        }

        if ($elapsed -ne [int]$session.LastHeartbeat) {
            $session.LastHeartbeat = $elapsed
            Write-DomeniaFastLoginLog -Stage "HEARTBEAT" -Detail "Elapsed=${elapsed}s Runspace=MTA Processus=$PID"
        }

        $completed = $false
        try { $completed = [bool]$session.AsyncResult.IsCompleted } catch { $completed = $true }
        if (-not $completed -and (Get-Date) -lt $session.Deadline) { return }
        if (-not $completed) {
            $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
            $ui.Error.Text = [string](Get-DomeniaLoginFailureText -Category 'Timeout').Text
            $ui.Stage.Text = 'Validation arrêtée après le délai prévu, sans bloquer la fenêtre.'
            Write-DomeniaFastLoginLog -Stage "TIMEOUT" -Status "ERROR" -Detail "Runspace MTA interne ; delai depasse."
            Reset-DomeniaFastLoginAttempt -Kill
            return
        }

        try { if ($null -ne $script:FastLoginTimer) { $script:FastLoginTimer.Stop() } } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaFastLoginAttempt' $_ }
        $script:FastLoginTimer = $null
        Write-DomeniaFastLoginLog -Stage "AUTH_COMPLETED" -Detail "Runspace MTA termine."

        $result = $null
        try { $result = Read-DomeniaAuthRunspaceResult -Session $session }
        catch {
            $detail = [string]$_.Exception.Message
            $failure = Get-DomeniaLoginFailureText -Message $detail
            Write-DomeniaFastLoginLog -Stage "NO_RESULT" -Status "ERROR" -Detail $detail
            Add-DomeniaFastLoginDetail $detail
            $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
            $ui.Error.Text = $failure.Text
            $ui.Stage.Text = 'Résultat de validation illisible : ' + $failure.Message
            $state.Session = $null
            Complete-DomeniaLoginAuthRunspaceCleanup -Session $session
            Set-DomeniaFastLoginBusy $false
            return
        }

        $validatedCredential = $null
        if($null -ne $result -and [bool]$result.Success -and -not [bool]$session.UseCurrentCredentials -and $null -ne $session.Request.Credential){
            $validatedCredential=[Management.Automation.PSCredential]::new($session.Request.Credential.UserName,$session.Request.Credential.Password.Copy())
        }
        $state.Session = $null
        Complete-DomeniaLoginAuthRunspaceCleanup -Session $session

        if ($null -eq $result -or -not [bool]$result.Success) {
            $errorText = if (($null -ne $result) -and (-not [string]::IsNullOrWhiteSpace([string]$result.Error))) { [string]$result.Error } else { "" }
            $rawMessage = if ($errorText) { $errorText } else { "Aucun motif renvoyé par la validation." }
            $errorCategory = ""
            try { $errorCategory = [string]$result.ErrorCategory } catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaFastLoginAttempt' $_ }
            # UI-20: a polite sentence with the next step on screen. The Active Directory code and the technical text
            # only go to the diagnostic (Copier le diagnostic) and to the connection log.
            $failure = Get-DomeniaLoginFailureText -Category $errorCategory -Message $errorText
            $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
            $ui.Error.Text = $failure.Text
            $ui.Stage.Text = 'Motif : ' + $failure.Message + $(if ($failure.Code) { ' Code Active Directory : ' + $failure.Code + '.' } else { '' })
            # Keep the technical cause in the log, not only the shortened UI message.
            Add-DomeniaFastLoginDetail $rawMessage
            if ($failure.Code) { Add-DomeniaFastLoginDetail ('Code Active Directory : ' + $failure.Code) }
            if ($null -ne $result) {
                $diagnosticProperty = $result.PSObject.Properties['Diagnostic']
                if ($null -ne $diagnosticProperty -and $null -ne $diagnosticProperty.Value) {
                    $d = $diagnosticProperty.Value
                    $diagnosticText = 'Category={0}; Stage={1}; ErrorId={2}; Type={3}; HResult={4}; WorkerLine={5}; CredentialAttempted={6}; Stack={7}; Server={8}; BindIdentity={9}; NativeMessage={10}; ExtendedCode={11}; ExtendedMessage={12}; LdapCode={13}' -f $errorCategory,$d.Stage,$d.ErrorId,$d.ExceptionType,$d.HResult,$d.WorkerLine,$d.CredentialAttempted,$d.Stack,$d.Server,$d.BindIdentity,$d.NativeMessage,$d.ExtendedCode,$d.ExtendedMessage,$d.LdapCode
                    Add-DomeniaFastLoginDetail $diagnosticText
                    Write-DomeniaFastLoginLog -Stage "LOGIN_DIAGNOSTIC" -Status "ERROR" -Detail $diagnosticText
                }
            }
            Write-DomeniaFastLoginLog -Stage "LOGIN_ERROR" -Status "ERROR" -Detail $rawMessage -DurationMs $(if($null -ne $result){[long]$result.DurationMs}else{0})
            Set-DomeniaFastLoginBusy $false
            return
        }

        try{Complete-DomeniaFastLoginSuccess -Result $result -Credential $validatedCredential}
        finally{if($null -ne $validatedCredential -and ($null -eq $script:Conn.Credential -or -not [object]::ReferenceEquals($validatedCredential.Password,$script:Conn.Credential.Password))){$validatedCredential.Password.Dispose()};$validatedCredential=$null}
    }
    catch {
        $detail = $_.Exception.ToString()
        Write-DomeniaFastLoginLog -Stage "MONITOR_ERROR" -Status "ERROR" -Detail $detail
        Add-DomeniaFastLoginDetail $detail
        try {
            # A refusal reported by the exception keeps its own wording; anything else is an internal error, never a
            # verdict on the password. The exception text stays in the diagnostic.
            $failure = Get-DomeniaLoginFailureText -Message $detail
            if ($failure.Kind -ne 'BadCredentials') { $failure = Get-DomeniaLoginFailureText -Category 'Internal' -Message $detail }
            $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
            $ui.Error.Text = $failure.Text
            $ui.Stage.Text = 'La fenêtre reste utilisable ; détail dans Domenia-login.log.'
        }
        catch { Write-DomeniaSwallowed 'Core' 'Update-DomeniaFastLoginAttempt' $_ }
        Reset-DomeniaFastLoginAttempt -Kill
    }
}

function Test-DomeniaComputerAccountIdentity {
    param([AllowNull()][string]$Identity)

    $value = ([string]$Identity).Trim()
    if ([string]::IsNullOrWhiteSpace($value)) { return $false }

    $account = $value
    if ($account.Contains([string][char]92)) { $account = $account.Split([char]92)[-1] }
    if ($account.Contains("@")) { $account = $account.Split("@")[0] }

    return $account.EndsWith([string][char]36)
}

function Get-DomeniaProcessWindowsIdentity {
    $identity = ""
    try { $identity = [string][System.Security.Principal.WindowsIdentity]::GetCurrent().Name } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaProcessWindowsIdentity' $_ }
    if ([string]::IsNullOrWhiteSpace($identity)) {
        try { $identity = "$env:USERDOMAIN\$env:USERNAME" } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaProcessWindowsIdentity' $_ }
    }

    # Un EXE demarre par SYSTEM peut s'executer sous DOMAIN\POSTE$.
    # Ce compte ordinateur ne doit jamais etre presente comme un login utilisateur.
    if (Test-DomeniaComputerAccountIdentity -Identity $identity) { return "" }
    if ($identity -match '^(?i:NT AUTHORITY|BUILTIN)\\') { return "" }
    try {
        if ($identity.Contains([string][char]92)) {
            $identityDomain = $identity.Split([char]92)[0]
            if (-not [string]::IsNullOrWhiteSpace([string]$env:COMPUTERNAME) -and $identityDomain -ieq [string]$env:COMPUTERNAME) { return "" }
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaProcessWindowsIdentity' $_ }
    return $identity.Trim()
}

function Start-DomeniaFastLoginAttempt {
    param([switch]$UseCurrentCredentials,[switch]$UseVault)

    if($UseVault -and $UseCurrentCredentials){throw 'Choisissez un seul mode de connexion.'}
    $ui = $script:FastLoginUi
    $state = $script:FastLoginState
    if ($null -eq $ui -or $null -eq $state -or $null -ne $state.Session) { return }

    if ([bool]$script:DemoMode) {
        # D002/C2: demonstration identity only. No password is read, no domain discovery, no LDAP bind:
        # the same session, worker, timer and completion as production, with a request marked DemoOnly.
        if ($UseCurrentCredentials -or $UseVault) { return }
        $demoLogin = ([string]$ui.Login.Text).Trim()
        Write-DomeniaFastLoginLog -Stage "CLICK" -Detail "Compte=$demoLogin Mode=Demo"
        if (-not (Test-DomeniaDemoIdentity $demoLogin)) {
            $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
            $ui.Error.Text = "Identité de démonstration attendue (DEMO\nom)."
            return
        }
        $state.Login = $demoLogin
        $state.LoginOk = $false
        $state.UseCurrentCredentials = $false
        $ui.Technical.Clear()
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Muted")
        $ui.Error.Text = "Vérification de l'identité de démonstration, sans connexion AD."
        $ui.Stage.Text = "Démonstration : annuaire fictif en mémoire."
        Set-DomeniaFastLoginBusy $true
        try {
            $session = New-DomeniaFastLoginSession -Login $demoLogin -TimeoutSeconds 8 -Demo
            $state.Session = Start-DomeniaFastLoginWorker -Session $session
            # FI-05: protected standalone timer (connection, before the engine).
            $script:FastLoginTimer = New-DomeniaTimer -Owner 'Timer:FastLogin' -IntervalMs 200 -Standalone -RunWhenHidden -Start -Tick { Update-DomeniaFastLoginAttempt }
            Write-DomeniaFastLoginLog -Stage "TIMER_STARTED" -Detail "Interval=200ms Mode=Demo"
        }
        catch {
            Write-DomeniaFastLoginLog -Stage "START_ERROR" -Status "ERROR" -Detail $_.Exception.ToString()
            $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
            $ui.Error.Text = 'Impossible de démarrer la démonstration. Copiez le diagnostic ou ouvrez le journal.'
            Add-DomeniaFastLoginDetail $_.Exception.ToString()
            Reset-DomeniaFastLoginAttempt -Kill -KeepDiagnostics
        }
        return
    }

    $login = if ($UseCurrentCredentials) {
        Get-DomeniaProcessWindowsIdentity
    }
    else {
        ([string]$ui.Login.Text).Trim()
    }
    $secret=$null;$vaultCredential=$null;$vaultIdentity=$null
    if($UseVault){
        $vaultIdentity=Get-DomeniaFastLoginVaultIdentity
        if(($null -eq $vaultIdentity) -or (($null -ne $script:FastLoginVaultRejected) -and ($script:FastLoginVaultRejected.ContainsKey($vaultIdentity.Target)))){$ui.Error.Text='Corrigez manuellement les identifiants avant de réutiliser le coffre.';return}
        try{$vaultCredential=Get-DomeniaCredentialVaultCredential -DomainDn $vaultIdentity.DomainDn -Scope Directory -UserName $vaultIdentity.UserName -Enabled}
        catch{$ui.Error.Text='Le coffre Windows est indisponible pour cet identifiant.';return}
        if($null -eq $vaultCredential){$ui.Error.Text='Aucun identifiant enregistré dans le coffre pour ce compte.';return}
        $secret=$vaultCredential.Password
    }elseif(-not $UseCurrentCredentials){
        # SE-16: always the SecureString of the PasswordBox; its plain Password property is never read here.
        $secret=$ui.Password.SecurePassword
    }
    try {
    $modeLabel = if ($UseCurrentCredentials) { "Windows" } else { "Explicit" }
    Write-DomeniaFastLoginLog -Stage "CLICK" -Detail "Compte=$login Mode=$modeLabel"
    Add-DomeniaFastLoginDetail "Demande de connexion. Mode=$modeLabel Build=$($script:DomeniaBuild)."

    if (-not $UseCurrentCredentials -and [string]::IsNullOrWhiteSpace($login)) {
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
        $ui.Error.Text = "Identifiant manquant."
        return
    }
    if ((-not $UseCurrentCredentials) -and (($null -eq $secret) -or ($secret.Length -eq 0))) {
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
        $ui.Error.Text = "Mot de passe manquant."
        return
    }
    if (-not $UseCurrentCredentials -and (Test-DomeniaComputerAccountIdentity -Identity $login)) {
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
        $ui.Error.Text = 'Ce compte est un compte dʼordinateur : il ne peut pas ouvrir de session dans Domenia. Saisissez un compte utilisateur.'
        $ui.Stage.Text = 'Compte dʼordinateur refusé avant toute validation.'
        return
    }
    if ($UseCurrentCredentials -and [string]::IsNullOrWhiteSpace($login)) {
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
        $ui.Error.Text = 'La session Windows ouverte nʼest pas un compte utilisateur du domaine. Utilisez un autre compte.'
        $ui.Stage.Text = 'Domenia semble lancé sous SYSTEM, un compte local ou un compte dʼordinateur.'
        return
    }

    $autoDiscover = [bool](Get-CfgValue "Conf" "AutoDiscover" $true)
    $domain = if ($autoDiscover) { "" } else { [string](Get-CfgValue "Conf" "DOMAINE" "") }
    $netbios = if ($autoDiscover) { "" } else { [string](Get-CfgValue "Conf" "NETBIOS" "") }
    $baseDn = if ($autoDiscover) { "" } else { [string](Get-CfgValue "Conf" "SearchBase" "") }
    if (-not [string]::IsNullOrWhiteSpace($SearchBase)) { $baseDn = $SearchBase }
    if (-not $autoDiscover -and [string]::IsNullOrWhiteSpace($baseDn)) { $baseDn = Convert-DomainToDn $domain }
    $serverValue = if ($autoDiscover) { "" } else { [string](Get-CfgValue "Conf" "Server" "") }
    if (-not [string]::IsNullOrWhiteSpace($Server)) { $serverValue = $Server }
    $timeout = [Math]::Max(8,[Math]::Min(45,[int](Get-CfgValue "Auth" "LoginTimeoutSeconds" 30)))

    if($UseVault){$baseDn=$vaultIdentity.DomainDn}
    $state.VaultRemember=(-not $UseCurrentCredentials -and [bool]$ui.VaultRemember.IsChecked)
    $state.VaultUsed=[bool]$UseVault
    $state.Login = $login
    $state.LoginOk = $false
    $state.UseCurrentCredentials = [bool]$UseCurrentCredentials
    $ui.Technical.Clear()
    $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Muted")
    $ui.Error.Text = if ($UseCurrentCredentials) { 'Vérification de la session Windows…' } else { 'Vérification du compte…' }
    $ui.Stage.Text = 'Démarrage du contrôle Active Directory…'
    Set-DomeniaFastLoginBusy $true

    try {
        Write-DomeniaFastLoginLog -Stage "SESSION_CREATE" -Detail "Mode=$modeLabel Domaine=$domain Base=$baseDn Serveur=$serverValue Timeout=${timeout}s"
        $session = New-DomeniaFastLoginSession -Login $login -SecurePassword $secret -Domain $domain -Netbios $netbios -ConfiguredBase $baseDn -ConfiguredServer $serverValue -TimeoutSeconds $timeout -UseCurrentCredentials:$UseCurrentCredentials
        $state.Session=$session
        if($UseVault){
            if($null -eq $script:FastLoginVaultRejected){$script:FastLoginVaultRejected=@{}}
            $script:FastLoginVaultRejected[$vaultIdentity.Target]=$true
        }
        $state.Session = Start-DomeniaFastLoginWorker -Session $session
        # The PasswordBox is emptied once its sealed copy has left with the worker request.
        try { $ui.Password.Password = "" } catch { Write-DomeniaSwallowed 'Core' 'Start-DomeniaFastLoginAttempt' $_ }
        Add-DomeniaFastLoginDetail "Validation lancee dans un runspace MTA interne. Aucun processus enfant et aucun fichier de mot de passe ne sont utilises."

        # FI-05: protected standalone timer (connection, before the engine).
        $script:FastLoginTimer = New-DomeniaTimer -Owner 'Timer:FastLogin' -IntervalMs 200 -Standalone -RunWhenHidden -Start -Tick { Update-DomeniaFastLoginAttempt }
        Write-DomeniaFastLoginLog -Stage "TIMER_STARTED" -Detail "Interval=200ms IsEnabled=$($script:FastLoginTimer.IsEnabled)"
    }
    catch {
        $detail = $_.Exception.ToString()
        Write-DomeniaFastLoginLog -Stage "START_ERROR" -Status "ERROR" -Detail $detail
        Add-DomeniaFastLoginDetail $detail
        $ui.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Error")
        $ui.Error.Text = 'Impossible de lancer la validation. Copiez le diagnostic ou ouvrez le journal.'
        $ui.Stage.Text = 'Détail dans Domenia-login.log.'
        Reset-DomeniaFastLoginAttempt -Kill -KeepDiagnostics
    }
    }finally{if($null -ne $secret){$secret.Dispose()};$vaultCredential=$null}
}

function Get-DomeniaLoginWindowMode {
    $script:LoginWindowModeSource = "Valeur integree"

    # 1) Marqueur d urgence : sa presence force le mode Debug.
    $flagPath = Join-Path $script:RootDir "Domenia.login.debug"
    try {
        if (Test-Path -LiteralPath $flagPath -PathType Leaf) {
            $script:LoginWindowModeSource = $flagPath
            return "Debug"
        }
    }
    catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaLoginWindowMode' $_ }

    # 2) Fichier operateur simple : Standard ou Debug sur une ligne.
    # Les formes LoginMode=Debug et LoginWindowMode=Debug sont aussi admises.
    $modeCfgPath = Join-Path $script:RootDir "Domenia.login-mode.cfg"
    try {
        if (Test-Path -LiteralPath $modeCfgPath -PathType Leaf) {
            foreach ($line in @(Get-Content -LiteralPath $modeCfgPath -Encoding UTF8 -ErrorAction Stop)) {
                $candidate = ([string]$line).Trim()
                if ([string]::IsNullOrWhiteSpace($candidate) -or $candidate.StartsWith("#") -or $candidate.StartsWith(";")) { continue }
                if ($candidate -match '(?i)^(?:LoginMode|LoginWindowMode)\s*=\s*(.+)$') { $candidate = [string]$Matches[1] }
                $candidate = $candidate.Trim().Trim('"').Trim("'")
                $script:LoginWindowModeSource = $modeCfgPath
                $normalizedCfg = $candidate.ToLowerInvariant()
                if (@("debug","diagnostic","diag","verbose","detail","detailed","true","1","on","oui") -contains $normalizedCfg) { return "Debug" }
                if (@("standard","normal","production","prod","false","0","off","non") -contains $normalizedCfg) { return "Standard" }
                try { Write-StartupTrace -Stage "Login/Mode" -Status "WARN" -Detail "Valeur '$candidate' inconnue dans $modeCfgPath. Repli securise sur Standard." } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaLoginWindowMode' $_ }
                $script:LoginWindowModeSource = "$modeCfgPath (valeur invalide)"
                return "Standard"
            }
        }
    }
    catch {
        try { Write-StartupTrace -Stage "Login/Mode" -Status "WARN" -Detail "Lecture impossible de $modeCfgPath : $($_.Exception.Message). Repli sur Domenia.config.json." } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaLoginWindowMode' $_ }
    }

    # 3) Configuration JSON existante.
    $rawMode = [string](Get-CfgValue "Auth" "LoginWindowMode" "Standard")
    $script:LoginWindowModeSource = if (Test-Path -LiteralPath $script:CfgPath -PathType Leaf) { "$($script:CfgPath) / Auth.LoginWindowMode" } else { "Valeur integree Auth.LoginWindowMode" }
    $normalized = ($rawMode + "").Trim().ToLowerInvariant()
    if (@("debug","diagnostic","diag","verbose","detail","detailed","true","1","on","oui") -contains $normalized) { return "Debug" }
    if (@("standard","normal","production","prod","false","0","off","non","") -contains $normalized) { return "Standard" }

    try { Write-StartupTrace -Stage "Login/Mode" -Status "WARN" -Detail "Valeur '$rawMode' inconnue dans Auth.LoginWindowMode. Repli securise sur Standard." } catch { Write-DomeniaSwallowed 'Core' 'Get-DomeniaLoginWindowMode' $_ }
    $script:LoginWindowModeSource = "$($script:LoginWindowModeSource) (valeur invalide)"
    return "Standard"
}

function Get-DomeniaStandardLoginXaml {
    # Layout and scoped styles from FILPRO 2.5.0 RC1 Login.xaml / Controls.xaml.
    # Only presentation is shared. Domenia keeps its own authentication and diagnostics.
    return (Convert-DomeniaXamlToBootTheme -Xaml @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Domenia · Connexion" Width="480" SizeToContent="Height" MinWidth="340" MinHeight="0" WindowStartupLocation="CenterScreen" ResizeMode="NoResize" Background="{DynamicResource DomeniaBootWindow}" Foreground="{DynamicResource DomeniaBootText}" FontFamily="Segoe UI" FontSize="13" UseLayoutRounding="True" SnapsToDevicePixels="True" TextOptions.TextFormattingMode="Display" xml:lang="fr-FR" ShowInTaskbar="True" MaxHeight="800">
  <Window.Resources>
    <!-- Theme resources injected by Domenia before XAML loading. --></Window.Resources>
  <Grid x:Name="LoginRoot">
    <Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <Grid.Resources><Style TargetType="ToolTip">
    <Setter Property="Background" Value="{DynamicResource DomeniaBootSurface}"/><Setter Property="Foreground" Value="{DynamicResource DomeniaBootText}"/>
    <Setter Property="BorderBrush" Value="{DynamicResource DomeniaBootBorder}"/><Setter Property="BorderThickness" Value="1"/>
    <Setter Property="Padding" Value="14,11"/><Setter Property="FontSize" Value="12"/><Setter Property="MaxWidth" Value="430"/>
    <Setter Property="HasDropShadow" Value="True"/>
    <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ToolTip">
      <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" Padding="{TemplateBinding Padding}" CornerRadius="10">
        <ContentPresenter/>
      </Border>
    </ControlTemplate></Setter.Value></Setter>
    <Setter Property="ContentTemplate"><Setter.Value><DataTemplate><TextBlock Text="{Binding}" TextWrapping="Wrap" MaxWidth="395" LineHeight="18" Foreground="{DynamicResource DomeniaBootText}"/></DataTemplate></Setter.Value></Setter>
  </Style>
  <Style x:Key="FocusRing" TargetType="Control"><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Control"><Border BorderBrush="{DynamicResource DomeniaBootAccentText}" BorderThickness="2" CornerRadius="10" Margin="-3"/></ControlTemplate></Setter.Value></Setter></Style>
  <Style TargetType="TextBlock"><Setter Property="Foreground" Value="{DynamicResource DomeniaBootText}"/><Setter Property="TextWrapping" Value="Wrap"/></Style>
  <Style TargetType="Label"><Setter Property="Foreground" Value="{DynamicResource DomeniaBootText}"/></Style>
  <Style x:Key="Muted" TargetType="TextBlock" BasedOn="{StaticResource {x:Type TextBlock}}"><Setter Property="Foreground" Value="{DynamicResource DomeniaBootMuted}"/><Setter Property="FontSize" Value="12"/><Setter Property="LineHeight" Value="19"/></Style>
  <Style x:Key="Card" TargetType="Border"><Setter Property="CornerRadius" Value="16"/><Setter Property="Background" Value="{DynamicResource DomeniaBootSurface}"/><Setter Property="BorderBrush" Value="{DynamicResource DomeniaBootBorder}"/><Setter Property="BorderThickness" Value="1"/><Setter Property="Padding" Value="22"/><Setter Property="Margin" Value="0,0,0,16"/></Style>
  <Style TargetType="Button">
    <Setter Property="Foreground" Value="{DynamicResource DomeniaBootButtonText}"/><Setter Property="Background" Value="{DynamicResource DomeniaBootButton}"/><Setter Property="BorderBrush" Value="{DynamicResource DomeniaBootBorder}"/><Setter Property="BorderThickness" Value="1"/>
    <Setter Property="Padding" Value="14,9"/><Setter Property="Margin" Value="0,0,8,6"/><Setter Property="FontSize" Value="13"/><Setter Property="FontWeight" Value="Medium"/><Setter Property="MinHeight" Value="38"/>
    <Setter Property="Cursor" Value="Hand"/><Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
    <Setter Property="ToolTipService.ShowOnDisabled" Value="True"/><Setter Property="ToolTipService.InitialShowDelay" Value="400"/><Setter Property="ToolTipService.ShowDuration" Value="30000"/>
    <Setter Property="HorizontalContentAlignment" Value="Center"/>
    <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button">
      <Border x:Name="Chrome" CornerRadius="10" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" Padding="{TemplateBinding Padding}">
        <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" VerticalAlignment="Center" RecognizesAccessKey="True" TextElement.Foreground="{TemplateBinding Foreground}"/>
      </Border>
      <!-- DS-11: hover and press take the colour of the border (a darker tint for the main action), the disabled state
           stays readable (secondary text on the input surface) and the focus keeps one ring (FocusRing). -->
      <ControlTemplate.Triggers>
        <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Chrome" Property="Background" Value="{Binding BorderBrush, RelativeSource={RelativeSource TemplatedParent}}"/></Trigger>
        <Trigger Property="IsPressed" Value="True"><Setter TargetName="Chrome" Property="Background" Value="{Binding BorderBrush, RelativeSource={RelativeSource TemplatedParent}}"/><Setter TargetName="Chrome" Property="BorderBrush" Value="{DynamicResource DomeniaBootAccentText}"/></Trigger>
        <Trigger Property="IsEnabled" Value="False"><Setter TargetName="Chrome" Property="Background" Value="{DynamicResource DomeniaBootInput}"/><Setter TargetName="Chrome" Property="BorderBrush" Value="{DynamicResource DomeniaBootBorder}"/><Setter Property="Foreground" Value="{DynamicResource DomeniaBootMuted}"/><Setter Property="Cursor" Value="Arrow"/></Trigger>
      </ControlTemplate.Triggers>
    </ControlTemplate></Setter.Value></Setter>
  </Style>
  <Style x:Key="Run" TargetType="Button" BasedOn="{StaticResource {x:Type Button}}"><Setter Property="Background" Value="{DynamicResource DomeniaBootAccent}"/><Setter Property="Foreground" Value="{DynamicResource DomeniaBootOnAccent}"/><Setter Property="FontWeight" Value="SemiBold"/><Setter Property="BorderBrush" Value="{DynamicResource DomeniaBootAccentHover}"/></Style>
  <Style TargetType="TextBox">
    <Setter Property="Background" Value="{DynamicResource DomeniaBootInput}"/><Setter Property="Foreground" Value="{DynamicResource DomeniaBootText}"/><Setter Property="CaretBrush" Value="{DynamicResource DomeniaBootText}"/><Setter Property="SelectionBrush" Value="{DynamicResource DomeniaBootAccent}"/>
    <Setter Property="BorderBrush" Value="{DynamicResource DomeniaBootBorder}"/><Setter Property="BorderThickness" Value="1"/><Setter Property="Padding" Value="11,8"/><Setter Property="MinHeight" Value="36"/>
    <Setter Property="VerticalContentAlignment" Value="Center"/><Setter Property="ToolTipService.ShowOnDisabled" Value="True"/>
    <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="TextBox"><Border x:Name="InputBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="9"><ScrollViewer x:Name="PART_ContentHost"/></Border><ControlTemplate.Triggers><Trigger Property="IsKeyboardFocusWithin" Value="True"><Setter TargetName="InputBorder" Property="BorderBrush" Value="{DynamicResource DomeniaBootAccentText}"/></Trigger><Trigger Property="IsEnabled" Value="False"><Setter TargetName="InputBorder" Property="Opacity" Value="0.55"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter>
  </Style>
  <Style TargetType="PasswordBox"><Setter Property="Background" Value="{DynamicResource DomeniaBootInput}"/><Setter Property="Foreground" Value="{DynamicResource DomeniaBootText}"/><Setter Property="CaretBrush" Value="{DynamicResource DomeniaBootText}"/><Setter Property="BorderBrush" Value="{DynamicResource DomeniaBootBorder}"/><Setter Property="Padding" Value="11,9"/><Setter Property="MinHeight" Value="40"/>
    <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="PasswordBox"><Border x:Name="PasswordBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="9"><ScrollViewer x:Name="PART_ContentHost"/></Border><ControlTemplate.Triggers><Trigger Property="IsKeyboardFocusWithin" Value="True"><Setter TargetName="PasswordBorder" Property="BorderBrush" Value="{DynamicResource DomeniaBootAccentText}"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter>
  </Style>
  <Style TargetType="CheckBox"><Setter Property="Foreground" Value="{DynamicResource DomeniaBootText}"/><Setter Property="VerticalContentAlignment" Value="Center"/><Setter Property="HorizontalContentAlignment" Value="Stretch"/><Setter Property="Padding" Value="0"/><Setter Property="Margin" Value="0,3"/><Setter Property="MinHeight" Value="32"/><Setter Property="Cursor" Value="Hand"/><Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/><Setter Property="ToolTipService.ShowOnDisabled" Value="True"/>
    <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="CheckBox"><Grid Background="Transparent"><Grid.ColumnDefinitions><ColumnDefinition Width="20"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Border x:Name="CheckBorder" Width="18" Height="18" CornerRadius="5" Background="{DynamicResource DomeniaBootInput}" BorderBrush="{DynamicResource DomeniaBootBorder}" BorderThickness="1" VerticalAlignment="Center"><Path x:Name="Tick" Data="M 3,8 L 6,11 L 12,4" Stroke="{DynamicResource DomeniaBootOnAccent}" StrokeThickness="1.7" StrokeStartLineCap="Round" StrokeEndLineCap="Round" Visibility="Collapsed"/></Border><ContentPresenter Grid.Column="1" Margin="9,0,0,0" VerticalAlignment="Center" HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" RecognizesAccessKey="True" TextElement.Foreground="{TemplateBinding Foreground}"/></Grid><ControlTemplate.Triggers><Trigger Property="IsChecked" Value="True"><Setter TargetName="CheckBorder" Property="Background" Value="{DynamicResource DomeniaBootAccent}"/><Setter TargetName="CheckBorder" Property="BorderBrush" Value="{DynamicResource DomeniaBootAccent}"/><Setter TargetName="Tick" Property="Visibility" Value="Visible"/></Trigger><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="CheckBorder" Property="BorderBrush" Value="{DynamicResource DomeniaBootAccentText}"/></Trigger><Trigger Property="IsEnabled" Value="False"><Setter Property="Opacity" Value="0.55"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter>
  </Style>
  <Style TargetType="ProgressBar"><Setter Property="Foreground" Value="{DynamicResource DomeniaBootAccentText}"/><Setter Property="Background" Value="{DynamicResource DomeniaBootBorder}"/><Setter Property="BorderThickness" Value="0"/></Style>
  </Grid.Resources><!-- Only the input area can scroll on a very small desktop. Actions remain outside it. -->
    <Border x:Name="PanelLogin" Grid.Row="0" Margin="16" Padding="20">
      <Border.Style><Style TargetType="Border" BasedOn="{StaticResource Card}"><Style.Triggers><DataTrigger Binding="{Binding Visibility, ElementName=PbLogin}" Value="Visible"><Setter Property="Visibility" Value="Hidden"/></DataTrigger></Style.Triggers></Style></Border.Style><Grid>
        <Grid.RowDefinitions>
          <RowDefinition Height="Auto"/>
          <RowDefinition Height="*"/>
          <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <Grid x:Name="LoginHeader" Grid.Row="0" Margin="0,0,0,18">
          <Grid.ColumnDefinitions>
            <ColumnDefinition Width="Auto"/>
            <ColumnDefinition Width="*"/>
            <ColumnDefinition Width="Auto"/>
          </Grid.ColumnDefinitions>
          <Border Width="42" Height="42" CornerRadius="12" Background="{DynamicResource DomeniaBootAccent}" VerticalAlignment="Center" Margin="0,0,13,0">
            <TextBlock Text="D" FontSize="27" FontWeight="SemiBold" Foreground="{DynamicResource DomeniaBootOnAccent}" HorizontalAlignment="Center" VerticalAlignment="Center" ToolTip="{Binding Text, RelativeSource={RelativeSource Self}}" ToolTipService.ShowOnDisabled="True"/>
          </Border>
          <StackPanel Grid.Column="1" VerticalAlignment="Center">
            <TextBlock Text="Connexion à Domenia" FontSize="22" FontWeight="SemiBold" ToolTip="{Binding Text, RelativeSource={RelativeSource Self}}" ToolTipService.ShowOnDisabled="True"/>
            <TextBlock Text="Votre compte Active Directory" Style="{StaticResource Muted}" LineHeight="16" Margin="0,3,0,0" ToolTip="{Binding Text, RelativeSource={RelativeSource Self}}" ToolTipService.ShowOnDisabled="True"/>
          </StackPanel>
          <Button x:Name="BtnSuiteLoginTheme" Grid.Column="2" Width="36" Height="36" MinHeight="36" Padding="7" Margin="8,0,0,0" VerticalAlignment="Center" KeyboardNavigation.TabIndex="6" ToolTip="Bascule entre clair et sombre et mémorise le choix pour Domenia. Ne lance pas la connexion et ne lit pas le mot de passe." ToolTipService.ShowOnDisabled="True" ToolTipService.InitialShowDelay="400" ToolTipService.ShowDuration="30000" AutomationProperties.Name="Thème de la connexion" AutomationProperties.HelpText="Bascule entre clair et sombre et mémorise le choix pour Domenia. Ne lance pas la connexion et ne lit pas le mot de passe.">
            <!-- DS-10 (L08): same Path icons and convention as the main window, the theme the button switches to. -->
            <Grid Width="18" Height="18" IsHitTestVisible="False">
              <Path x:Name="LoginThemeSun" Data="M16,12 A4,4 0 1 1 8,12 A4,4 0 1 1 16,12 M12,2 L12,4 M12,20 L12,22 M2,12 L4,12 M20,12 L22,12 M4.9,4.9 L6.3,6.3 M17.7,17.7 L19.1,19.1 M4.9,19.1 L6.3,17.7 M17.7,6.3 L19.1,4.9" Stretch="Uniform" Stroke="{DynamicResource DomeniaBootAccentText}" StrokeThickness="1.7" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" Visibility="Collapsed"/>
              <Path x:Name="LoginThemeMoon" Data="M20,14.5 A8,8 0 1 1 9.5,4 A6.5,6.5 0 0 0 20,14.5 Z" Stretch="Uniform" Stroke="{DynamicResource DomeniaBootAccentText}" StrokeThickness="1.7" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round"/>
            </Grid>
          </Button>
        </Grid>

        <ScrollViewer x:Name="LoginFormScroll" Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" CanContentScroll="False" Focusable="False" Padding="0">
          <StackPanel x:Name="LoginFields">
            <TextBlock Text="" TextWrapping="Wrap" FontSize="11" Foreground="{DynamicResource DomeniaBootWarning}" Margin="0,0,0,8" Visibility="Collapsed" x:Name="LblSuiteThemeSave"/><Label Content="Compte Windows" Target="{Binding ElementName=TxtLogin}" Padding="0" Margin="0,0,0,5" ToolTip="{Binding Content, RelativeSource={RelativeSource Self}}" ToolTipService.ShowOnDisabled="True"/>
            <TextBox x:Name="TxtLogin" MaxLength="256" MinHeight="40" Padding="11,7" VerticalContentAlignment="Center" Margin="0,0,0,14" KeyboardNavigation.TabIndex="0" ToolTip="Saisissez votre compte AD habituel : DOMAINE\identifiant, identifiant@domaine ou le format déjà utilisé. Le coffre Windows est facultatif et doit être choisi explicitement." ToolTipService.ShowOnDisabled="True" ToolTipService.InitialShowDelay="400" ToolTipService.ShowDuration="30000" AutomationProperties.HelpText="Saisissez votre compte AD habituel : DOMAINE\identifiant, identifiant@domaine ou le format déjà utilisé. Le coffre Windows est facultatif et doit être choisi explicitement." AutomationProperties.Name="Compte Windows"/>
            <Label Content="Mot de passe" Target="{Binding ElementName=PwdLogin}" Padding="0" Margin="0,0,0,5" ToolTip="{Binding Content, RelativeSource={RelativeSource Self}}" ToolTipService.ShowOnDisabled="True"/>
            <Grid x:Name="LoginPasswordRow" Margin="0,0,0,8">
              <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
              <PasswordBox x:Name="PwdLogin" Grid.Column="0" MinHeight="40" Padding="11,7" VerticalContentAlignment="Center" Margin="0" KeyboardNavigation.TabIndex="1" ToolTip="Mot de passe du compte saisi. Seule l’option explicite de coffre Windows permet sa conservation." ToolTipService.ShowOnDisabled="True" ToolTipService.InitialShowDelay="400" ToolTipService.ShowDuration="30000" AutomationProperties.HelpText="Mot de passe du compte saisi. Seule l’option explicite de coffre Windows permet sa conservation." AutomationProperties.Name="Mot de passe"/>
              <!-- SE-16: read-only overlay shown 5 s on request; the PasswordBox stays the only source of the secret. -->
              <Border x:Name="LoginPasswordPeek" Grid.Column="0" Margin="1" CornerRadius="8" Background="{DynamicResource DomeniaBootInput}" Visibility="Collapsed" IsHitTestVisible="False" Focusable="False">
                <TextBlock x:Name="LblLoginPasswordPeek" Text="" Margin="11,0" VerticalAlignment="Center" TextWrapping="NoWrap" TextTrimming="CharacterEllipsis" FontFamily="Consolas" FontSize="14" Focusable="False" ToolTip="Mot de passe affiché pendant 5 secondes, en lecture seule, sans copie possible." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Mot de passe affiché" AutomationProperties.HelpText="Mot de passe affiché pendant 5 secondes, en lecture seule, sans copie possible."/>
              </Border>
              <Button x:Name="BtnRevealLogin" Grid.Column="1" Content="Afficher" MinWidth="88" MinHeight="40" Padding="10,7" Margin="8,0,0,0" ToolTip="Affiche le mot de passe saisi pendant 5 secondes, en lecture seule. Rien nʼest copié ni enregistré." ToolTipService.ShowOnDisabled="True" ToolTipService.InitialShowDelay="400" ToolTipService.ShowDuration="30000" AutomationProperties.Name="Afficher le mot de passe pendant 5 secondes" AutomationProperties.HelpText="Affiche le mot de passe saisi pendant 5 secondes, en lecture seule. Rien nʼest copié ni enregistré."/>
            </Grid>
            <TextBlock x:Name="LblSuiteCapsLock" Text="Verr. Maj activé : le mot de passe distingue les majuscules." Visibility="Collapsed" Foreground="{DynamicResource DomeniaBootWarning}" FontSize="12" Margin="0,0,0,8" ToolTip="Désactivez Verr. Maj si les majuscules ne sont pas souhaitées." ToolTipService.ShowOnDisabled="True" AutomationProperties.LiveSetting="Polite"/>
            <CheckBox x:Name="ChkRemember" FontSize="12" MinHeight="28" Margin="0" KeyboardNavigation.TabIndex="2" ToolTip="Après une connexion réussie, propose cet identifiant à la prochaine connexion. Le mot de passe nʼest jamais mémorisé par cette case." ToolTipService.ShowOnDisabled="True" ToolTipService.InitialShowDelay="400" ToolTipService.ShowDuration="30000" AutomationProperties.HelpText="Après une connexion réussie, propose cet identifiant à la prochaine connexion. Le mot de passe nʼest jamais mémorisé par cette case." AutomationProperties.Name="Se souvenir de mon identifiant">
              <TextBlock Text="Se souvenir de mon identifiant" TextWrapping="Wrap" ToolTip="{Binding Text, RelativeSource={RelativeSource Self}}" ToolTipService.ShowOnDisabled="True"/>
            </CheckBox>
            <CheckBox x:Name="ChkLoginVaultRemember" Content="Mémoriser sur ce PC" IsChecked="False" FontSize="12" ToolTip="Après une connexion réussie, conserve ce compte dans le Gestionnaire d’identifiants Windows de cet utilisateur. Facultatif."/>
            <WrapPanel Margin="0,5,0,0"><Button x:Name="BtnLoginVaultUse" Content="Utiliser le coffre" MinHeight="32" FontSize="12" ToolTip="Lit et valide une fois le compte exact affiché. Aucun usage automatique."/><Button x:Name="BtnLoginVaultForget" Content="Oublier" MinHeight="32" FontSize="12" ToolTip="Supprime du coffre uniquement cet identifiant pour ce domaine et la connexion Domenia."/></WrapPanel>
      </StackPanel>
        </ScrollViewer>

        <StackPanel x:Name="LoginActions" Grid.Row="2" Margin="0,16,0,0">
          <!-- A long Windows error never pushes the buttons out of the window. -->
          <StackPanel x:Name="UxLoginFeedback" Margin="0,0,0,10"><StackPanel.Style><Style TargetType="StackPanel"><Style.Triggers><DataTrigger Binding="{Binding Text, ElementName=LblLoginError}" Value=""><Setter Property="Visibility" Value="Collapsed"/></DataTrigger><DataTrigger Binding="{Binding Visibility, ElementName=PbLogin}" Value="Visible"><Setter Property="Visibility" Value="Collapsed"/></DataTrigger></Style.Triggers></Style></StackPanel.Style><Border Background="{DynamicResource DomeniaBootSurface}" BorderBrush="{DynamicResource DomeniaBootError}" BorderThickness="1" CornerRadius="9" Padding="10,8"><ScrollViewer MaxHeight="60" Focusable="False" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled"><TextBlock x:Name="LblLoginError" Text="" Foreground="{DynamicResource DomeniaBootError}" FontSize="12" TextWrapping="Wrap" Margin="0" LineHeight="17"/>
              </ScrollViewer></Border><Grid x:Name="UxLoginDiagnostics" Margin="0,8,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="8"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Button x:Name="BtnLoginLog" Content="Ouvrir le journal" MinHeight="32" FontSize="11.5" ToolTip="Ouvre le journal technique de connexion pour comprendre une erreur. Aucun nouvel essai d’authentification n’est lancé." AutomationProperties.Name="Journal de connexion" AutomationProperties.HelpText="Ouvre le journal technique de connexion pour comprendre une erreur. Aucun nouvel essai d’authentification n’est lancé." ToolTipService.ShowOnDisabled="True" Margin="0"/>
            <Button x:Name="BtnCopyLoginDiag" Grid.Column="2" Content="Copier le diagnostic" MinHeight="32" FontSize="11.5" ToolTip="Copie les informations de diagnostic de connexion. Relisez-les avant de les transmettre hors de votre organisation." AutomationProperties.Name="Copier le diagnostic" AutomationProperties.HelpText="Copie les informations de diagnostic de connexion. Relisez-les avant de les transmettre hors de votre organisation." ToolTipService.ShowOnDisabled="True" Margin="0"/>
          </Grid></StackPanel><Grid x:Name="LoginActionButtons">
            <!-- UX-28: in a domain session BtnWindowsLogin moves to row 0 as the main action and the form folds under
                 BtnLoginOtherAccount (Set-DomeniaLoginWindowsFirst); otherwise it stays in row 2 under Se connecter. -->
            <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
            <Grid Grid.Row="1">
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="*"/>
              </Grid.ColumnDefinitions>
              <Button x:Name="BtnCancel" Grid.Column="0" Content="Annuler" IsCancel="True" MinWidth="96" MinHeight="40" Padding="14,8" Margin="0,0,8,0" KeyboardNavigation.TabIndex="5" ToolTip="Ferme la connexion, ou demande l’arrêt de la validation en cours." ToolTipService.ShowOnDisabled="True" ToolTipService.InitialShowDelay="400" ToolTipService.ShowDuration="30000" AutomationProperties.HelpText="Ferme la connexion, ou demande l’arrêt de la validation en cours." AutomationProperties.Name="Annuler"/>
              <Button x:Name="BtnLogin" Grid.Column="1" Content="Se connecter" Style="{StaticResource Run}" MinHeight="40" Padding="14,8" Margin="0" KeyboardNavigation.TabIndex="3" ToolTip="Valide une fois le compte et le mot de passe saisis avec le moteur de connexion Domenia." ToolTipService.ShowOnDisabled="True" ToolTipService.InitialShowDelay="400" ToolTipService.ShowDuration="30000" AutomationProperties.HelpText="Valide une fois le compte et le mot de passe saisis avec le moteur de connexion Domenia." AutomationProperties.Name="Se connecter" IsDefault="True"/>
              <Button x:Name="BtnLoginOtherAccount" Grid.Column="1" Content="Utiliser un autre compte" Visibility="Collapsed" MinHeight="40" Padding="14,8" Margin="0" KeyboardNavigation.TabIndex="3" ToolTip="Affiche le formulaire pour se connecter avec un autre compte et son mot de passe. Rien nʼest validé avant « Se connecter »." ToolTipService.ShowOnDisabled="True" ToolTipService.InitialShowDelay="400" ToolTipService.ShowDuration="30000" AutomationProperties.HelpText="Affiche le formulaire pour se connecter avec un autre compte et son mot de passe. Rien nʼest validé avant « Se connecter »." AutomationProperties.Name="Utiliser un autre compte"/>
            </Grid>
            <Button x:Name="BtnWindowsLogin" Grid.Row="2" Content="Utiliser mon compte Windows" MinHeight="36" Padding="10,7" Margin="0,8,0,0" KeyboardNavigation.TabIndex="4" ToolTip="Utilise la session Windows courante si cette option est autorisée. Cela ne demande pas le mot de passe du champ et n’ajoute aucun droit." ToolTipService.ShowOnDisabled="True" ToolTipService.InitialShowDelay="400" ToolTipService.ShowDuration="30000" AutomationProperties.HelpText="Utilise la session Windows courante si cette option est autorisée. Cela ne demande pas le mot de passe du champ et n’ajoute aucun droit." AutomationProperties.Name="Utiliser mon compte Windows"/>
          </Grid>
          <TextBlock x:Name="LoginPrivacy" Text="Coffre Windows facultatif, lecture uniquement sur votre demande." Style="{StaticResource Muted}" FontSize="12" LineHeight="16" HorizontalAlignment="Center" TextAlignment="Center" Margin="0,10,0,0" ToolTip="Le coffre Windows est facultatif et doit être choisi explicitement. Aucun mot de passe dans les préférences ou la base de Domenia." ToolTipService.ShowOnDisabled="True"/>
        </StackPanel>
      </Grid>
    </Border>

    <!-- CD-10: one sign-in template. The Debug mode only shows this live diagnostic panel (Show-DomeniaLoginDiagnosticPanel);
         in the standard mode it stays collapsed and only feeds Copier le diagnostic. -->
    <Border x:Name="LoginDiagnosticBuffer" Grid.Row="1" Visibility="Collapsed" IsHitTestVisible="False" Focusable="False" Margin="16,0,16,16" Padding="14" CornerRadius="12" Background="{DynamicResource DomeniaBootSurface}" BorderBrush="{DynamicResource DomeniaBootBorder}" BorderThickness="1">
      <StackPanel>
        <TextBlock Text="Diagnostic de connexion" FontWeight="SemiBold" Margin="0,0,0,6"/>
        <TextBlock x:Name="LblLoginStage" Text="" Foreground="{DynamicResource DomeniaBootAccentText}" FontSize="11.5" TextWrapping="Wrap" Focusable="False"/>
        <TextBox x:Name="TxtLoginTechnical" IsReadOnly="True" AcceptsReturn="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" MaxHeight="128" MinHeight="60" Margin="0,8,0,0" FontFamily="Consolas" FontSize="10.5" Padding="8" ToolTip="Détails techniques de la connexion. Aucun contenu de mot de passe n’est ajouté par cette interface. Relisez les noms et chemins internes avant partage." AutomationProperties.Name="Diagnostic de connexion" AutomationProperties.HelpText="Détails techniques de la connexion. Aucun contenu de mot de passe n’est ajouté par cette interface. Relisez les noms et chemins internes avant partage." ToolTipService.ShowOnDisabled="True" Focusable="False"/>
      </StackPanel>
    </Border>
    <Border x:Name="PanelSplash" Grid.Row="0" Margin="16" Padding="24" VerticalAlignment="Center"><Border.Style><Style TargetType="Border" BasedOn="{StaticResource Card}"><Setter Property="Visibility" Value="Collapsed"/><Style.Triggers><DataTrigger Binding="{Binding Visibility, ElementName=PbLogin}" Value="Visible"><Setter Property="Visibility" Value="Visible"/></DataTrigger></Style.Triggers></Style></Border.Style><StackPanel><TextBlock Text="Connexion à Domenia" FontSize="22" FontWeight="SemiBold"/><TextBlock x:Name="LblLoginWait" Text="Vérification du compte…" Style="{StaticResource Muted}" Margin="0,10,0,18" TextWrapping="Wrap" AutomationProperties.LiveSetting="Polite"/><ProgressBar x:Name="PbLogin" IsIndeterminate="True" Height="6" Visibility="Collapsed" Margin="0" ToolTip="Connexion en cours. Cette animation ne représente pas un pourcentage ni un délai garanti." AutomationProperties.Name="Vérification du compte" AutomationProperties.HelpText="Connexion en cours. Cette animation ne représente pas un pourcentage ni un délai garanti." ToolTipService.ShowOnDisabled="True" Background="{DynamicResource DomeniaBootBorder}" Foreground="{DynamicResource DomeniaBootAccentText}"/>
        <Button x:Name="BtnLoginWaitCancel" Content="Annuler la connexion" Margin="0,16,0,0" MinHeight="36" Padding="14,8" KeyboardNavigation.TabIndex="0" ToolTip="Demande l’arrêt de la validation et revient au formulaire. Aucun appel Windows n’est arrêté de force." ToolTipService.ShowOnDisabled="True" AutomationProperties.Name="Annuler la connexion" AutomationProperties.HelpText="Demande l’arrêt de la validation et revient au formulaire. Aucun appel Windows n’est arrêté de force."/></StackPanel></Border></Grid>
</Window>
"@)
}

function Show-LoginWindow {
    # -PreferForm: change of account asked by the operator; the form opens first, the Windows session stays below it.
    # -PrefillLogin: the account of the session being changed (CO-31), proposed instead of the remembered identifier.
    param([switch]$PreferForm,[string]$PrefillLogin='')
    $mode = Get-DomeniaLoginWindowMode
    $script:FastLoginMode = $mode
    # CD-10: one sign-in template for both modes; the Debug mode only adds the live diagnostic panel below.
    $loginXaml = Get-DomeniaStandardLoginXaml
    Write-DomeniaFastLoginLog -Stage "WINDOW_CREATE" -Detail "Construction du login $($script:DomeniaBuild) Mode=$mode Source=$($script:LoginWindowModeSource)"
    $window = ConvertFrom-DomeniaXaml -XamlText $loginXaml -Context "Fenetre de connexion ($mode)"
    # Keep the standalone credential prompt visible for its entire lifetime. An embedded relogin
    # must never change the main window's z-order. The flag is released when the prompt exits.
    if (-not (Test-DomeniaMainHostAvailable)) {
        $window.Topmost = $true
        $window.ShowActivated = $true
    }
    Set-AppWindowIcon $window
    if ($null -ne (Get-Command Initialize-DomeniaUxLoginPresentation -ErrorAction SilentlyContinue)) {
        Initialize-DomeniaUxLoginPresentation -Window $window
    }
    if ($mode -eq "Debug") { [void](Show-DomeniaLoginDiagnosticPanel -Window $window) }

    $ui = @{
        Window = $window
        Login = $window.FindName("TxtLogin")
        Password = $window.FindName("PwdLogin")
        PasswordPeek = $window.FindName("LoginPasswordPeek")
        PasswordPeekText = $window.FindName("LblLoginPasswordPeek")
        Reveal = $window.FindName("BtnRevealLogin")
        Remember = $window.FindName("ChkRemember")
        VaultRemember = $window.FindName("ChkLoginVaultRemember")
        VaultUse = $window.FindName("BtnLoginVaultUse")
        VaultForget = $window.FindName("BtnLoginVaultForget")
        Error = $window.FindName("LblLoginError")
        Stage = $window.FindName("LblLoginStage")
        Progress = $window.FindName("PbLogin")
        Technical = $window.FindName("TxtLoginTechnical")
        Connect = $window.FindName("BtnLogin")
        Windows = $window.FindName("BtnWindowsLogin")
        OtherAccount = $window.FindName("BtnLoginOtherAccount")
        Cancel = $window.FindName("BtnCancel")
        OpenLog = $window.FindName("BtnLoginLog")
        CopyDiag = $window.FindName("BtnCopyLoginDiag")
    }
    foreach ($name in $ui.Keys) {
        if ($null -eq $ui[$name]) { throw "Controle login introuvable : $name" }
    }

    # La meme table GuiElementPolicy placee au debut du script peut aussi
    # griser ou masquer les elements du login.
    Apply-DomeniaGuiElementPolicy -Window $window -ControlMap $ui

    $script:FastLoginUi = $ui
    $script:FastLoginState = [pscustomobject]@{
        VaultRemember = $false
        VaultUsed = $false
        LoginOk = $false
        Session = $null
        Login = ""
        Mode = $mode
        UseCurrentCredentials = $false
    }

    if ([bool]$script:DemoMode) {
        # D002/C2: demonstration identity, no password, no Windows session, nothing read from HKCU LastLogin.
        Initialize-DomeniaDemoLoginPresentation -Ui $ui
        Write-DomeniaFastLoginLog -Stage "DEMO_MODE" -Status "WARN" -Detail "Fournisseur de demonstration : aucune connexion AD, ecritures desactivees."
    }
    else {
    $lastLogin = [string]$PrefillLogin
    if ([string]::IsNullOrWhiteSpace($lastLogin)) { $lastLogin = [string](Get-CfgValue "Auth" "LastLogin" "") }
    if ([string]::IsNullOrWhiteSpace($lastLogin)) { $lastLogin = [string](Get-CfgValue "Auth" "VaultUserName" "") }
    if ([string]::IsNullOrWhiteSpace($lastLogin)) { $lastLogin = [string](Get-CfgValue "Conf" "ADM" "") }
    $lastLogin = $lastLogin.Trim()
    if (Test-DomeniaComputerAccountIdentity -Identity $lastLogin) {
        Write-DomeniaFastLoginLog -Stage "PREFILL_REJECTED" -Status "WARN" -Detail "Le login memorise correspondait a un compte ordinateur ; champ vide."
        $lastLogin = ""
    }

    $ui.Login.Text = $lastLogin
    $ui.Remember.IsChecked = [bool](Get-CfgValue "Auth" "RememberLogin" $false)

    # UX-28: in a domain session the main action is « Continuer en tant que DOMAINE\nom »; the form comes second.
    $choice = Get-DomeniaLoginChoice -WindowsIdentity (Get-DomeniaProcessWindowsIdentity) -AllowWindowsSession ([bool](Get-CfgValue "Auth" "AllowWindowsSession" $true)) -PreferForm ([bool]$PreferForm)
    Set-DomeniaLoginChoicePresentation -Ui $ui -Choice $choice
    }

    $ui.VaultRemember.IsChecked=$false
    $ui.VaultUse.Add_Click({Start-DomeniaFastLoginAttempt -UseVault})
    $ui.VaultForget.Add_Click({Remove-DomeniaFastLoginVault})
    $ui.Login.Add_TextChanged({Update-DomeniaFastLoginVaultUi -Busy ($null -ne $script:FastLoginState.Session)})
    Update-DomeniaFastLoginVaultUi
    # SE-16: the reveal is a read-only overlay closed after 5 s, on a second click or as soon as the password changes.
    $ui.Reveal.Add_Click({ [void](Show-DomeniaSecretPeek -PasswordBox $script:FastLoginUi.Password -Overlay $script:FastLoginUi.PasswordPeek -Display $script:FastLoginUi.PasswordPeekText -Button $script:FastLoginUi.Reveal -Owner 'Timer:LoginPasswordPeek' -Standalone) })
    $ui.Password.Add_PasswordChanged({ Hide-DomeniaSecretPeek -Owner 'Timer:LoginPasswordPeek' })
    $ui.Connect.Add_Click({ Start-DomeniaFastLoginAttempt })
    $ui.Windows.Add_Click({ Start-DomeniaFastLoginAttempt -UseCurrentCredentials })
    $ui.OtherAccount.Add_Click({
        # UX-28: unfolds the form only; nothing is validated before « Se connecter ».
        Set-DomeniaLoginWindowsFirst -Ui $script:FastLoginUi -WindowsFirst $false
        if ([string]::IsNullOrWhiteSpace([string]$script:FastLoginUi.Login.Text)) { [void]$script:FastLoginUi.Login.Focus() } else { [void]$script:FastLoginUi.Password.Focus() }
    })
    $ui.Cancel.Add_Click({
        if ($null -ne $script:FastLoginState.Session) {
            Add-DomeniaFastLoginDetail "Annulation demandee."
            Write-DomeniaFastLoginLog -Stage "CANCEL" -Status "WARN" -Detail "Annulation de la validation en memoire par l utilisateur"
            Reset-DomeniaFastLoginAttempt -Kill -KeepDiagnostics
            $script:FastLoginUi.Error.Foreground = (Get-DomeniaBootStatusColor -Kind "Warning")
            $script:FastLoginUi.Error.Text = 'Vérification annulée.'
            $script:FastLoginUi.Stage.Text = 'Vous pouvez corriger les informations puis réessayer.'
            return
        }
        $script:FastLoginState.LoginOk = $false
        Set-DomeniaSurfaceResult $script:FastLoginUi.Window $false
    })
    $ui.OpenLog.Add_Click({
        try {
            $path = Get-DomeniaFastLoginLogPath
            if (-not (Test-Path -LiteralPath $path)) { [System.IO.File]::WriteAllText($path,"",(New-Object System.Text.UTF8Encoding($false))) }
            Start-Process notepad.exe -ArgumentList @($path)
        }
        catch { Add-DomeniaFastLoginDetail $_.Exception.Message }
    })
    $ui.CopyDiag.Add_Click({
        try {
            $text = "Domenia $($script:DomeniaBuild)`r`nScript=$($script:LaunchPath)`r`nLog=$(Get-DomeniaFastLoginLogPath)`r`nEtat=$($script:FastLoginUi.Stage.Text)`r`n`r`n$($script:FastLoginUi.Technical.Text)"
            [System.Windows.Clipboard]::SetText($text)
            $script:FastLoginUi.Error.Text = 'Diagnostic copié. Relisez-le avant de le transmettre.'
        }
        catch { $script:FastLoginUi.Error.Text = "Copie impossible : $($_.Exception.Message)" }
    })
    Register-DomeniaSurfaceKeys $window ({
        param($sender,$eventArgs)
        if ($eventArgs.Key -ne "Enter") { return }
        # Entrée runs the main action shown: Se connecter with the form, the Windows session when it comes first.
        $loginUi = $script:FastLoginUi
        if (($loginUi.Connect.Visibility -eq [System.Windows.Visibility]::Visible) -and ([bool]$loginUi.Connect.IsEnabled)) { $eventArgs.Handled=$true; Start-DomeniaFastLoginAttempt }
        elseif (([bool]$loginUi.Windows.IsDefault) -and ($loginUi.Windows.Visibility -eq [System.Windows.Visibility]::Visible) -and ([bool]$loginUi.Windows.IsEnabled)) { $eventArgs.Handled=$true; Start-DomeniaFastLoginAttempt -UseCurrentCredentials }
    })
    Register-DomeniaSurfaceReady $window ({
        Write-DomeniaFastLoginLog -Stage "WINDOW_READY" -Detail "Fenetre affichee. Mode=$($script:FastLoginMode) Source=$($script:LoginWindowModeSource) Script=$($script:LaunchPath)"
        Add-DomeniaFastLoginDetail "Build : $($script:DomeniaBuild)"
        Add-DomeniaFastLoginDetail "Mode : $($script:FastLoginMode) ; source : $($script:LoginWindowModeSource)"
        $displayIdentity = Get-DomeniaProcessWindowsIdentity
        if ([string]::IsNullOrWhiteSpace($displayIdentity)) { $displayIdentity = "indisponible (SYSTEM, compte local ou compte ordinateur)" }
        Add-DomeniaFastLoginDetail "Session Windows : $displayIdentity"
        Add-DomeniaFastLoginDetail "Journal : $(Get-DomeniaFastLoginLogPath)"
        # Request focus once; then preserve the login-only topmost exception even when Windows
        # refuses activation. No repeated focus grabbing, and no promotion of an embedded relogin.
        if (-not (Test-DomeniaMainHostAvailable)) {
            try { [void](Request-DomeniaWindowActivation -Window $script:FastLoginUi.Window -Trigger 'Launch') } catch { Write-DomeniaSwallowed 'Core' 'Show-LoginWindow' $_ }
            $script:FastLoginUi.Window.Topmost = $true
        }
        if ([bool]$script:DemoMode) { $script:FastLoginUi.Connect.Focus() | Out-Null }
        elseif (([bool]$script:FastLoginUi.Windows.IsDefault) -and ([bool]$script:FastLoginUi.Windows.IsEnabled)) { $script:FastLoginUi.Windows.Focus() | Out-Null }
        elseif (-not [string]::IsNullOrWhiteSpace([string]$script:FastLoginUi.Login.Text)) { $script:FastLoginUi.Password.Focus() | Out-Null }
        else { $script:FastLoginUi.Login.Focus() | Out-Null }
    })
    $window.Add_Closing({
        Hide-DomeniaSecretPeek -Owner 'Timer:LoginPasswordPeek'
        if ($null -ne $script:FastLoginState.Session) { Reset-DomeniaFastLoginAttempt -Kill -KeepDiagnostics }
    })
    if (-not (Test-DomeniaMainHostAvailable)) { try { Register-DomeniaUserSwitchWatch -Window $window } catch { Write-DomeniaSwallowed 'Core' 'Show-LoginWindow' $_ } }

    Write-DomeniaFastLoginLog -Stage "WINDOW_SHOW" -Detail "ShowDialog"
    try {
        [void](Invoke-DomeniaHostWindow -Window $window -ManagedCancel -PreserveTheme)
    }
    finally {
        # Success, cancellation and a failed host all release the login-only z-order override.
        $window.Topmost = $false
    }
    $ok = [bool]$script:FastLoginState.LoginOk
    if ($null -ne $script:FastLoginState.Session) { Reset-DomeniaFastLoginAttempt -Kill -KeepDiagnostics }
    $script:LoginOk = $ok
    Write-DomeniaFastLoginLog -Stage "WINDOW_CLOSE" -Detail "LoginOk=$ok"
    return $ok
}

function Invoke-DomeniaSelfTest {
    [CmdletBinding()]
    param()
    $checks = [System.Collections.ArrayList]::new()
    function Add-SelfTestResult {
        param([string]$Name,[bool]$Success,[string]$Detail)
        [void]$checks.Add([pscustomobject]@{ Name=$Name; Success=$Success; Detail=$Detail })
    }

    foreach ($item in @(
        @{ Name='XAML principal'; Factory='Get-MainXaml' },
        @{ Name='Connexion'; Factory='Get-DomeniaStandardLoginXaml' },
        @{ Name='Chargement'; Factory='Get-DomeniaStartupXaml' }
    )) {
        try {
            $factoryName = [string]$item.Factory
            $xaml = & $factoryName
            Assert-DomeniaXamlPreflight -XamlText $xaml -Context ([string]$item.Name)
            $window = ConvertFrom-DomeniaXaml -XamlText $xaml -Context ([string]$item.Name)
            try { $window.Close() } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaSelfTest' $_ }
            Add-SelfTestResult -Name ([string]$item.Name) -Success $true -Detail 'XML et chargement WPF valides.'
        }
        catch { Add-SelfTestResult -Name ([string]$item.Name) -Success $false -Detail $_.Exception.ToString() }
    }

    $requiredFunctions = @(
        'Initialize-AsyncEngine','Get-DomeniaWorkerOperationHashes','Assert-DomeniaWorkerOperationCode','New-DomeniaWorkerRunspace','Start-UiTask','Complete-UiTasks','Invoke-GlobalSearch','Load-TreeChildren',
        'Open-AdObject','Complete-DomeniaComputerUserProbeUi','Save-UserMachineLinks','Show-LoginWindow',
        'Set-DomeniaItemsSource','ConvertTo-DomeniaCanonicalLinks','Complete-DomeniaComputerToolUi',
        'Fail-DomeniaComputerToolUi','Complete-DomeniaWriteTaskUi','Fail-DomeniaWriteTaskUi',
        'Invoke-DomeniaInProcessAuthProbe','Start-DomeniaLoginAuthRunspace','Read-DomeniaAuthRunspaceResult',
        'Update-DomeniaSecretActionUi','Assert-DomeniaReadWriteControlClassification',
        'Set-DomeniaActualCapabilityDenied','Test-DomeniaActualCapabilityDenied','Clear-DomeniaActualCapabilityDenials',
        'Test-DomeniaSensitiveAttributeName','Get-DomeniaAdModuleSources','Assert-DomeniaAdBinarySource',
        'Get-DomeniaRelationDirection','Test-DomeniaSameRelation','Resolve-DomeniaRelationUpsert','Resolve-DomeniaRelationStoragePlacement','Get-DomeniaEvidenceBadge','Step-DomeniaAssociationState','Merge-DomeniaRelationCandidates','Get-DomeniaDetectionScopePlan','Test-DomeniaDetectionWithinPlan','Test-DomeniaProbeAllowed','Test-DomeniaAccountIdentityMatch','New-DomeniaLinkHistoryEntry','Add-DomeniaRelation','Remove-DomeniaRelation','Restore-DomeniaRemovedLink','Complete-DomeniaRelationsComputerProbe','Show-DomeniaRelationDetectionPlan',
        # D011, D015, D017, D018, D020, D089 and the demonstration provider (D002, D003).
        'Test-DomeniaStartupPlan','Test-DomeniaTaskAdmission','Get-DomeniaTaskStateSummary','Get-DomeniaOperationCredentialNeeds',
        'Initialize-DomeniaEngineState','Invoke-DomeniaUiTaskDispatch','Invoke-DomeniaQueuedTaskPromotion','Test-DomeniaBackgroundWorkAllowed',
        'Initialize-DomeniaIdlePolicy','Get-DomeniaDemoDirectoryWorkerCode','New-DomeniaDemoDirectory','ConvertTo-DomeniaDemoWorkerContext',
        'Test-DomeniaDemoProviderEnabled','Request-DomeniaWindowActivation','Get-DomeniaLocalIndexReadWorkerCode','Get-DomeniaParkSharedSyncWorkerCode',
        'Get-DomeniaGlobalSearchPlan','Get-DomeniaContinuationDecision','Get-DomeniaCurrentSelectionIdentity','Initialize-DomeniaSearchUi','Invoke-DomeniaNavStep','Invoke-DomeniaSearchMore','Get-DomeniaOuRestoreDecision',
        'Get-DomeniaErrorDecision','Get-DomeniaCredentialScope','Test-DomeniaCredentialContext','ConvertTo-DomeniaMachineKey','Protect-DomeniaSecretText','Get-DomeniaBitLockerListWorkerCode','Get-DomeniaBitLockerKeyWorkerCode','Request-DomeniaBitLockerKey','Complete-DomeniaBitLockerListUi','Resolve-DomeniaCapabilityRoute','Update-DomeniaTransportPolicyView','Get-DomeniaRetryCredential','Set-DomeniaTargetCredentialContext',
        'Request-DomeniaInlineConfirmation','Complete-DomeniaInlineRequest','Test-DomeniaInlineBlocks',
        'Request-DomeniaLinkPersistence','Queue-DomeniaLinkChanges','Merge-DomeniaLiveLinkMemory','Get-DomeniaObjectCacheKey','Get-DomeniaCacheKey','Invoke-DomeniaObjectChanges',
        'Update-DomeniaAccessButton','Update-DomeniaExperienceActivity','Update-DomeniaSelectionReadUi','Enter-DomeniaSelectionContext','Reset-DomeniaSelectionBoundViews','Complete-DomeniaInventoryUi','Complete-DomeniaSoftwareUi',
        'Get-DomeniaReceiptRequirement','Get-DomeniaReceiptResumeState','New-DomeniaWriteRegistry','Test-DomeniaWriteAdmission','Set-DomeniaWriteOutcome','Start-DomeniaWriteTask','Invoke-ComputerTool','Start-DomeniaRimotteRun','Get-DomeniaRimotteWorkerCode','Initialize-DomeniaGuard',
        'Get-DomeniaWriteRoute','New-DomeniaSelectionWritePlan','Format-DomeniaPlanConfirmation','Test-DomeniaPlanDispatch','New-DomeniaInterventionPlan','Test-DomeniaPlanStillValid',
        'Get-DomeniaWritePostcondition','Get-DomeniaPostconditionRule','Resolve-DomeniaPostcondition',
        'Get-DomeniaRemotePostconditionText',
        'Get-DomeniaAttributeWriteStrategy','Get-DomeniaAtomicStrategy',
        'Get-DomeniaPersistenceState','Get-DomeniaPersistenceLabel',
        'ConvertTo-DomeniaLegacyNumber','ConvertTo-DomeniaLegacyDate','Read-DomeniaLegacySource','Get-DomeniaLegacySnapshot','New-DomeniaLegacyImportPlan','Invoke-DomeniaLegacyImport','Request-DomeniaLegacyImport',
        'Show-DomeniaLegacyImportPlan','Start-DomeniaLegacyImportWork','Complete-DomeniaLegacyImportWork','Fail-DomeniaLegacyImportWork','Get-DomeniaMigrationWorkerCode',
        'ConvertTo-DomeniaCompiledQuery','ConvertTo-DomeniaQueryRecords','Start-DomeniaQueryEvaluation',
        'Invoke-DomeniaOuRefresh','Stop-DomeniaOuRefresh','Get-DomeniaOuObservationFreshness','Format-DomeniaOuFreshnessSummary'
    )
    $missing = @($requiredFunctions | Where-Object { $null -eq (Get-Command -Name $_ -CommandType Function -ErrorAction SilentlyContinue) })
    Add-SelfTestResult -Name 'Fonctions critiques' -Success ($missing.Count -eq 0) -Detail $(if($missing.Count -eq 0){'Toutes presentes.'}else{"Absentes : $($missing -join ', ')"})

    try {
        # D011: the closed loader validated phases and dependencies before the business modules.
        $planValid = ($null -ne $script:DomeniaStartupPlan -and [bool]$script:DomeniaStartupPlan.Valid)
        $engineImported = (@($script:DomeniaRuntimeImports | Where-Object { [string]$_.File -eq 'Domenia-Engine.Model.ps1' -and [bool]$_.Validated }).Count -eq 1)
        Add-SelfTestResult -Name 'Plan de demarrage' -Success ($planValid -and $engineImported) -Detail ("Plan valide={0} ; moteur importe={1} ; ordre={2}." -f $planValid,$engineImported,(@($script:DomeniaStartupPlan.Order) -join ' > '))
    }
    catch { Add-SelfTestResult -Name 'Plan de demarrage' -Success $false -Detail $_.Exception.ToString() }

    try {
        Assert-DomeniaReadWriteControlClassification
        Add-SelfTestResult -Name 'Classification lecture / ecriture' -Success $true -Detail 'LAPS et BitLocker ne sont pas soumis au verrou des ecritures AD.'
    }
    catch { Add-SelfTestResult -Name 'Classification lecture / ecriture' -Success $false -Detail $_.Exception.ToString() }

    try {
        $testDn = 'CN=Domenia-SelfTest,DC=invalid'
        Set-DomeniaActualCapabilityDenied -Dn $testDn -Capability 'Edit' -Reason 'Self-test'
        $denialSet = Test-DomeniaActualCapabilityDenied -Dn $testDn -Capability 'Edit'
        Clear-DomeniaActualCapabilityDenials -Dn $testDn
        $denialCleared = -not (Test-DomeniaActualCapabilityDenied -Dn $testDn -Capability 'Edit')
        Add-SelfTestResult -Name 'Verrou apres refus AD reel' -Success ($denialSet -and $denialCleared) -Detail 'Le refus est cible par objet/capacite et une relecture peut le reinitialiser.'
    }
    catch { Add-SelfTestResult -Name 'Verrou apres refus AD reel' -Success $false -Detail $_.Exception.ToString() }

    try {
        $sensitiveNames = @('unicodePwd','ms-Mcs-AdmPwd','msLAPS-EncryptedPassword','msFVE-RecoveryPassword','supplementalCredentials')
        $filterOk = (@($sensitiveNames | Where-Object { -not (Test-DomeniaSensitiveAttributeName -Name $_) }).Count -eq 0)
        Add-SelfTestResult -Name 'Frontiere des attributs secrets' -Success $filterOk -Detail 'Les attributs LAPS, BitLocker et mots de passe sont exclus des lectures et grilles generiques.'
    }
    catch { Add-SelfTestResult -Name 'Frontiere des attributs secrets' -Success $false -Detail $_.Exception.ToString() }

    try {
        $moduleSources = @(Get-DomeniaAdModuleSources)
        if ($moduleSources.Count -eq 0) { throw 'Ni RSAT systeme ni paire de DLL Active Directory cote a cote ne sont disponibles.' }
        $binarySource = @($moduleSources | Where-Object { [string]$_.Kind -eq 'Binary' } | Select-Object -First 1)
        if ($binarySource.Count -gt 0) { Assert-DomeniaAdBinarySource -Source $binarySource[0] }
        Add-SelfTestResult -Name 'Source du module Active Directory' -Success $true -Detail (($moduleSources | ForEach-Object { "$($_.Kind)=$($_.Path)" }) -join ' | ')
    }
    catch { Add-SelfTestResult -Name 'Source du module Active Directory' -Success $false -Detail $_.Exception.ToString() }

    try {
        Initialize-AsyncEngine
        $engineReady = [bool]$script:AsyncEngineReady
        Add-SelfTestResult -Name 'Moteur worker ferme' -Success $engineReady -Detail $(if($engineReady){('Registre de {0} operations hash-pinnees pret.' -f (Get-DomeniaWorkerOperationHashes).Count)}else{'Moteur absent.'})

        if ($engineReady) {
            $tamperRejected = $false
            try {
                $alteredWorkerCode = [string](Get-DomeniaWorkerEngineSelfTestCode)
                $alteredWorkerCode += [Environment]::NewLine
                $alteredWorkerCode += '# worker-integrity-negative-test'
                [void](Assert-DomeniaWorkerOperationCode -OperationId 'EngineSelfTest' -Code $alteredWorkerCode)
            }
            catch { $tamperRejected = ($_.Exception.Message -like 'Integrite worker refusee*') }
            Add-SelfTestResult -Name 'Refus code worker altere' -Success $tamperRejected -Detail $(if($tamperRejected){'Une variation non enregistree est refusee avant creation du runspace.'}else{'Le controle negatif n a pas ete refuse.'})

            $worker = New-DomeniaWorkerRunspace -OperationId 'EngineSelfTest' -Code (Get-DomeniaWorkerEngineSelfTestCode)
            $workerPs = [System.Management.Automation.PowerShell]::Create()
            try {
                $workerPs.Runspace = $worker.Runspace
                [void]$workerPs.AddCommand([string]$worker.CommandName)
                [void]$workerPs.AddArgument((Get-WorkerContext -OperationId "EngineSelfTest"))
                [void]$workerPs.AddArgument([pscustomobject]@{ Echo='Domenia-self-test' })
                $workerHandle = $workerPs.BeginInvoke()
                if (-not $workerHandle.AsyncWaitHandle.WaitOne(10000)) {
                    try { [void]$workerPs.BeginStop($null,$null) } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaSelfTest' $_ }
                    throw 'Le worker de controle n a pas termine en 10 secondes.'
                }
                $workerRows = @($workerPs.EndInvoke($workerHandle))
                $workerProbe = @($workerRows | Where-Object { $null -ne $_.PSObject.Properties['Echo'] } | Select-Object -First 1)
                if ($workerProbe.Count -eq 0) { throw 'Le worker de controle ne retourne aucun objet exploitable.' }
                $workerOk = ([string]$workerProbe[0].Echo -eq 'Domenia-self-test' -and [string]$workerProbe[0].Apartment -eq 'MTA' -and [int]$workerProbe[0].WorkerThreadId -gt 0)
                Add-SelfTestResult -Name 'Execution worker MTA' -Success $workerOk -Detail "Thread=$($workerProbe[0].WorkerThreadId), appartement=$($workerProbe[0].Apartment), echo=$($workerProbe[0].Echo)."
            }
            finally {
                try { $workerPs.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaSelfTest' $_ }
                try { $worker.Runspace.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaSelfTest' $_ }
            }
        }
    }
    catch {
        Add-SelfTestResult -Name 'Moteur ferme / worker MTA' -Success $false -Detail $_.Exception.ToString()
    }
    finally { try { Dispose-AsyncEngine } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaSelfTest' $_ } }

    $authSelfTestSession = $null
    try {
        $authRequest = [pscustomobject]@{
            SelfTestOnly=$true; Login=""; Credential=$null; PasswordLength=0; UseCurrentCredentials=$true
            Domain="selftest.local"; Netbios="SELFTEST"; ConfiguredBase="DC=selftest,DC=local"; ConfiguredServer=""
            OverallTimeoutSeconds=8; PerServerTimeoutSeconds=2; MaxServers=1
        }
        $authSelfTestSession = Start-DomeniaLoginAuthRunspace -Request $authRequest
        if (-not $authSelfTestSession.AsyncResult.AsyncWaitHandle.WaitOne(10000)) {
            Stop-DomeniaLoginAuthRunspace -Session $authSelfTestSession -Terminate
            throw "Le runspace d authentification interne n a pas termine en 10 secondes."
        }
        $authProbe = Read-DomeniaAuthRunspaceResult -Session $authSelfTestSession
        $authOk = ([bool]$authProbe.Success -and [string]$authProbe.AuthMode -eq "SelfTest" -and [string]$authProbe.Apartment -eq "MTA" -and [int]$authProbe.WorkerThreadId -gt 0)
        Add-SelfTestResult -Name "Authentification interne" -Success $authOk -Detail "Processus=$PID, thread=$($authProbe.WorkerThreadId), appartement=$($authProbe.Apartment), processus enfant=aucun."
    }
    catch { Add-SelfTestResult -Name "Authentification interne" -Success $false -Detail $_.Exception.ToString() }
    finally { if ($null -ne $authSelfTestSession) { Complete-DomeniaLoginAuthRunspaceCleanup -Session $authSelfTestSession } }

    # D002/D003: the demonstration provider is checked whatever Auth.DemoProvider says, with the real consumer gates.
    $demoWorker = $null
    try {
        $demoCode = Get-DomeniaDemoDirectoryWorkerCode
        [void](Assert-DomeniaWorkerOperationCode -OperationId 'DemoDirectory' -Code $demoCode)
        Add-SelfTestResult -Name 'Registre demonstration' -Success $true -Detail 'Corps DemoDirectory conforme a son empreinte.'
        $demoDirectory = New-DomeniaDemoDirectory -LatencyMs 0
        $demoContext = ConvertTo-DomeniaDemoWorkerContext -Context ([pscustomobject]@{BaseDn=[string]$demoDirectory.BaseDn;Domain=[string]$demoDirectory.Domain;Netbios='DEMO';BindUser='DEMO\demo.operateur';PageSize=300}) -RequestedOperationId 'EngineSelfTest'
        $demoWorker = New-DomeniaWorkerRunspace -OperationId 'DemoDirectory' -Code $demoCode
        $demoInvoke = {
            param($Operation,$Request,$Context)
            $demoPs = [System.Management.Automation.PowerShell]::Create()
            try {
                if ($null -ne $demoWorker.PSObject.Properties['Pool'] -and $null -ne $demoWorker.Pool) { $demoPs.RunspacePool = $demoWorker.Pool } else { $demoPs.Runspace = $demoWorker.Runspace }
                [void]$demoPs.AddCommand([string]$demoWorker.CommandName)
                [void]$demoPs.AddArgument($Context)
                [void]$demoPs.AddArgument([pscustomobject]@{Operation=$Operation;Request=$Request;Directory=$demoDirectory})
                $demoHandle = $demoPs.BeginInvoke()
                if (-not $demoHandle.AsyncWaitHandle.WaitOne(10000)) { try { [void]$demoPs.BeginStop($null,$null) } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaSelfTest' $_ }; throw 'Le worker DemoDirectory n a pas termine en 10 secondes.' }
                return @($demoPs.EndInvoke($demoHandle))
            } finally { $demoPs.Dispose() }
        }
        $treeRows = & $demoInvoke 'TreeChildren' ([pscustomobject]@{DN=[string]$demoDirectory.BaseDn}) $demoContext
        $tree = Get-DomeniaEffectiveWorkerResult -Result $treeRows -RequiredProperties @('Rows')
        $treeOk = ($null -ne $tree -and @($tree.Rows | Where-Object { [string]$_.Name -eq 'Siege' -and [string]$_.Kind -eq 'OU' }).Count -eq 1)
        $progress = New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]'
        $stop = New-Object System.Threading.CancellationTokenSource
        $searchRequest = [pscustomobject]@{BaseDn=[string]$demoDirectory.BaseDn;Scope='Subtree';PrefixFilter='(&(|(&(objectCategory=person)(objectClass=user))(objectCategory=computer))(|(name=Jean*)(sAMAccountName=Jean*)))';FastFilter='';ExactFilter='';AnrFilter='';BroadFilter='';Limit=50;Properties=@('name');Progress=$progress;StopToken=$stop.Token;StreamPageSize=25}
        $search = Get-DomeniaEffectiveWorkerResult -Result (& $demoInvoke 'GlobalSearch' $searchRequest $demoContext) -RequiredProperties @('Rows','BaseDn','Scope')
        $events = 0; $demoEvent = $null
        while ($progress.TryDequeue([ref]$demoEvent)) { if (([string]$demoEvent.Kind -eq 'DirectoryRead') -and ($null -ne $demoEvent.Properties) -and ([string]$demoEvent.Source -eq 'Demonstration')) { $events++ } }
        $searchOk = ($null -ne $search -and @($search.Rows).Count -ge 1 -and $events -eq @($search.Rows).Count -and [string]$search.BaseDn -ieq [string]$demoDirectory.BaseDn -and [string]$search.Scope -ceq 'Subtree')
        $jean = @($search.Rows | Where-Object { [string]$_.Name -eq 'Jean Dupont' } | Select-Object -First 1)
        $openOk = $false
        if ($jean.Count -eq 1) {
            $object = Get-DomeniaEffectiveWorkerResult -Result (& $demoInvoke 'OpenAdObject' ([pscustomobject]@{DN=[string]$jean[0].DN;Type='Utilisateur';Properties=@(Get-DomeniaSafeObjectPropertyNames)}) $demoContext) -RequiredProperties @('Properties')
            $state = [pscustomobject]@{Dn=[string]$jean[0].DN;ExpectedGuid=[string]$jean[0].Guid}
            Assert-DomeniaObjectResultIdentity -Result $object -State $state
            $openOk = ([string](Get-DomeniaObjectResultGuid $object) -ieq [string]$jean[0].Guid)
        }
        $unavailable = ''
        try { [void](& $demoInvoke 'ComputerPing' ([pscustomobject]@{Computer='PC-DEMO-01'}) $demoContext) } catch { $unavailable = [string]$_.Exception.Message }
        $unavailableOk = ($unavailable -match 'non disponible en demonstration' -and -not [bool](Get-DomeniaStructuredError $unavailable).CanOfferCredential)
        $refused = $false
        try { [void](& $demoInvoke 'TreeChildren' ([pscustomobject]@{DN=[string]$demoDirectory.BaseDn}) ([pscustomobject]@{OperationId='DemoDirectory';DemoMode=$false;Credential=$null;BindUser='DEMO\demo.operateur'})) } catch { $refused = ([string]$_.Exception.Message -match 'DOMENIA_DEMO_CONTEXT') }
        Add-SelfTestResult -Name 'Annuaire de demonstration MTA' -Success ($treeOk -and $searchOk -and $openOk -and $unavailableOk -and $refused) -Detail ("Arbre={0} ; recherche={1} ({2} evenement(s)) ; fiche={3} ; non disponible={4} ; contexte reel refuse={5}." -f $treeOk,$searchOk,$events,$openOk,$unavailableOk,$refused)
    }
    catch { Add-SelfTestResult -Name 'Annuaire de demonstration MTA' -Success $false -Detail $_.Exception.ToString() }
    finally { if ($null -ne $demoWorker) { try { $demoWorker.Runspace.Dispose() } catch { Write-DomeniaSwallowed 'Core' 'Invoke-DomeniaSelfTest' $_ } } }

    $demoAuthSession = $null
    try {
        $demoAuthRequest = [pscustomobject]@{
            DemoOnly=$true; DemoIdentity='DEMO\demo.operateur'; Login='DEMO\demo.operateur'; Credential=$null; PasswordLength=0; UseCurrentCredentials=$false
            Domain='demo.invalid'; Netbios='DEMO'; ConfiguredBase='DC=demo,DC=invalid'; ConfiguredServer=''
            OverallTimeoutSeconds=8; PerServerTimeoutSeconds=2; MaxServers=1
        }
        $demoAuthSession = Start-DomeniaLoginAuthRunspace -Request $demoAuthRequest
        if (-not $demoAuthSession.AsyncResult.AsyncWaitHandle.WaitOne(10000)) {
            Stop-DomeniaLoginAuthRunspace -Session $demoAuthSession -Terminate
            throw "Le runspace d authentification de demonstration n a pas termine en 10 secondes."
        }
        $demoAuth = Read-DomeniaAuthRunspaceResult -Session $demoAuthSession
        $demoAuthOk = ([bool]$demoAuth.Success -and [string]$demoAuth.AuthMethod -ceq 'Demo.InMemory' -and [string]$demoAuth.BaseDn -eq 'DC=demo,DC=invalid' -and [string]$demoAuth.Apartment -eq 'MTA')
        Add-SelfTestResult -Name 'Authentification demonstration' -Success $demoAuthOk -Detail "Methode=$($demoAuth.AuthMethod), base=$($demoAuth.BaseDn), aucune decouverte de domaine."
    }
    catch { Add-SelfTestResult -Name 'Authentification demonstration' -Success $false -Detail $_.Exception.ToString() }
    finally { if ($null -ne $demoAuthSession) { Complete-DomeniaLoginAuthRunspaceCleanup -Session $demoAuthSession } }

    $failed = @($checks | Where-Object { -not $_.Success })
    return [pscustomobject]@{ Success=($failed.Count -eq 0); Checks=[object[]]$checks.ToArray(); Failed=$failed.Count; Version=$script:Version }
}

function Get-DomeniaFatalMessage {
    # FI-22 / UI-02: before the main window has rendered, the failure is an initialisation failure; once the session
    # was shown it is an unexpected stop, announced with its incident code and the journal paths. A raw .NET or
    # PowerShell message is shown only in Expert, or when no journal could keep it. A message Domenia raised for
    # the operator (-SummaryForOperator: what the administrator fixes) stays visible before display.
    param([bool]$SessionShown,[string]$Summary='',[string]$Code='',[string]$StartupLog='',[string]$LoginLog='',[string]$AppLog='',[bool]$Expert=$false,[bool]$SummaryForOperator=$false)
    $nl = "`r`n"
    $paths = @()
    if ($AppLog) { $paths += ('Journal Domenia :' + $nl + $AppLog) }
    if ($StartupLog) { $paths += ('Journal de démarrage :' + $nl + $StartupLog) }
    if ($LoginLog) { $paths += ('Journal de connexion :' + $nl + $LoginLog) }
    $written = ($paths.Count -gt 0)
    if ($SessionShown) {
        $message = 'Domenia sʼest arrêté de façon inattendue.' + $nl + $nl + 'Code incident : ' + $Code + '.'
        if ($written) { $message += ' Le détail technique est enregistré dans le journal.' }
        if ($Summary -and ($Expert -or (-not $written))) { $message += $nl + $nl + 'Détail technique : ' + $Summary }
    } else {
        $message = 'Domenia nʼa pas pu terminer son initialisation.'
        $showSummary = ($Summary -and ($SummaryForOperator -or $Expert -or (-not $written)))
        if ($showSummary) { $message += $nl + $nl + $Summary }
        $message += $nl + $nl + 'Code incident : ' + $Code + '.'
        if ($written -and (-not $showSummary)) { $message += ' Le détail technique est enregistré dans les journaux ci-dessous.' }
    }
    foreach ($path in $paths) { $message += $nl + $nl + $path }
    if (-not $written) { $message += $nl + $nl + 'Aucun journal nʼa pu être écrit ; conservez ce message.' }
    else { $message += $nl + $nl + 'Consultez les journaux indiqués pour le détail disponible.' }
    return $message
}

function Register-DomeniaSessionShownHook {
    # FI-22: the session counts as shown once the main window has rendered its content. A failure inside ShowDialog
    # before that moment is still reported as an initialisation failure.
    param($Window)
    $script:DomeniaSessionShown = $false
    if ($null -eq $Window) { return }
    $Window.Add_ContentRendered({ $script:DomeniaSessionShown = $true })
}

# Main autoritaire
try {
    # Same validated definition-only entry point as the standalone package check.
    # Dot-sourcing here keeps the functions in this application script scope.
    . (Join-Path $PSScriptRoot 'Domenia-Modules.ps1')
    $script:WorkerCommon += "`r`n"+(Get-DomeniaReceiptsCommon)
    $script:WorkerCommon += "`r`n"+(Get-DomeniaWorkerRulesCommon)
    $script:ReceiptReady=$false;$script:ReceiptPending=0
    Load-AppConfig | Out-Null
    # C2 (D002): demonstration mode fixed once for the whole session, right after the configuration is read.
    [void](Initialize-DomeniaDemoMode)
    Initialize-DomeniaDataStore | Out-Null
    if ($DomeniaSelfTest) {
        $selfTestResult = Invoke-DomeniaSelfTest
        $selfTestJson = $selfTestResult | ConvertTo-Json -Depth 8
        if (-not [string]::IsNullOrWhiteSpace([string]$DomeniaSelfTestResultPath)) {
            $selfTestFullPath = [System.IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables([string]$DomeniaSelfTestResultPath))
            $selfTestParent = Split-Path -Parent $selfTestFullPath
            if (-not [string]::IsNullOrWhiteSpace($selfTestParent) -and -not (Test-Path -LiteralPath $selfTestParent -PathType Container)) {
                [void](New-Item -ItemType Directory -Path $selfTestParent -Force)
            }
            $selfTestTemporary = "$selfTestFullPath.tmp.$PID.$([guid]::NewGuid().ToString('N'))"
            try {
                [System.IO.File]::WriteAllText($selfTestTemporary,$selfTestJson,[System.Text.UTF8Encoding]::new($false))
                Move-Item -LiteralPath $selfTestTemporary -Destination $selfTestFullPath -Force
            }
            finally { Remove-Item -LiteralPath $selfTestTemporary -Force -ErrorAction SilentlyContinue }
        }
        try { [Console]::Out.WriteLine($selfTestJson) } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
        if (-not [bool]$selfTestResult.Success) { throw "Self-test DOMENIA en echec : $($selfTestResult.Failed) controle(s)." }
        return
    }
    $script:StartupCorrelation = [guid]::NewGuid().ToString("N")
    [void](Invoke-DomeniaPreferenceMigration)
    Write-StartupTrace -Stage 'Stockage/Mode' -Detail ($script:StorageLayout.Mode+' ; '+$script:StorageLayout.ModeSource+' ; '+$script:StorageLayout.DataRoot)
    foreach($notice in @($script:StorageLayout.Notices)){Write-StartupTrace -Stage 'Stockage/Mode' -Status 'WARN' -Detail $notice}
    foreach($category in @($script:StorageLayout.Categories)){Write-StartupTrace -Stage 'Stockage/Categorie' -Detail ($category.Category+' ; '+$category.State+' ; '+$category.Path)}
    if($null -ne $script:PreferenceLegacyReads){
        foreach($path in @($script:PreferenceLegacyReads.Keys)){
            if(-not $script:PreferenceLegacyReads[$path]){Write-StartupTrace -Stage 'Preferences/LectureHistorique' -Detail $path;$script:PreferenceLegacyReads[$path]=$true}
        }
    }
    if($script:StoragePreferenceWarning){
        Write-StartupTrace -Stage 'Stockage/Preferences' -Status 'WARN' -Detail $script:StoragePreferenceWarning
        Show-WarningBox -Message $script:StoragePreferenceWarning
    }
    # P-CD-09: what Load-AppConfig could not read is traced, and an unreadable configuration file is shown.
    foreach($issue in @($script:ConfigLoadIssues)){
        if($null -eq $issue){continue}
        Write-StartupTrace -Stage ('Configuration/'+[string]$issue.Source) -Status 'WARN' -Detail ([string]$issue.Text)
        if([bool]$issue.Warning){Show-WarningBox -Message ([string]$issue.Text)}
    }
    Write-StartupTrace -Stage "Application" -Status "START" -Detail "Demarrage Domenia 1.0 (2026.10.16-DOMENIA-1.0-RC1.17.9-D120)"
    # PF-19: duration of the package integrity check made by Domenia-Start.ps1 before the core (absent when launched otherwise).
    $startIntegrity = Get-Variable -Name DomeniaStartIntegrity -ValueOnly -ErrorAction SilentlyContinue
    if ($null -ne $startIntegrity) { Write-StartupTrace -Stage "Integrite du paquet" -Status "OK" -DurationMs ([long]$startIntegrity.DurationMs) -Detail ("{0} fichiers runtime controles (plafond {1}), {2} composants requis." -f $startIntegrity.Files,$startIntegrity.Limit,$startIntegrity.Required) }
    if ([bool]$script:DemoMode) { Write-StartupTrace -Stage "Demonstration" -Status "WARN" -Detail "Demo=True : annuaire fictif en memoire, aucune connexion AD, ecritures desactivees." }
    Write-DomeniaFastLoginLog -Stage "APPLICATION_START" -Detail "PID=$PID Script=$($script:LaunchPath) Root=$($script:RootDir)"

    $preflightWatch = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        $xamlPreflightItems = @(
            [pscustomobject]@{ Context="Interface principale"; Xaml=(Get-MainXaml) },
            [pscustomobject]@{ Context="Connexion"; Xaml=(Get-DomeniaStandardLoginXaml) }
        )
        foreach ($xamlPreflightItem in $xamlPreflightItems) {
            Assert-DomeniaXamlPreflight -XamlText ([string]$xamlPreflightItem.Xaml) -Context ([string]$xamlPreflightItem.Context)
            [void](Test-DomeniaXamlRuntimeCompatibility -XamlText ([string]$xamlPreflightItem.Xaml) -Context ([string]$xamlPreflightItem.Context))
        }
        $preflightWatch.Stop()
        Write-StartupTrace -Stage "Prevalidation interface" -Status "OK" -DurationMs $preflightWatch.ElapsedMilliseconds -Detail "XML, membres XAML et chargement WPF reel valides avant authentification."
    }
    catch {
        $preflightWatch.Stop()
        Write-StartupTrace -Stage "Prevalidation interface" -Status "ERROR" -DurationMs $preflightWatch.ElapsedMilliseconds -Detail $_.Exception.ToString()
        throw
    }

    if (-not $NoAutoConnect) {
        $startupLoginMode = Get-DomeniaLoginWindowMode
        Write-StartupTrace -Stage "Login" -Status "START" -Detail "Ouverture du login V2.3.1 SINGLE FILE ENTERPRISE  mode=$startupLoginMode  source=$($script:LoginWindowModeSource)"
        if (-not (Show-LoginWindow)) {
            Write-StartupTrace -Stage "Login" -Status "CANCEL" -Detail "Connexion annulee"
            return
        }
        Write-StartupTrace -Stage "Login" -Status "OK" -Detail "Compte AD valide : $($script:Conn.BindUser)"
    }

    Write-StartupTrace -Stage "Apres login" -Status "START" -Detail "Initialisation de la fenetre principale"
    Initialize-Window
    if (-not $script:StartupReady) { throw "Initialisation incomplete : la fenetre principale reste masquee." }
    Write-StartupTrace -Stage "Apres login" -Status "OK" -Detail "Fenetre principale initialisee ; Domenia.db, cache initial et pool MTA valides"
    # The geometry may have been restored maximized after the activation choice: check again just before showing.
    try { [void](Set-DomeniaWindowActivationPolicy -Window $script:Window -UserSwitchedAway:(-not [bool]$script:Window.ShowActivated)) } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    # FI-22: once the main window has rendered, a failure is an unexpected stop of a shown session.
    Register-DomeniaSessionShownHook -Window $script:Window
    $null = $script:Window.ShowDialog()
}
catch {
    $fatalRecord = $_
    $fatalText = $_.Exception.ToString()
    $fatalCode = 'INC-0000'
    try { $fatalCode = New-DomeniaIncidentCode } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    try { Write-StartupTrace -Stage "Fatal" -Status "ERROR" -Detail ("[$fatalCode] " + $fatalText) } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    try { Write-DomeniaFastLoginLog -Stage "FATAL" -Status "ERROR" -Detail ("[$fatalCode] " + $fatalText) } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    $sessionShown = [bool]$script:DomeniaSessionShown
    if ($sessionShown) {
        try { Write-AppLog ("[$fatalCode] Arret inattendu de Domenia : " + $fatalText) 'ERROR' } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    }
    try { Stop-DomeniaAppLogQueue } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }

    $summary = [string]$_.Exception.Message
    if ([string]::IsNullOrWhiteSpace($summary)) { $summary = "Erreur inconnue pendant lʼinitialisation." }
    if ($summary.Length -gt 1400) { $summary = $summary.Substring(0,1400) + "..." }
    $startupLog = ""
    $loginLog = ""
    $appLog = ""
    try { $startupLog = [string]$script:StartupTracePath } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    try { $loginLog = [string](Get-DomeniaFastLoginLogPath) } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    try { $appLog = if ([bool]$script:AppLogUnavailable) { [string]$script:AppLogFallbackPath } else { [string]$script:AuditPath } } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }

    if ($DomeniaSelfTest) {
        [Console]::Error.WriteLine("DOMENIA SELF-TEST FAILED: $summary")
        exit 2
    }

    $existing = { param([string]$Path) if ($Path -and [IO.File]::Exists($Path)) { return $Path }; return '' }
    $forOperator = $false
    try { $forOperator = [bool](Test-DomeniaOperatorMessage $fatalRecord) } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    $message = Get-DomeniaFatalMessage -SessionShown $sessionShown -Summary $summary -Code $fatalCode -StartupLog (& $existing $startupLog) -LoginLog (& $existing $loginLog) -AppLog (& $existing $appLog) -Expert ([string]$script:CurrentUiProfile -eq 'Admin') -SummaryForOperator $forOperator
    # The page banner of a session that stopped would never be read: the report is a box of its own.
    if ($sessionShown) { try { if ($null -ne $script:Window -and $script:Window.IsVisible) { $script:Window.Hide() } } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ } }
    Show-ErrorBox -Message $message
}
finally {
    try {
        if ($null -ne $script:FastLoginState -and $null -ne $script:FastLoginState.Session) {
            Reset-DomeniaFastLoginAttempt -Kill
        }
    } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    try { if ($script:AsyncEngineReady -or @($script:AsyncJobs.Keys).Count -gt 0) { Dispose-AsyncEngine } } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    try { if ($null -ne $script:Conn) { $script:Conn.Credential = $null } } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    try { Hide-DomeniaSecretPeek -Owner 'Timer:LoginPasswordPeek' } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    try { $script:MachineCredential = $null } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    try { $script:RemoteAdminCredential = $null } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    try { $script:SecretsCredential = $null } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
    # PF-09: the queued Domenia.log lines are written before the process ends.
    try { Stop-DomeniaAppLogQueue } catch { Write-DomeniaSwallowed 'Core' 'Domenia-Core.ps1' $_ }
}
